# Configure future for async processing
options(future.globals.maxSize = 2000 * 1024^2)

# Use multicore (forking) on Linux - much faster and cleaner than multisession
# Forked processes are properly cleaned up by the OS
n_workers <- if (Sys.getenv("SHINY_PORT") != "") {
  # Production server - use multicore with moderate workers
  min(6, max(2, parallel::detectCores() / 4))
} else {
  # Local development
  2
}

# Multicore uses forking (Linux only) - no zombie issues like multisession
if (.Platform$OS.type == "unix") {
  plan(multicore, workers = n_workers)
  cat(paste("Future configured: multicore with", n_workers, "workers (fork-based)\n"))
} else {
  plan(multisession, workers = n_workers)
  cat(paste("Future configured: multisession with", n_workers, "workers\n"))
}

