# Organism-specific database loader
load_organism_db <- function(organism) {
  db_map <- list(
    "Human" = "org.Hs.eg.db",
    "Mouse" = "org.Mm.eg.db",
    "Rat" = "org.Rn.eg.db",
    "Fly" = "org.Dm.eg.db",
    "Zebrafish" = "org.Dr.eg.db",
    "Worm" = "org.Ce.eg.db",
    "Yeast" = "org.Sc.sgd.db",
    "Pig" = "org.Ss.eg.db",
    "Chicken" = "org.Gg.eg.db",
    "Bovine" = "org.Bt.eg.db",
    "Arabidopsis" = "org.At.tair.db"
  )
  
  pkg <- db_map[[organism]]
  if (!is.null(pkg) && !pkg %in% loadedNamespaces()) {
    cat("Loading", organism, "database...\n")
    library(pkg, character.only = TRUE)
    cat(organism, "database loaded!\n")
  }
}

# Load the bundled GSE151427 example transcriptome dataset (CMEC vs PMEC).
# Single source of truth used by:
#   - Transcriptome Analysis "Load Example Counts" button
#   - Standalone GRN "Load Example Expression" button
#   - Standalone GRN "Load Example DEG" fallback
# Returns:  list(counts = numeric matrix [genes x samples],
#                metadata = data.frame [Sample, group, batch, time, ...])
# Errors loudly if either bundled CSV is missing — *no* silent synthetic
# fallback (a previous bug where missing files generated random data
# silently produced a Figure-3 caused viper to run on noise).
load_example_transcriptome_data <- function(
  data_dir = "data",
  counts_file = "example_counts_GSE151427.csv",
  metadata_file = "example_metadata_GSE151427.csv"
) {
  counts_path <- file.path(data_dir, counts_file)
  metadata_path <- file.path(data_dir, metadata_file)

  if (!file.exists(counts_path)) {
    stop("Example counts file not found at: ", counts_path,
         " (expected bundled GSE151427 CSV)")
  }
  if (!file.exists(metadata_path)) {
    stop("Example metadata file not found at: ", metadata_path,
         " (expected bundled GSE151427 metadata CSV)")
  }

  counts_df <- utils::read.csv(counts_path, check.names = FALSE,
                               stringsAsFactors = FALSE)
  metadata_df <- utils::read.csv(metadata_path, check.names = FALSE,
                                 stringsAsFactors = FALSE)

  # First column expected to hold gene identifiers
  id_col <- colnames(counts_df)[1]
  gene_ids <- counts_df[[id_col]]
  counts_mat <- as.matrix(counts_df[, -1, drop = FALSE])
  storage.mode(counts_mat) <- "numeric"
  rownames(counts_mat) <- gene_ids

  list(counts = counts_mat, metadata = metadata_df)
}

# Resolve organism parameters for "other" organism support
# Returns a list with kegg_code, string_taxid, organism_name, has_orgdb
resolve_other_organism <- function(input) {
  result <- list(
    kegg_code = NULL,
    string_taxid = NULL,
    organism_name = "other",
    has_orgdb = FALSE,
    can_enrich = FALSE,
    can_ppi = FALSE
  )
  tryCatch({
    if (!is.null(input$other_organism_name) && nchar(trimws(input$other_organism_name)) > 0) {
      result$organism_name <- trimws(input$other_organism_name)
    }
    if (!is.null(input$other_kegg_code) && nchar(trimws(input$other_kegg_code)) > 0) {
      result$kegg_code <- tolower(trimws(input$other_kegg_code))
      result$can_enrich <- TRUE
    }
    if (!is.null(input$other_string_taxid) && !is.na(input$other_string_taxid) && input$other_string_taxid > 0) {
      result$string_taxid <- as.integer(input$other_string_taxid)
      result$can_ppi <- TRUE
    }
  }, error = function(e) NULL)
  return(result)
}

# Example Data Loader - GSE151427
#-------------------------------------------------------------------------------
load_example_counts <- function(app_dir = ".") {
  counts_path <- file.path(app_dir, "data", "example_counts_GSE151427.csv")
  
  if (!file.exists(counts_path)) {
    stop("Example counts file not found. Please ensure 'data/example_counts_GSE151427.csv' exists.")
  }
  
  # Read counts
  counts <- tryCatch({
    data <- read.csv(counts_path, check.names = FALSE, stringsAsFactors = FALSE)
    
    # Handle gene column (first column or "Gene" column)
    if ("Gene" %in% colnames(data)) {
      rownames(data) <- data$Gene
      data$Gene <- NULL
    } else if ("gene" %in% colnames(data)) {
      rownames(data) <- data$gene
      data$gene <- NULL
    } else {
      # Assume first column is gene names
      rownames(data) <- data[[1]]
      data <- data[, -1, drop = FALSE]
    }
    
    # Convert to numeric
    data <- as.data.frame(lapply(data, as.numeric))
    rownames(data) <- make.unique(rownames(data))
    
    data
  }, error = function(e) {
    stop(paste("Error reading counts file:", e$message))
  })
  
  return(counts)
}

load_example_metadata <- function(app_dir = ".") {
  metadata_path <- file.path(app_dir, "data", "example_metadata_GSE151427.csv")
  
  if (!file.exists(metadata_path)) {
    stop("Example metadata file not found. Please ensure 'data/example_metadata_GSE151427.csv' exists.")
  }
  
  metadata <- read.csv(metadata_path, check.names = FALSE, stringsAsFactors = FALSE)
  
  # Ensure Sample column exists
  if (!"Sample" %in% colnames(metadata)) {
    # Try common alternatives
    sample_cols <- c("sample", "SampleID", "sample_id", "Sample_ID", "SampleName")
    found <- intersect(sample_cols, colnames(metadata))
    if (length(found) > 0) {
      colnames(metadata)[colnames(metadata) == found[1]] <- "Sample"
    } else {
      # Use first column
      colnames(metadata)[1] <- "Sample"
    }
  }
  
  return(metadata)
}


