            results.removeClass('col-md-12').addClass('col-md-8');
            icon.removeClass('fa-chevron-right').addClass('fa-chevron-left');
            sidebarVisible = true;

            // Reset auto-hide trigger when user manually opens sidebar
            autoHideTriggered = false;
          }
        });

        // Auto-hide sidebar when analysis completes (only once)
