              if (sidebarVisible) { // Double-check sidebar is still visible
                $('#toggle-sidebar-btn').click();
              }
            }, 2000);
          }
        }

        // Check for analysis completion only once initially, then stop
        let checkCount = 0;
        const checkInterval = setInterval(function() {
          autoHideSidebar();
          checkCount++;

          // Stop checking after 10 attempts or if auto-hide was triggered
          if (checkCount > 10 || autoHideTriggered) {
            clearInterval(checkInterval);
          }
        }, 3000);

        // Prevent form interactions from triggering auto-hide
