      $(document).ready(function() {
        function updateCardStyling(selected) {
          // 1. Reset Styles
          $('#strategy_card_discovery, #strategy_card_disease, #strategy_card_comprehensive').css({
            'background-color': '#fafafa', 'border-color': '#ccc', 'border-width': '1px'
          });
          
          // 2. Reset Icons (Empty Circle)
          $('#icon_discovery, #icon_disease, #icon_comprehensive').removeClass('fa-dot-circle-o').addClass('fa-circle-o');
          
