    // Reset all card styles
    $('.network-type-card').css('border-color', '#dee2e6');

    if (type === 'physical') {
      $('#physical_card').css('border-color', '#3498db');
      $('#physical_card').css('border-width', '3px');
      $('#full_card').css('border-width', '2px');
      $('#selected_type').text('Physical Interactions');
      $('#expected_results').text('(Expected: 20-100 high-confidence interactions)');
    } else {
      $('#full_card').css('border-color', '#e67e22');
      $('#full_card').css('border-width', '3px');
      $('#physical_card').css('border-width', '2px');
      $('#selected_type').text('Full Network');
      $('#expected_results').text('(Expected: 100-500+ comprehensive associations)');
    }
  }

  // Initialize on page load
  $(document).ready(function() {
    selectNetworkType('physical');
  });
