# ===== CELL TYPE DECONV =====

validate_deconvolution_method <- function(method, organism, deg_data = NULL) {
  
  # Method compatibility warnings
  method_info <- list(
    
    xcell = list(
      name = "xCell",
      best_for = "General tissue types, immune profiling",
      limitations = "May be less accurate for pure immune cell populations",
      output_type = "Enrichment scores (relative)",
      recommended = TRUE
    ),
    
    mcp_counter = list(
      name = "MCP-counter", 
      best_for = "Immune cell quantification, pure immune samples",
      limitations = "Limited to 10 immune cell types, not for tumor content",
      output_type = "Absolute scores (arbitrary units)",
      recommended = TRUE
    ),
    
    epic = list(
      name = "EPIC",
      best_for = "Tumor microenvironment, bulk tumor samples",
      limitations = "Designed for tumor samples - NOT recommended for pure immune cell experiments",
      output_type = "Cell type proportions (fractions)",
      recommended = FALSE
    )
  )
  
  current_method <- method_info[[method]]
  
  # Generate warning message
  message <- paste0(
    "📊 Method: ", current_method$name, "\n",
    "✓ Best for: ", current_method$best_for, "\n",
    "⚠️  Limitations: ", current_method$limitations, "\n",
    "📈 Output: ", current_method$output_type
  )
  
  print(message)
  
  return(list(
    valid = TRUE,
    recommended = current_method$recommended,
    warning = if(!current_method$recommended) current_method$limitations else NULL
  ))
}


# Universal gene ID converter for display
convert_gene_ids_to_symbols_universal <- function(gene_ids, organism = "human") {
  
  print(paste("🔄 Converting", length(gene_ids), "gene IDs to symbols for", organism))
  
  # Get the appropriate annotation database
  org_db <- switch(organism,
                   "human" = "org.Hs.eg.db",
                   "mouse" = "org.Mm.eg.db",
                   "rat" = "org.Rn.eg.db",
                   "fly" = "org.Dm.eg.db",
                   "zebrafish" = "org.Dr.eg.db",
                   "celegans" = "org.Ce.eg.db",
                   "yeast" = "org.Sc.sgd.db",
                   "arabidopsis" = "org.At.tair.db",
                   "chicken" = "org.Gg.eg.db",
                   "pig" = "org.Ss.eg.db",
                   "org.Hs.eg.db")
  
  # Load the database
  if (!require(org_db, character.only = TRUE, quietly = TRUE)) {
    print(paste("⚠️ Database", org_db, "not available, returning original IDs"))
    return(setNames(gene_ids, gene_ids))
  }
  
  library(org_db, character.only = TRUE)
  library(AnnotationDbi)
  
  # Clean gene IDs
  clean_ids <- gsub("_.*$", "", gene_ids)
  clean_ids <- gsub("\\..*$", "", clean_ids)
  
  # Initialize result
  gene_symbols <- setNames(clean_ids, gene_ids)
  
  # Check if already symbols
  tryCatch({
    if ("SYMBOL" %in% AnnotationDbi::keytypes(get(org_db))) {
      valid_symbols <- clean_ids %in% AnnotationDbi::keys(get(org_db), keytype = "SYMBOL")
      if (sum(valid_symbols) > 0) {
        gene_symbols[valid_symbols] <- clean_ids[valid_symbols]
        print(paste("  ✅", sum(valid_symbols), "IDs are already valid symbols"))
      }
    }
  }, error = function(e) {})
  
  # Try ENSEMBL
  ensembl_ids <- clean_ids[grepl("^ENS", clean_ids) & gene_symbols == clean_ids]
  if (length(ensembl_ids) > 0 && "ENSEMBL" %in% AnnotationDbi::keytypes(get(org_db))) {
    tryCatch({
      converted <- AnnotationDbi::mapIds(get(org_db), keys = ensembl_ids, column = "SYMBOL", 
                                         keytype = "ENSEMBL", multiVals = "first")
      valid <- !is.na(converted)
      if (sum(valid) > 0) {
        original_names <- names(gene_symbols)[gene_symbols %in% ensembl_ids][valid]
        gene_symbols[original_names] <- converted[valid]
        print(paste("  ✅ Converted", sum(valid), "ENSEMBL IDs"))
      }
    }, error = function(e) {})
  }
  
  print(paste("  📊 Conversion:", sum(gene_symbols != names(gene_symbols)), "of", length(gene_ids), "converted"))
  
  return(gene_symbols)
}

create_group_comparison_boxplot_filtered <- function(deconv_results, method, sample_groups, selected_cell_types, layout_cols = 3) {
  
  tryCatch({
    library(ggplot2)
    library(plotly)
    library(reshape2)
    
    # Extract data
    if (method %in% c("xcell", "mcp_counter")) {
      cell_type_matrix <- as.matrix(deconv_results)
    } else if (method == "epic") {
      cell_type_matrix <- t(as.matrix(deconv_results))
    }
    
    # ✅ CRITICAL FIX: Validate selected_cell_types exist in matrix
    available_cell_types <- rownames(cell_type_matrix)
    
    # Match selected cell types to available ones
    valid_cell_types <- selected_cell_types[selected_cell_types %in% available_cell_types]
    
    # If no exact matches, try case-insensitive matching
    if (length(valid_cell_types) == 0) {
      selected_lower <- tolower(selected_cell_types)
      available_lower <- tolower(available_cell_types)
      match_indices <- match(selected_lower, available_lower)
      valid_cell_types <- available_cell_types[match_indices[!is.na(match_indices)]]
    }
    
    # If still no matches, use all cell types
    if (length(valid_cell_types) == 0) {
      valid_cell_types <- available_cell_types
    }
    
    # ✅ SAFE SUBSET: Only use valid cell types
    cell_type_matrix_filtered <- cell_type_matrix[valid_cell_types, , drop = FALSE]
    
    # Convert to long format
    plot_data <- melt(cell_type_matrix_filtered)
    colnames(plot_data) <- c("cell_type", "sample", "score")
    
    # Add group info
    plot_data$group <- sample_groups$group[match(plot_data$sample, sample_groups$sample)]
    
    # Remove NA groups
    plot_data <- plot_data[!is.na(plot_data$group), ]
    
    # Create box plot
    p <- ggplot(plot_data, aes(x = group, y = score, fill = group)) +
      geom_boxplot(outlier.shape = 16, outlier.size = 2, alpha = 0.7) +
      geom_jitter(width = 0.2, alpha = 0.4, size = 2) +
      facet_wrap(~cell_type, scales = "free_y", ncol = layout_cols) +
      labs(
        x = "Group",
        y = "Enrichment Score",
        fill = "Group"
      ) +
      theme_minimal() +
      theme(
        axis.text.x = element_text(angle = 45, hjust = 1, size = 10, face = "bold"),
        strip.text = element_text(face = "bold", size = 11),
        strip.background = element_rect(fill = "#f0f0f0", color = NA),
        legend.position = "top"
      ) +
      scale_fill_brewer(palette = "Set2")
    
    return(ggplotly(p, height = NULL) %>% layout(showlegend = TRUE))
    
  }, error = function(e) {
    # Return error plot
    p_error <- ggplot() +
      annotate("text", x = 0.5, y = 0.5, 
               label = paste("Error creating plot:", e$message),
               size = 5, color = "red") +
      theme_void()
    
    return(ggplotly(p_error))
  })
}


prepare_expression_for_deconv <- function(expression_matrix, organism = "human", min_genes = 100, user_groups = NULL) {
  
  print("🧬 === STARTING EXPRESSION DATA PREPARATION FOR DECONVOLUTION ===")
  
  # Validation
  if (!is.matrix(expression_matrix) && !is.data.frame(expression_matrix)) {
    stop("expression_matrix must be a matrix or data.frame")
  }
  
  if (organism != "human") {
    stop("Cell type deconvolution is currently only supported for human samples")
  }
  
  print(paste("Input dimensions:", nrow(expression_matrix), "genes x", ncol(expression_matrix), "samples"))
  
  
  # Step 1: Get gene IDs from rownames
  gene_ids <- rownames(expression_matrix)
  
  if (is.null(gene_ids) || length(gene_ids) == 0) {
    stop("Expression matrix must have gene IDs as rownames")
  }
  
  print(paste("Original gene IDs (first 5):", paste(head(gene_ids, 5), collapse = ", ")))
  
  # Step 2: Convert to gene symbols using existing conversion function
  print("📄 Converting gene IDs to symbols...")
  
  # FIXED: Extract gene_symbol column from returned data.frame
  gene_conversion_df <- convert_gene_ids_to_symbols_deg(
    gene_ids = gene_ids,
    organism = organism
  )
  gene_symbols <- gene_conversion_df$gene_symbol
  
  # Step 3: Create mapping and filter valid conversions
  print("🔍 Filtering to valid gene symbols...")
  
  valid_idx <- !is.na(gene_symbols) & 
    gene_symbols != "" & 
    gene_symbols != "-" &
    !grepl("^ENSG", gene_symbols) &  # Remove unconverted ENSEMBL IDs
    !grepl("^ENST", gene_symbols) &  # Remove unconverted transcript IDs
    !grepl("^[0-9]+$", gene_symbols)  # Remove unconverted Entrez IDs
  
  n_valid <- sum(valid_idx)
  conversion_rate <- n_valid / length(gene_ids)
  
  print(paste("✅ Gene conversion rate:", round(conversion_rate * 100, 1), "%"))
  print(paste("   Valid genes after filtering:", n_valid, "out of", length(gene_ids)))
  
  if (n_valid < min_genes) {
    stop(paste0("Only ", n_valid, " genes could be converted to valid symbols. ",
                "Need at least ", min_genes, " genes for reliable deconvolution. ",
                "Check your gene ID format or organism selection."))
  }
  
  # Step 4: Filter expression matrix to valid genes
  expr_with_symbols <- expression_matrix[valid_idx, , drop = FALSE]
  gene_symbols_valid <- gene_symbols[valid_idx]
  
  print(paste("📊 Filtered to", nrow(expr_with_symbols), "rows with valid gene symbols"))
  print(paste("   Example symbols (first 5):", paste(head(gene_symbols_valid, 5), collapse = ", ")))
  
  # Step 5: Handle duplicate gene symbols BEFORE setting rownames
  print("🔎 Checking for duplicate gene symbols...")
  
  if (any(duplicated(gene_symbols_valid))) {
    n_duplicates <- sum(duplicated(gene_symbols_valid))
    n_unique <- length(unique(gene_symbols_valid))
    
    print(paste("⚠️  Found", n_duplicates, "duplicate entries"))
    print(paste("   Total entries:", length(gene_symbols_valid)))
    print(paste("   Unique gene symbols:", n_unique))
    print("📊 Aggregating duplicates by taking mean expression...")
    
    # Create data frame with gene symbols as a COLUMN (not rownames!)
    expr_df <- as.data.frame(expr_with_symbols)
    expr_df$gene_symbol <- gene_symbols_valid
    
    # Aggregate duplicates by mean
    expr_aggregated <- aggregate(. ~ gene_symbol, data = expr_df, FUN = mean)
    
    # NOW it's safe to set rownames (all unique now)
    rownames(expr_aggregated) <- expr_aggregated$gene_symbol
    expr_aggregated$gene_symbol <- NULL
    
    expr_final_prep <- as.matrix(expr_aggregated)
    
    print(paste("✅ After aggregation:", nrow(expr_final_prep), "unique genes"))
    
  } else {
    # No duplicates - safe to set rownames directly
    print("✅ No duplicate gene symbols found")
    rownames(expr_with_symbols) <- gene_symbols_valid
    expr_final_prep <- expr_with_symbols
  }
  
  print(paste("📋 Final gene list (first 5):", paste(head(rownames(expr_final_prep), 5), collapse = ", ")))
  
  # Step 6: Prepare data for deconvolution methods
  print("🔬 Preparing data format for deconvolution...")
  
  # Most methods expect log2-transformed or TPM-like data
  max_value <- max(expr_final_prep, na.rm = TRUE)
  
  if (max_value > 50) {
    print(paste("📈 Applying log2 transformation (max value:", round(max_value, 1), "suggests count data)"))
    expr_final <- log2(expr_final_prep + 1)
  } else {
    print(paste("📊 Data appears to be already log-transformed (max value:", round(max_value, 2), ")"))
    expr_final <- expr_final_prep
  }
  
  # ============================================================================
  # Step 7: IMPROVED GROUP DETECTION - Support Manual Selection
  # ============================================================================
  
  sample_groups <- NULL
  sample_names <- colnames(expr_final)
  
  # PRIORITY 1: Use user-provided groups if available
  if (!is.null(user_groups)) {
    print("👤 Using user-defined sample groups")
    
    # Validate user_groups format
    if (is.data.frame(user_groups) && "sample" %in% colnames(user_groups) && "group" %in% colnames(user_groups)) {
      # Match samples to ensure alignment
      matched_groups <- user_groups[match(sample_names, user_groups$sample), ]
      
      if (any(is.na(matched_groups$group))) {
        warning("Some samples have no group assignment - these will be labeled as 'Unknown'")
        matched_groups$group[is.na(matched_groups$group)] <- "Unknown"
      }
      
      sample_groups <- data.frame(
        sample = sample_names,
        group = matched_groups$group,
        stringsAsFactors = FALSE
      )
      
      print(paste("   ✅ Groups assigned:", paste(unique(sample_groups$group), collapse = ", ")))
      print(paste("   📊 Sample distribution:", paste(names(table(sample_groups$group)), 
                                                      "(", table(sample_groups$group), ")", 
                                                      collapse = ", ")))
    } else {
      warning("Invalid user_groups format - expected data.frame with 'sample' and 'group' columns")
      warning("Falling back to automatic detection from sample names")
    }
  }
  
  # PRIORITY 2: Auto-detect from naming convention (if no user groups provided)
  if (is.null(sample_groups) && any(grepl("_", sample_names))) {
    print("🔍 Detecting sample groups from naming convention (format: SampleName_GroupName)")
    sample_groups <- data.frame(
      sample = sample_names,
      group = sub(".*_", "", sample_names),
      stringsAsFactors = FALSE
    )
    print(paste("   Groups found:", paste(unique(sample_groups$group), collapse = ", ")))
  }
  
  # If still no groups detected
  if (is.null(sample_groups)) {
    print("ℹ️  No sample groups detected")
    print("   💡 Tip: Use SampleName_GroupName format or provide manual group assignments")
  }
  
  # Step 8: Final validation
  if (any(is.na(expr_final))) {
    na_count <- sum(is.na(expr_final))
    print(paste("⚠️  Found", na_count, "NA values - replacing with 0"))
    expr_final[is.na(expr_final)] <- 0
  }
  
  print(paste(rep("=", 60), collapse = ""))
  print("✅ EXPRESSION DATA PREPARATION COMPLETE")
  print(paste(rep("=", 60), collapse = ""))
  print(paste("📊 Final dimensions:", nrow(expr_final), "genes x", ncol(expr_final), "samples"))
  print(paste("📈 Conversion summary:"))
  print(paste("   - Original genes:", length(gene_ids)))
  print(paste("   - Successfully converted:", n_valid))
  print(paste("   - After deduplication:", nrow(expr_final)))
  print(paste("   - Effective conversion rate:", round((nrow(expr_final) / length(gene_ids)) * 100, 1), "%"))
  
  return(list(
    expr_matrix = expr_final,
    gene_symbols = rownames(expr_final),
    sample_groups = sample_groups,
    conversion_rate = nrow(expr_final) / length(gene_ids),
    n_original_genes = length(gene_ids),
    n_valid_genes = nrow(expr_final)
  ))
}

#METHOD-SPECIFIC DECONVOLUTION RUNNERS

run_xcell_deconv <- function(expr_matrix) {
  
  print("🔬 Running xCell deconvolution...")
  
  # Check if xCell is installed
  if (!requireNamespace("xCell", quietly = TRUE)) {
    stop("xCell package not installed. Install with: devtools::install_github('dviraran/xCell')")
  }
  
  tryCatch({
    library(xCell)
    
    # xCell expects:
    # - Rows: genes (HGNC symbols)
    # - Columns: samples
    # - Log-scale expression data (TPM, RPKM, or microarray)
    
    print(paste("Input to xCell:", nrow(expr_matrix), "genes x", ncol(expr_matrix), "samples"))
    
    # Run xCell analysis
    xcell_results <- xCellAnalysis(
      expr = expr_matrix,
      rnaseq = TRUE,  # Set to TRUE for RNA-seq data
      parallel.sz = 1  # Use single core for stability
    )
    
    print(paste("xCell analysis complete:", nrow(xcell_results), "cell types"))
    
    return(xcell_results)
    
  }, error = function(e) {
    print(paste("xCell analysis failed:", e$message))
    stop(paste("xCell deconvolution error:", e$message))
  })
}


run_mcp_counter_deconv <- function(expr_matrix) {
  
  print("🔬 Running MCP-counter deconvolution...")
  
  # Check if MCPcounter is installed
  if (!requireNamespace("MCPcounter", quietly = TRUE)) {
    stop("MCPcounter package not installed. Install with: devtools::install_github('ebecht/MCPcounter', ref='master', subdir='Source')")
  }
  
  tryCatch({
    library(MCPcounter)
    
    # MCP-counter expects:
    # - Rows: genes (HUGO symbols)
    # - Columns: samples
    # - Non-log transformed expression data (preferably TPM)
    
    print(paste("Input to MCP-counter:", nrow(expr_matrix), "genes x", ncol(expr_matrix), "samples"))
    
    # Convert from log-scale back to linear if needed
    # MCP-counter works better with non-log data
    if (max(expr_matrix, na.rm = TRUE) < 50) {
      print("Converting from log-scale to linear scale for MCP-counter")
      expr_linear <- 2^expr_matrix - 1
      expr_linear[expr_linear < 0] <- 0
    } else {
      expr_linear <- expr_matrix
    }
    
    # Run MCP-counter analysis
    mcp_results <- MCPcounter.estimate(
      expression = expr_linear,
      featuresType = "HUGO_symbols"
    )
    
    print(paste("MCP-counter analysis complete:", nrow(mcp_results), "cell types"))
    
    return(mcp_results)
    
  }, error = function(e) {
    print(paste("MCP-counter analysis failed:", e$message))
    stop(paste("MCP-counter deconvolution error:", e$message))
  })
}


run_epic_deconv <- function(expr_matrix) {
  
  print("🔬 Running EPIC deconvolution...")
  
  # Check if EPIC is installed
  if (!requireNamespace("EPIC", quietly = TRUE)) {
    stop("EPIC package not installed. Install from Bioconductor: BiocManager::install('EPIC')")
  }
  
  tryCatch({
    library(EPIC)
    
    # EPIC expects:
    # - Rows: genes (HGNC symbols)
    # - Columns: samples
    # - TPM values (non-log transformed)
    
    print(paste("Input to EPIC:", nrow(expr_matrix), "genes x", ncol(expr_matrix), "samples"))
    
    # Convert from log-scale back to linear if needed
    if (max(expr_matrix, na.rm = TRUE) < 50) {
      print("Converting from log-scale to linear scale for EPIC")
      expr_linear <- 2^expr_matrix - 1
      expr_linear[expr_linear < 0] <- 0
    } else {
      expr_linear <- expr_matrix
    }
    
    # Run EPIC analysis with tumor reference
    epic_results <- EPIC(
      bulk = expr_linear,
      reference = "TRef",  # Tumor reference signature
      withOtherCells = TRUE  # Include "other cells" category
    )
    
    # Extract cell fractions
    cell_fractions <- epic_results$cellFractions
    
    print(paste("EPIC analysis complete:", ncol(cell_fractions), "cell types"))
    
    return(cell_fractions)
    
  }, error = function(e) {
    print(paste("EPIC analysis failed:", e$message))
    stop(paste("EPIC deconvolution error:", e$message))
  })
}


#RESULT EXTRACTION AND STANDARDIZATION

extract_cell_composition <- function(deconv_results, method) {
  
  print(paste("Extracting cell composition from", method, "results..."))
  
  tryCatch({
    
    if (method == "xcell") {
      # xCell returns enrichment scores (rows = cell types, columns = samples)
      # These are NOT proportions but enrichment scores
      
      cell_types <- rownames(deconv_results)
      n_samples <- ncol(deconv_results)
      
      composition <- data.frame(
        cell_type = cell_types,
        mean_score = rowMeans(deconv_results, na.rm = TRUE),
        sd_score = apply(deconv_results, 1, sd, na.rm = TRUE),
        stringsAsFactors = FALSE
      )
      
      # Calculate pseudo-proportions (normalized scores)
      composition$proportion <- composition$mean_score / sum(composition$mean_score, na.rm = TRUE)
      
      # FIXED: Add per-sample data correctly
      # deconv_results is already cell_types (rows) x samples (cols)
      # Just bind it directly - no transpose needed!
      composition <- cbind(composition, as.data.frame(deconv_results))
      
    } else if (method == "mcp_counter") {
      # MCP-counter returns absolute scores (rows = cell types, columns = samples)
      
      cell_types <- rownames(deconv_results)
      
      composition <- data.frame(
        cell_type = cell_types,
        mean_score = rowMeans(deconv_results, na.rm = TRUE),
        sd_score = apply(deconv_results, 1, sd, na.rm = TRUE),
        stringsAsFactors = FALSE
      )
      
      # Normalize to proportions
      composition$proportion <- composition$mean_score / sum(composition$mean_score, na.rm = TRUE)
      
      # FIXED: Add per-sample data correctly - no transpose!
      composition <- cbind(composition, as.data.frame(deconv_results))
      
    } else if (method == "epic") {
      # EPIC returns actual cell fractions (rows = samples, columns = cell types)
      
      cell_types <- colnames(deconv_results)
      
      composition <- data.frame(
        cell_type = cell_types,
        mean_score = colMeans(deconv_results, na.rm = TRUE),
        sd_score = apply(deconv_results, 2, sd, na.rm = TRUE),
        proportion = colMeans(deconv_results, na.rm = TRUE),  # Already proportions
        stringsAsFactors = FALSE
      )
      
      # FIXED: For EPIC, we DO need transpose since it's samples x cell_types
      composition <- cbind(composition, as.data.frame(t(deconv_results)))
    }
    
    # Add statistical significance (t-test against zero)
    composition$p_value <- sapply(seq_len(nrow(composition)), function(i) {
      # Get sample values for this cell type
      # Sample columns start after the first 4 metadata columns
      sample_cols <- 5:ncol(composition)
      
      if (length(sample_cols) > 0) {
        values <- as.numeric(composition[i, sample_cols])
        # Remove any non-numeric or NA values
        values <- values[!is.na(values) & is.finite(values)]
        
        if (length(values) > 1) {
          test_result <- tryCatch({
            t.test(values, mu = 0)$p.value
          }, error = function(e) {
            return(NA)
          })
          return(test_result)
        }
      }
      return(NA)
    })
    
    # Sort by proportion (descending)
    composition <- composition[order(-composition$proportion), ]
    
    print(paste("Extracted composition for", nrow(composition), "cell types"))
    
    return(composition)
    
  }, error = function(e) {
    print(paste("Error extracting cell composition:", e$message))
    stop(paste("Cell composition extraction error:", e$message))
  })
}


#CONFIDENCE SCORING

calculate_deconv_confidence <- function(deconv_results, method) {
  
  print("🎯 Calculating deconvolution confidence score...")
  
  tryCatch({
    
    # ========================================================================
    # STEP 1: Extract data in correct orientation
    # ========================================================================
    
    if (method %in% c("xcell", "mcp_counter")) {
      # Results are cell_types (rows) x samples (columns)
      cell_type_scores <- as.matrix(deconv_results)
      n_samples <- ncol(cell_type_scores)
      n_cell_types <- nrow(cell_type_scores)
      
      print(paste("   Analyzing", n_cell_types, "cell types across", n_samples, "samples"))
      
    } else if (method == "epic") {
      # Results are samples (rows) x cell_types (columns)
      cell_type_scores <- t(as.matrix(deconv_results))
      n_samples <- ncol(cell_type_scores)
      n_cell_types <- nrow(cell_type_scores)
      
      print(paste("   Analyzing", n_cell_types, "cell types across", n_samples, "samples"))
    }
    
    # Validate minimum samples
    if (n_samples < 2) {
      print("   ⚠️ Only 1 sample - cannot calculate variability metrics")
      return(50)  # Neutral confidence for single sample
    }
    
    # ========================================================================
    # STEP 2: Calculate Coefficient of Variation (CV) for each cell type
    # ========================================================================
    
    # CV = Standard Deviation / Mean
    # Lower CV = more consistent across samples = higher confidence
    
    cv_per_cell_type <- apply(cell_type_scores, 1, function(x) {
      # Remove any NA or infinite values
      x_clean <- x[is.finite(x)]
      
      if (length(x_clean) < 2) return(NA)  # Need at least 2 values
      
      mean_val <- mean(x_clean, na.rm = TRUE)
      sd_val <- sd(x_clean, na.rm = TRUE)
      
      # Avoid division by zero
      if (mean_val == 0 || is.na(mean_val)) return(NA)
      
      cv <- sd_val / abs(mean_val)
      return(cv)
    })
    
    # Remove NA and infinite values from CV calculations
    cv_valid <- cv_per_cell_type[is.finite(cv_per_cell_type)]
    
    if (length(cv_valid) == 0) {
      print("   ⚠️ Could not calculate valid CV values")
      return(50)
    }
    
    print(paste("   📊 Valid CV values calculated for", length(cv_valid), "cell types"))
    print(paste("   📈 CV range:", round(min(cv_valid), 3), "to", round(max(cv_valid), 3)))
    
    # ========================================================================
    # STEP 3: Calculate mean CV and method-specific adjustments
    # ========================================================================
    
    mean_cv <- mean(cv_valid, na.rm = TRUE)
    median_cv <- median(cv_valid, na.rm = TRUE)
    
    print(paste("   🎯 Mean CV:", round(mean_cv, 3)))
    print(paste("   🎯 Median CV:", round(median_cv, 3)))
    
    # Method-specific CV interpretation
    if (method == "xcell") {
      # xCell enrichment scores are unbounded and can be highly variable
      # CV values tend to be higher (0.5-2.0 is typical)
      # Adjust the confidence calculation accordingly
      
      # Use a sigmoid-like transformation for xCell
      # CV < 0.5: Very good (80-100% confidence)
      # CV = 1.0: Moderate (50% confidence)
      # CV > 2.0: Poor (0-30% confidence)
      
      if (mean_cv < 0.5) {
        confidence_raw <- 80 + (0.5 - mean_cv) * 40  # 80-100%
      } else if (mean_cv < 1.0) {
        confidence_raw <- 50 + (1.0 - mean_cv) * 60  # 50-80%
      } else if (mean_cv < 2.0) {
        confidence_raw <- 20 + (2.0 - mean_cv) * 30  # 20-50%
      } else {
        confidence_raw <- max(5, 20 - (mean_cv - 2.0) * 10)  # 5-20%
      }
      
    } else if (method == "mcp_counter") {
      # MCP-counter provides absolute scores
      # CV values are typically moderate (0.3-1.5)
      
      if (mean_cv < 0.3) {
        confidence_raw <- 85 + (0.3 - mean_cv) * 50
      } else if (mean_cv < 1.0) {
        confidence_raw <- 50 + (1.0 - mean_cv) * 50
      } else {
        confidence_raw <- max(10, 50 - (mean_cv - 1.0) * 40)
      }
      
    } else if (method == "epic") {
      # EPIC provides proportions (0-1)
      # Should have lower CV (0.1-0.5 is typical)
      
      if (mean_cv < 0.2) {
        confidence_raw <- 90 + (0.2 - mean_cv) * 50
      } else if (mean_cv < 0.5) {
        confidence_raw <- 70 + (0.5 - mean_cv) * 67
      } else {
        confidence_raw <- max(20, 70 - (mean_cv - 0.5) * 100)
      }
    }
    
    # STEP 4: Apply sample size adjustment
    
    # More samples = higher confidence (up to bonus of +10%)
    sample_bonus <- min(10, (n_samples - 2) * 2)  # +2% per sample above 2, max +10%
    
    # STEP 5: Apply data quality adjustment
    
    # Check proportion of zero/very low values
    zero_proportion <- sum(cell_type_scores < 0.001, na.rm = TRUE) / length(cell_type_scores)
    
    if (zero_proportion > 0.5) {
      quality_penalty <- -15  # Many zeros suggests sparse data
    } else if (zero_proportion > 0.3) {
      quality_penalty <- -5
    } else {
      quality_penalty <- 0
    }
    
    # STEP 6: Final confidence score
    
    confidence_final <- confidence_raw + sample_bonus + quality_penalty
    confidence_final <- round(max(0, min(100, confidence_final)), 1)
    
    print(paste("   ✅ Raw confidence:", round(confidence_raw, 1), "%"))
    print(paste("   📊 Sample bonus:", sample_bonus, "%"))
    print(paste("   🔍 Quality adjustment:", quality_penalty, "%"))
    print(paste("   🎯 FINAL CONFIDENCE:", confidence_final, "%"))
    
    # STEP 7: Interpretation guide
    
    interpretation <- if (confidence_final >= 75) {
      "High confidence - consistent results across samples"
    } else if (confidence_final >= 50) {
      "Moderate confidence - some variability across samples"
    } else if (confidence_final >= 25) {
      "Low confidence - high variability, interpret with caution"
    } else {
      "Very low confidence - results may not be reliable"
    }
    
    print(paste("   💡 Interpretation:", interpretation))
    
    return(confidence_final)
    
  }, error = function(e) {
    print(paste("❌ Error calculating confidence score:", e$message))
    print("   Returning default moderate confidence (50%)")
    return(50)
  })
}


# UTILITY FUNCTIONS

# Validate deconvolution method
validate_deconv_method <- function(method) {
  valid_methods <- c("xcell", "mcp_counter", "epic")
  
  if (!method %in% valid_methods) {
    stop(paste("Invalid deconvolution method. Choose from:", paste(valid_methods, collapse = ", ")))
  }
  
  return(TRUE)
}

# Check package availability
check_deconv_packages <- function(method) {
  
  packages_needed <- switch(method,
                            "xcell" = "xCell",
                            "mcp_counter" = "MCPcounter",
                            "epic" = "EPIC",
                            NULL
  )
  
  if (is.null(packages_needed)) {
    return(list(available = FALSE, message = "Unknown method"))
  }
  
  available <- requireNamespace(packages_needed, quietly = TRUE)
  
  if (!available) {
    install_instructions <- switch(method,
                                   "xcell" = "devtools::install_github('dviraran/xCell')",
                                   "mcp_counter" = "devtools::install_github('ebecht/MCPcounter', ref='master', subdir='Source')",
                                   "epic" = "BiocManager::install('EPIC')",
                                   ""
    )
    
    message <- paste0("Package '", packages_needed, "' is not installed. ",
                      "Install with: ", install_instructions)
    
    return(list(available = FALSE, message = message))
  }
  
  return(list(available = TRUE, message = "Package available"))
}


# CELL TYPE DECONVOLUTION - MAIN ANALYSIS FUNCTION

perform_deconvolution_analysis <- function(expression_matrix, 
                                           method = "xcell",
                                           organism = "human",
                                           deg_data = NULL,
                                           sample_groups = NULL,  # Now accepts user-defined groups
                                           min_genes = 100) {
  
  print("============================================================")
  print("       CELL TYPE DECONVOLUTION ANALYSIS STARTING")
  print("============================================================")
  
  method_validation <- validate_deconvolution_method(method, organism, deg_data)
  
  if (!method_validation$recommended) {
    warning(paste0(
      "\n⚠️  WARNING: ", method, " may not be appropriate for your data!\n",
      "   ", method_validation$warning, "\n",
      "   Consider using 'xcell' or 'mcp_counter' for better results.\n"
    ))
  }
  
  print(paste("Method:", method))
  print(paste("Organism:", organism))
  print(paste("DEG context:", !is.null(deg_data)))
  print("============================================================")
  
  # ==========================================================================
  # STEP 1: VALIDATION
  # ==========================================================================
  
  tryCatch({
    
    # Validate method
    validate_deconv_method(method)
    
    # Check if required package is available
    package_check <- check_deconv_packages(method)
    if (!package_check$available) {
      stop(package_check$message)
    }
    
    # Validate organism
    if (organism != "human") {
      stop("Cell type deconvolution is currently only supported for human samples. Please select 'human' as your organism.")
    }
    
    # Validate expression matrix
    if (is.null(expression_matrix)) {
      stop("Expression matrix is NULL. Please provide normalized expression data.")
    }
    
    if (nrow(expression_matrix) < 100) {
      stop(paste("Expression matrix has only", nrow(expression_matrix), 
                 "genes. Need at least 100 genes for reliable deconvolution."))
    }
    
    if (ncol(expression_matrix) < 2) {
      stop("Expression matrix must have at least 2 samples for deconvolution.")
    }
    
    print("âœ… Initial validation passed")
    
  }, error = function(e) {
    stop(paste("Validation failed:", e$message))
  })
  
  # ==========================================================================
  # STEP 2: PREPARE EXPRESSION DATA
  # ==========================================================================
  
  print("\n--- STEP 2: Preparing expression data ---")
  
  prepared_data <- tryCatch({
    prepare_expression_for_deconv(
      expression_matrix = expression_matrix,
      organism = organism,
      min_genes = min_genes,
      user_groups = sample_groups  # ← Pass user groups here
    )
  }, error = function(e) {
    stop(paste("Expression data preparation failed:", e$message))
  })
  
  # Override sample_groups with prepared data (which prioritizes user input)
  if (!is.null(prepared_data$sample_groups)) {
    sample_groups <- prepared_data$sample_groups
  }
  
  if (prepared_data$conversion_rate < 0.3) {
    warning(paste0("Low gene conversion rate (", round(prepared_data$conversion_rate * 100, 1), 
                   "%). Results may be less reliable. ",
                   "Consider checking your gene ID format."))
  }
  
  # Override sample_groups if provided in prepared data
  if (!is.null(prepared_data$sample_groups)) {
    sample_groups <- prepared_data$sample_groups
  }
  
  # ==========================================================================
  # STEP 3: RUN DECONVOLUTION
  # ==========================================================================
  
  print("\n--- STEP 3: Running deconvolution algorithm ---")
  
  deconv_results <- tryCatch({
    
    switch(method,
           "xcell" = run_xcell_deconv(prepared_data$expr_matrix),
           "mcp_counter" = run_mcp_counter_deconv(prepared_data$expr_matrix),
           "epic" = run_epic_deconv(prepared_data$expr_matrix),
           stop("Unknown deconvolution method")
    )
    
  }, error = function(e) {
    stop(paste("Deconvolution analysis failed:", e$message))
  })
  
  print("âœ… Deconvolution algorithm completed successfully")
  
  # ==========================================================================
  # STEP 4: EXTRACT AND PROCESS RESULTS
  # ==========================================================================
  
  print("\n--- STEP 4: Processing deconvolution results ---")
  
  # Extract cell composition
  cell_composition <- extract_cell_composition(deconv_results, method)
  
  # Calculate confidence score
  confidence_score <- calculate_deconv_confidence(deconv_results, method)
  
  print(paste("Identified", nrow(cell_composition), "cell types"))
  print(paste("Confidence score:", confidence_score))
  
  # ==========================================================================
  # STEP 5: DEG CONTEXTUALIZATION (if DEG data provided)
  # ==========================================================================
  
  marker_gene_analysis <- NULL
  
  if (!is.null(deg_data)) {
    print("\n--- STEP 5: Linking DEGs to cell types ---")
    
    marker_gene_analysis <- tryCatch({
      identify_cell_type_markers_for_degs(
        deconv_results = deconv_results,
        cell_composition = cell_composition,
        deg_data = deg_data,
        method = method
      )
    }, error = function(e) {
      print(paste(" Could not link DEGs to cell types:", e$message))
      NULL
    })
    
    if (!is.null(marker_gene_analysis)) {
      print(paste("Identified", nrow(marker_gene_analysis), "DEGs with cell type associations"))
    }
  }
  
  group_comparison <- NULL
  
  if (!is.null(sample_groups) && length(unique(sample_groups$group)) > 1) {
    print("\n--- STEP 6: Comparing cell type proportions between groups ---")
    
    group_comparison <- tryCatch({
      compare_cell_proportions_between_groups(
        deconv_results = deconv_results,
        cell_composition = cell_composition,
        sample_groups = sample_groups,
        method = method
      )
    }, error = function(e) {
      print(paste("âš ï¸ Could not compare groups:", e$message))
      NULL
    })
    
    if (!is.null(group_comparison)) {
      print(paste("âœ… Compared", length(unique(sample_groups$group)), "groups"))
    }
  }
  
  print("\n--- STEP 7: Preparing final results structure ---")
  
  # Get dominant cell type
  dominant_cell_type <- cell_composition$cell_type[which.max(cell_composition$proportion)]
  
  # Count marker genes with meaningful specificity only
  n_marker_genes <- if (!is.null(marker_gene_analysis)) {
    sum(marker_gene_analysis$specificity_score >= 0.5, na.rm = TRUE)
  } else {
    0
  }
  
  # Create comprehensive results object
  final_results <- list(
    
    # Analysis metadata
    analysis_type = "deconv",
    method = method,
    timestamp = Sys.time(),
    
    # Core deconvolution results
    cell_composition = cell_composition,
    raw_deconv_results = deconv_results,
    
    # DEG context (if available)
    marker_genes = marker_gene_analysis,
    
    # Group comparison (if available)
    group_comparison = group_comparison,
    
    # Data preparation info
    data_info = list(
      n_samples = ncol(prepared_data$expr_matrix),
      n_genes = nrow(prepared_data$expr_matrix),
      conversion_rate = prepared_data$conversion_rate,
      sample_groups = sample_groups
    ),
    
    # Deconvolution-specific data structure (for UI compatibility)
    deconv_data = list(
      cell_composition = cell_composition,
      marker_genes = marker_gene_analysis,
      group_comparison = group_comparison,
      raw_scores = deconv_results
    ),
    
    # Summary statistics (for dashboard cards)
    summary_stats = list(
      deconv = list(
        total_cell_types = nrow(cell_composition),
        dominant_cell_type = dominant_cell_type,
        confidence_score = confidence_score,
        marker_genes = n_marker_genes,
        has_groups = !is.null(sample_groups)
      )
    )
  )
  
  print("============================================================")
  print("     CELL TYPE DECONVOLUTION ANALYSIS COMPLETE")
  print("============================================================")
  print(paste("Cell types identified:", nrow(cell_composition)))
  print(paste("Dominant cell type:", dominant_cell_type))
  print(paste("Confidence score:", confidence_score))
  if (!is.null(marker_gene_analysis)) {
    print(paste("Marker genes linked:", nrow(marker_gene_analysis)))
  }
  if (!is.null(group_comparison)) {
    print(paste("Group comparison available: YES"))
  }
  print("============================================================")
  
  return(final_results)
}


# HELPER FUNCTIONS FOR DEG CONTEXTUALIZATION

identify_cell_type_markers_for_degs <- function(deconv_results,
                                                cell_composition,
                                                deg_data,
                                                method) {
  # Disabled: the previous implementation assigned DEGs to cell types by list position with a
  # random specificity score, which is not biologically meaningful. Returns no table.
  return(NULL)
  
  print("🔬 Linking significant DEGs to cell type markers...")
  
  tryCatch({
    
    if (is.null(deg_data) || nrow(deg_data) == 0) {
      print("❌ No DEG data provided")
      return(NULL)
    }
    
    print(paste("📊 Input DEG data:", nrow(deg_data), "genes"))
    print(paste("   Available columns:", paste(colnames(deg_data), collapse = ", ")))
    
    # ========================================================================
    # CRITICAL FIX: Extract gene symbols, not ENSEMBL IDs
    # ========================================================================
    
    # Priority 1: Use gene_symbol column if it exists
    if ("gene_symbol" %in% colnames(deg_data)) {
      deg_genes <- deg_data$gene_symbol
      print("✅ Using gene_symbol column")
      
      # Priority 2: Use gene column
    } else if ("gene" %in% colnames(deg_data)) {
      deg_genes <- deg_data$gene
      print("✅ Using gene column")
      
      # Priority 3: Convert gene_id (ENSEMBL) to symbols
    } else if ("gene_id" %in% colnames(deg_data)) {
      print("⚠️ Only gene_id (ENSEMBL) available - need to convert to symbols")
      
      # Need to convert ENSEMBL IDs to gene symbols
      # This is the MISSING STEP!
      gene_ids <- deg_data$gene_id
      
      # Try to find if conversion was already done
      if (exists("convert_gene_ids_to_symbols_deg")) {
        print("   Converting ENSEMBL IDs to gene symbols...")
        
        # Determine organism from deconv_results context
        organism <- "human"  # Default, adjust if needed
        
        conversion_result <- convert_gene_ids_to_symbols_deg(
          gene_ids = gene_ids,
          organism = organism
        )
        
        # Extract symbols from the data.frame returned
        if (is.data.frame(conversion_result)) {
          deg_genes <- conversion_result$gene_symbol
        } else {
          deg_genes <- conversion_result
        }
        
        print(paste("   Converted", sum(!is.na(deg_genes) & deg_genes != ""), "IDs to symbols"))
        
      } else {
        # Fallback: Use the IDs as-is (will likely fail matching)
        print("   ⚠️ WARNING: Conversion function not available, using ENSEMBL IDs")
        deg_genes <- gsub("\\..*$", "", gene_ids)  # Remove version numbers at least
      }
      
    } else {
      # Last resort: use rownames
      deg_genes <- rownames(deg_data)
      print("⚠️ Using rownames as gene identifiers")
    }
    
    # ========================================================================
    # Clean and validate gene symbols
    # ========================================================================
    
    # Remove NA, empty strings, and ENSEMBL IDs that weren't converted
    valid_mask <- !is.na(deg_genes) & 
      deg_genes != "" & 
      deg_genes != "-" &
      !grepl("^ENSG", deg_genes) &
      !grepl("^ENST", deg_genes)
    
    deg_genes_clean <- deg_genes[valid_mask]
    deg_data_clean <- deg_data[valid_mask, ]
    
    print(paste("✅ Extracted", length(deg_genes_clean), "valid gene symbols from DEGs"))
    print(paste("   Example genes:", paste(head(deg_genes_clean, 5), collapse = ", ")))
    
    if (length(deg_genes_clean) == 0) {
      print("❌ No valid gene symbols after filtering")
      return(NULL)
    }
    
    # ========================================================================
    # Get fold changes and regulation direction
    # ========================================================================
    
    fc_col <- if ("log2FC" %in% colnames(deg_data_clean)) "log2FC"
    else if ("log2FoldChange" %in% colnames(deg_data_clean)) "log2FoldChange"
    else if ("logFC" %in% colnames(deg_data_clean)) "logFC"
    else NULL
    
    if (!is.null(fc_col)) {
      deg_fc <- as.numeric(deg_data_clean[[fc_col]])
      names(deg_fc) <- deg_genes_clean
      
      deg_regulation <- ifelse(deg_fc > 0, "Upregulated", "Downregulated")
      names(deg_regulation) <- deg_genes_clean
      
      n_up <- sum(deg_fc > 0, na.rm = TRUE)
      n_down <- sum(deg_fc < 0, na.rm = TRUE)
      
      print(paste("   Upregulated:", n_up))
      print(paste("   Downregulated:", n_down))
    } else {
      print("⚠️ No fold change column found")
      deg_fc <- rep(0, length(deg_genes_clean))
      names(deg_fc) <- deg_genes_clean
      deg_regulation <- rep("Unknown", length(deg_genes_clean))
      names(deg_regulation) <- deg_genes_clean
    }
    
    # ========================================================================
    # Match DEGs to cell types using enrichment scores
    # ========================================================================
    
    if (method %in% c("xcell", "mcp_counter")) {
      # Results: rows = cell types, cols = samples
      cell_type_matrix <- as.matrix(deconv_results)
      cell_type_names <- rownames(cell_type_matrix)
      
      # Calculate mean enrichment per cell type
      cell_type_scores <- rowMeans(cell_type_matrix, na.rm = TRUE)
      names(cell_type_scores) <- cell_type_names
      
    } else if (method == "epic") {
      # Results: rows = samples, cols = cell types
      cell_type_matrix <- as.matrix(deconv_results)
      cell_type_names <- colnames(cell_type_matrix)
      
      cell_type_scores <- colMeans(cell_type_matrix, na.rm = TRUE)
      names(cell_type_scores) <- cell_type_names
    }
    
    # Sort cell types by enrichment score
    cell_type_scores_sorted <- sort(cell_type_scores, decreasing = TRUE)
    
    print(paste("📊 Cell type scores (top 5):"))
    print(paste("   ", names(head(cell_type_scores_sorted, 5)), ":", 
                round(head(cell_type_scores_sorted, 5), 3)))
    
    # ========================================================================
    # IMPROVED: Distribute DEGs across cell types based on expression patterns
    # ========================================================================
    
    # For each DEG, assign to top 1-3 cell types
    # This is still a heuristic - proper implementation needs signature databases
    
    marker_table_list <- lapply(seq_along(deg_genes_clean), function(i) {
      gene <- deg_genes_clean[i]
      
      # Assign to top 1 cell type (could be enhanced to use gene-specific logic)
      # For now, use a round-robin + regulation-based distribution
      
      if (deg_regulation[gene] == "Upregulated") {
        # Upregulated genes -> assign to most enriched cell types
        top_cells <- names(head(cell_type_scores_sorted, 10))
        # Rotate through top 10
        cell_idx <- ((i - 1) %% 10) + 1
        assigned_cell <- top_cells[cell_idx]
      } else {
        # Downregulated genes -> assign to moderately enriched cell types
        mid_cells <- names(cell_type_scores_sorted[11:min(30, length(cell_type_scores_sorted))])
        if (length(mid_cells) > 0) {
          cell_idx <- ((i - 1) %% length(mid_cells)) + 1
          assigned_cell <- mid_cells[cell_idx]
        } else {
          assigned_cell <- names(cell_type_scores_sorted)[1]
        }
      }
      
      data.frame(
        gene = gene,
        cell_type = assigned_cell,
        log2FoldChange = deg_fc[gene],
        regulation = deg_regulation[gene],
        cell_type_score = cell_type_scores[assigned_cell],
        specificity_score = runif(1, 0.3, 0.9),  # Placeholder
        stringsAsFactors = FALSE
      )
    })
    
    # Combine all entries
    marker_table <- do.call(rbind, marker_table_list)
    
    # Add expression level category
    marker_table$expression_level <- cut(
      abs(marker_table$log2FoldChange),
      breaks = c(0, 1, 2, Inf),
      labels = c("Low", "Medium", "High"),
      include.lowest = TRUE
    )
    
    # Summary
    n_unique_genes <- length(unique(marker_table$gene))
    n_cell_types <- length(unique(marker_table$cell_type))
    
    print(paste("✅ Created marker gene table with", nrow(marker_table), "DEG-cell type associations"))
    print(paste("   Unique DEGs:", n_unique_genes))
    print(paste("   Cell types involved:", n_cell_types))
    print(paste("   Top cell types:", paste(head(names(table(marker_table$cell_type)), 5), collapse = ", ")))
    
    return(marker_table)
    
  }, error = function(e) {
    print(paste("❌ Error creating marker gene table:", e$message))
    print("Stack trace:")
    print(traceback())
    return(NULL)
  })
}


compare_cell_proportions_between_groups <- function(deconv_results, 
                                                    cell_composition,
                                                    sample_groups, 
                                                    method) {
  
  print("Comparing cell type proportions between groups...")
  
  tryCatch({
    
    # Ensure sample names match
    if (method %in% c("xcell", "mcp_counter")) {
      # Results are cell_types x samples
      sample_names <- colnames(deconv_results)
    } else if (method == "epic") {
      # Results are samples x cell_types
      sample_names <- rownames(deconv_results)
    }
    
    # Match sample groups to results
    sample_groups_matched <- sample_groups[match(sample_names, sample_groups$sample), ]
    
    if (any(is.na(sample_groups_matched$group))) {
      print("Some samples don't have group assignments")
    }
    
    # Get unique groups
    groups <- unique(sample_groups_matched$group)
    groups <- groups[!is.na(groups)]
    
    if (length(groups) < 2) {
      print("Need at least 2 groups for comparison")
      return(NULL)
    }
    
    print(paste("Comparing groups:", paste(groups, collapse = " vs ")))
    
    # Prepare comparison table
    comparison_results <- data.frame()
    
    if (method %in% c("xcell", "mcp_counter")) {
      # For each cell type (row), compare groups
      
      for (cell_type in rownames(deconv_results)) {
        
        # Get values for each group
        group1_vals <- deconv_results[cell_type, sample_groups_matched$group == groups[1]]
        group2_vals <- deconv_results[cell_type, sample_groups_matched$group == groups[2]]
        
        # Remove NAs
        group1_vals <- group1_vals[!is.na(group1_vals)]
        group2_vals <- group2_vals[!is.na(group2_vals)]
        
        if (length(group1_vals) > 1 && length(group2_vals) > 1) {
          
          # Calculate means
          mean_g1 <- mean(group1_vals)
          mean_g2 <- mean(group2_vals)
          
          # Perform t-test with error handling for constant data
          test_result <- tryCatch({
            t.test(group1_vals, group2_vals)
          }, error = function(e) {
            # If t-test fails (e.g., "data are essentially constant"), 
            # create a dummy result
            if (grepl("essentially constant", e$message, ignore.case = TRUE)) {
              # Data has no variance - create manual comparison
              list(
                p.value = if (abs(mean_g1 - mean_g2) < 1e-10) 1.0 else NA,
                statistic = 0,
                parameter = length(group1_vals) + length(group2_vals) - 2,
                conf.int = c(NA, NA),
                estimate = c(mean_g1, mean_g2),
                null.value = 0,
                alternative = "two.sided",
                method = "Welch Two Sample t-test (failed - constant data)"
              )
            } else {
              # Other errors - return NA result
              list(p.value = NA)
            }
          })
          
          # Calculate effect size (Cohen's d)
          mean_diff <- mean_g1 - mean_g2
          pooled_sd <- sqrt((var(group1_vals) + var(group2_vals)) / 2)
          
          # Handle zero pooled_sd
          if (pooled_sd == 0 || is.na(pooled_sd)) {
            cohens_d <- 0
          } else {
            cohens_d <- mean_diff / pooled_sd
          }
          
          # ================================================================
          # FIX: Safe fold change calculation
          # ================================================================
          
          # Define a small threshold to avoid division by near-zero
          min_threshold <- 1e-10
          
          if (abs(mean_g2) < min_threshold && abs(mean_g1) < min_threshold) {
            # Both means are essentially zero - no meaningful fold change
            fold_change <- 1.0
            fold_change_method <- "both_zero"
            
          } else if (abs(mean_g2) < min_threshold) {
            # Denominator is zero/near-zero but numerator is not
            # Report as "Inf" or very large number with cap
            if (mean_g1 > 0) {
              fold_change <- Inf
              fold_change_method <- "divide_by_zero_positive"
            } else {
              fold_change <- -Inf
              fold_change_method <- "divide_by_zero_negative"
            }
            
          } else {
            # Normal calculation
            fold_change <- mean_g1 / mean_g2
            fold_change_method <- "normal"
          }
          
          # ================================================================
          # Alternative: Log2 Fold Change (more robust for small values)
          # ================================================================
          
          # Add pseudocount to avoid log(0)
          pseudocount <- 1e-10
          log2_fold_change <- log2((mean_g1 + pseudocount) / (mean_g2 + pseudocount))
          
          # ================================================================
          
          comparison_results <- rbind(comparison_results, data.frame(
            cell_type = cell_type,
            group1 = groups[1],
            group2 = groups[2],
            mean_group1 = mean_g1,
            mean_group2 = mean_g2,
            fold_change = fold_change,
            log2_fold_change = log2_fold_change,  # Add this for better interpretation
            p_value = test_result$p.value,
            cohens_d = cohens_d,
            significance = ifelse(test_result$p.value < 0.05, "Significant", "Not Significant"),
            stringsAsFactors = FALSE
          ))
        }
      }
      
    } else if (method == "epic") {
      # For each cell type (column), compare groups
      
      for (cell_type in colnames(deconv_results)) {
        
        # Get values for each group
        group1_vals <- deconv_results[sample_groups_matched$group == groups[1], cell_type]
        group2_vals <- deconv_results[sample_groups_matched$group == groups[2], cell_type]
        
        # Remove NAs
        group1_vals <- group1_vals[!is.na(group1_vals)]
        group2_vals <- group2_vals[!is.na(group2_vals)]
        
        if (length(group1_vals) > 1 && length(group2_vals) > 1) {
          
          # Calculate means
          mean_g1 <- mean(group1_vals)
          mean_g2 <- mean(group2_vals)
          
          # Perform t-test with error handling for constant data
          test_result <- tryCatch({
            t.test(group1_vals, group2_vals)
          }, error = function(e) {
            # If t-test fails (e.g., "data are essentially constant"), 
            # create a dummy result
            if (grepl("essentially constant", e$message, ignore.case = TRUE)) {
              # Data has no variance - create manual comparison
              list(
                p.value = if (abs(mean_g1 - mean_g2) < 1e-10) 1.0 else NA,
                statistic = 0,
                parameter = length(group1_vals) + length(group2_vals) - 2,
                conf.int = c(NA, NA),
                estimate = c(mean_g1, mean_g2),
                null.value = 0,
                alternative = "two.sided",
                method = "Welch Two Sample t-test (failed - constant data)"
              )
            } else {
              # Other errors - return NA result
              list(p.value = NA)
            }
          })
          
          mean_diff <- mean_g1 - mean_g2
          pooled_sd <- sqrt((var(group1_vals) + var(group2_vals)) / 2)
          
          # Handle zero pooled_sd
          if (pooled_sd == 0 || is.na(pooled_sd)) {
            cohens_d <- 0
          } else {
            cohens_d <- mean_diff / pooled_sd
          }
          
          # ================================================================
          # FIX: Safe fold change calculation (same as above)
          # ================================================================
          
          min_threshold <- 1e-10
          
          if (abs(mean_g2) < min_threshold && abs(mean_g1) < min_threshold) {
            fold_change <- 1.0
          } else if (abs(mean_g2) < min_threshold) {
            fold_change <- ifelse(mean_g1 > 0, Inf, -Inf)
          } else {
            fold_change <- mean_g1 / mean_g2
          }
          
          # Log2 fold change
          pseudocount <- 1e-10
          log2_fold_change <- log2((mean_g1 + pseudocount) / (mean_g2 + pseudocount))
          
          # ================================================================
          
          comparison_results <- rbind(comparison_results, data.frame(
            cell_type = cell_type,
            group1 = groups[1],
            group2 = groups[2],
            mean_group1 = mean_g1,
            mean_group2 = mean_g2,
            fold_change = fold_change,
            log2_fold_change = log2_fold_change,
            p_value = test_result$p.value,
            cohens_d = cohens_d,
            significance = ifelse(test_result$p.value < 0.05, "Significant", "Not Significant"),
            stringsAsFactors = FALSE
          ))
        }
      }
    }
    
    # Adjust p-values for multiple testing
    if (nrow(comparison_results) > 0) {
      comparison_results$p_adjusted <- p.adjust(comparison_results$p_value, method = "BH")
      
      # Sort by p-value
      comparison_results <- comparison_results[order(comparison_results$p_value), ]
      
      print(paste("Compared", nrow(comparison_results), "cell types between groups"))
      print(paste("Significant differences (p < 0.05):", 
                  sum(comparison_results$p_value < 0.05, na.rm = TRUE)))
      
      # Print warning for Inf fold changes
      inf_count <- sum(is.infinite(comparison_results$fold_change))
      if (inf_count > 0) {
        print(paste("⚠️ Warning:", inf_count, "cell types have Inf fold change (division by zero/near-zero)"))
        print("   These cell types have very low/zero expression in one group")
        print("   Consider using log2_fold_change for better interpretation")
      }
    }
    
    return(comparison_results)
    
  }, error = function(e) {
    print(paste("Error in group comparison:", e$message))
    return(NULL)
  })
}



# VISUALIZATION FUNCTIONS
create_cell_composition_barplot <- function(deconv_results, method, sample_groups = NULL) {
  
  cat("Creating cell type composition bar plot...\n")
  
  tryCatch({
    library(ggplot2)
    library(plotly)
    library(reshape2)
    library(dplyr)
    
    # Extract per-sample cell type scores
    if (method %in% c("xcell", "mcp_counter")) {
      cell_type_matrix <- as.matrix(deconv_results)
      sample_names <- colnames(cell_type_matrix)
      cell_types <- rownames(cell_type_matrix)
    } else if (method == "epic") {
      cell_type_matrix <- t(as.matrix(deconv_results))
      sample_names <- colnames(cell_type_matrix)
      cell_types <- rownames(cell_type_matrix)
    }
    
    cat("Samples:", length(sample_names), "\n")
    cat("Cell types:", length(cell_types), "\n")
    
    # Normalize to proportions per sample
    cell_type_props <- apply(cell_type_matrix, 2, function(x) x / sum(x, na.rm = TRUE))
    
    # Convert to long format for plotting
    plot_data <- melt(cell_type_props)
    colnames(plot_data) <- c("cell_type", "sample", "proportion")
    
    # Add group information if available
    if (!is.null(sample_groups)) {
      plot_data$group <- sample_groups$group[match(plot_data$sample, sample_groups$sample)]
    } else {
      plot_data$group <- "All Samples"
    }
    
    # ✅ CRITICAL FIX 1: Ensure all columns are factors
    plot_data$sample <- factor(plot_data$sample, levels = unique(plot_data$sample))
    plot_data$cell_type <- factor(plot_data$cell_type, levels = unique(plot_data$cell_type))
    plot_data$group <- factor(plot_data$group, levels = unique(plot_data$group))
    
    cat("Unique groups:", length(unique(plot_data$group)), "\n")
    cat("Groups:", paste(unique(plot_data$group), collapse = ", "), "\n")
    
    # Handle large sample sizes (>50 samples)
    n_samples <- length(unique(plot_data$sample))
    
    if (n_samples > 50) {
      # Create AGGREGATED view by group
      cat("Large dataset detected:", n_samples, "samples. Creating aggregated view...\n")
      
      agg_data <- plot_data %>%
        group_by(cell_type, group) %>%
        summarise(
          mean_proportion = mean(proportion, na.rm = TRUE),
          n_samples = n(),
          .groups = "drop"
        )
      
      agg_data$group_name <- agg_data$group
      
      p <- ggplot(agg_data, aes(x = group, y = mean_proportion * 100, fill = cell_type,
                                customdata = group_name,
                                text = paste0("Group: ", group, 
                                              "\nCell Type: ", cell_type,
                                              "\nMean: ", round(mean_proportion * 100, 2), "%",
                                              "\nSamples: ", n_samples,
                                              "\n\n🔍 Click to view individual samples"))) +
        geom_bar(stat = "identity", position = "stack", width = 0.7) +
        labs(
          title = paste("Average Cell Type Composition by Group (n =", n_samples, "samples)"),
          subtitle = "🔍 Click on any bar to see individual sample details",
          x = "Group",
          y = "Mean Proportion (%)",
          fill = "Cell Type"
        ) +
        theme_minimal() +
        theme(
          axis.text.x = element_text(angle = 0, hjust = 0.5, size = 12, face = "bold"),
          axis.text.y = element_text(size = 11),
          axis.title = element_text(size = 13, face = "bold"),
          legend.position = "right",
          plot.title = element_text(hjust = 0.5, size = 14, face = "bold"),
          plot.subtitle = element_text(hjust = 0.5, size = 11, color = "#666"),
          panel.grid.major.x = element_blank()
        ) +
        scale_fill_viridis_d(option = "turbo", direction = -1)
      
      p_interactive <- ggplotly(p, height = 550, tooltip = "text", source = "deconv_barplot_main") %>%
        event_register("plotly_click") %>%
        layout(
          font = list(family = "Arial, sans-serif"),
          legend = list(orientation = "v", x = 1.02, y = 1),
          margin = list(l = 60, r = 150, t = 80, b = 100)
        )
      
      return(list(
        plot = p_interactive,
        full_data = plot_data,
        is_aggregated = TRUE
      ))
      
    } else {
      # Original per-sample view for smaller datasets
      cat("Creating per-sample view...\n")
      
      # ✅ CRITICAL FIX 2: Handle faceting properly
      if (!is.null(sample_groups) && length(unique(plot_data$group)) > 1) {
        cat("Multiple groups detected, creating faceted plot\n")
        
        # Create separate plots for each group to avoid label issues
        plot_list <- list()
        
        for (grp in unique(plot_data$group)) {
          grp_data <- plot_data %>% filter(group == grp)
          
          # ✅ Drop unused factor levels
          grp_data$sample <- droplevels(grp_data$sample)
          
          p_grp <- ggplot(grp_data, aes(x = sample, y = proportion * 100, fill = cell_type)) +
            geom_bar(stat = "identity", position = "stack", width = 0.8) +
            labs(
              title = as.character(grp),
              x = "Sample",
              y = "Proportion (%)",
              fill = "Cell Type"
            ) +
            theme_minimal() +
            theme(
              axis.text.x = element_text(angle = 45, hjust = 1, size = 10, face = "bold"),
              axis.text.y = element_text(size = 11),
              axis.title = element_text(size = 12, face = "bold"),
              plot.title = element_text(hjust = 0.5, size = 13, face = "bold"),
              legend.position = "right",
              panel.grid.major.x = element_blank()
            ) +
            scale_fill_viridis_d(option = "turbo", direction = -1)
          
          plot_list[[as.character(grp)]] <- p_grp
        }
        
        # Combine plots using patchwork or just use first one with proper faceting
        # For now, use facet_wrap but with proper data handling
        
        # ✅ BETTER FIX: Use facet_grid with space="free_x"
        p <- ggplot(plot_data, aes(x = sample, y = proportion * 100, fill = cell_type)) +
          geom_bar(stat = "identity", position = "stack", width = 0.8) +
          labs(
            x = "Sample",
            y = "Proportion (%)",
            fill = "Cell Type"
          ) +
          theme_minimal() +
          theme(
            axis.text.x = element_text(angle = 45, hjust = 1, size = 10, face = "bold"),
            axis.text.y = element_text(size = 11),
            axis.title = element_text(size = 13, face = "bold"),
            legend.position = "right",
            panel.grid.major.x = element_blank(),
            strip.text = element_text(size = 12, face = "bold")
          ) +
          scale_fill_viridis_d(option = "turbo", direction = -1) +
          # ✅ KEY FIX: Use facet_grid with space="free_x" and drop=TRUE
          facet_grid(~ group, scales = "free_x", space = "free_x", drop = TRUE)
        
      } else {
        # Single group - no faceting needed
        cat("Single group, no faceting\n")
        
        p <- ggplot(plot_data, aes(x = sample, y = proportion * 100, fill = cell_type)) +
          geom_bar(stat = "identity", position = "stack", width = 0.8) +
          labs(
            x = "Sample",
            y = "Proportion (%)",
            fill = "Cell Type"
          ) +
          theme_minimal() +
          theme(
            axis.text.x = element_text(angle = 45, hjust = 1, size = 11, face = "bold"),
            axis.text.y = element_text(size = 11),
            axis.title = element_text(size = 13, face = "bold"),
            legend.position = "right",
            panel.grid.major.x = element_blank()
          ) +
          scale_fill_viridis_d(option = "turbo", direction = -1)
      }
      
      # Convert to plotly
      
      p_interactive <- ggplotly(p, height = 550) %>%
        layout(
          font = list(family = "Arial, sans-serif"),
          legend = list(orientation = "v", x = 1.02, y = 1),
          margin = list(l = 60, r = 150, t = 60, b = 100),
          # Fix background size
          autosize = TRUE,
          paper_bgcolor = 'white',
          plot_bgcolor = 'white'
        ) 
      
      cat("Bar plot created successfully\n")
      return(p_interactive)
    }
    
  }, error = function(e) {
    cat("ERROR creating bar plot:", e$message, "\n")
    print(traceback())
    
    p_empty <- ggplot() +
      annotate("text", x = 0.5, y = 0.5, 
               label = paste("Plot generation failed:", e$message), 
               size = 5, color = "red") +
      theme_void()
    return(ggplotly(p_empty))
  })
}


create_cell_composition_heatmap <- function(deconv_results, method, sample_groups = NULL) {
  
  print("Creating cell type composition heatmap...")
  
  tryCatch({
    library(ggplot2)
    library(plotly)
    library(reshape2)
    library(dplyr)
    
    # Extract per-sample cell type scores
    if (method %in% c("xcell", "mcp_counter")) {
      cell_type_matrix <- as.matrix(deconv_results)
    } else if (method == "epic") {
      cell_type_matrix <- t(as.matrix(deconv_results))
    }
    
    n_samples <- ncol(cell_type_matrix)
    n_cell_types <- nrow(cell_type_matrix)
    
    print(paste("Heatmap data:", n_cell_types, "cell types ×", n_samples, "samples"))
    
    # ✅ ADAPTIVE STRATEGY FOR LARGE DATASETS
    if (n_samples > 100) {
      print(paste("⚠️ Large dataset detected:", n_samples, "samples"))
      print("   Creating aggregated heatmap by group...")
      
      # Strategy: Show average per group instead of individual samples
      if (!is.null(sample_groups)) {
        
        # Calculate mean per group for each cell type
        agg_matrix <- sapply(unique(sample_groups$group), function(grp) {
          grp_samples <- sample_groups$sample[sample_groups$group == grp]
          grp_samples <- intersect(grp_samples, colnames(cell_type_matrix))
          
          if (length(grp_samples) > 0) {
            rowMeans(cell_type_matrix[, grp_samples, drop = FALSE], na.rm = TRUE)
          } else {
            rep(NA, nrow(cell_type_matrix))
          }
        })
        
        rownames(agg_matrix) <- rownames(cell_type_matrix)
        colnames(agg_matrix) <- unique(sample_groups$group)
        
        cell_type_matrix <- agg_matrix
        n_samples <- ncol(cell_type_matrix)
        
        print(paste("   Aggregated to", n_samples, "groups"))
      }
    }
    
    # ✅ Filter to top variable cell types (max 25 for clarity)
    max_cell_types <- if (n_samples > 50) 20 else 25
    
    if (n_cell_types > max_cell_types) {
      print(paste("   Filtering from", n_cell_types, "to top", max_cell_types, "most variable cell types"))
      row_vars <- apply(cell_type_matrix, 1, var, na.rm = TRUE)
      top_indices <- order(row_vars, decreasing = TRUE)[1:max_cell_types]
      cell_type_matrix <- cell_type_matrix[top_indices, ]
    }
    
    # Scale for better visualization (z-score)
    cell_type_scaled <- t(scale(t(cell_type_matrix)))
    
    # Replace any infinite or NA values
    cell_type_scaled[!is.finite(cell_type_scaled)] <- 0
    
    # Convert to long format
    plot_data <- melt(cell_type_scaled)
    colnames(plot_data) <- c("cell_type", "sample", "scaled_score")
    
    # ✅ Add group annotation if available
    if (!is.null(sample_groups) && n_samples <= 100) {
      plot_data$group <- sample_groups$group[match(plot_data$sample, sample_groups$sample)]
      
      # Order samples by group for better visualization
      plot_data <- plot_data %>%
        arrange(group, sample) %>%
        mutate(sample = factor(sample, levels = unique(sample)))
    } else {
      plot_data$sample <- factor(plot_data$sample, levels = unique(plot_data$sample))
    }
    
    # Order cell types by hierarchical clustering
    if (nrow(cell_type_scaled) > 1) {
      tryCatch({
        cell_dist <- dist(cell_type_scaled)
        cell_hclust <- hclust(cell_dist, method = "ward.D2")
        plot_data$cell_type <- factor(plot_data$cell_type, 
                                      levels = rownames(cell_type_scaled)[cell_hclust$order])
      }, error = function(e) {
        print("   Clustering failed, using default order")
      })
    }
    
    # ✅ ADAPTIVE HEIGHT based on data size
    plot_height <- max(500, min(1000, nrow(cell_type_scaled) * 25))
    
    # Create heatmap with plotly for better interactivity
    p_interactive <- plot_ly(
      data = plot_data,
      x = ~sample,
      y = ~cell_type,
      z = ~scaled_score,
      type = "heatmap",
      colors = colorRamp(c("#2166ac", "#f7f7f7", "#b2182b")),  # Blue-White-Red
      zauto = FALSE,
      zmin = -3,
      zmax = 3,
      hovertemplate = paste(
        "<b>%{y}</b><br>",
        "Sample: %{x}<br>",
        "Z-score: %{z:.2f}<br>",
        "<extra></extra>"
      ),
      colorbar = list(
        title = "Z-score",
        titleside = "right",
        len = 0.7,
        thickness = 15,
        x = 1.02
      )
    ) %>%
      layout(
        title = list(
          text = if (n_samples > 100) {
            paste("Cell Type Enrichment (Averaged by Group)")
          } else {
            "Cell Type Enrichment Heatmap"
          },
          font = list(size = 14, family = "Arial", color = "#333")
        ),
        xaxis = list(
          title = if (n_samples > 100) "Group" else "Sample",
          tickangle = if (n_samples > 20) -45 else -90,
          tickfont = list(size = if (n_samples > 50) 8 else 10),
          side = "bottom"
        ),
        yaxis = list(
          title = "Cell Type",
          tickfont = list(size = 10),
          autorange = "reversed"  # Top to bottom
        ),
        height = plot_height,
        margin = list(l = 150, r = 80, t = 80, b = 120),
        font = list(family = "Arial, sans-serif"),
        paper_bgcolor = "white",
        plot_bgcolor = "white"
      )
    
    # ✅ Add group separators if groups exist and samples <= 100
    if (!is.null(sample_groups) && n_samples <= 100 && length(unique(sample_groups$group)) > 1) {
      
      # Calculate group boundaries
      sample_order <- levels(plot_data$sample)
      group_info <- data.frame(
        sample = sample_order,
        group = sample_groups$group[match(sample_order, sample_groups$sample)]
      )
      
      group_changes <- which(diff(as.numeric(factor(group_info$group))) != 0)
      
      # Create a list to hold the line shapes
      line_shapes <- list()
      for (pos in group_changes) {
        # Plotly's categorical axes are 0-indexed internally. A line at x=0.5 is between
        # the first and second category. Our 'pos' is 1-indexed from R, so we subtract 0.5
        # to place the line correctly between the bars.
        line_shapes[[length(line_shapes) + 1]] <- list(
          type = "line",
          x0 = pos - 0.5, x1 = pos - 0.5,
          y0 = 0, y1 = 1,
          xref = "x",      # The line's x-coordinates refer to the x-axis
          yref = "paper",  # The line's y-coordinates span the full plot height (from 0 to 1)
          line = list(color = "black", width = 2, dash = "solid")
        )
      }
      
      # Add all shapes to the layout at once for better performance
      if (length(line_shapes) > 0) {
        p_interactive <- p_interactive %>% layout(shapes = line_shapes)
      }
    }
    
    print(paste("✅ Heatmap created successfully:", plot_height, "px height"))
    return(p_interactive)
    
  }, error = function(e) {
    print(paste("❌ Error creating heatmap:", e$message))
    traceback()
    
    # Return informative error plot
    p_empty <- plot_ly() %>%
      add_annotations(
        text = paste("Heatmap generation failed:", e$message),
        x = 0.5, y = 0.5,
        xref = "paper", yref = "paper",
        showarrow = FALSE,
        font = list(size = 16, color = "red")
      ) %>%
      layout(
        xaxis = list(visible = FALSE),
        yaxis = list(visible = FALSE),
        height = 600
      )
    
    return(p_empty)
  })
}


create_group_comparison_boxplot <- function(deconv_results, 
                                            method, 
                                            sample_groups,
                                            top_n = 10) {
  
  print("Creating group comparison box plots...")
  
  tryCatch({
    library(ggplot2)
    library(plotly)
    library(reshape2)
    
    if (is.null(sample_groups) || length(unique(sample_groups$group)) < 2) {
      print("Need at least 2 groups for comparison plot")
      return(NULL)
    }
    
    # Extract data
    if (method %in% c("xcell", "mcp_counter")) {
      cell_type_matrix <- as.matrix(deconv_results)
      sample_names <- colnames(cell_type_matrix)
    } else if (method == "epic") {
      cell_type_matrix <- t(as.matrix(deconv_results))
      sample_names <- colnames(cell_type_matrix)
    }
    
    # Convert to long format
    plot_data <- melt(cell_type_matrix)
    colnames(plot_data) <- c("cell_type", "sample", "score")
    
    # Add group information
    plot_data$group <- sample_groups$group[match(plot_data$sample, sample_groups$sample)]
    
    # Calculate variance to select most variable cell types
    cell_variance <- aggregate(score ~ cell_type, data = plot_data, FUN = var)
    top_cell_types <- head(cell_variance[order(-cell_variance$score), ], top_n)$cell_type
    
    # Filter to top variable cell types
    plot_data_filtered <- plot_data[plot_data$cell_type %in% top_cell_types, ]
    
    # Create box plot
    p <- ggplot(plot_data_filtered, aes(x = group, y = score, fill = group)) +
      geom_boxplot(outlier.shape = 16, outlier.size = 2, alpha = 0.7) +
      geom_jitter(width = 0.2, alpha = 0.3, size = 1.5) +
      facet_wrap(~cell_type, scales = "free_y", ncol = 3) +
      labs(
        title = "Cell Type Proportions by Group",
        subtitle = paste("Top", top_n, "most variable cell types"),
        x = "Group",
        y = "Score",
        fill = "Group"
      ) +
      theme_minimal() +
      theme(
        axis.text.x = element_text(angle = 45, hjust = 1),
        plot.title = element_text(face = "bold", size = 14),
        plot.subtitle = element_text(size = 10, color = "gray40"),
        strip.text = element_text(face = "bold", size = 9)
      ) +
      scale_fill_brewer(palette = "Set2")
    
    p_interactive <- ggplotly(p, height = 700)
    
    print("Box plot created successfully")
    return(p_interactive)
    
  }, error = function(e) {
    print(paste("Error creating box plot:", e$message))
    return(NULL)
  })
}

create_dominant_celltype_pie <- function(cell_composition) {
  
  print("Creating dominant cell type pie chart...")
  
  tryCatch({
    library(plotly)
    
    # Get top 8 cell types by proportion
    top_cells <- head(cell_composition[order(-cell_composition$proportion), ], 8)
    
    # Aggregate remaining as "Other"
    if (nrow(cell_composition) > 8) {
      other_proportion <- sum(cell_composition$proportion[9:nrow(cell_composition)])
      top_cells <- rbind(top_cells, data.frame(
        cell_type = "Other",
        proportion = other_proportion,
        mean_score = NA,
        sd_score = NA,
        p_value = NA,
        stringsAsFactors = FALSE
      ))
    }
    
    # Create pie chart
    p <- plot_ly(
      data = top_cells,
      labels = ~cell_type,
      values = ~proportion,
      type = 'pie',
      textposition = 'inside',
      textinfo = 'label+percent',
      hoverinfo = 'text',
      text = ~paste(cell_type, "\n", round(proportion * 100, 1), "%"),
      marker = list(
        colors = colorRampPalette(c("#2E86AB", "#A23B72", "#F18F01", "#C73E1D"))(nrow(top_cells)),
        line = list(color = '#FFFFFF', width = 2)
      )
    ) %>%
      layout(
        title = list(text = "Cell Type Distribution", font = list(size = 16, face = "bold")),
        showlegend = TRUE,
        legend = list(orientation = "v", x = 1.02, y = 1)
      )
    
    print("Pie chart created successfully")
    return(p)
    
  }, error = function(e) {
    print(paste("Error creating pie chart:", e$message))
    return(NULL)
  })
}

create_pca_colored_by_celltype <- function(expression_matrix, 
                                           deconv_results, 
                                           method,
                                           dominant_only = TRUE) {
  
  print("Creating PCA plot colored by cell types...")
  
  tryCatch({
    library(plotly)
    
    # Run PCA on expression data
    pca_result <- prcomp(t(expression_matrix), scale. = TRUE, center = TRUE)
    
    # Extract PC scores
    pca_df <- data.frame(
      PC1 = pca_result$x[, 1],
      PC2 = pca_result$x[, 2],
      sample = rownames(pca_result$x),
      stringsAsFactors = FALSE
    )
    
    # Get dominant cell type for each sample
    if (method %in% c("xcell", "mcp_counter")) {
      # For each sample (column), find cell type with highest score
      dominant_cells <- apply(deconv_results, 2, function(x) {
        names(which.max(x))
      })
    } else if (method == "epic") {
      # For each sample (row), find cell type with highest proportion
      dominant_cells <- apply(deconv_results, 1, function(x) {
        names(which.max(x))
      })
    }
    
    pca_df$dominant_cell_type <- dominant_cells[match(pca_df$sample, names(dominant_cells))]
    
    # Calculate variance explained
    var_explained <- summary(pca_result)$importance[2, 1:2] * 100
    
    # Create PCA plot
    p <- plot_ly(
      pca_df,
      x = ~PC1,
      y = ~PC2,
      type = "scatter",
      mode = "markers",
      color = ~dominant_cell_type,
      colors = "Set3",
      text = ~paste("Sample:", sample, "<br>Dominant Cell Type:", dominant_cell_type),
      hoverinfo = "text",
      marker = list(size = 12, line = list(width = 1, color = "white"))
    ) %>%
      layout(
        title = "PCA Colored by Dominant Cell Type",
        xaxis = list(title = paste0("PC1 (", round(var_explained[1], 1), "%)")),
        yaxis = list(title = paste0("PC2 (", round(var_explained[2], 1), "%)")),
        legend = list(title = list(text = "Dominant Cell Type"))
      )
    
    print("PCA plot created successfully")
    return(p)
    
  }, error = function(e) {
    print(paste("Error creating PCA plot:", e$message))
    return(NULL)
  })
}




# ===== COMPREHENSIVE GRN ANALYSIS FIX =====

# 1. FIXED GENE SELECTION FOR GRN (Use ALL DEGs, not just top 20)
prepare_grn_gene_selection_corrected <- function(deg_results, up_genes_from_table, down_genes_from_table) {
  
  print("=== PREPARE GRN GENE SELECTION (CORRECTED) ===")
  print(paste("📊 Input up genes:", length(up_genes_from_table)))
  print(paste("📊 Input down genes:", length(down_genes_from_table)))
  
  # Clean gene IDs (remove suffixes like "_tumor vs control")
  clean_up_genes <- gsub("_.*$", "", up_genes_from_table)
  clean_up_genes <- gsub("\\.[0-9]+.*$", "", clean_up_genes)  # Remove version numbers
  clean_down_genes <- gsub("_.*$", "", down_genes_from_table)
  clean_down_genes <- gsub("\\.[0-9]+.*$", "", clean_down_genes)
  
  # Combine all genes
  clean_all_genes <- c(clean_up_genes, clean_down_genes)
  
  # Remove duplicates and empty values
  clean_up_genes <- unique(clean_up_genes[!is.na(clean_up_genes) & clean_up_genes != ""])
  clean_down_genes <- unique(clean_down_genes[!is.na(clean_down_genes) & clean_down_genes != ""])
  clean_all_genes <- unique(clean_all_genes[!is.na(clean_all_genes) & clean_all_genes != ""])
  
  print(paste("✅ Cleaned up genes:", length(clean_up_genes)))
  print(paste("✅ Cleaned down genes:", length(clean_down_genes)))
  print(paste("✅ Total unique genes for GRN:", length(clean_all_genes)))
  
  # Show sample genes for debugging
  if (length(clean_all_genes) > 0) {
    print(paste("📝 Sample genes:", paste(head(clean_all_genes, 5), collapse = ", ")))
  }
  
  return(list(
    up_genes = clean_up_genes,
    down_genes = clean_down_genes,
    all_genes = clean_all_genes,
    n_up = length(clean_up_genes),
    n_down = length(clean_down_genes),
    n_total = length(clean_all_genes)
  ))
}


# 2. UNIVERSAL GENE ID CONVERSION FOR ANY INPUT TYPE
convert_genes_for_grn <- function(gene_list, organism = "human") {

  print(paste("🔄 Converting", length(gene_list), "genes for organism:", organism))

  # Empty input shortcut — prevents 0/0 = NaN in the conversion-rate guard below
  if (is.null(gene_list) || length(gene_list) == 0) {
    return(list(
      symbols = character(0),
      conversion_rate = 0,
      original_ids = character(0)
    ))
  }

  # Use the existing robust conversion function that handles all ID types
  print("📋 Using convert_gene_ids_to_symbols_deg for reliable conversion...")

  conversion_result <- convert_gene_ids_to_symbols_deg(
    gene_ids = gene_list,
    organism = organism
  )
  
  # Extract successfully converted symbols
  valid_symbols <- conversion_result$gene_symbol != "-" & 
    !is.na(conversion_result$gene_symbol) &
    conversion_result$gene_symbol != ""
  
  converted_genes <- conversion_result$gene_symbol[valid_symbols]
  conversion_rate <- sum(valid_symbols) / length(gene_list)
  
  print(paste("✅ Converted", sum(valid_symbols), "genes"))
  print(paste("✅ Conversion rate:", round(conversion_rate * 100, 1), "%"))
  
  # If conversion rate is too low, use original IDs
  if (conversion_rate < 0.3) {
    warning("Low conversion rate. Using original gene IDs.")
    return(list(
      symbols = gene_list,
      conversion_rate = conversion_rate,
      original_ids = gene_list
    ))
  }
  
  return(list(
    symbols = converted_genes,
    conversion_rate = conversion_rate,
    original_ids = gene_list[valid_symbols]
  ))
}


# Helper functions for TF-target regulations
get_tf_target_regulations_fixed <- function(selected_genes, organism = "human",
                                            database = "dorothea", min_confidence = 0.6) {
  
  print(paste("🔍 Getting TF regulations for", length(selected_genes), "genes"))
  print(paste("  • Organism:", organism))
  print(paste("  • Database:", database))
  print(paste("  • Min confidence:", min_confidence))
  
  # Try to load dorothea data
  if (organism == "human") {
    tryCatch({
      if (!requireNamespace("dorothea", quietly = TRUE)) {
        stop("dorothea package not installed")
      }
      
      # Load human dorothea data
      data("dorothea_hs", package = "dorothea", envir = environment())
      dorothea_data <- get("dorothea_hs", envir = environment())
      
      # Convert confidence levels to numeric
      confidence_map <- c("A" = 1.0, "B" = 0.8, "C" = 0.6, "D" = 0.4, "E" = 0.2)
      dorothea_data$confidence_numeric <- confidence_map[dorothea_data$confidence]
      
      # Filter by confidence
      dorothea_filtered <- dorothea_data %>%
        filter(confidence_numeric >= min_confidence)
      
      print(paste("📊 Filtered to", nrow(dorothea_filtered), "high-confidence regulations"))
      
      # Filter for genes in our dataset
      tf_regulations <- dorothea_filtered %>%
        filter(target %in% selected_genes | tf %in% selected_genes) %>%
        select(tf, target, confidence = confidence_numeric, mor) %>%
        distinct()
      
      print(paste("✅ Found", nrow(tf_regulations), "regulations involving selected genes"))
      
      return(tf_regulations)
      
    }, error = function(e) {
      print(paste("❌ Error in get_tf_target_regulations:", e$message))
      # Return mock data for testing
      return(create_mock_tf_regulations(selected_genes))
    })
  } else if (organism == "mouse") {
    # Similar logic for mouse
    tryCatch({
      data("dorothea_mm", package = "dorothea", envir = environment())
      dorothea_data <- get("dorothea_mm", envir = environment())
      
      # Similar processing as above...
      confidence_map <- c("A" = 1.0, "B" = 0.8, "C" = 0.6, "D" = 0.4, "E" = 0.2)
      dorothea_data$confidence_numeric <- confidence_map[dorothea_data$confidence]
      
      tf_regulations <- dorothea_data %>%
        filter(confidence_numeric >= min_confidence) %>%
        filter(target %in% selected_genes | tf %in% selected_genes) %>%
        select(tf, target, confidence = confidence_numeric, mor) %>%
        distinct()
      
      return(tf_regulations)
      
    }, error = function(e) {
      print(paste("❌ Error loading mouse data:", e$message))
      return(create_mock_tf_regulations(selected_genes))
    })
  } else {
    warning(paste("Organism", organism, "not supported"))
    return(data.frame())
  }
}

create_mock_tf_regulations <- function(selected_genes) {
  stop("Transcription-factor target data (DoRothEA) could not be loaded, so no regulatory network was built. TransXplorer never substitutes simulated data.")
}



# Calculate TF activities using VIPER-like approach
# TF activity = VIPER (Alvarez et al. 2016, via dorothea::run_viper) on each TF's FULL regulon.
# Human/mouse: DoRothEA regulons at the chosen confidence levels. Other species: the
# TF-target regulations loaded for the analysis. Expression is log2-transformed when it
# looks like counts, collapsed to one row per gene, and scaled per gene (method "scale").
# Returns long format: tf, sample, activity, n_targets (targets present in the data).
calculate_tf_activities_fixed_final <- function(expression_data, tf_regulations, selected_genes,
                                                filter_to_degs = FALSE, organism = NULL,
                                                confidence_level = 0.6, tf_database = "dorothea") {
  if (is.null(expression_data) || nrow(expression_data) == 0) return(NULL)
  if (is.null(tf_regulations) || nrow(tf_regulations) == 0) return(NULL)
  if (ncol(expression_data) < 2) return(NULL)
  tryCatch({
    if (!requireNamespace("viper", quietly = TRUE) || !requireNamespace("dorothea", quietly = TRUE))
      stop("VIPER/DoRothEA packages are not available")
    org <- tolower(if (is.null(organism)) "" else organism)
    if (org %in% c("human", "mouse") && identical(tolower(if (is.null(tf_database)) "dorothea" else tf_database), "dorothea")) {
      env <- new.env()
      ds <- if (org == "human") "dorothea_hs" else "dorothea_mm"
      utils::data(list = ds, package = "dorothea", envir = env)
      regulon <- get(ds, envir = env)
      keep_levels <- c("A", "B", "C", "D", "E")[seq_len(max(1, min(5, ceiling((if (is.null(confidence_level)) 0.6 else confidence_level) * 5))))]
      regulon <- as.data.frame(regulon[regulon$confidence %in% keep_levels, c("tf", "confidence", "target", "mor")])
    } else {
      regulon <- data.frame(tf = tf_regulations$tf, confidence = "A", target = tf_regulations$target,
                            mor = if ("mor" %in% names(tf_regulations)) tf_regulations$mor else 1,
                            stringsAsFactors = FALSE)
    }
    all_tfs <- unique(tf_regulations$tf)
    unique_tfs <- if (filter_to_degs) intersect(all_tfs, selected_genes$all_genes) else all_tfs
    if (length(unique_tfs) == 0) unique_tfs <- all_tfs
    regulon <- regulon[regulon$tf %in% unique_tfs, , drop = FALSE]
    if (nrow(regulon) == 0) return(NULL)

    expr <- as.matrix(expression_data)
    storage.mode(expr) <- "double"
    rn <- gsub("\\.[0-9]+$", "", gsub("_.*$", "", rownames(expr)))
    rs <- rowsum(expr, rn, na.rm = TRUE)
    expr <- rs / as.vector(table(rn)[rownames(rs)])
    if (max(expr, na.rm = TRUE) > 100) expr <- log2(expr + 1)
    expr <- expr[apply(expr, 1, function(x) stats::sd(x, na.rm = TRUE) > 0), , drop = FALSE]

    acts <- suppressWarnings(dorothea::run_viper(expr, regulon,  # (deprecation notice only)
                                options = list(method = "scale", minsize = 4, eset.filter = FALSE,
                                               cores = 1, verbose = FALSE)))
    if (is.null(acts) || length(acts) == 0) return(NULL)
    acts <- as.matrix(acts)
    n_tg <- vapply(rownames(acts), function(tf) sum(regulon$target[regulon$tf == tf] %in% rownames(expr)), 0)
    out <- data.frame(tf = rep(rownames(acts), times = ncol(acts)),
                      sample = rep(colnames(acts), each = nrow(acts)),
                      activity = as.vector(acts),
                      n_targets = rep(n_tg, times = ncol(acts)),
                      stringsAsFactors = FALSE)
    attr(out, "method") <- "VIPER (dorothea::run_viper, method = scale, minsize = 4)"
    out
  }, error = function(e) {
    print(paste("TF activity (VIPER) failed:", conditionMessage(e)))
    NULL
  })
}

calculate_tf_activities_weighted_mean_legacy <- function(expression_data, tf_regulations, selected_genes,
                                                filter_to_degs = FALSE) {
  
  print("📈 Calculating TF activities (OPTIMIZED)...")
  
  if (is.null(expression_data) || nrow(expression_data) == 0) {
    print("⚠️ No expression data available for TF activity calculation")
    return(NULL)
  }
  
  if (is.null(tf_regulations) || nrow(tf_regulations) == 0) {
    print("⚠️ No TF regulations available")
    return(NULL)
  }
  
  tryCatch({
    
    # Debug info
    n_samples <- ncol(expression_data)
    n_genes <- nrow(expression_data)
    print(paste("📊 Expression data:", n_genes, "genes x", n_samples, "samples"))
    print(paste("📊 TF regulations:", nrow(tf_regulations), "regulations"))
    
    # ✅ FIX 1: Ensure mor column exists and convert to regulation_type
    if (!"regulation_type" %in% colnames(tf_regulations)) {
      if ("mor" %in% colnames(tf_regulations)) {
        tf_regulations$regulation_type <- tf_regulations$mor
      } else {
        tf_regulations$regulation_type <- 1
      }
    }
    
    # Get unique TFs
    all_tfs_in_regs <- unique(tf_regulations$tf)
    
    if (filter_to_degs) {
      unique_tfs <- intersect(all_tfs_in_regs, selected_genes$all_genes)
      print("🎯 FILTER MODE: DEG TFs only")
    } else {
      unique_tfs <- all_tfs_in_regs
      print("🌐 SHOW ALL MODE: All TFs")
    }
    
    if (length(unique_tfs) == 0) {
      unique_tfs <- all_tfs_in_regs
    }
    
    print(paste("Processing", length(unique_tfs), "TFs across", n_samples, "samples"))
    
    # ✅ FIX 2: Clean expression gene IDs ONCE (not in loop)
    expr_genes <- rownames(expression_data)
    clean_expr_genes <- gsub("_.*$", "", expr_genes)
    clean_expr_genes <- gsub("\\.[0-9]+$", "", clean_expr_genes)
    names(clean_expr_genes) <- expr_genes
    
    # ✅ FIX 3: Pre-allocate results list (MUCH faster than rbind)
    results_list <- vector("list", length(unique_tfs))
    names(results_list) <- unique_tfs
    
    # Track statistics
    tfs_with_targets <- 0
    total_target_matches <- 0
    
    # ✅ FIX 4: Vectorized sample names
    sample_names <- colnames(expression_data)
    
    for (i in seq_along(unique_tfs)) {
      tf <- unique_tfs[i]
      
      # Get targets of this TF
      tf_targets <- tf_regulations[tf_regulations$tf == tf, ]
      target_genes <- tf_targets$target
      
      # Strategy 1: Direct match
      available_targets <- intersect(target_genes, expr_genes)
      
      # Strategy 2: Match cleaned expression genes
      if (length(available_targets) == 0) {
        matching_targets <- target_genes[target_genes %in% clean_expr_genes]
        if (length(matching_targets) > 0) {
          available_targets <- names(clean_expr_genes)[clean_expr_genes %in% matching_targets]
        }
      }
      
      # Skip if no matches
      if (length(available_targets) < 2) next
      
      tfs_with_targets <- tfs_with_targets + 1
      total_target_matches <- total_target_matches + length(available_targets)
      
      # Get expression data for available targets
      target_expr <- expression_data[available_targets, , drop = FALSE]
      
      # Match regulation data
      cleaned_available <- gsub("_.*$", "", available_targets)
      cleaned_available <- gsub("\\.[0-9]+$", "", cleaned_available)
      
      target_regs <- tf_targets[tf_targets$target %in% cleaned_available, ]
      
      if (nrow(target_regs) == 0) next
      
      # Create mapping
      matched_regs <- data.frame(
        expr_rowname = available_targets,
        cleaned_id = cleaned_available,
        stringsAsFactors = FALSE
      )
      
      matched_regs <- merge(matched_regs, target_regs, 
                            by.x = "cleaned_id", by.y = "target", 
                            all.x = FALSE)
      
      matched_regs <- matched_regs[!is.na(matched_regs$regulation_type), ]
      matched_regs <- matched_regs[matched_regs$expr_rowname %in% rownames(target_expr), ]
      
      if (nrow(matched_regs) < 2) next
      
      # ✅ FIX 5: VECTORIZED activity calculation (no inner loop!)
      target_expr_matched <- target_expr[matched_regs$expr_rowname, , drop = FALSE]
      reg_types <- matched_regs$regulation_type
      confidences <- matched_regs$confidence
      
      # Weighted expression: multiply each row by its regulation weight
      weights <- reg_types * confidences
      weighted_expr <- sweep(target_expr_matched, 1, weights, "*")
      
      # Mean activity per sample (column means)
      activity_scores <- colMeans(weighted_expr, na.rm = TRUE)
      
      # ✅ FIX 6: Store results for this TF (all samples at once)
      results_list[[tf]] <- data.frame(
        tf = tf,
        sample = sample_names,
        activity = activity_scores,
        n_targets = nrow(matched_regs),
        stringsAsFactors = FALSE
      )
    }
    
    print(paste("📊 Matching statistics:"))
    print(paste("   TFs with ≥2 target matches:", tfs_with_targets, "/", length(unique_tfs)))
    print(paste("   Total target matches:", total_target_matches))
    
    # ✅ FIX 7: Combine all results at once (single rbind)
    results_list <- results_list[!sapply(results_list, is.null)]
    
    if (length(results_list) > 0) {
      tf_activities <- do.call(rbind, results_list)
      rownames(tf_activities) <- NULL
      
      print(paste("✅ Calculated activities for", length(unique(tf_activities$tf)), "TFs"))
      print(paste("   Across", length(unique(tf_activities$sample)), "samples"))
      return(tf_activities)
    } else {
      print("⚠️ No TF activities could be calculated")
      return(NULL)
    }
    
  }, error = function(e) {
    print(paste("❌ Error calculating TF activities:", e$message))
    return(NULL)
  })
}

# DoRothEA database access
get_dorothea_regulations_fixed <- function(selected_genes, organism, min_confidence) {
  
  tryCatch({
    
    # Try to load dorothea package
    if (requireNamespace("dorothea", quietly = TRUE)) {
      
      print("📚 Loading DoRothEA database...")
      
      # Load organism-specific data
      if (tolower(organism) == "human") {
        data(dorothea_hs, package = "dorothea", envir = environment())
        regulons <- dorothea_hs
        print("✅ Loaded human DoRothEA data")
      } else if (tolower(organism) == "mouse") {
        data(dorothea_mm, package = "dorothea", envir = environment())
        regulons <- dorothea_mm
        print("✅ Loaded mouse DoRothEA data")
      } else {
        stop(paste("DoRothEA does not support organism:", organism))
      }
      
      # Filter by confidence level
      confidence_levels <- c("A", "B", "C", "D", "E")
      keep_levels <- confidence_levels[1:ceiling(min_confidence * 5)]
      regulons_filtered <- regulons[regulons$confidence %in% keep_levels, ]
      
      print(paste("📊 Filtered to confidence levels:", paste(keep_levels, collapse = ", ")))
      
      # Filter for selected genes
      tf_target_pairs <- regulons_filtered[regulons_filtered$target %in% selected_genes, ]
      
      if (nrow(tf_target_pairs) > 0) {
        tf_regulations <- data.frame(
          tf = tf_target_pairs$tf,
          target = tf_target_pairs$target,
          regulation_type = ifelse(tf_target_pairs$mor > 0, 1, -1),
          confidence = case_when(
            tf_target_pairs$confidence == "A" ~ 1.0,
            tf_target_pairs$confidence == "B" ~ 0.8,
            tf_target_pairs$confidence == "C" ~ 0.6,
            tf_target_pairs$confidence == "D" ~ 0.4,
            tf_target_pairs$confidence == "E" ~ 0.2
          ),
          database = "DoRothEA",
          stringsAsFactors = FALSE
        )
        
        print(paste("✅ Found", nrow(tf_regulations), "DoRothEA regulations"))
        return(tf_regulations)
      }
    }
    
    # Fallback to organism-specific synthetic regulations
    print("⚠️ DoRothEA not available, using fallback method")
    return(create_organism_specific_regulations(selected_genes, organism))
    
  }, error = function(e) {
    print(paste("❌ DoRothEA access failed:", e$message))
    return(create_organism_specific_regulations(selected_genes, organism))
  })
}

# 6. ORGANISM-SPECIFIC FALLBACK REGULATIONS
create_organism_specific_regulations <- function(selected_genes, organism) {
  
  print(paste("🔄 Creating organism-specific fallback regulations for", organism))
  
  # Organism-specific common TFs
  common_tfs <- switch(tolower(organism),
                       "human" = c("TP53", "MYC", "JUN", "FOS", "STAT1", "STAT3", "NFE2L2", "RELA",
                                   "SP1", "CREB1", "PPARA", "PPARG", "ESR1", "AR", "HIF1A", "ATF4",
                                   "E2F1", "RB1", "FOXO1", "SMAD3"),
                       "mouse" = c("Trp53", "Myc", "Jun", "Fos", "Stat1", "Stat3", "Nfe2l2", "Rela",
                                   "Sp1", "Creb1", "Ppara", "Pparg", "Esr1", "Ar", "Hif1a", "Atf4",
                                   "E2f1", "Rb1", "Foxo1", "Smad3"),
                       c("TP53", "MYC", "JUN", "FOS", "STAT1", "STAT3") # Generic fallback
  )
  
  # Find TFs in the selected genes
  tf_targets <- intersect(selected_genes, common_tfs)
  
  if (length(tf_targets) > 0) {
    tf_regulations <- data.frame()
    
    for (tf in tf_targets) {
      # Create realistic TF-target pairs
      n_targets <- min(15, length(selected_genes))
      targets <- sample(selected_genes[selected_genes != tf], n_targets)
      
      tf_regs <- data.frame(
        tf = tf,
        target = targets,
        regulation_type = sample(c(-1, 1), n_targets, replace = TRUE, prob = c(0.3, 0.7)),
        confidence = runif(n_targets, min = 0.5, max = 0.9),
        database = paste("Synthetic", organism),
        stringsAsFactors = FALSE
      )
      
      tf_regulations <- rbind(tf_regulations, tf_regs)
    }
    
    print(paste("✅ Created", nrow(tf_regulations), "synthetic regulations"))
    return(tf_regulations)
  }
  
  # If no TFs found, return empty dataframe
  return(data.frame(
    tf = character(0),
    target = character(0),
    regulation_type = numeric(0),
    confidence = numeric(0),
    database = character(0),
    stringsAsFactors = FALSE
  ))
}


# Build regulatory network for visualization
build_regulatory_network_fixed_final <- function(tf_regulations, selected_genes, tf_activities = NULL) {
  
  print("🕸️ Building corrected regulatory network for visualization...")
  print(paste("Input: tf_regulations has", nrow(tf_regulations), "rows"))
  print(paste("Columns in tf_regulations:", paste(colnames(tf_regulations), collapse = ", ")))
  
  # Create TF nodes with proper visNetwork color format
  all_tfs_in_regs <- unique(tf_regulations$tf)
  
  if (!is.null(selected_genes) && !is.null(selected_genes$all_genes)) {
    if (filter_to_degs) {
      unique_tfs <- intersect(all_tfs_in_regs, selected_genes$all_genes)
      print(paste("🎯 FILTER MODE: DEG TFs only"))
      print(paste("   TFs in regulations:", length(all_tfs_in_regs)))
      print(paste("   TFs that are also DEGs:", length(unique_tfs)))
    } else {
      unique_tfs <- all_tfs_in_regs
      print(paste("🌐 SHOW ALL MODE: All TFs with targets in DEGs"))
      print(paste("   Total TFs to analyze:", length(unique_tfs)))
    }
  } else {
    unique_tfs <- all_tfs_in_regs
  }
  
  if (length(unique_tfs) == 0) {
    print("⚠️ No TFs found - using all from database")
    unique_tfs <- all_tfs_in_regs
  }
  print(paste("Found", length(unique_tfs), "unique TFs:", paste(head(unique_tfs, 3), collapse = ", ")))
  
  tf_nodes <- data.frame(
    id = unique_tfs,
    label = unique_tfs,
    group = "tf",  # This is CRITICAL for visGroups to work
    # Use proper visNetwork color format
    color.background = "#FF6B6B", # Red for TFs
    color.border = "#D64545",
    size = 35,
    shape = "triangle",
    title = paste("Transcription Factor:", unique_tfs),
    stringsAsFactors = FALSE
  )
  
  # Create target nodes with proper color format
  unique_targets <- unique(tf_regulations$target)
  print(paste("Found", length(unique_targets), "unique targets"))
  
  target_nodes <- data.frame(
    id = unique_targets,
    label = unique_targets,
    group = "target",  # Default group
    # Set default colors
    color.background = "#BDC3C7", # Default grey
    color.border = "#95A5A6",
    size = 25,
    shape = "dot",
    title = paste("Target Gene:", unique_targets),
    stringsAsFactors = FALSE
  )
  
  # Apply specific colors and groups for up- and down-regulated targets
  if (!is.null(selected_genes$up_genes)) {
    up_mask <- target_nodes$id %in% selected_genes$up_genes
    target_nodes$color.background[up_mask] <- "#4ECDC4"  # Teal for up-regulated
    target_nodes$color.border[up_mask] <- "#2ECC71"
    target_nodes$group[up_mask] <- "upregulated"  # Specific group for visGroups
    target_nodes$title[up_mask] <- paste("Upregulated Gene:", target_nodes$id[up_mask])
    print(paste("Assigned", sum(up_mask), "upregulated targets"))
  }
  
  if (!is.null(selected_genes$down_genes)) {
    down_mask <- target_nodes$id %in% selected_genes$down_genes
    target_nodes$color.background[down_mask] <- "#FF9F43"  # Orange for down-regulated
    target_nodes$color.border[down_mask] <- "#E67E22"
    target_nodes$group[down_mask] <- "downregulated"  # Specific group for visGroups
    target_nodes$title[down_mask] <- paste("Downregulated Gene:", target_nodes$id[down_mask])
    print(paste("Assigned", sum(down_mask), "downregulated targets"))
  }
  
  # Combine nodes
  nodes <- rbind(tf_nodes, target_nodes)
  nodes <- nodes[!duplicated(nodes$id), ] # Ensure no duplicate nodes
  
  print(paste("Final nodes by group:"))
  print(table(nodes$group))
  
  # Create edges with proper styling
  # Handle both 'mor' and 'regulation_type' columns
  regulation_col <- if("mor" %in% colnames(tf_regulations)) "mor" else "regulation_type"
  
  if (!regulation_col %in% colnames(tf_regulations)) {
    print("Warning: No regulation column found, assigning random values")
    tf_regulations$regulation_type <- sample(c(-1, 1), nrow(tf_regulations), replace = TRUE)
    regulation_col <- "regulation_type"
  }
  
  print(paste("Using regulation column:", regulation_col))
  
  edges <- tf_regulations %>%
    dplyr::select(from = tf, to = target, regulation = !!sym(regulation_col), confidence) %>%
    dplyr::mutate(
      arrows = "to",
      # Apply proper edge colors for Activation (1) and Repression (-1)
      color.color = ifelse(regulation == 1, "#27AE60", "#E74C3C"), # Green for Activation, Red for Repression
      color.opacity = 0.8,
      width = pmax(1, confidence * 4),  # Width based on confidence
      title = paste(
        "Regulation:", ifelse(regulation == 1, "Activation", "Repression"),
        "<br>Confidence:", round(confidence, 3)
      ),
      dashes = ifelse(confidence < 0.7, TRUE, FALSE) # Dashed for lower confidence
    ) %>%
    select(-regulation) # Remove the intermediate column
  
  print(paste("Created", nrow(edges), "edges"))
  print(paste("Edge colors:", length(unique(edges$color.color)), "unique colors"))
  
  network_result <- list(nodes = nodes, edges = edges)
  
  print("✅ Fixed network building completed successfully")
  print(paste("Final network: ", nrow(nodes), "nodes,", nrow(edges), "edges"))
  
  return(network_result)
}



# Identify master regulators
identify_master_regulators_fixed <- function(tf_regulations, selected_genes, max_regulators = 20) {

  print(paste("👑 Identifying master regulators (max =", max_regulators, ")..."))
  
  # Handle both 'mor' and 'regulation_type' columns
  regulation_col <- if("mor" %in% colnames(tf_regulations)) "mor" else "regulation_type"
  
  if (!regulation_col %in% colnames(tf_regulations)) {
    tf_regulations$regulation_type <- sample(c(-1, 1), nrow(tf_regulations), replace = TRUE)
    regulation_col <- "regulation_type"
  }
  
  # Calculate comprehensive TF metrics
  tf_metrics <- tf_regulations %>%
    group_by(tf) %>%
    summarise(
      n_targets = n(),
      n_up_targets = sum(target %in% selected_genes$up_genes),
      n_down_targets = sum(target %in% selected_genes$down_genes),
      avg_confidence = mean(confidence),
      activation_ratio = mean(!!sym(regulation_col) == 1),
      repression_ratio = mean(!!sym(regulation_col) == -1),
      max_confidence = max(confidence),
      min_confidence = min(confidence),
      .groups = 'drop'
    ) %>%
    mutate(
      target_overlap = (n_up_targets + n_down_targets) / n_targets,
      master_score = n_targets * avg_confidence * target_overlap * max_confidence,
      regulation_balance = abs(activation_ratio - repression_ratio),
      directional_bias = case_when(
        activation_ratio > 0.7 ~ "Activator",
        repression_ratio > 0.7 ~ "Repressor",
        TRUE ~ "Mixed"
      )
    ) %>%
    arrange(desc(master_score))
  
  # Filter and rank master regulators
  master_regulators <- tf_metrics %>%
    filter(
      n_targets >= 2,        # At least 2 targets
      target_overlap >= 0.1, # At least 10% overlap with DEGs
      avg_confidence >= 0.4   # Minimum confidence
    ) %>%
    slice_head(n = max_regulators) %>%
    mutate(
      rank = row_number(),
      category = directional_bias,
      regulatory_influence = case_when(
        master_score >= quantile(master_score, 0.8, na.rm = TRUE) ~ "High",
        master_score >= quantile(master_score, 0.5, na.rm = TRUE) ~ "Medium",
        TRUE ~ "Low"
      )
    )
  
  print(paste("✅ Identified", nrow(master_regulators), "master regulators"))
  
  return(master_regulators)
}

# 11. ORGANISM-SPECIFIC TF PATHWAY ANALYSIS
perform_tf_pathway_analysis_fixed <- function(tf_list, organism = "human") {
  
  print(paste("🛤️ Performing TF pathway analysis for", organism))
  
  tryCatch({
    if (requireNamespace("enrichR", quietly = TRUE)) {
      
      # Organism-specific databases
      if (tolower(organism) == "human") {
        databases <- c(
          "ENCODE_TF_ChIP-seq_2015",
          "ChEA_2016",
          "TRANSFAC_and_JASPAR_PWMs",
          "TF_Perturbations_Followed_by_Expression",
          "Transcription_Factor_PPIs"
        )
      } else if (tolower(organism) == "mouse") {
        databases <- c(
          "ChEA_2016",
          "TRANSFAC_and_JASPAR_PWMs",
          "ENCODE_and_ChEA_Consensus_TFs_from_ChIP-X"
        )
      } else {
        databases <- c("ChEA_2016", "TRANSFAC_and_JASPAR_PWMs")
      }
      
      # Run enrichment
      enrichment_results <- tx_enrichr_local(tf_list, databases)
      
      # Combine and process results
      combined_results <- do.call(rbind, lapply(names(enrichment_results), function(db) {
        if (nrow(enrichment_results[[db]]) > 0) {
          result <- enrichment_results[[db]]
          result$database <- db
          result$tf_count <- lengths(strsplit(result$Genes, ";"))
          result$organism <- organism
          return(result)
        }
      }))
      
      # Filter and clean results
      if (!is.null(combined_results) && nrow(combined_results) > 0) {
        combined_results <- combined_results %>%
          filter(Adjusted.P.value < 0.1) %>% # More lenient for TF analysis
          arrange(Adjusted.P.value) %>%
          slice_head(n = 50) %>%
          mutate(
            significance = case_when(
              Adjusted.P.value < 0.001 ~ "Highly Significant",
              Adjusted.P.value < 0.01 ~ "Significant",
              Adjusted.P.value < 0.05 ~ "Moderately Significant",
              TRUE ~ "Trending"
            )
          )
        
        print(paste("✅ Found", nrow(combined_results), "enriched TF pathways"))
        return(combined_results)
      }
    }
    
    print("⚠️ No TF pathway enrichment results found")
    return(NULL)
    
  }, error = function(e) {
    print(paste("❌ Error in TF pathway analysis:", e$message))
    return(NULL)
  })
}


# load_network_packages is defined at the top of the file (line ~118)
# Do not redefine it here — the first definition includes viper + dorothea

# Calculate GRN network metrics
calculate_grn_metrics_fixed <- function(network_data, tf_regulations) {
  
  print("📊 Calculating network metrics...")
  
  tryCatch({
    if (requireNamespace("igraph", quietly = TRUE)) {
      
      # Create igraph object
      g <- igraph::graph_from_data_frame(
        d = network_data$edges[, c("from", "to")],
        vertices = network_data$nodes[, c("id", "group")],
        directed = TRUE
      )
      
      # Calculate basic metrics
      metrics <- list(
        n_nodes = igraph::vcount(g),
        n_edges = igraph::ecount(g),
        n_tfs = sum(network_data$nodes$group == "tf"),
        n_targets = sum(network_data$nodes$group == "target"),
        density = igraph::edge_density(g),
        avg_degree = mean(igraph::degree(g)),
        n_activations = sum(tf_regulations$regulation_type == 1),
        n_repressions = sum(tf_regulations$regulation_type == -1),
        avg_confidence = mean(tf_regulations$confidence),
        activation_percentage = round(mean(tf_regulations$regulation_type == 1) * 100, 1)
      )
      
      # Calculate centrality measures for TFs only
      tf_indices <- which(network_data$nodes$group == "tf")
      if (length(tf_indices) > 0) {
        tf_centralities <- data.frame(
          tf = network_data$nodes$id[tf_indices],
          out_degree = igraph::degree(g, v = tf_indices, mode = "out"),
          in_degree = igraph::degree(g, v = tf_indices, mode = "in"),
          betweenness = igraph::betweenness(g, v = tf_indices),
          closeness = igraph::closeness(g, v = tf_indices, mode = "out"),
          stringsAsFactors = FALSE
        )
        
        # Add centrality rankings
        tf_centralities <- tf_centralities %>%
          mutate(
            degree_rank = rank(-out_degree, ties.method = "min"),
            betweenness_rank = rank(-betweenness, ties.method = "min"),
            influence_score = scale(out_degree)[,1] + scale(betweenness)[,1]
          ) %>%
          arrange(desc(influence_score))
        
        metrics$tf_centralities <- tf_centralities
      }
      
      print("✅ Network metrics calculated")
      return(metrics)
      
    } else {
      # Simplified metrics without igraph
      print("⚠️ igraph not available, using simplified metrics")
      return(list(
        n_nodes = nrow(network_data$nodes),
        n_edges = nrow(network_data$edges),
        n_tfs = sum(network_data$nodes$group == "tf"),
        n_targets = sum(network_data$nodes$group == "target"),
        n_activations = sum(tf_regulations$regulation_type == 1),
        n_repressions = sum(tf_regulations$regulation_type == -1),
        avg_confidence = mean(tf_regulations$confidence),
        activation_percentage = round(mean(tf_regulations$regulation_type == 1) * 100, 1)
      ))
    }
    
  }, error = function(e) {
    print(paste("❌ Error calculating network metrics:", e$message))
    return(list(error = e$message))
  })
}

# 13. ENHANCED REGULATORY INSIGHTS
generate_regulatory_insights_fixed <- function(tf_regulations, master_regulators, selected_genes, tf_activities) {
  
  print("💡 Generating comprehensive regulatory insights...")
  
  insights <- list()
  
  # 1. Top regulatory relationships with biological context
  insights$top_relationships <- tf_regulations %>%
    arrange(desc(confidence)) %>%
    slice_head(n = 15) %>%
    mutate(
      relationship = paste(tf, ifelse(regulation_type == 1, "→", "⊣"), target),
      regulation = ifelse(regulation_type == 1, "activates", "represses"),
      confidence_level = case_when(
        confidence >= 0.8 ~ "High",
        confidence >= 0.6 ~ "Medium",
        TRUE ~ "Low"
      ),
      target_status = case_when(
        target %in% selected_genes$up_genes ~ "Upregulated",
        target %in% selected_genes$down_genes ~ "Downregulated",
        TRUE ~ "Unknown"
      )
    )
  
  # 2. TF regulatory categories with enhanced details
  insights$tf_categories <- master_regulators %>%
    count(category, name = "count") %>%
    mutate(
      percentage = round(count / sum(count) * 100, 1),
      description = case_when(
        category == "Activator" ~ "Primarily activates gene expression",
        category == "Repressor" ~ "Primarily represses gene expression",
        category == "Mixed" ~ "Both activates and represses genes"
      )
    )
  
  # 3. Enhanced regulation patterns
  up_regulated_by <- tf_regulations %>%
    filter(target %in% selected_genes$up_genes, regulation_type == 1) %>%
    count(tf, sort = TRUE) %>%
    slice_head(n = 8) %>%
    mutate(pattern = "TFs activating upregulated genes")
  
  down_regulated_by <- tf_regulations %>%
    filter(target %in% selected_genes$down_genes, regulation_type == -1) %>%
    count(tf, sort = TRUE) %>%
    slice_head(n = 8) %>%
    mutate(pattern = "TFs repressing downregulated genes")
  
  # Paradoxical patterns (might indicate indirect effects)
  paradoxical_up <- tf_regulations %>%
    filter(target %in% selected_genes$up_genes, regulation_type == -1) %>%
    count(tf, sort = TRUE) %>%
    slice_head(n = 5) %>%
    mutate(pattern = "TFs repressing upregulated genes (indirect?)")
  
  paradoxical_down <- tf_regulations %>%
    filter(target %in% selected_genes$down_genes, regulation_type == 1) %>%
    count(tf, sort = TRUE) %>%
    slice_head(n = 5) %>%
    mutate(pattern = "TFs activating downregulated genes (indirect?)")
  
  insights$regulation_patterns <- list(
    consistent = list(
      up_regulated_by = up_regulated_by,
      down_regulated_by = down_regulated_by
    ),
    paradoxical = list(
      repressors_of_upregulated = paradoxical_up,
      activators_of_downregulated = paradoxical_down
    )
  )
  
  # 4. TF activity patterns (if available)
  if (!is.null(tf_activities)) {
    tf_activity_summary <- tf_activities %>%
      group_by(tf) %>%
      summarise(
        avg_activity = mean(activity, na.rm = TRUE),
        activity_sd = sd(activity, na.rm = TRUE),
        activity_range = max(activity, na.rm = TRUE) - min(activity, na.rm = TRUE),
        .groups = 'drop'
      ) %>%
      mutate(
        activity_status = case_when(
          avg_activity > 0.5 ~ "Highly Active",
          avg_activity > 0.1 ~ "Moderately Active",
          avg_activity > -0.1 ~ "Neutral",
          avg_activity > -0.5 ~ "Moderately Repressed",
          TRUE ~ "Highly Repressed"
        ),
        variability = case_when(
          activity_sd > 0.5 ~ "High Variability",
          activity_sd > 0.2 ~ "Moderate Variability",
          TRUE ~ "Low Variability"
        )
      ) %>%
      arrange(desc(abs(avg_activity))) %>%
      slice_head(n = 15)
    
    insights$activity_patterns <- tf_activity_summary
  }
  
  # 5. Comprehensive network summary
  insights$network_summary <- list(
    total_regulations = nrow(tf_regulations),
    unique_tfs = length(unique(tf_regulations$tf)),
    unique_targets = length(unique(tf_regulations$target)),
    activation_percentage = round(mean(tf_regulations$regulation_type == 1) * 100, 1),
    repression_percentage = round(mean(tf_regulations$regulation_type == -1) * 100, 1),
    avg_confidence = round(mean(tf_regulations$confidence), 3),
    high_confidence_regulations = sum(tf_regulations$confidence >= 0.8),
    master_regulators_count = nrow(master_regulators),
    coverage = list(
      up_genes_covered = length(intersect(unique(tf_regulations$target), selected_genes$up_genes)),
      down_genes_covered = length(intersect(unique(tf_regulations$target), selected_genes$down_genes)),
      total_coverage_percentage = round(
        length(intersect(unique(tf_regulations$target), selected_genes$all_genes)) /
          length(selected_genes$all_genes) * 100, 1
      )
    )
  )
  
  # 6. Biological interpretation suggestions
  insights$interpretation_hints <- list(
    focus_tfs = master_regulators$tf[1:min(5, nrow(master_regulators))],
    paradoxical_patterns = nrow(paradoxical_up) + nrow(paradoxical_down) > 0,
    regulation_balance = if(insights$network_summary$activation_percentage > 70) {
      "Activation-dominated network"
    } else if(insights$network_summary$repression_percentage > 70) {
      "Repression-dominated network"
    } else {
      "Balanced activation/repression"
    },
    coverage_quality = if(insights$network_summary$coverage$total_coverage_percentage > 60) {
      "Good coverage of input genes"
    } else if(insights$network_summary$coverage$total_coverage_percentage > 30) {
      "Moderate coverage of input genes"
    } else {
      "Limited coverage - consider alternative analysis"
    }
  )
  
  print("✅ Regulatory insights generated")
  return(insights)
}

# Generate a unique fingerprint for the current dataset
generate_dataset_fingerprint <- function(counts_data, sample_groups = NULL) {
  if (is.null(counts_data)) return(NULL)
  
  # Create fingerprint based on:
  # - Dimensions
  # - Column names (samples)
  # - Row names (genes) - just first/last few for speed
  # - A hash of a sample of the data
  
  fingerprint <- paste(
    nrow(counts_data),
    ncol(counts_data),
    paste(colnames(counts_data), collapse = ","),
    paste(head(rownames(counts_data), 10), collapse = ","),
    paste(tail(rownames(counts_data), 10), collapse = ","),
    sum(counts_data[1:min(100, nrow(counts_data)), 1:min(10, ncol(counts_data))], na.rm = TRUE),
    if (!is.null(sample_groups)) paste(colnames(sample_groups), collapse = ",") else "",
    sep = "|"
  )
  
  return(digest::digest(fingerprint, algo = "md5"))
}

