# WGCNA, dynamicTreeCut, fastcluster, flashClust loaded on-demand via load_network_packages()
# dplyr, ggplot2, visNetwork already loaded or loaded on-demand

#Module trait analysis
detect_traits_from_data <- function(expression_data, sample_metadata = NULL) {
  
  print("🔍 Detecting available traits for module-trait correlation...")
  
  trait_data <- NULL
  trait_info <- list()
  
  # Method 1: Extract from sample names (Sample1_Control format)
  if (is.null(sample_metadata)) {
    sample_names <- colnames(expression_data)
    
    # Check if samples have underscore format
    if (any(grepl("_", sample_names))) {
      print("  ℹ️  Detected trait information in sample names (underscore format)")
      
      # Extract groups after underscore
      groups <- sapply(strsplit(sample_names, "_"), function(x) {
        if (length(x) > 1) tail(x, 1) else NA
      })
      
      if (!all(is.na(groups)) && length(unique(groups[!is.na(groups)])) >= 2) {
        trait_data <- data.frame(
          Sample = sample_names,
          Group = groups,
          stringsAsFactors = FALSE
        )
        rownames(trait_data) <- sample_names
        
        trait_info$source <- "sample_names"
        trait_info$n_traits <- 1
        trait_info$trait_names <- "Group"
        trait_info$trait_types <- "categorical"
        
        print(paste("  ✅ Extracted 'Group' trait with", length(unique(groups)), "levels:",
                    paste(unique(groups), collapse = ", ")))
      }
    }
  }
  
  # Method 2: Use provided metadata
  if (!is.null(sample_metadata)) {
    print("  ℹ️  Using provided sample metadata")
    
    # Validate metadata
    if (is.data.frame(sample_metadata) || is.matrix(sample_metadata)) {
      
      # Match samples
      common_samples <- intersect(rownames(sample_metadata), colnames(expression_data))
      
      if (length(common_samples) > 0) {
        trait_data <- as.data.frame(sample_metadata[common_samples, , drop = FALSE])
        
        # Analyze trait types
        trait_types <- sapply(trait_data, function(col) {
          if (is.numeric(col)) {
            "continuous"
          } else if (is.factor(col) || is.character(col)) {
            n_unique <- length(unique(col[!is.na(col)]))
            if (n_unique == 2) "binary"
            else if (n_unique <= 10) "categorical"
            else "continuous"  # Treat as continuous if many levels
          } else {
            "unknown"
          }
        })
        
        trait_info$source <- "metadata"
        trait_info$n_traits <- ncol(trait_data)
        trait_info$trait_names <- colnames(trait_data)
        trait_info$trait_types <- trait_types
        trait_info$n_samples_matched <- length(common_samples)
        
        print(paste("  ✅ Matched", length(common_samples), "samples with metadata"))
        print(paste("  ✅ Found", ncol(trait_data), "traits:", 
                    paste(colnames(trait_data), collapse = ", ")))
      } else {
        print("  ⚠️  No matching samples between metadata and expression data")
      }
    }
  }
  
  # Return results
  if (is.null(trait_data)) {
    print("  ❌ No trait data available for module-trait correlation")
    return(list(
      has_traits = FALSE,
      trait_data = NULL,
      trait_info = list()
    ))
  } else {
    return(list(
      has_traits = TRUE,
      trait_data = trait_data,
      trait_info = trait_info
    ))
  }
}

prepare_traits_for_correlation <- function(trait_data) {
  
  print("🔧 Preparing traits for correlation analysis...")
  
  prepared_traits <- data.frame(row.names = rownames(trait_data))
  trait_encoding_info <- list()
  
  for (col_name in colnames(trait_data)) {
    col_data <- trait_data[[col_name]]
    
    # Handle numeric traits
    if (is.numeric(col_data)) {
      prepared_traits[[col_name]] <- col_data
      trait_encoding_info[[col_name]] <- list(
        type = "continuous",
        encoding = "none",
        original_values = NA
      )
      print(paste("  ✅", col_name, "- Continuous trait (no encoding needed)"))
    }
    
    # Handle categorical traits
    else if (is.factor(col_data) || is.character(col_data)) {
      unique_vals <- unique(col_data[!is.na(col_data)])
      n_unique <- length(unique_vals)
      
      # Binary encoding (0/1)
      if (n_unique == 2) {
        encoded <- as.numeric(factor(col_data, levels = unique_vals)) - 1
        prepared_traits[[col_name]] <- encoded
        trait_encoding_info[[col_name]] <- list(
          type = "binary",
          encoding = paste(unique_vals[1], "=0,", unique_vals[2], "=1"),
          original_values = unique_vals
        )
        print(paste("  ✅", col_name, "- Binary trait encoded:", 
                    unique_vals[1], "=0,", unique_vals[2], "=1"))
      }
      
      # Multi-level categorical (create dummy variables)
      else if (n_unique > 2 && n_unique <= 10) {
        for (i in 1:n_unique) {
          dummy_name <- paste0(col_name, "_", unique_vals[i])
          prepared_traits[[dummy_name]] <- as.numeric(col_data == unique_vals[i])
        }
        trait_encoding_info[[col_name]] <- list(
          type = "categorical",
          encoding = paste("dummy variables created for", n_unique, "levels"),
          original_values = unique_vals
        )
        print(paste("  ✅", col_name, "- Categorical trait (", n_unique, 
                    "levels) encoded as dummy variables"))
      }
      
      # Too many levels - skip or treat as continuous
      else {
        print(paste("  ⚠️ ", col_name, "- Too many levels (", n_unique, 
                    "), attempting numeric conversion"))
        numeric_attempt <- suppressWarnings(as.numeric(as.character(col_data)))
        if (!all(is.na(numeric_attempt))) {
          prepared_traits[[col_name]] <- numeric_attempt
          trait_encoding_info[[col_name]] <- list(
            type = "converted_to_continuous",
            encoding = "categorical converted to numeric",
            original_values = NA
          )
        }
      }
    }
  }
  
  print(paste("✅ Prepared", ncol(prepared_traits), "traits for correlation"))
  
  return(list(
    prepared_traits = prepared_traits,
    encoding_info = trait_encoding_info
  ))
}


calculate_module_trait_correlations <- function(module_eigengenes, trait_data, 
                                                method = "pearson") {
  
  print("📊 Calculating module-trait correlations...")
  
  # Ensure sample alignment
  common_samples <- intersect(rownames(module_eigengenes), rownames(trait_data))
  
  if (length(common_samples) < 3) {
    stop("Not enough common samples (need ≥3) between module eigengenes and traits")
  }
  
  ME_subset <- module_eigengenes[common_samples, , drop = FALSE]
  traits_subset <- trait_data[common_samples, , drop = FALSE]
  
  print(paste("  Using", length(common_samples), "samples for correlation"))
  
  # Calculate correlations
  correlations <- cor(ME_subset, traits_subset, 
                      use = "pairwise.complete.obs", 
                      method = method)
  
  # Calculate p-values
  n_samples <- length(common_samples)
  p_values <- matrix(NA, nrow = nrow(correlations), ncol = ncol(correlations))
  rownames(p_values) <- rownames(correlations)
  colnames(p_values) <- colnames(correlations)
  
  for (i in 1:nrow(correlations)) {
    for (j in 1:ncol(correlations)) {
      cor_val <- correlations[i, j]
      if (!is.na(cor_val)) {
        # Use WGCNA's corPvalueStudent function
        p_values[i, j] <- WGCNA::corPvalueStudent(cor_val, n_samples)
      }
    }
  }
  
  print(paste("  ✅ Calculated correlations for", nrow(correlations), 
              "modules and", ncol(correlations), "traits"))
  
  # Identify significant associations
  sig_associations <- which(p_values < 0.05, arr.ind = TRUE)
  print(paste("  ✅ Found", nrow(sig_associations), 
              "significant module-trait associations (p < 0.05)"))
  
  return(list(
    correlations = correlations,
    p_values = p_values,
    n_samples = n_samples,
    method = method,
    significant_count = nrow(sig_associations)
  ))
}


create_module_trait_summary <- function(correlation_results, modules, 
                                        hub_genes, min_pval = 0.05) {
  
  correlations <- correlation_results$correlations
  p_values <- correlation_results$p_values
  
  # Find significant associations
  sig_idx <- which(p_values < min_pval, arr.ind = TRUE)
  
  if (nrow(sig_idx) == 0) {
    print("⚠️  No significant module-trait associations found")
    return(data.frame(
      Message = "No significant associations",
      Details = paste("Try p-value threshold >", min_pval),
      stringsAsFactors = FALSE
    ))
  }
  
  # Build summary table
  summary_df <- data.frame()
  
  for (i in 1:nrow(sig_idx)) {
    row_idx <- sig_idx[i, 1]
    col_idx <- sig_idx[i, 2]
    
    module_name <- gsub("ME", "", rownames(correlations)[row_idx])
    trait_name <- colnames(correlations)[col_idx]
    cor_value <- correlations[row_idx, col_idx]
    p_value <- p_values[row_idx, col_idx]
    
    # Get module info
    module_size <- if (module_name %in% names(modules)) {
      length(modules[[module_name]])
    } else { NA }
    
    # Get hub genes
    if (!is.null(hub_genes) && module_name %in% hub_genes$module) {
      module_hubs <- hub_genes[hub_genes$module == module_name, ]
      top_hubs <- paste(head(module_hubs$gene, 3), collapse = ", ")
      n_hubs <- nrow(module_hubs)
    } else {
      top_hubs <- "N/A"
      n_hubs <- 0
    }
    
    # Determine correlation strength
    cor_strength <- case_when(
      abs(cor_value) >= 0.7 ~ "Strong",
      abs(cor_value) >= 0.4 ~ "Moderate",
      abs(cor_value) >= 0.2 ~ "Weak",
      TRUE ~ "Very Weak"
    )
    
    # Direction
    cor_direction <- ifelse(cor_value > 0, "Positive", "Negative")
    
    summary_df <- rbind(summary_df, data.frame(
      Module = module_name,
      Trait = trait_name,
      Correlation = round(cor_value, 3),
      P_Value = format(p_value, scientific = TRUE, digits = 3),
      Direction = cor_direction,
      Strength = cor_strength,
      Module_Size = module_size,
      Hub_Genes = n_hubs,
      Top_Hub_Genes = top_hubs,
      stringsAsFactors = FALSE
    ))
  }
  
  # Sort by absolute correlation
  summary_df <- summary_df[order(-abs(summary_df$Correlation)), ]
  
  return(summary_df)
}

plot_module_trait_heatmap <- function(correlation_results, significance_threshold = 0.05) {
  
  correlations <- correlation_results$correlations
  p_values <- correlation_results$p_values
  
  # Prepare data for ggplot
  cor_df <- as.data.frame(correlations)
  cor_df$Module <- rownames(cor_df)
  
  plot_data <- cor_df %>%
    tidyr::pivot_longer(cols = -Module, names_to = "Trait", values_to = "Correlation")
  
  # Add significance
  pval_df <- as.data.frame(p_values)
  pval_df$Module <- rownames(pval_df)
  pval_data <- pval_df %>%
    tidyr::pivot_longer(cols = -Module, names_to = "Trait", values_to = "P_Value")
  
  plot_data <- plot_data %>%
    left_join(pval_data, by = c("Module", "Trait")) %>%
    mutate(
      Significant = P_Value < significance_threshold,
      Label = ifelse(Significant, 
                     paste0(round(Correlation, 2), "\n*"), 
                     round(Correlation, 2))
    )
  
  # Create HIGH RESOLUTION heatmap
  p <- ggplot(plot_data, aes(x = Trait, y = Module, fill = Correlation)) +
    geom_tile(color = "white", size = 1.5) +
    geom_text(aes(label = Label), 
              size = 5,           # ✅ Increased from 3 to 5
              color = "black", 
              fontface = "bold") +
    scale_fill_gradient2(
      low = "#2166AC",           # Blue
      mid = "white", 
      high = "#B2182B",          # Red
      midpoint = 0, 
      limits = c(-1, 1),
      name = "Pearson\nCorrelation"
    ) +
    theme_minimal(base_size = 16) +  # ✅ Increased from 12 to 16
    theme(
      axis.text.x = element_text(
        angle = 45, 
        hjust = 1, 
        size = 14,               # ✅ Increased font size
        face = "bold",
        color = "black"
      ),
      axis.text.y = element_text(
        size = 14,               # ✅ Increased font size
        face = "bold",
        color = "black"
      ),
      axis.title = element_text(
        size = 16,               # ✅ Increased font size
        face = "bold"
      ),
      legend.title = element_text(
        size = 14, 
        face = "bold"
      ),
      legend.text = element_text(size = 12),
      legend.position = "right",
      panel.grid = element_blank(),
      plot.title = element_text(
        size = 18,               # ✅ Increased font size
        face = "bold", 
        hjust = 0.5
      ),
      plot.subtitle = element_text(
        size = 13,               # ✅ Increased font size
        hjust = 0.5, 
        color = "gray40"
      ),
      plot.margin = margin(20, 20, 20, 20)  # ✅ Add margins
    ) +
    labs(
      title = "Module-Trait Correlations",
      subtitle = paste("* indicates p <", significance_threshold),
      x = "Trait",
      y = "Module"
    )
  
  return(p)
}

perform_module_trait_analysis <- function(wgcna_result, 
                                          trait_metadata,
                                          selected_trait_columns,
                                          sample_id_column = NULL) {
  
  print("=== MODULE-TRAIT ANALYSIS DEBUG ===")
  print(paste("Trait metadata rows:", nrow(trait_metadata)))
  print(paste("Trait metadata cols:", ncol(trait_metadata)))
  print(paste("Selected trait columns:", paste(selected_trait_columns, collapse=", ")))
  
  # Validate inputs
  if (is.null(trait_metadata) || is.null(selected_trait_columns)) {
    print("ERROR: NULL inputs provided")
    return(list(has_results = FALSE, message = "No trait data provided"))
  }
  
  if (length(selected_trait_columns) < 1) {
    print("ERROR: No traits selected")
    return(list(has_results = FALSE, message = "No traits selected"))
  }
  
  # Extract selected traits
  if (is.null(sample_id_column) || !sample_id_column %in% colnames(trait_metadata)) {
    sample_column <- colnames(trait_metadata)[1]
    print(paste("WARNING: sample_id_column not provided or invalid. Using first column:", sample_column))
  } else {
    sample_column <- sample_id_column
    print(paste("✅ Using specified sample column:", sample_column))
  }
  
  trait_data <- trait_metadata[, c(sample_column, selected_trait_columns), drop = FALSE]
  rownames(trait_data) <- trait_metadata[[sample_column]]
  trait_data <- trait_data[, -1, drop = FALSE]
  
  print(paste("Trait data extracted. Rows:", nrow(trait_data), "Cols:", ncol(trait_data)))
  
  # Match samples
  ME_samples <- rownames(wgcna_result$module_eigengenes)
  trait_samples <- rownames(trait_data)
  
  print(paste("Module eigengene samples:", length(ME_samples)))
  print(paste("ME sample names (first 3):", paste(head(ME_samples, 3), collapse=", ")))
  print(paste("Trait samples:", length(trait_samples)))
  print(paste("Trait sample names (first 3):", paste(head(trait_samples, 3), collapse=", ")))
  
  common_samples <- intersect(ME_samples, trait_samples)
  print(paste("Common samples found:", length(common_samples)))
  
  if (length(common_samples) < 3) {
    msg <- paste("Insufficient sample overlap. Need at least 3, found:", length(common_samples))
    print(paste("ERROR:", msg))
    print("=== SAMPLE MATCHING DEBUG ===")
    print("Module eigengene sample IDs:")
    print(head(ME_samples, 10))
    print("Trait metadata sample IDs:")
    print(head(trait_samples, 10))
    print("Please ensure sample IDs match exactly between expression data and metadata.")
    
    return(list(
      has_results = FALSE, 
      message = msg,
      me_samples = head(ME_samples, 5),
      trait_samples = head(trait_samples, 5)
    ))
  }
  
  print(paste("SUCCESS: Matched", length(common_samples), "samples"))
  
  # Subset data
  trait_data_matched <- trait_data[common_samples, , drop = FALSE]
  ME_matched <- wgcna_result$module_eigengenes[common_samples, , drop = FALSE]
  
  print("Preparing traits for correlation...")
  trait_prep <- prepare_traits_for_correlation(trait_data_matched)
  
  print(paste("Prepared traits:", ncol(trait_prep$prepared_traits)))
  
  # Calculate correlations
  print("Calculating correlations...")
  correlations <- cor(ME_matched, trait_prep$prepared_traits,
                      use = "pairwise.complete.obs", method = "pearson")
  
  print(paste("Correlation matrix dimensions:", 
              nrow(correlations), "x", ncol(correlations)))
  
  # Calculate p-values
  print("Calculating p-values...")
  n_samples <- length(common_samples)
  p_values <- matrix(NA, nrow = nrow(correlations), ncol = ncol(correlations))
  rownames(p_values) <- rownames(correlations)
  colnames(p_values) <- colnames(correlations)
  
  for (i in 1:nrow(correlations)) {
    for (j in 1:ncol(correlations)) {
      cor_val <- correlations[i, j]
      if (!is.na(cor_val)) {
        p_values[i, j] <- WGCNA::corPvalueStudent(cor_val, n_samples)
      }
    }
  }
  
  n_significant <- sum(p_values < 0.05, na.rm = TRUE)
  print(paste("Significant associations (p<0.05):", n_significant))
  
  # Create summary table
  print("Creating summary table...")
  summary_table <- create_module_trait_summary(
    correlation_results = list(correlations = correlations, p_values = p_values),
    modules = wgcna_result$modules,
    hub_genes = wgcna_result$hub_genes,
    min_pval = 0.05
  )
  
  print(paste("Summary table rows:", nrow(summary_table)))
  
  # Create heatmap
  print("Creating heatmap...")
  heatmap_plot <- plot_module_trait_heatmap(
    correlation_results = list(correlations = correlations, p_values = p_values),
    significance_threshold = 0.05
  )
  
  print("=== MODULE-TRAIT ANALYSIS COMPLETE ===")
  
  trait_info_proper <- list(
    n_traits = length(selected_trait_columns),  # Number of original traits selected
    n_samples_matched = n_samples,              # Number of matched samples
    trait_names = selected_trait_columns,       # Original trait column names
    encoding_details = trait_prep$encoding_info # Detailed encoding information
  )
  
  trait_info_detailed <- list(
    # Summary counts
    n_traits = length(selected_trait_columns),
    n_samples_matched = n_samples,
    
    # Trait details
    trait_names = selected_trait_columns,
    trait_types = sapply(trait_prep$encoding_info, function(x) x$type),
    
    # Encoding information
    encoding_details = trait_prep$encoding_info,
    
    # Additional metadata
    correlation_method = "pearson",
    analysis_date = Sys.time()
  )
  
  result <- list(
    has_results = TRUE,
    correlations = correlations,
    p_values = p_values,
    summary_table = summary_table,
    heatmap_plot = heatmap_plot,
    n_significant = n_significant,
    n_samples = n_samples,
    n_traits = ncol(trait_prep$prepared_traits),
    #trait_info = trait_info_proper
    trait_info = trait_info_detailed
  )
  
  print("Returning results with has_results = TRUE")
  
  return(result)
}





save_dendrogram_for_viz <- function(expression_data, adjacency, TOM = NULL) {
  
  print("🌳 Creating gene dendrogram for visualization...")
  
  tryCatch({
    # Calculate TOM if not provided
    if (is.null(TOM)) {
      if (requireNamespace("WGCNA", quietly = TRUE)) {
        dissTOM <- 1 - WGCNA::TOMsimilarity(adjacency)
      } else {
        # Fallback: use 1 - adjacency
        dissTOM <- 1 - adjacency
      }
    } else {
      dissTOM <- 1 - TOM
    }
    
    # Hierarchical clustering
    geneTree <- hclust(as.dist(dissTOM), method = "average")
    
    print("✅ Gene dendrogram created successfully")
    return(geneTree)
    
  }, error = function(e) {
    print(paste("⚠️ Could not create dendrogram:", e$message))
    return(NULL)
  })
}



# Main WGCNA analysis function
run_wgcna_analysis <- function(expression_data, selected_genes,
                               trait_data = NULL, soft_power = NULL,
                               min_module_size = 30, merge_threshold = 0.25,
                               max_genes = 5000, organism = "human") {
  
  print("🧬 Starting Enhanced WGCNA Co-expression Module Analysis...")
  
  tryCatch({
    
    # Step 1: Enhanced data preprocessing with quality control
    print("📊 Step 1: Data preprocessing and quality control...")
    processed_data <- preprocess_wgcna_data_enhanced(expression_data, selected_genes, max_genes)
    
    # Step 2: Intelligent soft power determination
    print("⚡ Step 2: Determining optimal soft power threshold...")
    if (is.null(soft_power)) {
      soft_power_result <- determine_soft_power_enhanced(processed_data$filtered_expression)
    } else {
      # Use provided soft power
      soft_power_result <- list(power = soft_power, scale_free_r2 = NA, fitIndices = NULL)
    }
    
    # Step 3: Build robust co-expression network
    print("🕸️ Step 3: Building co-expression network and detecting modules...")
    network_results <- build_coexpression_network_enhanced(
      expression_data = processed_data$filtered_expression,
      soft_power_result = soft_power_result,  # Pass the result object
      min_module_size = min_module_size,
      merge_threshold = merge_threshold
    )
    
    # Step 4: Comprehensive module analysis
    print("🔍 Step 4: Analyzing module properties and relationships...")
    module_analysis <- analyze_modules_enhanced(
      expression_data = processed_data$filtered_expression,
      module_colors = network_results$module_colors,
      trait_data = trait_data
    )
    
    # Step 5: Advanced hub gene identification
    print("⭐ Step 5: Identifying hub genes and key regulators...")
    hub_genes <- identify_hub_genes_enhanced(
      expression_data = processed_data$filtered_expression,
      module_colors = network_results$module_colors,
      adjacency_matrix = network_results$adjacency,
      selected_genes = selected_genes
    )
    
    # Step 6: Module functional enrichment
    print("🧪 Step 6: Performing functional enrichment analysis...")
    module_enrichment <- tryCatch({
      perform_module_enrichment_fixed_v2(
        modules = network_results$modules,
        selected_genes = selected_genes,
        hub_genes = hub_genes,
        organism = organism
      )
    }, error = function(e) {
      print(paste("⚠️ Enrichment analysis failed:", e$message))
      print("Continuing without enrichment results...")
      NULL
    })
    
    # Handle NULL result
    if (is.null(module_enrichment) || length(module_enrichment) == 0) {
      print("⚠️ No enrichment results available - analysis will continue")
      module_enrichment <- list()
    }
    
    # Step 7: Create interactive network visualization
    print("📈 Step 7: Creating safe network visualization...")
    
    network_visualization <- tryCatch({
      create_wgcna_network_viz_safe_fixed(
        modules = network_results$modules,
        hub_genes = hub_genes,
        module_colors = network_results$module_colors,
        selected_genes = selected_genes,
        module_enrichment = module_enrichment
      )
    }, error = function(viz_error) {
      print(paste("⚠️ Network visualization failed:", viz_error$message))
      print("Creating minimal network visualization...")
      
      # Fallback minimal visualization
      list(
        nodes = data.frame(
          id = "analysis_complete",
          label = "WGCNA Complete\nCheck Module Analysis Tab",
          color = "#28a745",
          size = 30,
          shape = "box",
          stringsAsFactors = FALSE
        ),
        edges = data.frame(),
        legend = list()
      )
    })
    
    # Step 8: Calculate comprehensive network metrics
    print("📊 Step 8: Calculating comprehensive network metrics...")
    wgcna_metrics <- calculate_wgcna_metrics_enhanced(
      expression_data = processed_data$filtered_expression,
      network_results = network_results,
      module_analysis = module_analysis,
      hub_genes = hub_genes
    )
    
    # if (exists("geneTree") && !is.null(geneTree)) {
    #   print("📊 Saving gene dendrogram for visualization...")
    #   # geneTree is created during hierarchical clustering
    # }
    
    # Save module colors as a vector (for dendrogram plot)
    module_colors_vector <- network_results$module_colors
    names(module_colors_vector) <- colnames(expression_data)
    
    # Compile comprehensive results
    results <- list(
      network_data = network_visualization,
      modules = network_results$modules,
      module_colors = network_results$module_colors,
      module_eigengenes = module_analysis$module_eigengenes,
      module_trait_correlations = module_analysis$trait_correlations,
      hub_genes = hub_genes,
      module_enrichment = module_enrichment,
      metrics = wgcna_metrics,
      quality_control = processed_data$qc_stats,
      analysis_type = "wgcna",

      # ✅ ADD THESE FOR DENDROGRAM VISUALIZATION
      dendrogram = network_results$gene_tree,  # The hierarchical clustering tree
      module_colors_vector = network_results$module_colors,  # Colors as named vector
      softPower = soft_power_result$power,
      soft_power_diagnostics = list(
        power = soft_power_result$power,
        fitIndices = soft_power_result$fitIndices,
        powerEstimate = soft_power_result$power
      ),
      analysis_params = list(
        soft_power = soft_power_result$power,
        min_module_size = min_module_size,
        merge_threshold = merge_threshold,
        n_samples = nrow(expression_data),      # Samples (15)
        n_genes = ncol(expression_data),        # Genes (4000)
        n_modules = length(unique(network_results$module_colors)) - 1,  # Exclude grey
        scale_free_r2 = network_results$scale_free_r2,
        analysis_timestamp = Sys.time()
      )
    )
    
    
    print("✅ WGCNA analysis completed successfully!")
    print(paste("🎯 Identified", length(results$modules), "co-expression modules"))
    print(paste("⭐ Found", nrow(hub_genes), "hub genes"))
    
    return(results)
    
  }, error = function(e) {
    print(paste("❌ Error in WGCNA analysis:", e$message))
    print("📍 Traceback:")
    print(traceback())
    return(list(error = e$message, traceback = traceback()))
  })
}

get_quality_assessment_html <- function(scale_free_r2, n_modules) {
  
  assessments <- c()
  
  # Scale-free topology
  if (!is.na(scale_free_r2)) {
    if (scale_free_r2 >= 0.8) {
      assessments <- c(assessments, 
                       '<p style="margin: 5px 0;"><span style="color: #28a745;">✓</span> 
        Excellent scale-free topology (R² ≥ 0.8)</p>')
    } else if (scale_free_r2 >= 0.7) {
      assessments <- c(assessments, 
                       '<p style="margin: 5px 0;"><span style="color: #ffc107;">⚠</span> 
        Good scale-free topology (R² ≥ 0.7)</p>')
    } else {
      assessments <- c(assessments, 
                       '<p style="margin: 5px 0;"><span style="color: #dc3545;">⚠</span> 
        Poor scale-free topology (R² < 0.7)</p>')
    }
  }
  
  # Module count
  if (n_modules >= 5 && n_modules <= 25) {
    assessments <- c(assessments, 
                     '<p style="margin: 5px 0;"><span style="color: #28a745;">✓</span> 
      Optimal module count (5-25 modules)</p>')
  } else if (n_modules < 5) {
    assessments <- c(assessments, 
                     '<p style="margin: 5px 0;"><span style="color: #ffc107;">⚠</span> 
      Few modules detected</p>')
  } else {
    assessments <- c(assessments, 
                     '<p style="margin: 5px 0;"><span style="color: #ffc107;">⚠</span> 
      Many modules detected</p>')
  }
  
  return(paste(assessments, collapse = ""))
}

get_quality_assessment <- function(scale_free_r2, n_modules) {
  
  assessments <- c()
  
  # Scale-free topology assessment
  if (!is.na(scale_free_r2)) {
    if (scale_free_r2 >= 0.8) {
      assessments <- c(assessments, " [OK] Excellent scale-free topology (R² ≥ 0.8)")
    } else if (scale_free_r2 >= 0.7) {
      assessments <- c(assessments, "  ⚠ Good scale-free topology (R² ≥ 0.7)")
    } else if (scale_free_r2 >= 0.6) {
      assessments <- c(assessments, "  ⚠ Acceptable scale-free topology (R² ≥ 0.6)")
    } else {
      assessments <- c(assessments, "  ⚠ Poor scale-free topology (R² < 0.6)")
    }
  }
  
  # Module count assessment
  if (n_modules >= 5 && n_modules <= 25) {
    assessments <- c(assessments, " [OK] Optimal module count (5-25 modules)")
  } else if (n_modules < 5) {
    assessments <- c(assessments, "  ⚠ Few modules - consider lowering merge threshold")
  } else if (n_modules > 25) {
    assessments <- c(assessments, "  ⚠ Many modules - consider increasing merge threshold")
  }
  
  return(paste(assessments, collapse = "\n"))
}

get_adaptive_wgcna_defaults <- function(n_samples, n_genes) {
  
  print(paste("📊 Calculating adaptive defaults for", n_samples, "samples and", n_genes, "genes"))
  
  # Calculate reasonable min module size based on actual gene count
  if (n_genes < 100) {
    # Very small gene sets - use tiny modules
    min_module_size <- max(5, round(n_genes * 0.1))  # 10% of genes, minimum 5
    print("⚠️ Very small gene set - using minimal module sizes")
  } else if (n_genes < 1000) {
    # Small gene sets
    min_module_size <- max(10, round(n_genes * 0.05))  # 5% of genes, minimum 10
  } else if (n_genes < 5000) {
    # Medium gene sets
    min_module_size <- max(15, round(n_genes * 0.01))  # 1% of genes, minimum 15
  } else {
    # Large gene sets
    min_module_size <- max(30, round(n_genes * 0.005))  # 0.5% of genes, minimum 30
  }
  
  # Cap module size to reasonable fraction of total genes
  max_reasonable_module_size <- round(n_genes * 0.3)  # Max 30% of genes per module
  min_module_size <- min(min_module_size, max_reasonable_module_size)
  
  # Ensure we can have at least 3-4 modules
  min_module_size <- min(min_module_size, floor(n_genes / 4))
  
  print(paste("📊 Adaptive min module size calculation:"))
  print(paste("   n_genes:", n_genes))
  print(paste("   Calculated min_module_size:", min_module_size))
  print(paste("   Max possible modules:", floor(n_genes / min_module_size)))
  
  return(list(
    min_module_size = min_module_size,
    max_genes = if (n_samples < 20) min(n_genes, 3000) else min(n_genes, 5000),
    merge_threshold = if (n_samples < 15) 0.30 else 0.25
  ))
}

# Preprocess data for WGCNA
preprocess_wgcna_data_enhanced <- function(expression_data, selected_genes, max_genes = 5000) {
  
  print("🔧 Enhanced preprocessing for WGCNA...")
  
  # Input validation - expression_data should already be samples × genes
  if (!is.matrix(expression_data) && !is.data.frame(expression_data)) {
    stop("❌ Expression data must be a matrix or data frame")
  }
  
  # Convert to matrix if needed (already in correct format: samples × genes)
  if (is.data.frame(expression_data)) {
    expression_matrix <- as.matrix(expression_data)
  } else {
    expression_matrix <- expression_data
  }
  
  print(paste("📊 Input dimensions:", nrow(expression_matrix), "samples ×", ncol(expression_matrix), "genes"))
  
  # Quality control checks
  gene_vars <- apply(expression_matrix, 2, var, na.rm = TRUE)
  gene_nas <- apply(expression_matrix, 2, function(x) sum(is.na(x)) / length(x))
  
  # Filter out problematic genes
  good_genes_mask <- !is.na(gene_vars) & gene_vars > 0 & gene_nas < 0.5
  filtered_expression <- expression_matrix[, good_genes_mask, drop = FALSE]
  
  print(paste("🗑️ Removed", sum(!good_genes_mask), "genes with zero variance or excessive missing values"))
  
  # WGCNA quality control
  print("🔍 Running WGCNA quality control checks...")
  
  tryCatch({
    good_samples <- WGCNA::goodSamples(filtered_expression, verbose = 1)
    good_genes <- WGCNA::goodGenes(filtered_expression, verbose = 1)
    
    if (sum(!good_samples) > 0) {
      filtered_expression <- filtered_expression[good_samples, , drop = FALSE]
      print(paste("🗑️ Removed", sum(!good_samples), "problematic samples"))
    }
    
    if (sum(!good_genes) > 0) {
      filtered_expression <- filtered_expression[, good_genes, drop = FALSE]
      print(paste("🗑️ Removed", sum(!good_genes), "problematic genes"))
    }
    
  }, error = function(e) {
    print(paste("⚠️ WGCNA quality control failed:", e$message))
  })
  
  # Final validation
  if (nrow(filtered_expression) < 4) {
    stop("❌ Too few samples remaining after filtering")
  }
  
  if (ncol(filtered_expression) < 20) {
    stop("❌ Too few genes remaining after filtering")
  }
  
  # Quality control statistics
  qc_stats <- list(
    original_samples = nrow(expression_matrix),
    original_genes = ncol(expression_matrix),
    final_samples = nrow(filtered_expression),
    final_genes = ncol(filtered_expression),
    missing_data_percent = sum(is.na(filtered_expression)) / (nrow(filtered_expression) * ncol(filtered_expression)) * 100
  )
  
  print(paste("✅ Final dataset:", nrow(filtered_expression), "samples ×", ncol(filtered_expression), "genes"))
  
  return(list(
    filtered_expression = filtered_expression,
    qc_stats = qc_stats
  ))
}


# Determine optimal soft power threshold
determine_soft_power_enhanced <- function(expression_data) {
  print("⚡ Determining optimal soft power threshold with enhanced diagnostics...")
  
  n_samples <- nrow(expression_data)
  n_genes <- ncol(expression_data)
  
  print(paste("📊 Dataset size:", n_samples, "samples"))
  
  powers <- if (n_samples < 20) c(1:10, seq(12, 20, 2)) else c(1:10, seq(12, 30, 2))
  
  tryCatch({
    sft <- pickSoftThreshold(
      expression_data,
      powerVector = powers,
      verbose = 5,
      networkType = "unsigned",
      corFnc = "cor"
    )
    
    fitIndices <- sft$fitIndices
    print(fitIndices)

    # A valid scale-free fit requires BOTH:
    #  - SFT.R.sq > 0.8 (the truncated power-law explains the connectivity
    #    distribution well)
    #  - slope < 0 (more high-degree nodes get progressively rarer; this
    #    is the defining property of a scale-free network)
    #
    # Filtering on R² alone (the previous behavior) silently picked
    # power = 1 on datasets where SFT.R.sq is already 0.9+ at power = 1
    # but slope is POSITIVE — meaning the data is fitting the WRONG
    # direction of the power law. Power = 1 effectively skips soft
    # thresholding and produces a dense "noise" network where every gene
    # connects to thousands of others.
    pass_both <- fitIndices$SFT.R.sq > 0.8 & fitIndices$slope < 0

    if (any(pass_both)) {
      # Lowest power that satisfies both criteria
      cand <- fitIndices[pass_both, ]
      idx  <- which.min(cand$Power)
      optimal_power <- cand$Power[idx]
      scale_free_r2 <- cand$SFT.R.sq[idx]
      print(paste("✅ Selected optimal power:", optimal_power,
                  "with R² =", round(scale_free_r2, 3),
                  "and slope =", round(cand$slope[idx], 3),
                  "(both criteria met)"))
      return(list(power = optimal_power, scale_free_r2 = scale_free_r2, fitIndices = fitIndices))
    }

    # No power achieved R² > 0.8 with negative slope. Use the canonical
    # sample-size-based fallback from Langfelder & Horvath's WGCNA tutorial
    # (https://horvath.genetics.ucla.edu/html/CoexpressionNetwork/Rpackages/WGCNA/Tutorials/).
    # Picking the lowest power with R² > 0.5 (the previous behaviour) is
    # non-standard and tends to retain noise correlations, producing a
    # denser network than warranted. The canonical table picks a moderate
    # power that gives a defensible network even when the data does not
    # quite reach the R² > 0.8 threshold.
    canonical_fallback <- if (n_samples < 20) 9
                          else if (n_samples < 30) 8
                          else if (n_samples < 40) 7
                          else 6
    fallback_idx <- which(fitIndices$Power == canonical_fallback)
    if (length(fallback_idx) == 1) {
      fallback_r2    <- fitIndices$SFT.R.sq[fallback_idx]
      fallback_slope <- fitIndices$slope[fallback_idx]
      print(paste("⚠️ No power reached R² > 0.8 with negative slope. Using Langfelder–Horvath canonical fallback for n =",
                  n_samples, "(unsigned): power =", canonical_fallback,
                  "| R² =", round(fallback_r2, 3),
                  "| slope =", round(fallback_slope, 3)))
      return(list(power = canonical_fallback,
                  scale_free_r2 = fallback_r2,
                  fitIndices = fitIndices))
    }
    # If the canonical power isn't in the tested grid for some reason,
    # report the maximum-R² power within negative-slope as a last resort.
    neg_slope <- fitIndices$slope < 0
    if (any(neg_slope)) {
      cand <- fitIndices[neg_slope, ]
      idx  <- which.max(cand$SFT.R.sq)
      optimal_power <- cand$Power[idx]
      scale_free_r2 <- cand$SFT.R.sq[idx]
      print(paste("⚠️ Canonical fallback power not in tested grid; using max-R² with negative slope:",
                  optimal_power, "(R² =", round(scale_free_r2, 3), ")"))
      return(list(power = optimal_power, scale_free_r2 = scale_free_r2, fitIndices = fitIndices))
    }

    print("⚠️ No power achieved a negative slope — input expression may not be scale-free; using sample-size-based fallback")

  }, error = function(e) {
    print(paste("⚠️ pickSoftThreshold failed:", e$message))
  })

  # Final fallback when pickSoftThreshold itself failed
  fallback_power <- if (n_samples < 20) 9
                    else if (n_samples < 30) 8
                    else if (n_samples < 40) 7
                    else 6
  print(paste("🔧 Using sample-size fallback power:", fallback_power, "for", n_samples, "samples"))
  return(list(power = fallback_power, scale_free_r2 = NA, fitIndices = NULL))
}


# Build co-expression network and detect modules
build_coexpression_network_enhanced <- function(expression_data, soft_power_result,
                                                min_module_size, merge_threshold) {
  
  print("🕸️ Building enhanced co-expression network...")
  
  # Extract power value
  if (is.list(soft_power_result)) {
    soft_power <- soft_power_result$power
    scale_free_r2 <- soft_power_result$scale_free_r2 %||% NA
    
    # Validate soft power
    if (is.null(soft_power) || is.na(soft_power) || soft_power < 1) {
      print("⚠️ Invalid soft power detected, using default")
      soft_power <- 6
      scale_free_r2 <- 0.6
    }
  } else {
    soft_power <- soft_power_result
    scale_free_r2 <- NA
    
    # Validate soft power
    if (is.null(soft_power) || is.na(soft_power) || soft_power < 1) {
      soft_power <- 6
      scale_free_r2 <- 0.6
    }
  }
  
  print(paste("🔧 Using soft power:", soft_power, "for network construction"))
  
  # Calculate adjacency matrix with progress
  print(paste("🔧 Calculating adjacency matrix with power =", soft_power))
  adjacency <- adjacency(
    expression_data,
    power = soft_power,
    type = "unsigned",
    corFnc = "cor"
  )
  
  # Transform to topological overlap matrix (TOM)
  print("🔄 Computing Topological Overlap Matrix...")
  TOM <- TOMsimilarity(adjacency, TOMType = "unsigned", verbose = 1)
  dissTOM <- 1 - TOM
  
  # Hierarchical clustering. flashClust is faster than base hclust on
  # large dissimilarity matrices, but newer WGCNA versions no longer
  # auto-load it. Use the package if available; otherwise fall back to
  # base R's hclust — algorithmically identical (Lance-Williams average).
  print("🌳 Performing hierarchical clustering...")
  gene_tree <- if (requireNamespace("flashClust", quietly = TRUE)) {
    flashClust::flashClust(as.dist(dissTOM), method = "average")
  } else if (requireNamespace("fastcluster", quietly = TRUE)) {
    fastcluster::hclust(as.dist(dissTOM), method = "average")
  } else {
    stats::hclust(as.dist(dissTOM), method = "average")
  }
  
  # Dynamic module detection with enhanced parameters
  print("🎯 Detecting modules with dynamic tree cutting...")
  dynamic_modules <- cutreeDynamic(
    dendro = gene_tree,
    distM = dissTOM,
    deepSplit = 2,
    pamRespectsDendro = FALSE,
    minClusterSize = min_module_size,
    maxCoreScatter = NULL,
    minGap = NULL,
    verbose = 2
  )
  
  # Convert to colors
  dynamic_colors <- labels2colors(dynamic_modules)
  n_initial_modules <- length(unique(dynamic_colors)) - 1  # Exclude grey
  print(paste("🎨 Initial modules detected:", n_initial_modules))
  
  # Calculate module eigengenes for merging
  MEList <- moduleEigengenes(expression_data, colors = dynamic_colors)
  MEs <- MEList$eigengenes
  
  # Merge similar modules
  print(paste("🔀 Merging similar modules (threshold =", merge_threshold, ")..."))
  merge_results <- mergeCloseModules(
    expression_data,
    dynamic_colors,
    cutHeight = merge_threshold,
    verbose = 2
  )
  
  # Final results
  merged_colors <- merge_results$colors
  merged_MEs <- merge_results$newMEs
  
  # Create final module assignments
  modules <- split(colnames(expression_data), merged_colors)
  if ("grey" %in% names(modules)) {
    print(paste("🔘 Unassigned genes (grey module):", length(modules$grey)))
    modules$grey <- NULL  # Remove unassigned genes
  }
  
  n_final_modules <- length(modules)
  print(paste("✅ Final modules after merging:", n_final_modules))
  
  return(list(
    adjacency = adjacency,
    TOM = TOM,
    gene_tree = gene_tree,
    module_colors = merged_colors,
    module_eigengenes = merged_MEs,
    modules = modules,
    scale_free_r2 = scale_free_r2
  ))
}

# Analyze modules and their relationships
analyze_modules_enhanced <- function(expression_data, module_colors, trait_data = NULL) {
  
  print("🔍 Enhanced module analysis...")
  
  # Calculate module eigengenes
  MEs <- moduleEigengenes(expression_data, module_colors)$eigengenes
  
  # Module-trait correlations if trait data provided
  trait_correlations <- NULL
  if (!is.null(trait_data) && nrow(trait_data) == nrow(expression_data)) {
    print("🎯 Calculating module-trait correlations...")
    
    # Ensure numeric trait data
    numeric_traits <- sapply(trait_data, is.numeric)
    if (sum(numeric_traits) > 0) {
      trait_data_numeric <- trait_data[, numeric_traits, drop = FALSE]
      
      # Calculate correlations
      module_trait_cor <- cor(MEs, trait_data_numeric, use = "pairwise.complete.obs")
      module_trait_pval <- corPvalueStudent(module_trait_cor, nrow(expression_data))
      
      trait_correlations <- list(
        correlations = module_trait_cor,
        p_values = module_trait_pval,
        trait_names = colnames(trait_data_numeric)
      )
      
      print(paste("📊 Calculated correlations for", ncol(trait_data_numeric), "traits"))
    }
  }
  
  # Module connectivity and preservation metrics
  module_connectivity <- data.frame(
    module = colnames(MEs),
    eigengene_connectivity = apply(MEs, 2, function(x) mean(abs(cor(x, expression_data, use = "pairwise.complete.obs")), na.rm = TRUE)),
    stringsAsFactors = FALSE
  )
  
  return(list(
    module_eigengenes = MEs,
    trait_correlations = trait_correlations,
    module_connectivity = module_connectivity
  ))
}

# Identify hub genes within each module
identify_hub_genes_enhanced <- function(expression_data, module_colors, adjacency_matrix, selected_genes) {
  
  print("⭐ Enhanced hub gene identification...")
  
  # FIXED: Handle different selected_genes formats
  if (is.character(selected_genes)) {
    # If it's a character vector, convert to expected format
    all_genes_list <- selected_genes
    print("🔧 Converting character vector to gene list")
  } else if (is.list(selected_genes) && !is.null(selected_genes$all_genes)) {
    # If it's already a list with all_genes
    all_genes_list <- selected_genes$all_genes
    print("🔧 Using provided gene list structure")
  } else {
    # Fallback: assume all genes in expression data are of interest
    all_genes_list <- colnames(expression_data)
    print("🔧 Using all expression data genes as fallback")
  }
  
  # Split genes by modules
  modules <- split(colnames(expression_data), module_colors)
  if ("grey" %in% names(modules)) {
    modules$grey <- NULL  # Remove unassigned genes
  }
  
  all_hub_genes <- data.frame()
  
  for (module_name in names(modules)) {
    module_genes <- modules[[module_name]]
    
    if (length(module_genes) >= 5) {
      print(paste("🔍 Analyzing module", module_name, "with", length(module_genes), "genes"))
      
      tryCatch({
        # Subset data for this module
        module_indices <- which(colnames(expression_data) %in% module_genes)
        module_adjacency <- adjacency_matrix[module_indices, module_indices, drop = FALSE]
        module_expr <- expression_data[, module_indices, drop = FALSE]
        
        # Calculate module eigengene safely
        if (ncol(module_expr) >= 3) {  # Need at least 3 genes for reliable ME
          ME_result <- WGCNA::moduleEigengenes(module_expr, colors = rep(module_name, ncol(module_expr)))
          ME <- ME_result$eigengenes[, 1]
        } else {
          # For very small modules, use first principal component
          ME <- prcomp(module_expr, scale. = TRUE)$x[, 1]
        }
        
        # Calculate hub metrics
        connectivity <- rowSums(module_adjacency, na.rm = TRUE)
        module_membership <- cor(module_expr, ME, use = "pairwise.complete.obs")[, 1]
        
        # Handle NA values
        module_membership[is.na(module_membership)] <- 0
        
        # Create hub metrics dataframe
        hub_metrics <- data.frame(
          gene = module_genes,
          module = module_name,
          connectivity = connectivity,
          module_membership = module_membership,
          is_deg = module_genes %in% all_genes_list,  # FIXED: Use converted gene list
          stringsAsFactors = FALSE
        )
        
        # Calculate composite hub score
        if (nrow(hub_metrics) > 1) {
          hub_metrics$hub_score <- (scale(hub_metrics$connectivity)[, 1] + 
                                      scale(abs(hub_metrics$module_membership))[, 1]) / 2
        } else {
          hub_metrics$hub_score <- 1  # Single gene gets max score
        }
        
        # Rank within module
        hub_metrics$hub_rank <- rank(-hub_metrics$hub_score)
        hub_metrics <- hub_metrics[order(hub_metrics$hub_rank), ]
        
        # Select top hubs adaptively
        n_hubs <- max(3, min(10, ceiling(nrow(hub_metrics) * 0.15)))
        module_hubs <- head(hub_metrics, n_hubs)
        
        all_hub_genes <- rbind(all_hub_genes, module_hubs)
        
      }, error = function(e) {
        print(paste("⚠️ Error analyzing module", module_name, ":", e$message))
      })
    }
  }
  
  # Add global rankings if we have results
  if (nrow(all_hub_genes) > 0) {
    all_hub_genes$global_hub_rank <- rank(-all_hub_genes$hub_score)
    all_hub_genes$percentile <- (nrow(all_hub_genes) - all_hub_genes$global_hub_rank + 1) / nrow(all_hub_genes) * 100
  }
  
  print(paste("✅ Identified", nrow(all_hub_genes), "hub genes across", length(modules), "modules"))
  if (nrow(all_hub_genes) > 0) {
    print(paste("🎯", sum(all_hub_genes$is_deg), "hub genes are also DEGs"))
  }
  
  return(all_hub_genes)
}

# Step 1: Debug function to check what your gene IDs actually look like
debug_gene_ids <- function(modules) {
  print("🔍 DEBUGGING GENE ID FORMATS...")
  
  # Check the first module
  if (length(modules) > 0) {
    first_module <- modules[[1]]
    print(paste("📝 Sample gene IDs from first module:"))
    print(head(first_module, 10))
    
    # Analyze ID patterns
    print("\n🔬 ID PATTERN ANALYSIS:")
    print(paste("- Total genes:", length(first_module)))
    print(paste("- Sample IDs:", paste(head(first_module, 5), collapse = ", ")))
    
    # Check for different ID patterns
    ensembl_pattern <- grepl("^ENSG[0-9]+", first_module)
    entrez_pattern <- grepl("^[0-9]+$", first_module)
    symbol_pattern <- grepl("^[A-Z][A-Z0-9-]+$", first_module)
    
    print(paste("- ENSEMBL IDs (ENSG...):", sum(ensembl_pattern)))
    print(paste("- Entrez IDs (numbers):", sum(entrez_pattern)))
    print(paste("- Gene symbols:", sum(symbol_pattern)))
    print(paste("- Other format:", sum(!ensembl_pattern & !entrez_pattern & !symbol_pattern)))
    
    # Check for version numbers or suffixes
    has_versions <- grepl("\\.", first_module)
    has_suffixes <- grepl("_", first_module)
    
    print(paste("- IDs with version numbers (.):", sum(has_versions)))
    print(paste("- IDs with suffixes (_):", sum(has_suffixes)))
    
    return(list(
      sample_ids = head(first_module, 10),
      ensembl_count = sum(ensembl_pattern),
      entrez_count = sum(entrez_pattern),
      symbol_count = sum(symbol_pattern),
      has_versions = sum(has_versions),
      has_suffixes = sum(has_suffixes)
    ))
  }
}

# Step 2: Smart gene ID conversion that handles multiple formats
smart_gene_conversion <- function(gene_ids) {
  print("🔄 SMART GENE CONVERSION STARTING...")
  print(paste("Input sample:", paste(head(gene_ids, 3), collapse = ", ")))
  
  # Clean the IDs first
  clean_ids <- gene_ids
  
  # Remove version numbers (e.g., ENSG00000139618.2 -> ENSG00000139618)
  clean_ids <- sub("\\.[0-9]+$", "", clean_ids)
  
  # Remove suffixes (e.g., GENE_red_vs_green -> GENE)
  clean_ids <- sub("_.*$", "", clean_ids)
  
  print(paste("Cleaned sample:", paste(head(clean_ids, 3), collapse = ", ")))
  
  # Try to identify the ID type
  if (any(grepl("^ENSG[0-9]+", clean_ids))) {
    print("✅ Detected ENSEMBL gene IDs")
    return(convert_ensembl_to_symbols(clean_ids))
    
  } else if (any(grepl("^[0-9]+$", clean_ids))) {
    print("✅ Detected Entrez IDs")
    return(convert_entrez_to_symbols(clean_ids))
    
  } else if (any(grepl("^[A-Z][A-Z0-9-]+$", clean_ids))) {
    print("✅ Detected gene symbols - using as-is")
    return(unique(clean_ids[!is.na(clean_ids) & clean_ids != ""]))
    
  } else {
    print("⚠️ Unknown ID format - trying multiple conversion methods...")
    return(try_multiple_conversions(clean_ids))
  }
}

# Helper function to convert ENSEMBL IDs
convert_ensembl_to_symbols <- function(ensembl_ids) {
  library(AnnotationDbi)
  library(org.Hs.eg.db)
  
  tryCatch({
    # Check if these are valid ENSEMBL keys
    valid_keys <- ensembl_ids %in% keys(org.Hs.eg.db, keytype = "ENSEMBL")
    print(paste("Valid ENSEMBL keys:", sum(valid_keys), "out of", length(ensembl_ids)))
    
    if (sum(valid_keys) == 0) {
      print("❌ No valid ENSEMBL keys found - trying alternative methods")
      return(try_alternative_conversions(ensembl_ids))
    }
    
    # Convert valid IDs
    symbols <- AnnotationDbi::mapIds(
      org.Hs.eg.db,
      keys = ensembl_ids[valid_keys],
      column = "SYMBOL",
      keytype = "ENSEMBL",
      multiVals = "first"
    )
    
    valid_symbols <- symbols[!is.na(symbols)]
    print(paste("✅ Converted", length(valid_symbols), "ENSEMBL IDs to symbols"))
    return(unique(valid_symbols))
    
  }, error = function(e) {
    print(paste("❌ ENSEMBL conversion failed:", e$message))
    return(try_alternative_conversions(ensembl_ids))
  })
}

# Helper function to convert Entrez IDs
convert_entrez_to_symbols <- function(entrez_ids) {
  library(AnnotationDbi)
  library(org.Hs.eg.db)
  
  tryCatch({
    symbols <- AnnotationDbi::mapIds(
      org.Hs.eg.db,
      keys = entrez_ids,
      column = "SYMBOL",
      keytype = "ENTREZID",
      multiVals = "first"
    )
    
    valid_symbols <- symbols[!is.na(symbols)]
    print(paste("✅ Converted", length(valid_symbols), "Entrez IDs to symbols"))
    return(unique(valid_symbols))
    
  }, error = function(e) {
    print(paste("❌ Entrez conversion failed:", e$message))
    return(entrez_ids)  # Return original as fallback
  })
}

# Try alternative conversion methods
try_alternative_conversions <- function(gene_ids) {
  print("🔄 Trying alternative conversion methods...")
  
  # Method 1: Try removing more prefixes/suffixes
  cleaned_ids <- gsub("^[^A-Z]*", "", gene_ids)  # Remove non-letter prefixes
  cleaned_ids <- gsub("[^A-Z0-9].*$", "", cleaned_ids)  # Remove after first non-alphanumeric
  
  if (any(grepl("^ENSG[0-9]+", cleaned_ids))) {
    print("📝 Found ENSEMBL pattern after cleaning")
    return(convert_ensembl_to_symbols(cleaned_ids))
  }
  
  # Method 2: Assume they are already symbols and clean them
  symbol_candidates <- toupper(gene_ids)
  symbol_candidates <- gsub("[^A-Z0-9-]", "", symbol_candidates)
  symbol_candidates <- symbol_candidates[nchar(symbol_candidates) >= 2]
  
  print(paste("📝 Treating as gene symbols:", length(symbol_candidates), "candidates"))
  return(unique(symbol_candidates))
}

# Try multiple conversion approaches
try_multiple_conversions <- function(gene_ids) {
  print("🔄 Trying multiple conversion approaches...")
  
  # Try each approach and combine results
  results <- c()
  
  # Approach 1: As ENSEMBL
  tryCatch({
    ensembl_results <- convert_ensembl_to_symbols(gene_ids)
    results <- c(results, ensembl_results)
  }, error = function(e) NULL)
  
  # Approach 2: As Entrez
  tryCatch({
    entrez_results <- convert_entrez_to_symbols(gene_ids)
    results <- c(results, entrez_results)
  }, error = function(e) NULL)
  
  # Approach 3: As symbols
  clean_symbols <- toupper(gene_ids)
  clean_symbols <- gsub("[^A-Z0-9-]", "", clean_symbols)
  results <- c(results, clean_symbols)
  
  # Return unique results
  final_results <- unique(results[!is.na(results) & results != ""])
  print(paste("🎯 Combined results:", length(final_results), "unique gene symbols"))
  
  return(final_results)
}

convert_gene_ids_to_symbols_deg <- function(gene_ids, organism) {
  print(paste("DEBUG: Converting", length(gene_ids), "gene IDs for organism:", organism))
  
  # Organism to annotation package mapping
  org_db_mapping <- list(
    human = "org.Hs.eg.db",
    mouse = "org.Mm.eg.db",
    rat = "org.Rn.eg.db",
    fly = "org.Dm.eg.db",
    zebrafish = "org.Dr.eg.db",
    celegans = "org.Ce.eg.db",
    yeast = "org.Sc.sgd.db",
    arabidopsis = "org.At.tair.db",
    chicken = "org.Gg.eg.db",
    pig = "org.Ss.eg.db"
  )
  
  org_db_name <- org_db_mapping[[organism]]
  
  # Return original IDs with "-" as symbol if no annotation package
  if (is.null(org_db_name)) {
    print(paste("DEBUG: No annotation package for organism:", organism))
    return(data.frame(
      original_id = gene_ids,
      gene_symbol = rep("-", length(gene_ids)),
      conversion_status = rep("no_annotation", length(gene_ids)),
      stringsAsFactors = FALSE
    ))
  }
  
  # Check if annotation package is available
  if (!requireNamespace(org_db_name, quietly = TRUE)) {
    print(paste("DEBUG: Annotation package", org_db_name, "not available"))
    return(data.frame(
      original_id = gene_ids,
      gene_symbol = rep("-", length(gene_ids)),
      conversion_status = rep("package_missing", length(gene_ids)),
      stringsAsFactors = FALSE
    ))
  }
  
  # Load required libraries
  tryCatch({
    library(org_db_name, character.only = TRUE)
    library(AnnotationDbi)
    
    db_obj <- get(org_db_name)
    
    # Initialize results
    results <- data.frame(
      original_id = gene_ids,
      gene_symbol = as.character(gene_ids),  # Default to original ID
      conversion_status = rep("no_conversion", length(gene_ids)),
      stringsAsFactors = FALSE
    )
    
    # Clean gene IDs (remove version numbers from Ensembl IDs)
    clean_gene_ids <- gsub("\\.[0-9]+$", "", gene_ids)
    
    # Detect ID types
    enst_indices <- grep("^ENST", clean_gene_ids)
    ensg_indices <- grep("^ENSG", clean_gene_ids)
    ensembl_indices <- grep("^ENS[A-Z]*G", clean_gene_ids)  # Catch all Ensembl gene IDs
    entrez_indices <- grep("^[0-9]+$", clean_gene_ids)
    
    print(paste("DEBUG: ID types detected -",
                "ENST:", length(enst_indices),
                "ENSG:", length(ensg_indices),
                "Ensembl:", length(ensembl_indices),
                "Entrez:", length(entrez_indices)))
    
    # Special handling for yeast
    if (organism == "yeast") {
      print("DEBUG: Applying yeast-specific conversion")
      yeast_keytypes <- c("SYMBOL", "ORF", "GENENAME", "ENTREZID")
      
      for (kt in yeast_keytypes) {
        if (kt %in% AnnotationDbi::keytypes(db_obj)) {
          tryCatch({
            temp_mapped <- AnnotationDbi::mapIds(
              db_obj,
              keys = clean_gene_ids,
              column = "GENENAME",
              keytype = kt,
              multiVals = "first"
            )
            
            # Update results where conversion was successful
            converted_indices <- which(!is.na(temp_mapped))
            if (length(converted_indices) > 0) {
              results$gene_symbol[converted_indices] <- temp_mapped[converted_indices]
              results$conversion_status[converted_indices] <- paste0("converted_from_", kt)
              print(paste("DEBUG: Yeast conversion from", kt, ":", length(converted_indices), "genes"))
            }
          }, error = function(e) {
            print(paste("DEBUG: Yeast conversion from", kt, "failed:", e$message))
          })
        }
      }
    } else {
      # Standard organism conversion
      
      # 1. Convert Ensembl gene IDs (ENSG, etc.)
      if (length(ensembl_indices) > 0) {
        tryCatch({
          if ("ENSEMBL" %in% AnnotationDbi::keytypes(db_obj)) {
            ensembl_symbols <- AnnotationDbi::mapIds(
              db_obj,
              keys = clean_gene_ids[ensembl_indices],
              column = "SYMBOL",
              keytype = "ENSEMBL",
              multiVals = "first"
            )
            
            valid_indices <- which(!is.na(ensembl_symbols))
            if (length(valid_indices) > 0) {
              global_indices <- ensembl_indices[valid_indices]
              results$gene_symbol[global_indices] <- ensembl_symbols[valid_indices]
              results$conversion_status[global_indices] <- "converted_from_ENSEMBL"
              print(paste("DEBUG: Converted", length(valid_indices), "Ensembl IDs to symbols"))
            }
          }
        }, error = function(e) {
          print(paste("DEBUG: Ensembl conversion failed:", e$message))
        })
      }
      
      # 2. Convert Entrez IDs
      if (length(entrez_indices) > 0) {
        tryCatch({
          if ("ENTREZID" %in% AnnotationDbi::keytypes(db_obj)) {
            entrez_symbols <- AnnotationDbi::mapIds(
              db_obj,
              keys = clean_gene_ids[entrez_indices],
              column = "SYMBOL",
              keytype = "ENTREZID",
              multiVals = "first"
            )
            
            valid_indices <- which(!is.na(entrez_symbols))
            if (length(valid_indices) > 0) {
              global_indices <- entrez_indices[valid_indices]
              results$gene_symbol[global_indices] <- entrez_symbols[valid_indices]
              results$conversion_status[global_indices] <- "converted_from_ENTREZID"
              print(paste("DEBUG: Converted", length(valid_indices), "Entrez IDs to symbols"))
            }
          }
        }, error = function(e) {
          print(paste("DEBUG: Entrez conversion failed:", e$message))
        })
      }
      
      # 3. Handle transcript IDs (ENST) with biomaRt fallback
      if (length(enst_indices) > 0 && organism %in% c("human", "mouse")) {
        tryCatch({
          if (requireNamespace("biomaRt", quietly = TRUE)) {
            dataset_name <- if (organism == "human") "hsapiens_gene_ensembl" else "mmusculus_gene_ensembl"
            
            mart <- biomaRt::useMart("ensembl", dataset = dataset_name)
            
            transcript_mapping <- biomaRt::getBM(
              attributes = c("ensembl_transcript_id", "external_gene_name"),
              filters = "ensembl_transcript_id",
              values = clean_gene_ids[enst_indices],
              mart = mart
            )
            
            if (nrow(transcript_mapping) > 0) {
              for (i in seq_along(enst_indices)) {
                transcript_id <- clean_gene_ids[enst_indices[i]]
                matching_row <- which(transcript_mapping$ensembl_transcript_id == transcript_id)
                
                if (length(matching_row) > 0 && !is.na(transcript_mapping$external_gene_name[matching_row[1]])) {
                  results$gene_symbol[enst_indices[i]] <- transcript_mapping$external_gene_name[matching_row[1]]
                  results$conversion_status[enst_indices[i]] <- "converted_from_TRANSCRIPT"
                }
              }
              print(paste("DEBUG: Converted", sum(results$conversion_status[enst_indices] == "converted_from_TRANSCRIPT"), "transcript IDs"))
            }
          }
        }, error = function(e) {
          print(paste("DEBUG: Transcript conversion failed:", e$message))
        })
      }
      
      # 4. Verify existing symbols
      symbol_indices <- which(results$conversion_status == "no_conversion")
      if (length(symbol_indices) > 0) {
        tryCatch({
          if ("SYMBOL" %in% AnnotationDbi::keytypes(db_obj)) {
            valid_symbols <- clean_gene_ids[symbol_indices] %in% AnnotationDbi::keys(db_obj, keytype = "SYMBOL")
            verified_indices <- symbol_indices[valid_symbols]
            if (length(verified_indices) > 0) {
              results$conversion_status[verified_indices] <- "verified_symbol"
              print(paste("DEBUG: Verified", length(verified_indices), "existing symbols"))
            }
          }
        }, error = function(e) {
          print(paste("DEBUG: Symbol verification failed:", e$message))
        })
      }
    }
    
    # Set unconverted genes to "-"
    unconverted_indices <- which(results$conversion_status == "no_conversion")
    if (length(unconverted_indices) > 0) {
      results$gene_symbol[unconverted_indices] <- "-"
      print(paste("DEBUG:", length(unconverted_indices), "genes could not be converted"))
    }
    
    # Summary
    conversion_summary <- table(results$conversion_status)
    print("DEBUG: Conversion summary:")
    print(conversion_summary)
    
    return(results)
    
  }, error = function(e) {
    print(paste("DEBUG: Gene conversion failed:", e$message))
    return(data.frame(
      original_id = gene_ids,
      gene_symbol = rep("-", length(gene_ids)),
      conversion_status = rep("conversion_error", length(gene_ids)),
      stringsAsFactors = FALSE
    ))
  })
}

convert_hub_genes_to_symbols <- function(hub_genes, organism = "mouse") {
  
  print("🔄 Converting hub gene IDs to symbols...")
  
  # Check if gene column exists and has ENSEMBL IDs
  if ("gene" %in% colnames(hub_genes) && nrow(hub_genes) > 0) {
    
    # Sample the IDs to check format
    sample_ids <- head(hub_genes$gene, 3)
    print(paste("Sample hub gene IDs:", paste(sample_ids, collapse = ", ")))
    
    # Check if they're ENSEMBL IDs
    if (any(grepl("^ENSMUSG|^ENSG", hub_genes$gene))) {
      
      print(paste("  Detected ENSEMBL IDs - converting", nrow(hub_genes), "genes..."))
      
      # Use your existing conversion function
      conversion_result <- convert_gene_ids_to_symbols_deg(
        gene_ids = hub_genes$gene,
        organism = organism
      )
      
      # FIXED: Handle different return types from conversion function
      converted_symbols <- if(is.list(conversion_result)) {
        # If it returns a list, extract just the symbols
        if("symbols" %in% names(conversion_result)) {
          conversion_result$symbols
        } else if("gene_symbol" %in% names(conversion_result)) {
          conversion_result$gene_symbol
        } else {
          # Take first element if structure is unclear
          unlist(conversion_result)[1:length(hub_genes$gene)]
        }
      } else {
        # If it's already a vector, use it directly
        conversion_result
      }
      
      # Ensure we have the right length
      if(length(converted_symbols) != nrow(hub_genes)) {
        warning(paste("Conversion returned", length(converted_symbols), 
                      "values but expected", nrow(hub_genes)))
        # Truncate or pad as needed
        if(length(converted_symbols) > nrow(hub_genes)) {
          converted_symbols <- converted_symbols[1:nrow(hub_genes)]
        } else {
          converted_symbols <- c(converted_symbols, 
                                 rep(NA, nrow(hub_genes) - length(converted_symbols)))
        }
      }
      
      # Add symbol column (keep original ID too for reference)
      hub_genes$original_id <- hub_genes$gene
      hub_genes$gene_symbol <- as.character(converted_symbols)
      
      # Replace gene column with symbols where available
      hub_genes$gene <- ifelse(
        !is.na(converted_symbols) & converted_symbols != "" & converted_symbols != "-",
        as.character(converted_symbols),
        hub_genes$gene  # Keep original if conversion failed
      )
      
      success_count <- sum(!is.na(converted_symbols) & converted_symbols != "" & converted_symbols != "-")
      print(paste("  ✅ Successfully converted", success_count, "out of", nrow(hub_genes), "hub genes"))
      
    } else {
      print("  ℹ️  Hub genes already appear to be symbols")
    }
  }
  
  return(hub_genes)
}

calculate_optimal_gene_count <- function(expression_data, min_genes = 1000, max_genes = 15000) {
  
  n_samples <- ncol(expression_data)
  n_total_genes <- nrow(expression_data)
  
  print(paste("📊 Calculating optimal gene count for", n_samples, "samples and", n_total_genes, "total genes"))
  
  # 1. SAMPLE SIZE CONSTRAINT
  max_genes_by_sample_ratio <- n_samples * 300
  
  # 2. COMPUTATIONAL CONSTRAINT  
  available_memory_gb <- 16
  available_memory_bytes <- available_memory_gb * (1024^3)
  max_genes_by_memory <- 1000
  for (test_genes in seq(1000, 20000, by = 500)) {
    memory_usage <- estimate_memory_usage(test_genes, n_samples)
    if (memory_usage$total_bytes > available_memory_bytes) break
    max_genes_by_memory <- test_genes
  }
  
  # 3. STATISTICAL POWER CONSTRAINT
  if (n_samples < 10) {
    max_genes_by_power <- min(2000, n_total_genes * 0.15)
  } else if (n_samples < 20) {
    max_genes_by_power <- min(4000, n_total_genes * 0.25)
  } else if (n_samples < 50) {
    max_genes_by_power <- min(8000, n_total_genes * 0.40)
  } else {
    max_genes_by_power <- min(15000, n_total_genes * 0.60)
  }
  
  # 4. VARIANCE-BASED SELECTION (FIXED!)
  print("📊 Analyzing variance distribution...")
  
  tryCatch({
    log_expr <- log2(expression_data + 1)
    gene_vars <- apply(log_expr, 1, var, na.rm = TRUE)
    
    # Remove invalid variance values
    valid_vars <- gene_vars[!is.na(gene_vars) & gene_vars > 0]
    
    print(paste("Valid genes with variance:", length(valid_vars)))
    print(paste("Variance range:", round(min(valid_vars), 4), "to", round(max(valid_vars), 4)))
    
    if (length(valid_vars) < 1000) {
      print("⚠️ Very few genes with valid variance - using all available")
      meaningful_var_genes <- length(valid_vars)
    } else {
      # Find variance "elbow" with better logic
      sorted_vars <- sort(valid_vars, decreasing = TRUE)
      n_genes_to_check <- min(length(sorted_vars), 10000)  # Check top 10k genes max
      
      # Calculate variance differences in top genes
      var_diffs <- diff(sorted_vars[1:n_genes_to_check])
      
      # Find significant drops (more robust approach)
      if (length(var_diffs) > 100) {
        # Use percentile-based cutoff instead of single threshold
        cutoff_threshold <- quantile(abs(var_diffs), 0.90)  # Less stringent than 0.95
        meaningful_var_genes <- which(var_diffs < -cutoff_threshold)[1]
        
        if (is.na(meaningful_var_genes) || meaningful_var_genes < 500) {
          # Fallback: use reasonable percentage of genes
          meaningful_var_genes <- min(5000, length(valid_vars))
          print("📊 Using fallback variance cutoff")
        }
      } else {
        meaningful_var_genes <- min(3000, length(valid_vars))
        print("📊 Using default variance cutoff for small gene set")
      }
    }
    
  }, error = function(e) {
    print(paste("⚠️ Variance calculation failed:", e$message))
    meaningful_var_genes <- min(3000, n_total_genes)  # Safe fallback
  })
  
  print(paste("📊 Variance cutoff allows:", meaningful_var_genes, "genes"))
  
  # 5. COMBINE ALL CONSTRAINTS (with minimum enforcement)
  optimal_gene_count <- min(
    max_genes_by_sample_ratio,
    max_genes_by_memory,
    max_genes_by_power,
    meaningful_var_genes,
    max_genes,
    n_total_genes
  )
  
  # CRITICAL: Enforce absolute minimum for WGCNA
  optimal_gene_count <- max(optimal_gene_count, min_genes)
  
  # 6. PROVIDE RECOMMENDATIONS
  constraints <- data.frame(
    Constraint = c("Sample Ratio", "Memory Limit", "Statistical Power", 
                   "Variance Cutoff", "User Max", "Total Available"),
    Limit = c(max_genes_by_sample_ratio, max_genes_by_memory, max_genes_by_power,
              meaningful_var_genes, max_genes, n_total_genes),
    Reasoning = c(
      paste("300 genes per sample * ", n_samples, " samples"),
      paste(available_memory_gb, "GB RAM correlation matrix limit"),
      paste("Statistical power for", n_samples, "samples"),
      "Meaningful variance threshold",
      "User-specified maximum",
      "Total genes in dataset"
    )
  )
  
  limiting_constraint <- constraints$Constraint[which.min(constraints$Limit)]
  
  print("📊 GENE COUNT ANALYSIS:")
  print(constraints)
  print(paste("🎯 Optimal gene count:", optimal_gene_count))
  print(paste("⚠️  Limiting factor:", limiting_constraint))
  
  return(list(
    optimal_count = optimal_gene_count,
    constraints = constraints,
    limiting_factor = limiting_constraint
  ))
}

