select_genes_adaptively <- function(expression_data, target_count = NULL) {
  
  if (is.null(target_count)) {
    # Calculate optimal count
    analysis <- calculate_optimal_gene_count(expression_data)
    target_count <- analysis$optimal_count
    print(paste("📊 Auto-calculated target gene count:", target_count))
  }
  
  # Calculate variance on log-transformed data
  log_expr <- log2(expression_data + 1)
  gene_vars <- apply(log_expr, 1, var, na.rm = TRUE)
  
  # Remove zero or NA variance genes
  valid_genes <- !is.na(gene_vars) & gene_vars > 0
  gene_vars <- gene_vars[valid_genes]
  valid_expression <- expression_data[valid_genes, ]
  
  # Select top variable genes
  top_genes <- names(sort(gene_vars, decreasing = TRUE))[1:min(target_count, length(gene_vars))]
  
  # Quality checks
  selected_vars <- gene_vars[top_genes]
  
  quality_metrics <- list(
    selected_count = length(top_genes),
    target_count = target_count,
    min_variance = min(selected_vars),
    max_variance = max(selected_vars),
    median_variance = median(selected_vars),
    variance_range_factor = max(selected_vars) / min(selected_vars)
  )
  
  print("📊 GENE SELECTION QUALITY:")
  print(paste("✅ Selected genes:", quality_metrics$selected_count))
  print(paste("📈 Variance range:", round(quality_metrics$min_variance, 3), "to", round(quality_metrics$max_variance, 3)))
  print(paste("📊 Range factor:", round(quality_metrics$variance_range_factor, 1), "x"))
  
  # Warning if variance range is too narrow (genes too similar)
  if (quality_metrics$variance_range_factor < 5) {
    warning("⚠️ Selected genes have similar variance - may indicate insufficient diversity")
  }
  
  # Warning if minimum variance is too low
  if (quality_metrics$min_variance < 0.1) {
    warning("⚠️ Some selected genes have very low variance - consider increasing threshold")
  }
  
  return(list(
    selected_genes = top_genes,
    selected_expression = valid_expression[top_genes, ],
    quality_metrics = quality_metrics,
    variance_distribution = selected_vars
  ))
}

estimate_memory_usage <- function(n_genes, n_samples) {
  # Correlation matrix: n_genes x n_genes x 8 bytes (double precision)
  corr_matrix_size <- n_genes^2 * 8
  
  # TOM matrix: similar size to correlation matrix
  tom_matrix_size <- n_genes^2 * 8
  
  # Expression data: n_samples x n_genes x 8 bytes
  expr_data_size <- n_samples * n_genes * 8
  
  # Additional WGCNA intermediate objects (estimated)
  intermediate_objects <- n_genes * n_samples * 8 * 2  # Rough estimate
  
  # Total estimated memory with 50% safety buffer
  total_estimated <- (corr_matrix_size + tom_matrix_size + expr_data_size + intermediate_objects) * 1.5
  
  return(list(
    total_bytes = total_estimated,
    total_gb = total_estimated / (1024^3),
    corr_matrix_gb = corr_matrix_size / (1024^3),
    tom_matrix_gb = tom_matrix_size / (1024^3),
    expr_data_gb = expr_data_size / (1024^3)
  ))
}

