check_druggability_chembl <- function(gene_symbols, organism = "Homo sapiens") {
  
  # Initialize results
  results <- data.frame(
    gene = gene_symbols,
    is_druggable = FALSE,
    has_approved_drug = FALSE,
    has_clinical_candidate = FALSE,
    n_bioactivities = 0,
    max_phase = 0,
    chembl_target_id = NA_character_,
    drug_names = NA_character_,
    stringsAsFactors = FALSE
  )
  
  # Check if httr is available
  if (!requireNamespace("httr", quietly = TRUE)) {
    print("⚠️ httr package not available - using fallback druggability list")
    return(check_druggability_fallback(gene_symbols))
  }
  
  if (!requireNamespace("jsonlite", quietly = TRUE)) {
    print("⚠️ jsonlite package not available - using fallback druggability list")
    return(check_druggability_fallback(gene_symbols))
  }
  
  print(paste("🔍 Checking druggability for", length(gene_symbols), "genes via ChEMBL API..."))
  
  # Process each gene
  for (i in seq_along(gene_symbols)) {
    gene <- gene_symbols[i]
    
    tryCatch({
      # Step 1: Search for target by gene symbol
      # ChEMBL API endpoint for target search
      target_url <- paste0(
        "https://www.ebi.ac.uk/chembl/api/data/target/search.json?q=",
        URLencode(gene),
        "&limit=5"
      )
      
      response <- httr::GET(
        target_url,
        httr::timeout(10),
        httr::add_headers("Accept" = "application/json")
      )
      
      if (httr::status_code(response) == 200) {
        content <- httr::content(response, as = "text", encoding = "UTF-8")
        data <- jsonlite::fromJSON(content, flatten = TRUE)
        
        if (!is.null(data$targets) && length(data$targets) > 0) {
          # Find human single protein target matching gene symbol
          targets <- data$targets
          
          # Filter for human targets
          human_targets <- targets[grepl("Homo sapiens", targets$organism, ignore.case = TRUE), ]
          
          if (nrow(human_targets) > 0) {
            # Get the first matching target
            target_id <- human_targets$target_chembl_id[1]
            results$chembl_target_id[i] <- target_id
            
            # Step 2: Check for drug mechanisms (approved drugs targeting this)
            mech_url <- paste0(
              "https://www.ebi.ac.uk/chembl/api/data/mechanism.json?target_chembl_id=",
              target_id,
              "&limit=10"
            )
            
            mech_response <- httr::GET(
              mech_url,
              httr::timeout(10),
              httr::add_headers("Accept" = "application/json")
            )
            
            if (httr::status_code(mech_response) == 200) {
              mech_content <- httr::content(mech_response, as = "text", encoding = "UTF-8")
              mech_data <- jsonlite::fromJSON(mech_content, flatten = TRUE)
              
              if (!is.null(mech_data$mechanisms) && length(mech_data$mechanisms) > 0) {
                results$is_druggable[i] <- TRUE
                
                # Get max phase
                if ("max_phase" %in% colnames(mech_data$mechanisms)) {
                  results$max_phase[i] <- max(mech_data$mechanisms$max_phase, na.rm = TRUE)
                  results$has_approved_drug[i] <- any(mech_data$mechanisms$max_phase >= 4, na.rm = TRUE)
                  results$has_clinical_candidate[i] <- any(mech_data$mechanisms$max_phase >= 1, na.rm = TRUE)
                }
                
                # Get drug names if available
                if ("molecule_chembl_id" %in% colnames(mech_data$mechanisms)) {
                  drug_ids <- head(unique(mech_data$mechanisms$molecule_chembl_id), 3)
                  results$drug_names[i] <- paste(drug_ids, collapse = "; ")
                }
              }
            }
            
            # Step 3: Count bioactivities (even if no approved drug)
            activity_url <- paste0(
              "https://www.ebi.ac.uk/chembl/api/data/activity.json?target_chembl_id=",
              target_id,
              "&limit=1"
            )
            
            act_response <- httr::GET(
              activity_url,
              httr::timeout(10),
              httr::add_headers("Accept" = "application/json")
            )
            
            if (httr::status_code(act_response) == 200) {
              act_content <- httr::content(act_response, as = "text", encoding = "UTF-8")
              act_data <- jsonlite::fromJSON(act_content, flatten = TRUE)
              
              if (!is.null(act_data$page_meta) && !is.null(act_data$page_meta$total_count)) {
                results$n_bioactivities[i] <- act_data$page_meta$total_count
                
                # If has bioactivities, mark as potentially druggable
                if (act_data$page_meta$total_count > 0) {
                  results$is_druggable[i] <- TRUE
                }
              }
            }
          }
        }
      }
      
      # Small delay to be nice to the API
      Sys.sleep(0.3)
      
    }, error = function(e) {
      # Silent fail for individual genes, continue with others
      print(paste("   ⚠️ Could not check", gene, ":", e$message))
    })
  }
  
  # Summary
  n_druggable <- sum(results$is_druggable)
  n_approved <- sum(results$has_approved_drug)
  print(paste("✅ ChEMBL check complete:", n_druggable, "druggable,", n_approved, "with approved drugs"))
  
  return(results)
}

#' Fallback druggability check using curated list
#' Used when ChEMBL API is unavailable
check_druggability_fallback <- function(gene_symbols) {
  
  # This list is based on literature-curated druggable TFs
  # Source: Various reviews on druggable transcription factors
  # Note: This is a FALLBACK only - real ChEMBL data is preferred
  known_druggable_tfs <- c(
    # Nuclear receptors (well-established drug targets)
    "ESR1", "ESR2", "AR", "PPARG", "PPARA", "PPARD",
    "NR3C1", "NR3C2", "RARA", "RARB", "RARG", "RXRA", "RXRB", "RXRG",
    "VDR", "THRA", "THRB", "NR1H3", "NR1H2", "NR1I2", "NR1I3",
    "NR2F1", "NR2F2", "NR2F6", "HNF4A", "NR4A1", "NR4A2", "NR4A3",
    # STAT family
    "STAT1", "STAT2", "STAT3", "STAT4", "STAT5A", "STAT5B", "STAT6",
    # Other TFs with known modulators
    "HIF1A", "EPAS1", "NFE2L2", "TP53", "MYC", "MYCN",
    "NFKB1", "NFKB2", "RELA", "RELB", "REL",
    "CREB1", "ATF1", "ATF2", "ATF3", "ATF4",
    "JUN", "JUNB", "JUND", "FOS", "FOSB", "FOSL1", "FOSL2",
    "EGR1", "SP1", "SP3",
    # GATA factors
    "GATA1", "GATA2", "GATA3", "GATA4", "GATA5", "GATA6",
    # Other
    "MAFB", "MAFA", "MAFF", "MAFG", "MAFK"
  )
  
  results <- data.frame(
    gene = gene_symbols,
    is_druggable = gene_symbols %in% known_druggable_tfs,
    has_approved_drug = FALSE,  # Can't determine without API
    has_clinical_candidate = FALSE,
    n_bioactivities = NA_integer_,
    max_phase = NA_integer_,
    chembl_target_id = NA_character_,
    drug_names = NA_character_,
    source = "curated_list",
    stringsAsFactors = FALSE
  )
  
  print(paste("⚠️ Using fallback curated list -", sum(results$is_druggable), "TFs marked as potentially druggable"))
  
  return(results)
}

