# Advanced Master Regulator Scoring Function
calculate_advanced_master_score <- function(tf_data, tf_regulations, selected_genes) {
  
  if (is.null(tf_data) || nrow(tf_data) == 0) return(tf_data)
  
  tf_data <- tf_data %>%
    rowwise() %>%
    mutate(
      # 1. Base score from out-degree (how many genes it regulates)
      degree_score = degree_out / max(tf_data$degree_out, na.rm = TRUE),
      
      # 2. DEG coverage - what % of DEGs does this TF regulate?
      deg_coverage = if (!is.null(selected_genes$all_genes)) {
        targets_in_degs <- sum(tf_regulations$target[tf_regulations$tf == label] %in% selected_genes$all_genes)
        targets_in_degs / length(selected_genes$all_genes)
      } else { 0 },
      
      # 3. Confidence score - average confidence of this TF's regulations
      avg_confidence = if (label %in% tf_regulations$tf) {
        mean(tf_regulations$confidence[tf_regulations$tf == label], na.rm = TRUE)
      } else { 0 },
      
      # 4. Consistency score - does it mainly activate OR repress (not mixed)?
      regulation_consistency = if (label %in% tf_regulations$tf) {
        tf_regs <- tf_regulations[tf_regulations$tf == label, ]
        if (nrow(tf_regs) > 0 && "mor" %in% colnames(tf_regs)) {
          max(mean(tf_regs$mor == 1, na.rm = TRUE), mean(tf_regs$mor == -1, na.rm = TRUE))
        } else { 0.5 }
      } else { 0.5 },
      
      # 5. Combined Master Score (weighted)
      master_score = round(
        (degree_score * 0.35) +           # Regulatory influence
          (deg_coverage * 0.30) +            # DEG coverage importance
          (avg_confidence * 0.20) +          # Evidence quality
          (regulation_consistency * 0.15),   # Regulatory specificity
        3
      ) * 100  # Scale to 0-100
    ) %>%
    ungroup() %>%
    arrange(desc(master_score))
  
  return(tf_data)
}

# Generate Biological Interpretation Text
generate_biological_interpretation <- function(grn_results, tf_enrichment, target_enrichment) {
  
  interpretation <- list()
  
  # 1. Top TF Interpretation
  if (!is.null(grn_results$master_regulators) && nrow(grn_results$master_regulators) > 0) {
    top_tf <- grn_results$master_regulators$label[1]
    top_tf_targets <- sum(grn_results$tf_regulations$tf == top_tf)
    
    interpretation$top_tf_summary <- paste0(
      "**", top_tf, "** emerges as the most influential transcription factor, ",
      "directly regulating ", top_tf_targets, " genes in your dataset."
    )
  }
  
  # 2. TF Enrichment Interpretation
  if (!is.null(tf_enrichment) && nrow(tf_enrichment) > 0) {
    sig_tf_pathways <- tf_enrichment %>% 
      filter(Adjusted.P.value < 0.05) %>%
      arrange(Adjusted.P.value) %>%
      head(3)
    
    if (nrow(sig_tf_pathways) > 0) {
      top_processes <- paste(sig_tf_pathways$Term[1:min(3, nrow(sig_tf_pathways))], collapse = ", ")
      interpretation$tf_enrichment_summary <- paste0(
        "Your master regulators are significantly enriched in: **", top_processes, "**. ",
        "This suggests these TFs are known players in these biological processes."
      )
    }
  }
  
  # 3. Target Enrichment Interpretation
  if (!is.null(target_enrichment) && nrow(target_enrichment) > 0) {
    sig_target_pathways <- target_enrichment %>% 
      filter(Adjusted.P.value < 0.05) %>%
      arrange(Adjusted.P.value) %>%
      head(3)
    
    if (nrow(sig_target_pathways) > 0) {
      top_target_processes <- paste(sig_target_pathways$Term[1:min(3, nrow(sig_target_pathways))], collapse = ", ")
      interpretation$target_enrichment_summary <- paste0(
        "The genes controlled by these TFs are enriched in: **", top_target_processes, "**. ",
        "This reveals the downstream biological effects of the regulatory network."
      )
    }
  }
  
  # 4. Combined Story
  if (!is.null(interpretation$tf_enrichment_summary) && !is.null(interpretation$target_enrichment_summary)) {
    interpretation$combined_story <- paste0(
      "**Regulatory Story:** Your transcription factors, known for their roles in specific processes, ",
      "are actively controlling genes involved in related downstream pathways. This coherent regulatory ",
      "cascade suggests a coordinated biological response in your experimental condition."
    )
  }
  
  return(interpretation)
}

# Detect Feed-Forward Loops
detect_regulatory_motifs <- function(tf_regulations, master_regulators) {
  
  motifs <- list(
    feed_forward_loops = data.frame(),
    tf_tf_interactions = data.frame(),
    hub_tfs = data.frame()
  )
  
  if (is.null(tf_regulations) || nrow(tf_regulations) == 0) return(motifs)
  
  # Get all TFs
  all_tfs <- unique(tf_regulations$tf)
  
  # 1. Find TF-TF interactions (TFs that regulate other TFs)
  tf_tf <- tf_regulations %>%
    filter(target %in% all_tfs) %>%
    select(regulator_tf = tf, target_tf = target, confidence, mor) %>%
    mutate(
      regulation_type = ifelse(mor == 1, "Activates", "Represses")
    )
  
  if (nrow(tf_tf) > 0) {
    motifs$tf_tf_interactions <- tf_tf
  }
  
  # 2. Find Feed-Forward Loops (TF1 -> TF2 -> Gene AND TF1 -> Gene)
  if (nrow(tf_tf) > 0) {
    ffl_list <- list()
    
    for (i in 1:nrow(tf_tf)) {
      tf1 <- tf_tf$regulator_tf[i]
      tf2 <- tf_tf$target_tf[i]
      
      # Get targets of TF1
      tf1_targets <- tf_regulations$target[tf_regulations$tf == tf1]
      # Get targets of TF2
      tf2_targets <- tf_regulations$target[tf_regulations$tf == tf2]
      
      # Find common targets (excluding TF2 itself)
      common_targets <- intersect(tf1_targets, tf2_targets)
      common_targets <- common_targets[!common_targets %in% all_tfs]
      
      if (length(common_targets) > 0) {
        ffl_list[[length(ffl_list) + 1]] <- data.frame(
          TF1 = tf1,
          TF2 = tf2,
          common_targets = length(common_targets),
          example_target = common_targets[1]
        )
      }
    }
    
    if (length(ffl_list) > 0) {
      motifs$feed_forward_loops <- bind_rows(ffl_list)
    }
  }
  
  # 3. Identify Hub TFs (high connectivity)
  tf_connectivity <- tf_regulations %>%
    group_by(tf) %>%
    summarise(
      n_targets = n_distinct(target),
      avg_confidence = mean(confidence, na.rm = TRUE),
      .groups = 'drop'
    ) %>%
    arrange(desc(n_targets)) %>%
    head(10)
  
  motifs$hub_tfs <- tf_connectivity
  
  return(motifs)
}

# Generate Key Findings Summary
generate_key_findings <- function(grn_results, motifs) {
  
  findings <- list()
  
  # Finding 1: Network Overview
  if (!is.null(grn_results$analysis_params)) {
    findings$network_overview <- list(
      title = "Network Scale",
      value = paste0(grn_results$analysis_params$n_tfs, " TFs → ", 
                     grn_results$analysis_params$n_regulations, " interactions"),
      interpretation = "regulatory relationships identified in your data"
    )
  }
  
  # Finding 2: Top Regulator
  if (!is.null(grn_results$master_regulators) && nrow(grn_results$master_regulators) > 0) {
    top_tf <- grn_results$master_regulators[1, ]
    findings$top_regulator <- list(
      title = "Top Master Regulator",
      value = top_tf$label,
      interpretation = paste0("Controls ", top_tf$degree_out, " target genes")
    )
  }
  
  # Finding 3: TF-TF Cascade
  if (!is.null(motifs$tf_tf_interactions) && nrow(motifs$tf_tf_interactions) > 0) {
    findings$tf_cascade <- list(
      title = "TF Cascade Depth",
      value = paste0(nrow(motifs$tf_tf_interactions), " TF-TF interactions"),
      interpretation = "suggesting hierarchical regulation"
    )
  }
  
  # Finding 4: Feed-Forward Loops
  if (!is.null(motifs$feed_forward_loops) && nrow(motifs$feed_forward_loops) > 0) {
    findings$regulatory_motifs <- list(
      title = "Feed-Forward Loops",
      value = nrow(motifs$feed_forward_loops),
      interpretation = "coherent regulatory circuits detected"
    )
  }
  
  return(findings)
}


