             "GWAS_Catalog_2023",
             "ClinVar_2019",
             # Tissue & Cell Type
             "Human_Gene_Atlas",
             "ARCHS4_Tissues",
             # Transcription Factors
             "ENCODE_TF_ChIP-seq_2015",
             "ChEA_2022"
           ),
           "mouse" = c(
             "GO_Biological_Process_2023", 
             "GO_Molecular_Function_2023",
             "GO_Cellular_Component_2023",
             "KEGG_2019_Mouse", 
             "WikiPathways_2019_Mouse",
             "Mouse_Gene_Atlas",
             "ARCHS4_Tissues"
           ),
           "rat" = c(
             "GO_Biological_Process_2023", 
             "GO_Molecular_Function_2023",
             "GO_Cellular_Component_2023",
             "KEGG_2021_Rat"
           ),
           "fly" = c(
             "GO_Biological_Process_2023", 
             "GO_Molecular_Function_2023",
             "KEGG_2019_Fly",
             "FlyBase_Gene_Summaries"
           ),
           "zebrafish" = c(
             "GO_Biological_Process_2023", 
             "GO_Molecular_Function_2023",
             "GO_Cellular_Component_2023"
           ),
           "celegans" = c(
             "GO_Biological_Process_2023", 
             "GO_Molecular_Function_2023",
             "WormBase_Gene_Summaries"
           ),
           "yeast" = c(
             "GO_Biological_Process_2023", 
             "GO_Molecular_Function_2023",
             "KEGG_2019_Yeast",
             "SGD_Gene_Summaries"
           ),
           "arabidopsis" = c(
             "GO_Biological_Process_2023", 
             "GO_Molecular_Function_2023",
             "TAIR_Gene_Summaries"
           ),
           "chicken" = c(
             "GO_Biological_Process_2023", 
             "GO_Molecular_Function_2023"
           ),
           "pig" = c(
             "GO_Biological_Process_2023", 
             "GO_Molecular_Function_2023"
           ),
           # Default fallback
           c("GO_Biological_Process_2023", "GO_Molecular_Function_2023")
    )
  }
  
  # Get available databases for organism
  available_dbs <- get_enrichr_databases(organism)
  print(paste("🔍 Available databases for", organism, ":", paste(available_dbs, collapse = ", ")))
  
  print("🔍 DEBUG: Starting enrichment loop")
  print(paste("🔍 DEBUG: Total modules to process:", length(names(modules))))
  print(paste("🔍 DEBUG: Module names:", paste(names(modules), collapse = ", ")))
  
  # Initialize result storage
  all_enrichment_results <- list()
  modules_processed <- 0
  modules_with_results <- 0
  
  # Process each module
  for (module_name in names(modules)) {
    # print(paste("🔍 DEBUG: Starting iteration for module:", module_name))
    modules_processed <- modules_processed + 1
    # print(paste("🔍 DEBUG: Modules processed counter:", modules_processed))
    
    if (length(modules[[module_name]]) < 3) {
      # print(paste("⚠️ Module", module_name, "has too few genes (<3). Skipping enrichment."))
      # print(paste("🔍 DEBUG: Skipping module", module_name, "- continuing to next iteration"))
      next
    }
    
    module_genes <- modules[[module_name]]
    print(paste("🔬 Processing module:", module_name, "with", length(module_genes), "genes"))
    
    # Convert gene IDs to symbols using multi-strategy approach
    print(paste("🔍 DEBUG: About to call convert_genes_multi_strategy for module:", module_name))
    
    converted_genes <- tryCatch({
      convert_genes_multi_strategy(module_genes, organism)
    }, error = function(e) {
      print(paste("🔍 DEBUG: Error in convert_genes_multi_strategy for module", module_name, ":", e$message))
      return(character(0))
    })
    
    print(paste("🔍 DEBUG: Conversion completed for module:", module_name, "- got", length(converted_genes), "genes"))
    
    if (length(converted_genes) < 3) {
      print(paste("⚠️ Module", module_name, "has too few converted genes (<3). Skipping."))
      print(paste("🔍 DEBUG: Skipping module", module_name, "due to low gene count - continuing to next iteration"))
      next
    }
    
    print(paste("✅ Converted", length(module_genes), "→", length(converted_genes), "genes"))
    print(paste("✅ Converted", length(converted_genes), "genes for enrichment"))
    
    # Perform enrichment analysis
    print(paste("🔍 DEBUG: About to start enrichment analysis for module:", module_name))
    
    module_enrichment <- tryCatch({
      
      print(paste("🔍 DEBUG: Calling enrichR::enrichr for module:", module_name))
      
      # Run enrichR analysis
      enrichr_results <- tx_enrichr_local(converted_genes, available_dbs)
      
      
      # Combine results from all databases
      combined_results <- data.frame()
      
      for (db_name in names(enrichr_results)) {
        print(paste("🔍 DEBUG: Processing database", db_name, "for module", module_name))
        
        db_results <- enrichr_results[[db_name]]
        if (!is.null(db_results) && nrow(db_results) > 0) {
          significant_results <- db_results[db_results$Adjusted.P.value < 0.05, ]
          if (nrow(significant_results) > 0) {
            significant_results$Database <- db_name
            significant_results$Module <- module_name
            significant_results <- significant_results[order(significant_results$Adjusted.P.value), ]
            significant_results <- head(significant_results, 20)
            combined_results <- rbind(combined_results, significant_results)
          }
        }
      }
      
      # Let the value of the block be the result
      if (nrow(combined_results) > 0) {
        combined_results <- combined_results[order(combined_results$Adjusted.P.value), ]
        print(paste("✅ Found", nrow(combined_results), "significant pathways for module", module_name))
        combined_results # This value is returned by tryCatch on success
      } else {
        print(paste("⚠️ No significant pathways found for module", module_name))
        NULL # This value is returned by tryCatch if no results
      }
      
    }, error = function(e) {
      print(paste("❌ Enrichment failed for module", module_name, ":", e$message))
      print(paste("🔍 DEBUG: Full error details for module", module_name, ":"))
      print(e)
      NULL # This value is returned by tryCatch on error
    })
    
    print(paste("🔍 DEBUG: Enrichment analysis completed for module:", module_name))
    print(paste("🔍 DEBUG: Module enrichment result is:", if(is.null(module_enrichment)) "NULL" else paste("data.frame with", nrow(module_enrichment), "rows")))
    
    # Store results if successful
    if (!is.null(module_enrichment) && nrow(module_enrichment) > 0) {
      all_enrichment_results[[module_name]] <- module_enrichment
      modules_with_results <- modules_with_results + 1
      print(paste("🔍 DEBUG: Successfully stored results for module:", module_name))
    } else {
      print(paste("🔍 DEBUG: No results to store for module:", module_name))
    }
    
    print(paste("🔍 DEBUG: Completed processing for module:", module_name, "- moving to next iteration"))
    print("🔍 DEBUG: ================================================")
  }
  
  print(paste("🔍 DEBUG: Loop completed. Final summary:"))
  print(paste("🔍 DEBUG: Modules processed:", modules_processed))
  print(paste("🔍 DEBUG: Modules with results:", modules_with_results))
  print(paste("🔍 DEBUG: Total enriched modules:", length(all_enrichment_results)))
  print(paste("🔍 DEBUG: Enriched module names:", paste(names(all_enrichment_results), collapse = ", ")))
  
  # Summary
  print(paste("🎯 Enrichment Summary:"))
  print(paste("  📊 Modules processed:", modules_processed, "/", length(modules)))
  print(paste("  📊 Modules with results:", modules_with_results))
  print(paste("  🛤️ Total enriched modules:", length(all_enrichment_results)))
  
  if (length(all_enrichment_results) == 0) {
    print("⚠️ No modules had significant enrichment results. This could be due to:")
    print("  1. Gene ID conversion issues")
    print("  2. Very stringent p-value threshold (p.adj < 0.05)")
    print("  3. Small module sizes")
    print("  4. Limited pathway databases for this organism")
    print("  5. Network connectivity issues with enrichR")
  }
  
  return(all_enrichment_results)
}

convert_genes_multi_strategy <- function(gene_ids, organism) {
  
  print("🔄 Converting genes using multi-strategy approach...")
  
  # Use the existing robust conversion function that works
  conversion_result <- convert_gene_ids_to_symbols_deg(gene_ids, organism)
  
  # Extract successfully converted symbols
  converted_genes <- conversion_result$gene_symbol[
    conversion_result$gene_symbol != "-" & 
      !is.na(conversion_result$gene_symbol) &
      conversion_result$conversion_status != "no_conversion"
  ]
  
  # Remove duplicates and empty strings
  converted_genes <- unique(converted_genes[converted_genes != ""])
  
  print(paste("✅ Multi-strategy conversion: converted", length(gene_ids), "→", length(converted_genes), "genes"))
  
  return(converted_genes)
}

