# Perform functional enrichment for each module
perform_module_enrichment_fixed <- function(modules, selected_genes, hub_genes) {
  
  print("🧪 Enhanced functional enrichment analysis...")
  
  # Check if enrichR is available
  if (!requireNamespace("enrichR", quietly = TRUE)) {
    print("⚠️ enrichR package not available. Installing...")
    tryCatch({
      install.packages("enrichR")
      library(enrichR)
    }, error = function(e) {
      print("❌ Failed to install enrichR. Skipping enrichment analysis.")
      return(NULL)
    })
  }
  
  # Load required libraries
  library(enrichR)
  
  # Check if org.Hs.eg.db is available
  if (!requireNamespace("org.Hs.eg.db", quietly = TRUE)) {
    print("⚠️ org.Hs.eg.db package not available. Installing...")
    tryCatch({
      if (!requireNamespace("BiocManager", quietly = TRUE)) {
        install.packages("BiocManager")
      }
      BiocManager::install("org.Hs.eg.db", update = FALSE, ask = FALSE)
      library(org.Hs.eg.db)
    }, error = function(e) {
      print("❌ Failed to install org.Hs.eg.db. Skipping enrichment analysis.")
      return(NULL)
    })
  } else {
    library(org.Hs.eg.db)  # For human gene annotation
  }
  
  # Check if AnnotationDbi is available
  if (!requireNamespace("AnnotationDbi", quietly = TRUE)) {
    print("⚠️ AnnotationDbi package not available. Installing...")
    tryCatch({
      if (!requireNamespace("BiocManager", quietly = TRUE)) {
        install.packages("BiocManager")
      }
      BiocManager::install("AnnotationDbi", update = FALSE, ask = FALSE)
      library(AnnotationDbi)
    }, error = function(e) {
      print("❌ Failed to install AnnotationDbi. Skipping enrichment analysis.")
      return(NULL)
    })
  } else {
    library(AnnotationDbi)
  }
  
  # Get available databases
  tryCatch({
    enrichR::listEnrichrDbs()
    print("✅ enrichR connection successful")
  }, error = function(e) {
    print("❌ enrichR connection failed. Check internet connection.")
    return(NULL)
  })
  
  # Enhanced database selection for better results
  databases <- c(
    "GO_Biological_Process_2023",
    "GO_Molecular_Function_2023",
    "KEGG_2021_Human",
    "Reactome_2022",
    "WikiPathways_2019_Human",
    "MSigDB_Hallmark_2020"
  )
  
  enrichment_results <- list()
  total_enriched_modules <- 0
  
  for (module_name in names(modules)) {
    module_genes <- modules[[module_name]]
    
    print(paste("🔬 Processing module", module_name, "with", length(module_genes), "genes"))
    
    # Skip very small modules
    if (length(module_genes) < 3) {
      print(paste("⚠️ Skipping module", module_name, "- too few genes (<3)"))
      next
    }
    
    # FIXED: Convert ENSEMBL IDs to gene symbols (REMOVED the missing function call)
    tryCatch({
      # Clean gene IDs (remove version numbers and suffixes)
      clean_genes <- sub("_.*$", "", module_genes)  # Remove suffixes like "_red vs green"
      clean_genes <- sub("\\..*$", "", clean_genes)  # Remove version numbers like ".1"
      
      # Convert ENSEMBL to SYMBOL using AnnotationDbi
      gene_symbols <- AnnotationDbi::mapIds(
        org.Hs.eg.db,
        keys = clean_genes,
        column = "SYMBOL",
        keytype = "ENSEMBL",
        multiVals = "first"
      )
      
      # Get valid symbols (remove NAs)
      valid_symbols <- gene_symbols[!is.na(gene_symbols)]
      valid_symbols <- unique(valid_symbols)
      
      print(paste("  📝 Converted", length(clean_genes), "ENSEMBL IDs to", length(valid_symbols), "gene symbols"))
      
      # Need at least 3 valid symbols for enrichment
      if (length(valid_symbols) < 3) {
        print(paste("  ⚠️ Too few valid symbols for enrichment:", length(valid_symbols)))
        next
      }
      
      # Perform enrichment with valid symbols
      print(paste("  🔍 Running enrichment with", length(valid_symbols), "symbols..."))
      
      module_enrichment <- tx_enrichr_local(valid_symbols, databases)
      
      # Process results
      combined_results <- data.frame()
      
      for (db in names(module_enrichment)) {
        db_results <- module_enrichment[[db]]
        
        if (nrow(db_results) > 0) {
          # Filter for significant results - FIXED: Removed dplyr dependency
          significant_results <- db_results[db_results$Adjusted.P.value < 0.05, ]
          
          if (nrow(significant_results) > 0) {
            # Add metadata
            significant_results$database <- db
            significant_results$module <- module_name
            significant_results$gene_count <- length(valid_symbols)
            
            # Sort by p-value and take top 10
            significant_results <- significant_results[order(significant_results$Adjusted.P.value), ]
            significant_results <- head(significant_results, 10)  # Top 10 per database
            
            combined_results <- rbind(combined_results, significant_results)
          }
        }
      }
      
      # Store results if any significant pathways found
      if (nrow(combined_results) > 0) {
        enrichment_results[[module_name]] <- combined_results
        total_enriched_modules <- total_enriched_modules + 1
        print(paste("  ✅ Found", nrow(combined_results), "significant pathways"))
      } else {
        print(paste("  ❌ No significant pathways found (p.adj < 0.05)"))
      }
      
    }, error = function(e) {
      print(paste("  ❌ Enrichment failed for module", module_name, ":", e$message))
    })
  }
  
  print(paste("✅ Enrichment completed for", total_enriched_modules, "modules"))
  
  if (total_enriched_modules == 0) {
    print("⚠️ No modules had significant enrichment results. Possible causes:")
    print("  1. Gene IDs couldn't be converted to symbols")
    print("  2. Modules are too small")
    print("  3. No significant pathways at p.adj < 0.05")
    print("  4. Internet connection issues with enrichR")
  }
  
  return(enrichment_results)
}

# Create network visualization for WGCNA results
# FIX FOR WGCNA NETWORK VISUALIZATION ERROR
# "numbers of columns of arguments do not match"

# The error occurs when rbind() tries to combine data frames with different column structures
# Let's create a safer version that handles column mismatches

create_wgcna_network_viz_safe_fixed <- function(modules, hub_genes, module_colors,
                                                selected_genes, module_enrichment = NULL) {
  
  print("Creating bulletproof WGCNA network visualization...")
  
  # Input validation to prevent subscript errors
  if (is.null(modules) || length(modules) == 0) {
    return(create_fallback_network())
  }
  
  if (is.null(hub_genes) || nrow(hub_genes) == 0) {
    return(create_fallback_network())
  }
  
  tryCatch({
    # Safely extract module information
    module_names <- names(modules)
    if (is.null(module_names) || length(module_names) == 0) {
      return(create_fallback_network())
    }
    
    # Create nodes data frame with consistent structure
    all_nodes <- data.frame(
      id = character(0),
      label = character(0),
      group = character(0),
      size = numeric(0),
      color = character(0),
      title = character(0),
      stringsAsFactors = FALSE
    )
    
    # Add module nodes
    for (i in seq_along(module_names)) {
      module_name <- module_names[i]
      
      # Safely get module size
      module_size <- length(modules[[module_name]])
      if (is.null(module_size) || module_size == 0) next
      
      # Get enrichment info if available
      enrichment_info <- ""
      if (!is.null(module_enrichment) && module_name %in% names(module_enrichment)) {
        top_pathways <- head(module_enrichment[[module_name]]$Term, 3)
        if (length(top_pathways) > 0) {
          enrichment_info <- paste("Top pathways:", paste(top_pathways, collapse = "; "))
        }
      }
      
      # Create module node
      module_node <- data.frame(
        id = paste0("module_", module_name),
        label = paste0(module_name, "\n(", module_size, " genes)"),
        group = "module",
        size = pmax(20, pmin(60, module_size / 5)),  # Size based on module size
        color = get_wgcna_color(module_name),
        title = paste0("Module: ", module_name, "<br>",
                       "Size: ", module_size, " genes<br>",
                       enrichment_info),
        stringsAsFactors = FALSE
      )
      
      all_nodes <- rbind(all_nodes, module_node)
    }
    
    # Add hub gene nodes (top 20 to avoid overcrowding)
    if (nrow(hub_genes) > 0) {
      top_hubs <- head(hub_genes[order(hub_genes$global_hub_rank), ], 20)
      
      for (i in seq_len(nrow(top_hubs))) {
        hub_info <- top_hubs[i, ]
        
        hub_node <- data.frame(
          id = paste0("hub_", hub_info$gene),
          label = as.character(hub_info$gene),
          group = "hub",
          size = 15,
          color = "#FF6B6B",
          title = paste0("Hub Gene: ", hub_info$gene, "<br>",
                         "Module: ", hub_info$module, "<br>",
                         "Connectivity: ", round(hub_info$connectivity, 2), "<br>",
                         "Hub Score: ", round(hub_info$hub_score, 2)),
          stringsAsFactors = FALSE
        )
        
        all_nodes <- rbind(all_nodes, hub_node)
      }
    }
    
    # Create edges between modules and their hub genes
    all_edges <- data.frame(
      from = character(0),
      to = character(0),
      color = character(0),
      width = numeric(0),
      stringsAsFactors = FALSE
    )
    
    if (nrow(hub_genes) > 0) {
      top_hubs <- head(hub_genes[order(hub_genes$global_hub_rank), ], 20)
      
      for (i in seq_len(nrow(top_hubs))) {
        hub_info <- top_hubs[i, ]
        
        edge <- data.frame(
          from = paste0("module_", hub_info$module),
          to = paste0("hub_", hub_info$gene),
          color = "#CCCCCC",
          width = 2,
          stringsAsFactors = FALSE
        )
        
        all_edges <- rbind(all_edges, edge)
      }
    }
    
    return(list(
      nodes = all_nodes,
      edges = all_edges,
      legend = create_network_legend()
    ))
    
  }, error = function(e) {
    print(paste("Network visualization error:", e$message))
    return(create_fallback_network())
  })
}

get_wgcna_color <- function(module_name) {
  color_map <- c(
    "turquoise" = "#40E0D0", "blue" = "#0000FF", "brown" = "#A52A2A",
    "yellow" = "#FFFF00", "green" = "#008000", "red" = "#FF0000",
    "black" = "#000000", "pink" = "#FFC0CB", "magenta" = "#FF00FF",
    "purple" = "#800080", "greenyellow" = "#ADFF2F", "tan" = "#D2B48C",
    "salmon" = "#FA8072", "cyan" = "#00FFFF", "lightcyan" = "#E0FFFF",
    "grey60" = "#999999", "orange" = "#FFA500", "darkorange" = "#FF8C00",
    "darkred" = "#8B0000", "darkgreen" = "#006400", "royalblue" = "#4169E1",
    "skyblue" = "#87CEEB", "white" = "#F5F5F5", "paleturquoise" = "#AFEEEE"
  )
  
  return(color_map[module_name] %||% "#CCCCCC")
}

create_fallback_network <- function() {
  list(
    nodes = data.frame(
      id = "analysis_complete",
      label = "WGCNA Analysis\nCompleted Successfully",
      group = "info",
      size = 30,
      color = "#28a745",
      title = "Click 'Module Analysis' tab for detailed results",
      stringsAsFactors = FALSE
    ),
    edges = data.frame(),
    legend = list()
  )
}

create_network_legend <- function() {
  list(
    list(label = "Modules", color = "#40E0D0", shape = "dot"),
    list(label = "Hub Genes", color = "#FF6B6B", shape = "dot")
  )
}

#ENHANCED WGCNA FEATURES: SCIENTIFIC MODULE INTERPRETATION
# Enhanced Module-Trait Correlation Analysis
perform_enhanced_module_trait_analysis <- function(expression_data, module_colors, clinical_data = NULL) {
  
  print("Performing enhanced module-trait correlation analysis...")
  
  # Calculate module eigengenes
  MEs <- WGCNA::moduleEigengenes(expression_data, module_colors)$eigengenes
  
  # If clinical data is available, correlate with traits
  if (!is.null(clinical_data)) {
    # Ensure sample names match
    common_samples <- intersect(rownames(MEs), rownames(clinical_data))
    
    if (length(common_samples) > 3) {
      MEs_subset <- MEs[common_samples, ]
      traits_subset <- clinical_data[common_samples, ]
      
      # Calculate correlations
      module_trait_cor <- cor(MEs_subset, traits_subset, use = "pairwise.complete.obs")
      module_trait_pval <- corPvalueStudent(module_trait_cor, nSamples = length(common_samples))
      
      return(list(
        correlations = module_trait_cor,
        p_values = module_trait_pval,
        module_eigengenes = MEs
      ))
    }
  }
  
  # If no clinical data, analyze module relationships
  module_cor <- cor(MEs, use = "pairwise.complete.obs")
  
  return(list(
    module_correlations = module_cor,
    module_eigengenes = MEs,
    message = "No clinical traits provided - showing module-module correlations"
  ))
}

# Generate Module Functional Summary
generate_module_functional_summary <- function(modules, module_enrichment, hub_genes) {
  
  print("Generating functional summary for each module...")
  
  module_summaries <- list()
  
  for (module_name in names(modules)) {
    module_genes <- modules[[module_name]]
    module_hubs <- hub_genes[hub_genes$module == module_name, ]
    
    # Get enrichment summary
    if (!is.null(module_enrichment) && module_name %in% names(module_enrichment)) {
      enrichment_data <- module_enrichment[[module_name]]
      
      if (nrow(enrichment_data) > 0) {
        # Categorize pathways
        biological_processes <- enrichment_data[grepl("GO.*Biological", enrichment_data$database), ]
        molecular_functions <- enrichment_data[grepl("GO.*Molecular", enrichment_data$database), ]
        kegg_pathways <- enrichment_data[grepl("KEGG", enrichment_data$database), ]
        
        # Generate summary
        functional_summary <- list(
          module = module_name,
          size = length(module_genes),
          hub_count = nrow(module_hubs),
          
          # Top functions
          primary_function = if(nrow(biological_processes) > 0) biological_processes$Term[1] else "Unknown",
          key_pathway = if(nrow(kegg_pathways) > 0) kegg_pathways$Term[1] else "No KEGG pathway",
          molecular_role = if(nrow(molecular_functions) > 0) molecular_functions$Term[1] else "Unknown function",
          
          # Top hub genes
          top_hubs = if(nrow(module_hubs) > 0) head(module_hubs$gene, 3) else character(0),
          
          # Pathway categories
          pathway_categories = categorize_pathways(enrichment_data$Term),
          
          # Biological interpretation
          interpretation = generate_module_interpretation(module_name, enrichment_data, module_hubs)
        )
        
        module_summaries[[module_name]] <- functional_summary
      }
    } else {
      # No enrichment data available
      module_summaries[[module_name]] <- list(
        module = module_name,
        size = length(module_genes),
        hub_count = nrow(module_hubs),
        primary_function = "No enrichment data",
        interpretation = paste("Module", module_name, "contains", length(module_genes), 
                               "co-expressed genes but lacks functional annotation.")
      )
    }
  }
  
  return(module_summaries)
}

# Categorize pathways into biological themes
categorize_pathways <- function(pathway_terms) {
  
  # FINAL MERGED LIST: A comprehensive and organized set of biological themes and keywords
  categories <- list(
    "Metabolism" = c("metabolism", "metabolic", "synthesis", "biosynthesis", "degradation", "catabolism", "oxidation", "reduction", "glycolysis", "gluconeogenesis", "citric acid", "TCA cycle", "pentose phosphate", "fatty acid", "lipid", "cholesterol", "steroid", "bile acid", "amino acid", "nucleotide", "purine", "pyrimidine", "carbohydrate", "energy", "respiration", "oxidative phosphorylation", "fermentation", "xenobiotic", "drug metabolism"),
    
    "Immune & Inflammatory Response" = c("immune", "immunity", "inflammatory", "inflammation", "cytokine", "chemokine", "interleukin", "interferon", "TNF", "antigen", "antibody", "complement system", "T cell", "B cell", "leukocyte", "lymphocyte", "neutrophil", "macrophage", "dendritic", "NK cell", "MHC", "toll-like", "TLR", "innate", "adaptive", "autoimmune", "allergy", "hypersensitivity", "NF-kappa B", "NFkB", "JAK-STAT"),
    
    "Signaling Pathways" = c("signaling", "signal transduction", "cascade", "receptor", "ligand", "kinase", "phosphatase", "G protein", "second messenger", "MAPK", "ERK", "JNK", "p38", "PI3K-Akt", "mTOR", "Ras", "Rap1", "Rho GTPase", "Wnt", "Hedgehog", "Hippo", "Notch", "TGF-beta", "SMAD", "BMP", "FGF", "EGF", "calcium signaling", "cAMP", "cGMP"),
    
    "Cell Cycle & Proliferation" = c("cell cycle", "mitosis", "meiosis", "division", "proliferation", "checkpoint", "cyclin", "CDK", "G1", "G2", "S phase", "M phase", "anaphase", "metaphase", "prophase", "telophase", "cytokinesis"),
    
    "DNA, RNA & Protein Homeostasis" = c("transcription", "RNA polymerase", "transcription factor", "gene expression", "gene regulation", "splicing", "spliceosome", "mRNA", "translation", "protein synthesis", "ribosome", "DNA replication", "DNA repair", "recombination", "homologous", "mismatch repair", "base excision", "nucleotide excision", "DNA damage", "telomere", "protein folding", "post-translational modification", "glycosylation", "phosphorylation", "ubiquitination", "proteasome", "chaperone"),
    
    "Cell Death & Senescence" = c("apoptosis", "apoptotic", "cell death", "necrosis", "necroptosis", "autophagy", "pyroptosis", "ferroptosis", "anoikis", "caspase", "Bcl-2", "p53", "cellular senescence"),
    
    "Development & Differentiation" = c("development", "differentiation", "morphogenesis", "organogenesis", "embryogenesis", "gastrulation", "neurulation", "stem cell", "cell fate", "patterning", "axis formation", "regeneration"),
    
    "Cellular Structure & Adhesion" = c("cytoskeleton", "actin", "microtubule", "intermediate filament", "cell adhesion", "focal adhesion", "adherens junction", "tight junction", "gap junction", "extracellular matrix", "ECM", "collagen", "integrin", "cadherin"),
    
    "Transport & Trafficking" = c("transport", "trafficking", "vesicular", "endocytosis", "exocytosis", "phagocytosis", "import", "export", "localization", "ion channel", "pump", "ABC transporters", "SLC carriers", "nuclear transport"),
    
    "Response to Stress" = c("stress", "response to", "stimulus", "heat shock", "HSP", "oxidative stress", "hypoxia", "HIF-1", "unfolded protein response", "UPR", "ER stress", "osmotic", "nutrient deprivation", "starvation"),
    
    "Cancer / Oncogenesis" = c("cancer", "oncogene", "tumor suppressor", "carcinogenesis", "metastasis", "tumor microenvironment", "hallmarks of cancer", "prostate cancer", "breast cancer", "lung cancer", "leukemia", "glioma"),
    
    "Nervous System" = c("neuronal", "neurogenesis", "synapse", "synaptic", "neurotransmission", "axon", "dendritic", "myelination", "neurodegenerative", "Alzheimer", "Parkinson", "Huntington", "glutamate", "GABA"),
    
    "Organismal Systems" = c("muscle contraction", "sarcomere", "cardiac", "hemostasis", "coagulation", "angiogenesis", "vascular", "VEGF", "circadian rhythm", "clock", "hormone", "endocrine", "estrogen", "androgen", "digestion", "secretion"),
    
    "Pathogen & Viral Response" = c("viral", "virus", "bacterial", "pathogen", "infection", "antiviral", "host-pathogen", "RIG-I", "STING", "interferon response", "COVID", "HIV", "influenza"),
    
    "Epigenetics & Chromatin" = c("epigenetic", "chromatin", "histone", "methylation", "acetylation", "DNA methylation", "remodeling", "HDAC", "HAT", "DNMT", "enhancer", "promoter"),
    
    # --- Organism-Specific Categories ---
    "Plant-Specific" = c("plant", "photosynthesis", "chloroplast", "stomata", "phytohormone", "auxin", "gibberellin", "abscisic acid", "ethylene", "root", "shoot", "flowering", "seed germination"),
    "Yeast-Specific" = c("budding", "mating", "sporulation", "cell wall", "fungal", "yeast", "Saccharomyces")
  )
  
  pathway_categories <- character(0)
  
  for (category in names(categories)) {
    keywords <- categories[[category]]
    
    matches <- sapply(keywords, function(keyword) {
      any(grepl(keyword, pathway_terms, ignore.case = TRUE))
    })
    
    if (any(matches)) {
      pathway_categories <- c(pathway_categories, category)
    }
  }
  
  return(if(length(pathway_categories) > 0) unique(pathway_categories) else "Uncategorized")
}

# Generate biological interpretation for each module
generate_module_interpretation <- function(module_name, enrichment_data, hub_genes) {
  
  if (nrow(enrichment_data) == 0) {
    return(paste("Module", module_name, "shows co-expression but lacks functional annotation."))
  }
  
  # Identify main biological theme
  top_pathways <- head(enrichment_data$Term, 3)
  pathway_categories <- categorize_pathways(top_pathways)
  
  # Generate interpretation based on categories
  if ("Immune Response" %in% pathway_categories) {
    interpretation <- paste("Module", module_name, "appears to represent an immune-related gene network, potentially involved in", tolower(top_pathways[1]))
  } else if ("Metabolism" %in% pathway_categories) {
    interpretation <- paste("Module", module_name, "represents a metabolic gene network, likely coordinating", tolower(top_pathways[1]))
  } else if ("Cell Cycle" %in% pathway_categories) {
    interpretation <- paste("Module", module_name, "contains cell cycle-related genes, suggesting involvement in", tolower(top_pathways[1]))
  } else if ("Development" %in% pathway_categories) {
    interpretation <- paste("Module", module_name, "appears to regulate developmental processes, particularly", tolower(top_pathways[1]))
  } else {
    interpretation <- paste("Module", module_name, "represents a co-expressed gene network involved in", tolower(top_pathways[1]))
  }
  
  # Add hub gene information
  if (nrow(hub_genes) > 0) {
    key_hubs <- paste(head(hub_genes$gene, 2), collapse = " and ")
    interpretation <- paste(interpretation, ". Key regulatory genes include", key_hubs)
  }
  
  return(interpretation)
}

#Using quantitative evidence (pathway significance, gene counts) 
# to determine module categories with confidence scores
analyze_module_categories_with_confidence <- function(modules, module_enrichment, hub_genes) {
  
  print("🔬 Performing evidence-based module category analysis...")
  
  module_analyses <- list()
  
  for (module_name in names(modules)) {
    module_genes <- modules[[module_name]]
    module_hubs <- hub_genes[hub_genes$module == module_name, ]
    
    # Initialize default analysis
    module_analysis <- list(
      module = module_name,
      size = length(module_genes),
      hub_count = nrow(module_hubs),
      top_hubs = if(nrow(module_hubs) > 0) head(module_hubs$gene, 3) else character(0),
      primary_category = "Uncategorized",
      confidence_score = 0,
      supporting_pathways = 0,
      evidence_summary = "No functional evidence available",
      all_category_scores = data.frame()  # Store all category scores
    )
    
    # Analyze enrichment if available
    if (!is.null(module_enrichment) && module_name %in% names(module_enrichment)) {
      enrichment_data <- module_enrichment[[module_name]]
      
      if (nrow(enrichment_data) > 0) {
        # Filter for significant pathways only (adj p < 0.05)
        significant_pathways <- enrichment_data[enrichment_data$adj_pval < 0.05, ]
        
        if (nrow(significant_pathways) > 0) {
          category_analysis <- calculate_category_confidence(significant_pathways)
          module_analysis <- update_module_analysis_with_categories(module_analysis, category_analysis)
        }
      }
    }
    
    module_analyses[[module_name]] <- module_analysis
  }
  
  return(module_analyses)
}

calculate_category_confidence <- function(significant_pathways) {
  
  # Map each pathway to its categories
  pathway_categories <- lapply(significant_pathways$Term, function(term) {
    categorize_pathways(term)
  })
  
  # Build pathway-category association table
  pathway_category_df <- data.frame()
  
  for (i in seq_along(pathway_categories)) {
    pathway_info <- significant_pathways[i, ]
    categories <- pathway_categories[[i]]
    
    if (length(categories) > 0 && !identical(categories, "Uncategorized")) {
      for (category in categories) {
        pathway_category_df <- rbind(pathway_category_df, data.frame(
          pathway = pathway_info$Term,
          category = category,
          adj_pval = pathway_info$adj_pval,
          gene_count = pathway_info$gene_count %||% 1,
          stringsAsFactors = FALSE
        ))
      }
    }
  }
  
  if (nrow(pathway_category_df) == 0) {
    return(list(
      primary_category = "Uncategorized",
      confidence_score = 0,
      supporting_pathways = 0,
      evidence_summary = "No categorizable pathways",
      all_categories = data.frame()
    ))
  }
  
  # Calculate scores for each category
  category_scores <- calculate_category_scores(pathway_category_df)
  
  return(category_scores)
}

calculate_category_scores <- function(pathway_category_df) {
  
  library(dplyr)
  
  # Group by category and calculate evidence metrics
  category_summary <- pathway_category_df %>%
    group_by(category) %>%
    summarise(
      pathway_count = n(),
      total_genes = sum(gene_count, na.rm = TRUE),
      avg_significance = mean(-log10(adj_pval), na.rm = TRUE),
      best_pvalue = min(adj_pval, na.rm = TRUE),
      .groups = 'drop'
    ) %>%
    mutate(
      # Normalize each component (0-10 scale)
      significance_score = pmin(10, avg_significance),          # Higher significance
      pathway_score = pmin(5, pathway_count),                    # More pathways
      gene_score = pmin(5, log10(total_genes + 1)),              # More genes
      
      # Weighted composite confidence score (0-10 scale)
      # 50% significance, 30% pathway count, 20% gene count
      confidence_score = round(
        (significance_score * 0.5 + pathway_score * 0.3 + gene_score * 0.2), 1
      )
    ) %>%
    arrange(desc(confidence_score))
  
  # Get primary category (highest confidence)
  primary_category <- category_summary$category[1]
  primary_confidence <- category_summary$confidence_score[1]
  primary_pathways <- category_summary$pathway_count[1]
  best_pval <- category_summary$best_pvalue[1]
  
  # Generate evidence summary
  evidence_summary <- generate_evidence_summary(
    primary_category, 
    primary_confidence, 
    primary_pathways,
    best_pval
  )
  
  return(list(
    primary_category = primary_category,
    confidence_score = primary_confidence,
    supporting_pathways = primary_pathways,
    evidence_summary = evidence_summary,
    all_categories = category_summary  # Return all scored categories
  ))
}


generate_evidence_summary <- function(category, confidence, pathway_count, best_pval) {
  
  # Confidence level interpretation
  confidence_level <- case_when(
    confidence >= 7 ~ "High",
    confidence >= 4 ~ "Moderate", 
    confidence >= 2 ~ "Low",
    TRUE ~ "Minimal"
  )
  
  # Statistical strength
  stat_strength <- case_when(
    best_pval < 0.001 ~ "very strong",
    best_pval < 0.01 ~ "strong", 
    best_pval < 0.05 ~ "moderate",
    TRUE ~ "weak"
  )
  
  # Build summary
  summary <- paste0(
    confidence_level, " confidence assignment to '", category, "' ",
    "(score: ", confidence, "/10) based on ", pathway_count, " ",
    "supporting pathway", ifelse(pathway_count > 1, "s", ""), 
    " with ", stat_strength, " statistical evidence ",
    "(best p = ", format(best_pval, scientific = TRUE, digits = 3), ")"
  )
  
  return(summary)
}

format_category_analysis <- function(category_summary) {
  
  if (nrow(category_summary) == 1) {
    return(paste0(category_summary$category[1], " (", category_summary$confidence_score[1], "/10)"))
  }
  
  # Show top 2 categories with scores
  top_categories <- head(category_summary, 2)
  formatted <- paste0(
    top_categories$category, " (", top_categories$confidence_score, "/10)",
    collapse = "; "
  )
  
  return(formatted)
}

update_module_analysis_with_categories <- function(module_analysis, category_analysis) {
  
  module_analysis$primary_category <- category_analysis$primary_category
  module_analysis$confidence_score <- category_analysis$confidence_score
  module_analysis$supporting_pathways <- category_analysis$supporting_pathways
  module_analysis$evidence_summary <- category_analysis$evidence_summary
  module_analysis$all_category_scores <- category_analysis$all_categories
  
  return(module_analysis)
}

create_evidence_based_summary_table <- function(module_analyses, hub_genes_converted) {
  
  summary_df <- data.frame()
  
  for (module_name in names(module_analyses)) {
    analysis <- module_analyses[[module_name]]
    
    # Calculate hub percentage
    hub_percentage <- if(analysis$size > 0) {
      round((analysis$hub_count / analysis$size) * 100, 1)
    } else { 0 }
    
    # Confidence level for display
    confidence_level <- case_when(
      analysis$confidence_score >= 7 ~ "High",
      analysis$confidence_score >= 4 ~ "Moderate",
      analysis$confidence_score >= 2 ~ "Low",
      TRUE ~ "Minimal"
    )
    
    # Get top regulators as SYMBOLS (not IDs)
    top_regulators <- if(length(analysis$top_hubs) > 0) {
      # Match with converted hub genes
      module_hubs <- hub_genes_converted[hub_genes_converted$module == module_name, ]
      
      if (nrow(module_hubs) > 0) {
        # Get top 2-3 hubs by hub_score
        top_hub_genes <- head(module_hubs[order(-module_hubs$hub_score), "gene"], 3)
        paste(top_hub_genes, collapse = ", ")
      } else {
        "None"
      }
    } else {
      "None"
    }
    
    row <- data.frame(
      Module = module_name,
      Size = analysis$size,
      Hub_Genes = paste0(analysis$hub_count, " (", hub_percentage, "%)"),
      Primary_Category = analysis$primary_category,
      Confidence_Score = analysis$confidence_score,
      Confidence_Level = confidence_level,
      Supporting_Pathways = analysis$supporting_pathways,
      Top_Regulators = top_regulators,  # Now contains symbols!
      Evidence = analysis$evidence_summary,
      stringsAsFactors = FALSE
    )
    
    summary_df <- rbind(summary_df, row)
  }
  
  # Sort by confidence score (descending), then by size
  summary_df <- summary_df[order(-summary_df$Confidence_Score, -summary_df$Size), ]
  
  return(summary_df)
}

debug_enrichment_data <- function(module_enrichment) {
  print("=== ENRICHMENT DATA DEBUG ===")
  
  if (is.null(module_enrichment)) {
    print("❌ module_enrichment is NULL")
    return()
  }
  
  print(paste("📊 Number of modules with enrichment:", length(module_enrichment)))
  print(paste("📊 Module names:", paste(names(module_enrichment), collapse = ", ")))
  
  # Check first module structure
  first_module <- names(module_enrichment)[1]
  first_data <- module_enrichment[[first_module]]
  
  print(paste("🔍 First module:", first_module))
  print(paste("🔍 Data class:", class(first_data)))
  print(paste("🔍 Number of rows:", nrow(first_data)))
  print("🔍 Column names:")
  print(colnames(first_data))
  print("🔍 First few rows:")
  print(head(first_data, 3))
  
  return(first_data)
}



create_enhanced_module_summary_table <- function(module_summaries) {
  
  print("Creating enhanced module summary table...")
  
  summary_df <- data.frame()
  
  for (module_name in names(module_summaries)) {
    summary <- module_summaries[[module_name]]
    
    tryCatch({
      # Safely handle potentially empty vectors
      top_hubs_str <- if(length(summary$top_hubs) > 0) {
        paste(summary$top_hubs, collapse = ", ")
      } else {
        "No hub genes"
      }
      
      categories_str <- if(length(summary$pathway_categories) > 0) {
        paste(summary$pathway_categories, collapse = ", ")
      } else {
        "Uncategorized"
      }
      
      primary_function_str <- if(!is.null(summary$primary_function) && summary$primary_function != "") {
        substr(summary$primary_function, 1, 50)
      } else {
        "Unknown function"
      }
      
      key_pathway_str <- if(!is.null(summary$key_pathway) && summary$key_pathway != "") {
        substr(summary$key_pathway, 1, 40)
      } else {
        "No pathway identified"
      }
      
      interpretation_str <- if(!is.null(summary$interpretation) && summary$interpretation != "") {
        substr(summary$interpretation, 1, 100)
      } else {
        paste("Module", module_name, "contains", summary$size, "co-expressed genes")
      }
      
      # Create row with safe string handling
      row <- data.frame(
        Module = as.character(module_name),
        Size = as.numeric(summary$size %||% 0),
        Hubs = as.numeric(summary$hub_count %||% 0),
        Primary_Function = as.character(primary_function_str),
        Key_Pathway = as.character(key_pathway_str),
        Top_Hubs = as.character(top_hubs_str),
        Categories = as.character(categories_str),
        Biological_Role = as.character(interpretation_str),
        stringsAsFactors = FALSE
      )
      
      summary_df <- rbind(summary_df, row)
      
    }, error = function(e) {
      print(paste("Error processing module", module_name, ":", e$message))
      
      # Create minimal fallback row
      fallback_row <- data.frame(
        Module = as.character(module_name),
        Size = as.numeric(summary$size %||% 0),
        Hubs = as.numeric(summary$hub_count %||% 0),
        Primary_Function = "Error in processing",
        Key_Pathway = "Error in processing", 
        Top_Hubs = "Error in processing",
        Categories = "Error in processing",
        Biological_Role = "Error in processing",
        stringsAsFactors = FALSE
      )
      
      summary_df <- rbind(summary_df, fallback_row)
    })
  }
  
  print(paste("Enhanced summary table created with", nrow(summary_df), "modules"))
  return(summary_df)
}

# ALSO ADD this helper function to prevent NULL errors:
`%||%` <- function(x, y) {
  if (is.null(x) || length(x) == 0) y else x
}


# Calculate WGCNA metrics
calculate_wgcna_metrics_enhanced <- function(expression_data, network_results,
                                             module_analysis, hub_genes) {
  
  print("📊 Calculating comprehensive WGCNA network metrics...")
  start_time <- Sys.time()
  
  # Basic network statistics
  n_genes <- ncol(expression_data)
  n_samples <- nrow(expression_data)
  n_modules <- length(network_results$modules)
  
  # Module size statistics
  module_sizes <- sapply(network_results$modules, length)
  
  # ✅ OPTIMIZED: Only calculate connectivity if adjacency is reasonable size
  connectivity_dist <- NULL
  if (!is.null(network_results$adjacency) && ncol(network_results$adjacency) <= 10000) {
    connectivity_dist <- rowSums(network_results$adjacency)
  } else {
    print("   ⚠️ Skipping full connectivity calculation (large matrix)")
    connectivity_dist <- rep(NA, n_genes)
  }
  
  # Module quality metrics - OPTIMIZED with early exit for large modules
  module_quality <- data.frame()
  for (module_name in names(network_results$modules)) {
    module_genes <- network_results$modules[[module_name]]
    
    if (length(module_genes) >= 3 && length(module_genes) <= 1000) {
      # Intramodule connectivity - SAMPLE if module is large
      if (length(module_genes) > 200) {
        # Sample subset for large modules
        sample_genes <- sample(module_genes, min(200, length(module_genes)))
        module_adj <- network_results$adjacency[sample_genes, sample_genes]
      } else {
        module_adj <- network_results$adjacency[module_genes, module_genes]
      }
      intra_connectivity <- mean(module_adj[upper.tri(module_adj)], na.rm = TRUE)
      
      # Module coherence (correlation with eigengene)
      ME_col <- paste0("ME", module_name)
      if (ME_col %in% colnames(module_analysis$module_eigengenes)) {
        # Sample genes for large modules
        if (length(module_genes) > 200) {
          sample_genes <- sample(module_genes, min(200, length(module_genes)))
          module_expr <- expression_data[, sample_genes, drop = FALSE]
        } else {
          module_expr <- expression_data[, module_genes, drop = FALSE]
        }
        ME <- module_analysis$module_eigengenes[, ME_col]
        coherence <- mean(abs(cor(module_expr, ME, use = "pairwise.complete.obs")), na.rm = TRUE)
      } else {
        coherence <- NA
      }
      
      module_quality <- rbind(module_quality, data.frame(
        module = module_name,
        size = length(module_genes),
        intra_connectivity = intra_connectivity,
        coherence = coherence,
        n_hubs = sum(hub_genes$module == module_name),
        hub_deg_overlap = sum(hub_genes$module == module_name & hub_genes$is_deg),
        stringsAsFactors = FALSE
      ))
    } else if (length(module_genes) >= 3) {
      # Large module - simplified stats
      module_quality <- rbind(module_quality, data.frame(
        module = module_name,
        size = length(module_genes),
        intra_connectivity = NA,
        coherence = NA,
        n_hubs = sum(hub_genes$module == module_name),
        hub_deg_overlap = sum(hub_genes$module == module_name & hub_genes$is_deg),
        stringsAsFactors = FALSE
      ))
    }
  }
  
  # ✅ OPTIMIZED: Skip clustering coefficient (very slow) - use sampling instead
  # Old code took O(n²) time - this is O(1)
  mean_clustering <- NA
  if (!is.null(network_results$adjacency) && ncol(network_results$adjacency) <= 2000) {
    # Only calculate for small networks
    sample_size <- min(500, ncol(network_results$adjacency))
    sample_idx <- sample(1:ncol(network_results$adjacency), sample_size)
    
    clustering_sample <- sapply(sample_idx, function(i) {
      row <- network_results$adjacency[i, ]
      neighbors <- which(row > 0.1)  # Threshold for adjacency
      if (length(neighbors) < 2) return(0)
      # Sample neighbors if too many
      if (length(neighbors) > 50) neighbors <- sample(neighbors, 50)
      neighbor_adj <- network_results$adjacency[neighbors, neighbors]
      sum(neighbor_adj > 0.1) / (length(neighbors) * (length(neighbors) - 1))
    })
    mean_clustering <- mean(clustering_sample, na.rm = TRUE)
  }
  print(paste("   ✅ Clustering coefficient (sampled):", round(mean_clustering, 4)))
  
  # Degree distribution (fast)
  degree_dist <- if (!is.null(network_results$adjacency)) {
    rowSums(network_results$adjacency > 0.1)
  } else {
    rep(NA, n_genes)
  }
  
  # Compile comprehensive metrics
  metrics <- list(
    # Basic counts
    network_size = list(
      total_genes = n_genes,
      total_samples = n_samples,
      total_modules = n_modules,
      total_hubs = nrow(hub_genes)
    ),
    
    # Module statistics
    module_stats = list(
      sizes = module_sizes,
      size_summary = summary(module_sizes),
      largest_module = names(which.max(module_sizes)),
      smallest_module = names(which.min(module_sizes)),
      quality_metrics = module_quality
    ),
    
    # Network topology
    topology = list(
      scale_free_r2 = network_results$scale_free_r2,
      mean_connectivity = mean(connectivity_dist, na.rm = TRUE),
      connectivity_summary = summary(connectivity_dist),
      degree_distribution = summary(degree_dist),
      mean_clustering = mean_clustering
    ),
    
    # Hub gene statistics
    hub_stats = list(
      total_hubs = nrow(hub_genes),
      hubs_per_module = table(hub_genes$module),
      deg_hubs = sum(hub_genes$is_deg),
      hub_connectivity_range = if(nrow(hub_genes) > 0) range(hub_genes$connectivity) else c(NA, NA),
      top_global_hubs = head(hub_genes$gene[order(hub_genes$global_hub_rank)], 10)
    ),
    
    # Quality assessments
    quality = list(
      modules_with_hubs = sum(table(hub_genes$module) > 0),
      avg_module_coherence = mean(module_quality$coherence, na.rm = TRUE),
      avg_intra_connectivity = mean(module_quality$intra_connectivity, na.rm = TRUE)
    )
  )
  
  elapsed <- difftime(Sys.time(), start_time, units = "secs")
  print(paste("✅ Metrics calculation completed in", round(elapsed, 1), "seconds"))
  
  # Print summary
  print("📈 Network Analysis Summary:")
  print(paste("  📸 Modules identified:", metrics$network_size$total_modules))
  print(paste("  📸 Hub genes found:", metrics$network_size$total_hubs))
  print(paste("  📸 Scale-free R²:", round(metrics$topology$scale_free_r2, 3)))
  print(paste("  📸 Mean connectivity:", round(metrics$topology$mean_connectivity, 3)))
  print(paste("  📸 DEG hubs:", metrics$hub_stats$deg_hubs))
  
  return(metrics)
}


# Function to extract key results for downstream analysis
extract_wgcna_summary <- function(wgcna_results) {
  
  if (is.null(wgcna_results) || !is.null(wgcna_results$error)) {
    return(NULL)
  }
  
  summary <- list(
    # Quick access to key results
    modules = wgcna_results$modules,
    hub_genes = wgcna_results$hub_genes,
    top_hubs = head(wgcna_results$hub_genes[order(wgcna_results$hub_genes$global_hub_rank), ], 20),
    
    # Module-trait associations (if available)
    trait_correlations = wgcna_results$module_trait_correlations,
    
    # Network quality
    network_quality = list(
      scale_free_r2 = wgcna_results$analysis_params$scale_free_r2,
      n_modules = wgcna_results$analysis_params$n_modules,
      soft_power = wgcna_results$analysis_params$soft_power
    ),
    
    # Functional insights
    enriched_functions = if (!is.null(wgcna_results$module_enrichment)) {
      lapply(wgcna_results$module_enrichment, function(mod) {
        head(mod$Term, 3)  # Top 3 functions per module
      })
    } else NULL
  )
  
  return(summary)
}

# Function to create publication-ready module table
create_module_table <- function(wgcna_results) {
  
  if (is.null(wgcna_results) || !is.null(wgcna_results$error)) {
    return(data.frame())
  }
  
  # Create comprehensive module table
  module_table <- data.frame()
  
  for (module_name in names(wgcna_results$modules)) {
    module_genes <- wgcna_results$modules[[module_name]]
    module_hubs <- wgcna_results$hub_genes[wgcna_results$hub_genes$module == module_name, ]
    
    # Top enriched function
    top_function <- if (!is.null(wgcna_results$module_enrichment) &&
                        module_name %in% names(wgcna_results$module_enrichment)) {
      head(wgcna_results$module_enrichment[[module_name]]$Term, 1)
    } else {
      "No enrichment data"
    }
    
    module_info <- data.frame(
      Module = module_name,
      Size = length(module_genes),
      Hub_Genes = nrow(module_hubs),
      DEG_Hubs = sum(module_hubs$is_deg),
      Top_Hub = if(nrow(module_hubs) > 0) module_hubs$gene[1] else "None",
      Top_Function = substr(top_function, 1, 60),  # Truncate for display
      All_Genes = paste(head(module_genes, 10), collapse = ", "),  # First 10 genes
      stringsAsFactors = FALSE
    )
    
    module_table <- rbind(module_table, module_info)
  }
  
  # Sort by module size
  module_table <- module_table[order(module_table$Size, decreasing = TRUE), ]
  
  return(module_table)
}

# Function for quick WGCNA diagnostics
diagnose_wgcna_results_clean <- function(wgcna_results) {
  
  if (is.null(wgcna_results)) {
    return("No WGCNA results provided")
  }
  
  if (!is.null(wgcna_results$error)) {
    return(paste("WGCNA analysis failed:", wgcna_results$error))
  }
  
  diagnostics <- c()
  
  # Check network quality (avoid unicode characters)
  scale_free_r2 <- wgcna_results$analysis_params$scale_free_r2
  if (!is.na(scale_free_r2)) {
    if (scale_free_r2 >= 0.8) {
      diagnostics <- c(diagnostics, "Excellent scale-free topology (R^2 >= 0.8)")
    } else if (scale_free_r2 >= 0.7) {
      diagnostics <- c(diagnostics, "Good scale-free topology (R^2 >= 0.7)")
    } else {
      diagnostics <- c(diagnostics, "Poor scale-free topology (R^2 < 0.7)")
    }
  }
  
  # Check module count
  n_modules <- wgcna_results$analysis_params$n_modules
  if (n_modules >= 5 && n_modules <= 20) {
    diagnostics <- c(diagnostics, "Optimal number of modules (5-20)")
  } else if (n_modules < 5) {
    diagnostics <- c(diagnostics, "Few modules detected - consider lowering merge threshold")
  } else {
    diagnostics <- c(diagnostics, "Many modules detected - consider increasing merge threshold")
  }
  
  # Check hub genes
  if (!is.null(wgcna_results$hub_genes) && nrow(wgcna_results$hub_genes) > 0) {
    n_hubs <- nrow(wgcna_results$hub_genes)
    deg_hubs <- sum(wgcna_results$hub_genes$is_deg)
    diagnostics <- c(diagnostics, paste(n_hubs, "hub genes identified"))
    if (deg_hubs > 0) {
      diagnostics <- c(diagnostics, paste(deg_hubs, "hub genes are also DEGs"))
    }
  }
  
  # Check enrichment
  if (!is.null(wgcna_results$module_enrichment) && length(wgcna_results$module_enrichment) > 0) {
    enriched_modules <- length(wgcna_results$module_enrichment)
    diagnostics <- c(diagnostics, paste(enriched_modules, "modules have functional enrichment"))
  } else {
    diagnostics <- c(diagnostics, "No modules have functional enrichment")
  }
  
  return(paste(diagnostics, collapse = "\n"))
}

