}

# Helper function to calculate scale-free topology fit
calculate_scale_free_fit <- function(connectivity) {
  
  # Calculate degree distribution
  k <- connectivity
  k_freq <- table(k)
  k_vals <- as.numeric(names(k_freq))
  freq <- as.numeric(k_freq)
  
  # Remove zero connectivity
  valid_idx <- k_vals > 0 & freq > 0
  k_vals <- k_vals[valid_idx]
  freq <- freq[valid_idx]
  
  if (length(k_vals) < 3) {
    return(list(R_squared = NA, slope = NA))
  }
  
  # Fit power law: log(freq) ~ slope * log(k)
  tryCatch({
    fit <- lm(log10(freq) ~ log10(k_vals))
    r_squared <- summary(fit)$r.squared
    slope <- coef(fit)[2]
    
    return(list(R_squared = r_squared, slope = slope))
  }, error = function(e) {
    return(list(R_squared = NA, slope = NA))
  })
}


########################ppi functions
detect_gene_id_type <- function(gene_ids) {
  
  if (length(gene_ids) == 0) {
    return(list(id_type = "unknown", confidence = 0, sample_ids = character(0)))
  }
  
  # Clean IDs first (remove version numbers, whitespace)
  clean_ids <- trimws(gene_ids)
  clean_ids <- sub("\\.[0-9]+$", "", clean_ids)  # Remove .version
  clean_ids <- clean_ids[!is.na(clean_ids) & clean_ids != ""]
  
  if (length(clean_ids) == 0) {
    return(list(id_type = "unknown", confidence = 0, sample_ids = character(0)))
  }
  
  # Count matches for each type
  n_total <- length(clean_ids)
  
  # ENSEMBL Gene IDs (human: ENSG, mouse: ENSMUSG, etc.)
  n_ensg <- sum(grepl("^ENS[A-Z]*G[0-9]{11}", clean_ids))
  
  # ENSEMBL Transcript IDs
  n_enst <- sum(grepl("^ENS[A-Z]*T[0-9]{11}", clean_ids))
  
  # ENSEMBL Protein IDs
  n_ensp <- sum(grepl("^ENS[A-Z]*P[0-9]{11}", clean_ids))
  
  # Entrez IDs (pure numbers, typically 1-8 digits)
  n_entrez <- sum(grepl("^[0-9]{1,8}$", clean_ids))
  
  # Gene Symbols (uppercase letters/numbers, 2-15 chars, may have hyphens)
  # Examples: TP53, BRCA1, HLA-A, C1orf112
  n_symbol <- sum(grepl("^[A-Z][A-Z0-9-]{1,14}$", clean_ids) & 
                    !grepl("^ENS", clean_ids))
  
  # UniProt IDs (e.g., P04637, Q9Y6K9)
  n_uniprot <- sum(grepl("^[OPQ][0-9][A-Z0-9]{3}[0-9]$|^[A-NR-Z][0-9][A-Z][A-Z0-9]{2}[0-9]$", clean_ids))
  
  # RefSeq IDs (NM_, NP_, XM_, XP_, NR_)
  n_refseq <- sum(grepl("^[NX][MRP]_[0-9]+", clean_ids))
  
  # Determine the predominant type
  type_counts <- c(
    "ensembl_gene" = n_ensg,
    "ensembl_transcript" = n_enst,
    "ensembl_protein" = n_ensp,
    "entrez" = n_entrez,
    "symbol" = n_symbol,
    "uniprot" = n_uniprot,
    "refseq" = n_refseq
  )
  
  best_type <- names(which.max(type_counts))
  best_count <- max(type_counts)
  confidence <- best_count / n_total
  
  # If no clear winner (less than 30% match), mark as mixed/unknown
  if (confidence < 0.3) {
    # Check if it's a mixed format
    if (sum(type_counts > 0) > 1) {
      best_type <- "mixed"
    } else {
      best_type <- "unknown"
    }
  }
  
  list(
    id_type = best_type,
    confidence = round(confidence, 3),
    total_ids = n_total,
    type_breakdown = type_counts[type_counts > 0],
    sample_ids = head(clean_ids, 5),
    clean_ids = clean_ids
  )
}

convert_gene_ids_universal <- function(gene_ids, from_type = NULL, to_type = "symbol", 
                                       organism = "human") {
  
  print(paste("🔄 Gene ID Conversion: Converting to", to_type, "for", organism))
  
  # Load required packages
  suppressPackageStartupMessages({
    require(AnnotationDbi)
  })
  
  # Get organism-specific annotation database
  org_db <- switch(tolower(organism),
                   "human" = "org.Hs.eg.db",
                   "mouse" = "org.Mm.eg.db",
                   "rat" = "org.Rn.eg.db",
                   "zebrafish" = "org.Dr.eg.db",
                   "fly" = "org.Dm.eg.db",
                   "worm" = "org.Ce.eg.db",
                   "yeast" = "org.Sc.sgd.db",
                   "org.Hs.eg.db"  # Default to human
  )
  
  # Try to load the annotation database
  db_loaded <- tryCatch({
    suppressPackageStartupMessages(require(org_db, character.only = TRUE))
    TRUE
  }, error = function(e) FALSE)
  
  if (!db_loaded) {
    print(paste("⚠️ Could not load", org_db, "- returning original IDs"))
    return(list(
      original_ids = gene_ids,
      converted_ids = gene_ids,
      mapping = data.frame(original = gene_ids, converted = gene_ids),
      success_rate = 0,
      from_type = "unknown",
      to_type = to_type
    ))
  }
  
  # Auto-detect ID type if not provided
  if (is.null(from_type)) {
    detection <- detect_gene_id_type(gene_ids)
    from_type <- detection$id_type
    clean_ids <- detection$clean_ids
    print(paste("  • Detected ID type:", from_type, 
                "(", round(detection$confidence * 100), "% confidence)"))
  } else {
    clean_ids <- sub("\\.[0-9]+$", "", trimws(gene_ids))
  }
  
  # If already in target format, return as-is
  if (from_type == to_type || 
      (from_type == "symbol" && to_type == "symbol")) {
    print("  • IDs already in target format")
    return(list(
      original_ids = gene_ids,
      converted_ids = clean_ids,
      mapping = data.frame(original = gene_ids, converted = clean_ids),
      success_rate = 1,
      from_type = from_type,
      to_type = to_type
    ))
  }
  
  # Define keytype mapping
  keytype_map <- c(
    "ensembl_gene" = "ENSEMBL",
    "ensembl_transcript" = "ENSEMBLTRANS",
    "entrez" = "ENTREZID",
    "symbol" = "SYMBOL",
    "uniprot" = "UNIPROT",
    "refseq" = "REFSEQ"
  )
  
  target_column <- switch(to_type,
                          "symbol" = "SYMBOL",
                          "ensembl" = "ENSEMBL",
                          "entrez" = "ENTREZID",
                          "SYMBOL"
  )
  
  source_keytype <- keytype_map[from_type]
  
  if (is.na(source_keytype)) {
    print(paste("  ⚠️ Unknown source type:", from_type, "- trying as symbols"))
    source_keytype <- "SYMBOL"
  }
  
  # Check if keytypes are available
  available_keytypes <- tryCatch({
    AnnotationDbi::keytypes(get(org_db))
  }, error = function(e) character(0))
  
  if (!source_keytype %in% available_keytypes) {
    print(paste("  ⚠️ Keytype", source_keytype, "not available in", org_db))
    return(list(
      original_ids = gene_ids,
      converted_ids = clean_ids,
      mapping = data.frame(original = gene_ids, converted = clean_ids),
      success_rate = 0,
      from_type = from_type,
      to_type = to_type
    ))
  }
  
  # Perform conversion
  converted <- tryCatch({
    AnnotationDbi::mapIds(
      get(org_db),
      keys = clean_ids,
      column = target_column,
      keytype = source_keytype,
      multiVals = "first"
    )
  }, error = function(e) {
    print(paste("  ❌ Conversion error:", e$message))
    setNames(rep(NA, length(clean_ids)), clean_ids)
  })
  
  # Create mapping dataframe
  mapping_df <- data.frame(
    original = gene_ids,
    clean = clean_ids,
    converted = as.character(converted[clean_ids]),
    stringsAsFactors = FALSE
  )
  
  # Fill in NA with original where possible
  mapping_df$final <- ifelse(is.na(mapping_df$converted), 
                             mapping_df$clean, 
                             mapping_df$converted)
  
  success_rate <- sum(!is.na(mapping_df$converted)) / nrow(mapping_df)
  
  print(paste("  ✅ Converted", sum(!is.na(mapping_df$converted)), "of", 
              length(gene_ids), "(", round(success_rate * 100, 1), "%)"))
  
  list(
    original_ids = gene_ids,
    converted_ids = mapping_df$final,
    converted_clean = mapping_df$converted[!is.na(mapping_df$converted)],
    mapping = mapping_df,
    success_rate = success_rate,
    from_type = from_type,
    to_type = to_type
  )
}

get_gene_id_formats <- function(gene_ids, organism = "human") {
  
  # Detect input type
  detection <- detect_gene_id_type(gene_ids)
  clean_ids <- detection$clean_ids
  from_type <- detection$id_type
  
  print(paste("📋 Getting multiple ID formats for", length(clean_ids), "genes"))
  print(paste("  • Input type:", from_type))
  
  # Initialize result
  result <- list(
    input_ids = clean_ids,
    input_type = from_type,
    symbols = character(0),
    ensembl_ids = character(0),
    entrez_ids = character(0),
    mapping = data.frame()
  )
  
  # Get organism database
  org_db <- switch(tolower(organism),
                   "human" = "org.Hs.eg.db",
                   "mouse" = "org.Mm.eg.db", 
                   "org.Hs.eg.db"
  )
  
  tryCatch({
    suppressPackageStartupMessages(require(org_db, character.only = TRUE))
    
    if (from_type == "symbol") {
      # Input is symbols, need to get Ensembl
      result$symbols <- clean_ids
      
      ensembl <- AnnotationDbi::mapIds(
        get(org_db), keys = clean_ids,
        column = "ENSEMBL", keytype = "SYMBOL", multiVals = "first"
      )
      result$ensembl_ids <- ensembl[!is.na(ensembl)]
      
      entrez <- AnnotationDbi::mapIds(
        get(org_db), keys = clean_ids,
        column = "ENTREZID", keytype = "SYMBOL", multiVals = "first"
      )
      result$entrez_ids <- entrez[!is.na(entrez)]
      
    } else if (from_type == "ensembl_gene") {
      # Input is Ensembl, need to get symbols
      result$ensembl_ids <- clean_ids
      
      symbols <- AnnotationDbi::mapIds(
        get(org_db), keys = clean_ids,
        column = "SYMBOL", keytype = "ENSEMBL", multiVals = "first"
      )
      result$symbols <- symbols[!is.na(symbols)]
      
      entrez <- AnnotationDbi::mapIds(
        get(org_db), keys = clean_ids,
        column = "ENTREZID", keytype = "ENSEMBL", multiVals = "first"
      )
      result$entrez_ids <- entrez[!is.na(entrez)]
      
    } else if (from_type == "entrez") {
      # Input is Entrez
      result$entrez_ids <- clean_ids
      
      symbols <- AnnotationDbi::mapIds(
        get(org_db), keys = clean_ids,
        column = "SYMBOL", keytype = "ENTREZID", multiVals = "first"
      )
      result$symbols <- symbols[!is.na(symbols)]
      
      ensembl <- AnnotationDbi::mapIds(
        get(org_db), keys = clean_ids,
        column = "ENSEMBL", keytype = "ENTREZID", multiVals = "first"
      )
      result$ensembl_ids <- ensembl[!is.na(ensembl)]
    }
    
    # Create mapping dataframe
    result$mapping <- data.frame(
      input = clean_ids,
      symbol = result$symbols[match(clean_ids, names(result$symbols))] %||% NA,
      ensembl = result$ensembl_ids[match(clean_ids, names(result$ensembl_ids))] %||% NA,
      entrez = result$entrez_ids[match(clean_ids, names(result$entrez_ids))] %||% NA,
      stringsAsFactors = FALSE
    )
    
  }, error = function(e) {
    print(paste("  ⚠️ ID conversion error:", e$message))
  })
  
  print(paste("  ✅ Got", length(result$symbols), "symbols,",
              length(result$ensembl_ids), "Ensembl IDs,",
              length(result$entrez_ids), "Entrez IDs"))
  
  result
}



