}

# 0. GENE ID CONVERSION INTEGRATION
# ============================================================================

#' Convert genes for PPI analysis using your existing system
#' Integrates with your organism-specific annotation databases
convert_genes_for_ppi_analysis <- function(selected_genes, organism) {
  
  print("🔄 Converting gene IDs for PPI analysis...")
  
  # Debug: Print the structure of selected_genes
  print("=== DEBUGGING SELECTED_GENES STRUCTURE ===")
  print(paste("selected_genes class:", class(selected_genes)))
  
  if (is.list(selected_genes)) {
    print(paste("selected_genes names:", paste(names(selected_genes), collapse = ", ")))
    if ("all_genes" %in% names(selected_genes)) {
      print(paste("all_genes length:", length(selected_genes[["all_genes"]])))
    }
    if ("up_genes" %in% names(selected_genes)) {
      print(paste("up_genes length:", length(selected_genes[["up_genes"]])))
    }
    if ("down_genes" %in% names(selected_genes)) {
      print(paste("down_genes length:", length(selected_genes[["down_genes"]])))
    }
  }
  print("=== END DEBUG ===")
  
  # FIXED: Safely extract gene lists using [[ ]] instead of [ ]
  tryCatch({
    # Use [[ ]] for list element access to avoid closure error
    all_genes <- selected_genes[["all_genes"]]
    up_genes <- selected_genes[["up_genes"]]
    down_genes <- selected_genes[["down_genes"]]
    
    # Validate extracted genes
    if (is.null(all_genes) || length(all_genes) == 0) {
      stop("No genes found in selected_genes$all_genes")
    }
    
    print(paste("Successfully extracted", length(all_genes), "genes for conversion"))
    
    # Convert genes to proper symbols for PPI analysis
    # For now, we'll assume the genes are already in symbol format
    # You can enhance this with actual ID conversion if needed
    
    # Create conversion result structure
    converted_genes <- list(
      all_genes_symbols = all_genes,
      up_genes_symbols = if(is.null(up_genes)) character(0) else up_genes,
      down_genes_symbols = if(is.null(down_genes)) character(0) else down_genes,
      conversion_stats = list(
        n_input = length(all_genes),
        n_converted = length(all_genes),
        conversion_rate = 1.0,
        failed_conversions = character(0)
      )
    )
    
    return(converted_genes)
    
  }, error = function(e) {
    print(paste("❌ Error extracting genes from selected_genes:", e$message))
    
    # Fallback: try alternative extraction methods
    tryCatch({
      if (is.list(selected_genes) && length(selected_genes) > 0) {
        # Try extracting by position if names don't work
        all_genes <- selected_genes[[1]]
        up_genes <- if(length(selected_genes) >= 2) selected_genes[[2]] else character(0)
        down_genes <- if(length(selected_genes) >= 3) selected_genes[[3]] else character(0)
        
        if (!is.null(all_genes) && length(all_genes) > 0) {
          print("Using fallback gene extraction by position")
          
          converted_genes <- list(
            all_genes_symbols = all_genes,
            up_genes_symbols = if(is.null(up_genes)) character(0) else up_genes,
            down_genes_symbols = if(is.null(down_genes)) character(0) else down_genes,
            conversion_stats = list(
              n_input = length(all_genes),
              n_converted = length(all_genes),
              conversion_rate = 1.0,
              failed_conversions = character(0)
            )
          )
          
          return(converted_genes)
        }
      }
      
      # Final fallback
      stop("Could not extract any genes from selected_genes")
      
    }, error = function(e2) {
      print(paste("❌ All gene extraction methods failed:", e2$message))
      return(NULL)
    })
  })
}

#' Safe version of convert_gene_list_to_symbols with better error handling
convert_gene_list_to_symbols_safe <- function(gene_ids, db_obj) {
  
  if (length(gene_ids) == 0) {
    return(list(symbols = character(0), methods = character(0)))
  }
  
  # Ensure gene_ids is a character vector
  gene_ids <- as.character(gene_ids)
  
  # Clean gene IDs (remove suffixes like "_red vs green")
  cleaned_ids <- gsub("_.*$", "", gene_ids)
  cleaned_ids <- gsub("\\.[0-9]+$", "", cleaned_ids)  # Remove version numbers
  
  # Initialize results
  symbols <- rep(NA_character_, length(cleaned_ids))
  methods <- rep("unknown", length(cleaned_ids))
  
  # Simple approach: Check if they're already gene symbols
  tryCatch({
    if ("SYMBOL" %in% AnnotationDbi::keytypes(db_obj)) {
      # Check which ones are already valid symbols
      valid_symbols <- cleaned_ids %in% AnnotationDbi::keys(db_obj, keytype = "SYMBOL")
      
      if (sum(valid_symbols) > 0) {
        symbols[valid_symbols] <- cleaned_ids[valid_symbols]
        methods[valid_symbols] <- "SYMBOL"
        print(paste("   Found", sum(valid_symbols), "genes already as valid symbols"))
      }
    }
  }, error = function(e) {
    print("Error checking for existing symbols")
  })
  
  # For remaining genes, try ENSEMBL conversion
  unmapped <- which(is.na(symbols))
  if (length(unmapped) > 0 && "ENSEMBL" %in% AnnotationDbi::keytypes(db_obj)) {
    tryCatch({
      ensembl_symbols <- AnnotationDbi::mapIds(
        db_obj,
        keys = cleaned_ids[unmapped],
        column = "SYMBOL",
        keytype = "ENSEMBL",
        multiVals = "first"
      )
      
      valid_indices <- which(!is.na(ensembl_symbols))
      if (length(valid_indices) > 0) {
        actual_indices <- unmapped[valid_indices]
        symbols[actual_indices] <- ensembl_symbols[valid_indices]
        methods[actual_indices] <- "ENSEMBL"
        print(paste("   Converted", length(valid_indices), "ENSEMBL IDs"))
      }
    }, error = function(e) {
      print("ENSEMBL conversion failed")
    })
  }
  
  # For remaining genes, use original IDs as fallback
  final_unmapped <- which(is.na(symbols))
  if (length(final_unmapped) > 0) {
    symbols[final_unmapped] <- cleaned_ids[final_unmapped]
    methods[final_unmapped] <- "ORIGINAL_ID"
    print(paste("   Using original IDs for", length(final_unmapped), "unmapped genes"))
  }
  
  return(list(symbols = symbols, methods = methods))
}

#' Convert a list of genes to symbols using your existing logic
convert_gene_list_to_symbols <- function(gene_ids, db_obj) {
  
  if (length(gene_ids) == 0) {
    return(list(symbols = character(0), methods = character(0)))
  }
  
  # Clean gene IDs (remove suffixes like "_red vs green")
  cleaned_ids <- gsub("_.*$", "", gene_ids)
  cleaned_ids <- gsub("\\.[0-9]+$", "", cleaned_ids)  # Remove version numbers
  
  # Initialize results
  symbols <- rep(NA_character_, length(cleaned_ids))
  methods <- rep("unknown", length(cleaned_ids))
  
  # Detect ID types using your existing patterns
  enst_indices <- grep("^ENST", cleaned_ids)
  ensg_indices <- grep("^ENSG", cleaned_ids)
  ensmusg_indices <- grep("^ENSMUSG", cleaned_ids)  # Mouse ENSEMBL
  entrez_indices <- grep("^[0-9]+$", cleaned_ids)
  symbol_indices <- grep("^[A-Z][A-Z0-9-]*$", cleaned_ids)
  
  # Combine ENSEMBL indices
  all_ensembl_indices <- unique(c(ensg_indices, ensmusg_indices))
  
  print(paste("ID type detection:"))
  print(paste("   ENST (transcript):", length(enst_indices)))
  print(paste("   ENSG (gene):", length(all_ensembl_indices)))
  print(paste("   Entrez:", length(entrez_indices)))
  print(paste("   Symbols:", length(symbol_indices)))
  
  # 1. Convert ENSEMBL gene IDs
  if (length(all_ensembl_indices) > 0 && "ENSEMBL" %in% AnnotationDbi::keytypes(db_obj)) {
    tryCatch({
      ensembl_symbols <- AnnotationDbi::mapIds(
        db_obj,
        keys = cleaned_ids[all_ensembl_indices],
        column = "SYMBOL",
        keytype = "ENSEMBL",
        multiVals = "first"
      )
      
      valid_indices <- which(!is.na(ensembl_symbols))
      if (length(valid_indices) > 0) {
        symbols[all_ensembl_indices[valid_indices]] <- ensembl_symbols[valid_indices]
        methods[all_ensembl_indices[valid_indices]] <- "ENSEMBL"
        print(paste("   Converted", length(valid_indices), "ENSEMBL IDs"))
      }
    }, error = function(e) {
      print(paste("ENSEMBL conversion failed:", e$message))
    })
  }
  
  # 2. Convert transcript IDs (ENST) - more complex, try multiple approaches
  if (length(enst_indices) > 0) {
    transcript_converted <- convert_transcript_ids_to_symbols(
      cleaned_ids[enst_indices], db_obj
    )
    
    valid_indices <- which(!is.na(transcript_converted))
    if (length(valid_indices) > 0) {
      symbols[enst_indices[valid_indices]] <- transcript_converted[valid_indices]
      methods[enst_indices[valid_indices]] <- "ENSEMBLTRANS"
      print(paste("   Converted", length(valid_indices), "transcript IDs"))
    }
  }
  
  # 3. Convert Entrez IDs
  if (length(entrez_indices) > 0 && "ENTREZID" %in% AnnotationDbi::keytypes(db_obj)) {
    tryCatch({
      entrez_symbols <- AnnotationDbi::mapIds(
        db_obj,
        keys = cleaned_ids[entrez_indices],
        column = "SYMBOL",
        keytype = "ENTREZID",
        multiVals = "first"
      )
      
      valid_indices <- which(!is.na(entrez_symbols))
      if (length(valid_indices) > 0) {
        symbols[entrez_indices[valid_indices]] <- entrez_symbols[valid_indices]
        methods[entrez_indices[valid_indices]] <- "ENTREZID"
        print(paste("   Converted", length(valid_indices), "Entrez IDs"))
      }
    }, error = function(e) {
      print(paste("Entrez conversion failed:", e$message))
    })
  }
  
  # 4. Handle gene symbols (verify they're valid)
  if (length(symbol_indices) > 0) {
    # Check if they're valid symbols in the database
    if ("SYMBOL" %in% AnnotationDbi::keytypes(db_obj)) {
      valid_symbols <- cleaned_ids[symbol_indices] %in% AnnotationDbi::keys(db_obj, keytype = "SYMBOL")
      valid_symbol_indices <- symbol_indices[valid_symbols]
      
      if (length(valid_symbol_indices) > 0) {
        symbols[valid_symbol_indices] <- cleaned_ids[valid_symbol_indices]
        methods[valid_symbol_indices] <- "SYMBOL"
        print(paste("   Verified", length(valid_symbol_indices), "gene symbols"))
      }
    } else {
      # If SYMBOL keytype not available, just use them as-is
      symbols[symbol_indices] <- cleaned_ids[symbol_indices]
      methods[symbol_indices] <- "SYMBOL_ASSUMED"
      print(paste("   Used", length(symbol_indices), "symbols as-is"))
    }
  }
  
  # 5. Handle remaining unmapped IDs - try alternative approaches
  unmapped_indices <- which(is.na(symbols))
  if (length(unmapped_indices) > 0) {
    print(paste("   Attempting alternative conversion for", length(unmapped_indices), "unmapped IDs"))
    
    # Try different keytypes
    alternative_keytypes <- c("GENENAME", "ALIAS", "ENSEMBLPROT")
    
    for (keytype in alternative_keytypes) {
      if (keytype %in% AnnotationDbi::keytypes(db_obj) && length(unmapped_indices) > 0) {
        tryCatch({
          alt_symbols <- AnnotationDbi::mapIds(
            db_obj,
            keys = cleaned_ids[unmapped_indices],
            column = "SYMBOL",
            keytype = keytype,
            multiVals = "first"
          )
          
          newly_mapped <- which(!is.na(alt_symbols))
          if (length(newly_mapped) > 0) {
            actual_indices <- unmapped_indices[newly_mapped]
            symbols[actual_indices] <- alt_symbols[newly_mapped]
            methods[actual_indices] <- keytype
            unmapped_indices <- unmapped_indices[-newly_mapped]
            print(paste("      ", keytype, "converted", length(newly_mapped), "additional IDs"))
          }
        }, error = function(e) {
          # Silently continue to next keytype
        })
      }
    }
  }
  
  # 6. Final fallback - use cleaned original IDs for unmapped
  final_unmapped <- which(is.na(symbols))
  if (length(final_unmapped) > 0) {
    symbols[final_unmapped] <- cleaned_ids[final_unmapped]
    methods[final_unmapped] <- "ORIGINAL_ID"
    print(paste("   Using original IDs for", length(final_unmapped), "unmapped genes"))
  }
  
  return(list(symbols = symbols, methods = methods))
}

#' Convert transcript IDs to symbols (handles ENST IDs)
convert_transcript_ids_to_symbols <- function(transcript_ids, db_obj) {
  
  symbols <- rep(NA_character_, length(transcript_ids))
  
  # Try ENSEMBLTRANS keytype if available
  if ("ENSEMBLTRANS" %in% AnnotationDbi::keytypes(db_obj)) {
    tryCatch({
      trans_symbols <- AnnotationDbi::mapIds(
        db_obj,
        keys = transcript_ids,
        column = "SYMBOL",
        keytype = "ENSEMBLTRANS",
        multiVals = "first"
      )
      symbols <- as.character(trans_symbols)
    }, error = function(e) {
      print("ENSEMBLTRANS conversion failed, trying alternative methods")
    })
  }
  
  # If still unmapped, try to convert transcript to gene ID first
  unmapped <- which(is.na(symbols))
  if (length(unmapped) > 0 && requireNamespace("biomaRt", quietly = TRUE)) {
    tryCatch({
      # Use biomaRt as fallback for transcript conversion
      ensembl <- biomaRt::useMart("ensembl", dataset = "hsapiens_gene_ensembl")
      
      mapping <- biomaRt::getBM(
        attributes = c("ensembl_transcript_id", "ensembl_gene_id", "external_gene_name"),
        filters = "ensembl_transcript_id",
        values = transcript_ids[unmapped],
        mart = ensembl
      )
      
      # Map back to original transcript IDs
      for (i in unmapped) {
        matches <- mapping[mapping$ensembl_transcript_id == transcript_ids[i], ]
        if (nrow(matches) > 0 && !is.na(matches$external_gene_name[1])) {
          symbols[i] <- matches$external_gene_name[1]
        }
      }
    }, error = function(e) {
      print("biomaRt transcript conversion also failed")
    })
  }
  
  return(symbols)
}

# CytoHubba-style centrality helpers --------------------------------------

# MCC: Maximal Clique Centrality. For each node v, sum over all maximal
# cliques C containing v of (|C| - 1)!. Computed from igraph::max_cliques().
# Uses log-factorial to avoid overflow, exponentiating only if the result
# will fit in a double (~cliques up to size 170).
calc_mcc <- function(g, max_clique_size = 20) {
  cliques <- igraph::max_cliques(g, min = 2)
  mcc <- setNames(rep(0, igraph::vcount(g)), igraph::V(g)$name)
  if (length(cliques) == 0) return(mcc)
  for (cl in cliques) {
    size <- length(cl)
    # Cap giant cliques to avoid Inf/overflow in (size-1)!
    n <- min(size, max_clique_size)
    contrib <- factorial(n - 1)
    names_cl <- igraph::V(g)$name[cl]
    mcc[names_cl] <- mcc[names_cl] + contrib
  }
  mcc
}

# MNC: Maximum Neighborhood Component. For each node v, size of the largest
# connected component in the subgraph induced by v's direct neighbors.
calc_mnc <- function(g) {
  sapply(igraph::V(g), function(v) {
    nbrs <- igraph::neighbors(g, v)
    if (length(nbrs) < 2) return(length(nbrs))
    sub <- igraph::induced_subgraph(g, nbrs)
    comps <- igraph::components(sub)
    if (comps$no == 0) 0L else max(comps$csize)
  })
}

# DMNC: Density of MNC = MNC / size(N(v))^1.7. CytoHubba's definition.
calc_dmnc <- function(g, mnc = NULL) {
  if (is.null(mnc)) mnc <- calc_mnc(g)
  deg <- igraph::degree(g)
  out <- ifelse(deg > 0, mnc / (deg ^ 1.7), 0)
  round(out, 6)
}

# EPC: Edge Percolated Component. Simulate bond percolation `n_sim` times;
# for each node v, average number of nodes in v's component (normalized by
# network size). Expensive — we cap / skip on large networks.
calc_epc <- function(g, n_sim = 500, seed = 12345) {
  set.seed(seed)
  n <- igraph::vcount(g)
  e <- igraph::ecount(g)
  if (n < 2 || e < 1) return(setNames(rep(0, n), igraph::V(g)$name))
  score <- setNames(numeric(n), igraph::V(g)$name)
  for (i in seq_len(n_sim)) {
    # Bernoulli edge retention with random threshold per edge (as CytoHubba)
    keep <- runif(e) < runif(e)
    sub <- igraph::subgraph.edges(g, igraph::E(g)[keep], delete.vertices = FALSE)
    comps <- igraph::components(sub)
    score <- score + comps$csize[comps$membership] / n
  }
  round(score / n_sim, 6)
}

# Calculate centrality measures for PPI network (CytoHubba-style).
# Returns a data.frame with columns:
#   gene, degree, betweenness, closeness, eigenvector, MCC, MNC, DMNC, EPC
# EPC is skipped (set to NA) on networks with >5000 nodes to keep runtime
# bounded; this is surfaced in the log message.
calculate_centrality_measures <- function(ppi_interactions,
                                          epc_node_cap = 5000,
                                          epc_n_sim = 500) {
  print("Calculating centrality measures (CytoHubba-style)...")

  tryCatch({
    if (is.null(ppi_interactions) || nrow(ppi_interactions) == 0) {
      print("❌ No interactions for centrality calculation")
      return(NULL)
    }

    # Ensure correct column names
    if (!all(c("gene_from", "gene_to") %in% colnames(ppi_interactions))) {
      if ("protein1" %in% colnames(ppi_interactions)) {
        colnames(ppi_interactions)[colnames(ppi_interactions) == "protein1"] <- "gene_from"
        colnames(ppi_interactions)[colnames(ppi_interactions) == "protein2"] <- "gene_to"
      } else if ("stringId_A" %in% colnames(ppi_interactions)) {
        colnames(ppi_interactions)[colnames(ppi_interactions) == "stringId_A"] <- "gene_from"
        colnames(ppi_interactions)[colnames(ppi_interactions) == "stringId_B"] <- "gene_to"
      }
    }

    if (!requireNamespace("igraph", quietly = TRUE)) {
      print("❌ igraph package not available")
      return(NULL)
    }

    # Create undirected simple graph (drop duplicate edges, self-loops)
    edges <- unique(ppi_interactions[, c("gene_from", "gene_to")])
    g <- igraph::graph_from_data_frame(edges, directed = FALSE)
    g <- igraph::simplify(g, remove.multiple = TRUE, remove.loops = TRUE)

    node_names <- igraph::V(g)$name
    n_nodes <- igraph::vcount(g)
    n_edges <- igraph::ecount(g)
    print(paste0("Graph: ", n_nodes, " nodes, ", n_edges, " edges"))

    # ---- Classical centralities (already there) ----
    degree      <- igraph::degree(g)
    betweenness <- igraph::betweenness(g)
    closeness   <- igraph::closeness(g)
    eigenvec    <- igraph::eigen_centrality(g)$vector

    # ---- CytoHubba additions ----
    mcc_vals <- tryCatch(calc_mcc(g),
                         error = function(e) {
                           print(paste("MCC failed:", e$message))
                           setNames(rep(NA_real_, n_nodes), node_names)
                         })
    mnc_vals <- tryCatch(calc_mnc(g),
                         error = function(e) {
                           print(paste("MNC failed:", e$message))
                           setNames(rep(NA_real_, n_nodes), node_names)
                         })
    dmnc_vals <- tryCatch(calc_dmnc(g, mnc = mnc_vals),
                          error = function(e) {
                            print(paste("DMNC failed:", e$message))
                            setNames(rep(NA_real_, n_nodes), node_names)
                          })
    # EPC: skip on large networks to keep runtime manageable
    if (n_nodes > epc_node_cap) {
      print(paste0("EPC skipped (", n_nodes, " nodes > cap ", epc_node_cap, ")"))
      epc_vals <- setNames(rep(NA_real_, n_nodes), node_names)
    } else {
      epc_vals <- tryCatch(calc_epc(g, n_sim = epc_n_sim),
                           error = function(e) {
                             print(paste("EPC failed:", e$message))
                             setNames(rep(NA_real_, n_nodes), node_names)
                           })
    }

    centrality_df <- data.frame(
      gene        = node_names,
      degree      = as.integer(degree),
      betweenness = round(as.numeric(betweenness), 2),
      closeness   = round(as.numeric(closeness), 4),
      eigenvector = round(as.numeric(eigenvec), 4),
      MCC         = as.numeric(mcc_vals[node_names]),
      MNC         = as.integer(mnc_vals[node_names]),
      DMNC        = as.numeric(dmnc_vals[node_names]),
      EPC         = as.numeric(epc_vals[node_names]),
      stringsAsFactors = FALSE
    )

    # Sort by degree (primary), MCC (tie-break)
    centrality_df <- centrality_df[order(-centrality_df$degree,
                                         -centrality_df$MCC), ]
    rownames(centrality_df) <- NULL

    print(paste("✅ Calculated 8 centrality measures for",
                nrow(centrality_df), "proteins"))

    return(centrality_df)

  }, error = function(e) {
    print(paste("❌ Centrality calculation failed:", e$message))
    return(NULL)
  })
}

# Consensus-hub summary: given a centrality_df (from the function above)
# and a top_n threshold, for each gene count the number of algorithms for
# which this gene ranks in the top_n. Returns a data.frame sorted by
# consensus score descending.
calculate_hub_consensus <- function(centrality_df,
                                    top_n = 10,
                                    algorithms = c("degree","betweenness","closeness",
                                                   "eigenvector","MCC","MNC",
                                                   "DMNC","EPC")) {
  if (is.null(centrality_df) || nrow(centrality_df) == 0) return(NULL)
  available <- intersect(algorithms, names(centrality_df))
  if (length(available) == 0) return(NULL)

  top_sets <- lapply(available, function(a) {
    v <- centrality_df[[a]]
    if (all(is.na(v))) return(character(0))
    ord <- order(v, decreasing = TRUE, na.last = NA)
    centrality_df$gene[ord[seq_len(min(top_n, length(ord)))]]
  })
  names(top_sets) <- available

  all_genes <- unique(unlist(top_sets))
  member_flags <- sapply(top_sets, function(s) all_genes %in% s)
  if (is.null(dim(member_flags))) {
    member_flags <- matrix(member_flags, nrow = length(all_genes))
    colnames(member_flags) <- available
  }
  consensus <- data.frame(
    gene = all_genes,
    consensus_score = rowSums(member_flags),
    member_flags,
    stringsAsFactors = FALSE,
    check.names = FALSE
  )
  consensus[order(-consensus$consensus_score, consensus$gene), ,
            drop = FALSE]
}

# Normalize a clinical-phase / stage string to an ordinal (higher = later
# stage / more advanced). Returns integer in {0..5}, or NA for unknown.
#
# Handles a variety of conventions seen across OpenTargets / DGIdb /
# ChEMBL / string mentions:
#   - "APPROVAL" / "Launched"                  -> 5
#   - "Phase 4" / "Phase IV" / "PHASE_4"       -> 4
#   - "Phase 3" / "Phase III" / "PHASE_3"      -> 3
#   - "Phase 2" / "Phase II" / "PHASE_2"       -> 2
#   - "Phase 1" / "Phase I" / "PHASE_1"        -> 1
#   - Ranges like "PHASE_1_2" / "Phase I/II"   -> higher phase (capped 4)
#   - "Preclinical" / "Discovery"              -> 0
normalize_clinical_stage <- function(x) {
  if (is.null(x)) return(NA_integer_)
  v <- toupper(trimws(as.character(x)))
  sapply(v, function(s) {
    if (is.na(s) || s == "" || s == "UNKNOWN") return(NA_integer_)
    if (grepl("APPROV|LAUNCH|MARKETED", s)) return(5L)
    if (grepl("PRECLIN|DISCOVERY|EARLY", s)) return(0L)
    # Pull every digit that follows a PHASE token, take the highest.
    # This handles "PHASE_1_2" (Phase I/II combined), "Phase 3/4", etc.
    m <- regmatches(s, gregexpr("PHASE[^A-Z]*[0-9]+", s))[[1]]
    if (length(m) > 0) {
      digits <- as.integer(unlist(regmatches(m, gregexpr("[0-9]+", m))))
      digits <- digits[!is.na(digits)]
      if (length(digits) > 0) return(as.integer(min(max(digits), 4L)))
    }
    # Roman numerals fallback (check longer strings first)
    if (grepl("PHASE[^A-Z]*IV", s))                   return(4L)
    if (grepl("PHASE[^A-Z]*III", s))                  return(3L)
    if (grepl("PHASE[^A-Z]*II(?!I)", s, perl = TRUE)) return(2L)
    if (grepl("PHASE[^A-Z]*I(?!I)", s, perl = TRUE))  return(1L)
    NA_integer_
  }, USE.NAMES = FALSE)
}

stage_label_from_rank <- function(r) {
  r <- as.integer(r)
  out <- character(length(r))
  out[is.na(r)] <- "Unknown"
  out[!is.na(r) & r == 5L] <- "Approved"
  out[!is.na(r) & r == 4L] <- "Phase IV"
  out[!is.na(r) & r == 3L] <- "Phase III"
  out[!is.na(r) & r == 2L] <- "Phase II"
  out[!is.na(r) & r == 1L] <- "Phase I"
  out[!is.na(r) & r == 0L] <- "Preclinical"
  out
}

# Build a per-gene druggability summary from an existing drug_targets df
# (the one produced by identify_drug_targets(...)). Reads the local
# OpenTargets drug_molecule Parquet to fill in maximumClinicalStage where
# the drug_targets$clinical_phase column is NA/unknown.
# Returns a data.frame with: gene, is_druggable, n_drugs, n_approved_drugs,
# max_stage_rank (int 0..5), max_approval_stage (human label).
build_druggability_summary <- function(drug_targets,
                                       ot_data_path = Sys.getenv(
                                         "OPENTARGETS_DATA_PATH",
                                         "/srv/opentargets")) {
  if (is.null(drug_targets) || !is.data.frame(drug_targets) ||
      nrow(drug_targets) == 0) return(data.frame())

  # Coerce arrow/tibble input into a plain data.frame with fully-atomic
  # columns so downstream row-wise rbind doesn't hit vctrs list-column
  # type conflicts (arrow collect() returns list_of<> for list cols; even
  # scalar string cols may be vctrs_vctr).
  drug_targets <- as.data.frame(drug_targets, stringsAsFactors = FALSE)
  drug_targets[] <- lapply(drug_targets, function(col) {
    if (is.list(col)) {
      vapply(col, function(x) {
        if (is.null(x) || length(x) == 0) NA_character_
        else as.character(x[[1]])
      }, character(1))
    } else if (is.numeric(col) || is.logical(col)) {
      as.vector(col)
    } else {
      as.character(col)
    }
  })

  # Use whatever stage column we have
  stage_col <- intersect(c("clinical_phase", "maxClinicalStage",
                           "maximumClinicalStage"),
                         names(drug_targets))[1]
  if (is.na(stage_col)) {
    drug_targets$clinical_phase <- NA_character_
    stage_col <- "clinical_phase"
  }
  drug_targets$stage_rank <- normalize_clinical_stage(drug_targets[[stage_col]])

  # Fill missing stages from local OT drug_molecule (ChEMBL id -> stage).
  # Use arrow::open_dataset + dplyr::collect and immediately coerce to
  # plain base character vectors so vctrs_list_of<character> types from
  # the Parquet layer don't propagate into our data.frame.
  missing_stage <- is.na(drug_targets$stage_rank) &
    !is.na(drug_targets$drug_chembl_id) &
    nzchar(drug_targets$drug_chembl_id)
  if (any(missing_stage) && requireNamespace("arrow", quietly = TRUE) &&
      requireNamespace("dplyr", quietly = TRUE)) {
    dm_path <- file.path(ot_data_path, "drug_molecule")
    if (dir.exists(dm_path)) {
      chembl_ids_needed <- unique(as.character(
        drug_targets$drug_chembl_id[missing_stage]))
      dm <- tryCatch({
        tbl <- arrow::open_dataset(dm_path, format = "parquet") %>%
          dplyr::select(id, maximumClinicalStage) %>%
          dplyr::collect()
        data.frame(
          id                   = as.character(tbl$id),
          maximumClinicalStage = as.character(tbl$maximumClinicalStage),
          stringsAsFactors     = FALSE
        )
      }, error = function(e) {
        print(paste("drug_molecule lookup failed:", e$message)); NULL
      })
      if (!is.null(dm) && nrow(dm) > 0) {
        dm <- dm[dm$id %in% chembl_ids_needed, , drop = FALSE]
        if (nrow(dm) > 0) {
          lookup <- setNames(dm$maximumClinicalStage, dm$id)
          extra_rank <- as.integer(normalize_clinical_stage(
            lookup[as.character(drug_targets$drug_chembl_id[missing_stage])]))
          drug_targets$stage_rank[missing_stage] <- extra_rank
        }
      }
    }
  }

  # Ensure stage_rank is plain integer (not vctrs) after the optional lookup
  drug_targets$stage_rank <- as.integer(drug_targets$stage_rank)

  # is_approved is already on drug_targets (logical); refresh from stage_rank
  is_approved_row <- !is.na(drug_targets$stage_rank) &
    drug_targets$stage_rank == 5L
  if ("is_approved" %in% names(drug_targets)) {
    is_approved_row <- is_approved_row |
      isTRUE(drug_targets$is_approved) | (drug_targets$is_approved %in% TRUE)
  }

  # Build the per-gene summary with atomic vector aggregations and a
  # single data.frame assembly at the end — avoids the row-wise rbind
  # pattern that can trip vctrs types when any upstream column is from
  # arrow/tibble (stage_rank had a history of that).
  gene_u <- toupper(as.character(drug_targets$gene))
  genes_uniq <- unique(gene_u)

  n_drugs_vec <- vapply(genes_uniq, function(g) {
    rows <- which(gene_u == g)
    length(unique(as.character(drug_targets$drug_name[rows])[
      !is.na(drug_targets$drug_name[rows])]))
  }, integer(1))

  n_approved_vec <- vapply(genes_uniq, function(g) {
    rows <- which(gene_u == g)
    sum(is_approved_row[rows], na.rm = TRUE)
  }, integer(1))

  max_rank_vec <- vapply(genes_uniq, function(g) {
    rows <- which(gene_u == g)
    mx <- suppressWarnings(max(as.integer(drug_targets$stage_rank[rows]),
                               na.rm = TRUE))
    if (is.infinite(mx)) NA_integer_ else as.integer(mx)
  }, integer(1))

  summary_df <- data.frame(
    gene               = as.character(genes_uniq),
    is_druggable       = rep(TRUE, length(genes_uniq)),
    n_drugs            = as.integer(n_drugs_vec),
    n_approved_drugs   = as.integer(n_approved_vec),
    max_stage_rank     = as.integer(max_rank_vec),
    stringsAsFactors   = FALSE
  )
  summary_df$max_approval_stage <- stage_label_from_rank(summary_df$max_stage_rank)
  rownames(summary_df) <- NULL
  summary_df
}

# Detect network modules/communities
detect_network_modules <- function(ppi_interactions, method = "louvain") {
  print(paste("Detecting network modules using", method, "algorithm..."))
  
  tryCatch({
    if (is.null(ppi_interactions) || nrow(ppi_interactions) == 0) {
      print("❌ No interactions for module detection")
      return(NULL)
    }
    
    # Fix column names if needed
    if (!all(c("gene_from", "gene_to") %in% colnames(ppi_interactions))) {
      if ("protein1" %in% colnames(ppi_interactions)) {
        colnames(ppi_interactions)[colnames(ppi_interactions) == "protein1"] <- "gene_from"
        colnames(ppi_interactions)[colnames(ppi_interactions) == "protein2"] <- "gene_to"
      }
    }
    
    if (!requireNamespace("igraph", quietly = TRUE)) {
      print("❌ igraph package not available")
      return(NULL)
    }
    
    # Create graph
    edges <- ppi_interactions[, c("gene_from", "gene_to")]
    g <- igraph::graph_from_data_frame(edges, directed = FALSE)
    
    # Detect communities
    if (method == "louvain") {
      communities <- igraph::cluster_louvain(g)
    } else if (method == "walktrap") {
      communities <- igraph::cluster_walktrap(g)
    } else {
      communities <- igraph::cluster_fast_greedy(g)
    }
    
    # Create module assignment data frame
    modules_df <- data.frame(
      gene = igraph::V(g)$name,
      module = igraph::membership(communities),
      stringsAsFactors = FALSE
    )
    
    n_modules <- max(modules_df$module)
    print(paste("✅ Detected", n_modules, "modules"))
    
    # Show module sizes
    module_sizes <- table(modules_df$module)
    print("  • Module sizes:")
    for (i in 1:min(5, length(module_sizes))) {
      print(paste("    - Module", names(module_sizes)[i], ":", module_sizes[i], "genes"))
    }
    
    return(list(
      modules = modules_df,
      n_modules = n_modules,
      modularity = igraph::modularity(communities)
    ))
    
  }, error = function(e) {
    print(paste("❌ Module detection failed:", e$message))
    return(NULL)
  })
}


debug_string_response <- function(genes, organism = "human", confidence = 0.4) {
  print("=== STRING API DIAGNOSTIC ===")
  
  species_id <- switch(organism,
                       "human" = 9606, "mouse" = 10090, "rat" = 10116,
                       "zebrafish" = 7955, "fly" = 7227, "worm" = 6239,
                       "yeast" = 4932, 9606)
  
  if (!requireNamespace("httr", quietly = TRUE)) {
    print("httr not available")
    return(NULL)
  }
  
  # Test with a small subset of genes
  test_genes <- head(genes, 10)
  genes_for_api <- paste(test_genes, collapse = "\n")
  
  print(paste("Testing with", length(test_genes), "genes"))
  
  # Step 1: Test mapping endpoint
  print("\n1. Testing STRING mapping endpoint...")
  map_url <- "https://string-db.org/api/tsv/get_string_ids"
  map_response <- httr::POST(
    url = map_url,
    body = list(
      identifiers = genes_for_api,
      species = species_id,
      limit = 1,
      caller_identity = "RNASeqAnalyzer_Debug"
    ),
    encode = "form",
    httr::timeout(30)
  )
  
  if (httr::status_code(map_response) == 200) {
    map_content <- httr::content(map_response, "text", encoding = "UTF-8")
    print("✓ Mapping successful")
    
    # Parse and show structure
    lines <- strsplit(map_content, "\n")[[1]]
    print(paste("  Response has", length(lines), "lines"))
    
    if (length(lines) > 0) {
      print("  Header line:")
      print(paste("   ", lines[1]))
      
      # Parse as data frame to see structure
      tryCatch({
        mapped <- read.delim(text = map_content, stringsAsFactors = FALSE)
        print(paste("  Parsed to data frame with", nrow(mapped), "rows and", ncol(mapped), "columns"))
        print("  Column names:")
        print(paste("   ", paste(colnames(mapped), collapse = ", ")))
        
        if (nrow(mapped) > 0) {
          print("  First row example:")
          print(mapped[1, ])
          
          # Now test network endpoint
          print("\n2. Testing STRING network endpoint...")
          
          # Get STRING IDs for network query
          string_id_col <- if ("stringId" %in% colnames(mapped)) "stringId" else colnames(mapped)[1]
          string_ids <- mapped[[string_id_col]]
          string_ids_for_api <- paste(string_ids, collapse = "\n")
          
          net_url <- "https://string-db.org/api/tsv/network"
          net_response <- httr::POST(
            url = net_url,
            body = list(
              identifiers = string_ids_for_api,
              species = species_id,
              required_score = as.integer(confidence * 1000),
              caller_identity = "RNASeqAnalyzer_Debug"
            ),
            encode = "form",
            httr::timeout(30)
          )
          
          if (httr::status_code(net_response) == 200) {
            net_content <- httr::content(net_response, "text", encoding = "UTF-8")
            print("✓ Network query successful")
            
            # Parse network response
            net_lines <- strsplit(net_content, "\n")[[1]]
            print(paste("  Response has", length(net_lines), "lines"))
            
            if (length(net_lines) > 0) {
              print("  Header line:")
              print(paste("   ", net_lines[1]))
              
              # Parse as data frame
              tryCatch({
                interactions <- read.delim(text = net_content, stringsAsFactors = FALSE)
                print(paste("  Parsed to data frame with", nrow(interactions), "rows and", ncol(interactions), "columns"))
                print("  Column names:")
                print(paste("   ", paste(colnames(interactions), collapse = ", ")))
                
                if (nrow(interactions) > 0) {
                  print("  First interaction example:")
                  print(interactions[1, ])
                  
                  # Check which columns contain the protein IDs
                  print("\n  Checking for protein ID columns:")
                  for (col in colnames(interactions)) {
                    sample_val <- as.character(interactions[[col]][1])
                    if (grepl(paste0("^", species_id), sample_val)) {
                      print(paste("   ", col, "appears to contain STRING IDs:", sample_val))
                    }
                  }
                }
                
              }, error = function(e) {
                print(paste("  Error parsing network response:", e$message))
              })
            }
          } else {
            print(paste("[FAIL] Network query failed with status:", httr::status_code(net_response)))
          }
        }
        
      }, error = function(e) {
        print(paste("  Error parsing mapping response:", e$message))
      })
    }
  } else {
    print(paste("[FAIL] Mapping failed with status:", httr::status_code(map_response)))
  }
  
  print("=== END DIAGNOSTIC ===\n")
}


