identify_drug_targets <- function(gene_list) {
  tryCatch({
    print("========================================")
    print("🔍 DEBUG: Starting Drug Target Identification")
    print(paste("  • Input gene list length:", length(gene_list)))
    print(paste("  • First 10 genes:", paste(head(gene_list, 10), collapse = ", ")))
    
    # Known drug targets (subset for demo)
    known_targets <- data.frame(
      gene = c("TP53", "EGFR", "BRCA1", "KRAS", "MYC", "VEGFA", "ALK", "BRAF", "PIK3CA", "ERBB2"),
      drug_name = c("APR-246", "Erlotinib", "Olaparib", "Sotorasib", "JQ1", "Bevacizumab", "Crizotinib", "Vemurafenib", "Alpelisib", "Trastuzumab"),
      interaction_type = c("activator", "inhibitor", "inhibitor", "inhibitor", "inhibitor", "inhibitor", "inhibitor", "inhibitor", "inhibitor", "inhibitor"),
      source = rep("Literature", 10),
      stringsAsFactors = FALSE
    )
    
    print(paste("  • Known targets database size:", nrow(known_targets)))
    print(paste("  • Known target genes:", paste(known_targets$gene, collapse = ", ")))
    
    # Find matches in user's gene list
    matches <- known_targets[known_targets$gene %in% gene_list, ]
    
    print(paste("  • Matches found:", nrow(matches)))
    if (nrow(matches) > 0) {
      print("  • Matched genes:")
      print(matches$gene)
      print("✅ Drug target search completed")
      print(paste("  • Returning", nrow(matches), "drug-gene interactions"))
      print("  • Structure of returned data:")
      print(str(matches))
      print("========================================")
      return(matches)
    } else {
      print("⚠️ No known drug targets found in this gene set")
      empty_df <- data.frame(
        gene = character(0),
        drug_name = character(0),
        interaction_type = character(0),
        source = character(0),
        stringsAsFactors = FALSE
      )
      print("  • Returning empty dataframe")
      print("  • Structure of empty dataframe:")
      print(str(empty_df))
      print("========================================")
      return(empty_df)
    }
    
  }, error = function(e) {
    print("========================================")
    print(paste("❌ ERROR in Drug target identification:", e$message))
    print("  • Error traceback:")
    print(traceback())
    print("========================================")
    return(data.frame(
      gene = character(0),
      drug_name = character(0),
      interaction_type = character(0),
      source = character(0),
      stringsAsFactors = FALSE
    ))
  })
}



# ============================================================================
# 1. CORE PPI ANALYSIS FUNCTIONS (UPDATED)
# ============================================================================

perform_ppi_analysis_fixed <- function(selected_genes, deg_data, input_params) {
  
  print("🚀 Starting PPI analysis with consolidated functions...")
  
  tryCatch({
    # Extract organism from params
    organism <- input_params$organism %||% "human"
    
    # Step 1: Extract and clean genes
    if (is.null(deg_data)) {
      genes_to_analyze <- selected_genes$all_genes
    } else {
      all_degs <- extract_all_degs_for_ppi(selected_genes, deg_data)
      genes_to_analyze <- all_degs$all_genes
    }
    
    if (length(genes_to_analyze) < 2) {
      return(list(error = "Need at least 2 genes for PPI analysis", analysis_type = "ppi"))
    }
    
    print(paste("📊 Analyzing", length(genes_to_analyze), "genes for organism:", organism))
    
    # Step 2: Query STRING database
    ppi_interactions <- query_string_database_safe(
      genes = genes_to_analyze,
      organism = organism,
      confidence = input_params$confidence_threshold %||% 0.4,
      max_interactions = input_params$max_interactions %||% 1000
    )
    
    if (nrow(ppi_interactions) == 0) {
      return(list(
        error = "No protein interactions found",
        analysis_type = "ppi",
        summary_stats = list(n_nodes = 0, n_edges = 0, coverage_rate = 0)
      ))
    }
    
    print(paste("Found", nrow(ppi_interactions), "interactions"))
    
    # Step 3: Identify Hubs (IMPROVED)
    temp_degs <- list(all_genes = genes_to_analyze, up_genes = character(0), down_genes = character(0))
    hub_proteins <- identify_ppi_hubs_safe(ppi_interactions, temp_degs)
    
    # Step 4: Functional Enrichment
    network_proteins <- unique(c(ppi_interactions$gene_from, ppi_interactions$gene_to))
    
    enrichment_results_raw <- perform_functional_enrichment_safe(
      network_proteins,
      temp_degs,
      organism = organism
    )
    
    # Convert list of enrichment results to single dataframe
    enrichment_results <- NULL
    if (!is.null(enrichment_results_raw) && length(enrichment_results_raw) > 0) {
      enrichment_results <- do.call(rbind, lapply(names(enrichment_results_raw), function(db_name) {
        df <- enrichment_results_raw[[db_name]]
        if (!is.null(df) && is.data.frame(df) && nrow(df) > 0) {
          df$Database <- db_name
          return(df)
        }
        return(NULL)
      }))
      if (!is.null(enrichment_results) && nrow(enrichment_results) > 0) {
        enrichment_results <- enrichment_results[order(enrichment_results$Adjusted.P.value), ]
      }
    }
    
    # Step 5: Visualization Data
    network_data <- fix_ppi_visualization(ppi_interactions, temp_degs, hub_proteins)
    summary_stats <- create_ppi_summary_stats_safe(ppi_interactions, network_data, temp_degs, hub_proteins)
    
    # Count ACTUAL hubs (not all proteins)
    n_actual_hubs <- sum(hub_proteins$hub_type %in% c("Hub", "Major Hub"), na.rm = TRUE)
    
    # Create flattened summary
    summary_flat <- list(
      total_nodes = summary_stats$basic_stats$n_nodes,
      total_edges = summary_stats$basic_stats$n_edges,
      avg_degree = summary_stats$network_metrics$avg_degree,
      density = summary_stats$network_metrics$density,
      n_hubs = n_actual_hubs,  # FIXED: Use actual hub count
      coverage_rate = summary_stats$basic_stats$coverage_rate
    )
    
    # Step 6: Advanced Features
    print("Calculating centrality measures...")
    centrality_measures <- calculate_centrality_measures(ppi_interactions)
    print(paste("✅ Calculated centrality for", nrow(centrality_measures), "proteins"))
    
    # Module Detection
    network_modules_result <- detect_network_modules(ppi_interactions, method = "louvain")
    
    # Module Enrichment
    module_enrichment <- NULL
    if (!is.null(network_modules_result) && !is.null(network_modules_result$modules)) {
      print("Performing module-specific enrichment...")
      unique_modules <- unique(network_modules_result$modules$module)
      module_sizes <- table(network_modules_result$modules$module)
      top_modules <- names(sort(module_sizes, decreasing = TRUE)[1:min(5, length(module_sizes))])
      
      module_enrichment <- list()
      for (module_id in top_modules) {
        module_genes <- network_modules_result$modules$gene[
          network_modules_result$modules$module == module_id
        ]
        
        if (length(module_genes) >= 3) {
          print(paste("Analyzing module", module_id))
          module_enrichment[[paste0("Module_", module_id)]] <- 
            perform_functional_enrichment_safe(module_genes, temp_degs, organism = organism)
        }
      }
    }
    
    # ═══════════════════════════════════════════════════════════════
    # STEP 7: DRUG TARGET QUERY (NEW!)
    # ═══════════════════════════════════════════════════════════════
    drug_targets <- data.frame()
    if (organism == "human") {
      print("💊 Querying drug-gene interaction databases...")
      
      # Ensure genes are converted to symbols for drug databases
      genes_for_drug_query <- network_proteins
      
      # Detect and convert gene IDs if needed
      id_detection <- detect_gene_id_type(genes_for_drug_query)
      print(paste("    • Input ID type detected:", id_detection$id_type, 
                  "(", round(id_detection$confidence * 100), "% confidence)"))
      
      if (id_detection$id_type %in% c("ensembl_gene", "ensembl_transcript", "entrez")) {
        print("    • Converting IDs to gene symbols for drug database queries...")
        conversion_result <- convert_gene_ids_universal(
          genes_for_drug_query, 
          from_type = id_detection$id_type, 
          to_type = "symbol", 
          organism = organism
        )
        genes_for_drug_query <- unique(conversion_result$converted_ids[
          !is.na(conversion_result$converted_ids) & conversion_result$converted_ids != ""
        ])
        print(paste("    • Converted", length(genes_for_drug_query), "genes to symbols"))
      }
      
      drug_targets <- tryCatch({
        query_drug_targets_comprehensive(genes_for_drug_query, organism = organism)
      }, error = function(e) {
        print(paste("  [FAIL] Drug target query error:", e$message))
        data.frame()
      })
    } else {
      print("💊 Drug target query skipped (human-only databases)")
    }
    
    # ═══════════════════════════════════════════════════════════════
    # COMPILE RESULTS
    # ═══════════════════════════════════════════════════════════════
    # Per-gene druggability summary (approval stage, drug counts) built
    # from drug_targets + local OpenTargets drug_molecule lookup.
    druggability_summary <- tryCatch(
      build_druggability_summary(drug_targets),
      error = function(e) {
        print(paste("⚠️ druggability summary failed:", e$message))
        data.frame()
      }
    )

    # Consensus hubs across 8 centrality algorithms (CytoHubba-style)
    hub_consensus <- tryCatch(
      calculate_hub_consensus(centrality_measures, top_n = 10),
      error = function(e) {
        print(paste("⚠️ hub consensus failed:", e$message))
        NULL
      }
    )

    ppi_results <- list(
      network_data = network_data,
      ppi_interactions = ppi_interactions,
      hub_proteins = hub_proteins,
      enrichment_results = enrichment_results,
      functional_enrichment = enrichment_results_raw,  # Also keep raw for module display
      summary_stats = summary_stats,
      summary = summary_flat,
      centrality_measures = centrality_measures,
      hub_consensus = hub_consensus,
      druggability_summary = druggability_summary,
      network_modules = if (!is.null(network_modules_result)) network_modules_result$modules else NULL,
      module_enrichment = module_enrichment,
      drug_targets = drug_targets,  # NEW!
      analysis_params = list(
        organism = organism,
        confidence_threshold = input_params$confidence_threshold,
        n_input_genes = length(genes_to_analyze),
        n_interactions = nrow(ppi_interactions),
        n_proteins = length(network_proteins),
        n_druggable_targets = if(nrow(drug_targets) > 0) length(unique(drug_targets$gene)) else 0,
        database = "STRING + DGIdb + OpenTargets"
      ),
      analysis_type = "ppi"
    )
    
    # ═══════════════════════════════════════════════════════════════
    # COMPLETION MESSAGE (NEW!)
    # ═══════════════════════════════════════════════════════════════
    print("═══════════════════════════════════════════════════════════════")
    print("✅ PPI ANALYSIS COMPLETE!")
    print("═══════════════════════════════════════════════════════════════")
    print(paste("📊 Network: ", summary_flat$total_nodes, "proteins,", 
                summary_flat$total_edges, "interactions"))
    print(paste("🎯 Hubs:", n_actual_hubs, "significant hub proteins"))
    print(paste("🧩 Modules:", length(unique(network_modules_result$modules$module)), "functional clusters"))
    print(paste("🧬 Enrichment:", nrow(enrichment_results %||% data.frame()), "significant pathways"))
    print(paste("💊 Drugs:", nrow(drug_targets), "drug-gene interactions"))
    print("═══════════════════════════════════════════════════════════════")
    
    return(ppi_results)
    
  }, error = function(e) {
    print(paste("❌ PPI analysis error:", e$message))
    return(list(error = e$message, analysis_type = "ppi"))
  })
}


perform_ppi_analysis_all_degs <- function(deg_data, input_params) {
  
  print("🧬 Starting PPI Analysis with ALL DEGs...")
  
  # USE THE PARAMETERS PASSED IN, NOT HARDCODED VALUES
  p_val_threshold <- input_params$p_val_threshold %||% 0.05
  log2fc_min <- input_params$log2fc_min %||% -2
  log2fc_max <- input_params$log2fc_max %||% 2
  pvalue_type <- input_params$pvalue_type %||% "adjusted"
  
  print(paste("Using parameters from main analysis:"))
  print(paste("  P-value threshold:", p_val_threshold))
  print(paste("  Log2FC range:", log2fc_min, "to", log2fc_max))
  
  # Get p-value column
  pval_col <- if(pvalue_type == "adjusted") "adj.P.Val" else "P.Value"
  
  # Apply SAME filtering as main selection
  significant_degs <- deg_data[
    !is.na(deg_data[[pval_col]]) &
      deg_data[[pval_col]] < p_val_threshold &
      !is.na(deg_data$log2FC) &
      (deg_data$log2FC < log2fc_min | deg_data$log2FC > log2fc_max),
  ]
  
  print(paste("Found", nrow(significant_degs), "significant DEGs"))
  
  # ========== FIX #1: Variable name correction ==========
  # You had 'sig_degs' but the variable is 'significant_degs'
  # Extract gene IDs
  if ("gene_symbol" %in% colnames(significant_degs)) {  # FIXED: was sig_degs
    gene_ids <- significant_degs$gene_symbol
  } else if ("gene_id" %in% colnames(significant_degs)) {  # FIXED: was sig_degs
    gene_ids <- significant_degs$gene_id
  } else {
    gene_ids <- rownames(significant_degs)  # FIXED: was sig_degs
  }
  
  # Clean gene IDs
  gene_ids <- gsub("\\..*$", "", gene_ids)
  
  # ========== FIX #2: Use correct column name and thresholds ==========
  # You had 'fc_col' which was undefined, should be 'log2FC'
  # Also, separation should be based on the thresholds, not 0
  up_genes <- gene_ids[significant_degs$log2FC > log2fc_max]  # FIXED: was sig_degs[[fc_col]] > 0
  down_genes <- gene_ids[significant_degs$log2FC < log2fc_min]  # FIXED: was sig_degs[[fc_col]] < 0
  all_genes <- unique(gene_ids)
  
  # Remove non-coding RNAs
  non_coding_pattern <- "^LINC|^MIR|^SNOR|^RNA[0-9]|^RNU|^SNHG"
  all_genes <- all_genes[!grepl(non_coding_pattern, all_genes)]
  up_genes <- up_genes[!grepl(non_coding_pattern, up_genes)]
  down_genes <- down_genes[!grepl(non_coding_pattern, down_genes)]
  
  print(paste("Analyzing", length(all_genes), "protein-coding DEGs"))
  print(paste("  • Up-regulated:", length(up_genes)))
  print(paste("  • Down-regulated:", length(down_genes)))
  
  # ========== FIX #3: Check if functions exist before calling ==========
  # Query STRING (with error handling)
  ppi_data <- tryCatch({
    if (exists("query_string_safe") && is.function(query_string_safe)) {
      query_string_safe(
        genes = all_genes,
        organism = input_params$organism %||% "human",
        confidence = input_params$confidence_threshold %||% 0.4
      )
    } else {
      # Fallback if function doesn't exist
      print("WARNING: query_string_safe function not found, using mock data")
      list(
        interactions = data.frame(),
        mapping = data.frame(gene = all_genes, STRING_id = paste0("9606.", all_genes)),
        mapping_rate = 0.5
      )
    }
  }, error = function(e) {
    print(paste("Error querying STRING:", e$message))
    list(error = e$message)
  })
  
  # ========== FIX #4: Build network with error handling ==========
  network_results <- tryCatch({
    if (exists("build_network_safe") && is.function(build_network_safe)) {
      build_network_safe(ppi_data, up_genes, down_genes)
    } else {
      # Fallback network structure
      print("WARNING: build_network_safe function not found, creating basic structure")
      list(
        network_data = list(
          nodes = data.frame(
            id = all_genes[1:min(length(all_genes), 100)],
            label = all_genes[1:min(length(all_genes), 100)],
            group = ifelse(all_genes[1:min(length(all_genes), 100)] %in% up_genes, "up",
                           ifelse(all_genes[1:min(length(all_genes), 100)] %in% down_genes, "down", "other"))
          ),
          edges = data.frame()
        ),
        ppi_interactions = ppi_data$interactions %||% data.frame(),
        network_metrics = list(
          n_nodes = length(all_genes),
          n_edges = 0
        ),
        hub_proteins = data.frame(),
        summary_stats = list(
          n_nodes = length(all_genes),
          n_edges = 0,
          n_up = length(up_genes),
          n_down = length(down_genes)
        ),
        selected_genes = list(
          all_genes = all_genes,
          up_genes = up_genes,
          down_genes = down_genes,
          n_total = length(all_genes),
          n_up = length(up_genes),
          n_down = length(down_genes)
        ),
        analysis_type = "ppi"
      )
    }
  }, error = function(e) {
    print(paste("Error building network:", e$message))
    list(error = e$message)
  })
  
  # ========== FIX #5: Ensure proper return structure ==========
  # Add analysis metadata if not present
  if (!is.null(network_results) && is.list(network_results) && is.null(network_results$error)) {
    if (is.null(network_results$selected_genes)) {
      network_results$selected_genes <- list(
        all_genes = all_genes,
        up_genes = up_genes,
        down_genes = down_genes,
        n_total = length(all_genes),
        n_up = length(up_genes),
        n_down = length(down_genes)
      )
    }
    if (is.null(network_results$analysis_type)) {
      network_results$analysis_type <- "ppi"
    }
  }
  
  return(network_results)
}

# Safe STRING query function
if (!exists("query_string_safe")) {
  query_string_safe <- function(genes, organism = "human", confidence = 0.4) {
    
    print("🔍 Querying STRING database...")
    
    # Map organism names to STRING taxonomy IDs
    organism_map <- list(
      human = 9606,
      mouse = 10090,
      rat = 10116,
      fly = 7227,
      zebrafish = 7955,
      yeast = 4932
    )
    
    species_id <- organism_map[[tolower(organism)]] %||% 9606
    
    tryCatch({
      # Check if STRINGdb is available
      if (requireNamespace("STRINGdb", quietly = TRUE)) {
        # Initialize STRING database connection
        string_db <- STRINGdb::STRINGdb$new(
          version = "11.5",
          species = species_id,
          score_threshold = confidence * 1000
        )
        
        # Map genes to STRING IDs
        mapped_genes <- string_db$map(
          data.frame(gene = genes),
          "gene",
          removeUnmappedRows = FALSE
        )
        
        # Get interactions
        interactions <- string_db$get_interactions(mapped_genes$STRING_id[!is.na(mapped_genes$STRING_id)])
        
        return(list(
          interactions = interactions,
          mapping = mapped_genes,
          mapping_rate = sum(!is.na(mapped_genes$STRING_id)) / length(genes),
          n_interactions = nrow(interactions),
          source = "STRINGdb"
        ))
        
      } else {
        print("STRINGdb package not available, using mock data")
        return(list(
          interactions = data.frame(),
          mapping = data.frame(gene = genes, STRING_id = paste0(species_id, ".", genes)),
          mapping_rate = 0.5,
          n_interactions = 0,
          source = "mock"
        ))
      }
    }, error = function(e) {
      print(paste("Error in STRING query:", e$message))
      return(list(
        error = e$message,
        interactions = data.frame(),
        mapping = data.frame()
      ))
    })
  }
}

# Safe network building function
if (!exists("build_network_safe")) {
  build_network_safe <- function(ppi_data, up_genes, down_genes) {
    
    print("Building network from PPI data...")
    
    tryCatch({
      # Check if ppi_data has error
      if (!is.null(ppi_data$error)) {
        return(list(error = ppi_data$error))
      }
      
      interactions <- ppi_data$interactions %||% data.frame()
      
      if (nrow(interactions) == 0) {
        print("No interactions found")
        all_genes <- unique(c(up_genes, down_genes))
        
        return(list(
          network_data = list(
            nodes = data.frame(
              id = all_genes[1:min(length(all_genes), 50)],
              label = all_genes[1:min(length(all_genes), 50)],
              group = ifelse(all_genes[1:min(length(all_genes), 50)] %in% up_genes, "up", "down")
            ),
            edges = data.frame()
          ),
          ppi_interactions = data.frame(),
          network_metrics = list(n_nodes = length(all_genes), n_edges = 0),
          hub_proteins = data.frame(),
          summary_stats = list(
            n_nodes = length(all_genes),
            n_edges = 0,
            n_up = length(up_genes),
            n_down = length(down_genes)
          )
        ))
      }
      
      # Extract unique nodes from interactions
      all_nodes <- unique(c(interactions$from, interactions$to))
      
      # Create node data frame
      nodes_df <- data.frame(
        id = all_nodes,
        label = all_nodes,
        group = ifelse(all_nodes %in% up_genes, "up",
                       ifelse(all_nodes %in% down_genes, "down", "network")),
        stringsAsFactors = FALSE
      )
      
      # Create edges data frame
      edges_df <- data.frame(
        from = interactions$from,
        to = interactions$to,
        weight = interactions$combined_score %||% rep(1, nrow(interactions))
      )
      
      print(paste("Network built:", nrow(nodes_df), "nodes,", nrow(edges_df), "edges"))
      print(paste("Node distribution - Up:", sum(nodes_df$group == "up"),
                  "Down:", sum(nodes_df$group == "down"),
                  "Network:", sum(nodes_df$group == "network")))
      
      return(list(
        network_data = list(
          nodes = nodes_df,
          edges = edges_df
        ),
        ppi_interactions = interactions,
        network_metrics = list(
          n_nodes = nrow(nodes_df),
          n_edges = nrow(edges_df),
          density = 2 * nrow(edges_df) / (nrow(nodes_df) * (nrow(nodes_df) - 1))
        ),
        hub_proteins = head(nodes_df[order(table(c(edges_df$from, edges_df$to)), decreasing = TRUE), ], 10),
        summary_stats = list(
          n_nodes = nrow(nodes_df),
          n_edges = nrow(edges_df),
          n_up = sum(nodes_df$group == "up"),
          n_down = sum(nodes_df$group == "down"),
          n_network = sum(nodes_df$group == "network")
        )
      ))
      
    }, error = function(e) {
      print(paste("Error building network:", e$message))
      return(list(error = e$message))
    })
  }
}


build_network_safe <- function(ppi_data, up_genes, down_genes) {
  
  if (is.null(ppi_data$interactions) || nrow(ppi_data$interactions) == 0) {
    return(create_empty_ppi_results("No interactions found"))
  }
  
  interactions <- ppi_data$interactions
  
  # Get all proteins in network
  all_proteins <- unique(c(interactions$gene_from, interactions$gene_to))
  
  # Create nodes with proper categorization
  nodes <- data.frame(
    id = all_proteins,
    label = all_proteins,
    stringsAsFactors = FALSE
  )
  
  # FIXED: Proper group assignment
  nodes$group <- ifelse(
    nodes$id %in% up_genes, "Up-regulated",
    ifelse(nodes$id %in% down_genes, "Down-regulated", "Network")
  )
  
  # Calculate degree
  degree_counts <- table(c(interactions$gene_from, interactions$gene_to))
  nodes$degree <- degree_counts[nodes$id]
  nodes$degree[is.na(nodes$degree)] <- 0
  
  # Set visual properties
  nodes$size <- 15 + sqrt(nodes$degree) * 5
  nodes$color <- ifelse(
    nodes$group == "Up-regulated", "#E74C3C",
    ifelse(nodes$group == "Down-regulated", "#3498DB", "#95A5A6")
  )
  
  # Create edges
  edges <- data.frame(
    from = interactions$gene_from,
    to = interactions$gene_to,
    weight = interactions$combined_score %||% 0.5,
    stringsAsFactors = FALSE
  )
  
  # Calculate metrics
  n_nodes <- nrow(nodes)
  n_edges <- nrow(edges)
  
  # Identify hubs
  hub_threshold <- quantile(nodes$degree, 0.9)
  hub_proteins <- nodes[nodes$degree >= hub_threshold, ]
  
  print(paste("Network built:", n_nodes, "nodes,", n_edges, "edges"))
  print(paste("Node distribution - Up:", sum(nodes$group == "Up-regulated"),
              "Down:", sum(nodes$group == "Down-regulated"),
              "Network:", sum(nodes$group == "Network")))
  
  # Return complete results
  return(list(
    network_data = list(
      nodes = nodes,
      edges = edges
    ),
    ppi_interactions = interactions,
    network_metrics = list(
      global_metrics = list(
        n_nodes = n_nodes,
        n_edges = n_edges,
        density = if (n_nodes > 1) 2 * n_edges / (n_nodes * (n_nodes - 1)) else 0,
        avg_degree = if (n_nodes > 0) 2 * n_edges / n_nodes else 0
      ),
      node_metrics = data.frame(
        protein = nodes$id,
        degree = nodes$degree,
        stringsAsFactors = FALSE
      )
    ),
    hub_proteins = hub_proteins,
    summary_stats = list(
      n_nodes = n_nodes,
      n_edges = n_edges,
      n_up_regulated = sum(nodes$group == "Up-regulated"),
      n_down_regulated = sum(nodes$group == "Down-regulated"),
      total_degs = length(up_genes) + length(down_genes),
      coverage_rate = round(sum(nodes$group != "Network") /
                              (length(up_genes) + length(down_genes)) * 100, 1),
      density = if (n_nodes > 1) 2 * n_edges / (n_nodes * (n_nodes - 1)) else 0,
      avg_degree = if (n_nodes > 0) 2 * n_edges / n_nodes else 0
    ),
    analysis_type = "ppi",
    analysis_params = list(
      mapping_rate = ppi_data$mapping_rate %||% 0
    )
  ))
}

# Helper functions
convert_string_ids <- function(interactions, mapped_genes) {
  # Create ID to gene mapping
  id_to_gene <- setNames(mapped_genes$gene, mapped_genes$STRING_id)
  
  # Convert interactions with explicit cleaning regex
  data.frame(
    gene_from = ifelse(
      interactions$from %in% names(id_to_gene),
      id_to_gene[interactions$from],
      gsub("^[0-9]+\\.", "", interactions$from) # Strip TaxID prefix
    ),
    gene_to = ifelse(
      interactions$to %in% names(id_to_gene),
      id_to_gene[interactions$to],
      gsub("^[0-9]+\\.", "", interactions$to) # Strip TaxID prefix
    ),
    combined_score = interactions$combined_score / 1000,
    stringsAsFactors = FALSE
  ) %>%
    filter(!is.na(gene_from) & !is.na(gene_to) & gene_from != gene_to)
}

create_mock_ppi_data <- function(genes) {
