      n_nodes = 0, n_edges = 0,
      n_up_regulated = 0, n_down_regulated = 0,
      total_degs = 0, coverage_rate = 0,
      density = 0, avg_degree = 0
    ),
    analysis_type = "ppi",
    error = message
  )
}

# Comprehensive STRING query function for PPI analysis
query_string_comprehensive <- function(genes, organism = "human", confidence = 0.4, network_type = "physical") {
  
  print("🔍 Querying STRING database (comprehensive mode)...")
  
  # Map organism to species ID
  species_id <- switch(tolower(organism),
                       "human" = 9606,
                       "homo sapiens" = 9606,
                       "mouse" = 10090,
                       "mus musculus" = 10090,
                       "rat" = 10116,
                       "rattus norvegicus" = 10116,
                       "zebrafish" = 7955,
                       "danio rerio" = 7955,
                       "fly" = 7227,
                       "drosophila" = 7227,
                       "drosophila melanogaster" = 7227,
                       "worm" = 6239,
                       "c. elegans" = 6239,
                       "caenorhabditis elegans" = 6239,
                       "yeast" = 4932,
                       "saccharomyces cerevisiae" = 4932,
                       "pig" = 9823,
                       "sus scrofa" = 9823,
                       "chicken" = 9031,
                       "gallus gallus" = 9031,
                       "cow" = 9913,
                       "bos taurus" = 9913,
                       "arabidopsis" = 3702,
                       "arabidopsis thaliana" = 3702,
                       # If already numeric, use as-is
                       as.numeric(organism)
  )
  
  print(paste("  • Organism:", organism, "→ Species ID:", species_id))
  print(paste("  • Confidence threshold:", confidence))
  print(paste("  • Network type:", network_type))
  print(paste("  • Input genes:", length(genes)))
  
  # Use the existing query_string_database_safe function
  result <- query_string_database_safe(
    genes = genes,
    organism = organism,
    confidence = confidence,
    max_interactions = 2000
  )
  
  return(result)
}

# Functional enrichment specifically for PPI analysis
perform_functional_enrichment_ppi <- function(all_proteins, all_degs) {
  
  print("🧬 Performing functional enrichment for PPI network...")
  
  # Use the existing safe enrichment function
  result <- perform_functional_enrichment_safe(all_proteins, all_degs)
  
  return(result)
}

# MAIN PPI ANALYSIS FUNCTION - COMPREHENSIVE VERSION
perform_comprehensive_ppi_analysis <- function(selected_genes, deg_data, input_params) {
  
  print("🧬 Starting Comprehensive PPI Analysis (STRING-style)...")
  
  # Use tryCatch for better error handling
  tryCatch({
    
    # Extract ALL DEGs (not just top genes)
    all_degs <- extract_all_degs_for_ppi(selected_genes, deg_data)
    
    if (length(all_degs$all_genes) < 2) {
      return(create_empty_ppi_results_comprehensive("Need at least 2 genes for analysis"))
    }
    
    print(paste("📊 Analyzing", length(all_degs$all_genes), "DEGs"))
    print(paste("  •", length(all_degs$up_genes), "up-regulated"))
    print(paste("  •", length(all_degs$down_genes), "down-regulated"))
    
    # Step 1: Query STRING database
    ppi_data <- query_string_comprehensive(
      genes = all_degs$all_genes,
      organism = input_params$organism %||% "human",
      confidence = input_params$confidence_threshold %||% 0.4,
      network_type = input_params$network_type %||% "physical"
    )
    
    # Step 2: Build comprehensive network
    network_analysis <- build_comprehensive_network(ppi_data, all_degs)
    
    # Step 3: Perform functional enrichment (optional)
    functional_analysis <- if (input_params$run_enrichment %||% TRUE) {
      perform_functional_enrichment_ppi(network_analysis$all_proteins, all_degs)
    } else {
      list()
    }
    
    # Step 4: Identify network modules/clusters (optional)
    network_modules <- if (input_params$detect_modules %||% TRUE) {
      identify_network_modules(network_analysis$graph)
    } else {
      list()
    }
    
    # Step 5: Calculate comprehensive statistics
    comprehensive_stats <- calculate_comprehensive_stats(network_analysis, all_degs, functional_analysis)
    
    # Step 6: Create visualizations
    visualizations <- create_comprehensive_visualizations(network_analysis, all_degs, network_modules)
    
    # CRITICAL FIX: Ensure ppi_interactions matches network_data edges
    ppi_interactions <- if (!is.null(visualizations$network_data$edges) &&
                            nrow(visualizations$network_data$edges) > 0) {
      data.frame(
        gene_from = visualizations$network_data$edges$from,
        gene_to = visualizations$network_data$edges$to,
        combined_score = visualizations$network_data$edges$weight %||% 0.5,
        stringsAsFactors = FALSE
      )
    } else {
      data.frame(
        gene_from = character(0),
        gene_to = character(0),
        combined_score = numeric(0),
        stringsAsFactors = FALSE
      )
    }
    
    # Compile results
    results <- list(
      # Core network data
      network_data = visualizations$network_data,
      ppi_interactions = ppi_interactions,
      
      # Network analysis
      network_metrics = network_analysis$metrics,
      hub_proteins = network_analysis$hubs,
      network_modules = network_modules,
      
      # Functional analysis
      functional_enrichment = functional_analysis,
      
      # Statistics
      summary_stats = comprehensive_stats,
      
      # Analysis metadata
      analysis_params = list(
        organism = input_params$organism %||% "human",
        confidence_threshold = input_params$confidence_threshold %||% 0.4,
        n_input_genes = length(all_degs$all_genes),
        n_up_regulated = length(all_degs$up_genes),
        n_down_regulated = length(all_degs$down_genes),
        analysis_date = Sys.Date()
      ),
      
      analysis_type = "ppi",
      selected_genes = all_degs
    )
    
    results$analysis_type <- "ppi"
    print("✅ Comprehensive PPI analysis completed!")
    return(results)
    
  }, error = function(e) {
    print(paste("❌ PPI Analysis Error:", e$message))
    print("Traceback:")
    print(traceback())
    
    # Return empty results with error message
    return(create_empty_ppi_results_comprehensive(paste("Analysis failed:", e$message)))
  })
}

extract_degs_consistent_with_main <- function(deg_data, input_params) {
  
  print("🎯 EXTRACTING DEGs WITH CONSISTENT FILTERING...")
  
  # Use the SAME parameters as your main DEG analysis
  pvalue_type <- input_params$pvalue_type_main %||% "adjusted"  # Get from main UI
  p_val_threshold <- input_params$p_val_threshold_main %||% 0.05
  log2fc_min <- input_params$log2fc_min_main %||% -2
  log2fc_max <- input_params$log2fc_max_main %||% 2
  
  print(paste("Using same parameters as main DEG analysis:"))
  print(paste("  • P-value type:", pvalue_type))
  print(paste("  • P-value threshold:", p_val_threshold))
  print(paste("  • Log2FC range: [", log2fc_min, ",", log2fc_max, "]"))
  
  # Get p-value column based on type (same logic as main analysis)
  if (pvalue_type == "adjusted") {
    pval_col <- "adj.P.Val"
    print("  • Using adjusted p-values (adj.P.Val)")
  } else {
    pval_col <- "P.Value"
    print("  • Using raw p-values (P.Value)")
  }
  
  # Apply EXACT same filtering as main DEG analysis
  significant_genes <- deg_data[
    !is.na(deg_data[[pval_col]]) &
      deg_data[[pval_col]] < p_val_threshold &
      !is.na(deg_data$log2FC) &
      (deg_data$log2FC < log2fc_min | deg_data$log2FC > log2fc_max),
  ]
  
  print(paste("✅ Found", nrow(significant_genes), "significant DEGs (should match main analysis!)"))
  
  # Get gene identifiers
  gene_ids <- if ("gene_id" %in% colnames(significant_genes)) {
    significant_genes$gene_id
  } else {
    rownames(significant_genes)
  }
  
  # Remove version numbers from Ensembl IDs
  gene_ids <- gsub("\\..*$", "", gene_ids)
  
  # Filter out non-coding RNAs (keep this filter)
  non_coding_pattern <- "^LINC|^MIR|^SNOR|^RNA[0-9]|^RNU|^SNHG|^MALAT|^NEAT|^XIST|^HOTAIR"
  is_protein_coding <- !grepl(non_coding_pattern, gene_ids, ignore.case = TRUE)
  
  protein_coding_genes <- significant_genes[is_protein_coding, ]
  gene_ids_filtered <- gene_ids[is_protein_coding]
  
  # Separate up and down regulated
  up_genes <- gene_ids_filtered[protein_coding_genes$log2FC > 0]
  down_genes <- gene_ids_filtered[protein_coding_genes$log2FC < 0]
  
  print(paste("After filtering non-coding RNAs:"))
  print(paste("  • Protein-coding genes:", length(gene_ids_filtered)))
  print(paste("  • Up-regulated:", length(up_genes)))
  print(paste("  • Down-regulated:", length(down_genes)))
  print(paste("  • Filtered out non-coding:", sum(!is_protein_coding)))
  
  # Validate results
  expected_total <- length(up_genes) + length(down_genes)
  if (expected_total != length(gene_ids_filtered)) {
    print("⚠️ Warning: Gene count mismatch detected")
  }
  
  return(list(
    all_genes = gene_ids_filtered,
    up_genes = up_genes,
    down_genes = down_genes,
    n_total = length(gene_ids_filtered),
    n_up = length(up_genes),
    n_down = length(down_genes),
    n_significant_before_filtering = nrow(significant_genes),
    n_filtered_noncoding = sum(!is_protein_coding),
    filtering_parameters = list(
      pvalue_type = pvalue_type,
      pval_column = pval_col,
      p_val_threshold = p_val_threshold,
      log2fc_min = log2fc_min,
      log2fc_max = log2fc_max
    )
  ))
}

clean_gene_names_for_ppi <- function(genes) {
  if (is.null(genes) || length(genes) == 0) {
    return(character(0))
  }
  
  # Convert to character and clean
  genes <- as.character(genes)
  genes <- trimws(genes)
  genes <- genes[!is.na(genes) & genes != "" & genes != "NA" & genes != "-"]
  
  # Remove any remaining Ensembl IDs
  genes <- genes[!grepl("^ENS[GT][0-9]+", genes)]
  
  # Remove numeric-only IDs (likely Entrez)
  genes <- genes[!grepl("^[0-9]+$", genes)]
  
  # Remove non-coding RNA identifiers
  non_coding_pattern <- "^(LINC|MIR|SNOR|RNU|SNHG|MALAT|NEAT|XIST|HOTAIR|LOC[0-9]+|AC[0-9]+\\.|AL[0-9]+\\.)"
  genes <- genes[!grepl(non_coding_pattern, genes, ignore.case = TRUE)]
  
  # Remove version numbers
  genes <- gsub("\\.\\d+$", "", genes)
  
  # Remove duplicates
  genes <- unique(genes)
  
  cat("PPI gene cleaning: ", length(genes), "final genes\n")
  return(genes)
}
