  print(paste("ENST IDs:", sum(enst_mask)))
  print(paste("ENSG IDs:", sum(ensg_mask)))
  print(paste("Entrez IDs:", sum(entrez_mask)))
  print(paste("Presumed symbols:", sum(!enst_mask & !ensg_mask & !entrez_mask)))
  
  if (any(enst_mask)) {
    print("\nENST examples:")
