# Extract ALL DEGs (not just top genes)
extract_all_degs_for_ppi <- function(selected_genes, deg_data) {
  print("Extracting DEGs for PPI analysis...")
  
  # Get all genes
  all_genes <- selected_genes$all_genes %||% character(0)
  up_genes <- selected_genes$up_genes %||% character(0)
  down_genes <- selected_genes$down_genes %||% character(0)
  
  print("=== DEBUG: Before cleaning ===")
  print(paste("Type of all_genes:", typeof(all_genes)))
  print(paste("Length of all_genes:", length(all_genes)))
  if (length(all_genes) > 0) {
    print(paste("First element:", all_genes[1]))
    if (length(all_genes) > 1) {
      print(paste("Second element (if exists):", all_genes[2]))
    }
  }
  print("==============================")
  
  # Identify which genes need conversion
  needs_conversion <- grepl("^ENST[0-9]+|^ENSG[0-9]+|^[0-9]+$", all_genes)
  
  if (any(needs_conversion)) {
    print(paste("🔄 Found", sum(needs_conversion), "IDs that need conversion"))
    
    # Show what we're converting
    ids_to_convert <- all_genes[needs_conversion]
    print("Examples of IDs to convert:")
    print(head(ids_to_convert, 5))
    
    # Try conversion using your function
    conversion_result <- tryCatch({
      convert_gene_ids_to_symbols_deg(
        gene_ids = all_genes,  # Pass all genes
        organism = "human"
      )
    }, error = function(e) {
      print(paste("❌ Conversion function error:", e$message))
      NULL
    })
    
    if (!is.null(conversion_result) && is.data.frame(conversion_result)) {
      print(paste("✅ Received conversion results for", nrow(conversion_result), "genes"))
      
      # Debug: Show structure of conversion result
      print("Conversion result structure:")
      print(str(conversion_result))
      if (nrow(conversion_result) > 0) {
        print("First few rows of conversion result:")
        print(head(conversion_result, 3))
      }
      
      # Apply conversions - handle the specific structure of your conversion function
      for (i in seq_along(all_genes)) {
        orig_id <- all_genes[i]
        
        # Find this ID in the conversion results
        match_row <- which(conversion_result$original_id == orig_id)
        
        if (length(match_row) > 0) {
          converted_symbol <- conversion_result$gene_symbol[match_row[1]]
          
          # Only update if we got a valid symbol (not "-" or empty)
          if (!is.na(converted_symbol) && converted_symbol != "" && converted_symbol != "-") {
            print(paste("  Converting:", orig_id, "→", converted_symbol))
            
            # Update all_genes
            all_genes[i] <- converted_symbol
            
            # Update up/down genes if needed
            if (orig_id %in% up_genes) {
              up_genes[up_genes == orig_id] <- converted_symbol
            }
            if (orig_id %in% down_genes) {
              down_genes[down_genes == orig_id] <- converted_symbol
            }
          }
        }
      }
    }
    
    # Alternative: Manual ENST conversion if the above didn't work
    remaining_enst <- grep("^ENST[0-9]+", all_genes)
    if (length(remaining_enst) > 0) {
      print(paste("⚠️ Still have", length(remaining_enst), "unconverted ENST IDs"))
      print("Removing unconverted ENST IDs...")
      
      enst_to_remove <- all_genes[remaining_enst]
      all_genes <- all_genes[-remaining_enst]
      up_genes <- up_genes[!up_genes %in% enst_to_remove]
      down_genes <- down_genes[!down_genes %in% enst_to_remove]
    }
  }
  
  # Clean gene names
  all_genes <- clean_gene_names_for_ppi(all_genes)
  up_genes <- clean_gene_names_for_ppi(up_genes)
  down_genes <- clean_gene_names_for_ppi(down_genes)
  
  # Ensure up/down genes are subsets of all_genes
  up_genes <- intersect(up_genes, all_genes)
  down_genes <- intersect(down_genes, all_genes)
  
  print(paste("Final gene counts - Total:", length(all_genes), 
              "Up:", length(up_genes), "Down:", length(down_genes)))
  
  return(list(
    all_genes = all_genes,
    up_genes = up_genes,
    down_genes = down_genes
  ))
}

# Helper function for ENST conversion using biomaRt
convert_enst_to_symbols_biomart <- function(enst_ids) {
  # Remove version numbers
  enst_ids_clean <- gsub("\\..*$", "", enst_ids)
  
  # Try multiple BioMart mirrors
  marts_to_try <- list(
    list(function() biomaRt::useMart("ensembl", dataset = "hsapiens_gene_ensembl"), "Standard"),
    list(function() biomaRt::useEnsembl("ensembl", dataset = "hsapiens_gene_ensembl", host = "useast.ensembl.org"), "US East"),
    list(function() biomaRt::useEnsembl("ensembl", dataset = "hsapiens_gene_ensembl", host = "uswest.ensembl.org"), "US West"),
    list(function() biomaRt::useEnsembl("ensembl", dataset = "hsapiens_gene_ensembl", host = "https://dec2021.archive.ensembl.org"), "Archive")
  )
  
  mart <- NULL
  for (mart_info in marts_to_try) {
    tryCatch({
      print(paste("  • Trying BioMart mirror:", mart_info[[2]]))
      mart <- mart_info[[1]]()
      print(paste(" [OK] Connected to:", mart_info[[2]]))
      break
    }, error = function(e) {
      print(paste("  [FAIL] Failed:", mart_info[[2]], "-", e$message))
    })
  }
  
  if (is.null(mart)) {
    print("  [FAIL] Could not connect to any BioMart mirror")
    return(rep(NA, length(enst_ids)))
  }
  
  # Query BioMart
  tryCatch({
    result <- biomaRt::getBM(
      attributes = c("ensembl_transcript_id", "external_gene_name", "gene_biotype"),
      filters = "ensembl_transcript_id",
      values = enst_ids_clean,
      mart = mart
    )
    
    if (nrow(result) == 0) {
      print("  ⚠️ No results from BioMart")
      return(rep(NA, length(enst_ids)))
    }
    
    # Show what we found
    print(paste(" [OK] BioMart returned", nrow(result), "mappings"))
    
    # Create output vector
    converted <- character(length(enst_ids))
    
    for (i in seq_along(enst_ids_clean)) {
      match_idx <- which(result$ensembl_transcript_id == enst_ids_clean[i])
      if (length(match_idx) > 0) {
        gene_name <- result$external_gene_name[match_idx[1]]
        biotype <- result$gene_biotype[match_idx[1]]
        
        # Only use protein-coding genes
        if (!is.na(gene_name) && gene_name != "" && 
            (is.na(biotype) || biotype == "protein_coding")) {
          converted[i] <- gene_name
        } else {
          converted[i] <- NA
        }
      } else {
        converted[i] <- NA
      }
    }
    
    # Summary
    n_converted <- sum(!is.na(converted))
    print(paste(" [OK] Successfully converted", n_converted, "of", length(enst_ids), "ENST IDs"))
    
    return(converted)
    
  }, error = function(e) {
    print(paste("  [FAIL] BioMart query failed:", e$message))
    return(rep(NA, length(enst_ids)))
  })
}

# Clean gene list - remove non-coding RNAs
clean_gene_list_for_ppi <- function(genes) {
  
  if (is.null(genes) || length(genes) == 0) {
    return(character(0))
  }
  
  # Convert to character to be safe
  genes <- as.character(genes)
  genes <- genes[!is.na(genes) & genes != "" & genes != "NA"]
  genes <- trimws(genes)
  genes <- genes[genes != ""]
  genes <- unique(genes)
  
  # Optional: for human only, filter non-coding (but don't break yeast!)
  if (any(grepl("^(ENSG|LINC|MIR|SNOR)", genes))) {
    non_coding_pattern <- "^(LINC|MIR|SNOR|RNU|SNHG|MALAT|NEAT|XIST|HOTAIR)"
    genes <- genes[!grepl(non_coding_pattern, genes, ignore.case = TRUE)]
  }
  
  cat("PPI gene cleaning: ", length(genes), "final genes\n")
  return(genes)
}

# STRING database query - uses local data for human/mouse, API for other species
# STRING lists every interaction in both directions (A-B and B-A). Return one row per
# unordered protein pair (highest combined_score) without self-loops, so every PPI path
# (standalone and Advanced Analysis) works on a simple undirected network.
tx_dedup_ppi <- function(df) {
  if (is.null(df) || !is.data.frame(df) || nrow(df) == 0 ||
      !all(c("gene_from", "gene_to") %in% names(df))) return(df)
  a <- as.character(df$gene_from); b <- as.character(df$gene_to)
  keep <- !is.na(a) & !is.na(b) & a != b
  df <- df[keep, , drop = FALSE]; a <- a[keep]; b <- b[keep]
  key <- ifelse(a < b, paste(a, b, sep = "|"), paste(b, a, sep = "|"))
  ord <- if ("combined_score" %in% names(df)) order(-df$combined_score) else seq_len(nrow(df))
  df <- df[ord, , drop = FALSE][!duplicated(key[ord]), , drop = FALSE]
  rownames(df) <- NULL
  df
}

query_string_database_safe <- function(...) tx_dedup_ppi(query_string_database_safe_raw(...))

query_string_database_safe_raw <- function(genes, organism = "human", confidence = 0.4, max_interactions = 1000, network_type = "full") {

  print("Querying STRING database...")

  # Define species ID — support named organisms AND numeric taxonomy IDs
  if (grepl("^[0-9]+$", as.character(organism))) {
    species_id <- as.integer(organism)
  } else {
    species_id <- switch(tolower(organism),
                         "human" = 9606, "homo sapiens" = 9606,
                         "mouse" = 10090, "mus musculus" = 10090,
                         "rat" = 10116, "zebrafish" = 7955,
                         "fly" = 7227, "worm" = 6239,
                         "yeast" = 4932, "pig" = 9823,
                         "chicken" = 9031, "bovine" = 9913,
                         "arabidopsis" = 3702, 9606)
  }

  genes <- unique(trimws(genes))
  genes <- genes[genes != "" & !is.na(genes)]

  if (length(genes) < 2) {
    print("Need at least 2 genes for PPI analysis")
    return(data.frame(gene_from = character(), gene_to = character(), combined_score = numeric()))
  }

  # --- CHECK FOR LOCAL STRING DATA (human=9606, mouse=10090) ---
  string_data_path <- Sys.getenv("STRING_DATA_PATH", "/srv/string_data")
  local_species <- c(9606, 10090)

  if (species_id %in% local_species) {
    local_result <- tryCatch({
      query_string_local(genes, species_id, confidence, string_data_path, network_type)
    }, error = function(e) {
      print(paste("Local STRING query failed:", e$message, "- falling back to API"))
      NULL
    })

    if (!is.null(local_result) && nrow(local_result) > 0) {
      return(local_result)
    } else if (!is.null(local_result) && nrow(local_result) == 0) {
      print("No interactions found in local STRING data")
      return(data.frame(gene_from = character(), gene_to = character(), combined_score = numeric()))
    }
    # If NULL (error), fall through to API
  }

  # --- API FALLBACK (for non-human/mouse species or when local data unavailable) ---
  print(paste("Using STRING API for species:", species_id))
  return(query_string_api(genes, species_id, confidence, max_interactions, network_type))
}

# Local STRING data query for human and mouse
query_string_local <- function(genes, species_id, confidence = 0.4, data_path = "/srv/string_data", network_type = "full") {

  print(paste("Querying local STRING data for species", species_id, "..."))

  links_suffix <- if (identical(network_type, "physical")) ".protein.physical.links.v12.0.txt.gz" else ".protein.links.v12.0.txt.gz"
  links_file <- file.path(data_path, paste0(species_id, links_suffix))
  if (!file.exists(links_file) && identical(network_type, "physical")) {
    links_file <- file.path(data_path, paste0(species_id, ".protein.links.v12.0.txt.gz"))
  }
  aliases_file <- file.path(data_path, paste0(species_id, ".protein.aliases.v12.0.txt.gz"))

  if (!file.exists(links_file) || !file.exists(aliases_file)) {
    print(paste("Local STRING files not found for species", species_id))
    return(NULL)  # NULL signals fallback to API
  }

  # Use cached RDS for faster loading on subsequent calls (store in /tmp since data dir may be read-only)
  cache_dir <- file.path(tempdir(), "string_cache")
  if (!dir.exists(cache_dir)) dir.create(cache_dir, recursive = TRUE)
  aliases_rds <- file.path(cache_dir, paste0(species_id, "_aliases_symbols.rds"))
  links_rds <- file.path(cache_dir, paste0(species_id, "_", network_type, "_links.rds"))

  # --- STEP 1: BUILD GENE SYMBOL → STRING ID MAPPING ---
  if (file.exists(aliases_rds)) {
    print("Loading cached gene-symbol mapping...")
    alias_map <- readRDS(aliases_rds)
  } else {
    print("Building gene-symbol mapping from STRING aliases (first-time, will be cached)...")
    # Read aliases and filter to gene symbol sources only
    all_aliases <- data.table::fread(
      cmd = paste("zcat", aliases_file),
      sep = "\t", header = TRUE, stringsAsFactors = FALSE,
      col.names = c("string_id", "alias", "source")
    )
    # Keep only gene symbol sources for mapping
    symbol_sources <- c("Ensembl_HGNC_symbol", "Ensembl_EntrezGene",
                        "Ensembl_HGNC", "BLAST_KEGG_NAME",
                        "Ensembl_MGI_symbol", "Ensembl_MGI")
    alias_map <- all_aliases[all_aliases$source %in% symbol_sources, c("string_id", "alias")]
    alias_map <- unique(alias_map)
    tryCatch(saveRDS(alias_map, aliases_rds), error = function(e) NULL)
    rm(all_aliases)
    print(paste("Cached", nrow(alias_map), "gene symbol mappings"))
  }

  # Map input genes to STRING IDs
  genes_upper <- toupper(genes)
  alias_map$alias_upper <- toupper(alias_map$alias)
  matched <- alias_map[alias_map$alias_upper %in% genes_upper, ]

  if (nrow(matched) == 0) {
    print("No genes could be mapped to STRING IDs")
    return(data.frame(gene_from = character(), gene_to = character(), combined_score = numeric()))
  }

  # Create bidirectional mapping
  string_ids <- unique(matched$string_id)
  # gene symbol → string ID (use first match)
  gene_to_sid <- setNames(matched$string_id, matched$alias_upper)
  # string ID → gene symbol (use first match)
  sid_to_gene <- setNames(matched$alias, matched$string_id)

  print(paste("Mapped", length(string_ids), "of", length(genes), "genes to STRING IDs"))

  # --- STEP 2: LOAD AND FILTER INTERACTIONS ---
  confidence_threshold <- as.integer(confidence * 1000)

  if (file.exists(links_rds)) {
    print("Loading cached interaction data...")
    all_links <- readRDS(links_rds)
  } else {
    print("Loading STRING interaction data (first-time, will be cached)...")
    all_links <- data.table::fread(
      cmd = paste("zcat", links_file),
      header = TRUE, stringsAsFactors = FALSE
    )
    tryCatch(saveRDS(all_links, links_rds), error = function(e) NULL)
    print(paste("Cached", nrow(all_links), "interactions"))
  }

  # Filter to interactions involving our proteins at required confidence
  relevant <- all_links[
    all_links$protein1 %in% string_ids & all_links$protein2 %in% string_ids &
    all_links$combined_score >= confidence_threshold,
  ]

  if (nrow(relevant) == 0) {
    print("No interactions found above confidence threshold")
    return(data.frame(gene_from = character(), gene_to = character(), combined_score = numeric()))
  }

  # --- STEP 3: MAP BACK TO GENE SYMBOLS ---
  map_sid_to_gene <- function(sids) {
    mapped <- sid_to_gene[sids]
    na_idx <- is.na(mapped)
    if (any(na_idx)) {
      mapped[na_idx] <- gsub("^[0-9]+\\.", "", sids[na_idx])
    }
    return(as.character(mapped))
  }

  result_df <- data.frame(
    gene_from = map_sid_to_gene(relevant$protein1),
    gene_to = map_sid_to_gene(relevant$protein2),
    combined_score = relevant$combined_score / 1000,
    stringsAsFactors = FALSE
  )

  # Remove self-interactions and duplicates
  result_df <- result_df[result_df$gene_from != result_df$gene_to, ]
  result_df <- unique(result_df)

  print(paste("Local STRING: Retrieved", nrow(result_df), "interactions"))
  return(result_df)
}

# STRING API query (original logic, used as fallback for non-human/mouse species)
query_string_api <- function(genes, species_id, confidence = 0.4, max_interactions = 1000, network_type = "full") {
  string_net_type <- if (identical(network_type, "physical")) "physical" else "functional"

  print(paste("Querying STRING API for species", species_id, "..."))

  if (!requireNamespace("httr", quietly = TRUE)) {
    return(create_mock_ppi_data_safe(genes))
  }

  tryCatch({
    # --- STEP 1: BATCHED MAPPING ---
    chunk_size <- 1000
    gene_chunks <- split(genes, ceiling(seq_along(genes)/chunk_size))
    all_mapped_data <- data.frame()

    print(paste("Mapping", length(genes), "genes via STRING API..."))

    for(i in seq_along(gene_chunks)) {
      chunk <- gene_chunks[[i]]
      genes_for_api <- paste(chunk, collapse = "\n")

      map_response <- httr::POST(
        url = "https://string-db.org/api/tsv/get_string_ids",
        body = list(
          identifiers = genes_for_api,
          species = species_id,
          limit = 1,
          caller_identity = "TransXplorer"
        ),
        encode = "form",
        httr::timeout(60)
      )

      if (httr::status_code(map_response) == 200) {
        content <- httr::content(map_response, "text", encoding = "UTF-8")
        chunk_mapped <- tryCatch({
          read.table(text = content, sep = "\t", header = TRUE, stringsAsFactors = FALSE, quote = "", fill = TRUE)
        }, error = function(e) NULL)

        if(!is.null(chunk_mapped) && nrow(chunk_mapped) > 0) {
          all_mapped_data <- rbind(all_mapped_data, chunk_mapped)
        }
      }
    }

    if (nrow(all_mapped_data) == 0) {
      print("No genes mapped to STRING IDs via API")
      return(create_mock_ppi_data_safe(genes))
    }

    # --- STEP 2: GET NETWORK ---
    string_id_col <- if ("stringId" %in% colnames(all_mapped_data)) "stringId" else colnames(all_mapped_data)[grep("string", colnames(all_mapped_data), ignore.case = TRUE)[1]]
    string_ids <- unique(all_mapped_data[[string_id_col]])

    print(paste("Retrieving interactions for", length(string_ids), "proteins via API..."))

    all_interactions <- data.frame()

    if (length(string_ids) > 2000) {
      network_chunk_size <- 500
      string_chunks <- split(string_ids, ceiling(seq_along(string_ids)/network_chunk_size))

      for (chunk_idx in seq_along(string_chunks)) {
        chunk_ids <- string_chunks[[chunk_idx]]
        chunk_ids_for_api <- paste(chunk_ids, collapse = "\n")

        net_response <- httr::POST(
          url = "https://string-db.org/api/tsv/network",
          body = list(
            identifiers = chunk_ids_for_api,
            species = species_id,
            required_score = as.integer(confidence * 1000),
            network_type = string_net_type,
            limit = 0,
            caller_identity = "TransXplorer"
          ),
          encode = "form",
          httr::timeout(120)
        )

        if (httr::status_code(net_response) == 200) {
          net_content <- httr::content(net_response, "text", encoding = "UTF-8")
          chunk_interactions <- tryCatch({
            read.table(text = net_content, sep = "\t", header = TRUE,
                       stringsAsFactors = FALSE, quote = "", fill = TRUE)
          }, error = function(e) NULL)

          if (!is.null(chunk_interactions) && nrow(chunk_interactions) > 0) {
            all_interactions <- rbind(all_interactions, chunk_interactions)
          }
        }
        Sys.sleep(0.5)
      }
      interactions <- all_interactions
    } else {
      string_ids_for_api <- paste(string_ids, collapse = "\n")

      net_response <- httr::POST(
        url = "https://string-db.org/api/tsv/network",
        body = list(
          identifiers = string_ids_for_api,
          species = species_id,
          required_score = as.integer(confidence * 1000),
          network_type = string_net_type,
          limit = 0,
          caller_identity = "TransXplorer"
        ),
        encode = "form",
        httr::timeout(120)
      )

      if (httr::status_code(net_response) != 200) {
        print(paste("[FAIL] STRING network API returned status:", httr::status_code(net_response)))
        return(create_mock_ppi_data_safe(genes))
      }

      net_content <- httr::content(net_response, "text", encoding = "UTF-8")
      interactions <- tryCatch({
        read.table(text = net_content, sep = "\t", header = TRUE,
                   stringsAsFactors = FALSE, quote = "", fill = TRUE)
      }, error = function(e) NULL)
    }

    if (is.null(interactions) || nrow(interactions) == 0) {
      print("No interactions found via STRING API")
      return(data.frame(gene_from = character(), gene_to = character(), combined_score = numeric()))
    }

    interactions <- unique(interactions)

    # --- STEP 3: FORMAT RESULTS ---
    p1_col <- colnames(interactions)[1]
    p2_col <- colnames(interactions)[2]
    score_col <- colnames(interactions)[grep("score", colnames(interactions))][1]

    preferred_col <- if ("preferredName" %in% colnames(all_mapped_data)) "preferredName" else "queryItem"
    id_map <- setNames(all_mapped_data[[preferred_col]], all_mapped_data[[string_id_col]])

    clean_and_map <- function(ids) {
      mapped <- id_map[ids]
      na_indices <- is.na(mapped)
      if (any(na_indices)) {
        mapped[na_indices] <- gsub("^[0-9]+\\.", "", ids[na_indices])
      }
      return(mapped)
    }

    result_df <- data.frame(
      gene_from = clean_and_map(interactions[[p1_col]]),
      gene_to = clean_and_map(interactions[[p2_col]]),
      combined_score = as.numeric(interactions[[score_col]]) / 1000,
      stringsAsFactors = FALSE
    )

    print(paste("STRING API: Retrieved", nrow(result_df), "interactions"))
    return(result_df)

  }, error = function(e) {
    print(paste("STRING API Critical Error:", e$message))
    return(create_mock_ppi_data_safe(genes))
  })
}

print_enst_conversion_summary <- function(enst_ids, converted_ids) {
  if (length(enst_ids) > 0) {
    print("=== ENST ID Conversion Summary ===")
    for (i in seq_along(enst_ids)) {
      if (i <= 5) {  # Show first 5 conversions
        if (!is.na(converted_ids[i]) && converted_ids[i] != "") {
          print(paste("  •", enst_ids[i], "→", converted_ids[i]))
        } else {
          print(paste("  •", enst_ids[i], "→ [not converted]"))
        }
      }
    }
    if (length(enst_ids) > 5) {
      print(paste("  ... and", length(enst_ids) - 5, "more"))
    }
    print("==================================")
  }
}

# Convert gene IDs to STRING-compatible format based on organism
convert_to_string_ids <- function(genes, organism) {
  
  print(paste("🔄 Converting", length(genes), "genes for organism:", organism))
  
  # For yeast, try to convert to systematic names (ORF)
  if (organism == "yeast" || organism == "4932") {
    
    tryCatch({
      print(" • Using enhanced cleaning for yeast IDs...")
      
      # CRITICAL: Ensure genes is a vector, not a single concatenated string
      if (length(genes) == 1 && grepl("[\\n\\r,]", genes[1])) {
        genes <- unlist(strsplit(genes, "[,\\n\\r\\t\\s]+"))
        genes <- trimws(genes)
        genes <- genes[genes != "" & !is.na(genes)]
        genes <- unique(genes)
        print(paste(" • Had to split concatenated input. Now have", length(genes), "genes"))
      }
      
      # Step 1: Handle multi-part IDs by taking the first valid part
      # This will split "YDR119W, R(ACG)D" and take "YDR119W"
      genes_cleaned <- sapply(genes, function(g) {
        # Split by comma or space and take the first part
        parts <- strsplit(g, "[,\\s]+")[[1]]
        return(parts[1])
      }, USE.NAMES = FALSE)
      
      # Step 2: Remove any remaining non-standard characters from the selected part
      genes_cleaned <- gsub("[^a-zA-Z0-9-]", "", genes_cleaned)
      
      # Step 3: Remove empty strings that may result from cleaning
      genes_cleaned <- genes_cleaned[genes_cleaned != "" & !is.na(genes_cleaned)]
      
      # Step 4: Ensure all are uppercase for consistency
      genes_cleaned <- toupper(genes_cleaned)
      
      print(paste(" • Cleaned gene list:", length(unique(genes_cleaned)), "unique genes"))
      print(paste(" • First 5 cleaned genes:", paste(head(unique(genes_cleaned), 5), collapse = ", ")))
      
      # Load yeast annotation
      if (requireNamespace("org.Sc.sgd.db", quietly = TRUE)) {
        
        print(" • Using org.Sc.sgd.db for yeast conversion...")
        
        # CRITICAL FIX: Handle input that might have embedded newlines
        # Convert to character first
        genes <- as.character(genes)
        
        # Split ALL elements by newlines, whitespace, commas
        genes_split <- unlist(strsplit(genes, "[\\n\\r\\t\\s,]+"))
        
        # Clean each gene: remove whitespace and empty strings
        genes_clean <- trimws(genes_split)
        genes_clean <- genes_clean[genes_clean != "" & !is.na(genes_clean)]
        genes_clean <- unique(genes_clean)
        genes_clean <- toupper(genes_clean)  # Ensure uppercase for matching
        
        print(paste(" • Cleaned gene list:", length(genes_clean), "genes"))
        print(paste(" • First 5 genes:", paste(head(genes_clean, 5), collapse = ", ")))
        
        # Check if genes are already systematic names (ORF format: YXL###C or YXL###W)
        is_systematic <- grepl("^Y[A-P][LR][0-9]{3}[WC](-[A-Z])?$", genes_clean, ignore.case = TRUE)
        
        n_systematic <- sum(is_systematic)
        print(paste(" •", n_systematic, "out of", length(genes_clean), "genes are systematic names (ORF)"))
        
        if (n_systematic > length(genes_clean) * 0.5) {
          # Most genes are already systematic names
          print(paste(" • Using genes as-is (already in systematic format)"))
          return(genes_clean)
        }
        
        # If not systematic names, try to convert
        print(" • Attempting conversion to systematic names...")
        converted <- rep(NA_character_, length(genes_clean))
        
        # Get valid keys
        valid_orf <- tryCatch({
          keys(org.Sc.sgd.db::org.Sc.sgd.db, keytype = "ORF")
        }, error = function(e) character(0))
        
        valid_common <- tryCatch({
          keys(org.Sc.sgd.db::org.Sc.sgd.db, keytype = "COMMON")
        }, error = function(e) character(0))
        
        valid_genename <- tryCatch({
          keys(org.Sc.sgd.db::org.Sc.sgd.db, keytype = "GENENAME")
        }, error = function(e) character(0))
        
        print(paste(" • Database keys - ORF:", length(valid_orf), "COMMON:", length(valid_common),
                    "GENENAME:", length(valid_genename)))
        
        # Strategy 1: Check if genes are already ORFs
        genes_in_orf <- genes_clean %in% valid_orf
        if (sum(genes_in_orf) > 0) {
          converted[genes_in_orf] <- genes_clean[genes_in_orf]
          print(paste(" • Matched", sum(genes_in_orf), "genes directly as ORF"))
        }
        
        # Strategy 2: Try as COMMON names (for unmapped genes)
        unmapped_idx <- which(is.na(converted))
        if (length(unmapped_idx) > 0 && length(valid_common) > 0) {
          genes_to_map <- genes_clean[unmapped_idx]
          genes_in_common <- genes_to_map %in% valid_common
          
          if (sum(genes_in_common) > 0) {
            genes_for_mapping <- genes_to_map[genes_in_common]
            
            tryCatch({
              mapping <- AnnotationDbi::select(
                org.Sc.sgd.db::org.Sc.sgd.db,
                keys = genes_for_mapping,
                columns = c("ORF"),
                keytype = "COMMON"
              )
              
              if (!is.null(mapping) && nrow(mapping) > 0) {
                for (i in which(genes_in_common)) {
                  idx <- unmapped_idx[i]
                  matches <- mapping$ORF[mapping$COMMON == genes_clean[idx]]
                  if (length(matches) > 0 && !is.na(matches[1])) {
                    converted[idx] <- matches[1]
                  }
                }
                n_newly_mapped <- sum(!is.na(converted[unmapped_idx]))
                print(paste(" • Mapped", n_newly_mapped, "additional genes using COMMON names"))
              }
            }, error = function(e) {
              print(paste(" • COMMON name mapping error:", e$message))
            })
          }
        }
        
        # Strategy 3: Try as GENENAME (for still unmapped genes)
        unmapped_idx <- which(is.na(converted))
        if (length(unmapped_idx) > 0 && length(valid_genename) > 0) {
          genes_to_map <- genes_clean[unmapped_idx]
          genes_in_genename <- genes_to_map %in% valid_genename
          
          if (sum(genes_in_genename) > 0) {
            genes_for_mapping <- genes_to_map[genes_in_genename]
            
            tryCatch({
              mapping <- AnnotationDbi::select(
                org.Sc.sgd.db::org.Sc.sgd.db,
                keys = genes_for_mapping,
                columns = c("ORF"),
                keytype = "GENENAME"
              )
              
              if (!is.null(mapping) && nrow(mapping) > 0) {
                for (i in which(genes_in_genename)) {
                  idx <- unmapped_idx[i]
                  matches <- mapping$ORF[mapping$GENENAME == genes_clean[idx]]
                  if (length(matches) > 0 && !is.na(matches[1])) {
                    converted[idx] <- matches[1]
                  }
                }
                n_newly_mapped <- sum(!is.na(converted[unmapped_idx]))
                print(paste(" • Mapped", n_newly_mapped, "additional genes using GENENAME"))
              }
            }, error = function(e) {
              print(paste(" • GENENAME mapping error:", e$message))
            })
          }
        }
        
        # For any remaining unmapped, keep original
        still_unmapped <- is.na(converted)
        if (sum(still_unmapped) > 0) {
          converted[still_unmapped] <- genes_clean[still_unmapped]
          print(paste(" •", sum(still_unmapped), "genes kept as-is (may still work with STRING)"))
        }
        
        # Summary
        n_total_mapped <- sum(!is.na(converted))
        print(paste(" • Final: Using", n_total_mapped, "genes for STRING query"))
        
        # Return only non-NA values
        return(unique(genes_cleaned))
        
      } else {
        print(" • org.Sc.sgd.db not available, using cleaned genes as-is")
        return(unique(genes_cleaned))
      }
      
    }, error = function(e) {
      print(paste(" • Yeast conversion error:", e$message))
      return(genes) # Fallback to original genes on error
    })
    
  }
  
  # For other organisms, return as-is (can add more conversions as needed)
  print(" • No conversion needed for this organism")
  return(genes)
}


# Helper function to convert STRING IDs back to gene symbols
convert_string_ids_to_genes <- function(interactions, mapped_genes) {
  
  # Create ID mapping lookup
  # Handle both formats: with and without original_gene column
  if ("original_gene" %in% colnames(mapped_genes)) {
    id_to_gene <- setNames(mapped_genes$original_gene, mapped_genes$STRING_id)
  } else {
    id_to_gene <- setNames(mapped_genes$gene, mapped_genes$STRING_id)
  }
  
  # Convert interactions
  interactions_clean <- data.frame(
    gene_from = id_to_gene[interactions$from],
    gene_to = id_to_gene[interactions$to],
    combined_score = interactions$combined_score / 1000,  # Convert back to 0-1 scale
    stringsAsFactors = FALSE
  )
  
  # Remove NA and self-interactions
  interactions_clean <- interactions_clean %>%
    filter(!is.na(gene_from) & !is.na(gene_to) & gene_from != gene_to) %>%
    distinct()
  
  # If we got nothing, try without dividing score (might already be normalized)
  if (nrow(interactions_clean) == 0 && nrow(interactions) > 0) {
    print("  • Retrying without score normalization...")
    interactions_clean <- data.frame(
      gene_from = id_to_gene[interactions$from],
      gene_to = id_to_gene[interactions$to],
      combined_score = interactions$combined_score,
      stringsAsFactors = FALSE
    ) %>%
      filter(!is.na(gene_from) & !is.na(gene_to) & gene_from != gene_to) %>%
      distinct()
  }
  
  return(interactions_clean)
}

# Safe mock data function for when STRING is unavailable
create_mock_ppi_data_safe <- function(genes) {
  stop("Protein-protein interaction data (STRING) could not be retrieved, so no network was built. Please try again later. TransXplorer never substitutes simulated data.")
}


query_string_safe <- function(genes, organism = "human", confidence = 0.4) {
  
  print("🔍 Querying STRING database...")
  
  species_id <- switch(organism,
                       "human" = 9606,
                       "mouse" = 10090,
                       "rat" = 10116,
                       "zebrafish" = 7955,
                       "fly" = 7227,
                       "worm" = 6239,
                       "yeast" = 4932,
                       9606  # default to human
  )
  
  if (!requireNamespace("STRINGdb", quietly = TRUE)) {
    print("STRINGdb not available, using mock data")
    return(create_mock_ppi_data(genes))
  }
  
  tryCatch({
    # Initialize STRING
    string_db <- STRINGdb::STRINGdb$new(
      version = "11.5",
      species = species_id,
      score_threshold = confidence * 1000
    )
    
    # Map genes
    gene_df <- data.frame(gene = genes, stringsAsFactors = FALSE)
    mapped <- string_db$map(gene_df, "gene", removeUnmappedRows = FALSE)
    
    # Count successful mappings
    n_mapped <- sum(!is.na(mapped$STRING_id))
    mapping_rate <- n_mapped / length(genes)
    print(paste("✅ Mapped", round(mapping_rate * 100, 1), "% of genes"))
    
    # Get only mapped genes
    mapped_clean <- mapped[!is.na(mapped$STRING_id), ]
    
    if (nrow(mapped_clean) == 0) {
      print("No genes could be mapped to STRING")
      return(create_mock_ppi_data(genes))
    }
    
    # Get interactions - FIXED STRING function call
    interactions <- string_db$get_interactions(mapped_clean$STRING_id)
    
    if (is.null(interactions) || nrow(interactions) == 0) {
      print("No interactions found")
      return(list(interactions = data.frame(), mapping = mapped_clean))
    }
    
    print(paste("Found", nrow(interactions), "interactions"))
    
    # Convert to gene symbols
    interactions_clean <- convert_string_ids(interactions, mapped_clean)
    
    return(list(
      interactions = interactions_clean,
      mapping = mapped_clean,
      mapping_rate = mapping_rate
    ))
    
  }, error = function(e) {
    print(paste("STRING error:", e$message))
    return(create_mock_ppi_data(genes))
  })
}


# 1. Fix for tooltip creation in network visualization
create_safe_tooltips <- function(nodes) {
  tryCatch({
    # SAFE VERSION - Replace paste0() with sprintf()
    nodes$title <- sprintf(
      "<b>%s</b><br>Type: %s<br>Degree: %d",
      as.character(nodes$label),
      as.character(nodes$group),
      as.numeric(nodes$degree)
    )
    return(nodes)
  }, error = function(e) {
    # Fallback - simple tooltips
    nodes$title <- as.character(nodes$label)
    return(nodes)
  })
}

# 2. Fix for edge tooltips
create_safe_edge_tooltips <- function(edges, confidence_scores) {
  tryCatch({
    # SAFE VERSION
    edges$title <- sprintf("Confidence: %.3f", as.numeric(confidence_scores))
    return(edges)
  }, error = function(e) {
    # Fallback
    edges$title <- "Protein Interaction"
    return(edges)
  })
}

# 3. Fix for hub protein labels
add_safe_hub_labels <- function(nodes, hub_proteins) {
  tryCatch({
    if (!is.null(hub_proteins) && nrow(hub_proteins) > 0 && "hub_type" %in% colnames(hub_proteins)) {
      # Only get ACTUAL hubs (not all proteins)
      actual_hubs <- hub_proteins[hub_proteins$hub_type %in% c("Hub", "Major Hub"), ]
      
      if (nrow(actual_hubs) > 0) {
        hub_genes <- actual_hubs$gene
        hub_mask <- nodes$id %in% hub_genes
        
        if (sum(hub_mask) > 0) {
          # Add star only to actual hubs
          hub_labels <- nodes$label[hub_mask]
          nodes$label[hub_mask] <- sprintf("★ %s", as.character(hub_labels))
        }
      }
    }
    return(nodes)
  }, error = function(e) {
    # If labeling fails, just return original nodes
    return(nodes)
  })
}

# 4. Main fix function to replace the problematic visualization code
fix_ppi_visualization <- function(ppi_interactions, selected_genes, hub_proteins) {
  
  print("🎨 Creating SAFE PPI visualization...")
  
  # Get all proteins
  all_proteins <- unique(c(ppi_interactions$gene_from, ppi_interactions$gene_to))
  
  if (length(all_proteins) == 0) {
    return(list(
      nodes = data.frame(
        id = "no_data",
        label = "No data",
        color = "#95A5A6",
        size = 30,
        title = "No interactions found",
        stringsAsFactors = FALSE
      ),
      edges = data.frame()
    ))
  }
  
  # Create nodes with SAFE methods
  nodes <- data.frame(
    id = all_proteins,
    label = all_proteins,
    group = "Network",
    degree = 1,
    stringsAsFactors = FALSE
  )
  
  # Assign groups SAFELY
  if (!is.null(selected_genes$up_genes) && length(selected_genes$up_genes) > 0) {
    up_mask <- nodes$id %in% selected_genes$up_genes
    nodes$group[up_mask] <- "Up-regulated"
  }
  
  if (!is.null(selected_genes$down_genes) && length(selected_genes$down_genes) > 0) {
    down_mask <- nodes$id %in% selected_genes$down_genes
    nodes$group[down_mask] <- "Down-regulated"
  }
  
  # Calculate degree SAFELY
  degree_table <- table(c(ppi_interactions$gene_from, ppi_interactions$gene_to))
  for (i in 1:nrow(nodes)) {
    protein_id <- nodes$id[i]
    if (protein_id %in% names(degree_table)) {
      nodes$degree[i] <- as.numeric(degree_table[protein_id])
    }
  }
  
  # Set visual properties SAFELY
  nodes$size <- 15 + sqrt(nodes$degree) * 3
  
  # Color assignment SAFELY
  nodes$color <- "#95A5A6"  # Default gray (network neighbors)
  
  # Mark input genes distinctly
  if (!is.null(selected_genes$all_genes)) {
    input_mask <- nodes$id %in% selected_genes$all_genes
    nodes$color[input_mask] <- "#2ECC71"  # Green for input genes
    nodes$group[input_mask] <- "Input Gene"
  }
  
  # Override with up/down if available
  nodes$color[nodes$group == "Up-regulated"] <- "#E74C3C"    # Red
  nodes$color[nodes$group == "Down-regulated"] <- "#3498DB"  # Blue
  
  # Add hub enhancements SAFELY
  nodes <- add_safe_hub_labels(nodes, hub_proteins)
  
  # Create tooltips SAFELY
  nodes <- create_safe_tooltips(nodes)
  
  # Create edges SAFELY
  edges <- data.frame(
    from = as.character(ppi_interactions$gene_from),
    to = as.character(ppi_interactions$gene_to),
    width = 2,
    color = "#95A5A6",
    stringsAsFactors = FALSE
  )
  
  # Add edge properties SAFELY
  if ("combined_score" %in% colnames(ppi_interactions)) {
    confidence_scores <- ppi_interactions$combined_score
    confidence_scores[is.na(confidence_scores)] <- 0.4
    
    edges$width <- pmax(1, confidence_scores * 4)
    edges$color <- ifelse(confidence_scores > 0.7, "#27AE60", "#95A5A6")
    
    # Add edge tooltips SAFELY
    edges <- create_safe_edge_tooltips(edges, confidence_scores)
  } else {
    edges$title <- "Protein Interaction"
  }
  
  print(sprintf("✅ Safe visualization: %d nodes, %d edges", nrow(nodes), nrow(edges)))
  
  return(list(
    nodes = nodes,
    edges = edges
  ))
}

# Build comprehensive network
build_comprehensive_network <- function(ppi_data, all_degs) {
  
  if (is.null(ppi_data) || is.null(ppi_data$interactions)) {
    return(list(
      graph = NULL,
      all_proteins = character(0),
      metrics = list(
        global_metrics = list(
          n_nodes = 0,
          n_edges = 0,
          density = 0,
          avg_degree = 0
        ),
        node_metrics = data.frame()
      ),
      hubs = data.frame()
    ))
  }
  
  interactions <- ppi_data$interactions
  
  if (nrow(interactions) == 0) {
    return(list(
      graph = NULL,
      all_proteins = character(0),
      metrics = list(
        global_metrics = list(
          n_nodes = 0,
          n_edges = 0,
          density = 0,
          avg_degree = 0
        ),
        node_metrics = data.frame()
      ),
      hubs = data.frame()
    ))
  }
  
  # Check if igraph is available
  if (!requireNamespace("igraph", quietly = TRUE)) {
    print("igraph package not available, using simplified network analysis")
    
    # Simplified analysis without igraph
    all_proteins <- unique(c(interactions$gene_from, interactions$gene_to))
    
    # Calculate degree manually
    degree_counts <- table(c(interactions$gene_from, interactions$gene_to))
    
    metrics <- list(
      global_metrics = list(
        n_nodes = length(all_proteins),
        n_edges = nrow(interactions),
        density = if (length(all_proteins) > 1) {
          2 * nrow(interactions) / (length(all_proteins) * (length(all_proteins) - 1))
        } else 0,
        avg_degree = if (length(all_proteins) > 0) {
          2 * nrow(interactions) / length(all_proteins)
        } else 0
      ),
      node_metrics = data.frame(
        protein = names(degree_counts),
        degree = as.numeric(degree_counts),
        stringsAsFactors = FALSE
      )
    )
    
    # Identify hubs (top 10% by degree)
    hubs <- metrics$node_metrics[order(metrics$node_metrics$degree, decreasing = TRUE), ]
    hubs <- head(hubs, max(10, round(length(all_proteins) * 0.1)))
    
    # Add regulation status
    hubs$regulation <- ifelse(
      hubs$protein %in% all_degs$up_genes, "Up",
      ifelse(hubs$protein %in% all_degs$down_genes, "Down", "None")
    )
    
    return(list(
      graph = NULL,  # No igraph object
      all_proteins = all_proteins,
      metrics = metrics,
      hubs = hubs
    ))
  }
  
  # Full analysis with igraph
  library(igraph)
  
  g <- graph_from_data_frame(
    d = interactions[, c("gene_from", "gene_to")],
    directed = FALSE,
    vertices = data.frame(
      name = unique(c(interactions$gene_from, interactions$gene_to))
    )
  )
  
  # Add edge weights
  E(g)$weight <- interactions$combined_score
  
  # Calculate comprehensive metrics
  all_proteins <- V(g)$name
  
  metrics <- list(
    global_metrics = list(
      n_nodes = vcount(g),
      n_edges = ecount(g),
      density = edge_density(g),
      clustering_coefficient = transitivity(g, type = "global"),
      avg_degree = mean(degree(g)),
      diameter = if(is_connected(g)) diameter(g) else NA,
      avg_path_length = if(is_connected(g)) mean_distance(g) else NA
    ),
    node_metrics = data.frame(
      protein = V(g)$name,
      degree = degree(g),
      betweenness = betweenness(g),
      closeness = closeness(g),
      eigenvector = eigen_centrality(g)$vector,
      stringsAsFactors = FALSE
    )
  )
  
  # Identify hubs (top 10% by degree + betweenness)
  hub_score <- scale(metrics$node_metrics$degree)[,1] +
    scale(metrics$node_metrics$betweenness)[,1]
  
  hubs <- metrics$node_metrics[order(hub_score, decreasing = TRUE), ]
  hubs <- head(hubs, max(10, round(vcount(g) * 0.1)))
  hubs$hub_score <- hub_score[order(hub_score, decreasing = TRUE)][1:nrow(hubs)]
  
  # Add DEG status
  hubs$regulation <- ifelse(
    hubs$protein %in% all_degs$up_genes, "Up",
    ifelse(hubs$protein %in% all_degs$down_genes, "Down", "None")
  )
  
  return(list(
    graph = g,
    all_proteins = V(g)$name,
    metrics = list(
      global_metrics = list(
        n_nodes = vcount(g),
        n_edges = ecount(g),
        density = edge_density(g),
        avg_degree = mean(degree(g))
      ),
      node_metrics = data.frame(
        protein = V(g)$name,
        degree = degree(g),
        stringsAsFactors = FALSE
      )
    ),
    hubs = data.frame()  # Simplified for now
  ))
}

# Perform functional enrichment (STRING-style)
perform_functional_enrichment_safe <- function(all_proteins, selected_genes, organism = "human") {
  
  print(paste("🧬 Running functional enrichment analysis for:", organism))
  
  tryCatch({
    if (length(all_proteins) < 3) {
      print("  • Too few proteins for enrichment")
      return(list())
    }
    
    # Check if enrichR is available
    if (!require("enrichR", quietly = TRUE)) {
      print("  • enrichR package not available")
      return(list())
    }
    
    # ═══════════════════════════════════════════════════════════════
    # STEP 1: Convert gene IDs to symbols (CRITICAL FOR NON-HUMAN!)
    # ═══════════════════════════════════════════════════════════════
    genes_for_enrichment <- all_proteins
    
    # For yeast: check if these are systematic names (YXXnnnX pattern)
    n_systematic_yeast <- sum(grepl("^Y[A-Z]{2}[0-9]{3}[WC](-[A-Z])?$", all_proteins, ignore.case = TRUE))
    is_yeast_systematic <- (tolower(organism) == "yeast" && n_systematic_yeast >= 3)
    
    if (is_yeast_systematic) {
      print(paste("  • Detected yeast systematic names:", n_systematic_yeast, "of", length(all_proteins)))
      print("  • Converting systematic names to standard gene names for enrichR...")
      
      converted <- tryCatch({
        if (requireNamespace("org.Sc.sgd.db", quietly = TRUE)) {
          library(org.Sc.sgd.db)
          library(AnnotationDbi)
          
          # Separate systematic names from non-systematic names
          is_systematic <- grepl("^Y[A-Z]{2}[0-9]{3}[WC](-[A-Z])?$", all_proteins, ignore.case = TRUE)
          systematic_names <- all_proteins[is_systematic]
          non_systematic_names <- all_proteins[!is_systematic]
          
          # Only convert the systematic names (ORFs)
          converted_orfs <- character(0)
          if (length(systematic_names) > 0) {
            symbols <- AnnotationDbi::mapIds(
              org.Sc.sgd.db,
              keys = systematic_names,
              column = "GENENAME",
              keytype = "ORF",
              multiVals = "first"
            )
            converted_orfs <- as.character(symbols[!is.na(symbols) & symbols != ""])
          }
          
          # Keep non-systematic names as-is (they're likely already gene symbols)
          # Combine converted ORFs with existing gene symbols
          all_valid <- unique(c(converted_orfs, non_systematic_names))
          all_valid <- all_valid[!is.na(all_valid) & all_valid != ""]
          
          print(paste("  • Converted", length(converted_orfs), "ORFs to gene names"))
          print(paste("  • Kept", length(non_systematic_names), "existing gene symbols"))
          
          if (length(all_valid) >= 3) {
            all_valid
          } else {
            print("  • Few valid genes, using original input...")
            all_proteins
          }
        } else {
          print("  • org.Sc.sgd.db not available, using original IDs")
          all_proteins
        }
      }, error = function(e) {
        print(paste("  • Yeast conversion error:", e$message))
        all_proteins
      })
      
      genes_for_enrichment <- unique(converted[!is.na(converted) & converted != ""])
      
    } else {
      # For all organisms including human, check if conversion is needed
      id_detection <- detect_gene_id_type(all_proteins)
      print(paste("  • Input ID type:", id_detection$id_type))
      
      if (id_detection$id_type %in% c("ensembl_gene", "ensembl_transcript", "ensembl_protein", "entrez")) {
        print("  • Converting IDs to gene symbols...")
        
        conversion_result <- tryCatch({
          convert_gene_ids_universal(all_proteins, from_type = id_detection$id_type, 
                                     to_type = "symbol", organism = organism)
        }, error = function(e) {
          print(paste("  • Conversion error:", e$message))
          list(converted_ids = all_proteins)
        })
        
        converted_genes <- conversion_result$converted_ids
        # Filter out failed conversions
        valid_converted <- converted_genes[
          !is.na(converted_genes) & 
            converted_genes != "" &
            !grepl("^ENS", converted_genes) &  # Remove unconverted ENSEMBL
            !grepl("^[0-9]+$", converted_genes)  # Remove unconverted Entrez
        ]
        
        if (length(valid_converted) >= 3) {
          genes_for_enrichment <- unique(valid_converted)
          print(paste("  • Successfully converted", length(genes_for_enrichment), "genes"))
        } else {
          print("  • Warning: Few genes converted, using original IDs")
        }
      }
    }
    
    print(paste("  • Genes for enrichment:", length(genes_for_enrichment)))
    
    if (length(genes_for_enrichment) < 3) {
      print("  • Too few genes for enrichment after conversion")
      return(list())
    }
    
    # ═══════════════════════════════════════════════════════════════
    # STEP 2: Select appropriate databases
    # ═══════════════════════════════════════════════════════════════
    databases <- switch(tolower(organism),
                        "human" = c("GO_Biological_Process_2023", "KEGG_2021_Human", "Reactome_2022"),
                        "mouse" = c("GO_Biological_Process_2023", "KEGG_2019_Mouse", "WikiPathways_2019_Mouse"),
                        "rat" = c("GO_Biological_Process_2023", "KEGG_2021_Rat"),
                        "zebrafish" = c("GO_Biological_Process_2023", "KEGG_2019_Zebrafish"),
                        "fly" = c("GO_Biological_Process_2023", "KEGG_2019_Fly"),
                        "worm" = c("GO_Biological_Process_2023", "KEGG_2019_C.elegans"),
                        "yeast" = c("GO_Biological_Process_2023", "GO_Molecular_Function_2023", "KEGG_2019_Yeast"),
                        c("GO_Biological_Process_2023", "GO_Molecular_Function_2023")
    )
    
    print(paste("  • Using databases:", paste(databases, collapse = ", ")))
    
    # ═══════════════════════════════════════════════════════════════
    # STEP 3: Perform enrichment
    # ═══════════════════════════════════════════════════════════════
    enrichment_results <- tryCatch({
      
      # Manually set enrichR options to fix connection issues
      options(enrichR.base.address = "https://maayanlab.cloud/Enrichr/")
      options(enrichR.sites.base.address = "https://maayanlab.cloud/")
      options(enrichR.sites = c("Enrichr", "FlyEnrichr", "WormEnrichr", "YeastEnrichr", "FishEnrichr", "OxEnrichr"))
      options(enrichR.live = TRUE)
      options(enrichR.quiet = FALSE)
      
      # Try setEnrichrSite (optional - may fail but we have fallback)
      tryCatch({
        enrichR::setEnrichrSite("Enrichr")
      }, error = function(e) {
        # Continue anyway since we set options manually
      })
      
      # Query databases one at a time for better error handling
      all_results <- list()
      successful_dbs <- 0
      
      for (db in databases) {
        db_result <- tryCatch({
          # Query single database
          single_result <- tx_enrichr_local(
            genes = genes_for_enrichment,
            databases = db
          )
          
          if (!is.null(single_result) && 
              !is.null(single_result[[db]]) && 
              is.data.frame(single_result[[db]])) {
            successful_dbs <- successful_dbs + 1
            single_result[[db]]
          } else {
            NULL
          }
        }, error = function(e) {
          print(paste("    • Error with", db, ":", e$message))
          NULL
        })
        
        if (!is.null(db_result)) {
          all_results[[db]] <- db_result
        }
        
        # Small delay to avoid rate limiting
        Sys.sleep(0.3)
      }
      
      print(paste("  • Successfully queried", successful_dbs, "of", length(databases), "databases"))
      
      if (length(all_results) > 0) {
        all_results
      } else {
        NULL
      }
      
    }, error = function(e) {
      print(paste("  • enrichR query error:", e$message))
      return(NULL)
    })
    
    if (is.null(enrichment_results) || length(enrichment_results) == 0) {
      print("  • No results returned from enrichR")
      return(list())
    }
    
    # ═══════════════════════════════════════════════════════════════
    # STEP 4: Process results safely (with extensive type checking)
    # ═══════════════════════════════════════════════════════════════
    processed_results <- list()
    
    # Debug: Check the structure of enrichment_results
    print(paste("  • DEBUG: enrichment_results class:", class(enrichment_results)[1]))
    print(paste("  • DEBUG: enrichment_results length:", length(enrichment_results)))
    
    if (!is.list(enrichment_results)) {
      print("  • ERROR: enrichment_results is not a list!")
      return(list())
    }
    
    for (db_name in names(enrichment_results)) {
      tryCatch({
        result <- enrichment_results[[db_name]]
        
        # Debug for first database
        if (db_name == names(enrichment_results)[1]) {
          print(paste("  • DEBUG: First result class:", class(result)[1]))
          if (is.data.frame(result)) {
            print(paste("  • DEBUG: First result dims:", nrow(result), "x", ncol(result)))
            print(paste("  • DEBUG: First result cols:", paste(colnames(result), collapse=", ")))
          }
        }
        
        # Multiple safety checks
        if (is.null(result)) next
        if (!is.data.frame(result)) next
        if (nrow(result) == 0) next
        if (!"Adjusted.P.value" %in% colnames(result)) next
        
        # Ensure Adjusted.P.value is numeric
        adj_pval <- as.numeric(result$Adjusted.P.value)
        
        # Debug: Show p-value distribution for first database
        if (db_name == names(enrichment_results)[1]) {
          print(paste("  • DEBUG: Min p-value:", min(adj_pval, na.rm = TRUE)))
          print(paste("  • DEBUG: Max p-value:", max(adj_pval, na.rm = TRUE)))
          print(paste("  • DEBUG: Terms with p < 0.1:", sum(adj_pval < 0.1, na.rm = TRUE)))
          print(paste("  • DEBUG: Terms with p < 0.05:", sum(adj_pval < 0.05, na.rm = TRUE)))
        }
        
        # Find significant results
        significant_idx <- which(!is.na(adj_pval) & adj_pval < 0.1)
        
        if (length(significant_idx) > 0) {
          significant <- result[significant_idx, , drop = FALSE]
          
          # Sort by p-value (recreate numeric version for sorting)
          significant$Adjusted.P.value <- as.numeric(significant$Adjusted.P.value)
          significant <- significant[order(significant$Adjusted.P.value), , drop = FALSE]
          
          # Take top 20
          if (nrow(significant) > 20) {
            significant <- significant[1:20, , drop = FALSE]
          }
          
          processed_results[[db_name]] <- significant
          print(paste("   [OK]", db_name, ":", nrow(significant), "significant terms"))
        }
        
      }, error = function(e) {
        print(paste("    • Error processing", db_name, ":", e$message))
      })
    }
    
    total_significant <- if (length(processed_results) > 0) {
      sum(vapply(processed_results, function(x) {
        if (is.data.frame(x)) nrow(x) else 0L
      }, FUN.VALUE = integer(1)))
    } else {
      0L
    }
    
    print(paste("✅ Enrichment analysis complete -", length(processed_results), 
                "databases with", total_significant, "significant results"))
    
    return(processed_results)
    
  }, error = function(e) {
    print(paste("  • Enrichment analysis error:", e$message))
    return(list())
  })
}

# Identify network modules/clusters
identify_network_modules <- function(graph) {
  
  if (is.null(graph) || vcount(graph) < 5) {
    return(list())
  }
  
  library(igraph)
  
  # Try different clustering algorithms
  modules <- list()
  
  tryCatch({
    # Fast greedy clustering
    modules$fast_greedy <- cluster_fast_greedy(graph)
    
    # Louvain clustering
    modules$louvain <- cluster_louvain(graph)
    
    # Edge betweenness (for smaller networks)
    if (vcount(graph) < 100) {
      modules$edge_betweenness <- cluster_edge_betweenness(graph)
    }
    
    # Get the best clustering (highest modularity)
    modularities <- sapply(modules, modularity)
    best_method <- names(which.max(modularities))
    
    best_clustering <- modules[[best_method]]
    
    # Create module summary
    module_summary <- data.frame(
      module_id = seq_len(length(best_clustering)),
      size = sizes(best_clustering),
      stringsAsFactors = FALSE
    )
    
    # Get module membership
    module_membership <- data.frame(
      protein = V(graph)$name,
      module = membership(best_clustering),
      stringsAsFactors = FALSE
    )
    
    return(list(
      method = best_method,
      modularity = max(modularities),
      n_modules = length(best_clustering),
      module_summary = module_summary,
      membership = module_membership
    ))
    
  }, error = function(e) {
    print(paste("Module detection error:", e$message))
    return(list())
  })
}

# Create comprehensive visualizations
create_comprehensive_visualizations <- function(network_analysis, all_degs, network_modules) {
  
  if (is.null(network_analysis$graph)) {
    return(list(
      network_data = list(
        nodes = data.frame(id = "No data", label = "No interactions found"),
        edges = data.frame()
      )
    ))
  }
  
  g <- network_analysis$graph
  
  # Create nodes dataframe
  nodes <- data.frame(
    id = V(g)$name,
    label = V(g)$name,
    stringsAsFactors = FALSE
  )
  
  # Add regulation status
  nodes$group <- ifelse(
    nodes$id %in% all_degs$up_genes, "Up-regulated",
    ifelse(nodes$id %in% all_degs$down_genes, "Down-regulated", "Network")
  )
  
  # Add metrics for sizing
  node_metrics <- network_analysis$metrics$node_metrics
  nodes <- merge(nodes, node_metrics[, c("protein", "degree")],
                 by.x = "id", by.y = "protein", all.x = TRUE)
  
  # Size based on degree
  nodes$size <- 10 + sqrt(nodes$degree) * 5
  
  # Color based on regulation
  nodes$color <- ifelse(
    nodes$group == "Up-regulated", "#E74C3C",
    ifelse(nodes$group == "Down-regulated", "#3498DB", "#95A5A6")
  )
  
  # Highlight hubs
  hub_proteins <- network_analysis$hubs$protein
  nodes$borderWidth <- ifelse(nodes$id %in% hub_proteins, 3, 1)
  nodes$borderColor <- ifelse(nodes$id %in% hub_proteins, "#F39C12", "#FFFFFF")
  
  # Add module information if available
  if (!is.null(network_modules$membership)) {
    module_colors <- rainbow(network_modules$n_modules)
    nodes$module <- network_modules$membership$module[match(nodes$id, network_modules$membership$protein)]
    nodes$module_color <- module_colors[nodes$module]
  }
  
  # Create edges dataframe
  edges_df <- as_data_frame(g, what = "edges")
  edges <- data.frame(
    from = edges_df$from,
    to = edges_df$to,
    weight = E(g)$weight,
    stringsAsFactors = FALSE
  )
  
  # Style edges
  edges$width <- 0.5 + edges$weight * 2
  edges$color <- ifelse(edges$weight > 0.7, "#27AE60", "#95A5A6")
  edges$title <- paste("Confidence:", round(edges$weight, 3))
  
  # Add tooltips to nodes
  nodes$title <- paste0(
    "<b>", nodes$label, "</b><br>",
    "Type: ", nodes$group, "<br>",
    "Degree: ", nodes$degree, "<br>",
    if (!is.null(nodes$module)) paste0("Module: ", nodes$module, "<br>") else "",
    if (nodes$id %in% hub_proteins) "<b>HUB PROTEIN</b>" else ""
  )
  
  return(list(
    network_data = list(
      nodes = nodes,
      edges = edges
    )
  ))
}

# Calculate comprehensive statistics
calculate_comprehensive_stats <- function(network_analysis, all_degs, functional_analysis) {
  
  stats <- list(
    # Basic counts
    n_nodes = network_analysis$metrics$global_metrics$n_nodes %||% 0,
    n_edges = network_analysis$metrics$global_metrics$n_edges %||% 0,
    
    # Network properties
    density = network_analysis$metrics$global_metrics$density %||% 0,
    avg_degree = network_analysis$metrics$global_metrics$avg_degree %||% 0,
    clustering = network_analysis$metrics$global_metrics$clustering_coefficient %||% 0,
    
    # DEG coverage
    total_degs = length(all_degs$all_genes),
    degs_in_network = sum(all_degs$all_genes %in% network_analysis$all_proteins),
    coverage_rate = round(sum(all_degs$all_genes %in% network_analysis$all_proteins) /
                            length(all_degs$all_genes) * 100, 1),
    
    # Hub analysis
    n_hubs = nrow(network_analysis$hubs),
    hub_up_regulated = sum(network_analysis$hubs$regulation == "Up"),
    hub_down_regulated = sum(network_analysis$hubs$regulation == "Down"),
    
    # Functional enrichment summary
    n_enriched_pathways = if (!is.null(functional_analysis$all_proteins)) {
      sum(sapply(functional_analysis$all_proteins, function(x) {
        sum(x$Adjusted.P.value < 0.05, na.rm = TRUE)
      }))
    } else 0
  )
  
  return(stats)
}

# Create empty results for error cases
create_empty_ppi_results_comprehensive <- function(message = "No data") {
  list(
    network_data = list(
      nodes = data.frame(
        id = "no_data",
        label = message,
        group = "info",
        color = "#95a5a6",
        size = 30
      ),
      edges = data.frame()
    ),
    ppi_interactions = data.frame(
      gene_from = character(0),
      gene_to = character(0),
      combined_score = numeric(0)
    ),
    network_metrics = list(
      global_metrics = list(n_nodes = 0, n_edges = 0, density = 0, avg_degree = 0),
      node_metrics = data.frame()
    ),
    hub_proteins = data.frame(),
    network_modules = list(),
    functional_enrichment = list(),
    summary_stats = list(
      n_nodes = 0, n_edges = 0, density = 0, avg_degree = 0,
      total_degs = 0, degs_in_network = 0, coverage_rate = 0
    ),
    analysis_params = list(),
    analysis_type = "ppi",
    error = message
  )
}


update_selected_genes_for_network <- function() {
  
  if (exists("rv_deg_main") && !is.null(rv_deg_main$deg_results)) {
    deg_data <- rv_deg_main$deg_results
    
    # Get significant genes
    sig_threshold <- input$pathway_pval_cutoff %||% 0.05
    fc_threshold <- input$log2fc_threshold %||% 1
    
    sig_genes <- deg_data[
      deg_data$adj.P.Val < sig_threshold &
        abs(deg_data$log2FC) > fc_threshold,
    ]
    
    if (nrow(sig_genes) > 0) {
      # Extract and clean gene IDs
      gene_ids <- gsub("\\..*$", "", rownames(sig_genes))
      
      # Create gene lists
      up_genes <- gene_ids[sig_genes$log2FC > 0]
      down_genes <- gene_ids[sig_genes$log2FC < 0]
      
      # Store in network_rv
      network_rv$selected_genes <- list(
        all_genes = gene_ids,
        up_genes = up_genes,
        down_genes = down_genes,
        n_total = length(gene_ids),
        n_up = length(up_genes),
        n_down = length(down_genes)
      )
      
      print(paste("Updated network gene selection:",
                  length(gene_ids), "total,",
                  length(up_genes), "up,",
                  length(down_genes), "down"))
    }
  }
}

# Convert STRING IDs to symbols
convert_to_symbols_comprehensive <- function(interactions, mapped_genes, protein_info) {
  
  # Create ID to symbol mapping
  id_to_symbol <- setNames(mapped_genes$gene, mapped_genes$STRING_id)
  
  # Add protein preferred names as fallback
  if (!is.null(protein_info) && "preferred_name" %in% colnames(protein_info)) {
    for (i in seq_len(nrow(protein_info))) {
      if (!protein_info$protein_external_id[i] %in% names(id_to_symbol)) {
        id_to_symbol[protein_info$protein_external_id[i]] <- protein_info$preferred_name[i]
      }
    }
  }
  
  # Convert interactions
  result <- data.frame(
    gene_from = id_to_symbol[interactions$from],
    gene_to = id_to_symbol[interactions$to],
    combined_score = interactions$combined_score / 1000,  # Normalize to 0-1
    stringsAsFactors = FALSE
  )
  
  # Clean up any remaining STRING IDs
  result$gene_from <- gsub("^[0-9]+\\.", "", result$gene_from)
  result$gene_to <- gsub("^[0-9]+\\.", "", result$gene_to)
  
  # Remove self-loops and invalid entries
  result <- result[
    !is.na(result$gene_from) &
      !is.na(result$gene_to) &
      result$gene_from != result$gene_to,
  ]
  
  return(result)
}

