perform_ppi_analysis_consistent <- function(deg_data, ui_input_params) {
  
  print("🚀 PERFORMING CONSISTENT PPI ANALYSIS...")
  
  # Extract the already-filtered genes from network_rv (set by your gene selection code)
  if (exists("network_rv") && !is.null(network_rv$selected_genes)) {
    selected_genes <- network_rv$selected_genes
  } else {
    return(list(error = "Selected genes not found in network_rv"))
  }
  
  print(paste("Using pre-selected genes:", length(selected_genes$all_genes)))
  print(paste("Up:", length(selected_genes$up_genes)))
  print(paste("Down:", length(selected_genes$down_genes)))
  
  # Use your existing PPI analysis function with FIXED organism parameter
  input_params_fixed <- list(
    organism = as.character(ui_input_params$organism_deg_main %||% "human")[1],  # FIXED
    confidence_threshold = ui_input_params$confidence_threshold %||% 0.4,
    network_type = ui_input_params$network_type %||% "physical",
    max_interactions = ui_input_params$max_interactions %||% 1000,
    expand_network = ui_input_params$expand_network %||% FALSE,
    filter_isolated = ui_input_params$filter_isolated %||% TRUE,
    detect_modules = ui_input_params$detect_modules %||% TRUE,
    run_enrichment = ui_input_params$run_enrichment %||% TRUE
  )
  
  print(paste("Fixed organism parameter:", input_params_fixed$organism))
  
  # Call your existing function with the fixed parameters
  tryCatch({
    
    # Use your existing perform_ppi_analysis_all_degs function
    if (exists("perform_ppi_analysis_all_degs")) {
      result <- perform_ppi_analysis_all_degs(
        deg_data = deg_data,
        input_params = input_params_fixed
      )
    } else {
      # Fallback to the simpler version
      result <- perform_ppi_analysis_simple_fallback(selected_genes, input_params_fixed)
    }
    
    # Add the selected_genes to the result for consistency
    result$selected_genes <- selected_genes
    result$analysis_type <- "ppi"
    result$analysis_status <- "complete"
    
    return(result)
    
  }, error = function(e) {
    print(paste("Error in PPI analysis:", e$message))
    return(list(
      error = paste("PPI analysis failed:", e$message),
      selected_genes = selected_genes,
      analysis_type = "ppi",
      analysis_status = "error"
    ))
  })
}

