# Simple fallback PPI analysis function
perform_ppi_analysis_simple_fallback <- function(selected_genes, input_params) {
  
  print("🔍 Using simple fallback PPI analysis...")
  
  all_genes <- selected_genes$all_genes
  
  if (length(all_genes) < 2) {
    return(list(error = "Need at least 2 genes for PPI analysis"))
  }
  
  # Create mock interactions for now (replace with real STRING query later)
  n_interactions <- min(50, length(all_genes) * 2)
  mock_interactions <- data.frame(
    gene_from = sample(all_genes, n_interactions, replace = TRUE),
    gene_to = sample(all_genes, n_interactions, replace = TRUE),
    combined_score = round(runif(n_interactions, 400, 900)),
    stringsAsFactors = FALSE
  )
  
  # Remove self-interactions
  mock_interactions <- mock_interactions[
    mock_interactions$gene_from != mock_interactions$gene_to,
  ]
  
  # Create basic results structure
  result <- list(
    ppi_data = list(
      interactions = mock_interactions,
      n_interactions = nrow(mock_interactions),
      source = "mock_data_fallback"
    ),
    network_results = list(
      network_data = list(
        nodes = data.frame(
          id = all_genes,
          label = all_genes,
          regulation = ifelse(all_genes %in% selected_genes$up_genes, "up",
                              ifelse(all_genes %in% selected_genes$down_genes, "down", "other")),
          stringsAsFactors = FALSE
        ),
        edges = mock_interactions
      ),
      summary_stats = list(
        n_nodes = length(all_genes),
        n_edges = nrow(mock_interactions),
        avg_degree = round(2 * nrow(mock_interactions) / length(all_genes), 2)
      )
    ),
    analysis_type = "ppi",
    timestamp = Sys.time()
  )
  
  print(paste("✅ Fallback analysis complete:", nrow(mock_interactions), "mock interactions"))
  
  return(result)
}


build_ppi_network_from_interactions <- function(interactions, selected_genes) {
  
  print("🕸️ Building network from interactions...")
  
  if (nrow(interactions) == 0) {
    return(list(
      error = "No interactions to build network",
      network_data = list(),
      summary_stats = list(n_nodes = 0, n_edges = 0)
    ))
  }
  
  # Get all unique genes in network
  all_network_genes <- unique(c(interactions$gene_from, interactions$gene_to))
  
  # Create nodes with regulation status
  nodes <- data.frame(
    id = all_network_genes,
    label = all_network_genes,
    regulation_status = ifelse(
      all_network_genes %in% selected_genes$up_genes, "up-regulated",
      ifelse(all_network_genes %in% selected_genes$down_genes, "down-regulated", "network-neighbor")
    ),
    is_input_gene = all_network_genes %in% selected_genes$all_genes,
    stringsAsFactors = FALSE
  )
  
  # Calculate basic network metrics if igraph is available
  if (requireNamespace("igraph", quietly = TRUE)) {
    
    # Create igraph object
    g <- igraph::graph_from_data_frame(
      interactions[, c("gene_from", "gene_to", "combined_score")],
      directed = FALSE,
      vertices = nodes
    )
    
    # Calculate centrality measures
    nodes$degree <- igraph::degree(g)
    nodes$betweenness <- igraph::betweenness(g)
    nodes$closeness <- igraph::closeness(g)
    
    # Network summary statistics
    summary_stats <- list(
      n_nodes = igraph::vcount(g),
      n_edges = igraph::ecount(g),
      avg_degree = mean(igraph::degree(g)),
      density = igraph::edge_density(g),
      n_components = igraph::components(g)$no
    )
    
  } else {
    
    # Basic calculations without igraph
    summary_stats <- list(
      n_nodes = length(all_network_genes),
      n_edges = nrow(interactions),
      avg_degree = round(2 * nrow(interactions) / length(all_network_genes), 2),
      density = "N/A (igraph not available)",
      n_components = "N/A (igraph not available)"
    )
  }
  
  # Prepare edges for visualization
  edges <- data.frame(
    from = interactions$gene_from,
    to = interactions$gene_to,
    weight = interactions$combined_score,
    confidence = interactions$combined_score / 1000,  # Convert to 0-1 scale
    stringsAsFactors = FALSE
  )
  
  print(paste("✅ Network built:", summary_stats$n_nodes, "nodes,", summary_stats$n_edges, "edges"))
  
  return(list(
    network_data = list(
      nodes = nodes,
      edges = edges
    ),
    summary_stats = summary_stats,
    ppi_interactions = interactions
  ))
}


# Fixed conversion of STRING IDs to gene symbols
convert_string_ids_to_symbols <- function(interactions, mapping) {
  
  print("Converting STRING IDs to gene symbols...")
  
  # Create lookup table from STRING ID to gene symbol
  id_to_symbol <- setNames(mapping$gene, mapping$STRING_id)
  
  # Convert interactions
  interactions_converted <- data.frame(
    gene_from = id_to_symbol[interactions$from],
    gene_to = id_to_symbol[interactions$to],
    combined_score = interactions$combined_score,
    stringsAsFactors = FALSE
  )
  
  # Remove interactions with missing gene symbols
  interactions_clean <- interactions_converted[
    !is.na(interactions_converted$gene_from) &
      !is.na(interactions_converted$gene_to) &
      interactions_converted$gene_from != interactions_converted$gene_to,  # Remove self-interactions
  ]
  
  print(paste("✅ Converted to", nrow(interactions_clean), "clean interactions"))
  
  return(interactions_clean)
}

# Calculate network metrics
calculate_network_metrics_safe <- function(ppi_interactions) {
  
  if (nrow(ppi_interactions) == 0) {
    return(list(
      node_metrics = data.frame(),
      global_metrics = list(
        n_nodes = 0,
        n_edges = 0,
        density = 0,
        avg_degree = 0
      )
    ))
  }
  
  # Get all unique proteins
  all_proteins <- unique(c(ppi_interactions$gene_from, ppi_interactions$gene_to))
  
  # Calculate degree for each protein
  degree_counts <- table(c(ppi_interactions$gene_from, ppi_interactions$gene_to))
  
  # Create node metrics dataframe
  node_metrics <- data.frame(
    protein = names(degree_counts),
    degree = as.numeric(degree_counts),
    stringsAsFactors = FALSE
  )
  
  # Sort by degree
  node_metrics <- node_metrics[order(node_metrics$degree, decreasing = TRUE), ]
  
  # Calculate global metrics
  n_nodes <- length(all_proteins)
  n_edges <- nrow(ppi_interactions)
  density <- if (n_nodes > 1) {
    2 * n_edges / (n_nodes * (n_nodes - 1))
  } else {
    0
  }
  avg_degree <- 2 * n_edges / n_nodes
  
  return(list(
    node_metrics = node_metrics,
    global_metrics = list(
      n_nodes = n_nodes,
      n_edges = n_edges,
      density = round(density, 4),
      avg_degree = round(avg_degree, 2)
    )
  ))
}

# Identify hub proteins
identify_hub_proteins_safe <- function(ppi_interactions, threshold = 3) {
  
  if (nrow(ppi_interactions) == 0) {
    return(data.frame(
      protein = character(0),
      degree = numeric(0),
      hub_score = numeric(0),
      stringsAsFactors = FALSE
    ))
  }
  
  # Calculate degree for each protein
  degree_counts <- table(c(ppi_interactions$gene_from, ppi_interactions$gene_to))
  
  # Create hub proteins dataframe
  hub_df <- data.frame(
    protein = names(degree_counts),
    degree = as.numeric(degree_counts),
    stringsAsFactors = FALSE
  )
  
  # Filter by threshold and add hub score
  hub_df <- hub_df[hub_df$degree >= threshold, ]
  
  if (nrow(hub_df) > 0) {
    hub_df$hub_score <- hub_df$degree / max(hub_df$degree)
    hub_df <- hub_df[order(hub_df$degree, decreasing = TRUE), ]
  }
  
  return(hub_df)
}


create_enhanced_network_viz <- function(ppi_interactions, selected_genes, hub_proteins) {
  
  print("🎨 Creating enhanced network visualization...")
  
  if (nrow(ppi_interactions) == 0) {
    return(list(
      nodes = data.frame(
        id = "no_data",
        label = "No interactions found",
        group = "info",
        color = "#95a5a6",
        size = 30,
        stringsAsFactors = FALSE
      ),
      edges = data.frame()
    ))
  }
  
  # Get all unique genes in network
  network_genes <- unique(c(ppi_interactions$gene_from, ppi_interactions$gene_to))
  print(paste("Network genes:", paste(head(network_genes, 5), collapse = ", ")))
  
  # Extract gene lists for categorization
  up_genes <- if (is.list(selected_genes) && !is.null(selected_genes$up_genes)) {
    unlist(selected_genes$up_genes)
  } else {
    character(0)
  }
  
  down_genes <- if (is.list(selected_genes) && !is.null(selected_genes$down_genes)) {
    unlist(selected_genes$down_genes)
  } else {
    character(0)
  }
  
  all_input_genes <- if (is.list(selected_genes) && !is.null(selected_genes$all_genes)) {
    unlist(selected_genes$all_genes)
  } else {
    character(0)
  }
  
  # Clean gene names for matching
  up_genes <- gsub("\\..*$", "", up_genes)
  down_genes <- gsub("\\..*$", "", down_genes)
  all_input_genes <- gsub("\\..*$", "", all_input_genes)
  
  print(paste("Up-regulated genes:", length(up_genes)))
  print(paste("Down-regulated genes:", length(down_genes)))
  
  # Create nodes dataframe with proper categorization
  nodes <- data.frame(
    id = network_genes,
    label = network_genes,  # Use actual gene symbols
    stringsAsFactors = FALSE
  )
  
  # Categorize nodes
  nodes$group <- "Network"  # Default
  nodes$group[nodes$id %in% up_genes] <- "Up-regulated"
  nodes$group[nodes$id %in% down_genes] <- "Down-regulated"
  nodes$group[nodes$id %in% all_input_genes &
                !(nodes$id %in% c(up_genes, down_genes))] <- "Input"
  
  # Calculate degree for sizing
  degree_counts <- table(c(ppi_interactions$gene_from, ppi_interactions$gene_to))
  nodes$degree <- degree_counts[nodes$id]
  nodes$degree[is.na(nodes$degree)] <- 1
  
  # Set visual properties
  nodes$size <- 15 + sqrt(nodes$degree) * 5
  
  # Color based on group
  color_map <- c(
    "Up-regulated" = "#E74C3C",    # Red
    "Down-regulated" = "#3498DB",   # Blue
    "Input" = "#2ECC71",           # Green
    "Network" = "#95A5A6"          # Gray
  )
  nodes$color <- color_map[nodes$group]
  
  # Enhance hub proteins
  if (nrow(hub_proteins) > 0) {
    hub_mask <- nodes$id %in% hub_proteins$protein
    nodes$size[hub_mask] <- nodes$size[hub_mask] + 10
    nodes$borderWidth <- ifelse(hub_mask, 3, 1)
    nodes$borderColor <- ifelse(hub_mask, "#8E44AD", "#FFFFFF")
    
    # Add star to hub protein labels
    nodes$label[hub_mask] <- paste0("★ ", nodes$label[hub_mask])
  }
  
  # Add tooltips
  nodes$title <- paste0(
    "<b>", nodes$label, "</b><br>",
    "Type: ", nodes$group, "<br>",
    "Degree: ", nodes$degree
  )
  
  # Create edges dataframe
  edges <- data.frame(
    from = ppi_interactions$gene_from,
    to = ppi_interactions$gene_to,
    width = 1 + (ppi_interactions$combined_score * 3),
    color = ifelse(ppi_interactions$combined_score > 0.7, "#27AE60", "#95A5A6"),
    title = paste("Confidence:", round(ppi_interactions$combined_score, 3)),
    stringsAsFactors = FALSE
  )
  
  print(paste("✅ Created visualization with", nrow(nodes), "nodes and", nrow(edges), "edges"))
  print("Node distribution:")
  print(table(nodes$group))
  
  return(list(
    nodes = nodes,
    edges = edges
  ))
}

