# Calculate network density
calculate_network_density <- function(ppi_interactions) {
  
  if (nrow(ppi_interactions) == 0) {
    return(0)
  }
  
  n_nodes <- length(unique(c(ppi_interactions$gene_from, ppi_interactions$gene_to)))
  n_edges <- nrow(ppi_interactions)
  
  if (n_nodes <= 1) {
    return(0)
  }
  
  max_edges <- n_nodes * (n_nodes - 1) / 2
  density <- n_edges / max_edges
  
  return(round(density, 4))
}


calculate_ppi_network_metrics_safe <- function(ppi_interactions, selected_genes) {
  
