      degree_distribution = as.data.frame(degree_counts)
    )
    
    return(metrics)
    
  }, error = function(e) {
    print(paste("Error calculating network metrics:", e$message))
    return(list(
      n_nodes = 0,
      n_edges = 0,
      avg_degree = 0,
      max_degree = 0,
      density = 0
    ))
  })
}

identify_ppi_hubs_safe <- function(ppi_interactions, all_degs) {
  print("🎯 Hub protein analysis:")
  
  tryCatch({
    if (is.null(ppi_interactions) || nrow(ppi_interactions) == 0) {
      return(data.frame(gene = character(0), degree = numeric(0), 
                        hub_type = character(0), stringsAsFactors = FALSE))
    }
    
    # Check column names and fix if needed
    if (!all(c("gene_from", "gene_to") %in% colnames(ppi_interactions))) {
      possible_from <- c("protein1", "protein_a", "stringId_A", "from")
      possible_to <- c("protein2", "protein_b", "stringId_B", "to")
      
      from_col <- intersect(possible_from, colnames(ppi_interactions))[1]
      to_col <- intersect(possible_to, colnames(ppi_interactions))[1]
      
      if (!is.na(from_col) && !is.na(to_col)) {
        colnames(ppi_interactions)[which(colnames(ppi_interactions) == from_col)] <- "gene_from"
        colnames(ppi_interactions)[which(colnames(ppi_interactions) == to_col)] <- "gene_to"
      } else {
        print("  • Could not identify interaction columns")
        return(data.frame(gene = character(0), degree = numeric(0), 
                          hub_type = character(0), stringsAsFactors = FALSE))
      }
    }
    
    # Combine all proteins and clean
    all_proteins <- c(ppi_interactions$gene_from, ppi_interactions$gene_to)
    all_proteins <- gsub("^[0-9]+\\.", "", all_proteins)
    
    degree_table <- table(all_proteins)
    
    hub_df <- data.frame(
      gene = names(degree_table),
      degree = as.numeric(degree_table),
      stringsAsFactors = FALSE
    )
    
    # Sort by degree
    hub_df <- hub_df[order(hub_df$degree, decreasing = TRUE), ]
    
    # ═══════════════════════════════════════════════════════════════
    # FIXED HUB CLASSIFICATION - Use meaningful thresholds
    # ═══════════════════════════════════════════════════════════════
    
    n_proteins <- nrow(hub_df)
    avg_degree <- mean(hub_df$degree, na.rm = TRUE)
    
    # MAJOR HUB: degree > 2x average AND in top 10%
    # HUB: degree > 1.5x average AND in top 25%
    # This prevents classifying everything as a hub in sparse networks
    
    major_hub_threshold <- max(
      avg_degree * 2,                                    # At least 2x average
      quantile(hub_df$degree, 0.90, na.rm = TRUE),       # Or top 10%
      3                                                   # Minimum 3 connections to be major hub
    )
    
    regular_hub_threshold <- max(
      avg_degree * 1.5,                                  # At least 1.5x average
      quantile(hub_df$degree, 0.75, na.rm = TRUE),       # Or top 25%
      2                                                   # Minimum 2 connections to be hub
    )
    
    # Apply classification
    hub_df$hub_type <- "Regular"
    hub_df$hub_type[hub_df$degree >= regular_hub_threshold] <- "Hub"
    hub_df$hub_type[hub_df$degree >= major_hub_threshold] <- "Major Hub"
    
    # Additional metrics for better hub scoring
    hub_df$normalized_degree <- hub_df$degree / max(hub_df$degree, 1)
    hub_df$is_hub <- hub_df$hub_type %in% c("Hub", "Major Hub")
    
    n_major_hubs <- sum(hub_df$hub_type == "Major Hub")
    n_regular_hubs <- sum(hub_df$hub_type == "Hub")
    
    print(paste("  • Total proteins in network:", n_proteins))
    print(paste("  • Average degree:", round(avg_degree, 2)))
    print(paste("  • Major hub threshold:", round(major_hub_threshold, 1), "connections"))
    print(paste("  • Major hubs (top):", n_major_hubs))
    print(paste("  • Regular hubs:", n_regular_hubs))
    print(paste("  • Non-hub proteins:", n_proteins - n_major_hubs - n_regular_hubs))
    
    # Show top hubs
    if (n_major_hubs + n_regular_hubs > 0) {
      top_hubs <- head(hub_df[hub_df$is_hub, ], 5)
      print("  • Top 5 hub proteins:")
      for (i in 1:min(nrow(top_hubs), 5)) {
        print(paste("    -", top_hubs$gene[i], "with degree", top_hubs$degree[i], 
                    paste0("(", top_hubs$hub_type[i], ")")))
      }
    } else {
      print("  • No significant hubs detected (network too sparse)")
    }
    
    return(hub_df)
    
  }, error = function(e) {
    print(paste("  • Hub analysis error:", e$message))
    return(data.frame(gene = character(0), degree = numeric(0), 
                      hub_type = character(0), stringsAsFactors = FALSE))
  })
}

# Local drug-target lookup using the OpenTargets Parquet mount at
# /srv/opentargets (set via OPENTARGETS_DATA_PATH). Returns a data.frame
# matching the column set of query_drug_targets_comprehensive() so
# downstream code doesn't care which source was used.
#
# Returns:
#   NULL           -> caller should fall back to API (unsupported organism,
#                     missing Parquet files, or arrow unavailable)
#   data.frame()   -> lookup ran but no hits for these genes
#   rows > 0       -> drug-gene interactions with clinical_phase populated
#
# Organism support: human only for now (OT's drug_molecule / mechanism_of_action
# are organism-agnostic but the gene -> Ensembl resolution uses the human
# target table). For mouse/rat/etc we return NULL so the API path runs.
query_drug_targets_local <- function(genes, organism = "human",
                                     ot_data_path = Sys.getenv(
                                       "OPENTARGETS_DATA_PATH",
                                       "/srv/opentargets")) {
  if (length(genes) == 0) return(data.frame())
  if (!tolower(as.character(organism)) %in% c("human", "homo sapiens", "9606")) {
    return(NULL)
  }
  if (!requireNamespace("arrow", quietly = TRUE) ||
      !requireNamespace("dplyr", quietly = TRUE)) return(NULL)

  genes_u <- unique(toupper(trimws(as.character(genes))))
  genes_u <- genes_u[genes_u != "" & !is.na(genes_u)]
  if (length(genes_u) == 0) return(data.frame())

  target_path <- file.path(ot_data_path, "target")
  dma_path    <- file.path(ot_data_path, "drug_mechanism_of_action")
  dm_path     <- file.path(ot_data_path, "drug_molecule")
  if (!dir.exists(target_path) || !dir.exists(dma_path) ||
      !dir.exists(dm_path)) {
    return(NULL)
  }

  tryCatch({
    print(paste("💊 [local] Resolving", length(genes_u),
                "gene symbols against OpenTargets Parquet..."))

    # Step 1: symbol -> Ensembl (filter target table).
    # Coerce immediately to plain base-R character vectors to avoid
    # arrow's vctrs_list_of types propagating through setNames/data.frame.
    tgt <- arrow::open_dataset(target_path) %>%
      dplyr::select(id, approvedSymbol) %>%
      dplyr::collect()
    tgt <- tgt[toupper(as.character(tgt$approvedSymbol)) %in% genes_u, ,
               drop = FALSE]
    if (nrow(tgt) == 0) {
      print("  no symbols matched target table")
      return(data.frame())
    }
    tgt_id_chr  <- as.character(tgt$id)
    tgt_sym_chr <- toupper(as.character(tgt$approvedSymbol))
    ensg_of     <- setNames(tgt_sym_chr, tgt_id_chr)

    # Step 2: drug_mechanism_of_action (list-col `targets`)
    dma <- arrow::open_dataset(dma_path) %>% dplyr::collect()
    relevant <- vapply(dma$targets, function(t) {
      if (is.null(t) || length(t) == 0) return(FALSE)
      any(as.character(t) %in% tgt_id_chr)
    }, logical(1))
    dma <- dma[relevant, , drop = FALSE]
    if (nrow(dma) == 0) {
      print("  no drug-mechanism rows for these targets")
      return(data.frame())
    }

    # Step 3: drug_molecule — name + maxClinicalStage for the chembls we need
    needed_chembls <- unique(as.character(unlist(dma$chemblIds)))
    dm <- arrow::open_dataset(dm_path) %>%
      dplyr::select(id, name, maximumClinicalStage) %>%
      dplyr::collect()
    dm <- dm[as.character(dm$id) %in% needed_chembls, , drop = FALSE]
    drug_name_of  <- setNames(as.character(dm$name),
                              as.character(dm$id))
    drug_stage_of <- setNames(as.character(dm$maximumClinicalStage),
                              as.character(dm$id))

    # Step 4: explode (gene, drug) pairs. Collect rows first in a
    # typed list of atomic vectors, then assemble the data.frame in one
    # shot so every column is a base character/numeric/logical vector
    # (no arrow/vctrs types leaking through).
    rows_gene <- rows_drug <- rows_cid <- rows_action <- rows_stage <-
      rows_target <- character(0)
    rows_approved <- logical(0)

    action_types <- as.character(dma$actionType)
    for (i in seq_len(nrow(dma))) {
      t_ids <- intersect(as.character(dma$targets[[i]]), tgt_id_chr)
      if (length(t_ids) == 0) next
      chs <- unique(as.character(dma$chemblIds[[i]]))
      chs <- chs[chs %in% needed_chembls]
      if (length(chs) == 0) next
      for (ens in t_ids) for (cid in chs) {
        stage <- drug_stage_of[[cid]]
        if (is.null(stage)) stage <- NA_character_
        dname <- drug_name_of[[cid]]
        if (is.null(dname) || is.na(dname) || !nzchar(dname)) dname <- cid
        rows_gene     <- c(rows_gene, ensg_of[[ens]])
        rows_drug     <- c(rows_drug, dname)
        rows_cid      <- c(rows_cid, cid)
        rows_action   <- c(rows_action, action_types[i])
        rows_stage    <- c(rows_stage, stage)
        rows_target   <- c(rows_target, ens)
        rows_approved <- c(rows_approved,
                           !is.na(stage) && toupper(stage) == "APPROVAL")
      }
    }
    if (length(rows_gene) == 0) return(data.frame())

    res <- data.frame(
      gene              = rows_gene,
      gene_name         = rows_gene,
      drug_name         = rows_drug,
      molecule_name     = rows_drug,
      drug_concept_id   = rows_cid,
      drug_chembl_id    = rows_cid,
      interaction_type  = rows_action,
      interaction_score = rep(NA_real_, length(rows_gene)),
      is_approved       = rows_approved,
      source            = rep("OpenTargets_local", length(rows_gene)),
      pmids             = rep(NA_character_, length(rows_gene)),
      database          = rep("OpenTargets", length(rows_gene)),
      clinical_phase    = rows_stage,
      target_id         = rows_target,
      stringsAsFactors  = FALSE
    )
    res <- res[!duplicated(paste(res$gene, res$drug_chembl_id)), , drop = FALSE]
    rownames(res) <- NULL
    print(paste("💊 [local] Found", nrow(res), "drug-gene interactions for",
                length(unique(res$gene)), "unique genes"))
    res
  }, error = function(e) {
    print(paste("💊 [local] failed:", e$message, "- caller should fall back to API"))
    NULL
  })
}

query_drug_targets_comprehensive <- function(genes, organism = "human") {
  
  print("💊 Querying drug-target databases...")
  
  if (length(genes) == 0) {
    return(data.frame())
  }
  
  # Clean gene names - ensure uppercase and remove duplicates
  genes <- unique(toupper(trimws(genes)))
  genes <- genes[genes != "" & !is.na(genes)]
  
  all_drug_targets <- data.frame()
  
  # ═══════════════════════════════════════════════════════════════
  # SOURCE 1: DGIdb REST API (v2 - still works as of 2024)
  # ═══════════════════════════════════════════════════════════════
  tryCatch({
    print("  • Querying DGIdb (v5 GraphQL)...")
    
    dgidb_results <- data.frame()
    
    # Process in batches of 50 genes
    batch_size <- 50
    gene_batches <- split(genes, ceiling(seq_along(genes) / batch_size))
    
    url <- "https://dgidb.org/api/graphql"
    
    for (batch_idx in seq_along(gene_batches)) {
      batch_genes <- gene_batches[[batch_idx]]
      
      # Build the GraphQL query properly - use variables approach
      query_string <- '
        query GeneInteractions($names: [String!]!) {
          genes(names: $names) {
            nodes {
              name
              longName
              interactions {
                drug {
                  name
                  conceptId
                  approved
                }
                interactionScore
                interactionTypes {
                  type
                  directionality
                }
                interactionAttributes {
                  name
                  value
                }
                sources {
                  sourceDbName
                }
                publications {
                  pmid
                }
              }
            }
          }
        }
      '
      
      # Create request body with variables
      request_body <- list(
        query = query_string,
        variables = list(names = as.list(batch_genes))
      )
      
      response <- tryCatch({
        httr::POST(
          url,
          body = jsonlite::toJSON(request_body, auto_unbox = TRUE),
          httr::add_headers(
            "Content-Type" = "application/json",
            "Accept" = "application/json"
          ),
          httr::timeout(60)
        )
      }, error = function(e) {
        print(paste("      DGIdb request error:", e$message))
        NULL
      })
      
      if (!is.null(response) && httr::status_code(response) == 200) {
        content <- tryCatch({
          httr::content(response, as = "parsed", encoding = "UTF-8")
        }, error = function(e) NULL)
        
        # Debug: Print response structure on first batch
        if (batch_idx == 1 && !is.null(content)) {
          if (!is.null(content$errors)) {
            print(paste("      DGIdb API errors:", jsonlite::toJSON(content$errors)))
          }
        }
        
        # Parse GraphQL Response
        if (!is.null(content$data$genes$nodes) && length(content$data$genes$nodes) > 0) {
          for (gene_node in content$data$genes$nodes) {
            gene_name <- gene_node$name %||% NA
            gene_long_name <- gene_node$longName %||% ""
            
            if (!is.null(gene_node$interactions) && length(gene_node$interactions) > 0) {
              for (interaction in gene_node$interactions) {
                
                # Extract drug info
                drug_name <- interaction$drug$name %||% NA
                drug_id <- interaction$drug$conceptId %||% NA
                is_approved <- interaction$drug$approved %||% FALSE
                
                # Extract interaction types
                int_types <- "Unknown"
                if (!is.null(interaction$interactionTypes) && length(interaction$interactionTypes) > 0) {
                  types_list <- sapply(interaction$interactionTypes, function(x) {
                    type <- x$type %||% ""
                    dir <- x$directionality %||% ""
                    if (dir != "" && dir != "NA") paste0(type, " (", dir, ")") else type
                  })
                  types_list <- types_list[types_list != "" & !is.na(types_list)]
                  if (length(types_list) > 0) int_types <- paste(unique(types_list), collapse = ", ")
                }
                
                # Extract sources
                sources <- "DGIdb"
                if (!is.null(interaction$sources) && length(interaction$sources) > 0) {
                  src_list <- sapply(interaction$sources, function(x) x$sourceDbName %||% "")
                  src_list <- src_list[src_list != "" & !is.na(src_list)]
                  if (length(src_list) > 0) sources <- paste(unique(src_list), collapse = ", ")
                }
                
                # Extract PMIDs
                pmids <- NA
                if (!is.null(interaction$publications) && length(interaction$publications) > 0) {
                  pmid_list <- sapply(interaction$publications, function(x) x$pmid %||% "")
                  pmid_list <- pmid_list[pmid_list != "" & !is.na(pmid_list)]
                  if (length(pmid_list) > 0) pmids <- paste(pmid_list, collapse = ", ")
                }
                
                # Extract interaction score
                int_score <- as.numeric(interaction$interactionScore %||% NA)
                
                drug_row <- data.frame(
                  gene = gene_name,
                  gene_name = gene_long_name,
                  drug_name = drug_name,
                  drug_concept_id = drug_id,
                  drug_chembl_id = NA,
                  interaction_type = int_types,
                  interaction_score = int_score,
                  is_approved = as.logical(is_approved),
                  source = sources,
                  pmids = pmids,
                  database = "DGIdb",
                  stringsAsFactors = FALSE
                )
                dgidb_results <- rbind(dgidb_results, drug_row)
              }
            }
          }
        }
      } else if (!is.null(response)) {
        print(paste("      DGIdb HTTP error:", httr::status_code(response)))
      }
      
      Sys.sleep(0.5)
    }
    
    if (nrow(dgidb_results) > 0) {
      print(paste("   [OK] DGIdb:", nrow(dgidb_results), "drug-gene interactions found"))
      all_drug_targets <- rbind(all_drug_targets, dgidb_results)
    } else {
      print("   [OK] DGIdb: No interactions found (genes may need symbol conversion)")
    }
    
  }, error = function(e) {
    print(paste("    [FAIL] DGIdb query error:", e$message))
  })
  
  # ═══════════════════════════════════════════════════════════════
  # SOURCE 2: Open Targets Platform - Local Parquet Data
  # ═══════════════════════════════════════════════════════════════
  tryCatch({
    print("  • Querying Open Targets (local data)...")

    opentargets_results <- data.frame()
    ot_data_path <- Sys.getenv("OPENTARGETS_DATA_PATH", "/srv/opentargets")

    # Check if local OT data is available
    ot_local_available <- requireNamespace("arrow", quietly = TRUE) &&
      dir.exists(file.path(ot_data_path, "drug_mechanism_of_action")) &&
      dir.exists(file.path(ot_data_path, "drug_molecule"))

    if (ot_local_available) {
      # Load datasets
      moa_ds <- arrow::open_dataset(file.path(ot_data_path, "drug_mechanism_of_action"))
      drug_ds <- arrow::open_dataset(file.path(ot_data_path, "drug_molecule"))
      target_ds <- arrow::open_dataset(file.path(ot_data_path, "target"))

      moa_all <- moa_ds %>% dplyr::collect()

      # Limit to first 40 genes for speed
      genes_to_query <- genes[1:min(40, length(genes))]

      # Get target info for gene symbol matching
      target_info <- target_ds %>%
        dplyr::select(id, approvedSymbol, approvedName) %>%
        dplyr::collect()

      # Create symbol to ensembl mapping
      symbol_to_ensembl <- setNames(target_info$id, toupper(target_info$approvedSymbol))

      # Convert gene symbols to ensembl IDs for matching
      ensembl_query <- sapply(genes_to_query, function(g) {
        eid <- symbol_to_ensembl[toupper(g)]
        if (!is.na(eid)) return(eid)
        if (grepl("^ENSG", g)) return(g)
        return(NA)
      })
      ensembl_query <- ensembl_query[!is.na(ensembl_query)]

      if (length(ensembl_query) > 0) {
        # Find drug-target links through mechanism of action
        for (i in seq_len(nrow(moa_all))) {
          target_list <- moa_all$targets[[i]]
          if (is.null(target_list)) next
          matched <- intersect(target_list, ensembl_query)
          if (length(matched) == 0) next

          chembl_ids <- moa_all$chemblIds[[i]]
          if (is.null(chembl_ids) || length(chembl_ids) == 0) next

          for (tid in matched) {
            sym <- target_info$approvedSymbol[target_info$id == tid]
            sym_name <- target_info$approvedName[target_info$id == tid]
            if (length(sym) == 0) sym <- tid
            if (length(sym_name) == 0) sym_name <- ""

            for (cid in chembl_ids) {
              # Get drug info
              d_info <- drug_ds %>%
                dplyr::filter(id == cid) %>%
                dplyr::select(id, name, maximumClinicalStage) %>%
                dplyr::collect()

              drug_name <- if (nrow(d_info) > 0) d_info$name[1] else cid
              max_stage <- if (nrow(d_info) > 0) d_info$maximumClinicalStage[1] else NA

              # Convert stage to numeric phase
              phase <- 0
              if (!is.na(max_stage)) {
                ms <- toupper(max_stage)
                if (grepl("APPROVAL|PHASE_4|APPROVED", ms)) phase <- 4
                else if (grepl("PHASE_3", ms)) phase <- 3
                else if (grepl("PHASE_2", ms)) phase <- 2
                else if (grepl("PHASE_1", ms)) phase <- 1
              }

              is_approved <- phase >= 4

              drug_row <- data.frame(
                gene = sym[1],
                gene_name = sym_name[1],
                drug_name = drug_name,
                molecule_name = drug_name,
                drug_concept_id = cid,
                drug_chembl_id = cid,
                interaction_type = moa_all$mechanismOfAction[i] %||% "Unknown",
                interaction_score = NA,
                is_approved = is_approved,
                clinical_phase = phase,
                source = "OpenTargets",
                pmids = NA,
                target_id = tid,
                database = "OpenTargets",
                stringsAsFactors = FALSE
              )
              opentargets_results <- rbind(opentargets_results, drug_row)
            }
          }
        }
      }
    } else {
      print("  • Local OT data not available, skipping OpenTargets source")
    }

    if (nrow(opentargets_results) > 0) {
      # Ensure OpenTargets results have all required columns
      required_cols <- c("gene", "gene_name", "drug_name","molecule_name", "drug_concept_id",
                         "drug_chembl_id", "interaction_type", "interaction_score",
                         "is_approved", "source", "pmids", "database",
                         "clinical_phase", "target_id")
      for (col in required_cols) {
        if (!col %in% colnames(opentargets_results)) {
          opentargets_results[[col]] <- NA
        }
      }

      print(paste("   [OK] OpenTargets:", nrow(opentargets_results), "drug associations found"))

      # Ensure DGIdb results also have all required columns before combining
      if (nrow(all_drug_targets) > 0) {
        for (col in required_cols) {
          if (!col %in% colnames(all_drug_targets)) {
            all_drug_targets[[col]] <- NA
          }
        }
        # Reorder columns to match
        all_drug_targets <- all_drug_targets[, required_cols]
      }

      # Reorder OpenTargets columns to match
      opentargets_results <- opentargets_results[, required_cols]

      # Now safely combine
      all_drug_targets <- rbind(all_drug_targets, opentargets_results)
    } else {
      print("   [OK] OpenTargets: No drugs found")
    }

  }, error = function(e) {
    print(paste("    [FAIL] OpenTargets query error:", e$message))
  })
  
  # ═══════════════════════════════════════════════════════════════
  # PROCESS AND DEDUPLICATE RESULTS
  # ═══════════════════════════════════════════════════════════════
  if (nrow(all_drug_targets) > 0) {
    
    # Ensure all columns exist
    required_cols <- c("gene", "gene_name", "drug_name","molecule_name", "drug_concept_id", 
                       "drug_chembl_id", "interaction_type", "interaction_score",
                       "is_approved", "source", "pmids", "database", 
                       "clinical_phase", "target_id")
    for (col in required_cols) {
      if (!col %in% colnames(all_drug_targets)) {
        all_drug_targets[[col]] <- NA
      }
    }
    
    # Convert is_approved to logical
    all_drug_targets$is_approved <- as.logical(all_drug_targets$is_approved)
    all_drug_targets$is_approved[is.na(all_drug_targets$is_approved)] <- FALSE
    
    # Create a unique key for each gene-drug pair
    all_drug_targets$merge_key <- paste(toupper(all_drug_targets$gene), 
                                        toupper(all_drug_targets$drug_name), 
                                        sep = "|||")
    
    # Split by database
    dgidb_data <- all_drug_targets[all_drug_targets$database == "DGIdb", ]
    ot_data <- all_drug_targets[all_drug_targets$database == "OpenTargets", ]
    
    print(paste("    • Before merge - DGIdb:", nrow(dgidb_data), ", OpenTargets:", nrow(ot_data)))
    
    # Find overlapping entries
    overlapping_keys <- intersect(dgidb_data$merge_key, ot_data$merge_key)
    print(paste("    • Overlapping drug-gene pairs:", length(overlapping_keys)))
    
    # Smart merge for overlapping entries
    if (length(overlapping_keys) > 0) {
      
      merged_results <- data.frame()
      
      for (key in overlapping_keys) {
        dgi_row <- dgidb_data[dgidb_data$merge_key == key, ][1, ]  # Take first if multiple
        ot_row <- ot_data[ot_data$merge_key == key, ][1, ]
        
        # Create merged entry - take best from each
        merged_row <- dgi_row  # Start with DGIdb as base (usually has better interaction types)
        
        # Take clinical_phase from OpenTargets (DGIdb doesn't have this)
        if (!is.na(ot_row$clinical_phase) && ot_row$clinical_phase != 0) {
          merged_row$clinical_phase <- ot_row$clinical_phase
        }
        
        # Take target_id from OpenTargets (useful for linking)
        if (!is.na(ot_row$target_id) && ot_row$target_id != "") {
          merged_row$target_id <- ot_row$target_id
        }
        
        # Take ChEMBL ID from OpenTargets if DGIdb doesn't have it
        if ((is.na(merged_row$drug_chembl_id) || merged_row$drug_chembl_id == "") && 
            !is.na(ot_row$drug_chembl_id)) {
          merged_row$drug_chembl_id <- ot_row$drug_chembl_id
        }
        
        # Prefer OpenTargets approval status if it says approved
        if (ot_row$is_approved == TRUE) {
          merged_row$is_approved <- TRUE
        }
        
        # If DGIdb interaction_type is "Unknown", use OpenTargets
        if (is.na(merged_row$interaction_type) || merged_row$interaction_type == "Unknown" || merged_row$interaction_type == "") {
          if (!is.na(ot_row$interaction_type) && ot_row$interaction_type != "Unknown") {
            merged_row$interaction_type <- ot_row$interaction_type
          }
        }
        
        # Combine sources from both databases
        dgi_sources <- if (!is.na(dgi_row$source)) dgi_row$source else ""
        ot_sources <- if (!is.na(ot_row$source)) ot_row$source else ""
        all_sources <- unique(c(
          unlist(strsplit(dgi_sources, ", ")),
          unlist(strsplit(ot_sources, ", "))
        ))
        all_sources <- all_sources[all_sources != "" & !is.na(all_sources)]
        merged_row$source <- paste(all_sources, collapse = ", ")
        
        # Mark as from both databases
        merged_row$database <- "DGIdb, OpenTargets"
        
        merged_results <- rbind(merged_results, merged_row)
      }
      
      # Get non-overlapping entries from each database
      dgidb_unique <- dgidb_data[!dgidb_data$merge_key %in% overlapping_keys, ]
      ot_unique <- ot_data[!ot_data$merge_key %in% overlapping_keys, ]
      
      print(paste("    • DGIdb-only entries:", nrow(dgidb_unique)))
      print(paste("    • OpenTargets-only entries:", nrow(ot_unique)))
      
      # Combine all results
      all_drug_targets <- rbind(merged_results, dgidb_unique, ot_unique)
      
    }
    
    # Remove the temporary merge_key column
    all_drug_targets$merge_key <- NULL
    
    # Final sort by gene, then by approval status, then by drug name
    all_drug_targets <- all_drug_targets[order(
      all_drug_targets$gene,
      -as.numeric(all_drug_targets$is_approved),
      -as.numeric(!is.na(all_drug_targets$clinical_phase) & all_drug_targets$clinical_phase > 0),
      all_drug_targets$drug_name
    ), ]
    
    # Summary statistics
    n_dgidb_only <- sum(all_drug_targets$database == "DGIdb", na.rm = TRUE)
    n_ot_only <- sum(all_drug_targets$database == "OpenTargets", na.rm = TRUE)
    n_both <- sum(grepl("DGIdb.*OpenTargets|OpenTargets.*DGIdb", all_drug_targets$database), na.rm = TRUE)
    n_with_phase <- sum(!is.na(all_drug_targets$clinical_phase) & all_drug_targets$clinical_phase > 0, na.rm = TRUE)
    
    print(paste("💊 Total unique drug-gene interactions:", nrow(all_drug_targets)))
    print(paste("   • Druggable targets:", length(unique(all_drug_targets$gene))))
    print(paste("   • Unique drugs:", length(unique(all_drug_targets$drug_name))))
    print(paste("   • FDA Approved:", sum(all_drug_targets$is_approved == TRUE, na.rm = TRUE)))
    print(paste("   • With clinical phase:", n_with_phase))
    print(paste("   • Sources: DGIdb-only:", n_dgidb_only, "| OpenTargets-only:", n_ot_only, "| Both:", n_both))
    
  } else {
    print("  ⚠ No drug targets found in databases")
  }
  
  return(all_drug_targets)
}


query_dgidb_enhanced <- function(gene_symbols, 
                                 max_drugs_per_gene = 20,
                                 filter_sources = NULL,
                                 approved_only = FALSE) {
  
  print("╔════════════════════════════════════════════════════════════════╗")
  print("║   ENHANCED DGIdb QUERY (Fast Batch Processing)                 ║")
  print("╚════════════════════════════════════════════════════════════════╝")
  
  if (length(gene_symbols) == 0) {
    print("No gene symbols provided")
    return(data.frame())
  }
  
  start_time <- Sys.time()
  
  # Clean gene symbols
  gene_symbols <- unique(toupper(trimws(gene_symbols)))
  gene_symbols <- gene_symbols[gene_symbols != "" & !is.na(gene_symbols)]
  
  print(paste("📊 Processing", length(gene_symbols), "genes via DGIdb"))
  
  all_results <- data.frame()
  
  # Process in batches of 100 genes (DGIdb handles this well)
  batch_size <- 100
  gene_batches <- split(gene_symbols, ceiling(seq_along(gene_symbols) / batch_size))
  
  print(paste("📦 Split into", length(gene_batches), "batches"))
  
  url <- "https://dgidb.org/api/graphql"
  
  for (batch_idx in seq_along(gene_batches)) {
    batch_genes <- gene_batches[[batch_idx]]
    
    print(paste("  Processing batch", batch_idx, "of", length(gene_batches), 
                "(", length(batch_genes), "genes )"))
    
    # Enhanced GraphQL query with more fields
    query_string <- '
      query GeneInteractions($names: [String!]!) {
        genes(names: $names) {
          nodes {
            name
            longName
            geneCategories {
              name
            }
            interactions {
              drug {
                name
                conceptId
                approved
                drugAttributes {
                  name
                  value
                }
              }
              interactionScore
              interactionTypes {
                type
                directionality
              }
              interactionAttributes {
                name
                value
              }
              sources {
                sourceDbName
                sourceDbVersion
              }
              publications {
                pmid
                citation
              }
            }
          }
        }
      }
    '
    
    request_body <- list(
      query = query_string,
      variables = list(names = as.list(batch_genes))
    )
    
    response <- tryCatch({
      httr::POST(
        url,
        body = jsonlite::toJSON(request_body, auto_unbox = TRUE),
        httr::add_headers(
          "Content-Type" = "application/json",
          "Accept" = "application/json"
        ),
        httr::timeout(120)  # Longer timeout for large batches
      )
    }, error = function(e) {
      print(paste("      DGIdb request error:", e$message))
      NULL
    })
    
    if (!is.null(response) && httr::status_code(response) == 200) {
      content <- tryCatch({
        httr::content(response, as = "parsed", encoding = "UTF-8")
      }, error = function(e) NULL)
      
      if (!is.null(content$data$genes$nodes) && length(content$data$genes$nodes) > 0) {
        for (gene_node in content$data$genes$nodes) {
          gene_symbol <- gene_node$name %||% NA
          gene_long_name <- gene_node$longName %||% ""
          
          # Extract gene categories (druggability info)
          gene_categories <- ""
          if (!is.null(gene_node$geneCategories) && length(gene_node$geneCategories) > 0) {
            cat_list <- sapply(gene_node$geneCategories, function(x) x$name %||% "")
            cat_list <- cat_list[cat_list != ""]
            if (length(cat_list) > 0) gene_categories <- paste(unique(cat_list), collapse = ", ")
          }
          
          if (!is.null(gene_node$interactions) && length(gene_node$interactions) > 0) {
            
            interaction_count <- 0
            
            for (interaction in gene_node$interactions) {
              
              # Apply max_drugs_per_gene limit
              if (interaction_count >= max_drugs_per_gene) break
              
              # Extract drug info
              drug_name <- interaction$drug$name %||% NA
              drug_concept_id <- interaction$drug$conceptId %||% NA
              is_approved <- interaction$drug$approved %||% FALSE
              
              # Apply approved_only filter
              if (approved_only && !isTRUE(is_approved)) next
              
              # Extract drug attributes (clinical phase, mechanism, etc.)
              drug_class <- NA
              mechanism_of_action <- NA
              if (!is.null(interaction$drug$drugAttributes)) {
                for (attr in interaction$drug$drugAttributes) {
                  if (!is.null(attr$name)) {
                    if (tolower(attr$name) == "drug class") drug_class <- attr$value
                    if (tolower(attr$name) == "mechanism of action") mechanism_of_action <- attr$value
                  }
                }
              }
              
              # Extract interaction types with directionality
              int_types <- "Unknown"
              int_directionality <- NA
              if (!is.null(interaction$interactionTypes) && length(interaction$interactionTypes) > 0) {
                types_list <- sapply(interaction$interactionTypes, function(x) x$type %||% "")
                dir_list <- sapply(interaction$interactionTypes, function(x) x$directionality %||% "")
                types_list <- types_list[types_list != ""]
                if (length(types_list) > 0) {
                  int_types <- paste(unique(types_list), collapse = ", ")
                  int_directionality <- paste(unique(dir_list[dir_list != "" & dir_list != "NA"]), collapse = ", ")
                }
              }
              
              # Extract interaction attributes (activity values if available)
              interaction_attrs <- list()
              if (!is.null(interaction$interactionAttributes)) {
                for (attr in interaction$interactionAttributes) {
                  if (!is.null(attr$name) && !is.null(attr$value)) {
                    interaction_attrs[[attr$name]] <- attr$value
                  }
                }
              }
              
              # Extract sources
              sources <- ""
              source_list <- c()
              if (!is.null(interaction$sources) && length(interaction$sources) > 0) {
                source_list <- sapply(interaction$sources, function(x) x$sourceDbName %||% "")
                source_list <- source_list[source_list != ""]
                if (length(source_list) > 0) sources <- paste(unique(source_list), collapse = ", ")
              }
              
              # Apply source filter if specified
              if (!is.null(filter_sources) && length(filter_sources) > 0) {
                if (!any(sapply(filter_sources, function(s) grepl(s, sources, ignore.case = TRUE)))) {
                  next
                }
              }
              
              # Extract PMIDs and citation count
              pmids <- NA
              n_publications <- 0
              if (!is.null(interaction$publications) && length(interaction$publications) > 0) {
                pmid_list <- sapply(interaction$publications, function(x) x$pmid %||% "")
                pmid_list <- pmid_list[pmid_list != "" & !is.na(pmid_list)]
                n_publications <- length(pmid_list)
                if (length(pmid_list) > 0) pmids <- paste(pmid_list, collapse = ", ")
              }
              
              # Get interaction score
              int_score <- as.numeric(interaction$interactionScore %||% NA)
              
              # Determine clinical phase from sources
              clinical_phase <- 0
              if (isTRUE(is_approved)) {
                clinical_phase <- 4
              } else if (any(grepl("ClinicalTrials|Clinical", sources, ignore.case = TRUE))) {
                clinical_phase <- 2  # Assume at least Phase 2 if in clinical trials
              } else if (any(grepl("ChEMBL", sources, ignore.case = TRUE))) {
                clinical_phase <- 1  # ChEMBL compounds are typically Phase 1+
              }
              
              # Calculate confidence score based on available evidence
              confidence_score <- calculate_dgidb_confidence(
                is_approved = is_approved,
                int_score = int_score,
                n_publications = n_publications,
                n_sources = length(source_list),
                has_interaction_type = (int_types != "Unknown")
              )
              
              # Create result row
              drug_row <- data.frame(
                gene_name = gene_symbol,
                gene_long_name = gene_long_name,
                gene_categories = gene_categories,
                drug_name = drug_name,
                drug_concept_id = drug_concept_id,
                is_approved = as.logical(is_approved),
                clinical_phase = clinical_phase,
                drug_class = drug_class,
                mechanism_of_action = mechanism_of_action,
                interaction_type = int_types,
                interaction_directionality = if(is.na(int_directionality) || int_directionality == "") NA else int_directionality,
                interaction_score = int_score,
                confidence_score = confidence_score,
                sources = sources,
                n_sources = length(source_list),
                pmids = pmids,
                n_publications = n_publications,
                database = "DGIdb",
                stringsAsFactors = FALSE
              )
              
              all_results <- rbind(all_results, drug_row)
              interaction_count <- interaction_count + 1
            }
          }
        }
      }
    } else if (!is.null(response)) {
      print(paste("      HTTP error:", httr::status_code(response)))
    }
    
    # Small delay between batches
    if (batch_idx < length(gene_batches)) {
      Sys.sleep(0.3)
    }
  }
  
  elapsed <- round(difftime(Sys.time(), start_time, units = "secs"), 1)
  
  print("╔════════════════════════════════════════════════════════════════╗")
  print(paste("║ ✅ DGIdb QUERY COMPLETE in", elapsed, "seconds"))
  print(paste("║ 📊 Total results:", nrow(all_results), "drug-gene interactions"))
  print(paste("║ 🎯 Unique drugs:", length(unique(all_results$drug_name))))
  print(paste("║ 🧬 Genes with hits:", length(unique(all_results$gene_name))))
  print("╚════════════════════════════════════════════════════════════════╝")
  
  return(all_results)
}

calculate_dgidb_confidence <- function(is_approved, int_score, n_publications, 
                                       n_sources, has_interaction_type) {
  score <- 0.3  # Base score
  
  # Approved drug bonus (+0.3)
  if (isTRUE(is_approved)) score <- score + 0.3
  
  # Interaction score bonus (up to +0.15)
  if (!is.na(int_score) && int_score > 0) {
    score <- score + min(0.15, int_score / 100)
  }
  
  # Publication evidence bonus (up to +0.15)
  if (!is.na(n_publications) && n_publications > 0) {
    score <- score + min(0.15, n_publications * 0.03)
  }
  
  # Multiple sources bonus (up to +0.1)
  if (!is.na(n_sources) && n_sources > 1) {
    score <- score + min(0.1, (n_sources - 1) * 0.025)
  }
  
  # Known interaction type bonus (+0.05)
  if (has_interaction_type) score <- score + 0.05
  
  return(min(1.0, round(score, 3)))
}


create_ppi_network_visualization_safe <- function(ppi_interactions, selected_genes, hub_proteins) {
  
  print("🎨 Creating network visualization...")
  
  tryCatch({
    if (nrow(ppi_interactions) == 0) {
      return(list(
        nodes = data.frame(
          id = "no_data",
          label = "No interactions found",
          color = "#95A5A6",
          size = 30,
          shape = "dot",
          stringsAsFactors = FALSE
        ),
        edges = data.frame()
      ))
    }
    
    # Get all unique proteins
    all_proteins <- unique(c(ppi_interactions$gene_from, ppi_interactions$gene_to))
    
    # Create nodes dataframe
    nodes <- data.frame(
      id = all_proteins,
      label = all_proteins,
      stringsAsFactors = FALSE
    )
    
    # Assign groups safely
    nodes$group <- "Network"
    if (!is.null(selected_genes$up_genes)) {
      nodes$group[nodes$id %in% selected_genes$up_genes] <- "Up-regulated"
    }
    if (!is.null(selected_genes$down_genes)) {
      nodes$group[nodes$id %in% selected_genes$down_genes] <- "Down-regulated"
    }
    if (!is.null(selected_genes$all_genes)) {
      unchanged_genes <- selected_genes$all_genes[!selected_genes$all_genes %in% c(selected_genes$up_genes, selected_genes$down_genes)]
      nodes$group[nodes$id %in% unchanged_genes] <- "Input"
    }
    
    # Calculate degree safely
    degree_counts <- table(c(ppi_interactions$gene_from, ppi_interactions$gene_to))
    nodes$degree <- as.numeric(degree_counts[nodes$id])
    nodes$degree[is.na(nodes$degree)] <- 1
    
    # Set visual properties
    nodes$size <- 15 + sqrt(nodes$degree) * 3
    
    # Color mapping
    color_map <- c(
      "Up-regulated" = "#E74C3C",    # Red
      "Down-regulated" = "#3498DB",   # Blue
      "Input" = "#2ECC71",           # Green
      "Network" = "#95A5A6"          # Gray
    )
    nodes$color <- color_map[nodes$group]
    nodes$color[is.na(nodes$color)] <- "#95A5A6"  # Default gray
    
    # Enhance hub proteins safely
    if (!is.null(hub_proteins) && nrow(hub_proteins) > 0) {
      hub_genes <- hub_proteins$gene
      hub_mask <- nodes$id %in% hub_genes
      
      if (sum(hub_mask) > 0) {
        nodes$size[hub_mask] <- nodes$size[hub_mask] + 8
        nodes$borderWidth <- ifelse(hub_mask, 3, 1)
        nodes$borderColor <- ifelse(hub_mask, "#8E44AD", "#FFFFFF")
        
        # Add star to hub protein labels - SAFE VERSION
        nodes$label[hub_mask] <- paste("★", nodes$label[hub_mask])
      }
    } else {
      nodes$borderWidth <- 1
      nodes$borderColor <- "#FFFFFF"
    }
    
    # Add safe tooltips - NO PASTE0 ERRORS
    nodes$title <- sprintf(
      "<b>%s</b><br>Type: %s<br>Degree: %d",
      nodes$label,
      nodes$group,
      nodes$degree
    )
    
    # Create edges dataframe safely
    edges <- data.frame(
      from = as.character(ppi_interactions$gene_from),
      to = as.character(ppi_interactions$gene_to),
      stringsAsFactors = FALSE
    )
    
    # Set edge properties safely
    confidence_scores <- ppi_interactions$combined_score
    confidence_scores[is.na(confidence_scores)] <- 0.4  # Default value
    
    edges$width <- pmax(1, confidence_scores * 4)
    edges$color <- ifelse(confidence_scores > 0.7, "#27AE60", "#95A5A6")
    
    # Safe edge tooltips
    edges$title <- sprintf("Confidence: %.3f", confidence_scores)
    
    print(paste("✅ Created visualization with", nrow(nodes), "nodes and", nrow(edges), "edges"))
    print("Node distribution:")
    print(table(nodes$group))
    
    return(list(
      nodes = nodes,
      edges = edges
    ))
    
  }, error = function(e) {
    print(paste("❌ Visualization error:", e$message))
    
    # Return error visualization
    return(list(
      nodes = data.frame(
        id = "error_node",
        label = "Visualization Error",
        color = "#E74C3C",
        size = 30,
        shape = "dot",
        title = sprintf("Error: %s", e$message),
        stringsAsFactors = FALSE
      ),
      edges = data.frame()
    ))
  })
}


#' Safe network visualization creation
create_ppi_network_viz_safe <- function(ppi_interactions, selected_genes, hub_proteins) {
  
  tryCatch({
    print("🎨 Creating enhanced network visualization...")
    
    # Get all genes from interactions
    all_genes <- unique(c(ppi_interactions$gene_from, ppi_interactions$gene_to))
    print(paste("Network genes:", paste(all_genes, collapse = ", ")))
    
    if (length(all_genes) == 0) {
      print("⚠️ No genes found for visualization")
      return(list(
        nodes = data.frame(id = character(0), label = character(0), group = character(0), stringsAsFactors = FALSE),
        edges = data.frame(from = character(0), to = character(0), weight = numeric(0), stringsAsFactors = FALSE)
      ))
    }
    
    # Debug selected_genes structure
    print("=== DEBUGGING GENE CATEGORIZATION ===")
    print(paste("selected_genes class:", class(selected_genes)))
    if (is.list(selected_genes)) {
      print(paste("selected_genes names:", paste(names(selected_genes), collapse = ", ")))
      
      if ("up_genes" %in% names(selected_genes)) {
        up_genes <- selected_genes[["up_genes"]]
        print(paste("up_genes:", paste(head(up_genes, 5), collapse = ", ")))
      }
      
      if ("down_genes" %in% names(selected_genes)) {
        down_genes <- selected_genes[["down_genes"]]
        print(paste("down_genes:", paste(head(down_genes, 5), collapse = ", ")))
      }
      
      if ("all_genes" %in% names(selected_genes)) {
        all_input <- selected_genes[["all_genes"]]
        print(paste("all_input_genes:", paste(head(all_input, 5), collapse = ", ")))
      }
    }
    print("=== END GENE CATEGORIZATION DEBUG ===")
    
    # Create nodes dataframe with enhanced styling
    nodes <- data.frame(
      id = all_genes,
      label = all_genes,
      stringsAsFactors = FALSE
    )
    
    # Calculate node degrees
    nodes$degree <- sapply(nodes$id, function(g) {
      sum(ppi_interactions$gene_from == g) + sum(ppi_interactions$gene_to == g)
    })
    
    # Default styling
    nodes$group <- "Network"
    nodes$color <- "#BDC3C7"  # Light gray default
    nodes$size <- 20
    nodes$borderWidth <- 1
    nodes$borderColor <- "#34495E"
    
    # Gene categorization with debugging
    if (is.list(selected_genes)) {
      
      # Up-regulated genes
      if ("up_genes" %in% names(selected_genes)) {
        up_genes <- selected_genes[["up_genes"]]
        if (!is.null(up_genes) && length(up_genes) > 0) {
          # Check for exact matches and partial matches
          exact_matches <- nodes$id %in% up_genes
          print(paste("Up-regulated exact matches:", sum(exact_matches)))
          
          if (sum(exact_matches) > 0) {
            nodes$group[exact_matches] <- "Up-regulated"
            nodes$color[exact_matches] <- "#E74C3C"  # Red
            nodes$size[exact_matches] <- 30
            print(paste("Colored", sum(exact_matches), "nodes as up-regulated"))
          }
        }
      }
      
      # Down-regulated genes
      if ("down_genes" %in% names(selected_genes)) {
        down_genes <- selected_genes[["down_genes"]]
        if (!is.null(down_genes) && length(down_genes) > 0) {
          exact_matches <- nodes$id %in% down_genes
          print(paste("Down-regulated exact matches:", sum(exact_matches)))
          
          if (sum(exact_matches) > 0) {
            nodes$group[exact_matches] <- "Down-regulated"
            nodes$color[exact_matches] <- "#3498DB"  # Blue
            nodes$size[exact_matches] <- 30
            print(paste("Colored", sum(exact_matches), "nodes as down-regulated"))
          }
        }
      }
      
      # Other input genes
      if ("all_genes" %in% names(selected_genes)) {
        all_input <- selected_genes[["all_genes"]]
        if (!is.null(all_input) && length(all_input) > 0) {
          # Only color as input if not already colored as up/down
          other_input <- nodes$id %in% all_input & nodes$group == "Network"
          print(paste("Other input gene matches:", sum(other_input)))
          
          if (sum(other_input) > 0) {
            nodes$group[other_input] <- "Input Gene"
            nodes$color[other_input] <- "#F39C12"  # Orange
            nodes$size[other_input] <- 25
            print(paste("Colored", sum(other_input), "nodes as input genes"))
          }
        }
      }
    }
    
    # Highlight hub proteins
    if (!is.null(hub_proteins) && nrow(hub_proteins) > 0) {
      hub_genes <- hub_proteins[["gene"]]
      if (!is.null(hub_genes) && length(hub_genes) > 0) {
        hub_mask <- nodes$id %in% hub_genes
        nodes$size[hub_mask] <- nodes$size[hub_mask] + 5  # Increase size
        nodes$borderWidth[hub_mask] <- 3
        nodes$borderColor[hub_mask] <- "#8E44AD"  # Purple border for hubs
        print(paste("Enhanced", sum(hub_mask), "hub proteins"))
      }
    }
    
    # Add detailed tooltips
    nodes$title <- paste0(
      "<b>", nodes$label, "</b><br>",
      "Type: ", nodes$group, "<br>",
      "Degree: ", nodes$degree, "<br>",
      "Size: ", nodes$size
    )
    
    # Create enhanced edges
    edges <- data.frame(
      from = as.character(ppi_interactions$gene_from),
      to = as.character(ppi_interactions$gene_to),
      stringsAsFactors = FALSE
    )
    
    # Style edges based on confidence score
    edges$width <- pmax(2, as.numeric(ppi_interactions$combined_score) * 8)
    edges$color <- ifelse(ppi_interactions$combined_score > 0.7, "#27AE60", "#7F8C8D")  # Green for high confidence, gray for normal
    edges$smooth <- TRUE
    edges$title <- paste("Confidence:", round(ppi_interactions$combined_score, 3))
    
    print(paste("✅ Created enhanced visualization with", nrow(nodes), "nodes and", nrow(edges), "edges"))
    print("Final node colors:")
    print(table(nodes$group))
    
    return(list(
      nodes = nodes,
      edges = edges
    ))
    
  }, error = function(e) {
    print(paste("❌ Error creating network visualization:", e$message))
    
    return(list(
      nodes = data.frame(
        id = "error_node",
        label = "Visualization Error",
        group = "error",
        color = "#E74C3C",
        size = 25,
        stringsAsFactors = FALSE
      ),
      edges = data.frame(
        from = character(0),
        to = character(0),
        weight = numeric(0),
        stringsAsFactors = FALSE
      )
    ))
  })
}

create_ultra_safe_summary <- function(ppi_interactions, hub_proteins, network_metrics) {
  list(
    ppi = list(
      total_proteins = network_metrics$global_metrics$n_nodes,
      total_interactions = network_metrics$global_metrics$n_edges,
      hub_proteins = nrow(hub_proteins),
      network_density = network_metrics$global_metrics$density
    )
  )
}

# Helper functions for the debug version

create_simple_network_metrics <- function(ppi_interactions, converted_genes) {
  
  all_nodes <- unique(c(ppi_interactions$gene_from, ppi_interactions$gene_to))
  n_nodes <- length(all_nodes)
  n_edges <- nrow(ppi_interactions)
  
  # Calculate basic network metrics
  max_possible_edges <- n_nodes * (n_nodes - 1) / 2
  density <- if (max_possible_edges > 0) n_edges / max_possible_edges else 0
  avg_degree <- if (n_nodes > 0) (2 * n_edges) / n_nodes else 0
  
  global_metrics <- list(
    n_nodes = n_nodes,
    n_edges = n_edges,
    density = density,
    avg_degree = avg_degree,
    clustering_coefficient = 0.3,  # Mock value
    diameter = 3,  # Mock value
    avg_path_length = 2.5  # Mock value
  )
  
  # Node-level metrics (simplified)
  node_metrics <- data.frame(
    gene = all_nodes,
    degree = sapply(all_nodes, function(g) {
      sum(ppi_interactions$gene_from == g) + sum(ppi_interactions$gene_to == g)
    }),
    stringsAsFactors = FALSE
  )
  
  return(list(
    global_metrics = global_metrics,
    node_metrics = node_metrics
  ))
}

identify_simple_hubs <- function(ppi_interactions, converted_genes) {
  
  all_nodes <- unique(c(ppi_interactions$gene_from, ppi_interactions$gene_to))
  
  # Calculate degree for each node
  hub_data <- data.frame(
    gene = all_nodes,
    degree = sapply(all_nodes, function(g) {
      sum(ppi_interactions$gene_from == g) + sum(ppi_interactions$gene_to == g)
    }),
    stringsAsFactors = FALSE
  )
  
  # Identify top hubs (top 20% by degree)
  top_threshold <- quantile(hub_data$degree, 0.8)
  hubs <- hub_data[hub_data$degree >= top_threshold, ]
  hubs <- hubs[order(hubs$degree, decreasing = TRUE), ]
  
  return(hubs)
}

#' Create simple PPI visualization
create_simple_ppi_viz_fixed <- function(ppi_interactions, selected_genes, hub_proteins) {
  
  # Handle empty interactions
  if (nrow(ppi_interactions) == 0) {
    print("⚠️ No interactions to visualize")
    return(list(
      nodes = data.frame(
        id = character(0), label = character(0), group = character(0),
        color = character(0), size = numeric(0), title = character(0),
        stringsAsFactors = FALSE
      ),
      edges = data.frame(
        from = character(0), to = character(0), width = numeric(0),
        color = character(0), title = character(0),
        stringsAsFactors = FALSE
      )
    ))
  }
  
  # Get all unique genes
  all_genes <- unique(c(ppi_interactions$gene_from, ppi_interactions$gene_to))
  
  if (length(all_genes) == 0) {
    print("⚠️ No genes found in interactions")
    return(list(
      nodes = data.frame(id = character(0), label = character(0), group = character(0),
                         color = character(0), size = numeric(0), title = character(0),
                         stringsAsFactors = FALSE),
      edges = data.frame(from = character(0), to = character(0), width = numeric(0),
                         color = character(0), title = character(0),
                         stringsAsFactors = FALSE)
    ))
  }
  
  # Create nodes dataframe with ALL required columns
  nodes <- data.frame(
    id = all_genes,
    label = all_genes,
    stringsAsFactors = FALSE
  )
  
  # Add colors and groups
  nodes$color <- sapply(nodes$id, function(g) {
    if (!is.null(selected_genes$up_genes_symbols) && g %in% selected_genes$up_genes_symbols) {
      return("#E74C3C")  # Red for up-regulated
    } else if (!is.null(selected_genes$down_genes_symbols) && g %in% selected_genes$down_genes_symbols) {
      return("#3498DB")  # Blue for down-regulated
    } else {
      return("#95A5A6")  # Gray for other
    }
  })
  
  # Add group column (REQUIRED for visNetwork)
  nodes$group <- sapply(nodes$id, function(g) {
    if (!is.null(selected_genes$up_genes_symbols) && g %in% selected_genes$up_genes_symbols) {
      return("Up-regulated")
    } else if (!is.null(selected_genes$down_genes_symbols) && g %in% selected_genes$down_genes_symbols) {
      return("Down-regulated")
    } else {
      return("Interacting")
    }
  })
  
  # Add sizes
  nodes$size <- 15  # Default size
  if (!is.null(hub_proteins) && nrow(hub_proteins) > 0) {
    nodes$size[nodes$id %in% hub_proteins$gene] <- 25
  }
  
  # Add hover information
  nodes$title <- paste0("<b>", nodes$label, "</b><br>",
                        "Group: ", nodes$group, "<br>",
                        "Connections: ", sapply(nodes$id, function(g) {
                          sum(ppi_interactions$gene_from == g) + sum(ppi_interactions$gene_to == g)
                        }))
  
  # Create edges dataframe
  edges <- data.frame(
    from = ppi_interactions$gene_from,
    to = ppi_interactions$gene_to,
    width = pmax(1, ppi_interactions$combined_score * 3),
    color = "#7F8C8D",
    title = paste("Score:", round(ppi_interactions$combined_score, 3)),
    stringsAsFactors = FALSE
  )
  
  print(paste("🎨 Created visualization:", nrow(nodes), "nodes,", nrow(edges), "edges"))
  
  return(list(nodes = nodes, edges = edges))
}

generate_simple_ppi_summary <- function(ppi_interactions, hub_proteins, network_metrics, converted_genes) {
  
  summary <- list(
    ppi = list(
      total_proteins = network_metrics$global_metrics$n_nodes,
      total_interactions = network_metrics$global_metrics$n_edges,
      hub_proteins = if(!is.null(hub_proteins)) nrow(hub_proteins) else 0,
      network_density = round(network_metrics$global_metrics$density * 100, 2),
      avg_degree = round(network_metrics$global_metrics$avg_degree, 2),
      up_regulated_in_network = length(intersect(
        unique(c(ppi_interactions$gene_from, ppi_interactions$gene_to)),
        converted_genes$up_genes_symbols
      )),
      down_regulated_in_network = length(intersect(
        unique(c(ppi_interactions$gene_from, ppi_interactions$gene_to)),
        converted_genes$down_genes_symbols
      ))
    )
  )
  
  return(summary)
}

create_simple_ppi_visualization <- function(ppi_interactions, converted_genes) {
  all_genes <- unique(c(ppi_interactions$gene_from, ppi_interactions$gene_to))
  
  nodes <- data.frame(
    id = all_genes,
    label = all_genes,
    color = sample(c("#E74C3C", "#3498DB", "#95A5A6"), length(all_genes), replace = TRUE),
    size = sample(15:30, length(all_genes), replace = TRUE),
    shape = "dot",
    group = sample(c("Up-regulated", "Down-regulated", "Network neighbor"), length(all_genes), replace = TRUE),
    title = paste0("<b>", all_genes, "</b><br>Mock protein for testing"),
    stringsAsFactors = FALSE
  )
  
  edges <- ppi_interactions %>%
    select(from = gene_from, to = gene_to, combined_score) %>%
    mutate(
      width = combined_score * 3,
      color = "#7F8C8D",
      title = paste0("Interaction: ", from, " — ", to, "<br>Confidence: ", round(combined_score, 3))
    )
  
  list(nodes = nodes, edges = edges)
}

create_simple_summary_stats <- function(ppi_interactions, converted_genes) {
  n_proteins <- length(unique(c(ppi_interactions$gene_from, ppi_interactions$gene_to)))
  
  list(
    basic_stats = list(
      total_proteins = n_proteins,
      total_interactions = nrow(ppi_interactions),
      input_genes_in_network = n_proteins,
      network_coverage = 100
    ),
    hub_stats = list(
      total_hubs = min(3, n_proteins),
      input_gene_hubs = min(2, n_proteins),
      hub_percentage = min(30, (3/n_proteins)*100)
    ),
    topology_stats = list(
      density = min(1, nrow(ppi_interactions) / (n_proteins * (n_proteins - 1) / 2)),
      avg_degree = 2 * nrow(ppi_interactions) / n_proteins,
      clustering_coefficient = 0.3
    ),
    confidence_stats = list(
      avg_confidence = mean(ppi_interactions$combined_score),
      median_confidence = median(ppi_interactions$combined_score),
      high_confidence_count = sum(ppi_interactions$combined_score >= 0.8),
      medium_confidence_count = sum(ppi_interactions$combined_score >= 0.6 & ppi_interactions$combined_score < 0.8),
      low_confidence_count = sum(ppi_interactions$combined_score < 0.6)
    )
  )  # <- This closing parenthesis and brace were missing!
}




