convert_interactions_to_symbols_safe <- function(interactions, string_db) {
  
  tryCatch({
    print("🔄 Starting enhanced symbol conversion...")
    print(paste("Processing", nrow(interactions), "interactions"))
    
    # Debug the interactions structure
    print("Interactions structure:")
    print(str(interactions))
    print("Column names:")
    print(colnames(interactions))
    
    # Get unique STRING IDs safely
    from_ids <- as.character(interactions$from)
    to_ids <- as.character(interactions$to)
    all_string_ids <- unique(c(from_ids, to_ids))
    
    print(paste("Found", length(all_string_ids), "unique STRING IDs"))
    print(paste("Sample IDs:", paste(head(all_string_ids, 3), collapse = ", ")))
    
    # BYPASS get_aliases() - use direct ID cleaning instead
    print("🔧 Using direct STRING ID to gene symbol conversion...")
    
    # Method 1: Clean STRING IDs directly (remove species prefix)
    clean_ids <- gsub("^[0-9]+\\.", "", all_string_ids)
    
    # Method 2: Try to get better names using STRING API if available
    id_to_gene <- setNames(clean_ids, all_string_ids)
    
    # Try alternative method using STRING database info if available
    tryCatch({
      # Use the protein info if available in the string_db object
      if (exists("proteins_df", envir = environment(string_db$map))) {
        proteins_info <- get("proteins_df", envir = environment(string_db$map))
        if (!is.null(proteins_info) && nrow(proteins_info) > 0) {
          # Match STRING IDs to preferred names
          for (id in all_string_ids) {
            matching_row <- which(proteins_info$protein_external_id == id)
            if (length(matching_row) > 0) {
              preferred_name <- proteins_info$preferred_name[matching_row[1]]
              if (!is.na(preferred_name) && nchar(preferred_name) > 0) {
                id_to_gene[id] <- preferred_name
              }
            }
          }
        }
      }
    }, error = function(e) {
      print("Alternative method failed, using cleaned IDs")
    })
    
    # Create result dataframe with proper gene symbols
    result_df <- data.frame(
      gene_from = id_to_gene[from_ids],
      gene_to = id_to_gene[to_ids],
      combined_score = as.numeric(interactions$combined_score),
      interaction_source = "STRING_enhanced",
      stringsAsFactors = FALSE
    )
    
    # Additional cleaning: prefer actual gene symbols over ENSP IDs
    result_df$gene_from <- sapply(result_df$gene_from, function(x) {
      if (grepl("^ENSP", x)) {
        # Try to extract a better name from the ID
        cleaned <- gsub("^ENSP[0-9]+", "", x)
        if (nchar(cleaned) > 2) {
          return(cleaned)
        }
      }
      return(x)
    })
    
    result_df$gene_to <- sapply(result_df$gene_to, function(x) {
      if (grepl("^ENSP", x)) {
        cleaned <- gsub("^ENSP[0-9]+", "", x)
        if (nchar(cleaned) > 2) {
          return(cleaned)
        }
      }
      return(x)
    })
    
    # Remove self-interactions and invalid entries
    result_df <- result_df[
      !is.na(result_df$gene_from) &
        !is.na(result_df$gene_to) &
        result_df$gene_from != result_df$gene_to &
        nchar(result_df$gene_from) > 0 &
        nchar(result_df$gene_to) > 0,
    ]
    
    print(paste("✅ Enhanced symbol conversion completed:", nrow(result_df), "valid interactions"))
    
    # Show sample of conversions
    if (nrow(result_df) > 0) {
      print("Sample conversions:")
      sample_df <- head(result_df, 3)
      for (i in seq_len(nrow(sample_df))) {
        print(paste("  ", sample_df$gene_from[i], "<->", sample_df$gene_to[i],
                    "(score:", round(sample_df$combined_score[i], 3), ")"))
      }
    }
    
    return(result_df)
    
  }, error = function(e) {
    print(paste("❌ Enhanced symbol conversion error:", e$message))
    
    # Ultimate fallback - just clean the IDs
    tryCatch({
      print("🔧 Using ultimate fallback conversion...")
      
      result_df <- data.frame(
        gene_from = gsub("^[0-9]+\\.", "", as.character(interactions$from)),
        gene_to = gsub("^[0-9]+\\.", "", as.character(interactions$to)),
        combined_score = as.numeric(interactions$combined_score),
        interaction_source = "STRING_cleaned",
        stringsAsFactors = FALSE
      )
      
      # Additional cleaning for ENSP IDs
      result_df$gene_from <- gsub("^ENSP[0-9]+\\.?", "", result_df$gene_from)
      result_df$gene_to <- gsub("^ENSP[0-9]+\\.?", "", result_df$gene_to)
      
      print(paste("✅ Fallback conversion completed:", nrow(result_df), "interactions"))
      
      return(result_df)
      
    }, error = function(e2) {
      print(paste("❌ Ultimate fallback also failed:", e2$message))
      
      # Return empty but properly structured dataframe
      return(data.frame(
        gene_from = character(0),
        gene_to = character(0),
        combined_score = numeric(0),
        interaction_source = character(0),
        stringsAsFactors = FALSE
      ))
    })
  })
}

