# Create user-friendly message
create_user_message <- function(results_summary) {
  
  if (results_summary$mapped_genes == 0) {
    return(paste0(
      "❌ NO PROTEIN INTERACTION DATA AVAILABLE\n\n",
      "ISSUE: None of your ", results_summary$attempted_genes, " genes could be mapped to the STRING database.\n\n",
      "POSSIBLE SOLUTIONS:\n",
      "• Check if gene symbols are in standard format (e.g., 'TP53', 'BRCA1')\n",
      "• Try converting from Ensembl IDs to gene symbols first\n",
      "• Verify genes are from the correct organism (", attr(results_summary, "organism", TRUE), ")\n\n",
      "NOTE: No mock data was generated - this analysis requires real interaction data."
    ))
  } else if (results_summary$found_interactions == 0) {
    mapping_rate <- round((results_summary$mapped_genes / results_summary$attempted_genes) * 100, 1)
    return(paste0(
      "❌ NO PROTEIN INTERACTIONS FOUND\n\n",
      "GENE MAPPING: ", results_summary$mapped_genes, " out of ", results_summary$attempted_genes,
      " genes mapped successfully (", mapping_rate, "%)\n\n",
      "ISSUE: The mapped genes do not have documented protein-protein interactions in the STRING database.\n\n",
      "POSSIBLE SOLUTIONS:\n",
      "• Lower the confidence threshold (currently set high)\n",
      "• Try genes from the same biological pathway\n",
      "• Include more well-studied genes in your analysis\n\n",
      "NOTE: This is real data - no interactions means no documented evidence of protein interactions."
    ))
  } else {
    return("✅ Real protein interaction data successfully retrieved from STRING database!")
  }
}

