#' Map Gene Names to STRING IDs
map_genes_to_string_ids <- function(genes, species_id) {
  
  # Create query for STRING API
  genes_query <- paste(genes, collapse = "%0d")
  
  # STRING mapping API endpoint
  string_api_url <- paste0(
    "https://string-db.org/api/tsv/get_string_ids?identifiers=",
    genes_query,
    "&species=", species_id,
    "&limit=1"
  )
  
  tryCatch({
    response <- httr::GET(string_api_url)
    
    if (httr::status_code(response) == 200) {
      content <- httr::content(response, as = "text", encoding = "UTF-8")
      
      # Parse TSV response
      mapped_data <- read.table(
        text = content,
        header = TRUE,
        sep = "\t",
        stringsAsFactors = FALSE,
        quote = ""
      )
      
      return(mapped_data)
    } else {
      warning("Failed to map genes to STRING IDs")
      return(data.frame())
    }
    
  }, error = function(e) {
    warning(paste("Error mapping genes:", e$message))
    # Fallback: create mock STRING IDs
    return(create_mock_string_mapping(genes, species_id))
  })
}

#' Get STRING Interactions
get_string_interactions <- function(string_ids, species_id, confidence, max_interactions) {
  
  # Limit to reasonable number of proteins
  if (length(string_ids) > 200) {
    string_ids <- string_ids[1:200]
  }
  
  # Create query
  ids_query <- paste(string_ids, collapse = "%0d")
  
  # STRING interaction API endpoint
  string_api_url <- paste0(
    "https://string-db.org/api/tsv/network?identifiers=",
    ids_query,
    "&species=", species_id,
    "&required_score=", as.integer(confidence * 1000),
    "&limit=", max_interactions
  )
  
  tryCatch({
    response <- httr::GET(string_api_url)
    
    if (httr::status_code(response) == 200) {
      content <- httr::content(response, as = "text", encoding = "UTF-8")
      
      # Parse TSV response
      interactions <- read.table(
        text = content,
        header = TRUE,
        sep = "\t",
        stringsAsFactors = FALSE,
        quote = ""
      )
      
      return(interactions)
    } else {
      warning("Failed to get STRING interactions")
      return(data.frame())
    }
    
  }, error = function(e) {
    warning(paste("Error getting interactions:", e$message))
    # Fallback: create mock interactions
    return(create_mock_interactions(string_ids, confidence))
  })
}

