#' Add Gene Names to Interactions
add_gene_names_to_interactions <- function(interactions, mapped_genes) {
  
  # Create lookup table
  lookup <- setNames(mapped_genes$preferredName, mapped_genes$stringId)
  
  # Add gene names
  interactions %>%
    mutate(
      gene_from = lookup[stringId_A] %||% preferredName_A,
      gene_to = lookup[stringId_B] %||% preferredName_B,
      combined_score = score,
      interaction_source = "STRING"
    ) %>%
    select(gene_from, gene_to, combined_score, interaction_source, everything()) %>%
    filter(!is.na(gene_from), !is.na(gene_to))
}

#' Add Network Neighbors (expand network)
add_network_neighbors <- function(interactions, mapped_genes, species_id, confidence) {
  
  # Get all genes in current network
  network_genes <- unique(c(interactions$gene_from, interactions$gene_to))
  
  # If network is small, add some neighbors
  if (length(network_genes) < 20) {
    
    # Get high-degree proteins from the network
    degree_counts <- table(c(interactions$gene_from, interactions$gene_to))
    hub_genes <- names(degree_counts)[degree_counts >= 3]
    
    if (length(hub_genes) > 0) {
      # Query neighbors of hub genes (simplified)
      # In practice, you'd make additional STRING API calls here
      print(paste("Network expanded with", length(hub_genes), "hub proteins"))
    }
  }
  
  return(interactions)
}

# ============================================================================
# 2. NETWORK ANALYSIS AND METRICS
# ============================================================================

#' Calculate Comprehensive Network Metrics
calculate_comprehensive_network_metrics <- function(ppi_interactions, selected_genes) {
  
  library(igraph)
  
  # Create graph from interactions
  g <- graph_from_data_frame(
    ppi_interactions[, c("gene_from", "gene_to", "combined_score")],
    directed = FALSE
  )
  
  # Remove self-loops and multiple edges
  g <- simplify(g, remove.multiple = TRUE, remove.loops = TRUE)
  
  # Basic metrics
  n_nodes <- vcount(g)
  n_edges <- ecount(g)
  density <- edge_density(g)
  
  # Centrality measures for all nodes
  node_metrics <- data.frame(
    gene = V(g)$name,
    degree = degree(g),
    betweenness = betweenness(g, normalized = TRUE),
    closeness = closeness(g, normalized = TRUE),
    eigenvector = eigen_centrality(g)$vector,
    page_rank = page_rank(g)$vector,
    stringsAsFactors = FALSE
  )
  
  # Global network properties
  global_metrics <- list(
    n_nodes = n_nodes,
    n_edges = n_edges,
    density = density,
    avg_degree = mean(degree(g)),
    clustering_coefficient = transitivity(g, type = "global"),
    diameter = ifelse(is.connected(g), diameter(g), NA),
    avg_path_length = ifelse(is.connected(g), mean_distance(g), NA),
    n_components = components(g)$no,
    largest_component_size = max(components(g)$csize),
    assortativity = assortativity_degree(g)
  )
  
  # Calculate metrics specifically for input genes
  input_genes_in_network <- intersect(selected_genes$all_genes, V(g)$name)
  input_gene_metrics <- node_metrics %>%
    filter(gene %in% input_genes_in_network) %>%
    summarise(
      avg_degree_input = mean(degree),
      avg_betweenness_input = mean(betweenness),
      avg_eigenvector_input = mean(eigenvector),
      n_input_genes_in_network = n()
    )
  
  return(list(
    global_metrics = global_metrics,
    node_metrics = node_metrics,
    input_gene_metrics = input_gene_metrics
  ))
}

#' Identify Comprehensive Hub Proteins
identify_comprehensive_hubs <- function(ppi_interactions, selected_genes) {
  
  library(igraph)
  
  # Create graph
  g <- graph_from_data_frame(
    ppi_interactions[, c("gene_from", "gene_to", "combined_score")],
    directed = FALSE
  )
  g <- simplify(g)
  
  # Calculate multiple centrality measures
  hub_metrics <- data.frame(
    gene = V(g)$name,
    degree = degree(g),
    betweenness = betweenness(g, normalized = TRUE),
    closeness = closeness(g, normalized = TRUE),
    eigenvector = eigen_centrality(g)$vector,
    page_rank = page_rank(g)$vector,
    stringsAsFactors = FALSE
  ) %>%
    # Calculate composite hub score
    mutate(
      hub_score = scale(degree)[,1] +
        scale(betweenness)[,1] +
        scale(eigenvector)[,1] +
        scale(page_rank)[,1],
      is_input_gene = gene %in% selected_genes$all_genes,
      regulation_status = case_when(
        gene %in% selected_genes$up_genes ~ "Up-regulated",
        gene %in% selected_genes$down_genes ~ "Down-regulated",
        gene %in% selected_genes$all_genes ~ "Input gene",
        TRUE ~ "Network neighbor"
      )
    ) %>%
    arrange(desc(hub_score))
  
  # Identify different types of hubs
  hub_classification <- hub_metrics %>%
    mutate(
      hub_type = case_when(
        degree >= quantile(degree, 0.9) & betweenness >= quantile(betweenness, 0.9) ~ "Super hub",
        degree >= quantile(degree, 0.8) ~ "Degree hub",
        betweenness >= quantile(betweenness, 0.8) ~ "Bottleneck",
        eigenvector >= quantile(eigenvector, 0.8) ~ "Authority hub",
        TRUE ~ "Regular node"
      )
    )
  
  return(hub_classification)
}

#' Detect Network Communities
detect_network_communities <- function(ppi_interactions) {
  
  library(igraph)
  
  # Create graph
  g <- graph_from_data_frame(
    ppi_interactions[, c("gene_from", "gene_to", "combined_score")],
    directed = FALSE
  )
  g <- simplify(g)
  
  # Try multiple community detection algorithms
  communities_results <- list()
  
  # Louvain algorithm (fast and good)
  tryCatch({
    louvain <- cluster_louvain(g, weights = E(g)$combined_score)
    communities_results$louvain <- list(
      membership = membership(louvain),
      modularity = modularity(louvain),
      n_communities = length(louvain)
    )
  }, error = function(e) {
    print("Louvain clustering failed")
  })
  
  # Leiden algorithm (if available)
  tryCatch({
    if (require("leiden", quietly = TRUE)) {
      leiden_result <- leiden(g, weights = E(g)$combined_score)
      communities_results$leiden <- list(
        membership = leiden_result,
        n_communities = length(unique(leiden_result))
      )
    }
  }, error = function(e) {
    print("Leiden clustering not available")
  })
  
  # Walktrap algorithm
  tryCatch({
    walktrap <- cluster_walktrap(g, weights = E(g)$combined_score)
    communities_results$walktrap <- list(
      membership = membership(walktrap),
      modularity = modularity(walktrap),
      n_communities = length(walktrap)
    )
  }, error = function(e) {
    print("Walktrap clustering failed")
  })
  
  # Return the best result (highest modularity)
  best_algorithm <- "louvain"  # default
  if (length(communities_results) > 1) {
    modularities <- sapply(communities_results, function(x) x$modularity %||% 0)
    best_algorithm <- names(which.max(modularities))
  }
  
  if (length(communities_results) > 0) {
    best_result <- communities_results[[best_algorithm]]
    
    # Create community summary
    community_summary <- data.frame(
      gene = V(g)$name,
      community = best_result$membership,
      stringsAsFactors = FALSE
    ) %>%
      group_by(community) %>%
      summarise(
        size = n(),
        genes = list(gene),
        .groups = 'drop'
      ) %>%
      arrange(desc(size))
    
    return(list(
      algorithm_used = best_algorithm,
      modularity = best_result$modularity,
      n_communities = best_result$n_communities,
      communities = community_summary,
      node_membership = data.frame(
        gene = V(g)$name,
        community = best_result$membership,
        stringsAsFactors = FALSE
      )
    ))
  } else {
    return(NULL)
  }
}

# ============================================================================
# 3. FUNCTIONAL ANALYSIS
# ============================================================================

#' Perform Network Functional Analysis
perform_network_functional_analysis <- function(ppi_interactions, selected_genes, organism) {
  
  # Extract all proteins in the network
  all_network_proteins <- unique(c(ppi_interactions$gene_from, ppi_interactions$gene_to))
  input_proteins <- intersect(all_network_proteins, selected_genes$all_genes)
  neighbor_proteins <- setdiff(all_network_proteins, selected_genes$all_genes)
  
  enrichment_results <- list()
  
  # Perform enrichment for different gene sets
  if (require("enrichR", quietly = TRUE)) {
    
    # Set up databases based on organism
    if (organism == "human") {
      databases <- c(
        "GO_Biological_Process_2023",
        "GO_Molecular_Function_2023",
        "KEGG_2021_Human",
        "Reactome_2022",
        "WikiPathway_2023_Human"
      )
    } else {
      databases <- c(
        "GO_Biological_Process_2021",
        "GO_Molecular_Function_2021",
        "KEGG_2019"
      )
    }
    
    # Enrichment for all network proteins
    if (length(all_network_proteins) >= 3) {
      tryCatch({
        enrichment_results$all_network <- tx_enrichr_local(all_network_proteins, databases)
      }, error = function(e) {
        print("Enrichment failed for all network proteins")
      })
    }
    
    # Enrichment for input proteins only
    if (length(input_proteins) >= 3) {
      tryCatch({
        enrichment_results$input_proteins <- tx_enrichr_local(input_proteins, databases)
      }, error = function(e) {
        print("Enrichment failed for input proteins")
      })
    }
    
    # Enrichment for network neighbors
    if (length(neighbor_proteins) >= 3) {
      tryCatch({
        enrichment_results$neighbor_proteins <- tx_enrichr_local(neighbor_proteins, databases)
      }, error = function(e) {
        print("Enrichment failed for neighbor proteins")
      })
    }
  }
  
  # Process and summarize enrichment results
  processed_results <- process_enrichment_results(enrichment_results)
  
  return(processed_results)
}

#' Process Enrichment Results
process_enrichment_results <- function(enrichment_results) {
  
  processed <- list()
  
  for (gene_set in names(enrichment_results)) {
    
    processed[[gene_set]] <- list()
    
    for (database in names(enrichment_results[[gene_set]])) {
      
      result <- enrichment_results[[gene_set]][[database]]
      
      if (nrow(result) > 0) {
        # Filter significant results
        significant <- result %>%
          filter(Adjusted.P.value < 0.05) %>%
          arrange(Adjusted.P.value) %>%
          slice_head(n = 20) %>%
          mutate(
            Gene_Count = sapply(strsplit(Genes, ";"), length),
            Gene_Ratio = Gene_Count / sapply(strsplit(Genes, ";"), function(x) length(unique(x))),
            database = database,
            gene_set = gene_set
          )
        
        processed[[gene_set]][[database]] <- significant
      }
    }
  }
  
  # Create combined summary
  all_results <- do.call(rbind, lapply(processed, function(x) do.call(rbind, x)))
  
  if (!is.null(all_results) && nrow(all_results) > 0) {
    # Top pathways across all databases
    top_pathways <- all_results %>%
      arrange(Adjusted.P.value) %>%
      slice_head(n = 50) %>%
      mutate(
        pathway_category = case_when(
          grepl("GO_Biological", database) ~ "Biological Process",
          grepl("GO_Molecular", database) ~ "Molecular Function",
          grepl("KEGG", database) ~ "KEGG Pathway",
          grepl("Reactome", database) ~ "Reactome Pathway",
          grepl("WikiPathway", database) ~ "WikiPathway",
          TRUE ~ "Other"
        )
      )
    
    processed$summary <- list(
      top_pathways = top_pathways,
      pathway_counts = table(top_pathways$pathway_category),
      gene_set_comparison = all_results %>%
        group_by(gene_set, database) %>%
        summarise(
          n_significant = n(),
          min_pvalue = min(Adjusted.P.value),
          .groups = 'drop'
        )
    )
  }
  
  return(processed)
}

