#' Create Comprehensive PPI Visualization
create_comprehensive_ppi_viz <- function(ppi_interactions, selected_genes,
                                         hub_proteins, communities = NULL) {
  
  # Create nodes dataframe
  all_genes <- unique(c(ppi_interactions$gene_from, ppi_interactions$gene_to))
  
  nodes <- data.frame(
    id = all_genes,
    label = all_genes,
    stringsAsFactors = FALSE
  ) %>%
    mutate(
      # Node colors based on regulation status
      color = case_when(
        id %in% selected_genes$up_genes ~ "#E74C3C",      # Red for up-regulated
        id %in% selected_genes$down_genes ~ "#3498DB",    # Blue for down-regulated
        id %in% selected_genes$all_genes ~ "#F39C12",     # Orange for other input genes
        TRUE ~ "#95A5A6"                                   # Gray for network neighbors
      ),
      
      # Node sizes based on degree and hub status
      degree = sapply(id, function(x) {
        sum(ppi_interactions$gene_from == x) + sum(ppi_interactions$gene_to == x)
      }),
      
      size = pmax(15, pmin(40, 15 + degree * 2)),
      
      # Node shapes
      shape = "dot",
      
      # Border for hub proteins
      borderWidth = ifelse(id %in% hub_proteins$gene[1:10], 3, 1),
      borderWidthSelected = 4,
      
      # Node groups for legend
      group = case_when(
        id %in% selected_genes$up_genes ~ "Up-regulated",
        id %in% selected_genes$down_genes ~ "Down-regulated",
        id %in% selected_genes$all_genes ~ "Input gene",
        TRUE ~ "Network neighbor"
      ),
      
      # Tooltips with detailed information
      title = paste0(
        "<b>", id, "</b><br>",
        "Degree: ", degree, "<br>",
        "Type: ", group,
        if (id %in% hub_proteins$gene[1:20]) "<br><b>Hub Protein</b>" else ""
      )
    )
  
  # Add community information if available
  if (!is.null(communities) && !is.null(communities$node_membership)) {
    community_info <- communities$node_membership
    nodes <- nodes %>%
      left_join(community_info, by = c("id" = "gene")) %>%
      mutate(
        community = ifelse(is.na(community), 0, community),
        # Add community info to tooltip
        title = paste0(title, "<br>Community: ", community)
      )
  }
  
  # Create edges dataframe
  edges <- ppi_interactions %>%
    select(from = gene_from, to = gene_to, combined_score) %>%
    mutate(
      # Edge widths based on confidence scores
      width = pmax(1, combined_score * 5),
      
      # Edge colors
      color = list(color = "#7F8C8D", opacity = 0.6),
      
      # Edge tooltips
      title = paste0(
        "Interaction: ", from, " — ", to, "<br>",
        "Confidence: ", round(combined_score, 3)
      ),
      
      # Smooth edges
      smooth = TRUE
    )
  
  return(list(
    nodes = nodes,
    edges = edges
  ))
}

#' Generate PPI Summary Statistics
create_ppi_summary_stats_safe <- function(ppi_interactions, network_data, selected_genes, hub_proteins) {
  
  print("📊 Creating summary statistics...")
  
  tryCatch({
    # Basic counts
    n_nodes <- if (!is.null(network_data$nodes)) nrow(network_data$nodes) else 0
    n_edges <- nrow(ppi_interactions)
    
    # Input gene analysis
    all_network_proteins <- unique(c(ppi_interactions$gene_from, ppi_interactions$gene_to))
    
    n_up_in_network <- 0
    n_down_in_network <- 0
    n_input_in_network <- 0
    
    if (!is.null(selected_genes$up_genes)) {
      n_up_in_network <- length(intersect(all_network_proteins, selected_genes$up_genes))
    }
    if (!is.null(selected_genes$down_genes)) {
      n_down_in_network <- length(intersect(all_network_proteins, selected_genes$down_genes))
    }
    if (!is.null(selected_genes$all_genes)) {
      n_input_in_network <- length(intersect(all_network_proteins, selected_genes$all_genes))
    }
    
    # Network metrics
    density <- if (n_nodes > 1) {
      n_edges / (n_nodes * (n_nodes - 1) / 2)
    } else {
      0
    }
    
    avg_degree <- if (n_nodes > 0) {
      2 * n_edges / n_nodes
    } else {
      0
    }
    
    # Hub analysis
    n_hubs <- if (!is.null(hub_proteins)) nrow(hub_proteins) else 0
    
    # Create summary
    summary_stats <- list(
      basic_stats = list(
        n_nodes = n_nodes,
        n_edges = n_edges,
        n_input_genes = length(selected_genes$all_genes %||% character(0)),
        n_input_in_network = n_input_in_network,
        coverage_rate = if (length(selected_genes$all_genes %||% character(0)) > 0) {
          round(n_input_in_network / length(selected_genes$all_genes) * 100, 1)
        } else {
          0
        }
      ),
      
      regulation_stats = list(
        n_up_regulated = length(selected_genes$up_genes %||% character(0)),
        n_down_regulated = length(selected_genes$down_genes %||% character(0)),
        n_up_in_network = n_up_in_network,
        n_down_in_network = n_down_in_network
      ),
      
      network_metrics = list(
        density = round(density, 4),
        avg_degree = round(avg_degree, 2),
        clustering_coefficient = 0.3  # Placeholder
      ),
      
      hub_stats = list(
        n_hubs = n_hubs,
        hub_percentage = if (n_nodes > 0) round(n_hubs / n_nodes * 100, 1) else 0
      )
    )
    
    print("✅ Summary statistics created successfully")
    
    return(summary_stats)
    
  }, error = function(e) {
    print(paste("❌ Summary stats error:", e$message))
    
    # Return minimal stats
    return(list(
      basic_stats = list(
        n_nodes = 0,
        n_edges = 0,
        n_input_genes = 0,
        n_input_in_network = 0,
        coverage_rate = 0
      ),
      error = e$message
    ))
  })
}

#' Create Detailed Protein Annotations
create_protein_annotations <- function(ppi_interactions, selected_genes, hub_proteins) {
  
  # Get all proteins in network
  all_proteins <- unique(c(ppi_interactions$gene_from, ppi_interactions$gene_to))
  
  # Calculate degree for each protein
  protein_degrees <- c(
    table(ppi_interactions$gene_from),
    table(ppi_interactions$gene_to)
  )
  protein_degrees <- tapply(protein_degrees, names(protein_degrees), sum)
  
  # Create comprehensive protein table
  protein_info <- data.frame(
    protein = all_proteins,
    stringsAsFactors = FALSE
  ) %>%
    mutate(
      degree = as.numeric(protein_degrees[protein]),
      is_input_gene = protein %in% selected_genes$all_genes,
      regulation_status = case_when(
        protein %in% selected_genes$up_genes ~ "Up-regulated",
        protein %in% selected_genes$down_genes ~ "Down-regulated",
        protein %in% selected_genes$all_genes ~ "Input gene (unchanged)",
        TRUE ~ "Network neighbor"
      )
    ) %>%
    # Add hub information
    left_join(
      hub_proteins %>% select(gene, hub_type, hub_score, betweenness, eigenvector),
      by = c("protein" = "gene")
    ) %>%
    mutate(
      hub_type = ifelse(is.na(hub_type), "Regular node", hub_type),
      hub_score = ifelse(is.na(hub_score), 0, hub_score)
    ) %>%
    # Add interaction partners count
    rowwise() %>%
    mutate(
      interaction_partners = list(unique(c(
        ppi_interactions$gene_to[ppi_interactions$gene_from == protein],
        ppi_interactions$gene_from[ppi_interactions$gene_to == protein]
      ))),
      n_partners = length(interaction_partners),
      avg_interaction_confidence = mean(c(
        ppi_interactions$combined_score[ppi_interactions$gene_from == protein],
        ppi_interactions$combined_score[ppi_interactions$gene_to == protein]
      ))
    ) %>%
    ungroup() %>%
    arrange(desc(degree), desc(hub_score))
  
  return(protein_info)
}

#' Initialize PPI analysis system (call this in your server function)
initialize_ppi_system <- function() {
  # Check dependencies
  required_packages <- c("igraph", "visNetwork", "httr", "digest", "DT", "plotly")
  missing_packages <- required_packages[!sapply(required_packages, requireNamespace, quietly = TRUE)]
  
  if (length(missing_packages) > 0) {
    warning(paste("Missing PPI packages:", paste(missing_packages, collapse = ", ")))
    return(FALSE)
  }
  
  # Create cache directory
  cache_dir <- file.path(tempdir(), "string_cache")
  if (!dir.exists(cache_dir)) {
    dir.create(cache_dir, recursive = TRUE)
  }
  
  print("✅ PPI analysis system initialized successfully!")
  return(TRUE)
}

validate_grn_inputs <- function(selected_genes, organism, tf_database, confidence_level) {
  errors <- c()
  
  # Check selected genes
  if (is.null(selected_genes) || length(selected_genes$all_genes) == 0) {
    errors <- c(errors, "No genes selected for analysis")
  }
  
  # Check organism
  if (!tolower(organism) %in% c("human", "mouse")) {
    errors <- c(errors, paste("Unsupported organism:", organism))
  }
  
  # Check confidence level
  if (confidence_level < 0 || confidence_level > 1) {
    errors <- c(errors, "Confidence level must be between 0 and 1")
  }
  
  # Check TF database
  valid_databases <- c("dorothea", "collectri", "both")
  if (!tolower(tf_database) %in% valid_databases) {
    errors <- c(errors, paste("Invalid TF database. Choose from:", paste(valid_databases, collapse = ", ")))
  }
  
  return(list(
    valid = length(errors) == 0,
    errors = errors
  ))
}


