# ---- Curated changelog (NEWEST FIRST). To add an entry, add ONE line at the top. ----
# tag must be one of: "New", "Improved", "Fixed"
tx_changelog <- list(
  list(date = "2026-10-09", tag = "Fixed",    text = "Differential expression: normalised or log-scale data (microarray, TPM, FPKM, RPKM) is now analysed with limma on log2 expression instead of being rounded into counts; a detected batch variable is matched to samples by name and kept in the model whenever it can be estimated; pairwise comparisons work again."),
list(date = "2026-10-09", tag = "Fixed",    text = "TCGA: re-sequenced duplicate tumour samples (e.g. 89 in GBM) are counted once in differential expression and box plots; cohorts with fewer than 3 normal samples are no longer tested against normals, and cohorts without normals say what is compared; MA plots show the tested comparison."),
list(date = "2026-10-09", tag = "Fixed",    text = "FASTQ jobs: queued jobs now start on their own even if you close the page, a job that stops unexpectedly frees its slot at once, and three jobs can run at the same time. Salmon now reports gene-level counts, count tables name each column by sample, and public downloads are checked against ENA's checksums."),
list(date = "2026-10-06", tag = "New",      text = "Resumable FASTQ uploads: large files upload in chunks, continue automatically after a dropped connection, and stay on the server for 3 days so you can reload the page or come back later before starting."),
list(date = "2026-10-06", tag = "New",      text = "Analyse public RNA-seq data by SRA/ENA accession: the server downloads each run itself (up to 200 GB per job). Uploads can now be up to 40 GB, and samples are processed one at a time to keep disk use low."),
  list(date = "2026-10-06", tag = "New",      text = "FASTQ runs now keep going if you close the page: every run gets a job ID, and results can be retrieved later with \u201cRetrieve results by job ID\u201d."),
  list(date = "2026-10-06", tag = "Fixed",    text = "Survival hazard ratios are now reported as HIGH vs LOW expression, and analyses never fall back to simulated data when a database is unavailable."),
  list(date = "2026-10-06", tag = "Improved", text = "Pathway enrichment now uses the genes you tested as the background; GSEA accepts Ensembl IDs; batch detection uses PVCA, kBET and silhouette, validated on simulated data."),
  list(date = "2026-10-06", tag = "New",      text = "Methods & Versions page listing software, reference genomes, database releases and citations; one-click reuse of DE results in PPI, GRN and deconvolution."),
  list(date = "2026-10-05", tag = "New",      text = "Four new Learn guides: Working with Your Own Data, From GEO Accession to Results, Working with TCGA Cancer Data, and Your First FASTQ to Results Workflow."),
  list(date = "2026-10-05", tag = "Fixed",    text = "FASTQ processing: HISAT2 runs complete again, every genome now uses its own matching index and annotation, Salmon downloads work, queued jobs start automatically, and Illumina _R1_001 file names are accepted."),
  list(date = "2026-10-05", tag = "Fixed",    text = "TCGA: differential expression now always compares primary tumour vs normal, and survival analysis counts each patient once (primary tumour samples only)."),
  list(date = "2026-10-05", tag = "Improved", text = "GEO import skips normalised (FPKM/TPM) tables instead of treating them as counts, and batch metadata files can be tab-separated."),
  list(date = "2026-08-12", tag = "New",      text = "Standalone PPI analysis now lets you choose Functional or Physical STRING networks, served from local data for human and mouse (faster, no rate limits)."),
  list(date = "2026-08-12", tag = "Improved", text = "Smoother updates \u2014 if the platform is briefly updating, you now see a friendly maintenance page instead of an error."),
  list(date = "2026-06-24", tag = "New",      text = "Functional enrichment (ORA & GSEA) now covers ~1,900 species via on-demand AnnotationHub, including non-model organisms."),
  list(date = "2026-06-11", tag = "New",      text = "Added this What's New feed and a feedback form to the footer."),
  list(date = "2026-06-10", tag = "Improved", text = "GSEA visualisations (classic + dot plot) and PCA/UMAP plot downloads."),
  list(date = "2026-06-09", tag = "Improved", text = "Volcano plot symmetric x-axis and a heatmap usability bundle (paste-list, manual genes, orientation toggle).")
)

tx_tag_colours <- c(New = "#2e7d32", Improved = "#1565c0", Fixed = "#e65100")

tx_changelog_entry <- function(e) {
  col <- tx_tag_colours[[e$tag]]
  if (is.null(col)) col <- "#555"
  tags$div(
    class = "tx-cl-entry",
    tags$span(class = "tx-cl-chip", style = sprintf("background:%s;", col), e$tag),
    tags$span(class = "tx-cl-date", e$date),
    tags$span(class = "tx-cl-text", e$text)
  )
}

tx_changelog_footer <- function(n = 3) tagList(lapply(head(tx_changelog, n), tx_changelog_entry))

tx_whats_new_pill <- function(max_age_days = 30) {
  latest <- as.Date(tx_changelog[[1]]$date)
  if (is.na(latest) || as.numeric(Sys.Date() - latest) > max_age_days) return(NULL)
  tags$a(
    class = "tx-news-pill", href = "#tx-whats-new", role = "button",
    onclick = "txGoToWhatsNew(); return false;",
    tags$span(class = "tx-news-tag", "New"),
    tags$span(class = "tx-news-text",
              paste0("Updated ", format(latest, "%-d %b %Y"),
                     ": resumable uploads, SRA/ENA import and more")),
    tags$span(class = "tx-news-cta", "See what\u2019s new", icon("arrow-down"))
  )
}
tx_changelog_full   <- function()      tagList(lapply(tx_changelog,         tx_changelog_entry))

