                          h3(icon("project-diagram"), " Analysis Pipeline Overview",
                             style = "color: #1565c0; margin-bottom: 1rem;"),
                          
                          div(class = "pipeline-steps",
                              div(class = "step-card",
                                  div(class = "step-number", "1"),
                                  h5("Quality Control"),
