                              # JavaScript for smooth collapsible sidebar
                              tags$script(HTML("
                                $(document).ready(function() {
                                  var sidebarCollapsed = false;
                                  
                                  // Handle collapse button click
                                  $(document).on('click', '#toggle_qc_sidebar', function() {
                                    var sidebar = $('#qc_sidebar');
                                    var viewer = $('#qc_viewer');
                                    var expandBtn = $('#qc_expand_btn');
                                    
                                    if (!sidebarCollapsed) {
                                      // Collapse: slide sidebar to the left
                                      sidebar.css('transform', 'translateX(-100%)');
                                      sidebar.css('opacity', '0');
                                      
                                      // Expand viewer to full width
                                      viewer.css('margin-left', '0');
                                      
                                      // Show expand button
                                      expandBtn.fadeIn(300);
                                      
                                      sidebarCollapsed = true;
                                    }
                                  });
                                  
                                  // Handle expand button click
                                  $(document).on('click', '#expand_qc_sidebar', function() {
                                    var sidebar = $('#qc_sidebar');
                                    var viewer = $('#qc_viewer');
                                    var expandBtn = $('#qc_expand_btn');
                                    
                                    if (sidebarCollapsed) {
                                      // Expand: slide sidebar back in
                                      sidebar.css('transform', 'translateX(0)');
                                      sidebar.css('opacity', '1');
                                      
                                      // Restore viewer margin
                                      viewer.css('margin-left', '320px');
                                      
                                      // Hide expand button
                                      expandBtn.fadeOut(300);
                                      
                                      sidebarCollapsed = false;
                                    }
                                  });
                                });
                              "))
