        cursor: pointer;
        transition: all 0.3s ease;
        border: 2px solid transparent;
      }
      
      .systems-module-card:hover {
        transform: translateY(-5px);
        box-shadow: 0 8px 20px rgba(0,0,0,0.15);
        border-color: #667eea;
      }
      
      .systems-module-card.active {
        background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
        color: white;
        border-color: #667eea;
      }
      
      .systems-module-card h4 {
        margin-top: 0;
        font-weight: 600;
      }
      
      .systems-module-card.active h4,
