# ============================================================================
#  Local over-representation analysis on Enrichr gene-set libraries
#  - libraries are downloaded once from Enrichr and cached on disk (reproducible,
#    no dependence on the live Enrichr API for each analysis)
#  - one-sided hypergeometric test; Benjamini-Hochberg adjustment across terms
#    with at least one overlapping gene
#  - `background`: the tested-gene universe (e.g. all genes in the DE table);
#    the universe is the background genes that appear in the library. Without a
#    background, all genes in the library are used (Enrichr's default)
#  Returns a named list of data frames with enrichR's column layout.
# ============================================================================
TX_ENRICHR_CACHE <- Sys.getenv("TX_ENRICHR_CACHE", "/srv/transxplorer/results/.enrichr_libraries")
TX_JOBS_DIR <- Sys.getenv("TX_JOBS_DIR", "/srv/transxplorer/results/jobs")

# ============================================================================
# Resumable FASTQ uploads (tus protocol)
#  The browser (Uppy) streams files in chunks to the tusd container, which keeps
#  <id> (data) and <id>.info (JSON: size, offset, metadata) in TX_TUS_DIR. Each
#  browser holds a random token; tusd's pre-create hook accepts an upload only
#  when TX_TUS_TOKENS/<token> exists. The finished uploads carrying a session's
#  token are the files that session's FASTQ job will process.
# ============================================================================
TX_TUS_DIR <- Sys.getenv("TX_TUS_DIR", "/srv/transxplorer/uploads/tus")
TX_TUS_TOKENS <- Sys.getenv("TX_TUS_TOKENS", "/srv/transxplorer/uploads/tus_tokens")
TX_WORK_DIR <- Sys.getenv("TX_WORK_DIR", "/srv/transxplorer/uploads/work")
TX_TUS_KEEP_DAYS <- 3
TX_FASTQ_NAME_RE <- "^[A-Za-z0-9._-]+\\.(fastq|fq)(\\.gz)?$"

tx_new_upload_token <- function() paste(as.character(openssl::rand_bytes(16)), collapse = "")

tx_empty_uploads <- function() {
  data.frame(name = character(0), size = numeric(0), type = character(0),
             datapath = character(0), id = character(0), stringsAsFactors = FALSE)
}

tx_tus_read_info <- function(info_file) {
  tryCatch(jsonlite::fromJSON(info_file, simplifyVector = TRUE), error = function(e) NULL)
}

# Finished uploads for one token, one row per file name (a re-upload replaces the older copy)
tx_tus_list <- function(token) {
  if (is.null(token) || !dir.exists(TX_TUS_DIR)) return(tx_empty_uploads())
  infos <- list.files(TX_TUS_DIR, pattern = "\\.info$", full.names = TRUE)
  rows <- lapply(infos, function(f) {
    x <- tx_tus_read_info(f)
    if (is.null(x) || !identical(x$MetaData$token, token)) return(NULL)
    # filestore keeps the received bytes in the data file; .info "Offset" is not updated
    data_file <- sub("\\.info$", "", f)
    if (isTRUE(x$SizeIsDeferred) || is.null(x$Size) || !file.exists(data_file) || file.size(data_file) != x$Size) return(NULL)
    nm <- x$MetaData$filename %||% ""
    if (!grepl(TX_FASTQ_NAME_RE, nm, ignore.case = TRUE)) return(NULL)
    data.frame(name = nm, size = as.numeric(x$Size), type = "", datapath = data_file,
               id = basename(data_file), mtime = as.numeric(file.mtime(f)), stringsAsFactors = FALSE)
  })
  df <- do.call(rbind, rows[!vapply(rows, is.null, TRUE)])
  if (is.null(df) || nrow(df) == 0) return(tx_empty_uploads())
  df <- df[order(df$mtime, decreasing = TRUE), , drop = FALSE]
  dup <- duplicated(df$name)
  if (any(dup)) {
    for (p in df$datapath[dup]) unlink(c(p, paste0(p, ".info")))
    df <- df[!dup, , drop = FALSE]
  }
  df <- df[order(df$name), , drop = FALSE]
  df$mtime <- NULL
  rownames(df) <- NULL
  df
}

# Delete one finished upload, only if it belongs to this token
tx_tus_remove <- function(token, id) {
  if (!grepl("^[A-Za-z0-9+_-]+$", id %||% "")) return(FALSE)
  data_file <- file.path(TX_TUS_DIR, id)
  x <- tx_tus_read_info(paste0(data_file, ".info"))
  if (is.null(x) || !identical(x$MetaData$token, token)) return(FALSE)
  unlink(c(data_file, paste0(data_file, ".info")))
  TRUE
}

# Hand uploads to a job: move them (same filesystem, so instant) under their real names
tx_tus_claim <- function(df, dest_dir) {
  dir.create(dest_dir, recursive = TRUE, showWarnings = FALSE)
  for (i in seq_len(nrow(df))) {
    dst <- file.path(dest_dir, df$name[i])
    if (!file.rename(df$datapath[i], dst)) {
      if (!file.copy(df$datapath[i], dst)) stop("Could not prepare uploaded file ", df$name[i])
      unlink(df$datapath[i])
    }
    unlink(paste0(df$datapath[i], ".info"))
    df$datapath[i] <- dst
  }
  df
}

# Remove abandoned uploads, expired tokens and leftover work folders (at most once an hour)
tx_tus_sweep <- function() {
  marker <- file.path(TX_TUS_TOKENS, ".last_sweep")
  if (file.exists(marker) && difftime(Sys.time(), file.mtime(marker), units = "hours") < 1) return(invisible())
  try({
    file.create(marker)
    now <- Sys.time()
    old <- function(f, days) difftime(now, file.mtime(f), units = "days") > days
    for (f in list.files(TX_TUS_DIR, full.names = TRUE)) {
      data_file <- sub("\\.info$", "", f)
      last <- max(file.mtime(c(data_file, paste0(data_file, ".info"))), na.rm = TRUE)
      if (is.finite(last) && difftime(now, last, units = "days") > TX_TUS_KEEP_DAYS) unlink(f)
    }
    for (f in list.files(TX_TUS_TOKENS, full.names = TRUE)) if (old(f, 30)) unlink(f)
    for (d in list.dirs(TX_WORK_DIR, recursive = FALSE)) if (old(d, 7)) unlink(d, recursive = TRUE)
  }, silent = TRUE)
  invisible()
}

# ---- FASTQ jobs ---------------------------------------------------------------------------
# The pipeline runs in its own background R process, started by the queue (queue_manager.R)
# when a processing slot is free. It reads its parameters from the job folder, writes progress
# and log files there, and saves completion.rds when it ends. Nothing here needs a browser.
TX_APP_DIR <- getwd()

tx_fastq_pipeline_job <- function(params_file, completion_file, app_dir) {
  setwd(app_dir)
  # Source just the pipeline function (not the whole app)
  # The function writes progress to files, no Shiny dependencies needed
  params <- readRDS(params_file)

  write_log <- function(message, type = "info") {
    timestamp <- format(Sys.time(), "%H:%M:%S")
    prefix <- switch(type, "info" = "[INFO]", "success" = "[DONE]",
                    "warning" = "[WARN]", "error" = "[ERROR]", "progress" = "[STEP]", "[INFO]")
    line <- paste0("[", timestamp, "] ", prefix, " ", message)
    tryCatch(cat(line, "\n", file = params$log_file, append = TRUE), error = function(e) NULL)
  }

  write_progress <- function(percent, step) {
    tryCatch(writeLines(paste0(percent, "|", step), params$progress_file), error = function(e) NULL)
  }

  # Dynamic thread allocation: 4 (default) <= n <= 8, leaving 2 cores for system/Shiny.
  # Falls back to 4 if detectCores() fails (e.g., in a cgroup with hidden limits).
  n_threads <- tryCatch(
    max(4, min(8, parallel::detectCores() - 2)),
    error = function(e) 4L
  )

  # Wrap system() with explicit return-code check.
  # On non-zero exit: write to log + abort the pipeline cleanly.
  run_cmd_or_fail <- function(cmd, step, sample_name = NULL) {
    rc <- tryCatch(system(cmd, intern = FALSE), error = function(e) -1L)
    if (!is.null(rc) && is.numeric(rc) && rc != 0) {
      msg <- if (!is.null(sample_name)) {
        paste0(step, " failed for sample '", sample_name, "' (exit code ", rc, ")")
      } else {
        paste0(step, " failed (exit code ", rc, ")")
      }
      write_log(msg, "error")
      stop(msg)
    }
    invisible(rc)
  }

  tryCatch({
    write_log("Starting FASTQ processing pipeline", "info")
    write_log(paste("Using", n_threads, "threads per process"), "info")
    write_progress(5, "Initializing pipeline...")

    # Samples are processed ONE AT A TIME (QC -> trim -> align/quantify -> count), and each
    # sample's raw reads, trimmed reads and alignments are deleted as soon as they are no
    # longer needed. Peak disk use is the uploaded data plus one sample's temporary files.
    input_dir <- file.path(params$tmp_dir, "input")
    output_dir <- file.path(params$tmp_dir, "output")
    work_dir <- file.path(params$tmp_dir, "work")
    for (d in c(input_dir, output_dir, work_dir, file.path(output_dir, c("fastqc_raw", "fastqc_trimmed", "counts", "alignment_logs"))))
      dir.create(d, recursive = TRUE, showWarnings = FALSE)
    write_log("Created working directories", "success")

    remote <- params$remote_runs
    if (!is.null(remote) && nrow(remote) > 0) {
      # Public data (SRA/ENA): each run is downloaded right before it is processed
      samples <- lapply(seq_len(nrow(remote)), function(j) {
        urls <- strsplit(remote$fastq_urls[j], ";", fixed = TRUE)[[1]]
        md5 <- if (!is.null(remote$fastq_md5)) strsplit(remote$fastq_md5[j], ";", fixed = TRUE)[[1]] else character(0)
        list(base = remote$run_accession[j], urls = urls, md5 = if (length(md5) == length(urls)) md5 else NULL,
             files = file.path(input_dir, basename(urls)), bytes = remote$total_bytes[j])
      })
      options(timeout = max(getOption("timeout"), 6 * 3600))
      write_log(paste("Public runs to download and process:", paste(remote$run_accession, collapse = ", ")), "info")
    } else {
      # Move (not copy) the uploaded files into the job's input folder
      write_progress(8, "Receiving uploaded files...")
      input_files <- character(0)
      for (i in seq_len(nrow(params$fastq_files_df))) {
        src <- params$fastq_files_df$datapath[i]
        dst <- file.path(input_dir, params$fastq_files_df$name[i])
        moved <- suppressWarnings(file.rename(src, dst))
        if (!moved) {
          if (!file.copy(src, dst)) stop(paste("Failed to receive file:", params$fastq_files_df$name[i]))
          unlink(src)
        }
        input_files <- c(input_files, dst)
      }
      write_log(paste("Received", length(input_files), "files"), "success")

      # Group files into samples
      if (params$sequencing_type == "paired") {
        r1_files <- sort(input_files[grepl("_R?1(_[0-9]{3})?\\.(fastq|fq)", basename(input_files), ignore.case = TRUE)])
        r2_files <- sort(input_files[grepl("_R?2(_[0-9]{3})?\\.(fastq|fq)", basename(input_files), ignore.case = TRUE)])
        if (length(r1_files) == 0 || length(r1_files) != length(r2_files)) stop("Could not pair the R1 and R2 files")
        samples <- lapply(seq_along(r1_files), function(j) list(
          base = sub("_R?1(_[0-9]{3})?(\\.(fastq|fq)(\\.gz)?)$", "", basename(r1_files[j]), ignore.case = TRUE),
          files = c(r1_files[j], r2_files[j])))
      } else {
        samples <- lapply(input_files, function(f) list(base = sub("(\\.(fastq|fq)(\\.gz)?)$", "", basename(f)), files = f))
      }
    }
    n_samples <- length(samples)

    # Disk-space guard: one sample's temporary files need about 3x its input size
    free_gb <- tryCatch({
      x <- system(paste("df -Pk", shQuote(params$tmp_dir), "| tail -1"), intern = TRUE)
      as.numeric(strsplit(trimws(x), "\\s+")[[1]][4]) / 1024^2
    }, error = function(e) NA_real_)
    largest_gb <- max(vapply(samples, function(s) if (!is.null(s$bytes)) as.numeric(s$bytes) else sum(file.size(s$files)), 0)) / 1024^3
    need_gb <- 3 * largest_gb + 5
    if (!is.na(free_gb) && free_gb < need_gb) {
      stop(sprintf("Not enough free disk space on the server right now (about %.0f GB needed, %.0f GB free). Please try again later.", need_gb, free_gb))
    }
    write_log(sprintf("%d samples; processing one at a time (largest sample %.1f GB)", n_samples, largest_gb), "info")

    quant_method <- params$quant_method %||% "hisat2"
    counts_file <- file.path(output_dir, "counts", "feature_counts.txt")
    trimmomatic_jar <- "/usr/share/java/trimmomatic.jar"
    first_existing <- function(paths) {
      paths <- paths[nzchar(paths) & file.exists(paths)]
      if (length(paths) > 0) paths[1] else NULL
    }
    # Transcript -> gene table for tximport. Salmon reports transcripts by ID only (--gencode
    # trims the FASTA header), so genes come from the reference itself: GENCODE headers
    # (ENST|ENSG|...) or, for a custom genome, the GTF's transcript_id / gene_id pairs.
    # IDs without versions, as tximport(ignoreTxVersion = TRUE) compares them.
    tx2gene_from_reference <- function(fa, gtf = NULL) {
      hdr <- sub("^>", "", system(paste(if (grepl("\\.gz$", fa)) "zcat" else "cat", shQuote(fa), "| grep '^>'"), intern = TRUE))
      if (length(hdr) > 0 && all(grepl("|", head(hdr, 100), fixed = TRUE))) {
        p <- strsplit(hdr, "|", fixed = TRUE)
        tx <- vapply(p, `[`, "", 1); gene <- vapply(p, `[`, "", 2)
      } else if (!is.null(gtf)) {
        prog <- tempfile(fileext = ".awk")
        writeLines(c('$3 == "transcript" || $3 == "exon" {',
                     '  if ($9 !~ /transcript_id "/ || $9 !~ /gene_id "/) next',
                     '  t = $9; sub(/.*transcript_id "/, "", t); sub(/".*/, "", t)',
                     '  g = $9; sub(/.*gene_id "/, "", g); sub(/".*/, "", g)',
                     '  print t "\\t" g }'), prog)
        x <- system(paste(if (grepl("\\.gz$", gtf)) "zcat" else "cat", shQuote(gtf), "| awk -F'\\t' -f", shQuote(prog), "| sort -u"), intern = TRUE)
        p <- strsplit(x, "\t", fixed = TRUE)
        tx <- vapply(p, `[`, "", 1); gene <- vapply(p, `[`, "", 2)
      } else {
        stop("Cannot tell which gene each transcript belongs to (no GENCODE headers and no GTF)")
      }
      tab <- data.frame(TXNAME = sub("\\..*", "", tx), GENEID = sub("\\..*", "", gene), stringsAsFactors = FALSE)
      tab[!duplicated(tab$TXNAME), ]
    }

    # ---------------- Reference set-up (once) ----------------
    write_progress(10, "Preparing reference...")
    if (quant_method == "salmon") {
      salmon_indices_base <- "/srv/salmon_indices"
      salmon_index_dir <- file.path(work_dir, "salmon_index")
      transcriptome_fa <- switch(params$genome_build,
        "hg38" = file.path(salmon_indices_base, "gencode.v47.transcripts.fa.gz"),
        "mm10" = file.path(salmon_indices_base, "gencode.vM25.transcripts.fa.gz"),   # GRCm38
        NULL)
      if (is.null(transcriptome_fa) && params$genome_build == "custom" &&
          !is.null(params$custom_genome) && !is.null(params$custom_gtf)) {
        write_log("Building transcriptome from custom genome + GTF...", "progress")
        custom_genome_path <- file.path(input_dir, params$custom_genome$name)
        custom_gtf_path <- file.path(input_dir, params$custom_gtf$name)
        if (!file.exists(custom_genome_path)) file.copy(params$custom_genome$datapath, custom_genome_path)
        if (!file.exists(custom_gtf_path)) file.copy(params$custom_gtf$datapath, custom_gtf_path)
        transcriptome_fa <- file.path(work_dir, "custom_transcripts.fa")
        gffread_result <- system(paste("gffread", shQuote(custom_gtf_path), "-g", shQuote(custom_genome_path),
                                       "-w", shQuote(transcriptome_fa)), intern = FALSE)
        if (gffread_result != 0 || !file.exists(transcriptome_fa)) {
          write_log("gffread not available or failed. Using genome FASTA directly for Salmon.", "warning")
          transcriptome_fa <- custom_genome_path
        }
      }
      if (is.null(transcriptome_fa) || !file.exists(transcriptome_fa)) {
        stop(paste("Salmon transcriptome reference not available for genome:", params$genome_build,
                   ". Use HISAT2 mode or select hg38/mm10."))
      }
      prebuilt_index <- file.path(salmon_indices_base, paste0(params$genome_build, "_salmon_idx"))
      if (dir.exists(prebuilt_index)) {
        salmon_index_dir <- prebuilt_index
        write_log("Using pre-built Salmon index", "success")
      } else {
        write_progress(12, "Building Salmon index (first time, will be cached)...")
        write_log("Building Salmon index from transcriptome...", "progress")
        dir.create(salmon_index_dir, recursive = TRUE, showWarnings = FALSE)
        run_cmd_or_fail(paste("salmon index -t", shQuote(transcriptome_fa), "-i", shQuote(salmon_index_dir),
                              "-p", n_threads, "--gencode > /dev/null 2>&1"), "Salmon index build")
        if (params$genome_build != "custom") tryCatch({
          file.copy(salmon_index_dir, salmon_indices_base, recursive = TRUE)
          file.rename(file.path(salmon_indices_base, basename(salmon_index_dir)), prebuilt_index)
          write_log("Salmon index cached for future use", "success")
        }, error = function(e) write_log("Could not cache index (non-critical)", "warning"))
      }
      salmon_output_dir <- file.path(output_dir, "salmon_quant")
      dir.create(salmon_output_dir, recursive = TRUE, showWarnings = FALSE)
    } else {
      # Resolve the HISAT2 index and a gene annotation built on the SAME assembly.
      # Never fall back to another organism: a wrong index/GTF pair silently yields
      # near-zero or misassigned counts.
      hisat2_base <- "/srv/hisat2_indexes"
      ann_base <- "/srv/annotations"
      gb <- params$genome_build
      gtf_file <- NULL
      if (gb == "custom") {
        if (is.null(params$custom_genome) || is.null(params$custom_gtf)) {
          stop("Custom genome requires both a genome FASTA and a GTF annotation file")
        }
        custom_genome_path <- file.path(input_dir, params$custom_genome$name)
        custom_gtf_path <- file.path(input_dir, params$custom_gtf$name)
        if (!file.exists(custom_genome_path)) file.copy(params$custom_genome$datapath, custom_genome_path)
        if (!file.exists(custom_gtf_path)) file.copy(params$custom_gtf$datapath, custom_gtf_path)
        custom_fa_plain <- custom_genome_path
        if (grepl("\\.gz$", custom_genome_path)) {
          custom_fa_plain <- file.path(work_dir, "custom_genome.fa")
          run_cmd_or_fail(paste("gunzip -c", shQuote(custom_genome_path), ">", shQuote(custom_fa_plain)),
                          "Decompressing custom genome")
        }
        idx_dir <- file.path(work_dir, "hisat2_index")
        dir.create(idx_dir, recursive = TRUE, showWarnings = FALSE)
        write_progress(12, "Building HISAT2 index for custom genome...")
        write_log("Building HISAT2 index for the custom genome (large genomes can take a long time)", "progress")
        run_cmd_or_fail(paste("hisat2-build -p", n_threads, shQuote(custom_fa_plain),
                              shQuote(file.path(idx_dir, "genome")), "> /dev/null 2>&1"),
                        "HISAT2 index build")
        hisat2_index <- file.path(idx_dir, "genome")
        gtf_file <- custom_gtf_path
      } else {
        hisat2_index <- switch(gb,
          "hg38" = Sys.getenv("HISAT2_HG38_INDEX", file.path(hisat2_base, "hg38", "genome")),
          "mm10" = Sys.getenv("HISAT2_MM10_INDEX", file.path(hisat2_base, "mm10", "genome")),
          "rn6"  = Sys.getenv("HISAT2_RN6_INDEX",  file.path(hisat2_base, "rn6", "genome")),
          file.path(hisat2_base, gb, "genome"))
        gtf_candidates <- switch(gb,
          "hg38" = c(Sys.getenv("GENCODE_HG38_GTF"), file.path(ann_base, "gencode.v47.annotation.gtf")),
          # mm10 = GRCm38: GENCODE vM25 is the last release on this assembly
          "mm10" = file.path(ann_base, c("gencode.vM25.annotation.gtf", "gencode.vM25.annotation.gtf.gz")),
          # rn6 = Rnor_6.0: Ensembl 104 is the last release on this assembly
          "rn6"  = file.path(ann_base, c("Rattus_norvegicus.Rnor_6.0.104.gtf", "Rattus_norvegicus.Rnor_6.0.104.gtf.gz")),
          # dm6 = BDGP6 (Ensembl names; chromosome names harmonised below)
          "dm6"  = file.path(ann_base, "Drosophila_melanogaster.BDGP6.46.111.gtf"),
          "danRer11" = c(file.path(hisat2_base, "danRer11", "genome.gtf"), file.path(ann_base, "Danio_rerio.GRCz11.111.gtf")),
          "wbcel235" = c(file.path(hisat2_base, "wbcel235", "genome.gtf"), file.path(ann_base, "Caenorhabditis_elegans.WBcel235.111.gtf")),
          "r64" = c(file.path(hisat2_base, "r64", "genome.gtf"), file.path(ann_base, "Saccharomyces_cerevisiae.R64-1-1.111.gtf")),
          file.path(hisat2_base, gb, "genome.gtf"))
        gtf_file <- first_existing(gtf_candidates)
        if (is.null(gtf_file) && gb == "mm10") {
          gtf_file <- first_existing(file.path(ann_base, "gencode.vM36.annotation.gtf"))
          if (!is.null(gtf_file)) {
            write_log("GENCODE vM25 (mm10) annotation not installed; using vM36 (GRCm39 coordinates). Gene assignment may be slightly reduced.", "warning")
          }
        }
      }
      if (!file.exists(paste0(hisat2_index, ".1.ht2"))) {
        stop(paste0("HISAT2 index for genome '", gb, "' is not installed on the server. ",
                    "Choose another genome, use Salmon (hg38/mm10), or run locally with Docker."))
      }
      if (is.null(gtf_file)) {
        stop(paste0("No gene annotation (GTF) matching the '", gb, "' assembly is installed on the server. ",
                    "Choose another genome or use the Custom Genome option with your own FASTA + GTF."))
      }
      write_log(paste0("Reference: ", gb, " | index: ", hisat2_index, " | annotation: ", basename(gtf_file)), "info")

      # Harmonise chromosome names between the index and the annotation
      # (UCSC "chr2L"/"chrM" vs Ensembl "2L"/"MT"). Only renames; never changes coordinates.
      idx_seqs <- tryCatch({
        x <- system(paste("hisat2-inspect -n", shQuote(hisat2_index)), intern = TRUE)
        unique(sub("\\s.*$", "", x))
      }, error = function(e) character(0))
      reader <- if (grepl("\\.gz$", gtf_file)) "zcat" else "cat"
      gtf_seqs <- tryCatch(
        system(paste(reader, shQuote(gtf_file), "| grep -v '^#' | cut -f1 | sort -u"), intern = TRUE),
        error = function(e) character(0))
      if (length(idx_seqs) > 0 && length(gtf_seqs) > 0 && !any(gtf_seqs %in% idx_seqs)) {
        to_ucsc <- ifelse(gtf_seqs %in% c("MT", "M", "mitochondrion_genome"), "chrM", paste0("chr", gtf_seqs))
        from_ucsc <- ifelse(gtf_seqs == "chrM", "MT", sub("^chr", "", gtf_seqs))
        new_names <- if (sum(to_ucsc %in% idx_seqs) >= sum(from_ucsc %in% idx_seqs)) to_ucsc else from_ucsc
        keep_map <- new_names %in% idx_seqs
        if (!any(keep_map)) {
          stop("Chromosome names in the annotation do not match the genome index - check that the GTF belongs to the selected assembly")
        }
        map_file <- file.path(work_dir, "seqname_map.tsv")
        writeLines(paste(gtf_seqs[keep_map], new_names[keep_map], sep = "\t"), map_file)
        harmonised_gtf <- file.path(work_dir, "annotation_harmonised.gtf")
        run_cmd_or_fail(paste(reader, shQuote(gtf_file), "| awk 'BEGIN{FS=OFS=\"\\t\"} NR==FNR{m[$1]=$2; next} /^#/{next} ($1 in m){$1=m[$1]; print}'",
                              shQuote(map_file), "- >", shQuote(harmonised_gtf)),
                        "Annotation chromosome-name harmonisation")
        write_log(paste("Harmonised annotation chromosome names to match the genome index (", sum(keep_map), "sequences)"), "info")
        gtf_file <- harmonised_gtf
      }
      pe_flag <- if (params$sequencing_type == "paired") "-p --countReadPairs" else ""
    }

    # ---------------- Per-sample processing ----------------
    fc_files <- character(0); quant_dirs <- character(0)
    for (si in seq_len(n_samples)) {
      s <- samples[[si]]; base <- s$base
      step_pct <- function(frac) write_progress(15 + round(80 * ((si - 1) + frac) / n_samples),
                                                sprintf("Sample %d of %d (%s)", si, n_samples, base))
      step_pct(0); write_log(sprintf("Sample %d of %d: %s", si, n_samples, base), "progress")

      # 0. Download this run (public data only), with retries
      if (!is.null(s$urls)) {
        for (u in seq_along(s$urls)) {
          ok <- FALSE
          for (attempt in 1:4) {
            rc <- tryCatch(utils::download.file(s$urls[u], s$files[u], mode = "wb", quiet = TRUE, method = "libcurl"),
                           error = function(e) 1L)
            if (identical(as.integer(rc), 0L) && file.exists(s$files[u]) && file.size(s$files[u]) > 0) {
              if (is.null(s$md5) || identical(unname(tools::md5sum(s$files[u])), tolower(s$md5[u]))) { ok <- TRUE; break }
              write_log(paste0("Checksum mismatch for ", basename(s$urls[u]), "; downloading again"), "warning")
            }
            unlink(s$files[u]); Sys.sleep(15 * attempt)
          }
          if (!ok) stop(paste0("Download failed for ", basename(s$urls[u]), " (run ", base, ") after 4 attempts"))
        }
        write_log(sprintf("Downloaded %s (%.2f GB)", base, sum(file.size(s$files)) / 1024^3), "success")
      }

      # 1. FastQC on raw reads
      run_cmd_or_fail(paste("fastqc", paste(shQuote(s$files), collapse = " "), "-o", shQuote(file.path(output_dir, "fastqc_raw")),
                            "-t", length(s$files), "--quiet"), "FastQC (raw reads)", base)
      # 2. Trimming
      if (params$sequencing_type == "paired") {
        tr <- file.path(work_dir, paste0(base, c("_R1_paired.fastq.gz", "_R1_unpaired.fastq.gz", "_R2_paired.fastq.gz", "_R2_unpaired.fastq.gz")))
        run_cmd_or_fail(paste("java -jar", shQuote(trimmomatic_jar), "PE -threads 4 -phred33",
                              shQuote(s$files[1]), shQuote(s$files[2]), paste(shQuote(tr), collapse = " "),
                              "ILLUMINACLIP:/opt/Trimmomatic-0.39/adapters/TruSeq3-PE.fa:2:30:10",
                              "LEADING:3 TRAILING:3 SLIDINGWINDOW:4:15 MINLEN:36 > /dev/null 2>&1"), "Trimmomatic", base)
        trimmed <- tr[c(1, 3)]; unlink(tr[c(2, 4)])
      } else {
        trimmed <- file.path(work_dir, paste0(base, "_trimmed.fastq.gz"))
        run_cmd_or_fail(paste("java -jar", shQuote(trimmomatic_jar), "SE -threads 4 -phred33",
                              shQuote(s$files), shQuote(trimmed),
                              "ILLUMINACLIP:/opt/Trimmomatic-0.39/adapters/TruSeq3-SE.fa:2:30:10",
                              "LEADING:3 TRAILING:3 SLIDINGWINDOW:4:15 MINLEN:36 > /dev/null 2>&1"), "Trimmomatic", base)
      }
      # 3. FastQC on trimmed reads
      run_cmd_or_fail(paste("fastqc", paste(shQuote(trimmed), collapse = " "), "-o", shQuote(file.path(output_dir, "fastqc_trimmed")),
                            "-t", length(trimmed), "--quiet"), "FastQC (trimmed reads)", base)
      unlink(s$files)                                   # raw reads no longer needed
      step_pct(0.4)

      # 4. Quantification
      if (quant_method == "salmon") {
        sample_dir <- file.path(salmon_output_dir, base)
        reads <- if (length(trimmed) == 2) paste("-1", shQuote(trimmed[1]), "-2", shQuote(trimmed[2])) else paste("-r", shQuote(trimmed))
        run_cmd_or_fail(paste("salmon quant -i", shQuote(salmon_index_dir), "-l A", reads,
                              "--gcBias --seqBias --validateMappings -p", n_threads, "-o", shQuote(sample_dir),
                              ">", shQuote(file.path(output_dir, "alignment_logs", paste0(base, ".salmon.log"))), "2>&1"),
                        "Salmon quantification", base)
        quant_dirs <- c(quant_dirs, sample_dir)
        unlink(trimmed)
      } else {
        sorted_bam <- file.path(work_dir, paste0(base, "_sorted.bam"))
        reads <- if (length(trimmed) == 2) paste("-1", shQuote(trimmed[1]), "-2", shQuote(trimmed[2])) else paste("-U", shQuote(trimmed))
        # stream alignments straight into a sorted BAM (no SAM file on disk)
        run_cmd_or_fail(paste("bash -c", shQuote(paste(
          "set -o pipefail; hisat2 -p", n_threads, "--dta -x", shQuote(hisat2_index), reads,
          "2>", shQuote(file.path(output_dir, "alignment_logs", paste0(base, ".hisat2.log"))),
          "| samtools sort -@", n_threads, "-T", shQuote(file.path(work_dir, paste0(base, "_sorttmp"))),
          "-o", shQuote(sorted_bam), "-"))), "HISAT2 alignment", base)
        unlink(trimmed)                                 # trimmed reads no longer needed
        step_pct(0.8)
        fc_out <- file.path(work_dir, paste0("fc_", base, ".txt"))
        run_cmd_or_fail(paste("featureCounts -T", n_threads, pe_flag, "-a", shQuote(gtf_file), "-o", shQuote(fc_out),
                              shQuote(sorted_bam), "> /dev/null 2>&1"), "featureCounts quantification", base)
        fc_files <- c(fc_files, fc_out)
        unlink(sorted_bam)                              # alignments no longer needed
      }
      write_log(sprintf("Sample %d of %d done: %s (temporary files removed)", si, n_samples, base), "success")
    }

    # ---------------- Combine samples ----------------
    write_progress(95, "Combining samples...")
    if (quant_method == "salmon") {
      quant_files <- file.path(quant_dirs, "quant.sf")
      names(quant_files) <- basename(quant_dirs)
      existing_quants <- quant_files[file.exists(quant_files)]
      if (length(existing_quants) == 0) stop("No Salmon quant.sf files found")
      tx2gene <- tx2gene_from_reference(transcriptome_fa, if (params$genome_build == "custom") custom_gtf_path else NULL)
      tx_ids <- sub("\\..*", "", read.table(existing_quants[1], header = TRUE, sep = "\t", stringsAsFactors = FALSE)$Name)
      mapped <- mean(tx_ids %in% tx2gene$TXNAME)
      if (mapped < 0.95) stop(sprintf("Only %.0f%% of Salmon transcripts could be matched to a gene in the annotation", 100 * mapped))
      write_log(sprintf("Summarising %d transcripts to %d genes", length(tx_ids), length(unique(tx2gene$GENEID[tx2gene$TXNAME %in% tx_ids]))), "info")
txi <- tximport::tximport(existing_quants, type = "salmon", tx2gene = tx2gene,
                                countsFromAbundance = "no", ignoreTxVersion = TRUE)
      gene_counts <- as.data.frame(round(txi$counts))
      gene_counts <- cbind(Geneid = rownames(gene_counts), gene_counts)
      write.table(gene_counts, counts_file, sep = "\t", row.names = FALSE, quote = FALSE)
      write_log(paste("Gene-level counts matrix:", nrow(gene_counts), "genes x", ncol(gene_counts) - 1, "samples"), "success")
      tpm_df <- as.data.frame(txi$abundance)
      tpm_df <- cbind(Geneid = rownames(tpm_df), tpm_df)
      write.table(tpm_df, file.path(output_dir, "counts", "salmon_tpm.txt"), sep = "\t", row.names = FALSE, quote = FALSE)
      write_log("Salmon quantification pipeline completed", "success")
    } else {
      tabs <- lapply(fc_files, function(f) read.delim(f, comment.char = "#", check.names = FALSE, stringsAsFactors = FALSE))
      merged <- tabs[[1]]
      if (length(tabs) > 1) for (k in 2:length(tabs)) {
        if (!identical(tabs[[k]]$Geneid, merged$Geneid)) stop("Per-sample count tables do not share the same genes")
        merged <- cbind(merged, tabs[[k]][, 7, drop = FALSE])
      }
      sample_names <- vapply(samples, function(x) x$base, "")
      names(merged)[-(1:6)] <- sample_names
      writeLines("# Program:featureCounts; per-sample runs combined by TransXplorer", counts_file)
suppressWarnings(write.table(merged, counts_file, sep = "\t", row.names = FALSE, quote = FALSE, append = TRUE))
      sums <- lapply(paste0(fc_files, ".summary"), function(f) read.delim(f, check.names = FALSE, stringsAsFactors = FALSE))
      summary_merged <- sums[[1]]
      if (length(sums) > 1) for (k in 2:length(sums)) summary_merged <- cbind(summary_merged, sums[[k]][, 2, drop = FALSE])
      names(summary_merged)[-1] <- sample_names
write.table(summary_merged, paste0(counts_file, ".summary"), sep = "\t", row.names = FALSE, quote = FALSE)
      write_log(paste("Gene expression quantification completed:", nrow(merged), "genes x", ncol(merged) - 6, "samples"), "success")
    }
    unlink(work_dir, recursive = TRUE)

    # Step 6: Complete
    write_progress(95, "Finalizing results...")
    write_log("Generating summary...", "progress")

    summary_file <- paste0(counts_file, ".summary")
    summary_data <- if (file.exists(summary_file)) {
      tryCatch(read.table(summary_file, header = TRUE, sep = "\t", row.names = 1, check.names = FALSE),
               error = function(e) NULL)
    } else NULL

    # Keep the results with the job (counts, QC reports, Salmon quantifications), so they
    # can be retrieved by job ID after the browser session has ended
    permanent <- FALSE
    if (!is.null(params$job_dir)) {
      keep_out <- file.path(params$job_dir, basename(output_dir))
      dir.create(keep_out, recursive = TRUE, showWarnings = FALSE)
      for (sub in c("counts", "fastqc_raw", "fastqc_trimmed", "salmon_quant", "alignment_logs")) {
        if (dir.exists(file.path(output_dir, sub))) file.copy(file.path(output_dir, sub), keep_out, recursive = TRUE)
      }
      output_dir <- keep_out
      counts_file <- file.path(output_dir, "counts", "feature_counts.txt")
      summary_file <- paste0(counts_file, ".summary")
      permanent <- TRUE
    }

    write_progress(100, "Complete!")
    write_log("Analysis completed successfully!", "success")

    result <- list(
      success = TRUE,
      counts_file = counts_file,
      summary_file = summary_file,
      summary_data = summary_data,
      output_dir = output_dir,
      job_id = params$job_id,
      permanent = permanent
    )
    saveRDS(result, completion_file)
    tryCatch({
      qm <- new.env(); sys.source(file.path(app_dir, "queue_manager.R"), envir = qm)
      if (!is.null(params$job_id)) qm$update_job_status(params$job_id, "complete")
    }, error = function(e) NULL)
    try(unlink(params$tmp_dir, recursive = TRUE), silent = TRUE)

  }, error = function(e) {
    write_log(paste("Pipeline error:", e$message), "error")
    write_progress(0, paste("Error:", e$message))
    saveRDS(list(success = FALSE, error = e$message, job_id = params$job_id), completion_file)
    tryCatch({
      qm <- new.env(); sys.source(file.path(app_dir, "queue_manager.R"), envir = qm)
      if (!is.null(params$job_id)) qm$update_job_status(params$job_id, "error", error = e$message)
    }, error = function(e2) NULL)
    try(unlink(params$tmp_dir, recursive = TRUE), silent = TRUE)   # no retry from these files; free the disk
  })
}

tx_launch_job <- function(job) {
  p <- callr::r_bg(
    tx_fastq_pipeline_job,
    args = list(params_file = file.path(job$job_dir, "params.rds"),
                completion_file = file.path(job$job_dir, "completion.rds"),
                app_dir = TX_APP_DIR),
    supervise = FALSE,
    cleanup = FALSE,        # keep running when the session or app process ends
    cleanup_tree = FALSE,
    stdout = file.path(job$job_dir, "bg_stdout.txt"),  # files, not pipes: a pipe to an exited
    stderr = file.path(job$job_dir, "bg_stderr.txt"),  # app process would kill the job (SIGPIPE)
    poll_connection = FALSE
  )
  p$get_pid()
}

# Every app process looks at the queue every 10 s: it frees the slots of finished or dead jobs
# and starts waiting ones, so a queued job starts even if its page was closed.
.tx_queue_state <- new.env(parent = emptyenv())
.tx_queue_state$last_cleanup <- Sys.time()
tx_queue_tick <- function() {
  tryCatch(process_queue(tx_launch_job), error = function(e) message("FASTQ queue check failed: ", conditionMessage(e)))
  if (difftime(Sys.time(), .tx_queue_state$last_cleanup, units = "hours") > 6) {
    .tx_queue_state$last_cleanup <- Sys.time()
    try(cleanup_old_jobs(), silent = TRUE)
  }
  later::later(tx_queue_tick, 10)
}
later::later(tx_queue_tick, 5)

# What an uploaded expression matrix holds: "counts" (raw or expected read counts), "log"
# (log-scale expression, e.g. microarray) or "linear" (normalised: TPM, FPKM, RPKM, CPM).
# Expected counts (RSEM, Salmon) are non-integer but rarely between 0 and 1; normalised
# values of lowly expressed genes very often are.
tx_expression_scale <- function(m) {
  v <- as.numeric(as.matrix(m))
  v <- v[is.finite(v)]
  if (length(v) > 2e5) v <- v[round(seq(1, length(v), length.out = 2e5))]
  if (length(v) == 0) return("counts")
  if (any(v < 0)) return("log")
  if (mean(v == round(v)) > 0.99) return("counts")
  if (max(v) <= 30) return("log")
  if (mean(v > 0 & v < 1) > 0.15) "linear" else "counts"
}

.tx_enrichr_mem <- new.env(parent = emptyenv())
# Enrichr renamed some libraries; map names used in the app to the published ones
TX_ENRICHR_ALIASES <- c(WikiPathways_2023_Human = "WikiPathway_2023_Human",
                        WikiPathways_2021_Human = "WikiPathway_2021_Human")

tx_enrichr_library <- function(lib) {
  if (exists(lib, envir = .tx_enrichr_mem, inherits = FALSE)) return(get(lib, envir = .tx_enrichr_mem))
  cache_dir <- TX_ENRICHR_CACHE
  dir.create(cache_dir, recursive = TRUE, showWarnings = FALSE)
  if (file.access(cache_dir, 2) != 0) {          # not writable: fall back to a per-process cache
    cache_dir <- file.path(tempdir(), "enrichr_libraries")
    dir.create(cache_dir, recursive = TRUE, showWarnings = FALSE)
  }
  f <- file.path(cache_dir, paste0(gsub("[^A-Za-z0-9_.-]", "_", lib), ".rds"))
  shared <- file.path(TX_ENRICHR_CACHE, basename(f))
  for (cand in unique(c(f, shared))) {
    if (file.exists(cand)) {
      sets <- tryCatch(readRDS(cand), error = function(e) NULL)
      if (!is.null(sets)) { assign(lib, sets, envir = .tx_enrichr_mem); return(sets) }
    }
  }
  remote <- if (lib %in% names(TX_ENRICHR_ALIASES)) TX_ENRICHR_ALIASES[[lib]] else lib
  url <- paste0("https://maayanlab.cloud/Enrichr/geneSetLibrary?mode=text&libraryName=",
                utils::URLencode(remote, reserved = TRUE))
  old_to <- getOption("timeout"); options(timeout = max(180, old_to)); on.exit(options(timeout = old_to))
  lines <- readLines(url, warn = FALSE)
  fields <- strsplit(lines, "\t", fixed = TRUE)
  sets <- lapply(fields, function(x) {
    g <- sub(",.*$", "", x[-(1:2)])
    unique(toupper(trimws(g[nzchar(g)])))
  })
  names(sets) <- vapply(fields, function(x) x[1], "")
  sets <- sets[lengths(sets) > 0]
  if (length(sets) == 0) stop(paste("Gene-set library", lib, "could not be downloaded from Enrichr"))
  attr(sets, "downloaded") <- as.character(Sys.Date())
  attr(sets, "enrichr_name") <- remote
  tryCatch(saveRDS(sets, f), error = function(e) NULL)
  assign(lib, sets, envir = .tx_enrichr_mem)
  sets
}

tx_enrichr_local <- function(genes, databases, background = NULL) {
  genes <- unique(toupper(trimws(as.character(genes))))
  genes <- genes[!is.na(genes) & nzchar(genes)]
  bg <- NULL
  if (!is.null(background)) {
    bg <- unique(toupper(trimws(as.character(background))))
    bg <- bg[!is.na(bg) & nzchar(bg)]
    if (length(bg) == 0) bg <- NULL
  }
  empty <- data.frame(Term = character(0), Overlap = character(0), P.value = numeric(0),
                      Adjusted.P.value = numeric(0), Old.P.value = numeric(0),
                      Old.Adjusted.P.value = numeric(0), Odds.Ratio = numeric(0),
                      Combined.Score = numeric(0), Genes = character(0), stringsAsFactors = FALSE)
  out <- list()
  for (db in databases) {
    sets <- tryCatch(tx_enrichr_library(db), error = function(e) {
      message("Enrichment library ", db, " unavailable: ", conditionMessage(e)); NULL })
    if (is.null(sets)) { out[[db]] <- empty; next }
    universe <- unique(unlist(sets, use.names = FALSE))
    if (!is.null(bg)) universe <- intersect(universe, bg)
    q <- intersect(genes, universe)
    N <- length(universe); n <- length(q)
    if (N == 0 || n == 0) { out[[db]] <- empty; next }
    sets_u <- lapply(sets, function(s) s[s %in% universe])
    K <- lengths(sets_u)
    hits <- lapply(sets_u, function(s) s[s %in% q])
    k <- lengths(hits)
    keep <- K > 0 & k > 0
    if (!any(keep)) { out[[db]] <- empty; next }
    K <- K[keep]; k <- k[keep]; hits <- hits[keep]
    p <- stats::phyper(k - 1, K, N - K, n, lower.tail = FALSE)
    or <- ((k + 0.5) * (N - K - n + k + 0.5)) / ((K - k + 0.5) * (n - k + 0.5))
    res <- data.frame(
      Term = names(K), Overlap = paste0(k, "/", K), P.value = p,
      Adjusted.P.value = stats::p.adjust(p, method = "BH"),
      Old.P.value = 0, Old.Adjusted.P.value = 0, Odds.Ratio = or,
      Combined.Score = log(or) * -log(p),
      Genes = vapply(hits, paste, "", collapse = ";"),
      stringsAsFactors = FALSE)
    res <- res[order(res$P.value), ]
    rownames(res) <- NULL
    attr(res, "universe_size") <- N
    attr(res, "library_downloaded") <- attr(sets, "downloaded")
    out[[db]] <- res
  }
  out
}

# ============================================================================
#  Methods & Versions: software, reference data, databases and citations,
#  read live from this server so reports match what actually ran.
# ============================================================================
tx_pkg_version <- function(p) tryCatch(as.character(utils::packageVersion(p)), error = function(e) "not installed")
tx_tool_version <- function(cmd, pattern = "[0-9]+\\.[0-9]+(\\.[0-9]+)?") {
  out <- tryCatch(suppressWarnings(system(cmd, intern = TRUE, ignore.stderr = FALSE)), error = function(e) character(0))
  v <- regmatches(paste(out, collapse = " "), regexpr(pattern, paste(out, collapse = " ")))
  if (length(v) == 0) "not available" else v
}
.tx_mv_cache <- new.env(parent = emptyenv())

tx_methods_versions <- function() {
  if (exists("mv", envir = .tx_mv_cache, inherits = FALSE)) return(get("mv", envir = .tx_mv_cache))
  pk <- function(name, pkg, role, cite) data.frame(Component = name, Version = tx_pkg_version(pkg), Used_for = role, Citation = cite, stringsAsFactors = FALSE)
  tl <- function(name, cmd, role, cite) data.frame(Component = name, Version = tx_tool_version(cmd), Used_for = role, Citation = cite, stringsAsFactors = FALSE)
  software <- rbind(
    data.frame(Component = "R", Version = paste(R.version$major, R.version$minor, sep = "."), Used_for = "Runtime", Citation = "R Core Team", stringsAsFactors = FALSE),
    data.frame(Component = "Bioconductor", Version = tryCatch(as.character(BiocManager::version()), error = function(e) "unknown"), Used_for = "Package release", Citation = "", stringsAsFactors = FALSE),
    pk("DESeq2", "DESeq2", "Differential expression", "Love et al. 2014, doi:10.1186/s13059-014-0550-8"),
    pk("edgeR", "edgeR", "Differential expression, normalisation", "Robinson et al. 2010, doi:10.1093/bioinformatics/btp616"),
    pk("limma (voom)", "limma", "Differential expression", "Ritchie et al. 2015, doi:10.1093/nar/gkv007; Law et al. 2014, doi:10.1186/gb-2014-15-2-r29"),
    pk("sva (ComBat-seq)", "sva", "Batch correction", "Zhang et al. 2020, doi:10.1093/nargab/lqaa078"),
    pk("clusterProfiler", "clusterProfiler", "GO/KEGG/Reactome/WikiPathways enrichment", "Wu et al. 2021, doi:10.1016/j.xinn.2021.100141"),
    pk("fgsea", "fgsea", "GSEA (fgseaMultilevel)", "Korotkevich et al. 2016, doi:10.1101/060012"),
    pk("msigdbr", "msigdbr", "MSigDB gene sets for GSEA", "Liberzon et al. 2015, doi:10.1016/j.cels.2015.12.004"),
    pk("WGCNA", "WGCNA", "Co-expression networks", "Langfelder & Horvath 2008, doi:10.1186/1471-2105-9-559"),
    pk("dorothea", "dorothea", "TF-target regulons", "Garcia-Alonso et al. 2019, doi:10.1101/gr.240663.118"),
    pk("viper", "viper", "TF activity inference", "Alvarez et al. 2016, doi:10.1038/ng.3593"),
    pk("igraph", "igraph", "Network metrics", "Csardi & Nepusz 2006"),
    pk("survival", "survival", "Kaplan-Meier, Cox models, log-rank", "Therneau, survival package; Kaplan & Meier 1958, doi:10.1080/01621459.1958.10501452"),
    pk("TCGAbiolinks", "TCGAbiolinks", "TCGA data", "Colaprico et al. 2016, doi:10.1093/nar/gkv1507"),
    pk("GEOquery", "GEOquery", "GEO import", "Davis & Meltzer 2007, doi:10.1093/bioinformatics/btm254"),
    pk("tximport", "tximport", "Salmon transcript-to-gene counts", "Soneson et al. 2015, doi:10.12688/f1000research.7563.2"),
    pk("immunedeconv", "immunedeconv", "Cell-type deconvolution (xCell, MCP-counter, EPIC)", "Aran et al. 2017, doi:10.1186/s13059-017-1349-1; Becht et al. 2016, doi:10.1186/s13059-016-1070-5; Racle et al. 2017, doi:10.7554/eLife.26476"),
    pk("shiny", "shiny", "Web application", "Chang et al., shiny package"),
    tl("HISAT2", "hisat2 --version 2>&1 | head -1", "Genome alignment", "Kim et al. 2019, doi:10.1038/s41587-019-0201-4"),
    tl("featureCounts (Subread)", "featureCounts -v 2>&1", "Read counting", "Liao et al. 2014, doi:10.1093/bioinformatics/btt656"),
    tl("Salmon", "salmon --version 2>&1", "Pseudo-alignment", "Patro et al. 2017, doi:10.1038/nmeth.4197"),
    tl("SAMtools", "samtools --version 2>&1 | head -1", "BAM sorting/indexing", "Li et al. 2009, doi:10.1093/bioinformatics/btp352"),
    tl("FastQC", "fastqc --version 2>&1", "Read quality control", "Andrews, FastQC (Babraham Bioinformatics)"),
    data.frame(Component = "Trimmomatic", Version = "0.39", Used_for = "Adapter/quality trimming", Citation = "Bolger et al. 2014, doi:10.1093/bioinformatics/btu170", stringsAsFactors = FALSE)
  )
  hb <- "/srv/hisat2_indexes"; an <- "/srv/annotations"
  ref <- function(genome, index, annot, annot_file) data.frame(
    Genome = genome, HISAT2_index = index, Annotation = annot,
    Installed = if (file.exists(file.path(hb, index, "genome.1.ht2")) && any(file.exists(annot_file))) "yes" else "no",
    stringsAsFactors = FALSE)
  references <- rbind(
    ref("Human hg38", "hg38", "GENCODE v47", file.path(an, "gencode.v47.annotation.gtf")),
    ref("Mouse mm10 (GRCm38)", "mm10", "GENCODE vM25", file.path(an, c("gencode.vM25.annotation.gtf", "gencode.vM25.annotation.gtf.gz"))),
    ref("Rat rn6 (Rnor_6.0)", "rn6", "Ensembl 104", file.path(an, c("Rattus_norvegicus.Rnor_6.0.104.gtf", "Rattus_norvegicus.Rnor_6.0.104.gtf.gz"))),
    ref("Fly dm6 (BDGP6)", "dm6", "Ensembl 111 (BDGP6.46), UCSC chromosome names", file.path(an, "Drosophila_melanogaster.BDGP6.46.111.gtf")),
    ref("Zebrafish danRer11 (GRCz11)", "danRer11", "Index-bundled GTF / Ensembl 111", c(file.path(hb, "danRer11/genome.gtf"), file.path(an, "Danio_rerio.GRCz11.111.gtf"))),
    ref("C. elegans WBcel235", "wbcel235", "Ensembl 111", file.path(an, "Caenorhabditis_elegans.WBcel235.111.gtf")),
    ref("Yeast R64", "r64", "Ensembl 111 (R64-1-1)", file.path(an, "Saccharomyces_cerevisiae.R64-1-1.111.gtf")),
    ref("Arabidopsis TAIR10", "araTha", "Index-bundled GTF", file.path(hb, "araTha/genome.gtf")),
    ref("Chicken galGal6 (GRCg6a)", "galGal6", "Index-bundled GTF", file.path(hb, "galGal6/genome.gtf")),
    ref("Pig susScr11 (Sscrofa11.1)", "susScr11", "Index-bundled GTF", file.path(hb, "susScr11/genome.gtf"))
  )
  references$Salmon_transcriptome <- ifelse(references$HISAT2_index == "hg38", "GENCODE v47 transcripts",
                                     ifelse(references$HISAT2_index == "mm10", "GENCODE vM25 transcripts", "not offered (use HISAT2)"))
  enr_files <- list.files(TX_ENRICHR_CACHE, pattern = "\\.rds$", full.names = TRUE)
  enr_libs <- if (length(enr_files)) paste(sprintf("%s (downloaded %s)", sub("\\.rds$", "", basename(enr_files)),
                                                     format(file.mtime(enr_files), "%Y-%m-%d")), collapse = "; ") else "downloaded on first use"
  tcga_files <- list.files("/srv/tcga_precomputed", full.names = TRUE)
  databases <- data.frame(
    Database = c("STRING", "OpenTargets Platform", "DGIdb", "DoRothEA regulons", "MSigDB (via msigdbr)",
                 "Enrichr gene-set libraries", "KEGG / Reactome / WikiPathways / GO", "TCGA", "GEO"),
    Release = c("v12.0 (local for human and mouse; API for other species)", "25.03 (local Parquet)", "v5 (live API)",
                paste("dorothea", tx_pkg_version("dorothea"), "(dorothea_hs / dorothea_mm)"), paste("msigdbr", tx_pkg_version("msigdbr")),
                enr_libs, "via clusterProfiler / organism annotation packages at the versions above",
                if (length(tcga_files)) paste0("GDC harmonised data via TCGAbiolinks; precomputed files dated ", format(max(file.mtime(tcga_files)), "%Y-%m-%d")) else "GDC harmonised data via TCGAbiolinks",
                "live NCBI GEO (GEOquery)"),
    Citation = c("Szklarczyk et al. 2023, doi:10.1093/nar/gkac1000", "Ochoa et al. 2023, doi:10.1093/nar/gkac1046",
                 "Cannon et al. 2024, doi:10.1093/nar/gkad1040", "Garcia-Alonso et al. 2019, doi:10.1101/gr.240663.118",
                 "Liberzon et al. 2015, doi:10.1016/j.cels.2015.12.004", "Kuleshov et al. 2016, doi:10.1093/nar/gkw377",
                 "Wu et al. 2021, doi:10.1016/j.xinn.2021.100141", "Colaprico et al. 2016, doi:10.1093/nar/gkv1507",
                 "Davis & Meltzer 2007, doi:10.1093/bioinformatics/btm254"),
    stringsAsFactors = FALSE)
  methods <- data.frame(
    Module = c("FASTQ processing", "FASTQ processing", "Differential expression", "Over-representation (Enrichr libraries)",
               "Over-representation (GO/KEGG/Reactome)", "GSEA", "TCGA survival", "TCGA differential expression",
               "PPI networks", "TF activity (GRN)", "Gene identifiers"),
    Method = c("FastQC -> Trimmomatic (ILLUMINACLIP TruSeq3, LEADING:3 TRAILING:3 SLIDINGWINDOW:4:15 MINLEN:36) -> HISAT2 (--dta) -> featureCounts (paired fragments counted once; unstranded)",
               "Salmon quant (-l A --gcBias --seqBias --validateMappings) -> tximport gene-level counts",
               "DESeq2, edgeR (TMM, quasi-likelihood) or limma-voom; BH-adjusted p-values",
               "One-sided hypergeometric test on cached Enrichr libraries; background = genes tested in the DE analysis (TCGA: tested genes); BH adjustment",
               "clusterProfiler with the tested genes as universe; BH adjustment",
               "fgseaMultilevel on a ranked list; Ensembl/Entrez IDs converted to symbols",
               "Primary tumour samples (type 01; 03 for LAML), one per patient; median split; Cox model with LOW as reference (HR = HIGH vs LOW); log-rank test",
               "Primary tumour vs Solid Tissue Normal tested by name in DESeq2, edgeR or limma-voom",
               "STRING edges deduplicated to one per unordered protein pair; 8 CytoHubba-style centralities",
               "VIPER (method = scale, minsize = 4) on full DoRothEA regulons at the chosen confidence levels",
               "Failed conversions are reported as missing; no simulated data is ever substituted"),
    stringsAsFactors = FALSE)
  mv <- list(software = software, references = references, databases = databases, methods = methods,
             generated = format(Sys.time(), "%Y-%m-%d %H:%M %Z"))
  assign("mv", mv, envir = .tx_mv_cache)
  mv
}

tx_methods_versions_text <- function() {
  mv <- tx_methods_versions()
  fmt <- function(df) paste(apply(df, 1, function(r) paste(paste0(names(df), ": ", r), collapse = " | ")), collapse = "\n")
  paste0("TransXplorer - Methods & Versions\nGenerated: ", mv$generated, " (https://transxplorer.org)\n\n",
         "SOFTWARE\n", fmt(mv$software), "\n\nREFERENCE GENOMES AND ANNOTATIONS\n", fmt(mv$references),
         "\n\nDATABASES\n", fmt(mv$databases), "\n\nMETHODS AND DEFAULTS\n", fmt(mv$methods),
         "\n\nPlease cite TransXplorer and the tools and databases above that your analysis used.\n")
}

convertGeneIDs <- function(gene_data, input_id_type, organism_db) {
  # Add input validation
  if (is.null(gene_data) || length(gene_data) == 0) {
    warning("Empty or NULL gene data provided")
    return(NULL)
  }
  
  # Ensure gene_data is sorted decreasingly
  gene_data <- sort(gene_data, decreasing = TRUE)
  
  # Load the organism database
  db_obj <- get(organism_db)
  
  # Create a copy of original data for reference
  original_genes <- gene_data
  result_list <- list(original = original_genes)
  
  # Get key types available for this organism
  available_keytypes <- keytypes(db_obj)
  
  # Map user selection to actual keytype
  fromType <- switch(input_id_type,
                     "symbol" = "SYMBOL",
                     "ensembl" = "ENSEMBL",
                     "entrez" = "ENTREZID",
                     "SYMBOL")  # Default
  
  # Check if the selected keytype is available
  if (!(fromType %in% available_keytypes)) {
    warning(paste("Selected ID type", fromType, "not available for this organism. Using SYMBOL instead."))
    fromType <- "SYMBOL"
  }
  
  # Skip conversion if already using ENTREZID
  if (fromType == "ENTREZID") {
    result_list$entrez <- original_genes
    result_list$kegg <- original_genes
    result_list$reactome <- original_genes
    result_list$wiki <- original_genes
    return(result_list)
  }
  
  # Extract gene names
  genes <- names(original_genes)
  
  # Convert to Entrez IDs
  tryCatch({
    entrez_conversion <- bitr(genes, fromType = fromType, toType = "ENTREZID", OrgDb = db_obj)
    idx <- match(genes, entrez_conversion[[fromType]])
    entrez_names <- entrez_conversion$ENTREZID[idx]
    valid_idx <- !is.na(entrez_names)
    
    # Create entrez version
    entrez_genes <- setNames(original_genes[valid_idx], entrez_names[valid_idx])
    result_list$entrez <- sort(entrez_genes, decreasing = TRUE)
    result_list$reactome <- sort(entrez_genes, decreasing = TRUE)  # Reactome uses Entrez
    
    # For KEGG, we'll use the Entrez IDs directly
    result_list$kegg <- sort(entrez_genes, decreasing = TRUE)
    
  }, error = function(e) {
    warning("Gene ID conversion failed:", e$message)
    result_list$entrez <- original_genes
    result_list$kegg <- original_genes
    result_list$reactome <- original_genes
  })
  
  # For WikiPathways - use Entrez if we have good conversion, otherwise original
  result_list$wiki <- if (length(result_list$entrez) > length(genes)/2) {
    sort(result_list$entrez, decreasing = TRUE)
  } else {
    sort(original_genes, decreasing = TRUE)
  }
  
  return(result_list)
}


# Define server function
server <- function(input, output, session) {

  # ===== Systems Biology: reuse DE results from Transcriptome Analysis =====
  tx_current_sig_degs <- function(max_n = 500) {
    res <- rv_deg_main$deg_results
    if (is.null(res) || !is.data.frame(res) || nrow(res) == 0) return(character(0))
    pcol <- intersect(c("padj", "FDR", "adj.P.Val", "p_adj", "adj_pvalue"), colnames(res))[1]
    fcol <- intersect(c("log2FC", "log2FoldChange", "logFC"), colnames(res))[1]
    gcol <- intersect(c("gene_symbol", "gene_name", "symbol", "gene_id", "gene", "Gene"), colnames(res))[1]
    if (is.na(gcol)) { res$..gene <- rownames(res); gcol <- "..gene" }
    if (is.na(pcol) || is.na(fcol)) return(character(0))
    keep <- !is.na(res[[pcol]]) & !is.na(res[[fcol]]) & res[[pcol]] < 0.05 & abs(res[[fcol]]) >= 1
    sig <- res[keep, , drop = FALSE]
    sig <- sig[order(sig[[pcol]]), , drop = FALSE]
    ids <- unique(as.character(sig[[gcol]]))
    ids <- ids[!is.na(ids) & nzchar(ids)]
    if (length(ids) > 0 && mean(grepl("^ENS[A-Z]*G[0-9]", ids)) > 0.5) {
      ids <- tryCatch(convert_gene_ids(ids, from_org = input$organism_deg_main %||% "human", to_type = "SYMBOL"),
                      error = function(e) ids)
    }
    head(unique(ids), max_n)
  }
  observeEvent(input$sb_use_degs_ppi, {
    genes <- tx_current_sig_degs()
    if (length(genes) < 3) {
      showNotification("No significant DE genes found. Run a differential expression analysis in Transcriptome Analysis first.", type = "warning", duration = 8)
      return()
    }
    updateTextAreaInput(session, "ppi_standalone_gene_text", value = paste(genes, collapse = "\n"))
    shinyjs::runjs("Shiny.setInputValue('select_systems_module', 'ppi', {priority: 'event'})")
    showNotification(sprintf("Loaded %d significant DE genes into the PPI gene list.", length(genes)), type = "message", duration = 6)
  })
  observeEvent(input$sb_use_degs_grn, {
    genes <- tx_current_sig_degs()
    if (length(genes) < 10) {
      showNotification("GRN needs at least 10 significant DE genes. Run a differential expression analysis in Transcriptome Analysis first.", type = "warning", duration = 8)
      return()
    }
    updateRadioButtons(session, "grn_standalone_input_mode", selected = "quick")
    updateTextAreaInput(session, "grn_standalone_gene_text", value = paste(genes, collapse = "\n"))
    grn_standalone_rv$quick_mode_genes <- genes
    shinyjs::runjs("Shiny.setInputValue('select_systems_module', 'grn', {priority: 'event'})")
    showNotification(sprintf("Loaded %d significant DE genes into the GRN gene list.", length(genes)), type = "message", duration = 6)
  })
  # Advanced Analysis picks its type through clickable cards (selectAnalysisCard); the cards
  # render after the tab opens, so wait for them before selecting.
  tx_go_advanced <- function(type = NULL, label = "") {
    updateTabsetPanel(session, "main_tabs", selected = "deg_main_panel")
    shinyjs::delay(150, updateTabsetPanel(session, "deg_results_tabs_main", selected = "network_analysis"))
    if (!is.null(type)) {
      shinyjs::runjs(sprintf(
        "(function(){ var n = 0; var t = setInterval(function(){ n++;
           if (typeof selectAnalysisCard === 'function' && document.querySelector('.analysis-card')) {
             selectAnalysisCard('%s', '%s'); clearInterval(t);
           } else if (n > 60) { Shiny.setInputValue('network_analysis_type_systems', '%s', {priority: 'event'}); clearInterval(t); }
         }, 250); })();", type, label, type))
    }
  }
  observeEvent(input$sb_open_advanced, {
    if (is.null(rv_deg_main$deg_results))
      showNotification("Run a differential expression analysis first; Advanced Analysis then works on its results.", type = "message", duration = 8)
    tx_go_advanced()
  })
  observeEvent(input$sb_open_deconv, {
    if (!identical(input$organism_deg_main, "human"))
      showNotification("Cell-type deconvolution is available for human samples: select Human as the organism in Transcriptome Analysis.", type = "message", duration = 8)
    tx_go_advanced("deconv", "Cell Type Deconvolution")
  })

  # ===== Methods & Versions page =====
  mv_table <- function(df) DT::datatable(df, rownames = FALSE, options = list(dom = "t", paging = FALSE, scrollX = TRUE))
  output$mv_software   <- DT::renderDT(mv_table(tx_methods_versions()$software))
  output$mv_references <- DT::renderDT(mv_table(tx_methods_versions()$references))
  output$mv_databases  <- DT::renderDT(mv_table(tx_methods_versions()$databases))
  output$mv_methods    <- DT::renderDT(mv_table(tx_methods_versions()$methods))
  output$download_methods_versions <- downloadHandler(
    filename = function() paste0("TransXplorer_methods_versions_", Sys.Date(), ".txt"),
    content = function(file) writeLines(tx_methods_versions_text(), file)
  )

  # ===== What's New + Feedback (footer feature) =====
  observeEvent(input$tx_changelog_seeall, {
    showModal(modalDialog(
      title = tagList(icon("bullhorn"), " What's New in TransXplorer"),
      tags$div(class = "tx-cl-modal", tx_changelog_full()),
      easyClose = TRUE, size = "l", footer = modalButton("Close")
    ))
  })

  # Feedback config from environment (loaded from the secrets file at startup)
  tx_feedback_cfg <- list(
    user = Sys.getenv("TX_SMTP_USER"),
    pass = Sys.getenv("TX_SMTP_APP_PASSWORD"),
    to   = Sys.getenv("TX_FEEDBACK_TO", "varinde2+transxplorer@ualberta.ca"),
    bcc  = Sys.getenv("TX_FEEDBACK_BCC", "dev.vmadhav@gmail.com")
  )
  tx_feedback_ready <- nzchar(tx_feedback_cfg$user) && nzchar(tx_feedback_cfg$pass) &&
    requireNamespace("emayili", quietly = TRUE)

  tx_fb_times <- reactiveVal(numeric(0))  # per-session rate-limit timestamps

  observeEvent(input$tx_feedback_open, {
    if (!isTRUE(tx_feedback_ready)) {
      showModal(modalDialog(
        title = tagList(icon("comment-dots"), " Feedback"),
        tags$p("Feedback submission is temporarily unavailable. Please email ",
               tags$a(href = "mailto:varinde2@ualberta.ca", "varinde2@ualberta.ca"),
               " directly \u2014 sorry for the inconvenience!"),
        easyClose = TRUE, footer = modalButton("Close")
      ))
      return()
    }
    showModal(modalDialog(
      title = tagList(icon("comment-dots"), " Send feedback or a question"),
      tags$p(class = "tx-fb-prompt", "Tell us what you think, what broke, or what you'd like to see. Thanks for helping improve TransXplorer!"),
      textInput("tx_fb_name", "Name", placeholder = "optional"),
      textInput("tx_fb_email", "Email", placeholder = "optional"),
      tags$div(class = "tx-fb-note", "We'll only use your email to reply to you."),
      selectInput("tx_fb_category", "Category",
                  choices = c("Bug", "Question", "Suggestion", "Other"), selected = "Question"),
      textAreaInput("tx_fb_message", "Message", rows = 5, placeholder = "Your feedback or question..."),
      tags$div(style = "position:absolute; left:-9999px; top:-9999px;",
               textInput("tx_fb_website", "Leave this empty", value = "")),
      easyClose = FALSE,
      footer = tagList(
        modalButton("Cancel"),
        actionButton("tx_fb_submit", tagList(icon("paper-plane"), " Send"), class = "tx-fb-btn")
      )
    ))
  })

  observeEvent(input$tx_fb_submit, {
    if (nzchar(input$tx_fb_website %||% "")) {  # honeypot filled -> silent fake-success
      removeModal(); showNotification("Thanks \u2014 your feedback was sent!", type = "message"); return()
    }
    msg <- trimws(input$tx_fb_message %||% "")
    if (!nzchar(msg)) { showNotification("Please enter a message before sending.", type = "warning"); return() }

    now <- as.numeric(Sys.time())
    recent <- tx_fb_times(); recent <- recent[recent > now - 60]
    if (length(recent) >= 3) {
      showNotification("You're sending feedback very quickly \u2014 please wait a moment and try again.", type = "warning"); return()
    }

    sender   <- trimws(input$tx_fb_email %||% "")
    name     <- trimws(input$tx_fb_name %||% "")
    category <- input$tx_fb_category %||% "Other"

    body <- paste0(
      "New TransXplorer feedback\n-------------------------\n",
      "Category: ", category, "\n",
      "Name:     ", ifelse(nzchar(name),   name,   "(not provided)"), "\n",
      "Email:    ", ifelse(nzchar(sender), sender, "(not provided)"), "\n",
      "Time UTC: ", format(as.POSIXct(now, origin = "1970-01-01", tz = "UTC"), "%Y-%m-%d %H:%M:%S"), "\n",
      "-------------------------\n\n", msg, "\n"
    )

    ok <- tryCatch({
      e <- emayili::envelope()
      e <- emayili::from(e, tx_feedback_cfg$user)
      e <- emayili::to(e, tx_feedback_cfg$to)
      if (nzchar(tx_feedback_cfg$bcc)) e <- emayili::bcc(e, tx_feedback_cfg$bcc)
      if (nzchar(sender)) e <- emayili::reply(e, sender)
      e <- emayili::subject(e, paste0("[TransXplorer Feedback] ", category))
      e <- emayili::text(e, body)
      smtp <- emayili::server(host = "smtp.gmail.com", port = 587,
                              username = tx_feedback_cfg$user, password = tx_feedback_cfg$pass)
      smtp(e, verbose = FALSE)
      TRUE
    }, error = function(err) { message("[feedback] send failed: ", conditionMessage(err)); FALSE })

    if (isTRUE(ok)) {
      tx_fb_times(c(recent, now)); removeModal()
      showNotification("Thanks \u2014 your feedback was sent!", type = "message")
    } else {
      showNotification("Sorry, we couldn't send your feedback right now. Please try again later or email varinde2@ualberta.ca.", type = "error")
    }
  })

  # ===== DIAGNOSTIC TRACE =====
  # Writes tagged lines to stderr and flushes immediately so traces survive
  # worker crashes (e.g., C stack overflow in DESeq2). Grep session logs for
  # "[DEG_TRACE]" after a crash to see the last phase reached.
  deg_trace <- function(...) {
    msg <- paste0("[DEG_TRACE ", format(Sys.time(), "%H:%M:%OS3"), "] ",
                  paste0(c(...), collapse = " "))
    try({ cat(msg, "\n", sep = "", file = stderr()); flush(stderr()) }, silent = TRUE)
  }

  # WGCNA pipeline tracer — same pattern but tagged so it doesn't mix
  # with DEG traces. Use this around every step in the advanced WGCNA
  # observer so a failure leaves a precise breadcrumb trail.
  wgcna_trace <- function(...) {
    msg <- paste0("[WGCNA_TRACE ", format(Sys.time(), "%H:%M:%OS3"), "] ",
                  paste0(c(...), collapse = " "))
    try({ cat(msg, "\n", sep = "", file = stderr()); flush(stderr()) }, silent = TRUE)
  }

  # ===== SESSION LIFECYCLE MANAGEMENT =====
  # Clean up resources when session ends (browser close, refresh, navigate away)
  session$onSessionEnded(function() {
    message(paste("Session ended:", session$token, "- cleaning up at", Sys.time()))
    # Force garbage collection to free memory from large datasets
    gc(verbose = FALSE)
  })

  # Auto-close idle sessions after 30 minutes of no input
  idle_timer <- reactiveVal(Sys.time())

  # Reset timer on any input activity
  observe({
    reactiveValuesToList(input)  # triggers on ANY input change
    idle_timer(Sys.time())
  })

  # Check for idle timeout every 5 minutes
  observe({
    invalidateLater(300000)  # 5 minutes
    idle_minutes <- as.numeric(difftime(Sys.time(), idle_timer(), units = "mins"))
    if (idle_minutes > 30) {
      showModal(modalDialog(
        title = "Session Idle",
        p("This session has been idle for 30 minutes and will close to free server resources."),
        p("If you saved your session, you can restore it using your session ID."),
        footer = NULL,
        easyClose = FALSE
      ))
      # Give 10 seconds for the modal to render, then close
      invalidateLater(10000)
      session$close()
    }
  })

  # ===== INITIALIZATION HANDLER =====

  # Flag to track if initialization is complete
  init_done <- reactiveVal(FALSE)
  
  # Server ready flag - signals to JavaScript when R is fully loaded
  server_ready <- reactiveVal(FALSE)
  
  # Signal to JS that server is ready (for button activation)
  observe({
    isolate({
      if (!server_ready()) {
        server_ready(TRUE)
        invalidateLater(100)
      } else {
        session$sendCustomMessage("server-ready", list(
          ready = TRUE,
          timestamp = as.character(Sys.time())
        ))
      }
    })
  }, priority = -9999) # Lowest priority = runs after everything else
  
  # Simple one-time init marker (no rebinding - let JS handle it)
  observe({
    if (isolate(init_done())) return()
    isolate(init_done(TRUE))
    message("Server observer initialization complete")
  }) |> bindEvent(TRUE, once = TRUE, ignoreNULL = FALSE)
  
  options(shiny.trace = FALSE)
  
  # Server's TUTORIAL section begins
  # Tutorial Export Handler
  observeEvent(input$export_tutorial_core, {
    tutorial_dir <- "data/tutorial"
    dir.create(file.path(tutorial_dir, "exploratory"), recursive = TRUE, showWarnings = FALSE)
    dir.create(file.path(tutorial_dir, "deg"), recursive = TRUE, showWarnings = FALSE)
    dir.create(file.path(tutorial_dir, "pathway"), recursive = TRUE, showWarnings = FALSE)
    
    export_log <- list()
    
    withProgress(message = "Exporting core tutorial data...", value = 0, {
      
      # 1. Dataset info & previews
      incProgress(0.1, detail = "Dataset previews...")
      tryCatch({
        if (!is.null(rv_deg_main$raw_counts) && nrow(rv_deg_main$raw_counts) > 0) {
          counts_preview <- rv_deg_main$raw_counts[1:min(100, nrow(rv_deg_main$raw_counts)), ]
          counts_preview <- cbind(Gene = rownames(counts_preview), as.data.frame(counts_preview))
          write.csv(counts_preview, file.path(tutorial_dir, "counts_preview.csv"), row.names = FALSE)
          export_log$counts <- paste("OK -", nrow(rv_deg_main$raw_counts), "genes")
        }
        if (!is.null(rv_deg_main$metadata_raw)) {
          write.csv(rv_deg_main$metadata_raw, file.path(tutorial_dir, "metadata_preview.csv"), row.names = FALSE)
          export_log$metadata <- paste("OK -", nrow(rv_deg_main$metadata_raw), "samples")
        }
        dataset_info <- list(
          n_genes = if(!is.null(rv_deg_main$raw_counts)) nrow(rv_deg_main$raw_counts) else NA,
          n_samples = if(!is.null(rv_deg_main$raw_counts)) ncol(rv_deg_main$raw_counts) else NA,
          export_date = Sys.time()
        )
        saveRDS(dataset_info, file.path(tutorial_dir, "dataset_info.rds"))
      }, error = function(e) export_log$dataset_error <- paste("Error:", e$message))
      
      # 2. Exploratory plots
      incProgress(0.2, detail = "Exploratory plots...")
      tryCatch({
        if (!is.null(rv_deg_main$pca_plot)) {
          saveRDS(rv_deg_main$pca_plot, file.path(tutorial_dir, "exploratory/pca_plot.rds"))
          export_log$pca_plot <- "OK"
        }
        if (!is.null(rv_deg_main$umap_plot)) {
          saveRDS(rv_deg_main$umap_plot, file.path(tutorial_dir, "exploratory/umap_plot.rds"))
          export_log$umap_plot <- "OK"
        }
        if (!is.null(rv_deg_main$pca_batch_before)) {
          saveRDS(rv_deg_main$pca_batch_before, file.path(tutorial_dir, "exploratory/pca_before_batch.rds"))
          export_log$pca_before_batch <- "OK"
        }
        if (!is.null(rv_deg_main$pca_batch_after)) {
          saveRDS(rv_deg_main$pca_batch_after, file.path(tutorial_dir, "exploratory/pca_after_batch.rds"))
          export_log$pca_after_batch <- "OK"
        }
        if (!is.null(rv_deg_main$umap_batch_before)) {
          saveRDS(rv_deg_main$umap_batch_before, file.path(tutorial_dir, "exploratory/umap_before_batch.rds"))
          export_log$umap_before_batch <- "OK"
        }
        if (!is.null(rv_deg_main$umap_batch_after)) {
          saveRDS(rv_deg_main$umap_batch_after, file.path(tutorial_dir, "exploratory/umap_after_batch.rds"))
          export_log$umap_after_batch <- "OK"
        }
      }, error = function(e) export_log$exploratory_error <- paste("Error:", e$message))
      
      # 3. DEG results
      incProgress(0.4, detail = "DEG results...")
      tryCatch({
        if (!is.null(rv_deg_main$deg_results) && nrow(rv_deg_main$deg_results) > 0) {
          deg_data <- rv_deg_main$deg_results
          write.csv(deg_data, file.path(tutorial_dir, "deg/all_degs.csv"), row.names = FALSE)
          export_log$all_degs <- paste("OK -", nrow(deg_data), "genes")
          
          fc_col <- intersect(c("log2FoldChange", "logFC", "log2FC"), colnames(deg_data))[1]
          pval_col <- intersect(c("padj", "FDR", "adj.P.Val"), colnames(deg_data))[1]
          gene_col <- intersect(c("gene_name", "Gene", "symbol", "gene_id"), colnames(deg_data))[1]
          
          col_info <- list(fc_col = fc_col, pval_col = pval_col, gene_col = gene_col)
          saveRDS(col_info, file.path(tutorial_dir, "deg/column_info.rds"))
          
          if (!is.na(fc_col) && !is.na(pval_col)) {
            up_genes <- deg_data[!is.na(deg_data[[pval_col]]) & deg_data[[pval_col]] < 0.05 & 
                                   !is.na(deg_data[[fc_col]]) & deg_data[[fc_col]] > 1, ]
            down_genes <- deg_data[!is.na(deg_data[[pval_col]]) & deg_data[[pval_col]] < 0.05 & 
                                     !is.na(deg_data[[fc_col]]) & deg_data[[fc_col]] < -1, ]
            
            write.csv(up_genes, file.path(tutorial_dir, "deg/upregulated_genes.csv"), row.names = FALSE)
            write.csv(down_genes, file.path(tutorial_dir, "deg/downregulated_genes.csv"), row.names = FALSE)
            export_log$up_genes <- paste("OK -", nrow(up_genes))
            export_log$down_genes <- paste("OK -", nrow(down_genes))
            
            # Volcano data
            volcano_data <- deg_data
            volcano_data$neg_log10_pval <- -log10(volcano_data[[pval_col]])
            volcano_data$neg_log10_pval[is.infinite(volcano_data$neg_log10_pval)] <- 50
            volcano_data$neg_log10_pval[is.na(volcano_data$neg_log10_pval)] <- 0
            volcano_data$significance <- "Not Significant"
            volcano_data$significance[!is.na(volcano_data[[pval_col]]) & volcano_data[[pval_col]] < 0.05 & 
                                        !is.na(volcano_data[[fc_col]]) & volcano_data[[fc_col]] > 1] <- "Upregulated"
            volcano_data$significance[!is.na(volcano_data[[pval_col]]) & volcano_data[[pval_col]] < 0.05 & 
                                        !is.na(volcano_data[[fc_col]]) & volcano_data[[fc_col]] < -1] <- "Downregulated"
            volcano_data$log2FoldChange <- volcano_data[[fc_col]]
            if (!is.na(gene_col)) volcano_data$gene <- volcano_data[[gene_col]]
            saveRDS(volcano_data, file.path(tutorial_dir, "deg/volcano_data.rds"))
            
            deg_summary <- list(
              total_genes = nrow(deg_data),
              upregulated = nrow(up_genes),
              downregulated = nrow(down_genes),
              fc_threshold = 1,
              pval_threshold = 0.05
            )
            saveRDS(deg_summary, file.path(tutorial_dir, "deg/deg_summary.rds"))
          }
        }
        
        if (!is.null(rv_deg_main$volcano_plot_obj)) {
          saveRDS(rv_deg_main$volcano_plot_obj, file.path(tutorial_dir, "deg/volcano_plot.rds"))
          export_log$volcano_plot <- "OK"
        }
      }, error = function(e) export_log$deg_error <- paste("Error:", e$message))
      
      # 4. Heatmap
      incProgress(0.6, detail = "Heatmap data...")
      tryCatch({
        heatmap_saved <- FALSE
        if (exists("heatmap_data") && is.function(heatmap_data)) {
          heatmap_dat <- tryCatch(heatmap_data(), error = function(e) NULL)
          if (!is.null(heatmap_dat) && !is.null(heatmap_dat$matrix) && nrow(heatmap_dat$matrix) > 0) {
            saveRDS(heatmap_dat, file.path(tutorial_dir, "deg/heatmap_data.rds"))
            export_log$heatmap_data <- paste("OK -", nrow(heatmap_dat$matrix), "genes")
            heatmap_saved <- TRUE
          }
        }
        
        if (!heatmap_saved && !is.null(rv_deg_main$normalized_counts) && !is.null(rv_deg_main$deg_results)) {
          norm_counts <- rv_deg_main$normalized_counts
          deg_data <- rv_deg_main$deg_results
          pval_col <- intersect(c("padj", "FDR", "adj.P.Val"), colnames(deg_data))[1]
          fc_col <- intersect(c("log2FoldChange", "logFC", "log2FC"), colnames(deg_data))[1]
          gene_col <- intersect(c("gene_name", "Gene", "symbol", "gene_id"), colnames(deg_data))[1]
          
          if (!is.na(pval_col) && !is.na(fc_col)) {
            deg_data_sorted <- deg_data[order(deg_data[[pval_col]]), ]
            sig_degs <- deg_data_sorted[!is.na(deg_data_sorted[[pval_col]]) & 
                                          deg_data_sorted[[pval_col]] < 0.05 &
                                          !is.na(deg_data_sorted[[fc_col]]) &
                                          abs(deg_data_sorted[[fc_col]]) > 1, ]
            
            if (nrow(sig_degs) > 0) {
              top_n <- min(50, nrow(sig_degs))
              top_degs <- sig_degs[1:top_n, ]
              
              if (!is.na(gene_col) && gene_col %in% colnames(top_degs)) {
                gene_ids <- as.character(top_degs[[gene_col]])
              } else {
                gene_ids <- rownames(top_degs)
              }
              
              common_genes <- intersect(gene_ids, rownames(norm_counts))
              
              if (length(common_genes) >= 5) {
                heatmap_matrix <- as.matrix(norm_counts[common_genes, , drop = FALSE])
                heatmap_matrix <- t(scale(t(heatmap_matrix)))
                heatmap_matrix[is.na(heatmap_matrix)] <- 0
                heatmap_matrix[is.infinite(heatmap_matrix)] <- 0
                heatmap_matrix[heatmap_matrix > 3] <- 3
                heatmap_matrix[heatmap_matrix < -3] <- -3
                
                groups <- NULL
                if (!is.null(rv_deg_main$metadata_raw) && !is.null(rv_deg_main$metadata_group_column)) {
                  meta <- rv_deg_main$metadata_raw
                  group_col <- rv_deg_main$metadata_group_column
                  if (group_col %in% colnames(meta)) {
                    sample_col <- intersect(c("sample", "Sample", "SampleID", "sample_id"), colnames(meta))[1]
                    if (!is.na(sample_col)) {
                      sample_order <- match(colnames(heatmap_matrix), meta[[sample_col]])
                      groups <- meta[[group_col]][sample_order]
                    } else {
                      groups <- meta[[group_col]]
                    }
                  }
                }
                
                heatmap_export <- list(matrix = heatmap_matrix, genes = common_genes, groups = groups)
                saveRDS(heatmap_export, file.path(tutorial_dir, "deg/heatmap_data.rds"))
                export_log$heatmap_data <- paste("OK -", length(common_genes), "genes")
              }
            }
          }
        }
      }, error = function(e) export_log$heatmap_error <- paste("Error:", e$message))
      
      # 5. Pathway results
      incProgress(0.8, detail = "Pathway results...")
      tryCatch({
        pathway_data <- NULL
        if (exists("enrichment_results") && is.function(enrichment_results)) {
          pathway_data <- tryCatch(enrichment_results(), error = function(e) NULL)
        }
        
        if (!is.null(pathway_data) && is.data.frame(pathway_data) && nrow(pathway_data) > 0) {
          write.csv(pathway_data, file.path(tutorial_dir, "pathway/enrichment_results.csv"), row.names = FALSE)
          saveRDS(pathway_data, file.path(tutorial_dir, "pathway/enrichment_results.rds"))
          export_log$pathway_results <- paste("OK -", nrow(pathway_data), "pathways")
        }
      }, error = function(e) export_log$pathway_error <- paste("Error:", e$message))
      
      incProgress(1, detail = "Done!")
      export_log$export_time <- as.character(Sys.time())
      saveRDS(export_log, file.path(tutorial_dir, "export_log.rds"))
    })
    
    showNotification("Core tutorial data exported successfully!", type = "message", duration = 3)
  })
  
  # PPI NETWORK EXPORT
  # =========================================================================
  observeEvent(input$export_tutorial_ppi, {
    tutorial_dir <- "data/tutorial/advanced/ppi"
    dir.create(tutorial_dir, recursive = TRUE, showWarnings = FALSE)
    
    withProgress(message = "Exporting PPI Network data...", value = 0, {
      tryCatch({
        # Get PPI results from the correct location
        results <- NULL
        
        # Check ppi_results first (dedicated storage)
        if (!is.null(network_rv$ppi_results)) {
          results <- network_rv$ppi_results
          cat("Found PPI results in network_rv$ppi_results\n")
        } else if (!is.null(network_rv$current_results) && 
                   !is.null(network_rv$current_results$analysis_type) &&
                   network_rv$current_results$analysis_type == "ppi") {
          results <- network_rv$current_results
          cat("Found PPI results in network_rv$current_results\n")
        }
        
        if (is.null(results)) {
          showNotification("No PPI results found. Run PPI analysis first.", type = "warning", duration = 5)
          return()
        }
        
        export_count <- 0
        
        # 1. PPI Interactions
        incProgress(0.15, detail = "Saving interactions...")
        if (!is.null(results$ppi_interactions) && is.data.frame(results$ppi_interactions) && nrow(results$ppi_interactions) > 0) {
          write.csv(results$ppi_interactions, file.path(tutorial_dir, "interactions.csv"), row.names = FALSE)
          export_count <- export_count + 1
          cat("✓ Exported", nrow(results$ppi_interactions), "interactions\n")
        }
        
        # 2. Hub Proteins
        incProgress(0.3, detail = "Saving hub proteins...")
        if (!is.null(results$hub_proteins) && is.data.frame(results$hub_proteins) && nrow(results$hub_proteins) > 0) {
          write.csv(results$hub_proteins, file.path(tutorial_dir, "hub_proteins.csv"), row.names = FALSE)
          export_count <- export_count + 1
          cat("✓ Exported", nrow(results$hub_proteins), "hub proteins\n")
        }
        
        # 3. Network Data (for visualization)
        incProgress(0.45, detail = "Saving network data...")
        if (!is.null(results$network_data)) {
          if (!is.null(results$network_data$nodes) && nrow(results$network_data$nodes) > 0) {
            write.csv(results$network_data$nodes, file.path(tutorial_dir, "network_nodes.csv"), row.names = FALSE)
            cat("✓ Exported", nrow(results$network_data$nodes), "network nodes\n")
          }
          if (!is.null(results$network_data$edges) && nrow(results$network_data$edges) > 0) {
            write.csv(results$network_data$edges, file.path(tutorial_dir, "network_edges.csv"), row.names = FALSE)
            cat("✓ Exported", nrow(results$network_data$edges), "network edges\n")
          }
          saveRDS(results$network_data, file.path(tutorial_dir, "network_data.rds"))
          export_count <- export_count + 1
        }
        
        # 4. Modules
        incProgress(0.6, detail = "Saving modules...")
        if (!is.null(results$network_modules)) {
          if (is.data.frame(results$network_modules)) {
            write.csv(results$network_modules, file.path(tutorial_dir, "modules.csv"), row.names = FALSE)
          } else {
            saveRDS(results$network_modules, file.path(tutorial_dir, "modules.rds"))
          }
          export_count <- export_count + 1
        }
        
        # 5. Functional Enrichment
        incProgress(0.75, detail = "Saving enrichment...")
        if (!is.null(results$functional_enrichment)) {
          saveRDS(results$functional_enrichment, file.path(tutorial_dir, "functional_enrichment.rds"))
          export_count <- export_count + 1
        }
        
        # 6. Summary
        incProgress(0.9, detail = "Saving summary...")
        n_nodes <- if(!is.null(results$network_data$nodes)) nrow(results$network_data$nodes) else 0
        n_edges <- if(!is.null(results$ppi_interactions)) nrow(results$ppi_interactions) else 0
        n_hubs <- if(!is.null(results$hub_proteins)) nrow(results$hub_proteins) else 0
        
        summary_stats <- list(
          n_nodes = n_nodes,
          n_edges = n_edges,
          n_hub_proteins = n_hubs,
          network_metrics = results$network_metrics,
          analysis_params = results$analysis_params,
          export_date = Sys.time()
        )
        saveRDS(summary_stats, file.path(tutorial_dir, "summary.rds"))
        # Save network metrics separately for detailed analysis
        if (!is.null(results$network_metrics)) {
          saveRDS(results$network_metrics, file.path(tutorial_dir, "network_metrics.rds"))
          cat("✓ Exported network metrics\n")
        }
        
        # Also ensure centrality data is in hub_proteins
        if (!is.null(results$centrality_measures) && is.data.frame(results$centrality_measures)) {
          # Merge centrality with hub proteins if not already present
          if (!is.null(results$hub_proteins) && !"closeness" %in% colnames(results$hub_proteins)) {
            # Centrality measures can be added
            write.csv(results$centrality_measures, file.path(tutorial_dir, "centrality_measures.csv"), row.names = FALSE)
          }
        }
        incProgress(1, detail = "Done!")
        
        showNotification(
          HTML(paste0(
            "<strong>✅ PPI data exported!</strong><br>",
            "• ", n_nodes, " proteins<br>",
            "• ", n_edges, " interactions<br>",
            "• ", n_hubs, " hub proteins"
          )),
          type = "message", duration = 5
        )
        
      }, error = function(e) {
        showNotification(paste("Export error:", e$message), type = "error", duration = 5)
        cat("PPI export error:", e$message, "\n")
      })
    })
  })
  
  # =========================================================================
  # WGCNA EXPORT
  # =========================================================================
  observeEvent(input$export_tutorial_wgcna, {
    tutorial_dir <- "data/tutorial/advanced/wgcna"
    dir.create(tutorial_dir, recursive = TRUE, showWarnings = FALSE)
    
    withProgress(message = "Exporting WGCNA data...", value = 0, {
      tryCatch({
        results <- NULL
        
        # Check multiple locations
        if (!is.null(network_rv$current_results) && 
            !is.null(network_rv$current_results$analysis_type) &&
            network_rv$current_results$analysis_type == "wgcna") {
          results <- network_rv$current_results
          cat("Found WGCNA results in network_rv$current_results\n")
        } else if (!is.null(wgcna_standalone_rv$wgcna_results)) {
          results <- wgcna_standalone_rv$wgcna_results
          cat("Found WGCNA results in wgcna_standalone_rv\n")
        }
        
        if (is.null(results)) {
          showNotification("No WGCNA results found. Run WGCNA analysis first.", type = "warning", duration = 5)
          return()
        }
        
        export_count <- 0
        n_modules <- 0
        n_genes <- 0
        n_hubs <- 0
        
        # 1. Modules - Convert list to data frame
        incProgress(0.1, detail = "Saving modules...")
        if (!is.null(results$modules) && length(results$modules) > 0) {
          module_df <- do.call(rbind, lapply(names(results$modules), function(mod) {
            genes <- results$modules[[mod]]
            if (length(genes) > 0) {
              data.frame(gene = genes, module = mod, stringsAsFactors = FALSE)
            } else {
              NULL
            }
          }))
          if (!is.null(module_df) && nrow(module_df) > 0) {
            write.csv(module_df, file.path(tutorial_dir, "modules.csv"), row.names = FALSE)
            n_modules <- length(unique(module_df$module))
            n_genes <- nrow(module_df)
            export_count <- export_count + 1
            cat("✓ Exported", n_genes, "genes in", n_modules, "modules\n")
          }
        }
        
        # 2. Hub Genes
        incProgress(0.25, detail = "Saving hub genes...")
        if (!is.null(results$hub_genes) && is.data.frame(results$hub_genes) && nrow(results$hub_genes) > 0) {
          write.csv(results$hub_genes, file.path(tutorial_dir, "hub_genes.csv"), row.names = FALSE)
          n_hubs <- nrow(results$hub_genes)
          export_count <- export_count + 1
          cat("✓ Exported", n_hubs, "hub genes\n")
        }
        
        # 3. Module Eigengenes
        incProgress(0.4, detail = "Saving eigengenes...")
        if (!is.null(results$module_eigengenes) && 
            (is.data.frame(results$module_eigengenes) || is.matrix(results$module_eigengenes)) &&
            length(results$module_eigengenes) > 0) {
          write.csv(as.data.frame(results$module_eigengenes), 
                    file.path(tutorial_dir, "module_eigengenes.csv"), row.names = TRUE)
          export_count <- export_count + 1
          cat("✓ Exported module eigengenes\n")
        }
        
        # 4. Module-Trait Correlations
        incProgress(0.5, detail = "Saving trait correlations...")
        if (!is.null(results$module_trait_correlations) && length(results$module_trait_correlations) > 0) {
          if (is.matrix(results$module_trait_correlations) || is.data.frame(results$module_trait_correlations)) {
            write.csv(as.data.frame(results$module_trait_correlations), 
                      file.path(tutorial_dir, "trait_correlations.csv"), row.names = TRUE)
            export_count <- export_count + 1
            cat("✓ Exported trait correlations\n")
          }
        }
        
        # 5. Module Enrichment
        incProgress(0.6, detail = "Saving enrichment...")
        if (!is.null(results$module_enrichment) && length(results$module_enrichment) > 0) {
          # Create combined enrichment table
          enrichment_list <- list()
          for (mod_name in names(results$module_enrichment)) {
            mod_enrich <- results$module_enrichment[[mod_name]]
            if (is.data.frame(mod_enrich) && nrow(mod_enrich) > 0) {
              mod_enrich$module <- mod_name
              enrichment_list[[mod_name]] <- head(mod_enrich, 20)  # Top 20 per module
            }
          }
          if (length(enrichment_list) > 0) {
            combined_enrichment <- do.call(rbind, enrichment_list)
            write.csv(combined_enrichment, file.path(tutorial_dir, "module_enrichment.csv"), row.names = FALSE)
            cat("✓ Exported module enrichment\n")
          }
          saveRDS(results$module_enrichment, file.path(tutorial_dir, "enrichment.rds"))
          export_count <- export_count + 1
        }
        
        # 6. Dendrogram
        incProgress(0.7, detail = "Saving dendrogram...")
        if (!is.null(results$dendrogram)) {
          saveRDS(results$dendrogram, file.path(tutorial_dir, "dendrogram.rds"))
          export_count <- export_count + 1
          cat("✓ Exported dendrogram\n")
        }
        
        # 7. Module Colors
        incProgress(0.8, detail = "Saving colors...")
        colors <- results$module_colors_vector %||% results$module_colors
        if (!is.null(colors) && length(colors) > 0) {
          saveRDS(colors, file.path(tutorial_dir, "module_colors.rds"))
          export_count <- export_count + 1
        }
        
        # 8. Enhanced Summary Table (if available)
        if (!is.null(results$enhanced_summary_table) && nrow(results$enhanced_summary_table) > 0) {
          write.csv(results$enhanced_summary_table, file.path(tutorial_dir, "module_summary_table.csv"), row.names = FALSE)
          export_count <- export_count + 1
        }
        
        # 9. Summary Stats
        incProgress(0.9, detail = "Saving summary...")
        summary_stats <- list(
          n_modules = n_modules,
          n_genes = n_genes,
          n_hub_genes = n_hubs,
          has_trait_correlations = !is.null(results$module_trait_correlations) && length(results$module_trait_correlations) > 0,
          has_enrichment = !is.null(results$module_enrichment) && length(results$module_enrichment) > 0,
          soft_power = results$analysis_params$soft_power,
          scale_free_r2 = results$analysis_params$scale_free_r2,
          analysis_params = results$analysis_params,
          export_date = Sys.time()
        )
        saveRDS(summary_stats, file.path(tutorial_dir, "summary.rds"))
        
        incProgress(1, detail = "Done!")
        
        showNotification(
          HTML(paste0(
            "<strong>✅ WGCNA data exported!</strong><br>",
            "• ", n_modules, " modules<br>",
            "• ", n_genes, " genes<br>",
            "• ", n_hubs, " hub genes"
          )),
          type = "message", duration = 5
        )
        
      }, error = function(e) {
        showNotification(paste("Export error:", e$message), type = "error", duration = 5)
        cat("WGCNA export error:", e$message, "\n")
      })
    })
  })
  
