  # =========================================================================
  # DRUG TARGET EXPORT
  # =========================================================================
  observeEvent(input$export_tutorial_drug, {
    tutorial_dir <- "data/tutorial/advanced/drug"
    dir.create(tutorial_dir, recursive = TRUE, showWarnings = FALSE)
    
    withProgress(message = "Exporting Drug Target data...", value = 0, {
      tryCatch({
        if (!exists("network_rv") || is.null(network_rv$current_results)) {
          showNotification("No drug target results found. Run drug target analysis first.", type = "warning", duration = 5)
          return()
        }
        
        results <- network_rv$current_results
        
        # Also check drug_target_results storage
        if (!is.null(network_rv$drug_target_results)) {
          results <- network_rv$drug_target_results
          cat("Using results from network_rv$drug_target_results\n")
        }
        
        all_drug_data <- NULL
        sources_used <- c()
        
        incProgress(0.15, detail = "Collecting drug data...")
        
        # 1. Get drug_targets (main combined data)
        if (!is.null(results$drug_targets) && is.data.frame(results$drug_targets) && nrow(results$drug_targets) > 0) {
          all_drug_data <- results$drug_targets
          sources_used <- c(sources_used, "Combined")
          cat("✓ Found", nrow(results$drug_targets), "in drug_targets\n")
        }
        
        # 2. Get raw_data (another name for combined data)
        if (is.null(all_drug_data) && !is.null(results$raw_data) && is.data.frame(results$raw_data) && nrow(results$raw_data) > 0) {
          all_drug_data <- results$raw_data
          sources_used <- c(sources_used, "Combined")
          cat("✓ Found", nrow(results$raw_data), "in raw_data\n")
        }
        
        # 3. Get chembl_data (DGIdb results)
        if (!is.null(results$chembl_data) && is.data.frame(results$chembl_data) && nrow(results$chembl_data) > 0) {
          write.csv(results$chembl_data, file.path(tutorial_dir, "dgidb_results.csv"), row.names = FALSE)
          if (is.null(all_drug_data)) {
            all_drug_data <- results$chembl_data
          }
          sources_used <- c(sources_used, "DGIdb")
          cat("✓ Found", nrow(results$chembl_data), "DGIdb interactions\n")
        }
        
        # 4. Get opentargets_data
        if (!is.null(results$opentargets_data) && is.data.frame(results$opentargets_data) && nrow(results$opentargets_data) > 0) {
          write.csv(results$opentargets_data, file.path(tutorial_dir, "opentargets_results.csv"), row.names = FALSE)
          if (is.null(all_drug_data)) {
            all_drug_data <- results$opentargets_data
          }
          sources_used <- c(sources_used, "OpenTargets")
          cat("✓ Found", nrow(results$opentargets_data), "OpenTargets interactions\n")
        }
        
        if (is.null(all_drug_data) || nrow(all_drug_data) == 0) {
          showNotification("No drug interaction data found. Run drug target analysis first.", type = "warning", duration = 5)
          return()
        }
        
        incProgress(0.4, detail = "Saving interactions...")
        
        # Save main interactions file
        write.csv(all_drug_data, file.path(tutorial_dir, "drug_interactions.csv"), row.names = FALSE)
        
        # Detect column names
        gene_col <- intersect(c("gene_name", "gene", "Gene", "target_gene", "target"), colnames(all_drug_data))[1]
        drug_col <- intersect(c("molecule_name", "drug_name", "Drug", "compound_name", "drug"), colnames(all_drug_data))[1]
        
        n_drugs <- 0
        n_targets <- 0
        
        incProgress(0.55, detail = "Creating summaries...")
        
        if (!is.na(gene_col) && !is.na(drug_col)) {
          n_drugs <- length(unique(all_drug_data[[drug_col]]))
          n_targets <- length(unique(all_drug_data[[gene_col]]))
          
          # Target summary
          target_summary <- all_drug_data %>%
            dplyr::group_by(!!rlang::sym(gene_col)) %>%
            dplyr::summarise(
              n_drugs = dplyr::n_distinct(!!rlang::sym(drug_col)),
              drugs = paste(head(unique(!!rlang::sym(drug_col)), 5), collapse = "; "),
              .groups = "drop"
            ) %>%
            dplyr::arrange(dplyr::desc(n_drugs))
          
          colnames(target_summary)[1] <- "gene"
          write.csv(target_summary, file.path(tutorial_dir, "target_summary.csv"), row.names = FALSE)
          
          # Drug summary
          drug_summary <- all_drug_data %>%
            dplyr::group_by(!!rlang::sym(drug_col)) %>%
            dplyr::summarise(
              n_targets = dplyr::n_distinct(!!rlang::sym(gene_col)),
              targets = paste(head(unique(!!rlang::sym(gene_col)), 5), collapse = "; "),
              .groups = "drop"
            ) %>%
            dplyr::arrange(dplyr::desc(n_targets))
          
          colnames(drug_summary)[1] <- "drug"
          write.csv(drug_summary, file.path(tutorial_dir, "drug_summary.csv"), row.names = FALSE)
          
          cat("✓ Created target and drug summaries\n")
        }
        
        # 5. Drug Prioritization
        incProgress(0.7, detail = "Saving prioritization...")
        if (!is.null(results$drug_prioritization) && is.data.frame(results$drug_prioritization) && nrow(results$drug_prioritization) > 0) {
          write.csv(results$drug_prioritization, file.path(tutorial_dir, "drug_prioritization.csv"), row.names = FALSE)
          cat("✓ Exported", nrow(results$drug_prioritization), "prioritized drugs\n")
        }
        
        # 6. Network Data
        incProgress(0.8, detail = "Saving network data...")
        if (!is.null(results$network_data)) {
          saveRDS(results$network_data, file.path(tutorial_dir, "network_data.rds"))
          if (!is.null(results$network_data$nodes)) {
            write.csv(results$network_data$nodes, file.path(tutorial_dir, "network_nodes.csv"), row.names = FALSE)
          }
          if (!is.null(results$network_data$edges)) {
            write.csv(results$network_data$edges, file.path(tutorial_dir, "network_edges.csv"), row.names = FALSE)
          }
          cat("✓ Exported network data\n")
        }
        
        # 7. Summary
        incProgress(0.9, detail = "Saving summary...")
        summary_stats <- list(
          n_drugs = n_drugs,
          n_targets = n_targets,
          n_interactions = nrow(all_drug_data),
          sources = unique(sources_used),
          columns = list(gene_col = gene_col, drug_col = drug_col),
          analysis_params = results$analysis_params,
          export_date = Sys.time()
        )
        saveRDS(summary_stats, file.path(tutorial_dir, "summary.rds"))
        
        incProgress(1, detail = "Done!")
        
        showNotification(
          HTML(paste0(
            "<strong>✅ Drug target data exported!</strong><br>",
            "• ", n_drugs, " drugs<br>",
            "• ", n_targets, " targets<br>",
            "• ", nrow(all_drug_data), " interactions<br>",
            "Sources: ", paste(unique(sources_used), collapse = ", ")
          )),
          type = "message", duration = 5
        )
        
      }, error = function(e) {
        showNotification(paste("Export error:", e$message), type = "error", duration = 5)
        cat("Drug export error:", e$message, "\n")
      })
    })
  })
  
  # =========================================================================
  # CELL DECONVOLUTION EXPORT
  # =========================================================================
  observeEvent(input$export_tutorial_deconv, {
    tutorial_dir <- "data/tutorial/advanced/deconv"
    dir.create(tutorial_dir, recursive = TRUE, showWarnings = FALSE)
    
    withProgress(message = "Exporting Deconvolution data...", value = 0, {
      tryCatch({
        results <- NULL
        
        # Check deconv_results first (dedicated storage)
        if (!is.null(network_rv$deconv_results)) {
          results <- network_rv$deconv_results
          cat("Found deconv results in network_rv$deconv_results\n")
        } else if (!is.null(network_rv$current_results) && 
                   !is.null(network_rv$current_results$analysis_type) &&
                   network_rv$current_results$analysis_type == "deconv") {
          results <- network_rv$current_results
          cat("Found deconv results in network_rv$current_results\n")
        }
        
        if (is.null(results)) {
          showNotification("No deconvolution results found. Run deconvolution analysis first.", type = "warning", duration = 5)
          return()
        }
        
        cat("Results structure:\n")
        cat("  - Names:", paste(names(results), collapse = ", "), "\n")
        
        export_count <- 0
        n_samples <- 0
        n_cell_types <- 0
        method_used <- results$method %||% "Unknown"
        
        # 1. Raw Deconvolution Results (the actual scores matrix)
        incProgress(0.2, detail = "Saving raw scores...")
        raw_scores <- results$raw_deconv_results %||% results$deconv_data$raw_scores
        
        if (!is.null(raw_scores)) {
          if (is.matrix(raw_scores) || is.data.frame(raw_scores)) {
            raw_df <- as.data.frame(raw_scores)
            write.csv(raw_df, file.path(tutorial_dir, "raw_scores.csv"), row.names = TRUE)
            
            # Determine dimensions based on method
            # xCell and MCP-counter: cell types as rows, samples as columns
            # EPIC: samples as rows, cell types as columns
            if (method_used %in% c("xcell", "mcp_counter")) {
              n_cell_types <- nrow(raw_df)
              n_samples <- ncol(raw_df)
            } else {
              n_samples <- nrow(raw_df)
              n_cell_types <- ncol(raw_df)
            }
            
            export_count <- export_count + 1
            cat("✓ Exported raw scores:", n_cell_types, "cell types x", n_samples, "samples\n")
          }
        }
        
        # 2. Cell Composition Summary
        incProgress(0.35, detail = "Saving cell composition...")
        cell_comp <- results$cell_composition %||% results$deconv_data$cell_composition
        
        if (!is.null(cell_comp) && is.data.frame(cell_comp) && nrow(cell_comp) > 0) {
          write.csv(cell_comp, file.path(tutorial_dir, "cell_composition.csv"), row.names = FALSE)
          export_count <- export_count + 1
          cat("✓ Exported cell composition summary\n")
        }
        
        # 3. Marker Genes (DEG to cell type mapping)
        incProgress(0.5, detail = "Saving marker genes...")
        marker_genes <- results$marker_genes %||% results$deconv_data$marker_genes
        
        if (!is.null(marker_genes) && is.data.frame(marker_genes) && nrow(marker_genes) > 0) {
          write.csv(marker_genes, file.path(tutorial_dir, "marker_genes.csv"), row.names = FALSE)
          export_count <- export_count + 1
          cat("✓ Exported", nrow(marker_genes), "marker gene mappings\n")
        }
        
        # 4. Group Comparison (if available)
        incProgress(0.65, detail = "Saving group comparison...")
        group_comp <- results$group_comparison %||% results$deconv_data$group_comparison
        
        if (!is.null(group_comp) && is.data.frame(group_comp) && nrow(group_comp) > 0) {
          write.csv(group_comp, file.path(tutorial_dir, "group_comparison.csv"), row.names = FALSE)
          export_count <- export_count + 1
          cat("✓ Exported group comparison\n")
        }
        
        # 5. Create a transposed version for easier visualization (samples x cell_types)
        incProgress(0.75, detail = "Creating visualization-ready data...")
        if (!is.null(raw_scores)) {
          if (method_used %in% c("xcell", "mcp_counter")) {
            # Transpose so samples are rows
            viz_data <- as.data.frame(t(raw_scores))
          } else {
            viz_data <- as.data.frame(raw_scores)
          }
          write.csv(viz_data, file.path(tutorial_dir, "cell_proportions.csv"), row.names = TRUE)
          cat("✓ Created cell_proportions.csv for visualization\n")
        }
        
        # 6. Summary Stats
        incProgress(0.9, detail = "Saving summary...")
        deconv_stats <- results$summary_stats$deconv %||% list()
        
        summary_stats <- list(
          n_samples = n_samples,
          n_cell_types = n_cell_types,
          method = method_used,
          total_cell_types = deconv_stats$total_cell_types %||% n_cell_types,
          dominant_cell_type = deconv_stats$dominant_cell_type %||% "Unknown",
          confidence_score = deconv_stats$confidence_score %||% NA,
          marker_genes_count = deconv_stats$marker_genes %||% 0,
          has_groups = deconv_stats$has_groups %||% FALSE,
          data_info = results$data_info,
          export_date = Sys.time()
        )
        saveRDS(summary_stats, file.path(tutorial_dir, "summary.rds"))
        
        # Also save method info separately
        method_info <- list(
          method = method_used,
          cell_types = if(!is.null(cell_comp)) cell_comp$cell_type else NULL,
          timestamp = results$timestamp
        )
        saveRDS(method_info, file.path(tutorial_dir, "method_info.rds"))
        
        incProgress(1, detail = "Done!")
        
        if (export_count > 0) {
          showNotification(
            HTML(paste0(
              "<strong>✅ Deconvolution data exported!</strong><br>",
              "• ", n_samples, " samples<br>",
              "• ", n_cell_types, " cell types<br>",
              "• Method: ", method_used
            )),
            type = "message", duration = 5
          )
        } else {
          showNotification("Could not export deconvolution data. Check console for details.", type = "warning", duration = 5)
        }
        
      }, error = function(e) {
        showNotification(paste("Export error:", e$message), type = "error", duration = 5)
        cat("Deconv export error:", e$message, "\n")
        cat("Traceback:\n")
        traceback()
      })
    })
  })
  
  
  #######################################
  
  # === TUTORIAL SERVER ===
  tutorial_path <- "data/tutorial"
  tutorial_current <- reactiveVal("intro")
  
  observeEvent(input$tutorial_section, {
    tutorial_current(input$tutorial_section)
  })
  
  # Load tutorial data LAZILY - only load what's needed per section
  tutorial_data <- reactive({
    section <- tutorial_current()
    tutorial_path <- "data/tutorial"
    advanced_path <- "data/tutorial/advanced"
    
    # Base info - always needed
    base_data <- list(
      dataset_info = tryCatch(readRDS(file.path(tutorial_path, "dataset_info.rds")), error = function(e) NULL)
    )
    
    # Load section-specific data only
    section_data <- switch(section,
                           "intro" = list(),
                           
                           "data" = list(
                             counts_preview = tryCatch(read.csv(file.path(tutorial_path, "counts_preview.csv")), error = function(e) NULL),
                             metadata_preview = tryCatch(read.csv(file.path(tutorial_path, "metadata_preview.csv")), error = function(e) NULL)
                           ),
                           
                           "pca" = list(
                             pca_plot = tryCatch(readRDS(file.path(tutorial_path, "exploratory/pca_plot.rds")), error = function(e) NULL),
                             pca_results = tryCatch(readRDS(file.path(tutorial_path, "exploratory/pca_results.rds")), error = function(e) NULL)
                           ),
                           
                           "umap" = list(
                             umap_plot = tryCatch(readRDS(file.path(tutorial_path, "exploratory/umap_plot.rds")), error = function(e) NULL)
                           ),
                           
                           "batch" = list(
                             pca_before_batch = tryCatch(readRDS(file.path(tutorial_path, "exploratory/pca_before_batch.rds")), error = function(e) NULL),
                             pca_after_batch = tryCatch(readRDS(file.path(tutorial_path, "exploratory/pca_after_batch.rds")), error = function(e) NULL),
                             umap_before_batch = tryCatch(readRDS(file.path(tutorial_path, "exploratory/umap_before_batch.rds")), error = function(e) NULL),
                             umap_after_batch = tryCatch(readRDS(file.path(tutorial_path, "exploratory/umap_after_batch.rds")), error = function(e) NULL)
                           ),
                           
                           "deg" = list(
                             deg_summary = tryCatch(readRDS(file.path(tutorial_path, "deg/deg_summary.rds")), error = function(e) NULL),
                             col_info = tryCatch(readRDS(file.path(tutorial_path, "deg/column_info.rds")), error = function(e) NULL),
                             up_genes = tryCatch(read.csv(file.path(tutorial_path, "deg/upregulated_genes.csv")), error = function(e) NULL),
                             down_genes = tryCatch(read.csv(file.path(tutorial_path, "deg/downregulated_genes.csv")), error = function(e) NULL)
                           ),
                           
                           "volcano" = list(
                             volcano_data = tryCatch(readRDS(file.path(tutorial_path, "deg/volcano_data.rds")), error = function(e) NULL),
                             volcano_plot = tryCatch(readRDS(file.path(tutorial_path, "deg/volcano_plot.rds")), error = function(e) NULL)
                           ),
                           
                           "heatmap" = list(
                             heatmap_data = tryCatch(readRDS(file.path(tutorial_path, "deg/heatmap_data.rds")), error = function(e) NULL)
                           ),
                           
                           "pathway" = list(
                             pathway_results = tryCatch({
                               csv_path <- file.path(tutorial_path, "pathway/enrichment_results.csv")
                               rds_path <- file.path(tutorial_path, "pathway/enrichment_results.rds")
                               if (file.exists(csv_path)) read.csv(csv_path, stringsAsFactors = FALSE) 
                               else if (file.exists(rds_path)) readRDS(rds_path) 
                               else NULL
                             }, error = function(e) NULL)
                           ),
                           
                           # === ADVANCED ANALYSIS SECTIONS ===
                           "ppi" = list(
                             ppi_summary = tryCatch(readRDS(file.path(advanced_path, "ppi/summary.rds")), error = function(e) NULL),
                             ppi_interactions = tryCatch(read.csv(file.path(advanced_path, "ppi/interactions.csv"), stringsAsFactors = FALSE), error = function(e) NULL),
                             ppi_hubs = tryCatch(read.csv(file.path(advanced_path, "ppi/hub_proteins.csv"), stringsAsFactors = FALSE), error = function(e) NULL),
                             ppi_modules = tryCatch({
                               # Try CSV first (more reliable), then RDS
                               csv_path <- file.path(advanced_path, "ppi/modules.csv")
                               rds_path <- file.path(advanced_path, "ppi/modules.rds")
                               if (file.exists(csv_path)) {
                                 read.csv(csv_path, stringsAsFactors = FALSE)
                               } else if (file.exists(rds_path)) {
                                 readRDS(rds_path)
                               } else {
                                 NULL
                               }
                             }, error = function(e) NULL),
                             ppi_network_nodes = tryCatch(read.csv(file.path(advanced_path, "ppi/network_nodes.csv"), stringsAsFactors = FALSE), error = function(e) NULL),
                             ppi_network_edges = tryCatch(read.csv(file.path(advanced_path, "ppi/network_edges.csv"), stringsAsFactors = FALSE), error = function(e) NULL),
                             ppi_network_data = tryCatch(readRDS(file.path(advanced_path, "ppi/network_data.rds")), error = function(e) NULL)
                           ),
                           
                           "wgcna" = list(
                             wgcna_summary = tryCatch(readRDS(file.path(advanced_path, "wgcna/summary.rds")), error = function(e) NULL),
                             wgcna_modules = tryCatch(read.csv(file.path(advanced_path, "wgcna/modules.csv"), stringsAsFactors = FALSE), error = function(e) NULL),
                             wgcna_hubs = tryCatch(read.csv(file.path(advanced_path, "wgcna/hub_genes.csv"), stringsAsFactors = FALSE), error = function(e) NULL),
                             wgcna_traits = tryCatch(read.csv(file.path(advanced_path, "wgcna/trait_correlations.csv"), row.names = 1), error = function(e) NULL),
                             wgcna_enrichment = tryCatch(readRDS(file.path(advanced_path, "wgcna/enrichment.rds")), error = function(e) NULL),
                             wgcna_dendrogram = tryCatch(readRDS(file.path(advanced_path, "wgcna/dendrogram.rds")), error = function(e) NULL),
                             wgcna_params = tryCatch(readRDS(file.path(advanced_path, "wgcna/params.rds")), error = function(e) NULL)
                           ),
                           
                           "grn" = list(
                             grn_summary = tryCatch(readRDS(file.path(advanced_path, "grn/summary.rds")), error = function(e) NULL),
                             grn_master_regulators = tryCatch(read.csv(file.path(advanced_path, "grn/master_regulators.csv"), stringsAsFactors = FALSE), error = function(e) NULL),
                             grn_tf_targets = tryCatch(read.csv(file.path(advanced_path, "grn/tf_targets.csv"), stringsAsFactors = FALSE), error = function(e) NULL),
                             grn_activities = tryCatch(read.csv(file.path(advanced_path, "grn/tf_activities.csv"), stringsAsFactors = FALSE), error = function(e) NULL)
                           ),
                           
                           "drug" = list(
                             drug_summary = tryCatch(readRDS(file.path(advanced_path, "drug/summary.rds")), error = function(e) NULL),
                             drug_interactions = tryCatch(read.csv(file.path(advanced_path, "drug/drug_interactions.csv"), stringsAsFactors = FALSE), error = function(e) NULL),
                             drug_targets = tryCatch(read.csv(file.path(advanced_path, "drug/target_summary.csv"), stringsAsFactors = FALSE), error = function(e) NULL),
                             drug_network = tryCatch(readRDS(file.path(advanced_path, "drug/network_data.rds")), error = function(e) NULL)
                           ),
                           
                           "deconv" = list(
                             deconv_summary = tryCatch(readRDS(file.path(advanced_path, "deconv/summary.rds")), error = function(e) NULL),
                             deconv_proportions = tryCatch(read.csv(file.path(advanced_path, "deconv/cell_proportions.csv"), row.names = 1, stringsAsFactors = FALSE), error = function(e) NULL),
                             deconv_method = tryCatch(readRDS(file.path(advanced_path, "deconv/method_info.rds")), error = function(e) NULL)
                           ),
                           
                           # Default - return empty
                           list()
    )
    
    c(base_data, section_data)
  })
  
  
  # Up genes table
  output$tut_up_genes_table <- DT::renderDataTable({
    data <- tutorial_data()
    req(data$up_genes)
    
    df <- data$up_genes
    if (is.null(df) || nrow(df) == 0) return(NULL)
    
    # Get display columns (show more columns now)
    all_cols <- colnames(df)
    
    # Priority order for columns
    priority_cols <- c("gene_id", "gene_name", "Gene", "symbol",
                       "log2FoldChange", "logFC", "log2FC",
                       "padj", "FDR", "adj.P.Val",
                       "pvalue", "P.Value", "PValue",
                       "baseMean", "AveExpr")
    
    display_cols <- intersect(priority_cols, all_cols)
    if (length(display_cols) == 0) display_cols <- all_cols[1:min(5, length(all_cols))]
    
    # Remove comparison column if present (not useful)
    display_cols <- setdiff(display_cols, c("comparison", "Comparison"))
    
    df_display <- df[, display_cols, drop = FALSE]
    
    # Round numeric columns
    num_cols <- sapply(df_display, is.numeric)
    
    DT::datatable(df_display,
                  options = list(
                    pageLength = 25,
                    scrollX = TRUE,
                    scrollY = "400px",
                    dom = 'Bfrtip',
                    buttons = c('copy', 'csv'),
                    columnDefs = list(list(className = 'dt-center', targets = '_all'))
                  ),
                  rownames = FALSE,
                  class = 'compact stripe hover',
                  caption = paste("All", nrow(df), "upregulated genes (|log2FC| > 1, adj.P < 0.05)"),
                  extensions = 'Buttons'
    ) %>% DT::formatSignif(columns = which(num_cols), digits = 4)
  })
  
  # Down genes table - FULL TABLE
  output$tut_down_genes_table <- DT::renderDataTable({
    data <- tutorial_data()
    req(data$down_genes)
    
    df <- data$down_genes
    if (is.null(df) || nrow(df) == 0) return(NULL)
    
    all_cols <- colnames(df)
    priority_cols <- c("gene_id", "gene_name", "Gene", "symbol",
                       "log2FoldChange", "logFC", "log2FC",
                       "padj", "FDR", "adj.P.Val",
                       "pvalue", "P.Value", "PValue",
                       "baseMean", "AveExpr")
    
    display_cols <- intersect(priority_cols, all_cols)
    if (length(display_cols) == 0) display_cols <- all_cols[1:min(5, length(all_cols))]
    display_cols <- setdiff(display_cols, c("comparison", "Comparison"))
    
    df_display <- df[, display_cols, drop = FALSE]
    num_cols <- sapply(df_display, is.numeric)
    
    DT::datatable(df_display,
                  options = list(
                    pageLength = 25,
                    scrollX = TRUE,
                    scrollY = "400px",
                    dom = 'Bfrtip',
                    buttons = c('copy', 'csv'),
                    columnDefs = list(list(className = 'dt-center', targets = '_all'))
                  ),
                  rownames = FALSE,
                  class = 'compact stripe hover',
                  caption = paste("All", nrow(df), "downregulated genes (log2FC < -1, adj.P < 0.05)"),
                  extensions = 'Buttons'
    ) %>% DT::formatSignif(columns = which(num_cols), digits = 4)
  })
  
  # Tutorial pathway network - regenerate from saved data
  output$tut_pathway_network <- visNetwork::renderVisNetwork({
    data <- tutorial_data()
    pathway_data <- data$pathway_results
    
    if (is.null(pathway_data) || nrow(pathway_data) == 0) {
      return(NULL)
    }
    
    # Find the gene column
    gene_col <- NULL
    possible_gene_cols <- c("Genes", "geneID", "Gene", "genes", "core_enrichment")
    for (col in possible_gene_cols) {
      if (col %in% colnames(pathway_data)) {
        gene_col <- col
        break
      }
    }
    
    if (is.null(gene_col)) return(NULL)
    
    # Extract genes
    gene_lists <- strsplit(as.character(pathway_data[[gene_col]]), "[/;,]")
    all_genes <- unique(unlist(gene_lists))
    all_genes <- all_genes[!is.na(all_genes) & nchar(trimws(all_genes)) > 0]
    all_genes <- trimws(all_genes)
    
    if (length(all_genes) < 3 || nrow(pathway_data) < 1) return(NULL)
    
    # Limit for performance
    max_pathways <- min(25, nrow(pathway_data))
    max_genes <- min(80, length(all_genes))
    
    network_subset <- pathway_data[1:max_pathways, ]
    genes_subset <- all_genes[1:max_genes]
    
    # Get term column
    term_col <- intersect(c("Term", "Description", "pathway", "Pathway"), colnames(network_subset))[1]
    if (is.na(term_col)) term_col <- colnames(network_subset)[1]
    
    # Create pathway nodes
    pathway_nodes <- data.frame(
      id = paste0("pathway_", seq_len(nrow(network_subset))),
      label = substr(as.character(network_subset[[term_col]]), 1, 35),
      group = "Pathway",
      title = as.character(network_subset[[term_col]]),
      shape = "box",
      color.background = "#667eea",
      color.border = "#5a6fd6",
      font.color = "white",
      stringsAsFactors = FALSE
    )
    
    # Create gene nodes
    gene_nodes <- data.frame(
      id = paste0("gene_", genes_subset),
      label = genes_subset,
      group = "Gene",
      title = genes_subset,
      shape = "dot",
      color.background = "#43a047",
      color.border = "#2e7d32",
      font.color = "#333333",
      stringsAsFactors = FALSE
    )
    
    nodes <- rbind(pathway_nodes, gene_nodes)
    
    # Create edges
    edges_list <- list()
    for (i in seq_len(nrow(network_subset))) {
      pathway_genes <- unlist(strsplit(as.character(network_subset[[gene_col]][i]), "[/;,]"))
      pathway_genes <- trimws(pathway_genes)
      pathway_genes <- pathway_genes[pathway_genes %in% genes_subset]
      
      if (length(pathway_genes) > 0) {
        edges_list[[i]] <- data.frame(
          from = paste0("gene_", pathway_genes),
          to = paste0("pathway_", i),
          stringsAsFactors = FALSE
        )
      }
    }
    edges <- do.call(rbind, edges_list)
    
    if (is.null(edges) || nrow(edges) == 0) return(NULL)
    
    # Create visNetwork
    visNetwork::visNetwork(nodes, edges, 
                           width = "100%", height = "600px",
                           main = "Gene-Pathway Network") %>%
      visNetwork::visGroups(groupname = "Pathway", 
                            color = list(background = "#667eea", border = "#5a6fd6")) %>%
      visNetwork::visGroups(groupname = "Gene", 
                            color = list(background = "#43a047", border = "#2e7d32")) %>%
      visNetwork::visOptions(highlightNearest = list(enabled = TRUE, degree = 1),
                             nodesIdSelection = TRUE,
                             selectedBy = "group") %>%
      visNetwork::visLayout(randomSeed = 42) %>%
      visNetwork::visPhysics(stabilization = list(iterations = 100),
                             solver = "forceAtlas2Based") %>%
      visNetwork::visInteraction(dragNodes = TRUE, dragView = TRUE, zoomView = TRUE)
  })
  
  # Pathway table
  output$tut_pathway_table <- DT::renderDataTable({
    data <- tutorial_data()
    if (!is.null(data$pathway_results) && nrow(data$pathway_results) > 0) {
      # Select display columns based on what's available
      all_cols <- colnames(data$pathway_results)
      display_cols <- intersect(c("Database", "Term", "Overlap", "Gene_Count", "P.value", 
                                  "Adjusted.P.value", "Combined.Score", "Genes"), all_cols)
      if (length(display_cols) == 0) display_cols <- all_cols[1:min(6, length(all_cols))]
      
      DT::datatable(
        head(data$pathway_results[, display_cols, drop = FALSE], 30),
        options = list(dom = 'tip', pageLength = 15, scrollX = TRUE, scrollY = "400px"),
        rownames = FALSE, class = 'compact stripe hover',
        caption = paste("Top 30 of", nrow(data$pathway_results), "enriched pathways")
      ) %>% DT::formatSignif(columns = intersect(c("P.value", "Adjusted.P.value"), display_cols), digits = 3)
    }
  })
  
  # Heatmap plot
  output$tut_heatmap <- renderPlot({
    data <- tutorial_data()
    if (!is.null(data$heatmap_data)) {
      hm <- data$heatmap_data
      
      # Handle different data structures
      if (is.list(hm) && "matrix" %in% names(hm)) {
        mat <- hm$matrix
        groups <- hm$groups
      } else if (is.matrix(hm)) {
        mat <- hm
        groups <- NULL
      } else {
        return(NULL)
