        border_color = NA,
        fontsize_row = 7,
        fontsize_col = 9,
        cluster_rows = TRUE,
        cluster_cols = TRUE,
        show_rownames = nrow(mat) <= 50
      )
    }
  })
  
  
  
  output$tut_ppi_network <- visNetwork::renderVisNetwork({
    data <- tutorial_data()
    
    # Try multiple data sources
    nodes_data <- NULL
    edges_data <- NULL
    
    # First try: network_nodes.csv and network_edges.csv
    if (!is.null(data$ppi_network_nodes) && nrow(data$ppi_network_nodes) > 0) {
      nodes_data <- data$ppi_network_nodes
      edges_data <- data$ppi_network_edges
    }
    # Second try: network_data.rds
    else if (!is.null(data$ppi_network_data)) {
      if (!is.null(data$ppi_network_data$nodes)) {
        nodes_data <- data$ppi_network_data$nodes
      }
      if (!is.null(data$ppi_network_data$edges)) {
        edges_data <- data$ppi_network_data$edges
      }
    }
    # Third try: Build from interactions
    else if (!is.null(data$ppi_interactions) && nrow(data$ppi_interactions) > 0) {
      interactions <- data$ppi_interactions
      
      # Find from/to columns
      from_col <- intersect(c("from", "protein1", "preferredName_A", "source"), colnames(interactions))[1]
      to_col <- intersect(c("to", "protein2", "preferredName_B", "target"), colnames(interactions))[1]
      
      if (!is.na(from_col) && !is.na(to_col)) {
        all_proteins <- unique(c(interactions[[from_col]], interactions[[to_col]]))
        nodes_data <- data.frame(id = all_proteins, label = all_proteins, stringsAsFactors = FALSE)
        edges_data <- data.frame(from = interactions[[from_col]], to = interactions[[to_col]], stringsAsFactors = FALSE)
        
        if ("score" %in% colnames(interactions) || "combined_score" %in% colnames(interactions)) {
          score_col <- intersect(c("score", "combined_score"), colnames(interactions))[1]
          edges_data$value <- interactions[[score_col]]
        }
      }
    }
    
    # Check if we have data
    if (is.null(nodes_data) || nrow(nodes_data) == 0) {
      return(NULL)
    }
    
    # Ensure required columns exist
    if (!"id" %in% colnames(nodes_data)) {
      # Try to find id column
      id_col <- intersect(c("id", "name", "gene", "protein", "node"), colnames(nodes_data))[1]
      if (!is.na(id_col)) {
        nodes_data$id <- nodes_data[[id_col]]
      } else {
        nodes_data$id <- seq_len(nrow(nodes_data))
      }
    }
    
    if (!"label" %in% colnames(nodes_data)) {
      label_col <- intersect(c("label", "name", "gene", "protein", "id"), colnames(nodes_data))[1]
      nodes_data$label <- nodes_data[[label_col]]
    }
    
    # Color hub proteins
    hub_genes <- c()
    if (!is.null(data$ppi_hubs) && nrow(data$ppi_hubs) > 0) {
      hub_col <- intersect(c("gene", "protein", "Protein", "name", "id"), colnames(data$ppi_hubs))[1]
      if (!is.na(hub_col)) {
        hub_genes <- head(data$ppi_hubs[[hub_col]], 30)
      }
    }
    
    # Set colors and sizes
    nodes_data$color <- ifelse(nodes_data$id %in% hub_genes | nodes_data$label %in% hub_genes, 
                               "#E53935", "#667eea")
    nodes_data$size <- ifelse(nodes_data$id %in% hub_genes | nodes_data$label %in% hub_genes, 
                              30, 18)
    nodes_data$title <- paste0("<b>", nodes_data$label, "</b>",
                               ifelse(nodes_data$id %in% hub_genes | nodes_data$label %in% hub_genes, 
                                      "<br><span style='color:#E53935'>Hub Protein</span>", ""))
    
    # Prepare edges
    if (!is.null(edges_data) && nrow(edges_data) > 0) {
      if (!"from" %in% colnames(edges_data)) {
        from_col <- intersect(c("from", "source", "protein1"), colnames(edges_data))[1]
        to_col <- intersect(c("to", "target", "protein2"), colnames(edges_data))[1]
        if (!is.na(from_col)) edges_data$from <- edges_data[[from_col]]
        if (!is.na(to_col)) edges_data$to <- edges_data[[to_col]]
      }
      
      edges_data$color <- "#999999"
      edges_data$smooth <- FALSE
      
      if ("value" %in% colnames(edges_data)) {
        edges_data$width <- scales::rescale(edges_data$value, to = c(1, 4))
      } else {
        edges_data$width <- 1.5
      }
    }
    
    # Create visNetwork
    visNetwork::visNetwork(
      nodes_data, 
      edges_data, 
      height = "550px", 
      width = "100%",
      main = list(text = "PPI Network", style = "font-family: sans-serif; font-size: 16px; color: #1a237e;")
    ) %>%
      visNetwork::visNodes(
        font = list(size = 14, color = "#333"),
        borderWidth = 2,
        borderWidthSelected = 3
      ) %>%
      visNetwork::visEdges(
        smooth = FALSE,
        color = list(color = "#999", highlight = "#667eea")
      ) %>%
      visNetwork::visOptions(
        highlightNearest = list(enabled = TRUE, degree = 1, hover = TRUE),
        nodesIdSelection = list(enabled = TRUE, style = "width: 200px; height: 30px;"),
        selectedBy = list(variable = "label", highlight = TRUE)
      ) %>%
      visNetwork::visPhysics(
        solver = "forceAtlas2Based",
        forceAtlas2Based = list(gravitationalConstant = -50, springLength = 100),
        stabilization = list(enabled = TRUE, iterations = 200)
      ) %>%
      visNetwork::visInteraction(
        dragNodes = TRUE, 
        dragView = TRUE, 
        zoomView = TRUE,
        navigationButtons = TRUE,
        keyboard = TRUE,
        tooltipDelay = 100
      ) %>%
      visNetwork::visLegend(
        addNodes = list(
          list(label = "Hub Protein", shape = "dot", color = "#E53935", size = 20),
          list(label = "Regular Protein", shape = "dot", color = "#667eea", size = 15)
        ),
        useGroups = FALSE,
        position = "right",
        width = 0.15
      )
  })
  
  output$tut_ppi_hubs <- DT::renderDataTable({
    data <- tutorial_data()
    hubs <- data$ppi_hubs
    
    if (is.null(hubs) || nrow(hubs) == 0) {
      return(DT::datatable(
        data.frame(Message = "No hub protein data available. Export PPI data first."),
        options = list(dom = 't', ordering = FALSE),
        rownames = FALSE,
        class = 'cell-border'
      ))
    }
    
    # Select and rename columns for display
    col_mapping <- c(
      "gene" = "Protein",
      "protein" = "Protein", 
      "hub_type" = "Hub Type",
      "degree" = "Degree",
      "hub_score" = "Hub Score",
      "betweenness" = "Betweenness",
      "eigenvector" = "Eigenvector",
      "closeness" = "Closeness",
      "regulation_status" = "Regulation"
    )
    
    # Find available columns
    available_cols <- intersect(names(col_mapping), colnames(hubs))
    
    if (length(available_cols) == 0) {
      # Use first few columns if no standard columns found
      available_cols <- colnames(hubs)[1:min(6, ncol(hubs))]
      hub_display <- hubs[, available_cols, drop = FALSE]
    } else {
      hub_display <- hubs[, available_cols, drop = FALSE]
      # Rename columns
      for (old_name in available_cols) {
        if (old_name %in% names(col_mapping)) {
          colnames(hub_display)[colnames(hub_display) == old_name] <- col_mapping[old_name]
        }
      }
    }
    
    # Filter to show only actual hubs (not regular nodes) if hub_type exists
    if ("Hub Type" %in% colnames(hub_display)) {
      hub_display <- hub_display[!hub_display$`Hub Type` %in% c("Regular node", "Regular", "Non-hub"), ]
    }
    
    # Limit rows
    hub_display <- head(hub_display, 100)
    
    # Identify numeric columns
    num_cols <- names(which(sapply(hub_display, is.numeric)))
    
    dt <- DT::datatable(
      hub_display,
      options = list(
        pageLength = 15,
        scrollX = TRUE,
        scrollY = "380px",
        scrollCollapse = TRUE,
        dom = 'frtip',
        ordering = TRUE,
        order = list(list(2, 'desc')),  # Sort by degree descending
        columnDefs = list(
          list(className = 'dt-center', targets = '_all')
        ),
        language = list(
          search = "Filter:",
          info = "Showing _START_ to _END_ of _TOTAL_ hub proteins"
        ),
        # CRITICAL: Keep headers visible
        fixedHeader = TRUE
      ),
      rownames = FALSE,
      class = 'compact stripe hover cell-border',
      selection = 'single'
    )
    
    # Format numeric columns
    if (length(num_cols) > 0) {
      dt <- dt %>% DT::formatRound(columns = num_cols, digits = 4)
    }
    
    # Style Hub Type column if present
    if ("Hub Type" %in% colnames(hub_display)) {
      dt <- dt %>% DT::formatStyle(
        'Hub Type',
        backgroundColor = DT::styleEqual(
          c("Super hub", "Major Hub", "Degree hub", "Bottleneck", "Authority hub", "Hub"),
          c('#c8e6c9', '#c8e6c9', '#dcedc8', '#fff9c4', '#ffe082', '#bbdefb')
        ),
        fontWeight = 'bold',
        color = DT::styleEqual(
          c("Super hub", "Major Hub", "Degree hub", "Bottleneck", "Authority hub", "Hub"),
          c('#1b5e20', '#1b5e20', '#33691e', '#f57f17', '#e65100', '#0d47a1')
        )
      )
    }
    
    dt
  })
  
  
  output$tut_ppi_modules <- DT::renderDataTable({
    data <- tutorial_data()
    modules <- data$ppi_modules
    
    # If no modules data, check summary for module count
    if (is.null(modules)) {
      summary <- data$ppi_summary
      n_modules <- 0
      if (!is.null(summary) && !is.null(summary$network_metrics)) {
        n_modules <- summary$network_metrics$n_modules %||% 0
      }
      
      if (n_modules == 0) {
        return(DT::datatable(
          data.frame(
            Module = 1:3,
            Proteins = c("-", "-", "-"),
            Description = c("Module detection requires sufficient network connectivity",
                            "Re-run PPI analysis with more genes or lower score threshold",
                            "Then export data again")
          ),
          options = list(dom = 't', ordering = FALSE, paging = FALSE),
          rownames = FALSE,
          class = 'cell-border stripe'
        ))
      }
    }
    
    # Process modules data based on format
    if (is.data.frame(modules)) {
      # Check if it's already a summary table
      if (all(c("module", "n_genes") %in% colnames(modules)) || 
          all(c("Module", "Proteins") %in% colnames(modules))) {
        module_summary <- modules
      } 
      # Check for gene-level module assignments
      else if ("module" %in% colnames(modules) || "cluster" %in% colnames(modules)) {
        mod_col <- intersect(c("module", "cluster", "Module"), colnames(modules))[1]
        gene_col <- intersect(c("gene", "protein", "name", "id"), colnames(modules))[1]
        
        if (!is.na(mod_col) && !is.na(gene_col)) {
          module_summary <- modules %>%
            group_by(!!sym(mod_col)) %>%
            summarise(
              n_genes = n(),
              top_genes = paste(head(!!sym(gene_col), 5), collapse = ", "),
              .groups = "drop"
            ) %>%
            arrange(desc(n_genes))
          
          # Add "..." if more than 5 genes
          module_summary$top_genes <- ifelse(
            module_summary$n_genes > 5,
            paste0(module_summary$top_genes, " ..."),
            module_summary$top_genes
          )
          
          colnames(module_summary) <- c("Module", "Proteins", "Top Proteins")
        } else {
          module_summary <- modules
        }
      }
      else {
        # Unknown format - display as is
        module_summary <- modules
      }
    } 
    else if (is.list(modules)) {
      # Convert list format to data frame
      module_summary <- data.frame(
        Module = names(modules),
        Proteins = sapply(modules, length),
        `Top Proteins` = sapply(modules, function(x) paste(head(x, 5), collapse = ", ")),
        stringsAsFactors = FALSE,
        check.names = FALSE
      )
    }
    else {
      return(DT::datatable(
        data.frame(Message = "Module data format not supported"),
        options = list(dom = 't'),
        rownames = FALSE
      ))
    }
    
    DT::datatable(
      module_summary,
      options = list(
        pageLength = 10,
        scrollX = TRUE,
        dom = 'frtip',
        columnDefs = list(
          list(className = 'dt-center', targets = '_all')
        )
      ),
      rownames = FALSE,
      class = 'compact stripe hover cell-border'
    )
  })
  
  # Network Statistics Table
  output$tut_ppi_network_stats <- renderTable({
    data <- tutorial_data()
    summary <- data$ppi_summary
    
    metrics <- data.frame(
      Metric = character(),
      Value = character(),
      stringsAsFactors = FALSE
    )
    
    # Get values from summary
    if (!is.null(summary)) {
      metrics <- rbind(metrics, data.frame(
        Metric = "Total Proteins", 
        Value = format(summary$n_nodes %||% 0, big.mark = ",")
      ))
      metrics <- rbind(metrics, data.frame(
        Metric = "Total Interactions", 
        Value = format(summary$n_edges %||% 0, big.mark = ",")
      ))
      metrics <- rbind(metrics, data.frame(
        Metric = "Hub Proteins", 
        Value = as.character(summary$n_hub_proteins %||% 0)
      ))
      
      # Network metrics if available
      nm <- summary$network_metrics
      if (!is.null(nm)) {
        if (!is.null(nm$input_genes)) {
          metrics <- rbind(metrics, data.frame(Metric = "Input Genes", Value = as.character(nm$input_genes)))
        }
        if (!is.null(nm$coverage_rate)) {
          metrics <- rbind(metrics, data.frame(Metric = "Coverage Rate", Value = paste0(round(nm$coverage_rate * 100, 1), "%")))
        }
        if (!is.null(nm$density)) {
          metrics <- rbind(metrics, data.frame(Metric = "Network Density", Value = format(round(nm$density, 4), nsmall = 4)))
        }
        if (!is.null(nm$avg_degree)) {
          metrics <- rbind(metrics, data.frame(Metric = "Average Degree", Value = format(round(nm$avg_degree, 2), nsmall = 2)))
        }
        if (!is.null(nm$n_modules)) {
          metrics <- rbind(metrics, data.frame(Metric = "Network Modules", Value = as.character(nm$n_modules)))
        }
      }
    }
    
    if (nrow(metrics) == 0) {
      metrics <- data.frame(Metric = "No data available", Value = "-")
    }
    
    metrics
  }, striped = TRUE, hover = TRUE, bordered = TRUE, width = "100%", align = "l")
  
