  # Degree Distribution Plot (Plotly)
  output$tut_ppi_degree_dist <- renderPlotly({
    data <- tutorial_data()
    hubs <- data$ppi_hubs
    interactions <- data$ppi_interactions
    
    degree_values <- NULL
    
    # Try to get degree from hubs data
    if (!is.null(hubs) && "degree" %in% colnames(hubs)) {
      degree_values <- hubs$degree
    }
    # Calculate from interactions
    else if (!is.null(interactions) && nrow(interactions) > 0) {
      from_col <- intersect(c("from", "protein1", "preferredName_A", "source"), colnames(interactions))[1]
      to_col <- intersect(c("to", "protein2", "preferredName_B", "target"), colnames(interactions))[1]
      
      if (!is.na(from_col) && !is.na(to_col)) {
        all_proteins <- c(interactions[[from_col]], interactions[[to_col]])
        degree_values <- as.numeric(table(all_proteins))
      }
    }
    
    if (is.null(degree_values) || length(degree_values) == 0) {
      return(plotly::plot_ly() %>% 
               plotly::layout(
                 title = list(text = "Degree Distribution", font = list(size = 18, color = "#1a237e")),
                 annotations = list(
                   list(text = "Export PPI data to view degree distribution", 
                        x = 0.5, y = 0.5, xref = "paper", yref = "paper",
                        showarrow = FALSE, font = list(size = 16, color = "#666"))
                 ),
                 xaxis = list(visible = FALSE),
                 yaxis = list(visible = FALSE)
               ))
    }
    
    # Create histogram
    plotly::plot_ly(
      x = degree_values,
      type = "histogram",
      marker = list(
        color = "#4caf50",
        line = list(color = "#2e7d32", width = 1)
      ),
      hovertemplate = "<b>Degree:</b> %{x}<br><b>Count:</b> %{y}<extra></extra>"
    ) %>%
      plotly::layout(
        title = list(text = "Degree Distribution", font = list(size = 18, color = "#1a237e")),
        xaxis = list(title = list(text = "Node Degree", font = list(size = 14)), gridcolor = "#eee", zeroline = FALSE),
        yaxis = list(title = list(text = "Number of Proteins", font = list(size = 14)), gridcolor = "#eee", zeroline = FALSE),
        plot_bgcolor = "#fafafa",
        paper_bgcolor = "white",
        bargap = 0.1,
        margin = list(t = 60, b = 60, l = 60, r = 40)
      )
  })
  
  
  # Confidence Score Distribution Plot
  output$tut_ppi_confidence_dist <- renderPlotly({
    data <- tutorial_data()
    interactions <- data$ppi_interactions
    
    score_col <- NULL
    if (!is.null(interactions)) {
      score_col <- intersect(c("score", "combined_score", "confidence"), colnames(interactions))[1]
    }
    
    if (is.null(interactions) || is.na(score_col)) {
      return(plotly::plot_ly() %>% 
               plotly::layout(
                 title = list(text = "Confidence Score Distribution", font = list(size = 18, color = "#1a237e")),
                 annotations = list(
                   list(text = "Confidence scores not available in exported data", 
                        x = 0.5, y = 0.5, xref = "paper", yref = "paper",
                        showarrow = FALSE, font = list(size = 16, color = "#666"))
                 ),
                 xaxis = list(visible = FALSE),
                 yaxis = list(visible = FALSE)
               ))
    }
    
    scores <- interactions[[score_col]]
    # Normalize scores if they're in 0-1000 range
    if (max(scores, na.rm = TRUE) > 1) {
      scores <- scores / 1000
    }
    
    plotly::plot_ly(
      x = scores,
      type = "histogram",
      marker = list(
        color = "#2196f3",
        line = list(color = "#1565c0", width = 1)
      ),
      hovertemplate = "<b>Score:</b> %{x:.2f}<br><b>Count:</b> %{y}<extra></extra>"
    ) %>%
      plotly::layout(
        title = list(text = "Confidence Score Distribution", font = list(size = 18, color = "#1a237e")),
        xaxis = list(title = list(text = "Confidence Score", font = list(size = 14)), 
                     range = c(0, 1), gridcolor = "#eee", zeroline = FALSE),
        yaxis = list(title = list(text = "Number of Interactions", font = list(size = 14)), 
                     gridcolor = "#eee", zeroline = FALSE),
        plot_bgcolor = "#fafafa",
        paper_bgcolor = "white",
        bargap = 0.1,
        margin = list(t = 60, b = 60, l = 60, r = 40),
        shapes = list(
          list(type = "line", x0 = 0.7, x1 = 0.7, y0 = 0, y1 = 1, yref = "paper",
               line = list(color = "#ff5722", dash = "dash", width = 2))
        ),
        annotations = list(
          list(x = 0.72, y = 0.95, xref = "x", yref = "paper",
               text = "High confidence threshold (0.7)", showarrow = FALSE,
               font = list(size = 12, color = "#ff5722"))
        )
      )
  })
  
  # Centrality Analysis Plot (Plotly)
  output$tut_ppi_centrality_plot <- renderPlotly({
    data <- tutorial_data()
    hubs <- data$ppi_hubs
    
    # Check for required centrality columns
    has_betweenness <- !is.null(hubs) && "betweenness" %in% colnames(hubs)
    has_degree <- !is.null(hubs) && "degree" %in% colnames(hubs)
    
    if (!has_betweenness || !has_degree) {
      return(plotly::plot_ly() %>% 
               plotly::layout(
                 title = list(text = "Centrality Analysis", font = list(size = 18, color = "#1a237e")),
                 annotations = list(
                   list(text = "Centrality data not available.\nExport PPI data to view this plot.", 
                        x = 0.5, y = 0.5, xref = "paper", yref = "paper",
                        showarrow = FALSE, font = list(size = 16, color = "#666"))
                 ),
                 xaxis = list(visible = FALSE),
                 yaxis = list(visible = FALSE)
               ))
    }
    
    # Prepare data
    plot_data <- hubs
    
    # Add closeness if missing (use eigenvector as proxy or calculate dummy)
    if (!"closeness" %in% colnames(plot_data)) {
      if ("eigenvector" %in% colnames(plot_data)) {
        plot_data$closeness <- plot_data$eigenvector
      } else {
        # Create normalized closeness proxy from betweenness and degree
        plot_data$closeness <- scales::rescale(plot_data$degree / (1 + plot_data$betweenness), to = c(0.3, 1))
      }
    }
    
    # Get protein name
    name_col <- intersect(c("gene", "protein", "Protein", "name", "id"), colnames(plot_data))[1]
    if (is.na(name_col)) name_col <- colnames(plot_data)[1]
    
    # Create hover text
    plot_data$protein_name <- plot_data[[name_col]]
    plot_data$hover_text <- paste0(
      "<b>", plot_data$protein_name, "</b><br>",
      "Degree: ", plot_data$degree, "<br>",
      "Betweenness: ", round(plot_data$betweenness, 4), "<br>",
      "Closeness: ", round(plot_data$closeness, 4)
    )
    
    # Limit to top proteins for clarity
    plot_data <- head(plot_data[order(-plot_data$degree), ], 100)
    
    plotly::plot_ly(
      data = plot_data,
      x = ~betweenness,
      y = ~closeness,
      size = ~degree,
      color = ~degree,
      colors = c("#1a237e", "#4caf50", "#ffc107"),
      type = "scatter",
      mode = "markers",
      marker = list(
        opacity = 0.75,
        sizemode = "diameter",
        sizeref = max(plot_data$degree, na.rm = TRUE) / 35,
        sizemin = 8,
        line = list(width = 1, color = "white")
      ),
      text = ~hover_text,
      hovertemplate = "%{text}<extra></extra>"
    ) %>%
      plotly::layout(
        title = list(text = "Centrality Analysis", font = list(size = 18, color = "#1a237e")),
        xaxis = list(title = list(text = "Betweenness Centrality", font = list(size = 14)), 
                     gridcolor = "#eee", zeroline = FALSE),
        yaxis = list(title = list(text = "Closeness Centrality", font = list(size = 14)), 
                     gridcolor = "#eee", zeroline = FALSE),
        plot_bgcolor = "#fafafa",
        paper_bgcolor = "white",
        margin = list(t = 60, b = 60, l = 60, r = 40),
        coloraxis = list(
          colorbar = list(title = list(text = "Degree", font = list(size = 12)))
        )
      ) %>%
      plotly::colorbar(title = "Degree")
  })
  
