  output$tut_grn_network <- visNetwork::renderVisNetwork({
    data <- tutorial_data()
    tf_targets <- data$grn_tf_targets
    
    if (is.null(tf_targets) || nrow(tf_targets) < 1) {
      return(NULL)
    }
    
    # Limit for visualization
    tf_targets <- head(tf_targets, 500)
    
    # Create nodes
    tfs <- unique(tf_targets$tf)
    targets <- unique(tf_targets$target)
    
    tf_nodes <- data.frame(
      id = tfs,
      label = tfs,
      group = "TF",
      color = "#E53935",
      size = 25,
      shape = "diamond",
      stringsAsFactors = FALSE
    )
    
    target_nodes <- data.frame(
      id = targets[!targets %in% tfs],
      label = targets[!targets %in% tfs],
      group = "Target",
      color = "#667eea",
      size = 15,
      shape = "dot",
      stringsAsFactors = FALSE
    )
    
    nodes <- rbind(tf_nodes, target_nodes)
    
    edges <- data.frame(
      from = tf_targets$tf,
      to = tf_targets$target,
      arrows = "to",
      stringsAsFactors = FALSE
    )
    
    visNetwork::visNetwork(nodes, edges, height = "500px", width = "100%") %>%
      visNetwork::visGroups(groupname = "TF", color = "#E53935") %>%
      visNetwork::visGroups(groupname = "Target", color = "#667eea") %>%
      visNetwork::visOptions(highlightNearest = TRUE) %>%
      visNetwork::visPhysics(solver = "forceAtlas2Based", 
                             stabilization = list(iterations = 100))
  })
  
  output$tut_grn_activity <- renderPlot({
    data <- tutorial_data()
    activities <- data$grn_activities
    
    if (is.null(activities) || nrow(activities) == 0) {
      plot.new()
      text(0.5, 0.5, "No TF activity data available", cex = 1.2, col = "gray50")
      return()
    }
    
    tryCatch({
      # Plot top TFs by activity
      top_activities <- head(activities[order(-abs(activities$activity)), ], 20)
      
      ggplot(top_activities, aes(x = reorder(tf, activity), y = activity, fill = activity > 0)) +
        geom_bar(stat = "identity") +
        coord_flip() +
        scale_fill_manual(values = c("TRUE" = "#43a047", "FALSE" = "#E53935"), guide = "none") +
        labs(title = "Top Transcription Factor Activities",
             x = "Transcription Factor",
             y = "Activity Score") +
        theme_minimal(base_size = 12) +
        theme(plot.title = element_text(hjust = 0.5, face = "bold"))
    }, error = function(e) {
      plot.new()
      text(0.5, 0.5, "Could not render activity plot", cex = 1.2, col = "gray50")
    })
  })
  
