  output$tut_heatmap <- renderPlot({
    data <- tutorial_data()
    hm <- data$heatmap_data
    
    if (is.null(hm)) {
      # Return empty plot with message
      plot.new()
      text(0.5, 0.5, "Heatmap data not available.\nGenerate heatmap in the analysis first,\nthen re-export tutorial data.", 
           cex = 1.2, col = "gray50")
      return()
    }
    
    # Handle different data structures
    if (is.list(hm) && "matrix" %in% names(hm)) {
      mat <- hm$matrix
      groups <- hm$groups
    } else if (is.matrix(hm)) {
      mat <- hm
      groups <- NULL
    } else {
      plot.new()
      text(0.5, 0.5, "Invalid heatmap data format", cex = 1.2, col = "gray50")
      return()
    }
    
    # Check matrix validity
    if (is.null(mat) || nrow(mat) < 2 || ncol(mat) < 2) {
      plot.new()
      text(0.5, 0.5, paste("Not enough data for heatmap\n(", 
                           if(is.null(mat)) "NULL" else paste(nrow(mat), "x", ncol(mat)), ")"), 
           cex = 1.2, col = "gray50")
      return()
    }
    
    cat("DEBUG: Rendering heatmap with", nrow(mat), "genes x", ncol(mat), "samples\n")
    
    # Create annotation if groups available
    annotation_col <- NULL
    ann_colors <- NULL
    if (!is.null(groups) && length(groups) == ncol(mat)) {
      annotation_col <- data.frame(Group = as.factor(groups), row.names = colnames(mat))
      
      # Create colors for groups
      unique_groups <- unique(groups)
      n_groups <- length(unique_groups)
      group_colors <- RColorBrewer::brewer.pal(max(3, min(n_groups, 9)), "Set1")[1:n_groups]
      names(group_colors) <- unique_groups
      ann_colors <- list(Group = group_colors)
    }
    
    # Draw heatmap
    pheatmap::pheatmap(
      mat,
      annotation_col = annotation_col,
      annotation_colors = ann_colors,
      main = paste("Top", nrow(mat), "DEGs Expression Heatmap (Z-score normalized)"),
      color = colorRampPalette(c("#2166AC", "#F7F7F7", "#B2182B"))(100),
      border_color = NA,
      fontsize_row = if(nrow(mat) > 30) 6 else 8,
      fontsize_col = 9,
      cluster_rows = TRUE,
      cluster_cols = TRUE,
      show_rownames = nrow(mat) <= 50,
      show_colnames = TRUE,
      scale = "none",  # Already scaled
      treeheight_row = 30,
      treeheight_col = 30
    )
  })
  
  
  
  
  
  
