  # Batch-effect detection on sample PCs (one row per sample).
  #  - PVCA (Li et al. 2009): linear mixed model per PC with every candidate variable as a
  #    random effect (lme4, REML); variance components weighted by PC variance over the PCs
  #    that explain >= 60% of the variance of the retained PCs. Falls back to one variable per
  #    model when the joint model cannot be fitted (e.g. fully confounded variables).
  #  - kBET (Buttner et al. 2019): for every sample, chi-square test of the batch labels of its
  #    k nearest neighbours (k = mean batch size, >= 5) against the global batch frequencies;
  #    rejection rate = share of tests with p < 0.05 (Monte-Carlo p-values for small counts).
  #  - Silhouette width of the batch labels in PC space.
  #  Combined score = 0.4 x PVCA + 0.4 x kBET rejection + 0.2 x max(0, silhouette).
  #  A variable is flagged when at least two of: PVCA >= 0.15, kBET rejection >= 0.25,
  #  silhouette >= 0.05. Thresholds were set from the 95th percentiles of each metric in
  #  simulated batch-free data (8-48 samples), so the expected false-positive rate is below 5%.
  TX_BATCH_THRESHOLDS <- c(pvca = 0.15, kbet = 0.25, silhouette = 0.05)
  tx_pvca <- function(pc_data, meta) {
    ev <- apply(pc_data, 2, stats::var)
    n_use <- max(2, which(cumsum(ev) / sum(ev) >= 0.6)[1])
    n_use <- min(n_use, ncol(pc_data))
    w <- ev[seq_len(n_use)] / sum(ev[seq_len(n_use)])
    vars <- colnames(meta)
    fit_one <- function(y, vs) {
      df <- data.frame(y = y, meta[, vs, drop = FALSE])
      for (v in vs) df[[v]] <- factor(df[[v]])
      f <- stats::as.formula(paste("y ~ 1 +", paste(sprintf("(1|`%s`)", vs), collapse = " + ")))
      fit <- suppressWarnings(suppressMessages(lme4::lmer(f, data = df, REML = TRUE,
               control = lme4::lmerControl(check.nobs.vs.nlev = "ignore", check.nobs.vs.nRE = "ignore",
                                           check.nlev.gtr.1 = "ignore", calc.derivs = FALSE))))
      vc <- as.data.frame(lme4::VarCorr(fit))
      stats::setNames(vc$vcov, vc$grp)
    }
    frac <- stats::setNames(numeric(length(vars)), vars); method <- "joint"
    joint_ok <- tryCatch({
      for (j in seq_len(n_use)) {
        comps <- fit_one(pc_data[, j], vars)
        comps <- comps / sum(comps)
        frac <- frac + w[j] * comps[vars]
      }
      TRUE
    }, error = function(e) FALSE)
    if (!joint_ok || any(is.na(frac))) {
      method <- "per-variable"
      frac <- sapply(vars, function(v) tryCatch({
        sum(sapply(seq_len(n_use), function(j) { comps <- fit_one(pc_data[, j], v); w[j] * comps[v] / sum(comps) }))
      }, error = function(e) NA_real_))
    }
    attr(frac, "method") <- method
    frac
  }
  tx_kbet <- function(pc_data, batch) {
    batch <- factor(batch)
    n <- nrow(pc_data)
    k <- min(n - 1, max(5, floor(mean(table(batch)))))
    p_glob <- as.numeric(table(batch)) / n
    nn <- as.matrix(stats::dist(pc_data))
    pvals <- sapply(seq_len(n), function(i) {
      idx <- order(nn[i, ])[2:(k + 1)]
      obs <- as.numeric(table(factor(batch[idx], levels = levels(batch))))
      small <- any(k * p_glob < 5)
      suppressWarnings(stats::chisq.test(obs, p = p_glob, simulate.p.value = small, B = 2000)$p.value)
    })
    mean(pvals < 0.05)
  }

  detect_batch_effects_advanced <- function(pca_data, metadata_cols, expression_data = NULL) {
    if (ncol(metadata_cols) == 0) {
      return(list(has_batch = FALSE, detection_phase = "no_metadata", scores = NULL, recommended_batch = NULL,
                  metrics = list(), message = "No metadata columns available for batch detection"))
    }
    n_samples <- nrow(pca_data)
    pc_data <- as.matrix(pca_data[, 1:min(10, ncol(pca_data)), drop = FALSE])
    usable <- Filter(function(cn) {
      n_unique <- length(unique(stats::na.omit(metadata_cols[[cn]])))
      n_unique > 1 && n_unique <= n_samples * 0.5 && n_unique < n_samples && !any(is.na(metadata_cols[[cn]]))
    }, colnames(metadata_cols))
    if (length(usable) == 0) {
      return(list(has_batch = FALSE, detection_phase = "no_suitable_variables", scores = NULL, recommended_batch = NULL,
                  metrics = list(), message = "No suitable batch variables detected in metadata"))
    }
    meta <- as.data.frame(metadata_cols[, usable, drop = FALSE])
    pvca <- tryCatch(tx_pvca(pc_data, meta), error = function(e) stats::setNames(rep(NA_real_, length(usable)), usable))
    rows <- lapply(usable, function(cn) {
      f <- factor(meta[[cn]])
      sil <- tryCatch(mean(cluster::silhouette(as.integer(f), stats::dist(pc_data))[, 3]), error = function(e) NA_real_)
      kb <- tryCatch(tx_kbet(pc_data, f), error = function(e) NA_real_)
      pv <- unname(pvca[cn])
      crit <- sum(c(isTRUE(pv >= TX_BATCH_THRESHOLDS[["pvca"]]), isTRUE(kb >= TX_BATCH_THRESHOLDS[["kbet"]]),
                    isTRUE(sil >= TX_BATCH_THRESHOLDS[["silhouette"]])))
      data.frame(column = cn, pvca_variance = pv, silhouette = sil, kbet_mixing = kb,
                 n_levels = nlevels(f), criteria_met = crit,
                 combined_score = 0.4 * ifelse(is.na(pv), 0, pv) + 0.4 * ifelse(is.na(kb), 0, kb) +
                                  0.2 * ifelse(is.na(sil), 0, max(0, sil)),
                 stringsAsFactors = FALSE)
    })
    scores_df <- do.call(rbind, rows)
    scores_df <- scores_df[order(-scores_df$criteria_met, -scores_df$combined_score), ]
    top_score <- scores_df[1, ]
    has_significant_batch <- isTRUE(top_score$criteria_met >= 2)
    message <- if (has_significant_batch) {
      sprintf("✓ Batch effect detected in '%s' (%d of 3 criteria met)\n   PVCA: %.1f%% | kBET rejection: %.2f | Silhouette: %.3f | Combined: %.3f",
              top_score$column, top_score$criteria_met, 100 * top_score$pvca_variance, top_score$kbet_mixing,
              top_score$silhouette, top_score$combined_score)
    } else {
      sprintf("✓ No significant batch effects detected\n   Highest: '%s' meets %d of 3 criteria (Combined: %.3f)",
              top_score$column, top_score$criteria_met, top_score$combined_score)
    }
    print(paste("\U0001F4CA", message))
    list(has_batch = has_significant_batch, detection_phase = "complete", scores = scores_df,
         recommended_batch = if (has_significant_batch) top_score$column else NULL,
         metrics = list(top_pvca = top_score$pvca_variance, top_silhouette = top_score$silhouette,
                        top_kbet = top_score$kbet_mixing, top_combined = top_score$combined_score,
                        criteria_met = top_score$criteria_met, pvca_method = attr(pvca, "method")),
         message = message)
  }

  detect_batch_effects_advanced_legacy <- function(pca_data, metadata_cols, expression_data = NULL) {
    # Advanced batch effect detection using multiple quantitative methods
    # Returns comprehensive assessment with metrics
    
    if (ncol(metadata_cols) == 0) {
      return(list(
        has_batch = FALSE,
        detection_phase = "no_metadata",
        scores = NULL,
        recommended_batch = NULL,
        metrics = list(),
        message = "No metadata columns available for batch detection"
      ))
    }
    
    print("🔍 Phase 1: Automated Batch Detection Started...")
    
    batch_scores <- list()
    n_samples <- nrow(pca_data)
    
    for (col_name in colnames(metadata_cols)) {
      col_data <- metadata_cols[[col_name]]
      
      # Skip if too many unique values (likely continuous) or only 1 level
      n_unique <- length(unique(na.omit(col_data)))
      if (n_unique <= 1 || n_unique > n_samples * 0.5 || n_unique == n_samples) {
        next
      }
      
      tryCatch({
        print(paste("   Testing column:", col_name, "with", n_unique, "levels"))
        
        # Use first 10 PCs for comprehensive assessment
        pc_data <- pca_data[, 1:min(10, ncol(pca_data))]
        
        # ================================================================
        # METRIC 1: Silhouette Score (Clustering Quality)
        # ================================================================
        dist_matrix <- dist(pc_data)
        factor_var <- as.factor(col_data)
        numeric_clusters <- as.numeric(factor_var)
        
        silhouette_score <- NA
        if (length(unique(numeric_clusters)) > 1 && length(unique(numeric_clusters)) < n_samples) {
          sil <- cluster::silhouette(numeric_clusters, dist_matrix)
          silhouette_score <- mean(sil[, 3])
        }
        
        # ================================================================
        # METRIC 2: PVCA (Principal Variance Component Analysis)
        # Measures variance explained by this variable
        # ================================================================
        pvca_score <- tryCatch({
          # Perform PERMANOVA-like variance partitioning
          # Calculate total sum of squares
          centroid <- colMeans(pc_data)
          ss_total <- sum(sapply(1:nrow(pc_data), function(i) {
            sum((pc_data[i, ] - centroid)^2)
          }))
          
          # Calculate within-group sum of squares
          ss_within <- 0
          for (level in unique(factor_var)) {
            group_idx <- which(factor_var == level)
            if (length(group_idx) > 1) {
              group_centroid <- colMeans(pc_data[group_idx, , drop = FALSE])
              ss_within <- ss_within + sum(sapply(group_idx, function(i) {
                sum((pc_data[i, ] - group_centroid)^2)
              }))
            }
          }
          
          # R-squared: proportion of variance explained
          r_squared <- 1 - (ss_within / ss_total)
          max(0, min(1, r_squared))  # Bound between 0 and 1
        }, error = function(e) NA)
        
        # ================================================================
        # METRIC 3: kBET-like Local Mixing Score
        # Tests if batches mix well locally (lower = more batch effect)
        # ================================================================
        kbet_score <- tryCatch({
          # For each sample, check k-nearest neighbors
          k <- min(15, floor(n_samples / 5))
          
          # Calculate distances and find k-nearest neighbors
          mixing_scores <- sapply(1:n_samples, function(i) {
            dists <- as.matrix(dist_matrix)[i, ]
            nearest_idx <- order(dists)[2:(k+1)]  # Exclude self
            
            # Expected proportion of each batch
            batch_i <- factor_var[i]
            neighbors_batches <- factor_var[nearest_idx]
            
            # Chi-square-like test: are neighbors from same batch?
            same_batch <- sum(neighbors_batches == batch_i)
            expected_same <- k * (sum(factor_var == batch_i) / n_samples)
            
            # Deviation from expected (normalized)
            abs(same_batch - expected_same) / k
          })
          
          mean(mixing_scores, na.rm = TRUE)
        }, error = function(e) NA)
        
        # ================================================================
        # METRIC 4: PC Correlation (how much do PCs correlate with batch?)
        # ================================================================
        pc_correlation <- tryCatch({
          # Test correlation between each PC and the batch variable
          cors <- sapply(1:min(5, ncol(pc_data)), function(pc_idx) {
            # Use Kruskal-Wallis for non-parametric correlation
            kw_test <- kruskal.test(pc_data[, pc_idx] ~ factor_var)
            # Convert p-value to effect size (higher = stronger effect)
            1 - kw_test$p.value
          })
          max(cors, na.rm = TRUE)
        }, error = function(e) NA)
        
        # ================================================================
        # Combined Score (weighted average of metrics)
        # ================================================================
        weights <- c(
          pvca = 0.35,        # Variance explained (most important)
          silhouette = 0.25,  # Clustering quality
          kbet = 0.25,        # Local mixing
          pc_cor = 0.15       # PC correlation
        )
        
        # Normalize silhouette from [-1,1] to [0,1]
        silhouette_norm <- if (!is.na(silhouette_score)) (silhouette_score + 1) / 2 else 0
        
        valid_scores <- c(
          if (!is.na(pvca_score)) weights["pvca"] * pvca_score else 0,
          if (!is.na(silhouette_score)) weights["silhouette"] * silhouette_norm else 0,
          if (!is.na(kbet_score)) weights["kbet"] * kbet_score else 0,
          if (!is.na(pc_correlation)) weights["pc_cor"] * pc_correlation else 0
        )
        
        combined_score <- sum(valid_scores)
        
        batch_scores[[col_name]] <- list(
          pvca = pvca_score,
          silhouette = silhouette_score,
          kbet = kbet_score,
          pc_correlation = pc_correlation,
          n_levels = n_unique,
          combined_score = combined_score
        )
        
        print(sprintf("     [OK] %s: PVCA=%.3f, Sil=%.3f, kBET=%.3f, Combined=%.3f", 
                      col_name, pvca_score, silhouette_score, kbet_score, combined_score))
        
      }, error = function(e) {
        print(paste("      [FAIL] Error testing", col_name, ":", e$message))
        NULL
      })
    }
    
    if (length(batch_scores) == 0) {
      return(list(
        has_batch = FALSE,
        detection_phase = "no_suitable_variables",
        scores = NULL,
        recommended_batch = NULL,
        metrics = list(),
        message = "No suitable batch variables detected in metadata"
      ))
    }
    
    # ================================================================
    # Phase 2: Source Identification - Rank all candidates
    # ================================================================
    print("🎯 Phase 2: Source Identification...")
    
    scores_df <- do.call(rbind, lapply(names(batch_scores), function(name) {
      data.frame(
        column = name,
        pvca_variance = batch_scores[[name]]$pvca,
        silhouette = batch_scores[[name]]$silhouette,
        kbet_mixing = batch_scores[[name]]$kbet,
        pc_correlation = batch_scores[[name]]$pc_correlation,
        n_levels = batch_scores[[name]]$n_levels,
        combined_score = batch_scores[[name]]$combined_score,
        stringsAsFactors = FALSE
      )
    }))
    
    scores_df <- scores_df[order(-scores_df$combined_score), ]
    
    # ================================================================
    # Significance Threshold
    # ================================================================
    # Consider significant if:
    # - PVCA (R²) > 0.15 (explains >15% variance) OR
    # - Silhouette > 0.2 (good clustering) OR
    # - kBET > 0.3 (poor mixing) OR
    # - Combined score > 0.25
    
    top_score <- scores_df[1, ]
    
    has_significant_batch <- (
      (!is.na(top_score$pvca_variance) && top_score$pvca_variance > 0.15) ||
        (!is.na(top_score$silhouette) && top_score$silhouette > 0.2) ||
        (!is.na(top_score$kbet_mixing) && top_score$kbet_mixing > 0.3) ||
        (!is.na(top_score$combined_score) && top_score$combined_score > 0.25)
    )
    
    # ================================================================
    # Generate detailed message
    # ================================================================
    if (has_significant_batch) {
      message <- sprintf(
        "✓ Significant batch effect detected in '%s'\n   PVCA: %.1f%% | Silhouette: %.3f | kBET: %.3f | Combined: %.3f",
        top_score$column,
        top_score$pvca_variance * 100,
        top_score$silhouette,
        top_score$kbet_mixing,
        top_score$combined_score
      )
    } else {
      message <- sprintf(
        "✓ No significant batch effects detected\n   Highest score: '%s' (Combined: %.3f) - below significance threshold",
        top_score$column,
        top_score$combined_score
      )
    }
    
    print(paste("📊", message))
    
    return(list(
      has_batch = has_significant_batch,
      detection_phase = "complete",
      scores = scores_df,
      recommended_batch = if (has_significant_batch) top_score$column else NULL,
      metrics = list(
        top_pvca = top_score$pvca_variance,
        top_silhouette = top_score$silhouette,
        top_kbet = top_score$kbet_mixing,
        top_combined = top_score$combined_score
      ),
      message = message
    ))
  }
  
  # Phase 3: Correction Assessment
  assess_batch_correction <- function(before_data, after_data, batch_variable) {
    # Quantify how much batch effect was reduced
    
    tryCatch({
      # Ensure data is valid
      if (is.null(before_data) || is.null(after_data) || is.null(batch_variable)) {
        stop("Invalid input data")
      }
      
      if (nrow(before_data) != nrow(after_data)) {
        stop("Before and after data have different sample sizes")
      }
      
      # Calculate metrics before and after
      before_pca <- prcomp(before_data, scale. = TRUE, center = TRUE)
      after_pca <- prcomp(after_data, scale. = TRUE, center = TRUE)
      
      # Use first 2 PCs for distance calculation
      before_dist <- dist(before_pca$x[, 1:2])
      after_dist <- dist(after_pca$x[, 1:2])
      
      factor_var <- as.factor(batch_variable)
      numeric_clusters <- as.numeric(factor_var)
      
      # Check if we have valid clustering
      if (length(unique(numeric_clusters)) < 2) {
        stop("Need at least 2 batch levels for assessment")
      }
      
      # Silhouette scores
      sil_before <- cluster::silhouette(numeric_clusters, before_dist)
      sil_after <- cluster::silhouette(numeric_clusters, after_dist)
      
      avg_sil_before <- mean(sil_before[, 3])
      avg_sil_after <- mean(sil_after[, 3])
      
      # Reduction percentage
      # High positive silhouette = samples cluster by batch (bad)
      # Low/negative silhouette = samples don't cluster by batch (good)
      
      batch_effect_before <- max(avg_sil_before, 0)
      batch_effect_after <- max(avg_sil_after, 0)
      
      if (batch_effect_before > 0.01) {
        reduction_pct <- ((batch_effect_before - batch_effect_after) / batch_effect_before) * 100
        # If silhouette went negative, cap at 100% (batch effect fully removed)
        if (avg_sil_after < 0) {
          reduction_pct <- 100
        }
      } else {
        reduction_pct <- 0
      }
      
      # Bound to sensible values
      reduction_pct <- max(-50, min(100, reduction_pct))
      
      # Assessment based on reduction and final silhouette
      if (reduction_pct >= 80 || (reduction_pct >= 60 && avg_sil_after < 0.1)) {
        assessment <- "Excellent correction"
        color <- "#4caf50"
      } else if (reduction_pct >= 50 || (reduction_pct >= 30 && avg_sil_after < 0.15)) {
        assessment <- "Good correction"
        color <- "#8bc34a"
      } else if (reduction_pct >= 20) {
        assessment <- "Moderate correction"
        color <- "#ff9800"
      } else if (reduction_pct >= 0) {
        assessment <- "Weak correction"
        color <- "#ff5722"
      } else {
        assessment <- "Correction ineffective"
        color <- "#f44336"
      }
      
      # Check for potential overcorrection
      if (avg_sil_after < -0.3 && avg_sil_before > 0) {
        assessment <- paste(assessment, "(possible overcorrection)")
        color <- "#ff9800"
      }
      
      print(sprintf("📊 Correction Assessment: %s (%.1f%% reduction)", assessment, reduction_pct))
      
      return(list(
        sil_before = avg_sil_before,
        sil_after = avg_sil_after,
        reduction_pct = reduction_pct,
        assessment = assessment,
        color = color,
        message = sprintf(
          "%s: %.1f%% batch variance reduction (Sil: %.3f → %.3f)",
          assessment, reduction_pct, avg_sil_before, avg_sil_after
        )
      ))
      
    }, error = function(e) {
      print(paste("⚠️ Correction assessment error:", e$message))
      return(list(
        sil_before = NA,
        sil_after = NA,
        reduction_pct = NA,
        assessment = "Unable to assess",
        color = "#666",
        message = paste("Could not compute correction metrics:", e$message)
      ))
    })
  }
  
  # UI Generator for Detection Report
  create_batch_detection_report_ui <- function(detection_results, correction_assessment = NULL) {
    # Create comprehensive UI showing detection results and correction assessment
    
    if (detection_results$detection_phase == "no_metadata") {
      return(
        div(
          style = "background: #fff3e0; padding: 15px; border-radius: 8px; border-left: 4px solid #ff9800; margin: 15px 0;",
          h5(icon("info-circle"), " Batch Detection Status", style = "color: #e65100; margin-top: 0;"),
          p("No metadata available for batch detection. Automatic detection requires metadata with potential batch variables.",
            style = "margin: 0;")
        )
      )
    }
    
    if (!detection_results$has_batch) {
      return(
        div(
          style = "background: #e8f5e9; padding: 15px; border-radius: 8px; border-left: 4px solid #4caf50; margin: 15px 0;",
          h5(icon("check-circle"), " Batch Effect Analysis", style = "color: #2e7d32; margin-top: 0;"),
          p(strong("Result:"), " No significant batch effects detected in your data.", 
            style = "margin-bottom: 8px;"),
          p("Your samples cluster primarily by biological groups, suggesting minimal technical variation.",
            style = "font-size: 0.9em; color: #555; margin: 0;"),
          
          if (!is.null(detection_results$scores) && nrow(detection_results$scores) > 0) {
            tagList(
              hr(style = "margin: 15px 0;"),
              p(strong("Top candidate checked:"), tags$code(detection_results$scores$column[1]),
                sprintf(" (Combined Score: %.3f - below threshold)", detection_results$scores$combined_score[1]),
                style = "font-size: 0.85em; color: #666; margin: 0;")
            )
          }
        )
      )
    }
    
    # Batch detected - comprehensive report
    scores_table <- detection_results$scores
    recommended <- detection_results$recommended_batch
    metrics <- detection_results$metrics
    
    # Create metrics display
    metrics_html <- sprintf(
      "<div style='display: grid; grid-template-columns: repeat(2, 1fr); gap: 10px; margin: 15px 0;'>
      <div style='background: white; padding: 10px; border-radius: 5px; border-left: 3px solid #2196F3;'>
        <div style='font-size: 0.75em; color: #666; margin-bottom: 3px;'>PVCA (Variance)</div>
        <div style='font-size: 1.3em; font-weight: bold; color: #1976D2;'>%.1f%%</div>
      </div>
      <div style='background: white; padding: 10px; border-radius: 5px; border-left: 3px solid #9c27b0;'>
        <div style='font-size: 0.75em; color: #666; margin-bottom: 3px;'>Silhouette Score</div>
        <div style='font-size: 1.3em; font-weight: bold; color: #7b1fa2;'>%.3f</div>
      </div>
      <div style='background: white; padding: 10px; border-radius: 5px; border-left: 3px solid #ff9800;'>
        <div style='font-size: 0.75em; color: #666; margin-bottom: 3px;'>kBET (rejection rate)</div>
        <div style='font-size: 1.3em; font-weight: bold; color: #f57c00;'>%.3f</div>
      </div>
      <div style='background: white; padding: 10px; border-radius: 5px; border-left: 3px solid #4caf50;'>
        <div style='font-size: 0.75em; color: #666; margin-bottom: 3px;'>Combined Score</div>
        <div style='font-size: 1.3em; font-weight: bold; color: #388e3c;'>%.3f</div>
      </div>
    </div>",
      metrics$top_pvca * 100,
      metrics$top_silhouette,
      metrics$top_kbet,
      metrics$top_combined
    )
    
    # Create ranking table (top 3) - COLLAPSED BY DEFAULT
    table_html <- "<table style='width:100%; font-size: 0.85em; margin-top: 10px; border-collapse: collapse;'>"
    table_html <- paste0(table_html, "<thead><tr style='background: #f5f5f5; border-bottom: 2px solid #ddd;'>")
    table_html <- paste0(table_html, "<th style='padding: 8px; text-align: left;'>Rank</th>")
    table_html <- paste0(table_html, "<th style='padding: 8px; text-align: left;'>Column</th>")
    table_html <- paste0(table_html, "<th style='padding: 8px; text-align: center;'>PVCA</th>")
    table_html <- paste0(table_html, "<th style='padding: 8px; text-align: center;'>kBET</th>")
    table_html <- paste0(table_html, "<th style='padding: 8px; text-align: center;'>Silhouette</th>")
    table_html <- paste0(table_html, "<th style='padding: 8px; text-align: center;'>Combined</th></tr></thead><tbody>")
    
    for (i in 1:min(3, nrow(scores_table))) {
      row <- scores_table[i, ]
      is_recommended <- row$column == recommended
      row_style <- if (is_recommended) {
        "background: #fff8e1; font-weight: bold; border-left: 3px solid #ff9800;"
      } else {
        "border-bottom: 1px solid #eee;"
      }
      
      table_html <- paste0(table_html, "<tr style='", row_style, "'>")
      table_html <- paste0(table_html, "<td style='padding: 8px;'>", 
                           if (is_recommended) "🏆" else paste0("#", i), "</td>")
      table_html <- paste0(table_html, "<td style='padding: 8px;'>", 
                           if (is_recommended) paste0("<strong>", row$column, "</strong>") else row$column, "</td>")
      table_html <- paste0(table_html, "<td style='padding: 8px; text-align: center;'>", 
                           sprintf("%.2f", row$pvca_variance), "</td>")
      table_html <- paste0(table_html, "<td style='padding: 8px; text-align: center;'>",
                           sprintf("%.2f", row$kbet_mixing), "</td>")
      table_html <- paste0(table_html, "<td style='padding: 8px; text-align: center;'>",
                           sprintf("%.3f", row$silhouette), "</td>")
      table_html <- paste0(table_html, "<td style='padding: 8px; text-align: center;'>", 
                           sprintf("%.3f", row$combined_score), "</td></tr>")
    }
    table_html <- paste0(table_html, "</tbody></table>")
    
    # Correction assessment (if available)
    correction_html <- ""
    if (!is.null(correction_assessment) && !is.na(correction_assessment$reduction_pct)) {
      
      # Create before/after comparison metrics
      metrics_comparison <- sprintf(
        "<div style='display: grid; grid-template-columns: repeat(3, 1fr); gap: 10px; margin: 15px 0;'>
        <div style='background: white; padding: 12px; border-radius: 5px; border-left: 3px solid #ff5722;'>
          <div style='font-size: 0.75em; color: #666; margin-bottom: 3px;'>Before Correction</div>
          <div style='font-size: 1.1em; font-weight: bold; color: #ff5722;'>Silhouette: %.3f</div>
          <div style='font-size: 0.8em; color: #999;'>Samples cluster by batch</div>
        </div>
        <div style='background: white; padding: 12px; border-radius: 5px; text-align: center; display: flex; align-items: center; justify-content: center;'>
          <div style='font-size: 2em; color: #4caf50;'>→</div>
        </div>
        <div style='background: white; padding: 12px; border-radius: 5px; border-left: 3px solid #4caf50;'>
          <div style='font-size: 0.75em; color: #666; margin-bottom: 3px;'>After Correction</div>
          <div style='font-size: 1.1em; font-weight: bold; color: #4caf50;'>Silhouette: %.3f</div>
          <div style='font-size: 0.8em; color: #999;'>Batch effect removed</div>
        </div>
      </div>",
        correction_assessment$sil_before,
        correction_assessment$sil_after
      )
      
      correction_html <- sprintf(
        "%s
      <div style='background: %s; padding: 12px; border-radius: 6px; margin-top: 10px; border-left: 4px solid %s;'>
        <p style='margin: 0; font-weight: bold; color: white; font-size: 1.1em;'>%s</p>
        <p style='margin: 5px 0 0 0; font-size: 0.95em; color: white; opacity: 0.95;'>
          Batch clustering reduced by %.1f%%
        </p>
      </div>",
        metrics_comparison,
        correction_assessment$color,
        correction_assessment$color,
        correction_assessment$assessment,
        correction_assessment$reduction_pct
      )
    }
    
    div(
      style = "background: linear-gradient(135deg, #fff3e0 0%, #ffe0b2 100%); padding: 15px; border-radius: 8px; border-left: 4px solid #ff9800; margin: 15px 0;",
      h5(icon("exclamation-triangle"), " Batch Effect Detected & Corrected", 
         style = "color: #e65100; margin-top: 0;"),
      
      p(strong("Primary batch source identified:"), tags$code(recommended, style = "background: #fff; padding: 2px 6px; border-radius: 3px;"),
        style = "margin-bottom: 10px;"),
      
      HTML(metrics_html),
      
      # REPLACED details() with Shiny's collapsible div
      div(
        style = "margin-top: 15px;",
        tags$button(
          class = "btn btn-sm btn-default",
          style = "margin-bottom: 10px;",
          `data-toggle` = "collapse",
          `data-target` = "#detection-metrics-table",
          icon("table"), " View Detection Metrics for All Candidates"
        ),
        div(
          id = "detection-metrics-table",
          class = "collapse",
          style = "margin-top: 10px;",
          HTML(table_html)
        )
      ),
      
      hr(style = "margin: 15px 0;"),
      
      div(
        style = "font-size: 0.9em;",
        p(strong("📊 What do these metrics mean?"), style = "margin-bottom: 8px; color: #d84315;"),
        tags$ul(
          style = "margin: 5px 0; padding-left: 20px; line-height: 1.6;",
          tags$li(strong("PVCA (Variance):"), " Share of variation explained by this variable, from mixed models on the top PCs (criterion: \u2265 15%)"),
          tags$li(strong("kBET (rejection rate):"), " Share of samples whose neighbours' batch mix differs from the overall mix (criterion: \u2265 0.25)"),
          tags$li(strong("Silhouette:"), " How tightly samples cluster by this variable (criterion: \u2265 0.05)"),
          tags$li(strong("Combined Score:"), " 0.4 PVCA + 0.4 kBET + 0.2 Silhouette, for ranking; a variable is flagged when at least two criteria are met")
        )
      ),
      
      HTML(correction_html),
      
      if (!is.null(correction_assessment)) {
        p(em("View the before/after PCA and UMAP plots below to visually assess the correction."),
          style = "font-size: 0.85em; color: #666; margin: 10px 0 0 0;")
      }
    )
