    withProgress(message = 'Loading TCGA tools...', value = 0, {
      incProgress(0.3, detail = "Loading TCGA packages")
      load_tcga_packages()
      
      incProgress(0.6, detail = "Loading survival analysis")
      load_survival_packages()
      
      incProgress(1, detail = "Ready!")
    })
    
    shinyjs::enable("run_tcga_enrichment")
    shinyjs::html("run_tcga_enrichment", "Run Analysis")
  })
  
  
