             # Find and reuse your PPI conditionalPanel UI
             find_ui_element(create_complete_compact_network_ui(), "ppi")
           }
    )
  })
  
  chembl_cache <- reactiveValues(
    # Raw API results cache: gene_symbol -> list(target_data, activity_data, timestamp)
    raw_data = list(),
    # Cache statistics
    stats = list(
      hits = 0,
      misses = 0,
      api_calls_saved = 0
    ),
    # Settings
    max_age_hours = 24,
    max_entries = 500
  )
  
  # Standalone WGCNA
  rv_wgcna_standalone <- reactiveValues(
    raw_counts = NULL,
    analysis_running = FALSE,
    results = NULL,
    trait_data = NULL,
    trait_configured = FALSE
  )
  
  # Standalone PPI
  rv_ppi_standalone <- reactiveValues(
    gene_list = NULL,
    analysis_running = FALSE,
    results = NULL
  )
  
  # Standalone GRN
  rv_grn_standalone <- reactiveValues(
    data = NULL,
    gene_list = NULL,
    analysis_running = FALSE,
    results = NULL
  )
  
  tcga_rv <- reactiveValues(
    results = NULL,
    deg_data = NULL,
    counts_normalized = NULL,
    coldata = NULL,
    analysis_complete = FALSE,
    pathway_results = NULL,
    pathway_complete = FALSE,
    volcano_generated = FALSE,
    heatmap_generated = FALSE
  )
  
  # ==============================================================================
  # PART 1: WGCNA STANDALONE - SERVER LOGIC
  # ============================================================================
  
  # Reactive values for WGCNA standalone with optimization
  wgcna_standalone_rv <- reactiveValues(
    counts_data = NULL,
    metadata = NULL,
    wgcna_results = NULL,
    results_ready = FALSE,
    optimization_results = NULL,
    enrichment_results = NULL,
    data_loaded = FALSE
  )
  
  # Load WGCNA standalone count matrix
  observeEvent(input$wgcna_standalone_counts, {
    req(input$wgcna_standalone_counts)
    
    tryCatch({
      file_path <- input$wgcna_standalone_counts$datapath
      file_ext <- tools::file_ext(input$wgcna_standalone_counts$name)
      
      if (file_ext %in% c("xlsx", "xls")) {
        counts_df <- read.xlsx(file_path, sheet = 1, rowNames = TRUE)
      } else {
        counts_df <- read.table(file_path, header = TRUE, row.names = 1, 
                                sep = ifelse(file_ext == "csv", ",", "\t"),
                                stringsAsFactors = FALSE, check.names = FALSE)
      }
      
      # Convert to numeric matrix
      counts_matrix <- as.matrix(counts_df)
      mode(counts_matrix) <- "numeric"
      
      wgcna_standalone_rv$counts_data <- counts_matrix
      wgcna_standalone_rv$data_loaded <- TRUE
      
      showNotification("Count matrix loaded successfully!", type = "message")
      
      # If auto-optimization is enabled, calculate optimal parameters
      if (input$wgcna_standalone_auto_optimize %||% TRUE) {
        tryCatch({
          # Calculate optimal gene count
          opt_analysis <- calculate_optimal_gene_count(counts_matrix)
          
          # Calculate optimal module size based on gene count
          optimal_genes <- opt_analysis$optimal_count
          optimal_module_size <- max(20, min(50, round(optimal_genes / 50)))
          
          # Calculate optimal merge threshold based on sample size
          n_samples <- ncol(counts_matrix)
          if (n_samples < 15) {
            optimal_merge <- 0.30  # More lenient for small samples
          } else if (n_samples < 30) {
            optimal_merge <- 0.25  # Standard
          } else {
            optimal_merge <- 0.20  # Stricter for large samples
          }
          
          # Store optimization results
          wgcna_standalone_rv$optimization_results <- list(
            optimal_gene_count = optimal_genes,
            optimal_module_size = optimal_module_size,
            optimal_merge_threshold = optimal_merge,
            constraints = opt_analysis$constraints,
            limiting_factor = opt_analysis$limiting_factor,
            n_samples = n_samples,
            n_genes = nrow(counts_matrix)
          )
          
          # Update UI with optimal values
          updateNumericInput(session, "wgcna_standalone_max_genes", 
                             value = optimal_genes)
          updateNumericInput(session, "wgcna_standalone_min_module_size",
                             value = optimal_module_size)
          updateNumericInput(session, "wgcna_standalone_merge_threshold",
                             value = optimal_merge)
          
          showNotification(
            paste0("🤖 Auto-optimization complete! Optimal settings applied: ",
                   optimal_genes, " genes, module size ", optimal_module_size),
            type = "message",
            duration = 5
          )
          
        }, error = function(e) {
          showNotification(
            paste("Auto-optimization failed:", e$message, "- Using default values"),
            type = "warning"
          )
        })
      }
      
    }, error = function(e) {
      showNotification(paste("Error loading count matrix:", e$message), type = "error")
      wgcna_standalone_rv$data_loaded <- FALSE
    })
  })
  
  # Load WGCNA standalone metadata
  observeEvent(input$wgcna_standalone_metadata, {
    req(input$wgcna_standalone_metadata)
    
    tryCatch({
      file_path <- input$wgcna_standalone_metadata$datapath
      file_ext <- tools::file_ext(input$wgcna_standalone_metadata$name)
      
      if (file_ext %in% c("xlsx", "xls")) {
        metadata_df <- read.xlsx(file_path, sheet = 1, rowNames = TRUE)
      } else {
        metadata_df <- read.table(file_path, header = TRUE, row.names = 1,
                                  sep = ifelse(file_ext == "csv", ",", "\t"),
                                  stringsAsFactors = FALSE, check.names = FALSE)
      }
      
      wgcna_standalone_rv$metadata <- metadata_df
      
      # Show modal for column selection
      showModal(modalDialog(
        title = "Select Metadata Columns for WGCNA",
        size = "l",
        easyClose = FALSE,
        
        tags$div(
          style = "padding: 10px;",
          tags$h4("Configure Trait Columns", style = "color: #2c3e50; margin-bottom: 15px;"),
          tags$p("Select which columns to use for module-trait correlation analysis."),
          tags$hr(),
          
          # Group/Condition Column
          tags$div(
            style = "margin-bottom: 20px; padding: 15px; background: #f8f9fa; border-radius: 5px;",
            tags$strong("Group/Condition Column:", style = "color: #495057;"),
            tags$p("Select the column that defines experimental groups (e.g., Control vs Treatment)", 
                   style = "font-size: 0.9em; color: #6c757d; margin: 5px 0;"),
            selectInput("wgcna_metadata_group_col",
                        NULL,
                        choices = colnames(metadata_df),
                        selected = colnames(metadata_df)[1])
          ),
          
          # Trait Columns
          tags$div(
            style = "margin-bottom: 20px; padding: 15px; background: #e7f3ff; border-radius: 5px;",
            tags$strong("Trait Columns:", style = "color: #495057;"),
            tags$p("Select additional columns for correlation analysis (e.g., age, weight, scores)", 
                   style = "font-size: 0.9em; color: #6c757d; margin: 5px 0;"),
            checkboxGroupInput("wgcna_metadata_trait_cols",
                               NULL,
                               choices = colnames(metadata_df),
                               selected = NULL)
          ),
          
          # Preview
          tags$div(
            style = "margin-top: 15px;",
            tags$strong("Metadata Preview:"),
            DT::dataTableOutput("wgcna_metadata_preview_modal")
          )
        ),
        
        footer = tagList(
          modalButton("Cancel"),
          actionButton("wgcna_metadata_confirm", "Confirm Selection", 
                       class = "btn-primary")
        )
      ))
      
      # Render metadata preview in modal
      output$wgcna_metadata_preview_modal <- DT::renderDataTable({
        DT::datatable(
          head(metadata_df, 10),
          options = list(
            pageLength = 5,
            scrollX = TRUE,
            dom = 't'
          ),
          rownames = TRUE
        )
      })
      
      showNotification("Metadata loaded successfully!", type = "message")
    }, error = function(e) {
      showNotification(paste("Error loading metadata:", e$message), type = "error")
    })
  })
  
  # Confirm metadata column selection
  observeEvent(input$wgcna_metadata_confirm, {
    req(input$wgcna_metadata_group_col)
    
    # Store selected columns
    wgcna_standalone_rv$metadata_group_col <- input$wgcna_metadata_group_col
    wgcna_standalone_rv$metadata_trait_cols <- input$wgcna_metadata_trait_cols
    
    # Prepare metadata with selected columns
    metadata_df <- wgcna_standalone_rv$metadata
    
    # Create processed metadata
    selected_cols <- c(input$wgcna_metadata_group_col, input$wgcna_metadata_trait_cols)
    selected_cols <- unique(selected_cols)
    
    processed_metadata <- metadata_df[, selected_cols, drop = FALSE]
    wgcna_standalone_rv$processed_metadata <- processed_metadata
    
    removeModal()
    
    showNotification(
      paste("Metadata configured:", length(selected_cols), "columns selected"),
      type = "message"
    )
  })
  
  # Executive Summary
  output$wgcna_standalone_executive_summary <- renderUI({
    req(wgcna_standalone_rv$wgcna_results)
    
    results <- wgcna_standalone_rv$wgcna_results
    
    # Safely get module colors
    module_colors <- results$moduleColors
    if (is.null(module_colors) || length(module_colors) == 0) {
      return(p("Analysis results not available", style = "color: white;"))
    }
    
    # Count modules (excluding grey)
    unique_modules <- unique(as.character(module_colors))
    unique_modules <- unique_modules[unique_modules != "grey"]
    n_modules <- length(unique_modules)
    
    # Get gene count
    n_genes <- length(module_colors)
    
    # Get largest module
    module_table <- table(as.character(module_colors))
    module_table <- module_table[names(module_table) != "grey"]
    
    if (length(module_table) > 0) {
      largest_module <- names(which.max(module_table))
      largest_size <- max(module_table)
    } else {
      largest_module <- "N/A"
      largest_size <- 0
    }
    
    # Quality score - handle different possible names
    quality <- results$quality_score %||% 
      results$scale_free_r2 %||% 
      results$soft_power_diagnostics$fitIndices$SFT.R.sq[results$softPower] %||%
      0.8
    
    if (is.null(quality) || is.na(quality)) quality <- 0.8
    
    div(
      p(style = "font-size: 1.1em; line-height: 1.6; margin: 0;",
        "Your WGCNA analysis identified ", strong(n_modules), " co-expression modules from ",
        strong(format(n_genes, big.mark = ",")), " genes. ",
        "The network achieved a scale-free topology fit of ", 
        strong(paste0("R", "\u00B2", " = ", round(quality, 2))), ". ",
        if (largest_module != "N/A") {
          paste0("The ", strong(largest_module), " module is the largest with ", 
                 strong(largest_size), " genes.")
        } else {
          ""
        }
      )
    )
  })
  
  # Top Module Name
  output$wgcna_standalone_top_module_name <- renderText({
    req(wgcna_standalone_rv$wgcna_results)
    
    module_colors <- wgcna_standalone_rv$wgcna_results$moduleColors
    if (is.null(module_colors) || length(module_colors) == 0) return("N/A")
    
    module_table <- table(as.character(module_colors))
    module_table <- module_table[names(module_table) != "grey"]
    
    if (length(module_table) > 0) {
      largest <- names(which.max(module_table))
      paste0(tools::toTitleCase(largest), " (", max(module_table), " genes)")
    } else {
      "N/A"
    }
  })
  
  # Key Findings Metrics
  output$wgcna_standalone_kf_modules <- renderText({
    req(wgcna_standalone_rv$wgcna_results)
    
    module_colors <- wgcna_standalone_rv$wgcna_results$moduleColors
    if (is.null(module_colors)) return("0 modules")
    
