    unique_modules <- unique_modules[unique_modules != "grey"]
    n_modules <- length(unique_modules)
    
    paste0(n_modules, " modules")
  })
  
  output$wgcna_standalone_kf_modules_detail <- renderText({
    req(wgcna_standalone_rv$wgcna_results)
    
    module_colors <- wgcna_standalone_rv$wgcna_results$moduleColors
    if (is.null(module_colors)) return("No modules found")
    
    module_table <- table(as.character(module_colors))
    module_table <- module_table[names(module_table) != "grey"]
    
    if (length(module_table) > 0) {
      paste0("Sizes: ", min(module_table), "-", max(module_table), " genes")
    } else {
      "No modules found"
    }
  })
  
  output$wgcna_standalone_kf_hubs <- renderText({
    req(wgcna_standalone_rv$wgcna_results)
    
    hub_genes <- wgcna_standalone_rv$wgcna_results$hub_genes
    
    if (!is.null(hub_genes) && is.data.frame(hub_genes) && nrow(hub_genes) > 0) {
      paste0(nrow(hub_genes), " hubs")
    } else {
      "N/A"
    }
  })
  
  output$wgcna_standalone_kf_hubs_detail <- renderText({
    req(wgcna_standalone_rv$wgcna_results)
    
    hub_genes <- wgcna_standalone_rv$wgcna_results$hub_genes
    
    if (!is.null(hub_genes) && is.data.frame(hub_genes) && nrow(hub_genes) > 0) {
      # Find top hub
      top_hub <- if ("gene" %in% colnames(hub_genes)) {
        hub_genes$gene[1]
      } else if ("Gene" %in% colnames(hub_genes)) {
        hub_genes$Gene[1]
      } else {
        rownames(hub_genes)[1]
      }
      paste0("Top: ", top_hub)
    } else {
      "Per module"
    }
  })
  
  output$wgcna_standalone_kf_quality <- renderText({
    req(wgcna_standalone_rv$wgcna_results)
    
    results <- wgcna_standalone_rv$wgcna_results
    
    # Try multiple sources for quality score
    quality <- NULL
    
    # Try soft_power_diagnostics first
    if (!is.null(results$soft_power_diagnostics) && 
        !is.null(results$soft_power_diagnostics$fitIndices)) {
      
      fit_indices <- results$soft_power_diagnostics$fitIndices
      power_idx <- which(fit_indices$Power == results$softPower)
      
      if (length(power_idx) > 0 && "SFT.R.sq" %in% colnames(fit_indices)) {
        quality <- fit_indices$SFT.R.sq[power_idx[1]]
      }
    }
    
    # Fallback to stored quality_score
    if (is.null(quality) || is.na(quality)) {
      quality <- results$quality_score %||% results$scale_free_r2 %||% 0.8
    }
    
    if (is.null(quality) || is.na(quality)) quality <- 0.8
    
    # Return without Unicode issues
    paste0("R2 = ", round(quality, 2))
  })
  
  output$wgcna_standalone_kf_quality_detail <- renderText({
    req(wgcna_standalone_rv$wgcna_results)
    
    results <- wgcna_standalone_rv$wgcna_results
    
    # Get quality score
    quality <- NULL
    if (!is.null(results$soft_power_diagnostics) && 
        !is.null(results$soft_power_diagnostics$fitIndices)) {
      fit_indices <- results$soft_power_diagnostics$fitIndices
      power_idx <- which(fit_indices$Power == results$softPower)
      if (length(power_idx) > 0 && "SFT.R.sq" %in% colnames(fit_indices)) {
        quality <- fit_indices$SFT.R.sq[power_idx[1]]
      }
    }
    
    if (is.null(quality) || is.na(quality)) {
      quality <- results$quality_score %||% results$scale_free_r2 %||% 0.8
    }
    
    if (is.null(quality) || is.na(quality)) quality <- 0.8
    
    if (quality >= 0.8) {
      "Excellent fit"
    } else if (quality >= 0.6) {
      "Good fit"
    } else {
      "Moderate fit"
    }
  })
  
  output$wgcna_standalone_kf_genes <- renderText({
    req(wgcna_standalone_rv$wgcna_results)
    
    module_colors <- wgcna_standalone_rv$wgcna_results$moduleColors
    n_genes <- if (!is.null(module_colors)) length(module_colors) else 0
    
    format(n_genes, big.mark = ",")
  })
  
