      return(p("No modules found", style = "color: #7f8c8d;"))
    }
    
    # Get module sizes (excluding grey)
    module_table <- table(as.character(module_colors))
    module_table <- module_table[names(module_table) != "grey"]
    module_table <- sort(module_table, decreasing = TRUE)
    
    if (length(module_table) == 0) {
      return(p("No modules found (all genes unassigned)", style = "color: #7f8c8d;"))
    }
    
    top5_modules <- head(names(module_table), 5)
    
    cards <- lapply(seq_along(top5_modules), function(i) {
      module <- top5_modules[i]
      size <- module_table[module]
      
      # Get hub gene for this module
      hub_gene <- "N/A"
      if (!is.null(hub_genes) && is.data.frame(hub_genes)) {
        # Check for module column
        module_col <- if ("module" %in% colnames(hub_genes)) "module" 
        else if ("Module" %in% colnames(hub_genes)) "Module"
        else NULL
        
        gene_col <- if ("gene" %in% colnames(hub_genes)) "gene"
        else if ("Gene" %in% colnames(hub_genes)) "Gene"
        else NULL
        
        if (!is.null(module_col) && !is.null(gene_col)) {
          module_hubs <- hub_genes[as.character(hub_genes[[module_col]]) == module, ]
          if (nrow(module_hubs) > 0) {
            hub_gene <- module_hubs[[gene_col]][1]
          }
        }
      }
      
      # Module color for display - handle named colors
      display_color <- tryCatch({
        col2rgb(module)
        module  # It's a valid color name
      }, error = function(e) {
        "#808080"  # Default grey
      })
      
      div(style = paste0("display: flex; align-items: center; padding: 12px; margin-bottom: 10px; ",
                         "background: #f8f9fa; border-radius: 8px; border-left: 4px solid ", display_color, ";"),
