  # Top Trait Associations (if available)
  output$wgcna_standalone_top_trait_associations <- renderUI({
    req(wgcna_standalone_rv$wgcna_results)
    
    trait_cor <- wgcna_standalone_rv$wgcna_results$trait_correlation
    
    if (is.null(trait_cor)) {
      return(p("No trait correlations available", style = "color: #7f8c8d;"))
    }
    
    cor_matrix <- trait_cor$correlation
    pval_matrix <- trait_cor$pvalue
    
    if (is.null(cor_matrix) || is.null(pval_matrix)) {
      return(p("Trait correlation data not available", style = "color: #7f8c8d;"))
    }
    
    # Find significant associations
    sig_threshold <- 0.05
    sig_associations <- list()
    
    for (i in 1:nrow(cor_matrix)) {
      for (j in 1:ncol(cor_matrix)) {
        pval <- pval_matrix[i, j]
        if (!is.na(pval) && pval < sig_threshold) {
          sig_associations[[length(sig_associations) + 1]] <- list(
            module = rownames(cor_matrix)[i],
            trait = colnames(cor_matrix)[j],
            cor = cor_matrix[i, j],
            pval = pval
          )
        }
      }
    }
    
    if (length(sig_associations) == 0) {
      return(p("No significant module-trait associations found (p < 0.05)", style = "color: #7f8c8d;"))
    }
    
    # Sort by absolute correlation
    sig_associations <- sig_associations[order(-abs(sapply(sig_associations, function(x) x$cor)))]
    top5 <- head(sig_associations, 5)
    
    items <- lapply(top5, function(assoc) {
      cor_color <- if (assoc$cor > 0) "#27ae60" else "#e74c3c"
      cor_text <- if (assoc$cor > 0) "+" else ""
      
      # Clean module name (remove "ME" prefix if present)
      module_name <- gsub("^ME", "", assoc$module)
      
      # Get display color
      display_color <- tryCatch({
        col2rgb(module_name)
        module_name
      }, error = function(e) {
        "#808080"
      })
      
      div(style = "display: flex; align-items: center; padding: 8px; margin-bottom: 6px; 
                background: #f8f9fa; border-radius: 6px;",
          div(style = paste0("width: 20px; height: 20px; background: ", display_color, 
                             "; border-radius: 50%; margin-right: 10px;")
          ),
          div(style = "flex: 1;",
              strong(tools::toTitleCase(module_name)),
              span(" - ", style = "color: #666;"),
              span(assoc$trait)
          ),
          div(style = "text-align: right;",
              span(paste0(cor_text, round(assoc$cor, 2)), 
                   style = paste0("font-weight: bold; color: ", cor_color, ";"))
          )
      )
    })
    
    do.call(tagList, items)
  })
  
