  # Run WGCNA standalone analysis
  observeEvent(input$run_wgcna_standalone, {
    req(wgcna_standalone_rv$counts_data)

    # Disable button and show spinner
    shinyjs::disable("run_wgcna_standalone")
    shinyjs::runjs("
      var btn = document.getElementById('run_wgcna_standalone');
      if (btn) {
        btn.dataset.originalHtml = btn.innerHTML;
        btn.innerHTML = '<i class=\"fa fa-spinner fa-spin\" style=\"margin-right: 6px;\"></i> Running WGCNA...';
        btn.classList.add('btn-disabled-running');
      }
    ")
    on.exit({
      shinyjs::enable("run_wgcna_standalone")
      shinyjs::runjs("
        var btn = document.getElementById('run_wgcna_standalone');
        if (btn && btn.dataset.originalHtml) {
          btn.innerHTML = btn.dataset.originalHtml;
          btn.classList.remove('btn-disabled-running');
        }
      ")
    }, add = TRUE)

    # Reset results
    wgcna_standalone_rv$results_ready <- FALSE
    wgcna_standalone_rv$wgcna_results <- NULL

    # Show progress
    progress <- Progress$new(session)
    progress$set(message = "Running WGCNA Analysis", value = 0)
    on.exit(progress$close(), add = TRUE)
    
    tryCatch({
      counts <- wgcna_standalone_rv$counts_data
      organism <- input$wgcna_standalone_organism
      max_genes <- input$wgcna_standalone_max_genes
      min_module_size <- input$wgcna_standalone_min_module_size
      merge_threshold <- input$wgcna_standalone_merge_threshold
      
      progress$set(value = 0.1, detail = "Filtering and normalizing data...")
      
      # Filter low-expressed genes
      keep_genes <- rowSums(counts > 1) >= ncol(counts) * 0.2
      counts_filtered <- counts[keep_genes, ]
      
      # Detect if data is already normalized/transformed
      # Raw counts typically have high max values (>1000) and are integers
      max_val <- max(counts_filtered, na.rm = TRUE)
      is_integer_data <- all(counts_filtered == floor(counts_filtered), na.rm = TRUE)
      
      print(paste("📊 Data detection - Max value:", round(max_val, 2), 
                  "| Integer data:", is_integer_data))
      
      if (max_val > 100 && is_integer_data) {
        # Looks like raw counts - normalize with DESeq2
        print("📊 Detected raw counts - applying DESeq2 normalization")
        
        # Ensure integer matrix for DESeq2
        counts_int <- round(counts_filtered)
        storage.mode(counts_int) <- "integer"
        
        tryCatch({
          dds <- DESeq2::DESeqDataSetFromMatrix(
            countData = counts_int,
            colData = data.frame(sample = colnames(counts_int)),
            design = ~ 1
          )
          dds <- DESeq2::estimateSizeFactors(dds)
          norm_counts <- DESeq2::counts(dds, normalized = TRUE)
          
          # Log transform
          expr_data <- log2(norm_counts + 1)
        }, error = function(e) {
          print(paste("⚠️ DESeq2 normalization failed:", e$message))
          print("📊 Falling back to simple log2 transformation")
          # Fallback: simple log transformation
          expr_data <<- log2(counts_filtered + 1)
        })
        
      } else if (max_val > 20) {
        # Likely normalized counts (TPM, FPKM, CPM) - just log transform
        print("📊 Detected normalized counts (TPM/FPKM/CPM) - applying log2 transformation")
        expr_data <- log2(counts_filtered + 1)
        
      } else {
        # Already log-transformed data
        print("📊 Detected log-transformed data - using as-is")
        expr_data <- as.matrix(counts_filtered)
      }
      
      print(paste("📊 Expression data range after processing:", 
                  round(min(expr_data, na.rm = TRUE), 2), "to", 
                  round(max(expr_data, na.rm = TRUE), 2)))
      
      # Select most variable genes
      gene_vars <- apply(expr_data, 1, var)
      top_genes <- names(sort(gene_vars, decreasing = TRUE)[1:min(max_genes, nrow(expr_data))])
      expr_filtered <- expr_data[top_genes, ]
      
      # Transpose for WGCNA (samples as rows)
      datExpr <- t(expr_filtered)
      
      progress$set(value = 0.3, detail = "Checking data quality...")
      
      # Check for good samples and genes
      # WGCNA / dynamicTreeCut functions below are called unqualified: attach them here
      suppressPackageStartupMessages({ library(WGCNA); library(dynamicTreeCut) })
      gsg <- goodSamplesGenes(datExpr, verbose = 0)
      if (!gsg$allOK) {
        if (sum(!gsg$goodGenes) > 0) {
          datExpr <- datExpr[, gsg$goodGenes]
        }
        if (sum(!gsg$goodSamples) > 0) {
          datExpr <- datExpr[gsg$goodSamples, ]
        }
      }
      
      progress$set(value = 0.4, detail = "Choosing soft threshold...")
      
      # Choose soft threshold
      # powers <- c(seq(1, 10, by = 1), seq(12, 20, by = 2))
      # sft <- pickSoftThreshold(datExpr, powerVector = powers, verbose = 0, 
      #                          networkType = "signed", corFnc = "cor")
      # 
      # softPower <- ifelse(!is.na(sft$powerEstimate), sft$powerEstimate, 6)
      
      softPowerAnalysis <- pickSoftThreshold(
        datExpr,
        powerVector = seq(1, 20, by = 1),
        networkType = "signed",
        verbose = 5
      )
      
      softPower <- softPowerAnalysis$powerEstimate
      
      if (is.na(softPower)) {
        softPower <- 6  # Default fallback
      }
      
      print(paste("✅ Soft power selected:", softPower))
      
      # Store the full analysis (not just the power value)
      soft_power_diagnostics <- list(
        power = softPower,
        fitIndices = softPowerAnalysis$fitIndices,
        powerEstimate = softPowerAnalysis$powerEstimate
      )
      
      progress$set(value = 0.5, detail = "Calculating adjacency matrix...")
      
      # Calculate adjacency
      adjacency <- adjacency(datExpr, power = softPower, type = "signed")
      
      progress$set(value = 0.6, detail = "Creating topological overlap matrix...")
      
      # TOM
      TOM <- TOMsimilarity(adjacency, TOMType = "signed")
      dissTOM <- 1 - TOM
      
      progress$set(value = 0.7, detail = "Detecting modules...")
      
      # Hierarchical clustering
      geneTree <- hclust(as.dist(dissTOM), method = "average")
      
      # Module identification
      dynamicMods <- cutreeDynamic(dendro = geneTree, distM = dissTOM,
                                   deepSplit = 2, pamRespectsDendro = FALSE,
                                   minClusterSize = min_module_size)
      
      dynamicColors <- labels2colors(dynamicMods)
      
      progress$set(value = 0.8, detail = "Merging similar modules...")
      
      # Merge close modules
      MEList <- moduleEigengenes(datExpr, colors = dynamicColors)
      MEs <- MEList$eigengenes
      MEDiss <- 1 - cor(MEs)
      METree <- hclust(as.dist(MEDiss), method = "average")
      
      merge <- mergeCloseModules(datExpr, dynamicColors, cutHeight = merge_threshold)
      mergedColors <- merge$colors
      mergedMEs <- merge$newMEs
      
      progress$set(value = 0.9, detail = "Calculating module membership...")
      
      # Module membership
      moduleColors <- mergedColors
      MEs <- mergedMEs
      
      if (is.null(names(moduleColors))) {
        names(moduleColors) <- colnames(datExpr)
      }
      
      print(paste("✅ moduleColors length:", length(moduleColors)))
      print(paste("✅ Sample genes:", paste(head(names(moduleColors), 5), collapse = ", ")))
      
      # Calculate connectivity
      connectivity <- intramodularConnectivity(adjacency, moduleColors)
      
      # Get hub genes for each module
      module_names <- unique(moduleColors)
      hub_genes_list <- list()
      
      for (mod in module_names) {
        if (mod == "grey") next  # Skip unassigned genes
        
        in_module <- which(moduleColors == mod)
        module_connectivity <- connectivity[in_module, ]
        
        # Top 10 hub genes per module
        top_hubs <- head(module_connectivity[order(-module_connectivity$kWithin), ], 10)
        
        hub_genes_list[[mod]] <- data.frame(
          Gene = rownames(top_hubs),
          Module = mod,
          kWithin = top_hubs$kWithin,
          kOut = top_hubs$kOut,
          kDiff = top_hubs$kDiff,
          stringsAsFactors = FALSE
        )
      }
      
      hub_genes_df <- do.call(rbind, hub_genes_list)
      rownames(hub_genes_df) <- NULL
      
      # Perform functional enrichment if enabled
      enrichment_results <- list() 
      if (input$wgcna_standalone_enable_enrichment) {
        progress$set(value = 0.95, detail = "Performing functional enrichment...")
        
        tryCatch({
          print("🧬 Starting enrichment analysis...")
          
          # Prepare modules for enrichment
          # module_list <- split(names(moduleColors), moduleColors)
          gene_names <- colnames(datExpr)  # These are the actual gene names
          module_assignments <- as.character(moduleColors)  # Remove any factor levels
          names(module_assignments) <- gene_names  # Assign names
          
          # Create module list by splitting gene names by their color
          module_list <- split(gene_names, module_assignments)
          
          # Remove grey module (unassigned genes)
          if ("grey" %in% names(module_list)) {
            module_list$grey <- NULL
          }
          
          print(paste("📊 Modules to enrich:", paste(names(module_list), collapse = ", ")))
          
          # Get selected genes (those actually used in analysis)
          selected_genes <- colnames(datExpr)
          
          # FIX: Prepare hub genes in correct format
          # Option 1: If hub_genes is already a data frame with gene names
          hub_genes_for_enrichment <- if (is.data.frame(hub_genes_df)) {
            # Extract just the gene names if it's a data frame
            if ("gene" %in% colnames(hub_genes_df)) {
              hub_genes_df$gene
            } else if ("Gene" %in% colnames(hub_genes_df)) {
              hub_genes_df$Gene
            } else {
              rownames(hub_genes_df)
            }
          } else if (is.vector(hub_genes_df)) {
            hub_genes_df
          } else {
            # Fallback: extract from connectivity
            names(head(sort(connectivity$kWithin, decreasing = TRUE), 100))
          }
          
          print(paste("🎯 Hub genes prepared:", length(hub_genes_for_enrichment), "genes"))
          
          # Perform enrichment
          enrichment_results <- perform_module_enrichment_fixed_v2(
            modules = module_list,
            selected_genes = selected_genes,
            hub_genes = hub_genes_for_enrichment,  # FIX: Pass vector, not data frame
            organism = input$wgcna_standalone_organism
          )
          
          print(paste("✅ Enrichment completed for", length(enrichment_results), "modules"))
          # DEBUG: Check enrichment structure
          print("🔍 DEBUG: Enrichment results structure:")
          print(paste("  - Type:", class(enrichment_results)))
          print(paste("  - Length:", length(enrichment_results)))
          print(paste("  - Is list:", is.list(enrichment_results)))
          print(paste("  - Names:", paste(names(enrichment_results), collapse = ", ")))
          
        }, error = function(e) {
          print(paste("⚠️ Enrichment failed:", e$message))
          print("Full error:")
          print(e)
          enrichment_results <- list()
        })
      }
      
      # Module-trait correlation (if metadata provided)
      trait_cor <- NULL
      if (input$wgcna_standalone_enable_trait && !is.null(wgcna_standalone_rv$metadata)) {
        print("🔍 DEBUG: Starting trait correlation analysis...")
        
        tryCatch({
          metadata <- wgcna_standalone_rv$metadata
          
          # Match samples
          common_samples <- intersect(rownames(datExpr), rownames(metadata))
          print(paste("  - Common samples:", length(common_samples)))
          
          if (length(common_samples) > 0) {
            datExpr_matched <- datExpr[common_samples, ]
            metadata_matched <- metadata[common_samples, , drop = FALSE]
            
            print(paste("  - datExpr_matched dim:", nrow(datExpr_matched), "x", ncol(datExpr_matched)))
            print(paste("  - moduleColors length:", length(moduleColors)))
            
            # FIX: Ensure moduleColors aligns with datExpr genes
            # moduleColors should be a vector with length = ncol(datExpr)
            if (length(moduleColors) != ncol(datExpr)) {
              print("  ⚠️ Warning: moduleColors length doesn't match datExpr columns")
              print(paste("    moduleColors:", length(moduleColors), "vs datExpr cols:", ncol(datExpr)))
            }
            
            # Subset moduleColors to match the genes in datExpr_matched
            # (they should have the same genes, just different samples)
            moduleColors_matched <- moduleColors  # Should already match since we only subset rows
            
            # Recalculate MEs for matched samples
            # CRITICAL: moduleColors must be a simple character vector, same length as ncol(datExpr_matched)
            print("  - Calculating module eigengenes for matched samples...")
            MEList_matched <- moduleEigengenes(datExpr_matched, colors = as.character(moduleColors_matched))
            MEs_matched <- MEList_matched$eigengenes
            
            print(paste("  - MEs calculated:", ncol(MEs_matched), "modules"))
            
            # Convert metadata to numeric if needed
            print("  - Converting metadata to numeric traits...")
            numeric_traits_list <- list()
            
            for (col_name in colnames(metadata_matched)) {
              col_data <- metadata_matched[[col_name]]
              
              if (is.numeric(col_data)) {
                numeric_traits_list[[col_name]] <- col_data
              } else if (is.factor(col_data) || is.character(col_data)) {
                # Convert to numeric if binary
                unique_vals <- unique(col_data)
                if (length(unique_vals) == 2) {
                  numeric_traits_list[[col_name]] <- as.numeric(as.factor(col_data)) - 1
                  print(paste("    Converted binary trait:", col_name))
                } else if (length(unique_vals) <= 5) {
                  # Convert categorical with few levels
                  numeric_traits_list[[col_name]] <- as.numeric(as.factor(col_data))
                  print(paste("    Converted categorical trait:", col_name))
                }
              }
            }
            
            print(paste("  - Found", length(numeric_traits_list), "convertible traits"))
            
            if (length(numeric_traits_list) > 0) {
              # Create numeric traits matrix with proper dimensions
              numeric_traits <- do.call(cbind, numeric_traits_list)
              rownames(numeric_traits) <- rownames(metadata_matched)
              colnames(numeric_traits) <- names(numeric_traits_list)
              
              print(paste("  - numeric_traits dimensions:", nrow(numeric_traits), "x", ncol(numeric_traits)))
              print(paste("  - MEs_matched dimensions:", nrow(MEs_matched), "x", ncol(MEs_matched)))
              
              # Verify dimensions match
              if (nrow(MEs_matched) == nrow(numeric_traits)) {
                # Calculate correlations
                moduleTraitCor <- cor(MEs_matched, numeric_traits, use = "p")
                moduleTraitPvalue <- corPvalueStudent(moduleTraitCor, nrow(datExpr_matched))
                
                trait_cor <- list(
                  correlation = moduleTraitCor,
                  pvalue = moduleTraitPvalue
                )
                
                print("  ✅ Trait correlations calculated successfully")
                print("\n📊 MODULE-TRAIT CORRELATION MATRIX:")
                print("====================================")
                print("Correlation values:")
                print(round(moduleTraitCor, 3))
                print("\nP-values:")
                print(formatC(moduleTraitPvalue, format = "e", digits = 2))
                print("====================================\n")
              } else {
                print(paste("  ❌ Dimension mismatch: MEs has", nrow(MEs_matched), 
                            "rows but traits has", nrow(numeric_traits), "rows"))
              }
            } else {
              print("  ⚠️ No numeric traits found in metadata")
            }
          }
        }, error = function(e) {
          print(paste("  ❌ Error in trait correlation:", e$message))
          print("  Full error:")
          print(e)
          trait_cor <- NULL
        })
      }
      
      if (!is.null(trait_cor)) {
        print("\n📊 MODULE-TRAIT CORRELATION MATRIX:")
        print("====================================")
        print("Correlation values:")
        print(round(trait_cor$correlation, 3))
        print("\nP-values:")
        print(formatC(trait_cor$pvalue, format = "e", digits = 2))
        print("====================================\n")
      }
      
      # Module summary
      print("🔍 DEBUG: Creating module summary...")
      print(paste("  - moduleColors class:", class(moduleColors)))
      print(paste("  - moduleColors length:", length(moduleColors)))
      
      # FIX: Ensure moduleColors is a simple vector for table()
      moduleColors_simple <- as.character(moduleColors)
      
      module_summary <- data.frame(
        Module = names(table(moduleColors_simple)),
        Size = as.numeric(table(moduleColors_simple)),
        stringsAsFactors = FALSE
      )
      module_summary <- module_summary[order(-module_summary$Size), ]
      
      print(paste("  ✅ Module summary created:", nrow(module_summary), "modules"))
      
      # # Module summary
      # module_summary <- data.frame(
      #   Module = names(table(moduleColors)),
      #   Size = as.numeric(table(moduleColors)),
      #   stringsAsFactors = FALSE
      # )
      # module_summary <- module_summary[order(-module_summary$Size), ]
      
      print("🔍 DEBUG: About to store results")
      print(paste("  - enrichment_results is NULL:", is.null(enrichment_results)))
      print(paste("  - enrichment_results is list:", is.list(enrichment_results)))
      if (!is.null(enrichment_results)) {
        print(paste("  - enrichment_results length:", length(enrichment_results)))
      }
      
      progress$set(value = 1, detail = "Analysis complete!")
      
      # Store results
      wgcna_standalone_rv$wgcna_results <- list(
        datExpr = datExpr,
        moduleColors = moduleColors,
        MEs = MEs,
        geneTree = geneTree,
        adjacency = adjacency,
        TOM = TOM,
        connectivity = connectivity,
        hub_genes = hub_genes_df,
        module_summary = module_summary,
        trait_correlation = trait_cor,
        softPower = softPower,
        soft_power_diagnostics = soft_power_diagnostics,
        enrichment = if(is.null(enrichment_results) || length(enrichment_results) == 0) list() else enrichment_results
      )
      
      wgcna_standalone_rv$results_ready <- TRUE
      
      showNotification("WGCNA analysis completed successfully!", type = "message", duration = 5)
      
    }, error = function(e) {
      showNotification(paste("WGCNA analysis failed:", e$message), type = "error", duration = 10)
      wgcna_standalone_rv$results_ready <- FALSE
    })
  })
  
  # Output: Results available flag
  output$wgcna_standalone_results_available <- reactive({
    wgcna_standalone_rv$results_ready
  })
  outputOptions(output, "wgcna_standalone_results_available", suspendWhenHidden = FALSE)
  
