        text(0.5, 0.5, "No trait correlation data available", cex = 1.5)
        return()
      }
      
      moduleTraitCor <- trait_cor$correlation
      moduleTraitPvalue <- trait_cor$pvalue
      
      # Validate dimensions
      if (!is.matrix(moduleTraitCor) || nrow(moduleTraitCor) == 0 || ncol(moduleTraitCor) == 0) {
        plot.new()
        text(0.5, 0.5, "Invalid correlation matrix", cex = 1.5)
        return()
      }
      
      # Text matrix for heatmap (correlation + p-value)
      textMatrix <- paste(signif(moduleTraitCor, 2), "\n(",
                          signif(moduleTraitPvalue, 1), ")", sep = "")
      dim(textMatrix) <- dim(moduleTraitCor)
      
      # Plot heatmap using WGCNA's labeledHeatmap
      par(mar = c(8, 10, 3, 3))
      
      # Check if WGCNA labeledHeatmap is available
      if (!exists("labeledHeatmap", mode = "function")) {
        library(WGCNA)
      }
      
      labeledHeatmap(
        Matrix = moduleTraitCor,
        xLabels = colnames(moduleTraitCor),
        yLabels = rownames(moduleTraitCor),
        ySymbols = gsub("ME", "", rownames(moduleTraitCor)),
        colorLabels = FALSE,
        colors = blueWhiteRed(50),
        textMatrix = textMatrix,
        setStdMargins = FALSE,
        cex.text = 0.9,
        zlim = c(-1, 1),
        main = "Module-Trait Relationships"
      )
      
    }, error = function(e) {
      print(paste("❌ Error rendering trait heatmap:", e$message))
      plot.new()
      text(0.5, 0.5, paste("Error creating heatmap:\n", e$message), cex = 1)
    })
  })
  
