  # Output: Trait correlation table
  # Output: Trait correlation table with colored background
  output$wgcna_standalone_trait_table <- DT::renderDataTable({
    req(wgcna_standalone_rv$wgcna_results)
    req(wgcna_standalone_rv$wgcna_results$trait_correlation)
    
    trait_cor <- wgcna_standalone_rv$wgcna_results$trait_correlation
    moduleTraitCor <- trait_cor$correlation
    moduleTraitPvalue <- trait_cor$pvalue
    
    # Create a data frame
    trait_df <- data.frame(
      Module = rep(gsub("ME", "", rownames(moduleTraitCor)), ncol(moduleTraitCor)),
      Trait = rep(colnames(moduleTraitCor), each = nrow(moduleTraitCor)),
      Correlation = as.vector(moduleTraitCor),
      Pvalue = as.vector(moduleTraitPvalue),
      stringsAsFactors = FALSE
    )
    
    # Sort by significance
    trait_df <- trait_df[order(trait_df$Pvalue), ]
    
    # Round correlation values
    trait_df$Correlation_display <- round(trait_df$Correlation, 3)
    
    # Format p-values
    trait_df$Pvalue_display <- format(trait_df$Pvalue, scientific = TRUE, digits = 3)
    
    # Create display dataframe
    display_df <- data.frame(
      Module = trait_df$Module,
      Trait = trait_df$Trait,
      Correlation = trait_df$Correlation_display,
      Pvalue = trait_df$Pvalue_display,
      stringsAsFactors = FALSE
    )
    
    # Create color function for correlation values
    # Soft colors: light blue for negative, light red for positive
    color_correlation <- function(correlation) {
      sapply(correlation, function(x) {
        if (is.na(x)) return("white")
        # Normalize to 0-1 range
        normalized <- (x + 1) / 2  # -1 to 1 becomes 0 to 1
        
        if (x < 0) {
          # Negative correlation: light to medium blue
          intensity <- abs(x)
          rgb(0.7 - intensity * 0.5, 0.8 - intensity * 0.3, 1, alpha = 0.7)
        } else {
          # Positive correlation: light to medium red
          intensity <- x
          rgb(1, 0.8 - intensity * 0.5, 0.7 - intensity * 0.5, alpha = 0.7)
        }
      })
    }
    
    # Create DT with conditional formatting
    DT::datatable(
      display_df,
      options = list(
        pageLength = 20,
        scrollX = TRUE,
        columnDefs = list(
          list(className = 'dt-center', targets = c(2, 3))
        )
      ),
      rownames = FALSE,
      filter = "top"
    ) %>%
      DT::formatStyle(
        'Correlation',
        target = 'row',
        backgroundColor = DT::styleEqual(
          trait_df$Correlation_display,
          color_correlation(trait_df$Correlation)
        )
      ) %>%
      DT::formatStyle(
        'Pvalue',
        backgroundColor = DT::styleInterval(
          c(0.001, 0.01, 0.05),
          c('rgba(76, 175, 80, 0.3)',   # p < 0.001 - green
            'rgba(255, 235, 59, 0.3)',   # 0.001 < p < 0.01 - yellow
            'rgba(255, 152, 0, 0.3)',    # 0.01 < p < 0.05 - orange
            'rgba(255, 255, 255, 0.1)')  # p > 0.05 - white
        )
      )
  })
  
  # Total modules
  output$wgcna_standalone_total_modules <- renderText({
    req(wgcna_standalone_rv$wgcna_results)
    
    results <- wgcna_standalone_rv$wgcna_results
    # Count non-grey modules
    n_modules <- length(unique(results$moduleColors)) - 1  # -1 for grey
    as.character(n_modules)
  })
  
  # Soft power
  output$wgcna_standalone_soft_power <- renderText({
    req(wgcna_standalone_rv$wgcna_results)
    
    results <- wgcna_standalone_rv$wgcna_results
    as.character(results$softPower)
  })
  
  # Genes analyzed
  output$wgcna_standalone_genes_analyzed <- renderText({
    req(wgcna_standalone_rv$wgcna_results)
    
    results <- wgcna_standalone_rv$wgcna_results
    as.character(ncol(results$datExpr))
  })
  
  # Quality score (calculate based on multiple factors)
  output$wgcna_standalone_quality_score <- renderText({
    req(wgcna_standalone_rv$wgcna_results)
    
    results <- wgcna_standalone_rv$wgcna_results
    
    # Calculate quality score (0-10)
    score <- 10
    
    # Penalty for low soft power (< 4)
    if (results$softPower < 4) {
      score <- score - 2
    }
    
    # Penalty for too many/few modules
    n_modules <- length(unique(results$moduleColors)) - 1
    if (n_modules < 3) {
      score <- score - 2  # Too few modules
    } else if (n_modules > 30) {
      score <- score - 1  # Too many modules
    }
    
    # Bonus for having hub genes
    if (nrow(results$hub_genes) > 20) {
      score <- score + 0.5
    }
    
    # Ensure score is between 0-10
    score <- max(0, min(10, score))
    
    sprintf("%.1f/10", score)
  })
  
  # Soft power plot
  output$wgcna_standalone_soft_power_plot <- renderPlot({
    req(wgcna_standalone_rv$wgcna_results)
    
    results <- wgcna_standalone_rv$wgcna_results
    
    # If soft power diagnostics were saved, plot them
    if (!is.null(results$soft_power_diagnostics) && 
        !is.null(results$soft_power_diagnostics$fitIndices)) {
      
      fitIndices <- results$soft_power_diagnostics$fitIndices
      selected_power <- results$soft_power_diagnostics$power
      
      # Create diagnostic plots
      par(mfrow = c(1, 2), mar = c(5, 5, 3, 2))
      
      # Plot 1: Scale Free Topology Fit
      plot(fitIndices$Power, 
           -sign(fitIndices$slope) * fitIndices$SFT.R.sq,
           xlab = "Soft Threshold (power)",
           ylab = "Scale Free Topology Model Fit, signed R²",
           type = "n",
           main = "Scale independence")
      
      text(fitIndices$Power, 
           -sign(fitIndices$slope) * fitIndices$SFT.R.sq,
           labels = fitIndices$Power,
           cex = 0.9,
           col = ifelse(fitIndices$Power == selected_power, "red", "black"))
      
      # Add threshold line at R² = 0.8
      abline(h = 0.8, col = "red", lty = 2)
      
      # Plot 2: Mean Connectivity
      plot(fitIndices$Power, 
           fitIndices$mean.k.,
           xlab = "Soft Threshold (power)",
           ylab = "Mean Connectivity",
           type = "n",
           main = "Mean connectivity")
      
      text(fitIndices$Power, 
           fitIndices$mean.k.,
           labels = fitIndices$Power,
           cex = 0.9,
           col = ifelse(fitIndices$Power == selected_power, "red", "black"))
      
      # Add info text
      mtext(paste("Selected soft power:", selected_power), 
            side = 3, line = -2, outer = TRUE, col = "red", font = 2)
      
    } else {
      # Fallback: simple info plot
      par(mfrow = c(1, 1), mar = c(3, 3, 3, 2))
      plot(1, type = "n", xlim = c(0, 10), ylim = c(0, 10), 
           xlab = "", ylab = "", axes = FALSE, main = "Soft Power Analysis")
      text(5, 6, paste("Soft Power Used:", results$softPower), 
           cex = 1.8, font = 2, col = "#2c3e50")
      text(5, 4, "Scale-free topology achieved", 
           cex = 1.3, col = "darkgreen")
      text(5, 2, "Detailed analysis not saved", 
           cex = 1, col = "gray50", font = 3)
      box()
    }
  })
  
