  #ENRICHMENT
  output$wgcna_standalone_enrichment_plot <- renderPlot({
    req(wgcna_standalone_rv$wgcna_results)
    req(wgcna_standalone_rv$wgcna_results$enrichment)
    req(input$wgcna_standalone_enrichment_module)
    
    enrichment <- wgcna_standalone_rv$wgcna_results$enrichment
    selected_module <- input$wgcna_standalone_enrichment_module
    
    if (!selected_module %in% names(enrichment)) {
      return(ggplot() + 
               annotate("text", x = 1, y = 1, label = "No enrichment data for this module") +
               theme_void())
    }
    
    module_enrich <- enrichment[[selected_module]]
    
    if (is.null(module_enrich) || nrow(module_enrich) == 0) {
      return(ggplot() + 
               annotate("text", x = 1, y = 1, label = "No significant enrichment found") +
               theme_void())
    }
    
    # Filter by database if selected
    if (input$wgcna_standalone_enrichment_database != "all") {
      module_enrich <- module_enrich[module_enrich$Database == input$wgcna_standalone_enrichment_database, ]
    }
    
    if (nrow(module_enrich) == 0) {
      return(ggplot() + 
               annotate("text", x = 1, y = 1, label = "No terms for selected database") +
               theme_void())
    }
    
    # Take top N terms
    top_n <- input$wgcna_standalone_enrichment_top %||% 20
    module_enrich <- head(module_enrich, top_n)
    
    # FIX: Extract gene count from Overlap column (e.g., "5/100" -> 5)
    module_enrich$GeneCount <- sapply(module_enrich$Overlap, function(x) {
      if (is.na(x) || is.null(x) || x == "") return(5)
      # Extract the number before "/"
      count <- as.numeric(gsub("/.*", "", as.character(x)))
      if (is.na(count) || count == 0) return(5)
      return(count)
    })
    
    # Debug: Print gene counts to verify
    print(paste("🔍 Gene counts for", selected_module, "module:"))
    print(head(module_enrich[, c("Term", "Overlap", "GeneCount")], 10))
    
    # Create enrichment plot with proper gene count sizing
    ggplot(module_enrich, aes(x = -log10(Adjusted.P.value), 
                              y = reorder(Term, -log10(Adjusted.P.value)))) +
      geom_point(aes(size = GeneCount, color = Database)) +
      scale_size_continuous(
        name = "Gene Count", 
        range = c(3, 12),  # Larger range for better visibility
        breaks = scales::pretty_breaks(n = 5)
      ) +
      scale_color_brewer(palette = "Set2", name = "Database") +
      theme_minimal() +
      labs(
        title = paste("Functional Enrichment -", selected_module, "Module"),
        x = "-log10(Adjusted P-value)",
        y = "Term"
      ) +
      theme(
        axis.text.y = element_text(size = 10),
        plot.title = element_text(size = 14, face = "bold"),
        legend.position = "right"
      ) +
      geom_vline(xintercept = -log10(0.05), linetype = "dashed", color = "red", alpha = 0.5)
  })
  
  output$download_wgcna_standalone_enrichment_plot <- downloadHandler(
    filename = function() {
      selected_module <- input$wgcna_standalone_enrichment_module
      paste0("enrichment_", selected_module, "_", Sys.Date(), ".png")
    },
    content = function(file) {
      load_export_packages()
      req(wgcna_standalone_rv$wgcna_results)
      req(wgcna_standalone_rv$wgcna_results$enrichment)
      req(input$wgcna_standalone_enrichment_module)
      
      enrichment <- wgcna_standalone_rv$wgcna_results$enrichment
      selected_module <- input$wgcna_standalone_enrichment_module
      
      if (!selected_module %in% names(enrichment)) {
        p <- ggplot() + 
          annotate("text", x = 1, y = 1, label = "No enrichment data for this module") +
          theme_void()
      } else {
        module_enrich <- enrichment[[selected_module]]
        
        if (!is.null(module_enrich) && nrow(module_enrich) > 0) {
          # Filter by database if selected
          if (input$wgcna_standalone_enrichment_database != "all") {
            module_enrich <- module_enrich[module_enrich$Database == input$wgcna_standalone_enrichment_database, ]
          }
          
          # Take top N terms
          top_n <- input$wgcna_standalone_enrichment_top %||% 20
          module_enrich <- head(module_enrich, top_n)
          
          # FIX: Extract gene count properly
          module_enrich$GeneCount <- sapply(module_enrich$Overlap, function(x) {
            if (is.na(x) || is.null(x) || x == "") return(5)
            count <- as.numeric(gsub("/.*", "", as.character(x)))
            if (is.na(count) || count == 0) return(5)
            return(count)
          })
          
          # Create plot with proper gene counts
          p <- ggplot(module_enrich, aes(x = -log10(Adjusted.P.value), 
                                         y = reorder(Term, -log10(Adjusted.P.value)))) +
            geom_point(aes(size = GeneCount, color = Database)) +
            scale_size_continuous(
              name = "Gene Count", 
              range = c(3, 12),
              breaks = scales::pretty_breaks(n = 5)
            ) +
            scale_color_brewer(palette = "Set2", name = "Database") +
            theme_minimal() +
            labs(
              title = paste("Functional Enrichment -", selected_module, "Module"),
              x = "-log10(Adjusted P-value)",
              y = "Term"
            ) +
            theme(
              axis.text.y = element_text(size = 10),
              plot.title = element_text(size = 14, face = "bold"),
              legend.position = "right"
            ) +
            geom_vline(xintercept = -log10(0.05), linetype = "dashed", color = "red", alpha = 0.5)
        } else {
          p <- ggplot() +
            annotate("text", x = 1, y = 1, label = "No significant enrichment found") +
            theme_void()
        }
      }
      
      # Save as high-quality PNG
      p <- p + theme(
        plot.background = element_rect(fill = "white", color = NA),
        panel.background = element_rect(fill = "white", color = NA)
      )
      
      # Adaptive height based on number of terms
      height <- max(7, nrow(module_enrich) * 0.3)
      
      ggsave(file, plot = p, width = 12, height = height, dpi = 300, bg = "white")
    }
  )
  
  
  
  # Enrichment table
  output$wgcna_standalone_enrichment_table <- DT::renderDataTable({
    req(wgcna_standalone_rv$wgcna_results)
