  # Update module selector for network visualization
  observe({
    req(wgcna_standalone_rv$wgcna_results)
    
    modules <- unique(wgcna_standalone_rv$wgcna_results$moduleColors)
    modules <- modules[modules != "grey"]
    
    updateSelectInput(session, "wgcna_standalone_module_select",
                      choices = modules,
                      selected = modules[1])
  })
  
  # Output: Network visualization
  output$wgcna_standalone_network <- renderVisNetwork({
    req(wgcna_standalone_rv$wgcna_results)
    req(input$wgcna_standalone_module_select)
    
    results <- wgcna_standalone_rv$wgcna_results
    selected_module <- input$wgcna_standalone_module_select
    threshold <- input$wgcna_standalone_network_threshold %||% 0.05
    max_nodes <- input$wgcna_standalone_max_nodes %||% 50
    
    # Validate module exists
    if (!selected_module %in% unique(results$moduleColors)) {
      return(NULL)
    }
    
    tryCatch({
      print(paste("🌐 Building network for module:", selected_module))
      
      # Get genes in selected module
      if (is.null(names(results$moduleColors))) {
        # If names are missing, use datExpr column names
        module_indices <- which(results$moduleColors == selected_module)
        module_genes <- colnames(results$datExpr)[module_indices]
      } else {
        # Names are present, use them directly
        module_genes <- names(results$moduleColors)[results$moduleColors == selected_module]
      }
      
      print(paste("  📊 Genes in module:", length(module_genes)))
      print(paste("  📊 Sample genes:", paste(head(module_genes, 5), collapse = ", ")))
      print(paste("  📊 Genes in module:", length(module_genes)))
      
      if (length(module_genes) < 2) {
        return(visNetwork(
          data.frame(id = "Info", label = paste("Module", selected_module, "has only", length(module_genes), "gene(s)"), 
                     stringsAsFactors = FALSE),
          data.frame(from = character(0), to = character(0), stringsAsFactors = FALSE)
        ) %>% visNodes(color = "lightgray"))
      }
      
      # FIX: Calculate connectivity properly
      # Get gene indices
      all_genes <- colnames(results$datExpr)
      gene_indices <- which(all_genes %in% module_genes)
      
      # Calculate within-module connectivity if not available
      if (is.null(results$connectivity) || !is.data.frame(results$connectivity)) {
        print("  ⚠️ Connectivity not available, calculating...")
        
        # Calculate from TOM
        module_TOM <- results$TOM[gene_indices, gene_indices]
        kWithin <- rowSums(module_TOM) - 1  # Subtract self
        names(kWithin) <- module_genes
        
      } else {
        # Extract connectivity for module genes
        if (is.data.frame(results$connectivity)) {
          if ("kWithin" %in% colnames(results$connectivity)) {
            kWithin <- results$connectivity[module_genes, "kWithin"]
          } else if ("connectivity" %in% colnames(results$connectivity)) {
            kWithin <- results$connectivity[module_genes, "connectivity"]
          } else {
            # Use first numeric column
            numeric_cols <- sapply(results$connectivity, is.numeric)
            kWithin <- results$connectivity[module_genes, which(numeric_cols)[1]]
          }
        } else if (is.vector(results$connectivity)) {
          kWithin <- results$connectivity[module_genes]
        } else {
          # Fallback: calculate from TOM
          module_TOM <- results$TOM[gene_indices, gene_indices]
          kWithin <- rowSums(module_TOM) - 1
          names(kWithin) <- module_genes
        }
      }
      
      print(paste("  📈 Connectivity range:", round(min(kWithin, na.rm = TRUE), 2), 
                  "to", round(max(kWithin, na.rm = TRUE), 2)))
      
      # Limit to top genes by connectivity
      # if (length(module_genes) > max_nodes) {
      #   sorted_kWithin <- sort(kWithin, decreasing = TRUE)[1:max_nodes]
      #   top_gene_names <- if(is.null(names(sorted_kWithin))) module_genes[order(kWithin, decreasing = TRUE)[1:max_nodes]] else names(sorted_kWithin)
      #   module_genes <- top_gene_names[!is.na(top_gene_names) & top_gene_names != ""]
      #   kWithin <- kWithin[module_genes]
      #   gene_indices <- which(all_genes %in% module_genes)
      # }
      
      if (length(module_genes) > max_nodes) {
        # Use indices instead of names to avoid NA issues
        top_indices <- order(kWithin, decreasing = TRUE, na.last = TRUE)[1:min(max_nodes, length(kWithin))]
        module_genes <- module_genes[top_indices]
        kWithin <- kWithin[top_indices]
        gene_indices <- which(all_genes %in% module_genes)
        
        print(paste("  📉 Limited to top", length(module_genes), "genes by connectivity"))
      }
      
      # Get TOM for module genes
      TOM_module <- results$TOM[gene_indices, gene_indices]
      colnames(TOM_module) <- module_genes
      rownames(TOM_module) <- module_genes
      
      # Apply threshold
      TOM_module[TOM_module < threshold] <- 0
      
      print(paste("  🔗 Edges after threshold:", sum(TOM_module > 0) / 2))
      
      # Convert gene IDs to symbols for display
      organism <- input$wgcna_standalone_organism %||% "human"
      gene_symbols <- convert_gene_ids_to_symbols_universal(module_genes, organism)
      
      
      # Check if module_genes is empty
      print(paste("🔍 DEBUG: module_genes length before conversion:", length(module_genes)))
      if (length(module_genes) == 0) {
        print("⚠️ WARNING: module_genes is empty!")
        return(visNetwork(
          data.frame(id = "Error", label = "No genes found in module"),
          data.frame(from = character(0), to = character(0))
        ) %>% visNodes(color = "red"))
      }
      
      # Debug statements before data.frame creation
      print(paste("🔍 DEBUG: Creating nodes with", length(module_genes), "genes"))
      print(paste("🔍 DEBUG: kWithin length:", length(kWithin)))
      print(paste("🔍 DEBUG: gene_symbols length:", length(gene_symbols)))
      
      # Identify hub genes (top 15% by connectivity)
      if (length(kWithin) > 0 && !all(is.na(kWithin))) {
        connectivity_threshold <- quantile(kWithin, 0.85, na.rm = TRUE)
        is_hub <- kWithin >= connectivity_threshold
      } else {
        is_hub <- rep(FALSE, length(module_genes))
      }
      
      # Create color gradient: darker for hubs, lighter for regular genes
      library(grDevices)
      base_color <- col2rgb(selected_module) / 255
      
      # For hub genes: darker/richer color
      hub_color <- rgb(
        base_color[1] * 0.7, 
        base_color[2] * 0.7, 
        base_color[3] * 0.7
      )
      
      # For regular genes: pastel/lighter version (NOT white)
      regular_color <- rgb(
        base_color[1] * 0.4 + 0.6,  # Mix with white but not pure white
        base_color[2] * 0.4 + 0.6,
        base_color[3] * 0.4 + 0.6
      )
      
      node_colors <- ifelse(is_hub, hub_color, regular_color)
      node_sizes <- scales::rescale(as.numeric(kWithin), to = c(12, 45))
      node_sizes <- ifelse(is_hub, node_sizes * 1.4, node_sizes)
      
      # Create nodes with hub highlighting
      nodes <- data.frame(
        id = module_genes,
        label = gene_symbols[module_genes],
        title = paste0(
          "<b>", gene_symbols[module_genes], "</b><br>",
          "ID: ", module_genes, "<br>",
          "Connectivity: ", round(kWithin, 2),
          ifelse(is_hub, "<br><b>⭐ HUB GENE</b>", "")
        ),
        value = node_sizes,
        color.background = node_colors,  # Node fill color
        color.border = ifelse(is_hub, "#000000", "#666666"),  # Black border for hubs
        color.highlight.background = "#FFD700",  # Gold when selected
        color.highlight.border = "#FF4500",
        borderWidth = ifelse(is_hub, 3, 1.5),
        stringsAsFactors = FALSE
      )
      
      print(paste("  ⭐ Identified", sum(is_hub), "hub genes"))
      
      # Create edges
      edges_list <- list()
      for (i in 1:(length(module_genes) - 1)) {
        for (j in (i + 1):length(module_genes)) {
          weight <- TOM_module[i, j]
          if (!is.na(weight) && weight > 0) {
            edges_list[[length(edges_list) + 1]] <- data.frame(
              from = module_genes[i],
              to = module_genes[j],
              value = weight,
              title = paste0("Weight: ", round(weight, 3)),
              stringsAsFactors = FALSE
            )
          }
        }
      }
      
      # Handle empty edges
      if (length(edges_list) > 0) {
        edges <- do.call(rbind, edges_list)
        print(paste("  ✅ Created network with", nrow(edges), "edges"))
      } else {
        edges <- data.frame(
          from = character(0), 
          to = character(0), 
          value = numeric(0),
          title = character(0),
          stringsAsFactors = FALSE
        )
        print("  ⚠️ No edges above threshold, showing nodes only")
      }
      
      # Create network visualization
      visNetwork(nodes, edges, height = "700px", width = "100%") %>%
        visNodes(
          shape = "dot",
          font = list(size = 14, face = "arial", color = "#000000"),
          shadow = list(enabled = TRUE, size = 5)
        ) %>%
        visEdges(
          smooth = list(enabled = FALSE),  # Straight edges for clarity
          color = list(
            color = "rgba(200, 200, 200, 0.3)",  # Light gray, semi-transparent
            highlight = "#2B7CE9"
          ),
          width = 0.5,  # Thinner edges
          selectionWidth = 2,
          scaling = list(
            min = 0.5,
            max = 3,
            label = list(enabled = FALSE)
          )
        ) %>%
        visOptions(
          highlightNearest = list(enabled = TRUE, hover = TRUE, degree = 1),
          nodesIdSelection = TRUE,
          selectedBy = "color"
        ) %>%
        visPhysics(
          enabled = TRUE,
          stabilization = list(
            enabled = TRUE,
            iterations = 200,
            updateInterval = 25,
            fit = TRUE
          ),
          solver = "forceAtlas2Based",
          forceAtlas2Based = list(
            gravitationalConstant = -50,
            centralGravity = 0.01,
            springLength = 150,
            springConstant = 0.08,
            damping = 0.4,
            avoidOverlap = 0.8
          ),
          maxVelocity = 30,
          minVelocity = 0.1,
          timestep = 0.5
        ) %>%
        visInteraction(
          navigationButtons = TRUE,
          keyboard = TRUE,
          dragNodes = TRUE,
          dragView = TRUE,
          zoomView = TRUE
        ) %>%
        visLegend(
          enabled = TRUE,
          useGroups = FALSE,
          addNodes = list(
            list(
              label = "Hub Genes (Top 10%)",
              shape = "dot",
              size = 40,
              color = hub_color,
              font = list(size = 12, color = "#000000")
            ),
            list(
              label = "Regular Genes",
              shape = "dot", 
              size = 20,
              color = regular_color,
              font = list(size = 12, color = "#000000")
            )
          ),
          position = "right",
          width = 0.2
        ) %>%
        visLayout(randomSeed = 123) %>%  # Consistent layout
        visEvents(stabilizationIterationsDone = "function() {
    this.setOptions({physics: false});
  }") %>%
        htmlwidgets::onRender("
    function(el, x) {
      // Auto-stop physics after 15 seconds
      setTimeout(function() {
        var network = this.instance;
        if (network) {
          network.setOptions({physics: false});
          console.log('Network physics stopped after 15 seconds');
        }
      }, 15000);
    }
  ")
      
    }, error = function(e) {
      print(paste("❌ Network error:", e$message))
      print(e)
      showNotification(paste("Network error:", e$message), type = "error")
      return(NULL)
    })
  })
  
  # NEW: Display enrichment results for selected module
  output$wgcna_standalone_network_enrichment <- renderUI({
    req(wgcna_standalone_rv$wgcna_results)
    req(wgcna_standalone_rv$wgcna_results$enrichment)
    req(input$wgcna_standalone_module_select)
    
    enrichment_data <- wgcna_standalone_rv$wgcna_results$enrichment
    selected_module <- input$wgcna_standalone_module_select
    
    # Check if enrichment exists for this module
    if (is.null(enrichment_data[[selected_module]])) {
      return(
        div(class = "alert alert-info", 
            style = "margin-top: 15px;",
            icon("info-circle"),
            " No enrichment data available for this module")
      )
    }
    
    module_enrich <- enrichment_data[[selected_module]]
    
    # Debug: print column names
    print(paste("📊 Enrichment columns:", paste(colnames(module_enrich), collapse = ", ")))
    
    if (!is.data.frame(module_enrich) || nrow(module_enrich) == 0) {
      return(
        div(class = "alert alert-info", 
            style = "margin-top: 15px;",
            "No significant enrichment found for this module")
      )
    }
    
    # Detect which columns are available
    desc_col <- if("Description" %in% colnames(module_enrich)) "Description" else 
      if("Term" %in% colnames(module_enrich)) "Term" else
        if("ID" %in% colnames(module_enrich)) "ID" else colnames(module_enrich)[1]
    
    count_col <- if("Count" %in% colnames(module_enrich)) "Count" else
      if("GeneRatio" %in% colnames(module_enrich)) "GeneRatio" else
        if("Overlap" %in% colnames(module_enrich)) "Overlap" else NA
    
    pval_col <- if("p.adjust" %in% colnames(module_enrich)) "p.adjust" else
      if("FDR" %in% colnames(module_enrich)) "FDR" else
        if("pvalue" %in% colnames(module_enrich)) "pvalue" else
          if("P.value" %in% colnames(module_enrich)) "P.value" else NA
    
    # Sort by p-value if available
    if (!is.na(pval_col)) {
      module_enrich <- module_enrich[order(module_enrich[[pval_col]]), ]
    }
    
    top_terms <- head(module_enrich, 5)
    
    # Create enrichment display panel
    div(class = "panel panel-primary", 
        style = "margin-top: 15px;",
        div(class = "panel-heading", 
            h4(class = "panel-title", 
               icon("dna"),
               paste(" Biological Functions -", selected_module, "Module")
            )
        ),
        div(class = "panel-body",
            tags$table(class = "table table-striped table-hover",
                       tags$thead(
                         tags$tr(
                           tags$th("GO Term / Pathway"),
                           tags$th("Gene Count"),
                           tags$th("P-value")
                         )
                       ),
                       tags$tbody(
                         lapply(1:nrow(top_terms), function(i) {
                           description <- as.character(top_terms[[desc_col]][i])
                           
                           count <- if(!is.na(count_col)) {
                             as.character(top_terms[[count_col]][i])
                           } else {
                             "-"
                           }
                           
                           pval <- if(!is.na(pval_col)) {
                             sprintf("%.2e", as.numeric(top_terms[[pval_col]][i]))
                           } else {
                             "-"
                           }
                           
                           tags$tr(
                             tags$td(strong(description)),
                             tags$td(count),
                             tags$td(pval)
                           )
                         })
                       )
            ),
            if(nrow(module_enrich) > 5) {
              tags$p(class = "text-muted", 
                     style = "margin-top: 10px;",
                     paste("Showing top 5 of", nrow(module_enrich), "significant terms"))
            }
        )
    )
  })
  
