  # ============================================================================
  # PART 2: COLUMN DETECTION HELPER FUNCTIONS
  # ============================================================================
  
  # Auto-detect gene column
  detect_gene_column <- function(column_names) {
    # Common gene column patterns (case-insensitive)
    gene_patterns <- c(
      "^gene$", "^genes$", "^gene_name$", "^gene_id$", "^geneid$",
      "^symbol$", "^gene_symbol$", "^genesymbol$",
      "^ensembl", "^ens", "^entrez",
      "^id$", "^name$", "^row.names$"
    )
    
    for (pattern in gene_patterns) {
      matches <- grep(pattern, column_names, ignore.case = TRUE, value = TRUE)
      if (length(matches) > 0) {
        return(matches[1])
      }
    }
    
    # Default: first column
    return(column_names[1])
  }
  
  # Auto-detect log2FC column
  detect_logfc_column <- function(column_names) {
    # Common log2FC patterns
    logfc_patterns <- c(
      "^log2fc$", "^log2foldchange$", "^log2.fold", "^logfc$",
      "^log2_fc$", "^log2_fold_change$", "^l2fc$",
      "^foldchange$", "^fold.change$", "^fc$",
      "logfold", "log.fold", "log_fold"
    )
    
    for (pattern in logfc_patterns) {
      matches <- grep(pattern, column_names, ignore.case = TRUE, value = TRUE)
      if (length(matches) > 0) {
        return(matches[1])
      }
    }
    
    # Look for any column with "log" and "fold"
    log_cols <- grep("log.*fold|fold.*change|^fc$", column_names, 
                     ignore.case = TRUE, value = TRUE)
    if (length(log_cols) > 0) {
      return(log_cols[1])
    }
    
    # Default: second column if exists
    if (length(column_names) >= 2) {
      return(column_names[2])
    }
    
    return(column_names[1])
  }
  
  # Auto-detect p-value column
  detect_pvalue_column <- function(column_names) {
    # Common p-value patterns
    pvalue_patterns <- c(
      "^padj$", "^adj.p", "^p.adj", "^p_adj", "^fdr$",
      "^pvalue$", "^p.value$", "^p_value$", "^pval$",
      "^qvalue$", "^q.value$", "^q_value$",
      "adjusted.*p", "p.*adjusted", "corrected.*p"
    )
    
    for (pattern in pvalue_patterns) {
      matches <- grep(pattern, column_names, ignore.case = TRUE, value = TRUE)
      if (length(matches) > 0) {
        return(matches[1])
      }
    }
    
    # Look for any p-value related column
    p_cols <- grep("^p\\.|^p_|pval|p.val|qval|q.val|fdr", 
                   column_names, ignore.case = TRUE, value = TRUE)
    if (length(p_cols) > 0) {
      # Prefer adjusted p-values
      adj_cols <- grep("adj|fdr|q", p_cols, ignore.case = TRUE, value = TRUE)
      if (length(adj_cols) > 0) {
        return(adj_cols[1])
      }
      return(p_cols[1])
    }
    
    # Default: third column if exists
    if (length(column_names) >= 3) {
      return(column_names[3])
    }
    
    return(column_names[1])
  }
  
  # ============================================================================
  # PART 3: CONFIRM COLUMNS AND PROCESS DATA
  # ============================================================================
  
  observeEvent(input$grn_confirm_columns, {
    req(grn_standalone_rv$deg_data_raw)
    req(input$grn_gene_column)
    req(input$grn_logfc_column)
    req(input$grn_pvalue_column)
    
    # Validate that columns are different
    selected_cols <- c(input$grn_gene_column, 
                       input$grn_logfc_column, 
                       input$grn_pvalue_column)
    
    if (length(unique(selected_cols)) != 3) {
      showNotification("Please select three different columns!", type = "error")
      return()
    }
    
    # Store selected columns
    grn_standalone_rv$selected_columns <- list(
      gene = input$grn_gene_column,
      logfc = input$grn_logfc_column,
      pvalue = input$grn_pvalue_column
    )
    
    # Process the data with STANDARDIZED column names
    deg_df <- grn_standalone_rv$deg_data_raw
    
    tryCatch({
      # Create standardized data frame
      processed_deg <- data.frame(
        gene = deg_df[[input$grn_gene_column]],
        log2FoldChange = as.numeric(deg_df[[input$grn_logfc_column]]),
        padj = as.numeric(deg_df[[input$grn_pvalue_column]]),
        stringsAsFactors = FALSE
      )
      
      # Remove rows with missing values
      processed_deg <- processed_deg[complete.cases(processed_deg), ]
      
      # Store processed data with STANDARDIZED names
      grn_standalone_rv$deg_data <- processed_deg
      
      print(paste("✅ Processed DEG data:", nrow(processed_deg), "genes"))
      print(paste("   - Log2FC range:", 
                  round(min(processed_deg$log2FoldChange, na.rm = TRUE), 2), "to",
                  round(max(processed_deg$log2FoldChange, na.rm = TRUE), 2)))
      print(paste("   - P-value range:", 
                  format(min(processed_deg$padj, na.rm = TRUE), scientific = TRUE), "to",
                  format(max(processed_deg$padj, na.rm = TRUE), scientific = TRUE)))
      
      # Close modal
      removeModal()
      
      # Show success message
      showNotification(
        div(
          icon("check-circle"), 
          strong(" Success! "),
          paste("Loaded", nrow(processed_deg), "genes")
        ),
        type = "message",
        duration = 5
      )
      
    }, error = function(e) {
      showNotification(
        paste("Error processing data:", e$message),
        type = "error",
        duration = 10
      )
      print(paste("❌ Data processing error:", e$message))
    })
  })
  
  # ============================================================================
  # PART 4: DATA LOADED FLAG AND SUMMARY
  # ============================================================================
  
  # Gene filtering (reactive to show filtered genes)
  observe({
    # Only run if processed data exists
    req(grn_standalone_rv$deg_data)  # This is the PROCESSED data with standardized names
    req(grn_standalone_rv$selected_columns)  # Columns must be selected first
    req(input$grn_standalone_pvalue_cutoff)
    req(input$grn_standalone_logfc_cutoff)
    
    deg_df <- grn_standalone_rv$deg_data  # NOW it has 'padj' column!
    
    # Apply filters
    filtered <- deg_df %>%
      filter(
        padj < input$grn_standalone_pvalue_cutoff,
        abs(log2FoldChange) > input$grn_standalone_logfc_cutoff
      )
    
    # Separate up and down
    up_genes <- filtered$gene[filtered$log2FoldChange > 0]
    down_genes <- filtered$gene[filtered$log2FoldChange < 0]
    
    # Store filtered genes
    grn_standalone_rv$filtered_genes <- list(
      all_genes = filtered$gene,
      up_genes = up_genes,
      down_genes = down_genes
    )
    
    print(paste("🔍 Filtered genes:", 
                length(up_genes), "up,", 
                length(down_genes), "down,",
                "total:", length(filtered$gene)))
  })
  
  # GRN STANDALONE - EXAMPLE DATASET LOADING
  # ============================================================================
  
  # Track example data loading
  grn_standalone_rv$example_deg_loaded <- FALSE
  grn_standalone_rv$example_expr_loaded <- FALSE
  
  # Load Example DEG Dataset
  observeEvent(input$grn_standalone_load_example_deg, {
    
    tryCatch({
      # Use the same example data as transcriptome analysis
      # This should be a pre-computed DEG results file
      
      # The bundled example DEG file is the precomputed CMEC-vs-PMEC
      # output from the Advanced pipeline (edgeR / TMM, |log2FC|>1.5,
      # adj.P.Val<0.05). Fail loudly if it's missing — we previously had
      # a silent synthetic fallback that produced fake "MYC/E2F1/STAT3"
      # results, which is exactly the bug that caused the manuscript's
      # Figure 3 to disagree with the case-study text.
      example_deg_path <- "./data/example_deg_results.csv"
      if (!file.exists(example_deg_path)) {
        msg <- paste0(
          "Bundled example DEG file not found at '", example_deg_path,
          "'. Please reinstall the application's `data/` directory."
        )
        showNotification(msg, type = "error", duration = 10)
        stop(msg)
      }
      example_deg <- read.csv(example_deg_path, stringsAsFactors = FALSE)
      
      # Store the example DEG data
      grn_standalone_rv$deg_data_raw <- example_deg
      grn_standalone_rv$example_deg_loaded <- TRUE
      
      # Auto-detect columns
      colnames_lower <- tolower(colnames(example_deg))
      
      # Find gene column
      gene_col <- colnames(example_deg)[which(colnames_lower %in% c("gene", "gene_symbol", "symbol", "geneid", "gene_id"))[1]]
      if (is.na(gene_col)) gene_col <- colnames(example_deg)[1]
      
      # Find log2FC column
      lfc_col <- colnames(example_deg)[which(colnames_lower %in% c("log2foldchange", "logfc", "log2fc", "lfc"))[1]]
      
      # Find padj column
      padj_col <- colnames(example_deg)[which(colnames_lower %in% c("padj", "adj.p.val", "fdr", "adj_pvalue", "adjusted_pvalue"))[1]]
      
      # Store column selections
      grn_standalone_rv$selected_columns <- list(
        gene_col = gene_col,
        lfc_col = lfc_col,
        padj_col = padj_col
      )
      
      # Process the data immediately
      if (!is.na(gene_col) && !is.na(lfc_col) && !is.na(padj_col)) {
        processed_deg <- example_deg
        colnames(processed_deg)[colnames(processed_deg) == gene_col] <- "gene"
        colnames(processed_deg)[colnames(processed_deg) == lfc_col] <- "log2FoldChange"
        colnames(processed_deg)[colnames(processed_deg) == padj_col] <- "padj"
        
        grn_standalone_rv$deg_data <- processed_deg
        
        # Apply default filters
        p_cutoff <- input$grn_standalone_pvalue_cutoff %||% 0.05
        lfc_cutoff <- input$grn_standalone_logfc_cutoff %||% 1.0
        
        sig_genes <- processed_deg %>%
          filter(!is.na(padj) & padj < p_cutoff & abs(log2FoldChange) >= lfc_cutoff)
        
        up_genes <- sig_genes %>% filter(log2FoldChange > 0) %>% pull(gene)
        down_genes <- sig_genes %>% filter(log2FoldChange < 0) %>% pull(gene)
        
        grn_standalone_rv$filtered_genes <- list(
          all_genes = c(up_genes, down_genes),
          up_genes = up_genes,
          down_genes = down_genes,
          n_total = length(up_genes) + length(down_genes),
          n_up = length(up_genes),
          n_down = length(down_genes)
        )
      }
      
      showNotification(
        paste("✅ Example DEG data loaded:", nrow(example_deg), "genes"),
        type = "message",
        duration = 4
      )
      
      print(paste("✅ Loaded example DEG data:", nrow(example_deg), "genes"))
      
    }, error = function(e) {
      showNotification(paste("Error loading example DEG:", e$message), type = "error")
      print(paste("❌ Error loading example DEG:", e$message))
    })
  })
  
  # Load Example Expression Dataset
  observeEvent(input$grn_standalone_load_example_expr, {

    tryCatch({
      # Load the real bundled GSE151427 transcriptome — same source the
      # Advanced path uses. NO silent synthetic fallback: if the file is
      # missing, surface that as an error so the user doesn't unknowingly
      # run viper on noise (this was the previous Figure-3 bug).
      example_data <- load_example_transcriptome_data()
      raw_counts <- example_data$counts

      print(paste("📦 Example raw counts loaded:",
                  nrow(raw_counts), "genes x", ncol(raw_counts), "samples"))

      # Match the Advanced path's normalization: TMM (via edgeR) + log2-CPM.
      # That makes the viper TF-activity heatmap (Figure 3C) directly
      # comparable across the two GRN entry points.
      if (!requireNamespace("edgeR", quietly = TRUE)) {
        stop("edgeR is required for TMM normalization of the example expression data")
      }
      counts_int <- round(pmax(raw_counts, 0))
      dge <- edgeR::DGEList(counts = counts_int)
      dge <- edgeR::calcNormFactors(dge, method = "TMM")
      expr_matrix <- edgeR::cpm(dge, log = TRUE, prior.count = 1)

      grn_standalone_rv$expression_data <- as.matrix(expr_matrix)
      grn_standalone_rv$example_expr_loaded <- TRUE

      showNotification(
        paste0("✅ Example expression loaded (TMM-log2CPM): ",
               nrow(expr_matrix), " genes x ",
               ncol(expr_matrix), " samples (GSE151427, CMEC vs PMEC)"),
        type = "message",
        duration = 5
      )
      print(paste("✅ Standalone GRN example expression ready:",
                  nrow(expr_matrix), "x", ncol(expr_matrix),
                  "(TMM-log2CPM)"))

    }, error = function(e) {
      showNotification(
        paste0("Error loading example expression: ", e$message,
               " — please reinstall the bundled `data/` directory."),
        type = "error", duration = 10
      )
      print(paste("❌ Error loading example expression:", e$message))
    })
  })
  
  # Example data loaded indicator
  output$grn_standalone_example_loaded_indicator <- renderUI({
    deg_loaded <- grn_standalone_rv$example_deg_loaded %||% FALSE
    expr_loaded <- grn_standalone_rv$example_expr_loaded %||% FALSE
    
    if (!deg_loaded && !expr_loaded) {
      return(NULL)
    }
    
    div(
      style = "margin: 15px 0; padding: 15px; background: linear-gradient(135deg, #e8f5e9 0%, #c8e6c9 100%); 
              border-radius: 8px; border: 1px solid #a5d6a7;",
      fluidRow(
        column(8,
               div(
                 icon("check-circle", style = "color: #2e7d32; font-size: 1.2em;"),
                 strong(" Example Data Loaded", style = "color: #2e7d32; margin-left: 8px;")
               ),
               div(style = "margin-top: 8px; font-size: 0.9em;",
                   if (deg_loaded) {
                     div(icon("file-alt", style = "color: #43a047;"), 
                         " DEG Results: ", 
                         strong(nrow(grn_standalone_rv$deg_data_raw) %||% 0), " genes")
                   },
                   if (expr_loaded) {
                     div(icon("table", style = "color: #1976d2;"), 
                         " Expression Matrix: ", 
                         strong(paste(dim(grn_standalone_rv$expression_data)[1], "x", 
                                      dim(grn_standalone_rv$expression_data)[2])))
                   }
               )
        ),
        column(4, style = "text-align: right;",
               actionButton(
                 "grn_standalone_clear_example",
                 "Clear Example Data",
                 icon = icon("times"),
                 class = "btn-sm btn-outline-danger"
               )
        )
      )
    )
  })
  
  # Clear example data
  observeEvent(input$grn_standalone_clear_example, {
    grn_standalone_rv$deg_data_raw <- NULL
    grn_standalone_rv$deg_data <- NULL
    grn_standalone_rv$expression_data <- NULL
    grn_standalone_rv$filtered_genes <- NULL
    grn_standalone_rv$example_deg_loaded <- FALSE
    grn_standalone_rv$example_expr_loaded <- FALSE
    grn_standalone_rv$selected_columns <- NULL
    
    showNotification("Example data cleared", type = "message")
  })
  
  # Quick mode gene count output
  output$grn_standalone_quick_gene_count <- renderText({
    req(grn_standalone_rv$quick_mode_genes)
    length(grn_standalone_rv$quick_mode_genes)
  })
  
  
  output$grn_standalone_data_loaded <- reactive({
    !is.null(grn_standalone_rv$deg_data) && 
      !is.null(grn_standalone_rv$selected_columns)
  })
  outputOptions(output, "grn_standalone_data_loaded", suspendWhenHidden = FALSE)
  
  # Executive Summary
  output$grn_standalone_executive_summary <- renderUI({
    req(grn_standalone_rv$grn_results)
    
    grn <- grn_standalone_rv$grn_results
    params <- grn$analysis_params
    master_regs <- grn$master_regulators
    tf_regs <- grn$tf_regulations
    
    if (is.null(master_regs) || nrow(master_regs) == 0) {
      return(p("Analysis results are being processed...", style = "opacity: 0.8;"))
    }
    
    top_tf <- master_regs$label[1]
    n_tfs <- params$n_tfs %||% nrow(master_regs)
    n_regs <- params$n_regulations %||% nrow(tf_regs)
    
    # Calculate activation percentage
    act_pct <- if (!is.null(tf_regs) && "mor" %in% colnames(tf_regs)) {
      round(mean(tf_regs$mor == 1, na.rm = TRUE) * 100)
    } else { 50 }

    n_network_tfs <- length(unique(tf_regs$tf))

    div(
      p(style = "font-size: 1.1em; line-height: 1.6; margin: 0;",
        "Of your input genes, ", strong(n_tfs), " are transcription factors, embedded within a network of ",
        strong(n_regs), " regulatory interactions across ", strong(n_network_tfs), " unique TFs. ",
        "The network shows ", strong(paste0(act_pct, "%")), " activating relationships. ",
        strong(top_tf), " emerges as the top master regulator with the highest regulatory influence."
      )
    )
  })

  # Key TF Name
  output$grn_standalone_key_tf_name <- renderText({
    req(grn_standalone_rv$grn_results$master_regulators)
    grn_standalone_rv$grn_results$master_regulators$label[1]
  })
  
  # Network Scale — split values are "input-list TFs" and "network edges"
  output$grn_standalone_kf_network_scale <- renderText({
    req(grn_standalone_rv$grn_results)
    params <- grn_standalone_rv$grn_results$analysis_params
    paste0(params$n_tfs %||% 0, " / ", params$n_regulations %||% 0)
  })

  output$grn_standalone_kf_network_detail <- renderText({
    if (isTRUE(grn_standalone_rv$quick_mode_active)) {
      "Input-list TFs / network edges"
    } else {
      "DEG TFs / network edges"
    }
  })
  outputOptions(output, "grn_standalone_kf_network_detail", suspendWhenHidden = FALSE)
  
  # Master Count — reflects the actual master_regulators table size (driven by the slider)
  output$grn_standalone_kf_master_count <- renderText({
    req(grn_standalone_rv$grn_results$master_regulators)
    n <- nrow(grn_standalone_rv$grn_results$master_regulators)
    paste0(n, " TFs")
  })
  
  output$grn_standalone_kf_master_detail <- renderText({
    req(grn_standalone_rv$grn_results$master_regulators)
    top_tf <- grn_standalone_rv$grn_results$master_regulators$label[1]
    paste0("Led by ", top_tf)
  })
  
  # Coverage card label — switches between "DEG Coverage" and "Gene Coverage"
  output$grn_standalone_kf_coverage_label <- renderText({
    if (isTRUE(grn_standalone_rv$quick_mode_active)) "Gene Coverage" else "DEG Coverage"
  })
  outputOptions(output, "grn_standalone_kf_coverage_label", suspendWhenHidden = FALSE)

  # DEG Coverage
  output$grn_standalone_kf_deg_coverage <- renderText({
    req(grn_standalone_rv$grn_results)

    params <- grn_standalone_rv$grn_results$analysis_params
    tf_regs <- grn_standalone_rv$grn_results$tf_regulations
    filtered_genes <- grn_standalone_rv$filtered_genes

    if (!is.null(tf_regs) && !is.null(filtered_genes)) {
      # Get unique targets in the network
      targets_in_network <- unique(tf_regs$target)

      # Get input DEGs
      input_degs <- filtered_genes$all_genes

      # Calculate how many INPUT DEGs are covered (found as targets)
      degs_covered <- sum(input_degs %in% targets_in_network)

      coverage <- round(degs_covered / length(input_degs) * 100)
      paste0(min(coverage, 100), "%")
    } else {
      "N/A"
    }
  })

  output$grn_standalone_kf_deg_detail <- renderText({
    req(grn_standalone_rv$grn_results)

    tf_regs <- grn_standalone_rv$grn_results$tf_regulations
    filtered_genes <- grn_standalone_rv$filtered_genes

    if (!is.null(tf_regs) && !is.null(filtered_genes)) {
      targets_in_network <- unique(tf_regs$target)
      input_degs <- filtered_genes$all_genes
      degs_covered <- sum(input_degs %in% targets_in_network)

      noun <- if (isTRUE(grn_standalone_rv$quick_mode_active)) "genes" else "DEGs"
      paste0(degs_covered, " of ", length(input_degs), " ", noun, " in network")
    } else {
      "N/A"
    }
  })
  
  # Regulatory Circuits (TF-TF interactions)
  output$grn_standalone_kf_circuits <- renderText({
    req(grn_standalone_rv$grn_results)
    
    tf_regs <- grn_standalone_rv$grn_results$tf_regulations
    if (!is.null(tf_regs)) {
      all_tfs <- unique(tf_regs$tf)
      tf_tf_count <- sum(tf_regs$target %in% all_tfs)
      paste0(tf_tf_count)
    } else {
      "0"
    }
  })
  
  output$grn_standalone_kf_circuits_detail <- renderText({
    "TF-TF regulatory links"
  })
  
  # Top 5 TFs Cards
  output$grn_standalone_top5_tfs_cards <- renderUI({
    req(grn_standalone_rv$grn_results$master_regulators)
    
    top5 <- head(grn_standalone_rv$grn_results$master_regulators, 5)
    tf_regs <- grn_standalone_rv$grn_results$tf_regulations
    
    if (nrow(top5) == 0) {
      return(div(style = "text-align: center; padding: 30px; color: #7f8c8d;",
                 icon("info-circle", style = "font-size: 32px;"),
                 p("No master regulators identified")))
    }
    
    # Check druggability via ChEMBL (or use cached results if available)
    druggability <- NULL
    if (!is.null(grn_standalone_rv$grn_results$druggability_info)) {
      druggability <- grn_standalone_rv$grn_results$druggability_info
    } else {
      # Query ChEMBL for these TFs
      druggability <- tryCatch({
        check_druggability_chembl(top5$label)
      }, error = function(e) {
        print(paste("ChEMBL query error:", e$message))
        NULL
      })
      
      # Cache the results
      if (!is.null(druggability)) {
        grn_standalone_rv$grn_results$druggability_info <- druggability
      }
    }
    
    # Define colors for ranks
    rank_colors <- c("#FFD700", "#C0C0C0", "#CD7F32", "#4A90A4", "#7B68EE")
    
    cards <- lapply(1:nrow(top5), function(i) {
      tf <- top5[i, ]
      
      # Get target count - handle different column names
      n_targets <- if ("degree_out" %in% colnames(tf)) {
        tf$degree_out
      } else if ("n_targets" %in% colnames(tf)) {
        tf$n_targets
      } else {
        if (!is.null(tf_regs)) sum(tf_regs$tf == tf$label) else 0
      }
      
      # Calculate up/down targets
      n_activations <- 0
      n_repressions <- 0
      if (!is.null(tf_regs) && "mor" %in% colnames(tf_regs)) {
        tf_target_regs <- tf_regs[tf_regs$tf == tf$label, ]
        n_activations <- sum(tf_target_regs$mor == 1, na.rm = TRUE)
        n_repressions <- sum(tf_target_regs$mor == -1, na.rm = TRUE)
      }
      
      # Determine TF role
      role <- if (n_activations > n_repressions * 2) {
        "Primarily Activator"
      } else if (n_repressions > n_activations * 2) {
        "Primarily Repressor"
      } else {
        "Mixed Regulator"
      }
      
      role_color <- switch(role,
                           "Primarily Activator" = "#27ae60",
                           "Primarily Repressor" = "#e74c3c",
                           "#f39c12")
      
      # Check druggability from ChEMBL results
      is_druggable <- FALSE
      drug_info <- ""
      if (!is.null(druggability) && tf$label %in% druggability$gene) {
        drug_row <- druggability[druggability$gene == tf$label, ]
        is_druggable <- drug_row$is_druggable[1]
        if (is_druggable && !is.na(drug_row$n_bioactivities[1]) && drug_row$n_bioactivities[1] > 0) {
          drug_info <- paste0(" (", drug_row$n_bioactivities[1], " bioactivities)")
        }
        if (!is.na(drug_row$has_approved_drug[1]) && drug_row$has_approved_drug[1]) {
          drug_info <- " (Approved drug exists)"
        }
      }
      
      div(style = paste0("display: flex; align-items: center; padding: 12px; margin-bottom: 10px; ",
                         "background: #f8f9fa; border-radius: 8px; border-left: 4px solid ", rank_colors[i], ";"),
          # Rank badge
          div(style = paste0("width: 35px; height: 35px; background: ", rank_colors[i], "; ",
                             "border-radius: 50%; display: flex; align-items: center; justify-content: center; ",
                             "margin-right: 15px; color: white; font-weight: bold;"),
              i
          ),
          # TF Info
          div(style = "flex: 1;",
              div(style = "display: flex; align-items: center; flex-wrap: wrap; gap: 8px;",
                  strong(tf$label, style = "font-size: 1.1em;"),
                  if (is_druggable) {
                    span(icon("pills"), " ChEMBL Target", drug_info,
                         style = "font-size: 0.75em; background: #e8f5e9; color: #2e7d32; 
                                 padding: 2px 8px; border-radius: 10px;")
                  } else {
                    span(icon("circle", class = "fa-regular"), " Not in ChEMBL", 
                         style = "font-size: 0.75em; background: #f5f5f5; color: #9e9e9e; 
                                 padding: 2px 8px; border-radius: 10px;")
                  }
              ),
              div(style = "font-size: 0.85em; color: #666; margin-top: 3px;",
                  span(paste0(n_targets, " targets"), style = "margin-right: 15px;"),
                  span(HTML(paste0("&#8593;", n_activations, " &#8595;", n_repressions)), style = "margin-right: 15px;"),
                  span(role, style = paste0("color: ", role_color, "; font-weight: 500;"))
              )
          ),
          # Score
          div(style = "text-align: right;",
              if ("master_score" %in% colnames(tf)) {
                div(
                  div(style = "font-size: 1.3em; font-weight: bold; color: #2c3e50;",
                      round(tf$master_score, 1)),
                  div(style = "font-size: 0.75em; color: #95a5a6;", "Score")
                )
              } else {
                div(
                  div(style = "font-size: 1.3em; font-weight: bold; color: #2c3e50;",
                      n_targets),
                  div(style = "font-size: 0.75em; color: #95a5a6;", "Targets")
                )
              }
          )
      )
    })
    
    do.call(tagList, cards)
  })
  
  # TF Hierarchy (TF-TF interactions)
  output$grn_standalone_tf_hierarchy <- renderUI({
    req(grn_standalone_rv$grn_results$tf_regulations)
    
    tf_regs <- grn_standalone_rv$grn_results$tf_regulations
    all_tfs <- unique(tf_regs$tf)
    
    # Find TF-TF interactions
    tf_tf <- tf_regs %>%
      filter(target %in% all_tfs) %>%
      arrange(desc(confidence)) %>%
      head(10)
    
    if (nrow(tf_tf) == 0) {
      return(
        div(style = "text-align: center; padding: 30px; color: #7f8c8d;",
            icon("info-circle", style = "font-size: 32px; margin-bottom: 10px;"),
            p("No TF-TF regulatory relationships detected"),
            p("This suggests a relatively flat regulatory structure", style = "font-size: 0.9em;")
        )
      )
    }
    
    # Create visual representation
    hierarchy_items <- lapply(1:nrow(tf_tf), function(i) {
      row <- tf_tf[i, ]
      reg_type <- if (!is.null(row$mor) && row$mor == 1) "activates" else "represses"
      reg_color <- if (reg_type == "activates") "#27ae60" else "#e74c3c"
      reg_icon <- if (reg_type == "activates") "arrow-right" else "ban"
      
      div(style = "display: flex; align-items: center; padding: 8px 0; border-bottom: 1px solid #eee;",
          span(strong(row$tf), style = "width: 80px;"),
          span(icon(reg_icon), style = paste0("color: ", reg_color, "; margin: 0 10px;")),
          span(strong(row$target), style = "width: 80px;"),
          span(paste0("(", round(row$confidence, 2), ")"), 
               style = "color: #95a5a6; font-size: 0.85em; margin-left: auto;")
      )
    })
    
    div(
      div(style = "display: flex; justify-content: space-between; margin-bottom: 10px; font-size: 0.85em; color: #7f8c8d;",
          span("Regulator"),
          span("Target TF"),
          span("Confidence")
      ),
      do.call(tagList, hierarchy_items)
    )
  })
  
  # Biological Story
  output$grn_standalone_biological_story <- renderUI({
    req(grn_standalone_rv$grn_results)
    
    grn <- grn_standalone_rv$grn_results
    master_regs <- grn$master_regulators
    tf_regs <- grn$tf_regulations
    
    story_parts <- list()
    
    # Part 1: Top regulator story
    if (!is.null(master_regs) && nrow(master_regs) > 0) {
      top_tf <- master_regs$label[1]
      n_targets <- if ("degree_out" %in% colnames(master_regs)) {
        master_regs$degree_out[1]
      } else {
        sum(tf_regs$tf == top_tf)
      }
      
      story_parts[[1]] <- p(
        icon("star", style = "color: #f1c40f;"), " ",
        strong(top_tf), " is your top master regulator, directly controlling ",
        strong(n_targets), " genes in your dataset. This TF appears central to the ",
        "regulatory response observed in your experiment."
      )
    }
    
    # Part 2: Regulation balance
    if (!is.null(tf_regs) && "mor" %in% colnames(tf_regs)) {
      n_act <- sum(tf_regs$mor == 1, na.rm = TRUE)
      n_rep <- sum(tf_regs$mor == -1, na.rm = TRUE)
      total <- n_act + n_rep
      
      if (total > 0) {
        act_pct <- round(n_act / total * 100)
        
        if (act_pct > 60) {
          story_parts[[2]] <- p(
            icon("arrow-up", style = "color: #27ae60;"), " ",
            "The network is dominated by ", strong("activating interactions"), " (",
            act_pct, "%), suggesting an overall transcriptional activation program. ",
            "This pattern is often seen in cellular proliferation, differentiation, or stress responses."
          )
        } else if (act_pct < 40) {
          story_parts[[2]] <- p(
            icon("arrow-down", style = "color: #e74c3c;"), " ",
            "The network shows predominantly ", strong("repressive interactions"), " (",
            100 - act_pct, "%), indicating active transcriptional silencing. ",
            "This may reflect cellular quiescence, differentiation, or response to inhibitory signals."
          )
        } else {
          story_parts[[2]] <- p(
            icon("balance-scale", style = "color: #f39c12;"), " ",
            "The network shows a ", strong("balanced mix"), " of activation (", act_pct, "%) ",
            "and repression (", 100 - act_pct, "%). This complex regulatory pattern suggests ",
            "fine-tuned transcriptional control with both positive and negative feedback."
          )
        }
      }
    }
    
    # Part 3: Network complexity
    if (!is.null(tf_regs)) {
      all_tfs <- unique(tf_regs$tf)
      tf_tf_count <- sum(tf_regs$target %in% all_tfs)
      
      if (tf_tf_count > 5) {
        story_parts[[3]] <- p(
          icon("sitemap", style = "color: #9b59b6;"), " ",
          "With ", strong(tf_tf_count), " TF-TF regulatory links, your network shows a ",
          strong("hierarchical structure"), " where master regulators control other TFs, ",
          "amplifying their regulatory reach."
        )
      }
    }
    
    # Part 4: Key insight
    if (length(story_parts) >= 2) {
      story_parts[[length(story_parts) + 1]] <- div(
        style = "background: #e8f5e9; padding: 12px; border-radius: 6px; margin-top: 15px;",
        p(style = "margin: 0;",
          icon("lightbulb", style = "color: #27ae60;"), " ",
          strong("Key Insight: "), 
          "These master regulators represent potential therapeutic targets or biomarkers. ",
          "Consider validating the top TFs experimentally through ChIP-seq or knockdown studies."
        )
      )
    }
    
    story_parts[[length(story_parts) + 1]] <- div(
      style = "background: #fff3e0; padding: 12px; border-radius: 6px; margin-top: 15px; font-size: 0.9em;",
      p(style = "margin: 0;",
        icon("exclamation-circle", style = "color: #f57c00;"), " ",
        strong("Note: "), 
        "TF 'activation' or 'repression' refers to the TF's known regulatory mode from databases (DoRothEA/TFLink), ",
        "not the direction of gene expression change in your experiment. An 'activating' TF can regulate both ",
        "up-regulated and down-regulated genes."
      )
    )
    
    if (length(story_parts) == 0) {
      return(p("Generating biological interpretation...", style = "color: #7f8c8d;"))
    }
    
    do.call(tagList, story_parts)
  })
  
