  # GRN STANDALONE - REGULATORY INSIGHTS TAB OUTPUTS
  
  # Activating TFs Table
  output$grn_standalone_activating_tfs_table <- DT::renderDataTable({
    req(grn_standalone_rv$grn_results$tf_regulations)
    
    tf_regs <- grn_standalone_rv$grn_results$tf_regulations
    
    if (!"mor" %in% colnames(tf_regs)) {
      return(DT::datatable(
        data.frame(Message = "Regulation mode data not available"),
        options = list(dom = 't'),
        rownames = FALSE
      ))
    }
    
    # Calculate activation stats per TF
    tf_stats <- tf_regs %>%
      group_by(tf) %>%
      summarise(
        total_targets = n(),
        activations = sum(mor == 1, na.rm = TRUE),
        repressions = sum(mor == -1, na.rm = TRUE),
        avg_confidence = round(mean(confidence, na.rm = TRUE), 3),
        .groups = "drop"
      ) %>%
      mutate(
        activation_pct = round(activations / total_targets * 100, 1),
        role = case_when(
          activation_pct >= 70 ~ "Activator",
          activation_pct <= 30 ~ "Repressor",
          TRUE ~ "Mixed"
        )
      ) %>%
      filter(role == "Activator") %>%
      arrange(desc(activations), desc(activation_pct)) %>%
      select(
        TF = tf,
        `Total Targets` = total_targets,
        `Activations` = activations,
        `Activation %` = activation_pct,
        `Avg Confidence` = avg_confidence
      )
    
    if (nrow(tf_stats) == 0) {
      return(DT::datatable(
        data.frame(Message = "No predominantly activating TFs found"),
        options = list(dom = 't'),
        rownames = FALSE
      ))
    }
    
    DT::datatable(
      tf_stats,
      options = list(
        pageLength = 10,
        dom = 'tip',
        scrollY = "300px",
        scrollCollapse = TRUE
      ),
      rownames = FALSE
