  # TF Co-regulation Analysis
  output$grn_standalone_tf_coregulation <- renderUI({
    req(grn_standalone_rv$grn_results$tf_regulations)

    tf_regs <- grn_standalone_rv$grn_results$tf_regulations
    master_regs <- grn_standalone_rv$grn_results$master_regulators
    filtered_genes <- grn_standalone_rv$filtered_genes

    # Find TFs that share targets
    tf_targets <- tf_regs %>%
      group_by(tf) %>%
      summarise(targets = list(unique(target)), .groups = "drop")

    if (nrow(tf_targets) < 2) {
      return(p("Not enough TFs to analyze co-regulation", style = "color: #7f8c8d;"))
    }

    # Candidate set: top-N master regulators by influence (so we don't iterate
    # alphabetically). Fall back to all TFs if master_regulators isn't populated.
    # Cap at 25 to keep pairwise comparisons tractable (25*24/2 = 300 pairs).
    candidate_tfs <- if (!is.null(master_regs) && nrow(master_regs) > 0 && "label" %in% colnames(master_regs)) {
      head(master_regs$label, 25)
    } else {
      head(tf_targets$tf, 25)
    }
    tf_targets <- tf_targets[tf_targets$tf %in% candidate_tfs, ]

    if (nrow(tf_targets) < 2) {
      return(p("Not enough overlapping TFs in the master-regulator set to analyze co-regulation",
               style = "color: #7f8c8d;"))
    }

    # Adapt the shared-target threshold to input-list size.
    # Small inputs (<100 genes) make 3+ overlap rare; relax to 2.
    n_input <- length(filtered_genes$all_genes %||% character(0))
    min_shared <- if (n_input > 0 && n_input < 100) 2L else 3L

    # Iterate ALL pairs in candidate set
    tf_list <- tf_targets$tf
    overlaps <- list()
    for (i in seq_len(length(tf_list) - 1)) {
      for (j in (i + 1):length(tf_list)) {
        targets1 <- tf_targets$targets[[i]]
        targets2 <- tf_targets$targets[[j]]
        shared <- length(intersect(targets1, targets2))
        if (shared >= min_shared) {
          overlaps[[length(overlaps) + 1]] <- list(
            tf1 = tf_list[i],
            tf2 = tf_list[j],
            shared = shared,
            total = length(union(targets1, targets2))
          )
        }
      }
    }

    if (length(overlaps) == 0) {
      return(
        div(style = "text-align: center; padding: 20px; color: #7f8c8d;",
            icon("info-circle", style = "font-size: 24px; margin-bottom: 10px;"),
            p("No significant TF co-regulation detected"),
            p(paste0("Among the top-", length(tf_list),
                     " master regulators, no pair shares ", min_shared,
                     "+ targets in your input list."),
              style = "font-size: 0.9em;")
        )
      )
    }

    # Sort by shared targets
    overlaps <- overlaps[order(-sapply(overlaps, function(x) x$shared))]
    overlaps <- head(overlaps, 5)  # Show top 5 pairs
    
    # Create display
    coregulation_items <- lapply(overlaps, function(pair) {
      jaccard <- round(pair$shared / pair$total * 100, 1)
      
      div(style = "display: flex; align-items: center; padding: 10px; margin-bottom: 8px; 
                  background: #f8f9fa; border-radius: 6px;",
          div(style = "flex: 1;",
              div(style = "display: flex; align-items: center; gap: 8px;",
                  strong(pair$tf1, style = "color: #3498db;"),
                  icon("arrows-alt-h", style = "color: #7f8c8d;"),
                  strong(pair$tf2, style = "color: #9b59b6;")
              ),
              p(style = "margin: 5px 0 0 0; font-size: 0.85em; color: #7f8c8d;",
                paste0(pair$shared, " shared targets (", jaccard, "% overlap)"))
          )
      )
    })
    
    div(
      do.call(tagList, coregulation_items),
      div(style = "margin-top: 10px; padding: 8px; background: #fff3cd; border-radius: 4px; font-size: 0.85em;",
          icon("lightbulb", style = "color: #856404;"),
          span(" Co-regulating TFs may function together in regulatory modules", style = "color: #856404;")
      )
    )
  })
  
