    example_genes <- c(
      "TP53", "BRCA1", "MYC", "STAT3", "NFKB1", "JUN", "FOS", "EGFR", "KRAS", "AKT1",
      "PTEN", "RB1", "CDKN2A", "MDM2", "BCL2", "BAX", "CASP3", "VEGFA", "HIF1A", "MTOR",
      "PIK3CA", "MAPK1", "MAPK3", "SRC", "ABL1", "ERBB2", "MET", "RAF1", "BRAF", "MEK1",
      "ERK1", "JNK1", "P38", "NFE2L2", "KEAP1", "SOX2", "OCT4", "NANOG", "KLF4", "MYB",
      "ETS1", "ELK1", "SRF", "CREB1", "ATF3", "FOXO1", "FOXO3", "SMAD2", "SMAD3", "SMAD4"
    )

    updateTextAreaInput(session, "grn_standalone_gene_text",
                        value = paste(example_genes, collapse = "\n"))

    grn_standalone_rv$quick_mode_genes <- example_genes
    grn_standalone_rv$quick_mode_active <- TRUE
    grn_standalone_rv$filtered_genes <- list(
      all_genes  = example_genes,
      up_genes   = example_genes,
      down_genes = character(0),
      n_total    = length(example_genes),
      n_up       = length(example_genes),
      n_down     = 0
    )
    grn_standalone_rv$expression_data <- NULL

    showNotification("Example gene list loaded and parsed (50 cancer-related genes)", type = "message")
  })
  
  # Parse gene list from text input
  observeEvent(input$grn_standalone_parse_genes, {
    req(input$grn_standalone_gene_text)
    
    gene_text <- input$grn_standalone_gene_text
    
    # Parse genes - handle both newline and comma separated
    genes <- unlist(strsplit(gene_text, "[,\n\r\t]+"))
    genes <- trimws(genes)
    genes <- genes[genes != "" & !is.na(genes)]
    genes <- unique(genes)
    
    if (length(genes) < 10) {
      showNotification(
        paste("Only", length(genes), "genes found. Minimum 10 genes required."),
        type = "error",
        duration = 5
      )
      return()
    }
    
    # Detect gene ID type
    has_ensembl <- sum(grepl("^ENS", genes)) > length(genes) * 0.5
    has_entrez <- sum(grepl("^[0-9]+$", genes)) > length(genes) * 0.5
    
    gene_type <- if (has_ensembl) {
      "Ensembl IDs"
    } else if (has_entrez) {
      "Entrez IDs"
    } else {
      "Gene Symbols"
    }
    
    # Store parsed genes
    grn_standalone_rv$quick_mode_genes <- genes
    grn_standalone_rv$quick_mode_active <- TRUE
    
    # Create a fake filtered_genes structure for compatibility
    grn_standalone_rv$filtered_genes <- list(
      all_genes = genes,
      up_genes = genes,  # Treat all as "up" since we don't know direction
      down_genes = character(0),
      n_total = length(genes),
      n_up = length(genes),
      n_down = 0
    )
    
    # Clear expression data for quick mode
    grn_standalone_rv$expression_data <- NULL
    
    print(paste("✅ Quick mode: Parsed", length(genes), "genes (", gene_type, ")"))
    
    showNotification(
      paste("Successfully parsed", length(genes), "genes"),
      type = "message",
      duration = 3
    )
  })
  
  # Quick genes parsed flag
  output$grn_standalone_quick_genes_parsed <- reactive({
    !is.null(grn_standalone_rv$quick_mode_genes) && 
      length(grn_standalone_rv$quick_mode_genes) >= 10 &&
      (input$grn_standalone_input_mode == "quick")
  })
  outputOptions(output, "grn_standalone_quick_genes_parsed", suspendWhenHidden = FALSE)
  
  # Quick genes summary
  output$grn_standalone_quick_genes_summary <- renderUI({
    req(grn_standalone_rv$quick_mode_genes)
    
    genes <- grn_standalone_rv$quick_mode_genes
    
    # Detect gene type
    has_ensembl <- sum(grepl("^ENS", genes)) > length(genes) * 0.5
    has_entrez <- sum(grepl("^[0-9]+$", genes)) > length(genes) * 0.5
    
    gene_type <- if (has_ensembl) {
      "Ensembl IDs"
    } else if (has_entrez) {
      "Entrez IDs"
    } else {
      "Gene Symbols"
    }
    
    div(
      p(paste0("• ", length(genes), " unique genes detected")),
      p(paste0("• Gene ID type: ", gene_type)),
      p(paste0("• Sample genes: ", paste(head(genes, 5), collapse = ", "), "...")),
      p(style = "color: #856404; font-size: 0.9em; margin-top: 10px;",
        icon("exclamation-triangle"),
        " Quick mode active: TF activities will not be calculated"
      )
    )
  })
  
  # Modify the main analysis trigger to handle both modes
  # This observer checks input mode before running analysis
  observeEvent(input$grn_standalone_input_mode, {
    # Reset quick mode when switching to full mode
    if (input$grn_standalone_input_mode == "full") {
      grn_standalone_rv$quick_mode_active <- FALSE
      grn_standalone_rv$quick_mode_genes <- NULL
    }
  })
  
  # GRN STANDALONE - ENHANCED SUMMARY TAB OUTPUTS
  
  # Analysis Timestamp
  output$grn_standalone_analysis_timestamp <- renderUI({
    req(grn_standalone_rv$grn_results)
    
    div(style = "background: rgba(255,255,255,0.2); padding: 10px; border-radius: 6px;",
        p(style = "margin: 0; font-size: 0.9em;", 
          icon("clock"), " Analysis completed"),
        p(style = "margin: 5px 0 0 0; font-weight: bold;",
          format(Sys.time(), "%Y-%m-%d %H:%M"))
    )
  })
  
  # Parameters Summary
  output$grn_standalone_params_summary <- renderUI({
    req(grn_standalone_rv$grn_results)
    
    params <- grn_standalone_rv$grn_results$analysis_params
    is_quick_mode <- grn_standalone_rv$quick_mode_active %||% FALSE
    
    param_items <- list(
      list(label = "Organism", value = params$organism %||% "Human", icon = "dna"),
      list(label = "TF Database", value = params$tf_database %||% "Hybrid", icon = "database"),
      list(label = "Confidence Threshold", value = params$confidence_level %||% 0.6, icon = "sliders-h"),
      list(label = "Input Genes", value = params$n_input_genes %||% 0, icon = "list"),
      list(label = "Analysis Mode", value = if(is_quick_mode) "Quick (Gene List)" else "Full (DEG File)", icon = "cog")
    )
    
    param_rows <- lapply(param_items, function(item) {
      div(style = "display: flex; justify-content: space-between; padding: 8px 0; border-bottom: 1px solid #eee;",
          span(icon(item$icon, style = "color: #667eea; margin-right: 8px;"), item$label),
          strong(item$value)
      )
    })
    
    do.call(tagList, param_rows)
  })
  
  # Results Summary
  output$grn_standalone_results_summary <- renderUI({
    req(grn_standalone_rv$grn_results)
    
    grn <- grn_standalone_rv$grn_results
    params <- grn$analysis_params
    master_regs <- grn$master_regulators
    tf_regs <- grn$tf_regulations
    
    n_tfs <- params$n_tfs %||% nrow(master_regs)
    n_regs <- params$n_regulations %||% nrow(tf_regs)
    n_targets <- length(unique(tf_regs$target))
    
    # Activation stats
    act_pct <- if (!is.null(tf_regs) && "mor" %in% colnames(tf_regs)) {
      round(mean(tf_regs$mor == 1, na.rm = TRUE) * 100)
    } else { NA }
    
    # Top TFs
    top_tfs <- if (!is.null(master_regs) && nrow(master_regs) > 0) {
      paste(head(master_regs$label, 5), collapse = ", ")
    } else { "None identified" }
    
    div(
      # Key numbers
      fluidRow(
        column(4,
               div(style = "text-align: center; padding: 15px; background: #e3f2fd; border-radius: 8px;",
                   h3(n_tfs, style = "margin: 0; color: #1976d2;"),
                   p("Master TFs", style = "margin: 5px 0 0 0; color: #1976d2; font-size: 0.9em;")
               )
        ),
        column(4,
               div(style = "text-align: center; padding: 15px; background: #f3e5f5; border-radius: 8px;",
                   h3(n_regs, style = "margin: 0; color: #7b1fa2;"),
                   p("Regulations", style = "margin: 5px 0 0 0; color: #7b1fa2; font-size: 0.9em;")
               )
        ),
        column(4,
               div(style = "text-align: center; padding: 15px; background: #e8f5e9; border-radius: 8px;",
                   h3(n_targets, style = "margin: 0; color: #388e3c;"),
                   p("Target Genes", style = "margin: 5px 0 0 0; color: #388e3c; font-size: 0.9em;")
               )
        )
      ),
      
      br(),
      
      # Top TFs highlight
      div(style = "background: #fff8e1; padding: 15px; border-radius: 8px; border-left: 4px solid #ffc107;",
          h6(icon("star", style = "color: #ffc107;"), " Top Master Regulators", style = "margin-top: 0;"),
          p(top_tfs, style = "margin: 5px 0 0 0; font-weight: 500;")
      ),
      
      if (!is.na(act_pct)) {
        div(style = "margin-top: 15px;",
            p(style = "margin: 0;",
              "Regulatory balance: ", 
              strong(paste0(act_pct, "% activation")), " / ",
              strong(paste0(100 - act_pct, "% repression"))
            )
        )
      }
    )
  })
  
  # Biological Conclusions
  output$grn_standalone_conclusions <- renderUI({
    req(grn_standalone_rv$grn_results)
    
    grn <- grn_standalone_rv$grn_results
    master_regs <- grn$master_regulators
    tf_regs <- grn$tf_regulations
    
    conclusions <- list()
    
    # Conclusion 1: Top regulator
    if (!is.null(master_regs) && nrow(master_regs) > 0) {
      top_tf <- master_regs$label[1]
      n_targets <- if ("degree_out" %in% colnames(master_regs)) {
        master_regs$degree_out[1]
      } else {
        sum(tf_regs$tf == top_tf)
      }
      
      conclusions[[1]] <- div(style = "margin-bottom: 15px;",
                              icon("check-circle", style = "color: #27ae60; margin-right: 8px;"),
                              strong(top_tf), " is the dominant master regulator, controlling ",
                              strong(n_targets), " target genes in your dataset."
      )
    }
    
    # Conclusion 2: Network structure
    if (!is.null(tf_regs)) {
      all_tfs <- unique(tf_regs$tf)
      tf_tf_count <- sum(tf_regs$target %in% all_tfs)
      
      if (tf_tf_count > 0) {
        conclusions[[2]] <- div(style = "margin-bottom: 15px;",
                                icon("check-circle", style = "color: #27ae60; margin-right: 8px;"),
                                "The network shows ", strong("hierarchical regulation"), " with ",
                                strong(tf_tf_count), " TF-TF regulatory relationships."
        )
      }
    }
    
    # Conclusion 3: Regulatory balance
    if (!is.null(tf_regs) && "mor" %in% colnames(tf_regs)) {
      n_act <- sum(tf_regs$mor == 1, na.rm = TRUE)
      n_rep <- sum(tf_regs$mor == -1, na.rm = TRUE)
      
      if (n_act > n_rep * 1.5) {
        conclusions[[3]] <- div(style = "margin-bottom: 15px;",
                                icon("check-circle", style = "color: #27ae60; margin-right: 8px;"),
                                "The network is dominated by ", strong("activating interactions"), 
                                ", suggesting transcriptional activation programs."
        )
      } else if (n_rep > n_act * 1.5) {
        conclusions[[3]] <- div(style = "margin-bottom: 15px;",
                                icon("check-circle", style = "color: #27ae60; margin-right: 8px;"),
                                "The network shows predominantly ", strong("repressive regulation"), 
                                ", indicating transcriptional silencing programs."
        )
      }
    }
    
    if (length(conclusions) == 0) {
      return(p("Generating conclusions...", style = "color: #7f8c8d;"))
    }
    
    do.call(tagList, conclusions)
  })
  
  # Methods Text
  output$grn_standalone_methods_text <- renderUI({
    req(grn_standalone_rv$grn_results)
    
