    organism <- params$organism %||% "Human"
    
    div(
      p(style = "text-align: justify; line-height: 1.6;",
        "Gene regulatory network analysis was performed using a ", strong(db_name), 
        " database approach for ", strong(organism), ". ",
        "TF-target relationships were filtered at a confidence threshold of ", strong(confidence), ". ",
        "Master regulators were identified based on the number of regulated target genes, ",
        "regulatory mode (activation/repression), and interaction confidence scores."
      ),
      p(style = "text-align: justify; line-height: 1.6; margin-top: 10px;",
        "Network visualization was generated using force-directed layout algorithms. ",
        "TF activity scores, when available, were calculated using the VIPER algorithm based on ",
        "the expression patterns of known target genes."
      )
    )
  })
  
