      ),
      div(style = "display: flex; justify-content: space-between; padding: 10px 0; border-bottom: 1px solid #eee;",
          span("Avg confidence:"),
          strong(avg_confidence)
      ),
      div(style = "display: flex; justify-content: space-between; padding: 10px 0; border-bottom: 1px solid #eee;",
          span("TF Activities:"),
          if (has_tf_activity) {
            span(icon("check", style = "color: #27ae60;"), " Available", style = "color: #27ae60;")
          } else {
            span(icon("times", style = "color: #e74c3c;"), " Not available", style = "color: #e74c3c;")
          }
      ),
      div(style = "display: flex; justify-content: space-between; padding: 10px 0;",
