          if (!is.null(grn$tf_pathway_enrichment) || !is.null(grn$target_pathway_enrichment)) {
            span(icon("check", style = "color: #27ae60;"), " Available", style = "color: #27ae60;")
          } else {
            span(icon("times", style = "color: #e74c3c;"), " Not available", style = "color: #e74c3c;")
          }
      )
    )
  })
  
  # Download Handlers for Summary Tab
  output$download_grn_standalone_master_tfs_csv <- downloadHandler(
    filename = function() {
      paste0("master_regulators_", Sys.Date(), ".csv")
    },
    content = function(file) {
      req(grn_standalone_rv$grn_results$master_regulators)
      write.csv(grn_standalone_rv$grn_results$master_regulators, file, row.names = FALSE)
    }
