      paste0("tf_target_regulations_", Sys.Date(), ".csv")
    },
    content = function(file) {
      req(grn_standalone_rv$grn_results$tf_regulations)
      write.csv(grn_standalone_rv$grn_results$tf_regulations, file, row.names = FALSE)
