  output$grn_standalone_total_targets <- renderText({
    req(grn_standalone_rv$grn_results$network_data$nodes)
    nodes <- grn_standalone_rv$grn_results$network_data$nodes
    
    # Try multiple detection methods
    if ("type" %in% colnames(nodes)) {
      n_targets <- sum(nodes$type %in% c("Target", "target"), na.rm = TRUE)
    } else {
      n_targets <- 0
    }
    
    # If still 0, count non-TF nodes
    if (n_targets == 0 && "group" %in% colnames(nodes)) {
      n_targets <- sum(nodes$group %in% c("target", "upregulated", "downregulated"), na.rm = TRUE)
    }
    
    # If still 0, subtract TFs from total
    if (n_targets == 0) {
      n_tfs <- sum(nodes$type == "TF" | nodes$group == "tf", na.rm = TRUE)
      n_targets <- nrow(nodes) - n_tfs
    }
    
    return(as.character(n_targets))
  })
  
  output$grn_standalone_total_edges <- renderText({
    req(grn_standalone_rv$grn_results$network_data$edges)
    nrow(grn_standalone_rv$grn_results$network_data$edges)
  })
  
  output$grn_standalone_network_density <- renderText({
    req(grn_standalone_rv$grn_results$network_data)
    edges <- grn_standalone_rv$grn_results$network_data$edges
    nodes <- grn_standalone_rv$grn_results$network_data$nodes
    
    n_nodes <- nrow(nodes)
    n_edges <- nrow(edges)
    max_edges <- n_nodes * (n_nodes - 1)
    
    if (max_edges > 0) {
      density <- round((n_edges / max_edges) * 100, 1)
      paste0(density, "%")
    } else {
      "0%"
    }
  })
  
