  observeEvent(input$grn_standalone_expression, {
    req(input$grn_standalone_expression)
    
    tryCatch({
      file_path <- input$grn_standalone_expression$datapath
      file_ext <- tools::file_ext(input$grn_standalone_expression$name)
      
      print("📊 Loading expression file...")
      
      # Load file based on extension
      if (file_ext %in% c("xlsx", "xls")) {
        expr_df <- read.xlsx(file_path, sheet = 1, rowNames = TRUE)
      } else if (file_ext == "csv") {
        expr_df <- read.csv(file_path, stringsAsFactors = FALSE, row.names = 1, check.names = FALSE)
      } else {
        expr_df <- read.table(file_path, header = TRUE, sep = "\t", 
                              stringsAsFactors = FALSE, row.names = 1, check.names = FALSE)
      }
      
      print(paste("✅ Loaded expression data:", nrow(expr_df), "genes x", ncol(expr_df), "samples"))
      
      # Check if expression data IDs match DEG data IDs
      if (!is.null(grn_standalone_rv$deg_data)) {
        
        deg_genes <- grn_standalone_rv$deg_data$gene
        expr_genes <- rownames(expr_df)
        
        # Check for ID type mismatch
        deg_has_ensembl <- sum(grepl("^ENS", deg_genes)) > length(deg_genes) * 0.5
        expr_has_ensembl <- sum(grepl("^ENS", expr_genes)) > length(expr_genes) * 0.5
        
        match_rate <- sum(expr_genes %in% deg_genes) / length(expr_genes)
        
        print(paste("🔍 Gene ID matching check:"))
        print(paste("   DEG genes with ENSG:", sum(grepl("^ENS", deg_genes))))
        print(paste("   Expression genes with ENSG:", sum(grepl("^ENS", expr_genes))))
        print(paste("   Initial match rate:", round(match_rate * 100, 1), "%"))
        
        # If match rate is low (<30%), try conversion
        if (match_rate < 0.3) {
          print("⚠️ Low match rate detected - attempting gene ID conversion...")
          
          # Determine which dataset needs conversion
          if (deg_has_ensembl && !expr_has_ensembl) {
            # Expression data has symbols, need to convert to ENSG
            print("   Converting expression gene symbols to Ensembl IDs...")
            
            tryCatch({
              # Get organism from inputs or default to human
              organism <- isolate(input$grn_standalone_organism) %||% "human"
              
              # Use biomaRt for conversion
              if (organism == "human") {
                mart <- biomaRt::useMart("ensembl", dataset = "hsapiens_gene_ensembl")
              } else if (organism == "mouse") {
                mart <- biomaRt::useMart("ensembl", dataset = "mmusculus_gene_ensembl")
              } else {
                stop("Organism not supported for automatic conversion")
              }
              
              conversion <- biomaRt::getBM(
                attributes = c("external_gene_name", "ensembl_gene_id"),
                filters = "external_gene_name",
                values = expr_genes,
                mart = mart
              )
              
              # Create mapping
              mapping <- setNames(conversion$ensembl_gene_id, conversion$external_gene_name)
              
              # Convert rownames
              new_rownames <- mapping[expr_genes]
              converted_idx <- !is.na(new_rownames)
              
              # Keep only converted genes
              expr_df <- expr_df[converted_idx, , drop = FALSE]
              rownames(expr_df) <- new_rownames[converted_idx]
              
              print(paste("✅ Converted", sum(converted_idx), "genes to Ensembl IDs"))
              
            }, error = function(e) {
              print(paste("❌ Conversion failed:", e$message))
            })
            
          } else if (!deg_has_ensembl && expr_has_ensembl) {
            # Expression data has ENSG, need to convert to symbols
            print("   Converting expression Ensembl IDs to gene symbols...")
            
            tryCatch({
              # Get organism
              organism <- isolate(input$grn_standalone_organism) %||% "human"
              
              # Use biomaRt for conversion
              if (organism == "human") {
                mart <- biomaRt::useMart("ensembl", dataset = "hsapiens_gene_ensembl")
              } else if (organism == "mouse") {
                mart <- biomaRt::useMart("ensembl", dataset = "mmusculus_gene_ensembl")
              } else {
                stop("Organism not supported for automatic conversion")
              }
              
              conversion <- biomaRt::getBM(
                attributes = c("ensembl_gene_id", "external_gene_name"),
                filters = "ensembl_gene_id",
                values = expr_genes,
                mart = mart
              )
              
              # Create mapping
              mapping <- setNames(conversion$external_gene_name, conversion$ensembl_gene_id)
              
              # Convert rownames
              new_rownames <- mapping[expr_genes]
              converted_idx <- !is.na(new_rownames) & new_rownames != ""
              
              # Keep only converted genes
              expr_df <- expr_df[converted_idx, , drop = FALSE]
              rownames(expr_df) <- new_rownames[converted_idx]
              
              print(paste("✅ Converted", sum(converted_idx), "genes to gene symbols"))
              
            }, error = function(e) {
              print(paste("❌ Conversion failed:", e$message))
            })
          }
          
          # Check new match rate
          new_match_rate <- sum(rownames(expr_df) %in% deg_genes) / nrow(expr_df)
          print(paste("   New match rate:", round(new_match_rate * 100, 1), "%"))
          
          if (new_match_rate < 0.3) {
            showNotification(
              div(
                icon("exclamation-triangle"),
                strong(" Warning: Low gene overlap! "),
                br(),
                paste("Only", round(new_match_rate * 100, 1), "% of genes match between DEG and expression files."),
                br(),
                "TF activity calculation may fail or be inaccurate.",
                br(),
                br(),
                strong("Suggestion:"),
                br(),
                "• Use the same gene ID type in both files (all Ensembl IDs or all gene symbols)"
              ),
              type = "warning",
              duration = 15
            )
          } else {
            showNotification(
              div(
                icon("check-circle"),
                strong(" Gene ID conversion successful! "),
                br(),
                paste("Matched", round(new_match_rate * 100, 1), "% of genes")
              ),
              type = "message",
              duration = 5
            )
          }
        }
      }
      
      # SMART DETECTION: Check if data is normalized or raw counts
      is_normalized <- detect_normalization_status(expr_df)
      
      if (is_normalized) {
        print("✅ Detected NORMALIZED data (log-transformed or TPM/FPKM)")
        # Data is already normalized, use as-is
        final_expr <- expr_df
        
      } else {
        print("⚠️ Detected RAW COUNT data - applying normalization...")
        
        # Normalize using simple log2(CPM+1) approach
        final_expr <- normalize_expression_data(expr_df)
        
        print("✅ Normalization complete")
      }
      
      # Store the normalized expression data
      grn_standalone_rv$expression_data <- final_expr
      grn_standalone_rv$expression_data_loaded <- TRUE
      
      print(paste("📊 Final expression data:", nrow(final_expr), "genes x", ncol(final_expr), "samples"))
      
      showNotification(
        div(
          icon("check-circle"), 
          strong(" Expression data loaded! "),
          paste(nrow(final_expr), "genes x", ncol(final_expr), "samples")
        ),
        type = "message",
        duration = 5
      )
      
    }, error = function(e) {
      showNotification(
        paste("Error loading expression file:", e$message),
        type = "error",
        duration = 10
      )
      print(paste("❌ Expression file error:", e$message))
      grn_standalone_rv$expression_data <- NULL
      grn_standalone_rv$expression_data_loaded <- FALSE
    })
  })
  
  # Helper function to detect if data is normalized
  detect_normalization_status <- function(expr_df) {
    # Convert to matrix for analysis
    expr_mat <- as.matrix(expr_df)
    
    # Sample 1000 random values for efficiency
    sample_size <- min(1000, length(expr_mat))
    sample_vals <- sample(as.numeric(expr_mat), sample_size)
    sample_vals <- sample_vals[!is.na(sample_vals) & is.finite(sample_vals)]
    
    # Check 1: If values are negative, it's normalized (log-transformed)
    has_negative <- any(sample_vals < 0)
    if (has_negative) {
      return(TRUE)
    }
    
    # Check 2: If max value < 100 and has decimals, likely normalized
    max_val <- max(sample_vals, na.rm = TRUE)
    has_decimals <- any(sample_vals %% 1 != 0)
    if (max_val < 100 && has_decimals) {
      return(TRUE)
    }
    
    # Check 3: If most values are whole numbers and large (>100), likely raw counts
    mostly_whole <- sum(sample_vals %% 1 == 0) / length(sample_vals) > 0.9
    if (mostly_whole && max_val > 100) {
      return(FALSE)
    }
    
    # Check 4: Check variance - normalized data has lower variance
    cv <- sd(sample_vals, na.rm = TRUE) / mean(sample_vals, na.rm = TRUE)
    if (cv < 2) {
      return(TRUE)  # Likely normalized
    }
    
    # Default: assume raw counts if unclear
    return(FALSE)
  }
  
  # Helper function to normalize expression data
  normalize_expression_data <- function(expr_df) {
    # Convert to matrix
    expr_mat <- as.matrix(expr_df)
    
    # Remove genes with all zeros
    expr_mat <- expr_mat[rowSums(expr_mat) > 0, , drop = FALSE]
    
    # Simple normalization: log2(CPM + 1)
    # Calculate library sizes (column sums)
    lib_sizes <- colSums(expr_mat)
    
    # Calculate CPM (Counts Per Million)
    cpm_mat <- sweep(expr_mat, 2, lib_sizes / 1e6, FUN = "/")
    
    # Log2 transform with pseudocount
    normalized_mat <- log2(cpm_mat + 1)
    
    # Convert back to data frame
    normalized_df <- as.data.frame(normalized_mat)
    
    return(normalized_df)
  }
  
  
  # Network visualization output
  output$grn_standalone_network <- renderVisNetwork({
    req(grn_standalone_rv$grn_results$network_data)
    
    print("🎨 Rendering standalone GRN network...")
    
    network_data <- grn_standalone_rv$grn_results$network_data
    
    # Get the selected genes for proper node coloring
    selected_genes <- grn_standalone_rv$filtered_genes
    
    # Fix network data if needed (ensure proper group assignments)
    if (!("group" %in% colnames(network_data$nodes))) {
      network_data <- fix_grn_network_data(network_data, selected_genes)
    }
    
    nodes <- network_data$nodes
    edges <- network_data$edges
    
    print(paste("  Nodes:", nrow(nodes)))
    print(paste("  Edges:", nrow(edges)))
    
    # Apply node filter if specified
    if (!is.null(input$grn_standalone_node_filter) && input$grn_standalone_node_filter != "all") {
      filter_type <- input$grn_standalone_node_filter
      
      if (filter_type == "tfs") {
        keep_nodes <- nodes$id[nodes$group == "tf"]
      } else if (filter_type == "master") {
        master_tfs <- grn_standalone_rv$grn_results$master_regulators$tf
        keep_nodes <- nodes$id[nodes$id %in% master_tfs]
      } else if (filter_type == "up") {
        keep_nodes <- nodes$id[nodes$group %in% c("tf", "upregulated")]
      } else if (filter_type == "down") {
        keep_nodes <- nodes$id[nodes$group %in% c("tf", "downregulated")]
      } else {
        keep_nodes <- nodes$id
      }
      
      # Filter nodes and edges
      nodes <- nodes[nodes$id %in% keep_nodes, ]
      edges <- edges[edges$from %in% keep_nodes & edges$to %in% keep_nodes, ]
    }
    
    # Apply TF focus filter — show ONLY selected TFs + their direct targets
    tf_focus <- input$grn_standalone_tf_focus
    if (!is.null(tf_focus) && length(tf_focus) > 0) {
      edges <- edges[edges$from %in% tf_focus, ]
      keep_ids <- unique(c(tf_focus, edges$to))
      nodes <- nodes[nodes$id %in% keep_ids, ]
      print(paste("TF Focus: showing", length(tf_focus), "TFs,",
                  nrow(nodes), "nodes,", nrow(edges), "edges"))
    }

    # Hide non-DEG target genes (grey nodes) if unchecked
    if (!is.null(input$grn_standalone_show_nondeg_targets) && !input$grn_standalone_show_nondeg_targets) {
      target_ids <- nodes$id[nodes$group == "target"]
      nodes <- nodes[nodes$group != "target", ]
      edges <- edges[!(edges$to %in% target_ids & !(edges$to %in% nodes$id)), ]
      # Also remove edges pointing to removed nodes
      edges <- edges[edges$from %in% nodes$id & edges$to %in% nodes$id, ]
      print(paste("Hidden non-DEG targets: removed", length(target_ids), "grey nodes"))
    }

    # Apply edge confidence threshold
    if (!is.null(input$grn_standalone_edge_threshold)) {
      if ("confidence" %in% colnames(edges)) {
        edges <- edges[edges$confidence >= input$grn_standalone_edge_threshold, ]
      }
    }
    
    # Handle label visibility
    if (!is.null(input$grn_standalone_show_labels) && !input$grn_standalone_show_labels) {
      nodes$label[nodes$group != "tf"] <- ""
    }
    
    # Use user-configurable label size (bigger = better for publication screenshots)
    base_label <- input$grn_standalone_label_size %||% 16
    tf_label   <- base_label + 6   # TFs always bigger than targets

    # Create visNetwork
    vis <- visNetwork(nodes, edges, height = "700px", width = "100%") %>%
      visNodes(
        shape = "dot",
        scaling = list(min = 15, max = 40,
                       label = list(enabled = TRUE,
                                    min = base_label, max = base_label + 10,
                                    maxVisible = 200, drawThreshold = 0)),
        font = list(size = base_label, face = "arial",
                    strokeWidth = 3, strokeColor = "#ffffff")
      ) %>%
      visEdges(
        arrows = list(to = list(enabled = TRUE, scaleFactor = 0.5)),
        smooth = list(enabled = TRUE, type = "continuous"),
        width = 2
      ) %>%
      visGroups(
        groupname = "tf",
        shape = "triangle",
        color = list(
          background = "#9C27B0",
          border = "#7B1FA2",
          highlight = list(background = "#AB47BC", border = "#7B1FA2"),
          hover = list(background = "#BA68C8", border = "#7B1FA2")
        ),
        font = list(color = "black", size = tf_label, face = "bold",
                    strokeWidth = 4, strokeColor = "#ffffff"),
        borderWidth = 3
      ) %>%
      visGroups(
        groupname = "upregulated",
        shape = "dot",
        color = list(
          background = "#F44336",
          border = "#C62828",
          highlight = list(background = "#E57373", border = "#C62828")
        ),
        font = list(size = base_label, strokeWidth = 3, strokeColor = "#ffffff")
      ) %>%
      visGroups(
        groupname = "downregulated",
        shape = "dot",
        color = list(
          background = "#2196F3",
          border = "#1565C0",
          highlight = list(background = "#64B5F6", border = "#1565C0")
        ),
        font = list(size = base_label, strokeWidth = 3, strokeColor = "#ffffff")
      ) %>%
      visGroups(
        groupname = "target",
        shape = "dot",
        color = list(
          background = "#9E9E9E",
          border = "#616161",
          highlight = list(background = "#BDBDBD", border = "#616161")
        ),
        font = list(size = base_label - 2, strokeWidth = 2, strokeColor = "#ffffff")
      ) %>%
      visOptions(
        highlightNearest = list(enabled = TRUE, degree = 1, hover = TRUE),
        selectedBy = list(variable = "group", multiple = TRUE),
        nodesIdSelection = TRUE
      ) %>%
      visInteraction(
        navigationButtons = TRUE,
        keyboard = TRUE,
        dragNodes = TRUE,
        dragView = TRUE,
        zoomView = TRUE
      ) %>%
      visPhysics(
        stabilization = TRUE,
        barnesHut = list(
          gravitationalConstant = -8000,
          centralGravity = 0.3,
          springLength = 150,
          springConstant = 0.04,
          damping = 0.09
        )
      ) %>%
      visLayout(randomSeed = 42) %>%
      visLegend(
        width = 0.15,
        position = "right"
      ) %>%
      visEvents(stabilizationIterationsDone = "function() {
        this.setOptions({ physics: { enabled: false } });
      }")

    print("✅ Network rendered successfully")

    return(vis)
  })
  
