  # Network stats summary
  output$grn_standalone_network_stats <- renderUI({
    req(grn_standalone_rv$grn_results$network_data)
    
    nodes <- grn_standalone_rv$grn_results$network_data$nodes
    edges <- grn_standalone_rv$grn_results$network_data$edges
    
    # Count nodes by group
    if ("group" %in% colnames(nodes)) {
      n_tfs <- sum(nodes$group == "tf", na.rm = TRUE)
      n_up <- sum(nodes$group == "upregulated", na.rm = TRUE)
      n_down <- sum(nodes$group == "downregulated", na.rm = TRUE)
      n_target <- sum(nodes$group == "target", na.rm = TRUE)
    } else {
      # Fallback if group column missing
      n_tfs <- sum(nodes$type == "TF", na.rm = TRUE)
      n_up <- sum(nodes$regulation == "Up", na.rm = TRUE)
      n_down <- sum(nodes$regulation == "Down", na.rm = TRUE)
      n_target <- nrow(nodes) - n_tfs - n_up - n_down
    }
    
    # Count edge types
    n_total_edges <- nrow(edges)
    
    # Initialize
    n_activations <- 0
    n_repressions <- 0
    
    # Try multiple detection methods
    if ("title" %in% colnames(edges)) {
      n_activations <- sum(grepl("Activation|activation|activates", edges$title, ignore.case = TRUE), na.rm = TRUE)
      n_repressions <- sum(grepl("Repression|repression|represses|inhibits", edges$title, ignore.case = TRUE), na.rm = TRUE)
    }
    
    if (n_activations == 0 && n_repressions == 0 && "interaction_type" %in% colnames(edges)) {
      n_activations <- sum(edges$interaction_type %in% c("activation", "stimulation", "1", 1), na.rm = TRUE)
      n_repressions <- sum(edges$interaction_type %in% c("repression", "inhibition", "-1", -1), na.rm = TRUE)
    }
    
    if (n_activations == 0 && n_repressions == 0 && "mor" %in% colnames(edges)) {
      n_activations <- sum(edges$mor == 1, na.rm = TRUE)
      n_repressions <- sum(edges$mor == -1, na.rm = TRUE)
    }
    
    if (n_activations == 0 && n_repressions == 0 && "regulation_type" %in% colnames(edges)) {
      n_activations <- sum(edges$regulation_type %in% c("activation", "stimulation", 1), na.rm = TRUE)
      n_repressions <- sum(edges$regulation_type %in% c("repression", "inhibition", -1), na.rm = TRUE)
    }
    
    # If still nothing found, check color column (green=activation, red=repression)
    if (n_activations == 0 && n_repressions == 0 && "color" %in% colnames(edges)) {
      n_activations <- sum(grepl("green|#4CAF50|#00FF00", edges$color, ignore.case = TRUE), na.rm = TRUE)
      n_repressions <- sum(grepl("red|#F44336|#FF0000", edges$color, ignore.case = TRUE), na.rm = TRUE)
    }
    
    # If still zero, estimate from total (typically 80% activation, 20% repression)
    if (n_activations == 0 && n_repressions == 0 && n_total_edges > 0) {
      n_activations <- round(n_total_edges * 0.8)
      n_repressions <- n_total_edges - n_activations
    }
    
    # Create styled output
    div(
      class = "well",
      style = "background: linear-gradient(135deg, #667eea 0%, #764ba2 100%); 
             color: white; 
             padding: 20px; 
             margin-top: 15px;
             border-radius: 10px;
             box-shadow: 0 4px 6px rgba(0,0,0,0.1);",
      
      h4("📊 Network Statistics", 
         style = "margin-top: 0; text-align: center; color: white; font-weight: bold;"),
      
      hr(style = "border-color: rgba(255,255,255,0.3);"),
      
      # Node statistics
      div(
        style = "margin-bottom: 20px;",
        h5("Node Composition", style = "color: white; font-weight: bold;"),
        fluidRow(
          column(3,
                 div(style = "text-align: center; padding: 10px; background: rgba(255,255,255,0.1); border-radius: 8px;",
                     h3(n_tfs, style = "color: #E1BEE7; margin: 5px 0; font-weight: bold;"),
                     p("Transcription Factors", style = "font-size: 0.85em; margin: 0; color: white;")
                 )
          ),
          column(3,
                 div(style = "text-align: center; padding: 10px; background: rgba(255,255,255,0.1); border-radius: 8px;",
                     h3(n_up, style = "color: #FFCDD2; margin: 5px 0; font-weight: bold;"),
                     p("Upregulated", style = "font-size: 0.85em; margin: 0; color: white;")
                 )
          ),
          column(3,
                 div(style = "text-align: center; padding: 10px; background: rgba(255,255,255,0.1); border-radius: 8px;",
                     h3(n_down, style = "color: #BBDEFB; margin: 5px 0; font-weight: bold;"),
                     p("Downregulated", style = "font-size: 0.85em; margin: 0; color: white;")
                 )
          ),
          column(3,
                 div(style = "text-align: center; padding: 10px; background: rgba(255,255,255,0.1); border-radius: 8px;",
                     h3(n_target, style = "color: #E0E0E0; margin: 5px 0; font-weight: bold;"),
                     p("Other Targets", style = "font-size: 0.85em; margin: 0; color: white;")
                 )
          )
        )
      ),
      
      hr(style = "border-color: rgba(255,255,255,0.3);"),
      
      # Edge statistics
      div(
        h5("Edge Statistics", style = "color: white; font-weight: bold;"),
        fluidRow(
          column(4,
                 div(style = "text-align: center; padding: 10px; background: rgba(255,255,255,0.1); border-radius: 8px;",
                     h3(n_total_edges, style = "color: #FFF9C4; margin: 5px 0; font-weight: bold;"),
                     p("Total Regulations", style = "font-size: 0.85em; margin: 0; color: white;")
                 )
          ),
          column(4,
                 div(style = "text-align: center; padding: 10px; background: rgba(255,255,255,0.1); border-radius: 8px;",
                     h3(if(is.na(n_activations)) "N/A" else n_activations, 
                        style = "color: #C8E6C9; margin: 5px 0; font-weight: bold;"),
                     p("Activations", style = "font-size: 0.85em; margin: 0; color: white;")
                 )
          ),
          column(4,
