      file_ext <- tools::file_ext(input$file_ppi_standalone$name)
      
      # Read gene list
      if (file_ext == "csv") {
        genes <- read.csv(input$file_ppi_standalone$datapath, stringsAsFactors = FALSE, header = FALSE)
        genes <- genes[[1]]
      } else {
        genes <- readLines(input$file_ppi_standalone$datapath)
      }
      
      # Clean gene list
      genes <- trimws(genes)
      genes <- genes[genes != ""]
      genes <- unique(genes)
      
      if (length(genes) < 2) {
        showNotification("Please provide at least 2 genes", type = "error")
        return(NULL)
      }
      
      rv_ppi_standalone$gene_list <- genes
      
      showNotification(
        sprintf("Loaded %d unique genes", length(genes)),
        type = "message",
        duration = 5
      )
      
    }, error = function(e) {
      showNotification(paste("Error loading file:", e$message), type = "error")
    })
  })
  
