  observeEvent(input$ppi_standalone_gene_text, {
    req(input$ppi_standalone_gene_text)
    
    text_input <- input$ppi_standalone_gene_text
    
    if (nchar(trimws(text_input)) > 0) {
      # Parse genes (comma or newline separated)
      genes <- unlist(strsplit(text_input, "[,\\n\\r\\t]+"))
      genes <- trimws(genes)
      genes <- genes[genes != ""]
      genes <- unique(genes)
      
      if (length(genes) >= 2) {
        rv_ppi_standalone$gene_list <- genes
        showNotification(
          sprintf("Loaded %d unique genes from text input", length(genes)),
          type = "message"
        )
      }
    }
  })
  
  # Handle example button
  observeEvent(input$ppi_load_example, {
    example_genes <- c("TP53", "BRCA1", "EGFR", "MYC", "KRAS", 
                       "AKT1", "PIK3CA", "PTEN", "RB1", "CDK4")
    
    updateTextAreaInput(session, "ppi_standalone_gene_text",
                        value = paste(example_genes, collapse = "\n"))
    
    rv_ppi_standalone$gene_list <- example_genes
    
    showNotification("Example genes loaded!", type = "message")
  })
  
  
