  observe({
    organism <- input$ppi_standalone_organism
    
    # Hide/show drug targets tab based on organism
    # This requires shinyjs
    if (organism == "9606") {  # Human
      shinyjs::show(selector = "#ppi_detailed_subtabs li:has(a[data-value='Drug Targets'])")
    } else {
      shinyjs::hide(selector = "#ppi_detailed_subtabs li:has(a[data-value='Drug Targets'])")
    }
  })
  
  observeEvent(input$run_ppi_standalone, {

    # --- PREVENT DUPLICATE SUBMISSIONS ---
    shinyjs::disable("run_ppi_standalone")
    shinyjs::runjs("
      var btn = document.getElementById('run_ppi_standalone');
      if (btn) {
        btn.dataset.originalHtml = btn.innerHTML;
        btn.innerHTML = '<i class=\"fa fa-spinner fa-spin\" style=\"margin-right: 6px;\"></i> Running...';
        btn.classList.add('btn-disabled-running');
      }
    ")
    on.exit({
      shinyjs::enable("run_ppi_standalone")
      shinyjs::runjs("
        var btn = document.getElementById('run_ppi_standalone');
        if (btn && btn.dataset.originalHtml) {
          btn.innerHTML = btn.dataset.originalHtml;
          btn.classList.remove('btn-disabled-running');
        }
      ")
    }, add = TRUE)

    # 1. ROBUST INPUT PARSING
    raw_text <- input$ppi_standalone_gene_text
    genes_from_file <- rv_ppi_standalone$gene_list

    final_genes <- NULL

    if (!is.null(raw_text) && nchar(trimws(raw_text)) > 0) {
      lines <- unlist(strsplit(raw_text, "[\r\n,;\\s]+"))
      final_genes <- trimws(lines)
      final_genes <- final_genes[!is.na(final_genes) & nchar(final_genes) > 1]
      final_genes <- unique(final_genes)
    } else if (!is.null(genes_from_file) && length(genes_from_file) > 0) {
      final_genes <- genes_from_file
    }

    # 2. VALIDATION
    if (is.null(final_genes) || length(final_genes) < 2) {
      showNotification("Please provide at least 2 valid gene IDs.", type = "error")
      return()
    }

    print(paste("PPI Standalone: Processing", length(final_genes), "genes"))

    rv_ppi_standalone$gene_list <- final_genes
    rv_ppi_standalone$analysis_running <- TRUE

    # 3. Read UI parameters
    organism <- input$ppi_standalone_organism
    confidence <- input$ppi_standalone_confidence %||% 0.4
    max_nodes <- input$ppi_standalone_max_nodes %||% 100
    add_neighbors <- input$ppi_standalone_add_neighbors %||% FALSE
    run_enrichment <- input$ppi_standalone_run_enrichment %||% TRUE
    detect_modules <- input$ppi_standalone_detect_modules %||% TRUE

    # Resolve organism - handle "other" with custom taxonomy ID
    if (organism == "other") {
      custom_taxid <- input$ppi_standalone_custom_taxid
      if (is.null(custom_taxid) || is.na(custom_taxid) || custom_taxid <= 0) {
        showNotification("Please enter a valid NCBI Taxonomy ID for your organism.", type = "error")
        rv_ppi_standalone$analysis_running <- FALSE
        return()
      }
      organism <- as.character(as.integer(custom_taxid))
      organism_name <- organism  # Pass numeric as organism name - query_string_api handles it
    } else {
      organism_name <- switch(as.character(organism),
                              "9606" = "human", "10090" = "mouse", "10116" = "rat",
                              "7227" = "fly", "7955" = "zebrafish", "6239" = "worm",
                              "4932" = "yeast", "9823" = "pig", "9031" = "chicken",
                              "9913" = "bovine", "3702" = "arabidopsis", "human")
    }

    # 4. RUN ANALYSIS
    withProgress(message = 'Running PPI Analysis', value = 0, {
      tryCatch({
        setProgress(0.1, detail = "Querying STRING database...")

        # Query STRING (uses local data for human/mouse)
        ppi_interactions <- query_string_database_safe(
          genes = final_genes,
          organism = organism_name,
          confidence = confidence,
          max_interactions = 2000,
          network_type = input$ppi_standalone_network_type %||% "full"
        )

        if (is.null(ppi_interactions) || nrow(ppi_interactions) == 0) {
          showNotification("No protein interactions found. Check gene names and organism.", type = "warning")
          rv_ppi_standalone$analysis_running <- FALSE
          return()
        }

        print(paste("STRING returned", nrow(ppi_interactions), "interactions"))

        # --- FIRST SHELL EXPANSION ---
        if (add_neighbors && nrow(ppi_interactions) > 0) {
          setProgress(0.25, detail = "Adding first-shell interactors...")

          species_id <- as.integer(organism)
          string_data_path <- Sys.getenv("STRING_DATA_PATH", "/srv/string_data")
          local_species <- c(9606, 10090)

          if (species_id %in% local_species && requireNamespace("data.table", quietly = TRUE)) {
            tryCatch({
              cache_dir <- file.path(tempdir(), "string_cache")
              if (!dir.exists(cache_dir)) dir.create(cache_dir, recursive = TRUE)
              aliases_rds <- file.path(cache_dir, paste0(species_id, "_aliases_symbols.rds"))
              links_rds <- file.path(cache_dir, paste0(species_id, "_links.rds"))

              # Load cached data
              if (file.exists(aliases_rds)) {
                alias_map <- readRDS(aliases_rds)
              } else {
                aliases_file <- file.path(string_data_path, paste0(species_id, ".protein.aliases.v12.0.txt.gz"))
                all_aliases <- data.table::fread(cmd = paste("zcat", aliases_file),
                  sep = "\t", header = TRUE, col.names = c("string_id", "alias", "source"))
                symbol_sources <- c("Ensembl_HGNC_symbol", "Ensembl_EntrezGene",
                                    "BLAST_KEGG_NAME", "Ensembl_MGI_symbol", "Ensembl_MGI")
                alias_map <- unique(all_aliases[all_aliases$source %in% symbol_sources, c("string_id", "alias")])
                tryCatch(saveRDS(alias_map, aliases_rds), error = function(e) NULL)
                rm(all_aliases)
              }

              if (file.exists(links_rds)) {
                all_links <- readRDS(links_rds)
              } else {
                links_file <- file.path(string_data_path, paste0(species_id, ".protein.links.v12.0.txt.gz"))
                all_links <- data.table::fread(cmd = paste("zcat", links_file), header = TRUE)
                tryCatch(saveRDS(all_links, links_rds), error = function(e) NULL)
              }

              # Map current network genes to STRING IDs
              current_genes <- unique(c(ppi_interactions$gene_from, ppi_interactions$gene_to))
              alias_map$alias_upper <- toupper(alias_map$alias)
              matched <- alias_map[alias_map$alias_upper %in% toupper(current_genes), ]
              current_sids <- unique(matched$string_id)
              conf_thresh <- as.integer(confidence * 1000)

              # Find first-shell neighbors
              neighbor_links <- all_links[
                (all_links$protein1 %in% current_sids | all_links$protein2 %in% current_sids) &
                !(all_links$protein1 %in% current_sids & all_links$protein2 %in% current_sids) &
                all_links$combined_score >= conf_thresh,
              ]

              if (nrow(neighbor_links) > 0) {
                neighbor_links <- neighbor_links[order(neighbor_links$combined_score, decreasing = TRUE), ]
                neighbor_links <- head(neighbor_links, 200)

                sid_to_gene <- setNames(matched$alias, matched$string_id)
                new_sids <- setdiff(unique(c(neighbor_links$protein1, neighbor_links$protein2)), current_sids)
                new_matched <- alias_map[alias_map$string_id %in% new_sids, ]
                new_matched <- new_matched[!duplicated(new_matched$string_id), ]
                all_sid_map <- c(sid_to_gene, setNames(new_matched$alias, new_matched$string_id))

                map_fn <- function(sids) {
                  mapped <- all_sid_map[sids]
                  na_idx <- is.na(mapped)
                  if (any(na_idx)) mapped[na_idx] <- gsub("^[0-9]+\\.", "", sids[na_idx])
                  as.character(mapped)
                }

                new_interactions <- data.frame(
                  gene_from = map_fn(neighbor_links$protein1),
                  gene_to = map_fn(neighbor_links$protein2),
                  combined_score = neighbor_links$combined_score / 1000,
                  stringsAsFactors = FALSE
                )

                n_new <- length(setdiff(unique(c(new_interactions$gene_from, new_interactions$gene_to)), current_genes))
                ppi_interactions <- rbind(ppi_interactions, new_interactions)
                print(paste("First-shell: added", nrow(new_interactions), "interactions,", n_new, "new proteins"))
              }
            }, error = function(e) {
              print(paste("First-shell expansion failed:", e$message))
            })
          } else {
            print("First-shell expansion requires local STRING data (human/mouse only)")
          }
        }

        # --- ONE EDGE PER PROTEIN PAIR ---
        # STRING lists every interaction in both directions (A-B and B-A). Keep one row per
        # unordered pair (highest score) and drop self-loops, so edge counts, degrees and
        # density describe a simple undirected network.
        if (nrow(ppi_interactions) > 0) {
          ppi_interactions <- ppi_interactions[as.character(ppi_interactions$gene_from) != as.character(ppi_interactions$gene_to), ]
          a <- as.character(ppi_interactions$gene_from); b <- as.character(ppi_interactions$gene_to)
          pair_key <- ifelse(a < b, paste(a, b, sep = "|"), paste(b, a, sep = "|"))
          ord <- order(-ppi_interactions$combined_score)
          ppi_interactions <- ppi_interactions[ord, , drop = FALSE][!duplicated(pair_key[ord]), , drop = FALSE]
          rownames(ppi_interactions) <- NULL
        }

        # --- LIMIT NETWORK SIZE ---
        if (nrow(ppi_interactions) > 0) {
          all_proteins <- unique(c(ppi_interactions$gene_from, ppi_interactions$gene_to))
          if (length(all_proteins) > max_nodes) {
            # Keep top nodes by degree
            degree_table <- sort(table(c(ppi_interactions$gene_from, ppi_interactions$gene_to)), decreasing = TRUE)
            keep_nodes <- names(degree_table)[1:max_nodes]
            ppi_interactions <- ppi_interactions[
              ppi_interactions$gene_from %in% keep_nodes & ppi_interactions$gene_to %in% keep_nodes,
            ]
            print(paste("Trimmed network to top", max_nodes, "nodes,", nrow(ppi_interactions), "edges"))
          }
        }

        setProgress(0.4, detail = "Identifying hub proteins...")

        # Hub identification
        temp_degs <- list(all_genes = final_genes, up_genes = final_genes, down_genes = character(0))
        hub_proteins <- identify_ppi_hubs_safe(ppi_interactions, temp_degs)

        # Centrality measures
        centrality_measures <- calculate_centrality_measures(ppi_interactions)

        setProgress(0.5, detail = "Building network visualization...")

        # Visualization data
        network_data <- fix_ppi_visualization(ppi_interactions, temp_degs, hub_proteins)
        summary_stats <- create_ppi_summary_stats_safe(ppi_interactions, network_data, temp_degs, hub_proteins)

        # Module detection (optional)
        network_modules_result <- NULL
        module_enrichment <- NULL
        if (detect_modules && nrow(ppi_interactions) >= 5) {
          setProgress(0.55, detail = "Detecting network modules...")
          network_modules_result <- detect_network_modules(ppi_interactions, method = "louvain")

          # Module-specific enrichment
          if (!is.null(network_modules_result) && !is.null(network_modules_result$modules)) {
            setProgress(0.6, detail = "Module enrichment analysis...")
            unique_modules <- unique(network_modules_result$modules$module)
            module_sizes <- table(network_modules_result$modules$module)
            top_modules <- names(sort(module_sizes, decreasing = TRUE)[1:min(5, length(module_sizes))])

            module_enrichment <- list()
            for (mod_id in top_modules) {
              mod_genes <- network_modules_result$modules$gene[network_modules_result$modules$module == mod_id]
              if (length(mod_genes) >= 3) {
                module_enrichment[[paste0("Module_", mod_id)]] <- tryCatch(
                  perform_functional_enrichment_safe(mod_genes, temp_degs, organism = organism_name),
                  error = function(e) NULL
                )
              }
            }
          }
        }

        # Functional enrichment (optional)
        enrichment_results <- NULL
        if (run_enrichment) {
          setProgress(0.7, detail = "Running pathway enrichment...")
          network_proteins <- unique(c(ppi_interactions$gene_from, ppi_interactions$gene_to))
          enrichment_raw <- perform_functional_enrichment_safe(network_proteins, temp_degs, organism = organism_name)
          if (!is.null(enrichment_raw) && length(enrichment_raw) > 0) {
            enrichment_results <- do.call(rbind, lapply(names(enrichment_raw), function(db_name) {
              df <- enrichment_raw[[db_name]]
              if (!is.null(df) && is.data.frame(df) && nrow(df) > 0) { df$Database <- db_name; df } else NULL
            }))
            if (!is.null(enrichment_results) && nrow(enrichment_results) > 0)
              enrichment_results <- enrichment_results[order(enrichment_results$Adjusted.P.value), ]
          }
        }

        # Drug targets (human only, skip if not needed for speed)
        drug_targets <- data.frame()
        if (organism_name == "human" && nrow(ppi_interactions) > 0) {
          setProgress(0.85, detail = "Querying drug targets...")
          network_proteins <- unique(c(ppi_interactions$gene_from, ppi_interactions$gene_to))
          drug_targets <- tryCatch({
            query_drug_targets_comprehensive(network_proteins, organism = organism_name)
          }, error = function(e) { data.frame() })
        }

        setProgress(0.95, detail = "Finalizing results...")

        n_actual_hubs <- sum(hub_proteins$hub_type %in% c("Hub", "Major Hub"), na.rm = TRUE)
        summary_flat <- list(
          total_nodes = summary_stats$basic_stats$n_nodes,
          total_edges = summary_stats$basic_stats$n_edges,
          avg_degree = summary_stats$network_metrics$avg_degree,
          density = summary_stats$network_metrics$density,
          n_hubs = n_actual_hubs,
          coverage_rate = summary_stats$basic_stats$coverage_rate
        )

        results <- list(
          ppi_interactions = ppi_interactions,
          hub_proteins = hub_proteins,
          centrality_measures = centrality_measures,
          network_data = network_data,
          network_modules = if (!is.null(network_modules_result)) network_modules_result$modules else NULL,
          module_enrichment = module_enrichment,
          enrichment_results = enrichment_results,
          functional_enrichment = enrichment_results,
          drug_targets = drug_targets,
          summary_stats = summary_stats,
          summary = summary_flat,
          selected_genes = temp_degs,
          analysis_params = list(
            organism = organism_name,
            confidence_threshold = confidence,
            n_input_genes = length(final_genes),
            analysis_date = Sys.Date()
          ),
          analysis_type = "ppi"
        )

        n_int <- nrow(ppi_interactions)
        showNotification(sprintf("Found %d interactions among %d proteins", n_int, summary_flat$total_nodes), type = "message")

        rv_ppi_standalone$results <- results
        setProgress(1, detail = "Complete!")

      }, error = function(e) {
        print(paste("PPI Error:", e$message))
        showNotification(paste("Analysis failed:", e$message), type = "error")
      }, finally = {
        rv_ppi_standalone$analysis_running <- FALSE
      })
    })
  })
  
  # Fallback PPI analysis function
  perform_ppi_analysis_fallback <- function(gene_list, organism, confidence_score) {
    
    print("🔍 Fallback: Querying STRING API directly...")
    
    # Map organism to species ID
    species_id <- switch(as.character(organism),
                         "9606" = "9606",    # Human
                         "10090" = "10090",  # Mouse
                         "10116" = "10116",  # Rat
                         "7227" = "7227",    # Fly
                         "7955" = "7955",    # Zebrafish
                         "6239" = "6239",    # C. elegans
                         "4932" = "4932",    # Yeast
                         "9823" = "9823",    # Pig
                         "9031" = "9031",    # Chicken
                         "9913" = "9913",    # Cow
                         "3702" = "3702",    # Arabidopsis
                         as.character(organism))
    
    print(paste("  • Species ID:", species_id))
    print(paste("  • Confidence:", confidence_score))
    print(paste("  • Input genes:", length(gene_list)))
    
    # Load required packages
    if (!requireNamespace("httr", quietly = TRUE)) stop("httr package required")
    if (!requireNamespace("jsonlite", quietly = TRUE)) stop("jsonlite package required")
    if (!requireNamespace("igraph", quietly = TRUE)) stop("igraph package required")
    
    # Clean gene names
    gene_list_clean <- gsub("[^A-Za-z0-9_-]", "", gene_list)
    gene_list_clean <- gene_list_clean[gene_list_clean != ""]
    
    # Limit to 100 genes for better performance (STRING can handle more via POST)
    if (length(gene_list_clean) > 100) {
      print(paste("  • Limiting to 100 genes for optimal performance"))
      gene_list_clean <- head(gene_list_clean, 100)
    }
    
    if (length(gene_list_clean) < 2) {
      print("  • ERROR: Need at least 2 genes")
      return(create_empty_ppi_result(gene_list, confidence_score))
    }
    
    # Join genes with newline
    genes_str <- paste(gene_list_clean, collapse = "\n")
    
    print("  • Querying STRING database...")
    
    tryCatch({
      # Use POST request to avoid URL length issues
      response <- httr::POST(
        url = "https://string-db.org/api/json/network",
        body = list(
          identifiers = genes_str,
          species = species_id,
          required_score = as.integer(confidence_score * 1000)
        ),
        encode = "form"
      )
      
      # Check response
      status <- httr::status_code(response)
      print(paste("  • API response status:", status))
      
      if (status != 200) {
        stop(paste("STRING API returned status code:", status))
      }
      
      # Parse JSON
      content_text <- httr::content(response, "text", encoding = "UTF-8")
      
      if (is.null(content_text) || nchar(content_text) == 0) {
        print("  • Empty response from STRING")
        return(create_empty_ppi_result(gene_list, confidence_score))
      }
      
      data <- jsonlite::fromJSON(content_text)
      
      # Check if empty
      if (is.null(data) || length(data) == 0 || nrow(data) == 0) {
        print("  • No interactions found in STRING")
        return(create_empty_ppi_result(gene_list, confidence_score))
      }
      
      print(paste("  • STRING returned", nrow(data), "interactions"))
      
      # Process interactions
      interactions <- data.frame(
        protein1 = data$preferredName_A,
        protein2 = data$preferredName_B,
        score = data$score / 1000,
        stringsAsFactors = FALSE
      )
      
      # Remove NAs and empty strings
      interactions <- interactions[
        !is.na(interactions$protein1) & 
          !is.na(interactions$protein2) & 
          interactions$protein1 != "" & 
          interactions$protein2 != "" &
          interactions$protein1 != interactions$protein2,  # Remove self-loops
      ]
      
      if (nrow(interactions) == 0) {
        print("  • No valid interactions after filtering")
        return(create_empty_ppi_result(gene_list, confidence_score))
      }
      
      print(paste("  • Valid interactions:", nrow(interactions)))
      print("  • Building network graph...")
      
      # Build network
      g <- igraph::graph_from_data_frame(
        interactions[, c("protein1", "protein2")], 
        directed = FALSE
      )
      
      # Remove duplicate edges
      g <- igraph::simplify(g)
      
      # Calculate metrics
      degrees <- igraph::degree(g)
      betweenness_scores <- igraph::betweenness(g)
      hub_scores <- igraph::hub_score(g)$vector
      
      # Hub proteins
      hub_proteins <- data.frame(
        gene = names(degrees),
        degree = as.numeric(degrees),
        betweenness = as.numeric(betweenness_scores),
        hub_score = as.numeric(hub_scores),
        stringsAsFactors = FALSE
      )
      
      # Sort by degree
      hub_proteins <- hub_proteins[order(-hub_proteins$degree), ]
      hub_proteins <- head(hub_proteins, 20)
      
      print(paste("  • Identified", nrow(hub_proteins), "hub proteins"))
      
      # Prepare visualization data
      all_genes <- unique(c(interactions$protein1, interactions$protein2))
      
      nodes <- data.frame(
        id = all_genes,
        label = all_genes,
        value = degrees[all_genes],
        title = paste0("<b>", all_genes, "</b><br>Degree: ", degrees[all_genes]),
        stringsAsFactors = FALSE
      )
      
      edges <- data.frame(
        from = interactions$protein1,
        to = interactions$protein2,
        value = interactions$score,
        title = paste0("Score: ", round(interactions$score, 3)),
        stringsAsFactors = FALSE
      )
      
      # Summary
      summary <- list(
        total_nodes = igraph::vcount(g),
        total_edges = igraph::ecount(g),
        network_density = igraph::edge_density(g),
        avg_degree = mean(degrees),
        max_degree = max(degrees)
      )
      
      print("✅ PPI analysis completed successfully!")
      print(paste("  • Nodes:", summary$total_nodes))
      print(paste("  • Edges:", summary$total_edges))
      
      return(list(
        ppi_interactions = interactions,
        hub_proteins = hub_proteins,
        network_data = list(nodes = nodes, edges = edges),
        summary = summary,
        analysis_params = list(
          n_input_genes = length(gene_list),
          n_proteins = igraph::vcount(g),
          confidence_score = confidence_score,
          database = "STRING"
        )
      ))
      
    }, error = function(e) {
      print(paste("❌ STRING API error:", e$message))
      print(paste("   Error class:", class(e)))
      traceback()
      return(create_empty_ppi_result(gene_list, confidence_score))
    })
  }
  
  # Helper function to create empty result structure
  create_empty_ppi_result <- function(gene_list, confidence_score) {
    return(list(
      ppi_interactions = data.frame(
        protein1 = character(0),
        protein2 = character(0),
        score = numeric(0),
        stringsAsFactors = FALSE
      ),
      hub_proteins = data.frame(
        gene = character(0),
        degree = numeric(0),
        betweenness = numeric(0),
        hub_score = numeric(0),
        stringsAsFactors = FALSE
      ),
      network_data = list(
        nodes = data.frame(
          id = character(0),
          label = character(0),
          value = numeric(0),
          title = character(0),
          stringsAsFactors = FALSE
        ),
        edges = data.frame(
          from = character(0),
          to = character(0),
          value = numeric(0),
          stringsAsFactors = FALSE
        )
      ),
      summary = list(
        total_nodes = 0,
        total_edges = 0,
        network_density = 0,
        avg_degree = 0,
        max_degree = 0
      ),
      analysis_params = list(
        n_input_genes = length(gene_list),
        n_proteins = 0,
        confidence_score = confidence_score,
        database = "STRING"
      )
    ))
  }
  
