        top_per_module <- enrichment %>%
          group_by(module) %>%
          arrange(!!sym(pval_col)) %>%
          slice_head(n = 5) %>%
          ungroup()
        
        # Create plot
        p <- ggplot(top_per_module, aes(x = reorder(!!sym(desc_col), -log10(!!sym(pval_col))), 
