    if (!is.null(rv_ppi_standalone$results$functional_enrichment)) {
      enrichment <- rv_ppi_standalone$results$functional_enrichment
    } else if (!is.null(rv_ppi_standalone$results$enrichment_results)) {
      enrichment <- rv_ppi_standalone$results$enrichment_results
    }
    
    # Handle both list and dataframe structures
    if (!is.null(enrichment)) {
      if (is.list(enrichment) && !is.data.frame(enrichment)) {
        # Convert list to dataframe
        enrichment <- do.call(rbind, lapply(names(enrichment), function(db_name) {
          df <- enrichment[[db_name]]
          if (!is.null(df) && nrow(df) > 0) {
            df$Database <- db_name
            return(df)
          }
          return(NULL)
        }))
      }
      
      if (is.data.frame(enrichment) && nrow(enrichment) > 0) {
        # Find the correct p-value column
        pval_col <- NULL
        if ("Adjusted.P.value" %in% colnames(enrichment)) {
          pval_col <- "Adjusted.P.value"
        } else if ("p.adjust" %in% colnames(enrichment)) {
          pval_col <- "p.adjust"
        } else if ("adj.P.Val" %in% colnames(enrichment)) {
          pval_col <- "adj.P.Val"
        }
        
        # Find description column
        desc_col <- NULL
        if ("Term" %in% colnames(enrichment)) {
          desc_col <- "Term"
        } else if ("Description" %in% colnames(enrichment)) {
          desc_col <- "Description"
        } else if ("Pathway" %in% colnames(enrichment)) {
          desc_col <- "Pathway"
        }
        
        if (!is.null(pval_col) && !is.null(desc_col)) {
          # Plot top pathways
          top_pathways <- head(enrichment[order(enrichment[[pval_col]]), ], 15)
          
          # Ensure p-values are numeric
          top_pathways[[pval_col]] <- as.numeric(top_pathways[[pval_col]])
          
          # Remove any NA or invalid values
          top_pathways <- top_pathways[!is.na(top_pathways[[pval_col]]) & top_pathways[[pval_col]] > 0, ]
          
          if (nrow(top_pathways) > 0) {
            par(mar = c(5, 15, 4, 2))
            barplot(
              -log10(top_pathways[[pval_col]]),
              names.arg = top_pathways[[desc_col]],
              horiz = TRUE,
              las = 1,
              col = "steelblue",
              main = "Top Enriched Pathways",
              xlab = "-log10(Adjusted P-value)"
            )
            abline(v = -log10(0.05), col = "red", lty = 2)
          } else {
            plot(1, type = "n", axes = FALSE, xlab = "", ylab = "")
            text(1, 1, "No significant pathways found", cex = 1.2)
          }
        } else {
          plot(1, type = "n", axes = FALSE, xlab = "", ylab = "")
          text(1, 1, "Column names not recognized", cex = 1.2)
        }
      } else {
        plot(1, type = "n", axes = FALSE, xlab = "", ylab = "")
        text(1, 1, "No enrichment data available", cex = 1.2)
      }
    } else {
      plot(1, type = "n", axes = FALSE, xlab = "", ylab = "")
      text(1, 1, "No enrichment analysis performed", cex = 1.2)
    }
  })
  
