        dt <- DT::datatable(enrichment,
                            options = list(pageLength = 15, scrollX = TRUE),
                            rownames = FALSE,
                            filter = "top")
        
        # Try to format p-value columns
        pval_cols <- grep("P value|Adjusted", colnames(enrichment), ignore.case = TRUE)
        if (length(pval_cols) > 0) {
          dt <- dt %>% DT::formatSignif(columns = pval_cols, digits = 3)
        }
        
        return(dt)
      }
    }
    
    # Default message
    DT::datatable(data.frame(Message = "No pathway enrichment results available. Enable pathway enrichment in analysis settings."))
  })
  
