  # Network visualization
  output$ppi_standalone_network <- renderVisNetwork({
    req(rv_ppi_standalone$results)
    
    nodes <- rv_ppi_standalone$results$network_data$nodes
    edges <- rv_ppi_standalone$results$network_data$edges
    
    # Validate data
    if (is.null(nodes) || nrow(nodes) == 0) {
      nodes <- data.frame(
        id = "no_data",
        label = "No interactions found",
        value = 10,
        color = "#95A5A6",
        title = "No PPI data available",
        stringsAsFactors = FALSE
      )
      edges <- data.frame(
        from = character(0),
        to = character(0),
        value = numeric(0),
        stringsAsFactors = FALSE
      )
    }
    
    # Apply module colors if checkbox is checked
    color_by_module <- input$ppi_color_by_module %||% TRUE
    
    if (color_by_module && !is.null(rv_ppi_standalone$results$network_modules)) {
      modules <- rv_ppi_standalone$results$network_modules
      
      if (!is.null(modules) && nrow(modules) > 0) {
        # Create color palette for modules
        unique_modules <- sort(unique(modules$module))
        n_modules <- length(unique_modules)
        module_colors <- rainbow(n_modules, s = 0.7, v = 0.85)
        names(module_colors) <- as.character(unique_modules)
        
        # Map module to each node
        node_modules <- modules$module[match(nodes$id, modules$gene)]
        nodes$color <- sapply(node_modules, function(m) {
          if (is.na(m)) "#95A5A6" else module_colors[as.character(m)]
        })
        nodes$group <- paste0("Module ", node_modules)
      }
    }
    
    # Ensure color column exists
    if (!"color" %in% colnames(nodes)) {
      nodes$color <- "#2ECC71"  # Default green for input genes
    }
    
    # Adaptive physics based on network size
    n_nodes <- nrow(nodes)
    n_edges <- nrow(edges)

    # For large networks: reduce physics, disable smooth edges, limit labels
    if (n_nodes > 200) {
      # Very large network: disable physics after initial layout
      physics_opts <- list(
        stabilization = list(enabled = TRUE, iterations = 50),
        barnesHut = list(gravitationalConstant = -4000, springLength = 150, damping = 0.5)
      )
      edge_smooth <- list(enabled = FALSE)
      font_size <- 10
    } else if (n_nodes > 80) {
      physics_opts <- list(
        stabilization = list(enabled = TRUE, iterations = 80),
        barnesHut = list(gravitationalConstant = -6000, springLength = 180, damping = 0.3)
      )
      edge_smooth <- list(enabled = TRUE, type = "continuous")
      font_size <- 12
    } else {
      physics_opts <- list(
        stabilization = list(enabled = TRUE, iterations = 100),
        barnesHut = list(gravitationalConstant = -8000, springLength = 200)
      )
      edge_smooth <- list(enabled = TRUE, type = "continuous")
      font_size <- 14
    }

    visNetwork(nodes, edges) %>%
      visNodes(
        shape = "dot",
        scaling = list(min = 10, max = 30),
        font = list(size = font_size)
      ) %>%
      visEdges(
        color = list(color = "#cccccc", highlight = "#f093fb"),
        smooth = edge_smooth
      ) %>%
      visOptions(
        highlightNearest = list(enabled = TRUE, degree = 1, hover = TRUE),
        nodesIdSelection = TRUE
      ) %>%
      visLayout(randomSeed = 123) %>%
      visPhysics(
        stabilization = physics_opts$stabilization,
        barnesHut = physics_opts$barnesHut
      ) %>%
      visLegend(useGroups = TRUE, position = "right") %>%
      visEvents(stabilizationIterationsDone = "function() { this.setOptions({physics: false}); }")
  })
  
