  create_safe_node_title <- function(gene, degree, hub_type, gene_source, regulation, hub_score, betweenness) {
    
    # Safe value extraction with defaults
    safe_gene <- as.character(gene %||% "Unknown")[1]
    safe_degree <- as.numeric(degree %||% 0)[1]
    safe_hub_type <- as.character(hub_type %||% "Unknown")[1]
    safe_gene_source <- as.character(gene_source %||% "Unknown")[1]
    safe_regulation <- as.character(regulation %||% "Unknown")[1]
    safe_hub_score <- as.numeric(hub_score %||% 0)[1]
    safe_betweenness <- as.numeric(betweenness %||% 0)[1]
    
    # Build title safely
    title_parts <- c(
      sprintf("<b>%s</b>", safe_gene),
      sprintf("Degree: %d", safe_degree),
      sprintf("Hub Type: %s", safe_hub_type),
      sprintf("Source: %s", safe_gene_source)
    )
    
    # Add regulation if available and meaningful
    if (!is.na(safe_regulation) && safe_regulation != "Unknown" && safe_regulation != "") {
      title_parts <- c(title_parts, sprintf("Regulation: %s", safe_regulation))
    }
    
    # Add hub score if available
    if (!is.na(safe_hub_score) && is.finite(safe_hub_score)) {
      title_parts <- c(title_parts, sprintf("Hub Score: %.3f", safe_hub_score))
    }
    
    # Add betweenness if available
    if (!is.na(safe_betweenness) && is.finite(safe_betweenness)) {
      title_parts <- c(title_parts, sprintf("Betweenness: %.3f", safe_betweenness))
    }
    
    # Join with <br> tags
    return(paste(title_parts, collapse = "<br>"))
  }
  
  create_safe_edge_title <- function(gene_from, gene_to, combined_score) {
    
    safe_from <- as.character(gene_from %||% "Unknown")[1]
    safe_to <- as.character(gene_to %||% "Unknown")[1]
    safe_score <- as.numeric(combined_score %||% 0)[1]
    
    if (is.na(safe_score) || !is.finite(safe_score)) {
      safe_score <- 0
    }
    
    return(sprintf("Interaction: %s ↔ %s<br>Confidence: %.3f", safe_from, safe_to, safe_score))
  }
  
