  check_wgcna_packages <- function() {
    required_packages <- c("WGCNA", "dynamicTreeCut", "fastcluster")
    missing_packages <- c()
    
    for (pkg in required_packages) {
      if (!requireNamespace(pkg, quietly = TRUE)) {
        missing_packages <- c(missing_packages, pkg)
      }
    }
    
    if (length(missing_packages) > 0) {
      stop("❌ Missing required packages for WGCNA: ", paste(missing_packages, collapse = ", "),
           "\nInstall with: install.packages(c('", paste(missing_packages, collapse = "', '"), "'))")
    }
    
    return(TRUE)
  }
  
