  # Enhanced filtering function with consistent interface
  filter_significant_genes <- function(deg_data, pvalue_type, p_val_threshold, log2fc_min, log2fc_max, direction = "all") {
    
    # Debug information
    cat("=== filter_significant_genes DEBUG ===\n")
    cat("Direction:", direction, "\n")
    cat("P-value type:", pvalue_type, "\n")
    cat("P-value threshold:", p_val_threshold, "\n")
    cat("Log2FC range:", log2fc_min, "to", log2fc_max, "\n")
    cat("Input data rows:", nrow(deg_data), "\n")
    
    # Validate inputs
    if (is.null(deg_data) || nrow(deg_data) == 0) {
      cat("ERROR: No DEG data provided\n")
      return(data.frame())
    }
    
    # Get the correct p-value column
    if (pvalue_type == "adjusted") {
      pval_col <- "adj.P.Val"
    } else {
      pval_col <- "P.Value"
    }
    
    cat("Using p-value column:", pval_col, "\n")
    
    # Check if required columns exist
    required_cols <- c(pval_col, "log2FC", "gene_id")
    missing_cols <- required_cols[!required_cols %in% colnames(deg_data)]
    if (length(missing_cols) > 0) {
      cat("ERROR: Missing columns:", paste(missing_cols, collapse = ", "), "\n")
      cat("Available columns:", paste(colnames(deg_data), collapse = ", "), "\n")
      return(data.frame())
    }
    
    # Filter based on significance
    significant_genes <- deg_data[
      !is.na(deg_data[[pval_col]]) &
        deg_data[[pval_col]] < p_val_threshold &
        !is.na(deg_data$log2FC),
    ]
    
    cat("After p-value filtering:", nrow(significant_genes), "genes\n")
    
    # Apply fold change filtering based on direction
    if (direction == "up") {
      # Upregulated: log2FC > log2fc_max (positive threshold)
      filtered_genes <- significant_genes[significant_genes$log2FC > log2fc_max, ]
      cat("Filtering for upregulated genes (log2FC >", log2fc_max, "):", nrow(filtered_genes), "genes\n")
      
    } else if (direction == "down") {
      # Downregulated: log2FC < log2fc_min (negative threshold)
      filtered_genes <- significant_genes[significant_genes$log2FC < log2fc_min, ]
      cat("Filtering for downregulated genes (log2FC <", log2fc_min, "):", nrow(filtered_genes), "genes\n")
      
    } else {
      # All significant genes (outside the fold change range)
      filtered_genes <- significant_genes[
        significant_genes$log2FC < log2fc_min | significant_genes$log2FC > log2fc_max,
      ]
      cat("Filtering for all DEGs (outside FC range):", nrow(filtered_genes), "genes\n")
    }
    
    # Remove any rows with NA values
    filtered_genes <- filtered_genes[complete.cases(filtered_genes[, c(pval_col, "log2FC")]), ]
    
    cat("Final filtered genes:", nrow(filtered_genes), "\n")
    cat("Sample log2FC values:", paste(head(filtered_genes$log2FC, 5), collapse = ", "), "\n")
    cat("=====================================\n")
    
    return(filtered_genes)
  }
  
  
