                                 "danRer11" = "/genome_indices/danRer11/genome/genome.gtf",
                                 "wbcel235" = "/genome_indices/wbcel235/genome/genome.gtf",
                                 "r64" = "/genome_indices/r64/genome/genome.gtf",
                                 "araTha" = "/genome_indices/araTha/genome/genome.gtf",
                                 "galGal6" = "/genome_indices/galGal6/genome/genome.gtf",
                                 "susScr11" = "/genome_indices/susScr11/genome/genome.gtf",
                                 "custom" = "/custom_ref_files_mounted/annotation.gtf"
    )
    
    is_custom_genome <- input$genome_build == "custom"
    
