        input$custom_genome_name
      } else {
        "my_custom_genome" # Default if both are empty
      }
    } else {
      "" # Not used if not custom
    }
    # Sanitize the custom genome name for use in file paths/scripting
    custom_genome_name_sanitized <- gsub("[^a-zA-Z0-9_.-]", "_", custom_genome_name_for_script)
    
    trim_adapters_path_docker <- "/tools/Trimmomatic-0.39/adapters"
    
    trim_args <- if(input$sequencing_type == "paired") {
