    }
    
    script_parts <- c(
      "#!/bin/bash",
      "# TransXplorer: Fixed RNA-seq Analysis Pipeline Script",
      "# Generated with hanging issue fixes",
      "set -euo pipefail # Robust error handling",
      "",
      "# --- Configuration ---",
      "INPUT_FASTQ_DIR=\"input_fastq\" # Directory where user places their FASTQ files",
