                      "INPUT_FASTQ_ABS_PATH=\"${CURRENT_DIR}/${INPUT_FASTQ_DIR}\"",
                      "OUTPUT_ABS_PATH=\"${CURRENT_DIR}/${OUTPUT_DIR}\"",
                      "",
                      "echo \"INFO: Detected paths:\"",
                      "echo \"  - Working directory: ${CURRENT_DIR}\"",
                      "echo \"  - Input directory: ${INPUT_FASTQ_ABS_PATH}\"",
                      "echo \"  - Output directory: ${OUTPUT_ABS_PATH}\"",
                      "",
                      "# Detect environment type",
                      "ENV_TYPE=\"unknown\"",
