                      "  echo \"  $vol\"",
                      "done"
    )
    
    # =============================================================================
    # SIMPLIFIED DOCKER ENVIRONMENT TESTING (THE KEY FIX!)
    # =============================================================================
    
    script_parts <- c(script_parts,
                      "",
                      "# =============================================================================",
                      "# SIMPLIFIED DOCKER ENVIRONMENT TESTING",
                      "# =============================================================================",
                      "",
                      "echo \"INFO: Testing Docker environment...\"",
                      "",
                      "# Test 1: Quick Docker connectivity check",
                      "echo \"INFO: Checking Docker availability...\"",
                      "if ! docker --version >/dev/null 2>&1; then",
                      "  echo \"ERROR: Docker is not installed or not in PATH.\"",
                      "  echo \"Please install Docker from: https://docs.docker.com/get-docker/\"",
                      "  exit 1",
