  outputOptions(output, "has_batch_correction_plots", suspendWhenHidden = FALSE)
  
  # Dynamic instructions based on batch detection mode
  output$metadata_instructions_dynamic <- renderUI({
    current_mode <- input$batch_detection_mode %||% "auto"
    
    if (current_mode == "auto") {
      div(
        class = "alert alert-info",
        style = "margin-bottom: 20px; border-left: 4px solid #2196F3;",
        HTML("<strong>🔍 Automatic Detection Mode</strong><br>
             1. Review the metadata preview below<br>
             2. Select the <strong>Group</strong> column for DEG comparison<br>
             3. <span style='color: #2196F3;'><strong>Batch detection will run automatically</strong> - all other columns will be analyzed</span><br>
             4. Click <strong>Confirm</strong> to apply the configuration")
      )
    } else if (current_mode == "manual") {
      div(
        class = "alert alert-warning",
        style = "margin-bottom: 20px; border-left: 4px solid #ff9800;",
        HTML("<strong>📋 Manual Selection Mode</strong><br>
             1. Review the metadata preview below<br>
             2. Select the <strong>Group</strong> column for DEG comparison<br>
             3. Select the <strong>Batch</strong> column for batch effect correction<br>
             4. Click <strong>Confirm</strong> to apply the configuration")
      )
    } else {
      div(
        class = "alert alert-success",
        style = "margin-bottom: 20px; border-left: 4px solid #4caf50;",
        HTML("<strong>⏭️ Skip Mode</strong><br>
             1. Review the metadata preview below<br>
             2. Select the <strong>Group</strong> column for DEG comparison<br>
             3. <span style='color: #4caf50;'><strong>No batch correction</strong> will be applied</span><br>
             4. Click <strong>Confirm</strong> to apply the configuration")
      )
    }
  })
  
  showMetadataConfigModal <- function(metadata) {
    
    col_names <- colnames(metadata)
    trait_cols <- setdiff(col_names, "Sample")
    
    # Smart defaults: auto-detect Group and Batch columns
    default_group <- if ("Group" %in% col_names) {
      "Group"
    } else if ("group" %in% col_names) {
      "group"
    } else if ("Condition" %in% col_names) {
      "Condition"
    } else {
      trait_cols[1]
    }
    
    default_batch <- if ("Batch" %in% col_names) {
      "Batch"
