    ))
  }
  
  showSampleColumnSelectionModal <- function(metadata, detection_result, context = "batch") {
    
    col_names <- colnames(metadata)
    
    # Context-specific messaging
    title_text <- if (context == "batch") {
      "Select Sample Column (Batch Metadata)"
    } else {
      "Select Sample Column (Group Metadata)"
    }
    
    # Create recommendation text
    recommendation_ui <- if (detection_result$detected) {
      div(
        class = "alert alert-warning",
        style = "margin-bottom: 15px; font-size: 0.9em;",
        HTML(paste0(
          "<strong>⚠️ Low Confidence Detection</strong><br>",
          "We found a possible sample column: <code>", detection_result$column_name, "</code><br>",
          "Please verify this is correct or select a different column below."
        ))
      )
    } else {
      div(
        class = "alert alert-info",
        style = "margin-bottom: 15px; font-size: 0.9em;",
        HTML("<strong>ℹ️ Could Not Auto-Detect Sample Column</strong><br>
            Please select which column contains the sample identifiers.")
      )
    }
    
    showModal(modalDialog(
      title = div(
        style = "background: linear-gradient(135deg, #667eea 0%, #764ba2 100%); 
               color: white; padding: 15px; margin: -15px -15px 20px -15px; 
               border-radius: 5px 5px 0 0;",
        icon("columns"),
        paste(" ", title_text)
      ),
      size = "l",
      
      recommendation_ui,
      
      # Instructions
      div(
        class = "alert alert-secondary",
        style = "font-size: 0.9em; margin-bottom: 20px;",
        HTML("<strong>📋 What is a Sample Column?</strong><br>
            The sample column contains unique identifiers for each sample 
            that match the column names in your count matrix.<br><br>
            <strong>Examples:</strong> Sample1, Control_Rep1, Patient_001")
      ),
      
      # Metadata preview
      div(
        style = "background: #f8f9fa; padding: 15px; border-radius: 8px; margin-bottom: 20px;",
        
        h5(
          style = "color: #2196F3; margin-top: 0; margin-bottom: 10px;",
          icon("eye"),
          " Metadata Preview (First 10 Rows)"
        ),
        
        div(
          style = "max-height: 250px; overflow-y: auto; background: white; 
                 border: 1px solid #ddd; border-radius: 5px;",
          DTOutput("sample_column_preview_table")
        )
      ),
      
      # Column selection
      div(
        style = "background: #ffffff; padding: 20px; border: 2px solid #e3e6f0; 
               border-radius: 8px; margin-bottom: 20px;",
        
        h5(
          style = "color: #667eea; margin-top: 0; margin-bottom: 15px;",
          icon("hand-pointer"),
          " Select Sample Column"
        ),
        
        selectInput(
          "sample_column_select",
          "Which column contains sample identifiers?",
          choices = col_names,
          selected = if (detection_result$detected) detection_result$column_name else col_names[1],
          width = "100%"
        ),
        
        # Preview selected column values
        div(
          style = "margin-top: 15px;",
          uiOutput("sample_column_preview_values")
        )
      ),
      
      # Validation info (if count matrix exists)
      uiOutput("sample_column_validation_info"),
      
      footer = tagList(
        modalButton("Cancel", icon = icon("times")),
        actionButton(
          paste0("confirm_sample_column_", context),  # Context-specific button ID
          "Confirm Selection",
          class = "btn btn-primary",
          icon = icon("check"),
          style = "margin-left: 10px;"
        )
      ),
      
      easyClose = FALSE
    ))
    
    # Store context for confirmation handler
    rv_deg_main$sample_column_context <- context
  }
  
  #Metadata related codes
  observeEvent(input$metadata_file_deg_main, {
    req(input$metadata_file_deg_main)
    
    tryCatch({
      print("📂 Loading batch metadata file...")
      
      inFile <- input$metadata_file_deg_main
      
      # ✅ USE NEW ROBUST READER
      metadata <- read_metadata_file(inFile$datapath, inFile$name)
      
      # Basic validation
      if (nrow(metadata) == 0) {
        stop("Metadata file is empty")
      }
      
      if (ncol(metadata) < 2) {
        stop("Metadata must have at least 2 columns (Sample + at least one trait)")
      }
      
      print(paste("📊 Batch metadata loaded successfully"))
      
      # Smart Sample Column Detection
      sample_detection <- detect_sample_column(
        metadata, 
        if (!is.null(rv_deg_main$raw_counts)) colnames(rv_deg_main$raw_counts) else NULL
      )
      
      print(paste("🔍 Sample column detection:", sample_detection$message))
      
      # Store detection results
      rv_deg_main$metadata_raw_unprocessed <- metadata
      rv_deg_main$sample_column_detection <- sample_detection
      
      # Decision: Auto-proceed or ask user?
      if (sample_detection$detected && sample_detection$confidence %in% c("high", "medium")) {
        
        # AUTO-RENAME and proceed
        detected_col <- sample_detection$column_name
        metadata_processed <- metadata
        colnames(metadata_processed)[colnames(metadata_processed) == detected_col] <- "Sample"
        
        rv_deg_main$metadata_raw <- metadata_processed
        rv_deg_main$metadata_sample_column_confirmed <- TRUE
        
        showNotification(
          paste0("✅ ", sample_detection$message),
          type = "message", 
          duration = 5
        )
        
        print(paste("✅ Renamed '", detected_col, "' → 'Sample'"))
        
        # Show configuration modal
        showMetadataConfigModal(metadata_processed)
        
      } else {
        
        # LOW CONFIDENCE: Ask user
        rv_deg_main$metadata_raw <- NULL
        rv_deg_main$metadata_sample_column_confirmed <- FALSE
        
        showNotification(
          "⚠️ Please select which column contains sample identifiers",
          type = "warning",
          duration = 5
        )
        
        showSampleColumnSelectionModal(metadata, sample_detection, context = "batch")
      }
      
    }, error = function(e) {
      showNotification(
        paste("❌ Error loading batch metadata:", e$message),
        type = "error", 
        duration = 10
      )
      rv_deg_main$metadata_raw <- NULL
      rv_deg_main$metadata_raw_unprocessed <- NULL
    })
  })
  
  observeEvent(input$confirm_sample_column_batch, {
    confirmSampleColumn("batch")
  })
  
  observeEvent(input$confirm_sample_column_group, {
    confirmSampleColumn("group")
  })
  
  # Helper function
  confirmSampleColumn <- function(context) {
    req(input$sample_column_select)
    
    tryCatch({
      # Get metadata based on context
      if (context == "batch") {
        metadata <- rv_deg_main$metadata_raw_unprocessed
        if (is.null(metadata)) {
          showNotification("❌ No metadata loaded", type = "error", duration = 5)
          return()
        }
      } else if (context == "group") {
        metadata <- rv_deg_main$group_metadata_raw_unprocessed
        if (is.null(metadata)) {
          showNotification("❌ No group metadata loaded", type = "error", duration = 5)
          return()
        }
      } else {
        stop("Unknown context")
      }
      
      selected_col <- input$sample_column_select
      
      # Validate selection
      if (is.null(selected_col) || selected_col == "") {
        showNotification(
          "❌ Please select a sample column",
          type = "error",
          duration = 5
        )
        return()
      }
      
      # Check for duplicates
      sample_values <- metadata[[selected_col]]
      if (any(duplicated(sample_values))) {
        showNotification(
          "❌ Selected column contains duplicate values. Sample IDs must be unique.",
          type = "error",
          duration = 7
        )
        return()
      }
      
      # Check for NA values
      if (any(is.na(sample_values))) {
        showNotification(
          "❌ Selected column contains missing (NA) values. All samples must have IDs.",
          type = "error",
          duration = 7
        )
        return()
      }
      
      # Create processed metadata with renamed column
      metadata_processed <- metadata
      colnames(metadata_processed)[colnames(metadata_processed) == selected_col] <- "Sample"
      
      # Store based on context
      if (context == "batch") {
        rv_deg_main$metadata_raw <- metadata_processed
        rv_deg_main$metadata_sample_column_confirmed <- TRUE
        rv_deg_main$metadata_raw_unprocessed <- NULL  # Clear temporary storage
        
        print(paste("✅ Batch metadata sample column confirmed:", selected_col, "→ Sample"))
        print(paste("   Samples:", nrow(metadata_processed)))
        
        # Show success
        showNotification(
          paste0("✅ Sample column '", selected_col, "' confirmed!"),
          type = "message",
          duration = 3
        )
        
        # Close modal and show metadata config modal
        removeModal()
        showMetadataConfigModal(metadata_processed)
        
      } else if (context == "group") {
        rv_deg_main$group_metadata_raw <- metadata_processed
        rv_deg_main$group_metadata_raw_unprocessed <- NULL
        
        print(paste("✅ Group metadata sample column confirmed:", selected_col, "→ Sample"))
        print(paste("   Samples:", nrow(metadata_processed)))
        
        showNotification(
          paste0("✅ Sample column '", selected_col, "' confirmed!"),
          type = "message",
          duration = 3
        )
        
        removeModal()
        
        # ✅ CRITICAL FIX: Show group column selection modal immediately
        Sys.sleep(0.3)  # Brief delay for smooth transition
        showGroupColumnSelectionModal(metadata_processed)
      }
      
    }, error = function(e) {
      showNotification(
        paste("❌ Error confirming sample column:", e$message),
        type = "error",
        duration = 7
      )
    })
  }
  
  showGroupColumnSelectionModal <- function(metadata) {
    
    col_names <- colnames(metadata)
    trait_cols <- setdiff(col_names, "Sample")
    
    # Auto-detect group column
    default_group <- if ("Group" %in% col_names) {
      "Group"
    } else if ("group" %in% col_names) {
      "group"
    } else if ("Condition" %in% col_names) {
      "Condition"
    } else if ("condition" %in% col_names) {
      "condition"
    } else {
      trait_cols[1]
    }
    
    showModal(modalDialog(
      title = div(
        style = "background: #4caf50; color: white; padding: 15px; margin: -15px -15px 20px -15px;",
        icon("users"),
        " Select Group Column"
      ),
      size = "m",
      
      div(
        class = "alert alert-info",
        style = "font-size: 0.9em;",
        HTML("<strong>📋 Instructions:</strong><br>
           Select which column contains your <strong>group assignments</strong> 
           (e.g., Control, Treatment, Disease, Healthy)")
      ),
      
      selectInput(
        "group_column_for_grouping",
        "Which column contains group information?",
        choices = trait_cols,
        selected = default_group,
        width = "100%"
      ),
      
      # Preview group distribution
      uiOutput("group_column_preview_dist"),
      
      footer = tagList(
        modalButton("Cancel"),
        actionButton(
          "confirm_group_column_selection",
          "✅ Confirm Group Column",
          class = "btn btn-success"
        )
      ),
      easyClose = FALSE
    ))
  }
  
  output$group_column_preview_dist <- renderUI({
    req(rv_deg_main$group_metadata_raw, input$group_column_for_grouping)
    
    metadata <- rv_deg_main$group_metadata_raw
    group_col <- input$group_column_for_grouping
    
    group_counts <- table(metadata[[group_col]])
    
    div(
      style = "background: #f0f8ff; padding: 12px; border-radius: 5px; margin-top: 15px;",
      h6("📊 Group Distribution:", style = "color: #2196F3; margin-top: 0;"),
      HTML(paste0(
        "<ul style='margin-bottom: 0;'>",
        paste0("<li><strong>", names(group_counts), ":</strong> ", group_counts, " samples</li>", collapse = ""),
        "</ul>"
      ))
    )
  })
  
  observeEvent(input$confirm_group_column_selection, {
    req(rv_deg_main$group_metadata_raw, input$group_column_for_grouping)
    
    metadata <- rv_deg_main$group_metadata_raw
    group_col <- input$group_column_for_grouping
    
