    rv_deg_main$group_metadata_configured <- TRUE
    
    print("✅ Group metadata configured!")
    print(paste("   Group column:", group_col))
    print(paste("   Groups:", paste(unique(sample_groups_df$group), collapse = ", ")))
    
    removeModal()
    
    showNotification(
      "✅ Groups assigned successfully!",
      type = "message",
      duration = 3
    )
    
    # Update group selection UI
    update_group_selection_ui()
  })
  
  # Render preview table for sample column selection
  output$sample_column_preview_table <- renderDT({
    # Check which context we're in
    metadata <- if (!is.null(rv_deg_main$metadata_raw_unprocessed)) {
      rv_deg_main$metadata_raw_unprocessed  # Batch metadata
    } else if (!is.null(rv_deg_main$group_metadata_raw_unprocessed)) {
