  output$sample_column_validation_info <- renderUI({
    req(input$sample_column_select)
    
    # Only show if count matrix is loaded
    if (is.null(rv_deg_main$raw_counts)) {
      return(
        div(
          class = "alert alert-info",
          style = "margin-top: 10px; font-size: 0.9em;",
          HTML("ℹ️ <strong>Note:</strong> Count matrix not loaded yet. 
              Sample matching will be validated after you upload expression data.")
        )
      )
    }
    
    # Get metadata based on context
    metadata <- if (!is.null(rv_deg_main$metadata_raw_unprocessed)) {
      rv_deg_main$metadata_raw_unprocessed
    } else if (!is.null(rv_deg_main$group_metadata_raw_unprocessed)) {
      rv_deg_main$group_metadata_raw_unprocessed
    } else {
      return(NULL)
    }
    
    selected_col <- input$sample_column_select
    
    meta_samples <- as.character(metadata[[selected_col]])
    count_samples <- colnames(rv_deg_main$raw_counts)
    
    matched <- intersect(meta_samples, count_samples)
    missing_in_meta <- setdiff(count_samples, meta_samples)
    missing_in_counts <- setdiff(meta_samples, count_samples)
    
    match_ratio <- length(matched) / length(count_samples)
    
    # Determine alert class
    if (length(matched) == 0) {
      alert_class <- "alert alert-danger"
      icon_html <- "❌"
      title <- "No Matching Samples"
    } else if (match_ratio >= 0.9) {
      alert_class <- "alert alert-success"
      icon_html <- "✅"
      title <- "Excellent Match"
    } else if (match_ratio >= 0.5) {
      alert_class <- "alert alert-warning"
      icon_html <- "⚠️"
      title <- "Partial Match"
    } else {
      alert_class <- "alert alert-danger"
      icon_html <- "❌"
      title <- "Poor Match"
    }
    
    div(
      class = alert_class,
      style = "margin-top: 10px; font-size: 0.9em;",
      HTML(paste0(
        "<strong>", icon_html, " ", title, "</strong><br>",
        "• Matched samples: ", length(matched), " / ", length(count_samples), 
        " (", round(match_ratio * 100, 1), "%)<br>",
        if (length(missing_in_meta) > 0) {
          paste0("• Samples in counts but not in metadata: ", length(missing_in_meta), "<br>")
        },
        if (length(missing_in_counts) > 0) {
          paste0("• Samples in metadata but not in counts: ", length(missing_in_counts))
        }
      ))
    )
  })
  
