  observeEvent(input$edit_metadata_config, {
    req(rv_deg_main$metadata_raw)
    
    showMetadataConfigModal(rv_deg_main$metadata_raw)
  })
  
  observeEvent(input$confirm_metadata_config_modal, {
    req(rv_deg_main$metadata_raw,
        input$metadata_group_col_select_modal,
        input$metadata_group_col_select_modal != "")
    
    tryCatch({
      
      metadata <- rv_deg_main$metadata_raw
      
      # Validate if expression data exists
      if (!is.null(rv_deg_main$raw_counts)) {
        validation <- validate_metadata_with_expression(
          metadata,
          colnames(rv_deg_main$raw_counts)
        )
        
        if (!validation$valid) {
          showNotification(
            paste("❌ Cannot confirm:", paste(validation$issues, collapse = "; ")),
            type = "error", duration = 10
          )
          return()
        }
        
        # Filter metadata to only matched samples
        metadata_filtered <- metadata %>%
          dplyr::filter(Sample %in% validation$matched_samples)
        
      } else {
        # No expression data yet - use all metadata
        metadata_filtered <- metadata
        showNotification(
          "ℹ️ Metadata saved. Will be validated when you upload expression data.",
          type = "message", duration = 5
        )
      }
      
      # Store validated metadata
      rv_deg_main$metadata_validated <- metadata_filtered
      rv_deg_main$metadata_group_column <- input$metadata_group_col_select_modal
      rv_deg_main$metadata_batch_column <- if(input$metadata_batch_col_select_modal == "none") {
        NULL
      } else {
        input$metadata_batch_col_select_modal
      }
      rv_deg_main$metadata_covariates <- input$metadata_covariate_cols_select_modal
      rv_deg_main$metadata_configured <- TRUE
      
      # Create sample_groups dataframe for compatibility with existing code
      sample_groups_df <- data.frame(
        sample = trimws(metadata_filtered$Sample),
        group = trimws(metadata_filtered[[input$metadata_group_col_select_modal]]),
        stringsAsFactors = FALSE
      )
      
      # ================================================================
      # STORE ALL METADATA COLUMNS FOR AUTOMATIC BATCH DETECTION
      # ================================================================
      
      # Get current batch detection mode
      current_mode <- input$batch_detection_mode %||% "auto"
      
      if (current_mode == "auto") {
        # AUTOMATIC MODE: Store ALL metadata columns (except Sample and Group)
        # These will be analyzed for batch effects
        
        all_metadata_cols <- setdiff(colnames(metadata_filtered), 
                                     c("Sample", input$metadata_group_col_select_modal))
        
        for (col_name in all_metadata_cols) {
          sample_groups_df[[col_name]] <- trimws(as.character(metadata_filtered[[col_name]]))
        }
        
        print(paste("âœ… Automatic mode: Stored", length(all_metadata_cols), 
                    "additional columns for batch detection"))
        print(paste("   Columns:", paste(all_metadata_cols, collapse = ", ")))
        
      } else if (current_mode == "manual") {
        # MANUAL MODE: Only add the user-selected batch column
        
        if (!is.null(rv_deg_main$metadata_batch_column) && 
            rv_deg_main$metadata_batch_column != "none") {
          sample_groups_df$batch <- trimws(as.character(
            metadata_filtered[[rv_deg_main$metadata_batch_column]]
          ))
          print(paste("Manual mode: Using batch column:", rv_deg_main$metadata_batch_column))
        } else {
          print("Manual mode: No batch column selected")
        }
        
      } else {
        # SKIP MODE: No batch column needed
        print("Skip mode: No batch correction will be applied")
      }
      
      # Store in the format expected by existing DEG code
      rv_deg_main$sample_groups <- sample_groups_df
      
      # ✅ FIX: Reset dropdowns to clear old values
      reset_group_dropdowns()
      
      
      unique_new_groups <- unique(sample_groups_df$group)
      print(paste("🔄 Forcing dropdown update to:", paste(unique_new_groups, collapse = ", ")))
      
      # Update dropdowns immediately
      if (length(unique_new_groups) >= 2) {
        updateSelectInput(session, "reference_group_main_specific",
                          choices = unique_new_groups,
                          selected = unique_new_groups[1])
        
        updateSelectInput(session, "treatment_group_main_specific",
                          choices = unique_new_groups[-1],
                          selected = unique_new_groups[2])
      }
      
      # Update comparison method
      if (length(unique_new_groups) == 2) {
        updateSelectInput(session, "comparison_method_main",
                          choices = c("Simple (Two Groups)" = "simple"),
                          selected = "simple")
      } else {
        updateSelectInput(session, "comparison_method_main",
                          choices = c("Specific Comparison" = "specific",
                                      "All Pairwise Comparisons" = "pairwise"),
                          selected = "specific")
      }
      
      print("✅ Metadata configuration confirmed!")
      print(paste("   Group column:", rv_deg_main$metadata_group_column))
      print(paste("   Batch column:", rv_deg_main$metadata_batch_column %||% "None"))
      print(paste("   Samples:", nrow(sample_groups_df)))
      print(paste("   ✅ Dropdowns updated to:", paste(unique_new_groups, collapse = ", ")))
      
      rv_deg_main$groups_timestamp <- Sys.time()
      
      # Update the group selection UI (trigger existing code)
      if (exists("update_group_selection_ui")) {
        update_group_selection_ui()
      }
      
      # Close modal
      removeModal()
      
      showNotification(
        "✅ Metadata configured successfully! Groups and batches have been assigned.",
        type = "message", duration = 5
      )
      
      # Show summary in sidebar
      output$metadata_config_summary <- renderUI({
        div(
          style = "background: linear-gradient(135deg, #e8f5e8 0%, #c8e6c9 100%); 
                 padding: 12px; border-radius: 8px; margin-top: 10px; 
                 border-left: 4px solid #4caf50;",
          h6(
            style = "margin-top: 0; color: #2e7d32; font-weight: bold;",
            icon("check-circle"),
            " Metadata Configured"
          ),
          p(
            style = "margin-bottom: 5px; font-size: 0.9em;",
            HTML(paste0(
              "<strong>Samples:</strong> ", nrow(sample_groups_df), "<br>",
              "<strong>Groups:</strong> ", paste(unique(sample_groups_df$group), collapse = ", "), "<br>",
              if (!is.null(rv_deg_main$metadata_batch_column)) {
                paste0("<strong>Batches:</strong> ", 
                       length(unique(sample_groups_df$batch)), " detected")
              } else {
                "<strong>Batch:</strong> None"
              }
            ))
          ),
          actionButton(
            "edit_metadata_config",
            "✏️ Edit Configuration",
            class = "btn btn-sm btn-outline-primary",
            style = "margin-top: 5px;"
          )
        )
      })
      
      # Warnings if any
      if (!is.null(rv_deg_main$raw_counts)) {
        validation <- validate_metadata_with_expression(
          metadata,
          colnames(rv_deg_main$raw_counts)
        )
        
        if (length(validation$warnings) > 0) {
          showNotification(
            paste("⚠️", paste(validation$warnings, collapse = "; ")),
            type = "warning", duration = 7
          )
        }
      }
      
    }, error = function(e) {
      showNotification(
        paste("❌ Error confirming metadata:", e$message),
        type = "error", duration = 10
      )
    })
  })
  
  observeEvent(rv_deg_main$sample_groups, {
    if (!is.null(rv_deg_main$sample_groups)) {
      group_data <- rv_deg_main$sample_groups
      unique_groups <- unique(group_data$group)
      
      print("DEBUG: ========== SAMPLE GROUPS CHANGED ==========")
      print(paste("   Detected", length(unique_groups), "groups:", paste(unique_groups, collapse = ", ")))
      
      # Check if current dropdown values are valid
      current_ref <- input$reference_group_main_specific
      current_treat <- input$treatment_group_main_specific
      
      if (!is.null(current_ref)) {
        print(paste("   Current ref dropdown:", current_ref))
        if (!trimws(current_ref) %in% unique_groups) {
          print("   ⚠️ Reference dropdown has INVALID value - will be reset")
        }
      }
      
      if (!is.null(current_treat)) {
        print(paste("   Current treat dropdown:", current_treat))
        if (!trimws(current_treat) %in% unique_groups) {
          print("   ⚠️ Treatment dropdown has INVALID value - will be reset")
        }
      }
      
      print("DEBUG: ===============================================")
    }
  }, ignoreNULL = TRUE, priority = 100) 
  
  output$metadata_validation_status_modal <- renderUI({
    req(rv_deg_main$metadata_raw)
    
    # Check if expression data exists
    if (is.null(rv_deg_main$raw_counts)) {
      return(
        div(
          class = "alert alert-warning",
          style = "margin-bottom: 15px;",
          HTML("⚠️ <strong>Note:</strong> Count matrix not loaded yet. 
             Metadata will be validated after you upload expression data.")
        )
      )
    }
    
    # Perform validation
    validation <- validate_metadata_with_expression(
      rv_deg_main$metadata_raw,
      colnames(rv_deg_main$raw_counts)
    )
    
    if (!validation$valid) {
      return(
        div(
          class = "alert alert-danger",
          style = "margin-bottom: 15px;",
          HTML(paste0(
            "❌ <strong>Validation Failed:</strong><br>",
            paste("• ", validation$issues, collapse = "<br>")
          ))
        )
      )
    }
    
    # Success with potential warnings
    status_html <- paste0(
      "✅ <strong>Validation Passed:</strong> ",
      length(validation$matched_samples), " samples matched between metadata and expression data"
    )
    
    if (length(validation$warnings) > 0) {
      status_html <- paste0(
        status_html, "<br>",
        paste("⚠️ ", validation$warnings, collapse = "<br>")
      )
      alert_class <- "alert alert-warning"
    } else {
      alert_class <- "alert alert-success"
    }
    
    div(
      class = alert_class,
      style = "margin-bottom: 15px;",
      HTML(status_html)
    )
  })
  
  
  # Summary statistics after column selection FOR MODAL
  output$metadata_summary_stats_modal <- renderUI({
    req(rv_deg_main$metadata_raw, 
        input$metadata_group_col_select_modal, 
        input$metadata_group_col_select_modal != "")
    
    metadata <- rv_deg_main$metadata_raw
    group_col <- input$metadata_group_col_select_modal
    batch_col <- input$metadata_batch_col_select_modal
    
    # Group distribution
    group_counts <- table(metadata[[group_col]])
    group_summary <- paste0(
