  # Function to validate metadata against expression data
  validate_metadata_with_expression <- function(metadata_df, expression_colnames) {
    
    validation <- list(
      valid = TRUE,
      issues = character(0),
      warnings = character(0),
      matched_samples = character(0),
      missing_in_meta = character(0),
      missing_in_expr = character(0)
    )
    
    if (!"Sample" %in% colnames(metadata_df)) {
      validation$valid <- FALSE
      validation$issues <- c(validation$issues, "Metadata missing 'Sample' column")
      return(validation)
    }
    
    meta_samples <- as.character(metadata_df$Sample)
    expr_samples <- expression_colnames
    
    # Find mismatches
    validation$missing_in_meta <- setdiff(expr_samples, meta_samples)
    validation$missing_in_expr <- setdiff(meta_samples, expr_samples)
    validation$matched_samples <- intersect(meta_samples, expr_samples)
    
    # Determine if valid
    if (length(validation$matched_samples) < 2) {
      validation$valid <- FALSE
      validation$issues <- c(validation$issues, 
                             "Less than 2 samples matched between metadata and expression data")
    }
    
    # Add warnings for partial matches
    if (length(validation$missing_in_meta) > 0) {
      validation$warnings <- c(validation$warnings,
                               paste(length(validation$missing_in_meta), 
                                     "expression samples not found in metadata"))
    }
    
    if (length(validation$missing_in_expr) > 0) {
      validation$warnings <- c(validation$warnings,
                               paste(length(validation$missing_in_expr), 
                                     "metadata samples not found in expression data"))
    }
    
    return(validation)
  }
  
  
