  # Function to normalize data based on the selected method
  normalizeData <- function(data_input, method) { # Changed 'data' to 'data_input' for clarity
    # Ensure data_input is a matrix or data.frame at the start
    if (!is.matrix(data_input) && !is.data.frame(data_input)) {
      stop("normalizeData: Input must be a matrix or data.frame.")
    }
    
    original_rownames <- rownames(data_input)
    original_colnames <- colnames(data_input)
    
    # Convert to matrix for internal operations, ensure it's numeric
    data_matrix_for_norm <- as.matrix(data_input)
    if(!all(sapply(data_matrix_for_norm, is.numeric))) {
      print("Warning: Non-numeric data detected in normalizeData input. Attempting coercion.")
      # This can be risky, ensure your input data is clean upstream
      storage.mode(data_matrix_for_norm) <- "numeric"
      data_matrix_for_norm[is.na(data_matrix_for_norm)] <- 0 # Handle NAs from coercion
    }
    
    normalized_output_matrix <- NULL # Initialize
    
    if (method == "none") {
      normalized_output_matrix <- data_matrix_for_norm
    } else if (method == "TMM") {
      if (!requireNamespace("edgeR", quietly = TRUE)) stop("Package 'edgeR' needed for TMM normalization.")
      counts_for_tmm <- round(pmax(data_matrix_for_norm, 0))
      dge <- edgeR::DGEList(counts = counts_for_tmm)
      dge <- edgeR::calcNormFactors(dge, method = "TMM")
      normalized_output_matrix <- edgeR::cpm(dge, log = TRUE, prior.count = 1)
    } else if (method == "RLE") {
      # ... (your working RLE code - ensure it returns a matrix) ...
      if (!requireNamespace("DESeq2", quietly = TRUE)) stop("Package 'DESeq2' needed for RLE normalization.")
      counts_for_rle <- round(pmax(data_matrix_for_norm, 0))
      col_data_for_rle <- data.frame(row.names = original_colnames)
      suppressMessages({
        dds <- DESeq2::DESeqDataSetFromMatrix(countData = counts_for_rle, colData = col_data_for_rle, design = ~ 1)
        dds <- DESeq2::estimateSizeFactors(dds)
        normalized_output_matrix <- SummarizedExperiment::assay(DESeq2::vst(dds, blind = TRUE))
      })
    } else if (method == "VST") {
      # ✅ NEW: Variance Stabilizing Transformation
      if (!requireNamespace("DESeq2", quietly = TRUE)) {
        stop("Package 'DESeq2' needed for VST normalization.")
      }
      
      counts_for_vst <- round(pmax(data_matrix_for_norm, 0))
      col_data_for_vst <- data.frame(row.names = original_colnames)
      
      suppressMessages({
        dds <- DESeq2::DESeqDataSetFromMatrix(
          countData = counts_for_vst,
          colData = col_data_for_vst,
          design = ~ 1
        )
        
        # VST is faster than rlog and works well for large datasets
        normalized_output_matrix <- SummarizedExperiment::assay(
          DESeq2::vst(dds, blind = TRUE)
        )
      })
      
      print("✅ VST normalization complete")
      
    } else if (method == "quantile") {
      print("--- Inside Quantile Normalization ---")
      if (!requireNamespace("preprocessCore", quietly = TRUE)) stop("Package 'preprocessCore' needed.")
      if (nrow(data_matrix_for_norm) < 1 || ncol(data_matrix_for_norm) < 1) {
        stop("Quantile: Input data matrix is empty.")
      }
      
      # Handle potential NAs or all-zero columns BEFORE quantile normalization
      # If a column is all zeros, quantile normalization might still produce a constant column.
      # Adding a tiny offset to avoid log-transform issues later, though it's mainly for variance.
      data_matrix_for_norm[is.na(data_matrix_for_norm)] <- 0
      
      # Store dimnames
      dn <- dimnames(data_matrix_for_norm)
      print(paste("Quantile: Input dims:", paste(dim(data_matrix_for_norm), collapse="x")))
      
      # Perform normalization
      normalized_temp_matrix <- preprocessCore::normalize.quantiles(data_matrix_for_norm)
      
      # Restore dimnames
      dimnames(normalized_temp_matrix) <- dn
      
      normalized_output_matrix <- normalized_temp_matrix
      print("Quantile: Dimnames restored.")
      
    } else if (method == "upperquartile") {
      # ... (your working upperquartile code - ensure it returns a matrix) ...
      # Make sure to handle cases where a column might be all zeros or have no variance after offset
      temp_data <- data_matrix_for_norm + 1e-6
      uq <- apply(temp_data, 2, function(x) quantile(x, 0.75, na.rm = TRUE))
      uq[is.na(uq) | uq == 0] <- 1 # Avoid division by zero/NA
      mean_uq <- mean(uq, na.rm = TRUE)
      if(is.na(mean_uq) || mean_uq == 0) mean_uq <- 1
      scale_factors <- uq / mean_uq
      scale_factors[is.na(scale_factors) | scale_factors == 0 | !is.finite(scale_factors)] <- 1
      normalized_output_matrix <- sweep(temp_data, 2, scale_factors, FUN = "/") # temp_data was already a matrix
    } else {
      stop("Invalid normalization method selected.")
    }
    
    # Final cleanup: Ensure no NA/Inf/NaN values are propagated from normalization output
    normalized_output_matrix[is.na(normalized_output_matrix) | !is.finite(normalized_output_matrix)] <- 0
    
    final_data_df <- as.data.frame(normalized_output_matrix)
    
    # Ensure dimnames are still there after as.data.frame (they should be if matrix had them)
    if(!identical(rownames(final_data_df), original_rownames) && length(original_rownames) == nrow(final_data_df)){
      rownames(final_data_df) <- original_rownames
    }
    if(!identical(colnames(final_data_df), original_colnames) && length(original_colnames) == ncol(final_data_df)){
      colnames(final_data_df) <- original_colnames
    }
    
    print(paste("normalizeData returning for method '", method, "'. Class:", class(final_data_df), "Type:", typeof(final_data_df), "Dims:", paste(dim(final_data_df), collapse="x")))
    if(nrow(final_data_df) > 0 && ncol(final_data_df) > 0) print(head(final_data_df[,1:min(ncol(final_data_df), 3)]))
    
    return(final_data_df)
  }
  
