  validate_package_normalization <- function(package, normalization) {
    
    warnings <- c()
    
    if (package == "deseq2") {
      if (normalization %in% c("TMM", "quantile", "upperquartile")) {
        warnings <- c(warnings, 
                      "⚠️ DESeq2 uses built-in size factor normalization. The selected normalization method will be ignored for DEG analysis but used for QC plots.")
      }
    }
    
    if (package == "edgeR") {
      if (normalization == "VST") {
        warnings <- c(warnings,
                      "⚠️ VST is a DESeq2 method. For edgeR, consider using TMM normalization instead.")
      }
    }
    
    if (package == "limma") {
      if (normalization == "deseq2_default") {
        warnings <- c(warnings,
                      "⚠️ limma-voom works best with TMM normalization.")
      }
    }
    
    return(warnings)
  }
  
