  handle_matrix_data <- function(file_path, file_ext) {
    tryCatch({
      # Determine file extension if not provided
      if (missing(file_ext) || is.null(file_ext)) {
        file_ext <- tolower(tools::file_ext(file_path))
      }
      
      # Normalize file extension
      file_ext <- tolower(file_ext)
      
      print(paste("DEBUG: Reading file with extension:", file_ext))
      
      # Read data based on file extension with enhanced support
      if (file_ext %in% c("xlsx", "xls")) {
        # Excel files
        if (!requireNamespace("openxlsx", quietly = TRUE)) {
          stop("Package 'openxlsx' is required for Excel files. Please install it with: install.packages('openxlsx')")
        }
        data <- openxlsx::read.xlsx(file_path, rowNames = FALSE, check.names = FALSE)
        print(paste("DEBUG: Successfully read Excel file with", nrow(data), "rows and", ncol(data), "columns"))
        
      } else if (file_ext %in% c("tsv", "tab")) {
        # Tab-separated files
        data <- read.delim(file_path, header = TRUE, sep = "\t", check.names = FALSE,
                           stringsAsFactors = FALSE, quote = "")
        print(paste("DEBUG: Successfully read TSV file with", nrow(data), "rows and", ncol(data), "columns"))
        
      } else if (file_ext == "txt") {
        # Text files - auto-detect separator
        # First, peek at the file to determine separator
        first_line <- readLines(file_path, n = 1)
        
        if (grepl("\t", first_line)) {
          # Tab-separated
          data <- read.delim(file_path, header = TRUE, sep = "\t", check.names = FALSE,
                             stringsAsFactors = FALSE, quote = "")
          print("DEBUG: Detected tab-separated TXT file")
        } else if (grepl(",", first_line)) {
          # Comma-separated
          data <- read.csv(file_path, header = TRUE, sep = ",", check.names = FALSE,
                           stringsAsFactors = FALSE)
          print("DEBUG: Detected comma-separated TXT file")
        } else if (grepl(";", first_line)) {
          # Semicolon-separated (common in some regions)
          data <- read.csv(file_path, header = TRUE, sep = ";", check.names = FALSE,
                           stringsAsFactors = FALSE)
          print("DEBUG: Detected semicolon-separated TXT file")
        } else {
          # Default to comma-separated
          data <- read.csv(file_path, header = TRUE, sep = ",", check.names = FALSE,
                           stringsAsFactors = FALSE)
          print("DEBUG: Using default comma separation for TXT file")
        }
        print(paste("DEBUG: Successfully read TXT file with", nrow(data), "rows and", ncol(data), "columns"))
        
      } else {
        # CSV files (default)
        data <- read.csv(file_path, header = TRUE, sep = ",", check.names = FALSE,
                         stringsAsFactors = FALSE)
        print(paste("DEBUG: Successfully read CSV file with", nrow(data), "rows and", ncol(data), "columns"))
      }
      
      # Validate that data was read successfully
      if (is.null(data) || nrow(data) == 0 || ncol(data) == 0) {
        stop("File appears to be empty or could not be read properly")
      }
      
      # Handle gene column identification and duplicate processing
      gene_col_name <- NULL
      
      # Check for common gene column names (case-insensitive)
      possible_gene_cols <- c("gene_id", "Gene_ID", "GeneID", "gene", "Gene", "Symbol",
                              "gene_symbol", "Gene_Symbol", "GENE_ID", "GENE", "ID",
                              "Genes", "GeneName", "Gene_Name")
      
      # Case-insensitive search
      for (col_name in possible_gene_cols) {
        matching_cols <- colnames(data)[tolower(colnames(data)) == tolower(col_name)]
        if (length(matching_cols) > 0) {
          gene_col_name <- matching_cols[1]  # Take first match
          break
        }
      }
      
      # If no gene column found, assume first column contains genes
      if (is.null(gene_col_name)) {
        gene_col_name <- colnames(data)[1]
        message(paste("Using first column '", gene_col_name, "' as gene identifiers"))
      } else {
        message(paste("Found gene column:", gene_col_name))
      }
      
      # Extract gene identifiers and expression data
      gene_ids <- data[[gene_col_name]]
      expr_data <- data[, !colnames(data) %in% gene_col_name, drop = FALSE]
      
      # Convert gene IDs to character to handle mixed types
      gene_ids <- as.character(gene_ids)
      
      # Remove rows with empty/NA gene IDs
      valid_rows <- !is.na(gene_ids) & gene_ids != "" & gene_ids != "NA"
      if (sum(!valid_rows) > 0) {
        message(paste("Removing", sum(!valid_rows), "rows with missing gene IDs"))
        gene_ids <- gene_ids[valid_rows]
        expr_data <- expr_data[valid_rows, , drop = FALSE]
      }
      
      # Handle duplicate gene names
      if (any(duplicated(gene_ids))) {
        message(paste("Found", sum(duplicated(gene_ids)), "duplicate gene IDs. Aggregating by mean expression..."))
        
        # Combine gene IDs and expression data for aggregation
        temp_df <- cbind(gene_id = gene_ids, as.data.frame(expr_data))
        
        # Use aggregate to calculate the mean for each gene.
        # The formula . ~ gene_id means "calculate for all other columns, grouping by gene_id"
        aggregated_data <- aggregate(. ~ gene_id, data = temp_df, FUN = mean)
        
        # Set the unique gene IDs as rownames and remove the now-redundant 'gene_id' column
        rownames(aggregated_data) <- aggregated_data$gene_id
        aggregated_data$gene_id <- NULL
        
        # Update the main expr_data object with the aggregated data
        expr_data <- aggregated_data
        # Update gene_ids to the new unique rownames
        gene_ids <- rownames(expr_data)
        
        message(paste("Data aggregated. New dimensions:", nrow(expr_data), "unique genes x", ncol(expr_data), "samples"))
      }
      
      # Convert expression data to numeric where possible
      for (i in 1:ncol(expr_data)) {
        if (!is.numeric(expr_data[, i])) {
          # Try to convert to numeric
          numeric_version <- suppressWarnings(as.numeric(as.character(expr_data[, i])))
          if (!all(is.na(numeric_version))) {
            expr_data[, i] <- numeric_version
          }
        }
      }
      
      # Set row names to gene IDs
      rownames(expr_data) <- gene_ids
      
      # Final validation
      if (nrow(expr_data) == 0) {
        stop("No valid genes found in the file")
      }
      
      numeric_cols <- sapply(expr_data, is.numeric)
      if (sum(numeric_cols) == 0) {
        stop("No numeric expression data found. Please check your file format.")
      }
      
      message(paste("Successfully processed file:", nrow(expr_data), "genes,",
                    ncol(expr_data), "samples,", sum(numeric_cols), "numeric columns"))
      
      return(expr_data)
      
    }, error = function(e) {
      stop(paste("Error reading file:", e$message,
                 "\n\nSupported formats: CSV, XLSX, TSV, TXT",
                 "\nEnsure your file has a header row and gene identifiers in the first column."))
    })
  }
  
  detect_file_format <- function(file_path) {
    # Get file extension
    ext <- tolower(tools::file_ext(file_path))
    
    # Read first few lines to detect format
    if (ext == "txt") {
      first_lines <- readLines(file_path, n = 3, warn = FALSE)
      
      # Count separators in first line
      tab_count <- length(gregexpr("\t", first_lines[1])[[1]])
      comma_count <- length(gregexpr(",", first_lines[1])[[1]])
      semicolon_count <- length(gregexpr(";", first_lines[1])[[1]])
      
      if (tab_count > comma_count && tab_count > semicolon_count) {
        return(list(format = "tab-separated", separator = "\t"))
      } else if (semicolon_count > comma_count) {
        return(list(format = "semicolon-separated", separator = ";"))
      } else {
        return(list(format = "comma-separated", separator = ","))
      }
    }
    
    format_map <- list(
      "csv" = list(format = "comma-separated", separator = ","),
      "tsv" = list(format = "tab-separated", separator = "\t"),
      "tab" = list(format = "tab-separated", separator = "\t"),
      "xlsx" = list(format = "Excel", separator = "N/A"),
      "xls" = list(format = "Excel", separator = "N/A")
    )
    
    return(format_map[[ext]] %||% list(format = "unknown", separator = "unknown"))
  }
  
  validate_expression_file <- function(file_path) {
    # Basic file checks
    if (!file.exists(file_path)) {
      return(list(valid = FALSE, message = "File does not exist"))
    }
    
    file_size <- file.info(file_path)$size
    if (file_size == 0) {
      return(list(valid = FALSE, message = "File is empty"))
    }
    
    if (file_size > 500 * 1024 * 1024) {  # 500 MB limit
      return(list(valid = FALSE, message = "File is too large (>500MB). Please use a smaller file."))
    }
    
    # Format detection
    format_info <- detect_file_format(file_path)
    
    # Try to read first few rows
    tryCatch({
      ext <- tolower(tools::file_ext(file_path))
      
      if (ext %in% c("xlsx", "xls")) {
        preview <- openxlsx::read.xlsx(file_path, rows = 1:5, check.names = FALSE)
      } else if (ext == "tsv" || format_info$separator == "\t") {
        preview <- read.delim(file_path, header = TRUE, sep = "\t", nrows = 3)
      } else {
        sep <- format_info$separator
        preview <- read.csv(file_path, header = TRUE, sep = sep, nrows = 3)
      }
      
      # Check structure
      if (ncol(preview) < 2) {
        return(list(valid = FALSE, message = "File must have at least 2 columns (genes + samples)"))
      }
      
      if (nrow(preview) < 1) {
        return(list(valid = FALSE, message = "File must have at least 1 data row"))
      }
      
      return(list(
        valid = TRUE,
        message = paste("Valid", format_info$format, "file detected"),
        format = format_info$format,
        dimensions = paste(nrow(preview), "rows (preview),", ncol(preview), "columns")
      ))
      
    }, error = function(e) {
      return(list(valid = FALSE, message = paste("File reading error:", e$message)))
    })
  }
  
  assign_control_treatment_groups <- function(group_names) {
    # Convert to lowercase for pattern matching
    groups_lower <- tolower(group_names)
    
    # Define control patterns (most common control naming conventions)
    control_patterns <- c(
      "ctrl", "control", "con", "baseline", "untreated", "vehicle",
      "sham", "mock", "wild", "wt", "wildtype", "normal", "placebo",
      "dmso", "pbs", "saline", "neg", "negative",
      # MEDICAL/BIOLOGICAL CONTROLS
      "healthy", "normal", "non", "unaffected", "control"
    )
    
    # Define treatment patterns (most common treatment naming conventions)
    treatment_patterns <- c(
      "treat", "treatment", "drug", "compound", "dose", "inhibitor",
      "agonist", "knockout", "ko", "mutant", "overexpression", "oe",
      "stimulated", "activated", "induced", "tumor", "cancer", "disease",
      "mmtv", "lps", "ifn", "tnf",
      # MEDICAL CONDITIONS/DISEASES
      "patient", "case", "affected", "diseased", "pathological",
      # Specific disease abbreviations - ADD MORE AS NEEDED
      "pbc", "pbcs", "alzheimer", "diabetes", "hypertension", "covid",
      "stroke", "heart", "liver", "kidney", "lung", "brain"
    )
    
    control_group <- NULL
    treatment_group <- NULL
    
    # Method 1: Direct pattern matching
    for (group in group_names) {
      group_lower <- tolower(group)
      
      # Check if this group matches control patterns
      if (any(sapply(control_patterns, function(pattern) grepl(pattern, group_lower)))) {
        control_group <- group
      }
      
      # Check if this group matches treatment patterns
      if (any(sapply(treatment_patterns, function(pattern) grepl(pattern, group_lower)))) {
        treatment_group <- group
      }
    }
    
    # Method 2: If no clear patterns, use time-based heuristics
    if (is.null(control_group) && is.null(treatment_group)) {
      # Look for time indicators (baseline/pre vs post/time points)
      baseline_patterns <- c("0h", "0hr", "0d", "0day", "pre", "baseline", "t0")
      
      for (group in group_names) {
        group_lower <- tolower(group)
        if (any(sapply(baseline_patterns, function(pattern) grepl(pattern, group_lower)))) {
          control_group <- group
          break
        }
      }
    }
    
    # Method 3: IMPROVED alphabetical assignment with medical bias
    if (is.null(control_group) && is.null(treatment_group)) {
      # Check for common medical terminology patterns first
      medical_control_indicators <- c("healthy", "normal", "control", "wild", "baseline")
      medical_treatment_indicators <- c("patient", "disease", "tumor", "cancer", "mutant", "ko")
      
      # Try to identify control group first
      for (group in group_names) {
        group_lower <- tolower(group)
        if (any(sapply(medical_control_indicators, function(ind) grepl(ind, group_lower)))) {
          control_group <- group
          treatment_group <- group_names[!group_names %in% control_group][1]
          message("Medical terminology detected: using '", control_group, "' as control")
          break
        }
      }
      
      # If still no assignment, use alphabetical as last resort
      if (is.null(control_group)) {
        sorted_groups <- sort(group_names)
        control_group <- sorted_groups[1]
        treatment_group <- sorted_groups[2]
        
        message("WARNING: Could not automatically determine control vs treatment groups.")
        message("Using alphabetical assignment: '", control_group, "' as control, '", treatment_group, "' as treatment.")
        message("Please verify this is correct!")
      }
    } else if (is.null(control_group)) {
      # Found treatment but not control
      control_group <- group_names[!group_names %in% treatment_group][1]
    } else if (is.null(treatment_group)) {
      # Found control but not treatment
      treatment_group <- group_names[!group_names %in% control_group][1]
    }
    
    # Calculate confidence score
    confidence <- "low"
    if (!is.null(control_group) && !is.null(treatment_group)) {
      control_match <- any(sapply(control_patterns, function(p) grepl(p, tolower(control_group))))
      treatment_match <- any(sapply(treatment_patterns, function(p) grepl(p, tolower(treatment_group))))
      
      if (control_match && treatment_match) {
        confidence <- "high"
      } else if (control_match || treatment_match) {
        confidence <- "medium"
      }
    }
    
    return(list(
      reference = control_group,
      treatment = treatment_group,
      confidence = confidence
    ))
  }
  
