          tags$li("Expression values should be ", tags$strong("numeric"))
        ),
        
        h5(
          "✅ Example Format:",
          style = "color: #0056b3; margin-bottom: 8px;"
        ),
        
        div(
          style = "background-color: #f8f9fa; padding: 10px; border-radius: 5px; font-family: monospace; font-size: 12px;",
          HTML("gene_id,Sample1_Control,Sample2_Control,Sample3_Treatment,Sample4_Treatment<br/>
             GENE1,100,120,150,140<br/>
             GENE2,80,90,200,180<br/>
             GENE3,200,210,50,60")
        ),
        
        div(
          style = "margin-top: 10px; padding: 8px; background-color: #e8f5e8; border-radius: 3px; border-left: 4px solid #28a745;",
          HTML("<strong>💡 Pro Tip:</strong> Files up to 500MB are supported. Larger files will be automatically validated before processing.")
        )
      )
    } else {
      NULL  # Don't render anything when panel is hidden
    }
  })
  
  # --- 1. Data Loading and Initial Processing ---
  observeEvent(input$file_deg_main, {
    shinyjs::show("analysis_progress_main")
    
    # Update progress text properly
    progress_text_id <- "analysis_progress_main"
    
    # Create a proper progress text element that's visible
    isolate({
      shinyjs::html(progress_text_id, paste0(
        '<div class="progress-bar progress-bar-striped active" role="progressbar" style="width: 100%">',
        'Loading and processing matrix file...',
        '</div>'
      ))
    })
    
    on.exit({
      shinyjs::hide("analysis_progress_main")
      isolate({
        shinyjs::html(progress_text_id, paste0(
          '<div class="progress-bar progress-bar-striped active" role="progressbar" style="width: 100%">',
          'Processing...',
          '</div>'
        ))
      })
    })
    
    req(input$file_deg_main)
    inFile <- input$file_deg_main
    
    tryCatch({
      # CRITICAL FIX: Clear all previous state when new file is loaded
      print("DEBUG: Clearing previous state for new dataset")
      
      # Clear all reactive values related to groups and analysis
      rv_deg_main$sample_groups <- NULL
      rv_deg_main$auto_groups_detected <- NULL
      rv_deg_main$group_dialog_shown <- FALSE
      rv_deg_main$deg_results <- NULL
      rv_deg_main$normalized_counts <- NULL
      rv_deg_main$pca_plot <- NULL
      rv_deg_main$umap_plot <- NULL
      rv_deg_main$active_deg_comparison <- NULL
      rv_deg_main$has_multiple_comparisons <- FALSE
      rv_deg_main$confirmed_groups <- NULL
      rv_deg_main$deg_results_list <- NULL
      
      # Clear batch-related reactive values
      rv_deg_main$batch_detection_results <- NULL
      rv_deg_main$pca_plot_batch <- NULL
      rv_deg_main$pca_batch_before <- NULL
      rv_deg_main$pca_batch_after <- NULL
      rv_deg_main$umap_batch_before <- NULL
      rv_deg_main$umap_batch_after <- NULL
      
      # Clear metadata-related values
      rv_deg_main$metadata_raw <- NULL
      rv_deg_main$metadata_validated <- NULL
      rv_deg_main$metadata_configured <- FALSE
      rv_deg_main$metadata_group_column <- NULL
      rv_deg_main$metadata_batch_column <- NULL
      rv_deg_main$metadata_covariates <- NULL
      
      # Reset UI parameters to default values
      updateRadioButtons(session, "batch_detection_mode", selected = "auto")
      updateSelectInput(session, "normalization_method_main", selected = "TMM")
      updateSelectInput(session, "deg_package_main", selected = "edgeR")
      
      # Clear UI inputs that might persist from previous dataset
      updateSelectInput(session, "reference_group_main_specific",
                        choices = character(0), selected = character(0))
      updateSelectInput(session, "treatment_group_main_specific",
                        choices = character(0), selected = character(0))
      updateSelectInput(session, "comparison_method_main",
                        choices = c("Simple (Two Groups)" = "simple"),
                        selected = "simple")
      
      # Clear any group-related UI outputs
      output$group_confirmation_display <- renderUI(NULL)
      output$pairwise_info_display <- renderUI(NULL)
      
      # File validation first
      isolate({
        shinyjs::html(progress_text_id, paste0(
          '<div class="progress-bar progress-bar-striped active" role="progressbar" style="width: 10%">',
          'Validating file...',
          '</div>'
        ))
      })
      
      # Validate file using enhanced function
      validation <- validate_expression_file(inFile$datapath)
      if (!validation$valid) {
        showNotification(validation$message, type = "error", duration = 10)
        return(NULL)
      }
      
      # FIXED: Use correct showNotification syntax
      showNotification(
        paste("Reading", validation$format, "file..."),
        type = "message",
        duration = 3
      )
      
      # Update progress
      isolate({
        shinyjs::html(progress_text_id, paste0(
          '<div class="progress-bar progress-bar-striped active" role="progressbar" style="width: 30%">',
          'Reading file...',
          '</div>'
        ))
      })
      
      # Use enhanced file reading function
      file_ext <- tools::file_ext(inFile$name)  # Use original filename extension
      data <- handle_matrix_data(inFile$datapath, file_ext)
      
      # Update progress
      isolate({
        shinyjs::html(progress_text_id, paste0(
          '<div class="progress-bar progress-bar-striped active" role="progressbar" style="width: 70%">',
          'Validating data...',
          '</div>'
        ))
      })
      
      # Additional validation for DEG analysis
      if (ncol(data) < 2) {
        stop("At least 2 samples required for differential expression analysis")
      }
      
      # Check for numeric data
      numeric_cols <- sapply(data, is.numeric)
      if (sum(numeric_cols) < 2) {
        stop("At least 2 numeric sample columns required for analysis")
      }
      
      # Store processed data
      rv_deg_main$raw_counts <- data
      
      # Generate new fingerprint to track dataset changes
      new_fingerprint <- paste(
        nrow(data),
        ncol(data),
        paste(colnames(data), collapse = "_"),
        sep = "|"
      )
      
      # Check if dataset actually changed
      if (!identical(rv_deg_main$dataset_fingerprint, new_fingerprint)) {
        print("📊 New dataset detected - exploratory analysis required")
        rv_deg_main$dataset_fingerprint <- new_fingerprint
        rv_deg_main$exploratory_completed <- FALSE
        
        # Clear previous exploratory results (but keep metadata if still valid)
        rv_deg_main$normalized_counts <- NULL
        rv_deg_main$pca_plot <- NULL
        rv_deg_main$umap_plot <- NULL
        rv_deg_main$pca_batch_before <- NULL
        rv_deg_main$pca_batch_after <- NULL
        rv_deg_main$umap_batch_before <- NULL
        rv_deg_main$umap_batch_after <- NULL
        rv_deg_main$batch_detection_results <- NULL
        rv_deg_main$correction_assessment <- NULL
        rv_deg_main$exploratory_deconv <- NULL
        rv_deg_main$deg_results <- NULL
        rv_deg_main$deg_results_list <- NULL
      } else {
        print("📊 Same dataset dimensions - checking if exploratory results can be reused")
      }
      
      # Check if metadata is already configured
      if (!is.null(rv_deg_main$metadata_configured) && 
          rv_deg_main$metadata_configured == TRUE) {
        
        print("📋 Metadata already configured, skipping group dialog")
        
        # Re-validate and apply metadata to new data
        if (!is.null(rv_deg_main$metadata_validated)) {
          validation <- validate_metadata_with_expression(
            rv_deg_main$metadata_validated,
            colnames(rv_deg_main$raw_counts)
          )
          
          if (validation$valid) {
            # Reapply metadata groups
            metadata_filtered <- rv_deg_main$metadata_validated %>%
              dplyr::filter(Sample %in% validation$matched_samples)
            
            sample_groups_df <- data.frame(
              sample = trimws(metadata_filtered$Sample),
              group = trimws(metadata_filtered[[input$metadata_group_col_select_modal]]),
              stringsAsFactors = FALSE
            )
            
            # ================================================================
            # STORE ALL METADATA COLUMNS FOR AUTOMATIC BATCH DETECTION
            # ================================================================
            
            # Get current batch detection mode
            current_mode <- input$batch_detection_mode %||% "auto"
            
            if (current_mode == "auto") {
              # AUTOMATIC MODE: Store ALL metadata columns (except Sample and Group)
              # These will be analyzed for batch effects
              
              all_metadata_cols <- setdiff(colnames(metadata_filtered), 
                                           c("Sample", input$metadata_group_col_select_modal))
              
              for (col_name in all_metadata_cols) {
                sample_groups_df[[col_name]] <- trimws(as.character(metadata_filtered[[col_name]]))
              }
              
              print(paste("Automatic mode: Stored", length(all_metadata_cols), 
                          "additional columns for batch detection"))
              print(paste("   Columns:", paste(all_metadata_cols, collapse = ", ")))
              
            } else if (current_mode == "manual") {
              # MANUAL MODE: Only add the user-selected batch column
              
              if (!is.null(rv_deg_main$metadata_batch_column) && 
                  rv_deg_main$metadata_batch_column != "none") {
                sample_groups_df$batch <- trimws(as.character(
                  metadata_filtered[[rv_deg_main$metadata_batch_column]]
                ))
                print(paste("Manual mode: Using batch column:", rv_deg_main$metadata_batch_column))
              } else {
                print("Manual mode: No batch column selected")
              }
              
            } else {
              # SKIP MODE: No batch column needed
              print("Skip mode: No batch correction will be applied")
            }
            
            # Store in the format expected by existing DEG code
            rv_deg_main$sample_groups <- sample_groups_df
            
            showNotification(
              "✅ Metadata groups applied to new data",
              type = "message", duration = 3
            )
          } else {
            # Metadata doesn't match new data - fall back to dialog
            print("⚠️ Metadata doesn't match new data, showing group dialog")
            auto_detected <- detect_sample_groups(colnames(rv_deg_main$raw_counts))
            rv_deg_main$auto_groups_detected <- auto_detected
            showSampleGroupingDialog(colnames(rv_deg_main$raw_counts), auto_detected)
          }
        }
        
      } else {
        # No metadata configured - use existing underscore detection / manual dialog
        print("🔍 No metadata, using auto-detection")
        auto_detected <- detect_sample_groups(colnames(rv_deg_main$raw_counts))
        rv_deg_main$auto_groups_detected <- auto_detected
        showSampleGroupingDialog(colnames(rv_deg_main$raw_counts), auto_detected)
      }
      
      # NEW: Auto-trigger sample grouping dialog for new dataset
      if (ncol(data) >= 2) {
        print("DEBUG: Triggering sample grouping dialog for new dataset")
        
        # Detect potential groups from column names
        sample_names <- colnames(data)
        auto_detected <- detect_sample_groups(sample_names)
        rv_deg_main$auto_groups_detected <- auto_detected
        
        # Show the grouping dialog
        showSampleGroupingDialog(sample_names, auto_detected)
      }
      
      # Success notification
      showNotification(
        paste("File loaded! Please review sample grouping in the dialog."),
        type = "message",
        duration = 5
      )
      
      # Clear any existing results when new data is loaded
      rv_deg_main$deg_results <- NULL
      rv_deg_main$normalized_counts <- NULL
      rv_deg_main$pca_plot <- NULL
      rv_deg_main$umap_plot <- NULL
      rv_deg_main$active_deg_comparison <- NULL
      rv_deg_main$has_multiple_comparisons <- FALSE
      
    }, error = function(e) {
      # Enhanced error handling with FIXED showNotification
      error_msg <- paste("Error loading file:", e$message)
      
      # Show user-friendly error messages
      if (grepl("No numeric expression data found", e$message)) {
        error_msg <- "❌ File format error: No numeric expression data found. Please ensure your file contains numeric values in sample columns."
      } else if (grepl("No valid genes found", e$message)) {
        error_msg <- "❌ File format error: No valid gene identifiers found. Please ensure the first column contains gene IDs."
      } else if (grepl("Error reading file", e$message)) {
        error_msg <- paste("❌ File reading error:", e$message, "\n\nSupported formats: CSV, XLSX, TSV, TXT\nEnsure your file has a header row and gene IDs in the first column.")
      }
      
      # FIXED: Use correct showNotification parameters
      showNotification(error_msg, type = "error", duration = 15)
      
      # Clear data on error
      rv_deg_main$sample_groups <- NULL
      rv_deg_main$auto_groups_detected <- NULL
      rv_deg_main$raw_counts <- NULL
      
      print(paste("DEBUG: File loading error:", e$message))
    })
  })
  
  # ============================================================
  # GEO ACCESSION FETCH HANDLER
  # ============================================================
  observeEvent(input$fetch_geo_btn, {
    geo_id <- trimws(input$geo_accession_input %||% "")

    # Validate input
    if (nchar(geo_id) == 0) {
      showNotification("Please enter a GEO accession ID (e.g., GSE52778)", type = "error")
      return()
    }

    # Normalize ID
    geo_id <- toupper(geo_id)
    if (!grepl("^GSE[0-9]+$", geo_id)) {
      showNotification("Invalid GEO ID format. Please enter a Series ID like GSE52778.", type = "error")
      return()
    }

    # Disable button during fetch
    shinyjs::disable("fetch_geo_btn")
    shinyjs::runjs("
      var btn = document.getElementById('fetch_geo_btn');
      if (btn) { btn.dataset.originalHtml = btn.innerHTML;
        btn.innerHTML = '<i class=\"fa fa-spinner fa-spin\"></i> Fetching...';
        btn.classList.add('btn-disabled-running'); }
    ")
    on.exit({
      shinyjs::enable("fetch_geo_btn")
      shinyjs::runjs("
        var btn = document.getElementById('fetch_geo_btn');
        if (btn && btn.dataset.originalHtml) {
          btn.innerHTML = btn.dataset.originalHtml;
          btn.classList.remove('btn-disabled-running'); }
      ")
    }, add = TRUE)

    withProgress(message = paste("Fetching", geo_id, "from GEO..."), value = 0, {
      tryCatch({
        if (!requireNamespace("GEOquery", quietly = TRUE)) {
          stop("GEOquery package not installed. Please contact the administrator.")
        }

        setProgress(0.1, detail = "Downloading dataset metadata...")
        print(paste("GEO Fetch: Downloading", geo_id))

        # Download GEO dataset
        geo_data <- GEOquery::getGEO(geo_id, GSEMatrix = TRUE, getGPL = FALSE, destdir = tempdir())

        # Handle multi-platform datasets: merge phenotype data from ALL platforms
        geo_data_all <- NULL
        if (is.list(geo_data) && length(geo_data) > 1) {
          geo_data_all <- geo_data  # Keep all platforms for metadata merging
          platform_sizes <- sapply(geo_data, function(x) nrow(Biobase::pData(x)))
          best_idx <- which.max(platform_sizes)
          print(paste("GEO Fetch: Multi-platform dataset.", length(geo_data), "platforms.",
                      paste(platform_sizes, collapse = " + "), "=", sum(platform_sizes), "total samples"))
          geo_data <- geo_data[[best_idx]]
        } else if (is.list(geo_data) && length(geo_data) == 1) {
          geo_data <- geo_data[[1]]
        }

        setProgress(0.3, detail = "Checking data type...")

        # Extract phenotype/metadata — merge from ALL platforms if multi-platform
        if (!is.null(geo_data_all)) {
          pheno_list <- lapply(geo_data_all, function(x) Biobase::pData(x))
          # Find common columns across platforms
          common_cols <- Reduce(intersect, lapply(pheno_list, colnames))
          pheno <- do.call(rbind, lapply(pheno_list, function(p) p[, common_cols, drop = FALSE]))
          # Fix rownames — rbind mangles them with file prefixes; use geo_accession instead
          if ("geo_accession" %in% colnames(pheno)) {
            rownames(pheno) <- as.character(pheno$geo_accession)
          }
          print(paste("GEO Fetch: Merged phenotype from all platforms:", nrow(pheno), "samples,", length(common_cols), "common columns"))
        } else {
          pheno <- Biobase::pData(geo_data)
        }
        n_samples <- nrow(pheno)
        print(paste("GEO Fetch: Found", n_samples, "samples"))

        # Detect data type (RNA-seq vs microarray)
        data_type <- "unknown"
        all_processing <- paste(as.character(pheno$data_processing), collapse = " ")
        type_info <- tolower(paste(
          pheno$type[1] %||% "",
          pheno$platform_id[1] %||% "",
          all_processing,
          pheno$library_strategy[1] %||% "",
          collapse = " "
        ))

        is_rnaseq <- grepl("rna.?seq|high.?throughput|next.?gen|htseq|count|fpkm|tpm|rsem|star|salmon|kallisto|featurecount|sequenc",
                           type_info, ignore.case = TRUE)

        # --- ATTEMPT 0: Try NCBI-generated RNA-seq counts (standardized HISAT2/featureCounts pipeline) ---
        counts_data <- NULL
        metadata_df <- NULL

        tryCatch({
          ncbi_counts_url <- paste0(
            "https://www.ncbi.nlm.nih.gov/geo/download/?acc=", geo_id,
            "&type=rnaseq_counts&format=file&file=", geo_id,
            "_raw_counts_GRCh38.p13_NCBI.tsv.gz"
          )
          ncbi_dest <- file.path(tempdir(), paste0(geo_id, "_ncbi_raw_counts.tsv.gz"))
          setProgress(0.35, detail = "Checking for NCBI-processed counts...")

          # Use curl with -f to fail on HTTP errors (404 etc.)
          dl_result <- system2("curl", args = c("-sfL", "-o", ncbi_dest, shQuote(ncbi_counts_url)),
                               stdout = TRUE, stderr = TRUE)
          dl_exit <- attr(dl_result, "status") %||% 0

          if (dl_exit == 0 && file.exists(ncbi_dest) && file.size(ncbi_dest) > 1000) {
            # Verify it's actually gzipped data, not HTML
            file_type <- system2("file", args = ncbi_dest, stdout = TRUE)
            if (grepl("gzip", file_type, ignore.case = TRUE)) {
              setProgress(0.45, detail = "Loading NCBI-processed count matrix...")
              counts_data <- read.table(gzfile(ncbi_dest), header = TRUE, sep = "\t",
                                        row.names = 1, check.names = FALSE,
                                        stringsAsFactors = FALSE, comment.char = "")
              # Keep only numeric columns (GSM sample columns)
              numeric_cols <- sapply(counts_data, is.numeric)
              if (sum(numeric_cols) >= 2) {
                counts_data <- counts_data[, numeric_cols, drop = FALSE]
                data_type <- "rnaseq"
                print(paste("GEO Fetch: NCBI-processed counts loaded:", nrow(counts_data), "genes x", ncol(counts_data), "samples"))
              } else {
                counts_data <- NULL
              }
            }
          }
        }, error = function(e) {
          print(paste("GEO Fetch: NCBI counts not available:", e$message))
        })

        # --- ATTEMPT 1: Try submitter-supplied RNA-seq counts from supplementary files ---
        if (is.null(counts_data) && is_rnaseq) {
          setProgress(0.4, detail = "RNA-seq detected. Checking for count data...")

          tryCatch({
            supp_files <- GEOquery::getGEOSuppFiles(geo_id, makeDirectory = FALSE, baseDir = tempdir())
            if (!is.null(supp_files) && nrow(supp_files) > 0) {
              fnames <- tolower(basename(rownames(supp_files)))

              # Skip DE result files, RPKM files, and individual sample files
              skip_mask <- grepl("edger|deseq|diff|rpkm|fpkm|tpm|[_.-]cpm|_de[.-]|_vs_|pvalue|foldchange|logfc", fnames)
              candidate_files <- rownames(supp_files)[!skip_mask]

              # Look specifically for count/matrix files
              count_files <- candidate_files[grepl("count|raw_count|matrix|gene_expression|read_count",
                                                     tolower(basename(candidate_files)))]

              # Only use a generic fallback if we have a single large file
              if (length(count_files) == 0 && length(candidate_files) <= 3) {
                count_files <- candidate_files[grepl("\\.(txt|csv|tsv)(\\.gz)?$",
                                                       tolower(basename(candidate_files)))]
              }

              if (length(count_files) > 0) {
                setProgress(0.5, detail = "Loading count matrix...")
                # Pick the largest file (most likely the count matrix)
                file_sizes <- file.size(count_files)
                f <- count_files[which.max(file_sizes)]

                counts_data <- tryCatch({
                  if (grepl("\\.gz$", f)) {
                    con <- gzfile(f)
                  } else {
                    con <- f
                  }
                  # Try tab-separated first, then comma
                  tryCatch(
                    read.table(con, header = TRUE, sep = "\t", row.names = 1,
                               check.names = FALSE, stringsAsFactors = FALSE, nrows = 5),
                    error = function(e) NULL
                  )
                }, error = function(e) NULL)

                # If preview looks good (enough columns = enough samples), load full file
                if (!is.null(counts_data) && ncol(counts_data) >= max(2, n_samples * 0.5)) {
                  if (grepl("\\.gz$", f)) con <- gzfile(f) else con <- f
                  counts_data <- tryCatch(
                    read.table(con, header = TRUE, sep = "\t", row.names = 1,
                               check.names = FALSE, stringsAsFactors = FALSE),
                    error = function(e) tryCatch(
                      read.csv(if (grepl("\\.gz$", f)) gzfile(f) else f,
                               row.names = 1, check.names = FALSE, stringsAsFactors = FALSE),
                      error = function(e2) NULL
                    )
                  )
                } else {
                  counts_data <- NULL
                }

                if (!is.null(counts_data)) {
                  numeric_cols <- sapply(counts_data, is.numeric)
                  if (sum(numeric_cols) >= 2) {
                    counts_data <- counts_data[, numeric_cols, drop = FALSE]
                    print(paste("GEO Fetch: Loaded supplementary counts:", nrow(counts_data), "genes x", ncol(counts_data), "samples"))
                  } else {
                    counts_data <- NULL
                  }
                }
              }
            }
          }, error = function(e) {
            print(paste("GEO Fetch: Supplementary files check failed:", e$message))
          })
        }

        # --- ATTEMPT 2: Use expression matrix from series matrix (microarray or processed RNA-seq) ---
        if (is.null(counts_data)) {
          setProgress(0.5, detail = "Extracting expression matrix...")

          expr_matrix <- tryCatch({
            Biobase::exprs(geo_data)
          }, error = function(e) NULL)

          if (!is.null(expr_matrix) && nrow(expr_matrix) > 0 && ncol(expr_matrix) >= 2) {
            counts_data <- as.data.frame(expr_matrix)

            # Detect if these are log-transformed (microarray typical)
            max_val <- max(counts_data, na.rm = TRUE)
            if (max_val < 25) {
              # Likely log2-transformed microarray data
              data_type <- "microarray"
              print(paste("GEO Fetch: Microarray data detected (max value:", round(max_val, 1), ")"))
            } else {
              data_type <- "rnaseq"
              print(paste("GEO Fetch: Expression matrix loaded (max value:", round(max_val, 1), ")"))
            }
          }
        } else {
          data_type <- "rnaseq"
        }

        setProgress(0.65, detail = "Preparing metadata...")

        # --- BUILD METADATA (GEO2R-style) ---
        # Step 1: Parse characteristics_ch1* columns into proper key:value pairs
        # GEO stores metadata like "tissue: brain" or "patient diagnosis: type 2 diabetes"
        char_cols <- grep("^characteristics_ch", colnames(pheno), value = TRUE)
        parsed_chars <- data.frame(row.names = rownames(pheno))

        for (cc in char_cols) {
          vals <- as.character(pheno[[cc]])
          # Check if values contain "key: value" format
          if (any(grepl(":\\s", vals))) {
            # Extract the key from the first non-NA value
            first_val <- vals[!is.na(vals) & vals != ""][1]
            if (!is.na(first_val) && grepl(":\\s", first_val)) {
              col_key <- trimws(sub(":.*", "", first_val))
              col_values <- trimws(sub("^[^:]+:\\s*", "", vals))
              col_key_clean <- gsub("[^A-Za-z0-9_]", "_", col_key)
              parsed_chars[[col_key_clean]] <- col_values
            } else {
              parsed_chars[[cc]] <- vals
            }
          } else {
            parsed_chars[[cc]] <- vals
          }
        }

        # Step 2: Select useful columns from pheno (skip GEO internal columns)
        skip_patterns <- "^geo_accession$|^status$|^submission_date$|^last_update_date$|^contact|^supplementary|^relation$|^data_row_count$|^channel_count$|^platform_id$|^description$|^data_processing$|^extract_protocol|^hyb_protocol|^scan_protocol|^label_protocol|^taxid_ch|^label_ch|^molecule_ch|^library_|^characteristics_ch"
        meta_cols <- colnames(pheno)
        useful_cols <- meta_cols[!grepl(skip_patterns, meta_cols, ignore.case = TRUE)]

        # Always include title and source_name_ch1
        always_keep <- c("title", "source_name_ch1")
        useful_cols <- unique(c(intersect(always_keep, meta_cols), useful_cols))

        # Build metadata from pheno columns + parsed characteristics
        metadata_df <- pheno[, intersect(useful_cols, colnames(pheno)), drop = FALSE]
        if (ncol(parsed_chars) > 0) {
          metadata_df <- cbind(metadata_df, parsed_chars)
        }

        # Remove columns with no variation or all identical values
        informative <- sapply(metadata_df, function(col) {
          vals <- as.character(col)
          n_uniq <- length(unique(vals[!is.na(vals) & vals != ""]))
          n_uniq > 1 || n_uniq == 0  # keep columns with variation; also keep empty ones for now
        })
        # But always keep title and source_name_ch1
        keep_mask <- informative | colnames(metadata_df) %in% always_keep
        metadata_df <- metadata_df[, keep_mask, drop = FALSE]

        # Add Sample column
        metadata_df$Sample <- rownames(metadata_df)
        metadata_df <- metadata_df[, c("Sample", setdiff(colnames(metadata_df), "Sample")), drop = FALSE]

        print(paste("GEO Fetch: Metadata columns:", paste(colnames(metadata_df), collapse = ", ")))

        # --- CHECK IF COUNT DATA WAS FOUND ---
        if (is.null(counts_data) || nrow(counts_data) < 10 || ncol(counts_data) < 2) {
          showModal(modalDialog(
            title = tags$div(icon("exclamation-triangle", style = "color: #e67e22;"),
                             paste("No Count Matrix Found for", geo_id)),
            tags$div(
              div(class = "alert alert-warning", style = "margin-bottom: 12px;",
                  HTML(paste0(
                    "This dataset has <strong>", n_samples, " samples</strong> with metadata, ",
                    "but no processed count matrix is available in GEO for direct download."
                  ))
              ),
              tags$strong("Metadata found (", ncol(metadata_df) - 1, " columns):"),
              div(style = "max-height: 150px; overflow: auto; border: 1px solid #ddd; border-radius: 4px; margin: 8px 0; font-size: 0.85em;",
                  tags$table(style = "width: 100%; border-collapse: collapse;",
                    tags$thead(tags$tr(style = "background: #e9ecef;",
                      lapply(colnames(metadata_df)[1:min(6, ncol(metadata_df))], function(cn)
                        tags$th(style = "padding: 3px 6px; border: 1px solid #dee2e6;", cn))
                    )),
                    tags$tbody(lapply(1:min(3, nrow(metadata_df)), function(i) {
                      tags$tr(lapply(1:min(6, ncol(metadata_df)), function(j) {
                        val <- as.character(metadata_df[i, j])
                        if (nchar(val) > 30) val <- paste0(substr(val, 1, 27), "...")
                        tags$td(style = "padding: 2px 6px; border: 1px solid #dee2e6;", val)
                      }))
                    }))
                  )
              ),
              tags$hr(),
              tags$strong("What you can do:"),
              tags$ul(
                tags$li("Upload your own count matrix (CSV/TSV) and pair it with this metadata"),
                tags$li("Download raw FASTQ files from SRA and process them in the FASTQ Processing tab"),
                tags$li("Use ", tags$code("recount3"), " or ", tags$code("DEE2"), " for uniformly processed public data")
              )
            ),
            easyClose = TRUE, size = "l",
            footer = modalButton("Close")
          ))
          return()
        }

        setProgress(0.85, detail = "Loading into TransXplorer...")

        # --- CLEAR PREVIOUS STATE ---
        rv_deg_main$deg_results <- NULL
        rv_deg_main$up_regulated <- NULL
        rv_deg_main$down_regulated <- NULL
        rv_deg_main$raw_counts <- NULL
        rv_deg_main$normalized_counts <- NULL

        # --- STORE COUNTS ---
        # Clean gene IDs
        rownames(counts_data) <- gsub("\\.\\d+$", "", rownames(counts_data))
        rv_deg_main$raw_counts <- counts_data
        rv_deg_main$example_data_loaded <- FALSE
        rv_deg_main$data_fingerprint <- digest::digest(list(dim(counts_data), colnames(counts_data)))

        # --- STORE METADATA ---
        rv_deg_main$metadata_raw <- metadata_df
        rv_deg_main$metadata_sample_column_confirmed <- TRUE

        setProgress(0.95, detail = "Done!")

        # Show success with data type info
        type_badge <- if (data_type == "microarray") {
          "Microarray (log2-transformed values)"
        } else {
          "RNA-seq counts"
        }

        showNotification(
          HTML(paste0(
            "<strong>", geo_id, " loaded successfully!</strong><br>",
            "<small>", nrow(counts_data), " genes x ", ncol(counts_data), " samples<br>",
            "Data type: ", type_badge, "<br>",
            "Metadata: ", ncol(metadata_df) - 1, " sample attributes</small>"
          )),
          type = "message", duration = 8
        )

        # If microarray, show a note
        if (data_type == "microarray") {
          showNotification(
            HTML(paste0(
              "<strong>Note:</strong> This appears to be microarray data (log2-transformed). ",
              "DEG analysis will use <strong>limma on the log2 values</strong> (limma-trend), ",
              "whichever method is selected: edgeR, DESeq2 and limma-voom are for raw RNA-seq counts."
            )),
            type = "warning", duration = 12
          )
        }

        # For GEO data: show a modal so the user picks the grouping column from metadata
        # Store metadata and let the user choose; do NOT auto-assign groups
        rv_deg_main$sample_groups <- NULL
        rv_deg_main$geo_metadata_for_grouping <- metadata_df
        rv_deg_main$geo_loaded_id <- geo_id
        rv_deg_main$geo_n_genes <- nrow(counts_data)
        rv_deg_main$geo_n_samples <- ncol(counts_data)

        # Build column choices for group selection modal (skip Sample and file-like columns)
        group_col_choices <- setdiff(colnames(metadata_df), "Sample")
        # Filter out columns with file paths, URLs, or all-NA values
        group_col_choices <- group_col_choices[!sapply(group_col_choices, function(cc) {
          vals <- as.character(metadata_df[[cc]])
          any(grepl("\\.(gz|tsv|csv|txt|tar|zip|bam|fastq)$", vals, ignore.case = TRUE)) ||
            any(grepl("^https?://|^ftp://", vals, ignore.case = TRUE)) ||
            all(is.na(vals) | vals == "")
        })]

        # Score columns for best default: prefer columns with 2-6 unique values, short labels
        # (these are most likely experimental groups like diagnosis, treatment, condition)
        col_scores <- sapply(group_col_choices, function(cc) {
          vals <- as.character(metadata_df[[cc]])
          n_uniq <- length(unique(vals[!is.na(vals) & vals != ""]))
          avg_len <- mean(nchar(vals[!is.na(vals)]))
          # Ideal: 2-6 groups, short labels (<50 chars avg)
          if (n_uniq >= 2 && n_uniq <= 6 && avg_len < 50) return(100 - n_uniq)
          if (n_uniq >= 2 && n_uniq <= 10 && avg_len < 80) return(50 - n_uniq)
          if (n_uniq >= 2) return(10)
          return(0)
        })
        best_col <- group_col_choices[which.max(col_scores)]

        # Build a metadata preview (first 5 samples)
        preview_df <- metadata_df[seq_len(min(5, nrow(metadata_df))), , drop = FALSE]

        # Show the grouping modal with metadata preview
        showModal(modalDialog(
          title = HTML('<i class="fa fa-columns"></i> Select Sample Grouping Column'),
          size = "l",
          div(
            class = "alert alert-info",
            style = "margin-bottom: 15px;",
            HTML(paste0(
              '<strong>', geo_id, '</strong> loaded: ',
              nrow(counts_data), ' genes x ', ncol(counts_data), ' samples<br>',
              '<small>Metadata has ', length(group_col_choices), ' columns from GEO. ',
              'Select the column that defines your experimental groups.</small>'
            ))
          ),
          # Metadata preview table (static HTML)
          div(
            style = "margin-bottom: 15px; max-height: 220px; overflow: auto; border: 1px solid #ddd; border-radius: 4px; font-size: 0.85em;",
            tags$small(tags$strong(paste0("Metadata preview (first 5 of ", nrow(metadata_df), " samples):")),
                       style = "display: block; padding: 6px; background: #f0f0f0;"),
            tags$table(
              style = "width: 100%; border-collapse: collapse;",
              tags$thead(
                tags$tr(style = "background: #e9ecef;",
                        lapply(colnames(preview_df), function(cn) {
                          tags$th(style = "padding: 4px 8px; border: 1px solid #dee2e6; white-space: nowrap;", cn)
                        })
                )
              ),
              tags$tbody(
                lapply(seq_len(nrow(preview_df)), function(i) {
                  tags$tr(
                    lapply(seq_len(ncol(preview_df)), function(j) {
                      val <- as.character(preview_df[i, j])
                      if (nchar(val) > 40) val <- paste0(substr(val, 1, 37), "...")
                      tags$td(style = "padding: 3px 8px; border: 1px solid #dee2e6;", val)
                    })
                  )
                })
              )
            )
          ),
          selectInput("geo_group_column_select", "Grouping column:",
                      choices = group_col_choices,
                      selected = best_col),
          uiOutput("geo_group_preview"),
          footer = tagList(
            modalButton("Cancel"),
            actionButton("geo_confirm_groups", "Confirm Groups", class = "btn-success", icon = icon("check"))
          )
        ))

        print(paste("GEO Fetch: Successfully loaded", geo_id, "-", nrow(counts_data), "genes x", ncol(counts_data), "samples"))

      }, error = function(e) {
        print(paste("GEO Fetch Error:", e$message))

        error_msg <- e$message
        if (grepl("cannot open URL|HTTP|timeout|connection", error_msg, ignore.case = TRUE)) {
          showNotification("Network error: Could not connect to GEO. Please check your internet connection and try again.", type = "error", duration = 10)
        } else if (grepl("not found|does not exist|404", error_msg, ignore.case = TRUE)) {
          showNotification(paste0("GEO dataset '", geo_id, "' not found. Please check the accession ID."), type = "error", duration = 8)
        } else {
          showNotification(paste("Error fetching GEO data:", error_msg), type = "error", duration = 10)
        }
      })
    })
  })

  # GEO group column preview (shows what the selected column looks like)
  output$geo_group_preview <- renderUI({
    req(input$geo_group_column_select)
    req(rv_deg_main$geo_metadata_for_grouping)
    meta <- rv_deg_main$geo_metadata_for_grouping
    col <- input$geo_group_column_select
    if (!col %in% colnames(meta)) return(NULL)
    vals <- as.character(meta[[col]])
    grp_counts <- table(vals)
    n_groups <- length(grp_counts)
    div(
      style = "background: #f8f9fa; padding: 12px; border-radius: 6px; margin-top: 10px;",
      h5(paste("Preview:", n_groups, "groups detected"), style = "margin-top: 0;"),
      tags$table(
        style = "width: 100%; font-size: 0.9em;",
        tags$thead(tags$tr(tags$th("Group"), tags$th("Samples"))),
        tags$tbody(
          lapply(seq_along(grp_counts), function(i) {
            tags$tr(
              tags$td(style = "padding: 4px 8px;", names(grp_counts)[i]),
              tags$td(style = "padding: 4px 8px; font-weight: bold;", as.integer(grp_counts[i]))
            )
          })
        )
      ),
      if (n_groups < 2) p("Warning: need at least 2 groups. Try a different column.", style = "color: red; margin-top: 8px;")
    )
  })

  # GEO group confirmation handler
  observeEvent(input$geo_confirm_groups, {
    req(input$geo_group_column_select)
    req(rv_deg_main$geo_metadata_for_grouping)
    req(rv_deg_main$raw_counts)

    meta <- rv_deg_main$geo_metadata_for_grouping
    col <- input$geo_group_column_select
    count_samples <- colnames(rv_deg_main$raw_counts)

    # Align metadata to count matrix columns by Sample/rowname (GSM IDs)
    meta_samples <- meta$Sample
    shared <- intersect(count_samples, meta_samples)

    if (length(shared) == 0) {
      showNotification("No matching sample IDs between count data and metadata. Cannot assign groups.", type = "error")
      return()
    }

    if (length(shared) < length(count_samples)) {
      # Subset counts to only samples with metadata
      rv_deg_main$raw_counts <- rv_deg_main$raw_counts[, shared, drop = FALSE]
      rv_deg_main$geo_n_samples <- length(shared)
      print(paste("GEO: Subset counts to", length(shared), "samples with metadata (dropped",
                  length(count_samples) - length(shared), "without metadata)"))
      count_samples <- shared
    }

    # Get group values aligned to count matrix column order
    meta_ordered <- meta[match(count_samples, meta$Sample), , drop = FALSE]
    vals <- as.character(meta_ordered[[col]])

    if (length(unique(vals[!is.na(vals)])) < 2) {
      showNotification("Selected column has fewer than 2 groups. Pick a different column.", type = "error")
      return()
    }

    rv_deg_main$sample_groups <- data.frame(
      sample = count_samples,
      group = vals,
      stringsAsFactors = FALSE
    )
    rv_deg_main$auto_groups_detected <- list(
      method = "geo_metadata",
      groups = vals,
      unique_groups = unique(vals),
      confidence = "high",
      message = paste("Groups from GEO metadata column:", col)
    )

    # Also auto-populate the batch metadata from GEO metadata
    rv_deg_main$metadata_raw <- meta
    rv_deg_main$metadata_sample_column_confirmed <- TRUE

    removeModal()
    showNotification(
      HTML(paste0("Groups confirmed from <strong>", col, "</strong>: ",
                  paste(unique(vals), collapse = ", "))),
      type = "message", duration = 6
    )
    print(paste("GEO groups confirmed from column", col, ":",
                paste(unique(vals), collapse = ", ")))
  })

  # EXAMPLE COUNTS HANDLER
  # Mimics file upload - loads data and triggers grouping dialog
  # ============================================================
  observeEvent(input$load_example_counts_btn, {
    
    # Show progress indicator
    shinyjs::show("analysis_progress_main")
    
    on.exit({
      shinyjs::hide("analysis_progress_main")
    })
    
    tryCatch({
      # Define path to example counts
      example_counts_path <- file.path("data", "example_counts_GSE151427.csv")
      
      # Check if file exists
      if (!file.exists(example_counts_path)) {
        stop("Example counts file not found at: data/example_counts_GSE151427.csv")
      }
      
      showNotification("Loading example counts...", type = "message", duration = 2)
      
      # ========================================
      # STEP 1: Clear ALL previous state
      # (Exactly like file_deg_main handler)
      # ========================================
      print("DEBUG: Clearing previous state for example dataset")
      
      rv_deg_main$sample_groups <- NULL
      rv_deg_main$auto_groups_detected <- NULL
      rv_deg_main$group_dialog_shown <- FALSE
      rv_deg_main$deg_results <- NULL
      rv_deg_main$normalized_counts <- NULL
      rv_deg_main$pca_plot <- NULL
      rv_deg_main$umap_plot <- NULL
      rv_deg_main$active_deg_comparison <- NULL
      rv_deg_main$has_multiple_comparisons <- FALSE
      rv_deg_main$confirmed_groups <- NULL
      
      # Clear batch-related reactive values
      rv_deg_main$batch_detection_results <- NULL
      rv_deg_main$pca_plot_batch <- NULL
      rv_deg_main$pca_batch_before <- NULL
      rv_deg_main$pca_batch_after <- NULL
      rv_deg_main$umap_batch_before <- NULL
      rv_deg_main$umap_batch_after <- NULL
      
      # Clear metadata-related values
      rv_deg_main$metadata_raw <- NULL
      rv_deg_main$metadata_validated <- NULL
      rv_deg_main$metadata_configured <- FALSE
      rv_deg_main$metadata_group_column <- NULL
      rv_deg_main$metadata_batch_column <- NULL
      rv_deg_main$metadata_covariates <- NULL
      
      # Reset UI parameters
      updateRadioButtons(session, "batch_detection_mode", selected = "auto")
      updateSelectInput(session, "normalization_method_main", selected = "TMM")
      updateSelectInput(session, "deg_package_main", selected = "edgeR")
      
      # Clear UI inputs
      updateSelectInput(session, "reference_group_main_specific",
                        choices = character(0), selected = character(0))
      updateSelectInput(session, "treatment_group_main_specific",
                        choices = character(0), selected = character(0))
      updateSelectInput(session, "comparison_method_main",
                        choices = c("Simple (Two Groups)" = "simple"),
                        selected = "simple")
      
      # Clear group-related UI outputs
      output$group_confirmation_display <- renderUI(NULL)
      output$pairwise_info_display <- renderUI(NULL)
      
      # ========================================
      # STEP 2: Load data using handle_matrix_data()
      # THIS IS THE KEY FIX - use same function as file upload!
      # ========================================
      print(paste("DEBUG: Loading example counts from:", example_counts_path))
      
      # Use handle_matrix_data - same as file upload uses!
      data <- handle_matrix_data(example_counts_path, "csv")
      
      print(paste("DEBUG: Loaded data dimensions:", nrow(data), "x", ncol(data)))
      print(paste("DEBUG: First 5 rownames:", paste(head(rownames(data), 5), collapse = ", ")))
      print(paste("DEBUG: First 5 colnames:", paste(head(colnames(data), 5), collapse = ", ")))
      
      # ========================================
      # STEP 3: Validate (same as file upload)
      # ========================================
      if (ncol(data) < 2) {
        stop("At least 2 samples required for differential expression analysis")
      }
      
      numeric_cols <- sapply(data, is.numeric)
      if (sum(numeric_cols) < 2) {
        stop("At least 2 numeric sample columns required for analysis")
      }
      
      # ========================================
      # STEP 4: Store processed data
      # ========================================
      rv_deg_main$raw_counts <- data
      
      # ========================================
      # STEP 5: Trigger sample grouping dialog
      # (Same as file upload)
      # ========================================
      sample_names <- colnames(data)
      auto_detected <- detect_sample_groups(sample_names)
      rv_deg_main$auto_groups_detected <- auto_detected
      
      print("DEBUG: Triggering sample grouping dialog for example dataset")
      showSampleGroupingDialog(sample_names, auto_detected)
      
      # Flag that example data is loaded (for UI indicator)
      rv_deg_main$example_data_loaded <- TRUE
      
      # Success notification
      showNotification(
        HTML(paste0(
          "<strong>✓ Example counts loaded!</strong><br>",
          nrow(data), " genes × ", ncol(data), " samples<br>",
          "<em style='font-size: 0.9em;'>Please review sample grouping in the dialog</em>"
        )),
        type = "message",
        duration = 6
      )
      
      # Clear any existing results
      rv_deg_main$deg_results <- NULL
      rv_deg_main$normalized_counts <- NULL
      rv_deg_main$pca_plot <- NULL
      rv_deg_main$umap_plot <- NULL
      rv_deg_main$active_deg_comparison <- NULL
      rv_deg_main$has_multiple_comparisons <- FALSE

    }, error = function(e) {
      showNotification(
        HTML(paste0(
          "<strong>Error loading example counts</strong><br>",
          e$message, "<br>",
          "<em style='font-size: 0.85em;'>Ensure file exists at: data/example_counts_GSE151427.csv</em>"
        )),
        type = "error",
        duration = 10
      )
      
      # Clear data on error
      rv_deg_main$sample_groups <- NULL
      rv_deg_main$auto_groups_detected <- NULL
      rv_deg_main$raw_counts <- NULL
      
      print(paste("DEBUG: Example counts loading error:", e$message))
    })
  })
  # ============================================================
  # END EXAMPLE COUNTS HANDLER
  
  
  # EXAMPLE METADATA HANDLER
  # Mimics batch metadata file upload
  # ============================================================
  observeEvent(input$load_example_metadata_btn, {
    
    tryCatch({
      # Check if counts are loaded first
      if (is.null(rv_deg_main$raw_counts)) {
        showNotification(
          "⚠️ Please load the example counts first before loading metadata.",
          type = "warning",
          duration = 5
        )
        return()
      }
      
      # Define path to example metadata
      example_metadata_path <- file.path("data", "example_metadata_GSE151427.csv")
      
      if (!file.exists(example_metadata_path)) {
        stop("Example metadata file not found at: data/example_metadata_GSE151427.csv")
      }
      
      showNotification("Loading example metadata...", type = "message", duration = 2)
      
      print(paste("DEBUG: Loading example metadata from:", example_metadata_path))
      
      # Read metadata (same method as batch_metadata_file handler)
      metadata <- read_metadata_file(example_metadata_path, "example_metadata_GSE151427.csv")
      
      print(paste("DEBUG: Metadata dimensions:", nrow(metadata), "x", ncol(metadata)))
      print(paste("DEBUG: Metadata columns:", paste(colnames(metadata), collapse = ", ")))
      
      # Basic validation
      if (nrow(metadata) == 0) {
        stop("Metadata file is empty")
      }
      
      if (ncol(metadata) < 2) {
        stop("Metadata must have at least 2 columns (Sample + at least one trait)")
      }
      
      # Smart Sample Column Detection (same as batch_metadata_file handler)
      sample_detection <- detect_sample_column(
        metadata, 
        colnames(rv_deg_main$raw_counts)
      )
      
      print(paste("DEBUG: Sample column detection:", sample_detection$message))
      
      # Store detection results
      rv_deg_main$metadata_raw_unprocessed <- metadata
      rv_deg_main$sample_column_detection <- sample_detection
      
      # Process based on detection confidence (same logic as file upload)
      if (sample_detection$detected && sample_detection$confidence %in% c("high", "medium")) {
        # Auto-rename and proceed
        detected_col <- sample_detection$column_name
        metadata_processed <- metadata
        
        if (detected_col != "Sample") {
          colnames(metadata_processed)[colnames(metadata_processed) == detected_col] <- "Sample"
          print(paste("DEBUG: Renamed '", detected_col, "' → 'Sample'"))
        }
        
        rv_deg_main$metadata_raw <- metadata_processed
        rv_deg_main$metadata_sample_column_confirmed <- TRUE
        
        showNotification(
          paste0("✓ ", sample_detection$message),
          type = "message", 
          duration = 4
        )
        
        # Flag that example metadata is loaded (for UI indicator)
        rv_deg_main$example_metadata_loaded <- TRUE
        
        # Show configuration modal (same as file upload)
        showMetadataConfigModal(metadata_processed)
        
      } else {
        # Low confidence - ask user to select
        rv_deg_main$metadata_raw <- NULL
        rv_deg_main$metadata_sample_column_confirmed <- FALSE
        
        showNotification(
          "⚠️ Please select which column contains sample identifiers",
          type = "warning",
          duration = 5
        )
        
        showSampleColumnSelectionModal(metadata, sample_detection, context = "batch")
      }
      
    }, error = function(e) {
      showNotification(
        HTML(paste0(
          "<strong>Error loading example metadata</strong><br>",
          e$message, "<br>",
          "<em style='font-size: 0.85em;'>Ensure file exists at: data/example_metadata_GSE151427.csv</em>"
        )),
        type = "error",
        duration = 10
      )
      rv_deg_main$metadata_raw <- NULL
      rv_deg_main$metadata_raw_unprocessed <- NULL
      print(paste("DEBUG: Example metadata loading error:", e$message))
    })
  })
  # ============================================================
  # END EXAMPLE METADATA HANDLER
  
  observeEvent(input$file_deg_main, {
    rv_deg_main$example_data_loaded <- FALSE
    rv_deg_main$geo_loaded_id <- NULL
  }, priority = 100)  # High priority to run before main handler
  
  observeEvent(input$batch_metadata_file, {
    rv_deg_main$example_metadata_loaded <- FALSE
  }, priority = 100)
  
  # Add handler for the clear link:
  
  observeEvent(input$clear_example_data, {
    rv_deg_main$example_data_loaded <- FALSE
    rv_deg_main$raw_counts <- NULL
    rv_deg_main$sample_groups <- NULL
    rv_deg_main$geo_loaded_id <- NULL
    showNotification("Example data cleared", type = "message", duration = 3)
  })

  observeEvent(input$clear_geo_data, {
    rv_deg_main$geo_loaded_id <- NULL
    rv_deg_main$geo_n_genes <- NULL
    rv_deg_main$geo_n_samples <- NULL
    rv_deg_main$geo_metadata_for_grouping <- NULL
    rv_deg_main$raw_counts <- NULL
    rv_deg_main$sample_groups <- NULL
    rv_deg_main$metadata_raw <- NULL
    showNotification("GEO data cleared", type = "message", duration = 3)
  })
  
  
  # ============================================================
  # SESSION SAVE / RESTORE
  # ============================================================
  SESSION_DIR <- "/srv/transxplorer/sessions"
  SESSION_EXPIRY_DAYS <- 7

  # Generate a short run ID
  generate_run_id <- function() {
    chars <- c(LETTERS, 0:9)
    paste0("TX-", paste0(sample(chars, 6, replace = TRUE), collapse = ""))
  }

  # Save button appears only when there's data to save
  output$session_save_btn_ui <- renderUI({
    if (!is.null(rv_deg_main$raw_counts)) {
      actionButton("save_session_btn",
                   HTML('<i class="fa fa-save"></i> Save Session'),
                   class = "btn-sm btn-default",
                   style = "flex: 1; border-radius: 6px; border: 1px solid #81c784; color: #43a047; font-size: 0.85em; padding: 6px 10px;")
    }
  })

  # Open session modal
  observeEvent(input$open_session_modal, {
    showModal(modalDialog(
      title = HTML('<i class="fa fa-folder-open" style="color: #3949ab;"></i> Restore Saved Session'),
      size = "s",
      div(
        style = "padding: 10px 0;",
        p("Enter your session ID to restore a previous analysis:", style = "color: #555; margin-bottom: 12px;"),
        textInput("restore_session_id", NULL,
                  placeholder = "e.g. TX-A7K3M9",
                  width = "100%"),
        tags$small(style = "color: #999;", "Sessions are kept for 7 days after saving.")
      ),
      footer = tagList(
        modalButton("Cancel"),
        actionButton("restore_session_btn", "Restore",
                     class = "btn-success", icon = icon("undo"))
      ),
      easyClose = TRUE
    ))
  })

  # SAVE SESSION
  observeEvent(input$save_session_btn, {
    req(rv_deg_main$raw_counts)

    tryCatch({
      run_id <- generate_run_id()

      # Ensure directory exists
      if (!dir.exists(SESSION_DIR)) dir.create(SESSION_DIR, recursive = TRUE)

      # Collect all saveable state
      session_data <- list(
        saved_at = Sys.time(),
        expiry = Sys.time() + (SESSION_EXPIRY_DAYS * 86400),
        run_id = run_id,
        # Core data
        raw_counts = rv_deg_main$raw_counts,
        normalized_counts = rv_deg_main$normalized_counts,
        deg_results = rv_deg_main$deg_results,
        up_regulated = rv_deg_main$up_regulated,
        down_regulated = rv_deg_main$down_regulated,
        sample_groups = rv_deg_main$sample_groups,
        metadata_raw = rv_deg_main$metadata_raw,
        # Analysis settings
        geo_loaded_id = rv_deg_main$geo_loaded_id,
        example_data_loaded = rv_deg_main$example_data_loaded,
        # Batch detection
        batch_detection_results = rv_deg_main$batch_detection_results,
        correction_assessment = rv_deg_main$correction_assessment,
        # Network/advanced results — save only serializable data, not plot objects
        network_results = tryCatch({
          nr <- list()
          # Only save data frames and lists, skip render functions and HTML widgets
          for (key in c("current_results", "analysis_type", "analysis_status",
                        "grn_results", "ppi_results", "wgcna_results",
                        "drug_target_results", "disease_context_results",
                        "drug_discovery_results", "comprehensive_results",
                        "selected_genes", "available")) {
            val <- network_rv[[key]]
            if (!is.null(val) && !is.function(val) && !inherits(val, "shiny.tag")) {
              nr[[key]] <- val
            }
          }
          nr
        }, error = function(e) { print(paste("Session save - network error:", e$message)); NULL }),
        # Input settings to restore
        settings = list(
          organism = isolate(input$organism_deg_main),
          deg_method = isolate(input$deg_method_main),
          normalization = isolate(input$normalization_method_main)
        )
      )

      # Save to disk
      save_path <- file.path(SESSION_DIR, paste0(run_id, ".rds"))
      saveRDS(session_data, save_path)
      file_size <- round(file.size(save_path) / 1024 / 1024, 1)

      print(paste("Session saved:", run_id, "-", file_size, "MB"))

      # Show success modal with run ID
      showModal(modalDialog(
        title = HTML('<i class="fa fa-check-circle" style="color: #43a047;"></i> Session Saved'),
        size = "m",
        div(
          style = "text-align: center; padding: 10px 0;",
          p("Your analysis has been saved. Use this ID to restore it within 7 days:",
            style = "color: #555; margin-bottom: 15px;"),
          # Run ID display box
          div(
            id = "run-id-display",
            style = "background: #f5f5f5; border: 2px dashed #3949ab; border-radius: 12px;
                     padding: 20px; margin: 0 auto 15px; max-width: 300px; position: relative;",
            span(style = "font-family: 'Courier New', monospace; font-size: 2em; font-weight: 700;
                          color: #3949ab; letter-spacing: 3px;",
                 run_id),
            tags$br(),
            actionButton("copy_run_id", HTML('<i class="fa fa-copy"></i> Copy to Clipboard'),
                          class = "btn-sm btn-outline-primary",
                          style = "margin-top: 10px; border-radius: 15px; font-size: 0.85em;",
                          onclick = paste0("navigator.clipboard.writeText('", run_id, "').then(function(){",
                                           "var btn=document.getElementById('copy_run_id');",
                                           "btn.innerHTML='<i class=\"fa fa-check\"></i> Copied!';",
                                           "setTimeout(function(){btn.innerHTML='<i class=\"fa fa-copy\"></i> Copy to Clipboard';},2000);",
                                           "});"))
          ),
          # Session info
          div(style = "font-size: 0.85em; color: #888;",
            p(HTML(paste0(
              '<i class="fa fa-database"></i> ',
              nrow(rv_deg_main$raw_counts), ' genes x ', ncol(rv_deg_main$raw_counts), ' samples<br>',
              '<i class="fa fa-clock"></i> Expires: ', format(Sys.time() + (SESSION_EXPIRY_DAYS * 86400), "%B %d, %Y"), '<br>',
              '<i class="fa fa-hdd"></i> Size: ', file_size, ' MB'
            )))
          )
        ),
        footer = modalButton("Close"),
        easyClose = TRUE
      ))

    }, error = function(e) {
      showNotification(paste("Failed to save session:", e$message), type = "error", duration = 8)
      print(paste("Session save error:", e$message))
    })
  })

  # RESTORE SESSION
  observeEvent(input$restore_session_btn, {
    run_id <- trimws(toupper(input$restore_session_id %||% ""))

    if (nchar(run_id) == 0) {
      showNotification("Please enter a session ID", type = "warning")
      return()
    }

    # Normalize format
    if (!grepl("^TX-", run_id)) run_id <- paste0("TX-", run_id)

    save_path <- file.path(SESSION_DIR, paste0(run_id, ".rds"))

    if (!file.exists(save_path)) {
      showNotification(
        HTML(paste0("Session <strong>", run_id, "</strong> not found. It may have expired or the ID may be incorrect.")),
        type = "error", duration = 6)
      return()
    }

    # Disable button during restore
    shinyjs::disable("restore_session_btn")
    on.exit(shinyjs::enable("restore_session_btn"), add = TRUE)

    tryCatch({
      withProgress(message = "Restoring session...", value = 0, {
        session_data <- readRDS(save_path)

        # Check expiry
        if (!is.null(session_data$expiry) && Sys.time() > session_data$expiry) {
          file.remove(save_path)
          showNotification("This session has expired and has been removed.", type = "warning", duration = 6)
          return()
        }

        incProgress(0.2, detail = "Loading expression data...")

        # Restore core data
        rv_deg_main$raw_counts <- session_data$raw_counts
        rv_deg_main$normalized_counts <- session_data$normalized_counts
        rv_deg_main$sample_groups <- session_data$sample_groups
        rv_deg_main$metadata_raw <- session_data$metadata_raw
        rv_deg_main$geo_loaded_id <- session_data$geo_loaded_id
        rv_deg_main$example_data_loaded <- session_data$example_data_loaded %||% FALSE

        incProgress(0.4, detail = "Loading DEG results...")

        rv_deg_main$deg_results <- session_data$deg_results
        rv_deg_main$up_regulated <- session_data$up_regulated
        rv_deg_main$down_regulated <- session_data$down_regulated

        incProgress(0.6, detail = "Loading batch detection...")

        rv_deg_main$batch_detection_results <- session_data$batch_detection_results
        rv_deg_main$correction_assessment <- session_data$correction_assessment

        incProgress(0.8, detail = "Loading advanced analysis results...")

        # Restore network/advanced results if available
        if (!is.null(session_data$network_results)) {
          nr <- session_data$network_results
          print(paste("Restoring network results:", paste(names(nr), collapse = ", ")))
          for (nm in names(nr)) {
            tryCatch({
              network_rv[[nm]] <- nr[[nm]]
              print(paste("  Restored:", nm))
            }, error = function(e) {
              print(paste("  Failed to restore", nm, ":", e$message))
            })
          }
        }

        # Restore input settings
        if (!is.null(session_data$settings)) {
          s <- session_data$settings
          if (!is.null(s$organism)) updateSelectInput(session, "organism_deg_main", selected = s$organism)
          if (!is.null(s$deg_method)) updateSelectInput(session, "deg_method_main", selected = s$deg_method)
          if (!is.null(s$normalization)) updateSelectInput(session, "normalization_method_main", selected = s$normalization)
        }

        incProgress(1.0, detail = "Done!")

        # Calculate what was restored
        has_deg <- !is.null(session_data$deg_results)
        has_network <- !is.null(session_data$network_results) &&
          any(!sapply(session_data$network_results, is.null))
        n_genes <- if (!is.null(session_data$raw_counts)) nrow(session_data$raw_counts) else 0
        n_samples <- if (!is.null(session_data$raw_counts)) ncol(session_data$raw_counts) else 0
        saved_ago <- round(difftime(Sys.time(), session_data$saved_at, units = "hours"), 1)

        showModal(modalDialog(
          title = HTML('<i class="fa fa-check-circle" style="color: #43a047;"></i> Session Restored'),
          size = "m",
          div(
            style = "text-align: center; padding: 10px 0;",
            div(style = "background: #e8f5e9; border-radius: 10px; padding: 15px; margin-bottom: 15px;",
              span(style = "font-family: 'Courier New', monospace; font-size: 1.5em; font-weight: 700; color: #2e7d32;",
                   run_id)
            ),
            tags$table(style = "margin: 0 auto; text-align: left; font-size: 0.9em;",
              tags$tr(tags$td(style = "padding: 4px 12px; color: #888;", "Data:"),
                      tags$td(style = "padding: 4px 12px; font-weight: 600;",
                              paste0(n_genes, " genes x ", n_samples, " samples"))),
              tags$tr(tags$td(style = "padding: 4px 12px; color: #888;", "DEG Results:"),
                      tags$td(style = "padding: 4px 12px;",
                              if (has_deg) HTML('<span style="color: #43a047;">Restored</span>')
                              else HTML('<span style="color: #999;">Not available</span>'))),
              tags$tr(tags$td(style = "padding: 4px 12px; color: #888;", "Advanced Analysis:"),
                      tags$td(style = "padding: 4px 12px;",
                              if (has_network) HTML('<span style="color: #43a047;">Restored</span>')
                              else HTML('<span style="color: #999;">Not available</span>'))),
              tags$tr(tags$td(style = "padding: 4px 12px; color: #888;", "Saved:"),
                      tags$td(style = "padding: 4px 12px;", paste0(saved_ago, " hours ago")))
            )
          ),
          footer = modalButton("Continue Analysis"),
          easyClose = TRUE
        ))

        print(paste("Session restored:", run_id, "-", n_genes, "genes x", n_samples, "samples"))
      })

    }, error = function(e) {
      showNotification(paste("Failed to restore session:", e$message), type = "error", duration = 8)
      print(paste("Session restore error:", e$message))
    })
  })

  # CLEANUP old sessions (runs once per app startup)
  tryCatch({
    if (dir.exists(SESSION_DIR)) {
      session_files <- list.files(SESSION_DIR, pattern = "\\.rds$", full.names = TRUE)
      for (sf in session_files) {
        tryCatch({
          sd <- readRDS(sf)
          if (!is.null(sd$expiry) && Sys.time() > sd$expiry) {
            file.remove(sf)
            print(paste("Cleaned expired session:", basename(sf)))
          }
        }, error = function(e) {
          # Corrupt file — remove it
          file.remove(sf)
        })
      }
    }
  }, error = function(e) NULL)

