      # ========================================
      removeNotification(loading_id)
      
      # Calculate summary stats for notification
      n_genes <- nrow(example_counts)
      n_samples <- ncol(example_counts)
      n_groups <- if (!is.na(group_col)) length(unique(example_metadata[[group_col]])) else 1
      group_names <- if (!is.na(group_col)) paste(unique(example_metadata[[group_col]]), collapse = ", ") else "N/A"
      batch_info <- if (!is.na(batch_col)) paste0("Batch: ", batch_col, " (", 
                                                  length(unique(example_metadata[[batch_col]])), " levels)") else "No batch column"
      
      showNotification(
        HTML(paste0(
          "<div style='line-height: 1.6;'>",
          "<strong style='font-size: 1.1em; color: #2e7d32;'>✓ Example Dataset Loaded</strong><br>",
          "<span style='color: #555;'>",
          "• <strong>", n_genes, "</strong> genes × <strong>", n_samples, "</strong> samples<br>",
          "• Groups: ", group_names, "<br>",
          "• ", batch_info, "<br>",
          "<em style='color: #888;'>Source: GEO GSE151427</em>",
          "</span></div>"
        )),
        type = "message",
        duration = 12
      )
      
      # ========================================
      # STEP 9: Update group confirmation UI
      # ========================================
      output$group_confirmation_display <- renderUI({
        div(
          class = "alert alert-success",
          style = "
            margin-top: 15px; 
            border-left: 4px solid #28a745; 
            border-radius: 8px;
            background: linear-gradient(135deg, #d4edda 0%, #c3e6cb 100%);
          ",
          div(
            style = "display: flex; align-items: flex-start;",
            icon("check-circle", 
                 style = "font-size: 1.8em; margin-right: 12px; color: #28a745; margin-top: 3px;"),
            div(
              strong("Example dataset loaded successfully!", style = "font-size: 1.05em;"),
              br(),
              tags$small(
                style = "color: #155724;",
                HTML(paste0(
                  "GEO: GSE151427 | ",
                  n_genes, " genes × ", n_samples, " samples<br>",
                  "Groups: ", group_names, " | ", batch_info
                ))
              ),
              br(),
              tags$small(
                style = "color: #666; font-style: italic;",
                "Metadata automatically configured for batch correction analysis"
