  detect_sample_groups <- function(sample_names) {
    # Strategy 1: Look for underscore patterns (Sample1_Control, Sample2_Treatment)
    if (any(grepl("_", sample_names))) {
      groups_from_underscore <- sub(".*_", "", sample_names)
      unique_groups <- unique(groups_from_underscore)
      
      if (length(unique_groups) >= 2 && length(unique_groups) <= length(sample_names)/2) {
        return(list(
          method = "underscore",
          groups = groups_from_underscore,
          unique_groups = unique_groups,
          confidence = "high",
          message = "Groups detected from sample names (Sample_Group format)"
        ))
      }
    }
    
    # Strategy 2: Look for common prefixes/suffixes
    prefixes <- sapply(sample_names, function(x) substr(x, 1, nchar(x)-1))
    suffixes <- sapply(sample_names, function(x) substr(x, 2, nchar(x)))
    
    if (length(unique(prefixes)) < length(sample_names) && length(unique(prefixes)) >= 2) {
      return(list(
        method = "prefix",
        groups = prefixes,
        unique_groups = unique(prefixes),
        confidence = "medium",
        message = "Potential groups detected from sample prefixes"
      ))
    }
    
    # Strategy 3: Look for numbers (Sample1, Sample2, Sample3, Sample4 -> two groups)
    if (all(grepl("\\d+$", sample_names))) {
      numbers <- as.numeric(gsub(".*?(\\d+)$", "\\1", sample_names))
      if (length(numbers) >= 4) {
        # Assign first half to group 1, second half to group 2
        groups <- ifelse(seq_along(sample_names) <= length(sample_names)/2, "Group1", "Group2")
        return(list(
          method = "numeric",
          groups = groups,
          unique_groups = c("Group1", "Group2"),
          confidence = "low",
          message = "No clear groups detected - suggested split by order"
        ))
      }
    }
    
    # Default: Unable to detect groups
    return(list(
      method = "manual",
      groups = rep("Unknown", length(sample_names)),
      unique_groups = "Unknown",
      confidence = "none",
      message = "Unable to auto-detect groups - manual assignment needed"
    ))
  }
  
  
