      # If high/medium confidence, auto-rename and proceed
      if (sample_detection$detected && sample_detection$confidence %in% c("high", "medium")) {
        
        detected_col <- sample_detection$column_name
        colnames(metadata)[colnames(metadata) == detected_col] <- "Sample"
        
        showNotification(
          paste0("✅ Auto-detected sample column: '", detected_col, "'"),
          type = "message",
