    matched_metadata <- metadata[metadata$Sample %in% matched, ]
    group_counts <- table(matched_metadata[[group_col]])
    
    div(
      class = if (length(matched) == length(count_samples)) "alert alert-success" else "alert alert-warning",
      style = "margin-top: 10px; font-size: 0.9em;",
      HTML(paste0(
        "<strong>", if (length(matched) == length(count_samples)) "✅" else "⚠️", 
        " Sample Matching:</strong><br>",
        "• Matched: ", length(matched), " / ", length(count_samples), " samples<br>",
        if (length(unmatched_in_counts) > 0) {
          paste0("• Unmatched in counts: ", paste(head(unmatched_in_counts, 3), collapse = ", "),
                 if (length(unmatched_in_counts) > 3) " ..." else "", "<br>")
