  read_metadata_file <- function(file_path, file_name) {
    
    file_ext <- tolower(tools::file_ext(file_name))
    
    print(paste("📂 Reading file:", file_name))
    print(paste("   Extension:", file_ext))
    
    tryCatch({
      
      # Excel files
      if (file_ext %in% c("xlsx", "xls")) {
        print("   Format: Excel")
        data <- readxl::read_excel(file_path)
        data <- as.data.frame(data, stringsAsFactors = FALSE)
        
        # TSV files (explicit tab separator)
      } else if (file_ext %in% c("tsv", "tab")) {
        print("   Format: TSV (tab-separated)")
        data <- read.delim(
          file_path,
          header = TRUE,
          sep = "\t",              # ✅ EXPLICIT TAB
          stringsAsFactors = FALSE,
          check.names = FALSE,
          quote = "",              # Ignore quotes
          comment.char = ""        # Ignore comments
        )
        
        # CSV files (explicit comma separator)
      } else if (file_ext == "csv") {
        print("   Format: CSV (comma-separated)")
        data <- read.csv(
          file_path,
          header = TRUE,
          sep = ",",               # ✅ EXPLICIT COMMA
          stringsAsFactors = FALSE,
          check.names = FALSE,
          quote = "\"",
          comment.char = ""
        )
        
        # TXT files (auto-detect separator)
      } else if (file_ext == "txt") {
        print("   Format: TXT (auto-detecting separator)")
        
        # Peek at first line to detect separator
        first_line <- readLines(file_path, n = 1, warn = FALSE)
        
        # Count different separators
        tab_count <- length(gregexpr("\t", first_line)[[1]])
        comma_count <- length(gregexpr(",", first_line)[[1]])
        semicolon_count <- length(gregexpr(";", first_line)[[1]])
        
        print(paste("   Detected separators - Tabs:", tab_count, "Commas:", comma_count, "Semicolons:", semicolon_count))
        
        # Choose separator based on counts
        if (tab_count > 0 && tab_count >= comma_count && tab_count >= semicolon_count) {
          print("   → Using TAB separator")
          data <- read.delim(
            file_path,
            header = TRUE,
            sep = "\t",
            stringsAsFactors = FALSE,
            check.names = FALSE,
            quote = "",
            comment.char = ""
          )
        } else if (semicolon_count > 0 && semicolon_count > comma_count) {
          print("   → Using SEMICOLON separator")
          data <- read.csv(
            file_path,
            header = TRUE,
            sep = ";",
            stringsAsFactors = FALSE,
            check.names = FALSE,
            quote = "\"",
            comment.char = ""
          )
        } else {
          print("   → Using COMMA separator (default)")
          data <- read.csv(
            file_path,
            header = TRUE,
            sep = ",",
            stringsAsFactors = FALSE,
            check.names = FALSE,
            quote = "\"",
            comment.char = ""
          )
        }
        
      } else {
        stop(paste("Unsupported file format:", file_ext, 
                   "\nSupported formats: CSV, TSV, TXT, XLSX, XLS"))
      }
      
      # Validate result
      if (is.null(data) || nrow(data) == 0) {
        stop("File appears to be empty")
      }
      
      if (ncol(data) < 2) {
        stop("File must have at least 2 columns")
      }
      
      # Clean column names (remove leading/trailing whitespace)
      colnames(data) <- trimws(colnames(data))
      
      # Print success info
      print(paste("✅ Successfully read:", nrow(data), "rows ×", ncol(data), "columns"))
      print(paste("   Column names:", paste(head(colnames(data), 10), collapse = ", "),
                  if (ncol(data) > 10) "..." else ""))
      
      return(data)
      
    }, error = function(e) {
      stop(paste("Error reading file:", e$message))
    })
  }
  
  detect_sample_column <- function(metadata_df, count_sample_names = NULL) {
    
    
    col_names <- colnames(metadata_df)
    
    detection_result <- list(
      detected = FALSE,
      column_name = NULL,
      confidence = "none",
      candidates = character(0),
      match_scores = numeric(0),
      message = ""
    )
    
    # Define sample column patterns (case-insensitive)
    sample_patterns <- c(
      "^sample$",           # Exact: sample, Sample, SAMPLE
      "^samples$",          # Exact: samples, Samples, SAMPLES
      "^sample_id$",        # sample_id, Sample_ID, SAMPLE_ID
      "^sampleid$",         # sampleid, SampleID, SAMPLEID
      "^sample_name$",      # sample_name, Sample_Name
      "^samplename$",       # samplename, SampleName
      "^id$",               # id, ID, Id
      "^ids$",              # ids, IDs
      "sample",             # Contains "sample" anywhere
      "name"                # Contains "name" anywhere
    )
    
    # Score each column
    scores <- sapply(col_names, function(col) {
      col_lower <- tolower(col)
      
      # Check exact matches first (highest score)
      for (i in seq_along(sample_patterns)) {
        if (grepl(sample_patterns[i], col_lower)) {
          # Earlier patterns get higher scores
          base_score <- 100 - (i * 5)
          
          # Bonus: if we have count data, check overlap
          if (!is.null(count_sample_names)) {
            overlap <- length(intersect(metadata_df[[col]], count_sample_names))
            overlap_ratio <- overlap / length(count_sample_names)
            
            # Add overlap bonus (up to 50 points)
            overlap_bonus <- overlap_ratio * 50
            
            return(base_score + overlap_bonus)
          }
          
          return(base_score)
        }
      }
      
      # No match
      return(0)
    })
    
    # Find candidates (score > 0)
    candidates_idx <- which(scores > 0)
    
    if (length(candidates_idx) > 0) {
      # Sort by score
      sorted_idx <- candidates_idx[order(scores[candidates_idx], decreasing = TRUE)]
      
      detection_result$candidates <- col_names[sorted_idx]
      detection_result$match_scores <- scores[sorted_idx]
      
      # Best match
      best_match <- col_names[sorted_idx[1]]
      best_score <- scores[sorted_idx[1]]
      
      detection_result$detected <- TRUE
      detection_result$column_name <- best_match
      
      # Determine confidence
      if (best_score > 120) {
        detection_result$confidence <- "high"
        detection_result$message <- paste0("Auto-detected '", best_match, "' as sample column (high confidence)")
      } else if (best_score > 80) {
        detection_result$confidence <- "medium"
        detection_result$message <- paste0("Detected '", best_match, "' as sample column (medium confidence)")
      } else {
        detection_result$confidence <- "low"
        detection_result$message <- paste0("Possible sample column: '", best_match, "' (low confidence)")
      }
      
    } else {
      detection_result$message <- "Could not auto-detect sample column. Please select manually."
    }
    
    return(detection_result)
  }
  
  
