  output$grouping_validation <- renderUI({
    req(rv_deg_main$raw_counts)
    
    sample_names <- colnames(rv_deg_main$raw_counts)
    available_groups <- rv_deg_main$available_groups
    
    # Check if we have groups created
    if (is.null(available_groups) || length(available_groups) == 0) {
      return(
        div(
          style = "color: #dc3545;",
          "⚠️ Please create at least 2 groups"
        )
      )
    }
    
    if (length(available_groups) < 2) {
      return(
        div(
          style = "color: #dc3545;",
          "⚠️ Need at least 2 groups for comparison"
        )
      )
    }
    
    # Check sample assignments
    assigned_samples <- 0
    group_counts <- table(factor(rep(NA, length(available_groups)), levels = available_groups))
    
    for (i in 1:length(sample_names)) {
      input_name <- paste0("sample_group_", i)
      if (!is.null(input[[input_name]]) && input[[input_name]] != "") {
        assigned_samples <- assigned_samples + 1
        group_counts[input[[input_name]]] <- group_counts[input[[input_name]]] + 1
      }
    }
    
    # Validation checks
    if (assigned_samples == 0) {
      return(
        div(style = "color: #dc3545;", "⚠️ No samples assigned to groups")
      )
    }
    
    if (assigned_samples < length(sample_names)) {
      return(
        div(
          style = "color: #ffc107;",
          paste("⚠️", length(sample_names) - assigned_samples, "samples not assigned")
        )
      )
    }
    
    # Check if each group has at least 1 sample
    empty_groups <- names(group_counts)[group_counts == 0]
    if (length(empty_groups) > 0) {
      return(
        div(
          style = "color: #ffc107;",
          paste("⚠️ Empty groups:", paste(empty_groups, collapse = ", "))
        )
      )
    }
    
    # Check if each group has at least 2 samples (recommended)
    small_groups <- names(group_counts)[group_counts == 1]
    if (length(small_groups) > 0) {
      return(
        div(
          style = "color: #17a2b8;",
          paste("ℹ️ Groups with 1 sample:", paste(small_groups, collapse = ", "), "(low statistical power)")
        )
      )
    }
    
    # All good!
    return(
      div(
        style = "color: #28a745;",
        paste("✅ Ready:", assigned_samples, "samples in", length(available_groups), "groups")
      )
    )
  })
  
  observeEvent(input$confirm_grouping, {
    req(rv_deg_main$raw_counts)
    
    sample_names <- colnames(rv_deg_main$raw_counts)
    
    # Determine which method was used
    active_tab <- input$group_assignment_method
    
    if (active_tab == "manual") {
      # === MANUAL ASSIGNMENT LOGIC (existing code) ===
      available_groups <- rv_deg_main$available_groups
      
      if (is.null(available_groups) || length(available_groups) < 2) {
        showNotification("❌ Need at least 2 groups for comparison", type = "error", duration = 5)
        return()
      }
      
      group_assignment <- data.frame(
        sample = sample_names,
        group = character(length(sample_names)),
        stringsAsFactors = FALSE
      )
      
      for (i in 1:length(sample_names)) {
        input_name <- paste0("sample_group_", i)
        assigned_group <- input[[input_name]]
        
        if (is.null(assigned_group) || assigned_group == "") {
          showNotification(paste("❌ Sample", sample_names[i], "not assigned"),
                           type = "error", duration = 5)
          return()
        }
        
        group_assignment$group[i] <- assigned_group
      }
      
      # Validate
      group_counts <- table(group_assignment$group)
      if (any(group_counts == 0)) {
        showNotification("❌ Some groups have no samples", type = "error", duration = 5)
        return()
      }
      
    } else if (active_tab == "metadata_groups") {
      # === METADATA-BASED ASSIGNMENT LOGIC (NEW) ===
      req(rv_deg_main$group_metadata_raw, input$group_metadata_column_select)
      
      metadata <- rv_deg_main$group_metadata_raw
      group_col <- input$group_metadata_column_select
      
      # Match samples
      matched_metadata <- metadata[metadata$Sample %in% sample_names, ]
      
      if (nrow(matched_metadata) == 0) {
        showNotification("❌ No samples matched between metadata and counts", 
                         type = "error", duration = 7)
        return()
      }
      
      # Create group assignment
      group_assignment <- data.frame(
        sample = matched_metadata$Sample,
        group = matched_metadata[[group_col]],
        stringsAsFactors = FALSE
      )
      
      # Add unmatched samples as "Unknown" (optional - or you can exclude them)
      unmatched <- setdiff(sample_names, matched_metadata$Sample)
      if (length(unmatched) > 0) {
        showNotification(
          paste("⚠️ Warning:", length(unmatched), "samples not found in metadata and will be excluded"),
          type = "warning",
          duration = 5
        )
        # Optionally exclude unmatched samples from analysis
      }
      
    } else {
      showNotification("❌ Unknown grouping method", type = "error", duration = 5)
      return()
    }
    
    # === COMMON: Store confirmed groups ===
    rv_deg_main$sample_groups <- group_assignment
    rv_deg_main$group_dialog_shown <- TRUE
    
    unique_groups <- unique(group_assignment$group)
    print(paste("DEBUG: Groups confirmed -", length(unique_groups), "groups:", 
                paste(unique_groups, collapse = ", ")))
    
    # Close modal
    removeModal()
    
    # Show success
    showNotification(
      paste("✅ Groups confirmed!", length(unique_groups), "groups assigned"),
      type = "message",
      duration = 3
    )
    
    # Trigger UI update
    if (exists("update_group_selection_ui")) {
      update_group_selection_ui()
    }
  })
  
  observeEvent(input$batch_metadata_file, {
    req(input$batch_metadata_file, rv_deg_main$sample_groups)
    
    tryCatch({
      file_path <- input$batch_metadata_file$datapath
      file_ext <- tools::file_ext(input$batch_metadata_file$name)
      
      # Read file (detect tab / semicolon / comma separators)
      if (file_ext %in% c("csv", "txt", "tsv")) {
        first_line <- readLines(file_path, n = 1, warn = FALSE)
        sep <- if (file_ext == "tsv" || grepl("\t", first_line)) "\t" else
          if (grepl(";", first_line) && !grepl(",", first_line)) ";" else ","
        metadata <- read.csv(file_path, sep = sep, stringsAsFactors = FALSE, check.names = FALSE)
      } else if (file_ext == "xlsx") {
        metadata <- readxl::read_excel(file_path)
        metadata <- as.data.frame(metadata)
      } else {
        stop("Unsupported file format")
      }
      
      # Validate: must have Sample column
      if (!"Sample" %in% colnames(metadata)) {
        showNotification(
          "❌ Error: Batch metadata must contain a 'Sample' column",
          type = "error",
          duration = 7
        )
        return()
      }
      
      # Validate against count matrix
      validation <- validate_metadata_with_expression(metadata, colnames(rv_deg_main$raw_counts))
      
      if (!validation$valid) {
        showNotification(
          paste("❌ Validation error:", paste(validation$issues, collapse = "; ")),
          type = "error",
          duration = 10
        )
        return()
      }
      
      # Store and show configuration modal
      rv_deg_main$metadata_raw <- metadata
      showMetadataConfigModal(metadata)
      
    }, error = function(e) {
      showNotification(
        paste("❌ Error loading batch metadata:", e$message),
        type = "error",
        duration = 7
      )
    })
  })
  
  # Output to control visibility of batch section
  output$groups_confirmed <- reactive({
    return(!is.null(rv_deg_main$sample_groups))
  })
  outputOptions(output, "groups_confirmed", suspendWhenHidden = FALSE)
  
  update_group_selection_ui <- function() {
    # This function updates your main UI to show the user-confirmed groups
    # instead of the auto-detected ones
    
    if (is.null(rv_deg_main$sample_groups)) {
      return()
    }
    
    group_data <- rv_deg_main$sample_groups
    unique_groups <- unique(group_data$group)
    
    # Create a summary display
    group_summary <- table(group_data$group)
    
    # Update the group selection UI with confirmed groups
    rv_deg_main$confirmed_groups <- unique_groups
    
    # Show a success message in the main UI
    output$group_confirmation_display <- renderUI({
      div(
        class = "alert alert-success",
        style = "margin: 10px 0;",
        h6("✅ Sample Groups Confirmed", style = "margin-top: 0;"),
        p(
          paste("Groups:", paste(names(group_summary), "(", group_summary, " samples)", collapse = ", ")),
          style = "margin-bottom: 0;"
        )
      )
    })
  }
  
