  # Observer to update treatment group choices when reference group changes
  observeEvent(input$reference_group_main_specific, {
    print("DEBUG: Reference group changed")
    
    # Determine the source of groups
    if (!is.null(rv_deg_main$sample_groups)) {
      print("DEBUG: Using confirmed groups for treatment update")
      group_data <- rv_deg_main$sample_groups
      unique_groups <- unique(group_data$group)
    } else {
      print("DEBUG: Using auto-detected groups for treatment update")
      data <- rv_deg_main$raw_counts
      col_names <- colnames(data)
      groups <- sub(".*_", "", col_names)
      unique_groups <- unique(groups)
    }
    
    current_ref <- input$reference_group_main_specific
    treatment_choices <- unique_groups[unique_groups != current_ref]
    
    print(paste("DEBUG: Updated treatment choices:", paste(treatment_choices, collapse = ", ")))
    
    # Preserve selected treatment if still valid, otherwise pick first
    selected_treat <- input$treatment_group_main_specific
    if (is.null(selected_treat) || !selected_treat %in% treatment_choices) {
      selected_treat <- treatment_choices[1]
    }
    
    updateSelectInput(session, "treatment_group_main_specific",
                      choices = treatment_choices,
                      selected = selected_treat)
  }, ignoreNULL = TRUE, ignoreInit = TRUE)
  
  
  # --- 2. Normalization (triggered by QC or DEG run, or could be separate) ---
  # This reactive will run whenever raw_counts or normalization_method_main changes AND is needed.
  # It's better to trigger normalization explicitly when an action button is pressed.
  # Let's do it inside the action button observers.
  
  create_pca_plot_batch <- function(pca_df, pca_res, title_suffix = "") {
    
    var_explained <- summary(pca_res)$importance[2, 1:2] * 100
    
    unique_groups <- unique(pca_df$Group)
    unique_batches <- unique(pca_df$Batch)
    
    # Create ggplot version first (for downloads)
    colors_gg <- RColorBrewer::brewer.pal(max(3, length(unique_groups)), "Set1")
    names(colors_gg) <- unique_groups
    
    gg_plot <- ggplot(pca_df, aes(x = PC1, y = PC2, color = Group, shape = Batch)) +
      geom_point(size = 3, alpha = 0.7) +
      scale_color_manual(values = colors_gg) +
      labs(
        title = paste("PCA", title_suffix),
        x = paste0("PC1 (", round(var_explained[1], 2), "%)"),
        y = paste0("PC2 (", round(var_explained[2], 2), "%)")
      ) +
      theme_minimal(base_size = 12) +
      theme(
        plot.title = element_text(hjust = 0.5, face = "bold", size = 14),
        legend.position = "right",
        legend.title = element_text(face = "bold")
      )
    
    # Create plotly version (for interactive display)
    fig <- plot_ly()
    
    # Colors for groups
    colors_plotly <- RColorBrewer::brewer.pal(max(3, length(unique_groups)), "Set1")
    
    # Shapes for batches
    shape_symbols <- c('circle', 'square', 'diamond', 'cross', 'triangle-up', 'star')
    
    # "Groups" header in legend
    fig <- fig %>% add_trace(
      x = NA, y = NA,
      type = "scatter",
      mode = "markers",
      marker = list(size = 0.01, color = 'rgba(0,0,0,0)'),
      showlegend = TRUE,
      name = "<b>Groups</b>",
      hoverinfo = "skip"
    )
    
    # Add traces for each group
    for (i in seq_along(unique_groups)) {
      grp <- unique_groups[i]
      data_subset <- pca_df[pca_df$Group == grp, ]
      
      fig <- fig %>% add_trace(
        data = data_subset,
        x = ~PC1,
        y = ~PC2,
        type = "scatter",
        mode = "markers",
        name = grp,
        marker = list(
          size = 8,
          color = colors_plotly[i],
          line = list(color = 'white', width = 0.5)
        ),
        text = ~paste("Sample:", SampleID, "<br>Group:", Group, "<br>Batch:", Batch),
        hoverinfo = "text",
        showlegend = TRUE
      )
    }
    
    # "Batches" header
    fig <- fig %>% add_trace(
      x = NA, y = NA,
      type = "scatter",
      mode = "markers",
      marker = list(size = 0.01, color = 'rgba(0,0,0,0)'),
      showlegend = TRUE,
      name = "<b>Batches</b>",
      hoverinfo = "skip"
    )
    
    # Add batch shapes
    for (j in seq_along(unique_batches)) {
      batch <- unique_batches[j]
      data_subset_batch <- pca_df[pca_df$Batch == batch, ]
      
      fig <- fig %>% add_trace(
        data = data_subset_batch,
        x = ~PC1,
        y = ~PC2,
        type = "scatter",
        mode = "markers",
        name = paste("Batch", batch),
        marker = list(
          size = 8,
          symbol = shape_symbols[min(j, length(shape_symbols))],
          color = 'rgba(128,128,128,0.3)',
          line = list(color = 'darkgray', width = 1)
        ),
        text = ~paste("Sample:", SampleID, "<br>Group:", Group, "<br>Batch:", Batch),
        hoverinfo = "text",
        showlegend = TRUE
      )
    }
    
    fig <- fig %>% layout(
      title = list(text = paste("<b>PCA", title_suffix, "</b>"), x = 0.5),
      xaxis = list(title = paste0("PC1 (", round(var_explained[1], 2), "%)")),
      yaxis = list(title = paste0("PC2 (", round(var_explained[2], 2), "%)")),
      
      hovermode = "closest",
      legend = list(x = 1.02, y = 1, xanchor = "left"),
      margin = list(r = 150, t = 50)
    )
    
    # Return BOTH versions as a list
    return(list(plotly = fig, ggplot = gg_plot))
  }
  
  # Helper function: Create batch assessment UMAP plot (Group color + Batch shape)
  create_umap_plot_batch <- function(umap_df, title_suffix = "") {
    
    unique_groups <- unique(umap_df$Group)
    unique_batches <- unique(umap_df$Batch)
    
    # Create ggplot version first (for downloads)
    colors_gg <- RColorBrewer::brewer.pal(max(3, length(unique_groups)), "Set1")
    names(colors_gg) <- unique_groups
    
    gg_plot <- ggplot(umap_df, aes(x = UMAP1, y = UMAP2, color = Group, shape = Batch)) +
      geom_point(size = 3, alpha = 0.7) +
      scale_color_manual(values = colors_gg) +
      labs(
        title = paste("UMAP", title_suffix),
        x = "UMAP1",
        y = "UMAP2"
      ) +
      theme_minimal(base_size = 12) +
      theme(
        plot.title = element_text(hjust = 0.5, face = "bold", size = 14),
