    }
    
    fig <- fig %>% layout(
      title = list(text = paste("<b>UMAP", title_suffix, "</b>"), x = 0.5),
      xaxis = list(title = "UMAP1"),
      yaxis = list(title = "UMAP2"),
      # margin = list(r = 150),
      hovermode = "closest",
      legend = list(x = 1.02, y = 1, xanchor = "left"),
      margin = list(r = 150, t = 50)
    )
    
    # Return BOTH versions as a list
    return(list(plotly = fig, ggplot = gg_plot))
  }
  
  
  # --- 3. Exploratory QC Plots (PCA & UMAP) ---
  observeEvent(input$run_exploratory_qc_main, {
    # Clear previous batch detection and correction results
    rv_deg_main$batch_detection_results <- NULL
    rv_deg_main$pca_plot_batch <- NULL
    rv_deg_main$pca_batch_before <- NULL
    rv_deg_main$pca_batch_after <- NULL
    rv_deg_main$umap_batch_before <- NULL
    rv_deg_main$umap_batch_after <- NULL
    
    req(rv_deg_main$raw_counts, input$normalization_method_main)
    
    # Calculate data size for time estimate
    n_samples <- ncol(rv_deg_main$raw_counts)
    n_genes <- nrow(rv_deg_main$raw_counts)
    data_size_mb <- object.size(rv_deg_main$raw_counts) / (1024^2)
    
    # Estimate processing time (rough heuristic)
    # Estimate processing time based on multiple factors
    batch_mode <- input$batch_detection_mode %||% "auto"
    include_deconv <- input$run_deconv_with_qc %||% FALSE
    
    # Base time components (in seconds)
    normalization_time <- (n_samples / 100) * (n_genes / 10000) * 10
    pca_time <- (n_samples / 100) * (n_genes / 10000) * 15
    umap_time <- (n_samples / 50) * 20  # UMAP scales mainly with samples
    
    # Batch correction adds significant time for large datasets
    batch_time <- if (batch_mode != "skip" && n_samples > 100) {
      (n_samples * n_genes / 500000) * 60  # ~1 min per 500k elements
    } else {
      0
    }
    
    # Deconvolution time (if enabled)
    deconv_time <- if (include_deconv) n_samples * 2 else 0
    
    # Total exploratory time
    exploratory_time_sec <- normalization_time + pca_time + umap_time + batch_time + deconv_time
    
    # DEG analysis time estimate (per comparison)
    deg_time_sec <- (n_samples / 50) * (n_genes / 20000) * 45
    
    # Total estimated time
    estimated_time_sec <- exploratory_time_sec + deg_time_sec
    
    # Show warning for large datasets
    if (n_samples > 500 || n_genes > 50000 || data_size_mb > 100) {
      showModal(modalDialog(
        title = tags$div(icon("exclamation-triangle", style = "color: #f39c12;"), " Large Dataset Detected"),
        tags$div(
          style = "line-height: 1.8;",
          tags$p(tags$strong("Dataset Information:")),
          tags$ul(
            tags$li(paste("Samples:", format(n_samples, big.mark = ","))),
            tags$li(paste("Genes:", format(n_genes, big.mark = ","))),
            tags$li(paste("Size:", round(data_size_mb, 1), "MB"))
          ),
          tags$p(tags$strong("Estimated Processing Time:")),
          tags$ul(
            tags$li(paste("Exploratory Analysis:", round(exploratory_time_sec / 60, 1), "minutes")),
            if (batch_mode != "skip") tags$li(paste("(includes batch correction:", round(batch_time / 60, 1), "min)")),
            tags$li(paste("DEG Analysis:", round(deg_time_sec / 60, 1), "minutes per comparison")),
            tags$li(tags$strong(paste("Total:", round(estimated_time_sec / 60, 1), "minutes")))
          ),
          tags$hr(),
          tags$p(icon("info-circle"), " ", 
                 tags$strong("Important:"), " Please keep this tab open during processing."),
          tags$p("If you close or refresh this page, all progress will be lost and you will need to restart the analysis.",
                 style = "color: #e74c3c;"),
          tags$div(
            style = "background: #e8f5e9; padding: 10px; border-radius: 5px; margin-top: 10px;",
            icon("lightbulb", style = "color: #4caf50;"),
            tags$strong(" Pro Tip: "),
            "Once exploratory analysis is complete, subsequent DEG comparisons will be much faster (~",
            round(deg_time_sec / 60, 1), " min each)!"
          )
        ),
        footer = tagList(
          modalButton("Cancel"),
          actionButton("confirm_large_analysis", "Continue Analysis", class = "btn-primary")
        ),
        easyClose = FALSE
      ))
      return()
    }
    
    # Run the actual analysis
    run_exploratory_qc_analysis()
  }, ignoreInit = TRUE, priority = -1)  # Lower priority so package loading happens first
  
  # Confirmation handler for large datasets
  observeEvent(input$confirm_large_analysis, {
    removeModal()
    run_exploratory_qc_analysis()
  })
  
  
  run_exploratory_qc_analysis <- function() {
    print(paste("--- Running QC for method:", input$normalization_method_main, "---"))
    
    withProgress(message = 'Running Exploratory QC Analysis', value = 0, {
      
      tryCatch({
        setProgress(0.05, detail = "Normalizing data...")
        data_for_norm <- as.data.frame(rv_deg_main$raw_counts)
        
        norm_data <- normalizeData(data_for_norm, input$normalization_method_main)
        
        setProgress(0.10, detail = "Preparing data for dimensionality reduction...")
        print("Inside run_exploratory_qc_main, AFTER normalizeData:")
        print(paste("Dimensions of norm_data:", paste(dim(norm_data), collapse=" x ")))
        
        # Transpose data for PCA/UMAP
        data_for_dim_red <- t(norm_data)
        
        # Remove zero-variance genes
        col_variances_dim_red <- apply(data_for_dim_red, 2, var, na.rm = TRUE)
        zero_var_features <- which(is.na(col_variances_dim_red) | col_variances_dim_red == 0)
        
        if (length(zero_var_features) > 0) {
          showNotification(
            paste("Removed", length(zero_var_features), "gene(s) with zero variance across samples for PCA/UMAP."),
            type = "warning", duration = 10
          )
          data_for_dim_red <- data_for_dim_red[, -zero_var_features, drop = FALSE]
        }
        
        if (nrow(data_for_dim_red) < 2 || ncol(data_for_dim_red) < 2) {
          stop("Not enough varying samples or genes remaining after filtering for PCA/UMAP.")
        }
        
        # Store normalized data
        rv_deg_main$normalized_counts <- norm_data
        
        # ============================================================================
        # NEW: ENHANCED GROUP & BATCH DETECTION
        # ============================================================================
        
        sample_names <- rownames(data_for_dim_red)
        
        # Initialize metadata for plotting
        plot_metadata <- data.frame(
          SampleID = sample_names,
          stringsAsFactors = FALSE
        )
        
        # Check if we have user-confirmed groups and batch info
        # if (!is.null(rv_deg_main$sample_groups)) {
        #   print("âœ… Using user-confirmed sample groups for QC plots")
        #   
        #   matched_idx <- match(sample_names, rv_deg_main$sample_groups$sample)
        #   
        #   # Always use groups for color
        #   plot_metadata$Group <- rv_deg_main$sample_groups$group[matched_idx]
        #   
        #   # Add batch for shape if available
        #   if ("batch" %in% colnames(rv_deg_main$sample_groups)) {
        #     plot_metadata$Batch <- rv_deg_main$sample_groups$batch[matched_idx]
        #     has_batch <- TRUE
        #     print("âœ… PCA/UMAP will show: Color=Group, Shape=Batch")
        #   } else {
        #     has_batch <- FALSE
        #     print("âœ… PCA/UMAP will show: Color=Group")
        #   }
        # } else {
        #   # Fallback: auto-detect from sample names
        #   print("âš ï¸ No user-confirmed groups - using auto-detection from sample names")
        #   groups <- sub(".*_", "", sample_names)
        #   plot_metadata$Category <- groups
        #   has_batch <- FALSE
        # }
        # 
        # print(paste("ðŸ“Š Plot metadata prepared:", nrow(plot_metadata), "samples"))
        # print(paste("   Groups:", paste(unique(plot_metadata$Category), collapse = ", ")))
        
        batch_detection_mode <- input$batch_detection_mode %||% "skip"
        print(paste("🎯 Batch Detection Mode:", batch_detection_mode))
        
        # Initialize has_batch as FALSE
        has_batch <- FALSE
        
        # Check if we have user-confirmed groups
        if (!is.null(rv_deg_main$sample_groups)) {
          print("✅ Using user-confirmed sample groups for QC plots")
          
          matched_idx <- match(sample_names, rv_deg_main$sample_groups$sample)
          plot_metadata$Group <- rv_deg_main$sample_groups$group[matched_idx]
          
          # ================================================================
          # MODE 1: AUTOMATIC DETECTION
          # ================================================================
          if (batch_detection_mode == "auto") {
            print("🔍 MODE: Automatic Batch Detection")
            
            # Get all metadata columns except 'sample' and 'group'
            metadata_for_detection <- rv_deg_main$sample_groups[matched_idx, ]
            exclude_cols <- c("sample", "group", "Sample", "Group")
            candidate_cols <- setdiff(colnames(metadata_for_detection), exclude_cols)
            
            if (length(candidate_cols) > 0) {
              setProgress(0.15, detail = "Running automatic batch detection...")
              
              temp_pca <- prcomp(data_for_dim_red, scale. = TRUE, center = TRUE)
              pca_coords <- temp_pca$x[, 1:min(10, ncol(temp_pca$x)), drop = FALSE]  # top PCs, as validated
              
              batch_detection <- detect_batch_effects_advanced(
                pca_coords,
                metadata_for_detection[, candidate_cols, drop = FALSE],
                data_for_dim_red
              )
              
              rv_deg_main$batch_detection_results <- batch_detection
              
              if (batch_detection$has_batch) {
                recommended_col <- batch_detection$recommended_batch
                plot_metadata$Batch <- metadata_for_detection[[recommended_col]]
                has_batch <- TRUE
                print(sprintf("✅ Batch detected: '%s' - will apply correction", recommended_col))
              } else {
                has_batch <- FALSE
                print("✅ No significant batch effects - proceeding without correction")
              }
              
            } else {
              has_batch <- FALSE
              rv_deg_main$batch_detection_results <- list(
                has_batch = FALSE,
                detection_phase = "no_metadata",
                message = "No additional metadata columns available for batch detection"
              )
              print("⚠️ No metadata columns available for automatic detection")
            }
            
            # ================================================================
            # MODE 2: MANUAL SELECTION
            # ================================================================
          } else if (batch_detection_mode == "manual") {
            print("📋 MODE: Manual Batch Selection")
            
            if ("batch" %in% colnames(rv_deg_main$sample_groups)) {
              plot_metadata$Batch <- rv_deg_main$sample_groups$batch[matched_idx]
              has_batch <- TRUE
              rv_deg_main$batch_detection_results <- list(
                has_batch = TRUE,
                detection_phase = "manual",
                recommended_batch = "batch",
                message = "User-specified batch column (manual mode)"
              )
              print("✅ Using user-specified batch column")
            } else {
              has_batch <- FALSE
              rv_deg_main$batch_detection_results <- NULL  # Don't show any batch message
              showNotification(
                "Manual mode selected but no 'batch' column found in metadata.",
                type = "warning",
                duration = 5
              )
            }
            
            # ================================================================
            # MODE 3: SKIP - Don't set batch_detection_results at all
            # ================================================================
          } else {
            print("⏭️ MODE: Skip - No batch correction")
            has_batch <- FALSE
            rv_deg_main$batch_detection_results <- NULL  # ✅ Don't store anything - skip means skip!
          }
          
        } else {
          # No metadata uploaded - use auto-detection from sample names for groups only
          print("⚠️ No metadata uploaded - using auto-detection from sample names")
          groups <- sub(".*_", "", sample_names)
          plot_metadata$Group <- groups
          has_batch <- FALSE
          rv_deg_main$batch_detection_results <- NULL  # ✅ Don't show batch message when no metadata
        }
        
        print(paste("📊 Final Status: has_batch =", has_batch))
        if (has_batch) {
          print(paste("   Batch levels:", paste(unique(plot_metadata$Batch), collapse = ", ")))
        }
        
        # if (batch_detection_mode == "auto" && !is.null(rv_deg_main$batch_detection_results$recommended_batch)) {
        #   print("ðŸ“Š Phase 3: Assessing correction quality...")
        #   
        #   correction_assessment <- assess_batch_correction(
        #     data_for_dim_red,
        #     corrected_data,
        #     plot_metadata$Batch
        #   )
        #   
        #   rv_deg_main$correction_assessment <- correction_assessment
        #   print(correction_assessment$message)
        # }
        # 
        # print("âœ… Batch correction assessment plots created!")
        
        # ========================================================================
        # PCA
        # ========================================================================
        setProgress(0.35, detail = "Generating PCA plot...")
        
        pca_res <- prcomp(data_for_dim_red, scale. = TRUE, center = TRUE)
        
        pca_df <- data.frame(
          PC1 = pca_res$x[, 1], 
          PC2 = pca_res$x[, 2],
          SampleID = rownames(pca_res$x)
        )
        
        # Merge with plot metadata
        pca_df <- merge(pca_df, plot_metadata, by = "SampleID", all.x = TRUE)
        
        # Calculate variance explained
        var_explained <- summary(pca_res)$importance[2, ]

        # Save underlying data + variance for static publication-quality download
        rv_deg_main$pca_data <- pca_df
        rv_deg_main$pca_var_explained <- var_explained

        # ============================================================================
        # CREATE PCA PLOTS (Multiple versions based on available data)
        # ============================================================================
        
        if (has_batch) {
          # Enhanced plot with BOTH group (color) AND batch (shape)
          print("✅ Creating PCA with Group (color) + Batch (shape)")
          
          # Get unique groups and batches
          unique_groups <- unique(pca_df$Group)
          unique_batches <- unique(pca_df$Batch)
          
          # Create base plot
          fig <- plot_ly()
          
          # Add invisible trace for "Groups" header
          fig <- fig %>% add_trace(
            x = NA, y = NA,
            type = "scatter",
            mode = "markers",
            marker = list(size = 0.01, color = 'rgba(0,0,0,0)'),
            showlegend = TRUE,
            name = "<b>Groups</b>",
            hoverinfo = "skip"
          )
          
          # Add traces for each group (colors only, all same shape)
          colors_plotly <- RColorBrewer::brewer.pal(max(3, length(unique_groups)), "Set1")
          
          for (i in seq_along(unique_groups)) {
            grp <- unique_groups[i]
            data_subset <- pca_df[pca_df$Group == grp, ]
            
            fig <- fig %>% add_trace(
              data = data_subset,
              x = ~PC1, 
              y = ~PC2,
              type = "scatter",
              mode = "markers",
              marker = list(
                size = 12,
                color = colors_plotly[i],
                opacity = 0.8,
                line = list(width = 1, color = 'white'),
                symbol = match(data_subset$Batch, unique_batches) - 1  # Shape by batch
              ),
              name = grp,
              text = ~paste0("Sample: ", SampleID, "<br>Group: ", Group, "<br>Batch: ", Batch),
              hoverinfo = "text",
              legendgroup = "groups",
              showlegend = TRUE
            )
          }
          
          # Add invisible trace for "Batch" header
          fig <- fig %>% add_trace(
            x = NA, y = NA,
            type = "scatter",
            mode = "markers",
            marker = list(size = 0.01, color = 'rgba(0,0,0,0)'),
            showlegend = TRUE,
            name = "<b>Batch</b>",
            hoverinfo = "skip"
          )
          
          # Add traces for each batch (shapes only, all same color gray)
          shape_symbols <- c('circle', 'square', 'diamond', 'cross', 'triangle-up', 'star')
          
          for (i in seq_along(unique_batches)) {
            batch <- unique_batches[i]
            data_subset <- pca_df[pca_df$Batch == batch, ]
            
            fig <- fig %>% add_trace(
              data = data_subset,
              x = ~PC1,
              y = ~PC2,
              type = "scatter",
              mode = "markers",
              marker = list(
                size = 12,
                color = 'rgba(150,150,150,0.6)',  # Gray color for batch legend
                symbol = shape_symbols[i],
                line = list(width = 1, color = 'white')
              ),
              name = batch,
              text = ~paste0("Sample: ", SampleID, "<br>Group: ", Group, "<br>Batch: ", Batch),
              hoverinfo = "text",
              legendgroup = "batches",
              showlegend = TRUE,
              visible = 'legendonly'  # Hide from plot, show in legend only
            )
          }
          
          # Apply layout
          fig <- fig %>% layout(
            title = list(
              text = "<b>PCA of Samples</b><br><sub style='color: #555;'>Color: Biological Group | Shape: Technical Batch</sub>",
              font = list(size = 18, color = '#2c3e50')
            ),
            xaxis = list(
              title = paste0("<b>PC1 (", round(var_explained[1] * 100, 1), "%)</b>"),
              zeroline = FALSE,
              gridcolor = 'rgba(200,200,200,0.3)',
              titlefont = list(size = 14, color = '#2c3e50')
            ),
            yaxis = list(
              title = paste0("<b>PC2 (", round(var_explained[2] * 100, 1), "%)</b>"),
              zeroline = FALSE,
              gridcolor = 'rgba(200,200,200,0.3)',
              titlefont = list(size = 14, color = '#2c3e50')
            ),
            legend = list(
              orientation = "v",
              x = 1.02,
              y = 1,
              bgcolor = 'rgba(255,255,255,0)',  # âœ… Transparent background (no box)
              bordercolor = 'rgba(0,0,0,0)',    # âœ… No border
              borderwidth = 0,                   # âœ… No border width
              font = list(size = 12, color = '#2c3e50')
            ),
            margin = list(r = 150),
            hovermode = "closest",
            plot_bgcolor = 'rgba(250,250,250,1)',
            paper_bgcolor = 'white',
            font = list(family = "Arial, sans-serif", color = '#2c3e50')
          )
          
          rv_deg_main$pca_plot <- fig
          rv_deg_main$pca_plot_batch <- NULL
          
        } else {
          # Simple plot without batch
          print("✅ CCreating PCA with Group (color only)")
          
          rv_deg_main$pca_plot <- plot_ly(
            pca_df, 
            x = ~PC1, 
            y = ~PC2, 
            type = "scatter", 
            mode = "markers",
            color = ~Group,
            text = ~paste0("Sample: ", SampleID, "<br>Group: ", Group),
            hoverinfo = "text",
            marker = list(size = 12, opacity = 0.8, line = list(width = 1, color = 'white')),
            source = "pca_plot_source"
          ) %>%
            layout(
              title = list(
                text = "<b>PCA of Samples</b>",
                font = list(size = 18, color = '#2c3e50')
              ),
              xaxis = list(
                title = paste0("<b>PC1 (", round(var_explained[1] * 100, 1), "%)</b>"),
                zeroline = FALSE,
                gridcolor = 'rgba(200,200,200,0.3)',
                titlefont = list(size = 14, color = '#2c3e50')
              ),
              yaxis = list(
                title = paste0("<b>PC2 (", round(var_explained[2] * 100, 1), "%)</b>"),
                zeroline = FALSE,
                gridcolor = 'rgba(200,200,200,0.3)',
                titlefont = list(size = 14, color = '#2c3e50')
              ),
              legend = list(
                title = list(text = "<b>Groups</b>", font = list(size = 14)),
                orientation = "v",
                x = 1.02,
                y = 1,
                bgcolor = 'rgba(255,255,255,0)',  # âœ… No box
                bordercolor = 'rgba(0,0,0,0)',
                borderwidth = 0,
                font = list(size = 12, color = '#2c3e50')
              ),
              hovermode = "closest",
              plot_bgcolor = 'rgba(250,250,250,1)',
              paper_bgcolor = 'white',
              font = list(family = "Arial, sans-serif", color = '#2c3e50')
            )
          
          rv_deg_main$pca_plot_batch <- NULL
        }
        
        # ========================================================================
        # UMAP
        # ========================================================================
        setProgress(0.55, detail = "Generating UMAP plot...")
        
        n_neighbors_val <- max(2, min(15, nrow(data_for_dim_red) - 1))
        
        umap_res <- uwot::umap(data_for_dim_red, 
                               n_neighbors = n_neighbors_val, 
                               min_dist = 0.1, 
                               n_threads = 2, 
                               verbose = FALSE)
        
        umap_df <- data.frame(
          UMAP1 = umap_res[, 1], 
          UMAP2 = umap_res[, 2],
          SampleID = rownames(umap_res)
        )
        
        # Merge with plot metadata
        umap_df <- merge(umap_df, plot_metadata, by = "SampleID", all.x = TRUE)

        # Save underlying data for static publication-quality download
        rv_deg_main$umap_data <- umap_df

        # ============================================================================
        # CREATE UMAP PLOTS (Multiple versions based on available data)
        # ============================================================================
        
        if (has_batch) {
          # Enhanced plot with BOTH group (color) AND batch (shape)
          print("✅ Creating UMAP with Group (color) + Batch (shape)")
          
          unique_groups <- unique(umap_df$Group)
          unique_batches <- unique(umap_df$Batch)
          
          fig <- plot_ly()
          
          # "Groups" header
          fig <- fig %>% add_trace(
            x = NA, y = NA,
            type = "scatter",
            mode = "markers",
            marker = list(size = 0.01, color = 'rgba(0,0,0,0)'),
            showlegend = TRUE,
            name = "<b>Groups</b>",
            hoverinfo = "skip"
          )
          
          # Add group traces
          colors_plotly <- RColorBrewer::brewer.pal(max(3, length(unique_groups)), "Set1")
          
          for (i in seq_along(unique_groups)) {
            grp <- unique_groups[i]
            data_subset <- umap_df[umap_df$Group == grp, ]
            
            fig <- fig %>% add_trace(
              data = data_subset,
              x = ~UMAP1, 
              y = ~UMAP2,
              type = "scatter",
              mode = "markers",
              marker = list(
                size = 12,
                color = colors_plotly[i],
                opacity = 0.8,
                line = list(width = 1, color = 'white'),
                symbol = match(data_subset$Batch, unique_batches) - 1
              ),
              name = grp,
              text = ~paste0("Sample: ", SampleID, "<br>Group: ", Group, "<br>Batch: ", Batch),
              hoverinfo = "text",
              legendgroup = "groups",
              showlegend = TRUE
            )
          }
          
          # "Batch" header
          fig <- fig %>% add_trace(
            x = NA, y = NA,
            type = "scatter",
            mode = "markers",
            marker = list(size = 0.01, color = 'rgba(0,0,0,0)'),
            showlegend = TRUE,
            name = "<b>Batch</b>",
            hoverinfo = "skip"
          )
          
          # Add batch traces
          shape_symbols <- c('circle', 'square', 'diamond', 'cross', 'triangle-up', 'star')
          
          for (i in seq_along(unique_batches)) {
            batch <- unique_batches[i]
            data_subset <- umap_df[umap_df$Batch == batch, ]
            
            fig <- fig %>% add_trace(
              data = data_subset,
              x = ~UMAP1,
              y = ~UMAP2,
              type = "scatter",
              mode = "markers",
              marker = list(
                size = 12,
                color = 'rgba(150,150,150,0.6)',
                symbol = shape_symbols[i],
                line = list(width = 1, color = 'white')
              ),
              name = batch,
              text = ~paste0("Sample: ", SampleID, "<br>Group: ", Group, "<br>Batch: ", Batch),
              hoverinfo = "text",
              legendgroup = "batches",
              showlegend = TRUE,
              visible = 'legendonly'
            )
          }
          
          fig <- fig %>% layout(
            title = list(
              text = "<b>UMAP of Samples</b><br><sub style='color: #555;'>Color: Biological Group | Shape: Technical Batch</sub>",
              font = list(size = 18, color = '#2c3e50')
            ),
            xaxis = list(
              title = "<b>UMAP1</b>",
              zeroline = FALSE,
              gridcolor = 'rgba(200,200,200,0.3)',
              titlefont = list(size = 14, color = '#2c3e50')
            ),
            yaxis = list(
              title = "<b>UMAP2</b>",
              zeroline = FALSE,
              gridcolor = 'rgba(200,200,200,0.3)',
              titlefont = list(size = 14, color = '#2c3e50')
            ),
            legend = list(
              orientation = "v",
              x = 1.02,
              y = 1,
              bgcolor = 'rgba(255,255,255,0)',  # âœ… No box
              bordercolor = 'rgba(0,0,0,0)',
              borderwidth = 0,
              font = list(size = 12, color = '#2c3e50')
            ),
            margin = list(r = 150),
            hovermode = "closest",
            plot_bgcolor = 'rgba(250,250,250,1)',
            paper_bgcolor = 'white',
            font = list(family = "Arial, sans-serif", color = '#2c3e50')
          )
          
          rv_deg_main$umap_plot <- fig
          rv_deg_main$umap_plot_batch <- NULL
          
        } else {
          print("✅ Creating UMAP with Group (color only)")
          
          rv_deg_main$umap_plot <- plot_ly(
            umap_df, 
            x = ~UMAP1, 
            y = ~UMAP2, 
            type = "scatter", 
            mode = "markers",
            color = ~Group,
            text = ~paste0("Sample: ", SampleID, "<br>Group: ", Group),
            hoverinfo = "text",
            marker = list(size = 12, opacity = 0.8, line = list(width = 1, color = 'white')),
            source = "umap_plot_source"
          ) %>%
            layout(
              title = list(
                text = "<b>UMAP of Samples</b>",
                font = list(size = 18, color = '#2c3e50')
              ),
              xaxis = list(
                title = "<b>UMAP1</b>",
                zeroline = FALSE,
                gridcolor = 'rgba(200,200,200,0.3)',
                titlefont = list(size = 14, color = '#2c3e50')
              ),
              yaxis = list(
                title = "<b>UMAP2</b>",
                zeroline = FALSE,
                gridcolor = 'rgba(200,200,200,0.3)',
                titlefont = list(size = 14, color = '#2c3e50')
              ),
              legend = list(
                title = list(text = "<b>Groups</b>", font = list(size = 14)),
                orientation = "v",
                x = 1.02,
                y = 1,
                bgcolor = 'rgba(255,255,255,0)',  # âœ… No box
                bordercolor = 'rgba(0,0,0,0)',
                borderwidth = 0,
                font = list(size = 12, color = '#2c3e50')
              ),
              hovermode = "closest",
              plot_bgcolor = 'rgba(250,250,250,1)',
              paper_bgcolor = 'white',
              font = list(family = "Arial, sans-serif", color = '#2c3e50')
            )
          
          rv_deg_main$umap_plot_batch <- NULL
        }
        
        print("✅ PCA and UMAP plots completed")
        
        if (has_batch) {
          print("🧪 Generating batch correction assessment plots...")
          
          # Create design matrix to preserve biological groups
          batch_vector <- plot_metadata$Batch
          group_vector <- plot_metadata$Group
          
          design_matrix <- model.matrix(~ Group, data = plot_metadata)
          
          # Apply batch correction
          corrected_data <- limma::removeBatchEffect(
            t(data_for_dim_red),  # genes x samples
            batch = factor(batch_vector),
            design = design_matrix
          )
          
          corrected_data <- t(corrected_data)  # Back to samples x genes
          
          # --- PCA Before Correction (batch colored) ---
          pca_before <- prcomp(data_for_dim_red, scale. = TRUE)
          pca_before_df <- data.frame(
            PC1 = pca_before$x[, 1],
            PC2 = pca_before$x[, 2],
            SampleID = rownames(pca_before$x)
          )
          pca_before_df <- merge(pca_before_df, plot_metadata, by = "SampleID")
          
          rv_deg_main$pca_batch_before <- create_pca_plot_batch(pca_before_df, pca_before, "Before Correction")
          
          # --- PCA After Correction (batch colored) ---
          pca_after <- prcomp(corrected_data, scale. = TRUE)
          pca_after_df <- data.frame(
            PC1 = pca_after$x[, 1],
            PC2 = pca_after$x[, 2],
            SampleID = rownames(pca_after$x)
          )
          pca_after_df <- merge(pca_after_df, plot_metadata, by = "SampleID")
          
          rv_deg_main$pca_batch_after <- create_pca_plot_batch(pca_after_df, pca_after, "After Correction")
          
          # --- UMAP Before Correction ---
          # --- UMAP Before Correction (using uwot for speed) ---
          tryCatch({
            n_neighbors_val <- max(2, min(15, nrow(data_for_dim_red) - 1))
            
            umap_before <- uwot::umap(data_for_dim_red, 
                                      n_neighbors = n_neighbors_val, 
                                      min_dist = 0.1,
                                      n_threads = 2,
                                      verbose = FALSE)
            umap_before_df <- data.frame(
              UMAP1 = umap_before[, 1],
              UMAP2 = umap_before[, 2],
              SampleID = rownames(data_for_dim_red)
            )
            umap_before_df <- merge(umap_before_df, plot_metadata, by = "SampleID")
            
            rv_deg_main$umap_batch_before <- create_umap_plot_batch(umap_before_df, "Before Correction")
          }, error = function(e) {
            print(paste("UMAP before correction failed:", e$message))
            rv_deg_main$umap_batch_before <- NULL
          })
          
          # --- UMAP After Correction (using uwot for speed) ---
          tryCatch({
            n_neighbors_val <- max(2, min(15, nrow(corrected_data) - 1))
            
            umap_after <- uwot::umap(corrected_data, 
                                     n_neighbors = n_neighbors_val, 
                                     min_dist = 0.1,
                                     n_threads = 2,
                                     verbose = FALSE)
            umap_after_df <- data.frame(
              UMAP1 = umap_after[, 1],
              UMAP2 = umap_after[, 2],
              SampleID = rownames(corrected_data)
            )
            umap_after_df <- merge(umap_after_df, plot_metadata, by = "SampleID")
            
            rv_deg_main$umap_batch_after <- create_umap_plot_batch(umap_after_df, "After Correction")
          }, error = function(e) {
            print(paste("UMAP after correction failed:", e$message))
            rv_deg_main$umap_batch_after <- NULL
          })
          
          # Only calculate assessment in automatic mode
          batch_mode <- input$batch_detection_mode %||% "skip"
          
          if (batch_mode == "auto" && !is.null(rv_deg_main$batch_detection_results$recommended_batch)) {
            print("📊 Phase 3: Assessing correction quality...")
            
            correction_assessment <- assess_batch_correction(
              data_for_dim_red,
              corrected_data,
              plot_metadata$Batch
            )
            
            rv_deg_main$correction_assessment <- correction_assessment
            print(correction_assessment$message)
          } else {
            # For manual mode or skip mode, still store basic assessment
            rv_deg_main$correction_assessment <- list(
              sil_before = NA,
              sil_after = NA,
              reduction_pct = NA,
              assessment = "Assessment available in automatic mode only",
              color = "#999"
            )
          }
          
          print("✅ Batch correction assessment plots created!")
        }
        
        # ========================================================================
        # CELL TYPE DECONVOLUTION (if human & checkbox is selected)
        # ========================================================================
        
        run_deconv <- input$run_deconv_with_qc %||% FALSE
        
        if (run_deconv && !is.null(input$organism_deg_main) && input$organism_deg_main == "human") {
          
          setProgress(0.75, detail = "Running cell type deconvolution...")
          
          tryCatch({
            
            print("🧬 Running cell type deconvolution alongside QC...")
            
            deconv_method <- input$deconv_method_exploratory %||% "xcell"
            
            deconv_results <- perform_deconvolution_analysis(
              expression_matrix = rv_deg_main$normalized_counts,
              method = deconv_method,
              organism = input$organism_deg_main,
              deg_data = NULL,
              sample_groups = rv_deg_main$sample_groups
            )
            
            rv_deg_main$exploratory_deconv <- deconv_results
            
            print(paste(" Deconvolution complete:", 
                        deconv_results$summary_stats$deconv$total_cell_types, 
                        "cell types identified"))
            
          }, error = function(e) {
            print(paste("Deconvolution failed:", e$message))
            rv_deg_main$exploratory_deconv <- NULL
            showNotification(
              paste("Cell type deconvolution failed:", e$message),
              type = "warning",
              duration = 5
            )
          })
          
        } else {
          rv_deg_main$exploratory_deconv <- NULL
        }
        
        # ========================================================================
        # FINALIZE
        # ========================================================================
        setProgress(1.0, detail = "Complete!")
        
        updateTabsetPanel(session, "deg_results_tabs_main", selected = "exploratory_panel")
        
        if (!is.null(rv_deg_main$exploratory_deconv)) {
          # Initialize plot data storage
          rv_deg_main$exploratory_deconv_plot_data <- NULL
          
          print("Deconvolution completed - plot data ready for interactive drill-down")
        }
        # Mark exploratory as complete for this dataset
        rv_deg_main$exploratory_completed <- TRUE
        print("✅ Exploratory analysis cached - subsequent DEG comparisons will skip this step")
        
        # Success message with batch detection info
        success_message <- "Exploratory QC plots generated!"
        
        if (!is.null(rv_deg_main$batch_detection_results)) {
          if (rv_deg_main$batch_detection_results$has_batch) {
            success_message <- paste0(
              success_message, 
              "Batch effects detected and corrected! Check the report above."
            )
          } else {
            success_message <- paste0(success_message, " No batch effects detected.")
          }
        }
        
        if (has_batch) {
          success_message <- paste0(success_message, " Batch visualization included!")
        }
        if (!is.null(rv_deg_main$exploratory_deconv)) {
          success_message <- paste0(success_message, " Cell type composition analyzed!")
        }
        
        showNotification(success_message, type = "message", duration = 8)
        
        # AUTO-TRIGGER DEG IF IT WAS WAITING FOR EXPLORATORY QC
        # ========================================================================
        if (!is.null(rv_deg_main$auto_run_deg_after_qc) && rv_deg_main$auto_run_deg_after_qc) {
          print("Exploratory QC complete - auto-triggering DEG analysis now...")
          
          # Reset the flag
          rv_deg_main$auto_run_deg_after_qc <- FALSE
          
          showNotification(
            HTML(paste0(
              "<div style='line-height: 1.6;'>",
              "<strong style='color: #2e7d32;'> Exploratory QC Complete</strong><br>",
              "<span style='color: #666;'>",
              "Batch detection completed. Starting DEG analysis automatically...",
              "</span></div>"
            )),
            type = "message",
            duration = 5
          )
          
          # Small delay to let the notification show
          Sys.sleep(1)
          
          # Programmatically click the DEG button
          shinyjs::click("run_deg_main")
          
          print("DEG analysis button triggered automatically")
        }
      }, error = function(e) {
        showNotification(paste("Error generating QC plots:", e$message), type = "error", duration = 10)
        rv_deg_main$pca_plot <- NULL
        rv_deg_main$umap_plot <- NULL
        rv_deg_main$pca_plot_batch <- NULL
        rv_deg_main$umap_plot_batch <- NULL
        rv_deg_main$exploratory_deconv <- NULL
        # Provide dummy plots
        rv_deg_main$pca_plot <- plot_ly() %>% layout(title = "PCA: Error or insufficient data.")
        rv_deg_main$umap_plot <- plot_ly() %>% layout(title = "UMAP: Error or insufficient data.")
      })
      
    }) # End withProgress
    
    print(paste("Batch plots created:", 
                !is.null(rv_deg_main$pca_batch_before),
                !is.null(rv_deg_main$pca_batch_after),
                !is.null(rv_deg_main$umap_batch_before),
                !is.null(rv_deg_main$umap_batch_after)))
    
    # Re-enable the button after analysis completes
    shinyjs::enable("run_exploratory_qc_main")
    shinyjs::html("run_exploratory_qc_main", "Run Exploratory QC")
  } # End run_exploratory_qc_analysis function
  
