  # Download handler for combined batch correction plots
  output$download_batch_comparison <- downloadHandler(
    filename = function() {
      paste0("batch_correction_assessment_", format(Sys.time(), "%Y%m%d_%H%M%S"), ".png")
    },
    content = function(file) {
      load_export_packages()
      req(rv_deg_main$pca_batch_before, 
          rv_deg_main$pca_batch_after,
          rv_deg_main$umap_batch_before,
          rv_deg_main$umap_batch_after)
      
      # Show progress notification
      progress <- shiny::Progress$new()
      on.exit(progress$close())
      
      progress$set(message = "Preparing high-resolution plots...", value = 0)
      
      tryCatch({
        library(png)
        
        # Create temporary files for individual plots
        temp_pca_before <- tempfile(fileext = ".png")
        temp_pca_after <- tempfile(fileext = ".png")
        temp_umap_before <- tempfile(fileext = ".png")
        temp_umap_after <- tempfile(fileext = ".png")
        
        # Export plot 1 - Use ggplot version
        progress$set(message = "Exporting PCA Before Correction...", value = 0.15)
        ggsave(temp_pca_before, rv_deg_main$pca_batch_before$ggplot, 
               width = 10, height = 8, dpi = 300, bg = "white")
        
        # Export plot 2
        progress$set(message = "Exporting PCA After Correction...", value = 0.35)
        ggsave(temp_pca_after, rv_deg_main$pca_batch_after$ggplot, 
               width = 10, height = 8, dpi = 300, bg = "white")
        
        # Export plot 3
        progress$set(message = "Exporting UMAP Before Correction...", value = 0.55)
        ggsave(temp_umap_before, rv_deg_main$umap_batch_before$ggplot, 
               width = 10, height = 8, dpi = 300, bg = "white")
        
        # Export plot 4
        progress$set(message = "Exporting UMAP After Correction...", value = 0.75)
        ggsave(temp_umap_after, rv_deg_main$umap_batch_after$ggplot, 
               width = 10, height = 8, dpi = 300, bg = "white")
        
        # Read the exported images
        progress$set(message = "Reading exported images...", value = 0.85)
        img1 <- readPNG(temp_pca_before)
        img2 <- readPNG(temp_pca_after)
        img3 <- readPNG(temp_umap_before)
        img4 <- readPNG(temp_umap_after)
        
        # Create ultra high-resolution combined plot (2x2 grid)
        progress$set(message = "Combining plots into high-resolution image...", value = 0.90)
        
        png(file, width = 7200, height = 6000, res = 400)
        
        par(mfrow = c(2, 2), 
            mar = c(0.5, 0.5, 3, 0.5),
            oma = c(0, 0, 4, 0))
        
        # Plot each image with titles
        plot(0:1, 0:1, type = 'n', axes = FALSE, xlab = "", ylab = "")
        title("PCA Before Batch Correction", 
              cex.main = 2.2, font.main = 2, col.main = "#2c3e50")
        rasterImage(img1, 0, 0, 1, 1)
        
        plot(0:1, 0:1, type = 'n', axes = FALSE, xlab = "", ylab = "")
        title("PCA After Batch Correction", 
              cex.main = 2.2, font.main = 2, col.main = "#2c3e50")
        rasterImage(img2, 0, 0, 1, 1)
        
        plot(0:1, 0:1, type = 'n', axes = FALSE, xlab = "", ylab = "")
        title("UMAP Before Batch Correction", 
              cex.main = 2.2, font.main = 2, col.main = "#2c3e50")
        rasterImage(img3, 0, 0, 1, 1)
        
        plot(0:1, 0:1, type = 'n', axes = FALSE, xlab = "", ylab = "")
        title("UMAP After Batch Correction", 
              cex.main = 2.2, font.main = 2, col.main = "#2c3e50")
        rasterImage(img4, 0, 0, 1, 1)
        
        # Add overall title
        mtext("Batch Correction Assessment", 
              outer = TRUE, cex = 2.8, font = 2, line = 1.5, col = "#2c3e50")
        
        dev.off()
        
        # Clean up temporary files
        progress$set(message = "Cleaning up temporary files...", value = 0.95)
        unlink(c(temp_pca_before, temp_pca_after, temp_umap_before, temp_umap_after))
        
        progress$set(message = "Download complete!", value = 1)
        Sys.sleep(0.5)
        
        showNotification(
          "✅ Ultra high-resolution combined plot downloaded successfully! (7200x6000 @ 400 DPI)", 
          type = "message", 
          duration = 5
        )
        
      }, error = function(e) {
