    if (package == "limma") {
      show_message <- TRUE
      
      if (normalization == "TMM") {
        message_type <- "success"
        message_text <- "✅ <strong>Excellent!</strong> TMM + voom is the recommended approach for limma.<br>
        • Used for both DEG analysis and QC plots"
        
      } else if (normalization == "VST") {
        message_type <- "warning"
        message_text <- "⚠️ <strong>Incompatible combination</strong><br>
        VST is a DESeq2 transformation. limma-voom works with count-based normalizations.<br>
        <em>Recommendation: Use TMM or quantile normalization for limma</em>"
        
      } else if (normalization == "none") {
        message_type <- "error"
        message_text <- "❌ <strong>Error:</strong> limma-voom requires normalization!<br>
        Without normalization, the analysis will fail.<br>
        <em>Please select TMM, RLE, quantile, or upper quartile normalization</em>"
        
      } else if (normalization %in% c("RLE", "quantile", "upperquartile")) {
        message_type <- "info"
        message_text <- "ℹ️ <strong>Valid choice</strong><br>
        • limma-voom will use your selected normalization<br>
        • TMM is most commonly used, but your choice will work fine"
      }
