  # Batch correction function using limma's removeBatchEffect
  perform_batch_correction <- function(normalized_data, batch_vector, design_matrix = NULL) {
    
    print("🧹 Performing batch effect correction...")
    
    library(limma)
    
    # Convert to matrix if needed
    expr_matrix <- as.matrix(normalized_data)
    
    # Remove batch effects
    if (!is.null(design_matrix)) {
      # If design matrix provided, preserve biological effects
      corrected_data <- limma::removeBatchEffect(
        expr_matrix,
        batch = factor(batch_vector),
        design = design_matrix
      )
    } else {
      # Simple batch correction without design
      corrected_data <- limma::removeBatchEffect(
        expr_matrix,
        batch = factor(batch_vector)
      )
    }
    
    print(paste("✅ Batch correction complete for", nrow(corrected_data), "genes"))
    
    return(corrected_data)
  }
  
