              "| sample_groups_null=", is.null(rv_deg_main$sample_groups))
    # Clear previous DEG and batch results when starting new analysis
    rv_deg_main$deg_results <- NULL
    rv_deg_main$volcano_plot_obj <- NULL
    rv_deg_main$heatmap_plot_obj <- NULL
    #rv_deg_main$batch_detection_results <- NULL
    # rv_deg_main$pca_plot_batch <- NULL
    # rv_deg_main$pca_batch_before <- NULL
    # rv_deg_main$pca_batch_after <- NULL
    # rv_deg_main$umap_batch_before <- NULL
    # rv_deg_main$umap_batch_after <- NULL

    print("--- run_deg_main TRIGGERED ---")
    # Check if exploratory analysis has been completed for this dataset
    if (!isTRUE(rv_deg_main$exploratory_completed) || is.null(rv_deg_main$normalized_counts)) {
      showModal(modalDialog(
        title = tags$div(
