    }
    
    # Debug print to verify batch detection is preserved
    if (!is.null(rv_deg_main$batch_detection_results)) {
      print(paste("📊 Batch detection from exploratory analysis:",
                  "has_batch =", rv_deg_main$batch_detection_results$has_batch,
                  "| recommended =", rv_deg_main$batch_detection_results$recommended_batch %||% "none"))
    } else {
      print("ℹ️ No batch detection results from exploratory analysis")
    }
    
    # AUTO-TRIGGER EXPLORATORY ANALYSIS IF NOT DONE YET
    if (!isTRUE(rv_deg_main$exploratory_completed) || is.null(rv_deg_main$normalized_counts)) {
      print("⚠️ No exploratory QC results found - triggering exploratory analysis first...")
      
      showNotification(
        HTML(paste0(
          "<div style='line-height: 1.6;'>",
          "<strong>🔄 Running Exploratory QC First</strong><br>",
          "<span style='color: #666;'>",
