      # Programmatically click the exploratory QC button
      shinyjs::click("run_exploratory_qc_main")
      
      print("✅ Exploratory QC triggered - DEG will run automatically after completion")
      
      # Button stays disabled since exploratory QC is running
      # It will be re-enabled when DEG auto-runs after QC completes
      shinyjs::html("run_deg_main", "<i class='fa fa-spinner fa-spin'></i> Running QC first...")
      
      # Stop current DEG execution - it will auto-restart after QC
      return()
    }
    
    if (!is.null(rv_deg_main$sample_groups)) {
      confirmed_groups <- unique(rv_deg_main$sample_groups$group)
      current_ref <- input$reference_group_main_specific
      current_treat <- input$treatment_group_main_specific
      
      print("🔍 Verifying dropdowns:")
      print(paste("   Confirmed groups:", paste(confirmed_groups, collapse = ", ")))
      print(paste("   Dropdown ref:", current_ref))
      print(paste("   Dropdown treat:", current_treat))
      
      # Check if dropdown values are invalid
      ref_invalid <- !is.null(current_ref) && !trimws(current_ref) %in% confirmed_groups
      treat_invalid <- !is.null(current_treat) && !trimws(current_treat) %in% confirmed_groups
      
      if (ref_invalid || treat_invalid) {
        print("⚠️ MISMATCH! Forcing dropdown update...")
        
        updateSelectInput(session, "reference_group_main_specific",
                          choices = confirmed_groups,
                          selected = confirmed_groups[1])
        
        if (length(confirmed_groups) > 1) {
          updateSelectInput(session, "treatment_group_main_specific",
                            choices = confirmed_groups[-1],
                            selected = confirmed_groups[2])
        }
        
        showNotification(
          "🔄 Dropdowns were out of sync and have been updated. Please click 'Run Analysis' again.",
          type = "warning",
          duration = 5
        )
        return()  # Stop analysis, make user click again
      }
      
      print("✅ Dropdowns are valid - proceeding with analysis")
    }
    
    # Validate organism selection first
    if (!validate_organism_selection()) {
      return() # Stop execution if validation fails
    }
    
    req(rv_deg_main$raw_counts,
        input$normalization_method_main,
        input$deg_package_main,
        input$comparison_method_main)
    
    if (isolate(input$comparison_method_main) == "specific") {
      req(input$reference_group_main_specific, input$treatment_group_main_specific)
    }

    # edgeR, DESeq2 and limma-voom model raw read counts. Normalised or log-scale values are
    # analysed with limma on log2 expression instead (rounding them into "counts" is invalid).
    data_scale <- tx_expression_scale(rv_deg_main$raw_counts)
    deg_engine <- if (data_scale == "counts") input$deg_package_main else "limma"
    rv_deg_main$deg_method_used <- if (data_scale == "counts") input$deg_package_main else "limma-trend (log2 expression)"
    if (data_scale != "counts") {
      showNotification(HTML(paste0(
        "<strong>These values are not raw read counts</strong> (they look like ",
        if (data_scale == "log") "log-scale expression, e.g. microarray" else "normalised expression such as TPM, FPKM or RPKM",
        "). edgeR, DESeq2 and limma-voom need raw counts, so this analysis uses <strong>limma on log2 expression</strong> ",
        "(limma-trend). For count-based analysis, upload raw counts.")), type = "warning", duration = 20)
    }

    # Batch labels for the given samples, matched by sample name: the detected batch variable,
    # or a "batch" column in the metadata
    tx_batch_values <- function(sample_names) {
      sg <- rv_deg_main$sample_groups
      bd <- rv_deg_main$batch_detection_results
      col <- if (isTRUE(bd$has_batch) && !is.null(bd$recommended_batch)) bd$recommended_batch
             else if (!is.null(sg) && "batch" %in% colnames(sg)) "batch" else NULL
      if (is.null(col) || is.null(sg) || !col %in% colnames(sg)) return(NULL)
      list(name = col, values = sg[[col]][match(sample_names, sg$sample)])
    }
    # A batch term can be fitted alongside the groups unless it is fully confounded with them
    tx_batch_estimable <- function(batch_factor, groups) {
      if (anyNA(batch_factor) || nlevels(batch_factor) < 2) return(FALSE)
      X <- model.matrix(~ batch_factor + groups)
      qr(X)$rank == ncol(X)
    }
    tx_add_batch <- function(sample_names, groups) {
      bt <- tx_batch_values(sample_names)
      if (is.null(bt)) return(NULL)
      bf <- factor(bt$values)
      if (tx_batch_estimable(bf, groups)) {
        showNotification(paste0("Including '", bt$name, "' in the DEG model (", nlevels(bf), " batches)."), type = "message", duration = 6)
        return(bf)
      }
      showNotification(paste0("The batch variable '", bt$name, "' could not be included: it is fully confounded with the groups ",
                              "compared (or missing for some samples), so batch and group effects cannot be separated. ",
                              "These results are not batch-adjusted."), type = "warning", duration = 15)
      NULL
    }

    shinyjs::show("analysis_progress_main")
    progress_text_id <- "analysis_progress_main"
    
    # Helper function to update progress text with proper HTML structure
    update_progress <- function(message, percentage = NULL) {
      if (is.null(percentage)) {
        percentage <- 100
      }
      
      isolate({
        shinyjs::html(progress_text_id, paste0(
          '<div class="progress-bar progress-bar-striped active" role="progressbar" style="width: ', percentage, '%">',
          message,
          '</div>'
        ))
      })
    }
    
    on.exit({
      shinyjs::hide("analysis_progress_main")
      update_progress("Processing...")
    })
    
    tryCatch({
      deg_trace("main#2 entered tryCatch")
      # Step 1: Normalize data
      update_progress("Step 1/5: Normalizing data...", 20)
      deg_trace("Step1 start | deg_package=", as.character(deg_engine),
                "| norm=", as.character(input$normalization_method_main))

      norm_data_for_limma <- NULL
      if (deg_engine == "limma") {
        deg_trace("Step1 calling normalizeData()")
        norm_data_for_limma <- normalizeData(rv_deg_main$raw_counts, input$normalization_method_main)
        deg_trace("Step1 normalizeData returned | dim=",
                  paste(dim(norm_data_for_limma), collapse = "x"))
      }
      deg_trace("Step1 done")

      # Step 2: Prepare experimental design
      update_progress("Step 2/5: Preparing experimental design...", 40)
      deg_trace("Step2 start")
      
      all_samples_data <- rv_deg_main$raw_counts
      col_names <- colnames(all_samples_data)
      
      # ========================================================================
      # NEW: CHECK FOR BATCH VARIABLE
      # ========================================================================
      # Check what batch info is available
      has_auto_detected_batch <- !is.null(rv_deg_main$batch_detection_results) && 
        isTRUE(rv_deg_main$batch_detection_results$has_batch)
      
      has_manual_batch_col <- !is.null(rv_deg_main$sample_groups) && 
        "batch" %in% colnames(rv_deg_main$sample_groups)
      
      if (has_auto_detected_batch) {
        print(paste("✅ Using auto-detected batch from exploratory analysis:",
                    rv_deg_main$batch_detection_results$recommended_batch))
      } else if (has_manual_batch_col) {
        print("🧬 Using manual 'batch' column from metadata")
        print(paste("   Batch levels:", paste(unique(rv_deg_main$sample_groups$batch), collapse = ", ")))
      } else {
        print("ℹ️ No batch variable - using simple design (~ condition)")
      }
      # ========================================================================
      
      # FIXED: Use user-confirmed groups instead of auto-detection
      if (!is.null(rv_deg_main$sample_groups)) {
        # Use user-confirmed groups from dialog
        print("DEBUG: Using user-confirmed groups from dialog")
        group_data <- rv_deg_main$sample_groups
        
        # Create groups vector matching column order
        actual_all_groups <- character(length(col_names))
        for (i in 1:length(col_names)) {
          sample_idx <- which(group_data$sample == col_names[i])
          if (length(sample_idx) > 0) {
            actual_all_groups[i] <- group_data$group[sample_idx[1]]
          } else {
            stop(paste("Sample", col_names[i], "not found in confirmed groups"))
          }
        }
        
        print(paste("DEBUG: User-confirmed groups:", paste(actual_all_groups, collapse = ", ")))
        
      } else {
        # Fallback to auto-detection (old logic)
        print("DEBUG: Falling back to auto-detection - no user groups confirmed")
        actual_all_groups <- sub(".*_", "", col_names)
        
        showNotification(
          "⚠️ Using auto-detected groups. Please use the sample grouping dialog for better control.",
          type = "warning",
          duration = 8
        )
      }
      
      # Step 3: Set up comparisons
      update_progress("Step 3/5: Setting up comparisons...", 60)
      deg_trace("Step3 start | unique_groups=",
                paste(unique(actual_all_groups), collapse = ","),
                "| comparison_method=", as.character(input$comparison_method_main))
      unique_all_groups <- unique(actual_all_groups)

      deg_results_list <- list() # To store results from multiple comparisons
      comparison_names_list <- list()
      rv_deg_main$has_multiple_comparisons <- FALSE # Reset flag

      update_progress("Step 4/5: Running differential expression analysis...", 80)
      deg_trace("Step4 start | engine=", as.character(deg_engine))
      
      # ========================================================================
      # MODIFIED DESIGN MATRIX AND CONTRAST LOGIC WITH BATCH SUPPORT
      # ========================================================================
      
      if (input$comparison_method_main == "simple") {
        # IMPROVED: Use user-confirmed groups if available
        if (!is.null(rv_deg_main$sample_groups)) {
          # Use user-confirmed groups for simple comparison
          user_groups <- unique(rv_deg_main$sample_groups$group)
          
          if (length(user_groups) == 2) {
            # Use user groups directly
            # ref_group <- user_groups[1]  # First group as reference
            # treat_group <- user_groups[2]  # Second group as treatment
            group_assignment <- assign_control_treatment_groups(user_groups)
            ref_group <- group_assignment$reference
            treat_group <- group_assignment$treatment
            
            print(paste("DEBUG: Using user groups - Reference:", ref_group, "Treatment:", treat_group))
            
            showNotification(
              paste("Using confirmed groups:", treat_group, "vs", ref_group),
              type = "message", duration = 5
            )
          } else {
            stop("Simple comparison requires exactly 2 groups. You have ", length(user_groups), " groups.")
          }
        } else {
          # Fallback to intelligent assignment for auto-detected groups
          group_assignment <- assign_control_treatment_groups(unique_all_groups)
          ref_group <- group_assignment$reference
          treat_group <- group_assignment$treatment
          
          showNotification(
            paste("Auto-assigned:", treat_group, "vs", ref_group, "- Please confirm in sample dialog"),
            type = "warning", duration = 10
          )
        }
        
        samples_to_keep_idx <- which(actual_all_groups %in% c(ref_group, treat_group))
        if (length(samples_to_keep_idx) == 0) {
          stop("No samples found for the selected groups after filtering.")
        }
        
        counts_for_deg <- rv_deg_main$raw_counts[, samples_to_keep_idx, drop = FALSE]
        current_groups_factor <- factor(actual_all_groups[samples_to_keep_idx], levels = c(ref_group, treat_group))
        
        if(nlevels(current_groups_factor) < 2) {
          stop(paste("Only one or zero levels found for comparison ('", ref_group, "' vs '", treat_group, "'). Check sample names or group definitions.", sep=""))
        }
        
        # ====================================================================
        # BATCH EFFECT INTEGRATION FOR SIMPLE COMPARISON
        # ====================================================================
        
        # Create base col_data_df
        col_data_df <- data.frame(
          condition = current_groups_factor, 
          row.names = colnames(counts_for_deg)
        )
        
        batch_factor <- tx_add_batch(colnames(counts_for_deg), current_groups_factor)
        use_batch <- !is.null(batch_factor)
        if (use_batch) col_data_df$batch <- batch_factor

        # Create design matrix/formula based on package and batch
        if (deg_engine == "deseq2") {
          # DESeq2 uses formula
          if (use_batch) {
            design_formula <- ~ batch + condition
            print("DESeq2 design formula: ~ batch + condition")
          } else {
            design_formula <- ~ condition
            print("DESeq2 design formula: ~ condition")
          }
          
          contrast_definition <- list(
            type = "contrast_vector", 
            value = c("condition", treat_group, ref_group)
          )
          
        } else {
          # edgeR/limma use design matrix
          if (use_batch) {
            design <- model.matrix(~ batch_factor + current_groups_factor)
            print("edgeR/limma design matrix: ~ batch + condition")
          } else {
            design <- model.matrix(~ current_groups_factor)
            print("edgeR/limma design matrix: ~ condition")
          }
          
          colnames(design) <- make.names(colnames(design))
          contrast_definition <- list(type = "coef", value = ncol(design))
        }
        # ====================================================================
        
        active_comparison_name <- paste(treat_group, "vs", ref_group)
        rv_deg_main$active_deg_comparison <- active_comparison_name
        
        deg_result_df_single <- run_single_deg_analysis(
          counts_data = counts_for_deg,
          normalized_data = norm_data_for_limma[, samples_to_keep_idx, drop=FALSE],
          design_matrix = if (deg_engine != "deseq2") design else NULL,
          col_data_df = col_data_df,
          design_formula = if (deg_engine == "deseq2") design_formula else ~ condition,
          contrast_def = contrast_definition,
          deg_package = deg_engine, data_scale = data_scale,
          ref_group = ref_group,
          treat_group = treat_group
        )
        deg_result_df_single$comparison <- active_comparison_name
        deg_results_list[[active_comparison_name]] <- deg_result_df_single
        
        if (input$comparison_method_main == "specific") {
          print("=" * 70)
          print("DEBUG: SPECIFIC COMPARISON - Data Structure Check")
          print("=" * 70)
          
          print("1. rv_deg_main$sample_groups structure:")
          print(str(rv_deg_main$sample_groups))
          
          print("\n2. Column names in sample_groups:")
          print(colnames(rv_deg_main$sample_groups))
          
          print("\n3. Unique groups:")
          print(unique(rv_deg_main$sample_groups$group))
          
          print("\n4. Unique batches (if exists):")
          if ("batch" %in% colnames(rv_deg_main$sample_groups)) {
            print(unique(rv_deg_main$sample_groups$batch))
          } else {
            print("No batch column")
          }
          
          print("\n5. User selected from dropdown:")
          print(paste("   Reference:", input$reference_group_main_specific))
          print(paste("   Treatment:", input$treatment_group_main_specific))
          
          print("\n6. Check for whitespace issues:")
          print(paste("   Ref has leading/trailing space:", 
                      input$reference_group_main_specific != trimws(input$reference_group_main_specific)))
          print(paste("   Treat has leading/trailing space:", 
                      input$treatment_group_main_specific != trimws(input$treatment_group_main_specific)))
          
          print("=" * 70)
        }
        
      } else if (input$comparison_method_main == "specific") {
        req(input$reference_group_main_specific, input$treatment_group_main_specific)
        ref_group <- trimws(input$reference_group_main_specific)
        treat_group <- trimws(input$treatment_group_main_specific)
        
        print(paste("DEBUG: User selected groups - Ref: '", ref_group, "' Treat: '", treat_group, "'", sep = ""))
        
        # ✅ ENHANCED DEBUG: Full validation info
        print("DEBUG: ============== GROUP VALIDATION ==============")
        print("   1. Raw Input Values:")
        print(paste("      Reference (raw):", input$reference_group_main_specific))
        print(paste("      Treatment (raw):", input$treatment_group_main_specific))
        
        print("\n   2. After trimws():")
        print(paste("      Reference:", ref_group))
        print(paste("      Treatment:", treat_group))
        
        print("\n   3. Available groups in sample_groups:")
        available_groups <- unique(rv_deg_main$sample_groups$group)
        print(paste("      ", paste(available_groups, collapse = ", ")))
        
        print("\n   4. Validation Results:")
        print(paste("      Ref '", ref_group, "' exists?", ref_group %in% available_groups))
        print(paste("      Treat '", treat_group, "' exists?", treat_group %in% available_groups))
        
        if ("batch" %in% colnames(rv_deg_main$sample_groups)) {
          print("\n   5. Batch Information:")
          print(paste("      Batches:", paste(unique(rv_deg_main$sample_groups$batch), collapse = ", ")))
        }
        print("DEBUG: ================================================")
        
        # Check if groups exist in current confirmed groups
        if (!is.null(rv_deg_main$sample_groups)) {
          available_groups <- unique(rv_deg_main$sample_groups$group)
          
          if (!ref_group %in% available_groups) {
            stop(paste("Reference group '", ref_group, "' not found in current dataset. Available groups: ",
                       paste(available_groups, collapse = ", ")))
          }
          
          if (!treat_group %in% available_groups) {
            stop(paste("Treatment group '", treat_group, "' not found in current dataset. Available groups: ",
                       paste(available_groups, collapse = ", ")))
          }
          
          print(paste("DEBUG: Validated groups exist - Ref:", ref_group, "Treat:", treat_group))
        } else {
          stop("No sample groups confirmed. Please use the sample grouping dialog first.")
        }
        
        samples_to_keep_idx <- which(actual_all_groups %in% c(ref_group, treat_group))
        if (length(samples_to_keep_idx) == 0) {
          stop(paste("No samples found for selected specific groups ('", ref_group, "' or '", treat_group, "').", sep=""))
        }
        
        counts_for_deg <- rv_deg_main$raw_counts[, samples_to_keep_idx, drop = FALSE]
        current_groups_factor <- factor(actual_all_groups[samples_to_keep_idx], levels = c(ref_group, treat_group))
        
        if(nlevels(current_groups_factor) < 2) {
          stop(paste("Only one or zero levels found for specified comparison ('", ref_group, "' vs '", treat_group, "'). Check sample names or group definitions.", sep=""))
        }
        if(any(table(current_groups_factor) < 1)) {
          showNotification("Warning: At least one group has fewer than 1 sample. This may cause errors or unreliable results. Please check your data.", type="warning", duration=7)
        }
        if(any(table(current_groups_factor) < 2)) {
          showNotification("Warning: At least one group has fewer than 2 replicates. Statistical power may be low.", type="warning", duration=7)
        }
        
        # ====================================================================
        # BATCH EFFECT INTEGRATION FOR SPECIFIC COMPARISON
        # ====================================================================
        
        col_data_df <- data.frame(
          condition = current_groups_factor, 
          row.names = colnames(counts_for_deg)
        )
        
        batch_factor <- tx_add_batch(colnames(counts_for_deg), current_groups_factor)
        use_batch <- !is.null(batch_factor)
        if (use_batch) col_data_df$batch <- batch_factor
        
        if (deg_engine == "deseq2") {
          design_formula <- if (use_batch) ~ batch + condition else ~ condition
          contrast_definition <- list(
            type = "contrast_vector", 
            value = c("condition", treat_group, ref_group)
          )
        } else {
          design <- if (use_batch) {
            model.matrix(~ batch_factor + current_groups_factor)
          } else {
            model.matrix(~ current_groups_factor)
          }
          colnames(design) <- make.names(colnames(design))
          contrast_definition <- list(type = "coef", value = ncol(design))
        }
        # ====================================================================
        
        active_comparison_name <- paste(treat_group, "vs", ref_group)
        rv_deg_main$active_deg_comparison <- active_comparison_name
        
        deg_result_df_single <- run_single_deg_analysis(
          counts_data = counts_for_deg,
          normalized_data = norm_data_for_limma[, samples_to_keep_idx, drop=FALSE],
          design_matrix = if (deg_engine != "deseq2") design else NULL,
          col_data_df = col_data_df,
          design_formula = if (deg_engine == "deseq2") design_formula else ~ condition,
          contrast_def = contrast_definition,
          deg_package = deg_engine, data_scale = data_scale,
          ref_group = ref_group,
          treat_group = treat_group
        )
        deg_result_df_single$comparison <- active_comparison_name
        deg_results_list[[active_comparison_name]] <- deg_result_df_single
        
      } else if (input$comparison_method_main == "pairwise") {
        rv_deg_main$has_multiple_comparisons <- TRUE # Set flag for multiple comparisons
        
        # Ensure all groups have at least 2 samples if possible, or warn if not
        if(any(table(actual_all_groups) < 1)) {
          stop("At least one group has no samples. Cannot perform pairwise comparison.")
        }
        if(any(table(actual_all_groups) < 2)) {
          showNotification("Warning: At least one group has fewer than 2 replicates. Pairwise DEG results may be unreliable.", type="warning", duration=7)
        }
        
        full_group_factor <- factor(actual_all_groups)
        
        # ====================================================================
        # BATCH EFFECT INTEGRATION FOR PAIRWISE COMPARISON
        # ====================================================================
        
        # Create col_data for all samples
        col_data_df_full <- data.frame(
          condition = full_group_factor,
          row.names = colnames(rv_deg_main$raw_counts)
        )
        
        batch_factor_full <- tx_add_batch(colnames(rv_deg_main$raw_counts), full_group_factor)
        use_batch <- !is.null(batch_factor_full)
        if (use_batch) col_data_df_full$batch <- batch_factor_full
        # ====================================================================
        
        if (deg_engine == "edgeR" || deg_engine == "limma") {
          
          # Design matrix for edgeR/limma pairwise
          if (use_batch) {
            design_pairwise <- model.matrix(~0 + full_group_factor + batch_factor_full)
            print("Pairwise design (edgeR/limma): ~0 + condition + batch")
          } else {
            design_pairwise <- model.matrix(~0 + full_group_factor)
            print("Pairwise design (edgeR/limma): ~0 + condition")
          }
          colnames(design_pairwise) <- make.names(colnames(design_pairwise))
          colnames(design_pairwise)[seq_len(nlevels(full_group_factor))] <- make.names(levels(full_group_factor))

          # Generate all pairwise contrasts
          contrast_pairs <- combn(levels(full_group_factor), 2, simplify = FALSE)
          
          for (pair in contrast_pairs) {
            ref_group_pair <- pair[1]
            treat_group_pair <- pair[2]
            comparison_name <- paste(treat_group_pair, "vs", ref_group_pair)
            shinyjs::html(progress_text_id, paste("Running", deg_engine, "for", comparison_name, "..."))
            
            contrast_formula <- paste(make.names(treat_group_pair), make.names(ref_group_pair), sep = "-")
            myCont.matrix <- limma::makeContrasts(contrasts=c(contrast_formula), levels=design_pairwise)
            
            deg_pairwise_result <- run_single_deg_analysis(
              counts_data = rv_deg_main$raw_counts,
              normalized_data = norm_data_for_limma,
              design_matrix = design_pairwise,
              col_data_df = col_data_df_full,
              design_formula = ~condition,
              contrast_def = list(type = "contrast_matrix", value = myCont.matrix),
              deg_package = deg_engine, data_scale = data_scale,
              ref_group = ref_group_pair,
              treat_group = treat_group_pair
            )
            deg_pairwise_result$comparison <- comparison_name
            deg_results_list[[comparison_name]] <- deg_pairwise_result
            comparison_names_list <- c(comparison_names_list, comparison_name)
          }
          
        } else if (deg_engine == "deseq2") {
          shinyjs::html(progress_text_id, "Running DESeq2 (full model)...")
          
          # Design formula for DESeq2 pairwise
          design_formula_deseq <- if (use_batch) ~ batch + condition else ~ condition
          
          deg_trace("pairwise deseq2 | before DESeqDataSetFromMatrix | formula=",
                    deparse(design_formula_deseq))
          dds_full <- DESeq2::DESeqDataSetFromMatrix(
            countData = round(rv_deg_main$raw_counts),
            colData = col_data_df_full,
            design = design_formula_deseq
          )
          deg_trace("pairwise deseq2 | before DESeq()")
          dds_full <- DESeq2::DESeq(dds_full, quiet = TRUE, sfType = "poscounts")
          deg_trace("pairwise deseq2 | DESeq() returned")
          
          contrast_pairs_deseq <- combn(levels(full_group_factor), 2, simplify = FALSE)
          for (pair in contrast_pairs_deseq) {
            ref_group_pair <- pair[1]
            treat_group_pair <- pair[2]
            comparison_name <- paste(treat_group_pair, "vs", ref_group_pair)
            shinyjs::html(progress_text_id, paste("Extracting DESeq2 results for", comparison_name, "..."))
            
            res_pairwise <- DESeq2::results(dds_full, contrast = c("condition", treat_group_pair, ref_group_pair))
            deg_pairwise_result <- as.data.frame(res_pairwise)
            deg_pairwise_result$gene_id <- rownames(deg_pairwise_result)
            # Standardize column names
            if("log2FoldChange" %in% colnames(deg_pairwise_result)) names(deg_pairwise_result)[names(deg_pairwise_result) == "log2FoldChange"] <- "log2FC"
            if("pvalue" %in% colnames(deg_pairwise_result)) names(deg_pairwise_result)[names(deg_pairwise_result) == "pvalue"] <- "P.Value"
            if("padj" %in% colnames(deg_pairwise_result)) names(deg_pairwise_result)[names(deg_pairwise_result) == "padj"] <- "adj.P.Val"
            
            deg_pairwise_result$comparison <- comparison_name
            deg_results_list[[comparison_name]] <- deg_pairwise_result
            comparison_names_list <- c(comparison_names_list, comparison_name)
          }
        }
        
        # Set the first comparison as active for initial display
        if(length(comparison_names_list) > 0) rv_deg_main$active_deg_comparison <- comparison_names_list[1]
        
      } else {
        stop("Invalid comparison method selected.")
      }
      
      # Step 5: Generate results
      update_progress("Step 5/5: Generating results and plots...", 95)
      deg_trace("Step5 start | n_results=", length(deg_results_list))

      # Combine all results if multiple comparisons were made
      if (length(deg_results_list) > 0) {
        # Ensure all data frames have the same required columns before rbind
        common_cols <- c("gene_id", "log2FC", "P.Value", "adj.P.Val", "comparison")
        
        final_deg_results_df <- do.call(rbind, lapply(names(deg_results_list), function(name) {
          df <- deg_results_list[[name]]
          if (!"gene_id" %in% colnames(df) && !is.null(rownames(df))) {
            df$gene_id <- rownames(df)
          }
          # Add missing common columns with NA if they don't exist
          missing_cols <- setdiff(common_cols, colnames(df))
          if (length(missing_cols) > 0) {
            df[missing_cols] <- NA
          }
          # Select and reorder to common columns
          return(df[, common_cols])
        }))
        rownames(final_deg_results_df) <- make.unique(paste(final_deg_results_df$gene_id, final_deg_results_df$comparison, sep="_"))
      } else {
        stop("No DEG results were generated.")
      }
      
      rv_deg_main$deg_results <- final_deg_results_df
      
      # Update UI elements
      updateTabsetPanel(session, "deg_results_tabs_main", selected = "deg_results_panel")
      update_progress("Analysis completed successfully!", 100)
      showNotification("DEG analysis completed successfully!", type = "message")
      
      # Re-enable the DEG button after successful completion
      shinyjs::enable("run_deg_main")
      shinyjs::html("run_deg_main", "<i class='fa fa-play'></i> Run DEG Analysis")
      deg_trace("main#2 SUCCESS")

    }, error = function(e) {
      deg_trace("main#2 ERROR caught: ", e$message)
      update_progress(paste("Error:", e$message), 100)
      showNotification(paste("Error in DEG analysis:", e$message), type = "error", duration = 10)
      rv_deg_main$deg_results <- NULL
      rv_deg_main$has_multiple_comparisons <- FALSE # Reset flag on error
      
      # Re-enable the DEG button on error
      shinyjs::enable("run_deg_main")
      shinyjs::html("run_deg_main", "<i class='fa fa-play'></i> Run DEG Analysis")
    })
  })
  # Re-enable DEG button when user changes analysis parameters
  observeEvent(list(input$deg_package_main, input$reference_group_main_specific, 
                    input$treatment_group_main_specific, input$pval_threshold_main,
                    input$fc_threshold_main), {
                      shinyjs::enable("run_deg_main")
                      shinyjs::html("run_deg_main", "<i class='fa fa-play'></i> Run DEG Analysis")
                    }, ignoreInit = TRUE)
  
  run_single_deg_analysis <- function(counts_data, normalized_data,
                                      design_matrix, # This is model.matrix for edgeR/limma
                                      col_data_df,   # Pass colData for DESeq2 (e.g., data.frame(condition=group_factor))
                                      design_formula, # Pass formula for DESeq2 (e.g., ~condition)
                                      contrast_def, deg_package,
                                      ref_group = NULL, treat_group = NULL, data_scale = "counts") {
    deg_trace("run_single_deg_analysis entry | engine=", deg_package,
              "| counts_dim=", paste(dim(counts_data), collapse = "x"),
              "| design_dim=", paste(dim(design_matrix), collapse = "x"),
              "| contrast_type=", as.character(contrast_def$type %||% "NA"))

    results_df <- NULL

    # Normalised or log-scale values (microarray, TPM/FPKM/RPKM): count models do not apply.
    # limma on log2 expression with an intensity-dependent prior variance (limma-trend).
    if (!identical(data_scale, "counts")) {
      E <- as.matrix(counts_data)
      if (identical(data_scale, "linear")) E <- log2(pmax(E, 0) + 1)
      keep <- rowSums(is.finite(E)) == ncol(E)
      keep[keep] <- apply(E[keep, , drop = FALSE], 1, var) > 0
      if (identical(data_scale, "linear")) keep <- keep & rowSums(E >= 1) >= min(3, ncol(E) / 2)  # value >= 1 in enough samples
      E <- E[keep, , drop = FALSE]
      print(paste("limma-trend on log2 expression:", nrow(E), "genes kept"))
      if (nrow(E) < 10) stop("Too few genes with varying expression remain for the analysis.")
      fit <- limma::lmFit(E, design_matrix)
      if (contrast_def$type == "coef") {
        fit <- limma::eBayes(fit, trend = TRUE, robust = TRUE)
        results_df <- limma::topTable(fit, coef = contrast_def$value, number = Inf, sort.by = "none")
      } else if (contrast_def$type == "contrast_matrix") {
        fit <- limma::eBayes(limma::contrasts.fit(fit, contrasts = contrast_def$value), trend = TRUE, robust = TRUE)
        results_df <- limma::topTable(fit, coef = 1, number = Inf, sort.by = "none")
      } else {
        stop("Unsupported contrast type for limma")
      }
      names(results_df)[names(results_df) == "logFC"] <- "log2FC"
      results_df$gene_id <- rownames(results_df)
      return(results_df)
    }

    # ✅ STEP 1: Create counts_data_processed FIRST
    counts_data_processed <- round(pmax(as.matrix(counts_data), 0))

    print(paste("📊 Input data:", nrow(counts_data_processed), "genes x",
                ncol(counts_data_processed), "samples"))
    
    # ✅ STEP 2: NOW apply pre-filtering (OPTIONAL - can be removed if you want)
    min_count <- 10
    min_samples <- min(3, ncol(counts_data_processed) / 2)  # Adaptive
    
    keep_genes <- rowSums(counts_data_processed >= min_count) >= min_samples
    
    n_input <- nrow(counts_data_processed)
    n_kept <- sum(keep_genes)
    
    print(paste("🔍 Gene filtering:", n_input, "→", n_kept, "genes"))
    
    if (n_kept < 100) {
      warning(paste("Only", n_kept, "genes pass filtering. Consider relaxing thresholds."))
    }
    
    if (n_kept < 10) {
      stop("Too few genes remain after filtering. Cannot proceed with analysis.")
    }
    
    # Apply filtering
    counts_data_processed <- counts_data_processed[keep_genes, , drop = FALSE]
    
    
    if (deg_package == "edgeR") {
      deg_trace("engine=edgeR | post-filter dim=",
                paste(dim(counts_data_processed), collapse = "x"),
                "| edgeR=", as.character(packageVersion("edgeR")))
      deg_trace("engine=edgeR | before DGEList")
      dge <- edgeR::DGEList(counts = counts_data_processed)
      deg_trace("engine=edgeR | before calcNormFactors")
      dge <- edgeR::calcNormFactors(dge)
      deg_trace("engine=edgeR | before estimateDisp")
      dge <- edgeR::estimateDisp(dge, design_matrix)
      deg_trace("engine=edgeR | before glmQLFit (legacy=TRUE)")
      # NOTE: edgeR 4.0+ introduced a new glmQLFit pipeline (legacy=FALSE default)
      # that C-stack-overflows on some datasets. Pipeline here pre-estimates
      # dispersion via estimateDisp(), so legacy=TRUE is the intended workflow
      # and uses the stable pre-4.0 quasi-likelihood path.
      fit <- tryCatch(
        edgeR::glmQLFit(dge, design_matrix, legacy = TRUE),
        error = function(e) {
          deg_trace("engine=edgeR | glmQLFit ERROR: ", e$message)
          stop(paste("edgeR glmQLFit failed:", e$message))
        }
      )
      deg_trace("engine=edgeR | glmQLFit complete")
      
      if (contrast_def$type == "coef") {
        qlf <- edgeR::glmQLFTest(fit, coef = contrast_def$value)
      } else if (contrast_def$type == "contrast_matrix") {
        qlf <- edgeR::glmQLFTest(fit, contrast = contrast_def$value)
      } else {
        stop("Unsupported contrast type for edgeR")
      }
      results_df <- edgeR::topTags(qlf, n = Inf, sort.by = "none")$table
      if("logFC" %in% colnames(results_df)) names(results_df)[names(results_df) == "logFC"] <- "log2FC"
      if("PValue" %in% colnames(results_df)) names(results_df)[names(results_df) == "PValue"] <- "P.Value"
      if("FDR" %in% colnames(results_df)) names(results_df)[names(results_df) == "FDR"] <- "adj.P.Val"
      
    } else if (deg_package == "deseq2") {
      # DESeq2 needs raw integer counts and colData
      # Use `counts_data_processed` which is the raw counts rounded and non-negative
      deg_trace("engine=deseq2 | before DESeqDataSetFromMatrix | formula=",
                deparse(design_formula))
      dds <- DESeq2::DESeqDataSetFromMatrix(countData = counts_data_processed,
                                            colData = col_data_df,
                                            design = design_formula)
      deg_trace("engine=deseq2 | DESeqDataSetFromMatrix returned")
      
      # For simple two-group from specific/simple:
      if (contrast_def$type == "contrast_vector" && length(contrast_def$value) == 3) {
        # Ensure the reference level is set correctly
        dds[[contrast_def$value[1]]] <- relevel(dds[[contrast_def$value[1]]], ref = contrast_def$value[3])
      }
      
      # ✅ DESeq2 handles normalization internally
      # User-selected normalization only affects QC plots, not DEG
      print("ℹ️ DESeq2 uses built-in size factor normalization for DEG analysis")
      
      # Run DESeq analysis. Wrap in tryCatch in case DESeq fails entirely.
      deg_trace("engine=deseq2 | before DESeq()")
      dds_analyzed <- tryCatch(
        DESeq2::DESeq(dds, quiet = TRUE, sfType = "poscounts"), # Added quiet and sfType
        error = function(e) {
          deg_trace("engine=deseq2 | DESeq() ERROR: ", e$message)
          message("DESeq2 analysis failed: ", e$message)
          stop(paste("DESeq2 analysis failed:", e$message, "This might be due to low counts or insufficient replicates."))
        }
      )
      deg_trace("engine=deseq2 | DESeq() returned")
      
      # Ensure dds_analyzed is valid before proceeding
      if (is.null(dds_analyzed) || !is(dds_analyzed, "DESeqDataSet")) {
        stop("DESeq2 analysis did not return a valid DESeqDataSet object.")
      }
      
      if (contrast_def$type == "coef") { # This case is less common for DESeq2, usually contrast vector
        # Assuming the last coefficient is the one of interest.
        res_name <- DESeq2::resultsNames(dds_analyzed)[contrast_def$value]
        res <- DESeq2::results(dds_analyzed, name=res_name)
      } else if (contrast_def$type == "contrast_vector") {
        # value should be c("factorName", "levelCase", "levelControl")
        res <- DESeq2::results(dds_analyzed, contrast = contrast_def$value)
      } else {
        stop("Unsupported contrast type for DESeq2")
      }
      results_df <- as.data.frame(res)
      if("log2FoldChange" %in% colnames(results_df)) names(results_df)[names(results_df) == "log2FoldChange"] <- "log2FC"
      if("pvalue" %in% colnames(results_df)) names(results_df)[names(results_df) == "pvalue"] <- "P.Value"
      if("padj" %in% colnames(results_df)) names(results_df)[names(results_df) == "padj"] <- "adj.P.Val"
      
    } else if (deg_package == "limma") {
      # limma-voom uses raw counts internally after DGEList
      # Pass `counts_data_processed` directly as the raw count input
      deg_trace("engine=limma | before DGEList")
      dge <- edgeR::DGEList(counts = counts_data_processed)
      deg_trace("engine=limma | before calcNormFactors")
      dge <- edgeR::calcNormFactors(dge, method = "TMM") # Apply TMM normalization factors
      
      # Filter low expression genes for limma
      keep <- edgeR::filterByExpr(dge, design_matrix)
      if (sum(keep) < 2) { # Ensure at least 2 genes remain for voom
        stop("Too few genes remain after filtering low expression for limma-voom analysis. Adjust your data or filtering criteria.")
      }
      dge <- dge[keep, ] # Keep only genes passing filter
      
      # Voom transformation
      # Voom takes DGEList object and converts to logCPM values and computes weights.
      deg_trace("engine=limma | before voom")
      v <- limma::voom(dge, design_matrix, plot = FALSE)
      deg_trace("engine=limma | voom complete")
      
      # Ensure no zero-variance genes after voom (though voom itself should filter some)
      row_variances <- apply(v$E, 1, var, na.rm = TRUE)
      zero_var_genes <- which(is.na(row_variances) | row_variances == 0)
      if (length(zero_var_genes) > 0) {
        message(paste("Removing", length(zero_var_genes), "zero-variance genes after voom transformation."))
        v$E <- v$E[-zero_var_genes, , drop = FALSE]
        v$weights <- v$weights[-zero_var_genes, , drop = FALSE]
        if(nrow(v$E) < 1) stop("No varying genes left after voom and zero-variance filtering.")
      }
      
      fit <- limma::lmFit(v, design_matrix)
      
      if (contrast_def$type == "coef") {
        fit_contrast <- limma::eBayes(fit)
        results_df <- limma::topTable(fit_contrast, coef = contrast_def$value, number = Inf, sort.by="none")
      } else if (contrast_def$type == "contrast_matrix") {
        fit_contrast <- limma::contrasts.fit(fit, contrasts = contrast_def$value)
        fit_contrast <- limma::eBayes(fit_contrast)
        results_df <- limma::topTable(fit_contrast, number = Inf, sort.by="none")
      } else {
        stop("Unsupported contrast type for limma")
      }
      if("logFC" %in% colnames(results_df)) names(results_df)[names(results_df) == "logFC"] <- "log2FC"
      # P.Value and adj.P.Val are usually correct from topTable
    }
    
    # Ensure gene_id column from rownames
    if (!is.null(results_df) && !"gene_id" %in% colnames(results_df)) {
      results_df$gene_id <- rownames(results_df)
    }
    
    return(results_df)
  }
  
  # Enhanced filtering function
  get_filtered_degs <- function(deg_data, pvalue_type, p_threshold, log2fc_min, log2fc_max) {
    if (is.null(deg_data) || nrow(deg_data) == 0) return(deg_data)
    
    # Select appropriate p-value column
    if (pvalue_type == "adjusted") {
      p_col <- "adj.P.Val"
    } else {
      p_col <- "P.Value"
    }
    
    # Apply filtering - only p-value and fold change cutoffs
    # Note: This function filters for significant genes that meet the fold change thresholds
    filtered <- deg_data %>%
      dplyr::filter(
        !!sym(p_col) < p_threshold,
        (log2FC <= log2fc_min | log2FC >= log2fc_max)
      )
    
    return(filtered)
  }
  
  # Universal gene ID to symbol conversion function
  convert_gene_ids_to_symbols_deg <- function(gene_ids, organism) {
    print(paste("DEBUG: Converting", length(gene_ids), "gene IDs for organism:", organism))
    
    # Organism to annotation package mapping
    org_db_mapping <- list(
      human = "org.Hs.eg.db",
      mouse = "org.Mm.eg.db",
      rat = "org.Rn.eg.db",
      fly = "org.Dm.eg.db",
      zebrafish = "org.Dr.eg.db",
      celegans = "org.Ce.eg.db",
      yeast = "org.Sc.sgd.db",
      arabidopsis = "org.At.tair.db",
      chicken = "org.Gg.eg.db",
      pig = "org.Ss.eg.db"
    )
    
    org_db_name <- org_db_mapping[[organism]]
    
    # Return original IDs with "-" as symbol if no annotation package
    if (is.null(org_db_name)) {
      print(paste("DEBUG: No annotation package for organism:", organism))
      return(data.frame(
        original_id = gene_ids,
        gene_symbol = rep("-", length(gene_ids)),
        conversion_status = rep("no_annotation", length(gene_ids)),
        stringsAsFactors = FALSE
      ))
    }
    
    # Check if annotation package is available
    if (!requireNamespace(org_db_name, quietly = TRUE)) {
      print(paste("DEBUG: Annotation package", org_db_name, "not available"))
      return(data.frame(
        original_id = gene_ids,
        gene_symbol = rep("-", length(gene_ids)),
        conversion_status = rep("package_missing", length(gene_ids)),
        stringsAsFactors = FALSE
      ))
    }
    
    # Load required libraries
    tryCatch({
      library(org_db_name, character.only = TRUE)
      library(AnnotationDbi)
      
      db_obj <- get(org_db_name)
      
      # Initialize results
      results <- data.frame(
        original_id = gene_ids,
        gene_symbol = as.character(gene_ids),  # Default to original ID
        conversion_status = rep("no_conversion", length(gene_ids)),
        stringsAsFactors = FALSE
      )
      
      # Clean gene IDs (remove version numbers from Ensembl IDs)
      clean_gene_ids <- gsub("\\.[0-9]+$", "", gene_ids)
      
      # Detect ID types
      enst_indices <- grep("^ENST", clean_gene_ids)
      ensg_indices <- grep("^ENSG", clean_gene_ids)
      ensembl_indices <- grep("^ENS[A-Z]*G", clean_gene_ids)  # Catch all Ensembl gene IDs
      entrez_indices <- grep("^[0-9]+$", clean_gene_ids)
      
      print(paste("DEBUG: ID types detected -",
                  "ENST:", length(enst_indices),
                  "ENSG:", length(ensg_indices),
                  "Ensembl:", length(ensembl_indices),
                  "Entrez:", length(entrez_indices)))
      
      # Special handling for yeast
      if (organism == "yeast") {
        print("DEBUG: Applying yeast-specific conversion")
        yeast_keytypes <- c("SYMBOL", "ORF", "GENENAME", "ENTREZID")
        
        for (kt in yeast_keytypes) {
          if (kt %in% AnnotationDbi::keytypes(db_obj)) {
            tryCatch({
              temp_mapped <- AnnotationDbi::mapIds(
                db_obj,
                keys = clean_gene_ids,
                column = "GENENAME",
                keytype = kt,
                multiVals = "first"
              )
              
              # Update results where conversion was successful
              converted_indices <- which(!is.na(temp_mapped))
              if (length(converted_indices) > 0) {
                results$gene_symbol[converted_indices] <- temp_mapped[converted_indices]
                results$conversion_status[converted_indices] <- paste0("converted_from_", kt)
                print(paste("DEBUG: Yeast conversion from", kt, ":", length(converted_indices), "genes"))
              }
            }, error = function(e) {
              print(paste("DEBUG: Yeast conversion from", kt, "failed:", e$message))
            })
          }
        }
      } else {
        # Standard organism conversion
        
        # 1. Convert Ensembl gene IDs (ENSG, etc.)
        if (length(ensembl_indices) > 0) {
          tryCatch({
            if ("ENSEMBL" %in% AnnotationDbi::keytypes(db_obj)) {
              ensembl_symbols <- AnnotationDbi::mapIds(
                db_obj,
                keys = clean_gene_ids[ensembl_indices],
                column = "SYMBOL",
                keytype = "ENSEMBL",
                multiVals = "first"
              )
              
              valid_indices <- which(!is.na(ensembl_symbols))
              if (length(valid_indices) > 0) {
                global_indices <- ensembl_indices[valid_indices]
                results$gene_symbol[global_indices] <- ensembl_symbols[valid_indices]
                results$conversion_status[global_indices] <- "converted_from_ENSEMBL"
                print(paste("DEBUG: Converted", length(valid_indices), "Ensembl IDs to symbols"))
              }
            }
          }, error = function(e) {
            print(paste("DEBUG: Ensembl conversion failed:", e$message))
          })
        }
        
        # 2. Convert Entrez IDs
        if (length(entrez_indices) > 0) {
          tryCatch({
            if ("ENTREZID" %in% AnnotationDbi::keytypes(db_obj)) {
              entrez_symbols <- AnnotationDbi::mapIds(
                db_obj,
                keys = clean_gene_ids[entrez_indices],
                column = "SYMBOL",
                keytype = "ENTREZID",
                multiVals = "first"
              )
              
              valid_indices <- which(!is.na(entrez_symbols))
              if (length(valid_indices) > 0) {
                global_indices <- entrez_indices[valid_indices]
                results$gene_symbol[global_indices] <- entrez_symbols[valid_indices]
                results$conversion_status[global_indices] <- "converted_from_ENTREZID"
                print(paste("DEBUG: Converted", length(valid_indices), "Entrez IDs to symbols"))
              }
            }
          }, error = function(e) {
            print(paste("DEBUG: Entrez conversion failed:", e$message))
          })
        }
        
        # 3. Handle transcript IDs (ENST) with biomaRt fallback
        if (length(enst_indices) > 0 && organism %in% c("human", "mouse")) {
          tryCatch({
            if (requireNamespace("biomaRt", quietly = TRUE)) {
              dataset_name <- if (organism == "human") "hsapiens_gene_ensembl" else "mmusculus_gene_ensembl"
              
              mart <- biomaRt::useMart("ensembl", dataset = dataset_name)
              
              transcript_mapping <- biomaRt::getBM(
                attributes = c("ensembl_transcript_id", "external_gene_name"),
                filters = "ensembl_transcript_id",
                values = clean_gene_ids[enst_indices],
                mart = mart
              )
              
              if (nrow(transcript_mapping) > 0) {
                for (i in seq_along(enst_indices)) {
                  transcript_id <- clean_gene_ids[enst_indices[i]]
                  matching_row <- which(transcript_mapping$ensembl_transcript_id == transcript_id)
                  
                  if (length(matching_row) > 0 && !is.na(transcript_mapping$external_gene_name[matching_row[1]])) {
                    results$gene_symbol[enst_indices[i]] <- transcript_mapping$external_gene_name[matching_row[1]]
                    results$conversion_status[enst_indices[i]] <- "converted_from_TRANSCRIPT"
                  }
                }
                print(paste("DEBUG: Converted", sum(results$conversion_status[enst_indices] == "converted_from_TRANSCRIPT"), "transcript IDs"))
              }
            }
          }, error = function(e) {
            print(paste("DEBUG: Transcript conversion failed:", e$message))
          })
        }
        
        # 4. Verify existing symbols
        symbol_indices <- which(results$conversion_status == "no_conversion")
        if (length(symbol_indices) > 0) {
          tryCatch({
            if ("SYMBOL" %in% AnnotationDbi::keytypes(db_obj)) {
              valid_symbols <- clean_gene_ids[symbol_indices] %in% AnnotationDbi::keys(db_obj, keytype = "SYMBOL")
              verified_indices <- symbol_indices[valid_symbols]
              if (length(verified_indices) > 0) {
                results$conversion_status[verified_indices] <- "verified_symbol"
                print(paste("DEBUG: Verified", length(verified_indices), "existing symbols"))
              }
            }
          }, error = function(e) {
            print(paste("DEBUG: Symbol verification failed:", e$message))
          })
        }
      }
      
      # Set unconverted genes to "-"
      unconverted_indices <- which(results$conversion_status == "no_conversion")
      if (length(unconverted_indices) > 0) {
        results$gene_symbol[unconverted_indices] <- "-"
        print(paste("DEBUG:", length(unconverted_indices), "genes could not be converted"))
      }
      
      # Summary
      conversion_summary <- table(results$conversion_status)
      print("DEBUG: Conversion summary:")
      print(conversion_summary)
      
      return(results)
      
    }, error = function(e) {
      print(paste("DEBUG: Gene conversion failed:", e$message))
      return(data.frame(
        original_id = gene_ids,
        gene_symbol = rep("-", length(gene_ids)),
        conversion_status = rep("conversion_error", length(gene_ids)),
        stringsAsFactors = FALSE
      ))
    })
  }
  
  # Enhanced create_gene_table function with gene name column
  create_gene_table_with_symbols <- function(data, table_id, organism) {
    withProgress(message = "Preparing gene table...", value = 0, {
      print(paste("DEBUG: Creating gene table with symbols for organism:", organism))
      
      # Step 1: Prepare Data
      incProgress(0.2, detail = "Validating input...")
      data <- as.data.frame(data)
      
      if (!"gene_id" %in% colnames(data)) {
        if ("Gene" %in% colnames(data)) {
          data <- data %>% dplyr::rename(gene_id = Gene)
        } else if (!is.null(rownames(data))) {
          data$gene_id <- rownames(data)
        } else {
          stop("Data must contain a 'gene_id' or 'Gene' column, or have rownames.")
        }
      }
      
      # Step 2: Gene ID Conversion
      incProgress(0.4, detail = "Converting gene IDs to symbols...")
      gene_conversion <- convert_gene_ids_to_symbols_deg(data$gene_id, organism)
      
      # Step 3: Add gene_name and reorder
      incProgress(0.2, detail = "Reformatting data...")
      data$gene_name <- gene_conversion$gene_symbol
      other_cols <- setdiff(colnames(data), c("gene_id", "gene_name"))
      data <- data %>% dplyr::select(gene_id, gene_name, dplyr::all_of(other_cols))
      
      # Step 4: Create the datatable
      incProgress(0.2, detail = "Rendering interactive table...")
      dt <- DT::datatable(
        data,
        selection = 'single',
        options = list(
          pageLength = 10,
          scrollY = "400px",
          scrollCollapse = TRUE,
          dom = 'frtip',
          ordering = TRUE,
          searching = TRUE,
          columnDefs = list(
            list(width = '150px', targets = 0),
            list(width = '120px', targets = 1),
            list(className = 'dt-center', targets = c(2, 3, 4))
          )
        ),
        rownames = FALSE,
        filter = 'top',
        escape = FALSE,
        callback = htmlwidgets::JS(sprintf("
        table.on('click.dt', 'tr', function() {
          var rowData = table.row(this).data();
          if (rowData && rowData[0]) {
            Shiny.setInputValue('%s_clicked_gene', rowData[0]);
          }
        });
      ", table_id))
      ) %>%
        DT::formatSignif(
          columns = grep("^(P\\.Value|adj\\.P\\.Val|FDR|PValue)$", colnames(data), value = TRUE),
          digits = 3
        ) %>%
        DT::formatRound(
          columns = grep("^(log2FC|logCPM|LR|AveExpr|B)$", colnames(data), value = TRUE),
          digits = 3
        )
      
      return(dt)
    })
  }
  
  
  organism_selected <- reactiveVal(FALSE)
  
  observeEvent(input$organism_deg_main, {
    if (is.null(input$organism_deg_main) || input$organism_deg_main == "") {
      organism_selected(FALSE)
      # Show validation message
      shinyjs::show("organism_validation_msg")
      # Add required field styling
      shinyjs::addClass("organism_deg_main", "required-field")
      shinyjs::removeClass("organism_deg_main", "organism-selected")
    } else {
      organism_selected(TRUE)
      # Hide validation message
      shinyjs::hide("organism_validation_msg")
      # Add success styling
      shinyjs::removeClass("organism_deg_main", "required-field")
      shinyjs::addClass("organism_deg_main", "organism-selected")
      
      # Show organism-specific information
      showNotification(
        paste("Organism selected:", input$organism_deg_main, "- Gene annotation will be available"),
        type = "message",
        duration = 3
      )
    }
  }, ignoreInit = TRUE)
  
  # 3. Reset organism selection when new dataset is loaded
  observeEvent(input$file_deg_main, {
    if (!is.null(input$file_deg_main)) {
      # Reset organism selection
      updateSelectInput(session, "organism_deg_main", selected = "")
      organism_selected(FALSE)
      
      # Show notification about organism selection
      showNotification(
        "New dataset loaded! Please select the appropriate organism for gene annotation.",
        type = "warning",
        duration = 5
      )
      
      # Scroll to organism selection (optional)
      shinyjs::runjs("document.getElementById('organism_deg_main').scrollIntoView({behavior: 'smooth'});")
    }
  })
  
  # 4. Validation function for analysis buttons
  validate_organism_selection <- function() {
    if (!organism_selected()) {
      showNotification(
        "Please select an organism before running the analysis. Gene names and annotations depend on organism selection.",
        type = "error",
        duration = 5
      )
      
      # Highlight the organism field
      shinyjs::addClass("organism_deg_main", "required-field")
      
      # Focus on organism selection
      shinyjs::runjs("document.getElementById('organism_deg_main').focus();")
      
      return(FALSE)
    }
    return(TRUE)
  }
  
  output$deg_table_main <- DT::renderDataTable({
    req(deg_data(), input$organism_deg_main)
    
    deg_df_to_display <- deg_data()
    current_organism <- input$organism_deg_main
    
    # Apply comparison filtering if needed
    if (rv_deg_main$has_multiple_comparisons && !is.null(rv_deg_main$active_deg_comparison)) {
      if (rv_deg_main$active_deg_comparison %in% unique(deg_df_to_display$comparison)) {
        deg_df_to_display <- deg_df_to_display %>%
          dplyr::filter(comparison == rv_deg_main$active_deg_comparison)
      }
    }
    
    # Remove comparison column for single view after filtering
    if ("comparison" %in% colnames(deg_df_to_display) && length(unique(deg_df_to_display$comparison)) <= 1) {
      deg_df_to_display$comparison <- NULL
    }
    
    print(paste("DEBUG: deg_table_main rendering with", nrow(deg_df_to_display), "rows for organism:", current_organism))
    
    create_gene_table_with_symbols(deg_df_to_display, "deg_table_main", current_organism)
  })
  
  
