      return(rv_deg_main$deg_results %>% dplyr::filter(comparison == rv_deg_main$active_deg_comparison))
    }
    return(rv_deg_main$deg_results)
  })
  
  # REMOVED: The old output$deg renderer. Functionality replaced by output$deg_table_main.
  # output$deg <- DT::renderDataTable({...})
  
  # Helper function to create interactive tables (adjusted for new structure)
  create_gene_table <- function(data, table_id) {
    # Ensure required columns exist and have appropriate names
    data <- as.data.frame(data)
    
    # Ensure 'gene_id' is present. If not, try 'Gene' or create from rownames.
    if (!"gene_id" %in% colnames(data)) {
      if ("Gene" %in% colnames(data)) {
        data <- data %>% dplyr::rename(gene_id = Gene)
      } else if (!is.null(rownames(data))) {
        data$gene_id <- rownames(data)
      } else {
        stop("Data must contain a 'gene_id' or 'Gene' column, or have rownames.")
      }
    }
    
    # Ensure gene_id is the first column
    data <- data %>% dplyr::select(gene_id, dplyr::everything())
    
    # Get the 0-indexed position of the gene column for JS callback
    # It will always be 0 because we just made it the first column.
    gene_col_index <- 0
    
    # Create the interactive table
    DT::datatable(
      data,
      selection = 'single',
      options = list(
        pageLength = 10,
        scrollY = "300px",
        scrollCollapse = TRUE,
        dom = 'frtip',
        ordering = TRUE,
        searching = TRUE
      ),
      rownames = FALSE,
      filter = 'top',
      escape = FALSE,
      callback = JS(sprintf("
      table.on('click.dt', 'tr', function() {
        // Get the data for the clicked row
        var rowData = table.row(this).data();
        // The Gene is in the column identified by gene_col_index (which is 0 here)
        var geneName = rowData[%s];
        // Send the gene name to Shiny
        Shiny.setInputValue('%s_clicked_gene', geneName, {priority: 'event'}); // Added priority
      });
    ", gene_col_index, table_id))
    ) %>%
      # Format numeric columns
      DT::formatSignif(
        columns = grep("^(P\\.Value|adj\\.P\\.Val|FDR|PValue)$", colnames(data), value = TRUE),
        digits = 3
      ) %>%
      DT::formatRound(
        columns = grep("^(log2FC|logFC|logCPM|LR|AveExpr|B|AveExpr)$", colnames(data), value = TRUE),
        digits = 3
      )
  }
  
