  output$download_all_degs_main <- downloadHandler(
    filename = function() {
      paste0("all_DEGs_with_names_", rv_deg_main$active_deg_comparison %||% "All", "_", Sys.Date(), ".csv")
    },
    content = function(file) {
      load_export_packages()
      req(deg_data(), input$organism_deg_main)
      
      # Show a notification as this can take a moment
      showNotification("Preparing and converting gene IDs for download...", type = "message", duration = 5)
      
      # 1. Get the current DEG data
      data_to_download <- deg_data()
      
      # 2. Call the CORRECT conversion function
      gene_conversion_df <- convert_gene_ids_to_symbols_deg(
        gene_ids = data_to_download$gene_id,
        organism = input$organism_deg_main
      )
      
      # 3. Safely add the new 'gene_symbol' column using a match
      # This ensures symbols are matched to the correct original ID
      data_to_download$gene_symbol <- gene_conversion_df$gene_symbol[
        match(data_to_download$gene_id, gene_conversion_df$original_id)
      ]
      
      # 4. Use original ID as a fallback if conversion failed
      failed_conversion_mask <- is.na(data_to_download$gene_symbol) | data_to_download$gene_symbol == "-"
      data_to_download$gene_symbol[failed_conversion_mask] <- data_to_download$gene_id[failed_conversion_mask]
      
      # 5. Reorder columns for a clean output file
      other_cols <- setdiff(colnames(data_to_download), c("gene_id", "gene_symbol"))
      final_data_for_download <- data_to_download %>%
        dplyr::select(gene_id, gene_symbol, dplyr::all_of(other_cols))
      
      # 6. Write the corrected data frame to the CSV file
      write.csv(final_data_for_download, file, row.names = FALSE)
    }
  )
  
