  rv_gene_mappings <- reactiveValues(cache = list())
  # Helper function to convert gene IDs (ENSG, ENST, or symbol) to ENSG IDs
  convert_to_ensg_id <- function(gene_name, organism = "human") {
    # Check cache first
    if (!is.null(rv_gene_mappings$cache[[gene_name]])) {
      return(rv_gene_mappings$cache[[gene_name]])
    }
    
    result <- list(ensg_id = NULL, status = "unknown", message = NULL)
    
    if (organism != "human") {
      result$status <- "non_human"
      result$message <- "Conversion only supported for human organism"
      rv_gene_mappings$cache[[gene_name]] <- result
      return(result)
    }
    
    # Check ID type and query accordingly
    if (grepl("^ENSG[0-9]+", gene_name)) {
      # Already an ENSG ID
      result$ensg_id <- gene_name
      result$status <- "success"
      result$message <- "Input is already an ENSG ID"
      
    } else if (grepl("^[0-9]+$", gene_name)) {
      # Handle Entrez IDs
      print(paste("DEBUG: Detected Entrez ID:", gene_name))
      
      tryCatch({
        # Make sure the organism database is loaded
        if (organism == "human") {
          if (!requireNamespace("org.Hs.eg.db", quietly = TRUE)) {
            stop("org.Hs.eg.db package required for Entrez conversion")
          }
          suppressPackageStartupMessages(library(org.Hs.eg.db))
          db_obj <- org.Hs.eg.db
        } else {
          # For other organisms, skip OpenTargets (it's human-only anyway)
          result$status <- "non_human_entrez"
          result$message <- "OpenTargets only supports human genes"
          rv_gene_mappings$cache[[gene_name]] <- result
          return(result)
        }
        
        # Direct conversion using AnnotationDbi
        ensembl_result <- tryCatch({
          AnnotationDbi::mapIds(
            db_obj,
            keys = gene_name,
            column = "ENSEMBL",
            keytype = "ENTREZID",
            multiVals = "first"
          )
        }, error = function(e) {
          print(paste("DEBUG: AnnotationDbi mapIds error:", e$message))
          return(NA)
        })
        
        if (!is.na(ensembl_result) && !is.null(ensembl_result) && 
            ensembl_result != "" && nchar(ensembl_result) > 0) {
          result$ensg_id <- as.character(ensembl_result)
          result$status <- "success"
          result$message <- paste("Entrez ID", gene_name, "mapped to ENSG:", result$ensg_id)
          print(paste("DEBUG: Entrez conversion successful:", gene_name, "->", result$ensg_id))
        } else {
          # Try getting symbol first, then symbol to ENSEMBL
          symbol_result <- tryCatch({
            AnnotationDbi::mapIds(
              db_obj,
              keys = gene_name,
              column = "SYMBOL",
              keytype = "ENTREZID",
              multiVals = "first"
            )
          }, error = function(e) NA)
          
          if (!is.na(symbol_result) && !is.null(symbol_result)) {
            # Try symbol to ENSEMBL
            ensembl_from_symbol <- tryCatch({
              AnnotationDbi::mapIds(
                db_obj,
                keys = as.character(symbol_result),
                column = "ENSEMBL",
                keytype = "SYMBOL",
                multiVals = "first"
              )
            }, error = function(e) NA)
            
            if (!is.na(ensembl_from_symbol) && !is.null(ensembl_from_symbol)) {
              result$ensg_id <- as.character(ensembl_from_symbol)
              result$status <- "success"
              result$message <- paste("Entrez", gene_name, "-> Symbol", symbol_result, "-> ENSG:", result$ensg_id)
              print(paste("DEBUG: Two-step conversion successful:", gene_name, "->", symbol_result, "->", result$ensg_id))
            } else {
              result$status <- "partial"
              result$message <- paste("Found symbol", symbol_result, "but no ENSEMBL mapping")
            }
          } else {
            result$status <- "no_mapping"
            result$message <- paste("No mapping found for Entrez ID", gene_name)
          }
        }
        
      }, error = function(e) {
        result$status <- "conversion_error"
        result$message <- paste("Error converting Entrez ID:", e$message)
        print(paste("DEBUG: Entrez conversion error:", e$message))
      })
      
    } else if (grepl("^ENST[0-9]+", gene_name)) {
      # ENST (transcript) ID: map to ENSG using BioMart
      if (requireNamespace("biomaRt", quietly = TRUE)) {
        ensembl <- tryCatch(
          biomaRt::useMart("ensembl", dataset = "hsapiens_gene_ensembl"),
          error = function(e) NULL
        )
        
        if (!is.null(ensembl)) {
          mapping <- tryCatch(
            biomaRt::getBM(
              attributes = c("ensembl_transcript_id", "ensembl_gene_id", "gene_biotype"),
              filters = "ensembl_transcript_id",
              values = gene_name,
              mart = ensembl
            ),
            error = function(e) data.frame()
          )
          
          if (nrow(mapping) > 0) {
            result$ensg_id <- mapping$ensembl_gene_id[1]
            result$status <- "success"
            result$message <- paste("ENST mapped to ENSG:", result$ensg_id,
                                    "(biotype:", mapping$gene_biotype[1], ")")
          } else {
            result$status <- "no_mapping"
            result$message <- paste("No ENSG ID found for transcript", gene_name)
          }
        } else {
          result$status <- "biomart_error"
          result$message <- "Failed to connect to BioMart for transcript conversion"
        }
      } else {
        result$status <- "no_biomart"
        result$message <- "BioMart not available for transcript conversion"
      }
      
    } else if (grepl("^[A-Z]{2}[0-9]+\\.[0-9]+$", gene_name)) {
      # RefSeq ID: try BioMart
      if (requireNamespace("biomaRt", quietly = TRUE)) {
        ensembl <- tryCatch(
          biomaRt::useMart("ensembl", dataset = "hsapiens_gene_ensembl"),
          error = function(e) NULL
        )
        
        if (!is.null(ensembl)) {
          mapping <- tryCatch(
            biomaRt::getBM(
              attributes = c("refseq_mrna", "ensembl_gene_id", "gene_biotype"),
              filters = "refseq_mrna",
              values = gene_name,
              mart = ensembl
            ),
            error = function(e) data.frame()
          )
          
          if (nrow(mapping) > 0) {
            result$ensg_id <- mapping$ensembl_gene_id[1]
            result$status <- "success"
            result$message <- paste("RefSeq mapped to ENSG:", result$ensg_id,
                                    "(biotype:", mapping$gene_biotype[1], ")")
          } else {
            result$status <- "no_mapping"
            result$message <- paste("No ENSG ID found for RefSeq ID", gene_name)
          }
        } else {
          result$status <- "biomart_error"
          result$message <- "Failed to connect to BioMart for RefSeq conversion"
        }
      } else {
        result$status <- "no_biomart"
        result$message <- "BioMart not available for RefSeq conversion"
      }
      
    } else {
      # Assume it's a gene symbol - try AnnotationDbi first, then BioMart
      print(paste("DEBUG: Detected gene symbol:", gene_name, "- Using AnnotationDbi conversion"))
      
      tryCatch({
        if (requireNamespace("org.Hs.eg.db", quietly = TRUE) &&
            requireNamespace("AnnotationDbi", quietly = TRUE)) {
          
          # ✅ FIXED: Proper library loading and error handling
          suppressPackageStartupMessages({
            library(org.Hs.eg.db, quietly = TRUE)
          })
          
          # ✅ FIXED: Use tryCatch around the mapIds call specifically
          ensembl_result <- tryCatch({
            AnnotationDbi::mapIds(
              org.Hs.eg.db,
              keys = gene_name,
              column = "ENSEMBL",
              keytype = "SYMBOL",
              multiVals = "first"
            )
          }, error = function(e) {
            print(paste("DEBUG: AnnotationDbi::mapIds error:", e$message))
            return(NA)
          })
          
          # ✅ FIXED: Proper checking for S4 objects and results
          if (!is.null(ensembl_result) && length(ensembl_result) > 0) {
            # Convert S4 object to character if needed
            ensembl_value <- tryCatch({
              as.character(ensembl_result)[1]  # Get first element as character
            }, error = function(e) {
              print(paste("DEBUG: Error converting result to character:", e$message))
              return(NA)
            })
            
            # ✅ FIXED: Safe checking for valid results
            if (!is.na(ensembl_value) && !is.null(ensembl_value) &&
                ensembl_value != "" && ensembl_value != "NA") {
              result$ensg_id <- ensembl_value
              result$status <- "success"
              result$message <- paste("Symbol", gene_name, "mapped via AnnotationDbi to ENSG:", result$ensg_id)
              print(paste("DEBUG: AnnotationDbi symbol conversion successful:", gene_name, "->", result$ensg_id))
            } else {
              print(paste("DEBUG: AnnotationDbi returned invalid result for", gene_name, ":", ensembl_value))
              # Try BioMart fallback...
              result <- try_biomart_conversion(gene_name, result)
            }
          } else {
            print(paste("DEBUG: AnnotationDbi returned NULL/empty result for", gene_name))
            # Try BioMart fallback...
            result <- try_biomart_conversion(gene_name, result)
          }
          
        } else {
          result$status <- "no_annotation"
          result$message <- "AnnotationDbi packages not available for symbol conversion"
          print("DEBUG: Required packages not available")
        }
        
      }, error = function(e) {
        result$status <- "conversion_error"
        result$message <- paste("Error converting symbol", gene_name, ":", e$message)
        print(paste("DEBUG: Error in symbol conversion:", e$message))
      })
    }
    
    print(paste("DEBUG: convert_to_ensg_id result for", gene_name,
                "- Status:", result$status,
                "- ENSG:", ifelse(is.null(result$ensg_id), "NULL", result$ensg_id),
                "- Message:", result$message))
    
    # Cache the result
    rv_gene_mappings$cache[[gene_name]] <- result
    return(result)
  }
  
