  observeEvent(input$deg_table_main_clicked_gene, {
    print(paste("DEBUG: Click event triggered for deg_table_main_clicked_gene:", input$deg_table_main_clicked_gene))
    
    req(input$deg_table_main_clicked_gene, rv_deg_main$deg_results)
    
    gene_name <- input$deg_table_main_clicked_gene
    print(paste("DEBUG: Gene name from click:", gene_name))
    
    # Get gene data
    gene_data_raw <- as.data.frame(lapply(rv_deg_main$deg_results, function(col) {
      if (inherits(col, "Rle")) as.vector(col) else col
    }))
    
    # Data type conversions
    if ("gene_id" %in% colnames(gene_data_raw)) {
      gene_data_raw$gene_id <- as.character(gene_data_raw$gene_id)
    }
    if ("log2FC" %in% colnames(gene_data_raw)) {
      gene_data_raw$log2FC <- as.numeric(gene_data_raw$log2FC)
    }
    if ("adj.P.Val" %in% colnames(gene_data_raw)) {
      gene_data_raw$adj.P.Val <- as.numeric(gene_data_raw$adj.P.Val)
    }
    
    gene_data <- gene_data_raw %>%
      dplyr::filter(gene_id == gene_name) %>%
      dplyr::slice(1)
    
    if (nrow(gene_data) == 0) {
      showNotification(paste("Gene data not found for:", gene_name), type = "warning")
      return()
    }
    
    # Reset reactive values
    rv_modal_gene_info$gene_name <- NULL
    rv_modal_gene_info$gene_data <- NULL
    rv_modal_gene_info$ot_data <- NULL
    rv_modal_gene_info$mouse_data <- NULL
    
    current_organism <- isolate(input$organism_deg_main)
    print(paste("DEBUG: Fetching info for organism:", current_organism))
    
    # Only fetch API data for human and mouse
    if (current_organism == "human") {
      progress_id <- showNotification("Fetching gene information...", duration = NULL, closeButton = FALSE, type = "message")
      
      tryCatch({
        rv_modal_gene_info$gene_name <- gene_name
        rv_modal_gene_info$gene_data <- gene_data
        
        conversion_result <- convert_to_ensg_id(gene_name, organism = "human")
        
        if (!is.null(conversion_result$ensg_id)) {
          print(paste("DEBUG: Querying OpenTargets with ENSEMBL ID:", conversion_result$ensg_id))
          rv_modal_gene_info$ot_data <- fetch_opentargets_data(conversion_result$ensg_id)
        }
        
        removeNotification(progress_id)
        showGeneModal(gene_name, gene_data)
        
      }, error = function(e) {
        removeNotification(progress_id)
        showNotification(paste("Error fetching gene info:", e$message), type = "error")
        # Show basic modal even if API fails
        showGeneModal(gene_name, gene_data)
      })
      
    } else if (current_organism == "mouse") {
      progress_id <- showNotification("Fetching gene information...", duration = NULL, closeButton = FALSE, type = "message")
      
      tryCatch({
        rv_modal_gene_info$gene_name <- gene_name
        rv_modal_gene_info$gene_data <- gene_data
        rv_modal_gene_info$mouse_data <- get_mouse_gene_info(gene_name)
        
        removeNotification(progress_id)
        showGeneModal(gene_name, gene_data)
        
      }, error = function(e) {
        removeNotification(progress_id)
        showNotification(paste("Error fetching gene info:", e$message), type = "error")
        # Show basic modal even if API fails
        showGeneModal(gene_name, gene_data)
      })
      
    } else {
      # For all other organisms, show universal modal immediately (no API calls)
      print(paste("DEBUG: Showing universal modal for organism:", current_organism))
      showGeneModal(gene_name, gene_data)
    }
  })
  
  observeEvent(input$up_genes_table_main_clicked_gene, {
    print(paste("DEBUG: Click event triggered for up_genes_table_main_clicked_gene:", input$up_genes_table_main_clicked_gene))
    print(paste("DEBUG: Structure of rv_deg_main$deg_results:", str(rv_deg_main$deg_results)))
    
    req(input$up_genes_table_main_clicked_gene, rv_deg_main$deg_results)
    
    gene_name <- input$up_genes_table_main_clicked_gene
    print(paste("DEBUG: Gene name from click:", gene_name))
    
    # Convert rv_deg_main$deg_results to a standard data frame and handle all columns
    gene_data_raw <- as.data.frame(lapply(rv_deg_main$deg_results, function(col) {
      if (inherits(col, "Rle")) {
        as.vector(col) # Convert Rle to vector
      } else {
        col
      }
    }))
    
    # Explicitly convert key columns to ensure correct types
    if ("gene_id" %in% colnames(gene_data_raw)) {
      gene_data_raw$gene_id <- as.character(gene_data_raw$gene_id)
    }
    if ("log2FC" %in% colnames(gene_data_raw)) {
      gene_data_raw$log2FC <- as.numeric(gene_data_raw$log2FC)
    }
    if ("adj.P.Val" %in% colnames(gene_data_raw)) {
      gene_data_raw$adj.P.Val <- as.numeric(gene_data_raw$adj.P.Val)
    }
    if ("AveExpr" %in% colnames(gene_data_raw)) {
      gene_data_raw$AveExpr <- as.numeric(gene_data_raw$AveExpr)
    }
    if ("B" %in% colnames(gene_data_raw)) {
      gene_data_raw$B <- as.numeric(gene_data_raw$B)
    }
    
    if (!("gene_id" %in% colnames(gene_data_raw))) {
      print("DEBUG: 'gene_id' column not found in DEG results data frame.")
      showNotification("Internal error: 'gene_id' column missing from DEG results.", type = "error", duration = 5)
      return()
    }
    
    gene_data <- gene_data_raw %>%
      dplyr::filter(gene_id == gene_name) %>%
      dplyr::slice(1)
    
    if (nrow(gene_data) == 0) {
      showNotification(paste("Gene data not found for:", gene_name, "in DEG results after filtering."), type = "warning")
      return()
    }
    
    # Reset reactive values for new gene click
    rv_modal_gene_info$gene_name <- NULL
    rv_modal_gene_info$gene_data <- NULL
    rv_modal_gene_info$ot_data <- NULL
    rv_modal_gene_info$mouse_data <- NULL
    
    # Show progress immediately for API calls
    progress_id <- showNotification("Fetching gene information...", duration = NULL, closeButton = FALSE, type = "message")
    
    tryCatch({
      # Store the initial data for the modal
      rv_modal_gene_info$gene_name <- gene_name
      rv_modal_gene_info$gene_data <- gene_data
      
      current_organism <- isolate(input$organism_deg_main)
      print(paste("DEBUG: Fetching info for organism:", current_organism))
      
      if (current_organism == "human") {
        # Convert gene_name to ENSG ID
        conversion_result <- convert_to_ensg_id(gene_name, organism = "human")
        
        if (!is.null(conversion_result$ensg_id)) {
          print(paste("DEBUG: Querying OpenTargets with ENSEMBL ID:", conversion_result$ensg_id))
          rv_modal_gene_info$ot_data <- fetch_opentargets_data(conversion_result$ensg_id)
          if (is.null(rv_modal_gene_info$ot_data)) {
            showNotification(
              paste("No OpenTargets data available for gene", conversion_result$ensg_id,
                    "(from", gene_name, "). This may be a pseudogene, lncRNA, or non-covered gene."),
              type = "warning", duration = 7
            )
          }
        } else {
          # Tailored message based on conversion result
          if (grepl("^ENST[0-9]+", gene_name) && conversion_result$status == "no_mapping") {
            showNotification(
              paste("No gene ID found for transcript", gene_name, ". It may not be a valid or mapped transcript."),
              type = "warning", duration = 7
            )
          } else if (grepl("^[A-Z]{2}[0-9]+\\.[0-9]+$", gene_name) && conversion_result$status == "no_mapping") {
            showNotification(
              paste("No ENSG ID found for RefSeq ID", gene_name,
                    ". It may be a non-Ensembl gene or unmapped transcript."),
              type = "warning", duration = 7
            )
          } else {
            showNotification(
              paste("Could not convert", gene_name, "to an ENSG ID for OpenTargets:",
                    conversion_result$message),
              type = "warning", duration = 7
            )
          }
        }
        
      } else if (current_organism == "mouse") {
        print(paste("DEBUG: Querying MouseMine for gene:", gene_name))
        rv_modal_gene_info$mouse_data <- get_mouse_gene_info(gene_name)
      } else {
        print(paste("DEBUG: No external API data for organism:", current_organism))
      }
      
      removeNotification(progress_id)
      removeModal()
      
      showGeneModal(gene_name, gene_data)
      
    }, error = function(e) {
      removeNotification(progress_id)
      showNotification(paste("Error fetching gene info for", gene_name, ":", e$message), type = "error", duration = NULL)
      print(paste("ERROR in gene info observer for", gene_name, ":", e$message))
      removeModal()
      showModal(modalDialog(
        title = "Error Fetching Gene Info",
        paste("An error occurred while retrieving data for gene", gene_name, ":", e$message),
        footer = modalButton("Close"),
        easyClose = TRUE
      ))
    })
  })
  
