  safe_extract <- function(obj, key) {
    if (is.null(obj) || is.null(obj[[key]])) {
      return(NULL)
    }
    return(obj[[key]])
  }
  
  # Helper function for null coalescing (already defined, keeping for context)
  `%||%` <- function(x, y) if (is.null(x)) y else x
  
  if (!exists("%||%")) {
    `%||%` <- function(x, y) if (is.null(x) || length(x) == 0 || (length(x) == 1 && is.na(x))) y else x
  }
  # Download handler for individual gene reports in Excel format (using rv_deg_main)
  output$download_gene_info <- downloadHandler(
    filename = function() {
      # Determine the gene name from the currently selected row in any of the tables
      gene_name <- NULL
      gene_data_for_download <- NULL
      
      # Determine which table provided the latest click event for gene info modal
      if (!is.null(input$deg_table_main_clicked_gene)) {
        gene_name <- input$deg_table_main_clicked_gene
        gene_data_for_download <- deg_data() %>% dplyr::filter(gene_id == gene_name)
      } else if (!is.null(input$up_genes_table_main_clicked_gene)) {
        gene_name <- input$up_genes_table_main_clicked_gene
        gene_data_for_download <- deg_data() %>% dplyr::filter(gene_id == gene_name)
      } else if (!is.null(input$down_genes_table_main_clicked_gene)) {
        gene_name <- input$down_genes_table_main_clicked_gene
        gene_data_for_download <- deg_data() %>% dplyr::filter(gene_id == gene_name)
      }
      load_export_packages()
      req(gene_name, gene_data_for_download)
      paste0(gene_name, "_report.xlsx")
    },
    content = function(file) {
      load_export_packages()
      # Re-extract gene_name and gene_data based on the latest click for download
      gene_name <- NULL
      gene_data_for_download <- NULL
      
      if (!is.null(input$deg_table_main_clicked_gene)) {
        gene_name <- input$deg_table_main_clicked_gene
        gene_data_for_download <- deg_data() %>% dplyr::filter(gene_id == gene_name)
      } else if (!is.null(input$up_genes_table_main_clicked_gene)) {
        gene_name <- input$up_genes_table_main_clicked_gene
        gene_data_for_download <- deg_data() %>% dplyr::filter(gene_id == gene_name)
      } else if (!is.null(input$down_genes_table_main_clicked_gene)) {
        gene_name <- input$down_genes_table_main_clicked_gene
        gene_data_for_download <- deg_data() %>% dplyr::filter(gene_id == gene_name)
      }
      
      req(gene_name, gene_data_for_download)
      
      # Convert gene symbol to ENSEMBL ID for OpenTargets if needed
      ensembl_id_for_ot <- NULL
      if (input$organism_deg_main == "human") {
        # Check if the gene_name is already an ENSEMBL ID
        if (grepl("^ENSG", gene_name)) {
          ensembl_id_for_ot <- gene_name
        } else {
          # Attempt to convert symbol to ENSEMBL
          converted_id <- mapIds(org.Hs.eg.db, keys = gene_name, column = "ENSEMBL", keytype = "SYMBOL", multiVals = "first")
          if (!is.na(converted_id)) {
            ensembl_id_for_ot <- converted_id
          }
        }
      }
      
      ot_data <- NULL
      if (!is.null(ensembl_id_for_ot)) {
        ot_data <- fetch_opentargets_data(ensembl_id_for_ot)
      }
      
      # Create workbook
      wb <- openxlsx::createWorkbook()
      
      # Add styling
      hs <- openxlsx::createStyle(textDecoration = "BOLD", fontSize = 12)
      
      # Basic Information Sheet
      openxlsx::addWorksheet(wb, "Basic Information")
      basic_info_df <- data.frame(
        Category = c("Gene ID", "Approved Symbol", "Approved Name", "Log2 FC",
                     "Adjusted P-value"),
        Value = c(
          gene_name,
          safe_extract(ot_data, "approvedSymbol") %||% "N/A",
          safe_extract(ot_data, "approvedName") %||% "N/A",
          sprintf("%.3f", gene_data_for_download$log2FC[1]),
          sprintf("%.2e", gene_data_for_download$adj.P.Val[1])
        ),
        stringsAsFactors = FALSE
      )
      # Add AveExpr and B-statistic if they exist in gene_data_for_download
      if ("AveExpr" %in% colnames(gene_data_for_download)) {
        basic_info_df <- rbind(basic_info_df, data.frame(Category="Average Expression", Value=sprintf("%.3f", gene_data_for_download$AveExpr[1])))
      }
      if ("B" %in% colnames(gene_data_for_download)) {
        basic_info_df <- rbind(basic_info_df, data.frame(Category="B-statistic", Value=sprintf("%.3f", gene_data_for_download$B[1])))
      }
      
      openxlsx::writeData(wb, "Basic Information", basic_info_df)
      openxlsx::addStyle(wb, "Basic Information", hs, rows = 1, cols = 1:2)
      
      # Function Descriptions Sheet
      func_desc <- safe_extract(ot_data, "functionDescriptions")
      if (!is.null(func_desc) && length(func_desc) > 0) {
        openxlsx::addWorksheet(wb, "Function Descriptions")
        func_desc_df <- data.frame(
          Description = func_desc,
          stringsAsFactors = FALSE
        )
        openxlsx::writeData(wb, "Function Descriptions", func_desc_df)
        openxlsx::addStyle(wb, "Function Descriptions", hs, rows = 1, cols = 1)
      }
      
      # Disease Associations Sheet
      if (!is.null(ot_data$associatedDiseases) && !is.null(ot_data$associatedDiseases$rows)) {
        diseases <- data.frame(
          Disease = ot_data$associatedDiseases$rows$disease$name,
          'Therapeutic Areas' = sapply(ot_data$associatedDiseases$rows$disease$therapeuticAreas, function(areas) {
            if (!is.null(areas) && nrow(areas) > 0) {
              paste(areas$name, collapse = ", ")
            } else {
              "N/A"
            }
          }),
          Score = round(ot_data$associatedDiseases$rows$score, 3),
          stringsAsFactors = FALSE
        )
        openxlsx::addWorksheet(wb, "Disease Associations")
        openxlsx::writeData(wb, "Disease Associations", diseases)
        openxlsx::addStyle(wb, "Disease Associations", hs, rows = 1, cols = 1:3)
        openxlsx::setColWidths(wb, "Disease Associations", cols = 1:3, widths = "auto")
      }
      
      # Subcellular Locations Sheet
      locations_data <- safe_extract(ot_data, "subcellularLocations")
      if (!is.null(locations_data) && nrow(locations_data) > 0) {
        openxlsx::addWorksheet(wb, "Subcellular Locations")
        locations <- as.data.frame(locations_data)
        openxlsx::writeData(wb, "Subcellular Locations", locations)
        openxlsx::addStyle(wb, "Subcellular Locations", hs, rows = 1, cols = 1:2)
        openxlsx::setColWidths(wb, "Subcellular Locations", cols = 1:2, widths = "auto")
      }
      
      # Tractability Sheet
      tractability_data <- safe_extract(ot_data, "tractability")
      if (!is.null(tractability_data) && nrow(tractability_data) > 0) {
        tractability <- as.data.frame(tractability_data)
        openxlsx::addWorksheet(wb, "Tractability")
        openxlsx::writeData(wb, "Tractability", tractability)
        openxlsx::addStyle(wb, "Tractability", hs, rows = 1, cols = 1:2)
        openxlsx::setColWidths(wb, "Tractability", cols = 1:2, widths = "auto")
      }
      
      # Save workbook
      openxlsx::saveWorkbook(wb, file, overwrite = TRUE)
    }
  )
  
