  # Helper function to try multiple Ensembl mirrors for biomaRt
  try_biomart_mirrors <- function(dataset) {
    mirrors <- c(
      "www.ensembl.org",
      "useast.ensembl.org",
      "uswest.ensembl.org",
      "asia.ensembl.org",
      "grch37.ensembl.org" # Old archive for human if main fails
    )
    for (mirror in mirrors) {
      tryCatch({
        message(paste("Trying BioMart mirror:", mirror))
        mart <- biomaRt::useEnsembl(biomart = "ensembl", dataset = dataset, host = mirror)
        if (!is.null(mart)) {
          message(paste("Successfully connected to BioMart mirror:", mirror))
          return(mart)
        }
      }, error = function(e) {
        message(paste("BioMart mirror", mirror, "failed:", e$message))
      })
    }
    message("All BioMart mirrors failed.")
    return(NULL)
  }
  
  # --- REVISED detect_id_type function ---
  
  detect_id_type <- function(genes) {
    genes_clean <- gsub("\\.[0-9]*$", "", genes)  # Strip versions if present
    types <- sapply(genes_clean, function(gene) {
      if (grepl("^ENST[0-9]+$", gene, ignore.case = TRUE)) {
        return("ENSEMBLTRANS")
      } else if (grepl("^ENSG[0-9]+$", gene, ignore.case = TRUE)) {
        return("ENSEMBL")
      } else if (grepl("^[0-9]+$", gene)) {
        return("ENTREZID")
      } else if (grepl("^[A-Za-z0-9-]+$", gene)) {
        return("SYMBOL")
      } else {
        return("UNKNOWN")
      }
    })
    
    detected_types <- unique(types)
    if (length(detected_types) == 1) {
      return(detected_types)
    } else {
      return("mixed")
    }
  }
  
  
  
  # Robust Gene ID Conversion Function
  convert_gene_ids <- function(genes, from_org = "human", to_type = "SYMBOL") {
    if (is.null(genes) || length(genes) == 0) return(character(0))
    
    # Remove version numbers and ensure uniqueness
    genes_clean <- unique(gsub("\\.[0-9]*$", "", genes))
    message(paste("Starting conversion for", length(genes_clean), "unique genes."))
    
    # Detect ID type
    detected_type <- detect_id_type(genes_clean)
    message(paste("Detected input ID type:", detected_type))
    
    ## 🔧 NEW: Handle mixed ID types
    if (detected_type == "mixed") {
      message("Detected mixed ID types. Processing separately...")
      
      # Re-detect each gene's type individually
      gene_types <- sapply(genes_clean, function(g) detect_id_type(g))
      
      results <- character(length(genes_clean))
      names(results) <- genes_clean
      
      for (type in unique(gene_types)) {
        message(paste("Processing", sum(gene_types == type), type, "genes..."))
        subset_genes <- genes_clean[gene_types == type]
        
        # Recursively call convert_gene_ids for each subset
        converted_subset_raw <- convert_gene_ids(subset_genes, from_org = from_org, to_type = to_type)
        
        # 🔧 FIX: Handle the case when converted genes are fewer than input genes
        if (length(converted_subset_raw) > 0) {
          # If converted_subset_raw has names, use them to map back to original genes
          if (!is.null(names(converted_subset_raw))) {
            # Map back using names
            for (original_gene in subset_genes) {
              if (original_gene %in% names(converted_subset_raw)) {
                results[original_gene] <- converted_subset_raw[original_gene]
              }
            }
          } else {
            # If no names, we can only assign what we can map back
            # In this case, we'll take the first N converted genes for the first N subset genes
            n_to_assign <- min(length(subset_genes), length(converted_subset_raw))
            if (n_to_assign > 0) {
              results[subset_genes[1:n_to_assign]] <- converted_subset_raw[1:n_to_assign]
            }
          }
        }
        
        # Count successful mappings for this type
        mapped_for_type <- sum(!is.na(results[subset_genes]) & nchar(results[subset_genes]) > 0)
        unmapped_for_type <- subset_genes[is.na(results[subset_genes]) | nchar(results[subset_genes]) == 0]
        
        message(paste("Successfully mapped", mapped_for_type, "out of", length(subset_genes), type, "genes"))
        if (length(unmapped_for_type) > 0) {
          message("Unmapped genes (sample):", paste(head(unmapped_for_type, 5), collapse = ", "))
        }
      }
      
      mapped_count <- sum(!is.na(results) & nchar(results) > 0)
      message(paste("Mixed ID mapping completed. Total mapped:", mapped_count, "out of", length(genes_clean)))
      
      # Return only the successfully mapped genes (non-NA, non-empty)
      final_results <- results[!is.na(results) & nchar(results) > 0]
      return(final_results)
    }
    
    # Organism-specific setup
    organism_map <- list(
      "human" = list(org_db = "org.Hs.eg.db", bm_dataset = "hsapiens_gene_ensembl"),
      "mouse" = list(org_db = "org.Mm.eg.db", bm_dataset = "mmusculus_gene_ensembl"),
      "rat" = list(org_db = "org.Rn.eg.db", bm_dataset = "rnorvegicus_gene_ensembl"),
      "fly" = list(org_db = "org.Dm.eg.db", bm_dataset = "dmelanogaster_gene_ensembl"),
      "zebrafish" = list(org_db = "org.Dr.eg.db", bm_dataset = "drerio_gene_ensembl"),
      "celegans" = list(org_db = "org.Ce.eg.db", bm_dataset = "celegans_gene_ensembl"),
      "yeast" = list(org_db = "org.Sc.sgd.db", bm_dataset = "scerevisiae_gene_ensembl"),
      "arabidopsis" = list(org_db = "org.At.tair.db", bm_dataset = "athaliana_gene_ensembl"),
      "chicken" = list(org_db = "org.Gg.eg.db", bm_dataset = "ggallus_gene_ensembl"),
      "pig" = list(org_db = "org.Ss.eg.db", bm_dataset = "sscrofa_gene_ensembl")
    )
    
    org_info <- organism_map[[from_org]]
    if (is.null(org_info)) {
      warning(paste("Unsupported organism:", from_org, ". Cannot perform gene ID conversion."))
      return(genes_clean)
    }
    
    # Load OrgDb
    if (!requireNamespace(org_info$org_db, quietly = TRUE)) {
      message(paste("Installing Bioconductor package:", org_info$org_db))
      if (!requireNamespace("BiocManager", quietly = TRUE)) install.packages("BiocManager")
      BiocManager::install(org_info$org_db, update = FALSE, ask = FALSE)
    }
    library(org_info$org_db, character.only = TRUE)
    db_obj <- get(org_info$org_db)
    
    final_mapped_set <- character(0)
    
    # Special case: Yeast
    if (from_org == "yeast") {
      message("Attempting yeast-specific mapping to GENENAME...")
      yeast_keytypes <- c("SYMBOL", "ORF", "GENENAME", "ENTREZID")
      for (kt in yeast_keytypes) {
        if (kt %in% AnnotationDbi::keytypes(db_obj)) {
          tryCatch({
            temp_mapped <- AnnotationDbi::mapIds(db_obj, keys = genes_clean, column = "GENENAME", keytype = kt, multiVals = "first")
            new_mappings <- temp_mapped[!is.na(temp_mapped) & nchar(temp_mapped) > 0]
            final_mapped_set <- unique(c(final_mapped_set, new_mappings))
            if (length(final_mapped_set) == length(genes_clean)) break
          }, error = function(e) {
            message(paste("Yeast mapping from", kt, "failed:", e$message))
          })
        }
      }
      if (length(final_mapped_set) == 0) {
        warning("Could not convert Yeast gene IDs. Returning original IDs.")
        return(genes_clean)
      } else {
        message(paste("Yeast mapping found", length(final_mapped_set), "genes."))
        return(final_mapped_set)
      }
    }
    
    # Keytype priority
    candidate_from_keytypes <- c("SYMBOL", "ENSEMBL", "ENTREZID", "REFSEQ", "ALIAS", "GENENAME", "ENSEMBLTRANS")
    if (detected_type == "ENSEMBLTRANS") {
      candidate_from_keytypes <- c("ENSEMBLTRANS", "ENSEMBL", "SYMBOL", "ENTREZID", "REFSEQ", "ALIAS", "GENENAME")
    } else if (detected_type == "ENTREZID") {
      candidate_from_keytypes <- c("ENTREZID", "SYMBOL", "ENSEMBL", "REFSEQ", "ALIAS", "GENENAME", "ENSEMBLTRANS")
    } else if (detected_type == "SYMBOL") {
      candidate_from_keytypes <- c("SYMBOL", "ENTREZID", "ENSEMBL", "REFSEQ", "ALIAS", "GENENAME", "ENSEMBLTRANS")
    }
    
    available_candidate_keytypes <- candidate_from_keytypes[candidate_from_keytypes %in% AnnotationDbi::keytypes(db_obj)]
    
    # Try AnnotationDbi
    for (kt in available_candidate_keytypes) {
      message(paste0("Attempting AnnotationDbi mapping from ", kt, " to ", to_type, "..."))
      tryCatch({
        temp_mapped <- AnnotationDbi::mapIds(
          db_obj,
          keys = genes_clean,
          column = to_type,
          keytype = kt,
          multiVals = "first"
        )
        new_mappings <- temp_mapped[!is.na(temp_mapped) & nchar(temp_mapped) > 0]
        final_mapped_set <- unique(c(final_mapped_set, new_mappings))
        message(paste0("  Mapped ", length(new_mappings), " genes from ", kt, ". Total unique mapped: ", length(final_mapped_set)))
        if (length(final_mapped_set) >= length(genes_clean) * 0.9 && (kt == detected_type || detected_type == "mixed")) {
          message("  Sufficient mappings found, stopping AnnotationDbi attempts.")
          break
        }
      }, error = function(e) {
        message(paste("  AnnotationDbi mapping from", kt, "failed:", e$message))
      })
    }
    
    # Try BioMart if needed
    if (length(final_mapped_set) < length(genes_clean) &&
        requireNamespace("biomaRt", quietly = TRUE) &&
        !is.null(org_info$bm_dataset)) {
      message("Attempting BioMart mapping for remaining genes...")
      tryCatch({
        mart <- try_biomart_mirrors(org_info$bm_dataset)
        if (!is.null(mart)) {
          # Determine which filters and attributes are available
          filters_avail <- biomaRt::listFilters(mart)$name
          attrs_avail <- biomaRt::listAttributes(mart)$name
          
          # Create mapping of ID type to filter name
          filter_map <- list(
            ENSEMBLTRANS = "ensembl_transcript_id",
            ENSEMBL = "ensembl_gene_id",
            SYMBOL = "external_gene_name",
            ENTREZID = "entrezgene_id",
            REFSEQ = "refseq_mrna"
          )
          filter_to_use <- filter_map[[detected_type]]
          
          if (filter_to_use %in% filters_avail) {
            query_results <- biomaRt::getBM(
              attributes = intersect(c("ensembl_transcript_id", "ensembl_gene_id", "external_gene_name"), attrs_avail),
              filters = filter_to_use,
              values = genes_clean,
              mart = mart,
              uniqueRows = TRUE
            )
            
            # Use correct column for mapping
            if ("external_gene_name" %in% colnames(query_results) && filter_to_use %in% colnames(query_results)) {
              temp_map <- setNames(query_results$external_gene_name, query_results[[filter_to_use]])
              mapped <- temp_map[genes_clean]
              final_mapped_set <- unique(c(final_mapped_set, mapped[!is.na(mapped)]))
            }
          }
        }
      }, error = function(e) {
        message(paste("BioMart mapping failed:", e$message))
      })
    }
    
    if (length(final_mapped_set) == 0) {
      warning(paste("No mappings found for requested genes from", from_org, ". Returning original IDs."))
      return(genes_clean)
    } else if (length(final_mapped_set) < length(genes_clean)) {
      warning(paste("Only", length(final_mapped_set), "out of", length(genes_clean), "genes could be mapped."))
    }
    
    final_mapped_set <- final_mapped_set[!is.na(final_mapped_set) & nchar(final_mapped_set) > 0]
    message(paste("Final successfully converted genes:", length(final_mapped_set)))
    validate_gene_symbols <- function(genes) {
      # Remove obvious non-symbols
      valid <- genes[!grepl("^ENS|^LOC[0-9]|^[0-9]+$|\\.[0-9]+$", genes)]
      
      # Keep genes that look like proper symbols (start with letter, reasonable length)
      valid <- valid[grepl("^[A-Za-z]", valid) & nchar(valid) >= 2 & nchar(valid) <= 15]
      
      return(valid)
    }
    final_mapped_set <- validate_gene_symbols(final_mapped_set)
    return(final_mapped_set)
  }
  
  debug_pathway_enrichment <- function(deg_data, params) {
    cat("\n=== PATHWAY ENRICHMENT DEBUG ===\n")
    
    # 1. Check DEG data structure
    cat("1. DEG Data Structure:\n")
    cat("   - Total genes:", nrow(deg_data), "\n")
    cat("   - Columns:", paste(colnames(deg_data), collapse = ", "), "\n")
    cat("   - Sample gene IDs:", paste(head(deg_data$gene_id, 5), collapse = ", "), "\n")
    
    # 2. Check parameter values
    cat("\n2. Parameter Values:\n")
    cat("   - P-value threshold:", params$p_val_threshold_main, "\n")
    cat("   - Log2FC min:", params$log2fc_min_main, "\n")
    cat("   - Log2FC max:", params$log2fc_max_main, "\n")
    cat("   - Organism:", params$organism_db, "\n")
    cat("   - Database:", params$enrichr_database, "\n")
    cat("   - Gene set:", params$pathway_gene_set, "\n")
    
    # 3. Check significant genes
    sig_genes <- deg_data[deg_data$adj.P.Val < params$p_val_threshold_main, ]
    cat("\n3. Significant Genes:\n")
    cat("   - Count:", nrow(sig_genes), "\n")
    if (nrow(sig_genes) > 0) {
      cat("   - P-value range:", min(sig_genes$adj.P.Val), "to", max(sig_genes$adj.P.Val), "\n")
      cat("   - Log2FC range:", min(sig_genes$log2FC), "to", max(sig_genes$log2FC), "\n")
    }
    
    # 4. Check fold change filtering
    up_genes <- sig_genes[sig_genes$log2FC > params$log2fc_max_main, ]
    down_genes <- sig_genes[sig_genes$log2FC < params$log2fc_min_main, ]
    both_genes <- sig_genes[abs(sig_genes$log2FC) > max(abs(params$log2fc_min_main), params$log2fc_max_main), ]
    
    cat("\n4. Fold Change Filtering:\n")
    cat("   - Up-regulated genes:", nrow(up_genes), "\n")
    cat("   - Down-regulated genes:", nrow(down_genes), "\n")
    cat("   - Both (meeting FC criteria):", nrow(both_genes), "\n")
    
    # 5. Return selected genes for further debugging
    selected_genes <- switch(params$pathway_gene_set,
                             "up" = up_genes$gene_id,
                             "down" = down_genes$gene_id,
                             "both_fc_filtered" = both_genes$gene_id
    )
    
    cat("\n5. Selected Genes for Enrichment:\n")
    cat("   - Count:", length(selected_genes), "\n")
    cat("   - Sample:", paste(head(selected_genes, 10), collapse = ", "), "\n")
    
    return(selected_genes)
  }
  
  
  suggest_organism_from_data <- function(gene_ids) {
    # Simple heuristic based on gene ID patterns
    if (any(grepl("^ENSG", gene_ids, ignore.case = TRUE))) {
      return("human")
    } else if (any(grepl("^ENSMUSG", gene_ids, ignore.case = TRUE))) {
      return("mouse")
    } else if (any(grepl("^ENSRNOG", gene_ids, ignore.case = TRUE))) {
      return("rat")
    } else if (any(grepl("^FBgn", gene_ids, ignore.case = TRUE))) {
      return("fly")
    }
    return(NULL)
  }
  
  observeEvent(deg_data(), {
    if (!is.null(deg_data()) && nrow(deg_data()) > 0) {
      # Get gene IDs from the first column (assuming it contains gene identifiers)
      gene_ids <- as.character(deg_data()[, 1])
      suggested_organism <- suggest_organism_from_data(gene_ids)
      
      if (!is.null(suggested_organism) && organism_selected() == FALSE) {
        showNotification(
          paste("Based on your gene IDs, we suggest organism:", suggested_organism,
                ". Please confirm or select the correct organism."),
          type = "message",
          duration = 7
        )
        
        # Optional: Auto-select if confidence is high
        # updateSelectInput(session, "organism_deg", selected = suggested_organism)
      }
    }
  })
  
  observe({
    if (!organism_selected()) {
      shinyjs::disable("run_deg_analysis")
      shinyjs::disable("pathway_analysis_button")
      shinyjs::disable("deg_summary_button")
    } else {
      shinyjs::enable("run_deg_analysis")
      shinyjs::enable("pathway_analysis_button")
      shinyjs::enable("deg_summary_button")
    }
  })
  
  output$analysis_results_header <- renderUI({
    if (organism_selected()) {
      div(class = "alert alert-info",
          paste("Analysis results for:", input$organism_deg,
                "- Gene symbols and pathways are organism-specific"))
    }
  })
  
  
  # ENHANCED PATHWAY ENRICHMENT OBSERVER WITH DEBUGGING
  # ENHANCED PATHWAY ENRICHMENT OBSERVER WITH SEPARATE UP/DOWN ANALYSIS
  observeEvent(input$run_enrichment, {
    # Validate organism selection first
    if (!validate_organism_selection()) {
      return() # Stop execution if validation fails
    }
    
    # Set analysis in progress
    analysis_in_progress(TRUE)
    
    isolate({
      withProgress(message = "Running pathway enrichment...", value = 0, {
        tryCatch({
          # Get selected databases
          selected_databases <- input$enrichr_database
          if (is.null(selected_databases) || length(selected_databases) == 0) {
            showNotification("Please select at least one pathway database.", type = "warning", duration = 10)
            analysis_in_progress(FALSE)
            return(NULL)
          }
          
          # Initialize with an empty data frame to prevent NULL issues
          enrichment_results(data.frame())
          
          # Get current analysis parameters
          current_params <- list(
            p_val_threshold_main = input$p_val_threshold_main %||% 0.05,
            log2fc_min_main = input$log2fc_min %||% -1,
            log2fc_max_main = input$log2fc_max %||% 1,
            organism_db = input$organism_db,
            enrichr_database = input$enrichr_database,
            pathway_gene_set = input$pathway_gene_set,
            pathway_pval_cutoff = input$pathway_pval_cutoff %||% 0.05,
            pvalue_type_deg = input$pvalue_type_main %||% "adjusted",
            pvalue_type_pathway = input$pvalue_type %||% "adjusted",
            min_genes_per_pathway = input$min_genes_per_pathway %||% 3
          )
          
          cat("\n=== PATHWAY ENRICHMENT STARTING ===\n")
          incProgress(0.1, detail = "Validating DEG data...")
          current_deg_results <- deg_data()
          
          if (is.null(current_deg_results) || nrow(current_deg_results) == 0) {
            showNotification("No DEG results available. Run DEG analysis first.", type = "error")
            analysis_in_progress(FALSE)
            return(NULL)
          }
          
          incProgress(0.2, detail = "Filtering significant genes...")
          
          # Get p-value column info
          pval_info_deg <- get_pvalue_info(current_params$pvalue_type_deg)
          deg_p_col <- pval_info_deg$column
          
          sig_degs <- current_deg_results %>%
            dplyr::filter(
              !is.na(!!sym(deg_p_col)) & !is.na(log2FC) & !is.na(gene_id) &
                !!sym(deg_p_col) < current_params$p_val_threshold_main
            )
          
          # --- NEW LOGIC: Prepare UP and DOWN gene lists ---
          up_regulated_genes <- sig_degs %>% 
            filter(log2FC > current_params$log2fc_max_main) %>% 
            pull(gene_id)
          
          down_regulated_genes <- sig_degs %>% 
            filter(log2FC < current_params$log2fc_min_main) %>% 
            pull(gene_id)
          
          all_results <- list() # To store results from all runs
          
          # --- Reusable function to run enrichment on a given gene list ---
          # Background = every gene tested in the DE analysis (as symbols)
          de_universe <- tryCatch(convert_gene_ids(genes = unique(current_deg_results$gene_id),
                                                   from_org = current_params$organism_db, to_type = "SYMBOL"),
                                  error = function(e) NULL)
          run_enrichment_on_list <- function(gene_list, regulation_status) {
            if (length(gene_list) < 3) return(NULL) # Need at least 3 genes
            
            # Convert gene IDs
            valid_genes <- convert_gene_ids(genes = gene_list, from_org = current_params$organism_db, to_type = "SYMBOL")
            if (length(valid_genes) == 0) return(NULL)
            
            # Run enrichment for each selected database
            db_results <- list()
            for (db in current_params$enrichr_database) {
              enriched <- tryCatch(tx_enrichr_local(valid_genes, databases = db, background = de_universe), error = function(e) NULL)
              if (!is.null(enriched[[db]]) && nrow(enriched[[db]]) > 0) {
                res <- enriched[[db]]
                res$Database <- create_readable_db_name(db)
                res$Regulation <- regulation_status # ADD THE REGULATION STATUS COLUMN
                db_results[[db]] <- res
              }
            }
            if (length(db_results) > 0) {
              return(do.call(rbind, db_results))
            } else {
              return(NULL)
            }
          }
          
          # --- Run enrichment based on user's selection ---
          if (current_params$pathway_gene_set %in% c("up", "both_fc_filtered")) {
            incProgress(0.4, detail = "Analyzing upregulated pathways...")
            up_results <- run_enrichment_on_list(up_regulated_genes, "Upregulated")
            if (!is.null(up_results)) all_results$up <- up_results
          }
          
          if (current_params$pathway_gene_set %in% c("down", "both_fc_filtered")) {
            incProgress(0.7, detail = "Analyzing downregulated pathways...")
            down_results <- run_enrichment_on_list(down_regulated_genes, "Downregulated")
            if (!is.null(down_results)) all_results$down <- down_results
          }
          
          # --- Combine and finalize results ---
          incProgress(0.9, detail = "Finalizing results...")
          if (length(all_results) > 0) {
            combined_results <- do.call(rbind, all_results)
            rownames(combined_results) <- NULL # Reset rownames to prevent issues
            
            # Filter the final combined results
            pathway_p_col <- if (current_params$pvalue_type_pathway == "adjusted") "Adjusted.P.value" else "P.value"
            gene_counts <- as.numeric(sapply(strsplit(combined_results$Overlap, "/"), `[`, 1))
            
            final_filtered_results <- combined_results[
              !is.na(combined_results[[pathway_p_col]]) &
                combined_results[[pathway_p_col]] < current_params$pathway_pval_cutoff &
                !is.na(gene_counts) &
                gene_counts >= current_params$min_genes_per_pathway,
            ]
            
            enrichment_results(final_filtered_results)
            
            if(nrow(final_filtered_results) > 0){
              showNotification(paste("Found", nrow(final_filtered_results), "significant pathways."), type = "message")
            } else {
              showNotification("No significant pathways found with the current filters.", type = "warning")
            }
            
          } else {
            showNotification("No significant pathways found for the selected gene sets.", type = "warning")
            enrichment_results(data.frame()) # Set to empty frame to clear old results
          }
          
          # Store completed analysis parameters
          # (This logic remains the same)
          if (exists("final_filtered_results") && nrow(final_filtered_results) > 0) {
            completed_params <- list(
              organism_name = switch(current_params$organism_db,
                                     "human" = "Human (Homo sapiens)",
                                     "mouse" = "Mouse (Mus musculus)",
                                     "rat" = "Rat (Rattus norvegicus)",
                                     "fly" = "Fruit Fly (Drosophila)",
                                     "zebrafish" = "Zebrafish (Danio rerio)",
                                     "celegans" = "C. elegans",
                                     "yeast" = "Yeast (S. cerevisiae)",
                                     "arabidopsis" = "Arabidopsis thaliana",
                                     "chicken" = "Chicken (Gallus gallus)",
                                     "pig" = "Pig (Sus scrofa)",
                                     current_params$organism_db), # fallback
              total_genes = nrow(current_deg_results),
              sig_genes = nrow(sig_degs),
              fc_genes = length(up_regulated_genes) + length(down_regulated_genes),
              p_threshold = current_params$p_val_threshold_main,
              fc_min = current_params$log2fc_min_main,
              fc_max = current_params$log2fc_max_main,
              pvalue_label = pval_info_deg$label,
              databases_used = paste(unique(final_filtered_results$Database), collapse = ", "),
              completion_time = format(Sys.time(), "%Y-%m-%d %H:%M:%S"),
              pathway_gene_set = current_params$pathway_gene_set,
              total_pathways_found = nrow(final_filtered_results),
              databases_count = length(unique(final_filtered_results$Database))
            )
            last_analysis_params(completed_params)
          }
          
        }, error = function(e) {
          showNotification(paste("Enrichment analysis failed:", e$message), type = "error")
          print(paste("Full error:", e$message))
        })
      }) # end withProgress
    }) # end isolate
    analysis_in_progress(FALSE)
  })
  
  
  create_readable_db_name <- function(db_id) {
    # Convert database IDs to readable names
    db_name_map <- c(
      # Gene Ontology
      "GO_Biological_Process_2023" = "GO Biological Process",
      "GO_Molecular_Function_2023" = "GO Molecular Function",
      "GO_Cellular_Component_2023" = "GO Cellular Component",
      
      # Pathway Databases - Human
      "KEGG_2021_Human" = "KEGG Human",
      "Reactome_Pathways_2024" = "Reactome",
      "WikiPathways_2024_Human" = "WikiPathways Human",
      "BioCarta_2016" = "BioCarta",
      
      # Gene Sets
      "MSigDB_Hallmark_2020" = "MSigDB Hallmark",
      "BioPlanet_2019" = "BioPlanet",
      
      # Disease/Phenotype
      "OMIM_Disease" = "OMIM Disease",
      "Human_Phenotype_Ontology" = "Human Phenotype Ontology",
      "DisGeNET" = "DisGeNET",
      
      # Mouse
      "KEGG_2021_Mouse" = "KEGG Mouse",
      "WikiPathways_2024_Mouse" = "WikiPathways Mouse",
      "MGI_Mammalian_Phenotype_Level_4_2019" = "MGI Phenotype",
      
      # Other organisms
      "KEGG_2021_Rat" = "KEGG Rat",
      "KEGG_2021_Drosophila" = "KEGG Drosophila",
      "KEGG_2021_Zebrafish" = "KEGG Zebrafish",
      "KEGG_2021_C.elegans" = "KEGG C.elegans",
      "KEGG_2021_Yeast" = "KEGG Yeast",
      "KEGG_2021_Arabidopsis" = "KEGG Arabidopsis",
      "KEGG_2021_Chicken" = "KEGG Chicken",
      "KEGG_2021_Pig" = "KEGG Pig"
    )
    
    # Return mapped name or original ID if not found
    readable_name <- db_name_map[db_id]
    if (is.na(readable_name) || is.null(readable_name)) {
      # Clean up the original ID for display
      readable_name <- gsub("_", " ", db_id)
      readable_name <- gsub("2023|2024|2021|2020|2019|2016", "", readable_name)
      readable_name <- trimws(readable_name)
    }
    
    return(as.character(readable_name))
  }
  
  # STEP 3: CREATE DIAGNOSTIC FUNCTION FOR MULTIPLE DATABASES
  create_multi_database_diagnostic <- function(selected_databases, genes) {
    diagnostic_summary <- data.frame(
      Information = c(
        "Analysis Status",
        "Databases Tested",
        "Genes Submitted",
        "Issue",
        "Recommendation 1",
        "Recommendation 2",
        "Recommendation 3"
      ),
      Details = c(
        HTML("&#9989; Analysis completed successfully"),  # ✅
        paste(length(selected_databases), "databases:", paste(selected_databases, collapse = ", ")),
        paste(length(genes), "valid genes"),
        HTML("&#10060; No pathways passed filtering in any database"),  # ❌
        HTML("&#128295; Try p-value threshold of 0.1"),  # 🔧
        HTML("&#128257; Switch to raw p-values"),  # 🔄
        HTML("&#128202; Reduce minimum genes per pathway to 2")  # 📊
      )
    )
    
    enrichment_results(diagnostic_summary)
    
    showNotification(
      paste0("No significant pathways found in any of the ", length(selected_databases),
             " selected databases. Try relaxing thresholds."),
      type = "warning",
      duration = 12
    )
  }
  
  # STEP 4: ENHANCED TABLE RENDERING WITH DATABASE COLUMN
  output$enrichment_table <- DT::renderDataTable({
    req(enrichment_results())
    
    results_df <- enrichment_results()
    
    # Check if this is diagnostic info
    if ("Information" %in% colnames(results_df)) {
      return(DT::datatable(
        results_df,
        options = list(dom = 't', ordering = FALSE, searching = FALSE, pageLength = -1),
        rownames = FALSE
      ) %>%
        DT::formatStyle('Information', backgroundColor = '#f8f9fa', fontWeight = 'bold'))
    }
    
    # Enhanced table with database information
    if ("Database" %in% colnames(results_df)) {
      # Count results per database
      db_counts <- table(results_df$Database)
      cat("Results per database:", paste(names(db_counts), "=", db_counts, collapse = ", "), "\n")
    }
    
    if (is.null(results_df) || nrow(results_df) == 0) {
      return(DT::datatable(
        data.frame(Message = "No significant pathways to display."),
        options = list(dom = 't'), rownames = FALSE
      ))
    }
    
    # Ensure Regulation column exists, if not, add it as "Unknown"
    if (!"Regulation" %in% colnames(results_df)) {
      results_df$Regulation <- "Unknown"
    }
    
    # Add Gene_Count column by parsing Overlap
    if ("Overlap" %in% colnames(results_df)) {
      results_df$Gene_Count <- as.numeric(sapply(strsplit(as.character(results_df$Overlap), "/"), `[`, 1))
    } else {
      results_df$Gene_Count <- 0
    }
    
    # FIXED: Create colors for databases BEFORE the pipe chain
    unique_dbs <- unique(results_df$Database)
    num_dbs <- length(unique_dbs)
    
    # Create colors based on number of databases
    if (num_dbs == 1) {
      db_colors <- c('#e3f2fd')
    } else if (num_dbs == 2) {
      db_colors <- c('#e3f2fd', '#f3e5f5')
    } else if (num_dbs <= 9 && requireNamespace("RColorBrewer", quietly = TRUE)) {
      # Use RColorBrewer for 3+ databases
      db_colors <- RColorBrewer::brewer.pal(max(3, num_dbs), "Set2")[1:num_dbs]
    } else {
      # Fallback for many databases or no RColorBrewer
      db_colors <- c('#e3f2fd', '#f3e5f5', '#e8f5e8', '#fff3e0', '#ffebee',
                     '#f1f8e9', '#fce4ec', '#e0f2f1', '#fff8e1')[1:num_dbs]
    }
    names(db_colors) <- unique_dbs
    
    # Select and reorder columns for display
    display_cols <- c("Database", "Term", "Regulation", "Gene_Count", "P.value", "Adjusted.P.value", "Combined.Score", "Genes")
    
    # Only select columns that actually exist
    display_cols <- display_cols[display_cols %in% colnames(results_df)]
    
    display_df <- results_df[, display_cols, drop = FALSE]
    
    dt_table <- DT::datatable(
      display_df,
      options = list(
        pageLength = 25,
        scrollX = TRUE,
        scrollY = "600px",  # *** NEW: Fixed height for scrolling ***
        scrollCollapse = FALSE,  # *** NEW: Keep height fixed ***
        fixedHeader = TRUE,  # *** NEW: Makes header sticky ***
        autoWidth = TRUE,
        columnDefs = list(
          list(width = "150px", targets = 0),  # Database column
          list(width = "300px", targets = 1),  # Term column
          list(width = "120px", targets = 2),  # Regulation column
          list(width = "80px", targets = 3),   # Gene_Count column
          list(width = "100px", targets = 4),  # P.value column
          list(width = "120px", targets = 5),  # Adjusted.P.value column
          list(width = "120px", targets = 6),  # Combined.Score column
          list(width = "200px", targets = 7)   # Genes column
        )
      ),
      rownames = FALSE,
      escape = FALSE,
      filter = 'top',
      extensions = 'FixedHeader'  # *** NEW: Enable FixedHeader extension ***
    ) %>%
      
      # Format numeric columns
      DT::formatSignif(columns = c("P.value", "Adjusted.P.value", "Combined.Score"), digits = 3) %>%
      
      # Color-code Regulation column
      DT::formatStyle(
        'Regulation',
        backgroundColor = DT::styleEqual(
          c("Upregulated", "Downregulated", "Unknown"),
          c('#ffebee', '#e3f2fd', '#f5f5f5') # Light red for up, light blue for down, grey for unknown
        ),
        color = DT::styleEqual(
          c("Upregulated", "Downregulated", "Unknown"),
          c('#c62828', '#1565c0', '#616161') # Darker text for contrast
        ),
        fontWeight = 'bold',
        textAlign = 'center'
      ) %>%
      
      # Color-code P.value column
      DT::formatStyle('P.value',
                      backgroundColor = DT::styleInterval(c(0.01, 0.05), c('#c8e6c9', '#fff3e0', '#ffcdd2')),
                      color = DT::styleInterval(c(0.01, 0.05), c('#2e7d32', '#e65100', '#c62828')),
                      fontWeight = 'bold') %>%
      
      # Color-code Adjusted.P.value column
      DT::formatStyle('Adjusted.P.value',
                      backgroundColor = DT::styleInterval(c(0.01, 0.05, 0.1), c('#a5d6a7', '#c8e6c9', '#fff3e0', '#ffcdd2')),
                      color = DT::styleInterval(c(0.01, 0.05, 0.1), c('#1b5e20', '#2e7d32', '#e65100', '#c62828')),
                      fontWeight = 'bold') %>%
      
      # Database column formatting
      DT::formatStyle('Database',
                      backgroundColor = DT::styleEqual(unique_dbs, db_colors),
                      fontWeight = 'bold',
                      fontSize = '90%') %>%
      
      # Other formatting
      DT::formatStyle('Combined.Score',
                      backgroundColor = DT::styleInterval(c(10, 50), c('#ffebee', '#e3f2fd', '#e8f5e8'))) %>%
      DT::formatStyle('Gene_Count', fontFamily = 'monospace', fontSize = '90%', textAlign = 'center') %>%
      DT::formatStyle('Term', fontSize = '95%', lineHeight = '1.2')
    
    return(dt_table)
  })
  
  # STEP 5: FIXED DATABASE SUMMARY PANEL WITH HTML ENTITIES
  output$database_summary <- renderUI({
    req(enrichment_results())
    
    results_df <- enrichment_results()
    
    if ("Database" %in% colnames(results_df)) {
      db_stats <- results_df %>%
        dplyr::group_by(Database) %>%
        dplyr::summarise(
          count = n(),
          sig_count = sum(Adjusted.P.value < 0.05, na.rm = TRUE),
          best_pval = min(Adjusted.P.value, na.rm = TRUE),
          .groups = 'drop'
        ) %>%
        dplyr::arrange(desc(count))
      
      # Create database stat cards
      db_cards <- lapply(seq_len(nrow(db_stats)), function(i) {
        db <- db_stats$Database[i]
        count <- db_stats$count[i]
        sig_count <- db_stats$sig_count[i]
        best_pval <- db_stats$best_pval[i]
        
        # Database-specific colors
        db_color <- switch(tolower(gsub("\\s+", "", db)),
                           "kegg" = "#4caf50",
                           "reactome" = "#e91e63",
                           "gobiologicalprocess" = "#2196f3",
                           "gomolecularfunction" = "#9c27b0",
                           "gocellularcomponent" = "#00bcd4",
                           "#607d8b"
        )
        
        div(
          class = "db-stat-item",
          style = paste0("border-left: 4px solid ", db_color, ";"),
          div(class = "db-stat-value primary", count),
          div(class = "db-stat-label", db),
          div(
            style = "margin-top: 8px; font-size: 11px;",
            tags$span(
              style = paste0("color: ", ifelse(sig_count > 0, "#28a745", "#999"), "; font-weight: 500;"),
              sig_count, " significant"
            )
          )
        )
      })
      
      # Overall summary
      total_pathways <- nrow(results_df)
      total_sig <- sum(results_df$Adjusted.P.value < 0.05, na.rm = TRUE)
      
      div(
        style = "margin: 15px 0; padding: 20px; background: linear-gradient(135deg, #f8fafc 0%, #f1f5f9 100%); border-radius: 12px;",
        
        # Header with totals
        div(
          style = "display: flex; justify-content: space-between; align-items: center; margin-bottom: 16px; padding-bottom: 12px; border-bottom: 1px solid #e2e8f0;",
          h5(
            style = "margin: 0; color: #2c3e50; font-weight: 600;",
            icon("chart-bar", style = "margin-right: 8px; color: #667eea;"),
            "Results Summary by Database"
          ),
          div(
            style = "display: flex; gap: 12px;",
            tags$span(
              style = "background: #e8f4fd; padding: 6px 14px; border-radius: 20px; font-size: 13px; font-weight: 500; color: #1976d2;",
              icon("layer-group"), " ", total_pathways, " total"
            ),
            tags$span(
              style = paste0("background: ", ifelse(total_sig > 0, "#e8f5e9", "#fff3e0"), 
                             "; padding: 6px 14px; border-radius: 20px; font-size: 13px; font-weight: 500; color: ",
                             ifelse(total_sig > 0, "#2e7d32", "#f57c00"), ";"),
              icon("check-circle"), " ", total_sig, " significant"
            )
          )
        ),
        
        # Database cards
        div(
          class = "db-summary-row",
          style = "background: transparent; padding: 0; margin: 0; box-shadow: none; border: none;",
          db_cards
        )
      )
    }
  })
  
  # Fix 1: Add the missing gene_count_info output to show the tabs
  output$gene_count_info <- renderText({
    # This will reactively update when enrichment_results() changes
    if (!is.null(enrichment_results()) && nrow(enrichment_results()) > 0) {
      result_text <- paste("Found", nrow(enrichment_results()), "significant pathways")
      cat("DEBUG: gene_count_info showing:", result_text, "\n")
      return(result_text)
    } else {
      cat("DEBUG: gene_count_info returning NULL (no results)\n")
      return(NULL)
    }
  })
  
  # Fix 2: Fixed Analysis Overview Display with proper HTML icons
  # Fix 1: Improved text contrast for better readability
  output$pathway_analysis_info <- renderUI({
    # Only show overview if we have completed analysis parameters
    if (!is.null(last_analysis_params())) {
      # Use COMPLETED analysis parameters, not current UI settings
      params <- last_analysis_params()
      
      # Create a comprehensive overview with better contrast
      div(class = "alert alert-success",
          style = "margin-bottom: 15px; padding: 15px; border-left: 4px solid #28a745; background-color: #d4edda; color: #155724;",
          div(
            h4(HTML("&#10004; Analysis Complete!"), style = "color: #155724; margin-top: 0; font-weight: bold;"),
            HTML(paste0(
              "<div style='display: grid; grid-template-columns: 1fr 1fr; gap: 15px; margin-top: 10px; color: #155724;'>",
              
              # Left column - Basic Info with HTML entities
              "<div>",
              "<strong style='color: #0d4f1c;'>&#8226; Dataset Information:</strong><br>",
              "<span style='color: #155724;'>&#8594; Organism: <strong style='color: #0d4f1c;'>", params$organism_name, "</strong></span><br>",
              "<span style='color: #155724;'>&#8594; Total genes in dataset: <strong style='color: #0d4f1c;'>", format(params$total_genes, big.mark = ","), "</strong></span><br>",
              "<span style='color: #155724;'>&#8594; P-value type: <strong style='color: #0d4f1c;'>", params$pvalue_label, "</strong></span><br>",
              "<span style='color: #155724;'>&#8594; P-value threshold: <strong style='color: #0d4f1c;'>&lt; ", params$p_threshold, "</strong></span><br>",
              "</div>",
              
              # Right column - Results Info with HTML entities
              "<div>",
              "<strong style='color: #0d4f1c;'>&#8226; Analysis Results:</strong><br>",
              "<span style='color: #155724;'>&#8594; Significant DEGs: <strong style='color: #0d4f1c;'>", format(params$sig_genes, big.mark = ","), "</strong></span><br>",
              "<span style='color: #155724;'>&#8594; Genes for enrichment: <strong style='color: #0d4f1c;'>", format(params$fc_genes, big.mark = ","), "</strong></span><br>",
              "<span style='color: #155724;'>&#8594; Pathways found: <strong style='color: #0d4f1c;'>", params$total_pathways_found, "</strong></span><br>",
              "<span style='color: #155724;'>&#8594; Databases: <strong style='color: #0d4f1c;'>", params$databases_count, "</strong> (", params$databases_used, ")</span><br>",
              "</div>",
              
              "</div>",
              
              # Additional details row with HTML entities
              "<div style='margin-top: 15px; padding-top: 10px; border-top: 1px solid #c3e6cb; color: #155724;'>",
              "<strong style='color: #0d4f1c;'>&#8226; Analysis Settings:</strong><br>",
              "<span style='color: #155724;'>&#8594; Log2FC thresholds: <strong style='color: #0d4f1c;'>&lt; ", params$fc_min, " or &gt; ", params$fc_max, "</strong></span><br>",
              "<span style='color: #155724;'>&#8594; Gene set analyzed: <strong style='color: #0d4f1c;'>", params$pathway_gene_set, "</strong></span><br>",
              "<span style='color: #155724;'>&#8594; Completed: <strong style='color: #0d4f1c;'>", params$completion_time, "</strong></span>",
              "</div>"
            ))
          )
      )
    } else {
      # Show setup info when no analysis has been completed yet
      div(class = "alert alert-info",
          style = "margin-bottom: 15px; padding: 15px; border-left: 4px solid #17a2b8; background-color: #d1ecf1; color: #0c5460;",
          div(
            h4(HTML("&#8594; Ready to Analyze"), style = "color: #0c5460; margin-top: 0; font-weight: bold;"),
            p("Configure your settings above and click 'Run Pathway Enrichment' to begin analysis.",
              style = "color: #0c5460; margin-bottom: 0;")
          )
      )
    }
  })
  
  # Reactive to store network data
  unified_network_data <- reactiveVal(NULL)
  
  # Reactive values for pathway selection
  network_pathway_selection_mode <- reactiveVal("default")  # "default" or "custom"
  network_selected_pathways <- reactiveVal(NULL)
  network_pathway_table <- reactiveVal(NULL)
  
  # Show pathway selection status
  output$pathway_selection_status <- renderUI({
    if (network_pathway_selection_mode() == "custom" && !is.null(network_selected_pathways())) {
      div(
        style = "background: #e8f5e9; padding: 8px 12px; border-radius: 6px; border: 1px solid #a5d6a7;",
        icon("check-circle", style = "color: #2e7d32;"),
        tags$span(style = "color: #2e7d32; font-weight: 500;",
                  paste(length(network_selected_pathways()), "pathways selected"))
      )
    } else {
      div(
        style = "background: #e3f2fd; padding: 8px 12px; border-radius: 6px; border: 1px solid #90caf9;",
        icon("info-circle", style = "color: #1565c0;"),
        tags$span(style = "color: #1565c0;", "Using top pathways")
      )
    }
  })
  
  # Reset pathway selection
  observeEvent(input$reset_pathway_selection, {
    network_pathway_selection_mode("default")
    network_selected_pathways(NULL)
    showNotification("Reset to default pathway selection", type = "message")
  })
  
  # Open pathway selector modal
  observeEvent(input$open_pathway_selector, {
    # Get results based on current mode
    results_df <- NULL
    
    if (!is.null(enrichment_rv$results) && length(enrichment_rv$results) > 0) {
      # Combine all enrichment results
      combined <- lapply(names(enrichment_rv$results), function(db_name) {
        df <- enrichment_rv$results[[db_name]]
        if (!is.data.frame(df)) df <- tryCatch(as.data.frame(df), error = function(e) NULL)
        if (is.null(df) || nrow(df) == 0) return(NULL)
        df$Database <- db_name
        return(df)
      })
      combined <- combined[!sapply(combined, is.null)]
      if (length(combined) > 0) {
        results_df <- dplyr::bind_rows(combined)
      }
    }
    
    if (is.null(results_df) || nrow(results_df) == 0) {
      showNotification("No enrichment results available. Please run analysis first.", type = "warning")
      return()
    }
    
    # Filter by p-value
    results_df <- results_df[results_df$p.adjust < input$network_pval_cutoff, ]
    
    if (nrow(results_df) == 0) {
      showNotification("No pathways pass the current p-value cutoff", type = "warning")
      return()
    }
    
    # Create table for selection
    pathway_table <- data.frame(
      Pathway = results_df$Description,
      Database = results_df$Database,
      P.adjust = signif(results_df$p.adjust, 3),
      Gene.Count = if("Count" %in% names(results_df)) results_df$Count else results_df$setSize,
      stringsAsFactors = FALSE
    )
    
    # Add NES if available (GSEA)
    if ("NES" %in% names(results_df)) {
      pathway_table$NES <- round(results_df$NES, 3)
      pathway_table <- pathway_table[, c("Pathway", "Database", "NES", "P.adjust", "Gene.Count")]
    }
    
    network_pathway_table(pathway_table)
    
    showModal(modalDialog(
      title = tagList(icon("list-check"), " Select Pathways for Network"),
      size = "l",
      easyClose = TRUE,
      
      # Add custom CSS for better table containment
      tags$head(tags$style(HTML("
        .pathway-selector-modal .dataTables_wrapper {
          width: 100% !important;
          overflow-x: auto !important;
        }
        .pathway-selector-modal table.dataTable {
          width: 100% !important;
          table-layout: fixed !important;
        }
        .pathway-selector-modal table.dataTable td:first-child {
          max-width: 400px !important;
          overflow: hidden !important;
          text-overflow: ellipsis !important;
          white-space: nowrap !important;
        }
        .pathway-selector-modal .dataTables_scrollBody {
          max-height: 400px !important;
          overflow-y: auto !important;
        }
        .pathway-selector-modal .modal-footer {
          position: sticky;
          bottom: 0;
          background: white;
          border-top: 1px solid #dee2e6;
          padding: 15px;
          z-index: 100;
        }
      "))),
      
      div(
        class = "pathway-selector-modal",
        style = "padding: 15px; max-height: 70vh; overflow: hidden;",
        
        p("Select specific pathways to include in the network visualization. Use Ctrl/Cmd+click for multiple selections."),
        
        fluidRow(
          column(4,
                 actionButton("select_all_network_pathways", "Select All", 
                              class = "btn-info btn-sm", icon = icon("check-square"))
          ),
          column(4,
                 actionButton("clear_all_network_pathways", "Clear All",
                              class = "btn-warning btn-sm", icon = icon("square"))
          ),
          column(4,
                 div(id = "network_pathway_count_display", 
                     style = "padding-top: 5px; font-weight: 500;")
          )
        ),
        
        br(),
        
        div(
          style = "overflow-x: auto; max-width: 100%;",
          DT::dataTableOutput("network_pathway_select_table")
        )
      ),
      
      footer = tagList(
        modalButton("Cancel"),
        actionButton("confirm_pathway_selection", "Generate Network with Selected",
                     class = "btn-primary", icon = icon("project-diagram"))
      )
    ))
  })
  
  # Render pathway selection table
  output$network_pathway_select_table <- DT::renderDataTable({
    req(network_pathway_table())
    
    DT::datatable(
      network_pathway_table(),
      selection = list(mode = "multiple", selected = NULL, target = "row"),
      options = list(
        pageLength = 15,
        scrollY = "350px",
        scrollX = TRUE,
        scrollCollapse = TRUE,
        paging = TRUE,
        dom = 'frtip',
        order = list(list(if("NES" %in% names(network_pathway_table())) 2 else 3, 'asc')),
        autoWidth = FALSE,
        columnDefs = list(
          list(className = 'dt-center', targets = "_all"),
          list(width = '350px', targets = 0),  # Pathway column
          list(width = '80px', targets = 1),   # Database column
          list(width = '70px', targets = 2),   # NES or P.adjust column
          list(width = '80px', targets = 3),   # P.adjust or Gene.Count
          list(width = '80px', targets = 4)    # Gene.Count (if exists)
        )
      ),
      rownames = FALSE,
      filter = "top",
      class = "display compact stripe hover nowrap"
    ) %>%
      DT::formatStyle('Pathway',
                      `white-space` = 'nowrap',
                      `overflow` = 'hidden',
                      `text-overflow` = 'ellipsis',
                      `max-width` = '350px') %>%
      DT::formatStyle('P.adjust',
                      backgroundColor = DT::styleInterval(c(0.01, 0.05),
                                                          c('#c8e6c9', '#fff3e0', '#ffcdd2')))
  }, server = FALSE)  # Important: server = FALSE for proper row selection
  
  # Select all pathways
  observeEvent(input$select_all_network_pathways, {
    req(network_pathway_table())
    DT::dataTableProxy("network_pathway_select_table") %>%
      DT::selectRows(seq_len(nrow(network_pathway_table())))
  })
  
  # Clear all pathways
  observeEvent(input$clear_all_network_pathways, {
    DT::dataTableProxy("network_pathway_select_table") %>%
      DT::selectRows(NULL)
  })
  
  # Confirm pathway selection and generate network
  observeEvent(input$confirm_pathway_selection, {
    selected_rows <- input$network_pathway_select_table_rows_selected
    
    if (length(selected_rows) == 0) {
      showNotification("Please select at least one pathway", type = "warning")
      return()
    }
    
    selected_pathways <- network_pathway_table()[selected_rows, "Pathway"]
    network_selected_pathways(selected_pathways)
    network_pathway_selection_mode("custom")
    
    removeModal()
    
    showNotification(
      paste("Generating network with", length(selected_pathways), "selected pathways..."),
      type = "message", duration = 3
    )
    
    # Trigger network generation
    shinyjs::click("generate_network_btn")
  })
  
  # Generate network when button clicked
  observeEvent(input$generate_network_btn, {
    # Get results based on current mode
    results_df <- NULL
    gene_column <- "geneID"  # Default for ORA
    
    if (!is.null(enrichment_rv$results) && length(enrichment_rv$results) > 0) {
      # Combine all enrichment results
      combined <- lapply(names(enrichment_rv$results), function(db_name) {
        df <- enrichment_rv$results[[db_name]]
        if (!is.data.frame(df)) df <- tryCatch(as.data.frame(df), error = function(e) NULL)
        if (is.null(df) || nrow(df) == 0) return(NULL)
        df$Database <- db_name
        return(df)
      })
      combined <- combined[!sapply(combined, is.null)]
      if (length(combined) > 0) {
        results_df <- dplyr::bind_rows(combined)
      }
      
      # Determine gene column
      if ("core_enrichment" %in% names(results_df)) {
        gene_column <- "core_enrichment"
      }
    }
    
    if (is.null(results_df) || nrow(results_df) == 0) {
      showNotification("No enrichment results available. Please run analysis first.", type = "warning")
      return()
    }
    
    withProgress(message = 'Creating gene-pathway network...', value = 0, {
      
      incProgress(0.1, detail = "Filtering pathways...")
      
      # Filter by p-value with column name fallback
      pval_col <- if ("p.adjust" %in% names(results_df)) {
        "p.adjust"
      } else if ("padj" %in% names(results_df)) {
        "padj"
      } else if ("adj.P.Val" %in% names(results_df)) {
        "adj.P.Val"
      } else if ("FDR" %in% names(results_df)) {
        "FDR"
      } else {
        "p.adjust"  # Default fallback
      }
      
      filtered <- tryCatch({
        results_df %>%
          dplyr::filter(!!sym(pval_col) <= input$network_pval_cutoff)
      }, error = function(e) {
        showNotification(paste("Filter error:", e$message), type = "warning")
        results_df
      })
      
      # Filter by database group if selected
      if (input$network_pathway_group != "all") {
        filtered <- filtered %>%
          dplyr::filter(Database == input$network_pathway_group)
      }
      
      if (nrow(filtered) == 0) {
        showNotification("No pathways pass the current filters", type = "warning")
        return()
      }
      
      # Handle custom pathway selection
      if (network_pathway_selection_mode() == "custom" && !is.null(network_selected_pathways())) {
        filtered <- filtered %>%
          dplyr::filter(Description %in% network_selected_pathways())
      } else {
        # Sort and take top N with proper column name handling
        sort_col <- input$network_sort_by
        
        filtered <- tryCatch({
          if (sort_col == "NES") {
            if ("NES" %in% names(filtered)) {
              filtered %>% dplyr::arrange(desc(abs(NES)))
            } else {
              # NES not available (ORA mode), fallback to p.adjust
              filtered %>% dplyr::arrange(!!sym(pval_col))
            }
          } else if (sort_col == "Count") {
            if ("Count" %in% names(filtered)) {
              filtered %>% dplyr::arrange(desc(Count))
            } else if ("setSize" %in% names(filtered)) {
              filtered %>% dplyr::arrange(desc(setSize))
            } else if ("size" %in% names(filtered)) {
              filtered %>% dplyr::arrange(desc(size))
            } else {
              filtered %>% dplyr::arrange(!!sym(pval_col))
            }
          } else if (sort_col == "pvalue") {
            if ("pvalue" %in% names(filtered)) {
              filtered %>% dplyr::arrange(pvalue)
            } else if ("pval" %in% names(filtered)) {
              filtered %>% dplyr::arrange(pval)
            } else if ("P.Value" %in% names(filtered)) {
              filtered %>% dplyr::arrange(P.Value)
            } else {
              filtered %>% dplyr::arrange(!!sym(pval_col))
            }
          } else if (sort_col == "p.adjust") {
            filtered %>% dplyr::arrange(!!sym(pval_col))
          } else {
            # Try using the column directly if it exists
            if (sort_col %in% names(filtered)) {
              filtered %>% dplyr::arrange(!!sym(sort_col))
            } else {
              filtered %>% dplyr::arrange(!!sym(pval_col))
            }
          }
        }, error = function(e) {
          showNotification(paste("Sort error, using default:", e$message), type = "warning")
          filtered
        })
        
        filtered <- head(filtered, input$network_top_pathways)
      }
      
      incProgress(0.3, detail = "Building network...")
      
      # Store filtered data with gene column info
      attr(filtered, "gene_column") <- gene_column
      unified_network_data(filtered)
      
      incProgress(1, detail = "Done!")
    })
  })
  
  # Render the unified network
  output$unified_gene_pathway_network <- visNetwork::renderVisNetwork({
    
    # Check if we have data
    if (is.null(unified_network_data())) {
      return(visNetwork::visNetwork(
        nodes = data.frame(id = 1, label = "Click 'Generate Network' to create visualization", 
                           shape = "text", font.size = 20),
        edges = data.frame(from = integer(), to = integer())
      ))
    }
    
    results_df <- unified_network_data()
    gene_column <- attr(results_df, "gene_column")
    if (is.null(gene_column)) gene_column <- "geneID"
    
    if (nrow(results_df) == 0) {
      return(visNetwork::visNetwork(
        nodes = data.frame(id = 1, label = "No pathways to display", shape = "text"),
        edges = data.frame(from = integer(), to = integer())
      ))
    }
    
    tryCatch({
      # Get organism database for gene ID conversion
      orgdb <- tryCatch(get_orgdb(input$enrichment_organism), error = function(e) NULL)
      
      # Extract genes from the appropriate column
      gene_lists <- strsplit(as.character(results_df[[gene_column]]), "/")
      all_genes <- unique(unlist(gene_lists))
      all_genes <- all_genes[!is.na(all_genes) & all_genes != ""]
      
      # Convert to symbols if needed
      gene_symbols <- all_genes
      if (!is.null(orgdb)) {
        # Check if genes look like Entrez IDs (numeric)
        if (all(grepl("^[0-9]+$", head(all_genes, 5)))) {
          mapped <- tryCatch({
            AnnotationDbi::mapIds(orgdb, keys = all_genes, column = "SYMBOL", 
                                  keytype = "ENTREZID", multiVals = "first")
          }, error = function(e) setNames(all_genes, all_genes))
          
          gene_symbols <- sapply(all_genes, function(g) {
            if (g %in% names(mapped) && !is.na(mapped[g])) mapped[g] else g
          })
        }
      }
      
      # Database colors
      db_colors <- list(
        "GO_BP" = list(background = "#667eea", border = "#5a6fd6"),
        "GO_MF" = list(background = "#9c27b0", border = "#7b1fa2"),
        "GO_CC" = list(background = "#00bcd4", border = "#0097a7"),
        "KEGG" = list(background = "#4caf50", border = "#388e3c"),
        "REACTOME" = list(background = "#f44336", border = "#d32f2f"),
        "WP" = list(background = "#ff9800", border = "#f57c00"),
        "HALLMARK" = list(background = "#795548", border = "#5d4037")
      )
      
      # Truncate pathway labels (max 35 chars)
      truncate_label <- function(x, max_chars = 35) {
        if (nchar(x) > max_chars) {
          paste0(substr(x, 1, max_chars - 3), "...")
        } else {
          x
        }
      }
      
      # Get gene count column
      count_col <- if ("Count" %in% names(results_df)) "Count" else "setSize"
      
      # Create pathway nodes
      pathway_nodes <- data.frame(
        id = paste0("pathway_", seq_len(nrow(results_df))),
        label = sapply(results_df$Description, truncate_label),
        group = results_df$Database,
        title = paste0(
          "<b>", results_df$Description, "</b><br>",
          "<b>Database:</b> ", results_df$Database, "<br>",
          if ("NES" %in% names(results_df)) paste0("<b>NES:</b> ", round(results_df$NES, 3), "<br>") else "",
          "<b>Adj. P-value:</b> ", signif(results_df$p.adjust, 3), "<br>",
          "<b>Gene Count:</b> ", results_df[[count_col]]
        ),
        value = pmax(20, pmin(60, results_df[[count_col]] * 2)),
        shape = "box",
        stringsAsFactors = FALSE
      )
      
      # Create gene nodes
      gene_nodes <- data.frame(
        id = paste0("gene_", seq_along(all_genes)),
        label = as.character(gene_symbols),
        group = "gene",
        title = paste0("<b>Gene:</b> ", gene_symbols),
        value = 12,
        shape = "dot",
        stringsAsFactors = FALSE
      )
      
      nodes <- rbind(pathway_nodes, gene_nodes)
      
      # Create edges - STRAIGHT lines, no smooth curves
      edges_list <- lapply(seq_len(nrow(results_df)), function(i) {
        genes <- unlist(gene_lists[[i]])
        genes <- genes[!is.na(genes) & genes != ""]
        
        if (length(genes) > 0) {
          gene_indices <- match(genes, all_genes)
          gene_indices <- gene_indices[!is.na(gene_indices)]
          
          if (length(gene_indices) > 0) {
            data.frame(
              from = rep(paste0("pathway_", i), length(gene_indices)),
              to = paste0("gene_", gene_indices),
              color = "#cccccc",
              width = 1.5,
              stringsAsFactors = FALSE
            )
          } else NULL
        } else NULL
      })
      
      edges <- do.call(rbind, edges_list[!sapply(edges_list, is.null)])
      
      if (is.null(edges) || nrow(edges) == 0) {
        return(visNetwork::visNetwork(
          nodes = data.frame(id = 1, label = "No gene-pathway connections found", shape = "text"),
          edges = data.frame(from = integer(), to = integer())
        ))
      }
      
      # Create network with STRAIGHT edges and physics that disables after stabilization
      visNetwork::visNetwork(nodes, edges, width = "100%", height = "700px") %>%
        visNetwork::visGroups(groupname = "GO_BP", color = db_colors$GO_BP, shape = "box",
                              font = list(size = 15, color = "white")) %>%
        visNetwork::visGroups(groupname = "GO_MF", color = db_colors$GO_MF, shape = "box",
                              font = list(size = 15, color = "white")) %>%
        visNetwork::visGroups(groupname = "GO_CC", color = db_colors$GO_CC, shape = "box",
                              font = list(size = 15, color = "white")) %>%
        visNetwork::visGroups(groupname = "KEGG", color = db_colors$KEGG, shape = "box",
                              font = list(size = 15, color = "white")) %>%
        visNetwork::visGroups(groupname = "REACTOME", color = db_colors$REACTOME, shape = "box",
                              font = list(size = 15, color = "white")) %>%
        visNetwork::visGroups(groupname = "WP", color = db_colors$WP, shape = "box",
                              font = list(size = 15, color = "white")) %>%
        visNetwork::visGroups(groupname = "HALLMARK", color = db_colors$HALLMARK, shape = "box",
                              font = list(size = 15, color = "white")) %>%
        visNetwork::visGroups(groupname = "gene",
                              color = list(background = "#FFA726", border = "#F57C00"),
                              shape = "dot",
                              font = list(size = 14)) %>%
        # STRAIGHT edges - no smooth curves
        visNetwork::visEdges(
          smooth = FALSE,
          color = list(color = "#cccccc", highlight = "#ff5722")
        ) %>%
        # Physics that stabilizes then turns off for free dragging
        visNetwork::visPhysics(
          enabled = TRUE,
          solver = "forceAtlas2Based",
          forceAtlas2Based = list(
            gravitationalConstant = -80,
            centralGravity = 0.005,
            springLength = 150,
            springConstant = 0.05,
            damping = 0.5,
            avoidOverlap = 0.8
          ),
          stabilization = list(
            enabled = TRUE,
            iterations = 300,
            updateInterval = 25,
            fit = TRUE
          )
        ) %>%
        visNetwork::visInteraction(
          dragNodes = TRUE,
          dragView = TRUE,
          zoomView = TRUE,
          navigationButtons = TRUE,
          tooltipDelay = 100,
          hover = TRUE,
          keyboard = TRUE
        ) %>%
        visNetwork::visOptions(
          highlightNearest = list(enabled = TRUE, degree = 1, hover = TRUE),
          selectedBy = list(variable = "group", multiple = TRUE)
        ) %>%
        visNetwork::visLegend(useGroups = TRUE, position = "right", width = 0.12) %>%
        # DISABLE physics after stabilization so nodes can be freely dragged
        visNetwork::visEvents(
          stabilizationIterationsDone = "function() { 
            this.setOptions({ physics: { enabled: false } }); 
            console.log('Network stabilized - physics disabled for free dragging');
          }"
        )
      
    }, error = function(e) {
      print(paste("Network error:", e$message))
      visNetwork::visNetwork(
        nodes = data.frame(id = 1, label = paste("Error:", e$message), shape = "text"),
        edges = data.frame(from = integer(), to = integer())
      )
    })
  })
  
  # Download handler for network HTML
  output$download_network_html_ea <- downloadHandler(
    filename = function() {
      paste0("gene_pathway_network_", format(Sys.time(), "%Y%m%d_%H%M"), ".html")
    },
    content = function(file) {
      req(unified_network_data())
      
      # Ensure visNetwork is loaded
      if (!requireNamespace("visNetwork", quietly = TRUE)) {
        showNotification("visNetwork package required for HTML export", type = "error")
        return(NULL)
      }
      
      # Recreate the network for export
      results_df <- unified_network_data()
      gene_column <- attr(results_df, "gene_column")
      if (is.null(gene_column)) gene_column <- "geneID"
      
      # Handle potential issues with gene column
      if (!gene_column %in% names(results_df)) {
        gene_column <- grep("gene|Gene|geneID", names(results_df), value = TRUE)[1]
        if (is.null(gene_column)) gene_column <- names(results_df)[1]
      }
      
      gene_lists <- strsplit(as.character(results_df[[gene_column]]), "/")
      all_genes <- unique(unlist(gene_lists))
      all_genes <- all_genes[!is.na(all_genes) & all_genes != ""]
      
      # Limit genes for performance
      if (length(all_genes) > 500) {
        showNotification(paste("Large network - limiting to top pathways"), type = "warning")
        all_genes <- all_genes[1:500]
      }
      
      count_col <- if ("Count" %in% names(results_df)) "Count" else "setSize"
      
      # Build nodes
      pathway_colors <- c("GO:BP" = "#4CAF50", "GO:MF" = "#2196F3", "GO:CC" = "#FF9800",
                          "KEGG" = "#9C27B0", "Reactome" = "#E91E63", "WikiPathways" = "#00BCD4",
                          "MSigDB" = "#795548", "Custom" = "#607D8B")
      
      nodes <- data.frame(
        id = c(paste0("pathway_", seq_len(nrow(results_df))),
               paste0("gene_", seq_along(all_genes))),
        label = c(sapply(results_df$Description, function(x) {
          if(nchar(x) > 40) paste0(substr(x, 1, 37), "...") else x
        }), all_genes),
        group = c(results_df$Database, rep("Gene", length(all_genes))),
        title = c(paste0("<b>", results_df$Description, "</b><br>",
                         "Database: ", results_df$Database, "<br>",
                         "p.adjust: ", signif(results_df$p.adjust, 3)),
                  paste0("<b>", all_genes, "</b>")),
        shape = c(rep("dot", nrow(results_df)), rep("diamond", length(all_genes))),
        size = c(rep(25, nrow(results_df)), rep(10, length(all_genes))),
        stringsAsFactors = FALSE
      )
      
      # Build edges
      edges_list <- lapply(seq_len(nrow(results_df)), function(i) {
        genes <- unlist(gene_lists[[i]])
        genes <- genes[!is.na(genes) & genes != "" & genes %in% all_genes]
        if (length(genes) > 0) {
          gene_indices <- match(genes, all_genes)
          gene_indices <- gene_indices[!is.na(gene_indices)]
          if (length(gene_indices) > 0) {
            data.frame(from = rep(paste0("pathway_", i), length(gene_indices)),
                       to = paste0("gene_", gene_indices), 
                       color = "#cccccc",
                       stringsAsFactors = FALSE)
          } else NULL
        } else NULL
      })
      edges <- do.call(rbind, edges_list[!sapply(edges_list, is.null)])
      
      if (is.null(edges) || nrow(edges) == 0) {
        showNotification("No network connections found", type = "warning")
        return(NULL)
      }
      
      # Create network with better styling
      network <- visNetwork::visNetwork(nodes, edges, 
                                        main = "Gene-Pathway Network",
                                        submain = paste("Generated:", Sys.time())) %>%
        visNetwork::visEdges(smooth = list(enabled = TRUE, type = "dynamic"),
                             color = list(opacity = 0.6)) %>%
        visNetwork::visNodes(font = list(size = 14)) %>%
        visNetwork::visPhysics(enabled = TRUE,
                               solver = "forceAtlas2Based",
                               forceAtlas2Based = list(gravitationalConstant = -50)) %>%
        visNetwork::visOptions(
          highlightNearest = list(enabled = TRUE, degree = 1, hover = TRUE),
          nodesIdSelection = TRUE,
          selectedBy = "group"
        ) %>%
        visNetwork::visLegend(useGroups = TRUE, position = "right") %>%
        visNetwork::visInteraction(navigationButtons = TRUE, zoomView = TRUE)
      
      # Save to file
      visNetwork::visSave(network, file, selfcontained = TRUE)
      
      showNotification(
        tagList(icon("check"), " Network exported as HTML"),
        type = "message",
        duration = 3
      )
    }
  )
  
