  # Filtered and sorted results
  filtered_enrichment_results <- reactive({
    req(enrichment_results())
    results_df <- enrichment_results()
    
    # Apply database filter
    if (!is.null(input$filter_database) && !"all" %in% input$filter_database) {
      if ("Database" %in% colnames(results_df)) {
        results_df <- results_df %>%
          dplyr::filter(Database %in% input$filter_database)
      }
    }
    
    # Apply sorting
    if (!is.null(input$sort_results_by) && input$sort_results_by %in% colnames(results_df)) {
      if (input$sort_results_by %in% c("Adjusted.P.value", "P.value")) {
        results_df <- results_df %>% dplyr::arrange(!!sym(input$sort_results_by))
      } else {
        results_df <- results_df %>% dplyr::arrange(desc(!!sym(input$sort_results_by)))
      }
    }
    
    return(results_df)
  })
  
  # Enhanced download handler for multiple databases
  output$download_enrichment_by_db <- downloadHandler(
    filename = function() {
      paste0("pathway_enrichment_by_database_", Sys.Date(), ".xlsx")
    },
    content = function(file) {
      load_export_packages()
      req(enrichment_results())
      results_df <- enrichment_results()
      
      if ("Database" %in% colnames(results_df)) {
        # Create workbook with separate sheets for each database
        wb <- openxlsx::createWorkbook()
        
        # Summary sheet
        summary_data <- results_df %>%
          dplyr::group_by(Database) %>%
          dplyr::summarise(
            Total_Pathways = n(),
            Avg_Pvalue = round(mean(Adjusted.P.value, na.rm = TRUE), 4),
            Top_Combined_Score = round(max(Combined.Score, na.rm = TRUE), 2),
            .groups = 'drop'
          )
        
        openxlsx::addWorksheet(wb, "Summary")
        openxlsx::writeData(wb, "Summary", summary_data)
        
        # Separate sheet for each database
        databases <- unique(results_df$Database)
        for (db in databases) {
          db_data <- results_df %>% dplyr::filter(Database == db)
          sheet_name <- gsub("[^A-Za-z0-9]", "_", db)  # Clean sheet name
          openxlsx::addWorksheet(wb, sheet_name)
          openxlsx::writeData(wb, sheet_name, db_data)
        }
        
        openxlsx::saveWorkbook(wb, file, overwrite = TRUE)
      } else {
        # Fallback to single CSV
        write.csv(results_df, file, row.names = FALSE)
      }
    }
  )
  
  # Pathway statistics
  output$pathway_statistics <- renderUI({
    req(enrichment_results())
    results_df <- enrichment_results()
    
    if ("Database" %in% colnames(results_df)) {
      # Calculate statistics
      total_pathways <- nrow(results_df)
      unique_databases <- length(unique(results_df$Database))
      sig_pathways <- sum(results_df$Adjusted.P.value < 0.05, na.rm = TRUE)
      top_pathway <- results_df$Term[which.min(results_df$Adjusted.P.value)]
      top_pval <- signif(min(results_df$Adjusted.P.value, na.rm = TRUE), 3)
      
      # Create horizontal card layout
      div(
        class = "enrichment-summary-row",
        style = "margin: 0;",
        
        # Card 1: Total Pathways
        div(
          class = "enrichment-stat-card stat-card-primary",
          div(class = "stat-icon", icon("layer-group")),
          div(
            div(class = "stat-value", format(total_pathways, big.mark = ",")),
            div(class = "stat-label", "Total Pathways")
          )
        ),
        
        # Card 2: Significant
        div(
          class = "enrichment-stat-card stat-card-success",
          div(class = "stat-icon", icon("check-double")),
          div(
            div(class = "stat-value", sig_pathways),
            div(class = "stat-label", "Significant (p<0.05)")
          )
        ),
        
        # Card 3: Databases
        div(
          class = "enrichment-stat-card stat-card-accent",
          div(class = "stat-icon", icon("database")),
          div(
            div(class = "stat-value", unique_databases),
            div(class = "stat-label", "Databases")
          )
        ),
        
        # Card 4: Top Finding
        div(
          class = "enrichment-stat-card stat-card-outline",
          div(class = "stat-icon", icon("trophy")),
          div(
            style = "margin-top: 5px;",
            div(style = "font-size: 12px; color: #667eea; font-weight: 600; margin-bottom: 5px;", "TOP PATHWAY"),
            div(
              style = "font-size: 13px; font-weight: 500; color: #2c3e50; line-height: 1.3; max-height: 36px; overflow: hidden;",
              title = top_pathway,
              substr(as.character(top_pathway), 1, 40),
              if (nchar(as.character(top_pathway)) > 40) "..." else ""
            ),
            div(
              style = "font-size: 12px; color: #28a745; margin-top: 6px; font-weight: 600;",
              paste("p =", format(top_pval, scientific = TRUE, digits = 2))
            )
          )
        )
      )
    } else {
      div(
        class = "alert alert-info",
        style = "text-align: center; padding: 20px; border-radius: 10px;",
        icon("check-circle", style = "font-size: 24px; color: #17a2b8; margin-bottom: 10px;"),
        p("Single database analysis completed.", style = "margin: 0; color: #0c5460;")
      )
    }
  })
  
  # 3. FIXED ENRICHMENT PLOT OUTPUT
  output$enrichment_plot <- renderPlot({
    req(enrichment_results())

    results_df <- enrichment_results()

    if (is.null(results_df) || nrow(results_df) == 0) {
      return(ggplot() +
               annotate("text", x = 0.5, y = 0.5, label = "No enrichment results to display.", size = 6) +
               theme_void())
    }

    # Data preparation. Enrichr's `Overlap` is "k/K" (pathway-coverage),
    # so GeneRatio here is the same quantity as IPA's Percent Dysregulated.
    plot_data <- results_df %>%
      arrange(Adjusted.P.value) %>%
      head(input$plot_pathways_count %||% 15) %>%
      mutate(
        Count = as.numeric(sapply(strsplit(Overlap, "/"), `[`, 1)),
        TotalGenes = as.numeric(sapply(strsplit(Overlap, "/"), `[`, 2)),
        GeneRatio = Count / TotalGenes,
        PercentDysregulated = GeneRatio * 100,
        neg_log_p = -log10(Adjusted.P.value),
        Term_Display = stringr::str_wrap(gsub("_", " ", Term), width = 50),
        Description_wrapped = factor(Term_Display, levels = rev(Term_Display))
      )

    if (nrow(plot_data) == 0) {
      return(ggplot() +
               annotate("text", x = 0.5, y = 0.5, label = "No pathways pass the filtering thresholds.", size = 6) +
               theme_void())
    }

    plot_type <- input$plot_type %||% "lollipop"
    color_scheme <- input$plot_color_scheme %||% "viridis"

    if (plot_type == "lollipop") {
      p <- build_enrichment_lollipop(plot_data, mode = "ora",
                                     top_n = input$plot_pathways_count %||% 15,
                                     base_size = 14)

    } else if (plot_type == "bubble") {
      # Advanced bubble plot - X axis: Gene Ratio, Y axis: Pathway, Color: -log10(p), Size: Gene Count
      p <- ggplot(plot_data, aes(x = GeneRatio, y = reorder(Term_Display, neg_log_p),
                                 size = Count, color = neg_log_p)) +
        geom_point(alpha = 0.7) +
        scale_color_viridis_c(option = color_scheme, name = "-log10(Adj. P-value)") +
        scale_size_continuous(name = "Gene Count", range = c(4, 15)) +
        scale_x_continuous(labels = scales::percent_format(accuracy = 1)) +
        labs(
          title = "Pathway Enrichment Bubble Plot",
          subtitle = paste("Database:", input$enrichr_database %||% ""),
          x = "Gene Ratio (% of pathway genes)",
          y = NULL
        ) +
        theme_minimal(base_size = 12) +
        theme(
          plot.title = element_text(face = "bold", size = 16, hjust = 0.5),
          plot.subtitle = element_text(size = 12, hjust = 0.5, color = "grey40"),
          axis.text.y = element_text(size = 10),
          axis.text.x = element_text(size = 10),
          axis.title.x = element_text(size = 12),
          legend.position = "bottom",
          legend.box = "horizontal",
          panel.grid.major.y = element_line(color = "grey90", linewidth = 0.5)
        )

    } else {
      # Classic bar plot
      p <- ggplot(plot_data, aes(x = reorder(Term_Display, neg_log_p), y = neg_log_p,
                                 fill = Count)) +
        geom_col(alpha = 0.8) +
        coord_flip() +
        scale_fill_viridis_c(option = color_scheme, name = "Gene Count") +
        labs(
          title = "Pathway Enrichment Bar Plot",
          subtitle = paste("Database:", input$enrichr_database %||% ""),
          x = NULL,
          y = "-log10(Adjusted P-value)"
        ) +
        theme_minimal(base_size = 12) +
        theme(
          plot.title = element_text(face = "bold", size = 16, hjust = 0.5),
          plot.subtitle = element_text(size = 12, hjust = 0.5, color = "grey40"),
          axis.text.y = element_text(size = 10),
          axis.text.x = element_text(size = 10),
          axis.title.y = element_text(size = 12),
          legend.position = "bottom"
        )
    }

    return(p)
  }, height = 700)
  
