          neg_log_p = -log10(Adjusted.P.value),
          Term_Display = stringr::str_wrap(gsub("_", " ", Term), width = 45),
          Description_wrapped = factor(Term_Display, levels = rev(Term_Display))
        )

      plot_type <- input$plot_type %||% "lollipop"
      color_scheme <- input$plot_color_scheme %||% "viridis"

      if (plot_type == "lollipop") {
        p <- build_enrichment_lollipop(plot_data, mode = "ora",
                                       top_n = input$plot_pathways_count %||% 15,
                                       base_size = 18)
      } else if (plot_type == "bubble") {
        p <- ggplot(plot_data, aes(x = GeneRatio, y = reorder(Term_Display, neg_log_p),
                                   size = Count, color = neg_log_p)) +
          geom_point(alpha = 0.7) +
          scale_color_viridis_c(option = color_scheme, name = "-log10(Adj. P-value)") +
          scale_size_continuous(name = "Gene Count", range = c(5, 18)) +
          scale_x_continuous(labels = scales::percent_format()) +
          labs(
            title = "Pathway Enrichment Bubble Plot",
            subtitle = paste("Database:", input$enrichr_database %||% ""),
            x = "Gene Ratio (% of pathway genes)",
            y = NULL
          ) +
          theme_minimal(base_size = 16) +
          theme(
            plot.title = element_text(face = "bold", size = 20, hjust = 0.5),
            plot.subtitle = element_text(size = 16, hjust = 0.5, color = "grey40"),
            axis.text.y = element_text(size = 14),
            axis.text.x = element_text(size = 14),
            axis.title.x = element_text(size = 16, face = "bold"),
            legend.position = "bottom",
            legend.box = "horizontal"
          )
      } else {
        p <- ggplot(plot_data, aes(x = reorder(Term_Display, neg_log_p), y = neg_log_p,
                                   fill = Count)) +
          geom_col(alpha = 0.8) +
          coord_flip() +
          scale_fill_viridis_c(option = color_scheme, name = "Gene Count") +
          labs(
            title = "Pathway Enrichment Bar Plot",
            subtitle = paste("Database:", input$enrichr_database %||% ""),
            x = NULL,
            y = "-log10(Adjusted P-value)"
          ) +
          theme_minimal(base_size = 16) +
          theme(
            plot.title = element_text(face = "bold", size = 20, hjust = 0.5),
            plot.subtitle = element_text(size = 16, hjust = 0.5, color = "grey40"),
            axis.text.y = element_text(size = 14),
            axis.text.x = element_text(size = 14),
            axis.title.x = element_text(size = 16, face = "bold"),
            legend.position = "bottom"
          )
      }

      # Publication-quality output; width widens with long labels
      max_label_chars <- max(nchar(as.character(plot_data$Term_Display)))
      plot_width  <- max(14, 10 + (max_label_chars / 18))
      plot_height <- max(10, (input$plot_pathways_count %||% 15) * 0.45)

      tryCatch({
        if (fmt == "svg") {
          ggsave(file, plot = p, device = "svg",
                 width = plot_width, height = plot_height, units = "in", bg = "white")
        } else if (fmt == "pdf") {
          ggsave(file, plot = p, device = cairo_pdf,
                 width = plot_width, height = plot_height, units = "in", bg = "white")
        } else {
          ggsave(file, plot = p, device = "png",
                 width = plot_width, height = plot_height, units = "in",
                 dpi = 600, bg = "white")
        }
      }, error = function(e) {
        # Vector device missing → fall back to PNG at 600 dpi
        ggsave(file, plot = p, device = "png",
               width = plot_width, height = plot_height, units = "in",
               dpi = 600, bg = "white")
      })
    }
  )
  
  # 4. ADD DOWNLOAD HANDLER FOR RESULTS
  output$download_enrichment <- downloadHandler(
    filename = function() {
      paste0("pathway_enrichment_results_", Sys.Date(), ".csv")
    },
    content = function(file) {
      load_export_packages()
      if (!is.null(enrichment_results())) {
        write.csv(enrichment_results(), file, row.names = FALSE)
      } else {
        write.csv(data.frame(Message = "No results available"), file, row.names = FALSE)
      }
    }
  )
  
  # 5. QUICK TEST: Add this temporary output to check if data is there
  output$debug_enrichment_info <- renderText({
    if (is.null(enrichment_results())) {
      return("No enrichment results")
    } else {
      return(paste("Enrichment results:", nrow(enrichment_results()), "pathways"))
    }
  })
  
  
  output$pathway_network <- renderVisNetwork({
    # This version uses the network tab specific controls instead of main controls
    req(enrichment_results())
    print("Starting HYBRID Gene-Pathway network (V2: Improved Aesthetics)...")
    
    # --- Data filtering section (no changes here, same as before) ---
    results_df <- enrichment_results()
    if (is.null(results_df) || nrow(results_df) == 0) { return() }
    tryCatch({
      pval_cutoff <- input$pathway_pval_cutoff_viz %||% 0.05
      min_genes <- input$min_genes_per_pathway_viz %||% 3
      pval_type <- input$pvalue_type_viz %||% "adjusted"
      pathway_count_val <- as.numeric(input$pathway_count %||% 10)
      if (pval_type == "raw") {
        results_df <- results_df %>% dplyr::filter(P.value < pval_cutoff)
      } else {
        results_df <- results_df %>% dplyr::filter(Adjusted.P.value < pval_cutoff)
      }
      if ("Overlap" %in% colnames(results_df)) {
        genes_in_pathway_count <- as.numeric(sapply(strsplit(results_df$Overlap, "/"), `[`, 1))
        results_df <- results_df[genes_in_pathway_count >= min_genes, ]
      }
      results_df <- results_df[order(results_df$Adjusted.P.value), ]
      if (!is.na(pathway_count_val) && pathway_count_val != -1) {
        results_df <- head(results_df, pathway_count_val)
      }
      if (nrow(results_df) == 0) {
        return(visNetwork(
          nodes = data.frame(id = 1, label = "No pathways passed filtering", shape = "text"),
          edges = data.frame(from = c(), to = c())
        ))
      }
      print(paste("Visualizing", nrow(results_df), "pathways"))
      gene_lists <- strsplit(as.character(results_df$Genes), ";")
      all_genes <- unique(unlist(gene_lists))
      
      # --- Node creation (no changes here, same as before) ---
      nodes <- data.frame(
        id = c(paste0("p_", 1:nrow(results_df)), paste0("g_", 1:length(all_genes))),
        label = c(stringr::str_wrap(results_df$Term, width = 25), all_genes),
        group = c(results_df$Database, rep("gene", length(all_genes))),
        title = c(
          paste0("<b>", results_df$Term, "</b><br><b>Database:</b> ", results_df$Database, "<br><b>Adj. P-value:</b> ", formatC(results_df$Adjusted.P.value, format = "e", digits = 2)),
          paste0("<b>", all_genes, "</b><br>Gene")
        ),
        value = c(pmax(30, pmin(70, -log10(results_df$Adjusted.P.value) * 10)), rep(20, length(all_genes))),
        font.size = c(rep(20, nrow(results_df)), rep(18, length(all_genes))),
        shape = c(rep("box", nrow(results_df)), rep("dot", length(all_genes))),
        stringsAsFactors = FALSE
      )
      if (!is.null(deg_data()) && nrow(deg_data()) > 0) {
        nodes$title <- create_enhanced_tooltips(nodes, deg_data())
      }
      
      # --- Edge creation with more transparent edges ---
      edges_list <- lapply(seq_len(nrow(results_df)), function(i) {
        genes <- unlist(gene_lists[[i]])
        genes <- genes[genes %in% all_genes]
        if (length(genes) > 0) {
          data.frame(
            from = rep(paste0("p_", i), length(genes)),
            to = paste0("g_", match(genes, all_genes)),
            width = 2,
            # <<< CHANGE 1: Made edges more transparent (0.5 -> 0.35) to reduce clutter
            color = list(color = "#848484", opacity = 0.35)
          )
        }
      })
      edges <- do.call(rbind, edges_list[!sapply(edges_list, is.null)])
      if (is.null(edges) || nrow(edges) == 0) {
        return(visNetwork(nodes = nodes, edges = data.frame(from=c(), to=c())))
      }
      
      # --- THE NETWORK VISUALIZATION ---
      # <<< CHANGE 2: Increased height for more vertical space (700px -> 850px)
      visNetwork(nodes, edges, width = "100%", height = "850px") %>%
        # 1. DEFINE COLORS AND STYLES FOR EACH DATABASE GROUP
        visGroups(groupname = "GO Biological Process", color = list(background="#a8e6cf", border="#4caf50", highlight="#4caf50"), shape = "box") %>%
        visGroups(groupname = "GO Molecular Function", color = list(background="#88d8c0", border="#26a69a", highlight="#26a69a"), shape = "box") %>%
        visGroups(groupname = "GO Cellular Component", color = list(background="#78c6a3", border="#388e3c", highlight="#388e3c"), shape = "box") %>%
        visGroups(groupname = "Reactome", color = list(background="#ffb3ba", border="#f44336", highlight="#f44336"), shape = "box") %>%
        visGroups(groupname = "KEGG Human", color = list(background="#bae1ff", border="#2196f3", highlight="#2196f3"), shape = "box") %>%
        visGroups(groupname = "WikiPathways Human", color = list(background="#ffd3a5", border="#ff9800", highlight="#ff9800"), shape = "box") %>%
        visGroups(groupname = "MSigDB Hallmark", color = list(background="#d4b5ff", border="#9c27b0", highlight="#9c27b0"), shape = "box") %>%
        visGroups(groupname = "BioCarta", color = list(background="#ffdfba", border="#ff5722", highlight="#ff5722"), shape = "box") %>%
        # <<< CHANGE 3: Changed gene color to a distinct blue
        visGroups(groupname = "gene", color = list(background="#d6e4ff", border="#2196f3", highlight="#2196f3"), shape = "dot") %>%
        
        # 2. TUNE PHYSICS FOR A GOOD INITIAL LAYOUT
        visPhysics(
          solver = "forceAtlas2Based",
          forceAtlas2Based = list(
            # --- KEY CHANGES FOR COMPACTNESS ---
            springLength = 100,      # Halved the desired spring length to pull nodes closer
            springConstant = 0.08,   # Slightly stiffer springs to enforce the new length
            avoidOverlap = 1,        # Maxed out avoidOverlap to prevent nodes from crashing into each other
            # --- Other parameters adjusted for balance ---
            gravitationalConstant = -70,
            centralGravity = 0.02,
            damping = 0.6
          ),
          stabilization = list(enabled = TRUE, iterations = 200, updateInterval = 25)
        ) %>%
        visEdges(
          smooth = FALSE,  # Disable smooth/curved edges
          width = 2
        ) %>%
        # 3. THE MAGIC: TURN OFF PHYSICS AFTER STABILIZATION
        visEvents(stabilizationIterationsDone = "function() {
         this.setOptions( { physics: false } );
       }") %>%
        
        # 4. GENERAL OPTIONS
        visOptions(
          highlightNearest = list(enabled = TRUE, degree = 1, hover = TRUE),
          nodesIdSelection = FALSE,
          selectedBy = list(variable = "group", multiple = TRUE)
        ) %>%
        visInteraction(
          dragNodes = TRUE,
          dragView = TRUE,
          zoomView = TRUE,
          navigationButtons = TRUE,
          tooltipDelay = 100
        ) %>%
        visLayout(randomSeed = 123) %>%
        # <<< CHANGE 4: Reduced legend width to give network more space (0.15 -> 0.12)
        visLegend(useGroups = TRUE, position = "right", width = 0.12, zoom = FALSE)
      
    }, error = function(e) {
      print(paste("Error in hybrid network:", e$message))
      return(visNetwork(nodes = data.frame(id = 1, label = paste("Error:", e$message), shape = "text"), edges = data.frame(from=c(), to=c())))
    })
  })
  
  
  # Enhanced reset button - it should now re-enable physics to re-calculate layout
  observeEvent(input$reset_network, {
    visNetworkProxy("pathway_network") %>%
      visPhysics(enabled = TRUE) # This re-enables physics to re-layout the network
    
    showNotification("Re-calculating network layout...", type = "message", duration = 4)
  })
  
  
  
  # Observer to sync network controls with main pathway controls
  observe({
    # Sync p-value type
    if (!is.null(input$pvalue_type) && !is.null(input$pvalue_type_viz)) {
      if (input$pvalue_type != input$pvalue_type_viz) {
        updateRadioButtons(session, "pvalue_type_viz", selected = input$pvalue_type)
      }
    }
    
    # Sync p-value cutoff
    if (!is.null(input$pathway_pval_cutoff) && !is.null(input$pathway_pval_cutoff_viz)) {
      if (input$pathway_pval_cutoff != input$pathway_pval_cutoff_viz) {
        updateNumericInput(session, "pathway_pval_cutoff_viz", value = input$pathway_pval_cutoff)
      }
    }
    
    # Sync min genes per pathway
    if (!is.null(input$min_genes_per_pathway) && !is.null(input$min_genes_per_pathway_viz)) {
      if (input$min_genes_per_pathway != input$min_genes_per_pathway_viz) {
        updateNumericInput(session, "min_genes_per_pathway_viz", value = input$min_genes_per_pathway)
      }
    }
  })
  
  # Keeping pathway_network_alt as is, assuming it's not the primary one for stability
  # and relies on physics for its layout, so visFit is not directly problematic there
  # (it wasn't in your original code either for this one).
  output$pathway_network_alt <- renderVisNetwork({
    # This version uses the network tab specific controls instead of main controls
    req(enrichment_results())
    print("Starting Gene-Pathway network visualization (alternative version)...")
    
    results_df <- enrichment_results()
    
    if (is.null(results_df) || nrow(results_df) == 0) {
      return(visNetwork(
        nodes = data.frame(id = 1, label = "No significant pathways found", shape = "text"),
        edges = data.frame(from = c(), to = c())
      ))
    }
    
    tryCatch({
      # Use network-specific controls
      pval_cutoff <- input$pathway_pval_cutoff_viz %||% input$pathway_pval_cutoff %||% 0.05
      min_genes <- input$min_genes_per_pathway_viz %||% input$min_genes_per_pathway %||% 3
      pval_type <- input$pvalue_type_viz %||% input$pvalue_type %||% "adjusted"
      pathway_count_val <- as.numeric(input$pathway_count %||% 10)
      
      # Apply filtering
      if (pval_type == "raw") {
        results_df <- results_df %>% dplyr::filter(P.value < pval_cutoff)
      } else {
        results_df <- results_df %>% dplyr::filter(Adjusted.P.value < pval_cutoff)
      }
      
      # Filter by minimum genes per pathway
      if ("Overlap" %in% colnames(results_df)) {
        genes_in_pathway_count <- as.numeric(sapply(strsplit(results_df$Overlap, "/"), `[`, 1))
        results_df <- results_df[genes_in_pathway_count >= min_genes, ]
      }
      
      # Sort and take top pathways
      results_df <- results_df[order(results_df$Adjusted.P.value), ]
      if (!is.na(pathway_count_val) && pathway_count_val != -1) {
        results_df <- head(results_df, pathway_count_val)
      }
      
      if (nrow(results_df) == 0) {
        return(visNetwork(
          nodes = data.frame(id = 1, label = "No pathways passed filtering", shape = "text"),
          edges = data.frame(from = c(), to = c())
        ))
      }
      
      print(paste("Visualizing", nrow(results_df), "pathways with network controls (Alternative, Physics-based)"))
      # Parse genes from pathways (split by semicolon in enrichR)
      gene_lists <- strsplit(as.character(results_df$Genes), ";")
      all_genes <- unique(unlist(gene_lists))
      
      print(paste("Total unique genes:", length(all_genes)))
      
      # Create database-specific colors (consistent with ultra_stable)
      unique_dbs <- unique(results_df$Database)
      database_colors <- list(
        "GO Biological Process" = list(background = "#a8e6cf", border = "#4caf50"),
        "GO Molecular Function" = list(background = "#88d8c0", border = "#26a69a"),
        "GO Cellular Component" = list(background = "#78c6a3", border = "#388e3c"),
        "Reactome" = list(background = "#ffb3ba", border = "#f44336"),
        "KEGG Human" = list(background = "#bae1ff", border = "#2196f3"),
        "WikiPathways Human" = list(background = "#ffd3a5", border = "#ff9800"),
        "MSigDB Hallmark" = list(background = "#d4b5ff", border = "#9c27b0"),
        "BioCarta" = list(background = "#ffdfba", border = "#ff5722")
      )
      
      if (length(unique_dbs) > length(names(database_colors))) {
        if (requireNamespace("RColorBrewer", quietly = TRUE)) {
          extra_colors <- RColorBrewer::brewer.pal(min(9, max(3, length(unique_dbs) - length(names(database_colors)))), "Dark2")
        } else {
          extra_colors <- rainbow(length(unique_dbs) - length(names(database_colors)))
        }
        current_db_names <- names(database_colors)
        extra_db_counter <- 1
        for (db_name in unique_dbs) {
          if (!(db_name %in% current_db_names)) {
            color_bg <- extra_colors[extra_db_counter]
            rgb_vals <- col2rgb(color_bg)
            color_border <- rgb(rgb_vals[1]*0.7/255, rgb_vals[2]*0.7/255, rgb_vals[3]*0.7/255)
            database_colors[[db_name]] <- list(background = color_bg, border = color_border)
            extra_db_counter <- extra_db_counter + 1
          }
        }
      }
      
      # Create nodes dataframe
      nodes <- data.frame(
        id = c(paste0("p_", 1:nrow(results_df)),
               paste0("g_", 1:length(all_genes))),
        label = c(
          # Truncate long pathway names for better display
          ifelse(nchar(results_df$Term) > 40,
                 paste0(substr(results_df$Term, 1, 37), "..."),
                 results_df$Term),
          all_genes
        ),
        group = c(results_df$Database, rep("gene", length(all_genes))),
        title = c(
          # Pathway tooltips
          paste0(
            "<b>", results_df$Term, "</b><br>",
            "Database: ", results_df$Database, "<br>",
            "Genes: ", sapply(strsplit(results_df$Overlap, "/"), `[`, 1), " / ",
            sapply(strsplit(results_df$Overlap, "/"), `[`, 2), "<br>",
            "P-value: ", formatC(results_df$P.value, format = "e", digits = 2), "<br>",
            "Adj. P-value: ", formatC(results_df$Adjusted.P.value, format = "e", digits = 2), "<br>",
            "Combined Score: ", round(results_df$Combined.Score, 2)
          ),
          # Gene tooltips
          paste0("<b>", all_genes, "</b><br>Gene")
        ),
        value = c(
          # Size pathways by significance (-log10 p-value)
          pmax(20, pmin(60, -log10(results_df$Adjusted.P.value) * 8)),
          rep(15, length(all_genes))  # Smaller nodes for genes
        ),
        color.background = c( # Use color.background directly
          sapply(results_df$Database, function(db) {
            if (db %in% names(database_colors)) {
              database_colors[[db]]$background
            } else {
              "#e0e0e0"  # Default gray
            }
          }),
          rep("#fb7e81", length(all_genes))  # Gene color (light red)
        ),
        color.border = c( # Use color.border directly
          sapply(results_df$Database, function(db) {
            if (db %in% names(database_colors)) {
              database_colors[[db]]$border
            } else {
              "#999999"  # Default gray border
            }
          }),
          rep("#e62e00", length(all_genes))  # Gene border color (dark red)
        ),
        shape = c(
          rep("box", nrow(results_df)),    # Pathways as boxes
          rep("dot", length(all_genes))    # Genes as dots
        ),
        stringsAsFactors = FALSE
      )
      
      # Apply enhanced tooltips if DEG data is available
      if (!is.null(deg_data()) && nrow(deg_data()) > 0) {
        nodes$title <- create_enhanced_tooltips(nodes, deg_data())
      }
      
      # Create edges between pathways and their genes
      edges_list <- lapply(seq_len(nrow(results_df)), function(i) {
        genes <- unlist(gene_lists[[i]])
        genes <- genes[genes %in% all_genes]  # Ensure genes exist in our list
        
        if (length(genes) > 0) {
          data.frame(
            from = rep(paste0("p_", i), length(genes)),
            to = paste0("g_", match(genes, all_genes)),
            width = 2,
            color = list(color = "#848484", opacity = 0.7),
            smooth = list(enabled = TRUE, type = "continuous"),
            stringsAsFactors = FALSE
          )
        } else {
          data.frame(from = character(0), to = character(0),
                     width = numeric(0), color = character(0),
                     smooth = logical(0), stringsAsFactors = FALSE)
        }
      })
      
      edges <- do.call(rbind, edges_list)
      
      if (nrow(edges) == 0 && nrow(nodes) > 0) {
        warning("No edges found for the selected pathways and genes.")
      } else if (nrow(nodes) == 0) {
        return(visNetwork(
          nodes = data.frame(id = 1, label = "No pathways or genes to display", shape = "text"),
          edges = data.frame(from = c(), to = c())
        ))
      }
      
      print(paste("Created", nrow(nodes), "nodes and", nrow(edges), "edges"))
      
      # Create the visNetwork
      network <- visNetwork(nodes, edges, width = "100%", height = "600px") %>%
        # Configure pathway groups by database
        {
          current_network <- .
          for (db_name in unique_dbs) {
            if (db_name %in% names(database_colors)) {
              current_network <- current_network %>%
                visGroups(
                  groupname = db_name,
                  color = database_colors[[db_name]],
                  shape = "box",
                  shadow = TRUE,
                  font = list(size = 12, color = "#333333")
                )
            }
          }
          current_network
        } %>%
        # Configure gene group
        visGroups(
          groupname = "gene",
          color = list(background = "#fb7e81", border = "#e62e00"),
          shape = "dot",
          shadow = TRUE,
          font = list(size = 10, color = "#333333")
        ) %>%
        # Physics settings for better layout
        visPhysics(
          solver = "forceAtlas2Based",
          forceAtlas2Based = list(
            gravitationalConstant = -50,
            centralGravity = 0.01,
            springLength = 100,
            springConstant = 0.08,
            damping = 0.4,
            avoidOverlap = 0.5
          ),
          maxVelocity = 20,
          minVelocity = 0.1,
          timestep = 0.35,
          stabilization = list(enabled = TRUE, iterations = 200)
        ) %>%
        # Layout options
        visLayout(randomSeed = 123) %>%
        # Interaction options
        visOptions(
          highlightNearest = list(enabled = TRUE, degree = 1, hover = TRUE),
          selectedBy = list(variable = "group", multiple = TRUE),
          nodesIdSelection = FALSE
        ) %>%
        # Configure edges
        visEdges(
          smooth = list(enabled = TRUE, type = "continuous"),
          color = list(color = "#848484", opacity = 0.7)
        ) %>%
        # Add legend
        visLegend(
          addNodes = list(
            list(label = "Pathways", shape = "box", color = "#a8e6cf"),
            list(label = "Genes", shape = "dot", color = "#fb7e81")
          ),
          useGroups = FALSE,
          position = "right",
          main = "Network Legend"
        )
      
      return(network)
    }, error = function(e) {
      print(paste("Error in alternative pathway network:", e$message))
      return(visNetwork(
        nodes = data.frame(id = 1, label = paste("Error:", e$message), shape = "text"),
        edges = data.frame(from = c(), to = c())
      ))
    })
  })
  
  # Function to create enhanced network tooltips with DEG info
  create_enhanced_tooltips <- function(nodes, deg_data = NULL) {
    if (is.null(deg_data) || nrow(deg_data) == 0 || !("log2FC" %in% colnames(deg_data)) || !("adj.P.Val" %in% colnames(deg_data))) {
      return(nodes$title)  # Return existing tooltips if no valid DEG data
    }
    
    # Ensure deg_data has rownames as gene names
    if (!is.null(rownames(deg_data)) && is.character(rownames(deg_data))) {
      # It's already good
    } else if ("Gene" %in% colnames(deg_data)) { # Common case if "Gene" is a column
      rownames(deg_data) <- deg_data$Gene
    } else { # Fallback
      warning("DEG data does not have gene names as row names or a 'Gene' column. Cannot enhance tooltips.")
      return(nodes$title)
    }
    
    # Create a copy to modify
    enhanced_titles <- nodes$title
    gene_indices <- which(startsWith(nodes$id, "g_"))
    
    for (i in gene_indices) {
      gene_name <- nodes$label[i]
      
      if (gene_name %in% rownames(deg_data)) {
        deg_info <- deg_data[gene_name, ]
        log2fc <- round(deg_info$log2FC, 2)
        adj_pval <- formatC(deg_info$adj.P.Val, format = "e", digits = 2)
        
        # Determine regulation status (adjust thresholds as needed)
        status <- "Not significantly changed"
        status_color <- "#757575" # Grey
        
        if (abs(log2fc) >= 1 && adj_pval < 0.05) { # Example criteria for significant change
          if (log2fc > 0) {
            status <- "Upregulated"
            status_color <- "#d32f2f" # Red
          } else {
            status <- "Downregulated"
            status_color <- "#1976d2" # Blue
          }
        }
        
        # Enhanced tooltip
        enhanced_titles[i] <- paste0(
          "<b style='color:", status_color, "'>", gene_name, "</b><br>",
          "<b>DEG Status:</b> ", status, "<br>",
          "<b>Log2FC:</b> ", log2fc, "<br>",
          "<b>Adj. P-value:</b> ", adj_pval
        )
      }
    }
    
    return(enhanced_titles)
  }
  
  
  
  # Initial fit when enrichment results are ready or filters change
  # This observer sends the visFit command after the network is rendered.
  observeEvent({
    enrichment_results()
    input$pathway_pval_cutoff_viz # Trigger on filter changes too
    input$min_genes_per_pathway_viz
    input$pvalue_type_viz
    input$pathway_count
  }, {
    if (!is.null(enrichment_results()) && nrow(enrichment_results()) > 0) {
      # Small delay to ensure network is rendered before fitting
      invalidateLater(1000, session)
      isolate({
        # IMPORTANT: Use the correct output ID for the network
        visNetworkProxy("pathway_network") %>%
          visFit(animation = list(duration = 1500))
      })
    }
  })
  
  # Network download handler (PNG)
  output$download_network_png <- downloadHandler(
    filename = function() {
      paste0("Gene-Pathway-Network-", Sys.Date(), ".png")
    },
    content = function(file) {
      load_export_packages()
      # 1. Show a notification to the user that the process has started
      progress_id <- showNotification(
        "Generating high-resolution PNG... This may take a few moments.",
        duration = NULL, closeButton = FALSE, type = "message"
      )
      # Ensure the notification is removed when the function exits
      on.exit(removeNotification(progress_id), add = TRUE)
      
      tryCatch({
        # 2. Re-fetch and re-filter data exactly as the interactive network does
        # This ensures the downloaded network represents the current view
        results_df <- enrichment_results()
        # (This filtering logic is copied from the renderVisNetwork block)
        pval_cutoff <- input$pathway_pval_cutoff_viz %||% 0.05
        min_genes <- input$min_genes_per_pathway_viz %||% 3
        pval_type <- input$pvalue_type_viz %||% "adjusted"
        pathway_count_val <- as.numeric(input$pathway_count %||% 10)
        if (pval_type == "raw") {
          results_df <- results_df %>% dplyr::filter(P.value < pval_cutoff)
        } else {
          results_df <- results_df %>% dplyr::filter(Adjusted.P.value < pval_cutoff)
        }
        if ("Overlap" %in% colnames(results_df)) {
          genes_in_pathway_count <- as.numeric(sapply(strsplit(results_df$Overlap, "/"), `[`, 1))
          results_df <- results_df[genes_in_pathway_count >= min_genes, ]
        }
        results_df <- results_df[order(results_df$Adjusted.P.value), ]
        if (!is.na(pathway_count_val) && pathway_count_val != -1) {
          results_df <- head(results_df, pathway_count_val)
        }
        if (nrow(results_df) == 0) {
          stop("No data to generate network plot. Please adjust filters.")
        }
        gene_lists <- strsplit(as.character(results_df$Genes), ";")
        all_genes <- unique(unlist(gene_lists))
        
        # 3. Re-build the nodes and edges with the same styling
        nodes_export <- data.frame(
          id = c(paste0("p_", 1:nrow(results_df)), paste0("g_", 1:length(all_genes))),
          label = c(stringr::str_wrap(results_df$Term, width = 25), all_genes),
          group = c(results_df$Database, rep("gene", length(all_genes))),
          value = c(pmax(30, pmin(70, -log10(results_df$Adjusted.P.value) * 10)), rep(20, length(all_genes))),
          font.size = c(rep(20, nrow(results_df)), rep(18, length(all_genes))),
          shape = c(rep("box", nrow(results_df)), rep("dot", length(all_genes))),
          stringsAsFactors = FALSE
        )
        
        edges_export <- do.call(rbind, lapply(seq_len(nrow(results_df)), function(i) {
          genes <- unlist(gene_lists[[i]])[unlist(gene_lists[[i]]) %in% all_genes]
          if (length(genes) > 0) {
            data.frame(from = rep(paste0("p_", i), length(genes)), to = paste0("g_", match(genes, all_genes)))
          }
        }))
        
        # 4. Create a DEDICATED visNetwork object for export
        #    It's large and has all interactive elements turned off.
        export_network <- visNetwork(nodes_export, edges_export,
                                     width = "2400px", height = "2400px", # Large canvas for high resolution
                                     main = list(text = "Gene-Pathway Network", style = "font-family:Arial;font-size:36px;font-weight:bold;")) %>%
          # Use the exact same group styling
          visGroups(groupname = "GO Biological Process", color = list(background="#a8e6cf", border="#4caf50"), shape = "box") %>%
          visGroups(groupname = "GO Molecular Function", color = list(background="#88d8c0", border="#26a69a"), shape = "box") %>%
          visGroups(groupname = "GO Cellular Component", color = list(background="#78c6a3", border="#388e3c"), shape = "box") %>%
          visGroups(groupname = "Reactome", color = list(background="#ffb3ba", border="#f44336"), shape = "box") %>%
          visGroups(groupname = "KEGG Human", color = list(background="#bae1ff", border="#2196f3"), shape = "box") %>%
          visGroups(groupname = "WikiPathways Human", color = list(background="#ffd3a5", border="#ff9800"), shape = "box") %>%
          visGroups(groupname = "MSigDB Hallmark", color = list(background="#d4b5ff", border="#9c27b0"), shape = "box") %>%
          visGroups(groupname = "BioCarta", color = list(background="#ffdfba", border="#ff5722"), shape = "box") %>%
          visGroups(groupname = "gene", color = list(background="#d6e4ff", border="#2196f3"), shape = "dot") %>%
          # Use the same physics to ensure a good layout
          visPhysics(
            solver = "forceAtlas2Based",
            forceAtlas2Based = list(
              # --- APPLYING THE SAME COMPACT LAYOUT SETTINGS ---
              springLength = 100,
              springConstant = 0.08,
              avoidOverlap = 1,
              gravitationalConstant = -70,
              centralGravity = 0.02,
              damping = 0.6
            ),
            stabilization = list(enabled = TRUE, iterations = 500) # Keep more iterations for a perfect static layout
          ) %>%
          visEdges(
            smooth = FALSE,
            width = 2
          ) %>%
          # Turn OFF all interactive elements for the final image
          visInteraction(
            dragNodes = FALSE, dragView = FALSE, zoomView = FALSE,
            navigationButtons = FALSE, tooltipDelay = 0
          ) %>%
          visOptions(highlightNearest = FALSE, nodesIdSelection = FALSE) %>%
          visLayout(randomSeed = 123)
        
        # 5. Save the network to a temporary HTML file
        temp_html_path <- tempfile(fileext = ".html")
        visSave(export_network, file = temp_html_path, selfcontained = TRUE, background = "white")
        
        # 6. Use webshot2 to take a high-resolution screenshot
        # Set Chrome args for server/Docker environments BEFORE calling webshot
        old_chrome_args <- Sys.getenv("CHROMOTE_CHROME_ARGS")
        Sys.setenv(CHROMOTE_CHROME_ARGS = "--no-sandbox --disable-gpu --disable-dev-shm-usage")
        on.exit(Sys.setenv(CHROMOTE_CHROME_ARGS = old_chrome_args), add = TRUE)
        
        
        webshot2::webshot(
          url = temp_html_path,
          file = file,
          delay = 5,      # IMPORTANT: Give enough time for physics to stabilize
          vwidth = 2400,  # Match the canvas width
          vheight = 2400, # Match the canvas height
          zoom = 2,        # KEY for high-res: renders at 2x pixel density
          # --- KEY ADDITION FOR SERVER/DOCKER ENVIRONMENTS ---
          extra_args = c(
            "--no-sandbox",
            "--disable-gpu",
            "--disable-dev-shm-usage"
          )
        )
        
        showNotification("PNG downloaded successfully!", type = "message", duration = 5)
        
      }, error = function(e) {
        showNotification(paste("Error generating PNG:", e$message), type = "error", duration = 10)
        print(paste("Error in PNG download:", e$message))
      })
    }
  )
  
