          visInteraction(
            dragNodes = TRUE, 
            dragView = TRUE, 
            zoomView = TRUE,
            navigationButtons = TRUE,
            keyboard = TRUE,
            tooltipDelay = 100,
            hover = TRUE
          ) %>%
