          ) %>%
          visLayout(randomSeed = 123) %>%
          visLegend(useGroups = TRUE, position = "right", width = 0.12, zoom = FALSE)
        
        # Save as self-contained HTML
        visSave(export_network, file = file, selfcontained = TRUE, background = "white")
        
        showNotification("Interactive HTML network downloaded!", type = "message", duration = 5)
        
      }, error = function(e) {
        showNotification(paste("Error generating HTML:", e$message), type = "error", duration = 10)
        print(paste("Error in HTML download:", e$message))
      })
    }
  )
  
  # Network statistics panel
  output$network_stats <- renderUI({
    req(enrichment_results())
    
    results_df <- enrichment_results()
    
    # Apply same filtering as network
    pval_cutoff <- input$pathway_pval_cutoff_viz %||% input$pathway_pval_cutoff %||% 0.05
    min_genes <- input$min_genes_per_pathway_viz %||% input$min_genes_per_pathway %||% 3
    pval_type <- input$pvalue_type_viz %||% input$pvalue_type %||% "adjusted"
    pathway_count_val <- as.numeric(input$pathway_count %||% 10)
    
    if (pval_type == "raw") {
      results_df <- results_df %>% dplyr::filter(P.value < pval_cutoff)
    } else {
      results_df <- results_df %>% dplyr::filter(Adjusted.P.value < pval_cutoff)
    }
    
    if ("Overlap" %in% colnames(results_df)) {
      genes_in_pathway_count <- as.numeric(sapply(strsplit(results_df$Overlap, "/"), `[`, 1))
      results_df <- results_df[genes_in_pathway_count >= min_genes, ]
    }
    
    if (!is.na(pathway_count_val) && pathway_count_val != -1) {
      results_df <- head(results_df[order(results_df$Adjusted.P.value), ], pathway_count_val)
    }
    
    if (nrow(results_df) > 0) {
      gene_lists <- strsplit(as.character(results_df$Genes), ";")
      all_genes <- unique(unlist(gene_lists))
      total_connections <- sum(sapply(gene_lists, length))
      
      # Get database counts and create colored indicators
      db_counts <- table(results_df$Database)
      unique_dbs <- names(db_counts)
      
      # Use same colors as network
      db_colors <- c("#4CAF50", "#2196F3", "#FF9800", "#9C27B0", "#F44336",
                     "#00BCD4", "#FF5722", "#795548", "#607D8B")[1:length(unique_dbs)]
      names(db_colors) <- unique_dbs
      
      # Create colored database indicators
      db_indicators <- sapply(unique_dbs, function(db) {
        paste0('<span style="background-color:', db_colors[db], '; color: white; padding: 3px 8px; border-radius: 4px; margin-right: 8px; font-size: 0.9em; font-weight: bold;">',
               db, ' (', db_counts[db], ')</span>')
      })
      db_html <- paste(db_indicators, collapse = " ")
      
      div(class = "alert alert-success",
          style = "margin: 5px 0; padding: 12px; background-color: #d4edda; border: 1px solid #c3e6cb;",
          HTML(paste0(
            "<div style='color: #155724;'>",
            "<div style='display: flex; justify-content: space-between; align-items: center; margin-bottom: 8px;'>",
            "<div><strong>&#128202; Network:</strong> ", nrow(results_df), " pathways | ",
            length(all_genes), " genes | ", total_connections, " connections</div>",
            "<div>", db_html, "</div>",
            "</div>",
            "</div>"
          ))
      )
    } else {
      div(class = "alert alert-warning",
          style = "margin: 5px 0; padding: 10px; background-color: #fff3cd; border: 1px solid #ffeaa7;",
          HTML("<div style='color: #856404;'><strong>&#9888; No pathways meet the current filtering criteria</strong></div>")
      )
    }
  })
  
  
  
