  tcga_pathway_selection_state <- reactiveVal("default")  # "default" or "custom"
  selected_tcga_pathways <- reactiveVal(NULL)
  tcga_pathway_data <- reactiveVal(NULL)
  
  # Observe the button click to show the pathway selection modal
  observeEvent(input$select_tcga_pathways, {
    req(tcga_pathway_results())
    
    # Combine results from all databases
    all_pathway_data <- list()
    
    # Process each database's results
    for (db_name in names(tcga_pathway_results())) {
      pathway_df <- tcga_pathway_results()[[db_name]]
      
      # Skip if no results for this database
      if (is.null(pathway_df) || nrow(pathway_df) == 0) {
        next
      }
      
      # Add database information
      pathway_df$Database <- db_name
      all_pathway_data[[db_name]] <- pathway_df
    }
    
    # Combine all database results
    if (length(all_pathway_data) > 0) {
      # Combine results with do.call/rbind
      combined_data <- do.call(rbind, all_pathway_data)
      
      # Filter by adjusted p-value
      combined_data <- combined_data[combined_data$Adjusted.P.value < input$tcga_pval_cutoff, ]
      
      # Create data for the table
      pathway_table <- data.frame(
        Pathway = combined_data$Term,
        Database = combined_data$Database,
        Adj.P.value = formatC(combined_data$Adjusted.P.value, format = "e", digits = 2),
        Combined.Score = round(combined_data$Combined.Score, 2),
        Gene.Count = sapply(strsplit(combined_data$Overlap, "/"), function(x) as.numeric(x[1])),
        stringsAsFactors = FALSE
      )
      
      # Add original data columns for reference
      pathway_table$Original_Term <- combined_data$Term
      pathway_table$Original_Database <- combined_data$Database
      pathway_table$Original_Genes <- combined_data$Genes
      pathway_table$Original_Adjusted_P_value <- combined_data$Adjusted.P.value
      pathway_table$Original_Combined_Score <- combined_data$Combined.Score
      pathway_table$Original_Overlap <- combined_data$Overlap
      
      # Store the pathway data for reference
      tcga_pathway_data(pathway_table)
      
      # Show the selection modal
      showModal(modalDialog(
        title = "Select Pathways to Visualize",
        size = "l",
        easyClose = TRUE,
        
        div(
          style = "height: 600px; padding: 20px;",
          div(
            style = "margin-bottom: 15px;",
            tags$b("Available Pathways:"),
            tags$p("Select pathways to include in the network visualization.",
                   style = "color: #666;")
          ),
          div(
            style = "height: 450px; overflow-y: auto;",
            DT::dataTableOutput("tcga_pathway_select_table")
          )
        ),
        
        footer = div(
          style = "display: flex; justify-content: space-between; align-items: center;",
          div(
            actionButton("select_all_tcga_pathways", "Select All",
                         class = "btn btn-info",
                         style = "margin-right: 10px;"),
            actionButton("clear_all_tcga_pathways", "Clear All",
                         class = "btn btn-warning")
          ),
          div(
            modalButton("Cancel"),
            actionButton("generate_custom_tcga_network", "Generate Network",
                         class = "btn btn-primary",
                         style = "margin-left: 10px;")
          )
        )
      ))
    } else {
      showNotification("No pathway results available to select from", type = "warning")
    }
  })
  
  output$pca_plot_tcga_auto <- renderPlotly({
    req(tcga_rv$analysis_complete, tcga_rv$counts_normalized, tcga_rv$coldata)
    
    tryCatch({
      counts <- tcga_rv$counts_normalized
      coldata <- tcga_rv$coldata
      
      # Remove genes with zero variance
      var_genes <- apply(counts, 1, var, na.rm = TRUE)
      var_genes[is.na(var_genes)] <- 0
      
      # Use top 1000 variable genes
      top_var_idx <- head(order(var_genes, decreasing = TRUE), min(1000, sum(var_genes > 0)))
      counts_pca <- counts[top_var_idx, ]
      
      # Remove any remaining NA
      counts_pca <- counts_pca[complete.cases(counts_pca), ]
      
      # Run PCA
      pca_result <- prcomp(t(counts_pca), scale. = TRUE, center = TRUE)
      
      # Variance explained
      var_explained <- round(100 * pca_result$sdev^2 / sum(pca_result$sdev^2), 1)
      
      # Plot data
      plot_data <- data.frame(
        PC1 = pca_result$x[, 1],
        PC2 = pca_result$x[, 2],
        Sample = rownames(pca_result$x),
        Group = coldata[rownames(pca_result$x), "group"]
      )
      
      plot_ly(plot_data, x = ~PC1, y = ~PC2,
              type = "scatter", mode = "markers",
              color = ~Group,
              marker = list(size = 10, opacity = 0.8),
              text = ~paste("Sample:", Sample, "<br>Group:", Group),
              hoverinfo = "text") %>%
        layout(
          xaxis = list(title = paste0("PC1 (", var_explained[1], "%)")),
          yaxis = list(title = paste0("PC2 (", var_explained[2], "%)")),
          legend = list(orientation = "h", y = -0.15)
        )
      
    }, error = function(e) {
      plotly::plot_ly() %>%
        layout(title = list(text = paste("PCA Error:", e$message), font = list(size = 12)))
    })
  })
  
  
  # Helper function to create clickable gene tables
  create_tcga_gene_table_clickable <- function(data, table_id) {
    DT::datatable(
      data,
      selection = 'single',
      rownames = FALSE,
      filter = 'top',
      options = list(
        pageLength = 15,
        scrollX = TRUE,
        dom = 'lfrtip',
        order = list(list(which(names(data) == "adj.P.Val") - 1, 'asc'))
      ),
      class = 'cell-border stripe hover',
      callback = JS(paste0("
      table.on('click', 'tbody tr', function() {
        var data = table.row(this).data();
        if (data) {
          Shiny.setInputValue('", table_id, "_row_clicked', {
            gene_name: data[0],
            ensembl_id: data[1],
            nonce: Math.random()
          });
        }
      });
    "))
    ) %>%
      DT::formatSignif(columns = intersect(c("P.Value", "adj.P.Val"), names(data)), digits = 3) %>%
      DT::formatRound(columns = intersect(c("log2FC", "AveExpr", "logCPM"), names(data)), digits = 3)
  }
  
  
  # Dynamic normalization options based on analysis method
  output$tcga_norm_ui <- renderUI({
    method <- input$analysis_method
    
    if (method == "limma") {
      selectInput("normalization_method",
                  "Normalization Method*",
                  choices = c("TMM (recommended)" = "TMM", 
                              "RLE" = "RLE", 
                              "Upper Quartile" = "upperquartile"),
                  selected = "TMM")
    } else if (method == "edgeR") {
      selectInput("normalization_method",
                  "Normalization Method*",
                  choices = c("TMM (recommended)" = "TMM", 
                              "RLE" = "RLE", 
                              "Upper Quartile" = "upperquartile"),
                  selected = "TMM")
    } else if (method == "DESeq2") {
      # DESeq2 uses its own internal normalization (median of ratios)
      selectInput("normalization_method",
                  "Normalization Method*",
                  choices = c("Median of Ratios (built-in)" = "DESeq2_default"),
                  selected = "DESeq2_default")
    }
  })
  
  # Dynamic help text for normalization
  output$norm_help_text <- renderText({
    method <- input$analysis_method
    
    if (method == "limma" || method == "edgeR") {
      "TMM is recommended for most RNA-seq data. RLE is robust to outliers."
    } else if (method == "DESeq2") {
      "DESeq2 uses its own median-of-ratios normalization automatically."
    }
  })
  
  # Render the pathway selection table
  output$tcga_pathway_select_table <- DT::renderDataTable({
    req(tcga_pathway_data())
    
    DT::datatable(
      tcga_pathway_data(),
      selection = 'multiple',
      options = list(
        pageLength = 15,
        scrollX = TRUE,
        scrollY = "400px",
        dom = 'frtip',
        order = list(list(2, 'asc')),  # Sort by adj p-value by default
        columnDefs = list(
          list(className = 'dt-center', targets = "_all")
        )
      ),
      rownames = FALSE
    ) %>%
      DT::formatStyle(
        columns = c("Pathway", "Database", "Adj.P.value", "Combined.Score", "Gene.Count"),
        backgroundColor = DT::styleEqual(
          c(NA), c('white')
        )
      )
  })
  
  # Handle select all button
  observeEvent(input$select_all_tcga_pathways, {
    req(tcga_pathway_data())
    all_rows <- seq_len(nrow(tcga_pathway_data()))
    DT::dataTableProxy("tcga_pathway_select_table") %>%
      DT::selectRows(all_rows)
  })
  
  # Handle clear all button
  observeEvent(input$clear_all_tcga_pathways, {
    DT::dataTableProxy("tcga_pathway_select_table") %>%
      DT::selectRows(NULL)
  })
  
  # Handle generate network button
  observeEvent(input$generate_custom_tcga_network, {
    req(tcga_pathway_data())
    selected_rows <- input$tcga_pathway_select_table_rows_selected
    
    if (length(selected_rows) > 0) {
      # Get the selected pathways with ALL necessary data
      selected_pathways <- tcga_pathway_data()[selected_rows, ]
      
      # Debug print to verify selection
      print(paste("Selected", length(selected_rows), "pathways for visualization"))
      print("First selected pathway:")
      if(length(selected_rows) > 0) {
        print(selected_pathways[1, ])
      }
      
      # Create proper enrichment results structure
      custom_results <- list()
      
      # Group selected pathways by database
      db_groups <- split(selected_pathways, selected_pathways$Database)
      
      # Recreate enrichment results structure for each database
      for(db_name in names(db_groups)) {
        pathways <- db_groups[[db_name]]
        
        # Create a data frame that matches the original enrichment results structure
        db_df <- data.frame(
          Term = pathways$Original_Term,
          Overlap = pathways$Original_Overlap,
          P.value = pathways$Original_Adjusted_P_value, # Using adjusted p-value as a placeholder
          Adjusted.P.value = pathways$Original_Adjusted_P_value,
          Combined.Score = pathways$Original_Combined_Score,
          Genes = pathways$Original_Genes,
          stringsAsFactors = FALSE
        )
        
        # Add the negative log p-value column
        db_df$negLogP <- -log10(db_df$Adjusted.P.value)
        
        # Add to results list
        custom_results[[db_name]] <- db_df
      }
      
      # Store the selected pathways for use in network visualization
      selected_tcga_pathways(selected_pathways)
      
      # Store the properly structured results
      if(length(custom_results) > 0) {
        tcga_pathway_selection_state("custom")
        tcga_pathway_results(custom_results)  # Update the main results with just selected pathways
      }
      
      removeModal()
      showNotification(paste(length(selected_rows), "pathways selected for visualization"), type = "message")
      
    } else {
      showNotification("Please select at least one pathway", type = "warning")
    }
  })
  
  observeEvent(input$deg_results_tabs_main, {
    if (input$deg_results_tabs_main == "volcano_panel" && !is.null(deg_data())) {
      # Auto-generate volcano plot when tab is selected
      if (is.null(rv_deg_main$volcano_plot_obj)) {
        # First time - generate automatically
        generate_volcano_plot()
      }
    }
  })
  
  # Add this observer to update button text
  observe({
    if (!is.null(rv_deg_main$volcano_plot_obj)) {
      updateActionButton(session, "generate_volcano_main", label = "Update Volcano Plot")
    } else {
      updateActionButton(session, "generate_volcano_main", label = "Generate Volcano Plot")
    }
  })
  
  generate_volcano_plot <- function() {
    withProgress(message = 'Generating volcano plot...', value = 0, {
      req(deg_data())
      
      incProgress(0.2, detail = "Preparing data")
      
      volcano_data <- deg_data()
      
      # Get current settings with proper defaults
      pvalue_type <- input$pvalue_type_main %||% "adjusted"
      p_val_thresh <- input$p_val_threshold_main %||% 0.05
      log2fc_min_thresh <- input$log2fc_min %||% -1
      log2fc_max_thresh <- input$log2fc_max %||% 1
      
      # Get p-value column info
      pval_info <- get_pvalue_info(pvalue_type)
      p_col <- pval_info$column
      y_axis_title <- pval_info$y_axis_label
      
      incProgress(0.4, detail = "Calculating significance")
      
      # Ensure the p-value column exists
      if (!p_col %in% colnames(volcano_data)) {
        showNotification(paste("Error: Column", p_col, "not found in data"), type = "error")
        return(NULL)
      }
      
      # Convert to data.frame to avoid any Rle issues
      volcano_data <- as.data.frame(volcano_data)
      
      # Ensure numeric columns
      volcano_data[[p_col]] <- as.numeric(volcano_data[[p_col]])
      volcano_data$log2FC <- as.numeric(volcano_data$log2FC)
      
      # Remove any rows with NA values in key columns
      volcano_data <- volcano_data[!is.na(volcano_data[[p_col]]) & !is.na(volcano_data$log2FC), ]
      
      if (nrow(volcano_data) == 0) {
        showNotification("No valid data for volcano plot", type = "error")
        return(NULL)
      }
      
      # Add significance classification
      volcano_data$significance <- "Not Significant"
      volcano_data$significance[volcano_data$log2FC <= log2fc_min_thresh &
                                  volcano_data[[p_col]] <= p_val_thresh] <- "Downregulated"
      volcano_data$significance[volcano_data$log2FC >= log2fc_max_thresh &
                                  volcano_data[[p_col]] <= p_val_thresh] <- "Upregulated"
      
      # Convert to factor with proper ordering
      volcano_data$significance <- factor(volcano_data$significance,
                                          levels = c("Upregulated", "Downregulated", "Not Significant"))
      
      # Calculate y-axis values
      volcano_data$y_val <- -log10(volcano_data[[p_col]])
      
      # Handle infinite values (p-value = 0)
      max_finite_y <- max(volcano_data$y_val[is.finite(volcano_data$y_val)], na.rm = TRUE)
      volcano_data$y_val[is.infinite(volcano_data$y_val)] <- max_finite_y + 1
      volcano_data$y_val[is.na(volcano_data$y_val)] <- 0
      
      incProgress(0.5, detail = "Converting gene symbols...")
      
      if (!"gene_symbol" %in% colnames(volcano_data) || 
          all(is.na(volcano_data$gene_symbol)) || 
          all(volcano_data$gene_symbol == "" | volcano_data$gene_symbol == "-")) {
        
        print("Converting gene IDs to symbols for volcano plot...")
        
        # Convert gene IDs to symbols
        conversion_result <- tryCatch({
          convert_gene_ids_to_symbols_deg(volcano_data$gene_id, input$organism_deg_main)
        }, error = function(e) {
          print(paste("⚠️ Gene conversion failed:", e$message))
          NULL
        })
        
        # Extract symbols from the returned data.frame
        if (!is.null(conversion_result) && is.data.frame(conversion_result) && 
            "gene_symbol" %in% colnames(conversion_result)) {
          
          # Create mapping from original_id to gene_symbol
          gene_mapping <- setNames(conversion_result$gene_symbol, conversion_result$original_id)
          
          # Map the volcano data gene IDs
          volcano_data$gene_symbol <- gene_mapping[volcano_data$gene_id]
          
          # Keep original IDs where conversion failed or returned "-"
          failed_conversion <- is.na(volcano_data$gene_symbol) | 
            volcano_data$gene_symbol == "-" | 
            volcano_data$gene_symbol == ""
          volcano_data$gene_symbol[failed_conversion] <- volcano_data$gene_id[failed_conversion]
          
          successful_conversions <- sum(!failed_conversion)
          print(paste("✅ Converted", successful_conversions, "out of", nrow(volcano_data), 
                      "genes to symbols for volcano plot"))
          
        } else {
          print("ℹ️ Using gene IDs (symbols not available)")
          volcano_data$gene_symbol <- volcano_data$gene_id
        }
      } else {
        print("✅ Gene symbols already present in data")
      }
      
      incProgress(0.6, detail = "Creating plot")
      
      # Create hover text safely
      if ("gene_symbol" %in% colnames(volcano_data)) {
        volcano_data$gene_name <- ifelse(
          is.na(volcano_data$gene_symbol) | volcano_data$gene_symbol == "",
          volcano_data$gene_id,
          volcano_data$gene_symbol
        )
      } else if ("gene_name" %in% colnames(volcano_data)) {
        # gene_name already exists, use it
        volcano_data$gene_name <- volcano_data$gene_name
      } else {
        # No symbols available, use gene_id
        volcano_data$gene_name <- volcano_data$gene_id
      }
      
      # Create hover text with gene symbols
      volcano_data$hover_text <- paste0(
        "<b>Gene: ", volcano_data$gene_symbol, "</b>",  # changed from gene_id to gene_symbol
        "<br>Gene ID: ", volcano_data$gene_id,          # added ID as secondary info
        "<br>Log2FC: ", round(volcano_data$log2FC, 3),
        "<br>", pval_info$label, ": ", signif(volcano_data[[p_col]], 3)
      )
      
      # Color palette
      colors <- c("Upregulated" = "#e74c3c", "Downregulated" = "#3498db", "Not Significant" = "#95a5a6")
      
      
      volcano_plot <- plot_ly(
        data = volcano_data,
        x = ~log2FC,
        y = ~y_val,
        type = "scatter",
        mode = "markers",  # FIXED: Explicitly specify mode
        color = ~significance,
        colors = colors,
        marker = list(size = 6, opacity = 0.7),
        text = ~hover_text,
        hoverinfo = "text",
        source = "volcano_plot"
      ) %>%
        layout(
          title = paste0("Volcano Plot (", pval_info$label, ")"),
          xaxis = list(title = "log2 Fold Change"),
          yaxis = list(title = y_axis_title),
          showlegend = TRUE,
          hovermode = 'closest'
        )
      
      # *** FIXED: Add threshold lines using shapes (more reliable) ***
      shapes <- list()
      
      # Vertical lines for fold change thresholds
      if (is.finite(log2fc_min_thresh)) {
        shapes[[length(shapes) + 1]] <- list(
          type = "line",
          x0 = log2fc_min_thresh, x1 = log2fc_min_thresh,
          y0 = 0, y1 = 1,
          yref = "paper",
          line = list(color = "gray", dash = "dash", width = 1)
        )
      }
      
      if (is.finite(log2fc_max_thresh)) {
        shapes[[length(shapes) + 1]] <- list(
          type = "line",
          x0 = log2fc_max_thresh, x1 = log2fc_max_thresh,
          y0 = 0, y1 = 1,
          yref = "paper",
          line = list(color = "gray", dash = "dash", width = 1)
        )
      }
      
      # Horizontal line for p-value threshold
      if (is.finite(p_val_thresh) && p_val_thresh > 0) {
        p_line_y <- -log10(p_val_thresh)
        shapes[[length(shapes) + 1]] <- list(
          type = "line",
          x0 = 0, x1 = 1,
          xref = "paper",
          y0 = p_line_y, y1 = p_line_y,
          line = list(color = "gray", dash = "dash", width = 1)
        )
      }
      
      # Add shapes to layout
      if (length(shapes) > 0) {
        volcano_plot <- volcano_plot %>%
          layout(shapes = shapes)
      }
      
      # Store the plot and data
      rv_deg_main$volcano_plot_obj <- volcano_plot
      rv_deg_main$volcano_data <- volcano_data
      rv_deg_main$volcano_y_axis_title <- y_axis_title
      
      incProgress(1, detail = "Complete")
      showNotification("Volcano plot generated successfully!", type = "message")
    })
  }
  
  # Server code for generating the volcano plot
  # This should replace your existing observeEvent(input$volcano_plot, { ... })
  observeEvent(input$generate_volcano_main, {
    generate_volcano_plot()
  })
  
  
  output$volcano_plot_main <- renderPlotly({
    # No req(rv_deg_main$volcano_plot_obj) here, so it renders NULL initially
    p <- rv_deg_main$volcano_plot_obj
    if (is.null(p)) return(NULL)
    if (isTRUE(input$volcano_symmetric_x) && !is.null(rv_deg_main$volcano_data) &&
        "log2FC" %in% colnames(rv_deg_main$volcano_data)) {
      xmax <- tryCatch(max(abs(rv_deg_main$volcano_data$log2FC), na.rm = TRUE) * 1.05,
                       error = function(e) 1, warning = function(w) 1)
      if (!is.finite(xmax) || xmax == 0) xmax <- 1
      p <- p %>% plotly::layout(xaxis = list(title = "log2 Fold Change", range = c(-xmax, xmax)))
    }
    p # Render the (possibly relaid-out) plotly object
  })
  
  # Auto-update volcano plot when parameters change (optional feature)
  observe({
    # Only auto-update if plot already exists and user is on volcano tab
    if (!is.null(rv_deg_main$volcano_plot_obj) &&
        !is.null(input$deg_results_tabs_main) &&
        input$deg_results_tabs_main == "volcano_panel") {
      
      # Add a small delay to prevent too frequent updates
      invalidateLater(1000, session)
      
      # Check if parameters have changed (you can make this more sophisticated)
      current_params <- list(
        input$pvalue_type_main,
        input$p_val_threshold_main,
        input$log2fc_min_main,
        input$log2fc_max_main
      )
      
      # Store and compare parameters (implement this if you want auto-updates)
      # For now, manual update via button is more user-friendly
    }
  })
  
  output$download_volcano_main <- downloadHandler(
    filename = function() {
      pvalue_type <- input$pvalue_type_main %||% "adjusted"
      paste0("volcano_plot_labeled_", pvalue_type, "_", Sys.Date(), ".png")
    },
    content = function(file) {
      load_export_packages()
      req(rv_deg_main$volcano_data)
      
      withProgress(message = 'Preparing high-resolution volcano plot...', value = 0, {
        
        tryCatch({
          incProgress(0.1, detail = "Loading required packages...")
          
          # Load required libraries
          if (!requireNamespace("ggplot2", quietly = TRUE)) {
            stop("ggplot2 package required for download")
          }
          if (!requireNamespace("ggrepel", quietly = TRUE)) {
            showNotification("Installing ggrepel package for gene labels...", duration = 5)
            install.packages("ggrepel", dependencies = TRUE)
          }
          
          library(ggplot2)
          library(ggrepel)
          library(dplyr)
          
          incProgress(0.2, detail = "Preparing plot data...")
          
          # Get plot data and parameters
          plot_data <- rv_deg_main$volcano_data
          pvalue_type <- input$pvalue_type_main %||% "adjusted"
          pval_info <- get_pvalue_info(pvalue_type)
          p_col <- pval_info$column
          
          # Get thresholds
          p_val_thresh <- input$p_val_threshold_main %||% 0.05
          log2fc_min_thresh <- input$log2fc_min %||% -1
          log2fc_max_thresh <- input$log2fc_max %||% 1
          
          # Ensure we have gene symbols
          if (!"gene_symbol" %in% colnames(plot_data)) {
            plot_data$gene_symbol <- plot_data$gene_id
          }
          
          incProgress(0.3, detail = "Selecting genes to label...")
          
          # ========================================================================
          # LABEL SELECTION STRATEGY - Label top genes by multiple criteria
          # ========================================================================
          
          genes_to_label <- character(0)
          
          # 1. Top 10 most significant UPREGULATED genes
          top_significant_up <- plot_data %>%
            dplyr::filter(significance == "Upregulated") %>%
            dplyr::arrange(!!sym(p_col)) %>%
            dplyr::slice_head(n = 10) %>%
            pull(gene_symbol)
          
          genes_to_label <- c(genes_to_label, top_significant_up)
          
          # 2. Top 10 most significant DOWNREGULATED genes
          top_significant_down <- plot_data %>%
            dplyr::filter(significance == "Downregulated") %>%
            dplyr::arrange(!!sym(p_col)) %>%
            dplyr::slice_head(n = 10) %>%
            pull(gene_symbol)
          
          genes_to_label <- c(genes_to_label, top_significant_down)
          
          # 3. Top 5 highest fold change (upregulated only)
          top_up_fc <- plot_data %>%
            dplyr::filter(significance == "Upregulated") %>%
            dplyr::arrange(desc(log2FC)) %>%
            dplyr::slice_head(n = 5) %>%
            pull(gene_symbol)
          
          genes_to_label <- c(genes_to_label, top_up_fc)
          
          # 4. Top 5 lowest fold change (downregulated only)
          top_down_fc <- plot_data %>%
            dplyr::filter(significance == "Downregulated") %>%
            dplyr::arrange(log2FC) %>%
            dplyr::slice_head(n = 5) %>%
            pull(gene_symbol)
          
          genes_to_label <- c(genes_to_label, top_down_fc)
          
          # Remove duplicates
          genes_to_label <- unique(genes_to_label)
          
          # Create label column - ONLY label significant genes
          plot_data$label_gene <- ifelse(plot_data$gene_symbol %in% genes_to_label & 
                                           plot_data$significance != "Not Significant", 
                                         plot_data$gene_symbol, 
                                         "")
          
          n_labeled <- sum(plot_data$label_gene != "")
          
          print(paste("📊 Labeling", n_labeled, "SIGNIFICANT genes on volcano plot"))
          
          incProgress(0.5, detail = paste("Creating plot with", n_labeled, "labeled genes..."))
          
          # ========================================================================
          # CREATE HIGH-QUALITY GGPLOT
          # ========================================================================
          
          # Define colors
          colors <- c(
            "Upregulated" = "#e74c3c",
            "Downregulated" = "#3498db",
            "Not Significant" = "#95a5a6"
          )
          
          # Create base plot
          p <- ggplot(plot_data, aes(x = log2FC, y = y_val, color = significance)) +
            geom_point(alpha = 0.6, size = 2) +
            scale_color_manual(values = colors) +
            
            # Add threshold lines
            geom_vline(xintercept = c(log2fc_min_thresh, log2fc_max_thresh), 
                       linetype = "dashed", color = "gray50", size = 0.5) +
            geom_hline(yintercept = -log10(p_val_thresh), 
                       linetype = "dashed", color = "gray50", size = 0.5) +
            
            labs(
              title = paste0("Volcano Plot (", pval_info$label, ")"),
              subtitle = paste0(n_labeled, " genes labeled | Thresholds: |log2FC| > ", 
                                abs(log2fc_max_thresh), ", ", pval_info$label, " < ", p_val_thresh),
              x = "log2 Fold Change",
              y = pval_info$y_axis_label,
              color = "Significance"
            ) +
            
            theme_minimal(base_size = 14) +
            theme(
              plot.title = element_text(hjust = 0.5, size = 18, face = "bold", margin = margin(b = 5)),
              plot.subtitle = element_text(hjust = 0.5, size = 12, color = "gray40", margin = margin(b = 15)),
              axis.title = element_text(size = 14, face = "bold"),
              axis.text = element_text(size = 12),
              legend.title = element_text(size = 13, face = "bold"),
              legend.text = element_text(size = 11),
              legend.position = "bottom",
              legend.box = "horizontal",
              panel.grid.minor = element_blank(),
              panel.grid.major = element_line(color = "gray90", size = 0.3),
              panel.border = element_rect(color = "gray80", fill = NA, size = 1),
              plot.background = element_rect(fill = "white", color = NA),
              plot.margin = margin(20, 20, 20, 20)
            )
          
          incProgress(0.7, detail = "Adding gene labels...")
          
          # Add gene labels with ggrepel
          if (n_labeled > 0) {
            labeled_data <- plot_data[plot_data$label_gene != "", ]
            
            p <- p +
              geom_point(
                data = labeled_data,
                aes(x = log2FC, y = y_val),
                size = 3,
                alpha = 1,
                shape = 21,
                stroke = 1.5,
                fill = NA
              ) +
              geom_text_repel(
                data = labeled_data,
                aes(label = label_gene),
                size = 3.5,
                fontface = "bold",
                color = "black",
                bg.color = "white",
                bg.r = 0.15,
                box.padding = 0.5,
                point.padding = 0.3,
                force = 3,
                force_pull = 0.5,
                max.overlaps = Inf,
                min.segment.length = 0,
                segment.color = "gray30",
                segment.size = 0.4,
                segment.alpha = 0.6,
                arrow = arrow(length = unit(0.01, "npc"), type = "closed"),
                seed = 42
              )
          }
          
          incProgress(0.8, detail = "Rendering high-resolution image...")
          
          # Calculate dynamic dimensions
          width_in <- 12
          height_in <- 10
          
          # Save as high-resolution PNG
          ggsave(
            filename = file,
            plot = p,
            width = width_in,
            height = height_in,
            units = "in",
            dpi = 300,
            bg = "white"
          )
          
          incProgress(1, detail = "Complete!")
          
          print("✅ High-resolution volcano plot with gene labels saved successfully")
          
          showNotification(
            paste0("Volcano plot saved with ", n_labeled, " labeled genes!"),
            type = "message",
            duration = 3
          )
          
        }, error = function(e) {
          print(paste("ERROR saving volcano plot:", e$message))
          showNotification(
            paste("Error saving volcano plot:", e$message),
            type = "error",
            duration = 10
          )
          
          # Create a simple fallback plot
          tryCatch({
            plot_data <- rv_deg_main$volcano_data
            png(file, width = 12, height = 10, units = "in", res = 150, bg = "white")
            plot(plot_data$log2FC, plot_data$y_val, 
                 col = ifelse(plot_data$significance == "Upregulated", "red",
                              ifelse(plot_data$significance == "Downregulated", "blue", "gray")),
                 pch = 16, cex = 0.8,
                 xlab = "log2 Fold Change",
                 ylab = "-log10(p-value)",
                 main = "Volcano Plot (fallback version)")
            dev.off()
          }, error = function(e2) {
            print(paste("Fallback plot also failed:", e2$message))
          })
        })
      })
    }
  )
  
  # Observer to populate the selectizeInput
  # NOTE: gating on gene_selection_method_main was removed (Feature 3) so manual
  # selection is available regardless of the selected method.
  observe({
    req(deg_data())
    
    if (isTRUE(input$manual_gene_selection)) {
      
      # Get current DEG data
      deg_results <- deg_data()
      
      # Get thresholds
      pvalue_type <- input$pvalue_type_main
      p_val_thresh <- input$p_val_threshold_main
      log2fc_min_thresh <- input$log2fc_min
      log2fc_max_thresh <- input$log2fc_max
      
      pval_info <- get_pvalue_info(pvalue_type)
      p_col <- pval_info$column
      
      # Apply BOTH p-value AND fold-change filters (same as up/down tables)
      direction_filter <- input$deg_direction_filter %||% "both"
      
      filtered_degs <- switch(
        direction_filter,
        "both" = {
          # Get genes that pass BOTH p-value AND fold-change thresholds
          deg_results %>%
            dplyr::filter(
              !!sym(p_col) < p_val_thresh,
              (log2FC <= log2fc_min_thresh | log2FC >= log2fc_max_thresh)
            )
        },
        "up" = {
          # Only upregulated genes (same as up table)
          deg_results %>%
            dplyr::filter(
              !!sym(p_col) < p_val_thresh,
              log2FC >= log2fc_max_thresh
            )
        },
        "down" = {
          # Only downregulated genes (same as down table)
          deg_results %>%
            dplyr::filter(
              !!sym(p_col) < p_val_thresh,
              log2FC <= log2fc_min_thresh
            )
        }
      )
      
      print(paste("Manual selection: Found", nrow(filtered_degs), "genes matching", direction_filter, "filter"))
      
      if (nrow(filtered_degs) == 0) {
        updateSelectizeInput(
          session, 
          "selected_gene_ids", 
          choices = c("No genes match current filters" = ""),
          server = TRUE
        )
        return(NULL)
      }
      
      # Convert gene IDs to symbols if not already present
      if (!"gene_symbol" %in% colnames(filtered_degs) || 
          all(is.na(filtered_degs$gene_symbol)) || 
          all(filtered_degs$gene_symbol == "" | filtered_degs$gene_symbol == "-")) {
        
        print("Converting gene IDs to symbols for dropdown...")
        conversion_result <- tryCatch({
          convert_gene_ids_to_symbols_deg(filtered_degs$gene_id, input$organism_deg_main)
        }, error = function(e) {
          print(paste("Conversion failed:", e$message))
          NULL
        })
        
        if (!is.null(conversion_result) && is.data.frame(conversion_result)) {
          gene_mapping <- setNames(conversion_result$gene_symbol, conversion_result$original_id)
          filtered_degs$gene_symbol <- gene_mapping[filtered_degs$gene_id]
          
          failed <- is.na(filtered_degs$gene_symbol) | filtered_degs$gene_symbol == "-"
          filtered_degs$gene_symbol[failed] <- filtered_degs$gene_id[failed]
        } else {
          filtered_degs$gene_symbol <- filtered_degs$gene_id
        }
      }
      
      # Sort by significance
      filtered_degs <- filtered_degs %>%
        dplyr::arrange(!!sym(p_col))
      
      # Create nice labels with gene names
      choices_labels <- paste0(
        filtered_degs$gene_symbol,
        " (FC: ", round(filtered_degs$log2FC, 2),
        ", p: ", format(filtered_degs[[p_col]], digits = 3, scientific = TRUE),
        ")"
      )
      
      choices <- setNames(filtered_degs$gene_id, choices_labels)
      
      print(paste("Updating selectizeInput with", length(choices), "filtered gene options"))
      
      updateSelectizeInput(
        session, 
        "selected_gene_ids", 
        choices = choices,
        selected = character(0),
        server = TRUE
      )
    }
  })
  
  # ============================================================
  # FEATURE 2: Bulk paste-list parser for the heatmap gene picker
  # ============================================================
  observeEvent(input$heatmap_parse_genes, {
    raw <- input$heatmap_gene_paste
    if (is.null(raw) || nchar(trimws(raw)) == 0) {
      showNotification("Paste a gene list first.", type = "warning", duration = 4)
      return()
    }
    # Auto-detect separator: newline, comma, semicolon, tab, or whitespace
    tokens <- unlist(strsplit(raw, "[\n,;\t[:space:]]+", perl = TRUE))
    tokens <- toupper(trimws(tokens))
    tokens <- tokens[nchar(tokens) > 0]
    tokens <- unique(tokens)
    
    if (length(tokens) == 0) {
      showNotification("No valid gene tokens found.", type = "warning", duration = 4)
      return()
    }
    
    # Get the universe of available genes from the current DEG results
    deg_df <- tryCatch(deg_data(), error = function(e) NULL)
    if (is.null(deg_df) || nrow(deg_df) == 0) {
      showNotification("No DEG results available yet. Run DEG analysis first.",
                       type = "warning", duration = 6)
      return()
    }
    
    # Convert IDs to symbols on the fly so paste-list users can use symbols
    if (!"gene_symbol" %in% colnames(deg_df) ||
        all(is.na(deg_df$gene_symbol)) ||
        all(deg_df$gene_symbol == "" | deg_df$gene_symbol == "-")) {
      conv <- tryCatch(
        convert_gene_ids_to_symbols_deg(deg_df$gene_id, input$organism_deg_main),
        error = function(e) NULL
      )
      if (!is.null(conv) && is.data.frame(conv) && "gene_symbol" %in% colnames(conv)) {
        mapping <- setNames(conv$gene_symbol, conv$original_id)
        deg_df$gene_symbol <- mapping[deg_df$gene_id]
        bad <- is.na(deg_df$gene_symbol) | deg_df$gene_symbol == "-" | deg_df$gene_symbol == ""
        deg_df$gene_symbol[bad] <- deg_df$gene_id[bad]
      } else {
        deg_df$gene_symbol <- deg_df$gene_id
      }
    }
    
    # Build a symbol->gene_id lookup (uppercased keys for case-insensitive match)
    sym_keys <- toupper(as.character(deg_df$gene_symbol))
    id_keys  <- toupper(as.character(deg_df$gene_id))
    name_keys <- if ("gene_name" %in% colnames(deg_df)) toupper(as.character(deg_df$gene_name)) else character(0)
    
    sym_to_id  <- setNames(deg_df$gene_id, sym_keys)
    id_to_id   <- setNames(deg_df$gene_id, id_keys)
    name_to_id <- if (length(name_keys) > 0) setNames(deg_df$gene_id, name_keys) else NULL
    
    matched_ids <- character(0)
    unmatched   <- character(0)
    for (tok in tokens) {
      hit <- NA_character_
      if (tok %in% names(sym_to_id))  hit <- sym_to_id[[tok]]
      else if (tok %in% names(id_to_id)) hit <- id_to_id[[tok]]
      else if (!is.null(name_to_id) && tok %in% names(name_to_id)) hit <- name_to_id[[tok]]
      if (is.na(hit)) {
        unmatched <- c(unmatched, tok)
      } else {
        matched_ids <- c(matched_ids, hit)
      }
    }
    matched_ids <- unique(matched_ids)
    
    # Merge with existing selection
    existing <- input$selected_gene_ids
    if (is.null(existing)) existing <- character(0)
    combined <- unique(c(existing, matched_ids))
    
    # Build choice labels (symbol shown, gene_id is the value)
    label_lookup <- setNames(as.character(deg_df$gene_symbol), as.character(deg_df$gene_id))
    combined_labels <- ifelse(is.na(label_lookup[combined]) | label_lookup[combined] == "",
                              combined, label_lookup[combined])
    choices_named <- setNames(combined, combined_labels)
    
    updateSelectizeInput(session, "selected_gene_ids",
                         choices  = choices_named,
                         selected = combined,
                         server   = TRUE)
    
    # Make sure manual-selection toggle is on so the picker is visible/used
    updateCheckboxInput(session, "manual_gene_selection", value = TRUE)
    
    msg <- paste0("Added ", length(matched_ids), " of ", length(tokens), " gene(s).")
    if (length(unmatched) > 0) {
      n_show <- min(length(unmatched), 8)
      msg <- paste0(msg, " Not found: ",
                    paste(head(unmatched, n_show), collapse = ", "),
                    if (length(unmatched) > n_show) paste0(" (+", length(unmatched) - n_show, " more)") else "")
    }
    showNotification(msg,
                     type     = if (length(matched_ids) > 0) "message" else "warning",
                     duration = 8)
  })
  
  # Reactive expression for heatmap data preparation
  heatmap_data <- eventReactive(input$generate_heatmap_main, {
    req(deg_data(), rv_deg_main$raw_counts)
    
    withProgress(message = 'Generating heatmap data...', value = 0, {
      tryCatch({
        incProgress(0.1, detail = "Selecting top genes...")
        
        # Get current settings
        pvalue_type <- input$pvalue_type_main
        p_val_thresh <- input$p_val_threshold_main
        log2fc_min_thresh <- input$log2fc_min
        log2fc_max_thresh <- input$log2fc_max
        
        gene_selection_method <- input$gene_selection_method_main
        top_n <- as.numeric(input$heatmap_gene_count_main)
        
        # ✅ FIX #1: Use deg_data() which is ALREADY filtered!
        deg_results <- deg_data()  # This is already filtered by your thresholds
        
        print(paste("📊 DEG data for heatmap:", nrow(deg_results), "genes (already filtered)"))
        
        pval_info <- get_pvalue_info(pvalue_type)
        p_col <- pval_info$column
        
        # Feature 3: Universal manual override. If manual selection is enabled
        # and the user has selected genes, use those regardless of gene_selection_method.
        manual_override <- isTRUE(input$manual_gene_selection) &&
                           !is.null(input$selected_gene_ids) &&
                           length(input$selected_gene_ids) > 0
        
        # ✅ FIX #2: Select genes WITHOUT additional filtering
        # deg_data() is already filtered, just sort and take top N
        selected_genes <- if (manual_override) {
          print(paste("   [universal manual override] Using",
                      length(input$selected_gene_ids), "manually selected genes"))
          input$selected_gene_ids
        } else switch(
          gene_selection_method,
          "pvalue" = {
            # Sort by p-value, then by absolute fold change
            deg_results %>%
              dplyr::arrange(!!sym(p_col), -abs(log2FC)) %>%
              dplyr::slice_head(n = min(top_n, nrow(deg_results))) %>%  # Don't exceed available genes
              pull(gene_id)
          },
          "foldchange" = {
            # Sort by absolute fold change (no additional filtering!)
            deg_results %>%
              dplyr::arrange(-abs(log2FC)) %>%
              dplyr::slice_head(n = min(top_n, nrow(deg_results))) %>%
              pull(gene_id)
          },
          "current_degs" = {
            # Check if manual selection is enabled
            if (isTRUE(input$manual_gene_selection) && !is.null(input$selected_gene_ids) && 
                length(input$selected_gene_ids) > 0) {
              
              print(paste("   Using", length(input$selected_gene_ids), "manually selected genes"))
              input$selected_gene_ids
              
            } else {
              # Automatic selection based on current thresholds
              direction_filter <- input$deg_direction_filter %||% "both"
              
              filtered_genes <- switch(
                direction_filter,
                "both" = {
                  up_genes <- deg_results %>%
                    dplyr::filter(log2FC >= log2fc_max_thresh) %>%
                    dplyr::arrange(!!sym(p_col)) %>%  # Sort by p-value (best first)
                    pull(gene_id)
                  
                  down_genes <- deg_results %>%
                    dplyr::filter(log2FC <= log2fc_min_thresh) %>%
                    dplyr::arrange(!!sym(p_col)) %>%  # Sort by p-value (best first)
                    pull(gene_id)
                  
                  # Take top N/2 from each direction
                  half_n <- ceiling(top_n / 2)
                  selected_up <- head(up_genes, min(half_n, length(up_genes)))
                  selected_down <- head(down_genes, min(half_n, length(down_genes)))
                  
                  print(paste("   Current DEGs - Up:", length(selected_up), "Down:", length(selected_down)))
                  c(selected_up, selected_down)
                },
                "up" = {
                  deg_results %>%
                    dplyr::filter(log2FC >= log2fc_max_thresh) %>%
                    dplyr::arrange(!!sym(p_col)) %>%
                    dplyr::slice_head(n = min(top_n, n())) %>%
                    pull(gene_id)
                },
                "down" = {
                  deg_results %>%
                    dplyr::filter(log2FC <= log2fc_min_thresh) %>%
                    dplyr::arrange(!!sym(p_col)) %>%
                    dplyr::slice_head(n = min(top_n, n())) %>%
                    pull(gene_id)
                }
              )
              
              print(paste("   Selected", length(filtered_genes), "genes by", direction_filter, "regulation"))
              filtered_genes
            }
          }
        )
        
        print(paste("✅ Selected", length(selected_genes), "genes for heatmap"))
        
        if (length(selected_genes) == 0) {
          showNotification(
            paste("No genes available for heatmap. Your filtered DEG results contain", 
                  nrow(deg_results), "genes."),
            type = "warning"
          )
          return(NULL)
        }
        
        incProgress(0.3, detail = "Preparing expression matrix...")
        
        # ✅ FIX: Use CACHED normalized data instead of re-normalizing!
        if (!is.null(rv_deg_main$normalized_counts)) {
          normalized_expression <- rv_deg_main$normalized_counts
          print("✅ Using cached normalized expression data")
        } else {
          # Fallback: normalize only if not cached (should rarely happen)
          print("⚠️ No cached normalized data - normalizing now (this may be slow)...")
          normalized_expression <- normalizeData(rv_deg_main$raw_counts, input$normalization_method_main)
        }
        
        available_genes <- intersect(selected_genes, rownames(normalized_expression))
        
        if (length(available_genes) == 0) {
          showNotification("None of the selected genes found in expression matrix.", type = "error")
          return(NULL)
        }
        
        print(paste("✅ Found", length(available_genes), "genes in expression matrix"))
        
        # Extract ONLY the selected genes (much smaller matrix!)
        matrix_data <- as.matrix(normalized_expression[available_genes, , drop = FALSE])
        
        if (!is.null(input$show_all_groups_heatmap) && !input$show_all_groups_heatmap) {
          # User wants ONLY the two compared groups
          if (!is.null(rv_deg_main$active_deg_comparison)) {
            # Extract the two groups from active comparison (format: "Group1 vs Group2")
            comp_groups <- strsplit(rv_deg_main$active_deg_comparison, " vs ")[[1]]
            
            # Filter samples belonging to these two groups
            samples_to_keep <- rv_deg_main$sample_groups$sample[
              rv_deg_main$sample_groups$group %in% comp_groups
            ]
            
            # Keep only these samples in matrix
            matrix_data <- matrix_data[, intersect(colnames(matrix_data), samples_to_keep), drop = FALSE]
            
            print(paste("✅ Filtered to", ncol(matrix_data), "samples from groups:", 
                        paste(comp_groups, collapse = " & ")))
          }
        }
        
        # ========================================================================
        # ✅ FIX #3: USE USER-CONFIRMED GROUPS (not auto-detection!)
        # ========================================================================
        incProgress(0.5, detail = "Extracting sample groups...")
        
        col_names <- colnames(matrix_data)
        
        # Check if we have user-confirmed groups
        if (!is.null(rv_deg_main$sample_groups)) {
          print("✅ Using USER-CONFIRMED groups for heatmap")
          
          # Create a mapping of sample names to groups
          sample_to_group <- setNames(
            rv_deg_main$sample_groups$group,
            rv_deg_main$sample_groups$sample
          )
          
          # Map column names to groups
          groups <- sample_to_group[col_names]
          
          # Handle any unmatched samples
          if (any(is.na(groups))) {
            print("⚠️ Warning: Some samples not found in group mapping")
            print(paste("Unmatched samples:", paste(col_names[is.na(groups)], collapse = ", ")))
            
            # Fallback to auto-detection for unmatched samples
            groups[is.na(groups)] <- sub(".*_", "", col_names[is.na(groups)])
          }
          
          print(paste("   Sample groups:", paste(unique(groups), collapse = ", ")))
          
          # ✅ FIX #4: Extract batch information from batch detection results
          batch_info <- NULL
          batch_col <- NULL
          
          # First, check if batch detection identified a batch column
          if (!is.null(rv_deg_main$batch_detection_results) && 
              !is.null(rv_deg_main$batch_detection_results$recommended_batch)) {
            batch_col <- rv_deg_main$batch_detection_results$recommended_batch
            print(paste("🔍 Using detected batch column:", batch_col))
          } else if ("batch" %in% colnames(rv_deg_main$sample_groups)) {
            # Fallback: use literal "batch" column if it exists
            batch_col <- "batch"
            print("🔍 Using 'batch' column from metadata")
          }
          
          # Extract batch info if we have a batch column
          if (!is.null(batch_col) && batch_col %in% colnames(rv_deg_main$sample_groups)) {
            sample_to_batch <- setNames(
              rv_deg_main$sample_groups[[batch_col]],
              rv_deg_main$sample_groups$sample
            )
            batch_info <- sample_to_batch[col_names]
            
            print(paste("✅ Batch information available:", length(unique(batch_info)), "batches"))
            print(paste("   Batch column:", batch_col))
            print(paste("   Batch levels:", paste(unique(batch_info), collapse = ", ")))
          } else {
            print("ℹ️ No batch information available")
          }
          
        } else {
          # Fallback: auto-detect from sample names
          print("⚠️ No user-confirmed groups - using auto-detection (not recommended)")
          groups <- sub(".*_", "", col_names)
          batch_info <- NULL
        }
        
        # ========================================================================
        # ✅ FIX #5: Map gene IDs to gene symbols for Y-axis labels
        # ========================================================================
        incProgress(0.7, detail = "Mapping gene symbols...")
        
        genes_to_convert <- rownames(matrix_data)
        
        print(paste("DEBUG: Attempting to convert", length(genes_to_convert), "gene IDs"))
        
        # Call conversion function - it returns a data.frame
        conversion_result <- tryCatch({
          convert_gene_ids_to_symbols_deg(genes_to_convert, input$organism_deg_main)
        }, error = function(e) {
          print(paste("⚠️ Gene conversion failed:", e$message))
          NULL
        })
        
        # Extract symbols from the returned data.frame
        if (!is.null(conversion_result) && is.data.frame(conversion_result) && 
            "gene_symbol" %in% colnames(conversion_result)) {
          
          # Create mapping from original_id to gene_symbol
          gene_mapping <- setNames(conversion_result$gene_symbol, conversion_result$original_id)
          
          # Map the matrix rownames
          new_rownames <- gene_mapping[rownames(matrix_data)]
          
          # Keep original IDs where conversion failed or returned "-"
          failed_conversion <- is.na(new_rownames) | new_rownames == "-" | new_rownames == ""
          new_rownames[failed_conversion] <- rownames(matrix_data)[failed_conversion]
          
          rownames(matrix_data) <- new_rownames
          
          successful_conversions <- sum(!failed_conversion)
          print(paste("✅ Converted", successful_conversions, "out of", length(genes_to_convert), "genes to symbols"))
          print(paste("   Sample symbols:", paste(head(new_rownames, 3), collapse = ", ")))
          
        } else {
          print("ℹ️ Heatmap using gene IDs (symbols not available)")
        }
        
        incProgress(1, detail = "Complete")
        
        # ========================================================================
        # RETURN DATA WITH BATCH INFO AND GENE MAPPING
        # ========================================================================
        return(list(
          matrix = matrix_data,  # Already has gene symbols as rownames if available
          groups = groups,
          batch = batch_info,
          selected_genes = available_genes,
          pvalue_type = pvalue_type,
          pvalue_threshold = p_val_thresh,
          deg_data = deg_results  # ADD THIS - pass the deg_results for use in rendering
        ))
        
      }, error = function(e) {
        showNotification(paste("Error generating heatmap:", e$message), type = "error")
        print(paste("ERROR:", e$message))
        return(NULL)
      })
    })
  })
  
  output$heatmap_plot_main <- renderPlot({
    heatmap_dat <- heatmap_data()
    req(heatmap_dat)
    
    print("🎨 Rendering ComplexHeatmap plot...")
    
    tryCatch({
      library(ComplexHeatmap)
      library(circlize)
      
      matrix_data <- heatmap_dat$matrix
      
      # Check for empty or invalid matrix
      if (is.null(matrix_data) || nrow(matrix_data) < 2 || ncol(matrix_data) < 2) {
        plot(1, type = "n", axes = FALSE, xlab = "", ylab = "")
        title("Not enough data for heatmap (min 2x2 matrix required).")
        return()
      }
      
      print(paste("📊 Matrix dimensions:", nrow(matrix_data), "genes x", ncol(matrix_data), "samples"))
      
      # Feature 4: Orientation toggle. "flipped" -> samples on rows, genes on cols.
      orientation <- input$heatmap_orientation_main %||% "standard"
      flipped <- isTRUE(orientation == "flipped")
      
      # Capture clustering choices and swap them when flipped so users still
      # get “row clustering”/“column clustering” behavior matching their mental model.
      cluster_rows_choice    <- input$enable_row_clustering_main %||% TRUE
      cluster_columns_choice <- input$enable_col_clustering_main %||% TRUE
      if (flipped) {
        tmp <- cluster_rows_choice
        cluster_rows_choice <- cluster_columns_choice
        cluster_columns_choice <- tmp
      }
      
      # Clustering method
      clustering_method <- input$heatmap_clustering_main %||% "ward.D2"
      
      # ✅ CREATE COLUMN ANNOTATION WITH BATCH INFO
      annotation_df <- data.frame(
        Group = heatmap_dat$groups,
        row.names = colnames(matrix_data)
      )
      
      # Add batch if available
      if (!is.null(heatmap_dat$batch)) {
        annotation_df$Batch <- heatmap_dat$batch
        print("✅ Adding batch annotation to heatmap")
      }
      
      # Define colors for groups
      group_levels <- unique(as.character(heatmap_dat$groups))
      n_groups <- length(group_levels)
      
      group_palette <- RColorBrewer::brewer.pal(max(3, min(n_groups, 9)), "Set1")[1:n_groups]
      group_colors <- setNames(group_palette, group_levels)
      
      # Define colors for batches if present
      annotation_colors <- list(Group = group_colors)
      
      if (!is.null(heatmap_dat$batch)) {
        batch_levels <- unique(as.character(heatmap_dat$batch))
        n_batches <- length(batch_levels)
        
        batch_palette <- RColorBrewer::brewer.pal(max(3, min(n_batches, 8)), "Set2")[1:n_batches]
        batch_colors <- setNames(batch_palette, batch_levels)
        
        annotation_colors$Batch <- batch_colors
      }
      
      # Create annotation
      legend_params <- list(Group = list(title = "Group"))
      if (!is.null(heatmap_dat$batch)) {
        legend_params$Batch <- list(title = "Batch")
      }
      
      column_ha <- HeatmapAnnotation(
        df = annotation_df,
        col = annotation_colors,
        annotation_name_side = "left",
        annotation_legend_param = legend_params
      )
      
      # ✅ Z-SCORE SCALING - Scale each gene (row) independently
      # This makes patterns more visible by showing relative changes
      matrix_data <- t(scale(t(matrix_data)))
      
      # Handle any NA/NaN/Inf values that might result from scaling
      matrix_data[is.na(matrix_data)] <- 0
      matrix_data[is.infinite(matrix_data)] <- 0
      
      # Define color scale for Z-scores
      # Z-scores typically range from -3 to +3, but we cap at -2 to +2 for better visualization
      col_fun <- colorRamp2(
        c(-2, 0, 2),
        c("blue", "white", "red")
      )
      
      # Feature 4: Build orientation-aware annotation + matrix.
      # In "standard" view: rows=genes, cols=samples, group annotation on top.
      # In "flipped"  view: rows=samples, cols=genes, group annotation on left.
      if (flipped) {
        matrix_data_oriented <- t(matrix_data)
        row_ha_flipped <- rowAnnotation(
          df = annotation_df,
          col = annotation_colors,
          annotation_name_side = "top",
          annotation_legend_param = legend_params
        )
        top_anno_arg   <- NULL
        left_anno_arg  <- row_ha_flipped
        row_split_arg  <- annotation_df$Group
        col_split_arg  <- NULL
        title_text     <- paste("Heatmap of Top", ncol(matrix_data_oriented), "DEGs (flipped)")
      } else {
        matrix_data_oriented <- matrix_data
        top_anno_arg   <- column_ha
        left_anno_arg  <- NULL
        row_split_arg  <- NULL
        col_split_arg  <- annotation_df$Group
        title_text     <- paste("Heatmap of Top", nrow(matrix_data_oriented), "DEGs")
      }
      
      # Create heatmap
      ht <- Heatmap(
        matrix_data_oriented,
        name = "Z-score",  # ✅ Changed from "Expression"
        col = col_fun,
        top_annotation = top_anno_arg,
        left_annotation = left_anno_arg,
        cluster_rows = cluster_rows_choice,
        
        # --- KEY CHANGES ---
        cluster_columns = cluster_columns_choice,
        row_split = row_split_arg,
        column_split = col_split_arg,
        
        # Row settings
        show_row_names = nrow(matrix_data_oriented) <= 50,
        row_names_gp = gpar(fontsize = max(6, min(10, 300 / nrow(matrix_data_oriented)))),
        row_dend_width = unit(2, "cm"),
        
        # Column settings
        show_column_names = TRUE,
        column_names_gp = gpar(fontsize = 8),
        column_dend_height = unit(2, "cm"),
        
        # Title
        column_title = title_text,
        column_title_gp = gpar(fontsize = 14, fontface = "bold"),
        
        # Legend
        heatmap_legend_param = list(
          title = "Expression\n(Z-score)",  # ✅ Updated legend title
          direction = "vertical",
          legend_height = unit(4, "cm")
        )
      )
      
      # Draw the heatmap
      draw(ht, heatmap_legend_side = "right", annotation_legend_side = "right")
      
      print("✅ Heatmap rendered successfully")
      
    }, error = function(e) {
      showNotification(paste("Error rendering heatmap:", e$message), type = "error")
      print(paste("ERROR in heatmap rendering:", e$message))
      plot(1, type = "n", axes = FALSE, xlab = "", ylab = "")
      title(paste("Error generating heatmap:\n", e$message))
    })
  }, height = 700)
  
