    content = function(file) {
      load_export_packages()
      # Create workbook
      wb <- openxlsx::createWorkbook()
      
      # Add styling
      hs <- openxlsx::createStyle(textDecoration = "BOLD", fontSize = 12)
      
      # Basic Information Sheet
      openxlsx::addWorksheet(wb, "Basic Information")
      basic_info <- data.frame(
        Category = c("MGI ID", "Symbol", "Name", "Description", "Chromosome", "Location", "Strand"),
        Value = c(
          mouse_data$basic_info$mgi_id,
          mouse_data$basic_info$symbol,
          mouse_data$basic_info$name,
          mouse_data$basic_info$description,
          mouse_data$basic_info$chromosome,
          paste(mouse_data$basic_info$start, "-", mouse_data$basic_info$end),
          mouse_data$basic_info$strand
        )
      )
      openxlsx::writeData(wb, "Basic Information", basic_info)
      openxlsx::addStyle(wb, "Basic Information", hs, rows = 1, cols = 1:2)
      
      # Orthologs Sheet
      if (length(mouse_data$orthologs) > 0) {
        openxlsx::addWorksheet(wb, "Human Orthologs")
        orthologs_df <- data.frame(
          ID = sapply(mouse_data$orthologs, `[[`, "id"),
          Symbol = sapply(mouse_data$orthologs, `[[`, "symbol"),
          Organism = sapply(mouse_data$orthologs, `[[`, "organism"),
