        datatable(orthologs_df, options = list(pageLength = 5, dom = 'tip'))
        colnames(orthologs_df) <- c("Symbol", "ID", "Relationship")
        openxlsx::writeData(wb, "Human Orthologs", orthologs_df)
        openxlsx::addStyle(wb, "Human Orthologs", hs, rows = 1, cols = 1:3)
      }
      
      # Diseases Sheet
      if (length(mouse_data$diseases) > 0) {
        openxlsx::addWorksheet(wb, "Disease Associations")
        diseases_df <- as.data.frame(do.call(rbind, lapply(mouse_data$diseases, function(d) {
