        openxlsx::addStyle(wb, "Disease Associations", hs, rows = 1, cols = 1:2)
      }
      
      # Create additional worksheets for other sections as needed
      
      # Save workbook
      openxlsx::saveWorkbook(wb, file, overwrite = TRUE)
    }
