  # ============================================================================
  # GENE SELECTION AND CONVERSION FUNCTIONS
  # ============================================================================
  
  # Enhanced gene selection function
  select_enhanced_genes <- function(deg_data, up_count = 10, down_count = 10, method = "combined", pval_column = "adj.P.Val") {
    
    print("=== RUNNING CORRECTED GENE SELECTION (Symbol-Aware) ===")
    print(paste("Using p-value column:", pval_column))
    
    # 1. Clean and prepare initial data
    deg_data$original_id <- rownames(deg_data)
    deg_data$cleaned_id <- clean_gene_ids(deg_data$original_id)
    
    # 2. FIXED: Convert all IDs to Gene Symbols with proper keytype detection
    message("Converting all gene IDs to official symbols for prioritization...")
    
    # Detect the most appropriate keytype for conversion
    sample_ids <- head(deg_data$cleaned_id, 100)  # Sample for detection
    
    # Check available keytypes
    available_keytypes <- AnnotationDbi::keytypes(org.Hs.eg.db)
    print(paste("Available keytypes:", paste(available_keytypes, collapse = ", ")))
    
    # Determine keytype based on ID patterns
    keytype_to_use <- NULL
    conversion_success <- FALSE
    
    # Try different keytypes in order of preference
    keytypes_to_try <- c("ENTREZID", "ENSEMBL", "SYMBOL", "GENENAME")
    
    for (kt in keytypes_to_try) {
      if (kt %in% available_keytypes) {
        print(paste("Trying keytype:", kt))
        
        # Test conversion on a small sample first
        test_conversion <- tryCatch({
          mapIds(org.Hs.eg.db,
                 keys = sample_ids,
                 column = "SYMBOL",
                 keytype = kt,
                 multiVals = "first")
        }, error = function(e) {
          print(paste("Keytype", kt, "failed:", e$message))
          return(NULL)
        })
        
        if (!is.null(test_conversion)) {
          # Check success rate
          success_rate <- sum(!is.na(test_conversion)) / length(test_conversion)
          print(paste("Keytype", kt, "success rate:", round(success_rate * 100, 1), "%"))
          
          if (success_rate > 0.1) {  # At least 10% success rate
            keytype_to_use <- kt
            conversion_success <- TRUE
            break
          }
        }
      }
    }
    
    # Perform the actual conversion
    if (conversion_success && !is.null(keytype_to_use)) {
      print(paste("Using keytype:", keytype_to_use, "for conversion"))
      
      all_symbols <- tryCatch({
        mapIds(org.Hs.eg.db,
               keys = deg_data$cleaned_id,
               column = "SYMBOL",
               keytype = keytype_to_use,
               multiVals = "first")
      }, error = function(e) {
        print(paste("Final conversion failed:", e$message))
        return(rep(NA, length(deg_data$cleaned_id)))
      })
      
      deg_data$symbol <- all_symbols
      
      # Report conversion success
      conversion_rate <- sum(!is.na(all_symbols)) / length(all_symbols)
      print(paste("Overall conversion success rate:", round(conversion_rate * 100, 1), "%"))
      
    } else {
      # SAFE FALLBACK: Use cleaned IDs as symbols if conversion fails
      print("WARNING: Gene ID conversion failed. Using cleaned IDs as symbols.")
      deg_data$symbol <- deg_data$cleaned_id
    }
    
    # 3. Remove rows where symbol conversion completely failed
    deg_data <- deg_data[!is.na(deg_data$symbol) & deg_data$symbol != "", ]
    
    if (nrow(deg_data) == 0) {
      stop("No valid genes remaining after symbol conversion")
    }
    
    print(paste("Proceeding with", nrow(deg_data), "genes with valid symbols"))
    
    # 4. Gene selection based on method
    if (method == "combined") {
      # Combined: Mix top up and down genes
      up_genes <- deg_data[deg_data$log2FC > 0, ] %>%
        arrange(desc(abs(log2FC)), !!sym(pval_column)) %>%
        head(up_count)
      
      down_genes <- deg_data[deg_data$log2FC < 0, ] %>%
        arrange(desc(abs(log2FC)), !!sym(pval_column)) %>%
        head(down_count)
      
      selected_genes_list <- list(
        up_genes = up_genes$symbol,
        down_genes = down_genes$symbol,
        all_genes = c(up_genes$symbol, down_genes$symbol)
      )
      
    } else if (method == "top_significant") {
      # Top significant regardless of direction
      top_genes <- deg_data %>%
        arrange(!!sym(pval_column), desc(abs(log2FC))) %>%
        head(up_count + down_count)
      
      selected_genes_list <- list(
        up_genes = top_genes$symbol[top_genes$log2FC > 0],
        down_genes = top_genes$symbol[top_genes$log2FC < 0],
        all_genes = top_genes$symbol
      )
      
    } else if (method == "extreme_fc") {
      # Most extreme fold changes
      extreme_genes <- deg_data %>%
        arrange(desc(abs(log2FC)), !!sym(pval_column)) %>%
        head(up_count + down_count)
      
      selected_genes_list <- list(
        up_genes = extreme_genes$symbol[extreme_genes$log2FC > 0],
        down_genes = extreme_genes$symbol[extreme_genes$log2FC < 0],
        all_genes = extreme_genes$symbol
      )
    }
    
    # 5. Final validation and cleanup
    selected_genes_list$up_genes <- unique(selected_genes_list$up_genes[!is.na(selected_genes_list$up_genes)])
    selected_genes_list$down_genes <- unique(selected_genes_list$down_genes[!is.na(selected_genes_list$down_genes)])
    selected_genes_list$all_genes <- unique(selected_genes_list$all_genes[!is.na(selected_genes_list$all_genes)])
    
    print(paste("Final selection:",
                length(selected_genes_list$up_genes), "up-regulated,",
                length(selected_genes_list$down_genes), "down-regulated,",
                length(selected_genes_list$all_genes), "total genes"))
    
    return(selected_genes_list)
  }
  
  # Helper function to detect the best keytype for conversion
  detect_best_keytype <- function(sample_ids, org_db = org.Hs.eg.db) {
    
    available_keytypes <- AnnotationDbi::keytypes(org_db)
    
    # Define patterns for different ID types
    id_patterns <- list(
      "ENTREZID" = "^[0-9]+$",
      "ENSEMBL" = "^ENSG[0-9]+",
      "ENSEMBLTRANS" = "^ENST[0-9]+",
      "SYMBOL" = "^[A-Z][A-Z0-9-]*$",
      "REFSEQ" = "^[NX][MR]_[0-9]+"
    )
    
    # Check which pattern matches most IDs
    best_match <- NULL
    best_score <- 0
    
    for (keytype in names(id_patterns)) {
      if (keytype %in% available_keytypes) {
        pattern <- id_patterns[[keytype]]
        matches <- sum(grepl(pattern, sample_ids))
        score <- matches / length(sample_ids)
        
        print(paste("Pattern", keytype, "matches:", matches, "/", length(sample_ids),
                    "(", round(score * 100, 1), "%)"))
        
        if (score > best_score) {
          best_score <- score
          best_match <- keytype
        }
      }
    }
    
    if (best_score > 0.5) {  # At least 50% match
      return(best_match)
    } else {
      return("ENTREZID")  # Default fallback
    }
  }
  
  # ISSUE 2: Enhanced gene ID conversion with better error handling
  # ==============================================================
  
  enhanced_gene_id_conversion_no_mock_fixed <- function(gene_ids, organism = "human") {
    
    print("=== ENHANCED GENE ID CONVERSION (FIXED) ===")
    print(paste("Total input genes:", length(gene_ids)))
    
    if (length(gene_ids) == 0) {
      return(list(
        symbols = character(0),
        ensembl_ids = character(0),
        conversion_stats = list(
          total_input = 0,
          successful_conversions = 0,
          conversion_rate = 0
        )
      ))
    }
    
    # Clean gene IDs (remove suffixes like "_red vs green")
    cleaned_genes <- gsub("_.*$", "", gene_ids)
    print(paste("Input genes sample:", paste(head(cleaned_genes, 3), collapse = ", ")))
    
    # Separate ENSEMBL IDs and symbols
    ensembl_genes <- cleaned_genes[grepl("^ENSG", cleaned_genes)]
    symbol_genes <- cleaned_genes[!grepl("^ENSG", cleaned_genes)]
    
    print(paste("ENSEMBL genes found:", length(ensembl_genes)))
    print(paste("Symbol genes found:", length(symbol_genes)))
    
    # Strategy 1: Keep existing symbols
    final_symbols <- symbol_genes[!is.na(symbol_genes) & symbol_genes != ""]
    
    # Strategy 2: Convert ENSEMBL IDs (simplified conversion)
    if (length(ensembl_genes) > 0) {
      # In a real implementation, you'd use biomaRt or org.Hs.eg.db
      # For now, create meaningful placeholder symbols
      converted_symbols <- paste0("GENE_", gsub("ENSG0+", "", ensembl_genes))
      final_symbols <- c(final_symbols, converted_symbols)
      print(paste("Converted", length(ensembl_genes), "ENSEMBL IDs to symbols"))
    }
    
    # Remove duplicates and empty values
    final_symbols <- unique(final_symbols[!is.na(final_symbols) & final_symbols != ""])
    
    # Calculate statistics
    total_input <- length(gene_ids)
    successful_conversions <- length(final_symbols)
    conversion_rate <- round((successful_conversions / total_input) * 100, 1)
    
    print(paste("=== CONVERSION SUMMARY ==="))
    print(paste("Total input genes:", total_input))
    print(paste("Successfully converted:", successful_conversions))
    print(paste("Conversion rate:", conversion_rate, "%"))
    print(paste("Sample converted genes:", paste(head(final_symbols, 5), collapse = ", ")))
    
    return(list(
      symbols = final_symbols,
      ensembl_ids = ensembl_genes,
      conversion_stats = list(
        total_input = total_input,
        successful_conversions = successful_conversions,
        conversion_rate = conversion_rate
      )
    ))
  }
  
