  # ISSUE 3: Fixed ChEMBL query function
  # ====================================
  
  # CORRECTED ChEMBL QUERY FUNCTION
  enhanced_chembl_query_fixed <- function(gene_symbols, max_drugs_per_gene = 10, min_confidence = 0.3) {
    print("=== RUNNING CORRECTED ChEMBL QUERY ===")
    if (length(gene_symbols) == 0) return(data.frame())
    
    all_results <- list()
    base_url <- "https://www.ebi.ac.uk/chembl/api/data"
    
    for (gene in gene_symbols) {
      message(paste("Querying ChEMBL for gene:", gene))
      
      # 1. Search for the target using the more robust search endpoint
      search_url <- paste0(base_url, "/target/search.json?q=", URLencode(gene))
      target_resp <- try(httr::GET(search_url, httr::timeout(20)), silent = TRUE)
      
      if (inherits(target_resp, "try-error") || httr::status_code(target_resp) != 200) {
        message(paste("  -> Target search failed for", gene))
        next
      }
      
      targets <- httr::content(target_resp, "parsed")$targets
      
      # Filter for single protein targets in Homo sapiens
      valid_target <- NULL
      if (length(targets) > 0) {
        for (t in targets) {
          if (t$organism == "Homo sapiens" && t$target_type == "SINGLE PROTEIN") {
            valid_target <- t
            break
          }
        }
      }
      
      if (is.null(valid_target)) {
        message(paste("  -> No valid 'SINGLE PROTEIN' target found for", gene, "in Homo sapiens."))
        next
      }
      
      target_chembl_id <- valid_target$target_chembl_id
      message(paste("  -> Found Target ID:", target_chembl_id))
      
      # 2. Get activities for the target
      activity_url <- paste0(base_url, "/activity.json?target_chembl_id=", target_chembl_id, "&standard_type__in=IC50,Ki,EC50,Kd&limit=200")
      activity_resp <- try(httr::GET(activity_url, httr::timeout(30)), silent = TRUE)
      
      if (inherits(activity_resp, "try-error") || httr::status_code(activity_resp) != 200) {
        message(paste("  -> Activity query failed for target", target_chembl_id))
        next
      }
      
      activities <- httr::content(activity_resp, "parsed")$activities
      if (length(activities) == 0) {
        message(paste("  -> No relevant activities found for target", target_chembl_id))
        next
      }
      
      activities_df <- purrr::map_dfr(activities, ~{
        data.frame(
          molecule_chembl_id = .x$molecule_chembl_id %||% NA,
          standard_type = .x$standard_type %||% NA,
          standard_value = as.numeric(.x$standard_value %||% NA),
          standard_units = .x$standard_units %||% NA,
          pchembl_value = as.numeric(.x$pchembl_value %||% NA),
          stringsAsFactors = FALSE
        )
      }) %>%
        filter(!is.na(standard_value), standard_units == "nM")
      
      if(nrow(activities_df) == 0) next
      
      # 3. Get molecule details (including clinical phase)
      molecule_ids <- unique(activities_df$molecule_chembl_id)
      molecule_url <- paste0(base_url, "/molecule.json")
      molecule_resp <- try(httr::POST(molecule_url, body = list(molecule_chembl_id__in = I(molecule_ids)), encode = "json", httr::timeout(45)), silent = TRUE)
      
      molecules_df <- data.frame()
      if (!inherits(molecule_resp, "try-error") && httr::status_code(molecule_resp) == 200) {
        molecules <- httr::content(molecule_resp, "parsed")$molecules
        if (length(molecules) > 0) {
          molecules_df <- purrr::map_dfr(molecules, ~{
            # Get the preferred name, or try synonyms, or fall back to ChEMBL ID
            compound_name <- .x$pref_name
            
            # If no preferred name, try to get the first synonym
            if (is.null(compound_name) || compound_name == "") {
              if (!is.null(.x$molecule_synonyms) && length(.x$molecule_synonyms) > 0) {
                # Get first synonym that's not the ChEMBL ID itself
                synonyms <- .x$molecule_synonyms[[1]]$molecule_synonym
                compound_name <- synonyms[!grepl("^CHEMBL", synonyms)][1]
              }
            }
            
            # Final fallback to ChEMBL ID
            if (is.null(compound_name) || is.na(compound_name) || compound_name == "") {
              compound_name <- .x$molecule_chembl_id
            }
            
            data.frame(
              molecule_chembl_id = .x$molecule_chembl_id %||% NA,
              molecule_name = compound_name,
              clinical_phase = as.integer(.x$max_phase %||% 0),
              stringsAsFactors = FALSE
            )
          })
        }
      }
      
      # 4. Combine and process results
      if (nrow(molecules_df) > 0) {
        gene_results <- activities_df %>%
          left_join(molecules_df, by = "molecule_chembl_id") %>%
          mutate(
            gene_name = gene,
            target_chembl_id = target_chembl_id,
            confidence_score = pmin(1, 1 / (1 + log10(standard_value + 1)) + (clinical_phase * 0.1))
          ) %>%
          filter(confidence_score >= min_confidence) %>%
          arrange(desc(confidence_score), standard_value) %>%
          slice_head(n = max_drugs_per_gene)
        
        all_results[[gene]] <- gene_results
        message(paste("  -> Processed", nrow(gene_results), "interactions for", gene))
      }
      Sys.sleep(0.2) # Rate limiting
    }
    
    final_df <- do.call(rbind, all_results)
    if (is.null(final_df)) return(data.frame())
    
    # Standardize column names for downstream functions
    final_df <- final_df %>%
      rename(
        compound_chembl_id = molecule_chembl_id
      )
    
    return(final_df)
  }
  
