  # Helper function for activity confidence calculation
  calculate_activity_confidence <- function(standard_type, standard_value, standard_units) {
    confidence <- 0.3  # Base confidence
    
    # Higher confidence for standard activity types
    if (standard_type %in% c("IC50", "Ki", "EC50", "Kd")) {
      confidence <- confidence + 0.3
    }
    
    # Higher confidence for reasonable value ranges
    if (!is.na(standard_value) && standard_value > 0) {
      if (standard_units %in% c("nM", "uM")) {
        if (standard_value >= 0.1 && standard_value <= 100000) {  # Reasonable range
          confidence <- confidence + 0.2
        }
      }
    }
    
    # Cap at 1.0
    return(min(confidence, 1.0))
  }
  
  # Convert transcript IDs to gene symbols (keep as is, add explicit biomaRt::)
  convert_transcript_to_gene_ids <- function(ids) {
    if (length(ids) == 0) return(character(0))
    
    # Check if these are transcript IDs (ENST...)
    if (any(grepl("^ENST", ids))) {
      print("BRIDGE: Converting transcript IDs to gene symbols...")
      
      tryCatch({
        if (requireNamespace("biomaRt", quietly = TRUE)) {
          mart <- biomaRt::useMart("ensembl", dataset = "hsapiens_gene_ensembl")
          
          # Get gene symbols from transcript IDs
          results <- biomaRt::getBM(
            attributes = c("ensembl_transcript_id", "external_gene_name"),
            filters = "ensembl_transcript_id",
            values = ids,
            mart = mart
          )
          
          # Map back to original order
          mapped_symbols <- sapply(ids, function(id) {
            symbol <- results$external_gene_name[results$ensembl_transcript_id == id]
            if (length(symbol) > 0 && symbol != "") {
              return(symbol[1])
            } else {
              return(id)  # Keep original if no mapping found
            }
          })
          
          print(paste("BRIDGE: Converted", sum(mapped_symbols != ids), "transcript IDs to gene symbols"))
          return(as.character(mapped_symbols))
        }
      }, error = function(e) {
        print(paste("BRIDGE: Error converting transcript IDs:", e$message))
      })
    }
    
    # Return original IDs if conversion fails or not needed
    return(as.character(ids))
  }
  
  # Enhanced gene conversion for drug analysis - FIXED biomaRt issue
  # 1. ROBUST GENE ID CONVERSION FUNCTION
  convert_mixed_gene_ids <- function(gene_ids, organism = "human") {
    
    
    if (length(gene_ids) == 0) {
      return(list(symbols = character(0), ensembl_ids = character(0), conversion_stats = list()))
    }
    
    # Initialize results
    result_symbols <- character(length(gene_ids))
    result_ensembl <- character(length(gene_ids))
    conversion_stats <- list(
      total_input = length(gene_ids),
      transcript_ids = 0,
      gene_ids = 0,
      symbols = 0,
      successful_conversions = 0
    )
    
    # Categorize input IDs
    enst_indices <- grepl("^ENST\\d+", gene_ids)
    ensg_indices <- grepl("^ENSG\\d+", gene_ids)
    symbol_indices <- !enst_indices & !ensg_indices
    
    conversion_stats$transcript_ids <- sum(enst_indices)
    conversion_stats$gene_ids <- sum(ensg_indices)
    conversion_stats$symbols <- sum(symbol_indices)
    
    print(paste("Converting", conversion_stats$total_input, "gene IDs:",
                conversion_stats$transcript_ids, "transcripts,",
                conversion_stats$gene_ids, "gene IDs,",
                conversion_stats$symbols, "symbols"))
    
    # 1. Handle ENSG IDs (already gene IDs, just need symbols)
    if (sum(ensg_indices) > 0) {
      ensg_ids <- gsub("\\.\\d+$", "", gene_ids[ensg_indices])  # Remove versions
      result_ensembl[ensg_indices] <- ensg_ids
      
      # Get symbols for ENSG IDs using biomaRt
      if (requireNamespace("biomaRt", quietly = TRUE)) {
        symbols_from_ensg <- get_symbols_from_ensembl(ensg_ids)
        if (length(symbols_from_ensg) > 0) {
          result_symbols[ensg_indices] <- symbols_from_ensg[ensg_ids]
        }
      }
    }
    
    # 2. Handle gene symbols (need to get ENSG IDs)
    if (sum(symbol_indices) > 0) {
      symbols <- gene_ids[symbol_indices]
      result_symbols[symbol_indices] <- symbols
      
      # Get ENSG IDs for symbols using biomaRt
      if (requireNamespace("biomaRt", quietly = TRUE)) {
        ensembl_from_symbols <- get_ensembl_from_symbols(symbols)
        if (length(ensembl_from_symbols) > 0) {
          result_ensembl[symbol_indices] <- ensembl_from_symbols[symbols]
        }
      }
    }
    
    # 3. Handle ENST IDs (need both symbols and ENSG IDs)
    if (sum(enst_indices) > 0) {
      enst_ids <- gsub("\\.\\d+$", "", gene_ids[enst_indices])  # Remove versions
      
      if (requireNamespace("biomaRt", quietly = TRUE)) {
        transcript_mappings <- get_mappings_from_transcripts(enst_ids)
        if (nrow(transcript_mappings) > 0) {
          # Create lookup maps
          symbol_map <- setNames(transcript_mappings$external_gene_name,
                                 transcript_mappings$ensembl_transcript_id)
          ensembl_map <- setNames(transcript_mappings$ensembl_gene_id,
                                  transcript_mappings$ensembl_transcript_id)
          
          # Apply mappings
          for (i in which(enst_indices)) {
            enst_clean <- enst_ids[sum(enst_indices[1:i])]
            if (enst_clean %in% names(symbol_map) && !is.na(symbol_map[enst_clean])) {
              result_symbols[i] <- symbol_map[enst_clean]
              result_ensembl[i] <- ensembl_map[enst_clean]
            }
          }
        }
      }
    }
    
    # Calculate success rate
    conversion_stats$successful_conversions <- sum(result_symbols != "" & !is.na(result_symbols))
    
    # Clean up results
    result_symbols[is.na(result_symbols)] <- ""
    result_ensembl[is.na(result_ensembl)] <- ""
    
    # Remove empty entries
    valid_indices <- result_symbols != "" | result_ensembl != ""
    
    return(list(
      symbols = result_symbols[valid_indices],
      ensembl_ids = result_ensembl[valid_indices],
      original_ids = gene_ids[valid_indices],
      conversion_stats = conversion_stats
    ))
  }
  
  # Helper functions for biomaRt queries with robust error handling (keep as is, add explicit biomaRt::)
  get_biomart_connection <- function(max_retries = 3) {
    
    
    mirrors <- list(
      list(func = function() biomaRt::useMart("ensembl", dataset = "hsapiens_gene_ensembl"),
           name = "Standard Ensembl"),
      list(func = function() biomaRt::useEnsembl("ensembl", dataset = "hsapiens_gene_ensembl",
                                                 host = "useast.ensembl.org"),
           name = "US East"),
      list(func = function() biomaRt::useEnsembl("ensembl", dataset = "hsapiens_gene_ensembl",
                                                 host = "uswest.ensembl.org"),
           name = "US West"),
      list(func = function() biomaRt::useEnsembl("ensembl", dataset = "hsapiens_gene_ensembl",
                                                 host = "asia.ensembl.org"),
           name = "Asia")
    )
    
    for (mirror in mirrors) {
      for (retry in 1:max_retries) {
        tryCatch({
          print(paste("Trying", mirror$name, "- attempt", retry))
          mart <- mirror$func()
          print(paste("Successfully connected to", mirror$name))
          return(mart)
        }, error = function(e) {
          print(paste("Failed to connect to", mirror$name, ":", e$message))
          if (retry < max_retries) Sys.sleep(2)  # Wait before retry
        })
      }
    }
    
    warning("Could not connect to any biomaRt mirror")
    return(NULL)
  }
  
  get_mappings_from_transcripts <- function(transcript_ids) {
    
    
    mart <- get_biomart_connection()
    if (is.null(mart)) return(data.frame())
    
    tryCatch({
      results <- biomaRt::getBM(
        attributes = c("ensembl_transcript_id", "external_gene_name", "ensembl_gene_id"),
        filters = "ensembl_transcript_id",
        values = transcript_ids,
        mart = mart
      )
      
      # Filter out empty gene names
      results <- results[!is.na(results$external_gene_name) &
                           results$external_gene_name != "", ]
      
      print(paste("Retrieved", nrow(results), "transcript mappings"))
      return(results)
    }, error = function(e) {
      print(paste("Error querying transcripts:", e$message))
      return(data.frame())
    })
  }
  
  get_symbols_from_ensembl <- function(ensembl_ids) {
    
    
    mart <- get_biomart_connection()
    if (is.null(mart)) return(character(0))
    
    tryCatch({
      results <- biomaRt::getBM(
        attributes = c("ensembl_gene_id", "external_gene_name"),
        filters = "ensembl_gene_id",
        values = ensembl_ids,
        mart = mart
      )
      
      # Create named vector
      symbol_map <- setNames(results$external_gene_name, results$ensembl_gene_id)
      print(paste("Retrieved", length(symbol_map), "symbol mappings"))
      return(symbol_map)
    }, error = function(e) {
      print(paste("Error querying ENSEMBL IDs:", e$message))
      return(character(0))
    })
  }
  
  get_ensembl_from_symbols <- function(gene_symbols) {
    
    
    mart <- get_biomart_connection()
    if (is.null(mart)) return(character(0))
    
    tryCatch({
      results <- biomaRt::getBM(
        attributes = c("external_gene_name", "ensembl_gene_id"),
        filters = "external_gene_name",
        values = gene_symbols,
        mart = mart
      )
      
      # Create named vector
      ensembl_map <- setNames(results$ensembl_gene_id, results$external_gene_name)
      print(paste("Retrieved", length(ensembl_map), "ENSEMBL mappings"))
      return(ensembl_map)
    }, error = function(e) {
      print(paste("Error querying gene symbols:", e$message))
      return(character(0))
    })
  }
  
  
  # DRUG DISCOVERY KEY FINDINGS OUTPUTS
  
  # Executive Summary
  output$drug_discovery_executive_summary <- renderUI({
    req(network_rv$current_results)
    req(input$drug_analysis_focus == "drug_discovery")
    
    drug_data <- network_rv$current_results$drug_targets
    if (is.null(drug_data) || nrow(drug_data) == 0) {
      return(p("No drug data available yet.", style = "opacity: 0.9;"))
    }
    
    n_compounds <- length(unique(drug_data$drug_name %||% drug_data$molecule_name))
    n_targets <- length(unique(drug_data$gene_name))
    n_approved <- sum(drug_data$is_approved == TRUE, na.rm = TRUE)
    n_clinical <- sum(drug_data$clinical_phase > 0, na.rm = TRUE)
    
    # Get source diversity
    sources_all <- paste(drug_data$sources, collapse = ", ")
    has_chembl <- grepl("ChEMBL", sources_all, ignore.case = TRUE)
    has_drugbank <- grepl("DrugBank", sources_all, ignore.case = TRUE)
    source_text <- if(has_chembl && has_drugbank) "ChEMBL, DrugBank & more" else "multiple databases"
    
    HTML(paste0(
      "<p style='font-size: 1.1em; margin: 0; line-height: 1.6;'>",
      "Your analysis identified <strong>", n_compounds, " drug compounds</strong> targeting <strong>",
      n_targets, "</strong> of your genes from ", source_text, ". ",
      if(n_approved > 0) paste0("<strong>", n_approved, "</strong> are FDA-approved drugs. ") else "",
      if(n_clinical > 0) paste0("<strong>", n_clinical, "</strong> are in clinical development.") else "Most are in preclinical/research stages.",
      "</p>"
    ))
  })
  
