    drug_data <- network_rv$current_results$drug_targets
    if (is.null(drug_data)) return("0")
    
    # For DGIdb, count approved drugs as "drug-like"
    # Or count high-confidence interactions from multiple sources
    if ("is_approved" %in% colnames(drug_data)) {
      n_approved <- sum(drug_data$is_approved == TRUE, na.rm = TRUE)
      if (n_approved > 0) return(as.character(n_approved))
    }
    
    # Fallback: count high-confidence entries
    if ("confidence_score" %in% colnames(drug_data)) {
      return(as.character(sum(drug_data$confidence_score >= 0.6, na.rm = TRUE)))
    }
    
    # Legacy fallback for ChEMBL data
    if ("standard_value" %in% colnames(drug_data)) {
      return(as.character(sum(as.numeric(drug_data$standard_value) <= 1000, na.rm = TRUE)))
    }
    
    return("0")
