  output$dd_top5_targets_cards <- renderUI({
    req(network_rv$current_results)
    req(input$drug_analysis_focus == "drug_discovery")
    
    drug_data <- network_rv$current_results$drug_targets
    if (is.null(drug_data) || nrow(drug_data) == 0) {
      return(p("No target data available", style = "color: #999;"))
    }
    
    # Get drug name column (compatibility)
    drug_col <- if("drug_name" %in% colnames(drug_data)) "drug_name" else "molecule_name"
    
    # Ensure is_approved column exists
    if (!"is_approved" %in% colnames(drug_data)) {
      drug_data$is_approved <- drug_data$clinical_phase >= 4
    }
    
    # Ensure n_sources column exists
    if (!"n_sources" %in% colnames(drug_data)) {
      drug_data$n_sources <- 1
    }
    
    # Count compounds per target with safe column access
    target_stats <- drug_data %>%
      dplyr::group_by(gene_name) %>%
      dplyr::summarise(
        n_compounds = dplyr::n_distinct(!!rlang::sym(drug_col)),
        n_approved = sum(is_approved == TRUE, na.rm = TRUE),
        avg_confidence = mean(confidence_score, na.rm = TRUE),
        max_n_sources = max(n_sources, na.rm = TRUE),
        .groups = 'drop'
      ) %>%
      dplyr::arrange(dplyr::desc(n_compounds), dplyr::desc(n_approved)) %>%
      head(5)
    
    cards <- lapply(seq_len(nrow(target_stats)), function(i) {
      row <- target_stats[i, ]
      
      # Display info based on available data
      detail_text <- paste0(
        row$n_compounds, " compounds",
        if(!is.na(row$n_approved) && row$n_approved > 0) paste0(" • ", row$n_approved, " approved") else ""
      )
      
      div(style = "display: flex; align-items: center; padding: 10px; margin-bottom: 8px; 
            background: white; border-radius: 6px; border-left: 3px solid #2196F3;",
          div(style = "width: 30px; height: 30px; background: #e3f2fd; border-radius: 50%; 
                display: flex; align-items: center; justify-content: center; margin-right: 12px;",
              span(i, style = "font-weight: bold; color: #2196F3;")
          ),
          div(style = "flex: 1;",
              strong(row$gene_name, style = "color: #2c3e50;"),
              div(style = "font-size: 0.85em; color: #7f8c8d;", detail_text)
          )
      )
    })
    
    do.call(tagList, cards)
  })
  
  # Top 5 Compounds Cards
  output$dd_top5_compounds_cards <- renderUI({
    req(network_rv$current_results)
    req(input$drug_analysis_focus == "drug_discovery")
    
    drug_data <- network_rv$current_results$drug_targets
    if (is.null(drug_data) || nrow(drug_data) == 0) {
      return(p("No compound data available", style = "color: #999;"))
    }
    
    # Get drug name column (compatibility)
    drug_col <- if("drug_name" %in% colnames(drug_data)) "drug_name" else "molecule_name"
    
    # Ensure required columns exist with defaults
    if (!"is_approved" %in% colnames(drug_data)) {
      drug_data$is_approved <- drug_data$clinical_phase >= 4
    }
    if (!"n_publications" %in% colnames(drug_data)) {
      drug_data$n_publications <- 0
    }
    if (!"n_sources" %in% colnames(drug_data)) {
      drug_data$n_sources <- 1
    }
    if (!"interaction_type" %in% colnames(drug_data)) {
      if ("standard_type" %in% colnames(drug_data)) {
        drug_data$interaction_type <- drug_data$standard_type
      } else {
        drug_data$interaction_type <- "Unknown"
      }
    }
    
    # Get top compounds by available metrics
    top_compounds <- drug_data %>%
      dplyr::arrange(
        dplyr::desc(is_approved),
        dplyr::desc(clinical_phase),
        dplyr::desc(confidence_score),
        dplyr::desc(n_publications)
      ) %>%
      dplyr::distinct(!!rlang::sym(drug_col), .keep_all = TRUE) %>%
      head(5)
    
    if (nrow(top_compounds) == 0) {
      return(p("No compound data available", style = "color: #999;"))
    }
    
    cards <- lapply(seq_len(nrow(top_compounds)), function(i) {
      row <- top_compounds[i, ]
      
      # Get drug name
      compound_name <- if("drug_name" %in% colnames(row)) row$drug_name else row$molecule_name
      
      # Status badge
      status_badge <- if(isTRUE(row$is_approved)) {
        span("Approved", style = "background: #4CAF50; color: white; padding: 2px 6px; 
                             border-radius: 4px; font-size: 0.75em; margin-left: 8px;")
      } else if(!is.na(row$clinical_phase) && row$clinical_phase > 0) {
        span(paste0("Phase ", row$clinical_phase), 
             style = "background: #FF9800; color: white; padding: 2px 6px; 
                  border-radius: 4px; font-size: 0.75em; margin-left: 8px;")
      } else NULL
      
      # Detail text
      detail_parts <- c()
      if(!is.na(row$interaction_type) && row$interaction_type != "Unknown" && row$interaction_type != "") {
        detail_parts <- c(detail_parts, row$interaction_type)
      }
      detail_parts <- c(detail_parts, paste0("Target: ", row$gene_name))
      if(!is.na(row$n_sources) && row$n_sources > 1) {
        detail_parts <- c(detail_parts, paste0(row$n_sources, " sources"))
      }
      detail_text <- paste(detail_parts, collapse = " • ")
      
      div(style = "display: flex; align-items: center; padding: 10px; margin-bottom: 8px; 
          background: white; border-radius: 6px; border-left: 3px solid #FF9800;",
          div(style = "width: 30px; height: 30px; background: #fff3e0; border-radius: 50%; 
              display: flex; align-items: center; justify-content: center; margin-right: 12px;",
              span(i, style = "font-weight: bold; color: #FF9800;")
          ),
          div(style = "flex: 1;",
              div(
                strong(compound_name, style = "color: #2c3e50;"),
                status_badge
              ),
              div(style = "font-size: 0.85em; color: #7f8c8d;", detail_text)
          )
      )
    })
    
    do.call(tagList, cards)
  })
  
  # Actionable Insights
  output$dd_actionable_insights <- renderUI({
    req(network_rv$current_results)
    
    drug_data <- network_rv$current_results$drug_targets
    if (is.null(drug_data) || nrow(drug_data) == 0) {
      return(div(class = "alert alert-info", "Complete analysis to see actionable insights"))
    }
    
    # Ensure columns exist
    if (!"is_approved" %in% colnames(drug_data)) drug_data$is_approved <- drug_data$clinical_phase >= 4
    if (!"n_sources" %in% colnames(drug_data)) drug_data$n_sources <- 1
    if (!"n_publications" %in% colnames(drug_data)) drug_data$n_publications <- 0
    if (!"interaction_type" %in% colnames(drug_data)) drug_data$interaction_type <- "Unknown"
    if (!"gene_categories" %in% colnames(drug_data)) drug_data$gene_categories <- ""
    
    # Calculate insights
    n_approved <- sum(drug_data$is_approved == TRUE, na.rm = TRUE)
    approved_drugs <- unique(drug_data$molecule_name[drug_data$is_approved == TRUE])
    
    n_high_conf <- sum(drug_data$confidence_score >= 0.7, na.rm = TRUE)
    n_multi_source <- sum(drug_data$n_sources >= 3, na.rm = TRUE)
    n_with_pubs <- sum(drug_data$n_publications >= 5, na.rm = TRUE)
    
    # Kinase targets
    kinase_targets <- drug_data %>%
      dplyr::filter(grepl("kinase", gene_categories, ignore.case = TRUE)) %>%
      dplyr::pull(gene_name) %>%
      unique()
    
    # Drugs with known mechanisms
    known_mechanisms <- drug_data %>%
      dplyr::filter(!is.na(interaction_type) & interaction_type != "Unknown" & interaction_type != "") %>%
      nrow()
    
    # Build insights panel
    div(
      style = "background: linear-gradient(135deg, #e8f5e9 0%, #c8e6c9 100%); 
             border-radius: 12px; padding: 20px; border-left: 4px solid #4caf50;",
      
      h4(icon("lightbulb"), "Actionable Insights", 
         style = "color: #2e7d32; margin-bottom: 15px; font-weight: 600;"),
      
      # Approved drugs insight
      if (n_approved > 0) {
        div(
          style = "margin-bottom: 12px; padding: 10px; background: white; border-radius: 8px;",
          div(
            icon("check-circle", style = "color: #4caf50; margin-right: 8px;"),
            strong(paste0(n_approved, " FDA-approved drug(s) target your genes:")),
            style = "margin-bottom: 5px;"
          ),
          div(
            style = "color: #666; font-size: 0.9em; margin-left: 28px;",
            paste(head(approved_drugs, 5), collapse = ", "),
            if (length(approved_drugs) > 5) paste0(" + ", length(approved_drugs) - 5, " more")
          ),
          div(
            style = "margin-top: 8px; margin-left: 28px;",
            tags$a(
              href = paste0("https://www.dgidb.org/results?searchType=drug&searchTerms=", 
                            URLencode(paste(head(approved_drugs, 3), collapse = ","))),
              target = "_blank",
              style = "color: #1976d2; font-size: 0.85em;",
              icon("external-link"), " Explore in DGIdb"
            )
          )
        )
      },
      
      # High confidence interactions
      if (n_high_conf > 0) {
        div(
          style = "margin-bottom: 12px; padding: 10px; background: white; border-radius: 8px;",
          icon("star", style = "color: #ffc107; margin-right: 8px;"),
          strong(paste0(n_high_conf, " high-confidence interactions")),
          span(" backed by multiple sources and publications", style = "color: #666;")
        )
      },
      
      # Multi-source validation
      if (n_multi_source > 0) {
        div(
          style = "margin-bottom: 12px; padding: 10px; background: white; border-radius: 8px;",
          icon("database", style = "color: #2196f3; margin-right: 8px;"),
          strong(paste0(n_multi_source, " interactions")),
          span(" validated across 3+ databases (higher reliability)", style = "color: #666;")
        )
      },
      
      # Kinase targets
      if (length(kinase_targets) > 0) {
        div(
          style = "margin-bottom: 12px; padding: 10px; background: white; border-radius: 8px;",
          icon("bullseye", style = "color: #e91e63; margin-right: 8px;"),
          strong(paste0(length(kinase_targets), " kinase target(s) identified")),
          span(" - highly druggable protein family", style = "color: #666;"),
          div(
            style = "margin-top: 5px; margin-left: 28px; font-size: 0.9em; color: #666;",
            paste(kinase_targets, collapse = ", ")
          )
        )
      },
      
      # Publications
      if (n_with_pubs > 0) {
        div(
          style = "margin-bottom: 12px; padding: 10px; background: white; border-radius: 8px;",
          icon("book", style = "color: #9c27b0; margin-right: 8px;"),
          strong(paste0(n_with_pubs, " interactions")),
          span(" supported by 5+ publications", style = "color: #666;"),
          tags$a(
            href = "https://pubmed.ncbi.nlm.nih.gov/",
            target = "_blank",
            style = "color: #1976d2; font-size: 0.85em; margin-left: 10px;",
            icon("external-link"), " Search PubMed"
          )
        )
      },
      
      # Known mechanisms
      if (known_mechanisms > 0) {
        div(
          style = "padding: 10px; background: white; border-radius: 8px;",
          icon("cogs", style = "color: #607d8b; margin-right: 8px;"),
          strong(paste0(known_mechanisms, " interactions")),
          span(" with known mechanism of action (inhibitor, agonist, etc.)", style = "color: #666;")
        )
      }
    )
  })
  
  
