  output$disease_context_executive_summary <- renderUI({
    req(network_rv$current_results)
    req(input$drug_analysis_focus == "disease_context")
    
    ot_data <- network_rv$current_results$opentargets_data
    if (is.null(ot_data)) ot_data <- network_rv$current_results$drug_targets
    
    if (is.null(ot_data) || nrow(ot_data) == 0) {
      return(p("No disease context data available yet.", style = "opacity: 0.9;"))
    }
    
    n_targets <- length(unique(ot_data$gene_name))
    n_drugs <- length(unique(ot_data$molecule_name))
    n_approved <- sum(ot_data$clinical_phase >= 4, na.rm = TRUE)
    n_clinical <- sum(ot_data$clinical_phase > 0 & ot_data$clinical_phase < 4, na.rm = TRUE)
    
    HTML(paste0(
      "<p style='font-size: 1.1em; margin: 0; line-height: 1.6;'>",
      "OpenTargets identified <strong>", n_drugs, " drugs/candidates</strong> associated with <strong>",
      n_targets, "</strong> of your target genes. ",
      if(n_approved > 0) paste0("<strong>", n_approved, "</strong> are approved drugs suitable for repurposing. ") else "",
      if(n_clinical > 0) paste0("<strong>", n_clinical, "</strong> additional candidates are in clinical trials.") else "",
      "</p>"
    ))
  })
  
  output$dc_top_therapeutic_area <- renderText({
    req(network_rv$current_results)
    req(input$drug_analysis_focus == "disease_context")
    
    ot_data <- network_rv$current_results$opentargets_data
    if (is.null(ot_data)) ot_data <- network_rv$current_results$drug_targets
    
    if (is.null(ot_data) || nrow(ot_data) == 0) return("Various")
    
    # Try multiple possible column names
    disease_col <- NULL
    for (col in c("therapeutic_area", "disease_indication", "disease_name", "indication")) {
      if (col %in% colnames(ot_data) && any(!is.na(ot_data[[col]]) & ot_data[[col]] != "")) {
        disease_col <- col
        break
      }
    }
    
    if (is.null(disease_col)) return("Various")
    
    disease_data <- ot_data[[disease_col]]
    disease_data <- disease_data[!is.na(disease_data) & disease_data != ""]
    
    if (length(disease_data) == 0) return("Various")
    
    ta_counts <- table(disease_data)
    if (length(ta_counts) == 0) return("Various")
    
    top_area <- names(ta_counts)[which.max(ta_counts)]
    
    # Truncate if too long
    if (nchar(top_area) > 18) {
      top_area <- paste0(substr(top_area, 1, 15), "...")
    }
    
    return(top_area)
  })
  
