  output$comp_top_crossval_cards <- renderUI({
    req(network_rv$current_results)
    req(input$drug_analysis_focus == "comprehensive")
    
    chembl_data <- network_rv$current_results$chembl_data
    ot_data <- network_rv$current_results$opentargets_data
    
    if (is.null(chembl_data) || nrow(chembl_data) == 0) {
      return(p("Waiting for DGIdb data...", style = "color: #999;"))
    }
    
    if (is.null(ot_data) || nrow(ot_data) == 0) {
      return(p("Waiting for OpenTargets data...", style = "color: #999;"))
    }
    
    chembl_genes <- unique(chembl_data$gene_name[!is.na(chembl_data$gene_name)])
    ot_genes <- unique(ot_data$gene_name[!is.na(ot_data$gene_name)])
    cross_val <- intersect(chembl_genes, ot_genes)
    
    if (length(cross_val) == 0) {
      return(p("No cross-validated targets found", style = "color: #999;"))
    }
    
    # Get stats for cross-validated genes
    cross_stats <- data.frame(gene_name = cross_val, stringsAsFactors = FALSE)
    
    cross_stats$dgidb_compounds <- sapply(cross_val, function(g) {
      sum(chembl_data$gene_name == g, na.rm = TRUE)
    })
    
    cross_stats$ot_drugs <- sapply(cross_val, function(g) {
      sum(ot_data$gene_name == g, na.rm = TRUE)
    })
    
    cross_stats$total_evidence <- cross_stats$dgidb_compounds + cross_stats$ot_drugs
    
    # Sort by total evidence and take top 5
    cross_stats <- cross_stats[order(-cross_stats$total_evidence), ]
    cross_stats <- head(cross_stats, 5)
    
    cards <- lapply(seq_len(nrow(cross_stats)), function(i) {
      row <- cross_stats[i, ]
      
      div(style = "display: flex; align-items: center; padding: 10px; margin-bottom: 8px; 
                background: white; border-radius: 6px; border-left: 3px solid #9C27B0;",
          div(style = "width: 30px; height: 30px; background: #f3e5f5; border-radius: 50%; 
                    display: flex; align-items: center; justify-content: center; margin-right: 12px;",
              icon("check-double", style = "color: #9C27B0;")
          ),
          div(style = "flex: 1;",
              strong(row$gene_name, style = "color: #2c3e50;"),
              div(style = "font-size: 0.85em; color: #7f8c8d;",
                  # Changed from "ChEMBL:" to "DGIdb:"
                  paste0("DGIdb: ", row$dgidb_compounds, "   OpenTargets: ", row$ot_drugs)
              )
          )
      )
    })
    
    do.call(tagList, cards)
  })
  
