  # ============================================================================
  # EXISTING DATABASE QUERY FUNCTIONS - Add your existing functions here
  # ============================================================================
  
  enhanced_chembl_query_with_filters <- function(gene_symbols, max_drugs_per_gene = 1000,
                                                 confidence_threshold = 0, experimental_only = FALSE) {
    
    print("╔══════════════════════════════════════════════════════════════╗")
    print("║   CACHED ChEMBL QUERY (Parallel Mode with Auto-Cleanup)      ║")
    print("╚══════════════════════════════════════════════════════════════╝")
    
    if (length(gene_symbols) == 0) {
      print("No gene symbols provided for ChEMBL query")
      return(data.frame())
    }
    
    # Clean gene symbols
    gene_symbols <- unique(gene_symbols[!is.na(gene_symbols) & gene_symbols != ""])
    print(paste("📊 Processing", length(gene_symbols), "unique genes"))
    
    start_time <- Sys.time()
    current_time <- Sys.time()
    base_url <- "https://www.ebi.ac.uk/chembl/api/data"
    
    all_results <- data.frame()
    genes_from_cache <- character(0)
    genes_to_query <- character(0)
    
    # -------------------------------------------------------------------------
    # PHASE 1: Separate Cached vs Uncached Genes
    # -------------------------------------------------------------------------
    for (gene in gene_symbols) {
      cache_key <- toupper(trimws(gene))
      
      if (cache_key %in% names(chembl_cache$raw_data)) {
        cached_entry <- chembl_cache$raw_data[[cache_key]]
        cache_age <- difftime(current_time, cached_entry$timestamp, units = "hours")
        
        if (cache_age < chembl_cache$max_age_hours) {
          genes_from_cache <- c(genes_from_cache, gene)
          next
        }
      }
      genes_to_query <- c(genes_to_query, gene)
    }
    
    # Update stats
    chembl_cache$stats$hits <- chembl_cache$stats$hits + length(genes_from_cache)
    chembl_cache$stats$misses <- chembl_cache$stats$misses + length(genes_to_query)
    
    print(paste("📦 Cache Status:", length(genes_from_cache), "hits /", length(genes_to_query), "misses",
                "(", round(length(genes_from_cache)/length(gene_symbols)*100, 1), "% hit rate)"))
    
    # -------------------------------------------------------------------------
    # PHASE 2: Process Cached Genes (FAST - no API calls)
    # -------------------------------------------------------------------------
    if (length(genes_from_cache) > 0) {
      print(paste("⚡ Processing", length(genes_from_cache), "genes from cache..."))
      chembl_cache$stats$api_calls_saved <- chembl_cache$stats$api_calls_saved + (length(genes_from_cache) * 2)
      
      for (gene in genes_from_cache) {
        cache_key <- toupper(trimws(gene))
        cached_entry <- chembl_cache$raw_data[[cache_key]]
        
        if (!is.null(cached_entry$activities) && length(cached_entry$activities) > 0) {
          tryCatch({
            gene_results <- process_chembl_activities_with_filters(
              activities = cached_entry$activities,
              gene_name = gene,
              target_id = cached_entry$target_id,
              max_drugs_per_gene = max_drugs_per_gene,
              confidence_threshold = confidence_threshold,
              experimental_only = experimental_only
            )
            if (!is.null(gene_results) && nrow(gene_results) > 0) {
              all_results <- rbind(all_results, gene_results)
            }
          }, error = function(e) {
            # Skip problematic cached entries
          })
        }
      }
      print(paste("✅ Cached genes processed:", nrow(all_results), "results so far"))
    }
    
    # -------------------------------------------------------------------------
    # PHASE 3: PARALLEL Query API for Uncached Genes
    # -------------------------------------------------------------------------
    if (length(genes_to_query) > 0) {
      print(paste("🚀 Querying ChEMBL API for", length(genes_to_query), "genes (PARALLEL mode)..."))
      
      # Load future.apply for parallel processing
      if (!requireNamespace("future.apply", quietly = TRUE)) {
        install.packages("future.apply", quiet = TRUE)
      }
      library(future.apply)
      
      # Split into batches for parallel processing
      batch_size <- 10
      n_workers <- getOption("mc.cores", 4)
      n_batches <- ceiling(length(genes_to_query) / batch_size)
      gene_batches <- split(genes_to_query, cut(seq_along(genes_to_query), n_batches, labels = FALSE))
      
      print(paste("  📦 Split into", length(gene_batches), "batches, processing in parallel..."))
      
      # Define the worker function that queries a batch of genes
      query_gene_batch <- function(batch_genes, base_url, max_drugs_per_gene) {
        batch_results <- list()
        batch_cache <- list()
        
        for (gene in batch_genes) {
          cache_key <- toupper(trimws(gene))
          
          tryCatch({
            # Query Target
            target_url <- paste0(base_url, "/target.json?target_synonym__iexact=", 
                                 URLencode(gene), "&limit=3")
            target_response <- httr::GET(target_url, httr::timeout(20))
            
            if (httr::status_code(target_response) != 200) {
              batch_cache[[cache_key]] <- list(target_id = NULL, activities = list(), 
                                               timestamp = Sys.time())
              next
            }
            
            target_data <- httr::content(target_response, "parsed")
            
            if (length(target_data$targets) == 0) {
              batch_cache[[cache_key]] <- list(target_id = NULL, activities = list(), 
                                               timestamp = Sys.time())
              next
            }
            
            # Find human target
            target_id <- NULL
            for (target in target_data$targets) {
              if (!is.null(target$organism) && target$organism == "Homo sapiens") {
                target_id <- target$target_chembl_id
                break
              }
            }
            if (is.null(target_id)) {
              target_id <- target_data$targets[[1]]$target_chembl_id
            }
            
            # Query Activities
            activity_url <- paste0(base_url, "/activity.json?target_chembl_id=", target_id,
                                   "&limit=", min(500, max_drugs_per_gene * 2))
            activity_response <- httr::GET(activity_url, httr::timeout(25))
            
            if (httr::status_code(activity_response) != 200) {
              batch_cache[[cache_key]] <- list(target_id = target_id, activities = list(), 
                                               timestamp = Sys.time())
              next
            }
            
            activity_data <- httr::content(activity_response, "parsed")
            
            # Store for cache
            batch_cache[[cache_key]] <- list(
              target_id = target_id,
              activities = activity_data$activities,
              timestamp = Sys.time(),
              n_activities = length(activity_data$activities)
            )
            
            # Store results
            if (length(activity_data$activities) > 0) {
              batch_results[[gene]] <- list(
                gene = gene,
                target_id = target_id,
                activities = activity_data$activities
              )
            }
            
            # Small delay to respect API
            Sys.sleep(0.1)
            
          }, error = function(e) {
            batch_cache[[cache_key]] <- list(target_id = NULL, activities = list(), 
                                             timestamp = Sys.time())
          })
        }
        
        return(list(results = batch_results, cache = batch_cache))
      }
      
      # Run parallel processing
      parallel_results <- tryCatch({
        future_lapply(gene_batches, function(batch) {
          query_gene_batch(batch, base_url, max_drugs_per_gene)
        }, future.seed = TRUE)
      }, error = function(e) {
        print(paste("⚠️ Parallel processing error:", e$message))
        print("  Falling back to sequential processing...")
        lapply(gene_batches, function(batch) {
          query_gene_batch(batch, base_url, max_drugs_per_gene)
        })
      })
      
      # Collect results and update cache
      print("  📥 Collecting parallel results...")
      
      for (batch_result in parallel_results) {
        # Update cache
        for (key in names(batch_result$cache)) {
          chembl_cache$raw_data[[key]] <- batch_result$cache[[key]]
        }
        
        # Process activities into final results
        for (gene_data in batch_result$results) {
          if (length(gene_data$activities) > 0) {
            tryCatch({
              gene_results <- process_chembl_activities_with_filters(
                activities = gene_data$activities,
                gene_name = gene_data$gene,
                target_id = gene_data$target_id,
                max_drugs_per_gene = max_drugs_per_gene,
                confidence_threshold = confidence_threshold,
                experimental_only = experimental_only
              )
              if (!is.null(gene_results) && nrow(gene_results) > 0) {
                all_results <- rbind(all_results, gene_results)
              }
            }, error = function(e) {
              # Skip problematic entries
            })
          }
        }
      }
      
      # IMPORTANT: Clean up parallel workers to prevent zombies
      print("  🧹 Cleaning up parallel workers...")
      gc()  # Force garbage collection
    }
    
    # -------------------------------------------------------------------------
    # PHASE 4: Cache Maintenance
    # -------------------------------------------------------------------------
    if (length(chembl_cache$raw_data) > chembl_cache$max_entries) {
      timestamps <- sapply(chembl_cache$raw_data, function(x) as.numeric(x$timestamp))
      oldest_keys <- names(sort(timestamps))[1:50]
      for (key in oldest_keys) {
        chembl_cache$raw_data[[key]] <- NULL
      }
      print("🧹 Cache pruned: 50 old entries removed")
    }
    
    # -------------------------------------------------------------------------
    # PHASE 5: Summary
    # -------------------------------------------------------------------------
    elapsed <- round(difftime(Sys.time(), start_time, units = "secs"), 1)
    
    print("╔══════════════════════════════════════════════════════════════╗")
    print(paste("║ ✅ QUERY COMPLETE in", elapsed, "seconds"))
    print(paste("║ 📊 Total results:", nrow(all_results), "drug-target interactions"))
    print(paste("║ 📦 Genes now cached:", length(chembl_cache$raw_data)))
    print(paste("║ 💰 API calls saved this session:", chembl_cache$stats$api_calls_saved))
    print("╚══════════════════════════════════════════════════════════════╝")
    
    return(all_results)
  }
  
  query_chembl_parallel_with_cache <- function(genes, max_drugs_per_gene, confidence_threshold,
                                               experimental_only, batch_size = 5, n_workers = 3) {
    # NOTE: n_workers parameter kept for backward compatibility but not used
    # API queries are I/O-bound; sequential with connection reuse is faster than parallel
    
    print(paste("🔍 Processing", length(genes), "genes sequentially (optimized for API calls)"))
    
    all_results <- data.frame()
    total <- length(genes)
    
    for (i in seq_along(genes)) {
      gene <- genes[i]
      
      # Progress indicator every 10 genes
      if (i %% 10 == 0 || i == 1) {
        print(paste("  Processing gene", i, "/", total, ":", gene))
      }
      
      tryCatch({
        result <- query_single_gene_and_cache(
          gene = gene,
          max_drugs_per_gene = max_drugs_per_gene,
          confidence_threshold = confidence_threshold,
          experimental_only = experimental_only
        )
        
        if (!is.null(result$processed) && nrow(result$processed) > 0) {
          all_results <- rbind(all_results, result$processed)
        }
        
        # Rate limiting - respect API limits
        Sys.sleep(0.1)
        
      }, error = function(e) {
        # Silent fail for individual genes, continue with others
        message(paste("Warning: Failed to query gene", gene, "-", e$message))
      })
    }
    
    print(paste("✅ Completed:", nrow(all_results), "drug-gene interactions found"))
    
    if (nrow(all_results) == 0) all_results <- data.frame()
    return(all_results)
  }
  
  
  process_chembl_activities_with_filters <- function(activities, gene_name, target_id,
                                                     max_drugs_per_gene = 1000,
                                                     confidence_threshold = 0,
                                                     experimental_only = FALSE) {
    
    results <- data.frame()
    
    for (activity in activities) {
      tryCatch({
        # Extract key information safely
        compound_id <- safe_extract(activity, c("molecule_chembl_id"), "Unknown")
        molecule_name <- safe_extract(activity, c("molecule_pref_name"), compound_id)
        if (is.null(molecule_name) || molecule_name == "Unknown" || nchar(trimws(molecule_name)) == 0) {
          molecule_name <- compound_id
        }
        
        standard_type <- safe_extract(activity, c("standard_type"), "Unknown")
        standard_units <- safe_extract(activity, c("standard_units"), "Unknown")
        activity_comment <- safe_extract(activity, c("activity_comment"), "")
        data_validity_comment <- safe_extract(activity, c("data_validity_comment"), "")
        
        # ========================================
        # FIX: Safely convert standard_value to numeric
        # ========================================
        standard_value_raw <- safe_extract(activity, c("standard_value"), NA)
        standard_value <- suppressWarnings(as.numeric(standard_value_raw))
        
        # Skip if conversion failed or value is invalid
        if (is.na(standard_value) || !is.finite(standard_value) || standard_value <= 0) {
          next
        }
        
        # Get clinical phase (safely)
        clinical_phase_raw <- safe_extract(activity, c("molecule_properties", "clinical_phase"), 0)
        clinical_phase <- suppressWarnings(as.integer(clinical_phase_raw))
        if (is.na(clinical_phase)) clinical_phase <- 0L
        
        # FILTER 1: Basic data quality - compound_id must be valid
        if (is.null(compound_id) || compound_id == "Unknown") {
          next
        }
        
        # FILTER 2: Standard activity types
        valid_types <- c("IC50", "Ki", "EC50", "Kd", "Potency", "Inhibition", "GI50", "ED50", "LC50", "CC50")
        if (!standard_type %in% valid_types) {
          next
        }
        
        # FILTER 3: Valid units
        valid_units <- c("nM", "uM", "pM", "mM", "%", "ug.mL-1", "mg.mL-1")
        if (!standard_units %in% valid_units) {
          next
        }
        
        # FILTER 4: Experimental evidence filter
        if (experimental_only) {
          is_experimental <- any(grepl("binding|inhibition|IC50|Ki|EC50|Kd",
                                       c(standard_type, activity_comment), ignore.case = TRUE))
          if (!is_experimental) {
            next
          }
        }
        
        # FILTER 5: Data validity filter
        if (!is.null(data_validity_comment) && nchar(data_validity_comment) > 0 &&
            grepl("invalid|outside|potential", data_validity_comment, ignore.case = TRUE)) {
          next
        }
        
        # ========================================
        # FIX: Safe unit conversion (standard_value is now guaranteed numeric)
        # ========================================
        converted_value <- standard_value
        if (standard_units == "uM") {
          converted_value <- standard_value * 1000
        } else if (standard_units == "mM") {
          converted_value <- standard_value * 1000000
        } else if (standard_units == "pM") {
          converted_value <- standard_value / 1000
        }
        
        # FILTER 6: Reasonable activity ranges
        if (standard_units %in% c("nM", "uM", "mM", "pM")) {
          if (converted_value < 0.001 || converted_value > 1e7) {
            next
          }
        }
        if (standard_units == "%" && (standard_value < 0 || standard_value > 100)) {
          next
        }
        
        # Calculate confidence score
        confidence_score_val <- calculate_confidence_score(
          standard_type = standard_type,
          standard_value = standard_value,
          standard_units = standard_units,
          activity_comment = activity_comment,
          data_validity_comment = data_validity_comment
        )
        
        # FILTER 7: Confidence threshold filter
        if (!is.na(confidence_score_val) && confidence_score_val < confidence_threshold) {
          next
        }
        
        # Build result row
        result_row <- data.frame(
          gene_name = gene_name,
          target_chembl_id = target_id,
          molecule_name = molecule_name,
          molecule_id = compound_id,
          compound_chembl_id = compound_id,
          standard_type = standard_type,
          standard_value = standard_value,  # Already numeric
          standard_units = standard_units,
          activity_comment = activity_comment,
          confidence_score = confidence_score_val,
          database_source = "ChEMBL",
          clinical_phase = clinical_phase,
          stringsAsFactors = FALSE
        )
        
        results <- rbind(results, result_row)
        
      }, error = function(e) {
        # Silently skip problematic activities instead of printing errors
        # Uncomment below for debugging:
        # print(paste("Error processing activity for", gene_name, ":", e$message))
      })
    }
    
    # FILTER 8: Apply max drugs per gene limit
    if (nrow(results) > max_drugs_per_gene) {
      results <- results %>%
        dplyr::arrange(dplyr::desc(confidence_score), standard_value) %>%
        dplyr::slice_head(n = max_drugs_per_gene)
    }
    
    return(results)
  }
  
  calculate_confidence_score <- function(standard_type, standard_value, standard_units,
                                         activity_comment, data_validity_comment) {
    
    score <- 0.5  # Base score
    
    # Boost for standard activity types
    if (!is.null(standard_type) && length(standard_type) == 1 && !is.na(standard_type)) {
      if (standard_type %in% c("IC50", "Ki", "Kd", "EC50", "Potency", "GI50", "ED50", "LC50", "CC50")) {
        score <- score + 0.2
      }
    }
    
    # Boost for reasonable activity values
    if (!is.null(standard_value) && length(standard_value) == 1) {
      value <- suppressWarnings(as.numeric(standard_value))
      if (!is.na(value) && is.finite(value) && value > 0 && value < 1000000) {
        score <- score + 0.2
      }
    }
    
    # Boost for standard units
    if (!is.null(standard_units) && length(standard_units) == 1 && !is.na(standard_units)) {
      if (standard_units %in% c("nM", "uM", "pM", "mM", "%", "ug.mL-1", "mg.mL-1")) {
        score <- score + 0.1
      }
    }
    
    # Penalize based on data validity comments
    if (!is.null(data_validity_comment) && length(data_validity_comment) == 1 && 
        !is.na(data_validity_comment) && nchar(data_validity_comment) > 0) {
      if (grepl("invalid|outside|potential", data_validity_comment, ignore.case = TRUE)) {
        score <- score - 0.2
      }
    }
    
    return(pmax(0.1, pmin(1.0, score)))
  }
  
  
  safe_extract <- function(data, path, default = NA) {
    
    
    result <- data
    for (key in path) {
      if (is.list(result) && key %in% names(result)) {
        result <- result[[key]]
      } else {
        return(default)
      }
    }
    return(if(is.null(result)) default else result)
  }
  
  safe_extract <- function(data, path, default = NA) {
    
    
    result <- data
    for (key in path) {
      if (is.list(result) && key %in% names(result)) {
        result <- result[[key]]
      } else {
        return(default)
      }
    }
    return(if(is.null(result)) default else result)
  }
  
