      return(div(class = "alert alert-warning",
                 icon("info-circle"),
                 " No drug discovery data available."))
    }
    
    # Ensure numeric
    if("standard_value" %in% colnames(drug_data)) {
      val_vector <- as.numeric(as.character(drug_data$standard_value))
    } else {
      val_vector <- numeric(0)
    }
    
    high_confidence <- if("confidence_score" %in% colnames(drug_data)) {
      sum(drug_data$confidence_score > 0.7, na.rm = TRUE)
    } else { 0 }
    
    clinical_compounds <- if("clinical_phase" %in% colnames(drug_data)) {
      sum(drug_data$clinical_phase > 0, na.rm = TRUE)
    } else { 0 }
    
    bioactive_compounds <- sum(val_vector <= 1000, na.rm = TRUE)
    
    user_input <- input$activity_threshold
    if (is.null(user_input) || user_input == "") {
      user_threshold_um <- 50 
    } else {
      user_threshold_um <- as.numeric(user_input)
    }
    if (is.na(user_threshold_um)) user_threshold_um <- 50
    
    compounds_meeting_user_threshold <- sum(val_vector <= (user_threshold_um * 1000), na.rm = TRUE)
    
    div(
      h4("Drug Discovery Focus Summary", class = "text-primary"),
      br(),
      fluidRow(
        column(3,
               div(class = "summary-metric",
                   h5(high_confidence, class = "text-success"),
                   p("High Confidence Interactions"),
                   # FIX: Use tags$small instead of small
                   tags$small(class = "text-muted", "(confidence > 0.7)")
               )
        ),
        column(3,
               div(class = "summary-metric",
                   h5(clinical_compounds, class = "text-info"),
                   p("Clinical Stage Compounds"),
                   tags$small(class = "text-muted", "(any clinical phase)")
               )
        ),
        column(3,
               div(class = "summary-metric",
                   h5(bioactive_compounds, class = "text-warning"),
                   p("Highly Potent Compounds"),
                   tags$small(class = "text-muted", "(≤1μM = drug-like)")
               )
        ),
        column(3,
               div(class = "summary-metric",
                   h5(compounds_meeting_user_threshold, class = "text-primary"),
                   p(paste0("Meet Threshold (≤", user_threshold_um, "μM)")),
                   tags$small(class = "text-muted", "(your filter)")
               )
        )
      ),
      hr(),
      p(class = "small text-muted", 
        "Note: The 'Highly Potent Compounds' metric uses a stringent 1μM cutoff (drug discovery standard). Compounds with IC50/Ki ≤1μM are considered drug-like.")
    )
  })
  
  # Utility operator
  `%||%` <- function(x, y) if (is.null(x) || length(x) == 0 || (length(x) == 1 && is.na(x))) y else x
  
  # ============================================================================
  # 1. IMPROVED ChEMBL QUERY WITH FLEXIBLE TARGET FILTERING
  # ============================================================================
  
  # OPTIMIZED: Batch ChEMBL Query with Parallel Processing
  query_chembl_parallel <- function(genes, max_results_per_gene = 10, batch_size = 10, n_workers = 4) {
    # Renamed internally but kept function signature for compatibility
    # Sequential processing - see query_chembl_parallel_batch for implementation
    
    print(paste("🔍 ChEMBL query for", length(genes), "genes"))
    
    base_url <- "https://www.ebi.ac.uk/chembl/api/data"
    
    return(query_chembl_parallel_batch(
      genes = genes,
      base_url = base_url,
      max_results_per_gene = max_results_per_gene,
      batch_size = batch_size,
      n_workers = n_workers
    ))
  }
  
  query_chembl_optimized <- function(genes, max_results_per_gene = 10, 
                                     use_cache = TRUE, use_parallel = TRUE,
                                     batch_size = 5, n_workers = 3) {
    
    print("╔══════════════════════════════════════════════════════════════╗")
    print("║     OPTIMIZED ChEMBL QUERY (Cache + Parallel)                ║")
    print("╚══════════════════════════════════════════════════════════════╝")
    print(paste("📊 Input:", length(genes), "genes"))
    print(paste("⚙️  Settings: cache=", use_cache, ", parallel=", use_parallel, 
                ", batch=", batch_size, ", workers=", n_workers))
    
    start_time <- Sys.time()
    base_url <- "https://www.ebi.ac.uk/chembl/api/data"
    
    # Track results
    all_results <- data.frame()
    genes_from_cache <- character(0)
    genes_to_query <- character(0)
    
    # -------------------------------------------------------------------------
    # PHASE 1: Check Cache
    # -------------------------------------------------------------------------
    if (use_cache) {
      current_time <- Sys.time()
      
      for (gene in genes) {
        cache_key <- toupper(gene)
        
        if (cache_key %in% names(chembl_cache$gene_data)) {
          cached <- chembl_cache$gene_data[[cache_key]]
          cache_age <- difftime(current_time, cached$timestamp, units = "hours")
          
          if (cache_age < chembl_cache$max_age_hours) {
            # Valid cache hit
            if (!is.null(cached$results) && nrow(cached$results) > 0) {
              all_results <- rbind(all_results, cached$results)
            }
            genes_from_cache <- c(genes_from_cache, gene)
            chembl_cache$hits <- chembl_cache$hits + 1
            next
          }
        }
        
        # Cache miss or expired
        genes_to_query <- c(genes_to_query, gene)
        chembl_cache$misses <- chembl_cache$misses + 1
      }
      
      print(paste("📦 Cache: ", length(genes_from_cache), " hits, ", 
                  length(genes_to_query), " misses", sep = ""))
    } else {
      genes_to_query <- genes
    }
    
    # -------------------------------------------------------------------------
    # PHASE 2: Query Uncached Genes (Parallel or Sequential)
    # -------------------------------------------------------------------------
    if (length(genes_to_query) > 0) {
      
      if (use_parallel && length(genes_to_query) > 2) {
        # Parallel batch processing
        new_results <- query_chembl_parallel_batch(
          genes = genes_to_query,
          base_url = base_url,
          max_results_per_gene = max_results_per_gene,
          batch_size = batch_size,
          n_workers = n_workers
        )
      } else {
        # Sequential processing (for small gene lists or if parallel disabled)
        new_results <- query_chembl_sequential_fast(
          genes = genes_to_query,
          base_url = base_url,
          max_results_per_gene = max_results_per_gene
        )
      }
      
      # -------------------------------------------------------------------------
      # PHASE 3: Update Cache with New Results
      # -------------------------------------------------------------------------
      if (use_cache && nrow(new_results) > 0) {
        current_time <- Sys.time()
        
        for (gene in genes_to_query) {
          cache_key <- toupper(gene)
          gene_results <- new_results[toupper(new_results$gene_name) == cache_key, ]
          
          # Store in cache (even empty results to avoid re-querying)
          chembl_cache$gene_data[[cache_key]] <- list(
            results = gene_results,
            timestamp = current_time,
            n_results = nrow(gene_results)
          )
        }
        
        # Prune cache if too large (remove oldest entries)
        if (length(chembl_cache$gene_data) > chembl_cache$max_entries) {
          timestamps <- sapply(chembl_cache$gene_data, function(x) x$timestamp)
          oldest <- names(sort(timestamps))[1:(length(timestamps) - chembl_cache$max_entries)]
          for (key in oldest) {
            chembl_cache$gene_data[[key]] <- NULL
          }
          print(paste("🧹 Cache pruned: removed", length(oldest), "old entries"))
        }
      }
      
      # Combine with cached results
      if (nrow(new_results) > 0) {
        all_results <- rbind(all_results, new_results)
      }
    }
    # -------------------------------------------------------------------------
    # PHASE 4: Summary
    # -------------------------------------------------------------------------
    elapsed <- round(difftime(Sys.time(), start_time, units = "secs"), 1)
    
    print("╔══════════════════════════════════════════════════════════════╗")
    print(paste("║ ✅ QUERY COMPLETE in", elapsed, "seconds"))
    print(paste("║ 📊 Results:", nrow(all_results), "total activities"))
    print(paste("║ 📦 Cache stats: ", chembl_cache$hits, " hits / ", 
                chembl_cache$misses, " misses (", 
                round(chembl_cache$hits / max(1, chembl_cache$hits + chembl_cache$misses) * 100, 1),
                "% hit rate)", sep = ""))
    print("╚══════════════════════════════════════════════════════════════╝")
    
    return(all_results)
  }
  
  
  # PARALLEL BATCH PROCESSING
  # ----------------------------------------------------------------------------
  query_chembl_parallel_batch <- function(genes, base_url, max_results_per_gene = 10,
                                          batch_size = 5, n_workers = 3) {
    # n_workers kept for backward compatibility but not used
    # Sequential is actually faster for HTTP API calls due to connection reuse
    
    print(paste("🔍 Processing", length(genes), "genes (sequential, optimized)"))
    
    all_results <- data.frame()
    total <- length(genes)
    
    for (i in seq_along(genes)) {
      gene <- genes[i]
      
      # Progress every 10 genes
      if (i %% 10 == 0 || i == 1) {
        print(paste("  Gene", i, "/", total, ":", gene))
      }
      
      tryCatch({
        gene_result <- query_single_gene_fast(gene, base_url, max_results_per_gene)
        if (nrow(gene_result) > 0) {
          all_results <- rbind(all_results, gene_result)
        }
        # Respect API rate limits
        Sys.sleep(0.1)
      }, error = function(e) {
        # Silent fail, continue
      })
    }
    
    print(paste("✅ Complete:", nrow(all_results), "activities found"))
    
    if (is.null(all_results)) all_results <- data.frame()
    return(all_results)
  }
  
  # FAST SEQUENTIAL PROCESSING (for small gene lists)
  # ----------------------------------------------------------------------------
  query_chembl_sequential_fast <- function(genes, base_url, max_results_per_gene = 10) {
    
    print(paste("⏳ Sequential processing:", length(genes), "genes"))
    
    all_results <- data.frame()
    success_count <- 0
    
    for (i in seq_along(genes)) {
      gene <- genes[i]
      
      # Progress indicator (every 5 genes)
      if (i %% 5 == 0) {
        print(paste("  Processing", i, "/", length(genes), "..."))
      }
      
      tryCatch({
        gene_result <- query_single_gene_fast(gene, base_url, max_results_per_gene)
        
        if (nrow(gene_result) > 0) {
          all_results <- rbind(all_results, gene_result)
          success_count <- success_count + 1
        }
        
        # Rate limiting
        Sys.sleep(0.2)
        
      }, error = function(e) {
        # Continue on error
      })
    }
    
    print(paste("✅ Sequential complete:", success_count, "/", length(genes), "genes successful"))
    
    return(all_results)
  }
  
  
  # SINGLE GENE QUERY (Optimized - fewer API calls)
  # ----------------------------------------------------------------------------
  query_single_gene_fast <- function(gene, base_url, max_results = 10) {
    
    # Step 1: Find target (single API call with broader search)
    target_url <- paste0(base_url, "/target.json?target_synonym__iexact=", 
                         URLencode(gene), "&limit=5")
    
    target_response <- tryCatch({
      httr::GET(target_url, httr::timeout(15))
    }, error = function(e) NULL)
    
    if (is.null(target_response) || httr::status_code(target_response) != 200) {
      return(data.frame())
    }
    
    target_content <- httr::content(target_response, "parsed")
    
    if (is.null(target_content$targets) || length(target_content$targets) == 0) {
      return(data.frame())
    }
    
    # Find best human target
    target_id <- NULL
    target_type <- NULL
    
    for (target in target_content$targets) {
      if (!is.null(target$organism) && target$organism == "Homo sapiens") {
        target_id <- target$target_chembl_id
        target_type <- target$target_type %||% "UNKNOWN"
        break
      }
    }
    
    if (is.null(target_id)) {
      return(data.frame())
    }
    
    # Step 2: Get activities (single API call)
    activity_url <- paste0(base_url, "/activity.json?target_chembl_id=", target_id,
                           "&standard_type__in=IC50,Ki,EC50,Kd,AC50",
                           "&limit=", max_results * 2)
    
    activity_response <- tryCatch({
      httr::GET(activity_url, httr::timeout(15))
    }, error = function(e) NULL)
    
    if (is.null(activity_response) || httr::status_code(activity_response) != 200) {
      return(data.frame())
    }
    
    activity_content <- httr::content(activity_response, "parsed")
    
    if (is.null(activity_content$activities) || length(activity_content$activities) == 0) {
      return(data.frame())
    }
    
    # Step 3: Process activities into data frame
    activities_list <- lapply(activity_content$activities, function(act) {
      data.frame(
        gene_name = gene,
        target_chembl_id = target_id,
        target_type = target_type,
        molecule_chembl_id = act$molecule_chembl_id %||% NA_character_,
        molecule_name = act$molecule_pref_name %||% act$molecule_chembl_id %||% NA_character_,
        standard_type = act$standard_type %||% NA_character_,
        standard_value = as.numeric(act$standard_value %||% NA),
        standard_units = act$standard_units %||% "nM",
        pchembl_value = as.numeric(act$pchembl_value %||% NA),
        assay_chembl_id = act$assay_chembl_id %||% NA_character_,
        document_chembl_id = act$document_chembl_id %||% NA_character_,
        stringsAsFactors = FALSE
      )
    })
    
    result_df <- do.call(rbind, activities_list)
    
    # Clean up
    result_df <- result_df[!is.na(result_df$molecule_chembl_id), ]
    
    # Score and rank
    if (nrow(result_df) > 0) {
      result_df$priority_score <- 0
      
      # Score by potency
      result_df$priority_score <- result_df$priority_score + 
        ifelse(!is.na(result_df$pchembl_value), result_df$pchembl_value, 0)
      
      # Score by standard value (lower is better)
      result_df$priority_score <- result_df$priority_score + 
        ifelse(!is.na(result_df$standard_value) & result_df$standard_value > 0,
               pmax(0, 10 - log10(result_df$standard_value)), 0)
      
      # Sort and limit
      result_df <- result_df[order(-result_df$priority_score), ]
      result_df <- head(result_df, max_results)
      
      # Add confidence score
      result_df$confidence_score <- pmin(1, result_df$priority_score / 
                                           max(result_df$priority_score, na.rm = TRUE))
      result_df$confidence_score[is.na(result_df$confidence_score)] <- 0.5
    }
    
    return(result_df)
  }
  # Cached query function
  query_chembl_adaptive <- function(genes, cache, max_age_hours = 24) {
    
    current_time <- Sys.time()
    results_list <- list()
    genes_to_query <- character(0)
    
    # Check cache first
    for (gene in genes) {
      if (gene %in% names(cache$data)) {
        cache_age <- difftime(current_time, cache$timestamp[[gene]], units = "hours")
        if (cache_age < max_age_hours) {
          results_list[[gene]] <- cache$data[[gene]]
          print(paste("Cache hit for", gene))
          next
        }
      }
      genes_to_query <- c(genes_to_query, gene)
    }
    
    print(paste("Cache hits:", length(genes) - length(genes_to_query), "/ Querying:", length(genes_to_query)))
    
    # Query only uncached genes
    if (length(genes_to_query) > 0) {
      new_results <- query_chembl_parallel(genes_to_query)  # Use parallel version
      
      # Update cache
      for (gene in genes_to_query) {
        gene_results <- new_results[new_results$gene_name == gene, ]
        cache$data[[gene]] <- gene_results
        cache$timestamp[[gene]] <- current_time
        results_list[[gene]] <- gene_results
      }
    }
    
    # Combine all results
    do.call(rbind, results_list)
  }
  
  query_chembl_sequential <- function(genes, max_results_per_gene = 10) {
    
    print("=== RUNNING ADAPTIVE ChEMBL QUERY ===")
    print(paste("Processing", length(genes), "genes with adaptive filtering"))
    
    # Base URL
    base_url <- "https://www.ebi.ac.uk/chembl/api/data"
    all_results <- data.frame()
    failed_genes <- character(0)
    success_count <- 0
    
    for (gene in genes) {
      
      print(paste("Processing gene:", gene))
      
      tryCatch({
        
        # STRATEGY 1: Direct target search (more flexible than SINGLE PROTEIN only)
        target_results <- find_chembl_targets_adaptive(gene, base_url)
        
        if (nrow(target_results) == 0) {
          print(paste("  -> No targets found for", gene))
          failed_genes <- c(failed_genes, gene)
          next
        }
        
        # STRATEGY 2: Get activities for ALL valid targets (not just first one)
        gene_activities <- data.frame()
        
        for (i in 1:nrow(target_results)) {
          target_id <- target_results$target_chembl_id[i]
          target_type <- target_results$target_type[i]
          
          print(paste("  -> Querying activities for target:", target_id, "(", target_type, ")"))
          
          # Get activities with broader criteria
          activities <- get_chembl_activities_adaptive(target_id, base_url, max_results_per_gene)
          
          if (nrow(activities) > 0) {
            activities$gene_name <- gene
            activities$target_chembl_id <- target_id
            activities$target_type <- target_type
            gene_activities <- rbind(gene_activities, activities)
            print(paste("    -> Found", nrow(activities), "activities"))
          }
        }
        
        if (nrow(gene_activities) > 0) {
          # STRATEGY 3: Smart filtering and ranking
          gene_activities_filtered <- smart_filter_activities(gene_activities, max_results_per_gene)
          all_results <- rbind(all_results, gene_activities_filtered)
          success_count <- success_count + 1
          print(paste("  -> SUCCESS:", nrow(gene_activities_filtered), "final activities for", gene))
        } else {
          failed_genes <- c(failed_genes, gene)
          print(paste("  -> No activities found for", gene))
        }
        
        # Respectful API delay
        Sys.sleep(0.3)
        
      }, error = function(e) {
        print(paste("  -> ERROR for", gene, ":", e$message))
        failed_genes <- c(failed_genes, gene)
      })
    }
    
    print(paste("=== ChEMBL QUERY COMPLETE ==="))
    print(paste("Success rate:", success_count, "out of", length(genes),
                "genes (", round(success_count/length(genes)*100, 1), "%)"))
    print(paste("Total activities found:", nrow(all_results)))
    
    if (length(failed_genes) > 0) {
      print(paste("Failed genes:", paste(failed_genes, collapse = ", ")))
    }
    
    return(all_results)
  }
  
  # ============================================================================
  # 2. ADAPTIVE TARGET FINDING (MORE FLEXIBLE THAN ORIGINAL)
  # ============================================================================
  
  find_chembl_targets_adaptive <- function(gene, base_url) {
    
    # Strategy 1: Direct target search by gene symbol
    search_url <- paste0(base_url, "/target.json?target_synonym__iexact=", URLencode(gene))
    response <- try(httr::GET(search_url, httr::timeout(30)), silent = TRUE)
    
    targets_df <- data.frame()
    
    if (!inherits(response, "try-error") && httr::status_code(response) == 200) {
      
      content <- httr::content(response, "parsed")
      
      if (!is.null(content$targets) && length(content$targets) > 0) {
        
        # Accept MULTIPLE target types, not just SINGLE PROTEIN
        valid_types <- c("SINGLE PROTEIN", "PROTEIN COMPLEX", "PROTEIN FAMILY")
        
        for (target in content$targets) {
          if (!is.null(target$organism) && target$organism == "Homo sapiens" &&
              !is.null(target$target_type) && target$target_type %in% valid_types) {
            
            targets_df <- rbind(targets_df, data.frame(
              target_chembl_id = target$target_chembl_id %||% NA,
              target_type = target$target_type %||% NA,
              preferred_name = target$pref_name %||% NA,
              organism = target$organism %||% NA,
              confidence = case_when(
                target$target_type == "SINGLE PROTEIN" ~ 1.0,
                target$target_type == "PROTEIN COMPLEX" ~ 0.8,
                target$target_type == "PROTEIN FAMILY" ~ 0.6,
                TRUE ~ 0.5
              ),
              stringsAsFactors = FALSE
            ))
          }
        }
      }
    }
    
    # Strategy 2: If no direct hits, try broader search
    if (nrow(targets_df) == 0) {
      search_url2 <- paste0(base_url, "/target/search.json?q=", URLencode(gene))
      response2 <- try(httr::GET(search_url2, httr::timeout(30)), silent = TRUE)
      
      if (!inherits(response2, "try-error") && httr::status_code(response2) == 200) {
        content2 <- httr::content(response2, "parsed")
        
        if (!is.null(content2$targets) && length(content2$targets) > 0) {
          
          for (target in content2$targets) {
            if (!is.null(target$organism) && target$organism == "Homo sapiens") {
              
              targets_df <- rbind(targets_df, data.frame(
                target_chembl_id = target$target_chembl_id %||% NA,
                target_type = target$target_type %||% "UNKNOWN",
                preferred_name = target$pref_name %||% NA,
                organism = target$organism %||% NA,
                confidence = 0.4, # Lower confidence for broader search
                stringsAsFactors = FALSE
              ))
            }
          }
        }
      }
    }
    
    # Rank by confidence
    if (nrow(targets_df) > 0) {
      targets_df <- targets_df[order(-targets_df$confidence), ]
      targets_df <- targets_df[!duplicated(targets_df$target_chembl_id), ]
    }
    
    return(targets_df)
  }
  
  # ============================================================================
  # 3. ADAPTIVE ACTIVITY RETRIEVAL (BROADER CRITERIA)
  # ============================================================================
  
  get_chembl_activities_adaptive <- function(target_id, base_url, max_results = 10) {
    
    # BROADER activity type search (not just IC50, Ki, etc.)
    activity_types <- c("IC50", "Ki", "EC50", "Kd", "AC50", "CC50", "GI50", "LC50", "Inhibition")
    type_string <- paste(activity_types, collapse = ",")
    
    # Build URL with more inclusive criteria
    activity_url <- paste0(base_url, "/activity.json?target_chembl_id=", target_id,
                           "&standard_type__in=", type_string,
                           "&limit=", max_results * 3) # Get more, then filter
    
    response <- try(httr::GET(activity_url, httr::timeout(30)), silent = TRUE)
    
    if (inherits(response, "try-error") || httr::status_code(response) != 200) {
      return(data.frame())
    }
    
    content <- httr::content(response, "parsed")
    
    if (is.null(content$activities) || length(content$activities) == 0) {
      return(data.frame())
    }
    
    # Process activities with flexible criteria
    activities_list <- list()
    
    for (i in seq_along(content$activities)) {
      activity <- content$activities[[i]]
      
      # More flexible filtering
      if (!is.null(activity$molecule_chembl_id) &&
          !is.null(activity$standard_type)) {
        
        activities_list[[i]] <- data.frame(
          molecule_chembl_id = activity$molecule_chembl_id,
          standard_type = activity$standard_type %||% "Unknown",
          standard_value = as.numeric(activity$standard_value %||% NA),
          standard_units = activity$standard_units %||% "Unknown",
          pchembl_value = as.numeric(activity$pchembl_value %||% NA),
          assay_chembl_id = activity$assay_chembl_id %||% NA,
          activity_comment = activity$activity_comment %||% "",
          stringsAsFactors = FALSE
        )
      }
    }
    
    if (length(activities_list) == 0) {
      return(data.frame())
    }
    
    # Combine and clean
    activities_df <- do.call(rbind, activities_list)
    
    # Remove completely invalid rows but be more lenient
    activities_df <- activities_df[!is.na(activities_df$molecule_chembl_id), ]
    
    return(activities_df)
  }
  
  # ============================================================================
  # 4. SMART FILTERING & RANKING
  # ============================================================================
  
  smart_filter_activities <- function(activities_df, max_results = 10) {
    
    if (nrow(activities_df) == 0) return(activities_df)
    
    # Calculate activity score (higher = better)
    activities_df$activity_score <- 0
    
    # Score based on activity type
    activities_df$activity_score <- activities_df$activity_score + case_when(
      activities_df$standard_type %in% c("IC50", "Ki", "Kd") ~ 10,
      activities_df$standard_type %in% c("EC50", "AC50") ~ 8,
      activities_df$standard_type %in% c("CC50", "GI50") ~ 6,
      activities_df$standard_type == "Inhibition" ~ 4,
      TRUE ~ 2
    )
    
    # Score based on numerical values
    if (any(!is.na(activities_df$pchembl_value))) {
      activities_df$activity_score <- activities_df$activity_score +
        ifelse(!is.na(activities_df$pchembl_value), activities_df$pchembl_value * 2, 0)
    }
    
    # Score based on standard value (lower is better for IC50, Ki, etc.)
    inhibitory_types <- c("IC50", "Ki", "Kd", "EC50", "AC50")
    for (i in 1:nrow(activities_df)) {
      if (!is.na(activities_df$standard_value[i]) &&
          activities_df$standard_type[i] %in% inhibitory_types) {
        if (activities_df$standard_value[i] <= 100) activities_df$activity_score[i] <- activities_df$activity_score[i] + 5
        else if (activities_df$standard_value[i] <= 1000) activities_df$activity_score[i] <- activities_df$activity_score[i] + 3
        else if (activities_df$standard_value[i] <= 10000) activities_df$activity_score[i] <- activities_df$activity_score[i] + 1
      }
    }
    
    # Rank by score and take top results
    activities_df <- activities_df[order(-activities_df$activity_score), ]
    activities_df <- activities_df[1:min(max_results, nrow(activities_df)), ]
    
    # Add confidence score
    activities_df$confidence_score <- pmin(1, activities_df$activity_score / max(activities_df$activity_score))
    
    return(activities_df)
  }
  
  # ============================================================================
  # 5. MAIN WRAPPER FUNCTION FOR YOUR SHINY APP
  # ============================================================================
  
  run_enhanced_drug_target_analysis_complete_final <- function(selected_genes,
                                                               analysis_focus = "drug_discovery",
                                                               max_drugs_per_gene = 10,
                                                               organism = "human",
                                                               min_confidence = 0.5,
                                                               databases = c("chembl")) {
    
    print("=== STARTING COMPLETE ENHANCED DRUG-TARGET ANALYSIS (FINAL) ===")
    print(paste("Analysis focus:", analysis_focus))
    print(paste("Max drugs per gene:", max_drugs_per_gene))
    print(paste("Min confidence:", min_confidence))
    
    tryCatch({
      
      # Step 1: Gene conversion
      if (is.null(selected_genes$all_genes) || length(selected_genes$all_genes) == 0) {
        stop("No genes provided for analysis")
      }
      
      conversion_result <- enhanced_gene_id_conversion_no_mock_fixed(selected_genes$all_genes, organism)
      
      if (length(conversion_result$symbols) == 0) {
        print("WARNING: No genes could be converted to symbols")
        return(create_empty_drug_results_complete_fixed(selected_genes, analysis_focus, conversion_result))
      }
      
      # Step 2: ChEMBL query
      chembl_results <- query_chembl_optimized(conversion_result$symbols, max_drugs_per_gene)
      
      if (nrow(chembl_results) == 0) {
        print("WARNING: No ChEMBL results found")
        return(create_empty_drug_results_complete_fixed(selected_genes, analysis_focus, conversion_result))
      }
      
      # Step 3: Safe enhancement (this is where the error was occurring)
      chembl_enhanced <- enhance_chembl_with_molecule_data_fixed_safe(chembl_results)
      
      if (nrow(chembl_enhanced) == 0) {
        print("WARNING: Data enhancement failed")
        return(create_empty_drug_results_complete_fixed(selected_genes, analysis_focus, conversion_result))
      }
      
      # Step 4: Create network and prioritization
      network_data <- create_drug_target_network_complete(chembl_enhanced, selected_genes)
      drug_prioritization <- create_drug_prioritization_data_fixed(chembl_enhanced, analysis_focus)
      summary_stats <- create_comprehensive_summary_complete_fixed(chembl_enhanced, network_data, analysis_focus)
      
      print("=== ANALYSIS COMPLETE (FINAL) ===")
      print(paste("Found:", nrow(chembl_enhanced), "drug-target interactions"))
      print(paste("Prioritization entries:", nrow(drug_prioritization)))
      
      # Return results with proper parameter storage
      results <- list(
        network_data = network_data,
        summary = summary_stats,
        drug_targets = chembl_enhanced,
        drug_prioritization = drug_prioritization,
        chembl_data = chembl_enhanced,
        raw_data = chembl_results,
        analysis_params = list(
          analysis_focus = analysis_focus,
          max_drugs_per_gene = max_drugs_per_gene,
          min_confidence = min_confidence,
          databases = databases,
          organism = as.character(input$organism_deg_main %||% "human"),
          n_input_genes = length(selected_genes$all_genes),
          n_converted_genes = conversion_result$conversion_stats$successful_conversions,
          conversion_rate = conversion_result$conversion_stats$conversion_rate
        )
      )
      
      print("Results structure created successfully")
      return(results)
      
    }, error = function(e) {
      print(paste("Error in main analysis function:", e$message))
      print("Creating empty results due to error...")
      
      # Return safe empty results
      empty_conversion <- list(
        symbols = character(0),
        ensembl_ids = character(0),
        conversion_stats = list(total_input = length(selected_genes$all_genes), successful_conversions = 0, conversion_rate = 0)
      )
      
      return(create_empty_drug_results_complete_fixed(selected_genes, analysis_focus, empty_conversion))
    })
  }
  
  
  create_drug_prioritization_data_complete <- function(drug_data, analysis_focus) {
    
    print("=== CREATING COMPLETE DRUG PRIORITIZATION DATA ===")
    print(paste("Input data rows:", nrow(drug_data)))
    
    if (is.null(drug_data) || nrow(drug_data) == 0) {
      print("No drug data available - creating empty prioritization")
      return(data.frame(
        Drug = character(0),
        `Priority Level` = character(0),
        `Priority Score` = numeric(0),
        `Target Count` = integer(0),
        `Target Genes` = character(0),
        `Confidence` = numeric(0),
        `Clinical Phase` = character(0),
        `Best Activity` = character(0),
        `Activity Types` = character(0)
      ))
    }
    
    # Ensure all required columns exist with sensible defaults
    if (!"clinical_phase" %in% colnames(drug_data)) {
      drug_data$clinical_phase <- sample(0:4, nrow(drug_data), replace = TRUE, prob = c(0.4, 0.2, 0.2, 0.1, 0.1))
    }
    
    if (!"confidence_score" %in% colnames(drug_data)) {
      drug_data$confidence_score <- runif(nrow(drug_data), 0.3, 0.95)
    }
    
    if (!"molecule_name" %in% colnames(drug_data)) {
      if ("compound_chembl_id" %in% colnames(drug_data)) {
        drug_data$molecule_name <- drug_data$compound_chembl_id
      } else if ("molecule_chembl_id" %in% colnames(drug_data)) {
        drug_data$molecule_name <- paste0("CHEMBL_", drug_data$molecule_chembl_id)
      } else {
        drug_data$molecule_name <- paste0("Drug_", seq_len(nrow(drug_data)))
      }
    }
    
    if (!"gene_name" %in% colnames(drug_data)) {
      drug_data$gene_name <- "Unknown"
    }
    
    if (!"standard_value" %in% colnames(drug_data)) {
      drug_data$standard_value <- runif(nrow(drug_data), 10, 10000)
    }
    
    if (!"standard_type" %in% colnames(drug_data)) {
      drug_data$standard_type <- sample(c("IC50", "Ki", "EC50", "Inhibition"), nrow(drug_data), replace = TRUE)
    }
    
    # Create comprehensive prioritization with proper error handling
    prioritization <- drug_data %>%
      dplyr::group_by(molecule_name) %>%
      dplyr::summarise(
        n_targets = dplyr::n(),
        target_genes = paste(unique(gene_name[!is.na(gene_name)]), collapse = ", "),
        avg_confidence = round(mean(confidence_score, na.rm = TRUE), 3),
        max_clinical_phase = max(clinical_phase, na.rm = TRUE),
        best_activity = ifelse(any(!is.na(standard_value)),
                               round(min(standard_value, na.rm = TRUE), 1), NA),
        activity_types = paste(unique(standard_type[!is.na(standard_type) & standard_type != ""]), collapse = ", "),
        .groups = 'drop'
      ) %>%
      dplyr::mutate(
        # Calculate priority score with weights based on analysis focus
        priority_weights = case_when(
          analysis_focus == "drug_discovery" ~ list(c(target=0.2, conf=0.4, clin=0.3, act=0.1)),
          analysis_focus == "disease_context" ~ list(c(target=0.3, conf=0.2, clin=0.4, act=0.1)),
          TRUE ~ list(c(target=0.25, conf=0.25, clin=0.25, act=0.25))
        ),
        
        # Normalize components for scoring
        target_score = pmin(1, n_targets / 5),  # Cap at 5 targets
        conf_score = avg_confidence,
        clin_score = max_clinical_phase / 4,    # Normalize to 0-1
        act_score = ifelse(is.na(best_activity), 0,
                           pmin(1, 10000 / (best_activity + 1))),  # Better activity = higher score
        
        # Calculate final priority score
        priority_score = round(
          (target_score * 0.2) +
            (conf_score * 0.4) +
            (clin_score * 0.3) +
            (act_score * 0.1), 3),
        
        # Assign priority levels based on percentiles
        priority_level = case_when(
          priority_score >= quantile(priority_score, 0.75, na.rm = TRUE) ~ "High",
          priority_score >= quantile(priority_score, 0.25, na.rm = TRUE) ~ "Medium",
          TRUE ~ "Low"
        ),
        
        # Create readable clinical phase description
        clinical_phase_desc = case_when(
          max_clinical_phase == 0 ~ "Preclinical",
          max_clinical_phase == 1 ~ "Phase I",
          max_clinical_phase == 2 ~ "Phase II",
          max_clinical_phase == 3 ~ "Phase III",
          max_clinical_phase == 4 ~ "Approved",
          is.na(max_clinical_phase) ~ "Unknown",
          TRUE ~ paste("Phase", max_clinical_phase)
        ),
        
        # Format activity display
        activity_display = case_when(
          is.na(best_activity) ~ "Not Available",
          best_activity < 100 ~ paste0(best_activity, " nM (Very Active)"),
          best_activity < 1000 ~ paste0(best_activity, " nM (Active)"),
          best_activity < 10000 ~ paste0(best_activity, " nM (Moderate)"),
          TRUE ~ paste0(best_activity, " nM (Weak)")
        ),
        
        # Clean up activity types
        activity_types = ifelse(activity_types == "" | is.na(activity_types), "Various", activity_types)
      ) %>%
      # Remove intermediate columns and select final columns
      dplyr::select(
        Drug = molecule_name,
        `Priority Level` = priority_level,
        `Priority Score` = priority_score,
        `Target Count` = n_targets,
        `Target Genes` = target_genes,
        `Confidence` = avg_confidence,
        `Clinical Phase` = clinical_phase_desc,
        `Best Activity` = activity_display,
        `Activity Types` = activity_types
      ) %>%
      dplyr::arrange(dplyr::desc(`Priority Score`))
    
    print(paste("Successfully created prioritization for", nrow(prioritization), "unique drugs"))
    print(paste("Priority level distribution:"))
    if (nrow(prioritization) > 0) {
      print(table(prioritization$`Priority Level`))
    }
    
    return(prioritization)
  }
  
