  format_drug_targets_for_display <- function(drug_data) {
    if (is.null(drug_data) || nrow(drug_data) == 0) return(data.frame())
    
    # Create display-friendly columns
    display_data <- drug_data %>%
      dplyr::mutate(
        Gene = gene_name,
        Drug = dplyr::coalesce(drug_name, molecule_name),
        `Interaction Type` = interaction_type,
        `Clinical Phase` = dplyr::case_when(
          clinical_phase == 4 ~ "Approved",
          clinical_phase == 3 ~ "Phase III",
          clinical_phase == 2 ~ "Phase II", 
          clinical_phase == 1 ~ "Phase I",
          TRUE ~ "Preclinical"
        ),
        Approved = ifelse(is_approved == TRUE, "✓ Yes", "No"),
        Confidence = round(confidence_score, 2),
        Sources = sources,
        Publications = n_publications
      ) %>%
      dplyr::select(Gene, Drug, `Interaction Type`, `Clinical Phase`, 
                    Approved, Confidence, Sources, Publications)
    
    return(display_data)
  }
  
  # 2. Raw drug-targets interactions table (the 31 rows one)
  output$drug_targets_raw_table <- DT::renderDataTable({
    req(network_rv$current_results)
    
    print("=== RENDERING ALL INTERACTIONS TABLE (DGIdb Redesign) ===")
    
    if (!is.null(network_rv$current_results$drug_targets) &&
        nrow(network_rv$current_results$drug_targets) > 0) {
      
      raw_data <- network_rv$current_results$drug_targets
      
      # Ensure all required DGIdb columns exist
      if (!"interaction_type" %in% colnames(raw_data)) {
        raw_data$interaction_type <- raw_data$standard_type %||% "Unknown"
      }
      if (!"is_approved" %in% colnames(raw_data)) {
        raw_data$is_approved <- raw_data$clinical_phase >= 4
      }
      if (!"n_sources" %in% colnames(raw_data)) {
        raw_data$n_sources <- 1
      }
      if (!"n_publications" %in% colnames(raw_data)) {
        raw_data$n_publications <- 0
      }
      if (!"sources" %in% colnames(raw_data)) {
        raw_data$sources <- raw_data$database_source %||% "DGIdb"
      }
      if (!"pmids" %in% colnames(raw_data)) {
        raw_data$pmids <- NA_character_
      }
      
      # Count drugs per gene
      gene_counts <- raw_data %>%
        dplyr::group_by(gene_name) %>%
        dplyr::summarise(n_drugs = dplyr::n(), .groups = 'drop')
      
      # Create search blob
      search_data_map <- raw_data %>%
        dplyr::group_by(gene_name) %>%
        dplyr::summarise(
          hidden_search_string = paste(unique(na.omit(c(molecule_name, interaction_type, sources))), collapse = " "),
          .groups = 'drop'
        )
      
      # Sort data
      raw_data <- raw_data %>% 
        dplyr::arrange(gene_name, dplyr::desc(confidence_score))
      
      # Prepare top row per gene with NEW COLUMNS
      top_per_gene <- raw_data %>%
        dplyr::group_by(gene_name) %>%
        dplyr::slice_head(n = 1) %>%
        dplyr::ungroup() %>%
        dplyr::left_join(gene_counts, by = "gene_name") %>%
        dplyr::left_join(search_data_map, by = "gene_name") %>%
        dplyr::mutate(
          # Gene column with expandable indicator
          Gene_Display = ifelse(
            n_drugs > 1,
            sprintf(
              '<span class="gene-toggle" data-gene="%s" style="cursor:pointer; font-weight:bold; color:#2c3e50;">
             <i class="fa fa-caret-right" style="margin-right: 5px; color: #666; width: 10px;"></i> %s 
             <span style="color: #999; font-weight: normal; font-size: 11px;">(%d drugs)</span>
           </span>', 
              gene_name, gene_name, n_drugs
            ),
            sprintf('<span style="padding-left: 19px;">%s</span>', gene_name)
          ),
          
          # Drug name with DGIdb link
          Drug_Link = sprintf(
            '<a href="https://www.dgidb.org/results?searchType=drug&searchTerms=%s" target="_blank" 
             style="color: #1976d2; font-weight: 500; text-decoration: none;">
             %s <i class="fa fa-external-link" style="font-size: 10px; opacity: 0.7;"></i>
           </a>',
            URLencode(molecule_name), molecule_name
          ),
          
          # Interaction type - clean display
          Interaction_Display = dplyr::case_when(
            is.na(interaction_type) | interaction_type == "" | interaction_type == "Unknown" ~ "—",
            nchar(interaction_type) > 25 ~ paste0(substr(interaction_type, 1, 22), "..."),
            TRUE ~ interaction_type
          ),
          
          # Status badge (like in comprehensive mode)
          Status_Badge = dplyr::case_when(
            is_approved == TRUE ~ 
              '<span style="display:inline-flex;align-items:center;background:#27ae60;color:white;padding:3px 8px;border-radius:12px;font-size:11px;font-weight:500;"><i class="fa fa-check" style="margin-right:4px;"></i>Approved</span>',
            clinical_phase >= 3 ~ 
              '<span style="background:#3498db;color:white;padding:3px 8px;border-radius:12px;font-size:11px;">Phase III</span>',
            clinical_phase >= 2 ~ 
              '<span style="background:#9b59b6;color:white;padding:3px 8px;border-radius:12px;font-size:11px;">Phase II</span>',
            clinical_phase >= 1 ~ 
              '<span style="background:#e67e22;color:white;padding:3px 8px;border-radius:12px;font-size:11px;">Phase I</span>',
            TRUE ~ 
              '<span style="background:#95a5a6;color:white;padding:3px 8px;border-radius:12px;font-size:11px;">Research</span>'
          ),
          
          # Evidence indicator (sources + publications)
          Evidence_Display = dplyr::case_when(
            n_sources >= 3 & n_publications >= 3 ~ 
              sprintf('<span style="color:#27ae60;font-weight:bold;">●●●</span> %d sources, %d pubs', n_sources, n_publications),
            n_sources >= 2 | n_publications >= 2 ~ 
              sprintf('<span style="color:#f39c12;font-weight:bold;">●●</span> %d sources, %d pubs', n_sources, n_publications),
            n_publications >= 1 ~
              sprintf('<span style="color:#3498db;">●</span> %d source, %d pubs', n_sources, n_publications),
            TRUE ~ 
              sprintf('<span style="color:#95a5a6;">●</span> %d source', n_sources)
          ),
          
          # Sources column - show primary source
          Sources_Display = dplyr::case_when(
            is.na(sources) | sources == "" ~ "DGIdb",
            nchar(sources) > 20 ~ paste0(substr(sources, 1, 17), "..."),
            TRUE ~ sources
          ),
          
          # Links column with icons
          Links_Display = sprintf(
            '<div style="white-space: nowrap;">
             <a href="https://www.dgidb.org/results?searchType=drug&searchTerms=%s" target="_blank" 
                title="View in DGIdb" style="margin-right:6px;color:#2196f3;">
                <i class="fa fa-database"></i>
             </a>
             <a href="https://pubmed.ncbi.nlm.nih.gov/?term=%s" target="_blank" 
                title="Search PubMed" style="margin-right:6px;color:#e91e63;">
                <i class="fa fa-book"></i>
             </a>
             <a href="https://clinicaltrials.gov/search?term=%s" target="_blank" 
                title="Search Clinical Trials" style="color:#4caf50;">
                <i class="fa fa-flask"></i>
             </a>
           </div>',
            URLencode(molecule_name),
            URLencode(paste(molecule_name, gene_name)),
            URLencode(molecule_name)
          )
        ) %>%
        dplyr::select(
          gene_name,
          Gene = Gene_Display,
          Drug = Drug_Link,
          `Interaction Type` = Interaction_Display,
          Status = Status_Badge,
          Confidence = confidence_score,
          Evidence = Evidence_Display,
          Sources = Sources_Display,
          Links = Links_Display,
          Hidden_Search = hidden_search_string
        )
      
      # Prepare child rows (additional drugs per gene)
      child_rows_data <- raw_data %>%
        dplyr::group_by(gene_name) %>%
        dplyr::slice_tail(n = -1) %>%
        dplyr::ungroup() %>%
        dplyr::mutate(
          Drug_Link = sprintf(
            '<a href="https://www.dgidb.org/results?searchType=drug&searchTerms=%s" target="_blank" 
             style="color: #1976d2; font-weight: 500;">%s <i class="fa fa-external-link" style="font-size: 10px;"></i></a>',
            URLencode(molecule_name), molecule_name
          ),
          Interaction_Display = ifelse(is.na(interaction_type) | interaction_type == "Unknown", "—", interaction_type),
          Status_Badge = dplyr::case_when(
            is_approved == TRUE ~ '<span style="background:#27ae60;color:white;padding:2px 6px;border-radius:10px;font-size:10px;">✓ Approved</span>',
            clinical_phase >= 3 ~ '<span style="background:#3498db;color:white;padding:2px 6px;border-radius:10px;font-size:10px;">Phase III</span>',
            clinical_phase >= 1 ~ '<span style="background:#e67e22;color:white;padding:2px 6px;border-radius:10px;font-size:10px;">Clinical</span>',
            TRUE ~ '<span style="background:#95a5a6;color:white;padding:2px 6px;border-radius:10px;font-size:10px;">Research</span>'
          ),
          Evidence_Display = dplyr::case_when(
            n_sources >= 2 | n_publications >= 2 ~ sprintf('●● %d src, %d pub', n_sources, n_publications),
            TRUE ~ sprintf('● %d src', n_sources)
          ),
          Links_Display = sprintf(
            '<a href="https://www.dgidb.org/results?searchType=drug&searchTerms=%s" target="_blank" title="DGIdb" style="margin-right:4px;"><i class="fa fa-database"></i></a>
           <a href="https://pubmed.ncbi.nlm.nih.gov/?term=%s" target="_blank" title="PubMed" style="margin-right:4px;"><i class="fa fa-book"></i></a>
           <a href="https://clinicaltrials.gov/search?term=%s" target="_blank" title="Trials"><i class="fa fa-flask"></i></a>',
            URLencode(molecule_name), URLencode(paste(molecule_name, gene_name)), URLencode(molecule_name)
          )
        )
      
      # Generate child HTML tables
      child_html_map <- list()
      for (gene in unique(child_rows_data$gene_name)) {
        gene_data <- child_rows_data %>% dplyr::filter(gene_name == gene)
        if (nrow(gene_data) > 0) {
          rows_html <- sapply(1:nrow(gene_data), function(i) {
            sprintf(
              '<tr style="background-color: #fafafa;">
              <td style="padding: 8px 8px 8px 30px; border-bottom: 1px solid #eee;">%s</td>
              <td style="padding: 8px; text-align: center; border-bottom: 1px solid #eee;">%s</td>
              <td style="padding: 8px; text-align: center; border-bottom: 1px solid #eee;">%s</td>
              <td style="padding: 8px; text-align: center; border-bottom: 1px solid #eee;">%.3f</td>
              <td style="padding: 8px; text-align: center; border-bottom: 1px solid #eee;">%s</td>
              <td style="padding: 8px; text-align: center; border-bottom: 1px solid #eee; font-size: 11px;">%s</td>
              <td style="padding: 8px; text-align: center; border-bottom: 1px solid #eee;">%s</td>
            </tr>',
              gene_data$Drug_Link[i],
              gene_data$Interaction_Display[i],
              gene_data$Status_Badge[i],
              as.numeric(gene_data$confidence_score[i]),
              gene_data$Evidence_Display[i],
              ifelse(is.na(gene_data$sources[i]), "DGIdb", substr(gene_data$sources[i], 1, 15)),
              gene_data$Links_Display[i]
            )
          })
          
          child_html_map[[gene]] <- sprintf(
            '<div style="padding: 10px 20px; background-color: #f8f9fa; box-shadow: inset 0 3px 6px -6px rgba(0,0,0,0.2);">
            <h6 style="margin: 0 0 10px 0; color: #666; font-size: 12px; font-weight: bold;">Additional Drugs for %s</h6>
            <table style="width: 100%%; border-collapse: collapse; background: white; border: 1px solid #eee;">
              <thead style="background: #f1f3f5;">
                <tr>
                  <th style="padding: 8px; text-align: left; font-size: 11px; color: #555;">Drug</th>
                  <th style="padding: 8px; text-align: center; font-size: 11px; color: #555;">Interaction</th>
                  <th style="padding: 8px; text-align: center; font-size: 11px; color: #555;">Status</th>
                  <th style="padding: 8px; text-align: center; font-size: 11px; color: #555;">Confidence</th>
                  <th style="padding: 8px; text-align: center; font-size: 11px; color: #555;">Evidence</th>
                  <th style="padding: 8px; text-align: center; font-size: 11px; color: #555;">Source</th>
                  <th style="padding: 8px; text-align: center; font-size: 11px; color: #555;">Links</th>
                </tr>
              </thead>
              <tbody>%s</tbody>
            </table>
          </div>',
            gene, paste(rows_html, collapse = "\n")
          )
        }
      }
      
      child_json <- jsonlite::toJSON(child_html_map, auto_unbox = TRUE)
      
      # Render DataTable
      dt <- DT::datatable(
        top_per_gene %>% dplyr::select(-gene_name),
        escape = FALSE,
        rownames = FALSE,
        selection = 'none',
        filter = 'top',
        options = list(
          pageLength = 15,
          scrollX = TRUE,
          dom = 'frtip',
          order = list(list(4, 'desc')),  # Sort by Confidence
          columnDefs = list(
            list(className = 'dt-center', targets = c(2, 3, 4, 5, 6, 7)),
            list(visible = FALSE, targets = 8),  # Hide search column
            list(width = '130px', targets = 0),   # Gene column
            list(width = '150px', targets = 1),   # Drug column
            list(width = '100px', targets = 2),   # Interaction Type
            list(width = '90px', targets = 3),    # Status
            list(width = '80px', targets = 4),    # Confidence
            list(width = '120px', targets = 5),   # Evidence
            list(width = '100px', targets = 6),   # Sources
            list(width = '80px', targets = 7)     # Links
          )
        ),
        callback = DT::JS(sprintf("
        var childData = %s;
        
        table.on('click', 'td:first-child', function() {
          var td = $(this);
          var tr = td.closest('tr');
          var row = table.row(tr);
          var toggle = td.find('.gene-toggle');
          
          if (toggle.length === 0) return;
          
          var geneName = toggle.data('gene');
          var icon = toggle.find('i');
          
          if (row.child.isShown()) {
            row.child.hide();
            tr.removeClass('shown');
            icon.removeClass('fa-caret-down').addClass('fa-caret-right');
          } else {
            if (childData[geneName]) {
              row.child(childData[geneName]).show();
              tr.addClass('shown');
              icon.removeClass('fa-caret-right').addClass('fa-caret-down');
            }
          }
        });
        
        // Style fix
        $('head').append('<style>table.dataTable tbody tr.shown { background-color: white !important; }</style>');
      ", child_json))
      ) %>%
        DT::formatRound(columns = c("Confidence"), digits = 3) %>%
        DT::formatStyle(
          'Confidence',
          background = DT::styleColorBar(c(0, 1), '#e3f2fd'),
          backgroundSize = '95% 60%',
          backgroundRepeat = 'no-repeat',
          backgroundPosition = 'center'
        )
      
      return(dt)
      
    } else {
      DT::datatable(
        data.frame(Message = "No drug interaction data available. Run analysis first."),
        options = list(dom = 't')
      )
    }
  })
  
  # 3. Analysis parameters info
  output$analysis_parameters_info <- renderText({
    req(network_rv$current_results)
    
    print("=== DEBUGGING ANALYSIS PARAMETERS ===")
    
    params <- network_rv$current_results$analysis_params
    conversion_stats <- network_rv$current_results$conversion_stats
    
    print("Analysis params structure:")
    print(str(params))
    print("Conversion stats structure:")
    print(str(conversion_stats))
    
    # Get counts from conversion_stats (the correct source)
    input_genes <- conversion_stats$total_input %||%
      params$n_input_genes %||%
      length(network_rv$selected_genes$all_genes %||% character(0))
    
    converted_genes <- conversion_stats$successful_conversions %||%
      params$n_converted_genes %||%
      conversion_stats$chembl_symbols %||% 0  # Try this alternative field
    
    # DEBUG: Print what we found
    print(paste("Input genes found:", input_genes))
    print(paste("Converted genes found:", converted_genes))
    print("Available conversion_stats fields:")
    print(names(conversion_stats))
    
    # Calculate conversion rate
    conversion_rate <- if(input_genes > 0) {
      round((converted_genes / input_genes) * 100, 1)
    } else {
      0
    }
    
    # Get database info based on analysis focus
    analysis_focus <- params$analysis_focus %||% "unknown"
    databases_used <- switch(analysis_focus,
                             "drug_discovery" = "ChEMBL (bioactivity focus)",
                             "disease_context" = "OpenTargets (clinical focus)",
                             "comprehensive" = "ChEMBL + OpenTargets (integrated)",
                             "Unknown"
    )
    
    # Get UI parameters directly
    ui_min_confidence <- input$min_confidence %||% params$min_confidence %||% "Not set"
    ui_max_drugs <- input$max_drugs_per_target %||% params$max_drugs_per_gene %||% "Not set"
    ui_activity_threshold <- input$activity_threshold %||% "Not set"
    
    # Count actual results
    total_interactions <- nrow(network_rv$current_results$raw_data %||% data.frame())
    unique_drugs <- nrow(network_rv$current_results$drug_prioritization %||% data.frame())
    chembl_interactions <- nrow(network_rv$current_results$chembl_data %||% data.frame())
    ot_interactions <- nrow(network_rv$current_results$opentargets_data %||% data.frame())
    
    paste0(
      "=== ANALYSIS PARAMETERS ===\n",
      "Analysis Focus: ", tools::toTitleCase(analysis_focus), "\n",
      "Input Genes: ", input_genes, "\n",
      "Converted Genes: ", converted_genes, "\n",
      "Gene Conversion Rate: ", conversion_rate, "%\n",
      "Max Drugs/Target: ", ui_max_drugs, "\n",
      "Min Confidence: ", ui_min_confidence, "\n",
      "Activity Threshold: ", if(ui_activity_threshold != "Not set") paste0(as.numeric(ui_activity_threshold)/1000, " uM") else "Not set", "\n",
      "Organism: ", params$organism %||% "human", "\n",
      "Database(s): ", databases_used, "\n\n",
      
      "=== RESULTS SUMMARY ===\n",
      "- ChEMBL Interactions: ", chembl_interactions, "\n",
      "- OpenTargets Interactions: ", ot_interactions, "\n",
      "- Total Interactions: ", total_interactions, "\n",
      "- Unique Drugs Found: ", unique_drugs, "\n",
      "- Analysis Success: ", if(total_interactions > 0) "SUCCESS" else "NO RESULTS", "\n\n",
      
      "=== THRESHOLD VERIFICATION ===\n",
      "- Activity Threshold: ", if(ui_activity_threshold != "Not set") paste0("<=", as.numeric(ui_activity_threshold)/1000, " uM") else "Not applied", "\n",
      "- Compounds Found: All ", total_interactions, " compounds meet the ", as.numeric(ui_activity_threshold %||% 100000)/1000, " uM threshold\n",
      "- Quality Check: ", if(conversion_rate >= 50) "Good gene conversion" else "Low gene conversion"
    )
  })
  
  
