  create_comprehensive_summary_complete <- function(drug_data, network_data, analysis_focus) {
    
    base_summary <- list(
      analysis_focus = analysis_focus,
      network = list(
        total_nodes = nrow(network_data$nodes),
        total_edges = nrow(network_data$edges),
        network_density = ifelse(nrow(network_data$nodes) > 1,
                                 nrow(network_data$edges) / (nrow(network_data$nodes) * (nrow(network_data$nodes) - 1) / 2), 0)
      ),
      total_drugs = length(unique(drug_data$molecule_name)),
      total_targets = length(unique(drug_data$gene_name)),
      total_interactions = nrow(drug_data)
    )
    
    if (nrow(drug_data) > 0) {
      base_summary$chembl <- list(
        total_interactions = nrow(drug_data),
        unique_drugs = length(unique(drug_data$molecule_name)),
        druggable_targets = length(unique(drug_data$gene_name)),
        high_confidence_interactions = sum(drug_data$confidence_score > 0.7, na.rm = TRUE),
        clinical_stage_drugs = sum(drug_data$clinical_phase > 0, na.rm = TRUE),
        bioactive_drugs = sum(drug_data$standard_value <= 1000, na.rm = TRUE)
      )
      
      # Activity type distribution
      if ("standard_type" %in% colnames(drug_data)) {
        base_summary$activity_types <- table(drug_data$standard_type)
      }
      
      # Clinical phase distribution
      if ("clinical_phase" %in% colnames(drug_data)) {
        base_summary$clinical_phases <- table(drug_data$clinical_phase)
      }
    }
    
    return(base_summary)
  }
  
