  # Create mock ChEMBL data if real function doesn't exist
  
  # Simple network creation function (keep as is)
  create_drug_target_network_simple <- function(drug_data, selected_genes) {
    
    # Create gene nodes
    unique_genes <- unique(drug_data$gene_name)
    gene_nodes <- data.frame(
      id = unique_genes,
      label = unique_genes,
      group = "gene",
      color = ifelse(unique_genes %in% selected_genes$up_genes, "#E74C3C",
                     ifelse(unique_genes %in% selected_genes$down_genes, "#3498DB", "#95A5A6")),
      size = 25,
      title = paste("Target Gene:", unique_genes),
      stringsAsFactors = FALSE
    )
    
    # Create drug nodes
    unique_drugs <- unique(drug_data$molecule_name)
    drug_nodes <- data.frame(
      id = unique_drugs,
      label = unique_drugs,
      group = "drug",
      color = "#F39C12",
      size = 20,
      title = paste("Drug Compound:", unique_drugs),
      stringsAsFactors = FALSE
    )
    
    # Combine nodes
    all_nodes <- rbind(gene_nodes, drug_nodes)
    
    # Create edges
    edges <- drug_data %>%
      dplyr::select(from = molecule_name, to = gene_name, confidence_score) %>% # Explicit dplyr::select
      dplyr::mutate( # Explicit dplyr::mutate
        arrows = "to",
        color = "#7F8C8D",
        width = pmax(1, confidence_score * 3),
        title = paste("Drug-Target Interaction<br>Confidence:", round(confidence_score, 2))
      )
    
    return(list(nodes = all_nodes, edges = edges))
  }
  
  # Multi-database drug-target query function (keep as is)
  get_multi_database_drug_targets <- function(genes, databases, min_confidence, organism) {
    
    print("Querying multiple drug databases...")
    
    all_drug_targets <- data.frame()
    
    for (db in databases) {
      print(paste("Querying", db, "database..."))
      
      db_results <- switch(db,
                           "chembl" = query_chembl_enhanced(genes, min_confidence),
                           "opentargets" = query_opentargets_enhanced(genes, min_confidence),
                           "drugbank" = query_drugbank_enhanced(genes, min_confidence),
                           data.frame()
      )
      
      if (nrow(db_results) > 0) {
        db_results$database_source <- db
        all_drug_targets <- rbind(all_drug_targets, db_results)
      }
    }
    
    # Remove duplicates and standardize
    drug_targets_clean <- all_drug_targets %>%
      dplyr::distinct(gene_name, drug_name, .keep_all = TRUE) %>% # Explicit dplyr::distinct
      dplyr::arrange(desc(confidence_score)) # Explicit dplyr::arrange
    
    print(paste("Found", nrow(drug_targets_clean), "unique drug-target interactions"))
    return(drug_targets_clean)
  }
  
  # Enhanced ChEMBL query with better filtering (keep as is, add explicit httr::, jsonlite::, dplyr::)
  query_chembl_enhanced <- function(genes, min_confidence) {
    
    tryCatch({
      # Use httr to query ChEMBL API
      library(httr)
      library(jsonlite)
      
      all_results <- data.frame()
      
      for (gene in genes[1:min(50, length(genes))]) {  # Limit to prevent timeout
        
        # Query ChEMBL for target information
        target_url <- paste0("https://www.ebi.ac.uk/chembl/api/data/target.json?target_synonym=", gene)
        target_response <- httr::GET(target_url) # Explicit httr::
        
        if (httr::status_code(target_response) == 200) { # Explicit httr::
          target_data <- jsonlite::fromJSON(httr::content(target_response, "text")) # Explicit jsonlite::, httr::
          
          if (length(target_data$targets) > 0) {
            target_id <- target_data$targets$target_chembl_id[1]
            
            # Query for activities
            activity_url <- paste0("https://www.ebi.ac.uk/chembl/api/data/activity.json?target_chembl_id=",
                                   target_id, "&limit=100")
            activity_response <- httr::GET(activity_url) # Explicit httr::
            
            if (httr::status_code(activity_response) == 200) { # Explicit httr::
              activity_data <- jsonlite::fromJSON(httr::content(activity_response, "text")) # Explicit jsonlite::, httr::
              
              if (length(activity_data$activities) > 0) {
                activities <- activity_data$activities
                
                # Process activities
                gene_results <- data.frame(
                  gene_name = gene,
                  target_chembl_id = target_id,
                  drug_name = activities$molecule_chembl_id,
                  drug_chembl_id = activities$molecule_chembl_id,
                  activity_type = activities$standard_type,
                  activity_value = as.numeric(activities$standard_value),
                  activity_units = activities$standard_units,
                  confidence_score = calculate_chembl_confidence(activities),
                  clinical_phase = get_clinical_phase_chembl(activities$molecule_chembl_id),
                  stringsAsFactors = FALSE
                )
                
                # Filter by confidence
                gene_results <- gene_results %>%
                  dplyr::filter(confidence_score >= min_confidence) %>% # Explicit dplyr::filter
                  dplyr::slice_head(n = 10)  # Explicit dplyr::slice_head
                
                all_results <- rbind(all_results, gene_results)
              }
            }
          }
        }
        
        # Add small delay to be respectful to API
        Sys.sleep(0.1)
      }
      
      return(all_results)
      
    }, error = function(e) {
      print(paste("Error querying ChEMBL:", e$message))
      return(data.frame())
    })
  }
  
  # Enhanced OpenTargets query (keep as is, add explicit httr::, jsonlite::, dplyr::)
  query_opentargets_enhanced <- function(genes, min_confidence) {
    
    tryCatch({
      library(httr)
      library(jsonlite)
      
      all_results <- data.frame()
      
      for (gene in genes[1:min(30, length(genes))]) {  # Limit for API efficiency
        
        # Query OpenTargets GraphQL API
        query <- sprintf('
        query {
          target(ensemblId: "%s") {
            id
            approvedSymbol
            knownDrugs {
              uniqueDrugs
              rows {
                drug {
                  id
                  name
                  drugType
                  maximumClinicalTrialPhase
                  hasBeenWithdrawn
                }
                mechanismOfAction
                targets {
                  id
                  approvedSymbol
                }
                diseaseFromSource
                clinicalTrial {
                  phase
                  status
                }
              }
            }
          }
        }
      ', gene)
        
        response <- httr::POST( # Explicit httr::
          url = "https://api.platform.opentargets.org/api/v4/graphql",
          body = list(query = query),
          encode = "json",
          httr::add_headers("Content-Type" = "application/json") # Explicit httr::
        )
        
        if (httr::status_code(response) == 200) { # Explicit httr::
          data <- jsonlite::fromJSON(httr::content(response, "text")) # Explicit jsonlite::, httr::
          
          if (!is.null(data$data$target$knownDrugs$rows)) {
            drugs_data <- data$data$target$knownDrugs$rows
            
            gene_results <- data.frame(
              gene_name = gene,
              drug_name = drugs_data$drug$name,
              drug_id = drugs_data$drug$id,
              drug_type = drugs_data$drug$drugType,
              mechanism_of_action = drugs_data$mechanismOfAction,
              clinical_phase = drugs_data$drug$maximumClinicalTrialPhase,
              is_withdrawn = drugs_data$drug$hasBeenWithdrawn,
              confidence_score = calculate_opentargets_confidence(drugs_data),
              disease_indication = drugs_data$diseaseFromSource,
              stringsAsFactors = FALSE
            )
            
            # Filter and clean
            gene_results <- gene_results %>%
              dplyr::filter(confidence_score >= min_confidence, # Explicit dplyr::filter
                            !is_withdrawn) %>%
              dplyr::slice_head(n = 8) # Explicit dplyr::slice_head
            
            all_results <- rbind(all_results, gene_results)
          }
        }
        
        Sys.sleep(0.1)  # API rate limiting
      }
      
      return(all_results)
      
    }, error = function(e) {
      print(paste("Error querying OpenTargets:", e$message))
      return(data.frame())
    })
  }
  
  # Add regulatory context to drug targets (keep as is, add explicit dplyr::)
  add_regulatory_context <- function(drug_targets, selected_genes) {
    
    print("Adding regulatory context to drug targets...")
    
    tryCatch({
      # Get TF-target relationships for druggable targets
      library(dorothea)
      data("dorothea_hs", package = "dorothea")
      
      druggable_genes <- unique(drug_targets$gene_name)
      
      # Find TFs that regulate our druggable targets
      tf_regulations <- dorothea_hs %>%
        dplyr::filter(confidence >= 0.6) %>% # Explicit dplyr::filter
        dplyr::filter(target %in% druggable_genes) %>% # Explicit dplyr::filter
        dplyr::select(tf, target, mor, confidence) %>% # Explicit dplyr::select
        dplyr::rename(gene_name = target, regulation_type = mor) # Explicit dplyr::rename
      
      # Add this to drug targets
      drug_targets_with_regulation <- drug_targets %>%
        dplyr::left_join(tf_regulations, by = "gene_name") %>% # Explicit dplyr::left_join
        dplyr::mutate( # Explicit dplyr::mutate
          has_tf_regulation = !is.na(tf),
          regulation_strength = ifelse(is.na(confidence.y), 0, confidence.y)
        )
      
      # Identify master regulators affecting multiple drug targets
      master_regulators <- tf_regulations %>%
        dplyr::group_by(tf) %>% # Explicit dplyr::group_by
        dplyr::summarise( # Explicit dplyr::summarise
          n_druggable_targets = n(),
          avg_confidence = mean(confidence),
          targets = paste(gene_name, collapse = "; "),
          .groups = 'drop'
        ) %>%
        dplyr::filter(n_druggable_targets >= 2) %>% # Explicit dplyr::filter
        dplyr::arrange(desc(n_druggable_targets)) # Explicit dplyr::arrange
      
      return(list(
        drug_targets_with_regulation = drug_targets_with_regulation,
        master_regulators = master_regulators,
        tf_regulations = tf_regulations
      ))
      
    }, error = function(e) {
      print(paste("Error adding regulatory context:", e$message))
      return(NULL)
    })
  }
  
  # Add disease associations (keep as is, add explicit httr::, jsonlite::)
  add_disease_context <- function(drug_targets, selected_genes) {
    
    print("Adding disease context...")
    
    tryCatch({
      # Query DisGeNET for disease associations
      library(httr)
      
      druggable_genes <- unique(drug_targets$gene_name)
      disease_associations <- data.frame()
      
      for (gene in druggable_genes[1:min(20, length(druggable_genes))]) {
        
        # Query DisGeNET API
        url <- paste0("https://www.disgenet.org/api/gda/gene/", gene)
        response <- httr::GET(url, httr::add_headers("Authorization" = paste("Bearer", Sys.getenv("DISGENET_API_KEY")))) # Explicit httr::
        
        if (httr::status_code(response) == 200) { # Explicit httr::
          gene_diseases <- jsonlite::fromJSON(httr::content(response, "text")) # Explicit jsonlite::, httr::
          
          if (length(gene_diseases) > 0) {
            gene_disease_df <- data.frame(
              gene_name = gene,
              disease_id = gene_diseases$disease_id,
              disease_name = gene_diseases$disease_name,
              disease_score = gene_diseases$score,
              disease_type = gene_diseases$disease_type,
              stringsAsFactors = FALSE
            )
            
            disease_associations <- rbind(disease_associations, gene_disease_df)
          }
        }
        
        Sys.sleep(0.1)
      }
      
      return(disease_associations)
      
    }, error = function(e) {
      print(paste("Error adding disease context:", e$message))
      return(data.frame())
    })
  }
  
  # Create comprehensive network visualization (keep as is, add explicit dplyr::)
  create_comprehensive_drug_network <- function(drug_targets, selected_genes,
                                                regulatory_context = NULL, disease_context = NULL) {
    
    print("Creating comprehensive drug-target network...")
    
    # Create gene nodes
    gene_nodes <- data.frame(
      id = unique(drug_targets$gene_name),
      label = unique(drug_targets$gene_name),
      group = "gene",
      color = ifelse(unique(drug_targets$gene_name) %in% selected_genes$up_genes,
                     "#E74C3C", "#3498DB"),
      size = 25,
      shape = "dot",
      title = paste("Target Gene:", unique(drug_targets$gene_name)),
      stringsAsFactors = FALSE
    )
    
    # Create drug nodes
    drug_nodes <- drug_targets %>%
      dplyr::group_by(molecule_name) %>% # Explicit dplyr::group_by # Changed from drug_name to molecule_name
      dplyr::summarise( # Explicit dplyr::summarise
        n_targets = n(),
        max_clinical_phase = max(clinical_phase_numeric, na.rm = TRUE),
        avg_confidence = mean(confidence_score, na.rm = TRUE),
        .groups = 'drop'
      ) %>%
      dplyr::mutate( # Explicit dplyr::mutate
        id = molecule_name, # Changed from drug_name to molecule_name
        label = molecule_name, # Changed from drug_name to molecule_name
        group = "drug",
        color = dplyr::case_when( # Explicit dplyr::case_when
          max_clinical_phase >= 4 ~ "#27AE60",  # Approved
          max_clinical_phase >= 2 ~ "#F39C12",  # Clinical trials
          TRUE ~ "#95A5A6"                       # Preclinical
        ),
        size = 15 + (n_targets * 2),
        shape = "square",
        title = paste("Drug:", molecule_name, # Changed to molecule_name
                      "<br>Targets:", n_targets,
                      "<br>Phase:", max_clinical_phase,
                      "<br>Confidence:", round(avg_confidence, 2))
      ) %>%
      dplyr::select(id, label, group, color, size, shape, title) # Explicit dplyr::select
    
    # Add TF nodes if regulatory context available
    tf_nodes <- data.frame()
    if (!is.null(regulatory_context) && !is.null(regulatory_context$master_regulators)) {
      tf_nodes <- regulatory_context$master_regulators %>%
        dplyr::slice_head(n = 10) %>% # Explicit dplyr::slice_head
        dplyr::mutate( # Explicit dplyr::mutate
          id = tf,
          label = tf,
          group = "tf",
          color = "#9B59B6",
          size = 20 + (n_druggable_targets * 3),
          shape = "triangle",
          title = paste("Transcription Factor:", tf,
                        "<br>Druggable Targets:", n_druggable_targets,
                        "<br>Avg Confidence:", round(avg_confidence, 2))
        ) %>%
        dplyr::select(id, label, group, color, size, shape, title) # Explicit dplyr::select
    }
    
    # Combine all nodes
    all_nodes <- rbind(gene_nodes, drug_nodes, tf_nodes)
    
    # Create edges
    drug_target_edges <- drug_targets %>%
      dplyr::select(from = molecule_name, to = gene_name, confidence_score, clinical_phase) %>% # Changed from drug_name to molecule_name # Explicit dplyr::select
      dplyr::mutate( # Explicit dplyr::mutate
        arrows = "to",
        color = "#34495E",
        width = confidence_score * 3,
        title = paste("Drug-Target Interaction",
                      "<br>Confidence:", round(confidence_score, 2),
                      "<br>Clinical Phase:", clinical_phase)
      )
    
    # Add TF-target edges if available
    tf_edges <- data.frame()
    if (!is.null(regulatory_context) && !is.null(regulatory_context$tf_regulations)) {
      tf_edges <- regulatory_context$tf_regulations %>%
        dplyr::filter(tf %in% tf_nodes$id) %>% # Explicit dplyr::filter
        dplyr::select(from = tf, to = gene_name, confidence, regulation_type) %>% # Explicit dplyr::select
        dplyr::mutate( # Explicit dplyr::mutate
          arrows = "to",
          color = dplyr::case_when(regulation_type == 1 ~ "#27AE60", TRUE ~ "#E74C3C"), # Explicit dplyr::case_when
          width = confidence * 2,
          dashes = TRUE,
          title = paste("TF Regulation:",
                        ifelse(regulation_type == 1, "Activation", "Repression"),
                        "<br>Confidence:", round(confidence, 2))
        )
    }
    
    # Combine all edges
    all_edges <- rbind(
      drug_target_edges[, intersect(names(drug_target_edges), names(tf_edges))],
      tf_edges[, intersect(names(drug_target_edges), names(tf_edges))]
    )
    
    return(list(nodes = all_nodes, edges = all_edges))
  }
  
  # Comprehensive drug prioritization (keep as is, add explicit dplyr::)
  prioritize_drugs_comprehensive <- function(drug_targets, regulatory_context = NULL,
                                             disease_context = NULL, selected_genes) {
    
    print("Performing comprehensive drug prioritization...")
    
    drug_scores <- drug_targets %>%
      dplyr::group_by(molecule_name) %>% # Changed from drug_name to molecule_name # Explicit dplyr::group_by
      dplyr::summarise( # Explicit dplyr::summarise
        n_targets = n(),
        avg_confidence = mean(confidence_score, na.rm = TRUE),
        max_clinical_phase = max(clinical_phase, na.rm = TRUE),
        target_list = paste(gene_name, collapse = "; "),
        .groups = 'drop'
      ) %>%
      dplyr::mutate( # Explicit dplyr::mutate
        # Base scoring
        target_score = log2(n_targets + 1),
        confidence_score = avg_confidence,
        clinical_score = max_clinical_phase / 4,
        
        # Combined base score
        base_score = (target_score + confidence_score + clinical_score) / 3
      )
    
    # Add regulatory context scoring
    if (!is.null(regulatory_context)) {
      regulatory_scores <- drug_targets %>%
        dplyr::filter(!is.na(tf)) %>% # Explicit dplyr::filter
        dplyr::group_by(molecule_name) %>% # Changed to molecule_name # Explicit dplyr::group_by
        dplyr::summarise( # Explicit dplyr::summarise
          n_regulated_targets = n(),
          avg_regulation_strength = mean(regulation_strength, na.rm = TRUE),
          .groups = 'drop'
        ) %>%
        dplyr::mutate( # Explicit dplyr::mutate
          regulatory_score = (log2(n_regulated_targets + 1) + avg_regulation_strength) / 2
        )
      
      drug_scores <- drug_scores %>%
        dplyr::left_join(regulatory_scores, by = c("molecule_name" = "molecule_name")) %>% # Changed to molecule_name # Explicit dplyr::left_join
        dplyr::mutate( # Explicit dplyr::mutate
          regulatory_score = ifelse(is.na(regulatory_score), 0, regulatory_score)
        )
    } else {
      drug_scores$regulatory_score <- 0
    }
    
    # Add disease relevance scoring
    if (!is.null(disease_context) && nrow(disease_context) > 0) {
      disease_scores <- drug_targets %>%
        dplyr::left_join(disease_context, by = "gene_name") %>% # Explicit dplyr::left_join
        dplyr::filter(!is.na(disease_score)) %>% # Explicit dplyr::filter
        dplyr::group_by(molecule_name) %>% # Changed to molecule_name # Explicit dplyr::group_by
        dplyr::summarise( # Explicit dplyr::summarise
          n_disease_targets = n(),
          avg_disease_score = mean(disease_score, na.rm = TRUE),
          .groups = 'drop'
        ) %>%
        dplyr::mutate( # Explicit dplyr::mutate
          disease_relevance_score = (log2(n_disease_targets + 1) + avg_disease_score) / 2
        )
      
      drug_scores <- drug_scores %>%
        dplyr::left_join(disease_scores, by = c("molecule_name" = "molecule_name")) %>% # Changed to molecule_name # Explicit dplyr::left_join
        dplyr::mutate( # Explicit dplyr::mutate
          disease_relevance_score = ifelse(is.na(disease_relevance_score), 0, disease_relevance_score)
        )
    } else {
      drug_scores$disease_relevance_score <- 0
    }
    
    # Calculate final priority score
    drug_scores <- drug_scores %>%
      dplyr::mutate( # Explicit dplyr::mutate
        final_priority_score = (base_score * 0.4) +
          (regulatory_score * 0.3) +
          (disease_relevance_score * 0.3),
        priority_rank = rank(-final_priority_score)
      ) %>%
      dplyr::arrange(desc(final_priority_score)) # Explicit dplyr::arrange
    
    # Rename molecule_name to drug_name for consistency in output
    drug_scores <- drug_scores %>%
      dplyr::rename(drug_name = molecule_name)
    
    return(drug_scores)
  }
  
  # Calculate comprehensive metrics (keep as is)
  calculate_drug_target_metrics <- function(drug_targets, network_data, drug_prioritization) {
    
    metrics <- list(
      # Basic counts
      total_drugs = length(unique(drug_targets$molecule_name)), # Changed from drug_name
      total_targets = length(unique(drug_targets$gene_name)),
      total_interactions = nrow(drug_targets),
      
      # Network metrics
      network_density = nrow(network_data$edges) / (nrow(network_data$nodes) * (nrow(network_data$nodes) - 1) / 2),
      avg_targets_per_drug = mean(table(drug_targets$molecule_name)), # Changed from drug_name
      avg_drugs_per_target = mean(table(drug_targets$gene_name)),
      
      # Clinical phase distribution
      clinical_phase_dist = table(drug_targets$clinical_phase),
      
      # Top prioritized drugs
      top_10_drugs = head(drug_prioritization$drug_name, 10),
      
      # Database coverage
      database_coverage = table(drug_targets$database_source)
    )
    
    return(metrics)
  }
  
