  get_target_genes_for_enrichment <- function(nodes, selected_genes) {
    # Method 1: Get targets based on regulation column (current approach)
    regulated_by_column <- nodes$id[nodes$type == "Target" &
                                      nodes$regulation %in% c("Up", "Down")]
    
    # Method 2: Get targets based on group assignment (visual grouping)
    regulated_by_group <- nodes$id[nodes$type == "Target" &
                                     nodes$group %in% c("upregulated", "downregulated")]
    
    # Method 3: Get ALL DEG targets regardless of TF regulation
    all_deg_targets <- nodes$id[nodes$type == "Target" &
                                  nodes$id %in% c(selected_genes$up_genes,
                                                  selected_genes$down_genes)]
    
    # Combine all methods to get the most comprehensive list
    all_regulated_targets <- unique(c(regulated_by_column,
                                      regulated_by_group,
                                      all_deg_targets))
    
    print(paste("Target gene selection for enrichment:"))
    print(paste("  • By regulation column:", length(regulated_by_column)))
    print(paste("  • By group assignment:", length(regulated_by_group)))
    print(paste("  • All DEG targets:", length(all_deg_targets)))
    print(paste("  • Combined total:", length(all_regulated_targets)))
    
    return(all_regulated_targets)
  }
  
  create_grn_nodes_fixed <- function(all_nodes, tfs_in_data, converted_genes) {
    
    nodes <- data.frame(
      id = all_nodes,
      label = all_nodes,
      type = ifelse(all_nodes %in% tfs_in_data, "TF", "Target"),
      stringsAsFactors = FALSE
    )
    
    # Better regulation assignment
    nodes$regulation <- "None"  # Default
    
    # For TFs: check if they're in DEG list
    tf_mask <- nodes$type == "TF"
    nodes$regulation[tf_mask & nodes$id %in% converted_genes$up_genes] <- "Up"
    nodes$regulation[tf_mask & nodes$id %in% converted_genes$down_genes] <- "Down"
    
    # For Targets: check if they're in DEG list OR targeted by TFs
    target_mask <- nodes$type == "Target"
    nodes$regulation[target_mask & nodes$id %in% converted_genes$up_genes] <- "Up"
    nodes$regulation[target_mask & nodes$id %in% converted_genes$down_genes] <- "Down"
    
    # Count regulated nodes
    print(paste("Node regulation assignment:"))
    print(paste("  • TFs Up:", sum(nodes$type == "TF" & nodes$regulation == "Up")))
    print(paste("  • TFs Down:", sum(nodes$type == "TF" & nodes$regulation == "Down")))
    print(paste("  • Targets Up:", sum(nodes$type == "Target" & nodes$regulation == "Up")))
    print(paste("  • Targets Down:", sum(nodes$type == "Target" & nodes$regulation == "Down")))
    print(paste("  • Unregulated:", sum(nodes$regulation == "None")))
    
    return(nodes)
  }
  
  # Helper functions for confidence calculation (keep as is)
  calculate_chembl_confidence <- function(activities) {
    # Simplified confidence calculation based on activity type and value
    confidence <- ifelse(
      activities$standard_type %in% c("IC50", "EC50", "Ki", "Kd"),
      pmin(1, 1 / (1 + log10(as.numeric(activities$standard_value) + 1))),
      0.5
    )
    return(pmax(0.1, confidence))
  }
  
  calculate_opentargets_confidence <- function(drugs_data) {
    # Confidence based on clinical phase and drug type
    phase_score <- (drugs_data$drug$maximumClinicalTrialPhase + 1) / 5
    type_score <- ifelse(drugs_data$drug$drugType == "Small molecule", 0.8, 0.6)
    return(pmin(1, phase_score * type_score))
  }
  
  get_clinical_phase_chembl <- function(molecule_ids) {
    # Simplified - in practice you'd query ChEMBL for clinical trial data
    return(sample(0:4, length(molecule_ids), replace = TRUE, prob = c(0.4, 0.2, 0.2, 0.1, 0.1)))
  }
  
  get_grn_regulations_hybrid <- function(selected_genes, organism, min_confidence = 0.6) {
    
    print(paste("🧬 Hybrid GRN regulation lookup for:", organism))
    
    # Define which organisms use which database
    dorothea_organisms <- c("human", "mouse")
    tflink_organisms <- c("rat", "zebrafish", "fly", "celegans", "yeast")
    
    if (organism %in% dorothea_organisms) {
      print("📊 Using DoRothEA (premium quality)")
      
      # ✅ CALL YOUR EXISTING DOROTHEA FUNCTION
      return(get_tf_target_regulations_fixed(
        selected_genes = selected_genes,
        organism = organism,
        database = "dorothea",
        min_confidence = min_confidence
      ))
      
    } else if (organism %in% tflink_organisms) {
      print("🔗 Using TFLink (comprehensive coverage)")
      
      # ✅ CALL NEW TFLINK FUNCTION (but return same format as DoRothEA)
      return(get_tflink_regulations_compatible(
        selected_genes = selected_genes,
        organism = organism,
        min_confidence = min_confidence
      ))
      
    } else {
      # Unsupported organism
      supported <- c(dorothea_organisms, tflink_organisms)
      stop(paste("GRN analysis supports:", paste(supported, collapse = ", "),
                 "\nRequested organism:", organism))
    }
  }
  
  
  
  get_dorothea_regulations_enhanced <- function(selected_genes, organism, min_confidence) {
    
    tryCatch({
      # Your existing DoRothEA code, but enhanced with additional metadata
      if (organism == "human") {
        data("dorothea_hs", package = "dorothea", envir = environment())
        dorothea_data <- get("dorothea_hs", envir = environment())
      } else if (organism == "mouse") {
        data("dorothea_mm", package = "dorothea", envir = environment())
        dorothea_data <- get("dorothea_mm", envir = environment())
      }
      
      # Enhanced confidence scoring
      confidence_map <- c("A" = 0.95, "B" = 0.85, "C" = 0.7, "D" = 0.5, "E" = 0.3)
      dorothea_data$confidence_numeric <- confidence_map[dorothea_data$confidence]
      
      tf_regulations <- dorothea_data %>%
        filter(
          confidence_numeric >= min_confidence,
          target %in% selected_genes | tf %in% selected_genes
        ) %>%
        select(tf, target, confidence = confidence_numeric, mor) %>%
        mutate(
          database_source = "DoRothEA",
          evidence_level = case_when(
            confidence >= 0.9 ~ "Very High",
            confidence >= 0.8 ~ "High",
            confidence >= 0.6 ~ "Medium",
            TRUE ~ "Low"
          ),
          regulation_type = ifelse(mor == 1, "Activation", "Repression")
        ) %>%
        distinct()
      
      print(paste("✅ DoRothEA:", nrow(tf_regulations), "high-quality regulations"))
      return(tf_regulations)
      
    }, error = function(e) {
      print(paste("❌ DoRothEA error:", e$message))
      return(data.frame())
    })
  }
  
  # ==============================================================================
  # 3. SMART TFLINK FUNCTION WITH INTELLIGENT CACHING
  # ==============================================================================
  
  get_tflink_regulations_compatible <- function(selected_genes, organism, min_confidence) {
    
    # This function downloads TFLink data and converts it to the exact same format
    # that your existing DoRothEA function returns, so the rest of your code works unchanged
    
    organism_mapping <- c(
      "rat" = "Rattus_norvegicus",
      "zebrafish" = "Danio_rerio",
      "fly" = "Drosophila_melanogaster",
      "celegans" = "Caenorhabditis_elegans",
      "yeast" = "Saccharomyces_cerevisiae"
    )
    
    if (!organism %in% names(organism_mapping)) {
      stop(paste("TFLink organism not supported:", organism))
    }
    
    tflink_organism <- organism_mapping[organism]
    
    # Smart caching system
    cache_dir <- file.path(getwd(), "grn_cache")
    if (!dir.exists(cache_dir)) dir.create(cache_dir, recursive = TRUE)
    
    cache_file <- file.path(cache_dir, paste0("tflink_", organism, "_processed.rds"))
    
    # Check cache (update weekly)
    use_cache <- FALSE
    if (file.exists(cache_file)) {
      file_age <- difftime(Sys.Date(), file.info(cache_file)$mtime, units = "days")
      if (file_age < 7) {
        print("📂 Loading processed TFLink data from cache...")
        all_regulations <- readRDS(cache_file)
        use_cache <- TRUE
      }
    }
    
    if (!use_cache) {
      print("🌐 Downloading and processing fresh TFLink data...")
      all_regulations <- download_and_process_tflink_compatible(tflink_organism, organism)
      
      if (!is.null(all_regulations) && nrow(all_regulations) > 0) {
        saveRDS(all_regulations, cache_file)
        print(paste("💾 Cached processed data:", nrow(all_regulations), "regulations"))
      } else {
        print("⚠️  Failed to download TFLink data, returning empty dataset")
        return(data.frame(tf = character(0), target = character(0),
                          confidence = numeric(0), mor = numeric(0)))
      }
    }
    
    # Filter for user's genes and confidence - SAME AS DOROTHEA
    tf_regulations <- all_regulations %>%
      filter(
        (tf %in% selected_genes | target %in% selected_genes),
        confidence >= min_confidence
      ) %>%
      distinct()
    
    print(paste("✅ TFLink: filtered to", nrow(tf_regulations), "regulations"))
    
    # ✅ RETURN EXACT SAME FORMAT AS YOUR DOROTHEA FUNCTION
    return(tf_regulations)
  }
  
  # ==============================================================================
  # 4. TFLINK DOWNLOAD AND PROCESSING FUNCTION
  # ==============================================================================
  
  download_and_process_tflink_compatible <- function(tflink_organism, organism) {
    
    tryCatch({
      # TFLink download URL - try small-scale first (higher quality)
      urls_to_try <- c(
        paste0("https://tflink.net/download/dirolTFLinkSS_", tflink_organism, ".tsv"),
        paste0("https://tflink.net/download/dirolTFLink_", tflink_organism, ".tsv")
      )
      
      tflink_data <- NULL
      
      for (url in urls_to_try) {
        print(paste("📥 Trying:", basename(url)))
        
        temp_file <- tempfile(fileext = ".tsv")
        
        tryCatch({
          download.file(url, temp_file, mode = "wb", quiet = TRUE)
          
          tflink_data <- read.table(temp_file, sep = "\t", header = TRUE,
                                    stringsAsFactors = FALSE, quote = "",
                                    fill = TRUE, comment.char = "")
          
          if (nrow(tflink_data) > 100) {
            print(paste("✅ Downloaded:", nrow(tflink_data), "interactions"))
            break
          }
          
        }, error = function(e) {
          print(paste("❌ Failed:", e$message))
        })
        
        unlink(temp_file)
      }
      
      if (is.null(tflink_data) || nrow(tflink_data) == 0) {
        print("❌ All TFLink downloads failed")
        return(data.frame())
      }
      
      # Process into DoRothEA-compatible format
      print("🔄 Converting to DoRothEA-compatible format...")
      print(paste("TFLink columns:", paste(colnames(tflink_data), collapse = ", ")))
      
      # Find TF and target columns (flexible naming)
      tf_col <- intersect(c("Name.TF", "TF.Name", "Transcription.Factor", "TF"), colnames(tflink_data))[1]
      target_col <- intersect(c("Name.target", "Target.Name", "Target.Gene", "Target"), colnames(tflink_data))[1]
      source_col <- intersect(c("Source.database", "Database", "Source"), colnames(tflink_data))[1]
      
      if (is.na(tf_col) || is.na(target_col)) {
        print("❌ Essential columns not found")
        return(data.frame())
      }
      
      # Convert to DoRothEA format: tf, target, confidence, mor
      processed_data <- tflink_data %>%
        filter(
          !is.na(get(tf_col)) & get(tf_col) != "",
          !is.na(get(target_col)) & get(target_col) != ""
        ) %>%
        mutate(
          tf = get(tf_col),
          target = get(target_col),
          # Assign confidence based on source database
          confidence = case_when(
            !is.na(source_col) & grepl("DoRothEA|TRRUST", get(source_col), ignore.case = TRUE) ~ 0.8,
            !is.na(source_col) & grepl("GTRD|ReMap", get(source_col), ignore.case = TRUE) ~ 0.7,
            TRUE ~ 0.6
          ),
          # TFLink doesn't have mode of regulation, default to activation
          mor = 1
        ) %>%
        select(tf, target, confidence, mor) %>%
        distinct()
      
      print(paste("🎯 Processed", nrow(processed_data), "DoRothEA-compatible regulations"))
      return(processed_data)
      
    }, error = function(e) {
      print(paste("❌ TFLink processing error:", e$message))
      return(data.frame())
    })
  }
  
  validate_grn_organism_hybrid <- function(organism) {
    
    supported_organisms <- list(
      "Premium (DoRothEA)" = c("human", "mouse"),
      "Standard (TFLink)" = c("rat", "zebrafish", "fly", "celegans", "yeast")
    )
    
    all_supported <- unlist(supported_organisms)
    
    if (!organism %in% all_supported) {
      return(list(
        supported = FALSE,
        message = paste("GRN analysis supports:", paste(all_supported, collapse = ", "),
                        "\nRequested:", organism),
        alternatives = c("human", "mouse", "rat")
      ))
    }
    
    # Determine quality level
    quality <- if (organism %in% supported_organisms$`Premium (DoRothEA)`) "Premium" else "Standard"
    
    return(list(
      supported = TRUE,
      quality = quality,
      database = if (quality == "Premium") "DoRothEA" else "TFLink",
      message = paste("✅", organism, "supported via",
                      if (quality == "Premium") "DoRothEA" else "TFLink")
    ))
  }
  
