  # 7. UI ENHANCEMENTS FOR HYBRID SYSTEM
  # ==============================================================================
  
  create_organism_quality_indicator <- function(organism) {
    validation <- validate_grn_organism_hybrid(organism)
    
    if (!validation$supported) {
      return(
        div(class = "alert alert-warning",
            "⚠️ GRN analysis not available for this organism")
      )
    }
    
    if (validation$quality == "Premium") {
      return(
        div(class = "alert alert-success",
            style = "padding: 8px; margin: 5px 0;",
            HTML("🏆 <strong>Premium Quality:</strong> DoRothEA database with detailed confidence levels and regulation direction"))
      )
    } else {
      return(
        div(class = "alert alert-info",
            style = "padding: 8px; margin: 5px 0;",
            HTML("🌐 <strong>Standard Quality:</strong> TFLink database with comprehensive multi-organism coverage"))
      )
    }
  }
  
  
