  enhance_grn_results_display <- function(tf_regulations) {
    
    if (is.null(tf_regulations) || nrow(tf_regulations) == 0) {
      return("No data available")
    }
    
    # Check data source
    is_dorothea <- "DoRothEA" %in% tf_regulations$database_source
    is_tflink <- "TFLink" %in% tf_regulations$database_source
    
    # Create enhanced summary based on source
    summary_info <- list()
    
    if (is_dorothea) {
      summary_info$quality <- "Premium (DoRothEA)"
      summary_info$features <- c(
        "Confidence levels A-E",
        "Regulation direction (activation/repression)",
        "Extensively curated",
        "High-confidence interactions"
      )
    } else if (is_tflink) {
      summary_info$quality <- "Standard (TFLink)"
      summary_info$features <- c(
        "Multi-database integration",
        "Broad organism coverage",
        "Experimental evidence tracking",
        "Cross-species comparisons"
      )
    }
    
    # Enhanced statistics
    stats <- list(
      total_regulations = nrow(tf_regulations),
      unique_tfs = length(unique(tf_regulations$tf)),
      unique_targets = length(unique(tf_regulations$target)),
      avg_confidence = round(mean(tf_regulations$confidence, na.rm = TRUE), 3)
    )
    
    if ("regulation_type" %in% colnames(tf_regulations)) {
      reg_breakdown <- table(tf_regulations$regulation_type)
      stats$activations <- reg_breakdown["Activation"] %||% 0
      stats$repressions <- reg_breakdown["Repression"] %||% 0
    }
    
    return(list(summary = summary_info, statistics = stats))
  }
  
