  run_grn_analysis_corrected <- function(selected_genes, expression_data = NULL, organism = "human",
                                         tf_database = "dorothea", confidence_level = 0.6,
                                         min_tf_edges = 2, calculate_activities = TRUE,
                                         run_enrichment = TRUE, check_druggability = TRUE,
                                         max_master_regulators = 100) {
    
    print("=== STARTING GRN ANALYSIS (CORRECTED) ===")
    print(paste("🚀 Organism:", organism))
    print(paste("📊 Input genes:", length(selected_genes$all_genes)))
    print(paste("🗂️ TF Database:", tf_database))
    print(paste("📈 Confidence level:", confidence_level))
    
    # Debug expression data
    if (!is.null(expression_data)) {
      print(paste("📊 Expression data dimensions:", nrow(expression_data), "x", ncol(expression_data)))
    } else {
      print("⚠️ Expression data is NULL - will proceed without expression-based filtering")
    }
    
    # Validate organism support
    dorothea_organisms <- c("human", "mouse")
    tflink_organisms <- c("rat", "zebrafish", "fly", "celegans", "yeast")
    supported_organisms <- c(dorothea_organisms, tflink_organisms)
    
    if (!tolower(organism) %in% supported_organisms) {
      error_msg <- paste("GRN analysis only supports:", paste(supported_organisms, collapse = ", "),
                         ". Current organism:", organism)
      print(paste("❌", error_msg))
      return(list(error = error_msg))
    }
    # Show which database will be used
    database_used <- if (organism %in% dorothea_organisms) "DoRothEA (Premium)" else "TFLink (Standard)"
    print(paste("🗄️ Database selection:", database_used))
    
    
    # Validate input genes
    if (is.null(selected_genes) || length(selected_genes$all_genes) == 0) {
      error_msg <- "No genes selected for GRN analysis"
      print(paste("❌", error_msg))
      return(list(error = error_msg))
    }
    
    tryCatch({
      
      # Step 1: Convert genes to appropriate format for the organism
      print("🔄 Step 1: Converting gene IDs...")
      gene_conversion <- convert_genes_for_grn(selected_genes$all_genes, organism)
      
      if (length(gene_conversion$symbols) == 0) {
        error_msg <- "No valid genes after ID conversion. Check if your gene IDs are in the correct format."
        print(paste("❌", error_msg))
        return(list(error = error_msg))
      }
      
      print(paste("✅ Converted", length(gene_conversion$symbols), "genes successfully"))
      
      # Create converted gene structure
      converted_genes <- list(
        all_genes = gene_conversion$symbols,
        up_genes = intersect(gene_conversion$symbols,
                             convert_genes_for_grn(selected_genes$up_genes, organism)$symbols),
        down_genes = intersect(gene_conversion$symbols,
                               convert_genes_for_grn(selected_genes$down_genes, organism)$symbols)
      )
      
      print(paste("📊 Converted genes breakdown:"))
      print(paste("  • Up-regulated:", length(converted_genes$up_genes)))
      print(paste("  • Down-regulated:", length(converted_genes$down_genes)))
      print(paste("  • Total:", length(converted_genes$all_genes)))
      
      # Step 2: Get TF-target regulations (organism-specific)
      print("🔍 Step 2: Getting TF-target regulations...")
      tf_regulations <- tryCatch({
        
        # 🎯 THIS IS THE ONLY CHANGE - USE HYBRID FUNCTION
        get_grn_regulations_hybrid(
          selected_genes = converted_genes$all_genes,
          organism = organism,
          min_confidence = confidence_level
        )
      }, error = function(e) {
        print(paste("❌ Error getting TF regulations:", e$message))
        NULL
      })
      
      if (is.null(tf_regulations) || nrow(tf_regulations) == 0) {
        error_msg <- paste("No TF-target regulations found for", organism,
                           "genes. Try lowering the confidence threshold or check if your genes are recognized TFs/targets.")
        print(paste("⚠️", error_msg))
        return(list(error = error_msg))
      }
      
      print(paste("✅ Found", nrow(tf_regulations), "TF-target regulations"))
      
      # Step 3: Identify TFs in the dataset
      print("👑 Step 3: Identifying transcription factors...")
      all_tfs <- unique(tf_regulations$tf)
      tfs_in_data <- intersect(all_tfs, converted_genes$all_genes)
      
      print(paste("✅ Found", length(tfs_in_data), "TFs in your gene list"))
      
      if (length(tfs_in_data) == 0) {
        print("⚠️ No TFs found in your gene list, using all TFs from regulations")
        tfs_in_data <- all_tfs[1:min(20, length(all_tfs))]  # Use top 20 TFs
      }
      
      # Step 4: Build network data
      print("🔗 Step 4: Building network structure...")
      
      # Create edges (TF -> target relationships).
      # Preserve `mor` from DoRothEA so fix_grn_network_data can colour
      # activations green and repressions red downstream. For TFLink-based
      # analyses (non-human/mouse), mor is hardcoded to +1 in the loader and
      # all edges will render as activations — that is a database limitation,
      # not a rendering bug.
      tf_regs_filtered <- tf_regulations %>%
        filter(tf %in% tfs_in_data | target %in% converted_genes$all_genes)

      edges <- data.frame(
        from = tf_regs_filtered$tf,
        to = tf_regs_filtered$target,
        confidence = tf_regs_filtered$confidence,
        interaction_type = "regulates",
        stringsAsFactors = FALSE
      )
      if ("mor" %in% colnames(tf_regs_filtered)) {
        edges$mor <- tf_regs_filtered$mor
      }
      rm(tf_regs_filtered)
      
      if (nrow(edges) == 0) {
        error_msg <- "No regulatory interactions found after filtering"
        print(paste("❌", error_msg))
        return(list(error = error_msg))
      }
      
      print(paste("✅ Created", nrow(edges), "network edges"))
      
      min_edges_per_tf <- if (!is.null(min_tf_edges)) min_tf_edges else 2
      
      # Count connections per TF
      tf_edge_counts <- table(edges$from)
      low_connection_tfs <- names(tf_edge_counts)[tf_edge_counts < min_edges_per_tf]
      
      # Store pre-filter stats
      original_edge_count <- nrow(edges)
      original_tf_count <- length(unique(edges$from))
      
      if (length(low_connection_tfs) > 0 && min_edges_per_tf > 1) {
        print(paste("🧹 Filtering TFs with <", min_edges_per_tf, "connections"))
        print(paste("   Removing", length(low_connection_tfs), "TFs"))
        
        edges <- edges %>% filter(!from %in% low_connection_tfs)
        
        print(paste("   Before: TFs =", original_tf_count, ", Edges =", original_edge_count))
        print(paste("   After:  TFs =", length(unique(edges$from)), ", Edges =", nrow(edges)))
      } else {
        print(paste("✅ Keeping all TFs (minimum threshold:", min_edges_per_tf, ")"))
      }
      
      # Create nodes
      all_nodes <- unique(c(edges$from, edges$to))
      # nodes <- data.frame(
      #   id = all_nodes,
      #   label = all_nodes,
      #   type = ifelse(all_nodes %in% tfs_in_data, "TF", "Target"),
      #   regulation = case_when(
      #     all_nodes %in% converted_genes$up_genes ~ "Up",
      #     all_nodes %in% converted_genes$down_genes ~ "Down",
      #     TRUE ~ "None"
      #   ),
      #   stringsAsFactors = FALSE
      # )
      
      nodes <- create_grn_nodes_fixed(all_nodes, tfs_in_data, converted_genes)
      
      
      print(paste("✅ Created", nrow(nodes), "network nodes"))
      print(paste("  • TFs:", sum(nodes$type == "TF")))
      print(paste("  • Targets:", sum(nodes$type == "Target")))
      
      # OPTIONAL: Network quality diagnostics
      # ===================================================================
      # n_nodes <- nrow(nodes)
      # n_edges <- nrow(edges)
      # max_possible_edges <- n_nodes * (n_nodes - 1)
      # network_density <- n_edges / max_possible_edges
      # 
      # print(paste("📊 Network Density:", round(network_density, 4)))
      # 
      # if (network_density > 0.5) {
      #   recommended_conf <- round(min(1.0, confidence_level + 0.1), 2)
      #   print("⚠️  WARNING: Network is VERY DENSE (>50% of possible edges)")
      #   print(paste("   → Recommendation: Increase confidence threshold to", recommended_conf))
      # } else if (network_density < 0.01) {
      #   recommended_conf <- round(max(0.1, confidence_level - 0.1), 2)
      #   print("⚠️  WARNING: Network is VERY SPARSE (<1% of possible edges)")
      #   print(paste("   → Recommendation: Decrease confidence threshold to", recommended_conf))
      # } else {
      #   print("✅ Network density is optimal")
      # }
      # 
      # # Average degree (connectivity)
      # avg_degree <- mean(nodes$degree_total, na.rm = TRUE)
      # print(paste("📊 Average Node Degree:", round(avg_degree, 2)))
      # 
      # if (avg_degree < 2) {
      #   print("⚠️  Many isolated nodes - consider lowering confidence threshold")
      # } else if (avg_degree > 10) {
      #   print("⚠️  Highly connected network - consider increasing confidence threshold")
      # }
      
      # Step 5: Calculate network statistics
      print("📊 Step 5: Calculating network statistics...")
      
      # Calculate degree for each node
      degree_in <- table(edges$to)
      degree_out <- table(edges$from)
      nodes$degree_in <- as.numeric(degree_in[nodes$id])
      nodes$degree_out <- as.numeric(degree_out[nodes$id])
      nodes$degree_in[is.na(nodes$degree_in)] <- 0
      nodes$degree_out[is.na(nodes$degree_out)] <- 0
      nodes$degree_total <- nodes$degree_in + nodes$degree_out
      
      # Calculate Master Regulators with Advanced Scoring
      master_regulators <- nodes %>%
        filter(type == "TF") %>%
        arrange(desc(degree_out))
      
      # Apply advanced scoring
      master_regulators <- calculate_advanced_master_score(
        tf_data = master_regulators,
        tf_regulations = tf_regulations,
        selected_genes = converted_genes
      )
      
      # Add regulatory type classification
      master_regulators <- master_regulators %>%
        mutate(
          regulatory_role = case_when(
            regulation == "Up" & degree_out >= 5 ~ "Major Activator",
            regulation == "Down" & degree_out >= 5 ~ "Major Repressor",
            regulation == "Up" ~ "Activator",
            regulation == "Down" ~ "Repressor",
            TRUE ~ "Mixed Regulator"
          ),
          clinical_relevance = label %in% c(
            # Common druggable TFs - expand this list as needed
            "ESR1", "AR", "PPARG", "PPARA", "NR3C1", "RARA", "RXRA",
            "HIF1A", "STAT3", "STAT1", "NFE2L2", "TP53", "MYC", "NFKB1",
            "RELA", "CREB1", "JUN", "FOS", "EGR1", "SP1", "GATA3"
          )
        ) %>%
        head(max_master_regulators)  # Honour the user-set slider (default 20)
      
      print(paste("✅ Identified", nrow(master_regulators), "master regulators with advanced scoring"))
      
      # Step 6: Prepare final results
      print("📦 Step 6: Preparing final results...")
      debug_target_gene_selection(nodes, selected_genes)
      
      tf_pathway_enrichment <- NULL
      target_pathway_enrichment <- NULL

      if (isTRUE(run_enrichment)) {
        print("🛤️ Step 6.5: Running TF pathway enrichment...")
        tf_pathway_enrichment <- perform_tf_pathway_enrichment_fixed(
          tf_list = master_regulators$label,
          organism = organism
        )

        if ("type" %in% colnames(nodes) && "regulation" %in% colnames(nodes)) {
          target_genes <- nodes$id[nodes$type == "Target" &
                                     (nodes$regulation == "Up" | nodes$regulation == "Down")]
        } else if ("group" %in% colnames(nodes)) {
          target_genes <- nodes$id[nodes$group %in% c("upregulated", "downregulated")]
        } else {
          target_genes <- c(selected_genes$up_genes, selected_genes$down_genes)
          target_genes <- target_genes[!is.na(target_genes)]
        }

        print(paste("🎯 Selected", length(target_genes), "target genes for enrichment"))

        target_pathway_enrichment <- perform_target_gene_enrichment_fixed(
          target_genes = target_genes,
          organism = organism
        )
      } else {
        print("⏭️ Pathway enrichment skipped (run_enrichment = FALSE)")
      }
      
      print("⚡ Step 6.7: Calculating TF activities...")
      tf_activities <- NULL
      
      # Only run if the user requested it AND expression data is available
      if (calculate_activities && !is.null(expression_data)) {
        print("📊 Expression data available and user requested activities - calculating...")
        
        filter_deg_tfs_only <- input$grn_filter_deg_tfs_only %||% FALSE
        
        tf_activities <- calculate_tf_activities_fixed_final(
          expression_data = expression_data,
          tf_regulations = tf_regulations,
          selected_genes = converted_genes,
          filter_to_degs = filter_deg_tfs_only,
          organism = organism,
          confidence_level = confidence_level,
          tf_database = tf_database
        )
        
        if (!is.null(tf_activities)) {
          print(paste("✅ TF activities calculated for", 
                      length(unique(tf_activities$tf)), "TFs"))
        } else {
          print("⚠️ TF activity calculation returned NULL")
        }
      } else {
        print("ℹ️ No expression data - skipping TF activity calculation")
      }
      
      
      grn_standalone_rv$expression_data <- expression_data
      grn_standalone_rv$converted_genes <- converted_genes
      grn_standalone_rv$selected_genes <- selected_genes
      grn_standalone_rv$tf_regulations <- tf_regulations
      
      druggability_info <- NULL
      if (isTRUE(check_druggability)) {
        druggability_info <- tryCatch({
          if (nrow(master_regulators) > 0) {
            check_druggability_chembl(master_regulators$label)
          } else {
            NULL
          }
        }, error = function(e) {
          print(paste("⚠️ ChEMBL druggability check failed:", e$message))
          check_druggability_fallback(master_regulators$label)
        })
      } else {
        print("⏭️ ChEMBL druggability check skipped")
        if (nrow(master_regulators) > 0) {
          druggability_info <- check_druggability_fallback(master_regulators$label)
        }
      }
      
      # Store both in results
      results <- list(
        network_data = list(nodes = nodes, edges = edges),
        tf_regulations = tf_regulations,
        master_regulators = master_regulators,
        tf_pathway_enrichment = tf_pathway_enrichment,
        target_pathway_enrichment = target_pathway_enrichment,
        tf_activities = tf_activities,
        druggability_info = druggability_info,
        analysis_params = list(
          organism = organism,
          tf_database = tf_database,
          confidence_level = confidence_level,
          n_input_genes = length(selected_genes$all_genes),
          n_converted_genes = length(converted_genes$all_genes),
          n_tfs = length(tfs_in_data),
          n_targets = sum(nodes$type == "Target"),
          n_regulations = nrow(edges),
          conversion_rate = length(converted_genes$all_genes) / length(selected_genes$all_genes)
        ),
        # summary_stats = list(
        #   n_nodes = nrow(nodes),
        #   n_edges = nrow(edges),
        #   n_tfs = length(tfs_in_data),
        #   n_master_regulators = nrow(master_regulators),
        #   avg_degree = mean(nodes$degree_total),
        #   max_out_degree = max(nodes$degree_out)
        # )
        summary_stats = generate_grn_summary_stats(nodes, edges, selected_genes)
        #print(summary_stats$summary_text)
      )
      
      print("✅ GRN analysis completed successfully!")
      print(paste("📊 Network summary:"))
      print(paste("  • Nodes:", results$summary_stats$n_nodes))
      print(paste("  • Edges:", results$summary_stats$n_edges))
      print(paste("  • Master TFs:", results$summary_stats$n_master_regulators))
      
      return(results)
      
    }, error = function(e) {
      error_msg <- paste("GRN analysis failed:", e$message)
      print(paste("❌", error_msg))
      print("📋 Traceback:")
      print(traceback())
      return(list(error = error_msg))
    })
  }
  
  fix_node_groups <- function(nodes, selected_genes) {
    print("🔧 Ensuring consistent node group assignment...")
    
    # First, establish base groups
    if (!"group" %in% colnames(nodes)) {
      nodes$group <- case_when(
        nodes$type == "TF" ~ "tf",
        TRUE ~ "target"
      )
    }
    
    # Now update non-TF nodes with regulation information
    if (!is.null(selected_genes)) {
      up_genes <- selected_genes$up_genes %||% c()
      down_genes <- selected_genes$down_genes %||% c()
      
      # Update target nodes to upregulated/downregulated
      if (length(up_genes) > 0) {
        target_up_mask <- (nodes$group == "target" | nodes$type == "Target") &
          (nodes$id %in% up_genes)
        nodes$group[target_up_mask] <- "upregulated"
        nodes$regulation[target_up_mask] <- "Up"  # Also update regulation column
        print(paste("🔧 Assigned", sum(target_up_mask), "upregulated targets"))
      }
      
      if (length(down_genes) > 0) {
        target_down_mask <- (nodes$group == "target" | nodes$type == "Target") &
          (nodes$id %in% down_genes)
        nodes$group[target_down_mask] <- "downregulated"
        nodes$regulation[target_down_mask] <- "Down"  # Also update regulation column
        print(paste("🔧 Assigned", sum(target_down_mask), "downregulated targets"))
      }
    }
    
    # Final verification
    print("🔧 Final node distribution:")
    print(paste("Groups:", paste(names(table(nodes$group)), "=", table(nodes$group), collapse = ", ")))
    if ("regulation" %in% colnames(nodes)) {
      print(paste("Regulation:", paste(names(table(nodes$regulation, useNA = "always")), "=",
                                       table(nodes$regulation, useNA = "always"), collapse = ", ")))
    }
    
    return(nodes)
  }
  
  
  debug_target_gene_selection <- function(nodes, selected_genes) {
    
    print("=== DEBUG TARGET GENE SELECTION ===")
    print(paste("Total nodes:", nrow(nodes)))
    print(paste("Node columns:", paste(colnames(nodes), collapse = ", ")))
    
    if ("type" %in% colnames(nodes)) {
      print("Node types:")
      print(table(nodes$type))
    }
    
    if ("regulation" %in% colnames(nodes)) {
      print("Node regulations:")
      print(table(nodes$regulation, useNA = "always"))
    }
    
    if ("group" %in% colnames(nodes)) {
      print("Node groups:")
      print(table(nodes$group, useNA = "always"))
    }
    
    # Method 1: Original automatic method
    if ("type" %in% colnames(nodes) && "regulation" %in% colnames(nodes)) {
      target_genes_auto <- nodes$id[nodes$type == "Target" &
                                      (nodes$regulation == "Up" | nodes$regulation == "Down")]
      print(paste("Method 1 (auto):", length(target_genes_auto), "genes"))
      print(paste("Method 1 first 10:", paste(head(target_genes_auto, 10), collapse = ", ")))
    }
    
    # Method 2: Group-based method
    if ("group" %in% colnames(nodes)) {
      target_genes_group <- nodes$id[nodes$group %in% c("upregulated", "downregulated")]
      print(paste("Method 2 (group):", length(target_genes_group), "genes"))
      print(paste("Method 2 first 10:", paste(head(target_genes_group, 10), collapse = ", ")))
    }
    
    # Method 3: From original selected_genes
    if (!is.null(selected_genes)) {
      original_degs <- c(selected_genes$up_genes, selected_genes$down_genes)
      original_degs <- original_degs[!is.na(original_degs)]
      print(paste("Method 3 (original):", length(original_degs), "genes"))
      print(paste("Method 3 first 10:", paste(head(original_degs, 10), collapse = ", ")))
      
      # Check intersection with network
      network_genes <- nodes$id
      intersection_genes <- intersect(original_degs, network_genes)
      print(paste("Intersection with network:", length(intersection_genes), "genes"))
    }
    
    print("=== END DEBUG TARGET GENE SELECTION ===")
  }
  
  debug_target_gene_counts <- function(network_rv) {
    if (is.null(network_rv$grn_results$network_data)) return()
    
    nodes <- network_rv$grn_results$network_data$nodes
    
    cat("\n=== NETWORK TARGET GENE COUNT VERIFICATION ===\n")
    cat("Total nodes:", nrow(nodes), "\n")
    
    if ("group" %in% colnames(nodes)) {
      group_table <- table(nodes$group)
      cat("Node groups:\n")
      for(g in names(group_table)) {
        cat("  ", g, ":", group_table[g], "\n")
      }
      
      target_genes_manual <- nodes$id[nodes$group %in% c("upregulated", "downregulated")]
      cat("Target genes (manual method):", length(target_genes_manual), "\n")
    }
    
    if ("type" %in% colnames(nodes) && "regulation" %in% colnames(nodes)) {
      target_genes_auto <- nodes$id[nodes$type == "Target" &
                                      (nodes$regulation == "Up" | nodes$regulation == "Down")]
      cat("Target genes (automatic method):", length(target_genes_auto), "\n")
    }
    
    cat("=== END VERIFICATION ===\n\n")
  }
  
  
  create_filtered_drug_target_network <- function(chembl_results, selected_genes, filters) {
    
    print("Creating filtered drug-target network...")
    
    if (nrow(chembl_results) == 0) {
      return(list(nodes = data.frame(), edges = data.frame()))
    }
    
    # Apply max_drugs_per_gene at network level too (double-check)
    max_drugs <- filters$max_drugs_per_gene %||% 1000
    
    # Group by gene and ensure we don't exceed max drugs per gene
    filtered_results <- chembl_results %>%
      dplyr::group_by(gene_name) %>% # Explicit dplyr::group_by
      dplyr::arrange(desc(confidence_score), standard_value) %>% # Explicit dplyr::arrange
      dplyr::slice_head(n = max_drugs) %>% # Explicit dplyr::slice_head
      dplyr::ungroup() # Explicit dplyr::ungroup
    
    print(paste("Network level filtering: reduced from", nrow(chembl_results),
                "to", nrow(filtered_results), "interactions"))
    
    # Create drug nodes
    drug_nodes <- filtered_results %>%
      dplyr::group_by(compound_chembl_id) %>% # Explicit dplyr::group_by
      dplyr::summarise( # Explicit dplyr::summarise
        interactions = n(),
        avg_confidence = mean(confidence_score, na.rm = TRUE),
        best_activity = min(standard_value, na.rm = TRUE),
        .groups = 'drop'
      ) %>%
      dplyr::mutate( # Explicit dplyr::mutate
        id = paste0("drug_", compound_chembl_id),
        label = compound_chembl_id,
        type = "drug",
        group = "drug",
        color = "#3498db",
        size = pmax(20, pmin(50, interactions * 3 + 15)),
        title = paste("Drug:", compound_chembl_id,
                      "<br>Interactions:", interactions,
                      "<br>Avg Confidence:", round(avg_confidence, 2),
                      "<br>Best Activity:", round(best_activity, 2))
      )
    
    # Create gene nodes
    gene_nodes <- filtered_results %>%
      dplyr::group_by(gene_name) %>% # Explicit dplyr::group_by
      dplyr::summarise( # Explicit dplyr::summarise
        drug_count = n_distinct(compound_chembl_id),
        total_interactions = n(),
        avg_confidence = mean(confidence_score, na.rm = TRUE),
        .groups = 'drop'
      ) %>%
      dplyr::mutate( # Explicit dplyr::mutate
        id = paste0("gene_", gene_name),
        label = gene_name,
        type = "gene",
        group = "gene",
        regulation = dplyr::case_when( # Explicit dplyr::case_when
          gene_name %in% selected_genes$up_genes ~ "up",
          gene_name %in% selected_genes$down_genes ~ "down",
          TRUE ~ "unchanged"
        ),
        color = dplyr::case_when( # Explicit dplyr::case_when
          regulation == "up" ~ "#e74c3c",
          regulation == "down" ~ "#2ecc71",
          TRUE ~ "#95a5a6"
        ),
        size = pmax(25, pmin(60, drug_count * 4 + 20)),
        title = paste("Gene:", gene_name,
                      "<br>Regulation:", stringr::str_to_title(regulation),
                      "<br>Drug Count:", drug_count, "/", max_drugs, "(max)",
                      "<br>Avg Confidence:", round(avg_confidence, 2))
      )
    
    # Combine nodes
    all_nodes <- rbind(
      drug_nodes %>% dplyr::select(id, label, type, group, color, size, title), # Explicit dplyr::select
      gene_nodes %>% dplyr::select(id, label, type, group, color, size, title) # Explicit dplyr::select
    )
    
    # Create edges
    edges <- filtered_results %>%
      dplyr::mutate( # Explicit dplyr::mutate
        from = paste0("drug_", compound_chembl_id),
        to = paste0("gene_", gene_name)
      ) %>%
      dplyr::select( # Explicit dplyr::select
        from, to,
        activity_type = standard_type,
        activity_value = standard_value,
        units = standard_units,
        confidence_score
      ) %>%
      dplyr::mutate( # Explicit dplyr::mutate
        title = paste("Activity:", activity_type,
                      "<br>Value:", round(activity_value, 2), units,
                      "<br>Confidence:", round(confidence_score, 2)),
        arrows = "to",
        color = "#7f8c8d",
        width = 1 + (confidence_score * 2)  # Width based on confidence
      )
    
    return(list(nodes = all_nodes, edges = edges))
  }
  
  calculate_network_density <- function(nodes, edges) {
    
    
    n_nodes <- nrow(nodes)
    n_edges <- nrow(edges)
    
    if (n_nodes <= 1) return(0)
    
    max_edges <- n_nodes * (n_nodes - 1) / 2
    return(n_edges / max_edges)
  }
  
