  safe_notification <- function(message, type = "message", duration = 5) {
    
    
    tryCatch({
      if (exists("showNotification")) {
        showNotification(message, type = type, duration = duration)
      } else {
        # Fallback for non-Shiny environments
        cat(paste0("[", toupper(type), "] ", message, "\n"))
      }
    }, error = function(e) {
      cat(paste0("[NOTIFICATION ERROR] ", message, "\n"))
    })
  }
  
