  # This function can handle ANY input gene ID type and convert to both symbols and ENSEMBL IDs
  universal_gene_id_converter <- function(gene_ids, organism = "human") {
    
    print("=== UNIVERSAL GENE ID CONVERTER ===")
    print(paste("Processing", length(gene_ids), "gene IDs for comprehensive analysis"))
    
    if (length(gene_ids) == 0) {
      return(list(
        symbols = character(0),
        ensembl_ids = character(0),
        conversion_stats = list(total_input = 0, successful_symbols = 0, successful_ensembl = 0)
      ))
    }
    
    # Step 1: Clean gene IDs (remove suffixes like "_red vs green")
    cleaned_ids <- clean_gene_ids(gene_ids)
    print(paste("Cleaned sample:", paste(head(cleaned_ids, 3), collapse = ", ")))
    
    # Step 2: Detect all gene ID types
    id_types <- detect_all_gene_id_types(cleaned_ids)
    print_id_type_summary(id_types)
    
    # Step 3: Convert all types to symbols and ENSEMBL IDs
    conversion_results <- convert_all_id_types(cleaned_ids, id_types, organism)
    
    # Step 4: Combine and deduplicate results
    final_symbols <- unique(conversion_results$symbols[!is.na(conversion_results$symbols) & conversion_results$symbols != ""])
    final_ensembl <- unique(conversion_results$ensembl_ids[!is.na(conversion_results$ensembl_ids) & conversion_results$ensembl_ids != ""])
    
    print("=== CONVERSION SUMMARY ===")
    print(paste("Input genes:", length(gene_ids)))
    print(paste("Final symbols for ChEMBL:", length(final_symbols)))
    print(paste("Final ENSEMBL IDs for OpenTargets:", length(final_ensembl)))
    print(paste("Symbol sample:", paste(head(final_symbols, 3), collapse = ", ")))
    print(paste("ENSEMBL sample:", paste(head(final_ensembl, 3), collapse = ", ")))
    
    return(list(
      symbols = final_symbols,
      ensembl_ids = final_ensembl,
      original_ids = gene_ids,
      cleaned_ids = cleaned_ids,
      conversion_stats = list(
        total_input = length(gene_ids),
        successful_symbols = length(final_symbols),
        successful_ensembl = length(final_ensembl),
        id_type_breakdown = id_types
      )
    ))
  }
  
  # ============================================================================
  # HELPER FUNCTIONS FOR UNIVERSAL CONVERSION
  # ============================================================================
  
  clean_gene_ids <- function(gene_ids) {
    cleaned <- sapply(gene_ids, function(x) {
      if (is.na(x) || x == "") return("")
      
      # Remove common contaminations
      x <- gsub("_.*vs.*", "", x, ignore.case = TRUE)  # Remove "_red vs green" etc.
      x <- gsub("_up$|_down$|_high$|_low$", "", x, ignore.case = TRUE)  # Remove direction indicators
      x <- gsub("\\.[0-9]+$", "", x)  # Remove version numbers (.1, .2, etc.)
      x <- gsub("_.*", "", x)  # Remove any remaining suffixes
      x <- trimws(x)  # Remove whitespace
      
      return(x)
    })
    
    return(as.character(cleaned))
  }
  
  detect_all_gene_id_types <- function(cleaned_ids) {
    
    # Comprehensive patterns for all gene ID types
    patterns <- list(
      # ENSEMBL patterns
      ensg_human = grepl("^ENSG[0-9]{11}$", cleaned_ids),
      ensg_mouse = grepl("^ENSMUSG[0-9]{11}$", cleaned_ids),
      enst_human = grepl("^ENST[0-9]{11}$", cleaned_ids),
      enst_mouse = grepl("^ENSMUST[0-9]{11}$", cleaned_ids),
      
      # Entrez IDs (pure numbers)
      entrez = grepl("^[0-9]+$", cleaned_ids),
      
      # Gene symbols (letters, numbers, hyphens)
      symbols = grepl("^[A-Z][A-Za-z0-9-]*$", cleaned_ids) &
        !grepl("^ENS", cleaned_ids) &
        !grepl("^[0-9]+$", cleaned_ids),
      
      # RefSeq patterns
      refseq_nm = grepl("^NM_[0-9]+$", cleaned_ids),
      refseq_nr = grepl("^NR_[0-9]+$", cleaned_ids),
      refseq_xm = grepl("^XM_[0-9]+$", cleaned_ids),
      
      # UniProt patterns
      uniprot = grepl("^[A-Z][0-9][A-Z0-9]{3}[0-9]$|^[A-Z][0-9][A-Z0-9]{3}[0-9]-[0-9]+$", cleaned_ids),
      
      # Other formats
      mixed_case = grepl("^[a-z]", cleaned_ids),  # Lowercase starting (might be symbols)
      unknown = rep(FALSE, length(cleaned_ids))
    )
    
    # Mark unknown/unmatched IDs
    all_matched <- Reduce(`|`, patterns[1:(length(patterns)-1)])
    patterns$unknown <- !all_matched & cleaned_ids != ""
    
    # Count each type
    counts <- lapply(patterns, sum)
    
    return(list(
      patterns = patterns,
      counts = counts,
      total = length(cleaned_ids)
    ))
  }
  
  print_id_type_summary <- function(id_types) {
    print("=== DETECTED GENE ID TYPES ===")
    for (name in names(id_types$counts)) {
      count <- id_types$counts[[name]]
      if (count > 0) {
        print(paste(name, ":", count, "IDs"))
      }
    }
  }
  
  convert_all_id_types <- function(cleaned_ids, id_types, organism) {
    
    print("=== CONVERTING ALL ID TYPES ===")
    
    # Initialize result vectors
    result_symbols <- character(length(cleaned_ids))
    result_ensembl <- character(length(cleaned_ids))
    
    patterns <- id_types$patterns
    
    # 1. Handle ENSEMBL Gene IDs (ENSG) - Already have ENSEMBL, need symbols
    if (any(patterns$ensg_human) || any(patterns$ensg_mouse)) {
      ensg_indices <- patterns$ensg_human | patterns$ensg_mouse
      ensg_ids <- cleaned_ids[ensg_indices]
      
      print(paste("Converting", sum(ensg_indices), "ENSEMBL gene IDs..."))
      
      # Keep ENSEMBL IDs as-is
      result_ensembl[ensg_indices] <- ensg_ids
      
      # Convert to symbols
      converted_symbols <- convert_ensembl_to_symbols_robust(ensg_ids, organism)
      result_symbols[ensg_indices] <- converted_symbols
    }
    
    # 2. Handle ENSEMBL Transcript IDs (ENST) - Need both gene IDs and symbols
    if (any(patterns$enst_human) || any(patterns$enst_mouse)) {
      enst_indices <- patterns$enst_human | patterns$enst_mouse
      enst_ids <- cleaned_ids[enst_indices]
      
      print(paste("Converting", sum(enst_indices), "ENSEMBL transcript IDs..."))
      
      # Convert transcripts to gene IDs and symbols
      transcript_results <- convert_transcripts_to_genes_robust(enst_ids, organism)
      result_ensembl[enst_indices] <- transcript_results$ensembl_ids
      result_symbols[enst_indices] <- transcript_results$symbols
    }
    
    # 3. Handle Entrez IDs - Need both symbols and ENSEMBL
    if (any(patterns$entrez)) {
      entrez_indices <- patterns$entrez
      entrez_ids <- cleaned_ids[entrez_indices]
      
      print(paste("Converting", sum(entrez_indices), "Entrez IDs..."))
      
      entrez_results <- convert_entrez_to_symbols_and_ensembl_robust(entrez_ids, organism)
      result_symbols[entrez_indices] <- entrez_results$symbols
      result_ensembl[entrez_indices] <- entrez_results$ensembl_ids
    }
    
    # 4. Handle Gene Symbols - Already have symbols, need ENSEMBL
    if (any(patterns$symbols) || any(patterns$mixed_case)) {
      symbol_indices <- patterns$symbols | patterns$mixed_case
      symbol_ids <- cleaned_ids[symbol_indices]
      
      print(paste("Converting", sum(symbol_indices), "gene symbols..."))
      
      # Keep symbols as-is (but clean them)
      result_symbols[symbol_indices] <- clean_gene_symbols(symbol_ids)
      
      # Convert to ENSEMBL
      converted_ensembl <- convert_symbols_to_ensembl_efficient(symbol_ids, organism)
      result_ensembl[symbol_indices] <- converted_ensembl
    }
    
    # 5. Handle RefSeq IDs
    if (any(patterns$refseq_nm) || any(patterns$refseq_nr) || any(patterns$refseq_xm)) {
      refseq_indices <- patterns$refseq_nm | patterns$refseq_nr | patterns$refseq_xm
      refseq_ids <- cleaned_ids[refseq_indices]
      
      print(paste("Converting", sum(refseq_indices), "RefSeq IDs..."))
      
      refseq_results <- convert_refseq_to_symbols_and_ensembl_robust(refseq_ids, organism)
      result_symbols[refseq_indices] <- refseq_results$symbols
      result_ensembl[refseq_indices] <- refseq_results$ensembl_ids
    }
    
    # 6. Handle UniProt IDs
    if (any(patterns$uniprot)) {
      uniprot_indices <- patterns$uniprot
      uniprot_ids <- cleaned_ids[uniprot_indices]
      
      print(paste("Converting", sum(uniprot_indices), "UniProt IDs..."))
      
      uniprot_results <- convert_uniprot_to_symbols_and_ensembl_robust(uniprot_ids, organism)
      result_symbols[uniprot_indices] <- uniprot_results$symbols
      result_ensembl[uniprot_indices] <- uniprot_results$ensembl_ids
    }
    
    # 7. Handle unknown IDs (fallback)
    if (any(patterns$unknown)) {
      unknown_indices <- patterns$unknown
      unknown_ids <- cleaned_ids[unknown_indices]
      
      print(paste("Creating fallback for", sum(unknown_indices), "unknown IDs..."))
      
      # Create fallback symbols and ENSEMBL IDs
      result_symbols[unknown_indices] <- unknown_ids
      result_ensembl[unknown_indices] <- NA_character_  # unmapped; never invent IDs
    }
    
    return(list(
      symbols = result_symbols,
      ensembl_ids = result_ensembl
    ))
  }
  
  # ============================================================================
  # ROBUST CONVERSION FUNCTIONS FOR EACH ID TYPE
  # ============================================================================
  
  convert_ensembl_to_symbols_robust <- function(ensembl_ids, organism) {
    
    if (length(ensembl_ids) == 0) return(character(0))
    
    symbols <- character(length(ensembl_ids))
    
    # Method 1: Try biomaRt
    tryCatch({
      if (requireNamespace("biomaRt", quietly = TRUE)) {
        dataset <- if (organism == "mouse") "mmusculus_gene_ensembl" else "hsapiens_gene_ensembl"
        mart <- biomaRt::useMart("ensembl", dataset = dataset)
        
        results <- biomaRt::getBM(
          attributes = c("ensembl_gene_id", "external_gene_name"),
          filters = "ensembl_gene_id",
          values = ensembl_ids,
          mart = mart
        )
        
        # Map back to original order
        for (i in seq_along(ensembl_ids)) {
          matches <- results$external_gene_name[results$ensembl_gene_id == ensembl_ids[i]]
          if (length(matches) > 0 && !is.na(matches[1]) && matches[1] != "") {
            symbols[i] <- matches[1]
          }
        }
        
        success_count <- sum(symbols != "")
        if (success_count > 0) {
          print(paste("biomaRt: Successfully converted", success_count, "ENSEMBL IDs to symbols"))
          return(symbols)
        }
      }
    }, error = function(e) {
      print(paste("biomaRt failed:", e$message))
    })
    
    # Method 2: Try org.Hs.eg.db or org.Mm.eg.db
    tryCatch({
      org_db <- if (organism == "mouse") "org.Mm.eg.db" else "org.Hs.eg.db"
      if (requireNamespace(org_db, quietly = TRUE) && requireNamespace("AnnotationDbi", quietly = TRUE)) {
        library(org_db, character.only = TRUE)
        db_obj <- get(org_db)
        
        converted <- AnnotationDbi::mapIds(
          db_obj,
          keys = ensembl_ids,
          column = "SYMBOL",
          keytype = "ENSEMBL",
          multiVals = "first"
        )
        
        symbols <- ifelse(is.na(converted), "", as.character(converted))
        success_count <- sum(symbols != "")
        
        if (success_count > 0) {
          print(paste("AnnotationDbi: Successfully converted", success_count, "ENSEMBL IDs to symbols"))
          return(symbols)
        }
      }
    }, error = function(e) {
      print(paste("AnnotationDbi failed:", e$message))
    })
    
    # Fallback: Create meaningful symbols
    print("Using fallback conversion for ENSEMBL IDs")
    fallback_symbols <- paste0("GENE_", gsub("ENS[MG]*G0*", "", ensembl_ids))
    return(fallback_symbols)
  }
  
  convert_transcripts_to_genes_robust <- function(transcript_ids, organism) {
    
    symbols <- character(length(transcript_ids))
    ensembl_ids <- character(length(transcript_ids))
    
    # Try biomaRt for transcript conversion
    tryCatch({
      if (requireNamespace("biomaRt", quietly = TRUE)) {
        dataset <- if (organism == "mouse") "mmusculus_gene_ensembl" else "hsapiens_gene_ensembl"
        mart <- biomaRt::useMart("ensembl", dataset = dataset)
        
        results <- biomaRt::getBM(
          attributes = c("ensembl_transcript_id", "ensembl_gene_id", "external_gene_name"),
          filters = "ensembl_transcript_id",
          values = transcript_ids,
          mart = mart
        )
        
        # Map back to original order
        for (i in seq_along(transcript_ids)) {
          matches <- results[results$ensembl_transcript_id == transcript_ids[i], ]
          if (nrow(matches) > 0) {
            if (!is.na(matches$external_gene_name[1]) && matches$external_gene_name[1] != "") {
              symbols[i] <- matches$external_gene_name[1]
            }
            if (!is.na(matches$ensembl_gene_id[1]) && matches$ensembl_gene_id[1] != "") {
              ensembl_ids[i] <- matches$ensembl_gene_id[1]
            }
          }
        }
        
        success_count <- sum(symbols != "" | ensembl_ids != "")
        if (success_count > 0) {
          print(paste("Successfully converted", success_count, "transcript IDs"))
          return(list(symbols = symbols, ensembl_ids = ensembl_ids))
        }
      }
    }, error = function(e) {
      print(paste("Transcript conversion failed:", e$message))
    })
    
    # Conversion failed: keep the original IDs and mark Ensembl IDs as unmapped (never invent IDs)
    fallback_symbols <- transcript_ids
    fallback_ensembl <- rep(NA_character_, length(transcript_ids))
    
    return(list(symbols = fallback_symbols, ensembl_ids = fallback_ensembl))
  }
  
  convert_entrez_to_symbols_and_ensembl_robust <- function(entrez_ids, organism) {
    
    symbols <- character(length(entrez_ids))
    ensembl_ids <- character(length(entrez_ids))
    
    # Try AnnotationDbi
    tryCatch({
      org_db <- if (organism == "mouse") "org.Mm.eg.db" else "org.Hs.eg.db"
      if (requireNamespace(org_db, quietly = TRUE) && requireNamespace("AnnotationDbi", quietly = TRUE)) {
        library(org_db, character.only = TRUE)
        db_obj <- get(org_db)
        
        # Convert to symbols
        symbol_results <- AnnotationDbi::mapIds(
          db_obj,
          keys = entrez_ids,
          column = "SYMBOL",
          keytype = "ENTREZID",
          multiVals = "first"
        )
        
        # Convert to ENSEMBL
        ensembl_results <- AnnotationDbi::mapIds(
          db_obj,
          keys = entrez_ids,
          column = "ENSEMBL",
          keytype = "ENTREZID",
          multiVals = "first"
        )
        
        symbols <- ifelse(is.na(symbol_results), "", as.character(symbol_results))
        ensembl_ids <- ifelse(is.na(ensembl_results), "", as.character(ensembl_results))
        
        success_count <- sum(symbols != "" | ensembl_ids != "")
        if (success_count > 0) {
          print(paste("Successfully converted", success_count, "Entrez IDs"))
          return(list(symbols = symbols, ensembl_ids = ensembl_ids))
        }
      }
    }, error = function(e) {
      print(paste("Entrez conversion failed:", e$message))
    })
    
    # Conversion failed: keep the original IDs and mark Ensembl IDs as unmapped (never invent IDs)
    fallback_symbols <- as.character(entrez_ids)
    fallback_ensembl <- rep(NA_character_, length(entrez_ids))
    
    return(list(symbols = fallback_symbols, ensembl_ids = fallback_ensembl))
  }
  
  smart_gene_processing_for_comprehensive <- function(selected_genes, organism) {
    
    print("=== SMART GENE PROCESSING FOR COMPREHENSIVE ANALYSIS (ROBUST VERSION) ===")
    
    input_genes <- selected_genes$all_genes
    print(paste("Processing", length(input_genes), "genes"))
    print(paste("Input sample:", paste(head(input_genes, 3), collapse = ", ")))
    
    # Clean gene IDs - remove comparison suffixes and version numbers
    # First remove any comparison text like "_mmtv vs ctrl", "_treated vs control", etc.
    clean_genes <- gsub("_.*$", "", input_genes)  # Remove everything after underscore
    clean_genes <- gsub("\\.[0-9]+$", "", clean_genes)  # Remove version numbers like .1, .2
    
    print(paste("Cleaned sample:", paste(head(clean_genes, 3), collapse = ", ")))
    
    # Detect ID types
    id_types <- detect_gene_id_types_robust(clean_genes)
    print("Detected ID types:")
    print(id_types$summary)
    
    # Initialize results
    symbols_for_chembl <- character(0)
    ensembl_for_opentargets <- character(0)
    gene_mapping <- data.frame(
      original_id = character(0),
      symbol = character(0),
      ensembl_id = character(0),
      stringsAsFactors = FALSE
    )
    
    # Convert based on ID type using the existing convert_gene_ids_to_symbols_deg function
    if (id_types$summary$total > 0) {
      print("Converting all gene IDs to symbols and ENSEMBL IDs...")
      
      # Use the existing robust conversion function
      conversion_result <- convert_gene_ids_to_symbols_deg(clean_genes, organism)
      
      # Extract successfully converted symbols
      valid_symbols <- conversion_result$gene_symbol != "-" & 
        !is.na(conversion_result$gene_symbol) &
        conversion_result$gene_symbol != ""
      
      symbols_for_chembl <- conversion_result$gene_symbol[valid_symbols]
      original_ids_with_symbols <- clean_genes[valid_symbols]
      
      print(paste("✓ Converted to symbols:", length(symbols_for_chembl), "out of", length(clean_genes)))
      
      # Now convert symbols to ENSEMBL IDs for OpenTargets
      if (length(symbols_for_chembl) > 0) {
        print("Converting symbols to ENSEMBL IDs for OpenTargets...")
        ensembl_for_opentargets <- convert_symbols_to_ensembl_efficient(symbols_for_chembl, organism)
        
        # Create comprehensive gene mapping
        gene_mapping <- data.frame(
          original_id = original_ids_with_symbols,
          symbol = symbols_for_chembl,
          ensembl_id = ensembl_for_opentargets[1:length(symbols_for_chembl)],
          stringsAsFactors = FALSE
        )
        
        # Remove entries where ENSEMBL conversion failed
        gene_mapping <- gene_mapping[!is.na(gene_mapping$ensembl_id) & 
                                       gene_mapping$ensembl_id != "", ]
        
        print(paste("✓ ENSEMBL IDs obtained:", nrow(gene_mapping)))
      }
    }
    
    # Summary statistics
    conversion_stats <- list(
      total_input = length(input_genes),
      successful_symbols = length(symbols_for_chembl),
      successful_ensembl = nrow(gene_mapping),
      conversion_rate = length(symbols_for_chembl) / length(input_genes),
      id_types_detected = id_types$summary
    )
    
    print("=== Conversion Summary ===")
    print(paste("Total input genes:", conversion_stats$total_input))
    print(paste("Successfully converted to symbols:", conversion_stats$successful_symbols))
    print(paste("Successfully converted to ENSEMBL:", conversion_stats$successful_ensembl))
    print(paste("Overall conversion rate:", round(conversion_stats$conversion_rate * 100, 1), "%"))
    
    return(list(
      symbols_for_chembl = symbols_for_chembl,
      ensembl_for_opentargets = gene_mapping$ensembl_id,
      gene_mapping = gene_mapping,
      efficiency_note = "Robust conversion handling ENST, ENSG, Entrez, and Symbol IDs",
      conversion_stats = conversion_stats
    ))
  }
  
  
  
  # Helper function to detect gene ID types
  detect_gene_id_types_robust <- function(gene_ids) {
    
    n_total <- length(gene_ids)
    n_enst <- sum(grepl("^ENST", gene_ids, ignore.case = TRUE))
    n_ensg <- sum(grepl("^ENSG", gene_ids, ignore.case = TRUE))
    n_ensembl_other <- sum(grepl("^ENS[A-Z]*G", gene_ids, ignore.case = TRUE)) - n_ensg
    n_entrez <- sum(grepl("^[0-9]+$", gene_ids))
    n_refseq <- sum(grepl("^[NX][MR]_", gene_ids, ignore.case = TRUE))
    n_symbols <- n_total - (n_enst + n_ensg + n_ensembl_other + n_entrez + n_refseq)
    
    summary <- list(
      total = n_total,
      transcript_ids = n_enst,
      ensembl_gene_ids = n_ensg,
      other_ensembl_ids = n_ensembl_other,
      entrez_ids = n_entrez,
      refseq_ids = n_refseq,
      potential_symbols = n_symbols
    )
    
    return(list(
      summary = summary,
      indices = list(
        enst = which(grepl("^ENST", gene_ids, ignore.case = TRUE)),
        ensg = which(grepl("^ENSG", gene_ids, ignore.case = TRUE)),
        entrez = which(grepl("^[0-9]+$", gene_ids)),
        refseq = which(grepl("^[NX][MR]_", gene_ids, ignore.case = TRUE))
      )
    ))
  }
  
  convert_symbols_to_ensembl_efficient <- function(gene_symbols, organism) {
    
    if (length(gene_symbols) == 0) return(character(0))
    
    ensembl_ids <- character(length(gene_symbols))
    
    # Method 1: Try biomaRt
    tryCatch({
      if (requireNamespace("biomaRt", quietly = TRUE)) {
        dataset <- if (organism == "mouse") "mmusculus_gene_ensembl" else "hsapiens_gene_ensembl"
        mart <- biomaRt::useMart("ensembl", dataset = dataset)
        
        results <- biomaRt::getBM(
          attributes = c("external_gene_name", "ensembl_gene_id"),
          filters = "external_gene_name",
          values = gene_symbols,
          mart = mart
        )
        
        # Map back to original order
        for (i in seq_along(gene_symbols)) {
          matches <- results$ensembl_gene_id[results$external_gene_name == gene_symbols[i]]
          if (length(matches) > 0 && !is.na(matches[1]) && matches[1] != "") {
            ensembl_ids[i] <- matches[1]
          }
        }
        
        success_count <- sum(ensembl_ids != "")
        if (success_count > 0) {
          print(paste("biomaRt: Successfully converted", success_count, "symbols to ENSEMBL"))
          return(ensembl_ids)
        }
      }
    }, error = function(e) {
      print(paste("biomaRt failed:", e$message))
    })
    
    # Method 2: Try AnnotationDbi
    tryCatch({
      org_db <- if (organism == "mouse") "org.Mm.eg.db" else "org.Hs.eg.db"
      if (requireNamespace(org_db, quietly = TRUE) && requireNamespace("AnnotationDbi", quietly = TRUE)) {
        library(org_db, character.only = TRUE)
        db_obj <- get(org_db)
        
        converted <- AnnotationDbi::mapIds(
          db_obj,
          keys = gene_symbols,
          column = "ENSEMBL",
          keytype = "SYMBOL",
          multiVals = "first"
        )
        
        ensembl_ids <- ifelse(is.na(converted), "", as.character(converted))
        success_count <- sum(ensembl_ids != "")
        
        if (success_count > 0) {
          print(paste("AnnotationDbi: Successfully converted", success_count, "symbols to ENSEMBL"))
          return(ensembl_ids)
        }
      }
    }, error = function(e) {
      print(paste("AnnotationDbi failed:", e$message))
    })
    
    # Conversion failed: return unmapped (NA) rather than invented IDs
    print("Symbol to Ensembl conversion failed; returning unmapped (NA) IDs")
    return(rep(NA_character_, length(gene_symbols)))
  }
  
