  run_comprehensive_drug_target_analysis_optimized_fixed <- function(selected_genes,
                                                                     analysis_focus = "comprehensive",
                                                                     max_drugs_per_gene = 10,
                                                                     min_confidence = 0.5,
                                                                     organism = "human") {
    
    print("=== OPTIMIZED COMPREHENSIVE ANALYSIS (FIXED RETURN STRUCTURE) ===")
    print(paste("Analysis focus:", analysis_focus))
    
    tryCatch({
      
      # Step 1-7: All your existing processing code stays the same...
      # (gene processing, ChEMBL analysis, OpenTargets analysis, etc.)
      
      # [Your existing code for steps 1-7 here - don't change the processing]
      
      # Step 1: Smart gene processing
      print("Step 1: Smart gene ID processing...")
      gene_processing_result <- smart_gene_processing_for_comprehensive(selected_genes, organism)
      
      if (length(gene_processing_result$symbols_for_chembl) == 0 && length(gene_processing_result$ensembl_for_opentargets) == 0) {
        print("ERROR: No valid genes for analysis")
        return(create_empty_comprehensive_results_fixed(selected_genes, analysis_focus, list()))
      }
      
      print("✓ Smart processing successful:")
      print(paste("  - Symbols for ChEMBL:", length(gene_processing_result$symbols_for_chembl)))
      print(paste("  - ENSEMBL IDs for OpenTargets:", length(gene_processing_result$ensembl_for_opentargets)))
      
      conversion_stats <- list(
        total_input = length(selected_genes$all_genes),
        successful_conversions = length(gene_processing_result$symbols_for_chembl),
        chembl_symbols = length(gene_processing_result$symbols_for_chembl),
        opentargets_ensembl = length(gene_processing_result$ensembl_for_opentargets),
        conversion_rate = length(gene_processing_result$symbols_for_chembl) / length(selected_genes$all_genes),
        symbols_obtained = gene_processing_result$symbols_for_chembl,
        ensembl_obtained = gene_processing_result$ensembl_for_opentargets
      )
      
      
      # Step 2: ChEMBL Analysis
      # Step 2: DGIdb Analysis (replaces slow ChEMBL API)
      chembl_data <- data.frame()  # Keep variable name for compatibility
      if (analysis_focus %in% c("drug_discovery", "comprehensive") &&
          length(gene_processing_result$symbols_for_chembl) > 0) {
        
        if (analysis_focus == "drug_discovery") {
          print("Step 2: Drug Discovery Analysis (DGIdb - Fast Mode)...")
          activity_threshold <- input$activity_threshold %||% 50000
          confidence_threshold <- input$drug_confidence_threshold %||% min_confidence
          chembl_data <- run_drug_discovery_dgidb_analysis(
            gene_processing_result$symbols_for_chembl,
            max_drugs_per_gene,
            min_confidence,
            activity_threshold
          )
        } else if (analysis_focus == "comprehensive") {
          print("Step 2: Comprehensive Analysis (DGIdb - Fast Mode)...")
          chembl_data <- run_comprehensive_dgidb_analysis(
            gene_processing_result$symbols_for_chembl,
            max_drugs_per_gene,
            min_confidence
          )
        }
        print(paste("✅ DGIdb results:", nrow(chembl_data), "interactions"))
      }
      
      # Step 3: OpenTargets Analysis
      opentargets_data <- data.frame()
      if (analysis_focus %in% c("disease_context", "comprehensive") &&
          length(gene_processing_result$ensembl_for_opentargets) > 0) {
        print("Step 3: OpenTargets comprehensive analysis...")
        opentargets_data <- run_opentargets_comprehensive_analysis_fixed(
          gene_processing_result$ensembl_for_opentargets,
          max_drugs_per_gene,
          gene_processing_result$gene_mapping
        )
        print(paste("✓ OpenTargets results:", nrow(opentargets_data), "interactions"))
      }
      
      # Step 4: Cross-database integration
      print("Step 4: Cross-database integration...")
      integrated_insights <- create_comprehensive_cross_database_insights_enhanced(chembl_data, opentargets_data)
      
      # Step 5: Data combination and prioritization
      print("Step 5: Fixed data combination and prioritization...")
      all_drug_data <- combine_chembl_opentargets_data_fixed(chembl_data, opentargets_data)
      drug_prioritization <- create_comprehensive_drug_prioritization_safe(all_drug_data, selected_genes)
      
      # Step 6: Create network
      print("Step 6: Network creation...")
      network_data <- create_comprehensive_integrated_network_enhanced(chembl_data, opentargets_data, analysis_focus)
      
      # Step 7: Summary statistics
      summary_stats <- create_comprehensive_summary_stats_enhanced(chembl_data, opentargets_data, network_data, gene_processing_result)
      
      print("===[OK] COMPREHENSIVE ANALYSIS COMPLETE ===")
      print(paste("Final results:"))
      print(paste("  - ChEMBL interactions:", nrow(chembl_data)))
      print(paste("  - OpenTargets interactions:", nrow(opentargets_data)))
      print(paste("  - Combined interactions:", nrow(all_drug_data)))
      
      # ============================================================================
      # FIXED RETURN STRUCTURE - This is the key fix!
      # ============================================================================
      # ADD THESE DEBUG LINES RIGHT BEFORE YOUR RETURN:
      print("=== PRE-RETURN VALIDATION ===")
      print(paste("chembl_data class:", class(chembl_data)[1], "- rows:", nrow(chembl_data)))
      print(paste("opentargets_data class:", class(opentargets_data)[1], "- rows:", nrow(opentargets_data)))
      print(paste("all_drug_data class:", class(all_drug_data)[1], "- rows:", nrow(all_drug_data)))
      
      # Check if data exists - FIXED PRINT STATEMENTS
      if (nrow(chembl_data) > 0) {
        print("✓ ChEMBL data exists")
        print(paste("ChEMBL columns:", paste(colnames(chembl_data)[1:min(5, ncol(chembl_data))], collapse = ", ")))
      } else {
        print("⚠ ChEMBL data is empty")
      }
      
      if (nrow(opentargets_data) > 0) {
        print("✓ OpenTargets data exists")
        print(paste("OpenTargets columns:", paste(colnames(opentargets_data)[1:min(5, ncol(opentargets_data))], collapse = ", ")))
      } else {
        print("⚠ OpenTargets data is empty")
      }
      
      # REPLACE YOUR CURRENT RETURN WITH THIS:
      results <- list(
        # Core data that UI looks for - ADD EXPLICIT VALIDATION
        chembl_data = chembl_data,  # Remove the if() check - it was causing issues
        opentargets_data = opentargets_data,
        raw_data = all_drug_data,
        
        # Analysis outputs
        network_data = network_data,
        summary = summary_stats,
        drug_prioritization = drug_prioritization,
        integrated_insights = integrated_insights,
        
        # Legacy compatibility (your existing code might expect these)
        drug_targets = all_drug_data,
        
        # Metadata
        conversion_stats = conversion_stats,
        #conversion_stats = gene_processing_result$conversion_stats,
        analysis_type = "comprehensive_drug_target",
        analysis_params = list(
          analysis_focus = analysis_focus,
          max_drugs_per_gene = max_drugs_per_gene,
          min_confidence = min_confidence,
          organism = organism
        )
      )
      
      # FINAL VALIDATION - SIMPLIFIED
      print("=== FINAL RETURN VALIDATION ===")
      print(paste("Returning chembl_data rows:", nrow(results$chembl_data)))
      print(paste("Returning opentargets_data rows:", nrow(results$opentargets_data)))
      print(paste("Returning raw_data rows:", nrow(results$raw_data)))
      print(paste("Returning drug_prioritization rows:", nrow(results$drug_prioritization)))
      
      
      if (analysis_focus == "disease_context") {
        print("=== DISEASE CONTEXT: Final data assignment ===")
        
        # For disease context, ensure drug_targets contains the OpenTargets data
        if (!is.null(opentargets_data) && nrow(opentargets_data) > 0) {
          print("Assigning opentargets_data to drug_targets for disease context UI")
          all_drug_data <- opentargets_data  # This becomes drug_targets
        }
        
        print(paste("Final drug_targets for disease context:", nrow(all_drug_data), "rows"))
      }
      
      return(results)
      
    }, error = function(e) {
      print(paste("❌ ERROR in comprehensive analysis:", e$message))
      return(create_empty_comprehensive_results_fixed(selected_genes, analysis_focus, list()))
    })
  }
  
  run_comprehensive_dgidb_analysis <- function(symbols, max_drugs_per_gene, min_confidence) {
    
    print("═══════════════════════════════════════════════════════════════")
    print("    COMPREHENSIVE MODE (DGIdb)")
    print("    Focus: Complete therapeutic landscape with evidence")
    print("═══════════════════════════════════════════════════════════════")
    
    if (length(symbols) == 0) {
      return(data.frame())
    }
    
    # Query DGIdb without source filter - get everything
    dgidb_results <- query_dgidb_enhanced(
      gene_symbols = symbols,
      max_drugs_per_gene = max_drugs_per_gene * 3,
      filter_sources = NULL,
      approved_only = FALSE
    )
    
    if (is.null(dgidb_results) || nrow(dgidb_results) == 0) {
      print("⚠️ No DGIdb results found")
      return(data.frame())
    }
    
    print(paste("Raw DGIdb results:", nrow(dgidb_results), "interactions"))
    
    # Comprehensive processing - KEEP ALL COLUMNS
    comprehensive_results <- dgidb_results %>%
      dplyr::filter(confidence_score >= (min_confidence * 0.7)) %>%
      dplyr::mutate(
        molecule_name = drug_name,
        interaction_type = ifelse(is.na(interaction_type) | interaction_type == "", "Unknown", interaction_type),
        standard_type = interaction_type,
        
        evidence_level = dplyr::case_when(
          is_approved & n_publications >= 10 ~ "Very High Evidence",
          is_approved & n_publications >= 5 ~ "High Evidence",
          is_approved ~ "Clinical Evidence",
          n_sources >= 4 ~ "Strong Preclinical",
          n_sources >= 2 ~ "Moderate Evidence",
          TRUE ~ "Limited Evidence"
        ),
        
        source_diversity = dplyr::case_when(
          grepl("ChEMBL", sources) & grepl("DrugBank", sources) ~ "Multi-Database",
          n_sources >= 3 ~ "Multi-Source",
          n_sources == 2 ~ "Dual-Source",
          TRUE ~ "Single-Source"
        ),
        
        pubmed_link = ifelse(
          !is.na(pmids) & pmids != "",
          paste0("https://pubmed.ncbi.nlm.nih.gov/?term=", gsub(",\\s*", "+OR+", pmids)),
          paste0("https://pubmed.ncbi.nlm.nih.gov/?term=", URLencode(paste(drug_name, gene_name)))
        ),
        
        dgidb_link = paste0("https://www.dgidb.org/results?searchType=drug&searchTerms=", URLencode(drug_name)),
        clinicaltrials_link = paste0("https://clinicaltrials.gov/search?term=", URLencode(drug_name)),
        
        database_source = "DGIdb",
        database = "DGIdb",
        analysis_context = "comprehensive",
        standard_value = NA_real_,
        pchembl_value = NA_real_,
        disease_area = "Not specified",
        druggability_score = confidence_score,
        safety_score = ifelse(is_approved, 0.9, 0.6),
        clinical_evidence_score = confidence_score
      ) %>%
      dplyr::group_by(gene_name) %>%
      dplyr::arrange(
        dplyr::desc(clinical_phase),
        dplyr::desc(is_approved),
        dplyr::desc(confidence_score)
      ) %>%
      dplyr::slice_head(n = max_drugs_per_gene) %>%
      dplyr::ungroup()
    
    print(paste("✅ Comprehensive results:", nrow(comprehensive_results), "interactions"))
    
    return(comprehensive_results)
  }
  
  run_opentargets_comprehensive_analysis_fixed <- function(ensembl_ids, max_drugs_per_gene = 10, gene_mapping = NULL) {

    print("=== OpenTargets COMPREHENSIVE ANALYSIS (Local Parquet Data) ===")

    # --- 1. SAFEGUARD INPUTS ---
    if (is.null(max_drugs_per_gene) || length(max_drugs_per_gene) == 0) {
      max_drugs_per_gene <- 10
    }

    if (length(ensembl_ids) == 0) {
      print("No ENSEMBL IDs provided.")
      return(data.frame())
    }

    if (!requireNamespace("dplyr", quietly = TRUE)) library(dplyr)

    # --- 2. LOCAL PARQUET DATA PATH ---
    ot_data_path <- Sys.getenv("OPENTARGETS_DATA_PATH", "/srv/opentargets")

    # Check if local data exists
    local_data_available <- dir.exists(file.path(ot_data_path, "drug_mechanism_of_action")) &&
      dir.exists(file.path(ot_data_path, "drug_molecule")) &&
      dir.exists(file.path(ot_data_path, "target"))

    if (!local_data_available) {
      print("Local OpenTargets data not found, falling back to API...")
      return(run_opentargets_api_fallback(ensembl_ids, max_drugs_per_gene))
    }

    if (!requireNamespace("arrow", quietly = TRUE)) {
      print("arrow package not available, falling back to API...")
      return(run_opentargets_api_fallback(ensembl_ids, max_drugs_per_gene))
    }

    # Strip Ensembl version suffixes (e.g., ENSG00000139618.15 -> ENSG00000139618)
    # Local OT parquet files use unversioned IDs; versioned IDs would match nothing.
    n_before <- length(ensembl_ids)
    ensembl_ids <- unique(sub("\\.[0-9]+$", "", as.character(ensembl_ids)))
    if (length(ensembl_ids) != n_before) {
      print(paste("Cleaned Ensembl IDs:", n_before, "->", length(ensembl_ids), "(deduplicated after version strip)"))
    }

    print(paste("Processing", length(ensembl_ids), "ENSEMBL IDs from local OpenTargets data"))

    tryCatch({
      # --- 3. LOAD LOCAL DATASETS (lazy - Arrow pushes filters to Parquet engine) ---

      # Load mechanism of action: maps drugs to targets
      moa_ds <- arrow::open_dataset(file.path(ot_data_path, "drug_mechanism_of_action"))

      # Load drug info
      drug_ds <- arrow::open_dataset(file.path(ot_data_path, "drug_molecule"))

      # Load target info for gene symbol lookup
      target_ds <- arrow::open_dataset(file.path(ot_data_path, "target"))

      # Load disease info
      disease_ds <- arrow::open_dataset(file.path(ot_data_path, "disease"))

      # Load clinical indications
      clinical_ds <- arrow::open_dataset(file.path(ot_data_path, "clinical_indication"))

      # --- 4. GET TARGET GENE SYMBOLS ---
      target_info <- target_ds %>%
        dplyr::filter(id %in% ensembl_ids) %>%
        dplyr::select(id, approvedSymbol, approvedName) %>%
        dplyr::collect()

      if (nrow(target_info) == 0) {
        print("No targets found in local OpenTargets data for provided Ensembl IDs")
        return(data.frame())
      }

      print(paste("Found", nrow(target_info), "targets in local data"))

      # --- 5. FIND DRUG-TARGET ASSOCIATIONS via mechanism of action ---
      # The 'targets' column in moa contains Ensembl IDs as a list column
      moa_all <- moa_ds %>% dplyr::collect()

      # Expand the targets list column to find matches
      moa_matches <- list()
      for (i in seq_len(nrow(moa_all))) {
        target_list <- moa_all$targets[[i]]
        if (is.null(target_list)) next
        matched_targets <- intersect(target_list, ensembl_ids)
        if (length(matched_targets) > 0) {
          chembl_ids <- moa_all$chemblIds[[i]]
          if (is.null(chembl_ids) || length(chembl_ids) == 0) next
          for (tid in matched_targets) {
            for (cid in chembl_ids) {
              moa_matches[[length(moa_matches) + 1]] <- data.frame(
                ensembl_id = tid,
                drug_id = cid,
                action_type = moa_all$actionType[i] %||% "Unknown",
                mechanism = moa_all$mechanismOfAction[i] %||% "Unknown",
                stringsAsFactors = FALSE
              )
            }
          }
        }
      }

      if (length(moa_matches) == 0) {
        print("No drug-target mechanisms found for provided genes")
        return(data.frame())
      }

      moa_df <- dplyr::bind_rows(moa_matches)
      print(paste("Found", nrow(moa_df), "drug-target mechanism links"))

      # --- 6. GET DRUG INFO ---
      unique_drug_ids <- unique(moa_df$drug_id)
      drug_info <- drug_ds %>%
        dplyr::filter(id %in% unique_drug_ids) %>%
        dplyr::select(id, name, drugType, maximumClinicalStage) %>%
        dplyr::collect()

      # --- 7. GET CLINICAL INDICATIONS (drug-disease-phase) ---
      clinical_info <- clinical_ds %>%
        dplyr::filter(drugId %in% unique_drug_ids) %>%
        dplyr::select(drugId, diseaseId, maxClinicalStage) %>%
        dplyr::collect()

      # Get disease names for the indications
      if (nrow(clinical_info) > 0) {
        unique_disease_ids <- unique(clinical_info$diseaseId)
        disease_info <- disease_ds %>%
          dplyr::filter(id %in% unique_disease_ids) %>%
          dplyr::select(id, name) %>%
          dplyr::collect()
      } else {
        disease_info <- data.frame(id = character(0), name = character(0))
      }

      # --- 8. HELPER: Convert clinical stage string to numeric phase ---
      stage_to_phase <- function(stage) {
        if (is.na(stage) || is.null(stage) || stage == "") return(0)
        stage <- toupper(as.character(stage))
        if (grepl("APPROVAL|PHASE_4|APPROVED", stage)) return(4)
        if (grepl("PHASE_3|PHASE3", stage)) return(3)
        if (grepl("PHASE_2|PHASE2", stage)) return(2)
        if (grepl("PHASE_1|PHASE1", stage)) return(1)
        if (grepl("PRECLINICAL|DISCOVERY", stage)) return(0)
        return(0)
      }

      # --- 9. BUILD RESULTS ---
      all_results <- list()

      for (eid in unique(moa_df$ensembl_id)) {
        gene_moa <- moa_df[moa_df$ensembl_id == eid, ]
        symbol <- target_info$approvedSymbol[target_info$id == eid]
        if (length(symbol) == 0) symbol <- eid
        symbol <- symbol[1]

        for (j in seq_len(nrow(gene_moa))) {
          did <- gene_moa$drug_id[j]

          # Get drug details
          d_info <- drug_info[drug_info$id == did, ]
          drug_name <- if (nrow(d_info) > 0) d_info$name[1] else did
          drug_type <- if (nrow(d_info) > 0) d_info$drugType[1] else "Unknown"
          drug_max_stage <- if (nrow(d_info) > 0) d_info$maximumClinicalStage[1] else NA

          # Get clinical indications for this drug
          drug_clinical <- clinical_info[clinical_info$drugId == did, ]

          if (nrow(drug_clinical) > 0) {
            # Create one row per disease indication (up to max_drugs_per_gene)
            drug_clinical <- head(drug_clinical, max_drugs_per_gene)
            for (k in seq_len(nrow(drug_clinical))) {
              dis_name <- disease_info$name[disease_info$id == drug_clinical$diseaseId[k]]
              dis_name <- if (length(dis_name) > 0) dis_name[1] else "Not specified"
              phase <- stage_to_phase(drug_clinical$maxClinicalStage[k])

              all_results[[length(all_results) + 1]] <- data.frame(
                ensembl_id = eid,
                gene_name = symbol,
                molecule_name = drug_name,
                molecule_id = did,
                clinical_phase = phase,
                disease_area = dis_name,
                drug_type = drug_type,
                mechanism = gene_moa$mechanism[j],
                action_type = gene_moa$action_type[j],
                stringsAsFactors = FALSE
              )
            }
          } else {
            # No clinical indications - still include the drug-target link
            phase <- stage_to_phase(drug_max_stage)
            all_results[[length(all_results) + 1]] <- data.frame(
              ensembl_id = eid,
              gene_name = symbol,
              molecule_name = drug_name,
              molecule_id = did,
              clinical_phase = phase,
              disease_area = "Not specified",
              drug_type = drug_type,
              mechanism = gene_moa$mechanism[j],
              action_type = gene_moa$action_type[j],
              stringsAsFactors = FALSE
            )
          }
        }
      }

      if (length(all_results) == 0) {
        print("No OpenTargets results after processing")
        return(data.frame())
      }

      final_results <- dplyr::bind_rows(all_results)

      # --- 10. SCORING (same logic as before) ---
      final_results <- final_results %>%
        dplyr::mutate(
          druggability_score = dplyr::case_when(
            clinical_phase >= 4 ~ 0.95,
            clinical_phase == 3 ~ 0.85,
            clinical_phase == 2 ~ 0.75,
            clinical_phase == 1 ~ 0.65,
            TRUE ~ 0.55
          ),
          safety_score = dplyr::case_when(
            clinical_phase >= 4 ~ 0.9,
            clinical_phase >= 2 ~ 0.7,
            TRUE ~ 0.5
          ),
          clinical_evidence_score = dplyr::case_when(
            clinical_phase >= 3 ~ 0.85,
            clinical_phase >= 1 ~ 0.65,
            TRUE ~ 0.55
          ),
          confidence_score = (druggability_score + safety_score + clinical_evidence_score) / 3,
          safety_risk = ifelse(safety_score >= 0.7, "Low", "High"),
          database_source = "OpenTargets",
          analysis_context = "comprehensive"
        )

      print(paste("OpenTargets local data results:", nrow(final_results), "associations found"))
      return(final_results)

    }, error = function(e) {
      print(paste("Error reading local OpenTargets data:", e$message))
      print("Falling back to API...")
      return(run_opentargets_api_fallback(ensembl_ids, max_drugs_per_gene))
    })
  }

  # API fallback for when local data is unavailable
  run_opentargets_api_fallback <- function(ensembl_ids, max_drugs_per_gene = 10) {

    print("=== OpenTargets API FALLBACK (updated schema v26+) ===")

    if (length(ensembl_ids) == 0) return(data.frame())
    if (!requireNamespace("httr", quietly = TRUE)) return(data.frame())
    if (!requireNamespace("jsonlite", quietly = TRUE)) return(data.frame())
    if (!requireNamespace("dplyr", quietly = TRUE)) library(dplyr)

    all_results <- list()
    total_genes <- length(ensembl_ids)

    for (i in seq_along(ensembl_ids)) {
      ensembl_id <- ensembl_ids[i]

      if (i %% 20 == 0) {
        print(paste("Progress:", i, "/", total_genes, "genes queried"))
      }

      # Updated GraphQL query for OT API v26+ (drugAndClinicalCandidates replaces knownDrugs)
      query <- sprintf('
      query TargetDrugs {
        target(ensemblId: "%s") {
          approvedSymbol
          drugAndClinicalCandidates {
            count
            rows {
              maxClinicalStage
              drug {
                id
                name
                drugType
                maximumClinicalStage
              }
              diseases {
                disease {
                  id
                  name
                }
              }
            }
          }
        }
      }
      ', ensembl_id)

      response <- tryCatch({
        httr::POST(
          url = "https://api.platform.opentargets.org/api/v4/graphql",
          body = list(query = query),
          encode = "json",
          httr::add_headers("Content-Type" = "application/json"),
          httr::timeout(15)
        )
      }, error = function(e) return(NULL))

      if (!is.null(response) && httr::status_code(response) == 200) {
        content_text <- httr::content(response, "text", encoding = "UTF-8")
        json_data <- tryCatch({
          jsonlite::fromJSON(content_text, flatten = FALSE)
        }, error = function(e) return(NULL))

        if (!is.null(json_data$data$target$drugAndClinicalCandidates$rows)) {
          rows <- json_data$data$target$drugAndClinicalCandidates$rows
          symbol <- json_data$data$target$approvedSymbol %||% ensembl_id

          # Helper to convert stage string to numeric
          stage_to_num <- function(s) {
            if (is.null(s) || is.na(s) || s == "") return(0)
            s <- toupper(s)
            if (grepl("APPROVAL|PHASE_4|APPROVED", s)) return(4)
            if (grepl("PHASE_3", s)) return(3)
            if (grepl("PHASE_2", s)) return(2)
            if (grepl("PHASE_1", s)) return(1)
            return(0)
          }

          if (is.data.frame(rows) && nrow(rows) > 0) {
            for (r in seq_len(min(nrow(rows), max_drugs_per_gene))) {
              drug_name <- tryCatch(rows$drug$name[r], error = function(e) "Unknown")
              drug_id <- tryCatch(rows$drug$id[r], error = function(e) "Unknown")
              max_stage <- tryCatch(rows$maxClinicalStage[r], error = function(e) NA)
              phase <- stage_to_num(max_stage)

              # Extract disease names
              diseases_list <- tryCatch(rows$diseases[[r]], error = function(e) NULL)
              disease_name <- "Not specified"
              if (!is.null(diseases_list) && length(diseases_list) > 0) {
                d_names <- sapply(diseases_list, function(d) {
                  if (!is.null(d$disease) && !is.null(d$disease$name)) d$disease$name else NA
                })
                d_names <- d_names[!is.na(d_names)]
                if (length(d_names) > 0) disease_name <- paste(head(d_names, 3), collapse = "; ")
              }

              all_results[[length(all_results) + 1]] <- data.frame(
                ensembl_id = ensembl_id,
                gene_name = symbol,
                molecule_name = drug_name %||% "Unknown",
                molecule_id = drug_id %||% "Unknown",
                clinical_phase = phase,
                disease_area = disease_name,
                stringsAsFactors = FALSE
              )
            }
          } else if (is.list(rows) && length(rows) > 0) {
            for (row in head(rows, max_drugs_per_gene)) {
              if (is.null(row) || is.null(row$drug)) next
              drug_name <- row$drug$name %||% "Unknown"
              drug_id <- row$drug$id %||% "Unknown"
              phase <- stage_to_num(row$maxClinicalStage)

              disease_name <- "Not specified"
              if (!is.null(row$diseases) && length(row$diseases) > 0) {
                d_names <- sapply(row$diseases, function(d) {
                  if (!is.null(d$disease) && !is.null(d$disease$name)) d$disease$name else NA
                })
                d_names <- d_names[!is.na(d_names)]
                if (length(d_names) > 0) disease_name <- paste(head(d_names, 3), collapse = "; ")
              }

              all_results[[length(all_results) + 1]] <- data.frame(
                ensembl_id = ensembl_id,
                gene_name = drug_name,
                molecule_name = drug_name,
                molecule_id = drug_id,
                clinical_phase = phase,
                disease_area = disease_name,
                stringsAsFactors = FALSE
              )
            }
          }
        }
      }

      if (i %% 5 == 0) Sys.sleep(0.15)
    }

    if (length(all_results) > 0) {
      final_results <- dplyr::bind_rows(all_results)
      final_results <- final_results %>%
        dplyr::mutate(
          druggability_score = dplyr::case_when(
            clinical_phase >= 4 ~ 0.95, clinical_phase == 3 ~ 0.85,
            clinical_phase == 2 ~ 0.75, clinical_phase == 1 ~ 0.65, TRUE ~ 0.55
          ),
          safety_score = dplyr::case_when(
            clinical_phase >= 4 ~ 0.9, clinical_phase >= 2 ~ 0.7, TRUE ~ 0.5
          ),
          clinical_evidence_score = dplyr::case_when(
            clinical_phase >= 3 ~ 0.85, clinical_phase >= 1 ~ 0.65, TRUE ~ 0.55
          ),
          confidence_score = (druggability_score + safety_score + clinical_evidence_score) / 3,
          safety_risk = ifelse(safety_score >= 0.7, "Low", "High"),
          database_source = "OpenTargets",
          analysis_context = "comprehensive"
        )
      print(paste("OpenTargets API results:", nrow(final_results), "associations"))
      return(final_results)
    } else {
      print("No OpenTargets data retrieved from API")
      return(data.frame())
    }
  }
  
  create_enhanced_opentargets_comprehensive_data <- function(ensembl_ids, symbols = NULL, max_per_gene) {
    
    if (length(ensembl_ids) == 0) return(data.frame())
    
    # Create more realistic OpenTargets-style comprehensive data
    n_interactions <- min(60, length(ensembl_ids) * max_per_gene)
    
    # Map ENSEMBL IDs to gene names (use symbols if provided, otherwise create meaningful names)
    if (!is.null(symbols) && length(symbols) >= length(ensembl_ids)) {
      gene_names <- symbols[1:length(ensembl_ids)]
    } else {
      gene_names <- paste0("GENE_", gsub("ENSG0+", "", ensembl_ids))
    }
    
    # Create comprehensive OpenTargets data
    mock_data <- data.frame(
      ensembl_id = sample(ensembl_ids, n_interactions, replace = TRUE),
      gene_name = sample(gene_names, n_interactions, replace = TRUE),
      molecule_name = paste0("OT_DRUG_", sample(1000:9999, n_interactions)),
      molecule_id = paste0("CHEMBL", sample(1000000:9999999, n_interactions)),
      
      # Clinical and disease context (OpenTargets focus)
      clinical_phase = sample(c(-1, 0, 1, 2, 3, 4), n_interactions, replace = TRUE,
                              prob = c(0.05, 0.25, 0.25, 0.25, 0.15, 0.05)),
      disease_area = sample(c("Oncology", "Immunology", "Neurology", "Metabolism",
                              "Cardiovascular", "Respiratory"), n_interactions, replace = TRUE),
      
      # OpenTargets-specific scores
      druggability_score = stats::runif(n_interactions, 0.3, 1.0),
      safety_score = stats::runif(n_interactions, 0.2, 0.9),
      clinical_evidence_score = stats::runif(n_interactions, 0.4, 0.95),
      target_tractability = sample(c("Small molecule", "Antibody", "Other modalities"),
                                   n_interactions, replace = TRUE),
      
      # Standardized columns for integration
      database_source = "OpenTargets",
      analysis_context = "comprehensive",
      standard_type = "Clinical Association",
      stringsAsFactors = FALSE
    ) %>%
      dplyr::mutate(
        # Derived confidence score
        confidence_score = (druggability_score + safety_score + clinical_evidence_score) / 3,
        standard_value = confidence_score,
        
        # Safety assessment
        safety_risk = dplyr::case_when(
          safety_score >= 0.8 ~ "Low",
          safety_score >= 0.5 ~ "Medium",
          TRUE ~ "High"
        )
      )
    
    return(mock_data)
  }
  
  combine_chembl_opentargets_data_fixed <- function(chembl_data, opentargets_data) {
    
    print("=== ENHANCED DATA COMBINATION (Full DGIdb Support) ===")
    
    all_data <- data.frame()
    
    # Process DGIdb/ChEMBL data - keep ALL columns
    if (!is.null(chembl_data) && nrow(chembl_data) > 0) {
      print("Processing DGIdb/ChEMBL data...")
      
      df <- chembl_data
      
      # Ensure critical columns exist with proper defaults
      if (!"molecule_name" %in% colnames(df)) {
        df$molecule_name <- df$drug_name
      }
      if (!"is_approved" %in% colnames(df)) {
        df$is_approved <- df$clinical_phase >= 4
      }
      if (!"n_sources" %in% colnames(df)) {
        df$n_sources <- 1
      }
      if (!"n_publications" %in% colnames(df)) {
        df$n_publications <- 0
      }
      if (!"sources" %in% colnames(df)) {
        df$sources <- df$database_source %||% "DGIdb"
      }
      if (!"interaction_type" %in% colnames(df)) {
        df$interaction_type <- df$standard_type %||% "Unknown"
      }
      if (!"pmids" %in% colnames(df)) {
        df$pmids <- NA_character_
      }
      if (!"drug_concept_id" %in% colnames(df)) {
        df$drug_concept_id <- NA_character_
      }
      
      # Create evidence/link columns if not present
      if (!"pubmed_link" %in% colnames(df)) {
        df$pubmed_link <- sapply(seq_len(nrow(df)), function(i) {
          if (!is.na(df$pmids[i]) && df$pmids[i] != "") {
            paste0("https://pubmed.ncbi.nlm.nih.gov/?term=", gsub(",\\s*", "+OR+", df$pmids[i]))
          } else {
            paste0("https://pubmed.ncbi.nlm.nih.gov/?term=", 
                   URLencode(paste(df$drug_name[i] %||% df$molecule_name[i], df$gene_name[i], "drug target")))
          }
        })
      }
      
      if (!"dgidb_link" %in% colnames(df)) {
        df$dgidb_link <- paste0("https://www.dgidb.org/results?searchType=drug&searchTerms=", 
                                URLencode(df$drug_name %||% df$molecule_name))
      }
      
      if (!"clinicaltrials_link" %in% colnames(df)) {
        df$clinicaltrials_link <- paste0("https://clinicaltrials.gov/search?term=", 
                                         URLencode(df$drug_name %||% df$molecule_name))
      }
      
      # Add disease/safety columns with defaults
      if (!"disease_area" %in% colnames(df)) df$disease_area <- "Not specified"
      if (!"druggability_score" %in% colnames(df)) df$druggability_score <- df$confidence_score %||% 0.5
      if (!"safety_score" %in% colnames(df)) df$safety_score <- ifelse(df$is_approved, 0.9, 0.6)
      if (!"clinical_evidence_score" %in% colnames(df)) df$clinical_evidence_score <- df$confidence_score %||% 0.5
      if (!"database_source" %in% colnames(df)) df$database_source <- "DGIdb"
      
      all_data <- df
      print(paste("Added", nrow(df), "DGIdb/ChEMBL interactions with", ncol(df), "columns"))
    }
    
    # Process OpenTargets data
    if (!is.null(opentargets_data) && nrow(opentargets_data) > 0) {
      print("Processing OpenTargets data...")
      
      df <- opentargets_data
      
      # Add required columns
      if (!"is_approved" %in% colnames(df)) df$is_approved <- df$clinical_phase >= 4
      if (!"n_sources" %in% colnames(df)) df$n_sources <- 1
      if (!"n_publications" %in% colnames(df)) df$n_publications <- 0
      if (!"sources" %in% colnames(df)) df$sources <- "OpenTargets"
      if (!"interaction_type" %in% colnames(df)) df$interaction_type <- "Clinical association"
      if (!"drug_name" %in% colnames(df)) df$drug_name <- df$molecule_name
      if (!"database_source" %in% colnames(df)) df$database_source <- "OpenTargets"
      
      # OpenTargets link
      if (!"opentargets_link" %in% colnames(df)) {
        df$opentargets_link <- ifelse(
          !is.na(df$molecule_id) & df$molecule_id != "" & df$molecule_id != "Unknown",
          paste0("https://platform.opentargets.org/drug/", df$molecule_id),
          paste0("https://platform.opentargets.org/search?q=", URLencode(df$molecule_name))
        )
      }
      
      # Combine with existing data
      if (nrow(all_data) > 0) {
        # Align columns
        all_cols <- union(colnames(all_data), colnames(df))
        for (col in all_cols) {
          if (!col %in% colnames(all_data)) all_data[[col]] <- NA
          if (!col %in% colnames(df)) df[[col]] <- NA
        }
        all_data <- rbind(all_data[, all_cols], df[, all_cols])
      } else {
        all_data <- df
      }
      
      print(paste("Added", nrow(df), "OpenTargets associations"))
    }
    
    print(paste("✓ Combined data:", nrow(all_data), "total interactions"))
    return(all_data)
  }
  
  create_comprehensive_drug_prioritization_safe <- function(combined_data, selected_genes) {
    
    print("=== COMPREHENSIVE DRUG PRIORITIZATION (DGIdb + OpenTargets) ===")
    
    if (is.null(combined_data) || nrow(combined_data) == 0) {
      print("No data available for prioritization")
      return(data.frame(
        drug_name = character(0),
        comprehensive_score = numeric(0),
        n_targets = numeric(0),
        target_genes = character(0),
        max_clinical_phase = numeric(0),
        priority_level = character(0),
        evidence_summary = character(0),
        disease_areas = character(0),
        total_publications = numeric(0),
        max_sources = numeric(0),
        mechanisms = character(0),
        is_approved = logical(0),
        all_sources = character(0)
      ))
    }
    
    print(paste("Processing", nrow(combined_data), "interactions"))
    
    # Ensure required columns exist
    if (!"n_sources" %in% colnames(combined_data)) combined_data$n_sources <- 1
    if (!"n_publications" %in% colnames(combined_data)) combined_data$n_publications <- 0
    if (!"interaction_type" %in% colnames(combined_data)) combined_data$interaction_type <- "Unknown"
    if (!"is_approved" %in% colnames(combined_data)) combined_data$is_approved <- combined_data$clinical_phase >= 4
    if (!"sources" %in% colnames(combined_data)) combined_data$sources <- combined_data$database_source %||% "Unknown"
    if (!"database_source" %in% colnames(combined_data)) combined_data$database_source <- "Unknown"
    if (!"disease_area" %in% colnames(combined_data)) combined_data$disease_area <- "Not specified"
    
    tryCatch({
      drug_scores <- combined_data %>%
        dplyr::group_by(molecule_name) %>%
        dplyr::summarise(
          n_targets = dplyr::n_distinct(gene_name),
          target_genes = paste(unique(gene_name), collapse = ", "),
          avg_confidence = mean(confidence_score, na.rm = TRUE),
          max_clinical_phase = max(clinical_phase, na.rm = TRUE),
          
          # DGIdb-specific aggregations
          total_publications = sum(n_publications, na.rm = TRUE),
          max_sources = max(n_sources, na.rm = TRUE),
          any_approved = any(is_approved == TRUE, na.rm = TRUE),
          
          # Mechanisms
          mechanisms = paste(unique(na.omit(interaction_type[interaction_type != "Unknown" & interaction_type != ""])), collapse = ", "),
          
          # All sources
          all_sources = paste(unique(na.omit(sources)), collapse = "; "),
          
          # Disease areas
          disease_areas = ifelse(
            all(is.na(disease_area)) | all(disease_area == "Not specified"),
            "Multiple areas",
            paste(unique(disease_area[!is.na(disease_area) & disease_area != "Not specified"]), collapse = "; ")
          ),
          
          # Database source detection - NOW PROPERLY DETECTS DGIdb vs OpenTargets
          has_dgidb = any(grepl("DGIdb|ChEMBL|DrugBank|PharmGKB|TTD|GuideToPharmacology", database_source, ignore.case = TRUE), na.rm = TRUE),
          has_opentargets = any(grepl("OpenTargets", database_source, ignore.case = TRUE), na.rm = TRUE),
          
          .groups = 'drop'
        ) %>%
        dplyr::mutate(
          # Scoring components
          target_score = log2(n_targets + 1),
          clinical_score = pmax(max_clinical_phase, 0) / 4,
          confidence_score_adj = avg_confidence,
          
          # Publication bonus
          publication_bonus = dplyr::case_when(
            total_publications >= 10 ~ 0.3,
            total_publications >= 5 ~ 0.2,
            total_publications >= 2 ~ 0.1,
            TRUE ~ 0
          ),
          
          # Multi-source bonus
          source_bonus = dplyr::case_when(
            max_sources >= 4 ~ 0.2,
            max_sources >= 2 ~ 0.1,
            TRUE ~ 0
          ),
          
          # CROSS-DATABASE BONUS: DGIdb + OpenTargets = highest confidence
          cross_database_bonus = dplyr::case_when(
            has_dgidb & has_opentargets ~ 1.5,  # Strong bonus for cross-validation
            has_dgidb & max_sources >= 3 ~ 1.2,  # Multi-source within DGIdb
            has_opentargets ~ 1.1,               # Clinical evidence
            TRUE ~ 1.0
          ),
          
          # Comprehensive score
          comprehensive_score = (target_score + clinical_score + confidence_score_adj + publication_bonus + source_bonus) * cross_database_bonus,
          
          # Evidence summary - PROPER DGIdb + OpenTargets cross-validation
          evidence_summary = dplyr::case_when(
            has_dgidb & has_opentargets ~ "Cross-validated",       # HIGHEST: Both databases
            total_publications >= 5 ~ "Well-documented",           # Strong publication support
            max_sources >= 3 ~ "Multi-source",                     # Multiple DGIdb sources
            has_dgidb ~ "DGIdb validated",                         # DGIdb only
            has_opentargets ~ "OpenTargets only",                  # OpenTargets only
            TRUE ~ "Limited"
          ),
          
          # Priority levels
          priority_level = dplyr::case_when(
            comprehensive_score >= stats::quantile(comprehensive_score, 0.9, na.rm = TRUE) ~ "Very High",
            comprehensive_score >= stats::quantile(comprehensive_score, 0.75, na.rm = TRUE) ~ "High",
            comprehensive_score >= stats::quantile(comprehensive_score, 0.25, na.rm = TRUE) ~ "Medium",
            TRUE ~ "Low"
          ),
          
          # Clean up
          mechanisms = ifelse(mechanisms == "" | is.na(mechanisms), "—", mechanisms),
          is_approved = any_approved
        ) %>%
        dplyr::select(
          drug_name = molecule_name,
          comprehensive_score,
          n_targets,
          target_genes,
          max_clinical_phase,
          priority_level,
          evidence_summary,
          disease_areas,
          total_publications,
          max_sources,
          mechanisms,
          is_approved,
          all_sources
        ) %>%
        dplyr::arrange(dplyr::desc(comprehensive_score))
      
      # Summary stats
      cross_validated <- sum(drug_scores$evidence_summary == "Cross-validated")
      print(paste("✓ Prioritization complete:", nrow(drug_scores), "drugs"))
      print(paste("  - Cross-validated (DGIdb + OT):", cross_validated))
      print(paste("  - Well-documented:", sum(drug_scores$evidence_summary == "Well-documented")))
      print(paste("  - Approved:", sum(drug_scores$is_approved)))
      
      return(drug_scores)
      
    }, error = function(e) {
      print(paste("❌ Error:", e$message))
      return(data.frame(
        drug_name = character(0),
        comprehensive_score = numeric(0),
        n_targets = numeric(0),
        target_genes = character(0),
        max_clinical_phase = numeric(0),
        priority_level = character(0),
        evidence_summary = character(0),
        disease_areas = character(0),
        total_publications = numeric(0),
        max_sources = numeric(0),
        mechanisms = character(0),
        is_approved = logical(0),
        all_sources = character(0)
      ))
    })
  }
  
  create_comprehensive_cross_database_insights_enhanced <- function(dgidb_data, opentargets_data) {
    
    print("=== CROSS-DATABASE INSIGHTS (DGIdb + OpenTargets) ===")
    
    insights <- list()
    
    # Cross-database validation: DGIdb ↔ OpenTargets
    if (!is.null(dgidb_data) && !is.null(opentargets_data) &&
        nrow(dgidb_data) > 0 && nrow(opentargets_data) > 0) {
      
      # Gene-level cross-validation
      dgidb_genes <- unique(dgidb_data$gene_name[!is.na(dgidb_data$gene_name)])
      ot_genes <- unique(opentargets_data$gene_name[!is.na(opentargets_data$gene_name)])
      all_genes <- unique(c(dgidb_genes, ot_genes))
      
      validation_summary <- data.frame(
        gene_name = all_genes,
        stringsAsFactors = FALSE
      ) %>%
        dplyr::mutate(
          in_dgidb = gene_name %in% dgidb_genes,
          in_opentargets = gene_name %in% ot_genes,
          validation_status = dplyr::case_when(
            in_dgidb & in_opentargets ~ "Cross-validated",
            in_dgidb & !in_opentargets ~ "DGIdb only",
            !in_dgidb & in_opentargets ~ "OpenTargets only",
            TRUE ~ "No validation"
          )
        )
      
      insights$validation_summary <- validation_summary
      
      # Drug-level overlap
      dgidb_drugs <- unique(dgidb_data$molecule_name[!is.na(dgidb_data$molecule_name)])
      ot_drugs <- unique(opentargets_data$molecule_name[!is.na(opentargets_data$molecule_name)])
      overlapping_drugs <- intersect(dgidb_drugs, ot_drugs)
      
      insights$drug_overlap <- list(
        dgidb_unique = length(dgidb_drugs),
        opentargets_unique = length(ot_drugs),
        overlapping = length(overlapping_drugs),
        overlap_percentage = if(length(union(dgidb_drugs, ot_drugs)) > 0) 
          round((length(overlapping_drugs) / length(union(dgidb_drugs, ot_drugs))) * 100, 1) else 0
      )
      
      # Coverage stats
      insights$coverage_stats <- list(
        total_genes = length(all_genes),
        cross_validated_genes = sum(validation_summary$validation_status == "Cross-validated"),
        dgidb_only_genes = sum(validation_summary$validation_status == "DGIdb only"),
        ot_only_genes = sum(validation_summary$validation_status == "OpenTargets only"),
        coverage_percentage = round((sum(validation_summary$validation_status == "Cross-validated") / length(all_genes)) * 100, 1)
      )
      
      # Database descriptions for UI
      insights$database_info <- list(
        dgidb = list(
          name = "DGIdb",
          full_name = "Drug-Gene Interaction Database",
          description = "Aggregates 40+ sources including ChEMBL, DrugBank, PharmGKB, TTD, GuideToPharmacology",
          focus = "Drug-target interactions and mechanisms of action"
        ),
        opentargets = list(
          name = "OpenTargets",
          full_name = "Open Targets Platform",
          description = "Integrates genetic, clinical, and literature evidence",
          focus = "Disease associations and clinical trial data"
        )
      )
      
      print(paste("✓ Cross-database insights created"))
      print(paste("  - Genes: DGIdb", length(dgidb_genes), "| OT", length(ot_genes), "| Cross-validated", 
                  sum(validation_summary$validation_status == "Cross-validated")))
      print(paste("  - Drugs: DGIdb", length(dgidb_drugs), "| OT", length(ot_drugs), "| Overlap", length(overlapping_drugs)))
      
    } else {
      # Single database case
      insights$validation_summary <- data.frame(
        gene_name = character(0),
        validation_status = character(0)
      )
      
      insights$drug_overlap <- list(
        dgidb_unique = if(!is.null(dgidb_data)) length(unique(dgidb_data$molecule_name)) else 0,
        opentargets_unique = if(!is.null(opentargets_data)) length(unique(opentargets_data$molecule_name)) else 0,
        overlapping = 0,
        overlap_percentage = 0
      )
      
      insights$coverage_stats <- list(
        total_genes = 0,
        cross_validated_genes = 0,
        coverage_percentage = 0
      )
    }
    
    print("✓ Enhanced cross-database insights created")
    return(insights)
  }
  
  create_comprehensive_integrated_network_enhanced <- function(chembl_data, opentargets_data, analysis_focus) {
    
    print("=== ENHANCED COMPREHENSIVE NETWORK CREATION ===")
    
    all_nodes <- data.frame()
    all_edges <- data.frame()
    
    # Collect all unique genes
    all_genes <- character(0)
    if (!is.null(chembl_data) && nrow(chembl_data) > 0) {
      all_genes <- c(all_genes, chembl_data$gene_name)
    }
    if (!is.null(opentargets_data) && nrow(opentargets_data) > 0) {
      all_genes <- c(all_genes, opentargets_data$gene_name)
    }
    
    unique_genes <- unique(all_genes[!is.na(all_genes) & all_genes != ""])
    
    if (length(unique_genes) > 0) {
      gene_nodes <- data.frame(
        id = unique_genes,
        label = unique_genes,
        group = "gene",
        color = "#3498db",
        size = 20,
        title = paste("Target Gene:", unique_genes),
        shape = "circle",
        stringsAsFactors = FALSE
      )
      all_nodes <- rbind(all_nodes, gene_nodes)
    }
    
    # Process ChEMBL/DGIdb data
    if (!is.null(chembl_data) && nrow(chembl_data) > 0) {
      
      is_dgidb <- "database" %in% colnames(chembl_data) && any(chembl_data$database == "DGIdb", na.rm = TRUE)
      
      # Ensure all required columns exist
      if (!"standard_value" %in% colnames(chembl_data)) chembl_data$standard_value <- NA_real_
      if (!"standard_type" %in% colnames(chembl_data)) chembl_data$standard_type <- NA_character_
      if (!"sources" %in% colnames(chembl_data)) chembl_data$sources <- "Unknown"
      if (!"interaction_type" %in% colnames(chembl_data)) chembl_data$interaction_type <- NA_character_
      if (!"is_approved" %in% colnames(chembl_data)) chembl_data$is_approved <- NA
      
      chembl_drugs <- chembl_data %>%
        dplyr::distinct(molecule_name, .keep_all = TRUE) %>%
        dplyr::mutate(
          id = paste0("DRUG_", gsub("[^A-Za-z0-9]", "_", molecule_name)),
          label = molecule_name,
          group = ifelse(is_dgidb, "dgidb_drug", "chembl_drug"),
          color = "#e74c3c",
          size = 15,
          shape = "square",
          title = paste0(
            ifelse(is_dgidb, "Drug: ", "ChEMBL Drug: "), molecule_name,
            "<br>Clinical Phase: ", ifelse(is.na(clinical_phase), "N/A", as.character(clinical_phase)),
            ifelse(is_dgidb,
                   paste0("<br>Approved: ", ifelse(is.na(is_approved), "Unknown", ifelse(is_approved, "Yes", "No")),
                          "<br>Sources: ", ifelse(is.na(sources), "DGIdb", sources)),
                   paste0("<br>Activity: ", ifelse(is.na(standard_value), "N/A", as.character(round(standard_value, 2)))))
          )
        ) %>%
        dplyr::select(id, label, group, color, size, shape, title)
      
      all_nodes <- rbind(all_nodes, chembl_drugs)
      
      chembl_edges <- chembl_data %>%
        dplyr::mutate(
          from = paste0("DRUG_", gsub("[^A-Za-z0-9]", "_", molecule_name)),
          to = gene_name,
          color = "#e74c3c",
          width = dplyr::case_when(
            !is.na(confidence_score) ~ pmax(1, confidence_score * 5),
            !is.na(standard_value) & standard_value > 0 ~ pmax(1, 5 - log10(standard_value + 1)),
            TRUE ~ 2
          ),
          title = paste0(
            ifelse(is_dgidb, "DGIdb Interaction", "ChEMBL Interaction"),
            ifelse(!is.na(interaction_type), paste0("<br>Type: ", interaction_type), ""),
            ifelse(!is.na(confidence_score), paste0("<br>Confidence: ", round(confidence_score, 2)), ""),
            ifelse(!is.na(standard_type) & !is.na(standard_value), 
                   paste0("<br>", standard_type, ": ", round(standard_value, 2)), ""),
            ifelse(!is.na(sources) & sources != "Unknown", paste0("<br>Sources: ", sources), "")
          ),
          database = ifelse(is_dgidb, "DGIdb", "ChEMBL"),
          dashes = FALSE
        ) %>%
        dplyr::select(from, to, color, width, title, database, dashes)
      
      all_edges <- rbind(all_edges, chembl_edges)
    }
    
    # Process OpenTargets data
    if (!is.null(opentargets_data) && nrow(opentargets_data) > 0) {
      
      if (!"disease_area" %in% colnames(opentargets_data)) opentargets_data$disease_area <- "Not specified"
      if (!"druggability_score" %in% colnames(opentargets_data)) opentargets_data$druggability_score <- NA_real_
      if (!"safety_score" %in% colnames(opentargets_data)) opentargets_data$safety_score <- NA_real_
      if (!"clinical_evidence_score" %in% colnames(opentargets_data)) opentargets_data$clinical_evidence_score <- NA_real_
      
      ot_drugs <- opentargets_data %>%
        dplyr::distinct(molecule_name, .keep_all = TRUE) %>%
        dplyr::mutate(
          id = paste0("OT_", gsub("[^A-Za-z0-9]", "_", molecule_name)),
          label = molecule_name,
          group = "opentargets_drug",
          color = "#2ecc71",
          size = 15,
          shape = "triangle",
          title = paste0(
            "OpenTargets Drug: ", molecule_name,
            "<br>Disease: ", ifelse(is.na(disease_area), "N/A", disease_area),
            "<br>Druggability: ", ifelse(is.na(druggability_score), "N/A", as.character(round(druggability_score, 2))),
            "<br>Safety: ", ifelse(is.na(safety_score), "N/A", as.character(round(safety_score, 2)))
          )
        ) %>%
        dplyr::select(id, label, group, color, size, shape, title)
      
      all_nodes <- rbind(all_nodes, ot_drugs)
      
      ot_edges <- opentargets_data %>%
        dplyr::mutate(
          from = paste0("OT_", gsub("[^A-Za-z0-9]", "_", molecule_name)),
          to = gene_name,
          color = "#2ecc71",
          width = dplyr::case_when(
            !is.na(clinical_evidence_score) ~ pmax(1, clinical_evidence_score * 5),
            !is.na(druggability_score) ~ pmax(1, druggability_score * 5),
            TRUE ~ 2
          ),
          title = paste0(
            "OpenTargets:",
            "<br>Clinical Evidence: ", ifelse(is.na(clinical_evidence_score), "N/A", as.character(round(clinical_evidence_score, 2))),
            "<br>Druggability: ", ifelse(is.na(druggability_score), "N/A", as.character(round(druggability_score, 2))),
            "<br>Disease: ", ifelse(is.na(disease_area), "N/A", disease_area)
          ),
          database = "OpenTargets",
          dashes = TRUE
        ) %>%
        dplyr::select(from, to, color, width, title, database, dashes)
      
      all_edges <- rbind(all_edges, ot_edges)
    }
    
    print(paste("✓ Enhanced network created:", nrow(all_nodes), "nodes,", nrow(all_edges), "edges"))
    
    return(list(
      nodes = all_nodes,
      edges = all_edges
    ))
  }
  
  
  
  create_comprehensive_summary_stats_enhanced <- function(chembl_data, opentargets_data, network_data, conversion_result) {
    
    print("=== ENHANCED COMPREHENSIVE SUMMARY STATS ===")
    
    # Calculate comprehensive statistics
    summary_stats <- list(
      analysis_type = "comprehensive_enhanced",
      
      # Network statistics
      network = list(
        total_nodes = if(!is.null(network_data$nodes)) nrow(network_data$nodes) else 0,
        total_edges = if(!is.null(network_data$edges)) nrow(network_data$edges) else 0,
        gene_nodes = if(!is.null(network_data$nodes)) sum(network_data$nodes$group == "gene") else 0,
        chembl_drug_nodes = if(!is.null(network_data$nodes)) sum(network_data$nodes$group == "chembl_drug") else 0,
        opentargets_drug_nodes = if(!is.null(network_data$nodes)) sum(network_data$nodes$group == "opentargets_drug") else 0,
        network_density = if(!is.null(network_data$nodes) && nrow(network_data$nodes) > 1) {
          n_nodes <- nrow(network_data$nodes)
          n_edges <- if(!is.null(network_data$edges)) nrow(network_data$edges) else 0
          round((2 * n_edges) / (n_nodes * (n_nodes - 1)), 4)
        } else { 0 }
      ),
      
      # Enhanced ChEMBL statistics
      chembl_stats = if(!is.null(chembl_data) && nrow(chembl_data) > 0) {
        list(
          total_interactions = nrow(chembl_data),
          unique_drugs = length(unique(chembl_data$molecule_name)),
          unique_targets = length(unique(chembl_data$gene_name)),
          clinical_stage_drugs = sum(chembl_data$clinical_phase > 0, na.rm = TRUE),
          high_confidence = sum(chembl_data$confidence_score > 0.7, na.rm = TRUE),
          bioactive_compounds = sum(chembl_data$standard_value <= 1000, na.rm = TRUE),
          activity_types = if("standard_type" %in% colnames(chembl_data)) length(unique(chembl_data$standard_type)) else 0
        )
      } else {
        list(total_interactions = 0, unique_drugs = 0, unique_targets = 0,
             clinical_stage_drugs = 0, high_confidence = 0, bioactive_compounds = 0, activity_types = 0)
      },
      
      # Enhanced OpenTargets statistics
      opentargets_stats = if(!is.null(opentargets_data) && nrow(opentargets_data) > 0) {
        list(
          total_associations = nrow(opentargets_data),
          unique_drugs = length(unique(opentargets_data$molecule_name)),
          unique_targets = length(unique(opentargets_data$gene_name)),
          druggable_targets = sum(opentargets_data$druggability_score > 0.7, na.rm = TRUE),
          high_clinical_evidence = sum(opentargets_data$clinical_evidence_score > 0.7, na.rm = TRUE),
          safe_compounds = sum(opentargets_data$safety_score > 0.7, na.rm = TRUE),
          disease_areas = if("disease_area" %in% colnames(opentargets_data)) length(unique(opentargets_data$disease_area)) else 0
        )
      } else {
        list(total_associations = 0, unique_drugs = 0, unique_targets = 0,
             druggable_targets = 0, high_clinical_evidence = 0, safe_compounds = 0, disease_areas = 0)
      },
      
      # Cross-database integration metrics
      integration_stats = list(
        total_unique_drugs = length(unique(c(
          if(!is.null(chembl_data)) chembl_data$molecule_name else character(0),
          if(!is.null(opentargets_data)) opentargets_data$molecule_name else character(0)
        ))),
        total_unique_targets = length(unique(c(
          if(!is.null(chembl_data)) chembl_data$gene_name else character(0),
          if(!is.null(opentargets_data)) opentargets_data$gene_name else character(0)
        ))),
        cross_validated_targets = if(!is.null(chembl_data) && !is.null(opentargets_data)) {
          length(intersect(unique(chembl_data$gene_name), unique(opentargets_data$gene_name)))
        } else { 0 }
      ),
      
      # Gene conversion statistics
      conversion_stats = conversion_result$conversion_stats %||% list(
        total_input = 0,
        successful_symbols = 0,
        successful_ensembl = 0
      )
    )
    
    # Add convenience accessors for UI components
    summary_stats$chembl_drugs <- summary_stats$chembl_stats$unique_drugs
    summary_stats$chembl_targets <- summary_stats$chembl_stats$unique_targets
    summary_stats$opentargets_drugs <- summary_stats$opentargets_stats$unique_drugs
    summary_stats$opentargets_targets <- summary_stats$opentargets_stats$unique_targets
    
    print("✓ Enhanced comprehensive summary statistics created")
    return(summary_stats)
  }
  
  # 3. COMPREHENSIVE GENE CONVERSION (SYMBOLS + ENSEMBL)
  # ============================================================================
  
  enhanced_comprehensive_gene_conversion_fixed <- function(gene_ids, organism = "human") {
    
    print("=== COMPREHENSIVE GENE CONVERSION (FIXED) ===")
    print(paste("Converting", length(gene_ids), "gene IDs for comprehensive analysis"))
    
    # Clean gene IDs first (remove suffixes like "_red vs green")
    cleaned_ids <- sapply(gene_ids, function(x) {
      # Remove common suffixes like "_red vs green", "_up", "_down", etc.
      x <- gsub("_.*vs.*", "", x, ignore.case = TRUE)
      x <- gsub("_.*", "", x)  # Remove any remaining suffixes
      x <- gsub("\\..*", "", x)  # Remove version numbers
      return(trimws(x))
    })
    
    print(paste("Cleaned sample:", paste(head(cleaned_ids, 3), collapse = ", ")))
    
    # Detect input ID types
    ensembl_pattern <- grepl("^ENSG[0-9]+", cleaned_ids)
    symbol_pattern <- grepl("^[A-Z][A-Z0-9-]*$", cleaned_ids) & !ensembl_pattern
    
    print(paste("ENSEMBL IDs detected:", sum(ensembl_pattern)))
    print(paste("Gene symbols detected:", sum(symbol_pattern)))
    
    # Initialize results
    symbols <- character(0)
    ensembl_ids <- character(0)
    
    # Process ENSEMBL IDs (these are already ENSEMBL, need to convert to symbols)
    if (sum(ensembl_pattern) > 0) {
      current_ensembl <- cleaned_ids[ensembl_pattern]
      ensembl_ids <- c(ensembl_ids, current_ensembl)
      
      print("Converting ENSEMBL IDs to symbols for ChEMBL...")
      # Convert ENSEMBL to symbols
      converted_symbols <- convert_ensembl_to_symbols(current_ensembl)
      symbols <- c(symbols, converted_symbols)
      
      print(paste("Converted", length(converted_symbols), "ENSEMBL IDs to symbols"))
    }
    
    # Process symbols (these are already symbols, need to get ENSEMBL IDs)
    if (sum(symbol_pattern) > 0) {
      current_symbols <- cleaned_ids[symbol_pattern]
      symbols <- c(symbols, current_symbols)
      
      print("Converting symbols to ENSEMBL IDs for OpenTargets...")
      # Convert symbols to ENSEMBL
      converted_ensembl <- convert_symbols_to_ensembl_efficient(current_symbols)
      ensembl_ids <- c(ensembl_ids, converted_ensembl)
      
      print(paste("Converted", length(converted_ensembl), "symbols to ENSEMBL IDs"))
    }
    
    # Remove duplicates and empty values
    symbols <- unique(symbols[!is.na(symbols) & symbols != ""])
    ensembl_ids <- unique(ensembl_ids[!is.na(ensembl_ids) & ensembl_ids != ""])
    
    print(paste("FINAL RESULTS:"))
    print(paste("- Symbols for ChEMBL:", length(symbols)))
    print(paste("- ENSEMBL IDs for OpenTargets:", length(ensembl_ids)))
    print(paste("- Symbol sample:", paste(head(symbols, 3), collapse = ", ")))
    print(paste("- ENSEMBL sample:", paste(head(ensembl_ids, 3), collapse = ", ")))
    
    return(list(
      symbols = symbols,
      ensembl_ids = ensembl_ids,
      original_ids = gene_ids,
      cleaned_ids = cleaned_ids,
      conversion_stats = list(
        total_input = length(gene_ids),
        successful_symbols = length(symbols),
        successful_ensembl = length(ensembl_ids)
      )
    ))
  }
  
  convert_ensembl_to_symbols <- function(ensembl_ids) {
    
    if (length(ensembl_ids) == 0) return(character(0))
    
    print("Converting ENSEMBL IDs to gene symbols...")
    
    # Try using your existing conversion function first
    tryCatch({
      # Use your existing enhanced_gene_id_conversion_no_mock_fixed function
      conversion_result <- enhanced_gene_id_conversion_no_mock_fixed(ensembl_ids, "human")
      if (!is.null(conversion_result$symbols) && length(conversion_result$symbols) > 0) {
        print(paste("Successfully converted", length(conversion_result$symbols), "ENSEMBL IDs using existing function"))
        return(conversion_result$symbols)
      }
    }, error = function(e) {
      print(paste("Existing conversion function failed:", e$message))
    })
    
    # Fallback: Create meaningful symbols from ENSEMBL IDs
    print("Using fallback conversion for ENSEMBL IDs...")
    fallback_symbols <- paste0("GENE_", gsub("ENSG0+", "", ensembl_ids))
    
    return(fallback_symbols)
  }
  
  
  
  
