  combine_chembl_opentargets_data <- function(chembl_data, opentargets_data) {
    
    print("=== COMBINING DGIdb and OpenTargets data ===")
    
    all_data <- data.frame()
    
    if (!is.null(chembl_data) && nrow(chembl_data) > 0) {
      chembl_standardized <- chembl_data %>%
        dplyr::mutate(
          data_source = "ChEMBL",
          data_quality = "Bioactivity"
        )
      all_data <- rbind(all_data, chembl_standardized)
    }
    
    if (!is.null(opentargets_data) && nrow(opentargets_data) > 0) {
      opentargets_standardized <- opentargets_data %>%
        dplyr::mutate(
          data_source = "OpenTargets",
          data_quality = "Clinical"
        )
      all_data <- rbind(all_data, opentargets_standardized)
    }
    
    print(paste("Combined data:", nrow(all_data), "total interactions"))
    return(all_data)
  }
  
  create_comprehensive_multi_factor_prioritization <- function(combined_data, selected_genes) {
    
    if (is.null(combined_data) || nrow(combined_data) == 0) {
      return(data.frame(
        drug_name = character(0),
        comprehensive_score = numeric(0),
        chembl_evidence = character(0),
        opentargets_evidence = character(0),
        priority_level = character(0)
      ))
    }
    
    # Multi-factor scoring for comprehensive analysis
    drug_scores <- combined_data %>%
      dplyr::group_by(molecule_name) %>%
      dplyr::summarise(
        n_targets = dplyr::n_distinct(gene_name),
        chembl_evidence = any(data_source == "ChEMBL"),
        opentargets_evidence = any(data_source == "OpenTargets"),
        max_clinical_phase = max(clinical_phase, na.rm = TRUE),
        avg_confidence = mean(confidence_score, na.rm = TRUE),
        disease_areas = paste(unique(disease_area[!is.na(disease_area)]), collapse = "; "),
        .groups = 'drop'
      ) %>%
      dplyr::mutate(
        # Multi-database bonus
        cross_database_bonus = ifelse(chembl_evidence & opentargets_evidence, 1.5, 1.0),
        
        # Component scores
        target_score = log2(n_targets + 1),
        clinical_score = pmax(max_clinical_phase, 0) / 4,
        confidence_score = avg_confidence,
        
        # Comprehensive score
        comprehensive_score = (target_score + clinical_score + confidence_score) * cross_database_bonus,
        
        # Evidence summary
        evidence_summary = dplyr::case_when(
          chembl_evidence & opentargets_evidence ~ "Cross-validated",
          chembl_evidence ~ "DGIdb Only",
          opentargets_evidence ~ "OpenTargets only",
          TRUE ~ "No evidence"
        ),
        
        # Priority level
        priority_level = dplyr::case_when(
          comprehensive_score >= stats::quantile(comprehensive_score, 0.8, na.rm = TRUE) ~ "Very High",
          comprehensive_score >= stats::quantile(comprehensive_score, 0.6, na.rm = TRUE) ~ "High",
          comprehensive_score >= stats::quantile(comprehensive_score, 0.4, na.rm = TRUE) ~ "Medium",
          TRUE ~ "Low"
        )
      ) %>%
      dplyr::arrange(desc(comprehensive_score))
    
    return(drug_scores)
  }
  
