            dplyr::filter(gene_name == gene) %>%
            nrow()
          
          ot_drugs <- network_rv$current_results$opentargets_data %>%
            dplyr::filter(gene_name == gene) %>%
            nrow()
          
          max_clinical <- max(
            c(network_rv$current_results$chembl_data$clinical_phase[network_rv$current_results$chembl_data$gene_name == gene],
              network_rv$current_results$opentargets_data$clinical_phase[network_rv$current_results$opentargets_data$gene_name == gene]),
            na.rm = TRUE
          )
          
          cross_val_details <- rbind(cross_val_details, data.frame(
            Target = gene,
            ChEMBL_Drugs = chembl_drugs,
            OpenTargets_Drugs = ot_drugs,
            Total_Drugs = chembl_drugs + ot_drugs,
            Max_Clinical_Phase = max_clinical,
            Confidence = "High",
            stringsAsFactors = FALSE
          ))
        }
        
        DT::datatable(
          cross_val_details,
          options = list(pageLength = 5, dom = 't'),
