    print(paste("Has chembl_data:", !is.null(network_rv$current_results$chembl_data)))
    print(paste("Has opentargets_data:", !is.null(network_rv$current_results$opentargets_data)))
    print(paste("ChEMBL rows:", if(!is.null(network_rv$current_results$chembl_data)) nrow(network_rv$current_results$chembl_data) else 0))
    print(paste("OpenTargets rows:", if(!is.null(network_rv$current_results$opentargets_data)) nrow(network_rv$current_results$opentargets_data) else 0))
    print(paste("Has integrated_insights:", !is.null(network_rv$current_results$integrated_insights)))
    
    # Check the analysis focus requirement
    if (!is.null(network_rv$current_results$analysis_params) &&
        network_rv$current_results$analysis_params$analysis_focus == "comprehensive") {
      
      print("DIAGNOSTIC: Analysis focus is comprehensive, proceeding...")
      
      # Check if we have actual data
      chembl_genes <- character(0)
      ot_genes <- character(0)
      
      if (!is.null(network_rv$current_results$chembl_data) && nrow(network_rv$current_results$chembl_data) > 0) {
        chembl_genes <- unique(network_rv$current_results$chembl_data$gene_name)
        print(paste("DIAGNOSTIC: ChEMBL genes found:", length(chembl_genes)))
        print(paste("DIAGNOSTIC: Sample ChEMBL genes:", paste(head(chembl_genes, 3), collapse = ", ")))
      }
      
      if (!is.null(network_rv$current_results$opentargets_data) && nrow(network_rv$current_results$opentargets_data) > 0) {
        ot_genes <- unique(network_rv$current_results$opentargets_data$gene_name)
        print(paste("DIAGNOSTIC: OpenTargets genes found:", length(ot_genes)))
        print(paste("DIAGNOSTIC: Sample OpenTargets genes:", paste(head(ot_genes, 3), collapse = ", ")))
      }
      
      if (length(chembl_genes) > 0 || length(ot_genes) > 0) {
        all_genes <- unique(c(chembl_genes, ot_genes))
        print(paste("DIAGNOSTIC: Total unique genes:", length(all_genes)))
        
        validation_summary <- data.frame(
          gene_name = all_genes,
          stringsAsFactors = FALSE
        ) %>%
          dplyr::mutate(
            validation_status = dplyr::case_when(
              gene_name %in% chembl_genes & gene_name %in% ot_genes ~ "Cross-validated",
              gene_name %in% chembl_genes ~ "DGIdb Only",
              gene_name %in% ot_genes ~ "OpenTargets only",
              TRUE ~ "No data"
            )
          ) %>%
          dplyr::count(validation_status, name = "Count") %>%
          dplyr::mutate(
            Percentage = round((Count / sum(Count)) * 100, 1)
          )
        
        print("DIAGNOSTIC: Validation summary created:")
        print(validation_summary)
        
        DT::datatable(
          validation_summary,
          options = list(pageLength = 10, dom = 'frtip'),
          rownames = FALSE,
          colnames = c("Validation Status", "Target Count", "Percentage")
        ) %>%
          DT::formatStyle(
            'validation_status',
            backgroundColor = DT::styleEqual(
              c("Cross-validated", "DGIdb Only", "OpenTargets only"),
              c('#d4edda', '#e7f3ff', '#fff3cd')
            )
          )
      } else {
        print("DIAGNOSTIC: No genes found in either database")
        DT::datatable(data.frame(Message = "DIAGNOSTIC: No genes found in ChEMBL or OpenTargets data"))
      }
    } else {
      print("DIAGNOSTIC: Analysis focus is not comprehensive or analysis_params missing")
      print("DIAGNOSTIC: Available analysis_params:")
      print(str(network_rv$current_results$analysis_params))
      DT::datatable(data.frame(Message = paste("DIAGNOSTIC: Analysis focus is",
                                               network_rv$current_results$analysis_params$analysis_focus %||% "MISSING")))
    }
  })
  
