      # Top level structure
      top_level_names = names(network_rv$current_results)
    )
    
    return(structure_info)
  })
  
  # Comprehensive ChEMBL table
  output$comprehensive_chembl_table <- DT::renderDataTable({
    req(network_rv$current_results)
    
    # Works for both drug_discovery and comprehensive modes
    if (!is.null(network_rv$current_results$chembl_data) && 
        nrow(network_rv$current_results$chembl_data) > 0) {
      
      print("=== RENDERING ENHANCED DRUG INTERACTIONS TABLE ===")
      drug_data <- network_rv$current_results$chembl_data
      
      # Ensure all display columns exist
      if (!"interaction_type" %in% colnames(drug_data)) {
        drug_data$interaction_type <- "Unknown"
      }
      if (!"sources" %in% colnames(drug_data)) {
        drug_data$sources <- drug_data$database_source %||% "DGIdb"
      }
      if (!"n_sources" %in% colnames(drug_data)) {
        drug_data$n_sources <- 1
      }
      if (!"n_publications" %in% colnames(drug_data)) {
        drug_data$n_publications <- 0
      }
      if (!"is_approved" %in% colnames(drug_data)) {
        drug_data$is_approved <- drug_data$clinical_phase >= 4
      }
      if (!"pmids" %in% colnames(drug_data)) {
        drug_data$pmids <- NA_character_
      }
      
      # Count drugs per gene
      gene_counts <- drug_data %>%
        dplyr::group_by(gene_name) %>%
        dplyr::summarise(n_drugs = dplyr::n(), .groups = 'drop')
      
      # Prepare display data with LINKS
      display_data <- drug_data %>%
        dplyr::left_join(gene_counts, by = "gene_name") %>%
        dplyr::arrange(gene_name, dplyr::desc(confidence_score)) %>%
        dplyr::mutate(
          # Gene column with drug count
          Gene = paste0(gene_name, " (", n_drugs, " drugs)"),
          
          # Drug name with link to DGIdb
          Drug = sprintf(
            '<a href="https://www.dgidb.org/results?searchType=drug&searchTerms=%s" target="_blank" 
             style="color: #1976d2; font-weight: 500; text-decoration: none;">
             %s <i class="fa fa-external-link" style="font-size: 10px;"></i>
           </a>',
            URLencode(molecule_name), molecule_name
          ),
          
          # Interaction type - clean up "Unknown"
          `Interaction Type` = dplyr::case_when(
            is.na(interaction_type) | interaction_type == "" | interaction_type == "Unknown" ~ "—",
            TRUE ~ interaction_type
          ),
          
          # Status badge
          Status = dplyr::case_when(
            is_approved == TRUE ~ '<span style="background:#27ae60;color:white;padding:2px 8px;border-radius:12px;font-size:11px;font-weight:500;">✓ Approved</span>',
            clinical_phase >= 3 ~ '<span style="background:#3498db;color:white;padding:2px 8px;border-radius:12px;font-size:11px;">Phase III</span>',
            clinical_phase >= 2 ~ '<span style="background:#9b59b6;color:white;padding:2px 8px;border-radius:12px;font-size:11px;">Phase II</span>',
            clinical_phase >= 1 ~ '<span style="background:#e67e22;color:white;padding:2px 8px;border-radius:12px;font-size:11px;">Phase I</span>',
            TRUE ~ '<span style="background:#95a5a6;color:white;padding:2px 8px;border-radius:12px;font-size:11px;">Research</span>'
          ),
          
          # Confidence with color coding
          Confidence = confidence_score,
          
          # Evidence column - shows source count and publications
          Evidence = dplyr::case_when(
            n_sources >= 3 & n_publications >= 3 ~ 
              sprintf('<span style="color:#27ae60;font-weight:bold;">●●●</span> %d sources, %d pubs', n_sources, n_publications),
            n_sources >= 2 | n_publications >= 2 ~ 
              sprintf('<span style="color:#f39c12;font-weight:bold;">●●</span> %d sources, %d pubs', n_sources, n_publications),
            TRUE ~ 
              sprintf('<span style="color:#95a5a6;">●</span> %d source', n_sources)
          ),
          
          # Sources column - truncated with tooltip
          Sources = ifelse(
            nchar(sources) > 30,
            sprintf('<span title="%s">%s...</span>', sources, substr(sources, 1, 27)),
            sources
          ),
          
          # Links column - icons for external resources
          Links = sprintf(
            '<div style="white-space: nowrap;">
             <a href="https://www.dgidb.org/results?searchType=drug&searchTerms=%s" target="_blank" 
                title="View in DGIdb" style="margin-right:8px;color:#1976d2;">
                <i class="fa fa-database"></i>
             </a>
             <a href="https://pubmed.ncbi.nlm.nih.gov/?term=%s" target="_blank" 
                title="Search PubMed" style="margin-right:8px;color:#e91e63;">
                <i class="fa fa-book"></i>
             </a>
             <a href="https://clinicaltrials.gov/search?term=%s" target="_blank" 
                title="Search Clinical Trials" style="color:#4caf50;">
                <i class="fa fa-flask"></i>
             </a>
           </div>',
            URLencode(molecule_name),
            URLencode(paste(molecule_name, gene_name)),
            URLencode(molecule_name)
          )
        ) %>%
        dplyr::select(Gene, Drug, `Interaction Type`, Status, Confidence, Evidence, Sources, Links)
      
      # Create DataTable
      DT::datatable(
        display_data,
        escape = FALSE,
        rownames = FALSE,
        filter = 'top',
        options = list(
          pageLength = 15,
          scrollX = TRUE,
          dom = 'Bfrtip',
          order = list(list(4, 'desc')),  # Sort by confidence
          columnDefs = list(
            list(className = 'dt-center', targets = c(2, 3, 4, 5)),
            list(width = '120px', targets = 0),
            list(width = '150px', targets = 1),
            list(width = '100px', targets = 7)
          )
        )
      ) %>%
        DT::formatRound(columns = c("Confidence"), digits = 3) %>%
        DT::formatStyle(
          'Confidence',
          background = DT::styleColorBar(c(0, 1), '#e3f2fd'),
          backgroundSize = '95% 60%',
          backgroundRepeat = 'no-repeat',
          backgroundPosition = 'center'
        ) %>%
        DT::formatStyle(
          'Status',
          backgroundColor = 'white'
        )
      
    } else {
      DT::datatable(data.frame(Message = "No drug interaction data available"))
    }
  })
  
  output$analysis_summary_message <- renderUI({
    req(network_rv$current_results)
    
    analysis_focus <- network_rv$current_results$analysis_params$analysis_focus %||% "unknown"
    chembl_count <- if(!is.null(network_rv$current_results$chembl_data)) nrow(network_rv$current_results$chembl_data) else 0
    ot_count <- if(!is.null(network_rv$current_results$opentargets_data)) nrow(network_rv$current_results$opentargets_data) else 0
    
    if (analysis_focus == "drug_discovery" && chembl_count == 0 && ot_count > 0) {
      div(class = "alert alert-info",
          h5(icon("info-circle"), " Analysis Summary"),
          p("No bioactive compounds found in ChEMBL meeting drug discovery criteria, but ",
            ot_count, " clinical associations found in OpenTargets."),
          p(strong("Suggestion:"), " Try adjusting the activity threshold or explore the Clinical Evidence tab for therapeutic insights.")
      )
    } else if (chembl_count == 0 && ot_count == 0) {
      div(class = "alert alert-warning",
          h5(icon("exclamation-triangle"), " No Results Found"),
          p("No drug interactions found for your input genes in either database."),
          p(strong("This could mean:")),
          tags$ul(
            tags$li("Your genes are not well-studied drug targets"),
            tags$li("The analysis parameters are too restrictive"),
            tags$li("These genes may be better suited for other types of analysis (PPI, GRN, etc.)")
          )
      )
    } else {
      div(class = "alert alert-success",
          h5(icon("check-circle"), " Analysis Complete"),
          p("Found ", chembl_count + ot_count, " total drug-target interactions (",
            chembl_count, " from ChEMBL, ", ot_count, " from OpenTargets).")
      )
    }
  })
  
  # Comprehensive OpenTargets table
  output$comprehensive_opentargets_table <- DT::renderDataTable({
    req(network_rv$current_results)
    
    print("=== DIAGNOSTIC: Rendering OpenTargets Table (Fixing Index & Links) ===")
    
    # FIX: Include both "comprehensive" AND "disease_context" modes
    if (!is.null(network_rv$current_results$analysis_params) &&
        network_rv$current_results$analysis_params$analysis_focus %in% c("comprehensive", "disease_context")) {
      
      if (!is.null(network_rv$current_results$opentargets_data) && nrow(network_rv$current_results$opentargets_data) > 0) {
        
        ot_raw <- network_rv$current_results$opentargets_data
        
        # 1. Ensure all required columns exist (handle legacy data and API variations)
        if (!"molecule_id" %in% names(ot_raw)) ot_raw$molecule_id <- "Unknown"
        if (!"disease_area" %in% names(ot_raw)) ot_raw$disease_area <- "Not specified"
        if (!"druggability_score" %in% names(ot_raw)) {
          ot_raw$druggability_score <- dplyr::case_when(
            ot_raw$clinical_phase >= 4 ~ 0.95,
            ot_raw$clinical_phase == 3 ~ 0.85,
            ot_raw$clinical_phase == 2 ~ 0.75,
            ot_raw$clinical_phase == 1 ~ 0.65,
            TRUE ~ 0.55
          )
        }
        if (!"safety_score" %in% names(ot_raw)) {
          ot_raw$safety_score <- dplyr::case_when(
            ot_raw$clinical_phase >= 4 ~ 0.9,
            ot_raw$clinical_phase >= 2 ~ 0.7,
            TRUE ~ 0.5
          )
        }
        if (!"clinical_evidence_score" %in% names(ot_raw)) {
          ot_raw$clinical_evidence_score <- dplyr::case_when(
            ot_raw$clinical_phase >= 3 ~ 0.85,
            ot_raw$clinical_phase >= 1 ~ 0.65,
            TRUE ~ 0.55
          )
        }
        
        # 2. Vectorized Link Creation (Safer than mapply)
        # Pre-calculate URLs to avoid complex logic inside mutate
        ot_raw$target_url <- ifelse(
          !is.na(ot_raw$molecule_id) & ot_raw$molecule_id != "Unknown" & ot_raw$molecule_id != "",
          paste0("https://platform.opentargets.org/drug/", ot_raw$molecule_id),
          paste0("https://platform.opentargets.org/search?q=", gsub(" ", "+", ot_raw$molecule_name))
        )
        
        ot_raw$drug_link_html <- sprintf(
          '<a href="%s" target="_blank" title="View on OpenTargets" style="color: #3489ca; font-weight: 500; text-decoration: none;">%s <i class="fa fa-external-link-square" style="font-size: 11px; opacity: 0.7;"></i></a>',
          ot_raw$target_url, ot_raw$molecule_name
        )
        
        # 3. Create Search Blob (Handle NAs safely)
        search_data_map <- ot_raw %>%
          dplyr::group_by(gene_name) %>%
          dplyr::summarise(
            hidden_search_string = paste(
              unique(na.omit(c(molecule_name, disease_area, clinical_phase))), 
              collapse = " "
            ),
            .groups = 'drop'
          )
        
        # Sort
        ot_sorted <- ot_raw %>%
          dplyr::arrange(gene_name, desc(clinical_evidence_score))
        
        # Group counts
        gene_counts <- ot_sorted %>%
          dplyr::group_by(gene_name) %>%
          dplyr::summarise(total_for_gene = n(), .groups = 'drop')
        
        # 4. Prepare Primary Rows
        primary_rows <- ot_sorted %>%
          dplyr::group_by(gene_name) %>%
          dplyr::slice_head(n = 1) %>%
          dplyr::ungroup() %>%
          dplyr::left_join(gene_counts, by = "gene_name") %>%
          dplyr::left_join(search_data_map, by = "gene_name") %>%
          dplyr::mutate(
            Gene_Display = ifelse(
              total_for_gene > 1,
              sprintf(
                '<span class="gene-toggle" data-gene="%s" style="cursor:pointer; font-weight:bold; color:#2c3e50;">
                 <i class="fa fa-caret-right" style="margin-right: 5px; color: #666; width: 10px;"></i> %s 
                 <span style="color: #999; font-weight: normal; font-size: 11px;">(+%d more)</span>
               </span>', 
                gene_name, gene_name, total_for_gene - 1
              ),
              sprintf('<span style="padding-left: 19px;">%s</span>', gene_name)
            )
          ) %>%
          dplyr::select(
            gene_name,
            Gene = Gene_Display,
            Drug = drug_link_html,
            Disease_Area = disease_area,
            Clinical_Phase = clinical_phase,
            Druggability = druggability_score,
            Safety = safety_score,
            Clinical_Evidence = clinical_evidence_score,
            Hidden_Search = hidden_search_string
          )
        
        # 5. Prepare Child Rows
        child_rows_data <- ot_sorted %>%
          dplyr::group_by(gene_name) %>%
          dplyr::slice_tail(n = -1) %>%
          dplyr::ungroup()
        
        # 6. Generate Child HTML
        child_html_map <- list()
        # Iterate only over genes that actually have child rows
        genes_with_children <- unique(child_rows_data$gene_name)
        
        for (gene in genes_with_children) {
          gene_data <- child_rows_data %>% dplyr::filter(gene_name == gene)
          
          if (nrow(gene_data) > 0) {
            rows_html <- sapply(1:nrow(gene_data), function(i) {
              sprintf(
                '<tr style="background-color: #f8f9fa;">
                <td style="padding-left: 40px; border-left: 3px solid #3489ca;">%s</td>
                <td style="text-align: center;">%s</td>
                <td style="text-align: center;">%s</td>
                <td style="text-align: center;">%s</td>
                <td style="text-align: center;">%s</td>
                <td style="text-align: center; background: linear-gradient(to right, #d4edda %s%%, transparent %s%%); background-size: 100%% 70%%; background-repeat: no-repeat; background-position: center;">%s</td>
              </tr>',
                gene_data$drug_link_html[i],
                gene_data$disease_area[i],
                gene_data$clinical_phase[i],
                round(as.numeric(gene_data$druggability_score[i]), 3),
                round(as.numeric(gene_data$safety_score[i]), 3),
                as.numeric(gene_data$clinical_evidence_score[i]) * 100,
                as.numeric(gene_data$clinical_evidence_score[i]) * 100,
                round(as.numeric(gene_data$clinical_evidence_score[i]), 3)
              )
            })
            
            child_html_map[[gene]] <- sprintf(
              '<div style="padding: 10px; background: #ffffff; margin: 5px 0; border: 1px solid #dee2e6;">
              <h6 style="margin: 0 0 10px 0; color: #666; font-size: 12px; font-weight: bold;">Additional Indications for %s</h6>
              <table style="width: 100%%; border-collapse: collapse;">
                <thead style="background-color: #e9ecef;">
                  <tr>
                    <th style="padding: 8px;">Drug</th>
                    <th style="padding: 8px; text-align: center;">Disease Area</th>
                    <th style="padding: 8px; text-align: center;">Clinical Phase</th>
                    <th style="padding: 8px; text-align: center;">Druggability</th>
                    <th style="padding: 8px; text-align: center;">Safety</th>
                    <th style="padding: 8px; text-align: center;">Clinical Evidence</th>
                  </tr>
                </thead>
                <tbody>%s</tbody>
              </table>
            </div>',
              gene, paste(rows_html, collapse = "\n")
            )
          }
        }
        
        child_json <- jsonlite::toJSON(child_html_map, auto_unbox = TRUE)
        
        # 7. Render DataTable
        DT::datatable(
          primary_rows %>% dplyr::select(-gene_name),
          escape = FALSE,
          rownames = FALSE,
          selection = 'none',
          options = list(
            pageLength = 10,
            scrollX = TRUE,
            dom = 'frtip',
            columnDefs = list(
              list(className = 'dt-center', targets = c(3, 4, 5, 6, 7)), # Center numbers
              list(width = '150px', targets = 0),
              list(width = '200px', targets = 1),
              # FIX: Target Index 7 for Hidden_Search (It is the 8th column: 0,1,2,3,4,5,6,7)
              list(visible = FALSE, targets = 7) 
            )
          ),
          class = 'cell-border stripe hover',
          style = 'bootstrap4',
          callback = JS(sprintf("
          var childData = %s;
          
          table.on('click', 'td:first-child', function() {
            var td = $(this);
            var tr = td.closest('tr');
            var row = table.row(tr);
            var toggle = td.find('.gene-toggle');
            
            if (toggle.length === 0) return;
            
            var geneName = toggle.data('gene');
            var icon = toggle.find('i');
            
            if (row.child.isShown()) {
              row.child.hide();
              tr.removeClass('shown');
              icon.removeClass('fa-caret-down').addClass('fa-caret-right');
            } else {
              if (childData[geneName]) {
                row.child(childData[geneName]).show();
                tr.addClass('shown');
                icon.removeClass('fa-caret-right').addClass('fa-caret-down');
              }
            }
          });
          
          $('head').append('<style>table.dataTable tbody tr.shown { background-color: white !important; }</style>');
        ", child_json))
        ) %>%
          DT::formatRound(columns = c("Druggability", "Safety", "Clinical_Evidence"), digits = 3) %>%
          DT::formatStyle(
            'Clinical_Evidence',
            background = DT::styleColorBar(c(0, 1), '#d4edda'),
            backgroundSize = '98% 70%',
            backgroundRepeat = 'no-repeat',
            backgroundPosition = 'center'
          ) %>%
          DT::formatStyle(
            'Gene',
            fontWeight = '600',
            color = '#2c3e50'
          ) %>%
          DT::formatStyle(
            columns = 0:8,
            fontSize = '13px'
          )
        
      } else {
        DT::datatable(
          data.frame(Message = "No clinical evidence data available from OpenTargets for the selected genes."),
          options = list(dom = 't'),
          rownames = FALSE
        )
      }
    } else {
      DT::datatable(
        data.frame(Message = "Clinical evidence data not available. Run analysis in Disease Context or Comprehensive mode."),
        options = list(dom = 't'),
        rownames = FALSE
      )
    }
  })
  
  # Comprehensive drug prioritization table
  output$comprehensive_drug_priorities_filtered <- DT::renderDataTable({
    req(network_rv$current_results)
    req(network_rv$current_results$analysis_params$analysis_focus == "comprehensive")
    
    if (!is.null(network_rv$current_results$drug_prioritization) &&
        nrow(network_rv$current_results$drug_prioritization) > 0) {
      
      priority_data <- network_rv$current_results$drug_prioritization
      
      # Apply filters
      if (!is.null(input$disease_filter) && input$disease_filter != "all") {
        priority_data <- priority_data %>%
          dplyr::filter(grepl(input$disease_filter, disease_areas, ignore.case = TRUE))
      }
      
      if (!is.null(input$evidence_filter) && input$evidence_filter != "all") {
        priority_data <- priority_data %>%
          dplyr::filter(evidence_summary == input$evidence_filter)
      }
      
      if (!is.null(input$priority_filter) && input$priority_filter != "all") {
        priority_data <- priority_data %>%
          dplyr::filter(priority_level == input$priority_filter)
      }
      
      # Ensure columns exist
      if (!"total_publications" %in% colnames(priority_data)) priority_data$total_publications <- 0
      if (!"max_sources" %in% colnames(priority_data)) priority_data$max_sources <- 1
      if (!"mechanisms" %in% colnames(priority_data)) priority_data$mechanisms <- "—"
      if (!"is_approved" %in% colnames(priority_data)) priority_data$is_approved <- priority_data$max_clinical_phase >= 4
      
      # Create display table
      priority_display <- priority_data %>%
        dplyr::mutate(
          # Drug with link
          Drug = sprintf(
            '<a href="https://www.dgidb.org/results?searchType=drug&searchTerms=%s" target="_blank" 
             style="color: #1976d2; font-weight: 600;">%s</a>',
            URLencode(drug_name), drug_name
          ),
          
          # Priority badge with "Very High" support
          Priority = dplyr::case_when(
            priority_level == "Very High" ~ '<span style="background:#1565c0;color:white;padding:3px 10px;border-radius:12px;font-weight:600;">Very High</span>',
            priority_level == "High" ~ '<span style="background:#27ae60;color:white;padding:3px 10px;border-radius:12px;font-weight:500;">High</span>',
            priority_level == "Medium" ~ '<span style="background:#f39c12;color:white;padding:3px 10px;border-radius:12px;font-weight:500;">Medium</span>',
            TRUE ~ '<span style="background:#95a5a6;color:white;padding:3px 10px;border-radius:12px;">Low</span>'
          ),
          
          Score = round(comprehensive_score, 2),
          Targets = n_targets,
          
          `Target Genes` = ifelse(
            nchar(target_genes) > 35,
            paste0(substr(target_genes, 1, 32), "..."),
            target_genes
          ),
          
          # Evidence with cross-validation highlighting
          Evidence = dplyr::case_when(
            evidence_summary == "Cross-validated" ~ 
              '<span style="color:#9c27b0;font-weight:bold;">★★★</span> <span style="color:#9c27b0;">Cross-validated</span>',
            evidence_summary == "Well-documented" ~ 
              sprintf('<span style="color:#27ae60;font-weight:bold;">●●●</span> %d pubs', total_publications),
            evidence_summary == "Multi-source" ~ 
              sprintf('<span style="color:#f39c12;font-weight:bold;">●●</span> %d sources', max_sources),
            evidence_summary == "DGIdb validated" ~ 
              '<span style="color:#2196f3;font-weight:bold;">●●</span> DGIdb',
            evidence_summary == "OpenTargets only" ~ 
              '<span style="color:#4caf50;font-weight:bold;">●</span> OpenTargets',
            TRUE ~ 
              sprintf('<span style="color:#95a5a6;">●</span> %s', evidence_summary)
          ),
          
          Phase = dplyr::case_when(
            max_clinical_phase >= 4 | is_approved == TRUE ~ '<span style="color:#27ae60;font-weight:bold;">Approved</span>',
            max_clinical_phase >= 3 ~ 'Phase III',
            max_clinical_phase >= 2 ~ 'Phase II',
            max_clinical_phase >= 1 ~ 'Phase I',
            TRUE ~ 'Preclinical'
          ),
          
          Mechanism = ifelse(
            !is.na(mechanisms) & mechanisms != "" & mechanisms != "—",
            ifelse(nchar(mechanisms) > 20, paste0(substr(mechanisms, 1, 17), "..."), mechanisms),
            "—"
          ),
          
          Links = sprintf(
            '<a href="https://www.dgidb.org/results?searchType=drug&searchTerms=%s" target="_blank" title="DGIdb" style="margin-right:5px;color:#2196f3;"><i class="fa fa-database"></i></a>
           <a href="https://pubmed.ncbi.nlm.nih.gov/?term=%s+drug" target="_blank" title="PubMed" style="margin-right:5px;color:#e91e63;"><i class="fa fa-book"></i></a>
           <a href="https://clinicaltrials.gov/search?term=%s" target="_blank" title="Clinical Trials" style="color:#4caf50;"><i class="fa fa-flask"></i></a>',
            URLencode(drug_name), URLencode(drug_name), URLencode(drug_name)
          )
        ) %>%
        dplyr::arrange(dplyr::desc(Score)) %>%
        dplyr::select(Drug, Priority, Score, Targets, `Target Genes`, Evidence, Phase, Mechanism, Links)
      
      DT::datatable(
        priority_display,
        escape = FALSE,
        rownames = FALSE,
        filter = 'top',
        options = list(
          pageLength = 15,
          scrollX = TRUE,
          order = list(list(2, 'desc')),
          columnDefs = list(
            list(className = 'dt-center', targets = c(1, 2, 3, 5, 6, 7, 8)),
            list(width = '150px', targets = 0),
            list(width = '80px', targets = 1),
            list(width = '80px', targets = 8)
          )
        )
      ) %>%
        DT::formatStyle(
          'Score',
          background = DT::styleColorBar(range(priority_display$Score, na.rm = TRUE), '#e1bee7'),
          backgroundSize = '95% 60%',
          backgroundRepeat = 'no-repeat',
          backgroundPosition = 'center'
        )
    } else {
      DT::datatable(
        data.frame(Message = "No prioritization data available. Run comprehensive analysis first."),
        options = list(dom = 't')
      )
    }
  })
  
