  create_comprehensive_cross_database_insights <- function(chembl_data, opentargets_data) {
    
    print("=== CREATING COMPREHENSIVE CROSS-DATABASE INSIGHTS ===")
    
    insights <- list()
    
    # Cross-database validation
    if (!is.null(chembl_data) && !is.null(opentargets_data) &&
        nrow(chembl_data) > 0 && nrow(opentargets_data) > 0) {
      
      # Gene-level validation
      chembl_genes <- unique(chembl_data$gene_name)
      ot_genes <- unique(opentargets_data$gene_name)
      
      validation_summary <- data.frame(
        gene_name = unique(c(chembl_genes, ot_genes)),
        stringsAsFactors = FALSE
      ) %>%
        dplyr::mutate(
          in_chembl = gene_name %in% chembl_genes,
          in_opentargets = gene_name %in% ot_genes,
          validation_status = dplyr::case_when(
            in_chembl & in_opentargets ~ "Cross-validated",
            in_chembl & !in_opentargets ~ "DGIdb Only",
            !in_chembl & in_opentargets ~ "OpenTargets only",
            TRUE ~ "No validation"
          )
        )
      
      insights$validation_summary <- validation_summary
      
      # Drug-level overlap analysis
      chembl_drugs <- unique(chembl_data$molecule_name[!is.na(chembl_data$molecule_name)])
      ot_drugs <- unique(opentargets_data$molecule_name[!is.na(opentargets_data$molecule_name)])
      
      drug_overlap <- length(intersect(chembl_drugs, ot_drugs))
      
      insights$drug_overlap <- list(
        chembl_unique = length(chembl_drugs),
        opentargets_unique = length(ot_drugs),
        overlapping = drug_overlap,
        overlap_percentage = if(length(chembl_drugs) > 0) round((drug_overlap / length(chembl_drugs)) * 100, 1) else 0
      )
      
      # Clinical phase concordance
      if ("clinical_phase" %in% colnames(chembl_data) && "clinical_phase" %in% colnames(opentargets_data)) {
        
        combined_clinical <- rbind(
          chembl_data %>% dplyr::select(gene_name, molecule_name, clinical_phase) %>% dplyr::mutate(source = "ChEMBL"),
          opentargets_data %>% dplyr::select(gene_name, molecule_name, clinical_phase) %>% dplyr::mutate(source = "OpenTargets")
        )
        
        clinical_concordance <- combined_clinical %>%
          dplyr::group_by(gene_name, molecule_name) %>%
          dplyr::summarise(
            n_sources = dplyr::n_distinct(source),
            clinical_phases = paste(unique(clinical_phase), collapse = ","),
            concordant = dplyr::n_distinct(clinical_phase) == 1,
            .groups = 'drop'
          ) %>%
          dplyr::filter(n_sources > 1)  # Only drugs found in both databases
        
        insights$clinical_concordance <- clinical_concordance
      }
      
    } else {
      # Single database insights
      insights$validation_summary <- data.frame(
        gene_name = character(0),
        validation_status = character(0)
      )
      
      insights$drug_overlap <- list(
        chembl_unique = if(!is.null(chembl_data)) length(unique(chembl_data$molecule_name)) else 0,
        opentargets_unique = if(!is.null(opentargets_data)) length(unique(opentargets_data$molecule_name)) else 0,
        overlapping = 0,
        overlap_percentage = 0
      )
    }
    
    print("Cross-database insights created")
    return(insights)
  }
  
  create_comprehensive_integrated_network <- function(chembl_data, opentargets_data, analysis_focus) {
    
    print("=== CREATING COMPREHENSIVE INTEGRATED NETWORK ===")
    
    all_nodes <- data.frame()
    all_edges <- data.frame()
    
    # Combine all unique genes
    all_genes <- character(0)
    if (!is.null(chembl_data) && nrow(chembl_data) > 0) {
      all_genes <- c(all_genes, chembl_data$gene_name)
    }
    if (!is.null(opentargets_data) && nrow(opentargets_data) > 0) {
      all_genes <- c(all_genes, opentargets_data$gene_name)
    }
    
    unique_genes <- unique(all_genes[!is.na(all_genes)])
    
    if (length(unique_genes) > 0) {
      # Create gene nodes
      gene_nodes <- data.frame(
        id = unique_genes,
        label = unique_genes,
        group = "gene",
        color = "#3498db",
        size = 15,
        title = paste("Gene:", unique_genes),
        stringsAsFactors = FALSE
      )
      all_nodes <- rbind(all_nodes, gene_nodes)
    }
    
    # Add ChEMBL drug nodes and edges
    if (!is.null(chembl_data) && nrow(chembl_data) > 0) {
      chembl_drugs <- chembl_data %>%
        dplyr::distinct(molecule_name, .keep_all = TRUE) %>%
        dplyr::mutate(
          id = paste0("CHEMBL_", molecule_name),
          label = molecule_name,
          group = "chembl_drug",
          color = "#e74c3c",
          size = 10,
          title = paste("ChEMBL Drug:", molecule_name, "<br>Clinical Phase:", clinical_phase)
        ) %>%
        dplyr::select(id, label, group, color, size, title)
      
      all_nodes <- rbind(all_nodes, chembl_drugs)
      
      # ChEMBL edges
      chembl_edges <- chembl_data %>%
        dplyr::mutate(
          from = paste0("CHEMBL_", molecule_name),
          to = gene_name,
          color = "#e74c3c",
          width = 2,
          title = paste("ChEMBL:", standard_type, "=", round(standard_value, 2)),
          database = "ChEMBL"
        ) %>%
        dplyr::select(from, to, color, width, title, database)
      
      all_edges <- rbind(all_edges, chembl_edges)
    }
    
    # Add OpenTargets drug nodes and edges
    if (!is.null(opentargets_data) && nrow(opentargets_data) > 0) {
      ot_drugs <- opentargets_data %>%
        dplyr::distinct(molecule_name, .keep_all = TRUE) %>%
        dplyr::mutate(
          id = paste0("OT_", molecule_name),
          label = molecule_name,
          group = "opentargets_drug",
          color = "#2ecc71",
          size = 10,
          title = paste("OpenTargets Drug:", molecule_name, "<br>Disease:", disease_area)
        ) %>%
        dplyr::select(id, label, group, color, size, title)
      
      all_nodes <- rbind(all_nodes, ot_drugs)
      
      # OpenTargets edges
      ot_edges <- opentargets_data %>%
        dplyr::mutate(
          from = paste0("OT_", molecule_name),
          to = gene_name,
          color = "#2ecc71",
          width = 2,
          title = paste("OpenTargets: Clinical Evidence =", round(clinical_evidence_score, 2)),
          database = "OpenTargets"
        ) %>%
        dplyr::select(from, to, color, width, title, database)
      
      all_edges <- rbind(all_edges, ot_edges)
    }
    
    print(paste("Created comprehensive network:", nrow(all_nodes), "nodes,", nrow(all_edges), "edges"))
    
    return(list(
      nodes = all_nodes,
      edges = all_edges
    ))
  }
  
  
