        total_targets = 0,
        integration_stats = list(
          total_unique_drugs = 0,
          total_unique_targets = 0,
          cross_validated_targets = 0
        ),
        chembl_stats = list(
          total_interactions = 0,
          unique_drugs = 0,
          unique_targets = 0
        ),
        opentargets_stats = list(
          total_associations = 0,
          unique_drugs = 0,
          unique_targets = 0
        )
      ),
      drug_prioritization = empty_prioritization,
      integrated_insights = list(
        validation_summary = data.frame(
          gene_name = character(0),
