  run_drug_discovery_dgidb_analysis <- function(symbols, max_drugs_per_gene, 
                                                min_confidence, activity_threshold = 50000) {
    
    print("═══════════════════════════════════════════════════════════════")
    print("    DRUG DISCOVERY MODE (DGIdb - Enhanced)")
    print("    Focus: Actionable drug-target relationships with evidence")
    print("═══════════════════════════════════════════════════════════════")
    
    if (length(symbols) == 0) {
      return(data.frame())
    }
    
    # Query DGIdb - focus on high-quality bioactivity sources
    bioactivity_sources <- c("ChEMBL", "GuideToPharmacology", "DrugBank", 
                             "BindingDB", "IUPHAR", "PharmGKB", "TTD")
    
    dgidb_results <- query_dgidb_enhanced(
      gene_symbols = symbols,
      max_drugs_per_gene = max_drugs_per_gene * 2,
      filter_sources = bioactivity_sources,
      approved_only = FALSE
    )
    
    if (is.null(dgidb_results) || nrow(dgidb_results) == 0) {
      print("⚠️ No DGIdb results found")
      return(data.frame())
    }
    
    print(paste("Raw DGIdb results:", nrow(dgidb_results), "interactions"))
    
    # Enhanced processing - KEEP ALL USEFUL COLUMNS
    drug_discovery_results <- dgidb_results %>%
      dplyr::filter(confidence_score >= min_confidence) %>%
      dplyr::mutate(
        # Ensure molecule_name exists
        molecule_name = drug_name,
        
        # Clean interaction type
        interaction_type = ifelse(is.na(interaction_type) | interaction_type == "", "Unknown", interaction_type),
        
        # Standard type for compatibility
        standard_type = interaction_type,
        
        # Actionability classification
        actionability = dplyr::case_when(
          is_approved & grepl("inhibitor|antagonist|blocker", interaction_type, ignore.case = TRUE) ~ 
            "Approved inhibitor - ready for repurposing",
          is_approved & grepl("agonist|activator", interaction_type, ignore.case = TRUE) ~ 
            "Approved activator - ready for repurposing",
          is_approved ~ "Approved drug available",
          clinical_phase >= 2 ~ "Clinical candidate available",
          n_sources >= 3 & n_publications >= 3 ~ "Well-validated compound",
          n_publications >= 5 ~ "Literature-validated",
          grepl("ChEMBL", sources) ~ "Bioactive compound available",
          TRUE ~ "Research stage"
        ),
        
        # Evidence level for display
        evidence_level = dplyr::case_when(
          is_approved & n_publications >= 5 ~ "Very High",
          is_approved ~ "High",
          n_sources >= 3 ~ "Moderate-High",
          n_sources >= 2 | n_publications >= 2 ~ "Moderate",
          TRUE ~ "Limited"
        ),
        
        # Priority score
        priority_score = dplyr::case_when(
          is_approved & grepl("inhibitor|antagonist|agonist", interaction_type, ignore.case = TRUE) ~ 100,
          is_approved ~ 90,
          clinical_phase >= 3 ~ 80,
          clinical_phase >= 1 ~ 70,
          n_sources >= 4 ~ 60,
          n_publications >= 5 ~ 50,
          n_sources >= 2 ~ 40,
          TRUE ~ 20
        ) + confidence_score * 10,
        
        # Links for UI
        pubmed_link = ifelse(
          !is.na(pmids) & pmids != "",
          paste0("https://pubmed.ncbi.nlm.nih.gov/?term=", gsub(",\\s*", "+OR+", pmids)),
          paste0("https://pubmed.ncbi.nlm.nih.gov/?term=", URLencode(paste(drug_name, gene_name, "drug")))
        ),
        
        dgidb_link = paste0("https://www.dgidb.org/results?searchType=drug&searchTerms=", URLencode(drug_name)),
        
        clinicaltrials_link = paste0("https://clinicaltrials.gov/search?term=", URLencode(drug_name)),
        
        # Database tracking
        database_source = "DGIdb",
        database = "DGIdb",
        analysis_context = "drug_discovery",
        
        # Compatibility fields
        standard_value = NA_real_,
        pchembl_value = NA_real_,
        disease_area = "Not specified",
        druggability_score = confidence_score,
        safety_score = ifelse(is_approved, 0.9, 0.6),
        clinical_evidence_score = confidence_score
      ) %>%
      # Rank by discovery priority
      dplyr::group_by(gene_name) %>%
      dplyr::arrange(dplyr::desc(priority_score)) %>%
      dplyr::slice_head(n = max_drugs_per_gene) %>%
      dplyr::ungroup()
    
    print(paste("✅ Drug Discovery results:", nrow(drug_discovery_results), "interactions"))
    print(paste("   • Approved drugs:", sum(drug_discovery_results$is_approved, na.rm = TRUE)))
    print(paste("   • With known mechanism:", sum(drug_discovery_results$interaction_type != "Unknown", na.rm = TRUE)))
    print(paste("   • Unique compounds:", length(unique(drug_discovery_results$drug_name))))
    
    return(drug_discovery_results)
  }
  
  
  
  # This function should replace your current drug-target analysis
  run_fixed_drug_target_analysis <- function(selected_genes, filters = list()) {
    
    
    print("Starting filtered drug-target analysis...")
    
    if (is.null(selected_genes) || length(selected_genes$all_genes) == 0) {
      stop("No genes provided for analysis")
    }
    
    print(paste("Analyzing", length(selected_genes$all_genes), "genes"))
    print(paste("Filter settings:"))
    print(paste("- Max drugs per gene:", filters$max_drugs_per_gene %||% "unlimited"))
    print(paste("- Confidence threshold:", filters$confidence_threshold %||% "none"))
    print(paste("- Experimental only:", filters$experimental_only %||% FALSE))
    
    # Step 1: Convert mixed gene IDs to standardized format
    conversion_result <- convert_mixed_gene_ids(selected_genes$all_genes, organism = "human")
    
    if (length(conversion_result$symbols) == 0) {
      stop("No valid gene symbols could be obtained from input genes")
    }
    
    print(paste("Conversion successful:", conversion_result$conversion_stats$successful_conversions,
                "out of", conversion_result$conversion_stats$total_input, "genes"))
    max_drugs_per_gene <- filters$max_drugs_per_gene %||% 1000
    confidence_threshold <- filters$confidence_threshold %||% 0
    experimental_only <- filters$experimental_only %||% FALSE
    
    print(paste("Filter settings:"))
    print(paste("- Max drugs per gene:", max_drugs_per_gene))
    print(paste("- Confidence threshold:", confidence_threshold))
    print(paste("- Experimental only:", experimental_only))
    
    # Step 2: Query ChEMBL for drug interactions WITH FILTERS
    chembl_results <- enhanced_chembl_query_with_filters(conversion_result$symbols)
    
    if (!is.null(chembl_results) && nrow(chembl_results) > 0) {
      print(paste("Before filtering:", nrow(chembl_results), "interactions"))
      
      # Filter by max drugs per gene
      chembl_results <- chembl_results %>%
        dplyr::group_by(gene_name) %>% # Explicit dplyr::group_by
        dplyr::arrange(standard_value) %>%  # Best activity first # Explicit dplyr::arrange
        dplyr::slice_head(n = max_drugs_per_gene) %>% # Explicit dplyr::slice_head
        dplyr::ungroup() # Explicit dplyr::ungroup
      
      print(paste("After max drugs filter:", nrow(chembl_results), "interactions"))
    }
    
    # Step 3: Create network visualization data
    network_data <- create_filtered_drug_target_network(chembl_results, selected_genes, filters)
    
    # Step 4: Create summary statistics
    summary_stats <- list(
      total_nodes = nrow(network_data$nodes),
      total_edges = nrow(network_data$edges),
      network_density = calculate_network_density(network_data$nodes, network_data$edges),
      total_drugs = length(unique(chembl_results$compound_chembl_id)),
      total_targets = length(unique(chembl_results$gene_name)),
      conversion_success_rate = round(conversion_result$conversion_stats$successful_conversions /
                                        conversion_result$conversion_stats$total_input * 100, 1),
      applied_filters = filters
    )
    
    print(paste("Final network:", summary_stats$total_drugs, "drugs,",
                summary_stats$total_targets, "targets"))
    
    return(list(
      network_data = network_data,
      summary = summary_stats,
      raw_data = chembl_results,
      conversion_stats = conversion_result$conversion_stats,
      analysis_type = "drug_target"
    ))
  }
  
  # Enhanced OpenTargets query function (your existing function) (keep as is, add explicit httr::, jsonlite::)
  enhanced_opentargets_druggability_query <- function(ensembl_id) {
    if (is.na(ensembl_id) || ensembl_id == "") {
      return(NULL)
    }
    
    print(paste("Querying OpenTargets druggability for:", ensembl_id))
    
    query_string <- sprintf('
  {
    target(ensemblId: "%s") {
      id
      approvedSymbol
      approvedName

      # Druggability assessment
      tractability {
        label
        modality
      }

      # Known drugs for this target
      knownDrugs {
        rows {
          drug {
            id
            name
            maximumClinicalTrialPhase
            drugType
          }
          approvedIndications {
            disease {
              name
            }
          }
          clinicalTrialPhase
          mechanismOfAction
        }
      }

      # Target safety profile
      safetyLiabilities {
        event
        description
        references {
          source
          id
        }
      }

      # Disease associations (existing)
      associatedDiseases {
        rows {
          disease {
            id
            name
            therapeuticAreas {
              name
            }
          }
          score
          datasourceScores {
            id
            score
          }
        }
      }

      # Baseline expression
      expressions {
        tissue {
          name
        }
        rna {
          value
          unit
        }
        protein {
          level
        }
      }
    }
  }', ensembl_id)
    
    tryCatch({
      response <- httr::POST( # Explicit httr::
        url = "https://api.platform.opentargets.org/api/v4/graphql",
        body = list(query = query_string),
        encode = "json",
        httr::add_headers( # Explicit httr::
          "Content-Type" = "application/json",
          "Accept" = "application/json"
        )
      )
      
      if (httr::http_error(response)) { # Explicit httr::
        print(paste("OpenTargets API error:", httr::http_status(response)$message)) # Explicit httr::
        return(NULL)
      }
      
      content <- httr::content(response, "text", encoding = "UTF-8") # Explicit httr::
      result <- jsonlite::fromJSON(content) # Explicit jsonlite::
      
      if (is.null(result$data$target)) {
        print(paste("No target found for ENSEMBL ID:", ensembl_id))
        return(NULL)
      }
      
      target_data <- result$data$target
      
      # Process and structure the comprehensive data
      processed_data <- list(
        gene_info = list(
          ensembl_id = target_data$id,
          symbol = target_data$approvedSymbol,
          name = target_data$approvedName
        ),
        
        # Druggability assessment
        tractability = if (!is.null(target_data$tractability)) {
          data.frame(
            modality = target_data$tractability$modality,
            assessment = target_data$tractability$label,
            stringsAsFactors = FALSE
          )
        } else { NULL },
        
        # Known drugs with clinical phases
        known_drugs = if (!is.null(target_data$knownDrugs$rows)) {
          drugs_data <- target_data$knownDrugs$rows
          data.frame(
            drug_id = drugs_data$drug$id,
            drug_name = drugs_data$drug$name,
            clinical_phase = drugs_data$drug$maximumClinicalTrialPhase,
            drug_type = drugs_data$drug$drugType,
            mechanism = drugs_data$mechanismOfAction,
            indications = sapply(drugs_data$approvedIndications, function(ind) {
              if (!is.null(ind) && length(ind) > 0) {
                paste(ind$disease$name, collapse = "; ")
              } else { "Unknown" }
            }),
            stringsAsFactors = FALSE
          )
        } else { NULL },
        
        # Safety liabilities
        safety_profile = if (!is.null(target_data$safetyLiabilities)) {
          data.frame(
            event = target_data$safetyLiabilities$event,
            description = target_data$safetyLiabilities$description,
            stringsAsFactors = FALSE
          )
        } else { NULL },
        
        # Disease associations (existing structure)
        disease_associations = if (!is.null(target_data$associatedDiseases$rows)) {
          diseases <- target_data$associatedDiseases$rows
          data.frame(
            disease_id = diseases$disease$id,
            disease_name = diseases$disease$name,
            therapeutic_areas = sapply(diseases$disease$therapeuticAreas,
                                       function(x) paste(x$name, collapse = "; ")),
            evidence_score = diseases$score,
            stringsAsFactors = FALSE
          )
        } else { NULL },
        
        # Expression data
        expression_profile = if (!is.null(target_data$expressions)) {
          data.frame(
            tissue = target_data$expressions$tissue$name,
            rna_expression = target_data$expressions$rna$value,
            protein_level = target_data$expressions$protein$level,
            stringsAsFactors = FALSE
          )
        } else { NULL }
      )
      
      print(paste("Successfully processed comprehensive data for:", target_data$approvedSymbol))
      return(processed_data)
      
    }, error = function(e) {
      print(paste("Error in OpenTargets druggability query:", e$message))
      return(NULL)
    })
  }
  
  # Enhanced drug-target analysis with three analysis modes (keep as is, add explicit dplyr::)
  run_enhanced_integrated_analysis <- function(selected_genes, analysis_mode = "comprehensive", organism = "human") {
    
    print(paste("Starting integrated analysis in mode:", analysis_mode))
    print(paste("Analyzing", length(selected_genes$all_genes), "genes"))
    
    # Step 1: Gene ID conversion
    conversion_result <- convert_mixed_gene_ids(selected_genes$all_genes, organism)
    
    if (length(conversion_result$symbols) == 0) {
      stop("No valid gene symbols could be obtained from input genes")
    }
    
    # Initialize results structure
    integrated_results <- list(
      analysis_mode = analysis_mode,
      gene_conversion = conversion_result,
      chembl_data = NULL,
      opentargets_data = NULL,
      integrated_insights = NULL,
      network_data = NULL,
      summary_stats = NULL
    )
    
    # Step 2: Query databases based on analysis mode
    if (analysis_mode %in% c("drug_discovery", "comprehensive")) {
      print("Querying ChEMBL for drug-target interactions...")
      # This will now include clinical_phase=0
      integrated_results$chembl_data <- enhanced_chembl_query_with_filters(conversion_result$symbols)
    }
    
    if (analysis_mode %in% c("disease_context", "comprehensive")) {
      print("Querying OpenTargets for comprehensive target assessment...")
      
      # Get ENSEMBL IDs for OpenTargets
      ensembl_ids <- conversion_result$ensembl_ids[!is.na(conversion_result$ensembl_ids)] # Corrected to use ensembl_ids
      # For comprehensive mode, use all converted symbols for mock OpenTargets data
      # The `enhanced_opentargets_druggability_query` is for real API calls and returns nested list.
      # The `create_mock_opentargets_data` returns a flat dataframe for consistency.
      integrated_results$opentargets_data <- create_mock_opentargets_data(conversion_result$symbols, analysis_mode)
      
    }
    
    # Step 3: Create integrated insights
    integrated_results$integrated_insights <- create_integrated_insights(
      integrated_results$chembl_data,
      integrated_results$opentargets_data, # This will be the flat dataframe
      selected_genes
    )
    
    # Step 4: Create enhanced network
    integrated_results$network_data <- create_enhanced_integrated_network(
      integrated_results$chembl_data,
      integrated_results$opentargets_data, # This will be the flat dataframe
      analysis_mode
    )
    
    # Step 5: Generate comprehensive summary
    integrated_results$summary_stats <- generate_integrated_summary(integrated_results)
    
    print("Integrated analysis complete!")
    return(integrated_results)
  }
  
  
