  # Create integrated insights combining both databases (keep as is, add explicit dplyr::)
  create_integrated_insights <- function(chembl_data, ot_data, selected_genes) {
    
    insights <- list()
    
    if (!is.null(chembl_data) && nrow(chembl_data) > 0) {
      # Drug discovery insights from ChEMBL
      insights$drug_targets <- chembl_data %>%
        dplyr::group_by(gene_name) %>% # Explicit dplyr::group_by
        dplyr::summarise( # Explicit dplyr::summarise
          drug_count = n_distinct(compound_chembl_id),
          best_activity = min(standard_value, na.rm = TRUE),
          activity_types = paste(unique(standard_type), collapse = ", "),
          druggability_score = dplyr::case_when( # Explicit dplyr::case_when
            drug_count >= 10 ~ "High",
            drug_count >= 5 ~ "Medium",
            drug_count >= 1 ~ "Low",
            TRUE ~ "None"
          ),
          .groups = 'drop'
        )
    }
    
    # `ot_data` here is the flat dataframe from `create_mock_opentargets_data`
    if (!is.null(ot_data) && nrow(ot_data) > 0) {
      
      # Druggability summary
      insights$druggability_assessment <- ot_data %>%
        dplyr::group_by(gene_name) %>%
        dplyr::summarise(
          modalities = paste(unique(c("Small molecule", "Antibody")), collapse = ", "), # Mocked
          assessment = dplyr::case_when( # Base on max clinical phase from mock data
            max(clinical_phase, na.rm = TRUE) >= 3 ~ "High",
            max(clinical_phase, na.rm = TRUE) >= 1 ~ "Medium",
            TRUE ~ "Low"
          ),
          .groups = 'drop'
        )
      
      # Clinical drugs (simplified for flat data)
      insights$clinical_validation <- ot_data %>%
        dplyr::group_by(gene_name, molecule_name, molecule_id) %>% # Group by drug for unique clinical info
        dplyr::summarise(
          clinical_phase = max(clinical_phase, na.rm = TRUE),
          drug_type = "Small molecule", # Mocked
          .groups = 'drop'
        ) %>%
        dplyr::mutate(
          clinical_status = dplyr::case_when( # Explicit dplyr::case_when
            clinical_phase == 4 ~ "Approved",
            clinical_phase == 3 ~ "Phase III",
            clinical_phase == 2 ~ "Phase II",
            clinical_phase == 1 ~ "Phase I",
            TRUE ~ "Preclinical"
          )
        )
      
      # Safety profile (simplified for flat data)
      insights$safety_profiles <- ot_data %>%
        dplyr::group_by(gene_name) %>%
        dplyr::summarise(
          safety_concerns = paste(unique(safety_concerns), collapse = ", "),
          .groups = 'drop'
        )
    }
    
    # Cross-database validation
    if (!is.null(insights$drug_targets) && !is.null(insights$clinical_validation)) {
      # This requires `clinical_validation` to be a list of dataframes per gene, but now it's a flat one.
      # Re-implement validate_cross_database_findings for flat data:
      insights$validation_summary <- ot_data %>%
        dplyr::select(gene_name, in_opentargets = TRUE) %>%
        dplyr::distinct() %>%
        dplyr::full_join(
          chembl_data %>%
            dplyr::select(gene_name, in_chembl = TRUE) %>%
            dplyr::distinct(),
          by = "gene_name"
        ) %>%
        dplyr::mutate(
          in_opentargets = ifelse(is.na(in_opentargets), FALSE, in_opentargets),
          in_chembl = ifelse(is.na(in_chembl), FALSE, in_chembl),
          validation_status = dplyr::case_when(
            in_chembl & in_opentargets ~ "Cross-validated",
            in_chembl & !in_opentargets ~ "DGIdb Only",
            !in_chembl & in_opentargets ~ "OpenTargets only",
            TRUE ~ "No validation"
          )
        ) %>%
        dplyr::select(gene_name, validation_status)
    }
    
    return(insights)
  }
  
  # Cross-database validation (REMOVED: Old implementation for nested data. Now handled directly in create_integrated_insights)
  # validate_cross_database_findings <- function(chembl_summary, ot_clinical) { ... }
  
  
  # Enhanced network creation with integrated data (keep as is, add explicit dplyr::)
  create_enhanced_integrated_network <- function(chembl_data, ot_data, analysis_mode) {
    
    nodes <- data.frame()
    edges <- data.frame()
    
    # Create gene nodes with enhanced information
    all_gene_names <- unique(c(chembl_data$gene_name, ot_data$gene_name))
    if (length(all_gene_names) > 0) {
      gene_nodes <- data.frame(
        id = all_gene_names,
        label = all_gene_names,
        type = "gene",
        group = "target",
        stringsAsFactors = FALSE
      )
      nodes <- rbind(nodes, gene_nodes)
    }
    
    # Add drug nodes from ChEMBL
    if (!is.null(chembl_data) && nrow(chembl_data) > 0 && analysis_mode %in% c("drug_discovery", "comprehensive")) {
      drug_nodes_chembl <- chembl_data %>%
        dplyr::distinct(molecule_id, .keep_all = TRUE) %>% # Changed to molecule_id for uniqueness
        dplyr::mutate(
          id = molecule_id,
          label = molecule_name, # Use molecule_name for label
          type = "drug",
          group = "compound",
          source_db = "ChEMBL"
        ) %>%
        dplyr::select(id, label, type, group, source_db)
      
      nodes <- rbind(nodes, drug_nodes_chembl)
      
      # Create drug-target edges from ChEMBL
      drug_edges_chembl <- chembl_data %>%
        dplyr::select(
          from = molecule_id,
          to = gene_name,
          weight = standard_value,
          type_rel = standard_type # Renamed to avoid clash with 'type' in network_data
        ) %>%
        dplyr::mutate(
          relationship = "targets",
          source = "ChEMBL",
          label = paste0(type_rel, ": ", round(weight,1)) # Add label for edge
        ) %>%
        dplyr::select(from, to, weight, relationship, source, label)
      
      edges <- rbind(edges, drug_edges_chembl)
    }
    
    # Add clinical validation information from OpenTargets
    if (!is.null(ot_data) && nrow(ot_data) > 0 && analysis_mode %in% c("disease_context", "comprehensive")) {
      
      clinical_drug_nodes_ot <- ot_data %>%
        dplyr::distinct(molecule_id, .keep_all = TRUE) %>% # Changed to molecule_id for uniqueness
        dplyr::mutate(
          id = molecule_id,
          label = molecule_name, # Use molecule_name for label
          type = "clinical_drug",
          group = "approved",
          clinical_phase = clinical_phase,
          source_db = "OpenTargets"
        ) %>%
        dplyr::select(id, label, type, group, clinical_phase, source_db)
      
      nodes <- rbind(nodes, clinical_drug_nodes_ot)
      
      # Create clinical drug-target edges from OpenTargets
      clinical_edges_ot <- ot_data %>%
        dplyr::select(
          from = molecule_id,
          to = gene_name,
          weight = clinical_phase,
          type_rel = standard_type # Re-using standard_type for consistency
        ) %>%
        dplyr::mutate(
          relationship = "clinical_target",
          source = "OpenTargets",
          label = paste0("Phase ", weight) # Label with clinical phase
        ) %>%
        dplyr::select(from, to, weight, relationship, source, label)
      
      edges <- rbind(edges, clinical_edges_ot)
    }
    
    # Ensure node IDs are unique after combining
    nodes <- nodes %>%
      dplyr::distinct(id, .keep_all = TRUE)
    
    return(list(nodes = nodes, edges = edges))
  }
  
  # Generate comprehensive summary statistics (keep as is, add explicit dplyr::)
  generate_integrated_summary <- function(results) {
    
    summary <- list(
      analysis_mode = results$analysis_mode,
      total_genes = length(results$gene_conversion$symbols),
      conversion_rate = round(
        results$gene_conversion$conversion_stats$successful_conversions /
          results$gene_conversion$conversion_stats$total_input * 100, 1
      )
    )
    
    # ChEMBL summary
    if (!is.null(results$chembl_data)) {
      summary$chembl <- list(
        total_interactions = nrow(results$chembl_data),
        unique_drugs = length(unique(results$chembl_data$molecule_id)), # Changed to molecule_id
        druggable_targets = length(unique(results$chembl_data$gene_name))
      )
    }
    
    # OpenTargets summary
    if (!is.null(results$opentargets_data)) {
      # Directly count from the flat dataframe
      clinical_drugs_count_ot <- length(unique(results$opentargets_data$molecule_id))
      
      summary$opentargets <- list(
        targets_with_data = length(unique(results$opentargets_data$gene_name)),
        total_clinical_drugs = clinical_drugs_count_ot,
        targets_with_safety_data = sum(results$opentargets_data$safety_concerns %in% c("Medium", "High")), # Using safety_concerns
        approved_drugs = sum(results$opentargets_data$clinical_phase == 4, na.rm = TRUE) # Count approved drugs
      )
    }
    
    # Network summary
    if (!is.null(results$network_data)) {
      summary$network <- list(
        total_nodes = nrow(results$network_data$nodes),
        total_edges = nrow(results$network_data$edges),
        node_types = table(results$network_data$nodes$type)
      )
    }
    
    return(summary)
  }
  
  
  
