        gradient = "linear-gradient(135deg, #4CAF50 0%, #8BC34A 100%)",
        badge = "DoRothEA • TFLink",
        available = current_organism %in% c("human", "mouse", "rat", "zebrafish", "fly", "celegans", "yeast")
      ),
      wgcna = list(
        id = "wgcna",
        title = "WGCNA",
        subtitle = "Modules",
        icon = "network-wired",
        base_color = "#00BCD4",
        light_bg = "#e0f7fa", # Light Cyan
        gradient = "linear-gradient(135deg, #00BCD4 0%, #03A9F4 100%)",
        badge = "Co-expression",
        available = TRUE
      )
    )
    
    available_cards <- Filter(function(x) x$available, cards)
    
    # Get current selection
    current_val <- isolate(input$network_analysis_type_systems)
    if (is.null(current_val) || !(current_val %in% names(available_cards))) {
      current_val <- names(available_cards)[1]
    }
    
    # Generate Card HTML
    card_divs <- lapply(available_cards, function(card) {
      is_active <- (card$id == current_val)
      
      # Logic: 
      # Active = Gradient BG, White Text
      # Inactive = Light Tint BG, Colored Text
      
      bg_style <- if(is_active) card$gradient else card$light_bg
      border_style <- if(is_active) "none" else paste0("1px solid ", card$base_color)
      text_color <- if(is_active) "#ffffff" else "#2c3e50"
      sub_color <- if(is_active) "rgba(255,255,255,0.9)" else "#666"
      icon_color <- if(is_active) "#ffffff" else card$base_color
      shadow <- if(is_active) paste0("0 8px 15px -3px ", card$base_color) else "none"
      transform <- if(is_active) "translateY(-3px)" else "translateY(0)"
      
      badge_bg <- if(is_active) "rgba(255,255,255,0.2)" else "#ffffff"
      badge_txt <- if(is_active) "#ffffff" else card$base_color
      badge_border <- if(is_active) "none" else paste0("1px solid ", card$base_color)
      
      div(
        id = paste0("card_", card$id),
        class = "analysis-card",
        `data-id` = card$id,
        `data-gradient` = card$gradient,
        `data-lightbg` = card$light_bg,
        `data-basecolor` = card$base_color,
        
        style = sprintf("
        flex: 1; min-width: 140px; 
        background: %s; 
        border: %s; 
        color: %s;
        border-radius: 10px; 
        padding: 15px 10px; 
        cursor: pointer; 
        transition: all 0.2s ease-in-out; 
        text-align: center;
        box-shadow: %s;
        transform: %s;
        position: relative;
        overflow: hidden;
      ", bg_style, border_style, text_color, shadow, transform),
        
        onclick = sprintf("selectAnalysisCard('%s', '%s')", card$id, paste(card$title, card$subtitle)),
        
        div(class = "card-icon", 
            style = sprintf("font-size: 30px; margin-bottom: 8px; color: %s; transition: color 0.2s;", icon_color),
            icon(card$icon)
        ),
        div(class = "card-title", 
            style = "font-weight: 700; font-size: 13px; margin-bottom: 2px;", 
            card$title),
        div(class = "card-subtitle", 
            style = sprintf("font-size: 11px; margin-bottom: 10px; color: %s;", sub_color), 
            card$subtitle),
        div(class = "card-badge",
            style = sprintf("font-size: 9px; background: %s; color: %s; border: %s; padding: 2px 8px; border-radius: 10px; display: inline-block; font-weight: 600;", 
                            badge_bg, badge_txt, badge_border),
            card$badge)
      )
    })
    
    tagList(
      div(style = "display: flex; gap: 12px; flex-wrap: wrap;", card_divs),
      
      # Instant Switching Script
      tags$script(HTML("
      function selectAnalysisCard(selectedId, displayText) {
        // Update Server Input
        Shiny.setInputValue('network_analysis_type_systems', selectedId, {priority: 'event'});
        
        // Update Display Text immediately
        $('#current_analysis_display').text(displayText);
        
        // Update Visuals immediately
        $('.analysis-card').each(function() {
          var el = $(this);
          var id = el.data('id');
          var baseColor = el.data('basecolor');
          var gradient = el.data('gradient');
          var lightBg = el.data('lightbg');
          
          if (id === selectedId) {
            // Active
            el.css({
              'background': gradient,
              'border': 'none',
              'color': '#ffffff',
              'transform': 'translateY(-3px)',
              'box-shadow': '0 8px 15px -3px ' + baseColor
            });
            el.find('.card-icon').css('color', '#ffffff');
            el.find('.card-subtitle').css('color', 'rgba(255,255,255,0.9)');
            el.find('.card-badge').css({'background': 'rgba(255,255,255,0.2)', 'color': '#ffffff', 'border': 'none'});
          } else {
            // Inactive
            el.css({
              'background': lightBg,
              'border': '1px solid ' + baseColor,
              'color': '#2c3e50',
              'transform': 'translateY(0)',
              'box-shadow': 'none'
            });
            el.find('.card-icon').css('color', baseColor);
            el.find('.card-subtitle').css('color', '#555');
            el.find('.card-badge').css({'background': '#ffffff', 'color': baseColor, 'border': '1px solid ' + baseColor});
          }
        });
      }
    "))
    )
  })
  
