  observeEvent(input$drug_analysis_focus, {
    req(input$drug_analysis_focus)
    
    new_focus <- input$drug_analysis_focus
    print(paste("🔄 Drug analysis focus changed to:", new_focus))
    
    # FIRST: Store current results before switching (if any exist and are drug-related)
    if (!is.null(network_rv$current_results) &&
        !is.null(network_rv$current_results$analysis_params) &&
        !is.null(network_rv$current_results$analysis_params$analysis_focus)) {
      
      old_focus <- network_rv$current_results$analysis_params$analysis_focus
      print(paste("📦 Storing previous results for focus:", old_focus))
      
      # Store the current results in the appropriate focus-specific storage
      if (old_focus == "disease_context") {
        network_rv$disease_context_results <- network_rv$current_results
        print("✅ Disease context results stored safely")
      } else if (old_focus == "drug_discovery") {
        network_rv$drug_discovery_results <- network_rv$current_results
        print("✅ Drug discovery results stored safely")
      } else if (old_focus == "comprehensive") {
        network_rv$comprehensive_results <- network_rv$current_results
        print("✅ Comprehensive results stored safely")
      }
    }
    
    # SECOND: Try to restore results for the new focus
    restored_results <- NULL
    
    if (new_focus == "disease_context" && !is.null(network_rv$disease_context_results)) {
      restored_results <- network_rv$disease_context_results
      print("🔄 Restored disease context results from storage")
    } else if (new_focus == "drug_discovery" && !is.null(network_rv$drug_discovery_results)) {
      restored_results <- network_rv$drug_discovery_results
      print("🔄 Restored drug discovery results from storage")
    } else if (new_focus == "comprehensive" && !is.null(network_rv$comprehensive_results)) {
      restored_results <- network_rv$comprehensive_results
      print("🔄 Restored comprehensive results from storage")
    }
    
    # THIRD: Set the current results and status
    if (!is.null(restored_results)) {
      network_rv$current_results <- restored_results
      network_rv$analysis_status <- "complete"
      print(paste("✅ Successfully restored", new_focus, "results"))
      
      showNotification(
        paste("📊 Restored previous", toupper(gsub("_", " ", new_focus)), "analysis results"),
        type = "message",
        duration = 3
      )
    } else {
      # No previous results for this focus
      network_rv$current_results <- NULL
      network_rv$analysis_status <- "ready"
      print(paste("🆕 No previous results for", new_focus, "- ready for new analysis"))
      
      showNotification(
        paste("🔄 Switched to", toupper(gsub("_", " ", new_focus)), "focus. Ready for analysis."),
        type = "message",
        duration = 3
      )
    }
    
  }, ignoreInit = TRUE, priority = 999)
  
