          !is.null(network_rv$current_results$analysis_params$analysis_focus)) {
        
        current_stored_focus <- network_rv$current_results$analysis_params$analysis_focus
        
        if (current_stored_focus != current_focus) {
          # We're switching focuses, store the current results
          if (current_stored_focus == "disease_context") {
            network_rv$disease_context_results <- network_rv$current_results
