          } else if (current_stored_focus == "comprehensive") {
            network_rv$comprehensive_results <- network_rv$current_results
            print("📦 Stored comprehensive results before running new analysis")
          }
        }
      }
      
      # Clear only the storage for the focus we're about to run
      if (current_focus == "disease_context") {
        network_rv$disease_context_results <- NULL
        print("🧹 Cleared disease context storage for new analysis")
      } else if (current_focus == "drug_discovery") {
        network_rv$drug_discovery_results <- NULL
        print("🧹 Cleared drug discovery storage for new analysis")
      } else if (current_focus == "comprehensive") {
        network_rv$comprehensive_results <- NULL
        print("🧹 Cleared comprehensive storage for new analysis")
      }
    }
    
    # IMPORTANT: Store current results before clearing (if switching analysis types)
    if (!is.null(network_rv$current_results)) {
      current_analysis_type <- network_rv$current_results$analysis_type %||% "unknown"
      
      if (current_analysis_type != current_type) {
        # We're switching analysis types, store the current results
        if (current_analysis_type == "wgcna") {
          network_rv$wgcna_results <- network_rv$current_results
          print("📦 Stored WGCNA results before running new analysis")
        } else if (current_analysis_type == "drug_target") {
          network_rv$drug_target_results <- network_rv$current_results
          print("📦 Stored drug-target results before running new analysis")
        } else if (current_analysis_type == "ppi") {
          network_rv$ppi_results <- network_rv$current_results
          print("📦 Stored PPI results before running new analysis")
        } else if (current_analysis_type == "grn") {
          network_rv$grn_results <- network_rv$current_results
          print("📦 Stored GRN results before running new analysis")
        }
      }
    }
    
    # Clear only the results for the current analysis type that we're about to run
    if (current_type == "wgcna") {
      network_rv$wgcna_results <- NULL
      print("🧹 Cleared WGCNA storage for new analysis")
    } else if (current_type == "drug_target") {
      network_rv$drug_target_results <- NULL
      print("🧹 Cleared drug-target storage for new analysis")
    } else if (current_type == "ppi") {
      network_rv$ppi_results <- NULL
      print("🧹 Cleared PPI storage for new analysis")
    } else if (current_type == "grn") {
      network_rv$grn_results <- NULL
