  # Add this observer to handle GRN analysis type selection
  observeEvent(input$network_analysis_type_systems, {
    req(input$network_analysis_type_systems)
    
    current_type <- input$network_analysis_type_systems
    old_type <- isolate(network_rv$analysis_type)
    
    print(paste("🔄 Analysis type changing from:", old_type, "to:", current_type))
    
    # ========================================================================
    # STEP 1: STORE current results before switching (if any exist)
    # ========================================================================
    
    if (!is.null(network_rv$current_results) && !is.null(old_type)) {
      
      print(paste("📦 Storing previous results for:", old_type))
      
      # Store based on the OLD type
      if (old_type == "wgcna") {
        network_rv$wgcna_results <- network_rv$current_results
        print("✅ WGCNA results stored safely")
        
      } else if (old_type == "drug_target") {
        network_rv$drug_target_results <- network_rv$current_results
        print("✅ Drug-target results stored safely")
        
      } else if (old_type == "ppi") {
        network_rv$ppi_results <- network_rv$current_results
        print("✅ PPI results stored safely")
        
      } else if (old_type == "grn") {
        network_rv$grn_results <- network_rv$current_results
        print("✅ GRN results stored safely")
        
      } else if (old_type == "deconv") {
        network_rv$deconv_results <- network_rv$current_results
        print("✅ Deconvolution results stored safely")
        print(paste("   - Cell types:", network_rv$current_results$summary_stats$deconv$total_cell_types))
        print(paste("   - Method:", network_rv$current_results$method))
      }
    }
    
    # ========================================================================
    # STEP 2: RESTORE results for the NEW analysis type (if available)
    # ========================================================================
    
    restored_results <- NULL
    
    if (current_type == "wgcna" && !is.null(network_rv$wgcna_results)) {
      restored_results <- network_rv$wgcna_results
      print("📄 Restored WGCNA results from storage")
      
    } else if (current_type == "drug_target" && !is.null(network_rv$drug_target_results)) {
      restored_results <- network_rv$drug_target_results
      print("📄 Restored drug-target results from storage")
      
    } else if (current_type == "ppi" && !is.null(network_rv$ppi_results)) {
      restored_results <- network_rv$ppi_results
      print("📄 Restored PPI results from storage")
      
    } else if (current_type == "grn" && !is.null(network_rv$grn_results)) {
      restored_results <- network_rv$grn_results
      print("📄 Restored GRN results from storage")
      
    } else if (current_type == "deconv" && !is.null(network_rv$deconv_results)) {
      restored_results <- network_rv$deconv_results
      print("📄 Restored Deconvolution results from storage")
      print(paste("   - Cell types:", restored_results$summary_stats$deconv$total_cell_types))
      print(paste("   - Method:", restored_results$method))
    }
    
    # ========================================================================
    # STEP 3: SET current results and update status
    # ========================================================================
    
    if (!is.null(restored_results)) {
      # We have previous results - restore them
      network_rv$current_results <- restored_results
      network_rv$analysis_status <- "complete"
      network_rv$analysis_type <- current_type
      
      print(paste("✅ Successfully restored", current_type, "results"))
      
      showNotification(
        paste("📊 Restored previous", toupper(current_type), "analysis results"),
        type = "message",
        duration = 3
      )
      
    } else {
      # No previous results for this analysis type - clear and prepare for new
      network_rv$current_results <- NULL
      network_rv$analysis_status <- "ready"
      network_rv$analysis_type <- current_type
      
      print(paste("🆕 No previous results for", current_type, "- ready for new analysis"))
    }
    
  }, ignoreInit = TRUE, priority = 999)
  
  observeEvent(network_rv$current_results, {
    
    # Only trigger if analysis is complete
    if (!is.null(network_rv$current_results) && 
        !is.null(network_rv$analysis_type) &&
        isTRUE(network_rv$analysis_status == "complete")) {
      
      analysis_type <- network_rv$analysis_type
      
      # Store in the appropriate cache immediately
      if (analysis_type == "deconv") {
        network_rv$deconv_results <- network_rv$current_results
        print("💾 Auto-saved deconvolution results to cache")
        
      } else if (analysis_type == "ppi") {
        network_rv$ppi_results <- network_rv$current_results
        print("💾 Auto-saved PPI results to cache")
        
      } else if (analysis_type == "grn") {
        network_rv$grn_results <- network_rv$current_results
        print("💾 Auto-saved GRN results to cache")
        
      } else if (analysis_type == "wgcna") {
        network_rv$wgcna_results <- network_rv$current_results
        print("💾 Auto-saved WGCNA results to cache")
        
      } else if (analysis_type == "drug_target") {
        network_rv$drug_target_results <- network_rv$current_results
        print("💾 Auto-saved Drug-target results to cache")
      }
    }
    
  }, ignoreNULL = TRUE, priority = 100)
  
  # Enhanced status display (keep as is)
  output$network_status_display <- renderUI({
    status <- network_rv$analysis_status %||% "ready"
    
    status_info <- switch(status,
                          "ready" = list(class = "status-ready", icon = "circle", text = "Ready"),
                          "running" = list(class = "status-running", icon = "spinner fa-spin", text = "Running"),
                          "complete" = list(class = "status-complete", icon = "check-circle", text = "Complete"),
                          "error" = list(class = "status-error", icon = "exclamation-triangle", text = "Error")
    )
    
    div(
      span(class = paste("status-badge", status_info$class),
           icon(status_info$icon), " ", status_info$text
      ),
      if (status == "running" && !is.null(network_rv$analysis_start_time)) {
        p(paste("Started:", format(network_rv$analysis_start_time, "%H:%M:%S")),
          style = "font-size: 12px; color: #6c757d; margin: 5px 0 0 0;")
      }
    )
  })
  
  # Results availability flag (keep as is)
  output$network_results_available <- reactive({
    !is.null(network_rv$current_results)
  })
  outputOptions(output, "network_results_available", suspendWhenHidden = FALSE)
  
  
  
  
