  output$drug_discovery_priorities_table <- DT::renderDataTable({
    req(network_rv$current_results) # Changed to network_rv
    req(network_rv$current_results$analysis_params$analysis_focus == "drug_discovery") # Changed to network_rv and analysis_params
    
    if (!is.null(network_rv$current_results$chembl_data)) { # Changed to network_rv
      # Create drug discovery focused priority table
      priority_data <- network_rv$current_results$chembl_data %>% # Changed to network_rv
        dplyr::group_by(gene_name) %>% # Explicit dplyr::group_by
        dplyr::summarise( # Explicit dplyr::summarise
          Drug_Count = n_distinct(compound_chembl_id),
          Best_Activity = min(standard_value, na.rm = TRUE),
          Activity_Types = paste(unique(standard_type), collapse = ", "),
          Druggability_Score = dplyr::case_when( # Explicit dplyr::case_when
            Drug_Count >= 8 ~ "High",
            Drug_Count >= 4 ~ "Medium",
            TRUE ~ "Low"
          ),
          .groups = 'drop'
        ) %>%
        dplyr::arrange(desc(Drug_Count)) %>% # Explicit dplyr::arrange
        dplyr::rename( # Explicit dplyr::rename
          Gene = gene_name,
          "Drug Count" = Drug_Count,
          "Best Activity (nM)" = Best_Activity,
          "Activity Types" = Activity_Types,
          "Druggability" = Druggability_Score
        )
      
      DT::datatable(
        priority_data,
        options = list(pageLength = 10, dom = 'frtip'),
        rownames = FALSE
      ) %>%
        DT::formatStyle(
          'Druggability',
          backgroundColor = DT::styleEqual(
            c("High", "Medium", "Low"),
            c('#d4edda', '#fff3cd', '#f8d7da')
          )
        ) %>%
        DT::formatRound(columns = c("Best Activity (nM)"), digits = 1)
    } else {
      DT::datatable(data.frame(Message = "No drug discovery data available"))
    }
  })
  
  
  
  
  output$disease_priorities_table <- DT::renderDataTable({
    req(network_rv$current_results)
    req(network_rv$current_results$analysis_params$analysis_focus == "disease_context")
    
    print("=== DISEASE PRIORITIES TABLE DEBUG ===")
    
    # Get data from available sources
    disease_data <- NULL
    
    if (!is.null(network_rv$current_results$opentargets_data) &&
        nrow(network_rv$current_results$opentargets_data) > 0) {
      disease_data <- network_rv$current_results$opentargets_data
    } else if (!is.null(network_rv$current_results$drug_targets) &&
               nrow(network_rv$current_results$drug_targets) > 0) {
      disease_data <- network_rv$current_results$drug_targets
    }
    
    if (is.null(disease_data) || nrow(disease_data) == 0) {
      return(DT::datatable(
        data.frame(Message = "No disease prioritization data available"),
        options = list(dom = 't'), rownames = FALSE
      ))
    }
    
    # Create drug-level prioritization for disease context
    priority_data <- disease_data %>%
      dplyr::group_by(molecule_name) %>%
      dplyr::summarise(
        Target_Count = dplyr::n_distinct(gene_name),
        Max_Clinical_Phase = max(clinical_phase, na.rm = TRUE),
        Disease_Areas = ifelse("disease_area" %in% colnames(disease_data),
                               paste(unique(disease_area[!is.na(disease_area)]), collapse = "; "),
                               "Multiple"),
        Avg_Safety_Score = ifelse("safety_score" %in% colnames(disease_data),
                                  round(mean(safety_score, na.rm = TRUE), 3),
                                  0.5),
        Avg_Clinical_Evidence = ifelse("clinical_evidence_score" %in% colnames(disease_data),
                                       round(mean(clinical_evidence_score, na.rm = TRUE), 3),
                                       0.5),
        Avg_Druggability = ifelse("druggability_score" %in% colnames(disease_data),
                                  round(mean(druggability_score, na.rm = TRUE), 3),
                                  0.5),
        .groups = 'drop'
      ) %>%
      dplyr::mutate(
        # Calculate disease-focused priority score
        Disease_Priority_Score = round(
          (Max_Clinical_Phase * 0.3) +          # 30% clinical phase
            (Avg_Clinical_Evidence * 0.3) +       # 30% clinical evidence
            (Avg_Safety_Score * 0.2) +            # 20% safety
            (Avg_Druggability * 0.2), 3),         # 20% druggability
        
        Clinical_Phase_Desc = dplyr::case_when(
          Max_Clinical_Phase == 4 ~ "Approved",
          Max_Clinical_Phase == 3 ~ "Phase III",
          Max_Clinical_Phase == 2 ~ "Phase II",
          Max_Clinical_Phase == 1 ~ "Phase I",
          Max_Clinical_Phase == 0 ~ "Preclinical",
          TRUE ~ "Unknown"
        ),
        
        Priority_Level = dplyr::case_when(
          Disease_Priority_Score >= quantile(Disease_Priority_Score, 0.75, na.rm = TRUE) ~ "High",
          Disease_Priority_Score >= quantile(Disease_Priority_Score, 0.25, na.rm = TRUE) ~ "Medium",
          TRUE ~ "Low"
        )
      ) %>%
      dplyr::arrange(desc(Disease_Priority_Score)) %>%
      dplyr::select(
        Drug = molecule_name,
        `Priority Level` = Priority_Level,
        `Priority Score` = Disease_Priority_Score,
        `Target Count` = Target_Count,
        `Clinical Phase` = Clinical_Phase_Desc,
        `Disease Areas` = Disease_Areas,
        `Safety Score` = Avg_Safety_Score,
        `Clinical Evidence` = Avg_Clinical_Evidence
      )
    
    print(paste("Disease priorities created:", nrow(priority_data), "drugs"))
    
    DT::datatable(
      priority_data,
      options = list(pageLength = 15, scrollX = TRUE),
      rownames = FALSE
    ) %>%
      DT::formatStyle(
        'Priority Level',
        backgroundColor = DT::styleEqual(
          c('High', 'Medium', 'Low'),
          c('#d4edda', '#fff3cd', '#f8d7da')
        )
      ) %>%
      DT::formatRound(c('Priority Score', 'Safety Score', 'Clinical Evidence'), 3) %>%
      DT::formatStyle(
        'Safety Score',
        color = DT::styleInterval(c(0.3, 0.7), c('#dc3545', '#fd7e14', '#28a745'))
      ) %>%
      DT::formatStyle(
        'Clinical Evidence',
        backgroundColor = DT::styleColorBar(c(0, 1), '#e3f2fd'),
        backgroundSize = '80% 80%',
        backgroundRepeat = 'no-repeat',
        backgroundPosition = 'center'
      )
  })
  
  output$disease_associations_table <- DT::renderDataTable({
    req(network_rv$current_results) # Changed to network_rv
    req(network_rv$current_results$analysis_params$analysis_focus == "disease_context") # Changed to network_rv and analysis_params
    
    if (!is.null(network_rv$current_results$opentargets_data)) { # Changed to network_rv
      # Create mock disease associations table (using existing opentargets_data structure)
      disease_data <- network_rv$current_results$opentargets_data %>% # Changed to network_rv
        dplyr::mutate( # Explicit dplyr::mutate
          Disease_Name = sample(c("Alzheimer's Disease", "Type 2 Diabetes", "Breast Cancer",
                                  "Cardiovascular Disease", "Depression", "Rheumatoid Arthritis"),
                                n(), replace = TRUE),
          Evidence_Score = stats::runif(n(), 0.3, 0.95), # Explicit stats::runif
          Therapeutic_Area = sample(c("Oncology", "Neurology", "Metabolic", "Immunology"),
                                    n(), replace = TRUE)
        ) %>%
        dplyr::select( # Explicit dplyr::select
          Gene = gene_name,
          Disease = Disease_Name,
          "Evidence Score" = Evidence_Score,
          "Therapeutic Area" = Therapeutic_Area,
          "Safety Level" = safety_concerns
        ) %>%
        dplyr::arrange(desc(`Evidence Score`)) # Explicit dplyr::arrange
      
      DT::datatable(
        disease_data,
        options = list(pageLength = 15, dom = 'frtip'),
        rownames = FALSE
      ) %>%
        DT::formatRound(columns = c("Evidence Score"), digits = 3) %>%
        DT::formatStyle(
          'Evidence Score',
          backgroundColor = DT::styleInterval(
            c(0.5, 0.7, 0.85),
            c('#ffffff', '#fff3cd', '#d4edda', '#28a745')
          )
        )
    } else {
      DT::datatable(data.frame(Message = "No disease association data available"))
    }
  })
  
  # ACTIVITY ANALYSIS OUTPUTS (Drug Discovery Mode)
  output$target_druggability_table <- DT::renderDataTable({
    req(network_rv$current_results) # Changed to network_rv
    req(network_rv$current_results$analysis_params$analysis_focus == "drug_discovery") # Changed to network_rv and analysis_params
    
    if (!is.null(network_rv$current_results$chembl_data)) { # Changed to network_rv
      druggability_data <- network_rv$current_results$chembl_data %>% # Changed to network_rv
        dplyr::group_by(gene_name) %>% # Explicit dplyr::group_by
        dplyr::summarise( # Explicit dplyr::summarise
          Total_Compounds = n_distinct(compound_chembl_id),
          Active_Compounds = sum(standard_value <= 1000, na.rm = TRUE),
          Druggability_Score = Active_Compounds / Total_Compounds,
          Target_Class = sample(c("Enzyme", "GPCR", "Ion Channel", "Transporter"), 1), # Mocked once per gene
          .groups = 'drop'
        ) %>%
        dplyr::mutate( # Explicit dplyr::mutate
          Druggability_Level = dplyr::case_when( # Explicit dplyr::case_when
            Druggability_Score >= 0.6 ~ "High",
            Druggability_Score >= 0.3 ~ "Medium",
            TRUE ~ "Low"
          )
        ) %>%
        dplyr::arrange(desc(Druggability_Score)) %>% # Explicit dplyr::arrange
        dplyr::select( # Explicit dplyr::select
          Gene = gene_name,
          "Target Class" = Target_Class,
          "Total Compounds" = Total_Compounds,
          "Active Compounds" = Active_Compounds,
          "Druggability Score" = Druggability_Score,
          "Level" = Druggability_Level
        )
      
      DT::datatable(
        druggability_data,
        options = list(pageLength = 8, dom = 't'),
        rownames = FALSE
      ) %>%
        DT::formatRound(columns = c("Druggability Score"), digits = 3) %>%
        DT::formatStyle(
          'Level',
          backgroundColor = DT::styleEqual(
            c("High", "Medium", "Low"),
            c('#d4edda', '#fff3cd', '#f8d7da')
          )
        )
    } else {
      DT::datatable(data.frame(Message = "No druggability data available"))
    }
  })
  
  
  # CROSS-DATABASE VALIDATION OUTPUTS (Comprehensive Mode)
  output$validation_status_plot <- renderPlotly({
    req(network_rv$current_results) # Changed to network_rv
    req(network_rv$current_results$analysis_params$analysis_focus == "comprehensive") # Changed to network_rv and analysis_params
    
    # Re-calculate validation data based on current filtered combined data
    chembl_genes <- unique(network_rv$current_results$chembl_data$gene_name) # Changed to network_rv
    opentargets_genes <- unique(network_rv$current_results$opentargets_data$gene_name) # Changed to network_rv
    all_genes_with_data <- unique(c(chembl_genes, opentargets_genes))
    
    if (length(all_genes_with_data) == 0) {
      p <- ggplot() +
        annotate("text", x = 0.5, y = 0.5,
                 label = "No validation data available for comprehensive analysis",
                 size = 4, hjust = 0.5, vjust = 0.5) +
        theme_void() +
        labs(title = "Cross-Database Validation Status")
      return(ggplotly(p, height = 350))
    }
    
    validation_summary_list <- lapply(all_genes_with_data, function(gene) {
      in_chembl <- gene %in% chembl_genes
      in_opentargets <- gene %in% opentargets_genes
      
      status <- if (in_chembl && in_opentargets) {
        "Both Databases"
      } else if (in_chembl) {
        "DGIdb Only"
      } else if (in_opentargets) {
        "OpenTargets Only"
      } else {
        "No Data" # Should ideally not happen if all_genes_with_data is correct
      }
      return(status)
    })
    
    validation_data <- data.frame(Status = unlist(validation_summary_list), stringsAsFactors = FALSE) %>%
      dplyr::count(Status, .drop = FALSE) # Explicit dplyr::count
    
    # Ensure all statuses are present for consistent plotting even if count is 0
    all_possible_statuses <- c("Both Databases", "DGIdb Only", "OpenTargets Only", "No Data")
    validation_data <- validation_data %>%
      dplyr::right_join(data.frame(Status = all_possible_statuses), by = "Status") %>% # Explicit dplyr::right_join
      dplyr::mutate(n = ifelse(is.na(n), 0, n)) # Explicit dplyr::mutate
    
    p <- ggplot(validation_data, aes(x = Status, y = n, fill = Status)) +
      geom_bar(stat = "identity") +
      scale_fill_manual(values = c(
        "Both Databases" = "#28a745",
        "DGIdb Only" = "#17a2b8",
        "OpenTargets Only" = "#ffc107",
        "No Data" = "#dc3545"
      )) +
      labs(
        title = "Cross-Database Validation Status",
        x = "Validation Status",
        y = "Number of Targets"
      ) +
      theme_minimal() +
      theme(
        legend.position = "none",
        axis.text.x = element_text(angle = 45, hjust = 1)
      )
    
    ggplotly(p, height = 350)
  })
  
  output$validation_agreement_table <- DT::renderDataTable({
    req(network_rv$current_results) # Changed to network_rv
    req(network_rv$current_results$analysis_params$analysis_focus == "comprehensive") # Changed to network_rv and analysis_params
    
    chembl_genes <- unique(network_rv$current_results$chembl_data$gene_name) # Changed to network_rv
    opentargets_genes <- unique(network_rv$current_results$opentargets_data$gene_name) # Changed to network_rv
    all_genes_with_data <- unique(c(chembl_genes, opentargets_genes))
    
    if (length(all_genes_with_data) == 0) {
      return(DT::datatable(data.frame(Message = "No validation data available for comprehensive analysis")))
    }
    
    validation_data <- data.frame(
      Gene = all_genes_with_data,
      ChEMBL = ifelse(all_genes_with_data %in% chembl_genes, "✓", "[FAIL]"),
      OpenTargets = ifelse(all_genes_with_data %in% opentargets_genes, "✓", "[FAIL]"),
      stringsAsFactors = FALSE
    ) %>%
      dplyr::mutate( # Explicit dplyr::mutate
        Status = dplyr::case_when( # Explicit dplyr::case_when
          ChEMBL == "✓" & OpenTargets == "✓" ~ "Cross-validated",
          ChEMBL == "✓" & OpenTargets == "[FAIL]" ~ "DGIdb Only",
          ChEMBL == "[FAIL]" & OpenTargets == "✓" ~ "OpenTargets only",
          TRUE ~ "No data"
        ),
        Confidence = round(stats::runif(n(), 0.4, 0.95), 2) # Mock confidence
      ) %>%
      dplyr::arrange(Gene) # Explicit dplyr::arrange
    
    DT::datatable(
      validation_data,
      options = list(
        pageLength = 6,
        dom = 't',
        scrollX = TRUE,
        columnDefs = list(
          list(width = '80px', targets = 1:2),  # Narrow ChEMBL/OpenTargets columns
          list(width = '120px', targets = 3),   # Status column
          list(width = '80px', targets = 4)     # Confidence column
        )
      ),
      rownames = FALSE
    ) %>%
      DT::formatStyle(
        'Status',
        backgroundColor = DT::styleEqual(
          c("Cross-validated", "DGIdb Only", "OpenTargets only", "No data"),
          c('#d4edda', '#cce5ff', '#fff3cd', '#f8d7da')
        )
      ) %>%
      DT::formatStyle(
        'ChEMBL',
        color = DT::styleEqual(c("✓", "[FAIL]"), c('#28a745', '#dc3545'))
      ) %>%
      DT::formatStyle(
        'OpenTargets',
        color = DT::styleEqual(c("✓", "[FAIL]"), c('#28a745', '#dc3545'))
      )
  })
  
