  # Activity Distribution Plot (keep as is, add explicit dplyr::)
  output$activity_distribution_plot <- renderPlotly({
    req(network_rv$current_results) # Changed to network_rv
    
    if (!is.null(network_rv$current_results$chembl_data) &&
        nrow(network_rv$current_results$chembl_data) > 0) { # Changed to network_rv
      
      chembl_data <- network_rv$current_results$chembl_data %>% # Changed to network_rv
        dplyr::mutate( # Explicit dplyr::mutate
          Activity_Range = dplyr::case_when( # Explicit dplyr::case_when
            standard_value <= 10 ~ "Very High (≤10 nM)",
            standard_value <= 100 ~ "High (10-100 nM)",
            standard_value <= 1000 ~ "Moderate (100-1000 nM)",
            standard_value <= 10000 ~ "Low (1-10 μM)",
            TRUE ~ "Very Low (>10 μM)"
          ),
          Activity_Range = factor(Activity_Range, levels = c(
            "Very High (≤10 nM)", "High (10-100 nM)", "Moderate (100-1000 nM)",
            "Low (1-10 μM)", "Very Low (>10 μM)"
          ))
        )
      
      # Create activity distribution plot
      activity_summary <- chembl_data %>%
        dplyr::count(Activity_Range, .drop = FALSE) %>% # Explicit dplyr::count
        dplyr::mutate( # Explicit dplyr::mutate
          Percentage = round(n / sum(n) * 100, 1)
        )
      
      p <- ggplot(activity_summary, aes(x = Activity_Range, y = n, fill = Activity_Range)) +
        geom_bar(stat = "identity") +
        geom_text(aes(label = paste0(n, " (", Percentage, "%)")),
                  vjust = -0.3, size = 3) +
        scale_fill_manual(values = c(
          "Very High (<=10 nM)" = "#d4edda",
          "High (10-100 nM)" = "#b8dab8",
          "Moderate (100-1000 nM)" = "#fff3cd",
          "Low (1-10 uM)" = "#f8d7da",
          "Very Low (>10 uM)" = "#e6cccc"
        )) +
        labs(
          title = "Drug Activity Distribution",
          subtitle = "Distribution of compound activities against selected targets",
          x = "Activity Range",
          y = "Number of Compounds"
        ) +
        theme_minimal() +
        theme(
          legend.position = "none",
          axis.text.x = element_text(angle = 45, hjust = 1),
          plot.title = element_text(hjust = 0.5),
          plot.subtitle = element_text(hjust = 0.5, size = 10)
        )
      
      ggplotly(p, height = 400)
    } else {
      # Empty plot with message
      p <- ggplot() +
        annotate("text", x = 0.5, y = 0.5,
                 label = "No activity data available\nfor this analysis mode",
                 size = 6, hjust = 0.5, vjust = 0.5) +
        theme_void() +
        labs(title = "Activity Distribution")
      
      ggplotly(p, height = 400)
    }
  })
  
  
  output$clinical_pipeline_plot <- renderPlotly({
    req(network_rv$current_results) # Changed to network_rv
    
    # Create clinical pipeline data based on analysis mode
    if (network_rv$current_results$analysis_params$analysis_focus == "disease_context" || # Changed to network_rv and analysis_params
        network_rv$current_results$analysis_params$analysis_focus == "comprehensive") { # Changed to network_rv and analysis_params
      
      if (!is.null(network_rv$current_results$opentargets_data) &&
          nrow(network_rv$current_results$opentargets_data) > 0) { # Changed to network_rv
        clinical_data <- network_rv$current_results$opentargets_data # Changed to network_rv
        
        # Use actual clinical_phase column from the combined data
        phase_counts <- clinical_data %>%
          dplyr::count(clinical_phase, .drop = FALSE) %>% # Explicit dplyr::count
          dplyr::mutate( # Explicit dplyr::mutate
            Phase = factor(clinical_phase,
                           levels = c(0, 1, 2, 3, 4),
                           labels = c("Preclinical", "Phase I", "Phase II", "Phase III", "Approved"))
          )
        
        # Ensure all phases are represented, even if count is 0
        full_phases <- data.frame(
          Phase = factor(c("Preclinical", "Phase I", "Phase II", "Phase III", "Approved"),
                         levels = c("Preclinical", "Phase I", "Phase II", "Phase III", "Approved"))
        )
        phase_data <- full_phases %>%
          dplyr::left_join(phase_counts, by = "Phase") %>% # Explicit dplyr::left_join
          dplyr::mutate(n = ifelse(is.na(n), 0, n)) %>% # Explicit dplyr::mutate
          dplyr::rename(Count = n) # Explicit dplyr::rename
        
      } else {
        # Fallback data if no OpenTargets data available for these modes
        phase_data <- data.frame(
          Phase = factor(c("Preclinical", "Phase I", "Phase II", "Phase III", "Approved"),
                         levels = c("Preclinical", "Phase I", "Phase II", "Phase III", "Approved")),
          Count = c(2, 4, 3, 1, 2)
        )
      }
    } else {
      # Default fallback for other modes (e.g., drug_discovery where clinical_phase might be mostly 0)
      # This might need to be adjusted if drug_discovery mode specifically uses clinical_phase
      # For now, if only ChEMBL data with default 0 is available, this might show just Preclinical.
      if (!is.null(network_rv$current_results$chembl_data) &&
          nrow(network_rv$current_results$chembl_data) > 0) { # Changed to network_rv
        
        clinical_data <- network_rv$current_results$chembl_data # Changed to network_rv
        
        phase_counts <- clinical_data %>%
          dplyr::count(clinical_phase, .drop = FALSE) %>% # Explicit dplyr::count
          dplyr::mutate( # Explicit dplyr::mutate
            Phase = factor(clinical_phase,
                           levels = c(0, 1, 2, 3, 4),
                           labels = c("Preclinical", "Phase I", "Phase II", "Phase III", "Approved"))
          )
        
        full_phases <- data.frame(
          Phase = factor(c("Preclinical", "Phase I", "Phase II", "Phase III", "Approved"),
                         levels = c("Preclinical", "Phase I", "Phase II", "Phase III", "Approved"))
        )
        phase_data <- full_phases %>%
          dplyr::left_join(phase_counts, by = "Phase") %>% # Explicit dplyr::left_join
          dplyr::mutate(n = ifelse(is.na(n), 0, n)) %>% # Explicit dplyr::mutate
          dplyr::rename(Count = n) # Explicit dplyr::rename
        
      } else {
        phase_data <- data.frame(
          Phase = factor(c("Preclinical", "Phase I", "Phase II", "Phase III", "Approved"),
                         levels = c("Preclinical", "Phase I", "Phase II", "Phase III", "Approved")),
          Count = c(1, 3, 4, 2, 1)
        )
      }
    }
    
    # Create the plot
    p <- ggplot(phase_data, aes(x = Phase, y = Count, fill = Phase)) +
      geom_bar(stat = "identity") +
      labs(
        title = "Clinical Development Pipeline",
        x = "Development Phase",
        y = "Number of Drugs"
      ) +
      theme_minimal() +
      theme(
        legend.position = "none",
        axis.text.x = element_text(angle = 45, hjust = 1),
        plot.title = element_text(hjust = 0.5)
      ) +
      scale_fill_manual(values = c( # Consistent colors
        "Preclinical" = "#ffc107",
        "Phase I" = "#17a2b8",
        "Phase II" = "#007bff",
        "Phase III" = "#6f42c1",
        "Approved" = "#28a745"
      ))
    
    ggplotly(p, height = 400)
  })
  
  
  # Druggability Table
  output$druggability_table <- DT::renderDataTable({
    req(network_rv$current_results) # Changed to network_rv
    
    # Create meaningful druggability data based on analysis mode
    if (network_rv$current_results$analysis_params$analysis_focus %in% c("disease_context", "comprehensive")) { # Changed to network_rv and analysis_params
      
      if (!is.null(network_rv$current_results$opentargets_data) &&
          nrow(network_rv$current_results$opentargets_data) > 0) { # Changed to network_rv
        
        druggability_data <- network_rv$current_results$opentargets_data %>% # Changed to network_rv
          dplyr::group_by(gene_name) %>% # Group by gene to summarise across its drugs
          dplyr::summarise( # Explicit dplyr::summarise
            # Use first for properties that should be consistent per gene, max for numerical
            Max_Clinical_Phase = max(clinical_phase, na.rm = TRUE),
            Avg_Confidence_Score = mean(confidence_score, na.rm = TRUE),
            Safety_Concerns_Level = dplyr::case_when( # Derive a single safety level if multiple
              any(safety_concerns == "High") ~ "High",
              any(safety_concerns == "Medium") ~ "Medium",
              TRUE ~ "Low"
            ),
            Modality = paste(unique(c("Small molecule", "Antibody")), collapse = ", "), # Mock modalities
            .groups = 'drop'
          ) %>%
          dplyr::mutate( # Explicit dplyr::mutate
            Assessment = dplyr::case_when( # Explicit dplyr::case_when
              Max_Clinical_Phase >= 3 & Avg_Confidence_Score >= 0.7 ~ "High",
              Max_Clinical_Phase >= 1 & Avg_Confidence_Score >= 0.5 ~ "Medium",
              TRUE ~ "Low"
            ),
            Druggability_Score = (Max_Clinical_Phase / 4 + Avg_Confidence_Score) / 2 # A simple score
          ) %>%
          dplyr::select( # Explicit dplyr::select
            Gene = gene_name,
            Modality,
            Assessment,
            "Druggability Score" = Druggability_Score,
            "Max Clinical Phase" = Max_Clinical_Phase,
            "Safety Concerns" = Safety_Concerns_Level
          ) %>%
          dplyr::arrange(desc(`Druggability Score`)) # Explicit dplyr::arrange
        
      } else {
        return(DT::datatable(data.frame(Message = "No OpenTargets-derived druggability data available")))
      }
    } else if (network_rv$current_results$analysis_params$analysis_focus == "drug_discovery") { # Changed to network_rv and analysis_params
      # Drug Discovery mode: Based on ChEMBL data (already handled by target_druggability_table)
      # This `druggability_table` is specifically intended for OpenTargets data in UI.
      return(DT::datatable(data.frame(Message = "Druggability table for Drug Discovery focus is in 'Activity Analysis' tab.")))
    } else {
      # Fallback for other modes
      selected_genes_sample <- head(network_rv$selected_genes$all_genes, 5)
      druggability_data <- data.frame(
        Gene = selected_genes_sample,
        Modality = sample(c("Small molecule", "Antibody", "Other"), length(selected_genes_sample), replace = TRUE),
        Assessment = sample(c("High", "Medium", "Low"), length(selected_genes_sample), replace = TRUE),
        "Druggability Score" = stats::runif(length(selected_genes_sample), 0.3, 0.9), # Explicit stats::runif
        stringsAsFactors = FALSE
      )
    }
    
    if (nrow(druggability_data) == 0) {
      return(DT::datatable(data.frame(Message = "No druggability data available")))
    }
    
    DT::datatable(
      druggability_data,
      options = list(
        pageLength = 10,
        dom = 'frtip',
        scrollY = "300px"
      ),
      rownames = FALSE
    ) %>%
      DT::formatStyle(
        'Assessment',
        backgroundColor = DT::styleEqual(
          c("High", "Medium", "Low"),
          c('#d4edda', '#fff3cd', '#f8d7da')
        )
      ) %>%
      DT::formatRound(columns = c("Druggability Score"), digits = 3)
  })
  
  output$safety_profile_table <- DT::renderDataTable({
    req(network_rv$current_results) # Changed to network_rv
    
    if (network_rv$current_results$analysis_params$analysis_focus %in% c("disease_context", "comprehensive")) { # Changed to network_rv and analysis_params
      
      # Directly use the opentargets_data and derive safety info
      if (!is.null(network_rv$current_results$opentargets_data) &&
          nrow(network_rv$current_results$opentargets_data) > 0) { # Changed to network_rv
        
        safety_data <- network_rv$current_results$opentargets_data %>% # Changed to network_rv
          dplyr::select(
            Gene = gene_name,
            # Use the mock safety_concerns from opentargets_data
            Risk_Level = safety_concerns
          ) %>%
          dplyr::mutate(
            Event = sample(c("Hepatotoxicity", "Cardiotoxicity", "CNS effects", "Immunogenicity"), n(), replace = TRUE),
            Description = "Generic safety concern (mocked)",
            Evidence_Source = sample(c("Clinical trials", "Preclinical", "Literature"), n(), replace = TRUE)
          ) %>%
          dplyr::distinct(Gene, Event, .keep_all = TRUE) %>% # Avoid duplicate events per gene
          dplyr::arrange(Gene, desc(Risk_Level)) # Arrange for better view
        
      } else {
        return(DT::datatable(data.frame(Message = "No OpenTargets-derived safety data available")))
      }
    } else {
      # Fallback for other modes
      safety_genes <- head(network_rv$selected_genes$all_genes, 4)
      # Changed to network_rv
      safety_data <- data.frame(
