  # Validation Status Plot (keep as is, ensure data extraction works)
  output$validation_status_plot <- renderPlotly({
    req(network_rv$current_results) # Changed to network_rv
    req(network_rv$current_results$analysis_params$analysis_focus == "comprehensive") # Changed to network_rv and analysis_params
    
    # The `extract_validation_summary` was trying to use `integrated_insights` which is not structured as expected in the latest `run_enhanced_drug_target_analysis`.
    # Re-calculate directly from `chembl_data` and `opentargets_data`
    chembl_genes <- unique(network_rv$current_results$chembl_data$gene_name) # Changed to network_rv
    opentargets_genes <- unique(network_rv$current_results$opentargets_data$gene_name) # Changed to network_rv
    all_genes_with_data <- unique(c(chembl_genes, opentargets_genes))
    
    if (length(all_genes_with_data) == 0) {
      p <- ggplot() +
        annotate("text", x = 0.5, y = 0.5, label = "No validation data available", size = 6) +
        theme_void()
      return(ggplotly(p))
    }
    
    validation_summary_list <- lapply(all_genes_with_data, function(gene) {
      in_chembl <- gene %in% chembl_genes
      in_opentargets <- gene %in% opentargets_genes
      
      status <- if (in_chembl && in_opentargets) {
        "Cross-validated"
      } else if (in_chembl) {
        "DGIdb Only"
      } else if (in_opentargets) {
        "OpenTargets only"
      } else {
        "No validation" # Should ideally not happen if all_genes_with_data is correctly derived
      }
      return(status)
    })
    
    validation_data <- data.frame(validation_status = unlist(validation_summary_list), stringsAsFactors = FALSE) %>%
      dplyr::count(validation_status, .drop = FALSE) # Count occurrences, keep all levels
    
    # Ensure all statuses are present for consistent plotting
    all_possible_statuses <- c("Cross-validated", "DGIdb Only", "OpenTargets only", "No validation")
    validation_data <- validation_data %>%
      dplyr::right_join(data.frame(validation_status = all_possible_statuses), by = "validation_status") %>%
      dplyr::mutate(n = ifelse(is.na(n), 0, n))
    
    p <- validation_data %>%
      ggplot(aes(x = validation_status, y = n, fill = validation_status)) +
      geom_bar(stat = "identity") +
      labs(
        title = "Cross-Database Validation Status",
        x = "Validation Status",
        y = "Number of Targets"
      ) +
      scale_fill_manual(values = c(
        "Cross-validated" = "#28a745",
        "DGIdb Only" = "#17a2b8",
        "OpenTargets only" = "#ffc107",
        "No validation" = "#dc3545"
      )) +
      theme_minimal() +
      theme(
        legend.position = "none",
        axis.text.x = element_text(angle = 45, hjust = 1)
      )
    
    ggplotly(p, height = 350)
  })
  
  # Enhanced Network Visualization (keep as is, add explicit dplyr::)
  output$enhanced_network_plot <- renderVisNetwork({
    req(network_rv$current_results) # Changed to network_rv
    req(network_rv$current_results$network_data) # Changed to network_rv
    
    network_data <- network_rv$current_results$network_data # Changed to network_rv
    
    if (is.null(network_data) || nrow(network_data$nodes) == 0) {
      return(NULL)
    }
    
    # Filter nodes based on selection
    show_types <- input$show_node_types %||% c("gene", "drug", "clinical_drug") # Ensure this input exists or default
    filtered_nodes <- network_data$nodes[network_data$nodes$type %in% show_types, ]
    filtered_edges <- network_data$edges[
      network_data$edges$from %in% filtered_nodes$id &
        network_data$edges$to %in% filtered_nodes$id,
    ]
    
    # Enhanced node styling
    filtered_nodes <- filtered_nodes %>%
      dplyr::mutate( # Explicit dplyr::mutate
        color = dplyr::case_when( # Explicit dplyr::case_when
          type == "gene" ~ "#3498db",
          type == "drug" ~ "#e74c3c",
          type == "clinical_drug" ~ "#2ecc71",
          TRUE ~ "#95a5a6"
        ),
        size = dplyr::case_when( # Explicit dplyr::case_when
          type == "gene" ~ 25 * (input$node_size_factor %||% 1), # Use %||% for default
          type == "drug" ~ 20 * (input$node_size_factor %||% 1),
          type == "clinical_drug" ~ 30 * (input$node_size_factor %||% 1),
          TRUE ~ 15 * (input$node_size_factor %||% 1)
        ),
        shape = dplyr::case_when( # Explicit dplyr::case_when
          type == "gene" ~ "circle",
          type == "drug" ~ "square",
          type == "clinical_drug" ~ "diamond",
          TRUE ~ "circle"
        )
      )
    
    visNetwork(filtered_nodes, filtered_edges) %>%
      visOptions(
        highlightNearest = TRUE,
        selectedBy = "group"
      ) %>%
      visLayout(randomSeed = 123) %>%
      visPhysics(enabled = TRUE, stabilization = TRUE) %>%
      visInteraction(dragNodes = TRUE, dragView = TRUE, zoomView = TRUE)
  })
  
