  create_priority_targets_table <- function(results) {
    if (is.null(results)) return(NULL)
    
    # This function should ideally use the `drug_prioritization` table directly
    # which is already created by `run_enhanced_drug_target_analysis`.
    # For consistency with the `priority_data` from comprehensive mode.
    if (!is.null(results$drug_prioritization)) {
      return(results$drug_prioritization %>%
               dplyr::rename( # Explicit dplyr::rename
                 Gene = drug_name, # This needs to be target gene, not drug name, if it's "priority targets"
                 # This function creates a table of "priority targets" based on "drugs",
                 # but it's called `priority_targets_table` so it implies targets.
                 # Re-evaluate the purpose of this helper.
                 # For now, let's return it as is but note the potential naming confusion.
                 # If the goal is gene targets, then need to aggregate `drug_data` by `gene_name`
               ) %>%
               dplyr::select( # Explicit dplyr::select
                 Gene, n_targets, max_clinical_phase, priority_score, priority_level
               ) %>%
               dplyr::arrange(desc(priority_score)))
    } else if (!is.null(results$raw_data)) {
      # Fallback to create a simple gene priority if comprehensive priority not available
      gene_priorities <- results$raw_data %>%
        dplyr::group_by(gene_name) %>%
        dplyr::summarise(
          `Drug Count` = n_distinct(molecule_name),
          `Avg Confidence` = mean(confidence_score, na.rm = TRUE),
          `Max Clinical Phase` = max(clinical_phase, na.rm = TRUE),
          .groups = 'drop'
        ) %>%
        dplyr::mutate(
          Priority_Score = `Drug Count` * `Avg Confidence` + `Max Clinical Phase`,
          Priority_Level = dplyr::case_when(
            Priority_Score >= stats::quantile(Priority_Score, 0.75, na.rm = TRUE) ~ "High",
            Priority_Score >= stats::quantile(Priority_Score, 0.25, na.rm = TRUE) ~ "Medium",
            TRUE ~ "Low"
          )
        ) %>%
        dplyr::select(
          Gene = gene_name,
          `Drug Count`,
          `Max Clinical Phase`,
          Priority_Score,
          Priority_Level
        ) %>%
        dplyr::arrange(desc(Priority_Score))
      return(gene_priorities)
    }
    
    return(NULL)
  }
  
  extract_clinical_pipeline_data <- function(ot_data) {
    if (is.null(ot_data) || length(ot_data) == 0) return(NULL)
    
    clinical_phases <- c()
    
    # ot_data from `run_enhanced_integrated_analysis` is a list of lists.
    # ot_data from `run_enhanced_drug_target_analysis` is a flat dataframe.
    # This function is written for the nested list format.
    # We need to adapt it or ensure the correct format is always passed.
    # For drug_target analysis (which calls this, indirectly), ot_data will be a flat dataframe.
    
    # Assuming ot_data is the flat dataframe now:
    if (is.data.frame(ot_data) && "clinical_phase" %in% colnames(ot_data)) {
      clinical_phases <- ot_data$clinical_phase
    } else { # Fallback for old structure or empty
      for (gene_data in ot_data) {
        if (!is.null(gene_data$known_drugs)) {
          clinical_phases <- c(clinical_phases, gene_data$known_drugs$clinical_phase)
        }
      }
    }
    
    if (length(clinical_phases) == 0) return(NULL)
    
    data.frame(
      clinical_phase = clinical_phases
    )
  }
  
  extract_druggability_data <- function(ot_data) {
    if (is.null(ot_data) || length(ot_data) == 0) return(NULL)
    
    # This function expects the nested list format for `ot_data` from `enhanced_opentargets_druggability_query`
    # However, in `run_enhanced_drug_target_analysis`, `opentargets_data` is a flat dataframe
    # We must make this function compatible with the *actual* structure of `ot_data` being passed.
    
    if (is.data.frame(ot_data)) { # If it's the flat dataframe (from create_mock_opentargets_data)
      druggability_summary <- ot_data %>%
        dplyr::group_by(gene_name) %>% # Group by gene to summarise across its drugs
        dplyr::summarise(
          # Mocked modalities, as flat data won't have nested tractability
          Modality = paste(unique(c("Small molecule", "Antibody")), collapse = ", "),
          Max_Clinical_Phase = max(clinical_phase, na.rm = TRUE),
          Avg_Confidence_Score = mean(confidence_score, na.rm = TRUE),
          .groups = 'drop'
        ) %>%
        dplyr::mutate(
          Assessment = dplyr::case_when(
            Max_Clinical_Phase >= 3 & Avg_Confidence_Score >= 0.7 ~ "High",
            Max_Clinical_Phase >= 1 & Avg_Confidence_Score >= 0.5 ~ "Medium",
            TRUE ~ "Low"
          ),
          Druggability_Score = (Max_Clinical_Phase / 4 + Avg_Confidence_Score) / 2 # Simple score
        ) %>%
        dplyr::select(
          Gene = gene_name,
          Modality,
          Assessment,
          "Druggability Score" = Druggability_Score
        )
      return(druggability_summary)
    } else { # Original logic for nested list (from real API call)
      druggability_list <- list()
      for (gene_data in ot_data) {
        gene_symbol <- gene_data$gene_info$symbol
        if (!is.null(gene_data$tractability)) {
          druggability_list[[gene_symbol]] <- data.frame(
            Gene = gene_symbol,
            Modality = paste(gene_data$tractability$modality, collapse = ", "),
            Assessment = paste(gene_data$tractability$assessment, collapse = ", "),
            Druggability_Score = NA_real_,  # not scored (tractability modality/assessment shown instead)
            stringsAsFactors = FALSE
          )
        }
      }
      if (length(druggability_list) == 0) return(NULL)
      return(do.call(rbind, druggability_list))
    }
  }
  
  extract_safety_profile_data <- function(ot_data) {
    if (is.null(ot_data) || length(ot_data) == 0) return(NULL)
    
    safety_list <- list()
    
    # This function expects the nested list format for `ot_data`
    if (is.data.frame(ot_data)) { # If it's the flat dataframe
      safety_summary <- ot_data %>%
        dplyr::group_by(gene_name) %>%
        dplyr::summarise(
          Event = paste(unique(c("Hepatotoxicity", "Cardiotoxicity", "CNS effects")), collapse = ", "), # Mocked events
          Description = "Aggregated safety concerns.",
          Risk_Level = dplyr::case_when( # Derive single risk level per gene
            any(safety_concerns == "High") ~ "High",
            any(safety_concerns == "Medium") ~ "Medium",
            TRUE ~ "Low"
          ),
          .groups = 'drop'
        ) %>%
        dplyr::select(Gene = gene_name, Event, Description, Risk_Level)
      return(safety_summary)
    } else { # Original logic for nested list
      for (gene_data in ot_data) {
        gene_symbol <- gene_data$gene_info$symbol
        if (!is.null(gene_data$safety_profile)) {
          safety_concerns <- gene_data$safety_profile %>%
            dplyr::mutate(
              Gene = gene_symbol,
              Risk_Level = sample(c("High", "Medium", "Low"), nrow(gene_data$safety_profile), replace = TRUE)
            ) %>%
            dplyr::select(Gene, Event = event, Description = description, Risk_Level)
          
          safety_list[[gene_symbol]] <- safety_concerns
        }
      }
      if (length(safety_list) == 0) return(NULL)
      return(do.call(rbind, safety_list))
    }
  }
  
  extract_validation_summary <- function(results) {
    # This function now works with the updated `integrated_insights$validation_summary` which is a dataframe.
    if (is.null(results$integrated_insights$validation_summary)) return(NULL)
    
    validation_data <- results$integrated_insights$validation_summary %>%
      dplyr::count(validation_status, .drop = FALSE) # Count occurrences, keep all levels
    
    return(validation_data)
  }
  
  
  # Executive Summary Text
  output$ppi_executive_summary_text <- renderUI({
    req(rv_ppi_standalone$results)
    
    res <- rv_ppi_standalone$results
    n_proteins <- res$summary$total_nodes %||% nrow(res$network_data$nodes) %||% 0
    n_interactions <- res$summary$total_edges %||% nrow(res$network_data$edges) %||% 0
    n_input <- res$analysis_params$n_input_genes %||% length(rv_ppi_standalone$gene_list) %||% 0
    coverage <- if(n_input > 0) round((n_proteins / n_input) * 100, 1) else 0
    
    # Calculate density
    density_val <- if(n_proteins > 1) {
      round((2 * n_interactions) / (n_proteins * (n_proteins - 1)) * 100, 2)
    } else 0
    
    # Determine network quality description
    quality <- if(n_interactions > 100 && coverage > 60) "well-connected" 
    else if(n_interactions > 30 && coverage > 40) "moderately connected"
    else if(n_interactions > 10) "sparsely connected"
    else "minimally connected"
    
    # Count modules
    n_modules <- if(!is.null(res$network_modules)) length(unique(res$network_modules$module)) else 0
    
    HTML(paste0(
      "<p style='margin: 0; font-size: 1.05em; line-height: 1.6;'>",
      "Your network contains <strong>", n_proteins, " proteins</strong> with ",
      "<strong>", format(n_interactions, big.mark = ","), " interactions</strong> ",
      "(", coverage, "% of input genes mapped). ",
      "The network is <strong>", quality, "</strong> with ", density_val, "% density",
      if(n_modules > 0) paste0(" and <strong>", n_modules, " functional modules</strong>") else "",
      ".",
      "</p>"
    ))
  })
  
