  # Network Quality Badge
  output$ppi_quality_badge <- renderUI({
    req(rv_ppi_standalone$results)
    
    res <- rv_ppi_standalone$results
    n_proteins <- res$summary$total_nodes %||% 0
    n_interactions <- res$summary$total_edges %||% 0
    n_input <- res$analysis_params$n_input_genes %||% length(rv_ppi_standalone$gene_list) %||% 1
    coverage <- n_proteins / n_input
    
    # Calculate quality score
    density <- if(n_proteins > 1) (2 * n_interactions) / (n_proteins * (n_proteins - 1)) else 0
    avg_degree <- if(n_proteins > 0) (2 * n_interactions) / n_proteins else 0
    
    quality_score <- (coverage * 40) + (min(density * 20, 30)) + (min(avg_degree / 10, 30))
    
    quality_info <- if(quality_score >= 70) {
      list(grade = "Excellent", color = "#4CAF50", icon = "check-circle", 
           tip = "High coverage and connectivity - reliable network")
    } else if(quality_score >= 50) {
      list(grade = "Good", color = "#8BC34A", icon = "thumbs-up",
           tip = "Decent network - suitable for most analyses")
    } else if(quality_score >= 30) {
      list(grade = "Fair", color = "#FF9800", icon = "exclamation-circle",
           tip = "Consider lowering confidence threshold for more interactions")
    } else {
      list(grade = "Limited", color = "#f44336", icon = "exclamation-triangle",
           tip = "Few interactions found - try lower confidence or check gene identifiers")
    }
    
    div(style = paste0("display: inline-flex; align-items: center; padding: 8px 15px; 
                      background: ", quality_info$color, "20; border-radius: 20px;
                      border: 1px solid ", quality_info$color, ";"),
        icon(quality_info$icon, style = paste0("color: ", quality_info$color, "; margin-right: 8px;")),
        span(paste0("Network Quality: ", quality_info$grade), 
             style = paste0("color: ", quality_info$color, "; font-weight: 600; margin-right: 10px;")),
        span(quality_info$tip, style = "color: #666; font-size: 0.9em;")
    )
  })
  
