  output$ppi_kf_modules <- renderText({
    req(rv_ppi_standalone$results)
    modules <- rv_ppi_standalone$results$network_modules
    if(!is.null(modules) && nrow(modules) > 0) {
      length(unique(modules$module))
    } else {
      "0"
    }
  })
  
  output$ppi_kf_hubs <- renderText({
    req(rv_ppi_standalone$results)
    
    hubs <- rv_ppi_standalone$results$hub_proteins
    
    if (!is.null(hubs) && nrow(hubs) > 0 && "hub_type" %in% colnames(hubs)) {
      # Count only proteins classified as Hub or Major Hub
      n_hubs <- sum(hubs$hub_type %in% c("Hub", "Major Hub"), na.rm = TRUE)
      return(as.character(n_hubs))
    }
    
    # Fallback: Calculate from centrality if hub_proteins doesn't have hub_type
    cent <- rv_ppi_standalone$results$centrality_measures
    if (!is.null(cent) && "degree" %in% colnames(cent) && nrow(cent) > 0) {
      avg_degree <- mean(cent$degree, na.rm = TRUE)
      # Hub = degree > 2x average
      n_hubs <- sum(cent$degree > (2 * avg_degree), na.rm = TRUE)
      return(as.character(n_hubs))
    }
    
    "0"
  })
  
  # Top 5 Hub Proteins Cards
  output$ppi_top5_hubs_cards <- renderUI({
    req(rv_ppi_standalone$results)
    
    hubs <- rv_ppi_standalone$results$hub_proteins
    
    # First, filter to only actual hubs if hub_type column exists
    if (!is.null(hubs) && nrow(hubs) > 0) {
      if ("hub_type" %in% colnames(hubs)) {
        # Only show Hub and Major Hub
        hubs <- hubs[hubs$hub_type %in% c("Hub", "Major Hub"), ]
      }
      
      # If no hubs after filtering, try centrality measures
      if (nrow(hubs) == 0) {
        cent <- rv_ppi_standalone$results$centrality_measures
        if (!is.null(cent) && nrow(cent) > 0) {
          avg_degree <- mean(cent$degree, na.rm = TRUE)
          hubs <- cent[cent$degree > (1.5 * avg_degree), ]
          hubs <- hubs[order(-hubs$degree), ]
          if (!"gene" %in% colnames(hubs) && !is.null(rownames(hubs))) {
            hubs$gene <- rownames(hubs)
          }
        }
      }
    } else {
      # Try centrality if hub_proteins is null
      cent <- rv_ppi_standalone$results$centrality_measures
      if (!is.null(cent) && nrow(cent) > 0) {
        avg_degree <- mean(cent$degree, na.rm = TRUE)
        hubs <- cent[cent$degree > (1.5 * avg_degree), ]
        hubs <- hubs[order(-hubs$degree), ]
        if (!"gene" %in% colnames(hubs) && !is.null(rownames(hubs))) {
          hubs$gene <- rownames(hubs)
        }
      }
    }
    
    if (is.null(hubs) || nrow(hubs) == 0) {
      return(div(
        style = "text-align: center; padding: 30px; color: #999;",
        icon("circle-info", style = "font-size: 2em; margin-bottom: 10px;"),
        p("No significant hub proteins identified."),
        p("This may indicate a sparse network.", style = "font-size: 0.9em;"),
        p("Try lowering the STRING confidence threshold.", style = "font-size: 0.85em; color: #aaa;")
      ))
    }
    
    top5 <- head(hubs, 5)
    max_degree <- max(top5$degree, na.rm = TRUE)
    
    cards <- lapply(seq_len(nrow(top5)), function(i) {
      hub <- top5[i, ]
      degree_val <- hub$degree %||% 0
      bar_width <- (degree_val / max(max_degree, 1)) * 100
      
      hub_type <- if ("hub_type" %in% colnames(hub)) hub$hub_type else "Hub"
      hub_color <- if (hub_type == "Major Hub") "#e74c3c" else "#f39c12"
      
      betweenness_text <- if ("betweenness" %in% colnames(hub) && !is.na(hub$betweenness)) {
        paste0(" • Betw: ", round(hub$betweenness, 3))
      } else ""
      
      div(style = paste0("display: flex; align-items: center; padding: 12px; margin-bottom: 8px;
                       background: linear-gradient(90deg, ", hub_color, "15 0%, #fff 100%); 
                       border-radius: 8px; border-left: 3px solid ", hub_color, ";"),
          
          # Rank badge
          div(style = paste0("width: 32px; height: 32px; background: linear-gradient(135deg, ", 
                             hub_color, ", ", hub_color, "cc); 
                           border-radius: 50%; display: flex; align-items: center; justify-content: center; 
                           margin-right: 12px; flex-shrink: 0;"),
              span(i, style = "font-weight: bold; color: white; font-size: 0.9em;")
          ),
          
          # Gene info
          div(style = "flex: 1; min-width: 0;",
              div(style = "display: flex; align-items: center;",
                  strong(hub$gene, style = "color: #2c3e50; font-size: 1.1em;"),
                  if (hub_type == "Major Hub") {
                    span(" ★★", style = "color: #e74c3c; margin-left: 5px;")
                  } else if (i == 1) {
                    span(" ★", style = "color: #f39c12; margin-left: 5px;")
                  } else NULL
              ),
              div(style = "font-size: 0.85em; color: #7f8c8d;",
                  paste0(degree_val, " connections", betweenness_text)
              )
          ),
          
          # Degree bar
          div(style = "width: 80px; flex-shrink: 0;",
              div(style = "background: #eee; border-radius: 4px; height: 8px; overflow: hidden;",
                  div(style = paste0("height: 100%; background: linear-gradient(90deg, ", 
                                     hub_color, ", #e74c3c);
                                   border-radius: 4px; width: ", bar_width, "%;"))
              )
          )
      )
    })
    
    do.call(tagList, cards)
  })
  
  output$ppi_enrichment_full_table <- DT::renderDataTable({
    if (is.null(rv_ppi_standalone$results)) {
      return(DT::datatable(
        data.frame(Message = "No PPI results available. Please run analysis first."),
        options = list(dom = 't'),
        rownames = FALSE
      ))
    }
    
    # Try multiple locations for enrichment data
    enrichment <- rv_ppi_standalone$results$enrichment_results
    
    if (is.null(enrichment)) {
      enrichment <- rv_ppi_standalone$results$functional_enrichment
    }
    
    # If it's a list, convert to dataframe
    if (is.list(enrichment) && !is.data.frame(enrichment)) {
      enrichment <- tryCatch({
        combined <- do.call(rbind, lapply(names(enrichment), function(db_name) {
          df <- enrichment[[db_name]]
          if (!is.null(df) && is.data.frame(df) && nrow(df) > 0) {
            df$Database <- db_name
            return(df)
          }
          return(NULL)
        }))
        combined
      }, error = function(e) NULL)
    }
    
    if (is.null(enrichment) || !is.data.frame(enrichment) || nrow(enrichment) == 0) {
      return(DT::datatable(
        data.frame(Message = "No enrichment results available. Run analysis with pathway enrichment enabled."),
        options = list(dom = 't'),
        rownames = FALSE
      ))
    }
    
    # Standardize column names
    if ("Adjusted.P.value" %in% colnames(enrichment)) {
      enrichment$pvalue <- enrichment$Adjusted.P.value
    } else if ("p.adjust" %in% colnames(enrichment)) {
      enrichment$pvalue <- enrichment$p.adjust
    } else if ("adj.P.Val" %in% colnames(enrichment)) {
      enrichment$pvalue <- enrichment$adj.P.Val
    }
    
    # Order by p-value
    if ("pvalue" %in% colnames(enrichment)) {
      enrichment <- enrichment[order(enrichment$pvalue), ]
    }
    
    # Build a clean, lightweight display table
    display_df <- data.frame(stringsAsFactors = FALSE)

    # Pathway name (prefer Term, then Description)
    if ("Term" %in% colnames(enrichment)) {
      display_df$Pathway <- enrichment$Term
    } else if ("Description" %in% colnames(enrichment)) {
      display_df$Pathway <- enrichment$Description
    } else {
      display_df$Pathway <- rownames(enrichment)
    }
    # Truncate long pathway names
    display_df$Pathway <- sapply(display_df$Pathway, function(x) {
      if (nchar(x) > 60) paste0(substr(x, 1, 57), "...") else x
    })

    if ("Database" %in% colnames(enrichment)) display_df$Database <- enrichment$Database
    if ("Overlap" %in% colnames(enrichment)) display_df$Overlap <- enrichment$Overlap
    display_df$`Adj. P-value` <- enrichment$pvalue
    if ("Combined.Score" %in% colnames(enrichment)) {
      display_df$Score <- round(enrichment$Combined.Score, 2)
    }
    if ("Genes" %in% colnames(enrichment)) {
      # Truncate gene lists for display
      display_df$Genes <- sapply(enrichment$Genes, function(x) {
        if (is.na(x)) return("")
        genes <- strsplit(as.character(x), "[;/,]")[[1]]
        if (length(genes) > 5) paste0(paste(head(genes, 5), collapse = ", "), " +", length(genes) - 5, " more")
        else paste(genes, collapse = ", ")
      })
    }

    DT::datatable(
      display_df,
      options = list(
        pageLength = 10,
        scrollX = TRUE,
        dom = "frtip",
        order = list(list(which(colnames(display_df) == "Adj. P-value") - 1, "asc")),
        columnDefs = list(
          list(className = "dt-center", targets = "_all"),
          list(width = "35%", targets = 0)
        ),
        language = list(search = "Filter:")
      ),
      rownames = FALSE,
      class = "compact stripe hover",
      escape = FALSE
    ) %>%
      DT::formatSignif(columns = "Adj. P-value", digits = 3)
  })
  
  output$ppi_enrichment_barplot <- renderPlot({
    req(rv_ppi_standalone$results)
    
    # Try multiple locations
    enrichment <- rv_ppi_standalone$results$enrichment_results
    if (is.null(enrichment)) {
      enrichment <- rv_ppi_standalone$results$functional_enrichment
    }
    
    # Convert list to dataframe if needed
    if (is.list(enrichment) && !is.data.frame(enrichment)) {
      enrichment <- tryCatch({
        do.call(rbind, lapply(names(enrichment), function(db_name) {
          df <- enrichment[[db_name]]
          if (!is.null(df) && is.data.frame(df) && nrow(df) > 0) {
            df$Database <- db_name
            return(df)
          }
          NULL
        }))
      }, error = function(e) NULL)
    }
    
    if (is.null(enrichment) || !is.data.frame(enrichment) || nrow(enrichment) == 0) {
      plot(1, type = "n", axes = FALSE, xlab = "", ylab = "")
      text(1, 1, "No enrichment results available\nRun analysis with pathway enrichment enabled", 
           cex = 1.2, col = "#666")
      return()
    }
    
    # Find p-value column
    pval_col <- NULL
    for (col in c("Adjusted.P.value", "p.adjust", "adj.P.Val", "P.value")) {
      if (col %in% colnames(enrichment)) {
        pval_col <- col
        break
      }
    }
    
    # Find term column  
    term_col <- NULL
    for (col in c("Term", "Description", "Pathway", "Name")) {
      if (col %in% colnames(enrichment)) {
        term_col <- col
        break
      }
    }
    
    if (is.null(pval_col) || is.null(term_col)) {
      plot(1, type = "n", axes = FALSE, xlab = "", ylab = "")
      text(1, 1, "Could not parse enrichment results\nColumn format not recognized", cex = 1.2, col = "#666")
      return()
    }
    
    # Get top 15 pathways
    enrichment[[pval_col]] <- as.numeric(enrichment[[pval_col]])
    enrichment <- enrichment[!is.na(enrichment[[pval_col]]) & enrichment[[pval_col]] > 0, ]
    top_enrichment <- head(enrichment[order(enrichment[[pval_col]]), ], 15)
    
    if (nrow(top_enrichment) == 0) {
      plot(1, type = "n", axes = FALSE, xlab = "", ylab = "")
      text(1, 1, "No significant pathways found", cex = 1.2, col = "#666")
      return()
    }
    
    # Truncate long names
    top_enrichment$display_term <- sapply(top_enrichment[[term_col]], function(x) {
      if (nchar(x) > 50) paste0(substr(x, 1, 47), "...") else x
    })
    
    # Reverse order for horizontal barplot (so top is at top)
    top_enrichment <- top_enrichment[nrow(top_enrichment):1, ]
    
    # Plot
    par(mar = c(5, 18, 4, 2))
    
    colors <- colorRampPalette(c("#27ae60", "#3498db", "#9b59b6"))(nrow(top_enrichment))
    
    barplot(
      -log10(top_enrichment[[pval_col]]),
      names.arg = top_enrichment$display_term,
      horiz = TRUE,
      las = 1,
      col = colors,
      main = "Top Enriched Pathways",
      xlab = "-log10(Adjusted P-value)",
      cex.names = 1.0,
      cex.main = 1.3,
      cex.lab = 1.1,
      border = NA
    )
    
    # Add significance line
    abline(v = -log10(0.05), col = "red", lty = 2, lwd = 2)
    legend("bottomright", legend = "p = 0.05", lty = 2, col = "red", bty = "n")
    
  }, height = 500)
  
  
  output$ppi_enrichment_dotplot <- renderPlot({
    req(rv_ppi_standalone$results)
    
    enrichment <- rv_ppi_standalone$results$enrichment_results
    if (is.null(enrichment)) {
      enrichment <- rv_ppi_standalone$results$functional_enrichment
    }
    
    # Convert list to dataframe if needed
    if (is.list(enrichment) && !is.data.frame(enrichment)) {
      enrichment <- tryCatch({
        do.call(rbind, lapply(names(enrichment), function(db_name) {
          df <- enrichment[[db_name]]
          if (!is.null(df) && is.data.frame(df) && nrow(df) > 0) {
            df$Database <- db_name
            return(df)
          }
          NULL
        }))
      }, error = function(e) NULL)
    }
    
    if (is.null(enrichment) || !is.data.frame(enrichment) || nrow(enrichment) == 0) {
      plot(1, type = "n", axes = FALSE, xlab = "", ylab = "")
      text(1, 1, "No enrichment results available", cex = 1.2, col = "#666")
      return()
    }
    
    # Find required columns
    pval_col <- intersect(c("Adjusted.P.value", "P.value", "p.adjust"), colnames(enrichment))[1]
    term_col <- intersect(c("Term", "Description", "Pathway"), colnames(enrichment))[1]
    
    if (is.na(pval_col) || is.na(term_col)) {
      plot(1, type = "n", axes = FALSE, xlab = "", ylab = "")
      text(1, 1, "Could not parse enrichment results", cex = 1.2, col = "#666")
      return()
    }
    
    # Get count from Overlap or Genes column
    if ("Overlap" %in% colnames(enrichment)) {
      enrichment$count <- as.numeric(gsub("/.*", "", enrichment$Overlap))
    } else if ("Genes" %in% colnames(enrichment)) {
      enrichment$count <- sapply(enrichment$Genes, function(x) length(strsplit(as.character(x), ";")[[1]]))
    } else {
      enrichment$count <- 5  # Default
    }
    
    # Prepare data
    enrichment[[pval_col]] <- as.numeric(enrichment[[pval_col]])
    enrichment <- enrichment[!is.na(enrichment[[pval_col]]) & enrichment[[pval_col]] > 0, ]
    top_enrichment <- head(enrichment[order(enrichment[[pval_col]]), ], 15)
    
    if (nrow(top_enrichment) == 0) {
      plot(1, type = "n", axes = FALSE, xlab = "", ylab = "")
      text(1, 1, "No significant pathways found", cex = 1.2, col = "#666")
      return()
    }
    
    # Truncate names
    top_enrichment$display_term <- sapply(top_enrichment[[term_col]], function(x) {
      if (nchar(x) > 40) paste0(substr(x, 1, 37), "...") else x
    })
    
    # Create dotplot using base R
    par(mar = c(5, 18, 4, 6))
    
    # Dotplot
    x <- -log10(top_enrichment[[pval_col]])
    y <- seq_len(nrow(top_enrichment))
    
    # Color by database if available
    if ("Database" %in% colnames(top_enrichment)) {
      dbs <- unique(top_enrichment$Database)
      db_colors <- setNames(rainbow(length(dbs), s = 0.7, v = 0.8), dbs)
      colors <- db_colors[top_enrichment$Database]
    } else {
      colors <- colorRampPalette(c("#3498db", "#e74c3c"))(nrow(top_enrichment))
    }
    
    plot(x, y, 
         pch = 19, 
         cex = sqrt(top_enrichment$count) / 2 + 1,
         col = colors,
         xlab = "-log10(Adjusted P-value)", 
         ylab = "",
         yaxt = "n",
         main = "Pathway Enrichment Dotplot",
         xlim = c(0, max(x) * 1.1))
    
    axis(2, at = y, labels = top_enrichment$display_term, las = 1, cex.axis = 1.0)
    
    abline(v = -log10(0.05), col = "red", lty = 2)
    
    # Legend for database colors if available
    if ("Database" %in% colnames(top_enrichment)) {
      legend("bottomright", legend = names(db_colors), col = db_colors, pch = 19,
             title = "Database", cex = 0.8, bty = "n")
    }

  }, height = 500)


  # ============================================================
  # Download handlers for PPI standalone enrichment plots
  # (added so manuscript supplement panels can export them)
  # ============================================================
  ppi_standalone_enrichment_df <- function() {
    if (is.null(rv_ppi_standalone$results)) return(NULL)
    enr <- rv_ppi_standalone$results$enrichment_results %||%
           rv_ppi_standalone$results$functional_enrichment
    if (is.list(enr) && !is.data.frame(enr)) {
      enr <- tryCatch({
        do.call(rbind, lapply(names(enr), function(db_name) {
          df <- enr[[db_name]]
          if (!is.null(df) && is.data.frame(df) && nrow(df) > 0) {
            df$Database <- db_name
            return(df)
          }
          NULL
        }))
      }, error = function(e) NULL)
    }
    enr
  }

  output$download_ppi_enrichment_barplot <- downloadHandler(
    filename = function() paste0("ppi_enrichment_barplot_", Sys.Date(), ".png"),
    content = function(file) {
      load_export_packages()
      enr <- ppi_standalone_enrichment_df()
      png(file, width = 2400, height = 1500, res = 200, bg = "white")
      tryCatch({
        if (is.null(enr) || !is.data.frame(enr) || nrow(enr) == 0) {
          plot.new(); text(0.5, 0.5, "No enrichment results available", cex = 1.2)
        } else {
          pval_col <- intersect(c("Adjusted.P.value", "p.adjust", "adj.P.Val", "P.value"),
                                colnames(enr))[1]
          term_col <- intersect(c("Term", "Description", "Pathway", "Name"),
                                colnames(enr))[1]
          enr[[pval_col]] <- as.numeric(enr[[pval_col]])
          enr <- enr[!is.na(enr[[pval_col]]) & enr[[pval_col]] > 0, ]
          top <- head(enr[order(enr[[pval_col]]), ], 15)
          top$display_term <- ifelse(nchar(top[[term_col]]) > 45,
                                     paste0(substr(top[[term_col]], 1, 42), "..."),
                                     top[[term_col]])
          par(mar = c(5, 22, 4, 4))
          barplot(rev(-log10(top[[pval_col]])),
                  names.arg = rev(top$display_term),
                  horiz = TRUE, las = 1, col = "#3498db",
                  main = "Top 15 Enriched Pathways (PPI Network)",
                  xlab = "-log10(Adjusted P-value)",
                  cex.names = 0.95, cex.main = 1.4, cex.lab = 1.1)
          abline(v = -log10(0.05), col = "red", lty = 2, lwd = 2)
        }
      }, error = function(e) {
        plot.new(); text(0.5, 0.5, paste("Error:", e$message), col = "red")
      })
      dev.off()
    }
  )

