  # Sidebar Hubs List
  output$ppi_sidebar_hubs_list <- renderUI({
    req(rv_ppi_standalone$results)
    
    hubs <- rv_ppi_standalone$results$hub_proteins
    
    # Filter to only actual hubs
    if (!is.null(hubs) && nrow(hubs) > 0 && "hub_type" %in% colnames(hubs)) {
      hubs <- hubs[hubs$hub_type %in% c("Hub", "Major Hub"), ]
    }
    
    if (is.null(hubs) || nrow(hubs) == 0) {
      return(p("No significant hubs", style = "color: #999; font-size: 0.9em; text-align: center;"))
    }
    
    top_hubs <- head(hubs[order(-hubs$degree), ], 8)
    
    items <- lapply(seq_len(nrow(top_hubs)), function(i) {
      hub <- top_hubs[i, ]
      hub_type <- hub$hub_type %||% "Hub"
      badge_color <- if (hub_type == "Major Hub") "#e74c3c" else "#f39c12"
      
      div(style = "display: flex; justify-content: space-between; align-items: center; 
                padding: 6px 0; border-bottom: 1px dashed #eee;",
          div(
            span(hub$gene, style = "font-weight: 500;"),
            if (hub_type == "Major Hub") span(" ★", style = "color: #e74c3c; font-size: 0.8em;") else NULL
          ),
          span(hub$degree, style = paste0("background: ", badge_color, "; color: white; padding: 2px 8px; 
                                 border-radius: 10px; font-size: 0.8em;"))
      )
    })
    
    do.call(tagList, items)
  })
  
  # Actionable Insights
  output$ppi_actionable_insights <- renderUI({
    req(rv_ppi_standalone$results)
    
    res <- rv_ppi_standalone$results
    organism <- input$ppi_standalone_organism %||% "9606"
    hubs <- res$hub_proteins %||% res$centrality_measures
    modules <- res$network_modules
    n_proteins <- res$summary$total_nodes %||% 0
    n_interactions <- res$summary$total_edges %||% 0
    n_input <- res$analysis_params$n_input_genes %||% length(rv_ppi_standalone$gene_list) %||% 1
    coverage <- n_proteins / n_input
    
    insights <- list()
    
    # Insight 1: Top hub protein
    if(!is.null(hubs) && nrow(hubs) > 0) {
      top_hub <- hubs$gene[1]
      hub_degree <- hubs$degree[1]
      avg_degree <- if(n_proteins > 0) round(2 * n_interactions / n_proteins, 1) else 0
      fold_above <- round(hub_degree / max(avg_degree, 1), 1)
      
      insights[[length(insights) + 1]] <- div(
        style = "margin-bottom: 15px; padding-left: 25px; position: relative;",
        div(style = "position: absolute; left: 0; top: 3px;",
            icon("star", style = "color: #f39c12;")
        ),
        HTML(paste0(
          "<strong style='color: #2c3e50;'>", top_hub, "</strong> is your top hub protein with ",
          hub_degree, " connections (", fold_above, "× the network average). ",
          "<span style='color: #27ae60;'>This protein may be a key regulatory node worth prioritizing for validation.</span>"
        ))
      )
    }
    
    # Insight 2: Network connectivity assessment
    if(n_interactions > 0) {
      avg_degree <- round(2 * n_interactions / max(n_proteins, 1), 1)
      
      if(coverage < 0.5) {
        insights[[length(insights) + 1]] <- div(
          style = "margin-bottom: 15px; padding-left: 25px; position: relative;",
          div(style = "position: absolute; left: 0; top: 3px;",
              icon("exclamation-triangle", style = "color: #FF9800;")
          ),
          HTML(paste0(
            "<strong>Low mapping rate (", round(coverage * 100), "%):</strong> ",
            "Many input genes weren't found in STRING. ",
            "<span style='color: #666;'>Consider: (1) Check gene identifier format, (2) Lower confidence threshold, ",
            "(3) Some genes may lack known interactions.</span>"
          ))
        )
      } else if(avg_degree > 5) {
        insights[[length(insights) + 1]] <- div(
          style = "margin-bottom: 15px; padding-left: 25px; position: relative;",
          div(style = "position: absolute; left: 0; top: 3px;",
              icon("check-circle", style = "color: #4CAF50;")
          ),
          HTML(paste0(
            "<strong>Well-connected network</strong> (avg ", avg_degree, " connections/protein). ",
            "<span style='color: #27ae60;'>Good foundation for identifying functional modules and key regulators.</span>"
          ))
        )
      }
    }
    
    # Insight 3: Module information
    if(!is.null(modules) && nrow(modules) > 0) {
      n_modules <- length(unique(modules$module))
      largest_size <- max(table(modules$module))
      
      insights[[length(insights) + 1]] <- div(
        style = "margin-bottom: 15px; padding-left: 25px; position: relative;",
        div(style = "position: absolute; left: 0; top: 3px;",
            icon("object-group", style = "color: #9b59b6;")
        ),
        HTML(paste0(
          "<strong>", n_modules, " functional modules</strong> detected (largest: ", largest_size, " proteins). ",
          "<span style='color: #666;'>Proteins within modules often share biological functions. ",
          "Check module enrichment for pathway insights.</span>"
        ))
      )
    }
    
    # Only add drug-related insight for human
    if (organism == "9606" && !is.null(res$drug_targets) && nrow(res$drug_targets) > 0) {
      n_drugs <- nrow(res$drug_targets)
      n_druggable <- length(unique(res$drug_targets$gene))
      
      insights[[length(insights) + 1]] <- div(
        style = "margin-bottom: 15px; padding-left: 25px; position: relative;",
        div(style = "position: absolute; left: 0; top: 3px;",
            icon("pills", style = "color: #3498db;")
        ),
        HTML(paste0(
          "<strong>", n_druggable, " proteins</strong> in your network have known drug interactions ",
          "(", n_drugs, " total drug-gene pairs). ",
          "<span style='color: #27ae60;'>Check the Drug Targets tab for potential therapeutic connections.</span>"
        ))
      )
    }
    
    # Insight 4: Recommended next steps
    insights[[length(insights) + 1]] <- div(
      style = "margin-top: 20px; padding: 15px; background: white; border-radius: 8px;",
      div(style = "font-weight: 600; color: #2e7d32; margin-bottom: 10px;",
          icon("tasks", style = "margin-right: 8px;"),
          "Recommended Next Steps"
      ),
      tags$ol(style = "margin: 0; padding-left: 20px; color: #444;",
              tags$li("Explore the ", strong("Network Explorer"), " tab to visualize protein clusters"),
              tags$li("Review ", strong("Centrality Metrics"), " to identify additional important proteins"),
              tags$li("Check ", strong("Pathway Enrichment"), " for biological context"),
              tags$li("Validate top hub proteins in published literature")
      )
    )
    
    do.call(tagList, insights)
  })
  
  
  # Combined Centrality Plot
  output$ppi_centrality_plotly <- plotly::renderPlotly({
    req(rv_ppi_standalone$results$centrality_measures)

    cent <- rv_ppi_standalone$results$centrality_measures
    metric <- input$ppi_centrality_metric %||% "degree"

    if (!metric %in% colnames(cent)) metric <- "degree"

    # Get top 20 proteins for the selected metric
    top_n <- head(cent[order(-cent[[metric]]), ], 20)
    top_n$gene <- factor(top_n$gene, levels = rev(top_n$gene))

    # Color based on metric
    colors <- list(degree = "#3498db", betweenness = "#e74c3c",
                   closeness = "#27ae60", eigenvector = "#9b59b6")
    bar_color <- colors[[metric]] %||% "#3498db"

    metric_labels <- list(degree = "Degree (connections)",
                          betweenness = "Betweenness Centrality",
                          closeness = "Closeness Centrality",
                          eigenvector = "Eigenvector Centrality")

    p <- plotly::plot_ly(
      data = top_n,
      y = ~gene,
      x = ~get(metric),
      type = "bar",
      orientation = "h",
      marker = list(color = bar_color, line = list(color = "white", width = 0.5)),
      hovertemplate = paste0("<b>%{y}</b><br>", metric_labels[[metric]],
                             ": %{x:.4f}<br>Degree: %{customdata}<extra></extra>"),
      customdata = ~degree
    ) %>%
      plotly::layout(
        xaxis = list(title = metric_labels[[metric]], gridcolor = "#f0f0f0"),
        yaxis = list(title = "", tickfont = list(size = 12)),
        margin = list(l = 100, r = 20, t = 10, b = 40),
        plot_bgcolor = "white",
        paper_bgcolor = "white"
      ) %>%
      plotly::config(displayModeBar = FALSE)

    p
  })
  
  # Module Enrichment Plot
  output$ppi_module_enrichment_plot <- renderPlot({
    req(rv_ppi_standalone$results)
    
    module_enrichment <- rv_ppi_standalone$results$module_enrichment
    selected_module <- input$ppi_module_select
    
    # If no enrichment data
    if (is.null(module_enrichment) || length(module_enrichment) == 0) {
      plot(1, type = "n", axes = FALSE, xlab = "", ylab = "")
      text(1, 1, "No module enrichment results available.\nModules may be too small for enrichment analysis.", 
           cex = 1.1, col = "#666")
      return()
    }
    
    # Combine enrichment data based on selection
    if (selected_module == "all" || is.null(selected_module)) {
      # Combine all module enrichments
      combined <- do.call(rbind, lapply(names(module_enrichment), function(mod_name) {
        mod_data <- module_enrichment[[mod_name]]
        if (is.list(mod_data) && !is.data.frame(mod_data)) {
          # If it's a nested list from enrichR
          mod_data <- do.call(rbind, lapply(names(mod_data), function(db) {
            df <- mod_data[[db]]
            if (!is.null(df) && is.data.frame(df) && nrow(df) > 0) {
              df$Module <- mod_name
              df$Database <- db
              return(df)
            }
            return(NULL)
          }))
        }
        if (!is.null(mod_data) && is.data.frame(mod_data) && nrow(mod_data) > 0) {
          if (!"Module" %in% colnames(mod_data)) mod_data$Module <- mod_name
          return(mod_data)
        }
        return(NULL)
      }))
    } else {
      # Get specific module
      mod_name <- paste0("Module_", selected_module)
      mod_data <- module_enrichment[[mod_name]]
      
      if (is.list(mod_data) && !is.data.frame(mod_data)) {
        combined <- do.call(rbind, lapply(names(mod_data), function(db) {
          df <- mod_data[[db]]
          if (!is.null(df) && is.data.frame(df) && nrow(df) > 0) {
            df$Module <- mod_name
            df$Database <- db
            return(df)
          }
          return(NULL)
        }))
      } else {
        combined <- mod_data
      }
    }
    
    if (is.null(combined) || !is.data.frame(combined) || nrow(combined) == 0) {
      plot(1, type = "n", axes = FALSE, xlab = "", ylab = "")
      text(1, 1, "No significant enrichment found for selected module(s)", cex = 1.1, col = "#666")
      return()
    }
    
    # Find p-value column
    pval_col <- intersect(c("Adjusted.P.value", "P.value", "p.adjust"), colnames(combined))[1]
    term_col <- intersect(c("Term", "Description", "Pathway"), colnames(combined))[1]
    
    if (is.na(pval_col) || is.na(term_col)) {
      plot(1, type = "n", axes = FALSE, xlab = "", ylab = "")
      text(1, 1, "Could not parse enrichment results", cex = 1.1, col = "#666")
      return()
    }
    
    # Get top 10 pathways
    combined <- combined[order(combined[[pval_col]]), ]
    top_terms <- head(combined, 10)
    
    # Truncate long names
    top_terms$display_term <- sapply(top_terms[[term_col]], function(x) {
      if (nchar(x) > 40) paste0(substr(x, 1, 37), "...") else x
    })
    
    # Reverse for plotting
    top_terms <- top_terms[nrow(top_terms):1, ]
    
    # Plot
    par(mar = c(5, 18, 4, 2))
    
    colors <- colorRampPalette(c("#3498db", "#9b59b6", "#e74c3c"))(nrow(top_terms))
    
    barplot(
      -log10(top_terms[[pval_col]]),
      names.arg = top_terms$display_term,
      horiz = TRUE,
      las = 1,
      col = colors,
      main = "Module Enrichment",
      xlab = "-log10(Adjusted P-value)",
      cex.names = 1.0,
      cex.main = 1.3,
      cex.lab = 1.1,
      border = NA
    )
    
    abline(v = -log10(0.05), col = "red", lty = 2)
    
  }, height = 350)
  
  # Module Enrichment Table
