        mod_data <- module_enrichment[[mod_name]]
        if (is.list(mod_data) && !is.data.frame(mod_data)) {
          mod_data <- do.call(rbind, lapply(names(mod_data), function(db) {
            df <- mod_data[[db]]
            if (!is.null(df) && is.data.frame(df) && nrow(df) > 0) {
              df$Module <- mod_name
              df$Database <- db
              return(df)
            }
            return(NULL)
          }))
        }
        if (!is.null(mod_data) && is.data.frame(mod_data) && nrow(mod_data) > 0) {
          if (!"Module" %in% colnames(mod_data)) mod_data$Module <- mod_name
          return(mod_data)
        }
        return(NULL)
      }))
    } else {
      mod_name <- paste0("Module_", selected_module)
      mod_data <- module_enrichment[[mod_name]]
      
      if (is.list(mod_data) && !is.data.frame(mod_data)) {
        combined <- do.call(rbind, lapply(names(mod_data), function(db) {
          df <- mod_data[[db]]
          if (!is.null(df) && is.data.frame(df) && nrow(df) > 0) {
            df$Module <- mod_name
            df$Database <- db
            return(df)
          }
          return(NULL)
        }))
      } else {
        combined <- mod_data
      }
    }
    
    if (is.null(combined) || !is.data.frame(combined) || nrow(combined) == 0) {
      return(DT::datatable(
        data.frame(Message = "No significant enrichment for selected module(s)"),
        options = list(dom = 't'),
        rownames = FALSE
      ))
    }
    
    # Select display columns
    display_cols <- c("Module", "Term", "Database", "Adjusted.P.value", "P.value", "Genes", "Overlap")
    available_cols <- intersect(display_cols, colnames(combined))
    
    if (length(available_cols) == 0) {
      available_cols <- colnames(combined)[1:min(5, ncol(combined))]
    }
    
    DT::datatable(
      combined[, available_cols, drop = FALSE],
      options = list(
        pageLength = 10,
        scrollX = TRUE
      ),
      rownames = FALSE,
      filter = "top"
    )
  })
  
  
