      ))
    }
    
    cent <- rv_ppi_standalone$results$centrality_measures
    
    if (is.null(cent) || !is.data.frame(cent) || nrow(cent) == 0) {
      return(DT::datatable(
        data.frame(Message = "No centrality measures available."),
        options = list(dom = 't', pageLength = 1),
        rownames = FALSE
      ))
    }
    
    # Round numeric columns
    numeric_cols <- sapply(cent, is.numeric)
    cent[numeric_cols] <- lapply(cent[numeric_cols], round, 4)
    
    # Ensure degree column exists for styling
    if (!"degree" %in% colnames(cent)) {
      return(DT::datatable(
        cent,
        options = list(
          pageLength = 15,
          scrollX = TRUE
        ),
        rownames = FALSE,
        filter = "top"
      ))
    }
    
    DT::datatable(
      cent,
      options = list(
        pageLength = 15,
        scrollX = TRUE,
        order = list(list(1, 'desc'))
      ),
      rownames = FALSE,
      filter = "top"
    ) %>%
      DT::formatStyle('degree', background = DT::styleColorBar(range(cent$degree, na.rm = TRUE), '#3498db40'))
  })
  
