  identify_hubs_with_significance <- function(ppi_interactions, n_permutations = 100) {
    
    # Build graph
    g <- igraph::graph_from_data_frame(
      ppi_interactions[, c("gene_from", "gene_to")],
      directed = FALSE
    )
    
    # Calculate actual degrees
    degrees <- igraph::degree(g)
    n_nodes <- length(degrees)
    n_edges <- igraph::ecount(g)
    
    # Calculate expected degree in random network (Erdos-Renyi)
    p <- 2 * n_edges / (n_nodes * (n_nodes - 1))
    expected_degree <- p * (n_nodes - 1)
    
    # Identify hubs: degree > 2 * expected OR top 10%
    threshold <- max(2 * expected_degree, quantile(degrees, 0.9))
    
    hub_genes <- names(degrees[degrees >= threshold])
    
    # Calculate other centrality measures for hubs
    betweenness <- igraph::betweenness(g, normalized = TRUE)
    closeness <- igraph::closeness(g, normalized = TRUE)
    eigenvector <- igraph::eigen_centrality(g)$vector
    
    hub_df <- data.frame(
      gene = hub_genes,
      degree = degrees[hub_genes],
      betweenness = betweenness[hub_genes],
      closeness = closeness[hub_genes],
      eigenvector = eigenvector[hub_genes],
      is_hub = TRUE,
      hub_score = (degrees[hub_genes] / max(degrees)) * 0.4 +
        (betweenness[hub_genes] / max(betweenness)) * 0.3 +
        (eigenvector[hub_genes] / max(eigenvector)) * 0.3,
      stringsAsFactors = FALSE
    )
    
    hub_df <- hub_df[order(-hub_df$hub_score), ]
    
    return(list(
      hubs = hub_df,
      threshold = threshold,
      expected_degree = expected_degree,
      network_stats = list(
        n_nodes = n_nodes,
        n_edges = n_edges,
        avg_degree = mean(degrees),
        max_degree = max(degrees)
      )
    ))
  }
  
  map_drug_targets_comprehensive <- function(proteins, organism = "human") {
    
    # This would query multiple sources:
    # 1. DrugBank (FDA approved)
    # 2. ChEMBL (clinical candidates)
    # 3. DGIdb (drug-gene interactions)
    
    # For now, use DGIdb API (free, comprehensive)
    tryCatch({
      base_url <- "https://dgidb.org/api/v2/interactions.json"
      
      # Batch query (max 100 genes at a time)
      batches <- split(proteins, ceiling(seq_along(proteins) / 100))
      
      all_results <- data.frame()
      
      for(batch in batches) {
        query_url <- paste0(base_url, "?genes=", paste(batch, collapse = ","))
        response <- httr::GET(query_url, httr::timeout(30))
        
        if(httr::status_code(response) == 200) {
          data <- httr::content(response, "parsed")
          
          for(match in data$matchedTerms) {
            gene <- match$searchTerm
            for(interaction in match$interactions) {
              all_results <- rbind(all_results, data.frame(
                gene = gene,
                drug_name = interaction$drugName %||% NA,
                interaction_type = interaction$interactionTypes %||% NA,
                source = interaction$source %||% NA,
                pmid = interaction$pmid %||% NA,
                stringsAsFactors = FALSE
              ))
            }
          }
        }
        
        Sys.sleep(0.5)  # Rate limiting
      }
      
      return(all_results)
      
    }, error = function(e) {
      print(paste("Drug target query error:", e$message))
      return(data.frame())
    })
  }
  
  calculate_network_quality <- function(ppi_interactions, input_genes) {
    
    g <- igraph::graph_from_data_frame(
      ppi_interactions[, c("gene_from", "gene_to")],
      directed = FALSE
    )
    
    # Basic metrics
    n_nodes <- igraph::vcount(g)
    n_edges <- igraph::ecount(g)
    
    # Connectivity
    components <- igraph::components(g)
    n_components <- components$no
    largest_component_size <- max(components$csize)
    largest_component_fraction <- largest_component_size / n_nodes
    
    # Network properties
    density <- igraph::edge_density(g)
    transitivity <- igraph::transitivity(g, type = "global")
    avg_path_length <- if(igraph::is_connected(g)) igraph::mean_distance(g) else NA
    diameter <- if(igraph::is_connected(g)) igraph::diameter(g) else NA
    
    # Coverage
    network_genes <- unique(c(ppi_interactions$gene_from, ppi_interactions$gene_to))
    coverage_rate <- length(intersect(network_genes, input_genes)) / length(input_genes)
    
    # Quality score (0-100)
    quality_score <- (
      coverage_rate * 30 +                           # Coverage weight
        largest_component_fraction * 30 +              # Connectivity weight
        min(1, n_edges / (n_nodes * 2)) * 20 +        # Edge density weight
        (1 - 1/max(n_nodes, 1)) * 20                   # Size weight
    )
    
    return(list(
      n_nodes = n_nodes,
      n_edges = n_edges,
      n_components = n_components,
      largest_component_size = largest_component_size,
      largest_component_fraction = round(largest_component_fraction, 3),
      density = round(density, 4),
      transitivity = round(transitivity, 4),
      avg_path_length = round(avg_path_length, 2),
      diameter = diameter,
      coverage_rate = round(coverage_rate, 3),
      quality_score = round(quality_score, 1),
      quality_grade = if(quality_score >= 80) "Excellent" 
      else if(quality_score >= 60) "Good"
      else if(quality_score >= 40) "Fair"
      else "Poor"
    ))
  }
  
  
