  # PPI Hub Table
  output$ppi_hub_table <- DT::renderDataTable({
    req(network_rv$current_results)
    req(network_rv$current_results$analysis_type == "ppi")
    req(network_rv$current_results$hub_proteins)

    hub_data     <- network_rv$current_results$hub_proteins
    centrality   <- network_rv$current_results$centrality_measures
    drug_sum     <- network_rv$current_results$druggability_summary

    if (nrow(hub_data) == 0) {
      return(DT::datatable(
        data.frame(Message = "No hub proteins found"),
        options = list(pageLength = 5, dom = 't')
      ))
    }

    # Start from hub_proteins; left-join centrality (for MCC/MNC/DMNC/EPC
    # columns that live only on centrality_measures) and druggability_summary.
    display_table <- hub_data %>%
      mutate(
        Protein = gene,
        Degree = degree,
        `Hub Type` = hub_type,
        `Hub Score` = round(hub_score, 3),
        Source = gene_source,
        Regulation = ifelse(regulation == "Unknown", "-", regulation),
        Betweenness = round(betweenness, 3),
        Closeness = if ("closeness" %in% names(hub_data)) round(closeness, 4) else NA_real_,
        Eigenvector = round(eigenvector, 3)
      )

    # Join CytoHubba columns (MCC / MNC / DMNC / EPC) from centrality_measures
    if (!is.null(centrality) && nrow(centrality) > 0) {
      cent_idx <- match(toupper(display_table$Protein), toupper(centrality$gene))
      display_table$MCC  <- centrality$MCC[cent_idx]
      display_table$MNC  <- centrality$MNC[cent_idx]
      display_table$DMNC <- centrality$DMNC[cent_idx]
      display_table$EPC  <- centrality$EPC[cent_idx]
    } else {
      display_table$MCC <- display_table$MNC <-
        display_table$DMNC <- display_table$EPC <- NA_real_
    }

    # Join druggability summary
    if (!is.null(drug_sum) && is.data.frame(drug_sum) && nrow(drug_sum) > 0) {
      drug_idx <- match(toupper(display_table$Protein), toupper(drug_sum$gene))
      display_table$Druggable      <- ifelse(!is.na(drug_idx), "✓", "")
      display_table$`Drug count`   <- ifelse(!is.na(drug_idx),
                                             drug_sum$n_drugs[drug_idx],
                                             NA_integer_)
      display_table$`Approval stage` <- ifelse(!is.na(drug_idx),
                                               drug_sum$max_approval_stage[drug_idx],
                                               "")
    } else {
      display_table$Druggable <- ""
      display_table$`Drug count` <- NA_integer_
      display_table$`Approval stage` <- ""
    }

    display_table <- display_table %>%
      select(Protein, Degree, `Hub Type`, `Hub Score`, Source, Regulation,
             Betweenness, Closeness, Eigenvector,
             MCC, MNC, DMNC, EPC,
             Druggable, `Drug count`, `Approval stage`) %>%
      arrange(desc(Degree))

    DT::datatable(
      display_table,
      options = list(
        pageLength = 15,
        scrollX = TRUE
      ),
      rownames = FALSE
    ) %>%
      DT::formatStyle(
        'Hub Type',
        backgroundColor = DT::styleEqual(
          c("Major Hub", "Hub", "Connector", "Peripheral"),
          c('#e74c3c', '#f39c12', '#3498db', '#95a5a6')
        ),
        color = "white"
      ) %>%
      DT::formatStyle(
        'Regulation',
        backgroundColor = DT::styleEqual(
          c("Up", "Down", "-"),
          c('#e8f5e8', '#e8f4fd', '#f8f9fa')
        )
      ) %>%
      DT::formatStyle(
        'Druggable',
        backgroundColor = DT::styleEqual("✓", "#fff3cd"),
        fontWeight = DT::styleEqual("✓", "bold")
      ) %>%
      DT::formatStyle(
        'Approval stage',
        backgroundColor = DT::styleEqual(
          c("Approved", "Phase IV", "Phase III", "Phase II", "Phase I",
            "Preclinical", "Unknown", ""),
          c('#d1e7dd', '#d1e7dd', '#cfe2ff', '#cfe2ff', '#fff3cd',
            '#f8d7da', '#f8f9fa', '#ffffff')
        )
      )
  })

  # ============================================================
  # Top hubs bar plot (added for manuscript supplement panel S6B)
  # ============================================================
  build_ppi_top_hubs_barplot <- function(hub_data, n_top = 15) {
    if (is.null(hub_data) || nrow(hub_data) == 0) return(NULL)

    top_hubs <- hub_data[order(-hub_data$degree), ][seq_len(min(n_top, nrow(hub_data))), ]
    top_hubs$gene       <- factor(top_hubs$gene, levels = rev(top_hubs$gene))
    top_hubs$Regulation <- ifelse(top_hubs$regulation %in% c("Up", "Down"),
                                  top_hubs$regulation, "Unspecified")
    reg_levels <- c("Up", "Down", "Unspecified")
    top_hubs$Regulation <- factor(top_hubs$Regulation, levels = reg_levels)

    ggplot(top_hubs, aes(x = gene, y = degree, fill = Regulation)) +
      geom_col(width = 0.75) +
      geom_text(aes(label = degree), hjust = -0.2, size = 3.8, fontface = "bold") +
      coord_flip() +
      scale_fill_manual(values = c("Up" = "#27ae60",
                                   "Down" = "#3498db",
                                   "Unspecified" = "#95a5a6"),
                        drop = FALSE) +
      scale_y_continuous(expand = expansion(mult = c(0, 0.12))) +
      labs(title = paste0("Top ", nrow(top_hubs),
                          " Hub Proteins by Network Degree"),
           x = NULL, y = "Degree") +
      theme_bw(base_size = 13) +
      theme(plot.background  = element_rect(fill = "white", color = NA),
            panel.background = element_rect(fill = "white", color = NA),
            legend.background = element_rect(fill = "white", color = NA),
            panel.grid.major.y = element_blank(),
            panel.grid.minor   = element_blank(),
            panel.border       = element_rect(color = "grey80", fill = NA),
            axis.text.y  = element_text(size = 11, color = "grey15", face = "bold"),
            axis.text.x  = element_text(size = 11, color = "grey20"),
            axis.title.x = element_text(size = 12, margin = margin(t = 8)),
            plot.title   = element_text(size = 15, face = "bold",
                                        margin = margin(b = 12)),
            legend.position = "top",
            legend.title    = element_text(face = "bold"),
            plot.margin     = margin(15, 25, 15, 15))
  }

