  # Reactive that builds the Key Drivers consensus table from current
  # centrality + druggability results, honoring the user's Top-N /
  # minimum-agreement / druggable-only controls.
  ppi_key_drivers_df <- reactive({
    req(network_rv$current_results)
    req(network_rv$current_results$analysis_type == "ppi")
    centrality <- network_rv$current_results$centrality_measures
    drug_sum   <- network_rv$current_results$druggability_summary
    if (is.null(centrality) || nrow(centrality) == 0) return(NULL)

    top_n     <- as.integer(input$ppi_kd_topn %||% 10)
    min_agree <- as.integer(input$ppi_kd_min_agree %||% 4)
    drug_only <- isTRUE(input$ppi_kd_druggable_only)

    cons <- calculate_hub_consensus(centrality, top_n = top_n)
    if (is.null(cons) || nrow(cons) == 0) return(NULL)

    cons <- cons[cons$consensus_score >= min_agree, , drop = FALSE]
    if (nrow(cons) == 0) return(cons)

    # Flags column: "d b c e M N D E" for each algorithm this gene is a
    # top-N member of (compact visualization without a wide table).
    algo_cols <- setdiff(names(cons), c("gene", "consensus_score"))
    short_keys <- c(degree = "d", betweenness = "b", closeness = "c",
                    eigenvector = "e", MCC = "M", MNC = "N",
                    DMNC = "D", EPC = "E")
    flags <- apply(cons[, algo_cols, drop = FALSE], 1, function(row) {
      paste(short_keys[algo_cols][as.logical(row)], collapse = " ")
    })

    out <- data.frame(
      Gene = cons$gene,
      `Consensus score` = cons$consensus_score,
      `Ranks in` = flags,
      stringsAsFactors = FALSE,
      check.names = FALSE
    )

    # Attach key centrality values for reference
    ci <- match(toupper(out$Gene), toupper(centrality$gene))
    out$Degree <- centrality$degree[ci]
    out$MCC    <- centrality$MCC[ci]
    out$Betweenness <- centrality$betweenness[ci]

    # Druggability columns
    if (!is.null(drug_sum) && is.data.frame(drug_sum) && nrow(drug_sum) > 0) {
      di <- match(toupper(out$Gene), toupper(drug_sum$gene))
      out$Druggable        <- ifelse(!is.na(di), "✓", "")
      out$`Drug count`     <- ifelse(!is.na(di), drug_sum$n_drugs[di], NA_integer_)
      out$`Approval stage` <- ifelse(!is.na(di), drug_sum$max_approval_stage[di], "")
    } else {
      out$Druggable <- ""
      out$`Drug count` <- NA_integer_
      out$`Approval stage` <- ""
    }

    if (drug_only) out <- out[out$Druggable == "✓", , drop = FALSE]
    out
  })

