  # ============================================================================
  
  # Deconvolution Summary Cards
  output$total_cell_types <- renderText({
    req(network_rv$current_results)
    req(input$network_analysis_type_systems == "deconv") # Corrected to network_analysis_type_systems
    
    if (!is.null(network_rv$current_results$summary_stats$deconv)) {
      as.character(network_rv$current_results$summary_stats$deconv$total_cell_types)
    } else { "0" }
  })
  
  output$dominant_cell_type <- renderText({
    req(network_rv$current_results)
    req(input$network_analysis_type_systems == "deconv") # Corrected to network_analysis_type_systems
    
    if (!is.null(network_rv$current_results$summary_stats$deconv)) {
      as.character(network_rv$current_results$summary_stats$deconv$dominant_cell_type)
    } else { "N/A" }
  })
  
  output$deconv_confidence <- renderText({
    req(network_rv$current_results)
    req(input$network_analysis_type_systems == "deconv") # Corrected to network_analysis_type_systems
    
    if (!is.null(network_rv$current_results$summary_stats$deconv)) {
      as.character(network_rv$current_results$summary_stats$deconv$confidence_score)
    } else { "0" }
  })
  
  output$marker_genes <- renderText({
    req(network_rv$current_results)
    req(input$network_analysis_type_systems == "deconv") # Corrected to network_analysis_type_systems
    
    if (!is.null(network_rv$current_results$summary_stats$deconv)) {
      as.character(network_rv$current_results$summary_stats$deconv$marker_genes)
    } else { "0" }
  })
  
  # Cell Type Composition Table
  output$deconv_composition_table <- DT::renderDataTable({
    req(network_rv$current_results)
    req(input$network_analysis_type_systems == "deconv") # Corrected to network_analysis_type_systems
    
    if (!is.null(network_rv$current_results$deconv_data$cell_composition)) {
      composition_table <- network_rv$current_results$deconv_data$cell_composition %>%
        dplyr::mutate( # Explicit dplyr::mutate
          Proportion_Percent = round(proportion * 100, 2),
          Significance = dplyr::case_when( # Explicit dplyr::case_when
            p_value < 0.001 ~ "***",
            p_value < 0.01 ~ "**",
            p_value < 0.05 ~ "*",
            TRUE ~ "ns"
          )
        ) %>%
        dplyr::select( # Explicit dplyr::select
          "Cell Type" = cell_type,
          "Proportion (%)" = Proportion_Percent,
          "Confidence Score" = confidence_score,
          "P-value" = p_value,
          "Significance" = Significance
        )
      
      DT::datatable(
        composition_table,
        options = list(pageLength = 10, dom = 'frtip'),
        rownames = FALSE
      ) %>%
        DT::formatRound(columns = c("Confidence Score", "P-value"), digits = 3) %>%
        DT::formatStyle(
          'Proportion (%)',
          backgroundColor = DT::styleInterval(
            c(10, 20, 30),
            c('#ffffff', '#e8f5e8', '#d4edda', '#28a745')
          )
        )
    } else {
      DT::datatable(data.frame(Message = "No deconvolution data available"))
    }
  })
  
  # Cell Type Pie Chart
  output$deconv_pie_chart <- renderPlotly({
    req(network_rv$current_results)
    req(input$network_analysis_type_systems == "deconv") # Corrected to network_analysis_type_systems
    
    if (!is.null(network_rv$current_results$deconv_data$cell_composition)) {
      pie_data <- network_rv$current_results$deconv_data$cell_composition
      
      p <- plotly::plot_ly( # Explicit plotly::plot_ly
        pie_data,
        labels = ~cell_type,
        values = ~proportion,
        type = 'pie',
        textinfo = 'label+percent',
        textposition = 'outside',
        marker = list(line = list(color = '#FFFFFF', width = 2))
      ) %>%
        plotly::layout( # Explicit plotly::layout
          title = "Cell Type Composition",
          showlegend = TRUE,
          legend = list(orientation = "v", x = 1.1, y = 0.5)
        )
      
      p
    } else {
      plotly::plot_ly() %>% # Explicit plotly::plot_ly
        plotly::add_annotations( # Explicit plotly::add_annotations
          text = "No deconvolution data available",
          x = 0.5, y = 0.5,
          showarrow = FALSE
        )
    }
  })
  
  # Cell Type Bar Chart
  output$deconv_bar_chart <- renderPlotly({
    req(network_rv$current_results)
    req(input$network_analysis_type_systems == "deconv") # Corrected to network_analysis_type_systems
    
    if (!is.null(network_rv$current_results$deconv_data$cell_composition)) {
      bar_data <- network_rv$current_results$deconv_data$cell_composition %>%
        dplyr::mutate(Proportion_Percent = proportion * 100) %>% # Explicit dplyr::mutate
        dplyr::arrange(desc(Proportion_Percent)) # Explicit dplyr::arrange
      
      p <- ggplot(bar_data, aes(x = reorder(cell_type, Proportion_Percent), y = Proportion_Percent, fill = cell_type)) +
        geom_bar(stat = "identity") +
        coord_flip() +
        labs(
          title = "Cell Type Proportions",
          x = "Cell Type",
          y = "Proportion (%)"
        ) +
        theme_minimal() +
        theme(
          legend.position = "none",
          plot.title = element_text(hjust = 0.5)
        ) +
        scale_fill_viridis_d()
      
      plotly::ggplotly(p, height = 400) # Explicit plotly::ggplotly
    } else {
      p <- ggplot() +
        annotate("text", x = 0.5, y = 0.5, label = "No deconvolution data available", size = 6) +
        theme_void()
      plotly::ggplotly(p, height = 400) # Explicit plotly::ggplotly
    }
  })
  
  output$deconv_method_comparison_warning <- renderUI({
    req(network_rv$current_results)
    
    if (!is.null(network_rv$current_results$method)) {
      method <- network_rv$current_results$method
      
      warning_box <- NULL
      
      if (method == "epic") {
        warning_box <- div(
          class = "alert alert-warning",
          style = "background-color: #fff3cd; border: 2px solid #ffc107; padding: 15px; margin: 20px 0;",
          h4(icon("exclamation-triangle"), " Method Compatibility Warning", style = "color: #856404; margin-top: 0;"),
          p(
            "You are using ", tags$strong("EPIC"), " method, which is designed for ",
            tags$strong("tumor microenvironment deconvolution"), ".", 
            style = "margin-bottom: 10px;"
          ),
          p(
            tags$strong("⚠️ Important:"), " If your experiment involves ",
            tags$strong("pure immune cells (e.g., CAR-T, PBMC, isolated T cells)"),
            ", EPIC may produce unreliable results.",
            style = "margin-bottom: 10px;"
          ),
          p(
            "Consider re-running with ", tags$strong("xCell"), " or ", 
            tags$strong("MCP-counter"), " for more accurate immune cell quantification.",
            style = "margin-bottom: 0; color: #856404;"
          ),
          hr(),
          p(
            icon("info-circle"), " Different methods may produce contradictory results. ",
            "Always choose the method appropriate for your sample type.",
            style = "font-size: 12px; color: #666; margin-bottom: 0;"
          )
        )
      }
      
      return(warning_box)
    }
  })
  
  output$deconv_interpretation_guide <- renderUI({
    req(network_rv$current_results)
    
    method <- network_rv$current_results$method
    
    interpretation <- switch(
      method,
      
      "xcell" = div(
        h5(icon("info-circle"), " xCell Results Interpretation:"),
        tags$ul(
          tags$li("Scores are ", tags$strong("enrichment scores"), " (not absolute quantities)"),
          tags$li("Higher scores = higher enrichment of that cell type"),
          tags$li("Compare scores ", tags$strong("between groups"), " for the same cell type"),
          tags$li("Scores are ", tags$strong("NOT comparable between different cell types"))
        )
      ),
      
      "mcp_counter" = div(
        h5(icon("info-circle"), " MCP-counter Results Interpretation:"),
        tags$ul(
          tags$li("Scores are ", tags$strong("absolute abundance scores"), " (arbitrary units)"),
          tags$li("Higher scores = more cells of that type present"),
          tags$li("Limited to ", tags$strong("10 immune cell types"), " and 2 stromal types"),
          tags$li("Best suited for ", tags$strong("immune cell quantification"))
        )
      ),
      
      "epic" = div(
        class = "alert alert-info",
        h5(icon("info-circle"), " EPIC Results Interpretation:"),
        tags$ul(
          tags$li("Values are ", tags$strong("proportions"), " (fractions of total)"),
          tags$li("All cell type proportions sum to ~1.0"),
          tags$li(tags$strong("⚠️ Designed for tumor samples"), " - may be inaccurate for pure immune samples"),
          tags$li("If your experiment uses ", tags$strong("isolated immune cells"), 
                  ", consider using xCell or MCP-counter instead")
        )
      )
    )
    
    return(interpretation)
  })
  
