  # Populate cell type choices
  observe({
    req(network_rv$current_results)
    req(network_rv$current_results$group_comparison)
    
    group_comp <- network_rv$current_results$group_comparison
    
    if (!is.null(group_comp) && "cell_type" %in% colnames(group_comp)) {
      cell_type_choices <- unique(group_comp$cell_type)
      
      updateSelectizeInput(
        session,
        "selected_cell_types_compare",
        choices = cell_type_choices,
        selected = head(cell_type_choices, 5)  # Default to first 5
      )
    }
  })
  
  # DEBUG: Monitor group comparison availability
  observe({
    cat("\n=== GROUP COMPARISON DEBUG ===\n")
    cat("Analysis type:", input$network_analysis_type_systems, "\n")
    cat("Current results exists:", !is.null(network_rv$current_results), "\n")
    
    if (!is.null(network_rv$current_results)) {
      cat("Analysis type in results:", network_rv$current_results$analysis_type, "\n")
      cat("Group comparison exists:", !is.null(network_rv$current_results$group_comparison), "\n")
      
      if (!is.null(network_rv$current_results$group_comparison)) {
        cat("Group comparison rows:", nrow(network_rv$current_results$group_comparison), "\n")
        cat("Significant (p<0.05):", sum(network_rv$current_results$group_comparison$p_value < 0.05), "\n")
      } else {
        cat("WHY NO GROUP COMPARISON?\n")
        cat("  - sample_groups exists:", !is.null(network_rv$current_results$data_info$sample_groups), "\n")
        if (!is.null(network_rv$current_results$data_info$sample_groups)) {
          cat("  - Number of groups:", length(unique(network_rv$current_results$data_info$sample_groups$group)), "\n")
          cat("  - Groups:", paste(unique(network_rv$current_results$data_info$sample_groups$group), collapse = ", "), "\n")
        }
      }
    }
    cat("View mode input:", input$group_comp_view_mode, "\n")
    cat("===============================\n\n")
  })
  
  # Summary statistics
  output$group_comp_summary <- renderUI({
    req(input$network_analysis_type_systems == "deconv")
    req(network_rv$current_results$group_comparison)
    
    group_comp <- network_rv$current_results$group_comparison
    pval_threshold <- input$group_comp_pval_threshold %||% 0.05
    
    total_cell_types <- nrow(group_comp)
    significant_cell_types <- sum(group_comp$p_value < pval_threshold, na.rm = TRUE)
    
    tagList(
      p(
        strong("Total:"), total_cell_types, "cell types",
        style = "margin: 5px 0;"
      ),
      p(
        strong("Significant:"), significant_cell_types, 
        paste0("(p < ", pval_threshold, ")"),
        style = "margin: 5px 0; color: #4caf50; font-weight: 500;"
      )
    )
  })
  
  # Download Bar Plot
  output$download_deconv_barplot <- downloadHandler(
    filename = function() {
      paste0("CellType_Barplot_", Sys.Date(), ".png")
    },
    content = function(file) {
      req(network_rv$current_results)
      
      tryCatch({
        if (!is.null(network_rv$current_results$raw_deconv_results)) {
          
          plot_result <- create_cell_composition_barplot(
            deconv_results = network_rv$current_results$raw_deconv_results,
            method = network_rv$current_results$method,
            sample_groups = network_rv$current_results$data_info$sample_groups
          )
          
          # Get the plotly object
          p <- if (is.list(plot_result) && !is.null(plot_result$plot)) {
            plot_result$plot
          } else {
            plot_result
          }
          
          # Save using orca or kaleido
          if (requireNamespace("plotly", quietly = TRUE)) {
            plotly::save_image(p, file, width = 1200, height = 600, scale = 2)
          }
        }
        
        showNotification("Bar plot downloaded!", type = "message", duration = 3)
        
      }, error = function(e) {
        showNotification(paste("Error downloading plot:", e$message), type = "error")
      })
    }
  )
  
  # Download Heatmap
  output$download_deconv_heatmap <- downloadHandler(
    filename = function() {
      paste0("CellType_Heatmap_", Sys.Date(), ".png")
    },
    content = function(file) {
      req(network_rv$current_results)
      
      tryCatch({
        if (!is.null(network_rv$current_results$raw_deconv_results)) {
          
          p <- create_cell_composition_heatmap(
            deconv_results = network_rv$current_results$raw_deconv_results,
            method = network_rv$current_results$method,
            sample_groups = network_rv$current_results$data_info$sample_groups
          )
          
          if (requireNamespace("plotly", quietly = TRUE)) {
            plotly::save_image(p, file, width = 1000, height = 800, scale = 2)
          }
        }
        
        showNotification("Heatmap downloaded!", type = "message", duration = 3)
        
      }, error = function(e) {
        showNotification(paste("Error downloading heatmap:", e$message), type = "error")
      })
    }
  )
  
  # Download Group Comparison Boxplot
  output$download_deconv_boxplot <- downloadHandler(
    filename = function() {
      paste0("CellType_GroupComparison_", Sys.Date(), ".png")
    },
    content = function(file) {
      req(network_rv$current_results)
      
      tryCatch({
        if (!is.null(network_rv$current_results$group_comparison)) {
          
          # Get current filter settings
          view_mode <- input$group_comp_view_mode %||% "significant"
          pval_threshold <- input$group_comp_pval_threshold %||% 0.05
          
          p <- create_group_comparison_boxplot(
            deconv_results = network_rv$current_results$raw_deconv_results,
            method = network_rv$current_results$method,
            sample_groups = network_rv$current_results$data_info$sample_groups,
            top_n = if (view_mode == "topn") input$top_n_cell_types else 10
          )
          
          if (requireNamespace("plotly", quietly = TRUE)) {
            plotly::save_image(p, file, width = 1200, height = 800, scale = 2)
          }
        }
        
        showNotification("Box plot downloaded!", type = "message", duration = 3)
        
      }, error = function(e) {
        showNotification(paste("Error downloading boxplot:", e$message), type = "error")
      })
    }
  )
  
  # Dynamic plot container with appropriate height
  output$group_comparison_plot_container <- renderUI({
    req(input$network_analysis_type_systems == "deconv")
    req(input$group_comp_view_mode)
    
    # Calculate height based on number of plots and layout
    n_plots <- if (input$group_comp_view_mode == "topn") {
      input$top_n_cell_types %||% 9
    } else if (input$group_comp_view_mode == "custom") {
      length(input$selected_cell_types_compare) %||% 5
    } else {
      # Significant mode
      req(network_rv$current_results$group_comparison)
      pval_threshold <- input$group_comp_pval_threshold %||% 0.05
      sum(network_rv$current_results$group_comparison$p_value < pval_threshold, na.rm = TRUE)
    }
    
    # Calculate height
    layout <- input$boxplot_layout %||% "3"
    
    if (layout == "row") {
      height_px <- 400
    } else {
      cols <- as.numeric(layout)
      rows <- ceiling(n_plots / cols)
      height_px <- max(400, rows * 250)
    }
    
    plotlyOutput("group_comparison_boxplot_filtered", height = paste0(height_px, "px")) %>% 
      withSpinner(color = "#667eea")
  })
  
  # Filtered box plot
  output$group_comparison_boxplot_filtered <- renderPlotly({
    req(network_rv$current_results)
    req(input$network_analysis_type_systems == "deconv")
    req(network_rv$current_results$raw_deconv_results)
    req(network_rv$current_results$group_comparison)
    
    cat("\n=== Rendering Group Comparison Boxplot ===\n")
    
    group_comp <- network_rv$current_results$group_comparison
    deconv_results <- network_rv$current_results$raw_deconv_results
    method <- network_rv$current_results$method
    sample_groups <- network_rv$current_results$data_info$sample_groups
    
    cat("Group comparison rows:", nrow(group_comp), "\n")
    cat("Deconv results class:", class(deconv_results), "\n")
    cat("Method:", method, "\n")
    
    # ✅ CRITICAL: Get actual cell type names from deconv results
    if (method %in% c("xcell", "mcp_counter")) {
      available_cell_types <- rownames(as.matrix(deconv_results))
    } else if (method == "epic") {
      available_cell_types <- rownames(t(as.matrix(deconv_results)))
    }
    
    cat("Available cell types:", length(available_cell_types), "\n")
    cat("First 5:", paste(head(available_cell_types), collapse = ", "), "\n")
    
    # Filter based on view mode
    view_mode <- input$group_comp_view_mode %||% "significant"
    pval_threshold <- input$group_comp_pval_threshold %||% 0.05
    
    cat("View mode:", view_mode, "\n")
    cat("P-value threshold:", pval_threshold, "\n")
    
    if (view_mode == "significant") {
      # Show only significant cell types
      selected_cell_types <- group_comp$cell_type[group_comp$p_value < pval_threshold]
      
      cat("Significant cell types found:", length(selected_cell_types), "\n")
      
      if (length(selected_cell_types) == 0) {
        # No significant - show top 5
        selected_cell_types <- head(group_comp$cell_type[order(group_comp$p_value)], 5)
        cat("No significant, using top 5\n")
      }
      
    } else if (view_mode == "custom") {
      # User-selected
      selected_cell_types <- input$selected_cell_types_compare
      
      if (is.null(selected_cell_types) || length(selected_cell_types) == 0) {
        selected_cell_types <- head(group_comp$cell_type, 5)
        cat("No custom selection, using first 5\n")
      }
      
    } else if (view_mode == "topn") {
      # Top N most different
      top_n <- input$top_n_cell_types %||% 9
      selected_cell_types <- head(group_comp$cell_type[order(group_comp$p_value)], top_n)
      
      cat("Using top", top_n, "cell types\n")
    }
    
    cat("Selected cell types:", paste(selected_cell_types, collapse = ", "), "\n")
    
    # ✅ VALIDATION: Ensure selected cell types exist in deconv results
    # Match selected to available
    matched_cell_types <- selected_cell_types[selected_cell_types %in% available_cell_types]
    
    if (length(matched_cell_types) == 0) {
      # Try case-insensitive matching
      selected_lower <- tolower(selected_cell_types)
      available_lower <- tolower(available_cell_types)
      match_indices <- match(selected_lower, available_lower)
      matched_cell_types <- available_cell_types[match_indices[!is.na(match_indices)]]
    }
    
    if (length(matched_cell_types) == 0) {
      # Last resort: use top 5 from available
      matched_cell_types <- head(available_cell_types, 5)
      showNotification(
        "Selected cell types not found in deconvolution results. Showing top 5 available cell types.",
        type = "warning",
        duration = 5
      )
    }
    
    cat("Final matched cell types:", length(matched_cell_types), "\n")
    cat("Names:", paste(matched_cell_types, collapse = ", "), "\n")
    
    # Create filtered plot
    create_group_comparison_boxplot_filtered(
      deconv_results = deconv_results,
      method = method,
      sample_groups = sample_groups,
      selected_cell_types = matched_cell_types,  # Use matched names
      layout_cols = as.numeric(input$boxplot_layout %||% "3")
    )
  })
  
  
  # Comparison table
  output$group_comparison_table <- DT::renderDataTable({
    req(input$network_analysis_type_systems == "deconv")
    req(network_rv$current_results$group_comparison)
    
    group_comp <- network_rv$current_results$group_comparison
    pval_threshold <- input$group_comp_pval_threshold %||% 0.05
    
    # Format table with CORRECT column names
    # STEP 1: Calculate mean_diff FIRST
    table_display <- group_comp %>%
      mutate(
        # CALCULATE mean_diff since it doesn't exist in the data
        mean_diff = mean_group1 - mean_group2
      ) %>%
      # STEP 2: Now format everything (mean_diff exists now)
      mutate(
        Significance = case_when(
          p_value < 0.001 ~ "***",
          p_value < 0.01 ~ "**",
          p_value < 0.05 ~ "*",
          TRUE ~ "ns"
        ),
        `P-value` = formatC(p_value, format = "e", digits = 2),
        `Mean Diff` = round(mean_diff, 4),
        # Use log2FC if available, otherwise show fold_change with warning for Inf
        `Log2 FC` = if("log2_fold_change" %in% colnames(.)) round(log2_fold_change, 2) else NA,
        `Fold Change` = ifelse(is.infinite(fold_change), 
                               ifelse(fold_change > 0, "Inf (↑)", "Inf (↓)"),
                               round(fold_change, 2)),
        `Cohen's d` = round(cohens_d, 2)
      ) %>%
      # STEP 3: Select and rename columns
      select(
        "Cell Type" = cell_type,
        "Group 1" = group1,
        "Group 2" = group2,
        "Mean (G1)" = mean_group1,
        "Mean (G2)" = mean_group2,
        "Mean Diff",
        "Log2 FC",
        "Fold Change",
        "Cohen's d",
        "P-value",
        "Sig." = Significance
      )
    
    DT::datatable(
      table_display,
      options = list(
        pageLength = 15,
        order = list(list(8, 'asc')),  # Sort by p-value (column index 8)
        columnDefs = list(
          list(className = 'dt-center', targets = 3:9)
        ),
        scrollX = TRUE  # Enable horizontal scrolling for better layout
      ),
      rownames = FALSE
    ) %>%
      formatRound(columns = c("Mean (G1)", "Mean (G2)", "Mean Diff"), digits = 4) %>%
      formatRound(columns = c("Fold Change", "Cohen's d"), digits = 2) %>%
      formatStyle(
        'Sig.',
        backgroundColor = styleEqual(
          c('***', '**', '*', 'ns'),
          c('#d4edda', '#d1ecf1', '#fff3cd', '#ffffff')
        ),
        color = styleEqual(
          c('***', '**', '*', 'ns'),
          c('#155724', '#0c5460', '#856404', '#6c757d')
        ),
        fontWeight = 'bold'
      ) %>%
      formatStyle(
        'Mean Diff',
        color = styleInterval(
          c(0),
          c('#d32f2f', '#388e3c')  # Red for negative, green for positive
        ),
        fontWeight = 'bold'
      )
  })
  
  
