  # Wrapper function for ChEMBL
  query_chembl_drugs <- function(genes, params) {
    print("BRIDGE: Using your existing enhanced_chembl_query function")
    
    results_list <- list()
    
    for(gene in genes) {
      result <- enhanced_chembl_query_fixed(gene)
      if (!is.null(result)) {
        # Standardize ChEMBL results structure
        standardized <- data.frame(
          gene_name = result$gene_name %||% gene,
          molecule_name = result$molecule_name %||% "Unknown",
          molecule_id = result$molecule_id %||% "Unknown",
          target_name = result$target_name %||% "Unknown",
          standard_type = result$standard_type %||% "Unknown",
          standard_value = as.numeric(result$standard_value %||% NA),
          source = "ChEMBL",
          stringsAsFactors = FALSE
        )
        results_list[[length(results_list) + 1]] <- standardized
      }
      Sys.sleep(0.5) # Rate limiting
    }
    
    if (length(results_list) > 0) {
      combined_results <- do.call(rbind, results_list)
      return(combined_results)
    } else {
      return(NULL)
    }
  }
  
  # Wrapper function for OpenTargets
  query_opentargets_drugs <- function(genes, params) {
    print("BRIDGE: Using your existing enhanced_opentargets_query function")
    
    results_list <- list()
    
    for(gene in genes) {
      result <- enhanced_opentargets_query(gene)
      if (!is.null(result)) {
        # Standardize OpenTargets results structure
        standardized <- data.frame(
          gene_name = result$gene_name %||% gene,
          molecule_name = result$drug_name %||% result$molecule_name %||% "Unknown",
          molecule_id = result$drug_id %||% result$molecule_id %||% "Unknown",
          target_name = result$target_name %||% "Unknown",
          standard_type = "Association Score",
          standard_value = as.numeric(result$score %||% result$evidence_score %||% NA),
          source = "OpenTargets",
          stringsAsFactors = FALSE
        )
        results_list[[length(results_list) + 1]] <- standardized
      }
      Sys.sleep(0.5) # Rate limiting
    }
    
    if (length(results_list) > 0) {
      combined_results <- do.call(rbind, results_list)
      return(combined_results)
    } else {
      return(NULL)
    }
  }
  
  create_ultra_simple_network <- function(drug_data, selected_genes) {
    print("=== ULTRA SIMPLE NETWORK CREATION ===")
    
    if (nrow(drug_data) == 0) {
      print("No data, returning empty")
      return(list(
        nodes = data.frame(id = character(0), label = character(0), stringsAsFactors = FALSE),
        edges = data.frame(from = character(0), to = character(0), stringsAsFactors = FALSE)
      ))
    }
    
    print("Creating basic nodes...")
    
    # Ultra simple nodes - just IDs and labels
    genes <- unique(drug_data$gene_name)[1:min(5, length(unique(drug_data$gene_name)))]  # Limit to 5
    drugs <- unique(drug_data$molecule_name)[1:min(5, length(unique(drug_data$molecule_name)))]  # Limit to 5
    
    nodes <- data.frame(
      id = c(genes, drugs),
      label = c(genes, drugs),
      stringsAsFactors = FALSE
    )
    
    print("Creating basic edges...")
    
    # Ultra simple edges - just connections
    sample_edges <- drug_data[1:min(5, nrow(drug_data)), ]  # Limit to 5 edges
    edges <- data.frame(
      from = sample_edges$molecule_name,
      to = sample_edges$gene_name,
      stringsAsFactors = FALSE
    )
    
    print(paste("Created network with", nrow(nodes), "nodes and", nrow(edges), "edges"))
    return(list(nodes = nodes, edges = edges))
  }
  
  # 2. ULTRA SIMPLE PRIORITIZATION FUNCTION (No complex operations)
  create_ultra_simple_prioritization <- function(drug_data, analysis_focus) {
    print("=== ULTRA SIMPLE PRIORITIZATION ===")
    
    if (nrow(drug_data) == 0) {
      print("No data, returning empty prioritization")
      return(data.frame(
        drug_name = character(0),
        n_targets = integer(0),
        priority_score = numeric(0),
        stringsAsFactors = FALSE
      ))
    }
    
    print("Creating basic prioritization...")
    
    # Just count drugs - no complex operations
    simple_priority <- data.frame(
      drug_name = unique(drug_data$molecule_name)[1:min(3, length(unique(drug_data$molecule_name)))],
      n_targets = c(1, 2, 1),  # Fixed values
      priority_score = c(0.8, 0.9, 0.7),  # Fixed values
      stringsAsFactors = FALSE
    )
    
    print(paste("Created", nrow(simple_priority), "priority entries"))
    return(simple_priority)
  }
  
  create_comprehensive_summary_complete_fixed <- function(drug_data, network_data, analysis_focus) {
    
    print("=== CREATING COMPREHENSIVE SUMMARY (FIXED) ===")
    
    tryCatch({
      
      # Safe calculation of basic stats
      total_drugs <- 0
      total_targets <- 0
      total_interactions <- 0
      network_density <- 0
      
      if (!is.null(drug_data) && nrow(drug_data) > 0) {
        total_interactions <- nrow(drug_data)
        
        # Safe unique drug calculation
        if ("molecule_name" %in% colnames(drug_data)) {
          total_drugs <- length(unique(drug_data$molecule_name[!is.na(drug_data$molecule_name)]))
        } else if ("compound_chembl_id" %in% colnames(drug_data)) {
          total_drugs <- length(unique(drug_data$compound_chembl_id[!is.na(drug_data$compound_chembl_id)]))
        }
        
        # Safe unique target calculation
        if ("gene_name" %in% colnames(drug_data)) {
          total_targets <- length(unique(drug_data$gene_name[!is.na(drug_data$gene_name)]))
        }
      }
      
      # Safe network density calculation
      if (!is.null(network_data) && !is.null(network_data$nodes) && !is.null(network_data$edges)) {
        n_nodes <- nrow(network_data$nodes)
        n_edges <- nrow(network_data$edges)
        
        if (n_nodes > 1) {
          max_possible_edges <- n_nodes * (n_nodes - 1) / 2
          network_density <- n_edges / max_possible_edges
        }
      }
      
      # Create base summary
      base_summary <- list(
        analysis_focus = analysis_focus,
        total_drugs = total_drugs,
        total_targets = total_targets,
        total_interactions = total_interactions,
        network = list(
          total_nodes = nrow(network_data$nodes %||% data.frame()),
          total_edges = nrow(network_data$edges %||% data.frame()),
          network_density = network_density
        )
      )
      
      # Add ChEMBL-specific stats if we have drug data
      if (!is.null(drug_data) && nrow(drug_data) > 0) {
        
        # Safe confidence calculation
        high_confidence <- 0
        if ("confidence_score" %in% colnames(drug_data)) {
          conf_scores <- as.numeric(drug_data$confidence_score)
          high_confidence <- sum(conf_scores > 0.7, na.rm = TRUE)
        }
        
        # Safe clinical stage calculation
        clinical_stage_drugs <- 0
        if ("clinical_phase" %in% colnames(drug_data)) {
          clinical_phases <- as.numeric(drug_data$clinical_phase)
          clinical_stage_drugs <- sum(clinical_phases > 0, na.rm = TRUE)
        }
        
        # Safe bioactive calculation
        bioactive_drugs <- 0
        if ("standard_value" %in% colnames(drug_data)) {
          std_values <- as.numeric(drug_data$standard_value)
          bioactive_drugs <- sum(std_values <= 1000, na.rm = TRUE)
        }
        
        base_summary$chembl <- list(
          total_interactions = total_interactions,
          unique_drugs = total_drugs,
          druggable_targets = total_targets,
          high_confidence_interactions = high_confidence,
          clinical_stage_drugs = clinical_stage_drugs,
          bioactive_drugs = bioactive_drugs
        )
        
        # Safe activity type distribution
        if ("standard_type" %in% colnames(drug_data)) {
          activity_types <- drug_data$standard_type[!is.na(drug_data$standard_type)]
          if (length(activity_types) > 0) {
            base_summary$activity_types <- table(activity_types)
          }
        }
        
        # Safe clinical phase distribution
        if ("clinical_phase" %in% colnames(drug_data)) {
          clinical_phases <- drug_data$clinical_phase[!is.na(drug_data$clinical_phase)]
          if (length(clinical_phases) > 0) {
            base_summary$clinical_phases <- table(clinical_phases)
          }
        }
      } else {
        # Empty ChEMBL summary
        base_summary$chembl <- list(
          total_interactions = 0,
          unique_drugs = 0,
          druggable_targets = 0,
          high_confidence_interactions = 0,
          clinical_stage_drugs = 0,
          bioactive_drugs = 0
        )
      }
      
      print("Summary creation completed successfully")
      return(base_summary)
      
    }, error = function(e) {
      print(paste("Error creating summary:", e$message))
      
      # Return minimal safe summary
      return(list(
        analysis_focus = analysis_focus,
        total_drugs = 0,
        total_targets = 0,
        total_interactions = 0,
        network = list(
          total_nodes = 0,
          total_edges = 0,
          network_density = 0
        ),
        chembl = list(
          total_interactions = 0,
          unique_drugs = 0,
          druggable_targets = 0,
          high_confidence_interactions = 0
        )
      ))
    })
  }
  
  
  # Create drug-target network
  create_drug_target_network_complete <- function(drug_data, selected_genes) {
    
    if (nrow(drug_data) == 0) {
      return(list(
        nodes = data.frame(id = character(0), label = character(0),
                           group = character(0), color = character(0),
                           size = numeric(0), title = character(0)),
        edges = data.frame(from = character(0), to = character(0),
                           arrows = character(0), color = character(0),
                           width = numeric(0), title = character(0))
      ))
    }
    
    # Create gene nodes with proper colors
    unique_genes <- unique(drug_data$gene_name)
    gene_nodes <- data.frame(
      id = unique_genes,
      label = unique_genes,
      group = "gene",
      color = case_when(
        unique_genes %in% selected_genes$up_genes ~ "#E74C3C",    # Red for up-regulated
        unique_genes %in% selected_genes$down_genes ~ "#3498DB",  # Blue for down-regulated
        TRUE ~ "#95A5A6"  # Gray for others
      ),
      size = 30,
      title = paste("Target Gene:", unique_genes),
      stringsAsFactors = FALSE
    )
    
    # Create drug nodes
    unique_drugs <- unique(drug_data$molecule_name)
    drug_nodes <- data.frame(
      id = unique_drugs,
      label = gsub("CHEMBL_", "", unique_drugs),  # Shorter labels
      group = "drug",
      color = "#F39C12",  # Orange for drugs
      size = 25,
      title = paste("Drug Compound:", unique_drugs),
      stringsAsFactors = FALSE
    )
    
    # Combine nodes
    all_nodes <- rbind(gene_nodes, drug_nodes)
    
    # Create edges with proper styling
    edges <- drug_data %>%
      dplyr::select(from = molecule_name, to = gene_name, confidence_score) %>%
      dplyr::mutate(
        arrows = "to",
        color = case_when(
          confidence_score >= 0.8 ~ "#27AE60",  # Green for high confidence
          confidence_score >= 0.6 ~ "#F39C12",  # Orange for medium confidence
          TRUE ~ "#95A5A6"  # Gray for low confidence
        ),
        width = pmax(2, confidence_score * 6),  # Width based on confidence
        title = paste0("Drug-Target Interaction<br>",
                       "Confidence: ", round(confidence_score, 3), "<br>",
                       "Strength: ", ifelse(confidence_score >= 0.8, "High",
                                            ifelse(confidence_score >= 0.6, "Medium", "Low")))
      )
    
    return(list(nodes = all_nodes, edges = edges))
  }
  
  # Alternative SIMPLE fix if the above still has issues
  create_drug_target_network_simple_safe <- function(drug_data, selected_genes) {
    
    print("Creating simple safe drug-target network...")
    
    if (nrow(drug_data) == 0) {
      return(list(
        nodes = data.frame(id = character(0), label = character(0), stringsAsFactors = FALSE),
        edges = data.frame(from = character(0), to = character(0), stringsAsFactors = FALSE)
      ))
    }
    
    # Create gene nodes
    unique_genes <- unique(drug_data$gene_name)
    gene_nodes <- data.frame(
      id = unique_genes,
      label = unique_genes,
      group = "gene",
      color = "#3498DB",
      size = 25,
      title = paste("Gene:", unique_genes),
      stringsAsFactors = FALSE
    )
    
    # Create drug nodes
    unique_drugs <- unique(drug_data$molecule_name)
    drug_nodes <- data.frame(
      id = unique_drugs,
      label = unique_drugs,
      group = "drug",
      color = "#F39C12",
      size = 20,
      title = paste("Drug:", unique_drugs),
      stringsAsFactors = FALSE
    )
    
    # Combine nodes
    all_nodes <- rbind(gene_nodes, drug_nodes)
    
    # Create simple edges with minimal formatting
    edges <- drug_data %>%
      select(from = molecule_name, to = gene_name) %>%
      distinct() %>%
      mutate(
        arrows = "to",
        color = "#7F8C8D",
        width = 2,
        title = "Drug-Target Interaction"
      )
    
    print(paste("Simple network created with", nrow(all_nodes), "nodes and", nrow(edges), "edges"))
    
    return(list(nodes = all_nodes, edges = edges))
  }
  
  # Prepare drug interactions table
  prepare_drug_interactions_table_enhanced <- function(drug_data) {
    table_data <- drug_data %>%
      dplyr::select( # Explicit dplyr::select
        Gene = gene_name,
        Drug = molecule_name,
        `ChEMBL ID` = molecule_id,
        `Target ChEMBL ID` = target_chembl_id, # Corrected from `target_name` to `target_chembl_id`
        `Activity Type` = standard_type,
        `Activity Value` = standard_value,
