  # Calculate global network metrics
  create_safe_global_metrics <- function(network_graph) {
    
    tryCatch({
      
      n_nodes <- vcount(network_graph)
      n_edges <- ecount(network_graph)
      
      # Calculate metrics safely
      density_val <- graph.density(network_graph)
      diameter_val <- ifelse(is_connected(network_graph), diameter(network_graph), NA)
      avg_path_length <- mean_distance(network_graph, directed = FALSE)
      clustering_coef <- transitivity(network_graph, type = "global")
      avg_degree <- mean(degree(network_graph))
      
      # Get components
      components <- components(network_graph)
      
      return(list(
        n_nodes = n_nodes,
        n_edges = n_edges,
        density = round(density_val, 4),
        diameter = diameter_val,
        avg_path_length = round(avg_path_length, 2),
        clustering_coefficient = round(clustering_coef, 3),
        avg_degree = round(avg_degree, 2),
        n_components = components$no,
        largest_component_size = max(components$csize)
      ))
      
    }, error = function(e) {
      print(paste("Error calculating global metrics:", e$message))
      return(list(
        n_nodes = vcount(network_graph),
        n_edges = ecount(network_graph),
        density = 0,
        diameter = NA,
        avg_path_length = 0,
        clustering_coefficient = 0,
        avg_degree = 0,
        n_components = 1,
        largest_component_size = vcount(network_graph)
      ))
    })
  }
  
  # Run enrichment analysis
  run_safe_enrichment_analysis <- function(gene_list, organism = "human") {
    
    print("🧬 Running functional enrichment analysis...")
    
    tryCatch({
      
      if (!requireNamespace("enrichR", quietly = TRUE)) {
        print("enrichR package not available")
        return(list())
      }
      
      # Set up enrichR databases based on organism
      dbs <- switch(tolower(organism),
                    "human" = c("GO_Biological_Process_2023", "KEGG_2021_Human", "Reactome_2022"),
                    "mouse" = c("GO_Biological_Process_2023", "KEGG_2019_Mouse", "WikiPathways_2019_Mouse"),
                    c("GO_Biological_Process_2023")  # Default
      )
      
      # Run enrichment
      enriched <- tx_enrichr_local(gene_list, dbs)
      
      # Filter significant results
      significant_results <- list()
      for (db in names(enriched)) {
        if (!is.null(enriched[[db]]) && nrow(enriched[[db]]) > 0) {
          sig_terms <- enriched[[db]][enriched[[db]]$Adjusted.P.value < 0.05, ]
          if (nrow(sig_terms) > 0) {
            significant_results[[db]] <- head(sig_terms, 10)  # Top 10 terms
          }
        }
      }
      
      return(significant_results)
      
    }, error = function(e) {
      print(paste("Error in enrichment analysis:", e$message))
      return(list())
    })
  }
  
  # Create network visualization data
  create_safe_network_visualization_with_modules <- function(gene_interactions, hub_proteins, selected_genes, network_modules = NULL) {
    
    print("🎨 Creating enhanced network visualization with modules...")
    
    tryCatch({
      
      if (is.null(gene_interactions) || nrow(gene_interactions) == 0) {
        return(list(
          nodes = data.frame(id = character(0), label = character(0), stringsAsFactors = FALSE),
          edges = data.frame(from = character(0), to = character(0), stringsAsFactors = FALSE)
        ))
      }
      
      # Get all proteins
      all_proteins <- unique(c(gene_interactions$gene_from, gene_interactions$gene_to))
      
      # Create nodes dataframe
      nodes <- data.frame(
        id = all_proteins,
        label = all_proteins,
        group = "Network",
        stringsAsFactors = FALSE
      )
      
      # Assign regulation groups
      if (!is.null(selected_genes$up_genes)) {
        nodes$group[nodes$id %in% selected_genes$up_genes] <- "Up-regulated"
      }
      if (!is.null(selected_genes$down_genes)) {
        nodes$group[nodes$id %in% selected_genes$down_genes] <- "Down-regulated"
      }
      
      # Calculate degree
      degree_table <- table(c(gene_interactions$gene_from, gene_interactions$gene_to))
      nodes$degree <- as.numeric(degree_table[nodes$id])
      nodes$degree[is.na(nodes$degree)] <- 1
      
      # Set node size based on degree
      nodes$size <- 15 + sqrt(nodes$degree) * 3
      
      # Set colors based on regulation
      nodes$color <- "#95A5A6"  # Default gray
      nodes$color[nodes$group == "Up-regulated"] <- "#E74C3C"    # Red
      nodes$color[nodes$group == "Down-regulated"] <- "#3498DB"  # Blue
      
      # ADD MODULE INFORMATION IF AVAILABLE
      if (!is.null(network_modules) && !is.null(network_modules$membership)) {
        print("🎨 Adding module information to visualization...")
        
        # Add module information to nodes
        module_info <- network_modules$membership
        nodes$module <- NA
        
        for (i in 1:nrow(nodes)) {
          protein_match <- which(module_info$protein == nodes$id[i])
          if (length(protein_match) > 0) {
            nodes$module[i] <- module_info$module[protein_match[1]]
          }
        }
        
        # Create module colors (rainbow palette)
        if (!is.na(max(nodes$module, na.rm = TRUE))) {
          n_modules <- max(nodes$module, na.rm = TRUE)
          module_colors <- rainbow(n_modules, alpha = 0.7)
          
          # Override regulation colors with module colors for border
          nodes$borderWidth <- 3
          nodes$borderColor <- "#FFFFFF"  # Default white border
          
          for (i in 1:nrow(nodes)) {
            if (!is.na(nodes$module[i])) {
              nodes$borderColor[i] <- module_colors[nodes$module[i]]
            }
          }
          
          # Add module info to tooltip
          nodes$title <- sprintf(
            "<b>%s</b><br>Type: %s<br>Degree: %d<br>Module: %s",
            nodes$label,
            nodes$group,
            nodes$degree,
            ifelse(is.na(nodes$module), "None", paste("Module", nodes$module))
          )
        }
      } else {
        # Standard tooltips without module info
        nodes$title <- sprintf(
          "<b>%s</b><br>Type: %s<br>Degree: %d",
          nodes$label,
          nodes$group,
          nodes$degree
        )
      }
      
      # Hub proteins are no longer badged with ⭐ on the label — the marker
      # is reserved for consensus hubs (tooltip + purple ring) so there is
      # no conflict with the "Highlight consensus hubs" toggle. Classical
      # Hub/Major Hub status is still surfaced via the Hub Proteins table
      # (Hub Type column) and via node size (sized by degree).
      
      # Create edges
      edges <- data.frame(
        from = as.character(gene_interactions$gene_from),
        to = as.character(gene_interactions$gene_to),
        stringsAsFactors = FALSE
      )
      
      # Set edge properties
      if ("combined_score" %in% colnames(gene_interactions)) {
        confidence_scores <- gene_interactions$combined_score
        confidence_scores[is.na(confidence_scores)] <- 0.4
        
        edges$width <- pmax(1, confidence_scores * 4)
        edges$color <- ifelse(confidence_scores > 0.7, "#27AE60", "#95A5A6")
        edges$title <- sprintf("Confidence: %.3f", confidence_scores)
      } else {
        edges$width <- 2
        edges$color <- "#95A5A6"
        edges$title <- "Protein Interaction"
      }
      
      print(paste("✅ Enhanced visualization created:", nrow(nodes), "nodes,", nrow(edges), "edges"))
      if (!is.null(network_modules)) {
        print(paste("   With", network_modules$n_modules, "modules detected"))
      }
      
      return(list(
        nodes = nodes,
        edges = edges
      ))
      
    }, error = function(e) {
      print(paste("❌ Enhanced visualization error:", e$message))
      
      # Fallback to basic visualization
      return(list(
        nodes = data.frame(
          id = "error_node",
          label = "Visualization Error",
          color = "#E74C3C",
          size = 30,
          title = paste("Error:", e$message),
          stringsAsFactors = FALSE
        ),
        edges = data.frame()
      ))
    })
  }
  
  # Create mock PPI results for testing
