  # Extract gene IDs from DEG table
  extract_gene_ids <- function(deg_table) {
    if (is.null(deg_table) || nrow(deg_table) == 0) {
      return(character(0))
    }
    
    organism <- isolate(input$organism_deg_main %||% "human")
    
    # Try different possible columns for gene IDs
    gene_ids <- NULL
    if ("gene_symbol" %in% colnames(deg_table)) {
      gene_ids <- deg_table$gene_symbol
    } else if ("gene_id" %in% colnames(deg_table)) {
      gene_ids <- deg_table$gene_id
    } else if ("Gene" %in% colnames(deg_table)) {
      gene_ids <- deg_table$Gene
    } else {
      gene_ids <- rownames(deg_table)
    }
    
    # Clean the IDs
    gene_ids <- as.character(gene_ids)
    gene_ids <- gsub("\\.\\d+$", "", gene_ids)  # Remove version numbers
    
    print(paste("Raw gene IDs (first 10):", paste(head(gene_ids, 10), collapse = ", ")))
    
    # Check what type of IDs we have
    ensembl_pattern <- "^ENS[A-Z]*(G|T)[0-9]+"
    is_ensembl <- grepl(ensembl_pattern, gene_ids)
    
    if (sum(is_ensembl) > length(gene_ids) * 0.5) {
      print(paste("Detected", sum(is_ensembl), "Ensembl IDs out of", length(gene_ids), "- converting to symbols"))
      
      # Convert Ensembl IDs to gene symbols
      converted_symbols <- convert_ensembl_to_symbols_safe(gene_ids, organism)
      
      # Use converted symbols where available, keep original otherwise
      gene_ids <- ifelse(!is.na(converted_symbols) & nchar(converted_symbols) > 0,
                         converted_symbols, gene_ids)
      
      # Remove any remaining Ensembl IDs that couldn't be converted
      gene_ids <- gene_ids[!grepl(ensembl_pattern, gene_ids)]
    }
    
    # Remove non-coding RNAs
    non_coding_pattern <- "^LINC|^MIR|^SNOR|^RNA[0-9]|^RNU|^SNHG|^LOC[0-9]"
    gene_ids <- gene_ids[!grepl(non_coding_pattern, gene_ids)]
    
    # Remove empty and NA
    gene_ids <- gene_ids[!is.na(gene_ids) & nchar(gene_ids) > 0]
    
    print(paste("Final gene symbols (first 10):", paste(head(gene_ids, 10), collapse = ", ")))
    
    return(unique(gene_ids))
  }
  
  # Convert Ensembl IDs to gene symbols
  convert_ensembl_to_symbols_safe <- function(ensembl_ids, organism = "human") {
    
    org_db_map <- list(
      human = "org.Hs.eg.db",
      mouse = "org.Mm.eg.db",
      rat = "org.Rn.eg.db",
      fly = "org.Dm.eg.db",
      zebrafish = "org.Dr.eg.db",
      yeast = "org.Sc.sgd.db"
    )
    
    org_db_name <- org_db_map[[tolower(organism)]]
    
    if (is.null(org_db_name)) {
      print(paste("No annotation database for organism:", organism))
      return(rep(NA, length(ensembl_ids)))
    }
    
    if (!requireNamespace(org_db_name, quietly = TRUE)) {
      print(paste("Annotation package", org_db_name, "not installed"))
      return(rep(NA, length(ensembl_ids)))
    }
    
    tryCatch({
      library(org_db_name, character.only = TRUE)
      db_obj <- get(org_db_name)
      
      clean_ids <- gsub("\\..*$", "", ensembl_ids)
      
      # Check if we have transcript IDs (ENST) and convert to gene IDs (ENSG) first
      is_transcript <- grepl("^ENS[A-Z]*T[0-9]+", clean_ids)
      
      if (sum(is_transcript) > 0) {
        print(paste("Converting", sum(is_transcript), "transcript IDs (ENST) to gene IDs (ENSG)..."))
        
        # Try to convert transcripts to genes using biomaRt
        if (requireNamespace("biomaRt", quietly = TRUE)) {
          tryCatch({
            ensembl <- biomaRt::useEnsembl(biomart = "genes", dataset = paste0(
              switch(tolower(organism),
                     "human" = "hsapiens",
                     "mouse" = "mmusculus",
                     "rat" = "rnorvegicus",
                     "fly" = "dmelanogaster",
                     "zebrafish" = "drerio",
                     "yeast" = "scerevisiae",
                     "hsapiens"), "_gene_ensembl"))
            
            transcript_mapping <- biomaRt::getBM(
              attributes = c("ensembl_transcript_id", "ensembl_gene_id"),
              filters = "ensembl_transcript_id",
              values = clean_ids[is_transcript],
              mart = ensembl
            )
            
            # Replace transcript IDs with gene IDs
            for (i in which(is_transcript)) {
              match_idx <- which(transcript_mapping$ensembl_transcript_id == clean_ids[i])
              if (length(match_idx) > 0) {
                clean_ids[i] <- transcript_mapping$ensembl_gene_id[match_idx[1]]
              }
            }
            
            print(paste("✅ Converted", nrow(transcript_mapping), "transcripts to genes"))
          }, error = function(e) {
            print(paste("⚠️ biomaRt conversion failed:", e$message, "- using original IDs"))
          })
        }
      }
      
      # Now convert gene IDs to symbols
      symbols <- AnnotationDbi::mapIds(
        db_obj,
        keys = clean_ids,
        column = "SYMBOL",
        keytype = "ENSEMBL",
        multiVals = "first"
      )
      
      print(paste("Converted", sum(!is.na(symbols)), "out of", length(ensembl_ids), "Ensembl IDs"))
      
      return(symbols)
      
    }, error = function(e) {
      print(paste("Error converting Ensembl IDs:", e$message))
      return(rep(NA, length(ensembl_ids)))
    })
  }
  
  # Create gene interactions from STRING data
  create_safe_gene_interactions <- function(interactions, mapped_genes) {

    tryCatch({

      # Check if interactions already have gene symbols (from local STRING query)
      # or STRING IDs that need mapping (from STRINGdb package)
      has_string_ids <- any(grepl("^\\d+\\.ENSP", interactions$from, perl = TRUE))

      if (has_string_ids && !is.null(mapped_genes$STRING_id) && any(!is.na(mapped_genes$STRING_id))) {
        # STRING IDs need mapping to gene symbols
        string_to_gene <- setNames(mapped_genes$gene, mapped_genes$STRING_id)
        gene_interactions <- data.frame(
          gene_from = string_to_gene[interactions$from],
          gene_to = string_to_gene[interactions$to],
          combined_score = interactions$combined_score / 1000,
          stringsAsFactors = FALSE
        )
      } else {
        # Already gene symbols (from query_string_database_safe / local data)
        score_divisor <- if (max(interactions$combined_score, na.rm = TRUE) > 1) 1000 else 1
        gene_interactions <- data.frame(
          gene_from = interactions$from,
          gene_to = interactions$to,
          combined_score = interactions$combined_score / score_divisor,
          stringsAsFactors = FALSE
        )
      }

      # Remove rows with missing gene symbols
      gene_interactions <- gene_interactions[
        !is.na(gene_interactions$gene_from) &
          !is.na(gene_interactions$gene_to) &
          gene_interactions$gene_from != gene_interactions$gene_to,
      ]

      gene_interactions$gene_from <- as.character(gene_interactions$gene_from)
      gene_interactions$gene_to <- as.character(gene_interactions$gene_to)
      gene_interactions$combined_score <- as.numeric(gene_interactions$combined_score)

      # Remove duplicates — use a canonical unordered-pair key so that
      # (A,B) and (B,A) collapse to one row for undirected PPI edges.
      pair_key <- apply(gene_interactions[, c("gene_from", "gene_to")], 1,
                        function(r) paste(sort(r), collapse = "|"))
      # Keep the highest-score row per canonical pair
      ord <- order(pair_key, -gene_interactions$combined_score)
      gene_interactions <- gene_interactions[ord, , drop = FALSE]
      gene_interactions <- gene_interactions[!duplicated(pair_key[ord]), , drop = FALSE]
      rownames(gene_interactions) <- NULL

      return(gene_interactions)

    }, error = function(e) {
      print(paste("Error creating gene interactions:", e$message))
      return(data.frame(
        gene_from = character(0),
        gene_to = character(0),
        combined_score = numeric(0),
        stringsAsFactors = FALSE
      ))
    })
  }
  
