  assign_ppi_results_clean <- function(ppi_results) {
    print("📦 Storing PPI results...")
    
    # Ensure analysis_type is set
    ppi_results$analysis_type <- "ppi"
    
    # Store results in reactive values
    isolate({
      network_rv$current_results <- ppi_results
      network_rv$analysis_status <- "complete"
      network_rv$analysis_type <- "ppi"
      
      # Also store backup copy
      network_rv$ppi_results <- ppi_results
    })
    
    print("✅ PPI results stored successfully")
    return(TRUE)
  }
  
  
