  # FIXED: Create safe hub analysis
  create_safe_hub_analysis <- function(network_graph, all_genes, up_genes, down_genes) {
    
    tryCatch({
      
      # Calculate centrality measures safely with igraph:: prefix
      node_degrees <- igraph::degree(network_graph, mode = "all")
      node_betweenness <- igraph::betweenness(network_graph, normalized = TRUE)
      node_closeness <- igraph::closeness(network_graph, normalized = TRUE)
      node_eigenvector <- igraph::eigen_centrality(network_graph)$vector
      
      # Create hub proteins data frame
      hub_proteins <- data.frame(
        gene = names(node_degrees),
        degree = as.numeric(node_degrees),
        betweenness = as.numeric(node_betweenness),
        closeness = as.numeric(node_closeness),
        eigenvector = as.numeric(node_eigenvector),
        stringsAsFactors = FALSE
      )
      
      # Handle NA values safely
      hub_proteins$degree[is.na(hub_proteins$degree)] <- 0
      hub_proteins$betweenness[is.na(hub_proteins$betweenness)] <- 0
      hub_proteins$closeness[is.na(hub_proteins$closeness)] <- 0
      hub_proteins$eigenvector[is.na(hub_proteins$eigenvector)] <- 0
      
      # Calculate composite hub score safely
      if (nrow(hub_proteins) > 1) {
        hub_proteins$hub_score <- scale(hub_proteins$degree)[,1] +
          scale(hub_proteins$betweenness)[,1] +
          scale(hub_proteins$eigenvector)[,1]
      } else {
        hub_proteins$hub_score <- 0
      }
      
      hub_proteins$hub_score[is.na(hub_proteins$hub_score)] <- 0
      
      # Classify hub types
      if (nrow(hub_proteins) > 0) {
        degree_q90 <- quantile(hub_proteins$degree, 0.9, na.rm = TRUE)
        degree_q75 <- quantile(hub_proteins$degree, 0.75, na.rm = TRUE)
        degree_q50 <- quantile(hub_proteins$degree, 0.5, na.rm = TRUE)
        
        hub_proteins$hub_type <- ifelse(
          hub_proteins$degree >= degree_q90, "Major Hub",
          ifelse(hub_proteins$degree >= degree_q75, "Hub",
                 ifelse(hub_proteins$degree >= degree_q50, "Connector", "Peripheral"))
        )
      } else {
        hub_proteins$hub_type <- character(0)
      }
      
      # Add gene source and regulation information
      hub_proteins$gene_source <- ifelse(hub_proteins$gene %in% all_genes, "Input DEG", "Network neighbor")
      
      hub_proteins$regulation <- ifelse(
        hub_proteins$gene %in% up_genes, "Up",
        ifelse(hub_proteins$gene %in% down_genes, "Down", "Unknown")
      )
      
      # Sort by hub score
      hub_proteins <- hub_proteins[order(hub_proteins$hub_score, decreasing = TRUE), ]
      
      return(hub_proteins)
      
    }, error = function(e) {
      print(paste("Error in hub analysis:", e$message))
      return(data.frame(
        gene = character(0),
        degree = numeric(0),
        hub_type = character(0),
        gene_source = character(0),
        regulation = character(0),
        stringsAsFactors = FALSE
      ))
    })
  }
  
  # FIXED: Create safe global network metrics
  create_safe_global_metrics <- function(network_graph) {
    
    tryCatch({
      
      n_nodes <- vcount(network_graph)
      n_edges <- ecount(network_graph)
      
      # Calculate metrics safely
      density <- if (n_nodes > 1) edge_density(network_graph) else 0
      clustering_coeff <- if (n_nodes > 2) transitivity(network_graph, type = "global") else 0
      avg_degree <- if (n_nodes > 0) mean(igraph::degree(network_graph, mode = "all")) else 0
      
      # More robust path calculations
      diameter <- tryCatch({
        if (n_nodes > 1 && is_connected(network_graph)) {
          diameter(network_graph, directed = FALSE)
        } else {
          0
        }
      }, error = function(e) 0)
      
      avg_path_length <- tryCatch({
        if (n_nodes > 1 && is_connected(network_graph)) {
          mean_distance(network_graph, directed = FALSE)
        } else {
          0
        }
      }, error = function(e) 0)
      
      return(list(
        n_nodes = n_nodes,
        n_edges = n_edges,
        density = density,
        clustering_coefficient = clustering_coeff,
        avg_degree = avg_degree,
        diameter = diameter,
        avg_path_length = avg_path_length
      ))
      
    }, error = function(e) {
      print(paste("Error calculating global metrics:", e$message))
      return(list(
        n_nodes = 0,
        n_edges = 0,
        density = 0,
        clustering_coefficient = 0,
        avg_degree = 0,
        diameter = 0,
        avg_path_length = 0
      ))
    })
  }
  
  # FIXED: Safe enrichment analysis
  run_safe_enrichment_analysis <- function(all_network_proteins, organism_param) {
    
    tryCatch({
      
      print("🧬 Running functional enrichment analysis...")
      
      databases <- if (organism_param == "human") {
        c("GO_Biological_Process_2023", "KEGG_2021_Human", "Reactome_2022")
      } else {
        c("GO_Biological_Process_2021", "KEGG_2019")
      }
      
      enrichment_results <- tx_enrichr_local(all_network_proteins, databases)
      
      functional_enrichment <- list()
      for (db in names(enrichment_results)) {
        result <- enrichment_results[[db]]
        if (nrow(result) > 0) {
          significant <- result %>%
            dplyr::filter(Adjusted.P.value < 0.05) %>%
            dplyr::arrange(Adjusted.P.value) %>%
            dplyr::slice_head(n = 20) %>%
            dplyr::mutate(
              Gene_Count = sapply(strsplit(Genes, ";"), length),
              Database = db
            )
          
          if (nrow(significant) > 0) {
            functional_enrichment[[db]] <- significant
          }
        }
      }
      
      return(functional_enrichment)
      
    }, error = function(e) {
      print(paste("Enrichment analysis failed:", e$message))
      return(list())
    })
  }
  
  # FIXED: Create safe network visualization
  create_safe_network_visualization <- function(gene_interactions, hub_proteins, selected_genes) {
    
    tryCatch({
      
      print("🎨 Creating safe network visualization...")
      
      # Get all unique proteins
      all_proteins <- unique(c(gene_interactions$gene_from, gene_interactions$gene_to))
      
      if (length(all_proteins) == 0) {
        return(list(
          nodes = data.frame(
            id = "no_data", label = "No data", color = "#95A5A6", size = 30,
            title = "No interactions found", stringsAsFactors = FALSE
          ),
          edges = data.frame()
        ))
      }
      
      # Create nodes data frame
      nodes <- data.frame(
        id = all_proteins,
        label = all_proteins,
        stringsAsFactors = FALSE
      )
      
      # Assign groups safely
      nodes$group <- "Network"
      if (!is.null(selected_genes$up_genes) && length(selected_genes$up_genes) > 0) {
        nodes$group[nodes$id %in% selected_genes$up_genes] <- "Up-regulated"
      }
      if (!is.null(selected_genes$down_genes) && length(selected_genes$down_genes) > 0) {
        nodes$group[nodes$id %in% selected_genes$down_genes] <- "Down-regulated"
      }
      
      # Calculate degree safely
      degree_table <- table(c(gene_interactions$gene_from, gene_interactions$gene_to))
      nodes$degree <- 1  # Default degree
      for (i in 1:nrow(nodes)) {
        protein_id <- nodes$id[i]
        if (protein_id %in% names(degree_table)) {
          nodes$degree[i] <- as.numeric(degree_table[protein_id])
        }
      }
      
      # Set visual properties safely
      nodes$size <- 15 + sqrt(nodes$degree) * 3
      
      # FIXED: Color assignment without list() issues
      nodes$color <- "#95A5A6"  # Default gray
      nodes$color[nodes$group == "Up-regulated"] <- "#E74C3C"    # Red
      nodes$color[nodes$group == "Down-regulated"] <- "#3498DB"  # Blue
      
      # Add hub enhancements safely
      if (!is.null(hub_proteins) && nrow(hub_proteins) > 0) {
        hub_mask <- nodes$id %in% hub_proteins$gene
        if (sum(hub_mask) > 0) {
          nodes$size[hub_mask] <- nodes$size[hub_mask] + 10
          nodes$borderWidth <- ifelse(hub_mask, 3, 1)
          nodes$borderColor <- ifelse(hub_mask, "#8E44AD", "#FFFFFF")
          # Add star to hub labels safely
          nodes$label[hub_mask] <- sprintf("★ %s", nodes$label[hub_mask])
        }
      }
      
      # FIXED: Create tooltips safely using sprintf
      nodes$title <- sprintf(
        "<b>%s</b><br>Type: %s<br>Degree: %d",
        nodes$label,
        nodes$group,
        nodes$degree
      )
      
      # FIXED: Create edges data frame safely
      edges <- data.frame(
        from = as.character(gene_interactions$gene_from),
        to = as.character(gene_interactions$gene_to),
        stringsAsFactors = FALSE
      )
      
      # FIXED: Set edge properties without list() issues
      confidence_scores <- gene_interactions$combined_score
      confidence_scores[is.na(confidence_scores)] <- 0.4  # Default value
      
      edges$width <- pmax(1, confidence_scores * 4)
      # FIXED: Simple color assignment instead of list
      edges$color <- ifelse(confidence_scores > 0.7, "#27AE60", "#95A5A6")
      
      # FIXED: Safe edge tooltips
      edges$title <- sprintf("Confidence: %.3f", confidence_scores)
      
      print(paste("✅ Created visualization with", nrow(nodes), "nodes and", nrow(edges), "edges"))
      
      return(list(
        nodes = nodes,
        edges = edges
      ))
      
    }, error = function(e) {
      print(paste("❌ Visualization error:", e$message))
      
      # Return error visualization
      return(list(
        nodes = data.frame(
          id = "error_node",
          label = "Visualization Error",
          color = "#E74C3C",
          size = 30,
          title = sprintf("Error: %s", e$message),
          stringsAsFactors = FALSE
        ),
        edges = data.frame()
      ))
    })
  }
  
  
  finalize_ppi_results_safe <- function(gene_interactions, hub_proteins, global_metrics,
                                        selected_genes, functional_enrichment = list(),
                                        analysis_params = list()) {
    
    print("📦 Finalizing PPI results safely...")
    
    tryCatch({
      
      # Validate inputs first
      if (is.null(gene_interactions) || nrow(gene_interactions) == 0) {
        return(list(
          error = "No gene interactions data available",
          analysis_type = "ppi"  # <-- CRITICAL: Set even in error case
        ))
      }
      
      # Create network visualization
      network_viz <- create_safe_network_visualization(gene_interactions, selected_genes, hub_proteins)
      
      # Calculate comprehensive summary stats
      all_network_proteins <- unique(c(gene_interactions$gene_from, gene_interactions$gene_to))
      
      # FIXED: Create proper summary stats structure
      summary_stats <- list(
        basic_stats = list(
          total_proteins = length(all_network_proteins),
          total_interactions = nrow(gene_interactions),
          input_genes = selected_genes$n_total %||% 0,
          mapped_genes = length(intersect(selected_genes$all_genes %||% character(0), all_network_proteins)),
          coverage_rate = if(length(selected_genes$all_genes %||% character(0)) > 0) {
            round(length(intersect(selected_genes$all_genes, all_network_proteins)) / length(selected_genes$all_genes) * 100, 1)
          } else { 0 }
        ),
        hub_stats = list(
          total_hubs = if(nrow(hub_proteins) > 0) sum(hub_proteins$hub_type %in% c("Major Hub", "Hub"), na.rm = TRUE) else 0,
          major_hubs = if(nrow(hub_proteins) > 0) sum(hub_proteins$hub_type == "Major Hub", na.rm = TRUE) else 0,
          input_hubs = if(nrow(hub_proteins) > 0) sum(hub_proteins$gene_source == "Input DEG" & hub_proteins$hub_type %in% c("Major Hub", "Hub"), na.rm = TRUE) else 0
        ),
        topology_stats = global_metrics,
        # CRITICAL: Add the n_edges field that the UI checks for
        n_edges = nrow(gene_interactions)
      )
      
      # FIXED: Structure final results with EXPLICIT analysis_type
      final_results <- list(
        # Core network data for visualization
        network_data = network_viz,
        
        # Complete analysis results
        ppi_interactions = gene_interactions,
        hub_proteins = hub_proteins,
        
        # Network analysis
        network_metrics = list(
          global_metrics = global_metrics,
          node_metrics = hub_proteins
        ),
        
        # Comprehensive statistics
        summary_stats = summary_stats,
        
        # Functional analysis
        functional_enrichment = functional_enrichment,
        
        # Analysis metadata
        analysis_params = analysis_params,
        
        # Gene information
        selected_genes = selected_genes,
        
        # CRITICAL: EXPLICITLY SET ANALYSIS TYPE
        analysis_type = "ppi"
      )
      
      print("✅ PPI results finalized successfully")
      # CRITICAL: Verify analysis_type is set
      print(paste("🎯 ANALYSIS TYPE SET TO:", final_results$analysis_type))
      
      return(final_results)
      
    }, error = function(e) {
      print(paste("❌ Error finalizing PPI results:", e$message))
      return(list(
        error = paste("Finalization failed:", e$message),
        analysis_type = "ppi"  # <-- CRITICAL: Set even in error case
      ))
    })
  }
  
  
  # Create comprehensive summary statistics
  create_comprehensive_summary_stats <- function(gene_interactions, hub_proteins, global_metrics,
                                                 selected_genes, all_network_proteins) {
    
    tryCatch({
      
      # Basic statistics
      basic_stats <- list(
        total_proteins = length(all_network_proteins),
        total_interactions = nrow(gene_interactions),
        input_genes = selected_genes$n_total,
        mapped_genes = length(intersect(selected_genes$all_genes, all_network_proteins)),
        coverage_rate = round(length(intersect(selected_genes$all_genes, all_network_proteins)) / selected_genes$n_total * 100, 1)
      )
      
      # Hub statistics
      hub_stats <- list(
        total_hubs = sum(hub_proteins$hub_type %in% c("Major Hub", "Hub"), na.rm = TRUE),
        major_hubs = sum(hub_proteins$hub_type == "Major Hub", na.rm = TRUE),
        input_hubs = sum(hub_proteins$gene_source == "Input DEG" &
                           hub_proteins$hub_type %in% c("Major Hub", "Hub"), na.rm = TRUE),
        up_hubs = sum(hub_proteins$regulation == "Up" &
                        hub_proteins$hub_type %in% c("Major Hub", "Hub"), na.rm = TRUE),
        down_hubs = sum(hub_proteins$regulation == "Down" &
                          hub_proteins$hub_type %in% c("Major Hub", "Hub"), na.rm = TRUE)
      )
      
      return(list(
        basic_stats = basic_stats,
        hub_stats = hub_stats,
        topology_stats = global_metrics
      ))
      
    }, error = function(e) {
      print(paste("Error creating summary stats:", e$message))
      return(list(
        basic_stats = list(total_proteins = 0, total_interactions = 0),
        hub_stats = list(total_hubs = 0),
        topology_stats = list(n_nodes = 0, n_edges = 0)
      ))
    })
  }
  
