  # Display completion summary
  display_ppi_completion_summary <- function(ppi_results) {
    
    tryCatch({
      
      basic_stats <- ppi_results$summary_stats$basic_stats %||% ppi_results$summary_stats
      hub_stats <- ppi_results$summary_stats$hub_stats %||% list(total_hubs = 0)
      
      interactions_count <- basic_stats$total_interactions %||% basic_stats$n_edges %||% 0
      nodes_count <- basic_stats$total_proteins %||% basic_stats$n_nodes %||% 0
      hub_count <- hub_stats$total_hubs %||% 0
      mapping_rate <- round((ppi_results$analysis_params$mapping_rate %||% 0) * 100, 1)
      enrichment_count <- length(ppi_results$functional_enrichment %||% list())
      
      print("=== PPI ANALYSIS COMPLETE ===")
      print(paste("✓ Input genes:", ppi_results$selected_genes$n_total))
      print(paste("✓ Mapped to STRING:", mapping_rate, "%"))
      print(paste("✓ Network nodes:", nodes_count))
      print(paste("✓ Interactions:", interactions_count))
      print(paste("✓ Hub proteins:", hub_count))
      print(paste("✓ Enriched pathways:", enrichment_count))
      print("===============================")
      
      showNotification(
        HTML(sprintf(
          "<strong>🧬 Complete PPI Analysis Finished!</strong><br>
        <table style='margin-top: 8px; font-size: 0.9em; line-height: 1.4;'>
        <tr><td style='padding-right: 15px;'>Input genes:</td><td><b>%d</b></td></tr>
        <tr><td style='padding-right: 15px;'>Mapped to STRING:</td><td><b>%s%%</b></td></tr>
        <tr><td style='padding-right: 15px;'>Network proteins:</td><td><b>%d</b></td></tr>
        <tr><td style='padding-right: 15px;'>Interactions found:</td><td><b>%d</b></td></tr>
        <tr><td style='padding-right: 15px;'>Hub proteins:</td><td><b>%d</b></td></tr>
        %s
        </table>
        <div style='margin-top: 8px; font-size: 0.85em; color: #666;'>
        ✅ Network visualization, hub analysis, and functional enrichment complete!
        </div>",
          ppi_results$selected_genes$n_total,
          mapping_rate,
          nodes_count,
          interactions_count,
          hub_count,
          if (enrichment_count > 0) sprintf(
            "<tr><td style='padding-right: 15px;'>Enriched pathways:</td><td><b>%d databases</b></td></tr>",
            enrichment_count
          ) else ""
        )),
        type = "message",
        duration = 10
      )
      
    }, error = function(e) {
      print(paste("Error displaying summary:", e$message))
      showNotification("PPI Analysis completed successfully!", type = "message", duration = 5)
    })
  }
  
  # Handle PPI analysis errors
