    print("=== PPI ANALYSIS ERROR ===")
    print(paste("Error:", e$message))
    print("Full error traceback:")
    print(traceback())
    
    isolate({
      network_rv$current_results <- list(
        error = paste("Analysis failed:", e$message),
        analysis_type = "ppi"
      )
      network_rv$analysis_status <- "error"
      network_rv$available <- FALSE
    })
    
    showNotification(
      HTML(sprintf(
        "<strong>❌ PPI Analysis Failed</strong><br>
      <div style='margin-top: 5px; font-size: 0.9em;'>
      Error: %s<br>
      Please check the console for detailed error information.
      </div>",
        e$message
      )),
      type = "error",
      duration = 15
    )
  }
  
