  fix_grn_network_data <- function(network_data, selected_genes) {
    
    print("🔧 Fixing GRN network data structure...")
    print(paste("🔍 DEBUG: Input selected_genes structure:"))
    if (!is.null(selected_genes)) {
      print(paste("  • up_genes length:", length(selected_genes$up_genes %||% c())))
      print(paste("  • down_genes length:", length(selected_genes$down_genes %||% c())))
      print(paste("  • up_genes sample:", paste(head(selected_genes$up_genes %||% c(), 3), collapse = ", ")))
      print(paste("  • down_genes sample:", paste(head(selected_genes$down_genes %||% c(), 3), collapse = ", ")))
    } else {
      print("  • selected_genes is NULL")
    }
    
    if (is.null(network_data) || is.null(network_data$nodes)) {
      return(network_data)
    }
    
    nodes <- network_data$nodes
    edges <- network_data$edges
    
    print(paste("🔍 DEBUG: Node sample before fixing:"))
    print(head(nodes[, c("id", "type", "regulation")]))
    
    # Fix nodes: Add proper group column and colors
    if (!"group" %in% colnames(nodes)) {
      print("🔧 Adding group column to nodes...")
      
      # CRITICAL FIX: Create group column based on type FIRST
      nodes$group <- case_when(
        nodes$type == "TF" ~ "tf",
        TRUE ~ "target"
      )
      
      # Count TFs first
      n_tfs_initial <- sum(nodes$group == "tf")
      print(paste("🔧 Initial TF count:", n_tfs_initial))
      
      # Now update non-TF nodes based on regulation column
      if ("regulation" %in% colnames(nodes)) {
        print("🔧 Using regulation column for up/down assignment...")
        
        # Only update non-TF nodes
        non_tf_mask <- nodes$group != "tf"
        
        # Update groups based on regulation column for non-TFs only
        up_mask <- non_tf_mask & (nodes$regulation == "Up")
        down_mask <- non_tf_mask & (nodes$regulation == "Down")
        
        nodes$group[up_mask] <- "upregulated"
        nodes$group[down_mask] <- "downregulated"
        
        print(paste("🔧 From regulation column - Assigned", sum(up_mask), "upregulated and", sum(down_mask), "downregulated nodes"))
      }
      
      # FALLBACK: Update groups based on selected_genes if available (for non-TFs only)
      if (!is.null(selected_genes)) {
        up_genes <- selected_genes$up_genes %||% c()
        down_genes <- selected_genes$down_genes %||% c()
        
        if (length(up_genes) > 0) {
          # Only update non-TF, non-already-classified nodes
          available_mask <- nodes$group == "target"
          up_mask_exact <- available_mask & (nodes$id %in% up_genes)
          nodes$group[up_mask_exact] <- "upregulated"
          
          if (sum(up_mask_exact) == 0) {
            nodes_clean <- gsub("\\..*$", "", nodes$id)
            up_genes_clean <- gsub("\\..*$", "", up_genes)
            up_mask_partial <- available_mask & (nodes_clean %in% up_genes_clean)
            nodes$group[up_mask_partial] <- "upregulated"
            print(paste("🔧 From selected_genes (partial match) - Assigned", sum(up_mask_partial), "upregulated nodes"))
          } else {
            print(paste("🔧 From selected_genes (exact match) - Assigned", sum(up_mask_exact), "upregulated nodes"))
          }
        }
        
        if (length(down_genes) > 0) {
          available_mask <- nodes$group == "target"
          down_mask_exact <- available_mask & (nodes$id %in% down_genes)
          nodes$group[down_mask_exact] <- "downregulated"
          
          if (sum(down_mask_exact) == 0) {
            nodes_clean <- gsub("\\..*$", "", nodes$id)
            down_genes_clean <- gsub("\\..*$", "", down_genes)
            down_mask_partial <- available_mask & (nodes_clean %in% down_genes_clean)
            nodes$group[down_mask_partial] <- "downregulated"
            print(paste("🔧 From selected_genes (partial match) - Assigned", sum(down_mask_partial), "downregulated nodes"))
          } else {
            print(paste("🔧 From selected_genes (exact match) - Assigned", sum(down_mask_exact), "downregulated nodes"))
          }
        }
      }
      
      # Do NOT set inline color.background / color.border / shape here.
      # The renderer's visGroups definitions handle all styling so the
      # auto-generated legend stays in sync with the actual node colors.

      nodes$size <- ifelse(nodes$group == "tf", 35, 25)

      # Add titles (hover tooltips)
      nodes$title <- case_when(
        nodes$group == "tf" ~ paste("Transcription Factor:", nodes$id),
        nodes$group == "upregulated" ~ paste("Upregulated Gene:", nodes$id),
        nodes$group == "downregulated" ~ paste("Downregulated Gene:", nodes$id),
        TRUE ~ paste("Target Gene:", nodes$id)
      )
      
      print(paste("🔧 Final node groups:", paste(names(table(nodes$group)), "=", table(nodes$group), collapse = ", ")))
    }
    
    # Fix edges: Add proper visual properties with better regulation detection
    if (!is.null(edges) && nrow(edges) > 0) {
      print("🔧 Fixing edge properties...")
      
      # IMPROVED: Try to infer regulation type from multiple sources
      regulation_type <- rep("Activation", nrow(edges))
      
      # Method 1: Check interaction_type column
      if ("interaction_type" %in% colnames(edges)) {
        repression_keywords <- c("repress", "inhibit", "negative", "down", "suppress", "block")
        repression_mask <- grepl(paste(repression_keywords, collapse = "|"), edges$interaction_type, ignore.case = TRUE)
        regulation_type[repression_mask] <- "Repression"
        print(paste("🔧 Found", sum(repression_mask), "repressions from interaction_type"))
      }
      
      # Method 2: Check if confidence is in a specific range that might indicate repression
      if ("confidence" %in% colnames(edges)) {
        # Some databases use negative confidence or specific ranges for repression
        negative_conf_mask <- edges$confidence < 0
        if (any(negative_conf_mask)) {
          regulation_type[negative_conf_mask] <- "Repression"
          edges$confidence[negative_conf_mask] <- abs(edges$confidence[negative_conf_mask])
          print(paste("🔧 Found", sum(negative_conf_mask), "repressions from negative confidence"))
        }
      }
      
      # If no repressions detected from data, check the mor column from DoRothEA
      if (sum(regulation_type == "Repression") == 0 && "mor" %in% colnames(edges)) {
        repression_mask <- !is.na(edges$mor) & edges$mor < 0
        regulation_type[repression_mask] <- "Repression"
        print(paste("🔧 Found", sum(repression_mask), "repressions from mor column"))
      }
      
      if (!"title" %in% colnames(edges)) {
        edges$title <- paste(
          "Regulation:", regulation_type,
          "<br>Confidence:", round(edges$confidence %||% 0.5, 3)
        )
      }
      
      if (!"width" %in% colnames(edges)) {
        edges$width <- pmax(1, (edges$confidence %||% 0.5) * 4)
      }
      
      if (!"color.color" %in% colnames(edges)) {
        # Color based on regulation type
        edges$color.color <- ifelse(regulation_type == "Activation", "#27AE60", "#E74C3C")
        edges$color.opacity <- 0.8
      }
      
      if (!"arrows" %in% colnames(edges)) {
        edges$arrows <- "to"
      }
      
      print(paste("🔧 Fixed", nrow(edges), "edges:",
                  sum(regulation_type == "Activation"), "activations,",
                  sum(regulation_type == "Repression"), "repressions"))
    }
    
    return(list(nodes = nodes, edges = edges))
  }
  
