  validate_ppi_results <- function(results) {
    required_fields <- c("network_data", "ppi_interactions", "summary_stats", "analysis_type")
    
    # Ensure all required fields exist
    for (field in required_fields) {
      if (is.null(results[[field]])) {
        print(paste("⚠️ Missing field:", field, "- adding default"))
        
        # Add defaults for missing fields
        if (field == "network_data") {
          results$network_data <- list(
            nodes = data.frame(id = character(0), label = character(0)),
            edges = data.frame(from = character(0), to = character(0))
          )
        } else if (field == "ppi_interactions") {
          results$ppi_interactions <- data.frame()
        } else if (field == "summary_stats") {
          results$summary_stats <- list(n_nodes = 0, n_edges = 0, density = 0, avg_degree = 0)
        } else if (field == "analysis_type") {
          results$analysis_type <- "ppi"
        }
      }
    }
    
    return(results)
  }
  
  diagnose_ppi_storage <- function() {
    cat("\n========================================\n")
    cat("PPI STORAGE DIAGNOSTIC REPORT\n")
    cat("========================================\n")
    
    # Check current_results
    cat("\n1. CURRENT RESULTS:\n")
    if (!is.null(network_rv$current_results)) {
      cat("   ✅ Exists\n")
      cat("   - analysis_type:", network_rv$current_results$analysis_type %||% "NULL", "\n")
      
      if (!is.null(network_rv$current_results$network_data)) {
        nodes_count <- nrow(network_rv$current_results$network_data$nodes %||% data.frame())
        edges_count <- nrow(network_rv$current_results$network_data$edges %||% data.frame())
        cat("   - Network: ", nodes_count, " nodes, ", edges_count, " edges\n", sep="")
      }
      
      if (!is.null(network_rv$current_results$ppi_interactions)) {
        cat("   - PPI interactions:", nrow(network_rv$current_results$ppi_interactions), "rows\n")
      }
      
      if (!is.null(network_rv$current_results$hub_proteins)) {
        cat("   - Hub proteins:", nrow(network_rv$current_results$hub_proteins), "proteins\n")
      }
    } else {
      cat("   ❌ NULL\n")
    }
    
    # Check ppi_results
    cat("\n2. PPI RESULTS:\n")
    if (!is.null(network_rv$ppi_results)) {
      cat("   ✅ Exists\n")
      cat("   - analysis_type:", network_rv$ppi_results$analysis_type %||% "NULL", "\n")
    } else {
      cat("   ❌ NULL\n")
    }
    
    # Check status variables
    cat("\n3. STATUS VARIABLES:\n")
    cat("   - analysis_status:", network_rv$analysis_status %||% "NULL", "\n")
    cat("   - analysis_type:", network_rv$analysis_type %||% "NULL", "\n")
    cat("   - available:", network_rv$available %||% "NULL", "\n")
    
    # Check data consistency
    cat("\n4. DATA CONSISTENCY:\n")
