                                     print(paste("📊 Input genes:", nrow(rv_deg_main$deg_results)))
                                     print(paste("🗂️ TF Database:", input$tf_database %||% "dorothea"))
                                     print(paste("📈 Confidence level:", input$tf_confidence %||% 0.6))
                                     
