                                         network_rv$error_message <- "No DEG results available"
                                       })
                                       return()
                                     }
                                     
                                     incProgress(0.1, detail = "Extracting significant DEGs...")
                                     
                                     # Use the SAME p-value column that was already determined at the top of the observer
                                     # (This is already set as pval_column variable)
                                     significance_col <- pval_column
                                     print(paste("🔍 Using p-value column:", significance_col))
                                     
                                     # Get user's actual filter settings (same as drug_target)
                                     log2fc_max <- rv_deg_main$log2fc_max_main %||% 
                                       input$log2fc_max_main %||% 
                                       input$log2fc_max %||% 
                                       1.5
                                     
                                     log2fc_min <- rv_deg_main$log2fc_min_main %||% 
                                       input$log2fc_min_main %||%
                                       input$log2fc_min %||% 
                                       -1.5
                                     
                                     pval_threshold <- input$pvalue_cutoff_deg_main %||% 
                                       input$pvalue_cutoff_main %||%
                                       input$pvalue_cutoff %||% 
                                       0.05
                                     
                                     fc_min_threshold <- log2fc_min
                                     fc_max_threshold <- log2fc_max
                                     
                                     print(paste("🔍 Filter criteria:"))
                                     print(paste("  • P-value column:", significance_col))
                                     print(paste("  • P-value threshold:", pval_threshold))
                                     print(paste("  • FC thresholds: <", fc_min_threshold, "or >", fc_max_threshold))
                                     
                                     # Apply filtering to get significant DEGs
                                     significant_degs <- tryCatch({
                                       rv_deg_main$deg_results %>%
                                         filter(
                                           !is.na(!!sym(significance_col)),
                                           !!sym(significance_col) < pval_threshold,
                                           !is.na(log2FC),
                                           (log2FC < fc_min_threshold | log2FC > fc_max_threshold)
                                         )
                                     }, error = function(e) {
                                       print(paste("❌ Filtering error:", e$message))
                                       rv_deg_main$deg_results[0, ]
                                     })
                                     
                                     if (nrow(significant_degs) == 0) {
                                       showNotification("No significant DEGs found with current thresholds", type = "warning")
                                       isolate({
                                         network_rv$analysis_status <- "error"
                                         network_rv$error_message <- "No significant DEGs found"
                                       })
                                       return()
                                     }
                                     
                                     print(paste("✅ Found", nrow(significant_degs), "significant DEGs"))
                                     
                                     incProgress(0.2, detail = "Preparing gene lists...")
                                     
                                     # Extract gene IDs
                                     # Extract gene IDs and CLEAN THEM (remove comparison suffix)
                                     if ("gene_id" %in% colnames(significant_degs)) {
                                       all_gene_ids <- significant_degs$gene_id
                                     } else {
                                       all_gene_ids <- rownames(significant_degs)
                                     }
                                     
                                     # CRITICAL: Clean gene IDs to remove comparison suffixes
                                     all_gene_ids_clean <- gsub("_.*$", "", all_gene_ids)  # Remove everything after underscore
                                     all_gene_ids_clean <- gsub("\\.[0-9]+$", "", all_gene_ids_clean)  # Remove version numbers
                                     
                                     print(paste("📝 Sample raw IDs:", paste(head(all_gene_ids, 3), collapse = ", ")))
                                     print(paste("📝 Sample cleaned IDs:", paste(head(all_gene_ids_clean, 3), collapse = ", ")))
                                     
                                     # Separate up and down regulated genes
                                     up_mask <- significant_degs$log2FC > 0  # Use 0 as threshold, not fc_max_threshold
                                     down_mask <- significant_degs$log2FC < 0
                                     
                                     up_gene_ids <- all_gene_ids_clean[up_mask]
                                     down_gene_ids <- all_gene_ids_clean[down_mask]
                                     
                                     # Remove NAs
                                     up_gene_ids <- up_gene_ids[!is.na(up_gene_ids) & up_gene_ids != ""]
                                     down_gene_ids <- down_gene_ids[!is.na(down_gene_ids) & down_gene_ids != ""]
                                     
                                     print(paste("📊 Gene distribution:"))
                                     print(paste("  • Up-regulated:", length(up_gene_ids)))
                                     print(paste("  • Down-regulated:", length(down_gene_ids)))
                                     
                                     # Create gene selection in the format expected by GRN analysis
                                     grn_genes <- list(
                                       up_genes = up_gene_ids,
                                       down_genes = down_gene_ids,
                                       all_genes = c(up_gene_ids, down_gene_ids),
                                       n_up = length(up_gene_ids),
                                       n_down = length(down_gene_ids),
                                       n_total = length(up_gene_ids) + length(down_gene_ids)
                                     )
                                     
                                     print(paste("✅ GRN gene selection prepared:"))
                                     print(paste("  • Total genes:", grn_genes$n_total))
                                     print(paste("  • Sample genes:", paste(head(grn_genes$all_genes, 5), collapse = ", ")))
                                     
                                     if (grn_genes$n_total == 0) {
                                       showNotification("No DEGs found for GRN analysis after cleaning", type = "warning")
                                       isolate({
                                         network_rv$analysis_status <- "error"
                                         network_rv$error_message <- "No DEGs after cleaning"
                                       })
                                       return()
                                     }
                                     
                                     incProgress(0.3, detail = "Validating inputs...")
                                     
                                     # Validate inputs
                                     validation <- validate_grn_inputs(
                                       selected_genes = grn_genes,
                                       organism = input$organism_deg_main %||% "human",
                                       tf_database = input$tf_database %||% "dorothea",
                                       confidence_level = input$tf_confidence %||% 0.6
                                     )
                                     
                                     if (!validation$valid) {
                                       errors_text <- paste(validation$errors, collapse = "; ")
                                       showNotification(paste("GRN Analysis Error:", errors_text), type = "error", duration = 10)
                                       isolate({
                                         network_rv$analysis_status <- "error"
                                         network_rv$error_message <- errors_text
                                       })
                                       return()
                                     }
                                     
                                     incProgress(0.4, detail = paste("Running GRN analysis on", grn_genes$n_total, "DEGs..."))
                                     network_rv$selected_genes <- grn_genes
                                     # Run GRN analysis
                                     analysis_organism <- tolower(input$organism_deg_main %||% "human")
                                     # ✅ GET EXPRESSION DATA IF AVAILABLE
                                     expression_data_for_grn <- NULL
                                     
                                     if (!is.null(rv_deg_main$normalized_counts)) {
                                       expression_data_for_grn <- as.matrix(rv_deg_main$normalized_counts)
                                       print(paste("✅ Expression data available for TF activity calculation"))
                                       print(paste("   Dimensions:", nrow(expression_data_for_grn), "genes x", 
                                                   ncol(expression_data_for_grn), "samples"))
                                     } else {
                                       print("ℹ️ No normalized counts available - TF activities will not be calculated")
                                     }
                                     
                                     # ===================================================================
                                     # ✅ STEP 2: CONVERT EXPRESSION DATA ROWNAMES TO GENE SYMBOLS
                                     # ===================================================================
                                     if (!is.null(expression_data_for_grn) && nrow(expression_data_for_grn) > 0) {
                                       
                                       expr_rownames <- rownames(expression_data_for_grn)
                                       
                                       # Check if conversion is needed (has ENSEMBL/ENTREZ IDs)
                                       needs_conversion <- any(
                                         grepl("^ENS", expr_rownames) |     # ENSEMBL IDs
                                           grepl("^[0-9]+$", expr_rownames)   # Entrez IDs
                                       )
                                       
                                       if (needs_conversion) {
                                         print("🔄 Converting expression data gene IDs to symbols for TF activity...")
                                         print(paste("   Original ID examples:", paste(head(expr_rownames, 3), collapse = ", ")))
                                         
                                         # Use existing conversion function
                                         conversion_result <- convert_gene_ids_to_symbols_deg(
                                           gene_ids = expr_rownames,
                                           organism = analysis_organism
                                         )
                                         
                                         if (!is.null(conversion_result) && nrow(conversion_result) > 0) {
                                           
                                           # Keep only successfully converted genes
                                           successfully_converted <- conversion_result$gene_symbol != "-" & 
                                             !is.na(conversion_result$gene_symbol)
                                           
                                           if (sum(successfully_converted) > 0) {
                                             
                                             # ✅ HANDLE DUPLICATE GENE SYMBOLS
                                             converted_symbols <- conversion_result$gene_symbol[successfully_converted]
                                             converted_original_ids <- conversion_result$original_id[successfully_converted]
                                             
                                             # Find duplicates
                                             duplicate_symbols <- duplicated(converted_symbols) | duplicated(converted_symbols, fromLast = TRUE)
                                             
                                             if (any(duplicate_symbols)) {
                                               n_duplicates <- sum(duplicate_symbols)
                                               print(paste("⚠️ Found", n_duplicates, "duplicate gene symbols"))
                                               
                                               # Get original expression data for successfully converted genes
                                               original_expr_subset <- expression_data_for_grn[successfully_converted, , drop = FALSE]
                                               
                                               # DEBUGGING: Check the class and dimensions
                                               print("--- Debug Info ---")
                                               print(paste("Class of original_expr_subset:", class(original_expr_subset)))
                                               print("Dimensions of original_expr_subset:")
                                               print(dim(original_expr_subset))
                                               print("--------------------")
                                               
                                               # Strategy: Aggregate duplicates by taking the mean
                                               unique_symbols <- unique(converted_symbols)
                                               
                                               # Create new expression matrix with unique symbols
                                               new_expr_data <- matrix(
                                                 nrow = length(unique_symbols),
                                                 ncol = ncol(expression_data_for_grn),
                                                 dimnames = list(unique_symbols, colnames(expression_data_for_grn))
                                               )
                                               
                                               # Aggregate duplicates by taking the mean
                                               for (symbol in unique_symbols) {
                                                 # Find which rows in the SUBSET have this symbol
                                                 matching_indices <- which(converted_symbols == symbol)
                                                 
                                                 if (length(matching_indices) == 1) {
                                                   # No duplication - direct copy from subset
                                                   new_expr_data[symbol, ] <- original_expr_subset[matching_indices, , drop = FALSE]
                                                 } else {
                                                   # Multiple genes map to same symbol - take mean expression
                                                   dup_expr <- original_expr_subset[matching_indices, , drop = FALSE]
                                                   new_expr_data[symbol, ] <- colMeans(dup_expr, na.rm = TRUE)
                                                 }
                                               }
                                               
                                               expression_data_for_grn <- new_expr_data
                                               
                                               print(paste("✅ Resolved duplicates by averaging expression"))
                                               print(paste("   Converted", length(unique_symbols), "unique genes"))
                                               
                                             } else {
                                               # No duplicates - simple approach
                                               expression_data_for_grn <- expression_data_for_grn[successfully_converted, , drop = FALSE]
                                               rownames(expression_data_for_grn) <- converted_symbols
                                               
                                               print(paste("✅ Converted", sum(successfully_converted), "genes (no duplicates)"))
                                             }
                                             
                                             print(paste("   Final gene count:", nrow(expression_data_for_grn)))
                                             print(paste("   Symbol examples:", paste(head(rownames(expression_data_for_grn), 3), collapse = ", ")))
                                             
                                           } else {
                                             print("⚠️ No genes could be converted - TF activity may not work")
                                           }
                                         }
                                       } else {
                                         print("✅ Expression data already has gene symbols")
                                         print(paste("   Gene examples:", paste(head(expr_rownames, 3), collapse = ", ")))
                                       }
                                     }
                                     
                                     
                                     # ADD THIS VERIFICATION LINE:
                                     print(paste("   Sample rownames:", paste(head(rownames(expression_data_for_grn), 5), collapse = ", ")))
                                     
                                     grn_results <- tryCatch({
                                       run_grn_analysis_corrected(
                                         selected_genes = grn_genes,
                                         expression_data = expression_data_for_grn,
                                         organism = analysis_organism,
                                         tf_database = input$tf_database %||% "dorothea",
                                         confidence_level = input$tf_confidence %||% 0.6,
                                         min_tf_edges = input$grn_min_tf_edges %||% 2,
                                         calculate_activities = input$include_tf_activities %||% TRUE # Pass the checkbox value
                                       )
                                     }, error = function(e) {
                                       print(paste("❌ GRN analysis error:", e$message))
                                       list(error = paste("GRN analysis failed:", e$message))
                                     })
                                     
                                     incProgress(0.6, detail = "Processing results...")
                                     
                                     # Check for errors in results
                                     if (!is.null(grn_results$error)) {
                                       print(paste("❌ GRN analysis returned error:", grn_results$error))
                                       showNotification(grn_results$error, type = "error", duration = 10)
                                       isolate({
                                         network_rv$analysis_status <- "error"
                                         network_rv$error_message <- grn_results$error
                                       })
                                       return()
                                     }
                                     
                                     # Validate results structure
                                     if (is.null(grn_results) || !is.list(grn_results) ||
                                         is.null(grn_results$network_data) ||
                                         !is.list(grn_results$network_data) ||
                                         is.null(grn_results$network_data$nodes) ||
                                         is.null(grn_results$network_data$edges)) {
                                       print("❌ Invalid GRN results structure")
                                       showNotification("GRN analysis returned invalid results", type = "error")
                                       isolate({
                                         network_rv$analysis_status <- "error"
                                         network_rv$error_message <- "Invalid results structure"
                                       })
                                       return()
                                     }
                                     
                                     incProgress(0.8, detail = "Storing results...")
                                     
                                     # Validate results structure first
                                     if (is.null(grn_results) || !is.list(grn_results) ||
                                         is.null(grn_results$network_data) ||
                                         !is.list(grn_results$network_data) ||
                                         is.null(grn_results$network_data$nodes) ||
                                         is.null(grn_results$network_data$edges)) {
                                       print("❌ Invalid GRN results structure")
                                       showNotification("GRN analysis returned invalid results", type = "error")
                                       
                                       isolate({
                                         network_rv$analysis_status <- "error"
                                         network_rv$error_message <- "Invalid results structure"
                                       })
                                       return()
                                     }
                                     
                                     print("🔧 Storing GRN results...")
                                     
                                     # CRITICAL FIX: Store results OUTSIDE isolate to trigger reactivity
                                     # Only use isolate for the final status update
                                     
                                     # Store GRN-specific results first
                                     # Store GRN-specific results first
                                     network_rv$grn_results <- grn_results
                                     network_rv$current_network <- grn_results$network_data
                                     # ✅ ADD: Store selected_genes for filtering at render time
                                     network_rv$selected_genes <- network_rv$deg_genes_for_grn
                                     print("🔍 DEBUG: Checking stored GRN results...")
                                     print(paste("   grn_results is NULL:", is.null(grn_results)))
                                     print(paste("   tf_activities is NULL:", is.null(grn_results$tf_activities)))
                                     if (!is.null(grn_results$tf_activities)) {
                                       print(paste("   tf_activities rows:", nrow(grn_results$tf_activities)))
                                       print(paste("   tf_activities columns:", paste(colnames(grn_results$tf_activities), collapse = ", ")))
                                     }
                                     print(paste("   network_rv$grn_results$tf_activities is NULL:", 
                                                 is.null(network_rv$grn_results$tf_activities)))
                                     
                                     # Create properly structured current_results
                                     network_rv$current_results <- list(
                                       analysis_type = "grn",
                                       network_data = list(
                                         nodes = grn_results$network_data$nodes,
                                         edges = grn_results$network_data$edges
                                       ),
                                       tf_regulations = grn_results$tf_regulations,
                                       master_regulators = grn_results$master_regulators,
                                       tf_pathway_enrichment = grn_results$tf_pathway_enrichment,  # ✅ ADD THIS
                                       target_pathway_enrichment = grn_results$target_pathway_enrichment,  # ✅ ADD THIS
                                       tf_activities = grn_results$tf_activities,
                                       summary_stats = grn_results$summary_stats,
                                       analysis_params = list(
                                         analysis_focus = "grn",
                                         organism = grn_results$analysis_params$organism %||% "human",
                                         tf_database = grn_results$analysis_params$tf_database %||% "dorothea",
                                         confidence_level = grn_results$analysis_params$confidence_level %||% 0.6,
                                         n_input_genes = grn_results$analysis_params$n_input_genes %||% 0,
                                         n_converted_genes = grn_results$analysis_params$n_converted_genes %||% 0,
                                         n_tfs = grn_results$analysis_params$n_tfs %||% 0,
                                         n_targets = grn_results$analysis_params$n_targets %||% 0,
                                         n_regulations = grn_results$analysis_params$n_regulations %||% 0,
                                         conversion_rate = grn_results$analysis_params$conversion_rate %||% 0
                                       )
                                     )
                                     
                                     # Set analysis type
                                     network_rv$analysis_type <- "grn"
                                     network_rv$available <- TRUE
                                     
                                     # CRITICAL: Set status LAST and OUTSIDE isolate to trigger observers
                                     network_rv$analysis_status <- "complete"
                                     
                                     print("✅ Results successfully stored in reactive values")
                                     
                                     # Final success message
                                     print("=== GRN ANALYSIS COMPLETE ===")
                                     print(paste("✅ Nodes:", nrow(grn_results$network_data$nodes)))
                                     print(paste("✅ Edges:", nrow(grn_results$network_data$edges)))
                                     print(paste("✅ Master TFs:", nrow(grn_results$master_regulators)))
                                     
                                     incProgress(1.0, detail = "Analysis complete!")
                                     
                                     showNotification(
                                       "GRN analysis completed successfully!",
                                       type = "message",
                                       duration = 5
                                     )
                                   },
                                   "ppi"= {
                                     req(input$network_analysis_type_systems == "ppi")
                                     ppi_results <- NULL
                                     tryCatch({
                                       
                                       # ==========================
                                       # STEP 1: GET GENES FROM EXISTING TABLES
                                       # ==========================
                                       incProgress(0.2, detail = "Getting DEGs from tables...")
                                       
                                       print("=== PPI ANALYSIS STARTING ===")
                                       print("Using genes from existing DEG tables (up/down regulated)")
                                       
                                       # Get the already-filtered DEGs from your reactive values
                                       up_regulated_data <- NULL
                                       down_regulated_data <- NULL
                                       
                                       if (!is.null(rv_deg_main$up_regulated)) {
                                         up_regulated_data <- rv_deg_main$up_regulated
                                         down_regulated_data <- rv_deg_main$down_regulated
                                       } else if (!is.null(rv_deg_main$deg_results)) {
                                         
                                         deg_data <- rv_deg_main$deg_results
                                         
                                         # ✅ Get p-value type from user selection
                                         pvalue_type <- input$pvalue_type_main %||% "adjusted"
                                         pval_column <- if (pvalue_type == "adjusted") "adj.P.Val" else "P.Value"
                                         
                                         print(paste("PPI filtering using p-value type:", pvalue_type, "- Column:", pval_column))
                                         
                                         # ✅ Get thresholds with correct variable names
                                         pval_threshold <- rv_deg_main$pvalue_cutoff_deg_main %||% 
                                           input$pvalue_cutoff_deg_main %||% 
                                           0.05
                                         
                                         log2fc_max <- rv_deg_main$log2fc_max_main %||% 
                                           input$log2fc_max %||% 
                                           2
                                         
                                         log2fc_min <- rv_deg_main$log2fc_min_main %||% 
                                           input$log2fc_min %||% 
                                           -2
                                         
                                         print(paste("Using thresholds:"))
                                         print(paste("  P-value type:", pvalue_type))
                                         print(paste("  P-value column:", pval_column))
                                         print(paste("  P-value threshold:", pval_threshold))
                                         print(paste("  Log2FC range: [", log2fc_min, ",", log2fc_max, "]"))
                                         
                                         # ✅ Apply correct thresholds using dynamic p-value column
                                         up_regulated_data <- deg_data[
                                           !is.na(deg_data[[pval_column]]) & 
                                             deg_data[[pval_column]] < pval_threshold &
                                             !is.na(deg_data$log2FC) &
                                             deg_data$log2FC > log2fc_max,
                                         ]
                                         
                                         down_regulated_data <- deg_data[
                                           !is.na(deg_data[[pval_column]]) & 
                                             deg_data[[pval_column]] < pval_threshold &
                                             !is.na(deg_data$log2FC) &
                                             deg_data$log2FC < log2fc_min,
                                         ]
                                       }
                                       
                                       # Check if we have data
                                       if (is.null(up_regulated_data) && is.null(down_regulated_data)) {
                                         stop("No DEG data available. Please run DEG analysis first.")
                                       }
                                       
                                       # Combine up and down regulated for total counts
                                       n_up <- nrow(up_regulated_data %||% data.frame())
                                       n_down <- nrow(down_regulated_data %||% data.frame())
                                       n_total <- n_up + n_down
                                       
                                       print(paste("Found DEGs from tables:"))
                                       print(paste("  • Up-regulated:", n_up))
                                       print(paste("  • Down-regulated:", n_down))
                                       print(paste("  • Total:", n_total))
                                       
