                                         up_genes = up_genes,
                                         down_genes = down_genes,
                                         n_total = length(all_genes),
                                         n_up = length(up_genes),
                                         n_down = length(down_genes)
                                       )
                                       
                                       if (selected_genes$n_total == 0) {
                                         stop("No significant DEGs found to analyze.")
                                       }
                                       
                                       isolate({
                                         network_rv$selected_genes <- selected_genes
                                       })
                                       
                                       # ==========================
                                       # STEP 3: GET PPI PARAMETERS FROM UI
                                       # ==========================
                                       incProgress(0.4, detail = "Setting up PPI parameters...")
                                       
                                       organism_param <- isolate(input$organism_deg_main %||% "human")
                                       confidence_threshold <- isolate(input$ppi_confidence_threshold %||% 0.4)
                                       network_type <- isolate(input$ppi_network_type %||% "physical")
                                       max_interactions <- isolate(input$ppi_max_interactions %||% 1000)
                                       expand_network <- isolate(input$ppi_expand_network %||% FALSE)
                                       filter_isolated <- isolate(input$ppi_filter_isolated %||% TRUE)
                                       detect_modules <- isolate(input$ppi_detect_modules %||% TRUE)
                                       run_enrichment <- isolate(input$ppi_run_enrichment %||% TRUE)
                                       evidence_channels <- isolate(input$ppi_evidence_channels %||% c("experiments", "databases"))
                                       
                                       print(paste("PPI Parameters:"))
                                       print(paste("  • Organism:", organism_param))
                                       print(paste("  • Confidence threshold:", confidence_threshold))
                                       print(paste("  • Network type:", network_type))
                                       print(paste("  • Max interactions:", max_interactions))
                                       
                                       # ==========================
                                       # STEP 4: RUN PPI ANALYSIS - FIXED VERSION
                                       # ==========================
                                       incProgress(0.5, detail = "Querying STRING database...")
                                       
                                       # Initialize variables at the outer scope
                                       gene_interactions <- NULL
                                       hub_proteins <- NULL
                                       global_metrics <- NULL
                                       functional_enrichment <- list()
                                       mapping_rate <- 0
                                       
                                       ppi_results <- tryCatch({

                                         species_map <- list(
                                           human = 9606, mouse = 10090, rat = 10116,
                                           fly = 7227, zebrafish = 7955, yeast = 4932
                                         )
                                         species_id <- species_map[[tolower(organism_param)]] %||% 9606

                                         print(paste("Querying STRING for species:", species_id, "(using local data if available)"))

