                                           stringsAsFactors = FALSE
                                         )
                                         mapping_rate <- length(intersect(all_genes, all_proteins_in_network)) / max(length(all_genes), 1)
                                         print(paste("Mapped", round(mapping_rate * 100, 1), "% of genes found in STRING"))

                                         # Convert to STRING-style interactions format (from/to with combined_score 0-1000)
                                         interactions <- data.frame()
                                         if (nrow(ppi_raw) > 0) {
                                           interactions <- data.frame(
                                             from = ppi_raw$gene_from,
                                             to = ppi_raw$gene_to,
                                             combined_score = as.integer(ppi_raw$combined_score * 1000),
                                             stringsAsFactors = FALSE
                                           )
                                         }

                                         incProgress(0.7, detail = "Processing interactions...")

                                         if (nrow(interactions) > 0) {
                                           if (nrow(interactions) > max_interactions) {
                                             interactions <- interactions[order(interactions$combined_score, decreasing = TRUE), ]
                                             interactions <- interactions[1:max_interactions, ]
                                           }

                                           # --- FIRST SHELL EXPANSION (using local data) ---
                                           if (expand_network && nrow(interactions) > 0) {
                                             print("Expanding network with first-shell interactors...")
                                             incProgress(0.72, detail = "Adding first-shell neighbors...")

                                             tryCatch({
                                               string_data_path <- Sys.getenv("STRING_DATA_PATH", "/srv/string_data")
                                               local_species <- c(9606, 10090)

                                               if (species_id %in% local_species && requireNamespace("data.table", quietly = TRUE)) {
                                                 # Use local STRING data for first-shell expansion
                                                 links_file <- file.path(string_data_path, paste0(species_id, ".protein.links.v12.0.txt.gz"))
                                                 aliases_file <- file.path(string_data_path, paste0(species_id, ".protein.aliases.v12.0.txt.gz"))

                                                 if (file.exists(links_file) && file.exists(aliases_file)) {
                                                   # Load cached alias mapping
                                                   cache_dir <- file.path(tempdir(), "string_cache")
                                                   if (!dir.exists(cache_dir)) dir.create(cache_dir, recursive = TRUE)
                                                   aliases_rds <- file.path(cache_dir, paste0(species_id, "_aliases_symbols.rds"))

                                                   if (file.exists(aliases_rds)) {
                                                     alias_map <- readRDS(aliases_rds)
                                                   } else {
                                                     all_aliases <- data.table::fread(cmd = paste("zcat", aliases_file),
                                                       sep = "\t", header = TRUE, col.names = c("string_id", "alias", "source"))
                                                     symbol_sources <- c("Ensembl_HGNC_symbol", "Ensembl_EntrezGene",
                                                                         "BLAST_KEGG_NAME", "Ensembl_MGI_symbol", "Ensembl_MGI")
                                                     alias_map <- unique(all_aliases[all_aliases$source %in% symbol_sources, c("string_id", "alias")])
                                                     tryCatch(saveRDS(alias_map, aliases_rds), error = function(e) NULL)
                                                     rm(all_aliases)
                                                   }

                                                   # Load cached links
                                                   links_rds <- file.path(cache_dir, paste0(species_id, "_links.rds"))
                                                   if (file.exists(links_rds)) {
                                                     all_links <- readRDS(links_rds)
                                                   } else {
                                                     all_links <- data.table::fread(cmd = paste("zcat", links_file), header = TRUE)
                                                     tryCatch(saveRDS(all_links, links_rds), error = function(e) NULL)
                                                   }

                                                   # Map current network genes to STRING IDs
                                                   current_genes <- unique(c(interactions$from, interactions$to))
                                                   alias_map$alias_upper <- toupper(alias_map$alias)
                                                   matched <- alias_map[alias_map$alias_upper %in% toupper(current_genes), ]
                                                   current_sids <- unique(matched$string_id)

                                                   # Find neighbors: proteins that interact with current network but are NOT in it
                                                   conf_thresh <- as.integer(confidence_threshold * 1000)
                                                   neighbor_links <- all_links[
                                                     (all_links$protein1 %in% current_sids | all_links$protein2 %in% current_sids) &
                                                     !(all_links$protein1 %in% current_sids & all_links$protein2 %in% current_sids) &
                                                     all_links$combined_score >= conf_thresh,
                                                   ]

                                                   if (nrow(neighbor_links) > 0) {
                                                     # Get top neighbors by score (limit to prevent explosion)
                                                     neighbor_links <- neighbor_links[order(neighbor_links$combined_score, decreasing = TRUE), ]
                                                     neighbor_links <- head(neighbor_links, 200)

                                                     # Map STRING IDs back to gene symbols
                                                     sid_to_gene <- setNames(matched$alias, matched$string_id)
                                                     # Also map new neighbor IDs
                                                     new_sids <- setdiff(
                                                       unique(c(neighbor_links$protein1, neighbor_links$protein2)),
                                                       current_sids
                                                     )
                                                     new_matched <- alias_map[alias_map$string_id %in% new_sids, ]
                                                     # Deduplicate: one symbol per string_id
                                                     new_matched <- new_matched[!duplicated(new_matched$string_id), ]
                                                     all_sid_map <- c(sid_to_gene, setNames(new_matched$alias, new_matched$string_id))

                                                     map_fn <- function(sids) {
                                                       mapped <- all_sid_map[sids]
                                                       na_idx <- is.na(mapped)
                                                       if (any(na_idx)) mapped[na_idx] <- gsub("^[0-9]+\\.", "", sids[na_idx])
                                                       return(as.character(mapped))
                                                     }

                                                     new_interactions <- data.frame(
                                                       from = map_fn(neighbor_links$protein1),
                                                       to = map_fn(neighbor_links$protein2),
                                                       combined_score = neighbor_links$combined_score,
                                                       stringsAsFactors = FALSE
                                                     )

                                                     interactions <- rbind(interactions, new_interactions)
                                                     n_new_proteins <- length(setdiff(
                                                       unique(c(new_interactions$from, new_interactions$to)),
                                                       current_genes
                                                     ))
                                                     print(paste("Network expanded: added", nrow(new_interactions),
                                                                 "first-shell interactions,", n_new_proteins, "new proteins"))
                                                   } else {
                                                     print("No first-shell neighbors found above confidence threshold")
                                                   }
                                                 }
                                               } else {
                                                 print("First-shell expansion via API not supported - use local data for human/mouse")
                                               }
                                             }, error = function(e) {
                                               print(paste("Network expansion failed:", e$message))
                                             })
                                           }

                                           print(paste("Found", nrow(interactions), "interactions"))
                                             
                                             
                                             # ==========================
                                             # CREATE NETWORK VISUALIZATION DATA
                                             # ==========================
                                             incProgress(0.75, detail = "Building network analysis...")
                                             
                                             if (require("igraph", quietly = TRUE) && nrow(interactions) > 0) {
                                               
                                               # Create gene-to-gene interaction data frame
                                               gene_interactions <- create_safe_gene_interactions(interactions, mapped_genes)
                                               
                                               print(paste("Created", nrow(gene_interactions), "gene-to-gene interactions"))
                                               
                                               if (nrow(gene_interactions) > 0) {
                                                 
                                                 # Create network graph for analysis
                                                 network_graph <- graph_from_data_frame(
                                                   gene_interactions[, c("gene_from", "gene_to")],
                                                   directed = FALSE
                                                 )
                                                 
                                                 # MODULE DETECTION IMPLEMENTATION
                                                 network_modules <- NULL
                                                 if (detect_modules && vcount(network_graph) >= 5) {  # Need at least 5 nodes
                                                   print("🔍 Detecting network modules/clusters...")
                                                   
                                                   tryCatch({
                                                     # Try multiple clustering algorithms
                                                     clustering_results <- list()
                                                     
                                                     # 1. Louvain algorithm (fast and effective)
                                                     if (requireNamespace("igraph", quietly = TRUE)) {
                                                       clustering_results$louvain <- cluster_louvain(network_graph)
                                                     }
                                                     
                                                     # 2. Fast greedy (good for small networks)
                                                     if (vcount(network_graph) < 100) {
                                                       clustering_results$fast_greedy <- cluster_fast_greedy(network_graph)
                                                     }
                                                     
                                                     # Select best clustering by modularity
                                                     if (length(clustering_results) > 0) {
                                                       modularities <- sapply(clustering_results, modularity)
                                                       best_method <- names(modularities)[which.max(modularities)]
                                                       best_clustering <- clustering_results[[best_method]]
                                                       
                                                       # Get module membership
                                                       module_membership <- membership(best_clustering)
                                                       
                                                       # Create membership dataframe
                                                       membership_df <- data.frame(
                                                         protein = V(network_graph)$name,
                                                         module = module_membership,
                                                         stringsAsFactors = FALSE
                                                       )
                                                       
                                                       # Create module summary with gene lists
                                                       module_summary <- membership_df %>%
                                                         group_by(module) %>%
                                                         summarise(
                                                           size = n(),
                                                           genes = paste(protein, collapse = ", "),
                                                           .groups = 'drop'
                                                         ) %>%
                                                         mutate(
                                                           module_name = paste0("Module_", module),
                                                           modularity_contribution = max(modularities) / n()
                                                         ) %>%
                                                         arrange(desc(size))
                                                       
                                                       # Create the network_modules structure that UI expects
                                                       network_modules <- list(
                                                         method = best_method,
                                                         modularity = max(modularities),
                                                         n_modules = length(unique(module_membership)),
                                                         module_sizes = as.numeric(table(module_membership)),
                                                         membership = membership_df,
                                                         statistics = as.data.frame(module_summary)  # ← Ensure this is a proper data.frame
                                                       )
                                                       
                                                       print(paste("✅ Detected", network_modules$n_modules, "modules using", best_method))
                                                       print(paste("   Module sizes:", paste(network_modules$module_sizes, collapse = ", ")))
                                                       
                                                       # VERIFY the structure
                                                       print("🔍 MODULE STRUCTURE VERIFICATION:")
                                                       print(paste("  • network_modules class:", class(network_modules)))
                                                       print(paste("  • statistics class:", class(network_modules$statistics)))
                                                       print(paste("  • statistics is data.frame:", is.data.frame(network_modules$statistics)))
                                                       print(paste("  • statistics rows:", nrow(network_modules$statistics)))
                                                       
                                                     } else {
                                                       network_modules <- NULL
                                                       print("❌ No clustering results - network_modules set to NULL")
                                                     }
                                                     
                                                   }, error = function(e) {
                                                     print(paste("⚠️ Module detection failed:", e$message))
                                                     network_modules <- NULL
                                                   })
                                                 } else if (detect_modules) {
                                                   print("ℹ️ Network too small for module detection (need ≥5 nodes)")
                                                 }
                                                 
                                                 # Get all unique proteins in network
                                                 all_network_proteins <- unique(c(gene_interactions$gene_from, gene_interactions$gene_to))
                                                 print(paste("Network contains", length(all_network_proteins), "unique proteins"))
                                                 
                                                 
                                                 # ISOLATED NODE FILTERING IMPLEMENTATION
                                                 if (filter_isolated && vcount(network_graph) > 0) {
                                                   print("🧹 Filtering isolated nodes...")
                                                   
                                                   # ✅ FIX: Safely extract degrees and convert to numeric vector
                                                   node_degrees <- tryCatch({
                                                     deg_result <- igraph::degree(network_graph, mode = "all")
                                                     as.numeric(deg_result)
                                                   }, error = function(e) {
                                                     print(paste("⚠️ Error calculating degrees:", e$message))
                                                     rep(1, vcount(network_graph))  # Fallback: assume all connected
                                                   })
                                                   
                                                   # Only filter if we have valid degree data
                                                   if (!is.null(node_degrees) && length(node_degrees) > 0) {
                                                     isolated_nodes <- which(node_degrees == 0)
                                                     
                                                     if (length(isolated_nodes) > 0) {
                                                       print(paste("Removing", length(isolated_nodes), "isolated nodes"))
                                                       
                                                       # Remove isolated nodes by index
                                                       network_graph <- delete_vertices(network_graph, isolated_nodes)
                                                       
                                                       # Update gene_interactions to match filtered graph
                                                       remaining_nodes <- V(network_graph)$name
                                                       gene_interactions <- gene_interactions[
                                                         gene_interactions$gene_from %in% remaining_nodes &
                                                           gene_interactions$gene_to %in% remaining_nodes,
                                                       ]
                                                       
                                                       print(paste("✅ Network now has", vcount(network_graph), "connected nodes"))
                                                     } else {
                                                       print("ℹ️ No isolated nodes found")
                                                     }
                                                   } else {
                                                     print("⚠️ Could not calculate node degrees, skipping isolated node filtering")
                                                   }
                                                 }
                                                 
                                                 
                                                 # Calculate comprehensive centrality measures
                                                 incProgress(0.8, detail = "Calculating network centrality measures...")
                                                 
                                                 hub_proteins <- create_safe_hub_analysis(network_graph, all_genes, up_genes, down_genes)
                                                 
                                                 print(paste("🎯 Hub protein analysis:"))
                                                 print(paste("  • Total proteins in network:", nrow(hub_proteins)))
                                                 print(paste("  • Major hubs:", sum(hub_proteins$hub_type == "Major Hub", na.rm = TRUE)))
                                                 print(paste("  • Regular hubs:", sum(hub_proteins$hub_type == "Hub", na.rm = TRUE)))
                                                 
                                                 # Calculate global network metrics
                                                 incProgress(0.85, detail = "Calculating network topology...")
                                                 
                                                 global_metrics <- create_safe_global_metrics(network_graph)
                                                 
                                                 # Run functional enrichment analysis
                                                 incProgress(0.9, detail = "Running functional enrichment analysis...")
                                                 
                                                 if (run_enrichment && require("enrichR", quietly = TRUE)) {
                                                   functional_enrichment <- run_safe_enrichment_analysis(
                                                     all_network_proteins, organism_param
                                                   )
                                                   
                                                   enrichment_count <- length(functional_enrichment)
                                                   print(paste("✅ Enrichment analysis complete -", enrichment_count, "databases with significant results"))
                                                 }
                                                 
                                                 # ==========================
                                                 # BUILD FINAL RESULTS DIRECTLY HERE - BUT DON'T RETURN YET!
                                                 # ==========================
                                                 incProgress(0.95, detail = "Creating final results...")
                                                 
                                                 # Create network visualization
                                                 network_viz_data <- create_safe_network_visualization_with_modules(
                                                   gene_interactions, hub_proteins, selected_genes, network_modules
                                                 )

                                                 print("✅ DEBUG: Network visualization created successfully")

                                                 # =========================================================
                                                 # CytoHubba-style centrality (degree/betweenness/closeness/
                                                 # eigenvector/MCC/MNC/DMNC/EPC) + consensus hubs
                                                 # =========================================================
                                                 print("🧮 Computing 8-algorithm centrality (CytoHubba-style)...")
                                                 ppi_centrality_measures <- tryCatch(
                                                   calculate_centrality_measures(gene_interactions),
                                                   error = function(e) {
                                                     print(paste("[PPI] centrality failed:", e$message)); NULL
                                                   }
                                                 )
                                                 ppi_hub_consensus <- tryCatch(
                                                   calculate_hub_consensus(ppi_centrality_measures, top_n = 10),
                                                   error = function(e) {
                                                     print(paste("[PPI] hub_consensus failed:", e$message)); NULL
                                                   }
                                                 )
                                                 print(paste("  • centrality rows:",
                                                             if (!is.null(ppi_centrality_measures))
                                                               nrow(ppi_centrality_measures) else 0))

                                                 # =========================================================
                                                 # Drug targets — prefer LOCAL OpenTargets Parquet (fast,
                                                 # ~1-3s for a 500-gene network). Fall back to the API-based
                                                 # DGIdb + OpenTargets query when local returns NULL (non-
                                                 # human species or missing Parquet mount) or empty and we
                                                 # want to try the API for coverage.
                                                 # =========================================================
                                                 print("💊 Identifying drug targets for network proteins...")
                                                 ppi_drug_targets <- tryCatch({
                                                   local_res <- query_drug_targets_local(
                                                     all_network_proteins,
                                                     organism = organism_param
                                                   )
                                                   if (is.null(local_res)) {
                                                     # NULL -> local path unavailable (non-human / no Parquet);
                                                     # use API
                                                     print("💊 [PPI] local OT unavailable — using API fallback")
                                                     query_drug_targets_comprehensive(
                                                       all_network_proteins,
                                                       organism = organism_param
                                                     )
                                                   } else if (nrow(local_res) == 0) {
                                                     # local ran but no hits — no need to hit API (would also
                                                     # likely return nothing and cost 30-60 s)
                                                     print("💊 [PPI] local OT returned zero hits — skipping API")
                                                     local_res
                                                   } else {
                                                     local_res
                                                   }
                                                 }, error = function(e) {
                                                   print(paste("[PPI] drug_targets failed:", e$message)); data.frame()
                                                 })
                                                 ppi_druggability_summary <- tryCatch(
                                                   build_druggability_summary(ppi_drug_targets),
                                                   error = function(e) {
                                                     print(paste("[PPI] druggability summary failed:", e$message)); data.frame()
                                                   }
                                                 )
                                                 print(paste("  • druggable genes:", nrow(ppi_druggability_summary),
                                                             "| drug rows:", nrow(ppi_drug_targets)))

                                                 # ==========================
                                                 # NOW BUILD THE COMPREHENSIVE RESULTS
                                                 # ==========================

                                                 print("🔍 DEBUG: About to create comprehensive results...")
                                                 
                                                 # Create comprehensive summary statistics
                                                 print("🔍 DEBUG: Creating summary statistics...")
                                                 summary_stats <- tryCatch({
                                                   list(
                                                     basic_stats = list(
                                                       total_proteins = length(all_network_proteins),
                                                       total_interactions = nrow(gene_interactions),
                                                       input_genes = selected_genes$n_total,
                                                       mapped_genes = length(intersect(selected_genes$all_genes, all_network_proteins)),
                                                       coverage_rate = round(length(intersect(selected_genes$all_genes, all_network_proteins)) / selected_genes$n_total * 100, 1)
                                                     ),
                                                     hub_stats = list(
                                                       total_hubs = sum(hub_proteins$hub_type %in% c("Major Hub", "Hub"), na.rm = TRUE),
                                                       major_hubs = sum(hub_proteins$hub_type == "Major Hub", na.rm = TRUE),
                                                       input_hubs = sum(hub_proteins$gene_source == "Input DEG" &
                                                                          hub_proteins$hub_type %in% c("Major Hub", "Hub"), na.rm = TRUE)
                                                     ),
                                                     topology_stats = global_metrics,
                                                     n_edges = nrow(gene_interactions)  # Critical field for UI
                                                   )
                                                 }, error = function(e) {
                                                   print(paste("❌ Error in summary_stats:", e$message))
                                                   return(list(basic_stats = list(), hub_stats = list(), topology_stats = list(), n_edges = 0))
                                                 })
                                                 
                                                 print("✅ DEBUG: Summary statistics created successfully")
                                                 
                                                 # Build comprehensive results structure
                                                 print("🔍 DEBUG: Building comprehensive results structure...")
                                                 comprehensive_results <- tryCatch({
                                                   list(
                                                     # Core network data for visualization
                                                     network_data = network_viz_data,

                                                     # Complete analysis results
                                                     ppi_interactions = gene_interactions,
                                                     hub_proteins = hub_proteins,

                                                     # Summary stats
                                                     summary_stats = summary_stats,

                                                     network_modules = network_modules,
                                                     # Network analysis
                                                     network_metrics = list(
                                                       global_metrics = global_metrics,
                                                       node_metrics = hub_proteins
                                                     ),

                                                     # CytoHubba-style centrality + consensus hubs
                                                     centrality_measures = ppi_centrality_measures,
                                                     hub_consensus       = ppi_hub_consensus,

                                                     # Drug targets + druggability summary
                                                     drug_targets         = ppi_drug_targets,
                                                     druggability_summary = ppi_druggability_summary,

                                                     # Functional analysis
                                                     functional_enrichment = functional_enrichment,
                                                     
                                                     # Analysis metadata
                                                     analysis_params = list(
                                                       organism = organism_param,
                                                       confidence_threshold = confidence_threshold,
                                                       network_type = network_type,
                                                       max_interactions = max_interactions,
                                                       run_enrichment = run_enrichment,
                                                       n_input_genes = length(all_genes),
                                                       n_mapped_genes = length(all_network_proteins),
                                                       mapping_rate = mapping_rate,
                                                       analysis_date = Sys.time()
                                                     ),
                                                     
                                                     # Gene information
                                                     selected_genes = selected_genes,
                                                     
                                                     # CRITICAL: Set analysis_type
                                                     analysis_type = "ppi"
                                                   )
                                                 }, error = function(e) {
                                                   print(paste("❌ Error building comprehensive_results:", e$message))
                                                   print("Error details:")
                                                   print(e)
                                                   return(list(
                                                     error = paste("Failed to build results:", e$message),
                                                     analysis_type = "ppi"
                                                   ))
                                                 })
                                                 
                                                 print("✅ DEBUG: Comprehensive results structure created")
                                                 
                                                 
                                                 # ✅ RETURN THE RESULTS (this should be the LAST return in your PPI analysis)
                                                 #return(comprehensive_results)
                                                 
                                                 # ✅ STORE THE RESULTS - DON'T RETURN THEM YET!
                                                 ppi_results <- comprehensive_results
                                                 print("🔍 DEBUG CHECKPOINT 1: ppi_results assigned from comprehensive_results")
                                                 print(paste("🔍 DEBUG: ppi_results class:", class(ppi_results)))
                                                 print(paste("🔍 DEBUG: ppi_results names:", paste(names(ppi_results), collapse=", ")))
                                                 
                                                 ppi_results_final <- ppi_results  # Save a copy with different name
                                                 print(paste("🔍 DEBUG: Saved ppi_results_final, class:", class(ppi_results_final)))
                                                 
                                                 # Check if we're in the right scope
                                                 print("🔍 DEBUG CHECKPOINT 2: About to check else conditions...")
                                                 
                                                 
                                               } else {
                                                 print("🔍 DEBUG: Entering ELSE block - No valid gene interactions")
                                                 # No valid gene interactions
                                                 ppi_results <- list(
                                                   error = "No valid gene interactions found after mapping",
                                                   selected_genes = selected_genes,
                                                   analysis_type = "ppi"
                                                 )
                                               }
                                               
                                             } else {
                                               print("No interactions found or igraph not available")
                                               ppi_results <- list(
                                                 error = "No interactions found or igraph package not available",
                                                 selected_genes = selected_genes,
                                                 analysis_type = "ppi"
                                               )
                                             }
                                         }

                                         print("DEBUG CHECKPOINT 4: About to return ppi_results")
                                       }, error = function(e) {
                                         print(paste("PPI analysis error:", e$message))
                                         ppi_results <<- list(
                                           error = e$message,
                                           selected_genes = selected_genes,
                                           analysis_type = "ppi"
                                         )
                                       })
                                       
                                       print("🚨 DEBUG: PPI analysis tryCatch block completed")
                                       print("🚨 DEBUG: About to check ppi_results for storage...")
                                       
                                       # Check what ppi_results contains
                                       if (exists("ppi_results")) {
                                         print("✅ DEBUG: ppi_results variable exists")
                                         print(paste("✅ DEBUG: ppi_results class:", class(ppi_results)))
                                         if (is.list(ppi_results)) {
                                           print(paste("✅ DEBUG: ppi_results names:", paste(names(ppi_results), collapse = ", ")))
                                           if ("error" %in% names(ppi_results)) {
                                             print(paste("❌ DEBUG: Error in ppi_results:", ppi_results$error))
                                           }
                                         }
                                       } else {
                                         print("❌ DEBUG: ppi_results variable does NOT exist!")
                                       }
                                       
                                       print("🚨 DEBUG: PPI analysis tryCatch block completed")
                                       print("🚨 DEBUG: About to check ppi_results for storage...")
                                       # Add a check to see if ppi_results exists in the current scope:
                                       if (exists("ppi_results")) {
                                         print("✅ DEBUG: ppi_results variable exists")
                                         print(paste("✅ DEBUG: ppi_results class:", class(ppi_results)))
                                         if (is.list(ppi_results)) {
                                           print(paste("✅ DEBUG: ppi_results names:", paste(names(ppi_results), collapse = ", ")))
                                           if ("error" %in% names(ppi_results)) {
                                             print(paste("❌ DEBUG: Error in ppi_results:", ppi_results$error))
                                           }
                                         }
                                       } else {
                                         print("❌ DEBUG: ppi_results variable does NOT exist!")
                                         # This is a problem - ppi_results should exist here
                                         # Create a fallback:
                                         # ppi_results <- list(
                                         #   error = "ppi_results was not properly assigned",
                                         #   analysis_type = "ppi"
                                         # )
                                       }
                                       
                                       print("🔍 FINAL VERIFICATION BEFORE STORAGE:")
                                       print(paste("  • comprehensive_results has network_modules:", "network_modules" %in% names(comprehensive_results)))
                                       
                                       if ("network_modules" %in% names(comprehensive_results)) {
                                         modules <- comprehensive_results$network_modules
                                         if (!is.null(modules)) {
                                           print(paste("  • network_modules is not NULL"))
                                           print(paste("  • has statistics:", "statistics" %in% names(modules)))
                                           if ("statistics" %in% names(modules) && !is.null(modules$statistics)) {
                                             print(paste("  • statistics rows:", nrow(modules$statistics)))
                                           }
                                         } else {
                                           print("  • network_modules is NULL")
                                         }
                                       } else {
                                         print("  • network_modules field missing from comprehensive_results")
                                       }
                                       
                                       print("🚨 DEBUG: Now entering STEP 5: STORE RESULTS...")
                                       
                                       # Check both variables to see which one is corrupted:
                                       if (exists("ppi_results")) {
                                         print(paste("ppi_results class:", class(ppi_results)))
                                         if (is.character(ppi_results)) {
                                           print(paste("WARNING: ppi_results corrupted to character:", ppi_results))
                                         }
                                       }
                                       
                                       if (exists("ppi_results_final")) {
                                         print(paste("ppi_results_final class:", class(ppi_results_final)))
                                         # Use the protected copy
                                         ppi_results <- ppi_results_final
                                       }
                                       
                                       # ==========================
                                       # STEP 5: STORE RESULTS - FIXED VERSION
                                       # ==========================
                                       incProgress(0.98, detail = "Storing results...")
                                       
                                       # Debug what ppi_results actually is
                                       print(paste("DEBUG: ppi_results class before processing:", class(ppi_results)))
                                       print(paste("DEBUG: ppi_results type:", typeof(ppi_results)))
                                       
                                       # Ensure ppi_results is a list
                                       if (!is.list(ppi_results)) {
                                         print(paste("ERROR: ppi_results is not a list, it's:", class(ppi_results)))
                                         
                                         # Try to recover from ppi_results_final if it exists
                                         if (exists("ppi_results_final") && is.list(ppi_results_final)) {
                                           print("Recovering from ppi_results_final...")
                                           ppi_results <- ppi_results_final
                                         } else {
                                           print("Creating fallback empty results...")
                                           ppi_results <- list(
                                             error = "PPI results were corrupted during processing",
                                             analysis_type = "ppi"
                                           )
                                         }
                                       }
                                       
                                       # Now continue with the rest of STEP 5
                                       if (!is.null(ppi_results) && is.list(ppi_results)) {
                                         
                                         if ("error" %in% names(ppi_results)) {
                                           # Handle error case
                                           print(paste("❌ PPI Analysis Error:", ppi_results$error))
                                           
                                           isolate({
                                             network_rv$current_results <- ppi_results
                                             network_rv$analysis_status <- "error"
                                             network_rv$analysis_type <- "ppi"
                                             network_rv$available <- FALSE
                                           })
                                           
                                           showNotification(
                                             HTML(paste0("<strong>❌ PPI Analysis Error</strong><br>", ppi_results$error)),
                                             type = "error",
                                             duration = 10
                                           )
                                           
                                         } else {
                                           # Success case
                                           print("🔧 APPLYING PPI RESULTS FIX...")
                                           
                                           # Safely extract fields with NULL checks.
                                           # IMPORTANT: this helper used to selectively copy a handful of
                                           # fields and silently drop anything else — including newly-added
                                           # centrality_measures / drug_targets / hub_consensus /
                                           # druggability_summary. Use a preserve-unknown approach:
                                           # start from the original list, then normalize known fields.
                                           safe_get <- function(x, key, default) {
                                             if (is.list(x) && key %in% names(x)) x[[key]] else default
                                           }
                                           safe_ppi_results <- if (is.list(ppi_results)) ppi_results else list()

                                           # Normalize core fields
                                           safe_ppi_results$ppi_interactions <- safe_get(ppi_results, "ppi_interactions", data.frame())
                                           safe_ppi_results$hub_proteins     <- safe_get(ppi_results, "hub_proteins", data.frame())
                                           safe_ppi_results$network_data     <- safe_get(ppi_results, "network_data",
                                                                                         list(nodes = data.frame(), edges = data.frame()))
                                           safe_ppi_results$network_modules  <- safe_get(ppi_results, "network_modules", NULL)
                                           safe_ppi_results$summary_stats    <- safe_get(ppi_results, "summary_stats", list())
                                           safe_ppi_results$network_metrics  <- safe_get(ppi_results, "network_metrics", list())
                                           safe_ppi_results$functional_enrichment <- safe_get(ppi_results, "functional_enrichment", list())
                                           safe_ppi_results$analysis_params  <- safe_get(ppi_results, "analysis_params", list())
                                           safe_ppi_results$selected_genes   <- safe_get(ppi_results, "selected_genes", list())

                                           # Preserve CytoHubba + druggability additions explicitly
                                           safe_ppi_results$centrality_measures   <- safe_get(ppi_results, "centrality_measures", NULL)
                                           safe_ppi_results$hub_consensus         <- safe_get(ppi_results, "hub_consensus", NULL)
                                           safe_ppi_results$drug_targets          <- safe_get(ppi_results, "drug_targets", data.frame())
                                           safe_ppi_results$druggability_summary  <- safe_get(ppi_results, "druggability_summary", data.frame())
                                           safe_ppi_results$enrichment_results    <- safe_get(ppi_results, "enrichment_results", NULL)
                                           safe_ppi_results$module_enrichment     <- safe_get(ppi_results, "module_enrichment", NULL)
                                           safe_ppi_results$summary               <- safe_get(ppi_results, "summary", NULL)

                                           safe_ppi_results$analysis_type <- "ppi"
                                           
                                           print("📊 PPI Results Summary:")
                                           print(paste("  • Interactions:", nrow(safe_ppi_results$ppi_interactions)))
                                           print(paste("  • Hub Proteins:", nrow(safe_ppi_results$hub_proteins)))
                                           print(paste("  • Network Nodes:", nrow(safe_ppi_results$network_data$nodes)))
                                           
                                           # Store in reactive values
                                           isolate({
                                             network_rv$current_results <- safe_ppi_results
                                             network_rv$ppi_results <- safe_ppi_results
                                             network_rv$analysis_status <- "complete"  # CRITICAL!
                                             network_rv$analysis_type <- "ppi"
                                             network_rv$available <- TRUE
                                           })
                                           
                                           print("✅ PPI Analysis Complete - Results Stored Successfully!")
                                           print(paste("  - Analysis status:", network_rv$analysis_status))
                                           print(paste("  - Analysis type:", network_rv$analysis_type))
                                           
                                           # Success notification
                                           showNotification(
                                             HTML(paste0(
                                               "<strong>✅ PPI Analysis Complete!</strong><br>",
                                               "Found ", nrow(safe_ppi_results$ppi_interactions), " interactions<br>",
                                               "Identified ", nrow(safe_ppi_results$hub_proteins), " proteins"
                                             )),
                                             type = "message",
                                             duration = 10
                                           )
                                           #return(safe_ppi_results)
                                         }
                                       } else {
                                         print("❌ CRITICAL: ppi_results is NULL or not a list in STEP 5")
                                         
                                         isolate({
                                           network_rv$current_results <- list(error = "No valid PPI results", analysis_type = "ppi")
                                           network_rv$analysis_status <- "error"
                                           network_rv$analysis_type <- "ppi"
                                         })
                                       }
                                       
                                     }, error = function(e) {
                                       # Main error handler
                                       print(paste("❌ Fatal error in PPI analysis:", e$message))
                                       
                                       isolate({
                                         network_rv$current_results <- list(
                                           error = e$message,
                                           analysis_type = "ppi"
                                         )
                                         network_rv$analysis_status <- "error"
                                         network_rv$available <- FALSE
                                       })
                                       
                                       showNotification(
                                         HTML(paste0(
                                           "<strong>PPI Analysis Failed</strong><br>",
                                           e$message
                                         )),
                                         type = "error",
                                         duration = 10
                                       )
                                     }
                                     )},
                                   
                                   
                                   
                                   "wgcna" = {
                                     incProgress(0.1, detail = "Building co-expression modules...")

                                     # CRITICAL: load_network_packages() loads STRINGdb / viper /
                                     # dorothea but NOT WGCNA. The downstream pipeline uses
                                     # WGCNA functions unprefixed (pickSoftThreshold, TOMsimilarity,
                                     # cutreeDynamic, moduleEigengenes, mergeCloseModules,
                                     # adjacency, corPvalueStudent, ...) so without an explicit
                                     # library() they all fail with "could not find function" and
                                     # run_wgcna_analysis returns its empty-error stub. The
                                     # standalone WGCNA path doesn't have this bug because it
                                     # explicitly calls library(WGCNA) before its inline pipeline.
                                     suppressPackageStartupMessages({
                                       if (!"WGCNA" %in% loadedNamespaces()) library(WGCNA)
                                     })

                                     wgcna_trace("observer entered | raw_counts_dim=",
                                                 if (!is.null(rv_deg_main$raw_counts))
                                                   paste(dim(rv_deg_main$raw_counts), collapse = "x") else "NULL",
                                                 "| sample_groups_null=", is.null(rv_deg_main$sample_groups),
                                                 "| metadata_raw_null=", is.null(rv_deg_main$metadata_raw),
                                                 "| WGCNA_loaded=", "WGCNA" %in% loadedNamespaces())
                                     print("🧬 Starting WGCNA analysis...")

                                     tryCatch({
                                       # Use raw_counts since normalized_counts doesn't exist
                                       req(rv_deg_main$raw_counts)
                                       expression_data <- rv_deg_main$raw_counts
                                       
                                       print(paste("Using raw_counts for WGCNA"))
                                       print(paste("Expression data dimensions:", paste(dim(expression_data), collapse = " x ")))
                                       print(paste("Expression rownames (first 5):", paste(head(rownames(expression_data), 5), collapse = ", ")))
                                       
                                       # Check if we have enough data for WGCNA
                                       if (ncol(expression_data) < 4) {  # You have 4 samples, which is minimum
                                         stop("❌ Not enough samples for WGCNA analysis. Need at least 6samples, got ", ncol(expression_data))
                                       }
                                       
                                       if (nrow(expression_data) < 1000) {
                                         stop("❌ Not enough genes for WGCNA analysis. Need at least 1000 genes, got ", nrow(expression_data))
                                       }
                                       
                                       print("✅ Data checks passed, proceeding with WGCNA...")
                                       
                                       # Extract clean ENSEMBL IDs from rownames for gene selection
                                       expr_gene_ids <- rownames(expression_data)
                                       clean_gene_ids <- sub("_.*$", "", expr_gene_ids)  # Remove "_red vs green" suffix
                                       clean_gene_ids <- sub("\\..*$", "", clean_gene_ids)  # Remove version numbers
                                       
                                       print(paste("Clean gene IDs (first 5):", paste(head(clean_gene_ids, 5), collapse = ", ")))
                                       
                                       # For WGCNA, select most variable genes instead of DEG-based selection
                                       print("🎯 Selecting most variable genes for WGCNA...")
                                       
                                       if (requireNamespace("DESeq2", quietly = TRUE)) {
                                         print("📊 Using DESeq2 VST for both gene selection AND WGCNA analysis...")
                                         
                                         # Create minimal DESeq2 object for VST
                                         col_data <- data.frame(
                                           condition = factor(rep("sample", ncol(expression_data))),
                                           row.names = colnames(expression_data)
                                         )
                                         
                                         dds <- DESeq2::DESeqDataSetFromMatrix(
                                           countData = round(expression_data),  # Ensure integer counts
                                           colData = col_data,
                                           design = ~ 1
                                         )
                                         
                                         # Apply VST transformation
                                         vst_data <- DESeq2::vst(dds, blind = TRUE)
                                         normalized_for_variance <- SummarizedExperiment::assay(vst_data)
                                         normalized_for_wgcna <- normalized_for_variance  # Same data for both!
                                         
                                         print("✅ VST transformation completed for gene selection and WGCNA")
                                         
                                       } else {
                                         # Fallback: Enhanced log2 transformation
                                         print("📊 Using enhanced log2 transformation for both gene selection AND WGCNA...")
                                         
                                         # Better log2 transformation with proper pseudocount
                                         pseudocount <- median(expression_data[expression_data > 0]) * 0.01
                                         normalized_for_variance <- log2(expression_data + pseudocount)
                                         normalized_for_wgcna <- normalized_for_variance  # Same data for both!
                                       }
                                       
                                       # Calculate variance for each gene
                                       gene_vars <- apply(normalized_for_variance, 1, var, na.rm = TRUE)
                                       gene_vars <- gene_vars[!is.na(gene_vars) & gene_vars > 0]
                                       
                                       # FIRST: Do initial gene selection
                                       top_var_genes <- names(sort(gene_vars, decreasing = TRUE))[1:min(5000, length(gene_vars))]
                                       initial_selected_genes <- intersect(top_var_genes, clean_gene_ids)
                                       
                                       # THEN: Apply sample size constraints
                                       n_samples <- ncol(expression_data)
                                       if (n_samples <= 6) {
                                         if (input$wgcna_auto_gene_selection %||% TRUE) {
                                           max_genes <- min(500, length(initial_selected_genes))  # ✅ Now initial_selected_genes exists!
                                           print(paste("⚠️ Small sample size detected. Limiting to", max_genes, "genes for computational efficiency."))
                                         } else {
                                           max_genes <- min(input$wgcna_max_genes %||% 3000, 500)
                                           print(paste("⚠️ Small sample size detected. User request capped at", max_genes, "genes."))
                                         }
                                       } else {
                                         # Use existing logic for larger sample sizes
                                         if (input$wgcna_auto_gene_selection %||% TRUE) {
                                           # Calculate optimal gene count for larger datasets
                                           optimal_analysis <- calculate_optimal_gene_count(expression_data)
                                           max_genes <- optimal_analysis$optimal_count
                                           print(paste("🤖 Auto-selected gene count:", max_genes, "based on", n_samples, "samples"))
                                         } else {
                                           # Manual selection for larger datasets
                                           max_genes <- input$wgcna_max_genes %||% 3000
                                           print(paste("👤 Using user-specified gene count:", max_genes))
                                         }
                                       }
                                       
                                       # FINALLY: Create final selection with correct count
                                       wgcna_selected_genes <- head(initial_selected_genes, max_genes)
                                       
                                       print(paste("✅ Selected", length(wgcna_selected_genes), "most variable genes for WGCNA"))
                                       print("🔧 Gene selection and WGCNA will use the SAME normalization method")
                                       
                                       # ADD THE NEW CODE HERE:
                                       # Prepare correctly formatted data for WGCNA
                                       print("🔧 Preparing data for WGCNA analysis...")
                                       
                                       # 1. Extract selected genes from normalized data
                                       selected_expression <- normalized_for_wgcna[wgcna_selected_genes, , drop = FALSE]
                                       print(paste("📊 Selected expression data:", nrow(selected_expression), "genes ×", ncol(selected_expression), "samples"))
                                       
                                       # 2. Transpose for WGCNA (samples as rows, genes as columns)
                                       wgcna_input_data <- t(selected_expression)
                                       print(paste("📊 WGCNA input format:", nrow(wgcna_input_data), "samples ×", ncol(wgcna_input_data), "genes"))
                                       
                                       # 3. Validate dimensions before analysis
                                       if (nrow(wgcna_input_data) < 4) {
                                         stop("❌ Not enough samples for WGCNA analysis. Need at least 4 samples, got ", nrow(wgcna_input_data))
                                       }
                                       
                                       if (ncol(wgcna_input_data) < 50) {
                                         stop("❌ Not enough genes for reliable WGCNA analysis. Need at least 50 genes, got ", ncol(wgcna_input_data))
                                       }
                                       
                                       print("✅ Data validation passed - proceeding with WGCNA")
                                       
                                       # 4. Recalculate adaptive defaults with CORRECT gene count
                                       adaptive_defaults <- get_adaptive_wgcna_defaults(
                                         n_samples = nrow(wgcna_input_data),  # Actual sample count (6)
                                         n_genes = ncol(wgcna_input_data)     # Selected gene count (500)
                                       )
                                       
                                       # THEN CONTINUE WITH YOUR EXISTING CODE:
                                       if (input$wgcna_auto_gene_selection %||% TRUE) {
                                         # AUTO MODE: Use adaptive defaults for all parameters
                                         final_min_module_size <- input$wgcna_min_module_size %||% adaptive_defaults$min_module_size
                                         final_max_genes <- max_genes  # Already calculated above
                                         final_merge_threshold <- input$wgcna_merge_threshold %||% adaptive_defaults$merge_threshold
                                       } else {
                                         # MANUAL MODE: Use user inputs with conservative fallbacks
                                         final_min_module_size <- input$wgcna_min_module_size %||% 30
                                         final_max_genes <- max_genes  # Already set to user's choice above
                                         final_merge_threshold <- input$wgcna_merge_threshold %||% 0.25
                                       }
                                       
                                       print(paste("📊 Using adaptive parameters:"))
                                       print(paste("   Min module size:", final_min_module_size))
                                       print(paste("   Max genes:", final_max_genes))
                                       print(paste("   Merge threshold:", final_merge_threshold))
                                       
                                       wgcna_trace("calling run_wgcna_analysis | input_dim=",
                                                   paste(dim(wgcna_input_data), collapse = "x"),
                                                   "| min_module_size=", final_min_module_size,
                                                   "| merge_threshold=", final_merge_threshold,
                                                   "| max_genes=", final_max_genes)
                                       # THEN UPDATE YOUR WGCNA FUNCTION CALL:
                                       wgcna_result <- run_wgcna_analysis(
                                         expression_data = wgcna_input_data,  # ✅ CHANGED: Use prepared data
                                         selected_genes = list(all_genes = wgcna_selected_genes),  # ✅ CHANGED: Proper list format
                                         trait_data = NULL,
                                         soft_power = if(input$wgcna_auto_power %||% TRUE) NULL else input$wgcna_soft_power %||% 6,
                                         min_module_size = final_min_module_size,
                                         merge_threshold = final_merge_threshold,
                                         max_genes = final_max_genes,
                                         organism = input$organism_deg_main %||% "human"
                                       )
                                       
                                       wgcna_trace("run_wgcna_analysis returned | result_null=",
                                                   is.null(wgcna_result),
                                                   "| modules=",
                                                   if (!is.null(wgcna_result$modules)) length(wgcna_result$modules) else 0,
                                                   "| hub_genes=",
                                                   if (!is.null(wgcna_result$hub_genes)) nrow(wgcna_result$hub_genes) else 0,
                                                   "| has_error_field=",
                                                   "error" %in% names(wgcna_result),
                                                   "| error_msg=",
                                                   if ("error" %in% names(wgcna_result)) as.character(wgcna_result$error) else "(none)")
                                       print("✅ WGCNA analysis completed successfully!")

                                       # CALL THIS in your WGCNA analysis after enrichment:
                                       print("🔍 About to debug enrichment data...")
                                       debug_enrichment_data(wgcna_result$module_enrichment)
                                       
                                       
                                       
                                       wgcna_trace("entering post-WGCNA processing branch")
                                       if (!is.null(wgcna_result) && !is.null(wgcna_result$modules)) {

                                         print("🔧 Fixing enrichment column names for module categorization...")
                                         
                                         for (module_name in names(wgcna_result$module_enrichment)) {
                                           if (!is.null(wgcna_result$module_enrichment[[module_name]])) {
                                             enrich_data <- wgcna_result$module_enrichment[[module_name]]
                                             
                                             # Skip if empty
                                             if (nrow(enrich_data) == 0) next
                                             
                                             # Fix 1: Rename Adjusted.P.value → adj_pval
                                             if ("Adjusted.P.value" %in% colnames(enrich_data) && !"adj_pval" %in% colnames(enrich_data)) {
                                               enrich_data$adj_pval <- enrich_data$Adjusted.P.value
                                               print(paste("  ✅", module_name, ": Added 'adj_pval' column"))
                                             }
                                             
                                             # Fix 2: Extract gene count from Overlap column
                                             # Overlap format is "23/176" → we want the first number (23)
                                             if ("Overlap" %in% colnames(enrich_data) && !"gene_count" %in% colnames(enrich_data)) {
                                               enrich_data$gene_count <- as.numeric(sapply(strsplit(enrich_data$Overlap, "/"), `[`, 1))
                                               print(paste("  ✅", module_name, ": Added 'gene_count' column from Overlap"))
                                             }
                                             
                                             # Update the enrichment data
                                             wgcna_result$module_enrichment[[module_name]] <- enrich_data
                                           }
                                         }
                                         print("✅ Column name fixes complete!")
                                         
                                         wgcna_trace("about to convert hub gene IDs to symbols (organism=mouse)")
                                         print("🔄 Converting hub gene IDs to symbols...")
                                         wgcna_result$hub_genes <- convert_hub_genes_to_symbols(
                                           hub_genes = wgcna_result$hub_genes,
                                           organism = "mouse"  # Change to "human" if needed
                                         )
                                         wgcna_trace("hub gene conversion done | hub_genes nrow=",
                                                     if (!is.null(wgcna_result$hub_genes)) nrow(wgcna_result$hub_genes) else 0)
                                         
                                         wgcna_trace("about to call analyze_module_categories_with_confidence")
                                         print("Generating enhanced module summaries...")

                                         # Generate functional summaries using your new functions
                                         module_summaries <- analyze_module_categories_with_confidence(
                                           modules = wgcna_result$modules,
                                           module_enrichment = wgcna_result$module_enrichment,
                                           hub_genes = wgcna_result$hub_genes
                                         )
                                         wgcna_trace("module_summaries built | n=",
                                                     if (!is.null(module_summaries)) length(module_summaries) else 0)
                                         
                                         # Add this debug print:
                                         print("🔍 Module summaries completed")
                                         print(paste("🔍 Number of module summaries:", length(module_summaries)))
                                         
                                         # Create enhanced summary table WITH SYMBOLS
                                         enhanced_summary_table <- create_evidence_based_summary_table(
                                           module_analyses = module_summaries,
                                           hub_genes_converted = wgcna_result$hub_genes
                                         )
                                         print("🔍 DEBUG: Checking wgcna_result structure...")
                                         print(paste("Soft Power:", wgcna_result$analysis_params$soft_power))
                                         print(paste("N Modules:", wgcna_result$analysis_params$n_modules))
                                         print(paste("N Samples:", wgcna_result$analysis_params$n_samples))
                                         print(paste("N Genes:", wgcna_result$analysis_params$n_genes))
                                         
                                         print("Checking for trait data for module-trait correlation...")
                                         
                                         if (input$wgcna_enable_trait_analysis %||% FALSE) {
                                           
                                           print("User enabled module-trait analysis...")
                                           
                                           # Check if properly configured
                                           if (trait_rv$configured && !is.null(trait_rv$raw_data)) {
                                             
                                             print(paste("Running module-trait analysis with", 
                                                         length(trait_rv$trait_columns), "traits"))
                                             print(paste("Sample ID column:", trait_rv$sample_id_column))
                                             print(paste("Trait columns:", paste(trait_rv$trait_columns, collapse = ", ")))
                                             
                                             module_trait_result <- tryCatch({
                                               perform_module_trait_analysis(
                                                 wgcna_result = wgcna_result,
                                                 trait_metadata = trait_rv$raw_data,
                                                 selected_trait_columns = trait_rv$trait_columns,
                                                 sample_id_column = trait_rv$sample_id_column  
                                               )
                                             }, error = function(e) {
                                               print(paste("Module-trait analysis error:", e$message))
                                               list(has_results = FALSE, message = e$message)
                                             })
                                             
                                             wgcna_result$module_trait_analysis <- module_trait_result
                                             
                                           } else {
                                             print("Module-trait analysis enabled but not configured")
                                             wgcna_result$module_trait_analysis <- list(
                                               has_results = FALSE,
                                               message = "Metadata not configured. Click 'Configure Traits' button."
                                             )
                                           }
                                           
                                         } else {
                                           # Module-trait analysis checkbox is unchecked: do nothing.
                                           # The previous auto-derive-from-DEG-metadata branch was
                                           # removed because it ran trait analysis even when the user
                                           # had explicitly opted out, which violated the checkbox
                                           # contract.
                                           print("Module-trait analysis disabled by user (checkbox unchecked); skipping.")
                                           wgcna_result$module_trait_analysis <- list(has_results = FALSE)
                                         }


                                         wgcna_trace("about to assemble safe_wgcna_results")
                                         print("🔧 APPLYING WGCNA RESULTS FIX...")

                                         safe_wgcna_results <- list(
                                           # Core WGCNA data
                                           modules = wgcna_result$modules %||% list(),
                                           module_colors = wgcna_result$module_colors %||% character(),
                                           hub_genes = wgcna_result$hub_genes %||% data.frame(),
                                           module_eigengenes = wgcna_result$module_eigengenes %||% data.frame(),
                                           module_trait_correlations = wgcna_result$module_trait_correlations %||% data.frame(),
                                           module_enrichment = wgcna_result$module_enrichment %||% list(),
                                           module_trait_analysis = wgcna_result$module_trait_analysis %||% list(has_results = FALSE),
                                           # NEW: Enhanced features
                                           module_summaries = module_summaries,
                                           enhanced_summary_table = enhanced_summary_table,

                                           # Soft-threshold diagnostics (for S7A plot)
                                           softPower = wgcna_result$softPower %||% wgcna_result$analysis_params$soft_power,
                                           soft_power_diagnostics = wgcna_result$soft_power_diagnostics,

                                           # DENDROGRAM DATA (for Gene Dendrogram tab)
                                           dendrogram = wgcna_result$dendrogram,
                                           module_colors_vector = wgcna_result$module_colors_vector %||% wgcna_result$module_colors,
                                           
                                           # Network visualization data
                                           network_data = wgcna_result$network_data %||% list(
                                             nodes = data.frame(id = character(0), label = character(0)),
                                             edges = data.frame(from = character(0), to = character(0))
                                           ),
                                           
                                           # ⭐ CRITICAL: Set analysis_type to "wgcna" (NOT "drug_target" or anything else)
                                           analysis_type = "wgcna",
                                           
                                           # Analysis parameters
                                           analysis_params = list(
                                             analysis_type = "wgcna",
                                             soft_power = wgcna_result$analysis_params$soft_power %||% 
                                               wgcna_result$soft_power %||% 14,
                                             min_module_size = wgcna_result$analysis_params$min_module_size %||% 30,
                                             merge_threshold = wgcna_result$analysis_params$merge_threshold %||% 0.25,
                                             n_genes = wgcna_result$analysis_params$n_genes %||% 3000,        # ✅ CORRECT: separate genes count
                                             n_samples = wgcna_result$analysis_params$n_samples %||% 6,       # Samples (15)
                                             n_modules = length(wgcna_result$modules) %||% 0,
                                             scale_free_r2 = wgcna_result$analysis_params$scale_free_r2 %||% 0.8,
                                             mean_connectivity = wgcna_result$metrics$topology$mean_connectivity %||% 0,
                                             total_hub_genes = nrow(wgcna_result$hub_genes) %||% 0,
                                             deg_hub_genes = sum(wgcna_result$hub_genes$is_deg, na.rm = TRUE) %||% 0,
                                             analysis_timestamp = wgcna_result$analysis_params$analysis_timestamp %||% Sys.time()
                                           )
                                         )
                                         
                                         print("📊 WGCNA Results Summary:")
                                         print(paste("  • Modules:", length(safe_wgcna_results$modules)))
                                         print(paste("  • Hub Genes:", nrow(safe_wgcna_results$hub_genes)))
                                         print(paste("  • Analysis Type:", safe_wgcna_results$analysis_type))
                                         
                                         print("🔍 DEBUG: Checking analysis_params...")
                                         print(paste("  • soft_power:", safe_wgcna_results$analysis_params$soft_power))
                                         print(paste("  • n_modules:", safe_wgcna_results$analysis_params$n_modules))
                                         print(paste("  • n_samples:", safe_wgcna_results$analysis_params$n_samples))
                                         print(paste("  • n_genes:", safe_wgcna_results$analysis_params$n_genes))
                                         print(paste("  • scale_free_r2:", safe_wgcna_results$analysis_params$scale_free_r2))
                                         
                                         wgcna_trace("safe_wgcna_results assembled — assigning to network_rv")
                                         # CRITICAL: Use isolate() to safely assign results
                                         isolate({
                                           network_rv$current_results <- safe_wgcna_results
                                           network_rv$analysis_status <- "complete"  # ← This is the key fix!
                                           network_rv$analysis_end_time <- Sys.time()
                                         })
                                         wgcna_trace("WGCNA SUCCESS — UI should show results")
                                         print("✅ WGCNA results successfully assigned!")
                                         print(paste("✅ Status updated to:", network_rv$analysis_status))
                                         
                                         # Show success notification
                                         showNotification(
                                           "✅ WGCNA analysis completed! Check the results tabs below.",
                                           type = "message",
                                           duration = 5
                                         )
                                         
                                       } else {
                                         wgcna_trace("PIPELINE BRANCH: wgcna_result is NULL or has no $modules — entering failure notification path")
                                         print("❌ WGCNA analysis failed - no valid results returned")

                                         isolate({
                                           network_rv$analysis_status <- "error"
                                           network_rv$current_results <- NULL
                                         })

                                         showNotification(
                                           "❌ WGCNA analysis failed. Please check your data and try again.",
                                           type = "error",
                                           duration = 10
                                         )
                                       }
                                       return(wgcna_result)

                                     }, error = function(e) {
                                       wgcna_trace("OUTER tryCatch ERROR: ", e$message)
                                       print(paste("❌ WGCNA analysis failed:", e$message))
                                       print("📍 Full error details:")
                                       print(e)
                                       print("📍 Traceback:")
                                       print(traceback())
                                       
                                       # Return a structured error instead of crashing
                                       return(list(
                                         error = paste("WGCNA analysis failed:", e$message),
                                         details = list(
                                           expression_data_available = !is.null(rv_deg_main$raw_counts),
                                           expression_dims = if(!is.null(rv_deg_main$raw_counts)) dim(rv_deg_main$raw_counts) else "NULL",
                                           error_message = e$message
                                         )
                                       ))
                                     })
                                   },
                                   
                                   "deconv" = {
                                     print("🧬 Running cell type deconvolution...")
                                     
                                     # ============================================================================
                                     # CORRECTED: DEG Filtering for Advanced Analysis Deconvolution
                                     # Matches your existing filter_significant_genes logic exactly
                                     # ============================================================================
                                     
                                     # In your observeEvent(input$run_network_analysis, {...})
                                     # Find the section where network_analysis_type_systems == "deconv"
                                     
                                     if (input$network_analysis_type_systems == "deconv") {
                                       print("🧬 Running Advanced cell type deconvolution with DEG context...")
                                       
                                       print("🔍 PRE-FLIGHT CHECK:")
                                       print(paste("   raw_counts exists:", !is.null(rv_deg_main$raw_counts)))
                                       if (!is.null(rv_deg_main$raw_counts)) {
                                         print(paste("   raw_counts dims:", paste(dim(rv_deg_main$raw_counts), collapse = " x ")))
                                       }
                                       
                                       print(paste("   normalized_counts exists:", !is.null(rv_deg_main$normalized_counts)))
                                       if (!is.null(rv_deg_main$normalized_counts)) {
                                         print(paste("   normalized_counts dims:", paste(dim(rv_deg_main$normalized_counts), collapse = " x ")))
                                         print(paste("   normalized_counts samples:", paste(head(colnames(rv_deg_main$normalized_counts), 5), collapse = ", ")))
                                       } else {
                                         print("   ❌ CRITICAL: normalized_counts is NULL!")
                                         print("   🔧 Attempting to create it now...")
                                         
                                         if (!is.null(rv_deg_main$raw_counts)) {
                                           norm_method <- input$normalization_method_main %||% "TMM"
                                           data_for_norm <- as.data.frame(rv_deg_main$raw_counts)
                                           rv_deg_main$normalized_counts <- normalizeData(data_for_norm, norm_method)
                                           print("   ✅ Created normalized_counts on-the-fly")
                                         }
                                       }
                                       
                                       print(paste("   deg_results exists:", !is.null(rv_deg_main$deg_results)))
                                       print(paste("   sample_groups exists:", !is.null(rv_deg_main$sample_groups)))
                                       
                                       if (is.null(rv_deg_main$normalized_counts)) {
                                         showNotification(
                                           "❌ Cannot run deconvolution: normalized expression data not available. Please run QC or DEG analysis first.",
                                           type = "error",
                                           duration = 10
                                         )
                                         return()
                                       }
                                       
                                       # ========================================================================
                                       # FILTER FOR SIGNIFICANT DEGs USING YOUR EXISTING LOGIC
                                       # ========================================================================
                                       
                                       deg_data_for_deconv <- NULL
                                       
                                       if (!is.null(deg_data()) && nrow(deg_data()) > 0) {
                                         
                                         deg_table <- deg_data()
                                         
                                         print("📊 FILTERING DEGs FOR DECONVOLUTION")
                                         print(paste("Total genes in dataset:", nrow(deg_table)))
                                         print(paste("Available columns:", paste(colnames(deg_table), collapse = ", ")))
                                         
                                         # ====================================================================
                                         # GET FILTER PARAMETERS (same as your main DEG filtering)
                                         # ====================================================================
                                         
                                         pvalue_type <- input$pvalue_type_main %||% "adjusted"
                                         p_threshold <- input$p_val_threshold_main %||% 0.05
                                         log2fc_min <- input$log2fc_min %||% -2
                                         log2fc_max <- input$log2fc_max %||% 2
                                         
                                         print(paste("🔍 Filter Parameters:"))
                                         print(paste("   - P-value type:", pvalue_type))
                                         print(paste("   - P-value threshold: <", p_threshold))
                                         print(paste("   - Log2FC outside range: [", log2fc_min, ",", log2fc_max, "]"))
                                         
                                         # ====================================================================
                                         # DETERMINE P-VALUE COLUMN (adjusted vs raw)
                                         # ====================================================================
                                         
                                         if (pvalue_type == "adjusted") {
                                           # Try multiple column names for adjusted p-values
                                           if ("adj.P.Val" %in% colnames(deg_table)) {
                                             pval_col <- "adj.P.Val"
                                           } else if ("padj" %in% colnames(deg_table)) {
                                             pval_col <- "padj"
                                           } else if ("FDR" %in% colnames(deg_table)) {
                                             pval_col <- "FDR"
                                           } else {
                                             print("❌ ERROR: Adjusted p-value column not found!")
                                             print(paste("   Available columns:", paste(colnames(deg_table), collapse = ", ")))
                                             showNotification(
                                               "Cannot find adjusted p-value column. Check your DEG results format.",
                                               type = "error",
                                               duration = 10
                                             )
                                             return()
                                           }
                                         } else {
                                           # Try multiple column names for raw p-values
                                           if ("P.Value" %in% colnames(deg_table)) {
                                             pval_col <- "P.Value"
                                           } else if ("pvalue" %in% colnames(deg_table)) {
                                             pval_col <- "pvalue"
                                           } else if ("PValue" %in% colnames(deg_table)) {
                                             pval_col <- "PValue"
                                           } else {
                                             print("❌ ERROR: Raw p-value column not found!")
                                             showNotification(
                                               "Cannot find p-value column. Check your DEG results format.",
                                               type = "error",
                                               duration = 10
                                             )
                                             return()
                                           }
                                         }
                                         
                                         print(paste("✅ Using p-value column:", pval_col))
                                         
                                         # ====================================================================
                                         # DETERMINE FOLD CHANGE COLUMN
                                         # ====================================================================
                                         
                                         if ("log2FC" %in% colnames(deg_table)) {
                                           fc_col <- "log2FC"
                                         } else if ("log2FoldChange" %in% colnames(deg_table)) {
                                           fc_col <- "log2FoldChange"
                                         } else if ("logFC" %in% colnames(deg_table)) {
                                           fc_col <- "logFC"
                                         } else {
                                           print("❌ ERROR: Fold change column not found!")
                                           showNotification(
                                             "Cannot find log2FC column. Check your DEG results format.",
                                             type = "error",
                                             duration = 10
                                           )
                                           return()
                                         }
                                         
                                         print(paste("✅ Using fold change column:", fc_col))
                                         
                                         # ====================================================================
                                         # APPLY FILTERING (exact same logic as filter_significant_genes)
                                         # ====================================================================
                                         
                                         pval_values <- as.numeric(deg_table[[pval_col]])
                                         fc_values <- as.numeric(deg_table[[fc_col]])
                                         
                                         # Create significance mask
                                         significant_mask <- !is.na(pval_values) & 
                                           !is.na(fc_values) &
                                           pval_values < p_threshold &
                                           (fc_values < log2fc_min | fc_values > log2fc_max)
                                         
                                         # Filter the data
                                         deg_data_for_deconv <- deg_table[significant_mask, ]
                                         
                                         n_total <- nrow(deg_table)
                                         n_significant <- nrow(deg_data_for_deconv)
                                         n_up <- sum(deg_data_for_deconv[[fc_col]] > 0, na.rm = TRUE)
                                         n_down <- sum(deg_data_for_deconv[[fc_col]] < 0, na.rm = TRUE)
                                         
                                         print(paste("✅ Filtered to", nrow(deg_data_for_deconv), "significant DEGs"))
                                         print(paste("   - Upregulated:", sum(deg_data_for_deconv[[fc_col]] > 0, na.rm = TRUE)))
                                         print(paste("   - Downregulated:", sum(deg_data_for_deconv[[fc_col]] < 0, na.rm = TRUE)))
                                         
                                         
                                         if (nrow(deg_data_for_deconv) == 0) {
                                           showNotification(
                                             "No significant DEGs found with current thresholds. Adjust p-value or log2FC thresholds.",
                                             type = "error",
                                             duration = 10
                                           )
                                           return()
                                         }
                                       }
                                       
                                     } else {
                                       print("⚠️ No DEG data available - running without DEG context")
                                     }
                                     
                                     if (!is.null(deg_data)) {
                                       print(paste("🎯 ADVANCED ANALYSIS MODE: DEG-Contextualized Deconvolution"))
                                       print(paste("   Will link", nrow(deg_data), "significant DEGs to cell types"))
                                     } else {
                                       print(paste("📊 EXPLORATORY MODE: General cell type composition"))
                                       print(paste("   No DEG context - showing overall cell type distribution"))
                                     }
                                     
                                     print("🔍 VALIDATING SAMPLE GROUPS BEFORE DECONVOLUTION...")
                                     
                                     # Get samples from normalized counts
                                     expression_samples <- colnames(rv_deg_main$normalized_counts)
                                     print(paste("   Expression matrix samples:", length(expression_samples)))
                                     print(paste("   First 5 samples:", paste(head(expression_samples, 5), collapse = ", ")))
                                     
                                     # Validate sample_groups structure
                                     validated_sample_groups <- NULL
                                     
                                     if (!is.null(rv_deg_main$sample_groups)) {
                                       print("   Sample groups provided by user")
                                       
                                       # Check if it's a data.frame with correct structure
                                       if (is.data.frame(rv_deg_main$sample_groups) && 
                                           "sample" %in% colnames(rv_deg_main$sample_groups) && 
                                           "group" %in% colnames(rv_deg_main$sample_groups)) {
                                         
                                         # Get samples from sample_groups
                                         group_samples <- rv_deg_main$sample_groups$sample
                                         print(paste("   Sample groups has:", length(group_samples), "samples"))
                                         print(paste("   First 5 from groups:", paste(head(group_samples, 5), collapse = ", ")))
                                         
                                         # Find common samples
                                         common_samples <- intersect(expression_samples, group_samples)
                                         print(paste("   ✅ Common samples:", length(common_samples)))
                                         
                                         if (length(common_samples) < 2) {
                                           showNotification(
                                             "Error: Sample names in expression matrix don't match sample groups. Check your sample naming!",
                                             type = "error",
                                             duration = 10
                                           )
                                           print("   ❌ MISMATCH DETAILS:")
                                           print("   Expression samples (first 10):")
                                           print(head(expression_samples, 10))
                                           print("   Group samples (first 10):")
                                           print(head(group_samples, 10))
                                           return()
                                         }
                                         
                                         # Filter sample_groups to only include common samples
                                         validated_sample_groups <- rv_deg_main$sample_groups[
                                           rv_deg_main$sample_groups$sample %in% common_samples, 
                                         ]
                                         
                                         # Also subset the expression matrix to common samples
                                         rv_deg_main$normalized_counts <- rv_deg_main$normalized_counts[, common_samples, drop = FALSE]
                                         
                                         print(paste("   ✅ Validated:", nrow(validated_sample_groups), "samples with groups"))
                                         print(paste("   Groups:", paste(unique(validated_sample_groups$group), collapse = ", ")))
                                         
                                       } else {
                                         print("   ⚠️ Sample groups not in correct format (need data.frame with 'sample' and 'group' columns)")
                                         print("   Will try to auto-detect groups from sample names")
                                         validated_sample_groups <- NULL
                                       }
                                       
                                     } else {
                                       print("   No sample groups provided - will auto-detect from naming")
                                     }
                                     
                                     deconv_results <- perform_deconvolution_analysis(
                                       expression_matrix = rv_deg_main$normalized_counts,
                                       method = input$deconv_method %||% "xcell",
                                       organism = input$organism_deg_main,
                                       deg_data = deg_data_for_deconv,
                                       #sample_groups = rv_deg_main$sample_groups
                                       sample_groups = validated_sample_groups
                                     )
                                     if (!is.null(deconv_results)) {
                                       print("📊 Storing deconvolution results...")
                                       
                                       # Store in the reactive value
                                       network_rv$current_results <- deconv_results
                                       network_rv$analysis_type <- "deconv"
                                       network_rv$analysis_status <- "complete"
                                       
                                       # Also store in deconv-specific storage for later retrieval
                                       network_rv$deconv_results <- deconv_results
                                       
                                       print("✅ Results stored successfully")
                                       print(paste("   - Analysis type:", network_rv$analysis_type))
                                       print(paste("   - Cell types:", deconv_results$summary_stats$deconv$total_cell_types))
                                       print(paste("   - Marker genes:", deconv_results$summary_stats$deconv$marker_genes))
                                       
                                       # Show success notification
                                       showNotification(
                                         HTML(paste0(
                                           "<strong>✅ Deconvolution Complete!</strong><br>",
                                           "• ", deconv_results$summary_stats$deconv$total_cell_types, " cell types identified<br>",
                                           "• ", deconv_results$summary_stats$deconv$marker_genes, " DEGs linked to cell types<br>",
                                           "• Confidence: ", deconv_results$summary_stats$deconv$confidence_score, "%"
                                         )),
                                         type = "message",
                                         duration = 10
                                       )
                                       
                                     } else {
                                       print("❌ Deconvolution returned NULL")
                                       network_rv$analysis_status <- "error"
                                       network_rv$error_message <- "Deconvolution analysis failed"
                                       
                                       showNotification(
                                         "Deconvolution analysis failed. Check console for details.",
                                         type = "error",
                                         duration = 10
                                       )
                                     }
                                   },
                                   # Default fallback
                                   {
                                     print("Using debug analysis for unknown type")
                                     debug_drug_target_analysis(network_rv$selected_genes, analysis_focus)
                                   }
        )
        
        
        incProgress(0.5, detail = "Processing results...")
        
        # Check which analysis type we just completed
        current_analysis_type <- input$network_analysis_type_systems
        
        # Special handling for analyses that manage their own results storage
        if (current_analysis_type == "grn") {
          # GRN already stored everything it needs
          print("✅ GRN analysis complete - results already stored internally")
          # Skip the rest of the processing
          
        } else if (current_analysis_type == "ppi" && isTRUE(network_rv$analysis_status == "complete")) {
          # PPI also handles its own storage
          print("✅ PPI analysis complete - results already stored internally")
          
        } else if (current_analysis_type == "wgcna") {
          # WGCNA handles its own storage
          print("✅ WGCNA analysis complete - checking results...")
          if (!is.null(network_rv$current_results)) {
            network_rv$wgcna_results <- network_rv$current_results
            print("✅ WGCNA results cached")
          }
          
        } else if (current_analysis_type == "drug_target") {
          # Drug target analysis uses the standard flow with analysis_results
          
          if (exists("analysis_results") && !is.null(analysis_results)) {
            
            # Your existing disease context debugging
            if (!is.null(analysis_results$analysis_params)) {
              print("=== DISEASE CONTEXT DEBUGGING ===")
              print(paste("Analysis focus:", analysis_results$analysis_params$analysis_focus %||% "unknown"))
              
              if (!is.null(analysis_results$opentargets_data)) {
                print(paste("OpenTargets data rows:", nrow(analysis_results$opentargets_data)))
              } else {
                print("❌ NO opentargets_data found!")
              }
              
              if (!is.null(analysis_results$drug_targets)) {
                print(paste("Drug targets data rows:", nrow(analysis_results$drug_targets)))
              } else {
                print("❌ NO drug_targets found!")
              }
              
              print("=== END DISEASE CONTEXT DEBUGGING ===")
            }
            
            # Drug discovery specific processing
            if (analysis_focus == "drug_discovery" && !is.null(analysis_results$drug_targets)) {
              print("=== DRUG DATA DIAGNOSIS ===")
              drug_data <- analysis_results$drug_targets
              
              print(paste("Total rows:", nrow(drug_data)))
              print(paste("Column names:", paste(colnames(drug_data), collapse = ", ")))
              
              # Show sample data
              print("Sample data (first 3 rows):")
              if (nrow(drug_data) > 0) {
                print(drug_data[1:min(3, nrow(drug_data)), 1:min(6, ncol(drug_data))])
              }
              
              # Check for unique drugs
              if ("molecule_name" %in% colnames(drug_data)) {
                non_null_drugs <- drug_data$molecule_name[!is.na(drug_data$molecule_name) & drug_data$molecule_name != ""]
                unique_drugs <- length(unique(non_null_drugs))
                print(paste("Non-null molecule names:", length(non_null_drugs)))
                print(paste("Unique drugs found:", unique_drugs))
                if (length(non_null_drugs) > 0) {
                  print(paste("Sample drug names:", paste(head(unique(non_null_drugs), 3), collapse = ", ")))
                }
              } else {
                print("Column 'molecule_name' not found!")
              }
              
              # Check for unique targets
              if ("gene_name" %in% colnames(drug_data)) {
                non_null_targets <- drug_data$gene_name[!is.na(drug_data$gene_name) & drug_data$gene_name != ""]
                unique_targets <- length(unique(non_null_targets))
                print(paste("Non-null gene names:", length(non_null_targets)))
                print(paste("Unique targets found:", unique_targets))
                if (length(non_null_targets) > 0) {
                  print(paste("Sample target names:", paste(head(unique(non_null_targets), 3), collapse = ", ")))
                }
              } else {
                print("Column 'gene_name' not found!")
              }
              
              # Check confidence scores
              if ("confidence_score" %in% colnames(drug_data)) {
                valid_scores <- drug_data$confidence_score[!is.na(drug_data$confidence_score)]
                print(paste("Valid confidence scores:", length(valid_scores)))
                if (length(valid_scores) > 0) {
                  print(paste("Confidence score range:", min(valid_scores), "to", max(valid_scores)))
                  high_conf <- sum(valid_scores > 0.7)
                  print(paste("High confidence interactions (>0.7):", high_conf))
                }
              } else {
                print("Column 'confidence_score' not found!")
              }
              
              # Check clinical phases
              if ("clinical_phase" %in% colnames(drug_data)) {
                valid_phases <- drug_data$clinical_phase[!is.na(drug_data$clinical_phase)]
                print(paste("Valid clinical phases:", length(valid_phases)))
                if (length(valid_phases) > 0) {
                  print("Clinical phase distribution:")
                  print(table(valid_phases))
                }
              } else {
                print("Column 'clinical_phase' not found!")
              }
              
              print("=== END DRUG DATA DIAGNOSIS ===")
            }
            
            # Ensure drug_prioritization exists
            if (is.null(analysis_results$drug_prioritization) ||
                nrow(analysis_results$drug_prioritization) == 0) {
              
              print("Creating missing drug prioritization data...")
              
              if (!is.null(analysis_results$drug_targets) && nrow(analysis_results$drug_targets) > 0) {
                analysis_results$drug_prioritization <- create_drug_prioritization_data_fixed(
                  analysis_results$drug_targets,
                  analysis_focus
                )
              }
            }
            
            # Store results
            tryCatch({
              # SAFE ASSIGNMENT: Ensure all required fields exist
              safe_results <- list(
                chembl_data = analysis_results$chembl_data %||% data.frame(),
                opentargets_data = analysis_results$opentargets_data %||% data.frame(),
                raw_data = analysis_results$raw_data %||% data.frame(),
                network_data = analysis_results$network_data %||% list(
                  nodes = data.frame(id = character(0), label = character(0), stringsAsFactors = FALSE),
                  edges = data.frame(from = character(0), to = character(0), stringsAsFactors = FALSE)
                ),
                summary = analysis_results$summary %||% list(
                  total_drugs = 0,
                  total_targets = 0,
                  total_nodes = 0,
                  total_edges = 0,
                  network_density = 0,
                  chembl = list(total_interactions = 0, unique_drugs = 0, druggable_targets = 0)
                ),
                drug_targets = analysis_results$drug_targets %||% data.frame(),
                drug_prioritization = analysis_results$drug_prioritization %||% data.frame(),
                integrated_insights = analysis_results$integrated_insights %||% list(),
                conversion_stats = analysis_results$conversion_stats %||% list(),
                analysis_type = "drug_target",
                analysis_params = analysis_results$analysis_params %||% list(analysis_focus = analysis_focus)
              )
              
              print("=== SAFE ASSIGNMENT DEBUG ===")
              print(paste("safe_results$chembl_data rows:", nrow(safe_results$chembl_data)))
              print(paste("safe_results$opentargets_data rows:", nrow(safe_results$opentargets_data)))
              print(paste("safe_results$raw_data rows:", nrow(safe_results$raw_data)))
              
              isolate({
                network_rv$current_results <- safe_results
                network_rv$drug_target_results <- safe_results
                network_rv$analysis_status <- "complete"
                network_rv$analysis_end_time <- Sys.time()
              })
              
              print("✅ Drug-target results stored successfully")
              
            }, error = function(e) {
              print(paste("Error storing drug-target results:", e$message))
              network_rv$analysis_status <- "error"
              showNotification("Error storing analysis results", type = "error")
            })
            
          } else {
            print("⚠️ No analysis_results for drug_target")
            network_rv$analysis_status <- "error"
            showNotification("Drug-target analysis failed to return results", type = "error")
          }
        }
        
        # Step 3: Show success notification
        incProgress(1.0, detail = "Analysis complete!")
        
        showNotification(
          "Network analysis completed successfully!",
          type = "message",
          duration = 5
        )
        
      }, error = function(e) {
        print(paste("Error in analysis or assignment:", e$message))
        print("Full error traceback:")
        print(traceback())
        
        # SAFE ERROR HANDLING
        isolate({
          network_rv$analysis_status <- "error"
          network_rv$current_results <- NULL
        })
        
        showNotification(
          paste("Analysis failed:", e$message),
          type = "error",
          duration = 10
        )
      })
    })
  })
  
  
  
  if (!exists("clean_gene_ids")) {
    clean_gene_ids <- function(gene_ids) {
      # Remove version numbers from Ensembl IDs
      cleaned <- gsub("\\.\\d+$", "", gene_ids)
      # Remove any remaining special characters
      cleaned <- gsub("[^A-Za-z0-9-]", "", cleaned)
      return(cleaned)
    }
  }
  
  
  # Function to prepare GRN gene selection (add if missing)
  if (!exists("prepare_grn_gene_selection_corrected")) {
    prepare_grn_gene_selection_corrected <- function(deg_results, up_genes_from_table, down_genes_from_table) {
      list(
        all_genes = unique(c(up_genes_from_table, down_genes_from_table)),
        up_genes = up_genes_from_table,
        down_genes = down_genes_from_table,
        n_up = length(up_genes_from_table),
        n_down = length(down_genes_from_table),
        n_total = length(unique(c(up_genes_from_table, down_genes_from_table)))
      )
    }
  }
  
  # Function to validate GRN inputs (add if missing)
  if (!exists("validate_grn_inputs")) {
    validate_grn_inputs <- function(selected_genes, organism, tf_database, confidence_level) {
      errors <- c()
      
      if (is.null(selected_genes) || selected_genes$n_total == 0) {
        errors <- c(errors, "No genes selected")
      }
      
      if (!(organism %in% c("human", "mouse"))) {
        errors <- c(errors, "Invalid organism")
      }
      
      if (!(tf_database %in% c("dorothea", "collectri"))) {
        errors <- c(errors, "Invalid TF database")
      }
      
      if (confidence_level < 0 || confidence_level > 1) {
        errors <- c(errors, "Confidence level must be between 0 and 1")
      }
      
      list(
        valid = length(errors) == 0,
        errors = errors
      )
    }
  }
  
  # Dynamic confidence level display
  output$confidence_level_display <- renderUI({
    conf_val <- input$ppi_confidence_threshold %||% 0.4
    
    if (conf_val <= 0.25) {
      div(class = "text-warning", icon("exclamation-triangle"), "Low confidence - more interactions, less reliable")
    } else if (conf_val <= 0.5) {
      div(class = "text-info", icon("info-circle"), "Medium confidence - balanced trade-off")
    } else if (conf_val <= 0.7) {
      div(class = "text-primary", icon("thumbs-up"), "High confidence - fewer but reliable interactions")
    } else {
      div(class = "text-success", icon("star"), "Very high confidence - most reliable interactions only")
    }
  })
  
  
