  # ===== KEY FINDINGS TAB OUTPUTS =====
  
  
  # Executive Summary Text
  output$grn_executive_summary <- renderUI({
    req(network_rv$grn_results)
    
    grn <- network_rv$grn_results
    params <- grn$analysis_params
    master_regs <- grn$master_regulators
    
    if (is.null(master_regs) || nrow(master_regs) == 0) {
      return(p("Analysis results are being processed..."))
    }
    
    top_tf <- master_regs$label[1]
    n_tfs <- params$n_tfs %||% nrow(master_regs)
    n_regs <- params$n_regulations %||% nrow(grn$tf_regulations)
    
    # Calculate activation percentage
    act_pct <- if (!is.null(grn$tf_regulations) && "mor" %in% colnames(grn$tf_regulations)) {
      round(mean(grn$tf_regulations$mor == 1, na.rm = TRUE) * 100)
    } else { 50 }
    
    div(
      p(style = "font-size: 1.1em; line-height: 1.6; margin: 0;",
        "Your analysis identified ", strong(n_tfs), " transcription factors controlling ",
        strong(n_regs), " regulatory interactions. ",
        "The network shows ", strong(paste0(act_pct, "%")), " activating relationships. ",
        strong(top_tf), " emerges as the top master regulator with the highest regulatory influence."
      )
    )
  })
  
  # Key TF Name
  output$grn_key_tf_name <- renderText({
    req(network_rv$grn_results$master_regulators)
    network_rv$grn_results$master_regulators$label[1]
  })
  
  # Network Scale - FIXED (no unicode arrow)
  output$kf_network_scale <- renderText({
    req(network_rv$grn_results)
    params <- network_rv$grn_results$analysis_params
    paste0(params$n_tfs %||% 0, " -> ", params$n_regulations %||% 0)
  })
  
  output$kf_network_detail <- renderText({
    "TFs to regulatory interactions"
  })
  
  # Master Count
  output$kf_master_count <- renderText({
    req(network_rv$grn_results$master_regulators)
    n <- min(nrow(network_rv$grn_results$master_regulators), 10)
    paste0(n, " TFs")
  })
  
  output$kf_master_detail <- renderText({
    req(network_rv$grn_results$master_regulators)
    top_tf <- network_rv$grn_results$master_regulators$label[1]
    paste0("Led by ", top_tf)
  })
  
  # DEG Coverage
  output$kf_deg_coverage <- renderText({
    req(network_rv$grn_results)
    
    params <- network_rv$grn_results$analysis_params
    if (!is.null(params$n_converted_genes) && !is.null(params$n_input_genes) && params$n_input_genes > 0) {
      coverage <- round(params$n_converted_genes / params$n_input_genes * 100)
      paste0(coverage, "%")
    } else {
      "N/A"
    }
  })
  
  output$kf_deg_detail <- renderText({
    req(network_rv$grn_results)
    params <- network_rv$grn_results$analysis_params
    paste0(params$n_converted_genes %||% 0, " of ", params$n_input_genes %||% 0, " DEGs in network")
  })
  
  # Regulatory Circuits
  output$kf_circuits <- renderText({
    req(network_rv$grn_results)
    
    tf_regs <- network_rv$grn_results$tf_regulations
    if (!is.null(tf_regs)) {
      all_tfs <- unique(tf_regs$tf)
      tf_tf_count <- sum(tf_regs$target %in% all_tfs)
      paste0(tf_tf_count)
    } else {
      "0"
    }
  })
  
  output$kf_circuits_detail <- renderText({
    "TF-TF regulatory links"
  })
  
  # Top 5 TFs Cards - WITH REAL DRUGGABILITY
  output$grn_top5_tfs_cards <- renderUI({
    req(network_rv$grn_results$master_regulators)
    
    top5 <- head(network_rv$grn_results$master_regulators, 5)
    tf_regs <- network_rv$grn_results$tf_regulations
    
    # Check druggability via ChEMBL (or use cached results if available)
    druggability <- if (!is.null(network_rv$grn_results$druggability_info)) {
      network_rv$grn_results$druggability_info
    } else {
      # Query ChEMBL for these TFs
      check_druggability_chembl(top5$label)
    }
    
    # Define colors for ranks
    rank_colors <- c("#FFD700", "#C0C0C0", "#CD7F32", "#4A90A4", "#7B68EE")
    
    cards <- lapply(1:nrow(top5), function(i) {
      tf <- top5[i, ]
      
      # Get regulation details
      n_targets <- tf$degree_out
      
      # Calculate up/down targets
      if (!is.null(tf_regs)) {
        tf_target_regs <- tf_regs[tf_regs$tf == tf$label, ]
        n_activations <- sum(tf_target_regs$mor == 1, na.rm = TRUE)
        n_repressions <- sum(tf_target_regs$mor == -1, na.rm = TRUE)
      } else {
        n_activations <- 0
        n_repressions <- 0
      }
      
      # Determine TF role
      role <- if (n_activations > n_repressions * 2) {
        "Primarily Activator"
      } else if (n_repressions > n_activations * 2) {
        "Primarily Repressor"
      } else {
        "Mixed Regulator"
      }
      
      role_color <- switch(role,
                           "Primarily Activator" = "#27ae60",
                           "Primarily Repressor" = "#e74c3c",
                           "#f39c12")
      
      # Check druggability from ChEMBL results
      is_druggable <- FALSE
      drug_info <- ""
      if (!is.null(druggability) && tf$label %in% druggability$gene) {
        drug_row <- druggability[druggability$gene == tf$label, ]
        is_druggable <- drug_row$is_druggable[1]
        if (is_druggable && !is.na(drug_row$n_bioactivities[1])) {
          drug_info <- paste0(" (", drug_row$n_bioactivities[1], " bioactivities)")
        }
        if (!is.na(drug_row$has_approved_drug[1]) && drug_row$has_approved_drug[1]) {
          drug_info <- " (Approved drug exists)"
        }
      }
      
      div(style = paste0("display: flex; align-items: center; padding: 12px; margin-bottom: 10px; ",
                         "background: #f8f9fa; border-radius: 8px; border-left: 4px solid ", rank_colors[i], ";"),
          # Rank badge
          div(style = paste0("width: 35px; height: 35px; background: ", rank_colors[i], "; ",
                             "border-radius: 50%; display: flex; align-items: center; justify-content: center; ",
                             "margin-right: 15px; color: white; font-weight: bold;"),
              i
          ),
          # TF Info
          div(style = "flex: 1;",
              div(style = "display: flex; align-items: center;",
                  strong(tf$label, style = "font-size: 1.1em; margin-right: 10px;"),
                  if (is_druggable) {
                    span(icon("pills"), " ChEMBL Target", drug_info,
                         style = "font-size: 0.75em; background: #e8f5e9; color: #2e7d32; 
                                 padding: 2px 8px; border-radius: 10px;")
                  } else {
                    span(icon("question-circle"), " Not in ChEMBL", 
                         style = "font-size: 0.75em; background: #f5f5f5; color: #9e9e9e; 
                                 padding: 2px 8px; border-radius: 10px;")
                  }
              ),
              div(style = "font-size: 0.85em; color: #666; margin-top: 3px;",
                  span(paste0(n_targets, " targets"), style = "margin-right: 15px;"),
                  span(HTML(paste0("&#8593;", n_activations, " &#8595;", n_repressions)), style = "margin-right: 15px;"),
                  span(role, style = paste0("color: ", role_color, "; font-weight: 500;"))
              )
          ),
          # Score
          div(style = "text-align: right;",
              if ("master_score" %in% colnames(tf)) {
                div(
                  div(style = "font-size: 1.3em; font-weight: bold; color: #2c3e50;",
                      round(tf$master_score, 1)),
                  div(style = "font-size: 0.75em; color: #95a5a6;", "Score")
                )
              } else {
                div(
                  div(style = "font-size: 1.3em; font-weight: bold; color: #2c3e50;",
                      n_targets),
                  div(style = "font-size: 0.75em; color: #95a5a6;", "Targets")
                )
              }
          )
      )
    })
    
    do.call(tagList, cards)
  })
  
  # TF Hierarchy (TF-TF interactions)
  output$grn_tf_hierarchy <- renderUI({
    req(network_rv$grn_results$tf_regulations)
    
    tf_regs <- network_rv$grn_results$tf_regulations
    all_tfs <- unique(tf_regs$tf)
    
    # Find TF-TF interactions
    tf_tf <- tf_regs %>%
      filter(target %in% all_tfs) %>%
      arrange(desc(confidence)) %>%
      head(10)
    
    if (nrow(tf_tf) == 0) {
      return(
        div(style = "text-align: center; padding: 30px; color: #7f8c8d;",
            icon("info-circle", style = "font-size: 32px; margin-bottom: 10px;"),
            p("No TF-TF regulatory relationships detected"),
            p("This suggests a relatively flat regulatory structure", style = "font-size: 0.9em;")
        )
      )
    }
    
    # Create visual representation
    hierarchy_items <- lapply(1:nrow(tf_tf), function(i) {
      row <- tf_tf[i, ]
      reg_type <- if (!is.null(row$mor) && row$mor == 1) "activates" else "represses"
      reg_color <- if (reg_type == "activates") "#27ae60" else "#e74c3c"
      reg_icon <- if (reg_type == "activates") "arrow-right" else "ban"
      
      div(style = "display: flex; align-items: center; padding: 8px 0; border-bottom: 1px solid #eee;",
          span(strong(row$tf), style = "width: 80px;"),
          span(icon(reg_icon), style = paste0("color: ", reg_color, "; margin: 0 10px;")),
          span(strong(row$target), style = "width: 80px;"),
          span(paste0("(", round(row$confidence, 2), ")"), 
               style = "color: #95a5a6; font-size: 0.85em; margin-left: auto;")
      )
    })
    
    div(
      div(style = "display: flex; justify-content: space-between; margin-bottom: 10px; font-size: 0.85em; color: #7f8c8d;",
          span("Regulator"),
          span("Target TF"),
          span("Confidence")
      ),
      do.call(tagList, hierarchy_items)
    )
  })
  
  # Biological Story
  output$grn_biological_story <- renderUI({
    req(network_rv$grn_results)
    
    grn <- network_rv$grn_results
    tf_enrich <- grn$tf_pathway_enrichment
    target_enrich <- grn$target_pathway_enrichment
    master_regs <- grn$master_regulators
    
    story_parts <- list()
    
    # Part 1: Top regulator story
    if (!is.null(master_regs) && nrow(master_regs) > 0) {
      top_tf <- master_regs$label[1]
      n_targets <- master_regs$degree_out[1]
      
      story_parts[[1]] <- p(
        icon("star", style = "color: #f1c40f;"), " ",
        strong(top_tf), " is your top master regulator, directly controlling ",
        strong(n_targets), " genes in your dataset. This TF appears central to the ",
        "regulatory response observed in your experiment."
      )
    }
    
    # Part 2: TF enrichment story
    if (!is.null(tf_enrich) && nrow(tf_enrich) > 0) {
      sig_pathways <- tf_enrich %>% filter(Adjusted.P.value < 0.05) %>% head(3)
      if (nrow(sig_pathways) > 0) {
        top_pathway <- sig_pathways$Term[1]
        story_parts[[2]] <- p(
          icon("dna", style = "color: #3498db;"), " ",
          "Your master regulators are significantly associated with ",
          strong(gsub("\\s*\\(GO:.*\\)", "", top_pathway)), ". ",
          "This suggests they are known players in this biological process."
        )
      }
    }
    
    # Part 3: Target enrichment story
    if (!is.null(target_enrich) && nrow(target_enrich) > 0) {
      sig_target_pathways <- target_enrich %>% filter(Adjusted.P.value < 0.05) %>% head(3)
      if (nrow(sig_target_pathways) > 0) {
        top_target_pathway <- sig_target_pathways$Term[1]
        story_parts[[3]] <- p(
          icon("bullseye", style = "color: #9b59b6;"), " ",
          "The genes controlled by these TFs are enriched in ",
          strong(gsub("\\s*\\(GO:.*\\)", "", top_target_pathway)), ". ",
          "This reveals the downstream biological impact of the regulatory network."
        )
      }
    }
    
    # Part 4: Combined insight
    if (length(story_parts) >= 2) {
      story_parts[[length(story_parts) + 1]] <- div(
        style = "background: #e8f5e9; padding: 12px; border-radius: 6px; margin-top: 15px;",
        p(style = "margin: 0;",
          icon("lightbulb", style = "color: #27ae60;"), " ",
          strong("Key Insight: "), 
          "The coherence between TF functions and target gene processes suggests ",
          "a coordinated regulatory response driving specific biological outcomes in your condition."
        )
      )
    }
    
    if (length(story_parts) == 0) {
      return(
        p(style = "color: #7f8c8d; font-style: italic;",
          "Complete the enrichment analyses to generate biological interpretation.")
      )
    }
    
    do.call(tagList, story_parts)
  })
  
  # TF Enrichment Summary Card
  output$grn_tf_enrichment_summary_card <- renderUI({
    tf_enrich <- network_rv$grn_results$tf_pathway_enrichment
    
    if (is.null(tf_enrich) || nrow(tf_enrich) == 0) {
      return(p("Run TF enrichment to see results", style = "color: #666; font-size: 0.9em;"))
    }
    
    n_sig <- sum(tf_enrich$Adjusted.P.value < 0.05, na.rm = TRUE)
    
    # FIXED: Use base R instead of dplyr::first()
    top_term <- if (n_sig > 0) {
      sig_terms <- tf_enrich$Term[tf_enrich$Adjusted.P.value < 0.05]
      sig_terms <- sig_terms[order(tf_enrich$Adjusted.P.value[tf_enrich$Adjusted.P.value < 0.05])]
      if (length(sig_terms) > 0) {
        substr(as.character(sig_terms[1]), 1, 40)
      } else {
        "None significant"
      }
    } else { 
      "None significant" 
    }
    
    tagList(
      p(strong(n_sig), " significant pathways", style = "margin: 5px 0;"),
      p("Top: ", em(paste0(top_term, if(nchar(top_term) >= 40) "..." else "")), 
        style = "font-size: 0.85em; margin: 0; color: #555;")
    )
  })
  
  # Target Enrichment Summary Card - FIXED
  output$grn_target_enrichment_summary_card <- renderUI({
    target_enrich <- network_rv$grn_results$target_pathway_enrichment
    
    if (is.null(target_enrich) || nrow(target_enrich) == 0) {
      return(p("Run target enrichment to see results", style = "color: #666; font-size: 0.9em;"))
    }
    
    n_sig <- sum(target_enrich$Adjusted.P.value < 0.05, na.rm = TRUE)
    
    # FIXED: Use base R instead of dplyr::first()
    top_term <- if (n_sig > 0) {
      sig_terms <- target_enrich$Term[target_enrich$Adjusted.P.value < 0.05]
      sig_terms <- sig_terms[order(target_enrich$Adjusted.P.value[target_enrich$Adjusted.P.value < 0.05])]
      if (length(sig_terms) > 0) {
        substr(as.character(sig_terms[1]), 1, 40)
      } else {
        "None significant"
      }
    } else { 
      "None significant" 
    }
    
    tagList(
      p(strong(n_sig), " significant pathways", style = "margin: 5px 0;"),
      p("Top: ", em(paste0(top_term, if(nchar(top_term) >= 40) "..." else "")), 
        style = "font-size: 0.85em; margin: 0; color: #555;")
    )
  })
  
  # Suggested Hypotheses
  output$grn_hypotheses <- renderUI({
    req(network_rv$grn_results)
    
    grn <- network_rv$grn_results
    master_regs <- grn$master_regulators
    tf_regs <- grn$tf_regulations
    tf_enrich <- grn$tf_pathway_enrichment
    
    hypotheses <- list()
    
    if (!is.null(master_regs) && nrow(master_regs) > 0) {
      top_tf <- master_regs$label[1]
      n_targets <- master_regs$degree_out[1]
      
      # Hypothesis 1: Knockdown/knockout
      hypotheses[[1]] <- div(
        style = "padding: 10px; background: white; border-radius: 6px; margin-bottom: 10px;",
        div(style = "display: flex; align-items: flex-start;",
            span("1", style = "background: #e65100; color: white; border-radius: 50%; 
                         width: 24px; height: 24px; display: flex; align-items: center; 
                         justify-content: center; margin-right: 10px; flex-shrink: 0;"),
            div(
              p(style = "margin: 0; font-weight: 500;", 
                paste0("Knockdown of ", top_tf, " may affect ", n_targets, " downstream genes")),
              p(style = "margin: 5px 0 0 0; font-size: 0.85em; color: #666;",
                "Test: siRNA/shRNA knockdown followed by RNA-seq")
            )
        )
      )
      
      # Hypothesis 2: Based on regulation type
      if (!is.null(tf_regs)) {
        tf_target_regs <- tf_regs[tf_regs$tf == top_tf, ]
        n_act <- sum(tf_target_regs$mor == 1, na.rm = TRUE)
        n_rep <- sum(tf_target_regs$mor == -1, na.rm = TRUE)
        
        if (n_act > n_rep) {
          hypotheses[[2]] <- div(
            style = "padding: 10px; background: white; border-radius: 6px; margin-bottom: 10px;",
            div(style = "display: flex; align-items: flex-start;",
                span("2", style = "background: #e65100; color: white; border-radius: 50%; 
                           width: 24px; height: 24px; display: flex; align-items: center; 
                           justify-content: center; margin-right: 10px; flex-shrink: 0;"),
                div(
                  p(style = "margin: 0; font-weight: 500;", 
                    paste0(top_tf, " overexpression should upregulate target genes")),
                  p(style = "margin: 5px 0 0 0; font-size: 0.85em; color: #666;",
                    paste0("As a primarily activating TF (", n_act, "/", n_act + n_rep, " activations)"))
                )
            )
          )
        }
      }
      
      # Hypothesis 3: Based on enrichment
      if (!is.null(tf_enrich) && nrow(tf_enrich) > 0) {
        sig_pathway <- tf_enrich %>% filter(Adjusted.P.value < 0.05) %>% head(1)
        if (nrow(sig_pathway) > 0) {
          pathway_clean <- gsub("\\s*\\(GO:.*\\)", "", sig_pathway$Term[1])
          hypotheses[[3]] <- div(
            style = "padding: 10px; background: white; border-radius: 6px;",
            div(style = "display: flex; align-items: flex-start;",
                span("3", style = "background: #e65100; color: white; border-radius: 50%; 
                           width: 24px; height: 24px; display: flex; align-items: center; 
                           justify-content: center; margin-right: 10px; flex-shrink: 0;"),
                div(
                  p(style = "margin: 0; font-weight: 500;", 
                    paste0("Your experimental condition may involve ", tolower(pathway_clean))),
                  p(style = "margin: 5px 0 0 0; font-size: 0.85em; color: #666;",
                    "Based on TF enrichment analysis results")
                )
            )
          )
        }
      }
    }
    
    if (length(hypotheses) == 0) {
      return(p("Complete the analysis to generate hypotheses", style = "color: #666;"))
    }
    
    do.call(tagList, hypotheses)
  })
  
  
  output$grn_analysis_complete <- reactive({
    !is.null(network_rv$grn_results) &&
      network_rv$analysis_type == "grn" &&
      isTRUE(network_rv$analysis_status == "complete")
  })
  outputOptions(output, "grn_analysis_complete", suspendWhenHidden = FALSE)
  
  
  # ===== ADDITIONAL HELPER FUNCTIONS =====
  
  # Add this reactive value to track guide visibility (add to your server):
  grn_guide_visible <- reactiveVal(FALSE)
  
  # Guide toggle observer
  observeEvent(input$grn_help_guide, {
    grn_guide_visible(!grn_guide_visible())
  })
  
  # Guide close observer
  observeEvent(input$close_grn_guide, {
    grn_guide_visible(FALSE)
  })
  
  # Node click observer for network interactivity
  observeEvent(input$grn_clicked_node, {
    req(input$grn_clicked_node)
    
    node_id <- input$grn_clicked_node
    grn_results <- network_rv$grn_results
    
    # Find information about clicked node
    if (node_id %in% grn_results$tf_regulations$tf) {
      # Clicked on a TF
      tf_info <- grn_results$master_regulators[grn_results$master_regulators$tf == node_id, ]
      if (nrow(tf_info) > 0) {
        showModal(modalDialog(
          title = paste("Target Gene:", node_id),
          div(
            h5("Regulatory Information:"),
            p(strong("Regulated by:"), paste(target_regs$tf, collapse = ", ")),
            p(strong("Number of TFs:"), nrow(target_regs)),
            h6("Regulatory Details:"),
            DT::dataTableOutput("clicked_gene_regulations")
          ),
          easyClose = TRUE,
          footer = modalButton("Close")
        ))
        
        # Render the regulations table for the clicked gene
        output$clicked_gene_regulations <- DT::renderDataTable({
          regulations_display <- target_regs %>%
            select(
              `Transcription Factor` = tf,
              `Regulation` = regulation_type,
              `Confidence` = confidence
            ) %>%
            mutate(
              `Regulation` = ifelse(`Regulation` == 1, "Activation", "Repression"),
              `Confidence` = round(`Confidence`, 3)
            )
          
          DT::datatable(regulations_display,
                        options = list(pageLength = 5, dom = 't'),
                        rownames = FALSE)
        }, server = FALSE)
      }
    }
  })
  
  # Reset network view
  observeEvent(input$grn_reset_network, {
    visNetworkProxy("grn_network_plot") %>%
      visFit() %>%
      visPhysics(enabled = TRUE) # Re-enable physics temporarily to recalculate layout
  })
  
  observeEvent(input$grn_network_physics, {
    physics_enabled <- input$grn_network_physics > 0.1
    
    visNetworkProxy("grn_network_plot") %>%
      visPhysics(enabled = physics_enabled)
  })
  
  observeEvent(input$grn_show_labels, {
    req(network_rv$grn_results$network_data)
    
    # Update node labels based on checkbox
    nodes <- network_rv$grn_results$network_data$nodes
    
    if (!input$grn_show_labels) {
      # Hide labels for target nodes, keep TF labels
      nodes$label[nodes$group != "tf"] <- ""
    } else {
      # Show all labels - restore original labels
      nodes$label <- nodes$id
    }
    
    visNetworkProxy("grn_network_plot") %>%
      visUpdateNodes(nodes)
  })
  
  # ===== GRN SPECIFIC OUTPUT FUNCTIONS =====
  
  # Network visualization
  output$grn_network_plot <- renderVisNetwork({
    req(network_rv$grn_results$network_data)
    
    print("🎯 DEBUG: Starting GRN network plot rendering")
    
    network_data <- network_rv$grn_results$network_data
    
    if (is.null(network_data$nodes) || nrow(network_data$nodes) == 0) {
      print("❌ DEBUG: No nodes found in network_data")
      return(NULL)
    }
    
    # Fix the network data structure if needed
    if (!"group" %in% colnames(network_data$nodes)) {
      print("🔧 Network data needs fixing - applying transformation...")
      
      # Get selected genes
      selected_genes <- network_rv$selected_genes %||% network_rv$grn_results$selected_genes
      network_data <- fix_grn_network_data(network_data, selected_genes)
      network_rv$grn_results$network_data <- network_data
    }
    
    print("🔍 DEBUG: Final network structure:")
    print(paste("Nodes:", nrow(network_data$nodes)))
    print(paste("Edges:", nrow(network_data$edges %||% data.frame())))
    print("🔍 DEBUG: Node groups:")
    print(table(network_data$nodes$group))
    
    # Create the network - SIMPLIFIED VERSION
    tryCatch({
      print("🔧 Creating visNetwork object...")
      
      # Filter nodes if "Hide Non-DEG Genes" is checked
      nodes_to_use <- network_data$nodes
      edges_to_use <- network_data$edges
      
      hide_non_deg <- input$grn_hide_non_deg_genes %||% FALSE
      if (hide_non_deg) {
        # Keep only TFs and DEG targets (upregulated/downregulated), remove "target" group
        deg_groups <- c("tf", "upregulated", "downregulated")
        nodes_to_use <- nodes_to_use[nodes_to_use$group %in% deg_groups, ]
        
        # Filter edges to only include nodes that exist
        valid_node_ids <- nodes_to_use$id
        edges_to_use <- edges_to_use[edges_to_use$from %in% valid_node_ids & 
                                       edges_to_use$to %in% valid_node_ids, ]
        
        print(paste("🔍 Filtered to DEG genes only:", nrow(nodes_to_use), "nodes,", nrow(edges_to_use), "edges"))
      }
      
      vis_net <- visNetwork(
        nodes = nodes_to_use,
        edges = edges_to_use,
        width = "100%",
        height = "650px"
      ) %>%
        visLayout(randomSeed = 123) %>%
        visNodes(font = list(size = 16, face = "arial")) %>%
        visEdges(smooth = FALSE,
                 color = list(color = "#cccccc", highlight = "#ff5722")) %>%
        visOptions(
          highlightNearest = list(enabled = TRUE, degree = 1, hover = TRUE),
          selectedBy = list(variable = "group", multiple = TRUE),
          nodesIdSelection = TRUE
        ) %>%
        visInteraction(
          dragNodes = TRUE,
          dragView = TRUE,
          zoomView = TRUE,
          navigationButtons = TRUE,
          tooltipDelay = 100
        )

      print("🔧 Adding group configurations...")

      unique_groups <- unique(nodes_to_use$group)

      if ("tf" %in% unique_groups) {
        vis_net <- vis_net %>%
          visGroups(
            groupname = "tf",
            shape = "triangle",
            color = list(background = "#FF6B6B", border = "#D64545", highlight = "#E53935"),
            size = 35,
            font = list(size = 16, face = "arial", color = "black")
          )
      }

      if ("upregulated" %in% unique_groups) {
        vis_net <- vis_net %>%
          visGroups(
            groupname = "upregulated",
            shape = "dot",
            color = list(background = "#4ECDC4", border = "#2ECC71", highlight = "#26A69A"),
            size = 25,
            font = list(size = 14)
          )
      }

      if ("downregulated" %in% unique_groups) {
        vis_net <- vis_net %>%
          visGroups(
            groupname = "downregulated",
            shape = "dot",
            color = list(background = "#FF9F43", border = "#E67E22", highlight = "#FF7043"),
            size = 25,
            font = list(size = 14)
          )
      }

      if ("target" %in% unique_groups) {
        vis_net <- vis_net %>%
          visGroups(
            groupname = "target",
            shape = "dot",
            color = list(background = "#BDC3C7", border = "#95A5A6", highlight = "#78909C"),
            size = 20,
            font = list(size = 12)
          )
      }

      # Tighter physics — shorter springs, less scatter, network pulls together
      vis_net <- vis_net %>%
        visPhysics(
          enabled = TRUE,
          solver = "forceAtlas2Based",
          forceAtlas2Based = list(
            gravitationalConstant = -80,
            centralGravity = 0.05,
            springLength = 90,
            springConstant = 0.1,
            avoidOverlap = 0.5,
            damping = 0.5
          ),
          stabilization = list(enabled = TRUE, iterations = 300, updateInterval = 25, fit = TRUE)
        ) %>%
        visEvents(stabilizationIterationsDone = "function() {
          this.setOptions({ physics: false });
        }")
      
      print("✅ DEBUG: Network object created successfully")
      return(vis_net)
      
    }, error = function(e) {
      print(paste("❌ DEBUG: Error creating network:", e$message))
      print("📋 DEBUG: Full error details:")
      print(str(e))
      
      # Return a minimal network to test rendering
      simple_nodes <- data.frame(
        id = c("Test1", "Test2"),
        label = c("Test1", "Test2"),
        color = c("red", "blue")
      )
      simple_edges <- data.frame(
        from = "Test1",
        to = "Test2"
      )
      
      return(visNetwork(simple_nodes, simple_edges))
    })
  })
  
  # Download GRN Network as HTML
  output$download_grn_network_html <- downloadHandler(
    filename = function() {
      paste0("GRN_Regulatory_Network_", Sys.Date(), ".html")
    },
    content = function(file) {
      req(network_rv$grn_results$network_data)
      
      network_data <- network_rv$grn_results$network_data
      
      # Apply same filtering as display
      nodes_to_use <- network_data$nodes
      edges_to_use <- network_data$edges
      
      hide_non_deg <- input$grn_hide_non_deg_genes %||% FALSE
      if (hide_non_deg) {
        deg_groups <- c("tf", "upregulated", "downregulated")
        nodes_to_use <- nodes_to_use[nodes_to_use$group %in% deg_groups, ]
        valid_node_ids <- nodes_to_use$id
        edges_to_use <- edges_to_use[edges_to_use$from %in% valid_node_ids & 
                                       edges_to_use$to %in% valid_node_ids, ]
      }
      
      # Create network with physics that stops after stabilization
      export_network <- visNetwork(
        nodes = nodes_to_use,
        edges = edges_to_use,
        width = "100%",
        height = "900px",
        main = list(text = "Gene Regulatory Network", 
                    style = "font-family:Arial;font-size:24px;font-weight:bold;")
      ) %>%
        visGroups(groupname = "tf", shape = "triangle",
                  color = list(background = "#FF6B6B", border = "#D64545", highlight = "#E53935"),
                  size = 35) %>%
        visGroups(groupname = "upregulated", shape = "dot",
                  color = list(background = "#4ECDC4", border = "#2ECC71", highlight = "#26A69A"),
                  size = 25) %>%
        visGroups(groupname = "downregulated", shape = "dot",
                  color = list(background = "#FF9F43", border = "#E67E22", highlight = "#FF7043"),
                  size = 25) %>%
        visGroups(groupname = "target", shape = "dot",
                  color = list(background = "#BDC3C7", border = "#95A5A6", highlight = "#78909C"),
                  size = 20) %>%
        visLayout(randomSeed = 123) %>%
        visPhysics(
          enabled = TRUE,
          solver = "forceAtlas2Based",
          forceAtlas2Based = list(
            gravitationalConstant = -100,
            centralGravity = 0.01,
            springLength = 150,
            springConstant = 0.05,
            avoidOverlap = 1,
            damping = 0.5
          ),
          stabilization = list(enabled = TRUE, iterations = 200, updateInterval = 25)
        ) %>%
        # Stop physics after stabilization so user can move nodes
        visEvents(stabilizationIterationsDone = "function() {
          this.setOptions({ physics: false });
        }") %>%
        visOptions(
          highlightNearest = list(enabled = TRUE, degree = 1, hover = TRUE),
          nodesIdSelection = TRUE
        ) %>%
        visInteraction(
          dragNodes = TRUE,
          dragView = TRUE,
          zoomView = TRUE,
          navigationButtons = TRUE,
          keyboard = TRUE
        ) %>%
        visLegend(
          addNodes = list(
            list(label = "TF", shape = "triangle", color = "#FF6B6B", size = 25),
            list(label = "Upregulated", shape = "dot", color = "#4ECDC4", size = 20),
            list(label = "Downregulated", shape = "dot", color = "#FF9F43", size = 20),
            list(label = "Target", shape = "dot", color = "#BDC3C7", size = 15)
          ),
          useGroups = FALSE,
          position = "right",
          width = 0.15
        )
      
      visSave(export_network, file = file, selfcontained = TRUE, background = "white")
      
      showNotification("GRN Network HTML downloaded!", type = "message", duration = 3)
    }
  )
  
  # Re-render network when hide non-DEG filter changes
  observeEvent(input$grn_hide_non_deg_genes, {
    # Force network to re-render by invalidating it
    # The renderVisNetwork will pick up the new filter value
  }, ignoreInit = TRUE)
  # # Network statistics
  output$grn_network_stats <- renderUI({
    req(network_rv$grn_results)
    
    grn <- network_rv$grn_results
    nodes <- grn$network_data$nodes
    edges <- grn$network_data$edges
    tf_regs <- grn$tf_regulations
    
    # Calculate statistics
    n_nodes <- nrow(nodes) %||% 0
    n_edges <- nrow(edges) %||% 0
    n_tfs <- sum(nodes$type == "TF" | nodes$group == "tf", na.rm = TRUE)
    n_targets <- n_nodes - n_tfs
    
    # Regulation stats
    n_up <- sum(nodes$group == "upregulated" | nodes$regulation == "Up", na.rm = TRUE)
    n_down <- sum(nodes$group == "downregulated" | nodes$regulation == "Down", na.rm = TRUE)
    
    # Edge stats
    if (!is.null(tf_regs) && "mor" %in% colnames(tf_regs)) {
      n_act <- sum(tf_regs$mor == 1, na.rm = TRUE)
      n_rep <- sum(tf_regs$mor == -1, na.rm = TRUE)
      act_pct <- round(n_act / (n_act + n_rep) * 100)
    } else {
      n_act <- "N/A"
      n_rep <- "N/A"
      act_pct <- "N/A"
    }
    
    # Network density
    max_edges <- n_tfs * n_targets
    density <- if (max_edges > 0) round(n_edges / max_edges * 100, 2) else 0
    
    div(
      # Overview section
      div(style = "margin-bottom: 15px;",
          div(style = "display: flex; justify-content: space-between; margin-bottom: 8px;",
              span("Total Nodes:", style = "color: #7f8c8d;"),
              strong(n_nodes)
          ),
          div(style = "display: flex; justify-content: space-between; margin-bottom: 8px;",
              span("Total Edges:", style = "color: #7f8c8d;"),
              strong(n_edges)
          ),
          div(style = "display: flex; justify-content: space-between; margin-bottom: 8px;",
              span("Network Density:", style = "color: #7f8c8d;"),
              strong(paste0(density, "%"))
          )
      ),
      
      hr(style = "margin: 10px 0;"),
      
      # Node breakdown
      h6("Node Types", style = "margin-bottom: 10px;"),
      div(style = "display: flex; justify-content: space-between; margin-bottom: 5px;",
          span(HTML("<span style='color: #FF6B6B;'>●</span> TFs:"), style = "color: #7f8c8d;"),
          strong(n_tfs)
      ),
      div(style = "display: flex; justify-content: space-between; margin-bottom: 5px;",
          span(HTML("<span style='color: #4ECDC4;'>●</span> Upregulated:"), style = "color: #7f8c8d;"),
          strong(n_up)
      ),
      div(style = "display: flex; justify-content: space-between; margin-bottom: 5px;",
          span(HTML("<span style='color: #FF9F43;'>●</span> Downregulated:"), style = "color: #7f8c8d;"),
          strong(n_down)
      ),
      
      hr(style = "margin: 10px 0;"),
      
      # Edge breakdown
      h6("Regulation Types", style = "margin-bottom: 10px;"),
      div(style = "display: flex; justify-content: space-between; margin-bottom: 5px;",
          span(HTML("<span style='color: #27AE60;'>→</span> Activations:"), style = "color: #7f8c8d;"),
          strong(n_act)
      ),
      div(style = "display: flex; justify-content: space-between; margin-bottom: 5px;",
          span(HTML("<span style='color: #E74C3C;'>⊣</span> Repressions:"), style = "color: #7f8c8d;"),
          strong(n_rep)
      ),
      div(style = "display: flex; justify-content: space-between;",
          span("Activation %:", style = "color: #7f8c8d;"),
          strong(paste0(act_pct, "%"))
      )
    )
  })
  
  # Master regulators table
  output$grn_master_regulators_table <- DT::renderDataTable({
    req(network_rv$grn_results$master_regulators)
    
    master_regs <- network_rv$grn_results$master_regulators
    tf_regs <- network_rv$grn_results$tf_regulations
    
    # Build enhanced display table
    display_table <- master_regs %>%
      mutate(
        Rank = row_number()
      )
    
    # Add activation/repression counts if tf_regulations available
    if (!is.null(tf_regs)) {
      display_table <- display_table %>%
        rowwise() %>%
        mutate(
          n_activations = sum(tf_regs$tf == label & tf_regs$mor == 1, na.rm = TRUE),
          n_repressions = sum(tf_regs$tf == label & tf_regs$mor == -1, na.rm = TRUE),
          activation_ratio = ifelse(n_activations + n_repressions > 0,
                                    round(n_activations / (n_activations + n_repressions) * 100), 50)
        ) %>%
        ungroup()
    } else {
      display_table <- display_table %>%
        mutate(
          n_activations = NA,
          n_repressions = NA,
          activation_ratio = NA
        )
    }
    
    # Determine regulatory role
    display_table <- display_table %>%
      mutate(
        `Regulatory Role` = case_when(
          activation_ratio >= 70 ~ "Activator",
          activation_ratio <= 30 ~ "Repressor",
          TRUE ~ "Mixed"
        ),
        # Check druggability
        Druggable = ifelse(label %in% c(
          "ESR1", "AR", "PPARG", "PPARA", "NR3C1", "RARA", "RXRA",
          "HIF1A", "STAT3", "STAT1", "NFE2L2", "TP53", "MYC", "NFKB1",
          "RELA", "CREB1", "JUN", "FOS", "EGR1", "SP1", "GATA3",
          "NR2F1", "NR2F2", "GATA4", "MAFB", "VDR", "THRB", "NR1H3"
        ), "Yes", "No")
      )
    
    # Select columns for display
    final_table <- display_table %>%
      select(
        Rank,
        `TF` = label,
        `Targets` = degree_out,
        `↑ Act` = n_activations,
        `↓ Rep` = n_repressions,
        `Act %` = activation_ratio,
        `Role` = `Regulatory Role`,
        Druggable
      ) %>%
      head(15)
    
    DT::datatable(
      final_table,
      options = list(
        pageLength = 15,
        dom = 'tip',
        order = list(list(0, 'asc')),
        columnDefs = list(
          list(className = 'dt-center', targets = "_all"),
          list(width = '50px', targets = 0),
          list(width = '80px', targets = 1)
        )
      ),
      rownames = FALSE,
      class = 'cell-border stripe hover'
    ) %>%
      DT::formatStyle(
        'Role',
        backgroundColor = DT::styleEqual(
          c('Activator', 'Repressor', 'Mixed'),
          c('#d4edda', '#f8d7da', '#fff3cd')
        ),
        fontWeight = 'bold'
      ) %>%
      DT::formatStyle(
        'Druggable',
        backgroundColor = DT::styleEqual(c('Yes', 'No'), c('#e3f2fd', '#fff')),
        color = DT::styleEqual(c('Yes', 'No'), c('#1565c0', '#666'))
      ) %>%
      DT::formatStyle(
        'TF',
        fontWeight = 'bold',
        color = '#2c3e50'
      ) %>%
      DT::formatStyle(
        'Targets',
