  # Target gene enrichment function
  perform_target_gene_enrichment <- function(target_genes, organism = "human") {
    
    print("🎯 Starting target gene enrichment analysis...")
    print(paste("Input genes:", paste(head(target_genes, 5), collapse = ", ")))
    
    tryCatch({
      
      if (length(target_genes) < 3) {
        print("Too few target genes for enrichment analysis")
        return(NULL)
      }
      
      if (requireNamespace("enrichR", quietly = TRUE)) {
        print("Running enrichR for target gene analysis...")
        
        # Same databases as TF analysis for comparison
        dbs <- c("GO_Biological_Process_2023", "KEGG_2021_Human", "WikiPathway_2023_Human")
        
        # Run enrichment
        enrichr_results <- tx_enrichr_local(target_genes, dbs)
        
        # Process results
        combined_results <- NULL
        for (db_name in names(enrichr_results)) {
          if (!is.null(enrichr_results[[db_name]]) && nrow(enrichr_results[[db_name]]) > 0) {
            db_results <- enrichr_results[[db_name]] %>%
              filter(Adjusted.P.value < 0.05) %>%
              mutate(
                database = db_name,
                gene_count = lengths(strsplit(Genes, ";")),
                significance = case_when(
                  Adjusted.P.value < 0.001 ~ "Highly Significant",
                  Adjusted.P.value < 0.01 ~ "Significant",
                  TRUE ~ "Moderately Significant"
                )
              ) %>%
              select(Term, P.value, Adjusted.P.value, gene_count, Genes, database, significance)
            
            combined_results <- rbind(combined_results, db_results)
          }
        }
        
        if (!is.null(combined_results) && nrow(combined_results) > 0) {
          print(paste("Found", nrow(combined_results), "enriched target pathways"))
          return(combined_results)
        }
      }
      
      return(NULL)
      
    }, error = function(e) {
      print(paste("Error in target gene enrichment:", e$message))
      return(NULL)
    })
  }
  
  perform_target_gene_enrichment_fixed <- function(target_genes, organism = "human") {
    
    print("🎯 Starting target gene enrichment analysis...")
    print(paste("Organism:", organism))
    
    # ✅ ROBUST INPUT VALIDATION
    if (is.null(target_genes) || length(target_genes) == 0) {
      print("⚠️ Empty or NULL target gene list provided")
      return(NULL)
    }
    
    print(paste("Input genes:", paste(head(target_genes, 5), collapse = ", ")))
    
    # Store original input count
    original_input_count <- length(target_genes)
    
    # Convert factors/other types to character safely
    if (is.factor(target_genes)) {
      target_genes <- as.character(levels(target_genes))[as.integer(target_genes)]
    } else if (!is.character(target_genes)) {
      target_genes <- as.character(target_genes)
    }
    
    # Remove NA, NULL, and empty values
    target_genes <- target_genes[!is.na(target_genes)]
    target_genes <- target_genes[!sapply(target_genes, is.null)]
    target_genes <- target_genes[nchar(trimws(target_genes)) > 0]
    target_genes <- unique(target_genes)
    
    if (length(target_genes) == 0) {
      print("⚠️ No valid target genes after initial cleaning")
      return(NULL)
    }
    
    # Clean gene names
    target_genes_clean <- vapply(target_genes, function(x) {
      cleaned <- gsub("[^A-Za-z0-9_-]", "", trimws(as.character(x)))
      return(cleaned)
    }, FUN.VALUE = character(1), USE.NAMES = FALSE)
    
    target_genes_clean <- unique(target_genes_clean[nchar(target_genes_clean) > 0])
    
    if (length(target_genes_clean) == 0) {
      print("⚠️ No valid target genes after character cleaning")
      return(NULL)
    }
    
    print(paste("✅ Cleaned target gene list:", length(target_genes_clean), "genes"))
    print(paste("   Examples:", paste(head(target_genes_clean, 5), collapse = ", ")))
    
    # GET ORGANISM-SPECIFIC DATABASES
    databases <- get_enrichr_databases(organism)
    
    if (is.null(databases) || length(databases) == 0) {
      print("⚠️ No databases available for organism")
      return(NULL)
    }
    
    print(paste("🔍 Using", length(databases), "databases for", organism))
    print(paste("   Databases:", paste(head(databases, 3), collapse = ", "), "..."))
    print("Running enrichR for target gene analysis...")
    
    # ✅ WRAP ENTIRE enrichR INTERACTION IN TRYCATCH
    enrichment_results <- tryCatch({
      
      # Check if enrichR is loaded
      if (!requireNamespace("enrichR", quietly = TRUE)) {
        print("❌ enrichR package not available")
        return(NULL)
      }
      
      # ✅ FIX: MANUALLY SET enrichR OPTIONS BEFORE setEnrichrSite
      # This fixes the "invalid 'pattern' argument" error
      options(enrichR.base.address = "https://maayanlab.cloud/Enrichr/")
      options(enrichR.sites.base.address = "https://maayanlab.cloud/")
      options(enrichR.sites = c("Enrichr", "FlyEnrichr", "WormEnrichr", "YeastEnrichr", "FishEnrichr", "OxEnrichr"))
      options(enrichR.live = TRUE)
      options(enrichR.quiet = FALSE)
      
      print("✅ enrichR options set manually")
      
      # Now try setEnrichrSite (optional - may still fail but we have fallback)
      tryCatch({
        enrichR::setEnrichrSite("Enrichr")
        print("✅ setEnrichrSite successful")
      }, error = function(e) {
        print(paste("⚠️ setEnrichrSite failed, but options are set manually:", e$message))
        # Continue anyway since we set options manually
      })
      
      # ✅ FIX: Run enrichment ONE DATABASE AT A TIME to isolate errors
      all_results <- NULL
      successful_dbs <- 0
      
      for (db in databases) {
        db_result <- tryCatch({
          print(paste("   Querying:", db))
          
          # Query single database
          single_result <- tx_enrichr_local(
            genes = target_genes_clean,
            databases = db
          )
          
          if (!is.null(single_result) && 
              !is.null(single_result[[db]]) && 
              is.data.frame(single_result[[db]]) &&
              nrow(single_result[[db]]) > 0) {
            
            # Simplify database name for display
            db_label <- gsub("_20[0-9]{2}.*", "", db)
            db_label <- gsub("_", " ", db_label)
            
            temp_results <- single_result[[db]] %>%
              mutate(database = db_label)
            
            successful_dbs <- successful_dbs + 1
            temp_results
          } else {
            NULL
          }
        }, error = function(e) {
          print(paste("   ⚠️ Error with", db, ":", e$message))
          NULL
        })
        
        if (!is.null(db_result)) {
          all_results <- bind_rows(all_results, db_result)
        }

        Sys.sleep(0.1)
      }

      print(paste("✅ Successfully queried", successful_dbs, "of", length(databases), "databases"))
      all_results

    }, error = function(e) {
      print(paste("❌ Error in enrichR processing:", e$message))
      NULL
    })

    # Process results
    if (!is.null(enrichment_results) && nrow(enrichment_results) > 0) {

      enrichment_results$gene_count <- sapply(enrichment_results$Genes, function(x) {
        if (is.na(x) || x == "") return(0)
        length(strsplit(as.character(x), ";")[[1]])
      })

      enrichment_results$significance <- case_when(
        enrichment_results$Adjusted.P.value < 0.001 ~ "Highly Significant",
        enrichment_results$Adjusted.P.value < 0.01 ~ "Significant",
        enrichment_results$Adjusted.P.value < 0.05 ~ "Moderately Significant",
        enrichment_results$Adjusted.P.value < 0.1 ~ "Marginally Significant",
        TRUE ~ "Not Significant"
      )

      # Add metadata
      attr(enrichment_results, "original_input_count") <- original_input_count
      attr(enrichment_results, "cleaned_input_count") <- length(target_genes_clean)
      attr(enrichment_results, "organism") <- organism
      attr(enrichment_results, "databases_used") <- databases
      
      n_significant <- sum(enrichment_results$Adjusted.P.value < 0.05, na.rm = TRUE)
      
      print(paste("✅ Found", nrow(enrichment_results), "total pathways"))
      print(paste("✅ Found", n_significant, "significant pathways (p < 0.05)"))
      
      return(enrichment_results)
    }
    
    print("⚠️ No enrichment results found")
    return(NULL)
  }
  
  generate_grn_summary_stats <- function(nodes, edges, selected_genes) {
    
    # ✅ SAFETY CHECK: Ensure regulation column exists
    if (!"regulation" %in% colnames(nodes)) {
      print("⚠️ regulation column missing - adding it now")
      nodes$regulation <- "None"
      
      # Try to infer from group column
      if ("group" %in% colnames(nodes)) {
        nodes$regulation[nodes$group == "upregulated"] <- "Up"
        nodes$regulation[nodes$group == "downregulated"] <- "Down"
      }
    }
    
    # ✅ SAFETY CHECK: Ensure type column exists
    if (!"type" %in% colnames(nodes)) {
      print("⚠️ type column missing - inferring from group")
      nodes$type <- ifelse(nodes$group == "tf", "TF", "Target")
    }
    
    # Detailed node statistics
    node_stats <- list(
      total_nodes = nrow(nodes),
      tfs = sum(nodes$type == "TF", na.rm = TRUE),
      targets = sum(nodes$type == "Target", na.rm = TRUE),
      
      # Regulation by type
      tfs_up = sum(nodes$type == "TF" & nodes$regulation == "Up", na.rm = TRUE),
      tfs_down = sum(nodes$type == "TF" & nodes$regulation == "Down", na.rm = TRUE),
      targets_up = sum(nodes$type == "Target" & nodes$regulation == "Up", na.rm = TRUE),
      targets_down = sum(nodes$type == "Target" & nodes$regulation == "Down", na.rm = TRUE),
      
      # Alternative counting by group
      group_upregulated = sum(nodes$group == "upregulated", na.rm = TRUE),
      group_downregulated = sum(nodes$group == "downregulated", na.rm = TRUE),
      
      # DEG overlap
      targets_in_deg_list = sum(nodes$type == "Target" &
                                  nodes$id %in% c(selected_genes$up_genes,
                                                  selected_genes$down_genes), na.rm = TRUE),
      
      # For enrichment
      targets_for_enrichment = sum(nodes$type == "Target" &
                                     (nodes$regulation %in% c("Up", "Down") |
                                        nodes$group %in% c("upregulated", "downregulated") |
                                        nodes$id %in% c(selected_genes$up_genes,
                                                        selected_genes$down_genes)), na.rm = TRUE)
    )
    
    # Edge statistics
    edge_stats <- list(
      total_edges = nrow(edges),
      activations = sum(edges$regulation == 1, na.rm = TRUE),
      repressions = sum(edges$regulation == -1, na.rm = TRUE),
      activation_percentage = round(mean(edges$regulation == 1, na.rm = TRUE) * 100, 1)
    )
    
    # ✅ SAFETY: Handle case where we have no master regulators counted
    n_master_regulators <- node_stats$tfs
    
    return(list(
      nodes = node_stats,
      edges = edge_stats,
      n_nodes = node_stats$total_nodes,
      n_edges = edge_stats$total_edges,
      n_tfs = node_stats$tfs,
      n_master_regulators = n_master_regulators,
      summary_text = paste(
        "Network: ", node_stats$tfs, " TFs regulating ",
        node_stats$targets_up + node_stats$targets_down, " DEG targets ",
        "(", node_stats$targets_up, "↑, ", node_stats$targets_down, "↓) ",
        "with ", edge_stats$total_edges, " interactions ",
        "(", edge_stats$activation_percentage, "% activations)",
        sep = ""
      )
    ))
  }
  
