  # Target enrichment button observer
  # ==============================================================================
  # FIXED TARGET GENE ENRICHMENT - CONSISTENT WITH NETWORK STATISTICS
  # ==============================================================================
  
  # 1. Fix the manual target enrichment button observer
  observeEvent(input$run_target_enrichment, {
    
    if (!is.null(network_rv$grn_results$network_data)) {
      
      showNotification("Running target gene enrichment...")
      
      nodes <- network_rv$grn_results$network_data$nodes
      
      # CRITICAL FIX: Use consistent logic with automatic enrichment
      # Method 1: Try multiple approaches to get ALL regulated target genes
      
      # Approach A: Use type and regulation columns (matches automatic enrichment)
      if ("type" %in% colnames(nodes) && "regulation" %in% colnames(nodes)) {
        target_genes <- nodes$id[nodes$type == "Target" &
                                   (nodes$regulation == "Up" | nodes$regulation == "Down")]
        print(paste("🎯 Method A - Found", length(target_genes), "target genes using type+regulation"))
      }
      
      # Approach B: Use group column as fallback
      else if ("group" %in% colnames(nodes)) {
        target_genes <- nodes$id[nodes$group %in% c("upregulated", "downregulated")]
        print(paste("🎯 Method B - Found", length(target_genes), "target genes using group"))
      }
      
      # Approach C: Ultimate fallback - get all non-TF nodes that are DEGs
      else {
        # Get all non-TF nodes and check against original DEG lists
        tf_mask <- if("type" %in% colnames(nodes)) {
          nodes$type == "TF"
        } else if("group" %in% colnames(nodes)) {
          nodes$group == "tf"
        } else {
          rep(FALSE, nrow(nodes))  # No TFs found
        }
        
        non_tf_genes <- nodes$id[!tf_mask]
        
        # Check against original DEG data
        if (!is.null(rv_deg_main$deg_results)) {
          deg_data <- rv_deg_main$deg_results
          sig_genes <- deg_data$gene[deg_data$padj < input$pvalue_cutoff_deg_main &
                                       abs(deg_data$log2FoldChange) > input$log2fc_threshold_deg_main]
          target_genes <- intersect(non_tf_genes, sig_genes)
          print(paste("🎯 Method C - Found", length(target_genes), "target genes using DEG intersection"))
        } else {
          target_genes <- non_tf_genes
          print(paste("🎯 Method C - Using all non-TF nodes:", length(target_genes), "genes"))
        }
      }
      
      # Diagnostic information
      print("=== TARGET GENE ENRICHMENT DIAGNOSTICS ===")
      print(paste("Total network nodes:", nrow(nodes)))
      if ("type" %in% colnames(nodes)) print(paste("Node types:", paste(names(table(nodes$type)), "=", table(nodes$type), collapse = ", ")))
      if ("group" %in% colnames(nodes)) print(paste("Node groups:", paste(names(table(nodes$group)), "=", table(nodes$group), collapse = ", ")))
      if ("regulation" %in% colnames(nodes)) print(paste("Regulation types:", paste(names(table(nodes$regulation)), "=", table(nodes$regulation), collapse = ", ")))
      print(paste("Final target genes for enrichment:", length(target_genes)))
      print("=== END DIAGNOSTICS ===")
      
      if (length(target_genes) > 0) {
        # Run enrichment
        enrichment_results <- perform_target_gene_enrichment(target_genes, "human")
        
        # Store results
        network_rv$grn_results$target_pathway_enrichment <- enrichment_results
        
        if (!is.null(enrichment_results)) {
          showNotification(
            paste("✅ Found", nrow(enrichment_results), "enriched pathways for", length(target_genes), "target genes!"),
            type = "message"
          )
        } else {
          showNotification("No significant pathways found for target genes", type = "warning")
        }
      } else {
        showNotification("❌ No target genes found for enrichment", type = "error")
      }
    }
  })
  
  # Comparison plot for enrichment results
  output$enrichment_comparison_plot <- renderPlot({
    req(network_rv$grn_results$tf_pathway_enrichment,
        network_rv$grn_results$target_pathway_enrichment)
    
    tf_enrich <- network_rv$grn_results$tf_pathway_enrichment
    target_enrich <- network_rv$grn_results$target_pathway_enrichment
    
    # Get top N from each
    top_n <- input$comparison_top_n %||% 10
    
    # Prepare TF enrichment data
    tf_top <- tf_enrich %>%
      filter(Adjusted.P.value < 0.1) %>%
      arrange(Adjusted.P.value) %>%
      head(top_n) %>%
      mutate(
        Source = "TF Functions",
        Term_short = substr(gsub("\\s*\\(GO:.*\\)", "", Term), 1, 50),
        neg_log_p = -log10(Adjusted.P.value + 1e-10)
      ) %>%
      select(Term = Term_short, neg_log_p, Source, Adjusted.P.value)
    
    # Prepare Target enrichment data
    target_top <- target_enrich %>%
      filter(Adjusted.P.value < 0.1) %>%
      arrange(Adjusted.P.value) %>%
      head(top_n) %>%
      mutate(
        Source = "Target Effects",
        Term_short = substr(gsub("\\s*\\(GO:.*\\)", "", Term), 1, 50),
        neg_log_p = -log10(Adjusted.P.value + 1e-10)
      ) %>%
      select(Term = Term_short, neg_log_p, Source, Adjusted.P.value)
    
    # Combine
    combined <- bind_rows(tf_top, target_top)
    
    if (nrow(combined) == 0) {
      return(
        ggplot() +
          annotate("text", x = 0.5, y = 0.5, label = "No significant pathways found\n(p < 0.1)",
                   size = 6, color = "#7f8c8d") +
          theme_void()
      )
    }
    
    # Create comparison plot
    ggplot(combined, aes(x = neg_log_p, y = reorder(Term, neg_log_p), fill = Source)) +
      geom_col(position = position_dodge(width = 0.8), width = 0.7, alpha = 0.85) +
      geom_vline(xintercept = -log10(0.05), linetype = "dashed", color = "#e74c3c", linewidth = 0.8) +
      annotate("text", x = -log10(0.05) + 0.3, y = 1, label = "p = 0.05", 
               color = "#e74c3c", size = 3, hjust = 0) +
      scale_fill_manual(values = c("TF Functions" = "#3498db", "Target Effects" = "#9b59b6")) +
      labs(
        title = "TF Functions vs Target Gene Effects",
        subtitle = "Comparing enrichment between master regulators and their downstream targets",
        x = "-log₁₀(Adjusted P-value)",
        y = NULL,
        fill = "Analysis Type"
      ) +
      theme_minimal(base_size = 12) +
      theme(
        plot.title = element_text(face = "bold", size = 14),
        plot.subtitle = element_text(color = "#7f8c8d", size = 11),
        axis.text.y = element_text(size = 10),
        legend.position = "top",
        legend.title = element_text(face = "bold"),
        panel.grid.major.y = element_blank(),
        panel.grid.minor = element_blank()
      )
  })
  
  # Check if both enrichments available
  output$both_enrichments_available <- reactive({
    !is.null(network_rv$grn_results$tf_pathway_enrichment) &&
      !is.null(network_rv$grn_results$target_pathway_enrichment) &&
      nrow(network_rv$grn_results$tf_pathway_enrichment) > 0 &&
      nrow(network_rv$grn_results$target_pathway_enrichment) > 0
  })
  outputOptions(output, "both_enrichments_available", suspendWhenHidden = FALSE)
  
  
  # Download handler for comparison plot
  output$download_comparison_plot <- downloadHandler(
    filename = function() {
      paste0("GRN_Enrichment_Comparison_", Sys.Date(), ".pdf")
    },
    content = function(file) {
      load_export_packages()
      # Recreate the plot
      req(network_rv$grn_results$tf_pathway_enrichment)
      req(network_rv$grn_results$target_pathway_enrichment)
      
      library(ggplot2)
      n_pathways <- input$comparison_top_n %||% 10
      
      tf_data <- network_rv$grn_results$tf_pathway_enrichment %>%
        arrange(Adjusted.P.value) %>%
        slice_head(n = n_pathways) %>%
        mutate(
          Analysis = "TF-Only",
          neg_log_p = -log10(Adjusted.P.value),
          Term = substr(Term, 1, 50)
        )
      
      target_data <- network_rv$grn_results$target_pathway_enrichment %>%
        arrange(Adjusted.P.value) %>%
        slice_head(n = n_pathways) %>%
        mutate(
          Analysis = "Target Genes",
          neg_log_p = -log10(Adjusted.P.value),
          Term = substr(Term, 1, 50)
        )
      
      combined_data <- rbind(
        tf_data %>% select(Term, neg_log_p, Analysis),
        target_data %>% select(Term, neg_log_p, Analysis)
      )
      
      p <- ggplot(combined_data, aes(x = reorder(Term, neg_log_p), y = neg_log_p, fill = Analysis)) +
        geom_col(position = "dodge", alpha = 0.8, width = 0.7) +
        coord_flip() +
        scale_fill_manual(values = c("TF-Only" = "#1976d2", "Target Genes" = "#7b1fa2")) +
        labs(
          title = paste0("Top ", n_pathways, " Enriched Pathways: TF vs Target Analysis"),
          x = "Pathway Terms",
          y = "-log10(Adjusted P-value)",
          fill = "Analysis Type"
        ) +
        theme_minimal(base_size = 12) +
        theme(
          axis.text.y = element_text(size = 10),
          legend.position = "bottom",
          plot.title = element_text(hjust = 0.5, face = "bold")
        )
      
      ggsave(file, plot = p, width = 12, height = max(8, n_pathways * 0.4), dpi = 300)
    }
  )
  
