  # UPDATED TF-Only Table (replace existing output$grn_tf_pathways_table)
  output$grn_tf_only_table <- DT::renderDataTable({
    
    if (!is.null(network_rv$grn_results$tf_pathway_enrichment)) {
      
      tf_results <- network_rv$grn_results$tf_pathway_enrichment
      
      cat("TF enrichment columns available:", paste(colnames(tf_results), collapse = ", "), "\n")
      cat("TF enrichment rows:", nrow(tf_results), "\n")
      
      # Safety check: ensure required columns exist
      required_cols <- c("Term", "P.value", "Adjusted.P.value", "Genes")
      missing_cols <- setdiff(required_cols, colnames(tf_results))
      
      if (length(missing_cols) > 0) {
        cat("Missing required columns:", paste(missing_cols, collapse = ", "), "\n")
        return(DT::datatable(
          data.frame(Error = paste("Missing columns:", paste(missing_cols, collapse = ", "))),
          options = list(dom = 't'), rownames = FALSE
        ))
      }
      
      tryCatch({
        
        # STEP 1: Sort FIRST, before renaming columns
        tf_results_sorted <- tf_results %>%
          arrange(Adjusted.P.value)  # Use original column name
        
        # STEP 2: Then select and rename columns
        if ("gene_count" %in% colnames(tf_results_sorted) &&
            "database" %in% colnames(tf_results_sorted) &&
            "significance" %in% colnames(tf_results_sorted)) {
          
          # Full version with all custom columns
          pathways <- tf_results_sorted %>%
            select(
              Term,
              `P-value` = P.value,
              `Adj P-value` = Adjusted.P.value,
              `Gene Count` = gene_count,
              `Genes Involved` = Genes,
              Database = database,
              Significance = significance
            )
        } else {
          
          # Basic version - create custom columns
          pathways <- tf_results_sorted %>%
            mutate(
              gene_count = sapply(Genes, function(x) {
                if (is.na(x) || x == "") return(0)
                length(strsplit(as.character(x), ";")[[1]])
              }),
              database = "Mixed",
              significance = case_when(
                Adjusted.P.value < 0.001 ~ "Highly Significant",
                Adjusted.P.value < 0.01 ~ "Significant",
                Adjusted.P.value < 0.05 ~ "Moderately Significant",
                Adjusted.P.value < 0.1 ~ "Marginally Significant",
                TRUE ~ "Not Significant"
              )
            ) %>%
            select(
              Term,
              `P-value` = P.value,
              `Adj P-value` = Adjusted.P.value,
              `Gene Count` = gene_count,
              `Genes Involved` = Genes,
              Database = database,
              Significance = significance
            )
        }
        
        # STEP 3: Format the final columns
        pathways <- pathways %>%
          mutate(
            `P-value` = formatC(`P-value`, format = "e", digits = 2),
            `Adj P-value` = formatC(`Adj P-value`, format = "e", digits = 2),
            `Genes Involved` = gsub(";", ", ", as.character(`Genes Involved`))
          )
        
        # STEP 4: Create the datatable
        dt <- DT::datatable(
          pathways,
          extensions = 'Buttons',
          options = list(
            pageLength = 15,
            scrollX = TRUE,
            order = list(list(2, 'asc')),  # Sort by Adj P-value
            dom = 'Bfrtip',
            buttons = list(
              list(extend = 'copy', title = 'TF_Pathway_Enrichment'),
              list(extend = 'csv', filename = 'TF_Pathway_Enrichment', title = 'TF Pathway Enrichment'),
              list(extend = 'excel', filename = 'TF_Pathway_Enrichment', title = 'TF Pathway Enrichment')
            )
          ),
          rownames = FALSE
        )
        
        # STEP 5: Add styling if Significance column exists
        if ("Significance" %in% colnames(pathways)) {
          dt <- dt %>%
            DT::formatStyle('Significance',
                            backgroundColor = DT::styleEqual(
                              c('Highly Significant', 'Significant', 'Moderately Significant',
                                'Marginally Significant', 'Not Significant'),
                              c('#d1ecf1', '#d4edda', '#fff3cd', '#f8d7da', '#f8f9fa')
                            ),
                            color = DT::styleEqual(
                              c('Highly Significant', 'Significant', 'Moderately Significant',
                                'Marginally Significant', 'Not Significant'),
                              c('#0c5460', '#155724', '#856404', '#721c24', '#6c757d')
                            ))
        }
        
        return(dt)
        
      }, error = function(e) {
        cat("Error in TF table creation:", e$message, "\n")
        return(DT::datatable(
          data.frame(Error = paste("Table creation failed:", e$message)),
          options = list(dom = 't'), rownames = FALSE
        ))
      })
      
    } else {
      DT::datatable(
        data.frame(Message = "Click 'Run Analysis' to perform TF enrichment"),
        options = list(dom = 't'), rownames = FALSE
      )
    }
  }, server = FALSE)
  
