  # TF categories
  output$grn_tf_categories <- renderUI({
    
    tryCatch({
      if (!is.null(network_rv$grn_results$master_regulators)) {
        
        master_regs <- network_rv$grn_results$master_regulators
        tf_regs <- network_rv$grn_results$tf_regulations
        
        # Calculate Role (Activator/Repressor/Mixed) based on activation ratio
        # This should match the table's "Role" column calculation
        if (!is.null(tf_regs)) {
          role_data <- master_regs %>%
            rowwise() %>%
            mutate(
              n_activations = sum(tf_regs$tf == label & tf_regs$mor == 1, na.rm = TRUE),
              n_repressions = sum(tf_regs$tf == label & tf_regs$mor == -1, na.rm = TRUE),
              activation_ratio = ifelse(n_activations + n_repressions > 0,
                                        round(n_activations / (n_activations + n_repressions) * 100), 50),
              Role = case_when(
                activation_ratio >= 70 ~ "Activator",
                activation_ratio <= 30 ~ "Repressor",
                TRUE ~ "Mixed"
              )
            ) %>%
            ungroup()
          
          n_activators <- sum(role_data$Role == "Activator", na.rm = TRUE)
          n_repressors <- sum(role_data$Role == "Repressor", na.rm = TRUE)
          n_mixed <- sum(role_data$Role == "Mixed", na.rm = TRUE)
          total <- n_activators + n_repressors + n_mixed
          
          div(
            h6(icon("chart-pie"), " TF Categories", style = "color: #2c3e50; margin-bottom: 10px;"),
            div(style = "display: flex; flex-direction: column; gap: 8px;",
                div(style = "background: #d4edda; padding: 8px 12px; border-radius: 6px; display: flex; justify-content: space-between;",
                    span("Activators", style = "color: #155724;"),
                    strong(paste0(n_activators, " (", round(100 * n_activators / total, 0), "%)"), 
                           style = "color: #155724;")
                ),
                div(style = "background: #fff3cd; padding: 8px 12px; border-radius: 6px; display: flex; justify-content: space-between;",
                    span("Mixed", style = "color: #856404;"),
                    strong(paste0(n_mixed, " (", round(100 * n_mixed / total, 0), "%)"), 
                           style = "color: #856404;")
                ),
                div(style = "background: #f8d7da; padding: 8px 12px; border-radius: 6px; display: flex; justify-content: space-between;",
                    span("Repressors", style = "color: #721c24;"),
                    strong(paste0(n_repressors, " (", round(100 * n_repressors / total, 0), "%)"), 
                           style = "color: #721c24;")
                )
            )
          )
        } else {
          div(p("TF regulation data not available"))
        }
      } else {
        div(p("No master regulators data available"))
      }
    }, error = function(e) {
      div(
        p("Error calculating TF categories"),
        p(paste("Details:", e$message))
      )
    })
  })
  
