  # TF activity heatmap
  output$grn_activity_heatmap <- renderPlot({
    print("🎨 DEBUG: Starting grn_activity_heatmap rendering...")
    
    print(paste("  current_results$tf_activities is NULL?", 
                is.null(network_rv$current_results$tf_activities)))
    print(paste("  grn_results$tf_activities is NULL?", 
                is.null(network_rv$grn_results$tf_activities)))
    
    req(network_rv$current_results$tf_activities)
    print("  Passed req() check")
    
    # Use current_results consistently
    tf_activities <- network_rv$current_results$tf_activities
    
    print(paste("  tf_activities rows:", nrow(tf_activities)))
    print(paste("  tf_activities columns:", paste(colnames(tf_activities), collapse = ", ")))
    
    tryCatch({
      # ✅ FIX: Apply DEG filter at RENDER time (not just analysis time)
      filter_deg_only <- input$grn_filter_deg_tfs_only %||% FALSE
      
      if (filter_deg_only && !is.null(network_rv$current_results$analysis_params)) {
        # Get the DEG list from the analysis
        deg_genes <- NULL
        
        # Try to get DEGs from different possible sources
        if (!is.null(network_rv$grn_results$network_data$nodes)) {
          nodes <- network_rv$grn_results$network_data$nodes
          # Get genes that are actual DEGs (up or down regulated)
          if ("regulation" %in% colnames(nodes)) {
            deg_genes <- nodes$id[nodes$regulation %in% c("Up", "Down")]
          } else if ("group" %in% colnames(nodes)) {
            deg_genes <- nodes$id[nodes$group %in% c("upregulated", "downregulated")]
          }
        }
        
        # Also check if we have selected_genes stored
        if (is.null(deg_genes) && !is.null(network_rv$selected_genes)) {
          deg_genes <- c(network_rv$selected_genes$up_genes, 
                         network_rv$selected_genes$down_genes)
        }
        
        if (!is.null(deg_genes) && length(deg_genes) > 0) {
          # Filter tf_activities to only include TFs that are DEGs
          unique_tfs <- unique(tf_activities$tf)
          deg_tfs <- intersect(unique_tfs, deg_genes)
          
          print(paste("🎯 FILTER MODE: Filtering to DEG TFs only"))
          print(paste("   Total TFs in activities:", length(unique_tfs)))
          print(paste("   TFs that are also DEGs:", length(deg_tfs)))
          
          if (length(deg_tfs) > 0) {
            tf_activities <- tf_activities[tf_activities$tf %in% deg_tfs, ]
            print(paste("   Filtered to", length(unique(tf_activities$tf)), "DEG TFs"))
          } else {
            print("⚠️ No TFs found that are DEGs - showing all TFs")
          }
        } else {
          print("⚠️ Could not retrieve DEG list - showing all TFs")
        }
      } else {
        print("🌐 SHOW ALL MODE: Displaying all TFs")
      }
      
      # Create activity matrix
      activity_matrix <- tf_activities %>%
        dplyr::select(tf, sample, activity) %>%
        tidyr::pivot_wider(names_from = sample, values_from = activity) %>%
        tibble::column_to_rownames("tf") %>%
        as.matrix()
      
      print(paste("  Activity matrix dimensions:", nrow(activity_matrix), "x", ncol(activity_matrix)))
      
      # Filter by threshold
      threshold <- input$grn_activity_threshold %||% 0.5
      print(paste("  Activity threshold:", threshold))
      
      active_tfs <- rownames(activity_matrix)[apply(abs(activity_matrix), 1, max, na.rm = TRUE) >= threshold]
      print(paste("  TFs above threshold:", length(active_tfs)))
      
      if (length(active_tfs) > 0) {
        activity_subset <- activity_matrix[active_tfs, , drop = FALSE]
        
        print("  Creating pheatmap...")
        # Create heatmap with row scaling (z-score normalization per TF)
        # After row scaling, values become z-scores typically ranging from -3 to +3
        color_breaks <- seq(-3, 3, length.out = 51)
        
        # Create heatmap - capture the object for Shiny
        p <- pheatmap::pheatmap(
          activity_subset,
          scale = "row",
          cluster_rows = TRUE,
          cluster_cols = input$grn_cluster_activities %||% TRUE,
          color = colorRampPalette(c("#2166ac", "white", "#d73027"))(50),
          breaks = color_breaks,
          main = if (filter_deg_only) "TF Activity Scores (DEG TFs Only)" else "TF Activity Scores (All TFs)",
          fontsize = 10,
          angle_col = 45,
          silent = TRUE
        )
        
        # Draw the plot explicitly for Shiny
        grid::grid.newpage()
        grid::grid.draw(p$gtable)
        
        print("  ✅ Heatmap created successfully")
      } else {
        print("  ⚠️ No TFs above threshold - showing message")
        plot.new()
        text(0.5, 0.5, "No TFs above activity threshold", cex = 1.5)
      }
    }, error = function(e) {
      print(paste("  ❌ ERROR:", e$message))
      plot.new()
      text(0.5, 0.5, paste("Error creating heatmap:\n", e$message), cex = 1)
    })
  })
  
  # Download TF activity heatmap
  output$download_tf_activity_heatmap <- downloadHandler(
    filename = function() {
      paste0("TF_Activity_Heatmap_", Sys.Date(), ".png")
    },
    content = function(file) {
      req(network_rv$current_results$tf_activities)
      
      tf_activities <- network_rv$current_results$tf_activities
      
      # Check if DEG filter is enabled
      filter_deg_only <- input$grn_filter_deg_tfs_only %||% FALSE
      
      if (filter_deg_only && !is.null(network_rv$grn_results$network_data$nodes)) {
        nodes <- network_rv$grn_results$network_data$nodes
        deg_genes <- NULL
        if ("regulation" %in% colnames(nodes)) {
          deg_genes <- nodes$id[nodes$regulation %in% c("Up", "Down")]
        } else if ("group" %in% colnames(nodes)) {
          deg_genes <- nodes$id[nodes$group %in% c("upregulated", "downregulated")]
        }
        
        if (!is.null(deg_genes) && length(deg_genes) > 0) {
          unique_tfs <- unique(tf_activities$tf)
          deg_tfs <- intersect(unique_tfs, deg_genes)
          if (length(deg_tfs) > 0) {
            tf_activities <- tf_activities[tf_activities$tf %in% deg_tfs, ]
          }
        }
      }
      
      # Create activity matrix
      activity_matrix <- tf_activities %>%
        dplyr::select(tf, sample, activity) %>%
        tidyr::pivot_wider(names_from = sample, values_from = activity) %>%
        tibble::column_to_rownames("tf") %>%
        as.matrix()
      
      # Filter by threshold
      threshold <- input$grn_activity_threshold %||% 0.5
      active_tfs <- rownames(activity_matrix)[apply(abs(activity_matrix), 1, max, na.rm = TRUE) >= threshold]
      
      if (length(active_tfs) > 0) {
        activity_subset <- activity_matrix[active_tfs, , drop = FALSE]
        
        # Fixed breaks for z-scores (after row scaling)
        color_breaks <- seq(-3, 3, length.out = 51)
        
        # Calculate appropriate dimensions
        n_tfs <- nrow(activity_subset)
        n_samples <- ncol(activity_subset)
        plot_height <- max(8, n_tfs * 0.25 + 3)
        plot_width <- max(10, n_samples * 0.4 + 4)
        
        # Save to PNG with proper dimensions
        png(file, width = plot_width, height = plot_height, units = "in", res = 300)
        
        pheatmap::pheatmap(
          activity_subset,
          scale = "row",
          cluster_rows = TRUE,
          cluster_cols = input$grn_cluster_activities %||% TRUE,
          color = colorRampPalette(c("#2166ac", "white", "#d73027"))(50),
          breaks = color_breaks,
          main = if (filter_deg_only) "TF Activity Scores (DEG TFs Only)" else "TF Activity Scores (All TFs)",
          fontsize = 10,
          angle_col = 45
        )
        
        dev.off()
      }
    }
  )
  
