  output$grn_top_relationships <- DT::renderDataTable({
    
    tryCatch({
      if (!is.null(network_rv$grn_results$tf_regulations)) {
        
        tf_regs <- network_rv$grn_results$tf_regulations
        print("🔍 TF regulations columns:")
