        print("🔍 Sample tf_regulations data:")
        print(head(tf_regs))
        
        # Create relationships table with safer column handling
        relationships <- tf_regs %>%
          arrange(desc(confidence)) %>%
          head(100) %>%  # Get top 100 relationships
          mutate(
            # FIXED: Safer regulation type handling
            Regulation = if("mor" %in% colnames(tf_regs)) {
              ifelse(mor == 1, "Activation", ifelse(mor == -1, "Repression", "Unknown"))
            } else if("regulation_type" %in% colnames(tf_regs)) {
              ifelse(regulation_type == 1, "Activation", ifelse(regulation_type == -1, "Repression", "Unknown"))
            } else {
              "Unknown"
            }
          ) %>%
          select(
            `Transcription Factor` = tf,
            `Target Gene` = target,
            Regulation,
            `Confidence` = confidence
          ) %>%
          mutate(
            Confidence = round(Confidence, 3),
            Rank = row_number()  # Add rank column
          ) %>%
          select(Rank, everything())  # Put Rank first
        
        print("🔍 Created relationships table:")
        print(paste("Total relationships:", nrow(relationships)))
        print(head(relationships))
        
        # Color confidence by rank percentile
        DT::datatable(
          relationships,
          options = list(
            pageLength = 10,  # 10 per page
            dom = 'Bfrtip',  # Add buttons
            buttons = c('copy', 'csv', 'excel'),  # Download options
            scrollX = TRUE,
            order = list(list(0, 'asc'))  # Sort by Rank
          ),
          rownames = FALSE,
          extensions = 'Buttons'
        ) %>%
          formatStyle(
            'Confidence',
            background = styleColorBar(range(relationships$Confidence), '#E3F2FD'),
            backgroundSize = '100% 90%',
            backgroundRepeat = 'no-repeat',
            backgroundPosition = 'center'
          ) %>%
          formatStyle(
            'Rank',
            background = styleInterval(
              cuts = quantile(relationships$Rank, probs = c(0.25, 0.5, 0.75)),
              values = c('#4CAF50', '#8BC34A', '#FFC107', '#FF9800')
            ),
            color = 'white',
            fontWeight = 'bold'
          )
        
      } else {
        DT::datatable(
          data.frame(Message = "No TF regulations data available"),
          options = list(dom = 't'),
          rownames = FALSE
        )
      }
    }, error = function(e) {
      print(paste("Error in grn_top_relationships:", e$message))
      DT::datatable(
        data.frame(
          Error = "Data processing error",
          Details = paste("Error:", e$message),
          Solution = "Check TF regulations data format"
        ),
        options = list(dom = 't'),
        rownames = FALSE
      )
    })
  }, server = FALSE)
  
  
