  perform_tf_pathway_enrichment_fixed <- function(tf_list, organism = "human") {
    
    print("🛤️ Starting TF pathway enrichment analysis...")
    print(paste("Organism:", organism))
    
    # ✅ ROBUST INPUT VALIDATION
    if (is.null(tf_list) || length(tf_list) == 0) {
      print("⚠️ Empty or NULL TF list provided")
      return(NULL)
    }
    
    print(paste("Input TFs:", paste(head(tf_list, 5), collapse = ", ")))
    
    # Store original input count
    original_input_count <- length(tf_list)
    
    # Convert factors/other types to character safely
    if (is.factor(tf_list)) {
      tf_list <- as.character(levels(tf_list))[as.integer(tf_list)]
    } else if (!is.character(tf_list)) {
      tf_list <- as.character(tf_list)
    }
    
    # Remove NA, NULL, and empty values
    tf_list <- tf_list[!is.na(tf_list)]
    tf_list <- tf_list[!sapply(tf_list, is.null)]
    tf_list <- tf_list[nchar(trimws(tf_list)) > 0]
    
    if (length(tf_list) == 0) {
      print("⚠️ No valid TFs after initial cleaning")
      return(NULL)
    }
    
    # Clean gene names
    tf_list_clean <- vapply(tf_list, function(x) {
      cleaned <- gsub("[^A-Za-z0-9_-]", "", trimws(as.character(x)))
      return(cleaned)
    }, FUN.VALUE = character(1), USE.NAMES = FALSE)
    
    tf_list_clean <- unique(tf_list_clean[nchar(tf_list_clean) > 0])
    
    if (length(tf_list_clean) == 0) {
      print("⚠️ No valid TFs after character cleaning")
      return(NULL)
    }
    
    print(paste("✅ Cleaned TF list:", length(tf_list_clean), "genes"))
    print(paste("   Examples:", paste(head(tf_list_clean, 5), collapse = ", ")))
    
    # GET ORGANISM-SPECIFIC DATABASES
    databases <- get_enrichr_databases(organism)
    
    if (is.null(databases) || length(databases) == 0) {
      print("⚠️ No databases available for organism")
      return(NULL)
    }
    
    print(paste("🔍 Using", length(databases), "databases for", organism))
    print(paste("   Databases:", paste(head(databases, 3), collapse = ", "), "..."))
    print("🔎 Using enrichR for TF pathway analysis...")
    
    # ✅ WRAP ENTIRE enrichR INTERACTION IN TRYCATCH
    enrichment_results <- tryCatch({
      
      # Check if enrichR is loaded
      if (!requireNamespace("enrichR", quietly = TRUE)) {
        print("❌ enrichR package not available")
        return(NULL)
      }
      
      # ✅ FIX: MANUALLY SET enrichR OPTIONS BEFORE setEnrichrSite
      # This fixes the "invalid 'pattern' argument" error
      options(enrichR.base.address = "https://maayanlab.cloud/Enrichr/")
      options(enrichR.sites.base.address = "https://maayanlab.cloud/")
      options(enrichR.sites = c("Enrichr", "FlyEnrichr", "WormEnrichr", "YeastEnrichr", "FishEnrichr", "OxEnrichr"))
      options(enrichR.live = TRUE)
      options(enrichR.quiet = FALSE)
      
      print("✅ enrichR options set manually")
      
      # Now try setEnrichrSite (optional - may still fail but we have fallback)
      tryCatch({
        enrichR::setEnrichrSite("Enrichr")
        print("✅ setEnrichrSite successful")
      }, error = function(e) {
        print(paste("⚠️ setEnrichrSite failed, but options are set manually:", e$message))
        # Continue anyway since we set options manually
      })
      
      # ✅ FIX: Run enrichment ONE DATABASE AT A TIME to isolate errors
      all_results <- NULL
      successful_dbs <- 0
      
      for (db in databases) {
        db_result <- tryCatch({
          print(paste("   Querying:", db))
          
          # Query single database
          single_result <- tx_enrichr_local(
            genes = tf_list_clean,
            databases = db
          )
          
          if (!is.null(single_result) && 
              !is.null(single_result[[db]]) && 
              is.data.frame(single_result[[db]]) &&
              nrow(single_result[[db]]) > 0) {
            
            # Simplify database name for display
            db_label <- gsub("_20[0-9]{2}.*", "", db)
            db_label <- gsub("_", " ", db_label)
            
            temp_results <- single_result[[db]] %>%
              mutate(database = db_label)
            
            successful_dbs <- successful_dbs + 1
            temp_results
          } else {
            NULL
          }
        }, error = function(e) {
          print(paste("   ⚠️ Error with", db, ":", e$message))
          NULL
        })
        
        if (!is.null(db_result)) {
          all_results <- bind_rows(all_results, db_result)
        }

        Sys.sleep(0.1)
      }

      print(paste("✅ Successfully queried", successful_dbs, "of", length(databases), "databases"))
      all_results

    }, error = function(e) {
      print(paste("❌ Error in enrichR processing:", e$message))
      NULL
    })
    
    # Process results
    if (!is.null(enrichment_results) && nrow(enrichment_results) > 0) {
      
      enrichment_results$gene_count <- sapply(enrichment_results$Genes, function(x) {
        if (is.na(x) || x == "") return(0)
        length(strsplit(as.character(x), ";")[[1]])
      })
      
      enrichment_results$significance <- case_when(
        enrichment_results$Adjusted.P.value < 0.001 ~ "Highly Significant",
        enrichment_results$Adjusted.P.value < 0.01 ~ "Significant",
        enrichment_results$Adjusted.P.value < 0.05 ~ "Moderately Significant",
        enrichment_results$Adjusted.P.value < 0.1 ~ "Marginally Significant",
        TRUE ~ "Not Significant"
      )
      
      # Add metadata
      attr(enrichment_results, "original_input_count") <- original_input_count
      attr(enrichment_results, "cleaned_input_count") <- length(tf_list_clean)
      attr(enrichment_results, "organism") <- organism
      attr(enrichment_results, "databases_used") <- databases
      
      n_significant <- sum(enrichment_results$Adjusted.P.value < 0.05, na.rm = TRUE)
      print(paste("✅ Found", nrow(enrichment_results), "total pathways"))
      print(paste("✅ Found", n_significant, "significant TF pathways"))
      
      return(enrichment_results)
    }
    
    print("⚠️ No enrichment results found")
    return(NULL)
  }
  
  # TF Enrichment Details
  output$grn_tf_analysis_details <- renderUI({
    req(network_rv$grn_results$tf_pathway_enrichment)
    
    tf_results <- network_rv$grn_results$tf_pathway_enrichment
    
    tryCatch({
      # Get input counts from attributes (with safety checks)
      original_input <- attr(tf_results, "original_input_count")
      if (is.null(original_input)) original_input <- "Unknown"
      
      total_pathways <- nrow(tf_results)
      
      # Safe calculation of significant pathways
      if ("Adjusted.P.value" %in% colnames(tf_results)) {
        significant_pathways <- sum(tf_results$Adjusted.P.value < 0.05, na.rm = TRUE)
        sig_results <- tf_results[tf_results$Adjusted.P.value < 0.05 & !is.na(tf_results$Adjusted.P.value), ]
      } else {
        significant_pathways <- "Unknown"
        sig_results <- data.frame()
      }
      
      # Count genes in significant pathways
      genes_in_sig_pathways <- 0
      if (nrow(sig_results) > 0 && "Genes" %in% colnames(sig_results)) {
        genes_in_sig <- unique(unlist(strsplit(as.character(sig_results$Genes), ";")))
        genes_in_sig_pathways <- length(genes_in_sig[!is.na(genes_in_sig) & genes_in_sig != ""])
      }
      
      # Calculate coverage
      coverage <- "N/A"
      if (is.numeric(original_input) && genes_in_sig_pathways > 0) {
        coverage <- paste0(round((genes_in_sig_pathways / original_input) * 100, 1), "%")
      }
      
      div(
        class = "alert alert-info",
        h5("📊 TF Enrichment Analysis Details"),
        tags$ul(
          tags$li(strong("Input TFs: "), original_input),
          tags$li(strong("Total Pathways Found: "), total_pathways),
          tags$li(strong("Significant Pathways (p < 0.05): "), significant_pathways),
          tags$li(strong("TFs in Significant Pathways: "), genes_in_sig_pathways),
          tags$li(strong("Coverage: "), coverage)
        )
      )
      
    }, error = function(e) {
      div(
        class = "alert alert-warning",
        h5("⚠️ Analysis Details"),
        p("Details temporarily unavailable. Analysis results should still be visible in the table below.")
      )
    })
  })
  
  # Target Gene Enrichment Details
  output$grn_target_analysis_details <- renderUI({
    req(network_rv$grn_results$target_pathway_enrichment)
    
    target_results <- network_rv$grn_results$target_pathway_enrichment
    
    tryCatch({
      # Get input counts from attributes (with safety checks)
      original_input <- attr(target_results, "original_input_count")
      if (is.null(original_input)) original_input <- "Unknown"
      
      total_pathways <- nrow(target_results)
      
      # Safe calculation of significant pathways
      if ("Adjusted.P.value" %in% colnames(target_results)) {
        significant_pathways <- sum(target_results$Adjusted.P.value < 0.05, na.rm = TRUE)
        sig_results <- target_results[target_results$Adjusted.P.value < 0.05 & !is.na(target_results$Adjusted.P.value), ]
      } else {
        significant_pathways <- "Unknown"
        sig_results <- data.frame()
      }
      
      # Count genes in significant pathways
      genes_in_sig_pathways <- 0
      if (nrow(sig_results) > 0 && "Genes" %in% colnames(sig_results)) {
        genes_in_sig <- unique(unlist(strsplit(as.character(sig_results$Genes), ";")))
        genes_in_sig_pathways <- length(genes_in_sig[!is.na(genes_in_sig) & genes_in_sig != ""])
      }
      
      # Calculate coverage
      coverage <- "N/A"
      if (is.numeric(original_input) && genes_in_sig_pathways > 0) {
        coverage <- paste0(round((genes_in_sig_pathways / original_input) * 100, 1), "%")
      }
      
      div(
        class = "alert alert-info",
        h5("📊 Target Gene Enrichment Analysis Details"),
        tags$ul(
