  # Regulation patterns
  output$grn_regulation_patterns <- renderUI({
    
    tryCatch({
      # Calculate from available network data
      network_data <- network_rv$grn_results$network_data
      
      if (!is.null(network_data)) {
        n_nodes <- nrow(network_data$nodes %||% data.frame())
        n_edges <- nrow(network_data$edges %||% data.frame())
        n_tfs <- sum(network_data$nodes$group == "tf", na.rm = TRUE)
        n_upregulated <- sum(network_data$nodes$group == "upregulated", na.rm = TRUE)
        n_downregulated <- sum(network_data$nodes$group == "downregulated", na.rm = TRUE)
        
        # Calculate edge statistics if available
        if (!is.null(network_data$edges) && "title" %in% colnames(network_data$edges)) {
          n_activations <- sum(grepl("Activation", network_data$edges$title), na.rm = TRUE)
          n_repressions <- sum(grepl("Repression", network_data$edges$title), na.rm = TRUE)
          activation_pct <- round(n_activations / (n_activations + n_repressions) * 100, 1)
        } else {
          n_activations <- "Unknown"
          n_repressions <- "Unknown"
          activation_pct <- "Unknown"
        }
        
        div(
          h6("Network Statistics:"),
          p(paste("Total Nodes:", n_nodes)),
          p(paste("Total Edges:", n_edges)),
          p(paste("Transcription Factors:", n_tfs)),
          hr(),
          h6("Gene Regulation:"),
          p(paste("Upregulated Genes:", n_upregulated)),
          p(paste("Downregulated Genes:", n_downregulated)),
          p(paste("Unregulated Targets:", n_nodes - n_tfs - n_upregulated - n_downregulated)),
          hr(),
          h6("Edge Statistics:"),
          p(paste("Activations:", n_activations)),
          p(paste("Repressions:", n_repressions)),
          if (activation_pct != "Unknown") p(paste("Activation %:", activation_pct, "%"))
        )
      } else {
        div(p("No network data available for regulation patterns"))
      }
    }, error = function(e) {
      div(
        p("Error calculating regulation patterns"),
        p(paste("Details:", e$message))
      )
    })
  })
  
