  fix_ppi_results_emergency <- function() {
    
    print("🚨 EMERGENCY PPI RESULTS FIX")
    
    # Check if we have results but wrong type
    if (!is.null(network_rv$current_results) &&
        isTRUE(network_rv$analysis_status == "complete")) {
      
      # Force correct analysis type
      network_rv$analysis_type <- "ppi"
      network_rv$current_results$analysis_type <- "ppi"
      
      # Ensure ppi_results is also set
      network_rv$ppi_results <- network_rv$current_results
      
      # Add missing fields if needed
      if (is.null(network_rv$current_results$summary_stats$n_edges)) {
        if (!is.null(network_rv$current_results$ppi_interactions)) {
          network_rv$current_results$summary_stats$n_edges <- nrow(network_rv$current_results$ppi_interactions)
        } else if (!is.null(network_rv$current_results$network_data$edges)) {
          network_rv$current_results$summary_stats$n_edges <- nrow(network_rv$current_results$network_data$edges)
        }
      }
      
      print("✅ Emergency fix applied")
      print(paste("  Analysis type:", network_rv$analysis_type))
      print(paste("  Results type:", network_rv$current_results$analysis_type))
      print(paste("  Has ppi_results:", !is.null(network_rv$ppi_results)))
      
      # Force UI refresh
      session$sendCustomMessage("forceUpdate", "emergency_fix_applied")
      
      return(TRUE)
    }
    
    print("❌ Emergency fix failed - no results to fix")
    return(FALSE)
  }
  
  
