  # Enhanced gene selection function
  select_genes_for_analysis <- function(deg_data, n_up = 10, n_down = 10, priority = "combined") {
    
    # Ensure required columns exist
    required_cols <- c("log2FC", "P.Value", "adj.P.Val")
    missing_cols <- setdiff(required_cols, colnames(deg_data))
    if (length(missing_cols) > 0) {
      stop(paste("Missing required columns:", paste(missing_cols, collapse = ", ")))
    }
    
    # Create combined score for prioritization
    deg_data_scored <- deg_data %>%
      mutate(
        abs_logFC = abs(log2FC),
        neg_log_pval = -log10(P.Value + 1e-10),
        neg_log_adj_pval = -log10(adj.P.Val + 1e-10),
        combined_score = scale(abs_logFC)[,1] + scale(neg_log_adj_pval)[,1]
      )
    
    # Select genes based on priority method
    if (priority == "log2FC") {
      deg_data_sorted <- deg_data_scored %>% arrange(desc(abs_logFC))
    } else if (priority == "P.Value") {
      deg_data_sorted <- deg_data_scored %>% arrange(PValue)
    } else {  # combined
      deg_data_sorted <- deg_data_scored %>% arrange(desc(combined_score))
    }
    
    # Split into up and down regulated
    up_genes <- deg_data_sorted %>%
      filter(log2FC > 0) %>%
      slice_head(n = n_up) %>%
      rownames()
    
    down_genes <- deg_data_sorted %>%
      filter(log2FC < 0) %>%
      slice_head(n = n_down) %>%
      rownames()
    
    return(list(
      up_genes = up_genes,
      down_genes = down_genes,
      all_genes = c(up_genes, down_genes),
      selection_stats = list(
        n_up_selected = length(up_genes),
        n_down_selected = length(down_genes),
        total_deg_genes = nrow(deg_data),
        priority_method = priority
      )
    ))
  }
  
