  #' Extract All Genes from Selected Genes Structure
  extract_all_genes_clean <- function(selected_genes) {
    
    all_genes <- c()
    
    # Extract from all possible sources
    if (!is.null(selected_genes$up_genes)) {
      all_genes <- c(all_genes, unlist(selected_genes$up_genes))
    }
    if (!is.null(selected_genes$down_genes)) {
      all_genes <- c(all_genes, unlist(selected_genes$down_genes))
    }
    if (!is.null(selected_genes$all_genes)) {
      all_genes <- c(all_genes, unlist(selected_genes$all_genes))
    }
    
    # Clean and deduplicate
    all_genes <- unique(all_genes[!is.na(all_genes) & all_genes != "" & all_genes != "NA"])
    
    return(all_genes)
  }
  
  
  
  #' Convert STRING Results to Clean Format
  convert_string_to_clean_format <- function(string_interactions, mapped_genes) {
    
    # Create mapping from STRING ID to gene symbol
    id_to_gene <- setNames(mapped_genes$gene, mapped_genes$STRING_id)
    
    # Convert interactions
    clean_interactions <- data.frame(
      protein_a = character(nrow(string_interactions)),
      protein_b = character(nrow(string_interactions)),
      confidence_score = as.numeric(string_interactions$combined_score) / 1000,
      stringsAsFactors = FALSE
    )
    
    # Map STRING IDs back to gene symbols
    for (i in 1:nrow(string_interactions)) {
      from_id <- as.character(string_interactions$from[i])
      to_id <- as.character(string_interactions$to[i])
      
      # Direct mapping
      from_gene <- id_to_gene[from_id]
      to_gene <- id_to_gene[to_id]
      
      # If direct mapping fails, try without species prefix
      if (is.na(from_gene)) {
        clean_from <- gsub("^[0-9]+\\.", "", from_id)
        from_gene <- id_to_gene[clean_from]
      }
      if (is.na(to_gene)) {
        clean_to <- gsub("^[0-9]+\\.", "", to_id)
        to_gene <- id_to_gene[clean_to]
      }
      
      # Last resort: use the cleaned ID as gene name
      if (is.na(from_gene)) from_gene <- gsub("^[0-9]+\\.", "", from_id)
      if (is.na(to_gene)) to_gene <- gsub("^[0-9]+\\.", "", to_id)
      
      clean_interactions$protein_a[i] <- from_gene
      clean_interactions$protein_b[i] <- to_gene
    }
    
    # Remove any rows with missing gene names
    clean_interactions <- clean_interactions[
      !is.na(clean_interactions$protein_a) & !is.na(clean_interactions$protein_b),
    ]
    
    return(clean_interactions)
  }
  
  
  #' Build Complete PPI Results Structure
  build_ppi_results_clean <- function(interactions, selected_genes, all_input_genes) {
    
    cat("📊 Building complete results structure...\n")
    
    # Get all proteins in network
    all_proteins <- unique(c(interactions$protein_a, interactions$protein_b))
    
    # Build hub analysis
    hub_data <- calculate_hub_analysis_clean(interactions, selected_genes, all_input_genes)
    
    # Build network metrics
    network_metrics <- calculate_network_metrics_clean(interactions)
    
    # Build network visualization
    network_viz <- create_network_visualization_clean(interactions, selected_genes, all_input_genes, hub_data)
    
    # Build summary statistics
    summary_stats <- calculate_summary_stats_clean(interactions, hub_data, network_metrics)
    
    # Compile final results
    results <- list(
      # Core data for tables
      ppi_interactions = interactions,
      hub_proteins = hub_data,
      network_metrics = network_metrics,
      summary_stats = summary_stats,
      
      # Visualization
      network_data = network_viz,
      
      # Metadata
      analysis_type = "ppi",
      analysis_params = list(
        n_input_genes = length(all_input_genes),
        n_interactions = nrow(interactions),
        n_proteins = length(all_proteins),
        analysis_timestamp = Sys.time()
      )
    )
    
    cat("✅ Results structure built successfully\n")
    return(results)
  }
  
  #' Calculate Hub Analysis - Clean Implementation
  calculate_hub_analysis_clean <- function(interactions, selected_genes, all_input_genes) {
    
    if (nrow(interactions) == 0) {
      return(data.frame(
        gene = character(0),
        degree = numeric(0),
        hub_type = character(0),
        gene_source = character(0),
        stringsAsFactors = FALSE
      ))
    }
    
    # Count connections for each protein
    protein_connections <- table(c(interactions$protein_a, interactions$protein_b))
    
    # Build hub analysis dataframe
    hub_data <- data.frame(
      gene = names(protein_connections),
      degree = as.numeric(protein_connections),
      stringsAsFactors = FALSE
    )
    
    # Add hub classification
    hub_data$hub_type <- ifelse(hub_data$degree >= 5, "Major Hub",
                                ifelse(hub_data$degree >= 3, "Hub",
                                       ifelse(hub_data$degree >= 2, "Connector", "Peripheral")))
    
    # Add gene source classification
    hub_data$gene_source <- sapply(hub_data$gene, function(gene) {
      if (gene %in% unlist(selected_genes$up_genes)) {
        return("Up-regulated")
      } else if (gene %in% unlist(selected_genes$down_genes)) {
        return("Down-regulated")
      } else if (gene %in% all_input_genes) {
        return("Input gene")
      } else {
        return("Network neighbor")
      }
    })
    
    # Sort by degree
    hub_data <- hub_data[order(hub_data$degree, decreasing = TRUE), ]
    
    return(hub_data)
  }
  
  #' Calculate Network Metrics - Clean Implementation
  calculate_network_metrics_clean <- function(interactions) {
    
    if (nrow(interactions) == 0) {
      return(list(
        global_metrics = list(
          n_nodes = 0, n_edges = 0, density = 0,
          avg_degree = 0, clustering_coefficient = 0
        )
      ))
    }
    
    # Basic network statistics
    all_proteins <- unique(c(interactions$protein_a, interactions$protein_b))
    n_nodes <- length(all_proteins)
    n_edges <- nrow(interactions)
    
    # Calculate density
    max_possible_edges <- n_nodes * (n_nodes - 1) / 2
    density <- ifelse(max_possible_edges > 0, n_edges / max_possible_edges, 0)
    
    # Calculate average degree
    avg_degree <- ifelse(n_nodes > 0, (2 * n_edges) / n_nodes, 0)
    
    # For clustering coefficient, use igraph if available
    clustering_coeff <- 0
    if (requireNamespace("igraph", quietly = TRUE)) {
      tryCatch({
        g <- igraph::graph_from_data_frame(interactions[, c("protein_a", "protein_b")], directed = FALSE)
        clustering_coeff <- igraph::transitivity(g, type = "global")
        if (is.na(clustering_coeff)) clustering_coeff <- 0
      }, error = function(e) {
        clustering_coeff <- 0
      })
    }
    
    global_metrics <- list(
      n_nodes = n_nodes,
      n_edges = n_edges,
      density = density,
      avg_degree = avg_degree,
      clustering_coefficient = clustering_coeff
    )
    
    return(list(global_metrics = global_metrics))
  }
  
  #' Create Network Visualization - Clean Implementation
  create_network_visualization_clean <- function(interactions, selected_genes, all_input_genes, hub_data) {
    
    if (!requireNamespace("visNetwork", quietly = TRUE) || nrow(interactions) == 0) {
      return(NULL)
    }
    
    # Get all proteins
    all_proteins <- unique(c(interactions$protein_a, interactions$protein_b))
    
    # Create nodes dataframe
    nodes <- data.frame(
      id = all_proteins,
      label = all_proteins,
      stringsAsFactors = FALSE
    )
    
    # Add colors based on gene source
    nodes$color <- sapply(nodes$id, function(protein) {
      if (protein %in% unlist(selected_genes$up_genes)) {
        return("#e74c3c")  # Red for up-regulated
      } else if (protein %in% unlist(selected_genes$down_genes)) {
        return("#3498db")  # Blue for down-regulated
      } else if (protein %in% all_input_genes) {
        return("#95a5a6")  # Gray for other input genes
      } else {
        return("#f39c12")  # Orange for network neighbors
      }
    })
    
    # Add sizes based on degree
    nodes$size <- sapply(nodes$id, function(protein) {
      degree <- hub_data$degree[hub_data$gene == protein]
      if (length(degree) > 0 && degree > 0) {
        return(20 + (degree * 3))  # Scale size with degree
      } else {
        return(20)  # Default size
      }
    })
    
    # Add tooltips
    nodes$title <- paste0("<b>", nodes$id, "</b><br>",
                          "Connections: ", sapply(nodes$id, function(p) {
                            deg <- hub_data$degree[hub_data$gene == p]
                            if (length(deg) > 0) deg else 0
                          }))
    
    # Create edges dataframe
    edges <- data.frame(
      from = interactions$protein_a,
      to = interactions$protein_b,
      width = pmax(1, interactions$confidence_score * 5),
      title = paste("Confidence:", round(interactions$confidence_score, 3)),
      color = "#7f8c8d",
      stringsAsFactors = FALSE
    )
    
    # Create the network
    network <- visNetwork::visNetwork(nodes, edges) %>%
      visNetwork::visOptions(
        highlightNearest = TRUE,
        nodesIdSelection = TRUE
      ) %>%
      visNetwork::visLayout(randomSeed = 123) %>%
      visNetwork::visPhysics(
        stabilization = list(enabled = TRUE, iterations = 100)
      ) %>%
      visNetwork::visInteraction(
        navigationButtons = TRUE,
        dragNodes = TRUE,
        dragView = TRUE,
        zoomView = TRUE
      )
    
    return(network)
  }
  
  #' Calculate Summary Statistics - Clean Implementation
  calculate_summary_stats_clean <- function(interactions, hub_data, network_metrics) {
    
    n_proteins <- length(unique(c(interactions$protein_a, interactions$protein_b)))
    n_interactions <- nrow(interactions)
    n_hubs <- sum(hub_data$hub_type %in% c("Hub", "Major Hub"), na.rm = TRUE)
    
    basic_stats <- list(
      total_proteins = n_proteins,
      total_interactions = n_interactions
    )
    
    hub_stats <- list(
      total_hubs = n_hubs
    )
    
    topology_stats <- list(
      density = network_metrics$global_metrics$density,
      avg_degree = network_metrics$global_metrics$avg_degree,
      clustering_coefficient = network_metrics$global_metrics$clustering_coefficient
    )
    
    return(list(
      basic_stats = basic_stats,
      hub_stats = hub_stats,
      topology_stats = topology_stats
    ))
  }
  
  #' Create Empty PPI Result
  create_empty_ppi_result <- function(message = "No data available") {
    
    return(list(
      ppi_interactions = data.frame(
        protein_a = character(0),
        protein_b = character(0),
        confidence_score = numeric(0),
        stringsAsFactors = FALSE
      ),
      hub_proteins = data.frame(
        gene = character(0),
        degree = numeric(0),
        hub_type = character(0),
        gene_source = character(0),
        stringsAsFactors = FALSE
      ),
      network_metrics = list(
        global_metrics = list(n_nodes = 0, n_edges = 0, density = 0, avg_degree = 0)
      ),
      summary_stats = list(
        basic_stats = list(total_proteins = 0, total_interactions = 0),
        hub_stats = list(total_hubs = 0),
        topology_stats = list(density = 0)
      ),
      network_data = NULL,
      analysis_type = "ppi",
      analysis_params = list(error_message = message)
    ))
  }
  
  # ==============================================================================
  # CLEAN OUTPUT FUNCTIONS FOR SHINY
  # ==============================================================================
  
  
  
  #' Clean Network Visualization Output
  output$ppi_network_advanced <- renderVisNetwork({

    req(network_rv$current_results)
    req(network_rv$current_results$analysis_type == "ppi")

    network_data <- network_rv$current_results$network_data
    drug_sum     <- network_rv$current_results$druggability_summary
    centrality   <- network_rv$current_results$centrality_measures
    # Debug logging
    cat("\n=== PPI Network Debug ===\n")
    cat("Analysis type:", network_rv$current_results$analysis_type, "\n")
    cat("Network data exists:", !is.null(network_data), "\n")
    if (!is.null(network_data)) {
      cat("Nodes exist:", !is.null(network_data$nodes), "\n")
      cat("Edges exist:", !is.null(network_data$edges), "\n")
      if (!is.null(network_data$nodes)) cat("Number of nodes:", nrow(network_data$nodes), "\n")
      if (!is.null(network_data$edges)) cat("Number of edges:", nrow(network_data$edges), "\n")
    }
    cat("========================\n\n")

    if (is.null(network_data) || is.null(network_data$nodes) || nrow(network_data$nodes) == 0) {
      return(visNetwork(
        nodes = data.frame(id = "No Data", label = "No Network Data Available", color = "#cccccc"),
        edges = data.frame()
      ))
    }

    nodes <- network_data$nodes
    edges <- network_data$edges

    # ---------- Druggability + consensus overlays ----------
    drug_mode     <- input$ppi_druggable_mode %||% "off"
    show_cons     <- isTRUE(input$ppi_highlight_consensus)
    consensus_n   <- input$ppi_consensus_topn %||% 10

    # Druggable gene set (match by node label uppercased; fall back to id)
    node_symbols <- toupper(as.character(nodes$label %||% nodes$id))
    druggable_set <- character(0)
    if (!is.null(drug_sum) && is.data.frame(drug_sum) && nrow(drug_sum) > 0) {
      druggable_set <- toupper(as.character(drug_sum$gene))
    }
    is_drug_node <- node_symbols %in% druggable_set

    # Consensus hub set (Top-N per algorithm, appearing in >= half of them)
    consensus_set <- character(0)
    if (show_cons && !is.null(centrality) && nrow(centrality) > 0) {
      cons_df <- tryCatch(
        calculate_hub_consensus(centrality, top_n = as.integer(consensus_n)),
        error = function(e) NULL
      )
      if (!is.null(cons_df) && nrow(cons_df) > 0) {
        n_algos <- ncol(cons_df) - 2   # minus gene + consensus_score
        threshold <- max(2, ceiling(n_algos / 2))
        consensus_set <- toupper(cons_df$gene[cons_df$consensus_score >= threshold])
      }
    }
    is_cons_node <- node_symbols %in% consensus_set

    # "Druggable only" filter: keep druggable nodes + their 1-hop neighbors
    if (drug_mode == "only" && any(is_drug_node)) {
      keep_ids <- as.character(nodes$id[is_drug_node])
      if (!is.null(edges) && nrow(edges) > 0) {
        neighbor_ids <- unique(c(
          as.character(edges$to[edges$from %in% keep_ids]),
          as.character(edges$from[edges$to %in% keep_ids])
        ))
        keep_ids <- union(keep_ids, neighbor_ids)
        edges <- edges[edges$from %in% keep_ids & edges$to %in% keep_ids, , drop = FALSE]
      }
      keep_mask  <- as.character(nodes$id) %in% keep_ids
      nodes      <- nodes[keep_mask, , drop = FALSE]
      node_symbols <- node_symbols[keep_mask]
      is_drug_node <- is_drug_node[keep_mask]
      is_cons_node <- is_cons_node[keep_mask]
    }

    # Per-node decorations.
    #
    # Design goals informed by user feedback:
    #   - Default state should not look "near invisible" and toggling
    #     druggability should not cause a dramatic size/ring jump.
    #   - Consensus hubs should be obvious at a glance (⭐ prefix on the
    #     label, not only in the tooltip) when the checkbox is on.
    #   - Druggability detail is always available on hover via the tooltip;
    #     the "Highlight" mode adds a visible but restrained gold ring, no
    #     size boost, so the layout stays stable when toggled.
    if (!"borderWidth" %in% names(nodes)) nodes$borderWidth <- 2
    if (!"color.border" %in% names(nodes)) {
      nodes$color.border <- as.character(nodes$color)
    }

    if (drug_mode %in% c("highlight", "only")) {
      nodes$borderWidth[is_drug_node]  <- 4              # was 6 — less shouty
      nodes$color.border[is_drug_node] <- "#FFD700"      # gold (unchanged)
      # No size boost — avoids the abrupt layout shift on toggle
    }
    if (show_cons) {
      # Consensus hubs get a moderate purple ring AND a ⭐ prefix in the
      # visible label so they're identifiable without hovering.
      nodes$borderWidth[is_cons_node]  <- 5
      nodes$color.border[is_cons_node] <- "#8e44ad"      # purple
      if (any(is_cons_node)) {
        lbl <- as.character(nodes$label)
        # Guard against double-prefixing if this renderer re-runs
        already_starred <- startsWith(lbl, "⭐ ")
        nodes$label[is_cons_node & !already_starred] <-
          paste("⭐", lbl[is_cons_node & !already_starred])
      }
    }

    # Tooltip: centrality rank, consensus score, druggability summary
    if (!is.null(centrality) && nrow(centrality) > 0) {
      cent_idx <- match(node_symbols, toupper(centrality$gene))
      deg      <- centrality$degree[cent_idx]
      mcc      <- centrality$MCC[cent_idx]
      btw      <- centrality$betweenness[cent_idx]
    } else {
      deg <- mcc <- btw <- rep(NA_real_, nrow(nodes))
    }
    drug_idx <- match(node_symbols, toupper(drug_sum$gene %||% character(0)))
    n_drugs  <- drug_sum$n_drugs[drug_idx]
    n_appr   <- drug_sum$n_approved_drugs[drug_idx]
    stage_lbl <- drug_sum$max_approval_stage[drug_idx]

    mk_tooltip <- function(i) {
      gene_lbl <- nodes$label[i] %||% nodes$id[i]
      parts <- paste0("<b>", gene_lbl, "</b>")
      if (!is.na(deg[i]))   parts <- c(parts, paste0("Degree: ", deg[i]))
      if (!is.na(mcc[i]))   parts <- c(parts, paste0("MCC: ", signif(mcc[i], 3)))
      if (!is.na(btw[i]))   parts <- c(parts, paste0("Betweenness: ", signif(btw[i], 3)))
      if (!is.na(drug_idx[i])) {
        dr <- paste0("💊 Druggable (", n_drugs[i], " drugs")
        if (!is.na(n_appr[i]) && n_appr[i] > 0) {
          dr <- paste0(dr, ", ", n_appr[i], " approved")
        }
        dr <- paste0(dr, ")")
        if (!is.na(stage_lbl[i]) && stage_lbl[i] != "Unknown") {
          dr <- paste0(dr, "<br>Max stage: ", stage_lbl[i])
        }
        parts <- c(parts, dr)
      }
      if (is_cons_node[i]) parts <- c(parts, "⭐ Consensus hub")
      paste(parts, collapse = "<br>")
    }
    nodes$title <- vapply(seq_len(nrow(nodes)), mk_tooltip, character(1))

    print("🎨 Rendering PPI network visualization...")
    print(paste("✓ Network data found:", nrow(nodes), "nodes,",
                nrow(edges), "edges",
                "| druggable_mode=", drug_mode,
                "| consensus_highlight=", show_cons))

    tryCatch({

      # Create PPI network with ORIGINAL layout spacing but LARGE labels
      visNetwork(nodes, edges, width = "100%", height = "100%") %>%

        # 1. LARGE LABELS + zoom-responsive (only top-degree nodes labeled
        #    at default zoom; rest appear as you zoom in, so the canvas
        #    isn't a wall of text but every label is reachable)
        visNodes(
          font = list(
            size = 22,
            color = "black",
            strokeWidth = 3,     # heavier white outline for contrast
            strokeColor = "white",
            face = "Helvetica, Arial, sans-serif"
          ),
          borderWidth = 2,
          shadow = list(enabled = TRUE, size = 3),
          scaling = list(
            min = 22,            # ensure even low-degree nodes stay visible
            max = 55,
            label = list(enabled = TRUE, min = 16, max = 34,
                         maxVisible = 40, drawThreshold = 6)
          ),
          widthConstraint = list(maximum = 120),
          chosen = list(node = "function(values, id, selected, hovering) {
          values.size = values.size * 1.1;
          values.borderWidth = 3;
        }")
        ) %>%

        # 2. SIMPLE EDGE STYLING
        visEdges(
          smooth = list(enabled = TRUE, type = "continuous"),
          shadow = FALSE,
          color = list(
            color = "#c0c0c0",
            highlight = "#E74C3C",
            opacity = 0.55
          ),
          width = 1
        ) %>%
        
        # 3. GROUP STYLING (same as before)
        visGroups(
          groupname = "Up-regulated",
          color = list(background = "#E74C3C", border = "#C0392B"),
          shape = "dot"
        ) %>%
        visGroups(
          groupname = "Down-regulated",
          color = list(background = "#3498DB", border = "#2980B9"),
          shape = "dot"
        ) %>%
        visGroups(
          groupname = "Network",
          color = list(background = "#95A5A6", border = "#7F8C8D"),
          shape = "dot"
        ) %>%
        visGroups(
          groupname = "Input",
          color = list(background = "#F39C12", border = "#E67E22"),
          shape = "dot"
        ) %>%
        
        # 4. PHYSICS SETTINGS - tighter layout so labels are readable at
        #    default zoom, without losing overview of the whole network
        visPhysics(
          enabled = TRUE,
          solver = "forceAtlas2Based",
          forceAtlas2Based = list(
            gravitationalConstant = -120,    # Stronger spread → less overlap
            centralGravity = 0.02,           # Slightly more center pull
            springLength = 80,               # Shorter edges → compact graph
            springConstant = 0.1,            # Slightly stiffer springs
            damping = 0.4,
            avoidOverlap = 0.8               # Keep labels apart
          ),
          stabilization = list(
            enabled = TRUE,
            iterations = 800,                # More iterations for the tighter layout
            updateInterval = 25,
            onlyDynamicEdges = FALSE,
            fit = TRUE
          )
        ) %>%
        
        # 5. AUTO-STABILIZATION (keep this)
        visEvents(
          stabilizationIterationsDone = "function() {
          this.setOptions({ physics: false });
          console.log('PPI network stabilized - physics disabled');
        }"
        ) %>%
        
        # 6. INTERACTION OPTIONS (simplified)
        visOptions(
          highlightNearest = list(enabled = TRUE, degree = 1, hover = TRUE),
          nodesIdSelection = TRUE,
          selectedBy = "group",
          collapse = FALSE
        ) %>%
        
        # 7. INTERACTION CONTROLS (keep these)
        visInteraction(
          dragNodes = TRUE,
          dragView = TRUE,
          zoomView = TRUE,
          navigationButtons = TRUE,
          tooltipDelay = 200
        ) %>%
        
        # 8. CONSISTENT LAYOUT (same seed as before)
        visLayout(randomSeed = 12345) %>%
        
        # 9. LEGEND (keep this)
        visLegend(
          useGroups = TRUE,
          position = "right",
          width = 0.12,  # Smaller width to give more space to network
          zoom = FALSE
        )
      
    }, error = function(e) {
      print(paste("❌ Error creating PPI network visualization:", e$message))
      
      return(visNetwork(
        nodes = data.frame(
          id = "error_node",
          label = paste("Network Error:", e$message),
          color = "#E74C3C"
        ),
        edges = data.frame()
      ))
    })
  })
  
