    cat("\n=== PPI RESULTS STRUCTURE CHECK ===\n")
    
    if (!is.null(network_rv$current_results)) {
      cat("current_results fields:\n")
      print(names(network_rv$current_results))
      
      cat("\nanalysis_type value:",
          network_rv$current_results$analysis_type %||% "NULL/missing", "\n")
      
      # Check if we have PPI-specific fields
      has_ppi_fields <- all(c("ppi_interactions", "network_data", "hub_proteins") %in%
                              names(network_rv$current_results))
      cat("Has PPI-specific fields:", has_ppi_fields, "\n")
      
      if (!is.null(network_rv$current_results$network_data)) {
        cat("Network nodes:", nrow(network_rv$current_results$network_data$nodes), "\n")
        cat("Network edges:", nrow(network_rv$current_results$network_data$edges), "\n")
      }
    } else {
      cat("No current_results found\n")
    }
    
    if (!is.null(network_rv$ppi_results)) {
      cat("\nppi_results exists: YES\n")
      cat("ppi_results$analysis_type:",
          network_rv$ppi_results$analysis_type %||% "NULL/missing", "\n")
    } else {
      cat("\nppi_results exists: NO\n")
    }
    
    cat("====================================\n\n")
  }
  
  
