  # Helper function to create summary table
  create_analysis_summary_table <- function(results, analysis_type) {
    
    print(paste("Creating summary table for analysis type:", analysis_type))
    
    tryCatch({
      switch(analysis_type,
             "drug_target" = {
               if (!is.null(results$drug_prioritization) && nrow(results$drug_prioritization) > 0) {
                 
                 # Check what columns actually exist
                 available_cols <- colnames(results$drug_prioritization)
                 print(paste("Available columns:", paste(available_cols, collapse = ", ")))
                 
                 # Build select statement based on available columns
                 select_cols <- list()
                 
                 if ("drug_name" %in% available_cols) select_cols$Drug <- "drug_name"
                 if ("molecule_name" %in% available_cols && !"drug_name" %in% available_cols) select_cols$Drug <- "molecule_name"
                 if ("n_targets" %in% available_cols) select_cols$Targets <- "n_targets"
                 if ("max_clinical_phase" %in% available_cols) select_cols$`Clinical Phase` <- "max_clinical_phase"
                 if ("clinical_phase" %in% available_cols && !"max_clinical_phase" %in% available_cols) select_cols$`Clinical Phase` <- "clinical_phase"
                 if ("priority_score" %in% available_cols) select_cols$`Priority Score` <- "priority_score"
                 if ("final_priority_score" %in% available_cols) select_cols$`Priority Score` <- "final_priority_score"
                 
                 # If we have columns to select, create the table
                 if (length(select_cols) > 0) {
                   table_data <- results$drug_prioritization
                   
                   # Safely select only existing columns
                   for (new_name in names(select_cols)) {
                     old_name <- select_cols[[new_name]]
                     if (old_name %in% colnames(table_data)) {
                       table_data[[new_name]] <- table_data[[old_name]]
                     }
                   }
                   
                   # Select final columns
                   final_cols <- intersect(names(select_cols), colnames(table_data))
                   if (length(final_cols) > 0) {
                     result_table <- table_data[, final_cols, drop = FALSE]
                     
                     # Round numeric columns
                     numeric_cols <- sapply(result_table, is.numeric)
                     result_table[numeric_cols] <- lapply(result_table[numeric_cols], function(x) round(x, 3))
                     
                     # Return top 10 rows
                     return(head(result_table, 10))
                   }
                 }
                 
                 # Fallback if column selection fails
                 return(data.frame(Message = "Drug data structure not compatible with table format"))
                 
               } else {
                 return(data.frame(Message = "No drug prioritization data available"))
               }
             },
             
             "grn" = {
               if (!is.null(results$master_regulators)) {
                 results$master_regulators %>%
                   select(`Transcription Factor` = tf,
                          `Target Genes` = n_targets,
                          `Avg Confidence` = avg_confidence,
                          `Master Score` = master_score) %>%
                   mutate(across(where(is.numeric), ~ round(.x, 3))) %>%
                   slice_head(n = 10)
               } else {
                 data.frame(Message = "No master regulators identified")
               }
             },
             
             "ppi" = {
               if (!is.null(results$hub_proteins)) {
                 results$hub_proteins %>%
                   select(Protein = gene,
                          Degree = degree,
                          `Betweenness Centrality` = betweenness,
                          `Hub Score` = hub_score) %>%
                   mutate(across(where(is.numeric), ~ round(.x, 3))) %>%
                   slice_head(n = 10)
               } else {
                 data.frame(Message = "No hub proteins identified")
               }
             },
             
             "wgcna" = {
               if (!is.null(results$modules)) {
                 module_summary <- data.frame(
                   Module = names(results$modules),
                   `Gene Count` = sapply(results$modules, length),
                   `Hub Genes` = sapply(names(results$modules), function(m) {
                     if (!is.null(results$hub_genes)) {
                       module_hubs <- results$hub_genes %>%
                         filter(module == m) %>%
                         slice_head(n = 3)
                       paste(module_hubs$gene, collapse = ", ")
                     } else {
                       "Not calculated"
                     }
                   }),
                   stringsAsFactors = FALSE
                 ) %>%
                   arrange(desc(`Gene Count`)) %>%
                   slice_head(n = 10)
                 
                 return(module_summary)
               } else {
                 data.frame(Message = "No modules identified")
               }
             },
             
             # Default case
             data.frame(Message = "Analysis results not available")
      )
    })
  }
  
