  # Additional helper functions for PPI analysis
  calculate_ppi_network_metrics <- function(ppi_interactions, selected_genes) {
    
    # Create graph from interactions
    library(igraph)
    
    g <- graph_from_data_frame(
      ppi_interactions[, c("gene_from", "gene_to")],
      directed = FALSE
    )
    
    metrics <- list(
      n_nodes = vcount(g),
      n_edges = ecount(g),
      density = edge_density(g),
      clustering_coefficient = transitivity(g, type = "global"),
      avg_degree = mean(degree(g)),
      diameter = diameter(g),
      avg_path_length = mean_distance(g)
    )
    
    return(metrics)
  }
  
  identify_ppi_hubs <- function(ppi_interactions, selected_genes) {
    
    library(igraph)
    
    # Create graph
    g <- graph_from_data_frame(
      ppi_interactions[, c("gene_from", "gene_to")],
      directed = FALSE
    )
    
    # Calculate centrality measures
    hub_metrics <- data.frame(
      gene = V(g)$name,
      degree = degree(g),
      betweenness = betweenness(g),
      closeness = closeness(g),
      eigenvector = eigen_centrality(g)$vector,
      stringsAsFactors = FALSE
    ) %>%
      mutate(
        hub_score = scale(degree)[,1] + scale(betweenness)[,1] + scale(eigenvector)[,1]
      ) %>%
      arrange(desc(hub_score)) %>%
      slice_head(n = 10)
    
    return(hub_metrics)
  }
  
  perform_ppi_functional_analysis <- function(ppi_interactions) {
    
    # Extract all proteins
    all_proteins <- unique(c(ppi_interactions$gene_from, ppi_interactions$gene_to))
    
    # Perform enrichment if enrichR is available
    if (require("enrichR", quietly = TRUE)) {
      databases <- c("GO_Biological_Process_2021", "KEGG_2021_Human")
      enrichment_results <- tx_enrichr_local(all_proteins, databases)
      return(enrichment_results)
    }
    
    return(NULL)
  }
  
  
  
