    if (!is.null(network_rv$current_results$opentargets_data) &&
        nrow(network_rv$current_results$opentargets_data) > 0) {
      plot_data <- network_rv$current_results$opentargets_data
    } else if (!is.null(network_rv$current_results$drug_targets) &&
               nrow(network_rv$current_results$drug_targets) > 0) {
      plot_data <- network_rv$current_results$drug_targets
    } else if (!is.null(network_rv$current_results$raw_data) &&
               nrow(network_rv$current_results$raw_data) > 0) {
      plot_data <- network_rv$current_results$raw_data
    }
    
    if (is.null(plot_data) || nrow(plot_data) == 0) {
      p <- ggplot() +
        geom_text(aes(x = 1, y = 1, label = "No safety data available"), size = 5) +
        theme_void() +
        labs(title = "Safety Score Distribution")
      return(ggplotly(p))
    }
    
    # Create safety score distribution
    if ("safety_score" %in% colnames(plot_data)) {
      safety_scores <- plot_data$safety_score
    } else {
      safety_scores <- plot_data$confidence_score
    }
    
    # Create histogram of safety scores
    p <- ggplot(data.frame(Safety_Score = safety_scores), aes(x = Safety_Score)) +
      geom_histogram(aes(fill = cut(Safety_Score, breaks = c(0, 0.3, 0.5, 0.8, 1.0))),
                     bins = 20, alpha = 0.8) +
      labs(
        title = "Safety Score Distribution",
        x = "Safety Score",
        y = "Number of Drugs",
        fill = "Risk Level"
      ) +
      theme_minimal() +
      scale_fill_manual(
        values = c('#f5c6cb', '#f8d7da', '#fff3cd', '#d4edda'),
        labels = c("Very High Risk", "High Risk", "Medium Risk", "Low Risk"),
        na.value = "grey"
      ) +
      theme(plot.title = element_text(hjust = 0.5))
    
    ggplotly(p, height = 300)
  })
  
  
  # Clinical Phase Plot
  output$clinical_phase_plot <- renderPlot({
    req(network_rv$current_results)
    req(network_rv$current_results$analysis_params$analysis_focus == "disease_context")

    clinical_data <- NULL
    if (!is.null(network_rv$current_results$opentargets_data) &&
        nrow(network_rv$current_results$opentargets_data) > 0) {
      clinical_data <- network_rv$current_results$opentargets_data
    } else {
      return(NULL)
    }
    
    print(paste("Clinical data rows for plot:", nrow(clinical_data)))
    
    # Create clinical phase distribution
    tryCatch({
      phase_data <- clinical_data %>%
        dplyr::count(clinical_phase) %>%
        dplyr::mutate(
          Phase = dplyr::case_when(
            clinical_phase == -1 ~ "Withdrawn",
            clinical_phase == 0 ~ "Preclinical",
            clinical_phase == 1 ~ "Phase I",
            clinical_phase == 2 ~ "Phase II",
            clinical_phase == 3 ~ "Phase III",
            clinical_phase == 4 ~ "Approved",
            TRUE ~ "Unknown"
          ),
          Phase = factor(Phase, levels = c("Preclinical", "Phase I", "Phase II", "Phase III", "Approved", "Withdrawn"))
        ) %>%
        dplyr::filter(!is.na(Phase))
      
      print("Creating clinical phase plot...")
      
      # Create the plot
      p <- ggplot(phase_data, aes(x = Phase, y = n, fill = Phase)) +
        geom_bar(stat = "identity", alpha = 0.8) +
        geom_text(aes(label = n), vjust = -0.3, size = 4) +  # Add numbers on bars
        labs(
          title = "Clinical Development Pipeline",
          x = "Development Phase",
          y = "Number of Drugs"
        ) +
        theme_minimal() +
        theme(
          legend.position = "none",
          axis.text.x = element_text(angle = 45, hjust = 1, size = 10),
          axis.text.y = element_text(size = 10),
          plot.title = element_text(hjust = 0.5, size = 14, face = "bold"),
          panel.grid.minor = element_blank()
        ) +
        scale_fill_manual(values = c(
          "Preclinical" = "#ffc107",
          "Phase I" = "#17a2b8",
          "Phase II" = "#007bff",
          "Phase III" = "#6f42c1",
          "Approved" = "#28a745",
          "Withdrawn" = "#dc3545"
        )) +
        scale_y_continuous(expand = expansion(mult = c(0, 0.1)))  # Add space at top for labels
      
      print("Clinical phase plot created successfully")
      return(p)
      
    }, error = function(e) {
      print(paste("Error creating clinical phase plot:", e$message))
      # Return a simple error plot
      ggplot() +
        geom_text(aes(x = 1, y = 1, label = paste("Plot error:", e$message)), size = 5) +
        theme_void() +
        labs(title = "Clinical Phase Distribution - Error")
    })
  }, height = 400)
  
