  # Clinical Evidence Table
  output$clinical_evidence_table <- DT::renderDataTable({
    req(network_rv$current_results)
    req(network_rv$current_results$analysis_params$analysis_focus == "disease_context")
    
    print("=== CLINICAL EVIDENCE TABLE DEBUG (FIXED) ===")
    
    # Get data from available sources
    evidence_data <- NULL
    if (!is.null(network_rv$current_results$opentargets_data) &&
        nrow(network_rv$current_results$opentargets_data) > 0) {
      evidence_data <- network_rv$current_results$opentargets_data
      print("Using opentargets_data for clinical evidence")
    } else if (!is.null(network_rv$current_results$drug_targets) &&
               nrow(network_rv$current_results$drug_targets) > 0) {
      evidence_data <- network_rv$current_results$drug_targets
      print("Using drug_targets for clinical evidence")
    } else if (!is.null(network_rv$current_results$raw_data) &&
               nrow(network_rv$current_results$raw_data) > 0) {
      evidence_data <- network_rv$current_results$raw_data
      print("Using raw_data for clinical evidence")
    }
    
    if (is.null(evidence_data) || nrow(evidence_data) == 0) {
      return(DT::datatable(
        data.frame(Message = "No clinical evidence data available"),
        options = list(dom = 't'), rownames = FALSE
      ))
    }
    
    print(paste("Clinical evidence data rows:", nrow(evidence_data)))
    cat("Available columns:", paste(colnames(evidence_data), collapse = ", "), "\n")
    
    # Create clinical evidence table with FIXED column selection
    tryCatch({
      
      # FIXED: Create the table step by step instead of using if() inside select()
      clinical_table <- evidence_data %>%
        dplyr::mutate(
          # Create all columns with proper fallbacks BEFORE selecting
          Gene = gene_name,
          Drug = molecule_name,
          `Clinical Phase Num` = clinical_phase,
          `Disease Area` = ifelse("disease_area" %in% colnames(evidence_data) & !is.na(disease_area) & disease_area != "",
                                  disease_area, "Multiple"),
          `Clinical Evidence Score` = ifelse("clinical_evidence_score" %in% colnames(evidence_data),
                                             clinical_evidence_score, confidence_score),
          `Druggability Score` = ifelse("druggability_score" %in% colnames(evidence_data),
                                        druggability_score, confidence_score),
          `Safety Score` = ifelse("safety_score" %in% colnames(evidence_data),
                                  safety_score, confidence_score)
        ) %>%
        # Now convert clinical phase to text
        dplyr::mutate(
          `Clinical Phase` = dplyr::case_when(
            `Clinical Phase Num` == -1 ~ "Withdrawn",
            `Clinical Phase Num` == 0 ~ "Preclinical",
            `Clinical Phase Num` == 1 ~ "Phase I",
            `Clinical Phase Num` == 2 ~ "Phase II",
            `Clinical Phase Num` == 3 ~ "Phase III",
            `Clinical Phase Num` == 4 ~ "Approved",
            TRUE ~ "Unknown"
          )
        ) %>%
        # Select final columns
        dplyr::select(
          Gene,
          Drug,
          `Clinical Phase`,
          `Disease Area`,
          `Clinical Evidence Score`,
          `Druggability Score`,
          `Safety Score`
        ) %>%
        # Arrange by clinical evidence score
        dplyr::arrange(desc(`Clinical Evidence Score`))
      
      print(paste("Clinical evidence table created with", nrow(clinical_table), "rows"))
      
      # Debug: Check for any missing values
      print("Clinical Phase distribution:")
      print(table(clinical_table$`Clinical Phase`, useNA = "always"))
      
      DT::datatable(
        clinical_table,
        options = list(
          pageLength = 15,
          scrollX = TRUE,
          dom = 'frtip'
        ),
        rownames = FALSE
      ) %>%
        DT::formatRound(c("Clinical Evidence Score", "Druggability Score", "Safety Score"), 3) %>%
        DT::formatStyle(
          'Clinical Phase',
          backgroundColor = DT::styleEqual(
            c("Approved", "Phase III", "Phase II", "Phase I", "Preclinical", "Withdrawn"),
            c('#28a745', '#6f42c1', '#007bff', '#17a2b8', '#ffc107', '#dc3545')
          ),
          color = "white"
        ) %>%
        DT::formatStyle(
          'Clinical Evidence Score',
          backgroundColor = DT::styleColorBar(c(0, 1), '#e3f2fd'),
          backgroundSize = '80% 80%',
          backgroundRepeat = 'no-repeat',
          backgroundPosition = 'center'
        )
      
    }, error = function(e) {
      print(paste("Error creating clinical evidence table:", e$message))
      print("Error details:")
      print(str(e))
      return(DT::datatable(
        data.frame(Error = paste("Error creating clinical evidence table:", e$message)),
        options = list(dom = 't'), rownames = FALSE
      ))
    })
  })
  
  create_analysis_parameters_summary <- function(results) {
    
    # Extract actual values from results
    analysis_focus <- results$analysis_params$analysis_focus %||% "unknown"
    input_genes <- results$conversion_stats$total_input %||% 0
    converted_genes <- results$conversion_stats$successful_conversions %||% 0
    conversion_rate <- if(input_genes > 0) round((converted_genes / input_genes) * 100, 1) else 0
    
    # Determine actual databases used based on analysis focus
    databases_used <- switch(analysis_focus,
                             "drug_discovery" = "ChEMBL",
                             "disease_context" = "OpenTargets",
                             "comprehensive" = "ChEMBL, OpenTargets",
                             "Unknown"
    )
    
    # Count actual results
    chembl_interactions <- if(!is.null(results$chembl_data)) nrow(results$chembl_data) else 0
    ot_interactions <- if(!is.null(results$opentargets_data)) nrow(results$opentargets_data) else 0
    total_drugs <- if(!is.null(results$drug_prioritization)) nrow(results$drug_prioritization) else 0
    
    summary_data <- data.frame(
      Parameter = c(
        "Analysis Focus",
        "Input Genes",
        "Converted Genes",
        "Conversion Rate",
        "Database(s) Used",
        "Max Drugs/Target",
        "Min Confidence",
        "ChEMBL Interactions",
        "OpenTargets Interactions",
        "Total Unique Drugs",
        "Analysis Status"
      ),
      Value = c(
        tools::toTitleCase(analysis_focus),
        as.character(input_genes),
        as.character(converted_genes),
        paste0(conversion_rate, "%"),
        databases_used,
        as.character(results$analysis_params$max_drugs_per_gene %||% "Unknown"),
        as.character(results$analysis_params$min_confidence %||% "Unknown"),
        as.character(chembl_interactions),
        as.character(ot_interactions),
        as.character(total_drugs),
        if(total_drugs > 0) "SUCCESS" else "LIMITED RESULTS"
      ),
      stringsAsFactors = FALSE
    )
    
    return(summary_data)
  }
  
  
  output$analysis_parameters_table <- DT::renderDataTable({
    req(network_rv$current_results)
    
    summary_data <- create_analysis_parameters_summary(network_rv$current_results)
    
    DT::datatable(
      summary_data,
      options = list(
        dom = 't',
        pageLength = 15,
        columnDefs = list(
          list(width = '200px', targets = 0),
          list(width = '150px', targets = 1)
        )
      ),
      rownames = FALSE
    ) %>%
      DT::formatStyle(
        'Parameter',
        fontWeight = 'bold'
      ) %>%
      DT::formatStyle(
        'Value',
        backgroundColor = DT::styleEqual(
          c("SUCCESS", "LIMITED RESULTS"),
          c('#d4edda', '#fff3cd')
        )
      )
  })
  
  
