  # Reusable builder — used by both the live plot and the download
  build_drug_priority_plot <- function(prio_data, n_top = 15) {
    if (is.null(prio_data) || nrow(prio_data) == 0) {
      return(ggplot() +
               annotate("text", x = 0.5, y = 0.5, label = "No drug prioritization data available",
                        size = 6, color = "#999") +
               theme_void())
    }

    score_col <- if ("comprehensive_score" %in% colnames(prio_data)) "comprehensive_score" else "priority_score"

    top_drugs <- prio_data %>%
      dplyr::arrange(dplyr::desc(.data[[score_col]])) %>%
      head(n_top) %>%
      dplyr::mutate(
        Phase = dplyr::case_when(
          max_clinical_phase >= 4 | (!is.null(is_approved) & is_approved == TRUE) ~ "Approved",
          max_clinical_phase >= 3 ~ "Phase III",
          max_clinical_phase >= 2 ~ "Phase II",
          max_clinical_phase >= 1 ~ "Phase I",
          TRUE ~ "Preclinical"
        ),
        Phase = factor(Phase, levels = c("Approved", "Phase III", "Phase II", "Phase I", "Preclinical")),
        drug_label = drug_name
      )

    phase_colors <- c(
      "Approved"    = "#27AE60",
      "Phase III"   = "#3498DB",
      "Phase II"    = "#9B59B6",
      "Phase I"     = "#F39C12",
      "Preclinical" = "#95A5A6"
    )

    ggplot(top_drugs, aes(x = reorder(drug_label, .data[[score_col]]),
                          y = .data[[score_col]], fill = Phase)) +
      geom_col(width = 0.75, color = "#444", linewidth = 0.3) +
      geom_text(aes(label = sprintf("%.2f", .data[[score_col]])),
                hjust = -0.15, size = 4, color = "#222") +
      scale_fill_manual(values = phase_colors, drop = FALSE) +
      coord_flip() +
      scale_y_continuous(expand = expansion(mult = c(0, 0.18))) +
      labs(
        title = paste("Top", nrow(top_drugs), "Drug Candidates by Priority Score"),
        x = NULL,
        y = "Priority Score",
        fill = "Clinical Phase"
      ) +
      guides(fill = guide_legend(nrow = 1, byrow = TRUE,
                                 title.position = "top", title.hjust = 0.5)) +
      theme_minimal(base_size = 14) +
      theme(
        plot.title = element_text(face = "bold", size = 16, margin = margin(b = 15)),
        plot.margin = margin(t = 15, r = 30, b = 15, l = 15),
        axis.text.y = element_text(face = "bold", color = "#222", size = 12),
        axis.text.x = element_text(color = "#222"),
        panel.grid.major.y = element_blank(),
        panel.grid.minor = element_blank(),
        legend.position = "bottom",
        legend.title = element_text(face = "bold"),
        legend.margin = margin(t = 10, b = 5),
        legend.box.margin = margin(t = 5)
      )
  }

  output$drug_priority_plot <- plotly::renderPlotly({
