  # =====================================================================
  # DRUG DISCOVERY VISUALIZATIONS — Top Druggable Targets + Interaction Type
  # =====================================================================

  build_top_targets_plot <- function(drug_targets_data, n_top = 15) {
    if (is.null(drug_targets_data) || nrow(drug_targets_data) == 0) {
      return(ggplot() + annotate("text", x = 0.5, y = 0.5,
                                 label = "No drug-target data available",
                                 size = 6, color = "#999") + theme_void())
    }
    gene_col <- if ("gene_name" %in% colnames(drug_targets_data)) "gene_name" else "gene"
    if (!gene_col %in% colnames(drug_targets_data)) gene_col <- colnames(drug_targets_data)[1]

    top_targets <- drug_targets_data %>%
      dplyr::filter(!is.na(.data[[gene_col]]) & .data[[gene_col]] != "") %>%
      dplyr::group_by(target = .data[[gene_col]]) %>%
      dplyr::summarise(n_drugs = dplyr::n_distinct(drug_name %||% molecule_name),
                       n_approved = sum(is_approved == TRUE, na.rm = TRUE),
                       .groups = "drop") %>%
      dplyr::arrange(dplyr::desc(n_drugs)) %>%
      head(n_top)

    ggplot(top_targets, aes(x = reorder(target, n_drugs), y = n_drugs, fill = n_approved)) +
      geom_col(width = 0.75, color = "#333", linewidth = 0.3) +
      geom_text(aes(label = n_drugs), hjust = -0.25, size = 4.2, color = "#222") +
      scale_fill_gradient(low = "#90CAF9", high = "#1565C0", name = "Approved\nDrugs") +
      coord_flip() +
      scale_y_continuous(expand = expansion(mult = c(0, 0.15))) +
      labs(title = paste("Top", nrow(top_targets), "Druggable Targets"),
           x = NULL, y = "Number of Unique Drugs Targeting Gene") +
      theme_minimal(base_size = 14) +
      theme(plot.title = element_text(face = "bold", size = 16, margin = margin(b = 12)),
            plot.margin = margin(t = 15, r = 30, b = 15, l = 15),
            axis.text.y = element_text(face = "bold", color = "#222", size = 12),
            panel.grid.major.y = element_blank(),
            panel.grid.minor = element_blank(),
            legend.position = "right")
  }

  output$drug_top_targets_plot <- plotly::renderPlotly({
    req(network_rv$current_results$drug_targets)
    p <- build_top_targets_plot(network_rv$current_results$drug_targets,
