  build_interaction_type_donut <- function(drug_targets_data) {
    if (is.null(drug_targets_data) || nrow(drug_targets_data) == 0 ||
        !"interaction_type" %in% colnames(drug_targets_data)) {
      return(ggplot() + annotate("text", x = 0.5, y = 0.5,
                                 label = "No interaction type data available",
                                 size = 6, color = "#999") + theme_void())
    }
    type_data <- drug_targets_data %>%
      dplyr::filter(!is.na(interaction_type) & interaction_type != "" & interaction_type != "Unknown") %>%
      dplyr::mutate(interaction_type = stringr::str_to_title(interaction_type)) %>%
      dplyr::count(interaction_type, name = "n") %>%
      dplyr::arrange(dplyr::desc(n))
    # Collapse long tail to "Other" for readability
    if (nrow(type_data) > 8) {
      top8 <- head(type_data, 8)
      other <- data.frame(interaction_type = "Other", n = sum(type_data$n[-(1:8)]))
      type_data <- rbind(top8, other)
    }
    if (nrow(type_data) == 0) {
      return(ggplot() + annotate("text", x = 0.5, y = 0.5,
                                 label = "No interaction types classified",
                                 size = 6, color = "#999") + theme_void())
    }
    type_data <- type_data %>%
      dplyr::mutate(pct = round(n / sum(n) * 100, 1),
                    label = paste0(interaction_type, "\n", n, " (", pct, "%)"),
                    interaction_type = factor(interaction_type, levels = interaction_type))

    ggplot(type_data, aes(x = 2, y = n, fill = interaction_type)) +
      geom_col(color = "white", linewidth = 1) +
      coord_polar(theta = "y", start = 0) +
      xlim(c(0.2, 2.6)) +
      scale_fill_brewer(palette = "Set2", name = "Interaction Type") +
      labs(title = "Drug-Target Interaction Types",
           subtitle = paste0("n = ", sum(type_data$n), " interactions")) +
      theme_void(base_size = 14) +
      theme(plot.title = element_text(face = "bold", size = 16, hjust = 0.5),
            plot.subtitle = element_text(size = 11, color = "#666", hjust = 0.5),
            plot.margin = margin(15, 15, 15, 15),
            legend.position = "right",
            legend.title = element_text(face = "bold"))
  }

