  # =====================================================================
  # COMPREHENSIVE VISUALIZATIONS — Cross-Validation Venn + Evidence Scatter
  # =====================================================================

  # Normalize the source column — real data uses either `source` or `database_source`,
  # with values like "ChEMBL", "DGIdb", "OpenTargets", "ChEMBL_Mock", etc.
  get_source_column <- function(df) {
    if (is.null(df) || nrow(df) == 0) return(NULL)
    if ("source" %in% colnames(df)) return(df$source)
    if ("database_source" %in% colnames(df)) return(df$database_source)
    if ("sources" %in% colnames(df)) return(df$sources)
    NULL
  }

  classify_source <- function(src_vec) {
    dplyr::case_when(
      grepl("DGIdb|ChEMBL|DrugBank|PharmGKB|TTD", src_vec, ignore.case = TRUE) ~ "DGIdb",
      grepl("OpenTargets|Open[_ ]Targets", src_vec, ignore.case = TRUE) ~ "OpenTargets",
      TRUE ~ as.character(src_vec)
    )
  }

  build_xvalidation_venn <- function(drug_targets_data) {
    src_vec <- get_source_column(drug_targets_data)
    if (is.null(drug_targets_data) || nrow(drug_targets_data) == 0 || is.null(src_vec)) {
      return(ggplot() + annotate("text", x = 0.5, y = 0.5,
                                 label = "No source information available",
                                 size = 6, color = "#999") + theme_void())
    }
    work_df <- drug_targets_data
    work_df$src_class <- classify_source(src_vec)
    src_drugs <- work_df %>%
      dplyr::filter(!is.na(drug_name) & drug_name != "") %>%
      dplyr::distinct(drug_name, src = src_class)
    dgidb <- unique(src_drugs$drug_name[src_drugs$src == "DGIdb"])
    optgt <- unique(src_drugs$drug_name[src_drugs$src == "OpenTargets"])
    both  <- intersect(dgidb, optgt)
    only_d <- setdiff(dgidb, optgt)
    only_o <- setdiff(optgt, dgidb)

    # Simple 2-circle Venn using ggplot (no external pkg dependency)
    circle_df <- data.frame(
      x0 = c(-0.75, 0.75), y0 = c(0, 0), r = c(1.2, 1.2),
      label = c("DGIdb", "OpenTargets"),
      fill = c("#2196F3", "#4CAF50")
    )
    angles <- seq(0, 2*pi, length.out = 200)
    circle_pts <- do.call(rbind, lapply(seq_len(nrow(circle_df)), function(i) {
      data.frame(x = circle_df$x0[i] + circle_df$r[i]*cos(angles),
                 y = circle_df$y0[i] + circle_df$r[i]*sin(angles),
                 grp = circle_df$label[i])
    }))

    ggplot() +
      geom_polygon(data = circle_pts, aes(x = x, y = y, group = grp, fill = grp),
                   alpha = 0.45, color = NA) +
      geom_path(data = circle_pts, aes(x = x, y = y, group = grp, color = grp),
                linewidth = 1.2) +
      scale_fill_manual(values = c("DGIdb" = "#2196F3", "OpenTargets" = "#4CAF50"),
                        guide = "none") +
      scale_color_manual(values = c("DGIdb" = "#1565C0", "OpenTargets" = "#2E7D32"),
                         guide = "none") +
      # Count labels
      annotate("text", x = -1.3, y = 0, label = length(only_d), size = 10, fontface = "bold", color = "#0D47A1") +
      annotate("text", x =  1.3, y = 0, label = length(only_o), size = 10, fontface = "bold", color = "#1B5E20") +
      annotate("text", x =  0,   y = 0, label = length(both),   size = 11, fontface = "bold", color = "#4A148C") +
      # Header labels
      annotate("text", x = -1.3, y = 1.5, label = "DGIdb only",    size = 5, fontface = "bold", color = "#0D47A1") +
      annotate("text", x =  1.3, y = 1.5, label = "OpenTargets only", size = 5, fontface = "bold", color = "#1B5E20") +
      annotate("text", x =  0,   y = -1.55, label = "Cross-validated", size = 5.5, fontface = "bold", color = "#4A148C") +
      labs(title = "Cross-Database Validation",
           subtitle = paste0("Unique drugs — DGIdb: ", length(dgidb),
                             " | OpenTargets: ", length(optgt),
                             " | Shared: ", length(both))) +
      coord_fixed(xlim = c(-2.5, 2.5), ylim = c(-2, 2)) +
      theme_void(base_size = 14) +
      theme(plot.title = element_text(face = "bold", size = 16, hjust = 0.5),
            plot.subtitle = element_text(size = 11, color = "#666", hjust = 0.5),
            plot.margin = margin(15, 15, 15, 15))
  }

  output$drug_xvalidation_venn <- renderPlot({
    req(network_rv$current_results$drug_targets)
    build_xvalidation_venn(network_rv$current_results$drug_targets)
  })

