  build_evidence_scatter <- function(drug_prioritization, drug_targets, n_top = 30) {
    if (is.null(drug_prioritization) || nrow(drug_prioritization) == 0) {
      return(ggplot() + annotate("text", x = 0.5, y = 0.5,
                                 label = "No drug prioritization data available",
                                 size = 6, color = "#999") + theme_void())
    }
    score_col <- if ("comprehensive_score" %in% colnames(drug_prioritization)) "comprehensive_score" else "priority_score"

    # Count sources per drug — handles either `source` or `database_source`
    in_dgidb <- in_opt <- character(0)
    src_vec <- get_source_column(drug_targets)
    if (!is.null(drug_targets) && !is.null(src_vec) && nrow(drug_targets) > 0) {
      classified <- classify_source(src_vec)
      in_dgidb <- unique(drug_targets$drug_name[classified == "DGIdb" & !is.na(drug_targets$drug_name)])
      in_opt   <- unique(drug_targets$drug_name[classified == "OpenTargets" & !is.na(drug_targets$drug_name)])
    }

    top_drugs <- drug_prioritization %>%
      dplyr::arrange(dplyr::desc(.data[[score_col]])) %>%
      head(n_top) %>%
      dplyr::mutate(
        in_dgidb = drug_name %in% in_dgidb,
        in_opt   = drug_name %in% in_opt,
        Source = dplyr::case_when(
          in_dgidb & in_opt ~ "Cross-validated",
          in_dgidb ~ "DGIdb only",
          in_opt   ~ "OpenTargets only",
          TRUE ~ "Other"
        ),
        Source = factor(Source, levels = c("Cross-validated", "DGIdb only", "OpenTargets only", "Other")),
        Phase = dplyr::case_when(
          max_clinical_phase >= 4 ~ "Approved",
          max_clinical_phase >= 3 ~ "Phase III",
          max_clinical_phase >= 2 ~ "Phase II",
          max_clinical_phase >= 1 ~ "Phase I",
          TRUE ~ "Preclinical"
        )
      )

    ggplot(top_drugs, aes(x = n_targets, y = .data[[score_col]],
                          color = Source, size = max_clinical_phase + 1,
                          text = paste0("<b>", drug_name, "</b><br>",
                                        "Targets: ", n_targets, "<br>",
                                        "Score: ", round(.data[[score_col]], 2), "<br>",
                                        "Phase: ", Phase, "<br>",
                                        "Source: ", Source))) +
      geom_point(alpha = 0.85) +
      ggrepel::geom_text_repel(aes(label = drug_name),
                               size = 3.5, max.overlaps = 20,
                               segment.color = "#999", segment.size = 0.3,
                               min.segment.length = 0, show.legend = FALSE) +
      scale_color_manual(values = c("Cross-validated" = "#9C27B0",
                                    "DGIdb only" = "#2196F3",
                                    "OpenTargets only" = "#4CAF50",
                                    "Other" = "#9E9E9E")) +
      scale_size_continuous(range = c(3, 9), guide = "none") +
      labs(title = paste("Top", nrow(top_drugs), "Drugs: Evidence vs Target Coverage"),
           subtitle = "Size ∝ clinical phase · Color = database support",
           x = "Number of DEG Targets", y = "Priority Score",
           color = "Database Support") +
      theme_minimal(base_size = 14) +
      theme(plot.title = element_text(face = "bold", size = 16, margin = margin(b = 8)),
            plot.subtitle = element_text(size = 11, color = "#666", margin = margin(b = 12)),
            plot.margin = margin(t = 15, r = 20, b = 15, l = 15),
            panel.grid.minor = element_blank(),
            legend.position = "bottom",
            legend.title = element_text(face = "bold"))
  }

  output$drug_evidence_scatter <- plotly::renderPlotly({
    req(network_rv$current_results$drug_prioritization)
    p <- build_evidence_scatter(network_rv$current_results$drug_prioritization,
                                network_rv$current_results$drug_targets,
                                n_top = input$drug_evidence_ntop %||% 30)
    # Remove ggrepel layer (not supported by ggplotly) — drugs still identifiable on hover
    p$layers <- Filter(function(l) !inherits(l$geom, "GeomTextRepel"), p$layers)
    suppressWarnings(plotly::ggplotly(p, tooltip = "text")) %>%
      plotly::config(displayModeBar = TRUE, displaylogo = FALSE)
  })

