  build_clinical_phase_plot <- function(ot_data) {
    if (is.null(ot_data) || nrow(ot_data) == 0) {
      return(ggplot() + annotate("text", x = 0.5, y = 0.5,
                                 label = "No clinical phase data available",
                                 size = 6, color = "#999") + theme_void())
    }
    phase_data <- ot_data %>%
      dplyr::count(clinical_phase) %>%
      dplyr::mutate(Phase = dplyr::case_when(
        clinical_phase == -1 ~ "Withdrawn",
        clinical_phase == 0 ~ "Preclinical",
        clinical_phase == 1 ~ "Phase I",
        clinical_phase == 2 ~ "Phase II",
        clinical_phase == 3 ~ "Phase III",
        clinical_phase == 4 ~ "Approved",
        TRUE ~ "Unknown"
      ),
      Phase = factor(Phase, levels = c("Preclinical", "Phase I", "Phase II", "Phase III", "Approved", "Withdrawn"))) %>%
      dplyr::filter(!is.na(Phase))

    ggplot(phase_data, aes(x = Phase, y = n, fill = Phase)) +
      geom_col(alpha = 0.85, color = "#333", linewidth = 0.3, width = 0.75) +
      geom_text(aes(label = n), vjust = -0.4, size = 4.2, fontface = "bold") +
      scale_fill_manual(values = c("Preclinical" = "#ffc107", "Phase I" = "#17a2b8",
                                   "Phase II" = "#007bff", "Phase III" = "#6f42c1",
                                   "Approved" = "#28a745", "Withdrawn" = "#dc3545"),
                        guide = "none") +
      scale_y_continuous(expand = expansion(mult = c(0, 0.12))) +
      labs(title = "Clinical Development Pipeline",
           x = "Development Phase", y = "Number of Drugs") +
      theme_minimal(base_size = 14) +
      theme(plot.title = element_text(face = "bold", size = 16, hjust = 0.5),
            axis.text.x = element_text(angle = 30, hjust = 1, size = 11),
            axis.text.y = element_text(size = 11),
            panel.grid.minor = element_blank())
  }

