  build_td_heatmap <- function(ot_data, n_genes = 20, n_diseases = 15) {
    if (is.null(ot_data) || nrow(ot_data) == 0) {
      return(ggplot() + annotate("text", x = 0.5, y = 0.5,
                                 label = "No OpenTargets data available",
                                 size = 6, color = "#999") + theme_void())
    }
    # Need gene + disease/disease_area columns
    gene_col <- if ("gene_name" %in% colnames(ot_data)) "gene_name" else "gene"
    disease_col <- if ("disease_name" %in% colnames(ot_data)) "disease_name" else
                   if ("disease_area" %in% colnames(ot_data)) "disease_area" else NULL
    if (is.null(disease_col)) {
      return(ggplot() + annotate("text", x = 0.5, y = 0.5,
                                 label = "No disease association data available",
                                 size = 6, color = "#999") + theme_void())
    }
    cell_col <- if ("association_score" %in% colnames(ot_data)) "association_score" else NULL

    # Build gene x disease matrix of counts (or mean score)
    df <- ot_data %>%
      dplyr::filter(!is.na(.data[[gene_col]]) & !is.na(.data[[disease_col]]) &
                    .data[[gene_col]] != "" & .data[[disease_col]] != "")

    if (nrow(df) == 0) {
      return(ggplot() + annotate("text", x = 0.5, y = 0.5,
                                 label = "No valid gene-disease pairs",
                                 size = 6, color = "#999") + theme_void())
    }

    top_genes <- df %>% dplyr::count(.data[[gene_col]]) %>%
      dplyr::arrange(dplyr::desc(n)) %>% head(n_genes) %>% dplyr::pull(1)
    top_diseases <- df %>% dplyr::count(.data[[disease_col]]) %>%
      dplyr::arrange(dplyr::desc(n)) %>% head(n_diseases) %>% dplyr::pull(1)

    mat_df <- df %>%
      dplyr::filter(.data[[gene_col]] %in% top_genes & .data[[disease_col]] %in% top_diseases) %>%
      dplyr::group_by(Gene = .data[[gene_col]], Disease = .data[[disease_col]]) %>%
      dplyr::summarise(value = if (!is.null(cell_col)) mean(.data[[cell_col]], na.rm = TRUE) else dplyr::n(),
                       .groups = "drop") %>%
      dplyr::mutate(Gene = factor(Gene, levels = rev(top_genes)),
                    Disease = factor(Disease, levels = top_diseases))

    value_label <- if (!is.null(cell_col)) "Mean association score" else "Association count"

    ggplot(mat_df, aes(x = Disease, y = Gene, fill = value)) +
      geom_tile(color = "white", linewidth = 0.3) +
      geom_text(aes(label = if (!is.null(cell_col)) sprintf("%.2f", value) else as.character(value)),
                size = 3, color = "#222") +
      scale_fill_gradient(low = "#E8F5E9", high = "#1B5E20", name = value_label) +
      labs(title = "Target–Disease Association Heatmap",
           subtitle = paste("Top", length(top_genes), "genes ×", length(top_diseases), "diseases"),
           x = NULL, y = NULL) +
      theme_minimal(base_size = 13) +
      theme(plot.title = element_text(face = "bold", size = 16),
            plot.subtitle = element_text(size = 11, color = "#666"),
            axis.text.x = element_text(angle = 45, hjust = 1, size = 10),
            axis.text.y = element_text(face = "bold", size = 10),
            panel.grid = element_blank(),
            legend.position = "right")
  }

