  # Enhanced network visualization that works for all analysis types
  output$enhanced_network <- renderVisNetwork({
    req(network_rv$current_results)
    
    tryCatch({
      network_data <- network_rv$current_results$network_data
      
      # Ensure network_data has the required structure
      if (is.null(network_data) || is.null(network_data$nodes) || is.null(network_data$edges)) {
        print("No valid network data, creating empty network")
        return(visNetwork(
          nodes = data.frame(id = "No Data", label = "No Network Data Available", stringsAsFactors = FALSE),
          edges = data.frame(stringsAsFactors = FALSE)
        ))
      }
      
      # Ensure nodes and edges have required columns
      if (nrow(network_data$nodes) == 0) {
        return(visNetwork(
          nodes = data.frame(id = "Empty", label = "No Nodes", stringsAsFactors = FALSE),
          edges = data.frame(stringsAsFactors = FALSE)
        ))
      }
      
      print(paste("Creating network with", nrow(network_data$nodes), "nodes and", nrow(network_data$edges), "edges"))
      
      visNetwork(network_data$nodes, network_data$edges) %>%
        visOptions(highlightNearest = TRUE) %>%
        visLayout(randomSeed = 123)
      
    }, error = function(e) {
      print(paste("Error in enhanced_network:", e$message))
      
      # Return empty network on error
      visNetwork(
        nodes = data.frame(id = "Error", label = paste("Error:", e$message), stringsAsFactors = FALSE),
        edges = data.frame(stringsAsFactors = FALSE)
      )
    })
  })
  
