  output$drug_target_analysis_table <- DT::renderDataTable({
    req(network_rv$current_results, input$network_analysis_type_systems == "drug_target")
    
    if (!is.null(network_rv$current_results$drug_targets) &&
        nrow(network_rv$current_results$drug_targets) > 0) {
      
      # Create target analysis from drug-target data
      target_analysis <- network_rv$current_results$drug_targets %>%
        dplyr::group_by(gene_name) %>%
        dplyr::summarise(
          `Number of Drugs` = dplyr::n_distinct(molecule_name),
          `Total Interactions` = dplyr::n(),
          `Best Activity Value` = min(standard_value, na.rm = TRUE),
          `Activity Types` = paste(unique(standard_type), collapse = ", "),
          `Average Confidence` = mean(confidence_score, na.rm = TRUE),
          .groups = 'drop'
        ) %>%
        dplyr::mutate(
          Regulation = dplyr::case_when(
            gene_name %in% network_rv$selected_genes$up_genes ~ "Up-regulated",
            gene_name %in% network_rv$selected_genes$down_genes ~ "Down-regulated",
            TRUE ~ "Unchanged"
          )
        ) %>%
        dplyr::rename(Gene = gene_name) %>%
        dplyr::arrange(desc(`Number of Drugs`))
      
      DT::datatable(
        target_analysis,
        options = list(
          pageLength = 15,
          scrollX = TRUE,
          dom = 'Bfrtip',
          buttons = c('copy', 'csv', 'excel')
        ),
        filter = "top",
        rownames = FALSE
      ) %>%
        DT::formatRound(columns = c("Best Activity Value", "Average Confidence"), digits = 2) %>%
        DT::formatStyle(
          'Regulation',
          backgroundColor = DT::styleEqual(
            c("Up-regulated", "Down-regulated", "Unchanged"),
            c('#ffebee', '#e3f2fd', '#f5f5f5')
          )
        )
      
    } else {
      DT::datatable(data.frame(Message = "No drug interaction data available"))
    }
  })
  
  # Enhanced drug interactions table
  output$drug_interactions_table <- DT::renderDataTable({
    req(network_rv$current_results, input$network_analysis_type_systems == "drug_target")
    req(network_rv$current_results$raw_data)
    
    chembl_data <- network_rv$current_results$raw_data
    
    if (nrow(chembl_data) == 0) {
      return(DT::datatable(data.frame(Message = "No drug interaction data available")))
    }
    
    # Group data by gene
    chembl_by_gene <- split(chembl_data, chembl_data$gene_name)
    
    # Create main table data (one row per gene with best drug)
    main_interactions <- lapply(names(chembl_by_gene), function(gene) {
      gene_drugs <- chembl_by_gene[[gene]]
      
      # Get the best drug (lowest activity value = strongest interaction)
      best_drug <- gene_drugs[which.min(gene_drugs$standard_value), ]
      
      # Determine regulation status
      regulation <- case_when(
        gene %in% network_rv$selected_genes$up_genes ~ "Up-regulated",
        gene %in% network_rv$selected_genes$down_genes ~ "Down-regulated",
        TRUE ~ "Unchanged"
      )
      
      data.frame(
        Expand = "",  # Column for expand arrow
        Gene = gene,
        Regulation = regulation,
        "Best Drug" = ifelse(is.na(best_drug$compound_chembl_id), "Unknown", best_drug$compound_chembl_id),
        "Activity Type" = best_drug$standard_type,
        "Activity Value" = as.numeric(best_drug$standard_value),
        "Units" = best_drug$standard_units,
        "Total Drugs" = nrow(gene_drugs),
        "Reference" = sprintf('<a href="https://www.ebi.ac.uk/chembl/compound_report_card/%s" target="_blank">ChEMBL</a>',
                              best_drug$compound_chembl_id),
        stringsAsFactors = FALSE,
        check.names = FALSE
      )
    })
    
    main_interactions <- do.call(rbind, main_interactions)
    
    # Create child interactions data for expandable rows
    all_child_interactions <- list()
    for(gene in names(chembl_by_gene)) {
      gene_drugs <- chembl_by_gene[[gene]]
      
      if(nrow(gene_drugs) > 1) {  # Only create child data if there are multiple drugs
        # Sort by activity value (best first)
        gene_drugs <- gene_drugs[order(gene_drugs$standard_value), ]
        
        child_entries <- lapply(1:nrow(gene_drugs), function(i) {
          drug <- gene_drugs[i, ]
          list(
            "Drug ID" = drug$compound_chembl_id,
            "Activity Type" = drug$standard_type,
            "Activity Value" = round(as.numeric(drug$standard_value), 2),
            "Units" = drug$standard_units,
            "Reference" = sprintf('<a href="https://www.ebi.ac.uk/chembl/compound_report_card/%s" target="_blank">View in ChEMBL</a>',
                                  drug$compound_chembl_id)
          )
        })
        all_child_interactions[[gene]] <- child_entries
      }
    }
    
    # Create the datatable with expandable functionality
    DT::datatable(
      main_interactions,
      options = list(
        pageLength = 15,
        scrollX = TRUE,
        dom = 'Bfrtip',
        buttons = c('copy', 'csv', 'excel'),
        columnDefs = list(
          list(
            className = 'details-control',
            orderable = FALSE,
            targets = 0,  # First column (Expand)
            render = JS("function(data, type, row, meta) {
          return row[7] > 1 ? '<span style=\"cursor:pointer; color:#007bff;\">\\u25B6</span>' : '';
        }")
          )
        )
      ),
      
      # JavaScript callback for expand/collapse functionality
      callback = JS(sprintf(
        "var childData = %s;

      table.on('click', 'td.details-control', function() {
        var tr = $(this).closest('tr');
        var row = table.row(tr);
        var gene = row.data()[1];  // Gene name is in column 1

        if(row.child.isShown()) {
          // Hide child row
          row.child.hide();
          tr.removeClass('shown');
          $(this).find('span').html('►');
        } else {
          // Show child row
          if(childData[gene]) {
            row.child(formatChildTable(childData[gene], gene)).show();
            tr.addClass('shown');
            $(this).find('span').html('▼');
          }
        }
      });

      function formatChildTable(data, gene) {
        var html = '<div style=\"padding: 10px; background-color: #f8f9fa;\">' +
                   '<h6 style=\"color: #495057; margin-bottom: 10px;\">All Drug Interactions for <strong>' + gene + '</strong> (' + data.length + ' drugs)</h6>' +
                   '<table class=\"table table-sm table-striped\" style=\"margin-bottom: 0;\">' +
                   '<thead style=\"background-color: #e9ecef;\">' +
                     '<tr>' +
                       '<th>Drug ID</th>' +
                       '<th>Activity Type</th>' +
                       '<th>Activity Value</th>' +
                       '<th>Units</th>' +
                       '<th>Reference</th>' +
                     '</tr>' +
                   '</thead>' +
                   '<tbody>';

        data.forEach(function(row) {
          html += '<tr>' +
                    '<td><strong>' + (row['Drug ID'] || '') + '</strong></td>' +
                    '<td>' + (row['Activity Type'] || '') + '</td>' +
                    '<td>' + (row['Activity Value'] || '') + '</td>' +
                    '<td>' + (row['Units'] || '') + '</td>' +
                    '<td>' + (row['Reference'] || '') + '</td>' +
                  '</tr>';
        });

        html += '</tbody></table></div>';
        return html;
      }",
        jsonlite::toJSON(all_child_interactions, auto_unbox = TRUE)
      )),
      
      colnames = c(
        "",           # Expand column
        "Gene",
        "Regulation",
        "Best Drug",
        "Activity Type",
        "Activity Value",
        "Units",
        "Total Drugs",
        "Reference"
      ),
      escape = c(FALSE, TRUE, TRUE, TRUE, TRUE, TRUE, TRUE, TRUE, FALSE),  # Don't escape Expand and Reference columns
      rownames = FALSE,
      selection = 'none',
      filter = 'top'
    ) %>%
      
      # Format numeric columns
      DT::formatRound(columns = "Activity Value", digits = 2) %>%
      
      # Style regulation column
      DT::formatStyle(
        'Regulation',
        backgroundColor = DT::styleEqual(
          c("Up-regulated", "Down-regulated", "Unchanged"),
          c('#ffebee', '#e8f5e8', '#f5f5f5')
        ),
        color = DT::styleEqual(
          c("Up-regulated", "Down-regulated", "Unchanged"),
          c('#c62828', '#2e7d32', '#757575')
        )
      ) %>%
      
      # Style activity values with color gradient
      DT::formatStyle(
        'Activity Value',
        backgroundColor = DT::styleInterval(
          c(1, 10, 100, 1000),
          c('#c8e6c9', '#dcedc8', '#fff3e0', '#ffcdd2', '#ffcdd2')
        )
      ) %>%
      
      # Style total drugs column
      DT::formatStyle(
        'Total Drugs',
        backgroundColor = DT::styleInterval(
          c(5, 10, 20),
          c('#ffffff', '#e3f2fd', '#bbdefb', '#90caf9')
        ),
        fontWeight = 'bold'
      )
  })
  
