  # Enhanced PPI interactions table
  output$ppi_interactions_table <- DT::renderDataTable({
    req(network_rv$current_results, input$network_analysis_type_systems == "ppi")
    req(ppi_rv$network_data)
    
    # Create more informative table with evidence details
    DT::datatable(
      ppi_rv$network_data$edges %>%
        select(
          "Source" = from_symbol,
          "Target" = to_symbol,
          "Interaction Score" = score,
          "Experimental Evidence" = experimental_score,
          "Database Evidence" = database_score,
          "Text Mining Evidence" = textmining_score,
          "Coexpression Evidence" = coexpression_score,
          "Neighborhood Evidence" = neighborhood_score
        ) %>%
        mutate(
          "Confidence Level" = case_when(
            `Interaction Score` >= 0.9 ~ "Very High",
            `Interaction Score` >= 0.7 ~ "High",
            `Interaction Score` >= 0.4 ~ "Medium",
            TRUE ~ "Low"
          )
        ) %>%
        arrange(desc(`Interaction Score`)),
      options = list(
        pageLength = 15,
        scrollX = TRUE,
        dom = 'Bfrtip',
        buttons = c('copy', 'csv', 'excel')
      ),
      rownames = FALSE,
      filter = 'top'
    ) %>%
      formatRound(
        columns = c("Interaction Score", "Experimental Evidence",
                    "Database Evidence", "Text Mining Evidence",
                    "Coexpression Evidence", "Neighborhood Evidence"),
        digits = 1
      ) %>%
      formatStyle(
        'Confidence Level',
        backgroundColor = styleEqual(
          c("Very High", "High", "Medium", "Low"),
          c('#a1d99b', '#c7e9c0', '#fee0d2', '#fcae91')
        )
      )
  })
  
  # Download handler
  output$download_network <- downloadHandler(
    # 1. Change the filename to end in .png
    filename = function() {
      analysis_type <- input$network_analysis_type_systems %||% "network"
      paste0(analysis_type, "_network_", format(Sys.time(), "%Y%m%d_%H%M"), ".png")
    },
    content = function(file) {
      load_export_packages()
      req(network_rv$current_results)
      
      # Show a notification to the user
      progress_id <- showNotification(
        "Generating high-resolution PNG... This may take a moment.",
        duration = NULL, closeButton = FALSE, type = "message"
      )
      on.exit(removeNotification(progress_id), add = TRUE)
      
      tryCatch({
        print("Creating network for PNG download...")
        
        export_network <- NULL # Initialize a variable to hold the network object
        
        # --- Handle Drug-Target Network ---
        if (input$network_analysis_type_systems == "drug_target") {
          network_data <- network_rv$current_results$network_data
          
          if (is.null(network_data) || nrow(network_data$nodes) == 0) {
            stop("No Drug-Target network data available to export.")
          }
          
          # Fix: Ensure nodes have correct shapes for export
          export_nodes <- network_data$nodes
          export_edges <- network_data$edges
          
          # Make sure gene nodes are diamond-shaped and drugs are circular
          export_nodes$shape <- ifelse(export_nodes$type == "drug", "dot", "diamond")
          
          # 2. Create a dedicated, large, static network for export
          export_network <- visNetwork(
            nodes = export_nodes,  # Use the corrected nodes
            edges = export_edges,
            main = list(text = "Drug-Target Network", style = "font-family:Arial;font-size:36px;font-weight:bold;"),
            width = "2400px", height = "2400px" # Large canvas for high resolution
          ) %>%
            # Use the same physics as the interactive plot to get a good layout
            visPhysics(
              solver = "forceAtlas2Based",
              forceAtlas2Based = list(gravitationalConstant = -80, springLength = 180, avoidOverlap = 0.8),
              stabilization = list(enabled = TRUE, iterations = 500) # More iterations for a perfect layout
            ) %>%
            # Turn OFF all interactive elements for the final image
            visInteraction(
              dragNodes = FALSE, dragView = FALSE, zoomView = FALSE,
              navigationButtons = FALSE, tooltipDelay = 0
            ) %>%
            visOptions(highlightNearest = FALSE, nodesIdSelection = FALSE) %>%
            visLayout(randomSeed = 123) %>%
            # Add the same legend, but styled for a larger export image
            visLegend(
              enabled = TRUE, useGroups = FALSE, position = "right", width = 0.15,
              addNodes = list(
                list(label = "Drug/Compound", shape = "dot", color = "#3498db", size = 25, font = list(size = 20)),
                list(label = "Up-regulated Gene", shape = "diamond", color = "#e74c3c", size = 30, font = list(size = 20)),
                list(label = "Down-regulated Gene", shape = "diamond", color = "#2ecc71", size = 30, font = list(size = 20)),
                list(label = "Unchanged Gene", shape = "diamond", color = "#95a5a6", size = 30, font = list(size = 20))
              ),
              ncol = 1
            )
          
          # --- Handle PPI Network ---
        } else if (input$network_analysis_type_systems == "ppi") {
          req(ppi_rv$network_data)
          ppi_data <- ppi_rv$network_data
          
          if (is.null(ppi_data) || nrow(ppi_data$nodes) == 0) {
            stop("No PPI network data available to export.")
          }
          
          # 2. Create a dedicated, large, static network for PPI export
          export_network <- visNetwork(
            nodes = ppi_data$nodes,
            edges = ppi_data$edges,
            main = list(text = "Protein-Protein Interaction Network", style = "font-family:Arial;font-size:36px;font-weight:bold;"),
            width = "2400px", height = "2400px"
          ) %>%
            visPhysics(
              solver = "barnesHut",
              stabilization = list(enabled = TRUE, iterations = 500)
            ) %>%
            visInteraction(
              dragNodes = FALSE, dragView = FALSE, zoomView = FALSE,
              navigationButtons = FALSE, tooltipDelay = 0
            ) %>%
            visOptions(highlightNearest = FALSE, nodesIdSelection = FALSE) %>%
            visLayout(randomSeed = 42)
          
        } else {
          stop("Unknown network type selected for download.")
        }
        
        # 3. Save the prepared network to a temporary HTML file
        if (!is.null(export_network)) {
          temp_html_path <- tempfile(fileext = ".html")
          visSave(export_network, file = temp_html_path, selfcontained = TRUE, background = "white")
          
          # 4. Use webshot2 to take a high-resolution screenshot of the HTML
          webshot2::webshot(
            url = temp_html_path,
            file = file,
            delay = 5,      # IMPORTANT: Give enough time for physics to stabilize
            vwidth = 2400,  # Match the canvas width
            vheight = 2400, # Match the canvas height
            zoom = 2,        # KEY for high-res: renders at 2x pixel density
            # --- KEY ADDITION FOR SERVER/DOCKER ENVIRONMENTS ---
            extra_args = c(
              "--no-sandbox",
              "--disable-gpu",
              "--disable-dev-shm-usage"
            )
          )
          
          showNotification("PNG downloaded successfully!", type = "message", duration = 5)
          
        } else {
          stop("Failed to create a network object for export.")
        }
        
      }, error = function(e) {
        # Handle any errors during the process
        print(paste("Error creating download PNG:", e$message))
        showNotification(paste("Download Error:", e$message), type = "error", duration = 10)
        # Create an empty file to prevent a failed download error in the browser
        file.create(file)
      })
    }
  )
  
  # Button observers
  observeEvent(input$stabilize_network, {
    req(network_rv$current_results)
    
    if (input$network_analysis_type_systems == "drug_target") {
