  # Top 5 Modules Cards
  output$wgcna_top5_modules_cards <- renderUI({
    req(network_rv$current_results)
    results <- network_rv$current_results
    if (results$analysis_type != "wgcna" || is.null(results$modules)) {
      return(p("No module data available", style = "color: #999;"))
    }
    
    # Get module sizes and sort
    module_sizes <- sapply(results$modules, length)
    top5_modules <- names(sort(module_sizes, decreasing = TRUE))[1:min(5, length(module_sizes))]
    
    # Get enrichment data if available
    enrichment <- results$module_enrichment
    
    # Module colors
    module_colors <- c("#3498db", "#e74c3c", "#2ecc71", "#f39c12", "#9b59b6")
    
    cards <- lapply(seq_along(top5_modules), function(i) {
      mod_name <- top5_modules[i]
      mod_size <- module_sizes[mod_name]
      
      # Get hub count for this module
      n_hubs <- sum(results$hub_genes$module == mod_name, na.rm = TRUE)
      
      # Get top enriched term if available
      top_function <- if (!is.null(enrichment) && mod_name %in% names(enrichment)) {
        enr <- enrichment[[mod_name]]
        if (!is.null(enr) && nrow(enr) > 0 && "Term" %in% colnames(enr)) {
          # Get significant terms
          sig_terms <- enr[enr$Adjusted.P.value < 0.05, ]
          if (nrow(sig_terms) > 0) {
            # Prioritize biological pathway databases (KEGG, Reactome, WikiPathways, GO_BP)
            pathway_dbs <- c("KEGG", "Reactome", "WikiPathways", "GO_Biological_Process")
            
            # Check if Database column exists
            if ("Database" %in% colnames(sig_terms)) {
              # Filter for pathway databases first
              pathway_terms <- sig_terms[grepl(paste(pathway_dbs, collapse = "|"), sig_terms$Database, ignore.case = TRUE), ]
              
              if (nrow(pathway_terms) > 0) {
                # Use the most significant pathway term
                term <- as.character(pathway_terms$Term[1])
              } else {
                # Fallback to most significant term from any database
                term <- as.character(sig_terms$Term[1])
              }
            } else {
              # No Database column, use first significant term
              term <- as.character(sig_terms$Term[1])
            }
            
            # Clean up term
            term <- gsub("\\s*\\(GO:.*\\)", "", term)
            if (nchar(term) > 45) paste0(substr(term, 1, 42), "...") else term
          } else {
            "No significant enrichment"
          }
        } else {
          "Enrichment pending"
        }
      } else {
        "Enrichment not available"
      }
      
      div(style = paste0("display: flex; align-items: center; padding: 12px; margin-bottom: 10px; ",
                         "background: #f8f9fa; border-radius: 8px; border-left: 4px solid ", module_colors[i], ";"),
          # Color indicator
          div(style = paste0("width: 40px; height: 40px; background: ", module_colors[i], "; ",
                             "border-radius: 6px; display: flex; align-items: center; justify-content: center; ",
                             "margin-right: 15px;"),
              span(mod_name, style = "color: white; font-weight: bold; font-size: 0.7em;")
          ),
          # Module Info
          div(style = "flex: 1;",
              div(style = "display: flex; align-items: center; justify-content: space-between;",
                  strong(paste0("Module ", mod_name), style = "font-size: 1em;"),
                  span(paste0(mod_size, " genes"), style = "color: #666; font-size: 0.9em;")
              ),
              div(style = "font-size: 0.85em; color: #666; margin-top: 3px;",
                  span(paste0(n_hubs, " hub genes"), style = "margin-right: 15px;"),
                  span(icon("flask"), " ", top_function, style = "color: #3498db;")
              )
          )
      )
    })
    
    do.call(tagList, cards)
  })
  
