  # Biological Story
  output$wgcna_biological_story <- renderUI({
    req(network_rv$current_results)
    results <- network_rv$current_results
    if (results$analysis_type != "wgcna") return(NULL)
    
    story_parts <- list()
    
    # Part 1: Module overview
    n_modules <- length(results$modules)
    module_sizes <- sapply(results$modules, length)
    largest_mod <- names(which.max(module_sizes))
    
    story_parts[[1]] <- p(
      icon("layer-group", style = "color: #3498db;"), " ",
      "Your expression data clustered into ", strong(n_modules), " co-expression modules. ",
      "The largest module (", strong(largest_mod), ") contains ",
      strong(max(module_sizes)), " co-expressed genes."
    )
    
    # Part 2: Hub gene insight
    if (!is.null(results$hub_genes) && nrow(results$hub_genes) > 0) {
      top_hub <- results$hub_genes$gene[1]
      top_hub_module <- results$hub_genes$module[1]
      deg_hubs <- sum(results$hub_genes$is_deg, na.rm = TRUE)
      
      story_parts[[2]] <- p(
        icon("star", style = "color: #f39c12;"), " ",
        strong(top_hub), " is the top hub gene in module ", strong(top_hub_module), ". ",
        strong(deg_hubs), " hub genes are also differentially expressed, ",
        "suggesting they may be key drivers of your experimental phenotype."
      )
    }
    
    # Part 3: Enrichment insight (if available)
    if (!is.null(results$module_enrichment)) {
      # Count modules with significant enrichment
      sig_modules <- if (length(results$module_enrichment) > 0) {
        sum(vapply(results$module_enrichment, function(x) {
          if (!is.null(x) && is.data.frame(x) && nrow(x) > 0 && "Adjusted.P.value" %in% colnames(x)) {
            any(x$Adjusted.P.value < 0.05, na.rm = TRUE)
          } else {
            FALSE
          }
        }, FUN.VALUE = logical(1)))
      } else {
        0L
      }
      
      if (sig_modules > 0) {
        story_parts[[3]] <- p(
          icon("flask", style = "color: #9b59b6;"), " ",
          strong(sig_modules), " modules have significant functional enrichment, ",
          "indicating distinct biological processes represented by each module."
        )
      }
    }
    
    # Part 4: Quality assessment
    r2 <- results$analysis_params$scale_free_r2 %||% NA
    if (!is.na(r2)) {
      quality_text <- if (r2 >= 0.8) {
        "excellent, indicating a biologically meaningful network structure"
      } else if (r2 >= 0.7) {
        "good, suggesting reliable module detection"
      } else {
        "acceptable for exploratory analysis"
      }
      
      story_parts[[4]] <- div(
        style = "background: #e8f5e9; padding: 12px; border-radius: 6px; margin-top: 15px;",
        p(style = "margin: 0;",
          icon("check-circle", style = "color: #27ae60;"), " ",
          strong("Quality: "), "The scale-free topology fit (R² = ", round(r2, 2), ") is ",
          quality_text, "."
        )
      )
    }
    
    do.call(tagList, story_parts)
  })
  
  # Top Trait Associations
  output$wgcna_top_trait_associations <- renderUI({
    req(network_rv$current_results)
    results <- network_rv$current_results
    
    if (results$analysis_type != "wgcna") {
      return(p("No trait analysis available", style = "color: #999;"))
    }
    
    # Check multiple possible locations for trait correlation data
    trait_cors <- NULL
    
    # First check module_trait_analysis (new location)
    if (!is.null(results$module_trait_analysis) && 
        results$module_trait_analysis$has_results == TRUE) {
      if (!is.null(results$module_trait_analysis$correlations) && 
          !is.null(results$module_trait_analysis$p_values)) {
        trait_cors <- list(
          correlation = results$module_trait_analysis$correlations,
          p_value = results$module_trait_analysis$p_values
        )
      }
    }
    
    # Fallback to module_trait_correlations (old location)
    if (is.null(trait_cors) && !is.null(results$module_trait_correlations)) {
      if (!is.null(results$module_trait_correlations$correlation) && 
          !is.null(results$module_trait_correlations$p_value)) {
        trait_cors <- results$module_trait_correlations
      }
    }
    
    if (is.null(trait_cors)) {
      return(p("Module-trait analysis not performed. Upload trait data and run analysis.", style = "color: #999;"))
    }
    
    if (is.null(trait_cors$correlation) || is.null(trait_cors$p_value)) {
      return(p("Trait correlation data incomplete", style = "color: #999;"))
    }
    
    # Find top significant associations
    cor_mat <- trait_cors$correlation
    p_mat <- trait_cors$p_value
    
    # Flatten and get top correlations
    top_assoc <- list()
    for (i in 1:nrow(cor_mat)) {
      for (j in 1:ncol(cor_mat)) {
        if (!is.na(p_mat[i, j]) && p_mat[i, j] < 0.05) {
          top_assoc[[length(top_assoc) + 1]] <- list(
            module = rownames(cor_mat)[i],
            trait = colnames(cor_mat)[j],
            cor = cor_mat[i, j],
            p = p_mat[i, j]
          )
        }
      }
    }
    
    if (length(top_assoc) == 0) {
      return(p("No significant associations (p < 0.05)", style = "color: #999;"))
    }
    
    # Sort by absolute correlation
    top_assoc <- top_assoc[order(-abs(sapply(top_assoc, function(x) x$cor)))]
    top_assoc <- head(top_assoc, 5)
    
    assoc_items <- lapply(top_assoc, function(assoc) {
      cor_color <- if (assoc$cor > 0) "#e74c3c" else "#3498db"
      cor_sign <- if (assoc$cor > 0) "+" else ""
      
      div(style = "display: flex; align-items: center; padding: 8px; margin-bottom: 5px; 
                  background: #fff; border-radius: 4px;",
          span(gsub("^ME", "", assoc$module), style = "width: 60px; font-weight: bold;"),
          span(icon("arrows-alt-h"), style = "color: #999; margin: 0 10px;"),
          span(assoc$trait, style = "flex: 1;"),
          span(paste0("r = ", cor_sign, round(assoc$cor, 2)), 
               style = paste0("color: ", cor_color, "; font-weight: bold;"))
      )
    })
    
    do.call(tagList, assoc_items)
  })
  
