  output$wgcna_dendrogram_plot <- renderPlot({
    req(network_rv$current_results)
    results <- network_rv$current_results
    
    if (results$analysis_type != "wgcna") return(NULL)
    
    # Check if we have dendrogram data
    # It's stored as 'dendrogram' in results (which comes from network_results$gene_tree)
    if (is.null(results$dendrogram)) {
      plot.new()
      text(0.5, 0.5, "Dendrogram data not available.\nThe analysis may need to be re-run.", 
           cex = 1.5, col = "#999")
      return(NULL)
    }
    
    # Get settings from inputs (with defaults)
    show_labels <- if (!is.null(input$dendro_show_labels)) input$dendro_show_labels else FALSE
    hang <- if (!is.null(input$dendro_hang)) input$dendro_hang else 0.03
    
    # Get module colors
    module_colors <- results$module_colors_vector
    if (is.null(module_colors)) {
      module_colors <- results$module_colors
    }
    
    # Plot dendrogram
    tryCatch({
      if (requireNamespace("WGCNA", quietly = TRUE)) {
        WGCNA::plotDendroAndColors(
          results$dendrogram,
          module_colors,
          "Module colors",
          dendroLabels = show_labels,
          hang = hang,
          addGuide = TRUE,
          guideHang = 0.05,
          main = "Gene Clustering Dendrogram with Module Colors"
        )
      } else {
        # Fallback to base R if WGCNA not available
        plot(results$dendrogram, labels = show_labels, hang = hang,
             main = "Gene Clustering Dendrogram")
      }
    }, error = function(e) {
      plot.new()
      text(0.5, 0.5, paste("Error plotting dendrogram:\n", e$message), 
           cex = 1.2, col = "#e74c3c")
    })
  })
  
