  # 1. COMPREHENSIVE GENE ID TYPE DETECTION FUNCTION
  detect_gene_id_types <- function(gene_ids, organism = "human") {
    if (length(gene_ids) == 0) {
      return(list(
        patterns = list(),
        counts = list(),
        primary_type = "unknown",
        clean_ids = character(0)
      ))
    }
    
    print(paste("🔍 Detecting gene ID types for", length(gene_ids), "genes..."))
    
    # Clean up gene IDs first
    clean_ids <- gsub("\\s+", "", gene_ids)  # Remove whitespace
    clean_ids <- clean_ids[clean_ids != "" & !is.na(clean_ids)]  # Remove empty/NA
    
    if (length(clean_ids) == 0) {
      return(list(
        patterns = list(),
        counts = list(),
        primary_type = "unknown",
        clean_ids = character(0)
      ))
    }
    
    # Initialize detection patterns
    patterns <- list(
      # Human ENSEMBL patterns
      ensg_human = grepl("^ENSG[0-9]{11}(\\.[0-9]+)?$", clean_ids),
      enst_human = grepl("^ENST[0-9]{11}(\\.[0-9]+)?$", clean_ids),
      
      # Mouse ENSEMBL patterns
      ensg_mouse = grepl("^ENSMUSG[0-9]{11}(\\.[0-9]+)?$", clean_ids),
      enst_mouse = grepl("^ENSMUST[0-9]{11}(\\.[0-9]+)?$", clean_ids),
      
      # Other species ENSEMBL (generic)
      ensg_other = grepl("^ENS[A-Z]*G[0-9]{11}(\\.[0-9]+)?$", clean_ids),
      enst_other = grepl("^ENS[A-Z]*T[0-9]{11}(\\.[0-9]+)?$", clean_ids),
      
      # Entrez IDs (purely numeric)
      entrez = grepl("^[0-9]+$", clean_ids),
      
      # RefSeq patterns
      refseq_nm = grepl("^NM_[0-9]+$", clean_ids),
      refseq_nr = grepl("^NR_[0-9]+$", clean_ids),
      refseq_xm = grepl("^XM_[0-9]+$", clean_ids),
      
      # Gene symbols (heuristic detection)
      symbols = grepl("^[A-Z][A-Z0-9-]*[0-9]*$", clean_ids) &
        nchar(clean_ids) >= 2 & nchar(clean_ids) <= 20 &
        !grepl("^ENS", clean_ids) & !grepl("^[0-9]+$", clean_ids),
      
      # Mixed case symbols (like human genes)
      mixed_case = grepl("^[A-Za-z][A-Za-z0-9-]*$", clean_ids) &
        nchar(clean_ids) >= 2 & nchar(clean_ids) <= 20 &
        !grepl("^ENS", clean_ids) & !grepl("^[0-9]+$", clean_ids) &
        !grepl("^[A-Z]+$", clean_ids),
      
      # Complex IDs with suffixes/versions
      versioned = grepl("\\.", clean_ids),
      suffixed = grepl("_", clean_ids)
    )
    
    # Count each type
    type_counts <- lapply(patterns, sum)
    
    # Determine primary ID type
    primary_type <- "mixed"  # Default for mixed types
    max_count <- max(unlist(type_counts))
    
    if (max_count > length(clean_ids) * 0.5) {
      # Find the most common type if it's >50%
      max_type <- names(type_counts)[which.max(unlist(type_counts))]
      primary_type <- max_type
    }
    
    # Print detection summary
    print("📊 Gene ID type detection results:")
    for (type_name in names(type_counts)) {
      if (type_counts[[type_name]] > 0) {
        print(paste("  •", type_name, ":", type_counts[[type_name]]))
      }
    }
    print(paste("  • Primary Type:", primary_type))
    
    return(list(
      patterns = patterns,
      counts = type_counts,
      primary_type = primary_type,
      clean_ids = clean_ids
    ))
  }
  
  # 2. UNIVERSAL GENE ID CONVERSION FUNCTION
  convert_gene_ids_to_symbols <- function(gene_ids, organism = "human") {
    
    print(paste("🔄 Converting", length(gene_ids), "gene IDs to symbols..."))
    print(paste("🧬 Organism:", organism))
    print(paste("📝 Sample input IDs:", paste(head(gene_ids, 3), collapse = ", ")))
    
    # Initialize result vector
    converted_symbols <- gene_ids  # Start with original IDs as fallback
    
    # Determine organism database
    org_db_name <- switch(tolower(organism),
                          "human" = "org.Hs.eg.db",
                          "mouse" = "org.Mm.eg.db",
                          "rat" = "org.Rn.eg.db",
                          "org.Hs.eg.db"  # Default to human
    )
    
    print(paste("🗄️ Using annotation database:", org_db_name))
    
    # Check if required packages are available
    if (!requireNamespace(org_db_name, quietly = TRUE) ||
        !requireNamespace("AnnotationDbi", quietly = TRUE)) {
      
      print("⚠️ Required annotation packages not available. Attempting to install...")
      
      tryCatch({
        # Install BiocManager if not available
        if (!requireNamespace("BiocManager", quietly = TRUE)) {
          install.packages("BiocManager")
        }
        
        # Install required packages
        BiocManager::install(c("AnnotationDbi", org_db_name), update = FALSE, ask = FALSE)
        
        print("✅ Packages installed successfully")
      }, error = function(e) {
        print(paste("❌ Package installation failed:", e$message))
        print("💡 Returning original IDs without conversion")
        return(gene_ids)
      })
    }
    
    # Load required libraries
    tryCatch({
      library(AnnotationDbi, quietly = TRUE)
      library(org_db_name, character.only = TRUE, quietly = TRUE)
      
      print("✅ Annotation packages loaded")
      
      # Get the database object
      db_obj <- get(org_db_name)
      
      # Clean up gene IDs and classify them
      original_ids <- as.character(gene_ids)
      clean_ids <- gsub("\\.[0-9]+$", "", original_ids)  # Remove version numbers
      
      # Classify gene ID types
      ensg_pattern <- "^ENSG[0-9]+"
      enst_pattern <- "^ENST[0-9]+"
      entrez_pattern <- "^[0-9]+$"
      
      ensg_indices <- grep(ensg_pattern, clean_ids)
      enst_indices <- grep(enst_pattern, clean_ids)
      entrez_indices <- grep(entrez_pattern, clean_ids)
      symbol_indices <- setdiff(1:length(clean_ids), c(ensg_indices, enst_indices, entrez_indices))
      
      print(paste("🔍 Identified:",
                  length(ensg_indices), "ENSEMBL genes,",
                  length(enst_indices), "transcript IDs,",
                  length(entrez_indices), "Entrez IDs,",
                  length(symbol_indices), "assumed symbols"))
      
      # 1. Convert ENSEMBL gene IDs (ENSG)
      if (length(ensg_indices) > 0 && "ENSEMBL" %in% AnnotationDbi::keytypes(db_obj)) {
        ensg_ids <- clean_ids[ensg_indices]
        
        print("🧪 Converting ENSEMBL gene IDs...")
        ensg_symbols <- AnnotationDbi::mapIds(
          db_obj,
          keys = ensg_ids,
          column = "SYMBOL",
          keytype = "ENSEMBL",
          multiVals = "first"
        )
        
        # Update successful conversions
        valid_indices <- which(!is.na(ensg_symbols))
        if (length(valid_indices) > 0) {
          converted_symbols[ensg_indices[valid_indices]] <- ensg_symbols[valid_indices]
          print(paste("✅ Converted", length(valid_indices), "ENSEMBL IDs"))
        }
      }
      
      # 2. Convert Entrez IDs
      if (length(entrez_indices) > 0 && "ENTREZID" %in% AnnotationDbi::keytypes(db_obj)) {
        entrez_ids <- clean_ids[entrez_indices]
        
        print("🧪 Converting Entrez IDs...")
        entrez_symbols <- AnnotationDbi::mapIds(
          db_obj,
          keys = entrez_ids,
          column = "SYMBOL",
          keytype = "ENTREZID",
          multiVals = "first"
        )
        
        # Update successful conversions
        valid_indices <- which(!is.na(entrez_symbols))
        if (length(valid_indices) > 0) {
          converted_symbols[entrez_indices[valid_indices]] <- entrez_symbols[valid_indices]
          print(paste("✅ Converted", length(valid_indices), "Entrez IDs"))
        }
      }
      
      # 3. Handle transcript IDs (ENST) using biomaRt if available
      if (length(enst_indices) > 0 && requireNamespace("biomaRt", quietly = TRUE)) {
        enst_ids <- clean_ids[enst_indices]
        
        print("🧪 Converting transcript IDs using BioMart...")
        
        # Try multiple BioMart mirrors
        marts_to_try <- list(
          list(function() biomaRt::useMart("ensembl", dataset = "hsapiens_gene_ensembl"), "Standard"),
          list(function() biomaRt::useEnsembl("ensembl", dataset = "hsapiens_gene_ensembl", host = "useast.ensembl.org"), "US East"),
          list(function() biomaRt::useEnsembl("ensembl", dataset = "hsapiens_gene_ensembl", host = "uswest.ensembl.org"), "US West")
        )
        
        mart <- NULL
        for (mart_info in marts_to_try) {
          tryCatch({
            mart_func <- mart_info[[1]]
            mart_name <- mart_info[[2]]
            print(paste("🌐 Trying BioMart mirror:", mart_name))
            mart <- mart_func()
            break  # Success, exit loop
          }, error = function(e) {
            print(paste("❌ Failed to connect to", mart_name, "mirror"))
          })
        }
        
        if (!is.null(mart)) {
          tryCatch({
            enst_results <- biomaRt::getBM(
              attributes = c("ensembl_transcript_id", "external_gene_name"),
              filters = "ensembl_transcript_id",
              values = enst_ids,
              mart = mart
            )
            
            if (nrow(enst_results) > 0) {
              # Map transcript IDs to symbols
              enst_mapping <- setNames(enst_results$external_gene_name, enst_results$ensembl_transcript_id)
              
              for (i in seq_along(enst_ids)) {
                if (enst_ids[i] %in% names(enst_mapping) &&
                    !is.na(enst_mapping[enst_ids[i]]) &&
                    enst_mapping[enst_ids[i]] != "") {
                  converted_symbols[enst_indices[i]] <- enst_mapping[enst_ids[i]]
                }
              }
              
              converted_count <- sum(enst_ids %in% names(enst_mapping))
              print(paste("✅ Converted", converted_count, "transcript IDs"))
            }
          }, error = function(e) {
            print(paste("❌ BioMart conversion failed:", e$message))
          })
        } else {
          print("❌ Could not connect to any BioMart mirror")
        }
      }
      
      # 4. Verify symbols (for those assumed to be symbols already)
      if (length(symbol_indices) > 0 && "SYMBOL" %in% AnnotationDbi::keytypes(db_obj)) {
        symbol_ids <- clean_ids[symbol_indices]
        
        print("🧪 Verifying assumed gene symbols...")
        valid_symbols <- symbol_ids %in% AnnotationDbi::keys(db_obj, keytype = "SYMBOL")
        print(paste("✅ Verified", sum(valid_symbols), "out of", length(symbol_indices), "symbols"))
      }
      
      # Calculate and report conversion statistics
      conversion_success <- converted_symbols != original_ids
      conversion_rate <- round(mean(conversion_success) * 100, 1)
      
      print("🏁 CONVERSION SUMMARY:")
      print(paste("   Total input genes:", length(gene_ids)))
      print(paste("   Successfully converted:", sum(conversion_success)))
      print(paste("   Conversion rate:", conversion_rate, "%"))
      print(paste("   Sample converted symbols:", paste(head(converted_symbols, 5), collapse = ", ")))
      
      # Remove duplicates and empty values
      final_symbols <- unique(converted_symbols[!is.na(converted_symbols) & converted_symbols != ""])
      
      return(final_symbols)
      
    }, error = function(e) {
      print(paste("❌ Gene conversion failed:", e$message))
      print("💡 Returning original gene IDs")
      return(gene_ids)
    })
  }
  
  convert_gene_ids_to_symbols_enhanced <- function(gene_ids, organism = "human") {
    
    symbols <- convert_gene_ids_to_symbols(gene_ids, organism)
    
    # Calculate statistics
    original_count <- length(gene_ids)
    final_count <- length(symbols)
    conversion_rate <- round((final_count / original_count) * 100, 1)
    
    return(list(
      symbols = symbols,
      stats = list(
        total_input = original_count,
        successful_conversions = final_count,
        conversion_rate = conversion_rate,
        failed_conversions = original_count - final_count
      )
    ))
  }
  
  convert_module_genes_to_symbols <- function(module_genes, organism = "human") {
    print(paste("🔄 Converting", length(module_genes), "module genes to symbols for", organism))
    
    if (length(module_genes) == 0) {
      return(character(0))
    }
    
    # Use the main conversion function
    conversion_result <- convert_gene_ids_to_symbols(module_genes, organism, "SYMBOL")
    
    # Extract valid symbols
    valid_symbols <- conversion_result$symbols
    valid_symbols <- valid_symbols[!is.na(valid_symbols) & valid_symbols != "" & valid_symbols != "NA"]
    valid_symbols <- unique(valid_symbols)
    
    print(paste("  📝 Result:", length(valid_symbols), "valid symbols from", length(module_genes), "input genes"))
    
    return(valid_symbols)
  }
  
  # 3. HELPER FUNCTIONS FOR SPECIFIC CONVERSIONS
  
  convert_ensembl_to_symbols_robust <- function(ensembl_ids, organism, db_obj) {
    if (length(ensembl_ids) == 0) return(character(0))
    
    tryCatch({
      symbols <- AnnotationDbi::mapIds(
        db_obj,
        keys = ensembl_ids,
        column = "SYMBOL",
        keytype = "ENSEMBL",
        multiVals = "first"
      )
      
      symbols <- as.character(symbols)
      symbols[is.na(symbols) | symbols == "NA"] <- ensembl_ids[is.na(symbols) | symbols == "NA"]
      return(symbols)
      
    }, error = function(e) {
      print(paste("AnnotationDbi ENSEMBL conversion failed:", e$message))
      return(ensembl_ids)  # Return original if conversion fails
    })
  }
  
  convert_transcripts_to_genes_robust <- function(transcript_ids, organism, db_obj) {
    # For transcript IDs, we need to first convert to gene IDs, then to symbols
    clean_transcripts <- gsub("\\..*$", "", transcript_ids)
    
    symbols <- rep(NA_character_, length(transcript_ids))
    ensembl_ids <- rep(NA_character_, length(transcript_ids))
    
    # This is complex - for now, try biomaRt if available
    if (requireNamespace("biomaRt", quietly = TRUE) && organism == "human") {
      tryCatch({
        ensembl <- biomaRt::useMart("ensembl", dataset = "hsapiens_gene_ensembl")
        
        mapping <- biomaRt::getBM(
          attributes = c("ensembl_transcript_id", "ensembl_gene_id", "external_gene_name"),
          filters = "ensembl_transcript_id",
          values = clean_transcripts,
          mart = ensembl
        )
        
        for (i in seq_along(transcript_ids)) {
          matches <- mapping[mapping$ensembl_transcript_id == clean_transcripts[i], ]
          if (nrow(matches) > 0) {
            ensembl_ids[i] <- matches$ensembl_gene_id[1]
            symbols[i] <- matches$external_gene_name[1]
          }
        }
        
      }, error = function(e) {
        print(paste("BioMart transcript conversion failed:", e$message))
      })
    }
    
    # Fill in NAs with original IDs
    symbols[is.na(symbols)] <- transcript_ids[is.na(symbols)]
    ensembl_ids[is.na(ensembl_ids)] <- transcript_ids[is.na(ensembl_ids)]
    
    return(list(symbols = symbols, ensembl_ids = ensembl_ids))
  }
  
  convert_entrez_to_symbols_and_ensembl_robust <- function(entrez_ids, organism, db_obj) {
    symbols <- rep(NA_character_, length(entrez_ids))
    ensembl_ids <- rep(NA_character_, length(entrez_ids))
    
    tryCatch({
      # Convert to symbols
      symbol_mapping <- AnnotationDbi::mapIds(
        db_obj,
        keys = entrez_ids,
        column = "SYMBOL",
        keytype = "ENTREZID",
        multiVals = "first"
      )
      symbols <- as.character(symbol_mapping)
      
      # Convert to ENSEMBL
      ensembl_mapping <- AnnotationDbi::mapIds(
        db_obj,
        keys = entrez_ids,
        column = "ENSEMBL",
        keytype = "ENTREZID",
        multiVals = "first"
      )
      ensembl_ids <- as.character(ensembl_mapping)
      
    }, error = function(e) {
      print(paste("Entrez conversion failed:", e$message))
    })
    
    # Fill NAs
    symbols[is.na(symbols) | symbols == "NA"] <- entrez_ids[is.na(symbols) | symbols == "NA"]
    ensembl_ids[is.na(ensembl_ids) | ensembl_ids == "NA"] <- entrez_ids[is.na(ensembl_ids) | ensembl_ids == "NA"]
    
    return(list(symbols = symbols, ensembl_ids = ensembl_ids))
  }
  
  convert_symbols_to_ensembl_robust <- function(symbols, organism, db_obj) {
    tryCatch({
      ensembl_mapping <- AnnotationDbi::mapIds(
        db_obj,
        keys = symbols,
        column = "ENSEMBL",
        keytype = "SYMBOL",
        multiVals = "first"
      )
      
      ensembl_ids <- as.character(ensembl_mapping)
      ensembl_ids[is.na(ensembl_ids) | ensembl_ids == "NA"] <- symbols[is.na(ensembl_ids) | ensembl_ids == "NA"]
      
      return(ensembl_ids)
      
    }, error = function(e) {
      print(paste("Symbol to ENSEMBL conversion failed:", e$message))
      return(symbols)  # Return original if conversion fails
    })
  }
  
  convert_refseq_to_symbols_robust <- function(refseq_ids, organism, db_obj) {
    # RefSeq conversion is complex and not always available in all org.db packages
    # For now, return original IDs - can be enhanced later
    symbols <- refseq_ids
    ensembl_ids <- refseq_ids
    
    # Try if REFSEQ keytype is available
    tryCatch({
      available_keys <- AnnotationDbi::keytypes(db_obj)
      if ("REFSEQ" %in% available_keys) {
        symbol_mapping <- AnnotationDbi::mapIds(
          db_obj,
          keys = refseq_ids,
          column = "SYMBOL",
          keytype = "REFSEQ",
          multiVals = "first"
        )
        symbols <- as.character(symbol_mapping)
        symbols[is.na(symbols)] <- refseq_ids[is.na(symbols)]
      }
    }, error = function(e) {
      print(paste("RefSeq conversion not available:", e$message))
    })
    
    return(list(symbols = symbols, ensembl_ids = ensembl_ids))
  }
  
  clean_gene_symbols <- function(symbols) {
    # Clean up gene symbols
    clean_symbols <- trimws(symbols)
    clean_symbols <- gsub("[^A-Za-z0-9-]", "", clean_symbols)
    return(clean_symbols)
  }
  
  try_biomart_ensembl_to_symbol <- function(ensembl_ids) {
    # BioMart fallback for ENSEMBL to symbol conversion
    symbols <- ensembl_ids  # Default fallback
    
    tryCatch({
      ensembl <- biomaRt::useMart("ensembl", dataset = "hsapiens_gene_ensembl")
      
      mapping <- biomaRt::getBM(
        attributes = c("ensembl_gene_id", "external_gene_name"),
        filters = "ensembl_gene_id",
        values = ensembl_ids,
        mart = ensembl
      )
      
      for (i in seq_along(ensembl_ids)) {
        matches <- mapping[mapping$ensembl_gene_id == ensembl_ids[i], ]
        if (nrow(matches) > 0 && !is.na(matches$external_gene_name[1])) {
          symbols[i] <- matches$external_gene_name[1]
        }
      }
      
    }, error = function(e) {
      print(paste("BioMart fallback failed:", e$message))
    })
    
    return(symbols)
  }
  
  
  select_genes_for_wgcna <- function(deg_data, n_up = 10, n_down = 10) {
    print("🧬 Selecting genes for WGCNA using ENSEMBL IDs...")
    
    # Get the original ENSEMBL IDs from rownames
    ensembl_ids <- rownames(deg_data)
    
    # Clean the ENSEMBL IDs (remove suffixes like "_red vs green")
    clean_ensembl <- sub("_.*$", "", ensembl_ids)
    clean_ensembl <- sub("\\..*$", "", clean_ensembl)  # Remove version numbers
    
    print(paste("Total genes available:", length(clean_ensembl)))
    print(paste("Sample clean ENSEMBL IDs:", paste(head(clean_ensembl, 5), collapse = ", ")))
    
    # Sort by significance and fold change
    deg_df <- data.frame(
      ensembl_id = clean_ensembl,
      original_rowname = ensembl_ids,
      logFC = deg_data$log2FC,
      pvalue = deg_data$adj.P.Val,
      stringsAsFactors = FALSE
    )
    
    # Remove any rows with missing values
    deg_df <- deg_df[!is.na(deg_df$logFC) & !is.na(deg_df$pvalue), ]
    
    # Sort by significance
    deg_df <- deg_df[order(deg_df$pvalue), ]
    
    # Select top up and down regulated genes
    up_genes_df <- deg_df[deg_df$logFC > 0, ][1:min(n_up, sum(deg_df$logFC > 0, na.rm = TRUE)), ]
    down_genes_df <- deg_df[deg_df$logFC < 0, ][1:min(n_down, sum(deg_df$logFC < 0, na.rm = TRUE)), ]
    
    # Remove any NA rows
    up_genes_df <- up_genes_df[!is.na(up_genes_df$ensembl_id), ]
    down_genes_df <- down_genes_df[!is.na(down_genes_df$ensembl_id), ]
    
    # Get the clean ENSEMBL IDs
    up_genes <- up_genes_df$ensembl_id
    down_genes <- down_genes_df$ensembl_id
    all_genes <- c(up_genes, down_genes)
    
    print(paste("Selected", length(up_genes), "up-regulated genes"))
    print(paste("Selected", length(down_genes), "down-regulated genes"))
    print(paste("Total selected:", length(all_genes)))
    print(paste("Sample selected genes:", paste(head(all_genes, 5), collapse = ", ")))
    
    return(list(
      up_genes = up_genes,
      down_genes = down_genes,
      all_genes = all_genes,
      up_indices = match(up_genes_df$original_rowname, ensembl_ids),
      down_indices = match(down_genes_df$original_rowname, ensembl_ids)
    ))
  }
  
  prepare_wgcna_gene_selection <- function(expression_data, selected_genes) {
    print("🔍 Preparing gene selection for WGCNA...")
    
    # Get the actual gene names from expression data
    expr_genes <- rownames(expression_data)
    print(paste("Expression data has", length(expr_genes), "genes"))
    
    # Check if selected genes match expression data genes
    matching_genes <- intersect(selected_genes$all_genes, expr_genes)
    print(paste("Selected genes that match expression data:", length(matching_genes)))
    
    if (length(matching_genes) == 0) {
      print("⚠️ No selected genes match expression data rownames!")
      print("Sample expression genes:", paste(head(expr_genes, 5), collapse = ", "))
      print("Sample selected genes:", paste(head(selected_genes$all_genes, 5), collapse = ", "))
      
      # Use the selected gene indices instead if available
      if (!is.null(selected_genes$up_indices) && !is.null(selected_genes$down_indices)) {
        up_genes <- expr_genes[selected_genes$up_indices]
        down_genes <- expr_genes[selected_genes$down_indices]
        all_genes <- c(up_genes, down_genes)
        
        return(list(
          up_genes = up_genes,
          down_genes = down_genes,
          all_genes = all_genes
        ))
      }
    }
    
    return(selected_genes)
  }
  
  
  
