  # Make the Enhanced-Module-Analysis tab outputs eager so they
  # populate as soon as WGCNA finishes, even if the user is on
  # another tab. Without this, Shiny suspends hidden outputs and
  # the user sees a blank tab when they switch in late.
  outputOptions(output, "enhanced_module_summary_table", suspendWhenHidden = FALSE)
  outputOptions(output, "module_category_scores_plot",   suspendWhenHidden = FALSE)
  outputOptions(output, "category_distribution_plot",    suspendWhenHidden = FALSE)
  outputOptions(output, "module_evidence_summary",       suspendWhenHidden = FALSE)
  outputOptions(output, "module_detailed_info",          suspendWhenHidden = FALSE)

  # ============================================================
  # Advanced-analysis WGCNA: extra plot outputs + downloads
  # added for manuscript supplement panels (S7A, S7E, S7F)
  # ============================================================

  # S7A — Soft-threshold (scale-free topology) diagnostic plot
  output$wgcna_advanced_soft_power_plot <- renderPlot({
    req(network_rv$current_results)
    results <- network_rv$current_results

    if (!is.null(results$soft_power_diagnostics) &&
        !is.null(results$soft_power_diagnostics$fitIndices)) {

      fitIndices     <- results$soft_power_diagnostics$fitIndices
      selected_power <- results$soft_power_diagnostics$power %||% results$softPower

      par(mfrow = c(1, 2), mar = c(5, 5, 3, 2))

      plot(fitIndices$Power,
           -sign(fitIndices$slope) * fitIndices$SFT.R.sq,
           xlab = "Soft Threshold (power)",
           ylab = "Scale Free Topology Model Fit, signed R²",
           type = "n", main = "Scale independence")
      text(fitIndices$Power,
           -sign(fitIndices$slope) * fitIndices$SFT.R.sq,
           labels = fitIndices$Power, cex = 0.9,
           col = ifelse(fitIndices$Power == selected_power, "red", "black"))
      abline(h = 0.8, col = "red", lty = 2)

      plot(fitIndices$Power, fitIndices$mean.k.,
           xlab = "Soft Threshold (power)", ylab = "Mean Connectivity",
           type = "n", main = "Mean connectivity")
      text(fitIndices$Power, fitIndices$mean.k.,
           labels = fitIndices$Power, cex = 0.9,
           col = ifelse(fitIndices$Power == selected_power, "red", "black"))

      mtext(paste("Selected soft power:", selected_power),
            side = 3, line = -2, outer = TRUE, col = "red", font = 2)
    } else {
      par(mfrow = c(1, 1), mar = c(3, 3, 3, 2))
      plot(1, type = "n", xlim = c(0, 10), ylim = c(0, 10),
           xlab = "", ylab = "", axes = FALSE,
           main = "Soft Power Analysis")
      text(5, 6, paste("Soft Power Used:", results$softPower %||% "n/a"),
           cex = 1.6, font = 2, col = "#2c3e50")
      text(5, 4, "Per-power diagnostics not saved for this run",
           cex = 1.1, col = "darkgreen")
    }
  })

  output$download_wgcna_advanced_soft_power <- downloadHandler(
    filename = function() paste0("wgcna_soft_threshold_", Sys.Date(), ".png"),
    content = function(file) {
      load_export_packages()
      results <- network_rv$current_results

      png(file, width = 2400, height = 1100, res = 200)
      tryCatch({
        if (!is.null(results) &&
            !is.null(results$soft_power_diagnostics) &&
            !is.null(results$soft_power_diagnostics$fitIndices)) {

          fitIndices     <- results$soft_power_diagnostics$fitIndices
          selected_power <- results$soft_power_diagnostics$power %||% results$softPower

          par(mfrow = c(1, 2), mar = c(5, 5, 3, 2), oma = c(0, 0, 2, 0))

          plot(fitIndices$Power,
               -sign(fitIndices$slope) * fitIndices$SFT.R.sq,
               xlab = "Soft Threshold (power)",
               ylab = "Scale Free Topology Model Fit, signed R^2",
               type = "n", main = "Scale independence")
          text(fitIndices$Power,
               -sign(fitIndices$slope) * fitIndices$SFT.R.sq,
               labels = fitIndices$Power, cex = 0.9,
               col = ifelse(fitIndices$Power == selected_power, "red", "black"))
          abline(h = 0.8, col = "red", lty = 2)

          plot(fitIndices$Power, fitIndices$mean.k.,
               xlab = "Soft Threshold (power)", ylab = "Mean Connectivity",
               type = "n", main = "Mean connectivity")
          text(fitIndices$Power, fitIndices$mean.k.,
               labels = fitIndices$Power, cex = 0.9,
               col = ifelse(fitIndices$Power == selected_power, "red", "black"))

          mtext(paste("Selected soft power:", selected_power),
                side = 3, line = 0, outer = TRUE, col = "red", font = 2, cex = 1.1)
        } else {
          plot.new()
          text(0.5, 0.5, "Soft-threshold diagnostics not available\n(re-run WGCNA after the latest update)",
               cex = 1.2, col = "#444")
        }
      }, error = function(e) {
        plot.new()
        text(0.5, 0.5, paste("Error:", e$message), cex = 1.0, col = "red")
      })
      dev.off()
    }
  )

  # S7E — Module categorisation plot downloads
  output$download_module_category_scores_plot <- downloadHandler(
    filename = function() {
      mod <- input$selected_module_enhanced %||% "module"
      paste0("wgcna_category_scores_", mod, "_", Sys.Date(), ".png")
    },
    content = function(file) {
      load_export_packages()
      req(input$selected_module_enhanced)
      req(network_rv$current_results$module_summaries)
      module_data <- network_rv$current_results$module_summaries[[input$selected_module_enhanced]]
      p <- ggplot(head(module_data$all_category_scores, 5),
                  aes(x = reorder(category, confidence_score), y = confidence_score)) +
        geom_col(aes(fill = confidence_score), width = 0.7) +
        geom_text(aes(label = round(confidence_score, 1)),
                  hjust = -0.2, size = 4, fontface = "bold") +
        coord_flip() +
        scale_fill_gradient(low = "#ffccbc", high = "#66bb6a",
                            limits = c(0, 10), guide = "none") +
        labs(title = paste("Top 5 Category Matches for", input$selected_module_enhanced),
             x = NULL, y = "Confidence Score (0-10)") +
        theme_minimal(base_size = 12) +
        theme(plot.title  = element_text(face = "bold", size = 14),
              axis.text.y = element_text(size = 11),
              panel.grid.minor = element_blank()) +
        ylim(0, 10)
      ggsave(file, p, width = 8, height = 5, dpi = 300)
    }
  )

  output$download_category_distribution_plot <- downloadHandler(
    filename = function() paste0("wgcna_category_distribution_", Sys.Date(), ".png"),
    content = function(file) {
      load_export_packages()
      req(network_rv$current_results$enhanced_summary_table)
      category_counts <- network_rv$current_results$enhanced_summary_table %>%
        dplyr::group_by(Primary_Category) %>%
        dplyr::summarise(Count = dplyr::n(),
                         Avg_Confidence = mean(Confidence_Score, na.rm = TRUE),
                         .groups = 'drop') %>%
        dplyr::arrange(dplyr::desc(Count))
      p <- ggplot(category_counts,
                  aes(x = reorder(Primary_Category, Count), y = Count)) +
        geom_col(aes(fill = Avg_Confidence), width = 0.7) +
        geom_text(aes(label = Count), hjust = -0.3, size = 4, fontface = "bold") +
        coord_flip() +
        scale_fill_gradient(low = "#fff9c4", high = "#66bb6a",
                            limits = c(0, 10), name = "Avg Confidence") +
        labs(title = "Module Distribution Across Biological Categories",
             subtitle = "Color intensity represents average confidence score",
             x = NULL, y = "Number of Modules") +
        theme_minimal(base_size = 13) +
        theme(plot.title    = element_text(face = "bold", size = 16, margin = margin(b = 5)),
              plot.subtitle = element_text(size = 12, color = "#666", margin = margin(b = 15)),
              axis.text.y   = element_text(size = 11),
              legend.position    = "right",
              panel.grid.major.y = element_blank(),
              panel.grid.minor   = element_blank())
      ggsave(file, p, width = 10, height = 6, dpi = 300)
    }
  )

  # S7F — Advanced functional-enrichment dotplot
  build_advanced_enrichment_plot <- function(network_rv, input) {
    if (is.null(network_rv$current_results$module_enrichment) ||
        is.null(input$enrichment_module_filter)) return(NULL)

    selected_module <- input$enrichment_module_filter
    if (!selected_module %in% names(network_rv$current_results$module_enrichment)) {
      return(ggplot() + annotate("text", x = 1, y = 1,
                                 label = "No enrichment data for selected module") +
               theme_void())
    }
    module_enrich <- network_rv$current_results$module_enrichment[[selected_module]]
    if (is.null(module_enrich) || nrow(module_enrich) == 0) {
      return(ggplot() + annotate("text", x = 1, y = 1,
                                 label = "No significant enrichment found") +
               theme_void())
    }

    if (!is.null(input$enrichment_database_filter) &&
        input$enrichment_database_filter != "All" &&
        "Database" %in% colnames(module_enrich)) {
      module_enrich <- module_enrich[module_enrich$Database == input$enrichment_database_filter, ]
    }
    if (!is.null(input$enrichment_pval_cutoff) &&
        "Adjusted.P.value" %in% colnames(module_enrich)) {
      module_enrich <- module_enrich[module_enrich$Adjusted.P.value <= input$enrichment_pval_cutoff, ]
    }
    if (is.null(module_enrich) || nrow(module_enrich) == 0) {
      return(ggplot() + annotate("text", x = 1, y = 1,
                                 label = "No terms passing current filters") +
               theme_void())
    }

    module_enrich <- head(module_enrich[order(module_enrich$Adjusted.P.value), ], 20)

    if ("Overlap" %in% colnames(module_enrich)) {
      module_enrich$GeneCount <- sapply(module_enrich$Overlap, function(x) {
        if (is.na(x) || is.null(x) || x == "") return(5)
        count <- as.numeric(gsub("/.*", "", as.character(x)))
        if (is.na(count) || count == 0) return(5)
        return(count)
      })
    } else {
      module_enrich$GeneCount <- 5
    }
    if (!"Database" %in% colnames(module_enrich)) module_enrich$Database <- "enrichR"

    # Wrap long pathway labels so they don't get clipped off the left
    module_enrich$Term <- stringr::str_wrap(as.character(module_enrich$Term), width = 55)

    ggplot(module_enrich, aes(x = -log10(Adjusted.P.value),
                              y = reorder(Term, -log10(Adjusted.P.value)))) +
      geom_vline(xintercept = -log10(0.05), linetype = "dashed",
                 color = "red", alpha = 0.6) +
      geom_point(aes(size = GeneCount, color = Database)) +
      scale_size_continuous(name = "Gene Count", range = c(4, 14),
                            breaks = scales::pretty_breaks(n = 5)) +
      scale_color_brewer(palette = "Set2", name = "Database") +
      labs(title = paste("Functional Enrichment -", selected_module, "Module"),
           x = "-log10(Adjusted P-value)", y = NULL) +
      theme_bw(base_size = 13) +
      theme(plot.background  = element_rect(fill = "white", color = NA),
            panel.background = element_rect(fill = "white", color = NA),
            legend.background = element_rect(fill = "white", color = NA),
            panel.grid.major.y = element_line(color = "grey88"),
            panel.grid.minor   = element_blank(),
            panel.border       = element_rect(color = "grey80", fill = NA),
            axis.text.y  = element_text(size = 11, color = "grey20",
                                        margin = margin(r = 6)),
            axis.text.x  = element_text(size = 11, color = "grey20"),
            axis.title.x = element_text(size = 12, margin = margin(t = 8)),
            plot.title   = element_text(size = 15, face = "bold",
                                        margin = margin(b = 12)),
            legend.position = "right",
            legend.key      = element_rect(fill = "white", color = NA),
            plot.margin     = margin(15, 20, 15, 20))
  }

  output$wgcna_advanced_enrichment_plot <- renderPlot({
    req(network_rv$current_results)
    p <- build_advanced_enrichment_plot(network_rv, input)
    if (is.null(p)) {
      return(ggplot() + annotate("text", x = 1, y = 1,
                                 label = "Enrichment data not yet available") +
               theme_void())
    }
    p
  })

  output$download_wgcna_advanced_enrichment_plot <- downloadHandler(
    filename = function() {
      mod <- input$enrichment_module_filter %||% "module"
      paste0("wgcna_enrichment_", mod, "_", Sys.Date(), ".png")
    },
    content = function(file) {
      load_export_packages()
      p <- build_advanced_enrichment_plot(network_rv, input)
      if (is.null(p)) {
        p <- ggplot() + annotate("text", x = 1, y = 1, label = "No enrichment data") + theme_void()
      }
      ggsave(file, p, width = 12, height = 9, dpi = 300, bg = "white")
    }
  )

  # Module overview statistics
  output$module_overview_stats <- renderText({
    req(input$selected_module_detail, network_rv$current_results)
    
    if (!is.null(network_rv$current_results$module_summaries)) {
      module_summary <- network_rv$current_results$module_summaries[[input$selected_module_detail]]
      
      if (!is.null(module_summary)) {
        paste(
          paste("Module:", module_summary$module),
          paste("Size:", module_summary$size, "genes"),
          paste("Hub Genes:", module_summary$hub_count),
          paste("Categories:", paste(module_summary$pathway_categories, collapse = ", ")),
          sep = "\n"
        )
      }
    }
  })
  
  # Biological interpretation
  output$module_biological_interpretation <- renderUI({
    req(input$selected_module_detail, network_rv$current_results)
    
    if (!is.null(network_rv$current_results$module_summaries)) {
      module_summary <- network_rv$current_results$module_summaries[[input$selected_module_detail]]
      
      if (!is.null(module_summary)) {
        HTML(paste0(
          "<h6><strong>Primary Function:</strong></h6>",
          "<p>", module_summary$primary_function, "</p>",
          
          "<h6><strong>Key Pathway:</strong></h6>", 
          "<p>", module_summary$key_pathway, "</p>",
          
          "<h6><strong>Biological Interpretation:</strong></h6>",
          "<p style='font-style: italic; color: #495057;'>", 
          module_summary$interpretation, "</p>",
          
          "<h6><strong>Top Regulatory Genes:</strong></h6>",
          "<p><code>", paste(module_summary$top_hubs, collapse = ", "), "</code></p>"
        ))
      }
    }
  })
  
  # Pathway categories visualization
  output$module_pathway_categories <- renderPlot({
    req(input$selected_module_detail, network_rv$current_results)
    
    if (!is.null(network_rv$current_results$module_summaries)) {
      module_summary <- network_rv$current_results$module_summaries[[input$selected_module_detail]]
      
      if (!is.null(module_summary) && length(module_summary$pathway_categories) > 0) {
        
        # Create a simple bar plot of pathway categories
        categories_df <- data.frame(
          Category = module_summary$pathway_categories,
          Count = rep(1, length(module_summary$pathway_categories))
        )
        
        ggplot(categories_df, aes(x = reorder(Category, Count), y = Count)) +
          geom_col(fill = "#007bff", alpha = 0.7) +
          coord_flip() +
          theme_minimal() +
          labs(
            title = paste("Biological Categories for", input$selected_module_detail, "Module"),
            x = "Pathway Categories",
            y = "Presence"
          ) +
          theme(
            plot.title = element_text(size = 14, face = "bold"),
            axis.text = element_text(size = 12)
          )
      } else {
        # Empty plot if no categories
        ggplot() + 
          geom_text(aes(x = 1, y = 1, label = "No pathway categories available"), 
                    size = 6, color = "gray") +
          theme_void() +
          labs(title = "No Pathway Categories Available")
      }
    }
  })
  
  # Detailed hub genes for selected module
  output$module_hub_genes_detail <- DT::renderDataTable({
    req(input$selected_module_detail, network_rv$current_results)
    
    if (!is.null(network_rv$current_results$hub_genes)) {
      module_hubs <- network_rv$current_results$hub_genes[
        network_rv$current_results$hub_genes$module == input$selected_module_detail, 
      ]
      
      if (nrow(module_hubs) > 0) {
        # Select relevant columns - now "gene" contains symbols!
        display_hubs <- module_hubs %>%
          select(gene, connectivity, module_membership, hub_score, global_hub_rank, is_deg) %>%
          arrange(global_hub_rank) %>%
          mutate(
            connectivity = round(connectivity, 3),
            module_membership = round(module_membership, 3),
            hub_score = round(hub_score, 3)
          ) %>%
          rename(
            Gene_Symbol = gene  # Make it clear these are symbols now
          )
        
        # Add original ID if available
        if ("original_id" %in% colnames(module_hubs)) {
          display_hubs$Original_ID <- module_hubs$original_id[
            network_rv$current_results$hub_genes$module == input$selected_module_detail
          ]
        }
        
        DT::datatable(
          display_hubs,
          options = list(
            pageLength = 10, 
            scrollX = TRUE,
            columnDefs = list(
              list(width = '120px', targets = 0)  # Gene_Symbol column
            )
          ),
          rownames = FALSE,
          caption = paste("Hub Genes in", input$selected_module_detail, "Module (Gene Symbols)")
        ) %>%
          DT::formatStyle(
            "is_deg",
            backgroundColor = DT::styleEqual(TRUE, "lightcoral")
          ) %>%
          DT::formatStyle(
            "hub_score",
            background = DT::styleColorBar(range(display_hubs$hub_score), "lightblue")
          ) %>%
          DT::formatStyle(
            "Gene_Symbol",
            fontWeight = 'bold',
            fontFamily = 'monospace'
          )
      }
    }
  })
  
  # Summary statistics
  output$total_categorized_modules <- renderText({
    req(network_rv$current_results$module_summaries)
    length(network_rv$current_results$module_summaries)
  })
  
  output$high_confidence_modules <- renderText({
    req(network_rv$current_results$module_summaries)
    sum(sapply(network_rv$current_results$module_summaries, 
               function(x) x$confidence_score >= 7))
  })
  
  output$avg_confidence_score <- renderText({
    req(network_rv$current_results$module_summaries)
    avg_score <- mean(sapply(network_rv$current_results$module_summaries, 
                             function(x) x$confidence_score))
    round(avg_score, 1)
  })
  
  output$total_pathways_analyzed <- renderText({
    req(network_rv$current_results$module_summaries)
    sum(sapply(network_rv$current_results$module_summaries, 
               function(x) x$supporting_pathways))
  })
  
  # Module summary table
  output$wgcna_module_table <- DT::renderDataTable({
    req(network_rv$current_results)
    req(input$network_analysis_type_systems == "wgcna")
    
    if (!is.null(network_rv$current_results$modules)) {
      # Create module summary table
      module_data <- data.frame(
        Module = names(network_rv$current_results$modules),
        Size = sapply(network_rv$current_results$modules, length),
        Hub_Genes = sapply(names(network_rv$current_results$modules), function(mod) {
          sum(network_rv$current_results$hub_genes$module == mod)
        }),
        DEG_Hubs = sapply(names(network_rv$current_results$modules), function(mod) {
          sum(network_rv$current_results$hub_genes$module == mod & network_rv$current_results$hub_genes$is_deg)
        }),
        Top_Hub = sapply(names(network_rv$current_results$modules), function(mod) {
          module_hubs <- network_rv$current_results$hub_genes[network_rv$current_results$hub_genes$module == mod, ]
          if (nrow(module_hubs) > 0) {
            module_hubs$gene[1]
          } else {
            "None"
          }
        }),
        stringsAsFactors = FALSE
      )
      
      DT::datatable(
        module_data,
        options = list(pageLength = 15, scrollX = TRUE),
        rownames = FALSE
      ) %>%
        DT::formatStyle(
          "Size",
          background = DT::styleColorBar(range(module_data$Size), "lightblue"),
          backgroundSize = "100% 90%",
          backgroundRepeat = "no-repeat",
          backgroundPosition = "center"
        )
    }
  })
  
  # Download handler for WGCNA hub genes
  output$download_hub_genes <- downloadHandler(
    filename = function() {
      paste0("wgcna_hub_genes_", Sys.Date(), ".csv")
    },
    content = function(file) {
      req(network_rv$current_results)
      req(network_rv$current_results$hub_genes)
      
      write.csv(network_rv$current_results$hub_genes, file, row.names = FALSE)
    }
  )
  
  # Hub genes table with filtering
  output$wgcna_hub_table <- DT::renderDataTable({
    req(network_rv$current_results)
    req(input$network_analysis_type_systems == "wgcna")
    
    if (!is.null(network_rv$current_results$hub_genes)) {
      hub_data <- network_rv$current_results$hub_genes
      
      # Apply filters if they exist
      if (!is.null(input$hub_module_filter) && input$hub_module_filter != "All") {
        hub_data <- hub_data[hub_data$module == input$hub_module_filter, ]
      }
      
      if (!is.null(input$hub_deg_only) && input$hub_deg_only) {
        hub_data <- hub_data[hub_data$is_deg, ]
      }
      
      if (!is.null(input$hub_top_n)) {
        hub_data <- head(hub_data[order(hub_data$global_hub_rank), ], input$hub_top_n)
      }
      
      # Format the table
      display_data <- hub_data %>%
        select(gene, module, connectivity, module_membership, hub_score, global_hub_rank, is_deg) %>%
        mutate(
          connectivity = round(connectivity, 3),
          module_membership = round(module_membership, 3),
          hub_score = round(hub_score, 3)
        )
      
      DT::datatable(
        display_data,
        options = list(pageLength = 15, scrollX = TRUE),
        rownames = FALSE
      ) %>%
        DT::formatStyle(
          "is_deg",
          backgroundColor = DT::styleEqual(TRUE, "lightcoral")
        )
    }
  })
  
  # Dynamic choices for hub gene module filter
  observe({
    if (!is.null(network_rv$current_results) && isTRUE(input$network_analysis_type_systems == "wgcna")) {
      module_choices <- c("All", names(network_rv$current_results$modules))
      updateSelectInput(session, "hub_module_filter", choices = module_choices)
    }
  })

  # Dynamic choices for enrichment module filter and database filter
  observe({
    if (!is.null(network_rv$current_results) &&
        isTRUE(input$network_analysis_type_systems == "wgcna") &&
        !is.null(network_rv$current_results$module_enrichment)) {
      # Populate module dropdown from enrichment results
      enrich_modules <- names(network_rv$current_results$module_enrichment)
      updateSelectInput(session, "enrichment_module_filter",
                        choices = c("All", enrich_modules),
                        selected = "All")
      # Populate database dropdown from actual data
      all_dbs <- unique(unlist(lapply(network_rv$current_results$module_enrichment, function(x) {
        if (!is.null(x) && "Database" %in% colnames(x)) unique(x$Database) else NULL
      })))
      if (length(all_dbs) > 0) {
        updateSelectInput(session, "enrichment_database_filter",
                          choices = c("All", sort(all_dbs)),
                          selected = "All")
      }
    }
  })
  
  # WGCNA preview stats
  output$wgcna_preview_stats <- renderUI({
    req(network_rv$current_results)
    
    n_modules <- network_rv$current_results$analysis_params$n_modules
    n_hubs <- nrow(network_rv$current_results$hub_genes)
    r2 <- network_rv$current_results$analysis_params$scale_free_r2
    
    quality_icon <- if (r2 >= 0.8) "check-circle" else if (r2 >= 0.7) "exclamation-circle" else "times-circle"
    quality_color <- if (r2 >= 0.8) "#28a745" else if (r2 >= 0.7) "#ffc107" else "#dc3545"
    
    div(
      p(paste("✅ Identified", n_modules, "co-expression modules"),
        style = "margin: 0; color: #28a745; font-weight: 500; font-size: 14px;"),
      p(paste("⭐", n_hubs, "hub genes found"),
        style = "margin: 0; color: #17a2b8; font-weight: 500; font-size: 14px;"),
      p(icon(quality_icon), paste("Network quality R² =", round(r2, 3)),
