  output$wgcna_enrichment_table <- DT::renderDataTable({
    req(network_rv$current_results)
    req(input$network_analysis_type_systems == "wgcna")
    
    print("🔍 ENRICHMENT TABLE DEBUG:")
    print(paste("Current results available:", !is.null(network_rv$current_results)))
    print(paste("Module enrichment available:", !is.null(network_rv$current_results$module_enrichment)))
    
    if (!is.null(network_rv$current_results$module_enrichment)) {
      print(paste("Number of enriched modules:", length(network_rv$current_results$module_enrichment)))
      print(paste("Module names with enrichment:", paste(names(network_rv$current_results$module_enrichment), collapse = ", ")))
    }
    
    # Check if enrichment data exists
    if (is.null(network_rv$current_results$module_enrichment) ||
        length(network_rv$current_results$module_enrichment) == 0) {
      
      # Return empty message table
      empty_df <- data.frame(
        Message = "No enrichment results available",
        Details = "Either enrichment analysis failed or no significant pathways were found at p.adj < 0.05",
        stringsAsFactors = FALSE
      )
      
      return(DT::datatable(
        empty_df,
        options = list(dom = 't', ordering = FALSE),
        rownames = FALSE
      ))
    }
    
    # Combine all enrichment results into one table
    all_enrichment <- data.frame()
    
    for (module_name in names(network_rv$current_results$module_enrichment)) {
      module_enrichment <- network_rv$current_results$module_enrichment[[module_name]]
      
      if (!is.null(module_enrichment) && nrow(module_enrichment) > 0) {
        # Add module column and clean up the data
        module_enrichment$Module <- module_name
        
        # Check available columns BEFORE selecting
        available_cols <- colnames(module_enrichment)
        
        # Build display_data handling missing columns gracefully
        display_data <- data.frame(
          Module = module_enrichment$Module,
          stringsAsFactors = FALSE
        )
        
        # Term column (required)
        if ("Term" %in% available_cols) {
          display_data$`Pathway/Function` <- module_enrichment$Term
        } else {
          display_data$`Pathway/Function` <- "Unknown"
        }
        
        # Database column (may be missing)
        if ("Database" %in% available_cols) {
          display_data$Database <- module_enrichment$Database
        } else {
          display_data$Database <- "enrichR"  # Default
        }
        
        # Adjusted.P.value column
        if ("Adjusted.P.value" %in% available_cols) {
          display_data$`Adj. P-value` <- round(module_enrichment$Adjusted.P.value, 4)
        } else {
          display_data$`Adj. P-value` <- NA
        }
        
        # Combined.Score column
        if ("Combined.Score" %in% available_cols) {
          display_data$`Combined Score` <- round(module_enrichment$Combined.Score, 2)
        } else {
          display_data$`Combined Score` <- NA
        }
        
        # Genes column
        if ("Genes" %in% available_cols) {
          display_data$`Genes in Pathway` <- substr(module_enrichment$Genes, 1, 100)
        } else {
          display_data$`Genes in Pathway` <- ""
        }
        
        all_enrichment <- rbind(all_enrichment, display_data)
      }
    }
    
    if (nrow(all_enrichment) == 0) {
      # Return message if no data after processing
      empty_df <- data.frame(
        Message = "No enrichment data found",
        Details = "Module enrichment processing completed but no displayable results",
        stringsAsFactors = FALSE
      )

      return(DT::datatable(
        empty_df,
        options = list(dom = 't', ordering = FALSE),
        rownames = FALSE
      ))
    }

    # Apply user filters
    if (!is.null(input$enrichment_module_filter) && input$enrichment_module_filter != "All") {
      all_enrichment <- all_enrichment[all_enrichment$Module == input$enrichment_module_filter, , drop = FALSE]
    }
    if (!is.null(input$enrichment_database_filter) && input$enrichment_database_filter != "All") {
      all_enrichment <- all_enrichment[all_enrichment$Database == input$enrichment_database_filter, , drop = FALSE]
    }
    if (!is.null(input$enrichment_pval_cutoff) && "Adj. P-value" %in% colnames(all_enrichment)) {
      all_enrichment <- all_enrichment[!is.na(all_enrichment$`Adj. P-value`) &
                                         all_enrichment$`Adj. P-value` <= input$enrichment_pval_cutoff, , drop = FALSE]
    }

    if (nrow(all_enrichment) == 0) {
      empty_df <- data.frame(
        Message = "No results match current filters",
        Details = "Try selecting a different module, database, or increasing the p-value cutoff",
        stringsAsFactors = FALSE
      )
      return(DT::datatable(empty_df, options = list(dom = 't', ordering = FALSE), rownames = FALSE))
    }

    print(paste("📊 Displaying", nrow(all_enrichment), "enrichment results (after filtering)"))
    
    # Create the data table with proper formatting
    DT::datatable(
      all_enrichment,
      options = list(
        pageLength = 15,
        scrollX = TRUE,
        dom = 'Bfrtip',
        buttons = c('copy', 'csv', 'excel'),
        columnDefs = list(
          list(width = '200px', targets = 1),  # Pathway column
          list(width = '100px', targets = 0),  # Module column
          list(width = '300px', targets = 5)   # Genes column
        )
      ),
      extensions = 'Buttons',
      rownames = FALSE,
      filter = 'top'
    ) %>%
      DT::formatStyle(
        "Adj. P-value",
        backgroundColor = DT::styleInterval(c(0.01, 0.05), c('#ffcccc', '#ffffcc', '#ffffff'))
      ) %>%
      DT::formatStyle(
        "Module",
        backgroundColor = DT::styleEqual(
          unique(all_enrichment$Module),
          rainbow(length(unique(all_enrichment$Module)), alpha = 0.3)
        )
      )
  })
  
  debug_wgcna_enrichment <- function() {
    
    print("=== WGCNA ENRICHMENT DEBUG ===")
    
    # Check if we have current results
    if (is.null(network_rv$current_results)) {
      print("❌ No current results available")
      return()
    }
    
    # Check analysis type
    analysis_type <- network_rv$current_results$analysis_type %||% "unknown"
    print(paste("📊 Analysis type:", analysis_type))
    
    # Check if module_enrichment exists
    has_enrichment <- !is.null(network_rv$current_results$module_enrichment)
    print(paste("🧪 Has module_enrichment:", has_enrichment))
    
    if (has_enrichment) {
      enrichment_data <- network_rv$current_results$module_enrichment
      print(paste("📋 Number of enriched modules:", length(enrichment_data)))
      print(paste("📋 Module names:", paste(names(enrichment_data), collapse = ", ")))
      
      # Check structure of each module's enrichment
      for (module_name in names(enrichment_data)) {
        module_data <- enrichment_data[[module_name]]
        if (!is.null(module_data) && is.data.frame(module_data)) {
          print(paste("  Module", module_name, ":", nrow(module_data), "pathways"))
          print(paste("    Columns:", paste(colnames(module_data), collapse = ", ")))
          if (nrow(module_data) > 0) {
            print(paste("    Sample pathway:", module_data$Term[1]))
          }
        } else {
          print(paste("  Module", module_name, ": Invalid data structure"))
        }
      }
    }
    
    # Check the reactive flag
    enrichment_flag <- tryCatch({
      output$wgcna_enrichment_available()
    }, error = function(e) {
      paste("Error:", e$message)
    })
    print(paste("🚩 Enrichment available flag:", enrichment_flag))
    
    # Check current input states
    print(paste("🎛️ Current network analysis type:", input$network_analysis_type_systems %||% "NULL"))
    print(paste("🎛️ Network results available:", !is.null(network_rv$current_results)))
    
    print("=== END DEBUG ===")
  }
  
  observeEvent(input$debug_enrichment, {
    debug_wgcna_enrichment()
    
    # Also try to manually trigger the enrichment table
    if (!is.null(network_rv$current_results) &&
        input$network_analysis_type_systems == "wgcna") {
      
      print("🔄 Manually triggering enrichment table update...")
      
      # Force update the enrichment available flag
      session$sendCustomMessage("triggerReactive", "wgcna_enrichment_available")
    }
  })
  
  
  # Check if enrichment results are available
  output$wgcna_enrichment_available <- reactive({
    # Check basic requirements
    if (is.null(network_rv$current_results)) {
      print("📊 Enrichment check: No current results")
      return(FALSE)
    }
    
    if (is.null(input$network_analysis_type_systems) || 
        input$network_analysis_type_systems != "wgcna") {
      return(FALSE)
    }
    
    # Check for module enrichment data
    enrichment_data <- network_rv$current_results$module_enrichment
    
    if (is.null(enrichment_data)) {
      print("📊 Enrichment check: module_enrichment is NULL")
      return(FALSE)
    }
    
    if (length(enrichment_data) == 0) {
      print("📊 Enrichment check: module_enrichment is empty")
      return(FALSE)
    }
    
    # Check if any module has actual data
    has_data <- any(sapply(enrichment_data, function(x) {
      !is.null(x) && is.data.frame(x) && nrow(x) > 0
    }))
    
    print(paste("📊 Enrichment check: has_data =", has_data))
    print(paste("📊 Modules with enrichment:", paste(names(enrichment_data), collapse = ", ")))
    
    return(has_data)
  })
  outputOptions(output, "wgcna_enrichment_available", suspendWhenHidden = FALSE)
  
  
  #Module trait codes
  trait_rv <- reactiveValues(
    raw_data = NULL,
    sample_id_column = NULL,
    trait_columns = NULL,
    configured = FALSE
  )
  
  # File upload handler
  observeEvent(input$wgcna_trait_metadata, {
    req(input$wgcna_trait_metadata)
    
    tryCatch({
      inFile <- input$wgcna_trait_metadata
      
      # ✅ USE NEW ROBUST READER
      metadata <- read_metadata_file(inFile$datapath, inFile$name)
      
      if (ncol(metadata) < 2) {
        showNotification("File must have at least 2 columns", type = "error")
        return()
      }
      
      trait_rv$raw_data <- metadata
      trait_rv$configured <- FALSE
      
      # Populate selectors
      col_names <- colnames(metadata)
      updateSelectInput(session, "wgcna_sample_id_column",
                        choices = col_names, selected = col_names[1])
      updateCheckboxGroupInput(session, "wgcna_trait_columns",
                               choices = col_names[-1], selected = col_names[-1])
      
      showNotification("File loaded! Click 'Configure Traits' to proceed.",
                       type = "message", duration = 3)
      
    }, error = function(e) {
      showNotification(paste("Error loading file:", e$message), 
                       type = "error", duration = 7)
    })
  })
  
  # File uploaded flag
  output$trait_file_uploaded <- reactive({
    !is.null(trait_rv$raw_data)
  })
  outputOptions(output, "trait_file_uploaded", suspendWhenHidden = FALSE)
  
  # Trait configured flag
  output$trait_configured <- reactive({
    trait_rv$configured
  })
  outputOptions(output, "trait_configured", suspendWhenHidden = FALSE)
  
  # Select/deselect all in modal
  observeEvent(input$select_all_traits_modal, {
    req(trait_rv$raw_data)
    sample_col <- input$wgcna_sample_id_column %||% colnames(trait_rv$raw_data)[1]
    trait_cols <- setdiff(colnames(trait_rv$raw_data), sample_col)
    updateCheckboxGroupInput(session, "wgcna_trait_columns", selected = trait_cols)
  })
  
  observeEvent(input$deselect_all_traits_modal, {
    updateCheckboxGroupInput(session, "wgcna_trait_columns", selected = character(0))
  })
  
  # Preview in modal
  output$trait_metadata_modal_preview <- DT::renderDataTable({
    req(trait_rv$raw_data, input$wgcna_sample_id_column, input$wgcna_trait_columns)
    
    selected_cols <- c(input$wgcna_sample_id_column, input$wgcna_trait_columns)
    preview_data <- trait_rv$raw_data[, selected_cols, drop = FALSE]
    
    DT::datatable(
      head(preview_data, 10),
      options = list(pageLength = 5, scrollX = TRUE, dom = 't', ordering = FALSE),
      rownames = FALSE
    )
  })
  
  # Trait columns selected flag
  output$trait_columns_selected_modal <- reactive({
    !is.null(input$wgcna_trait_columns) && length(input$wgcna_trait_columns) > 0
  })
  outputOptions(output, "trait_columns_selected_modal", suspendWhenHidden = FALSE)
  
  # Trait type detection in modal
  output$trait_type_detection_modal <- renderUI({
    req(trait_rv$raw_data, input$wgcna_trait_columns)
    
    trait_data <- trait_rv$raw_data[, input$wgcna_trait_columns, drop = FALSE]
    
    html <- "<table style='width: 100%; font-size: 12px;'>"
    html <- paste0(html, "<tr style='background: #f5f5f5; font-weight: 600;'>",
                   "<th style='padding: 8px;'>Trait</th>",
                   "<th style='padding: 8px;'>Type</th>",
                   "<th style='padding: 8px;'>Details</th></tr>")
    
    for (col_name in colnames(trait_data)) {
      col_data <- trait_data[[col_name]]
      
      if (is.numeric(col_data)) {
        type_badge <- "<span style='background: #4caf50; color: white; padding: 2px 8px; 
                            border-radius: 12px;'>Continuous</span>"
        details <- sprintf("Range: %.1f - %.1f", min(col_data, na.rm=T), max(col_data, na.rm=T))
      } else {
        n_unique <- length(unique(col_data[!is.na(col_data)]))
        if (n_unique == 2) {
          type_badge <- "<span style='background: #2196f3; color: white; padding: 2px 8px; 
                              border-radius: 12px;'>Binary</span>"
          details <- "Will encode as 0/1"
        } else if (n_unique <= 10) {
          type_badge <- "<span style='background: #ff9800; color: white; padding: 2px 8px; 
                              border-radius: 12px;'>Categorical</span>"
          details <- sprintf("%d levels", n_unique)
        } else {
          type_badge <- "<span style='background: #9e9e9e; color: white; padding: 2px 8px; 
                              border-radius: 12px;'>Many Levels</span>"
          details <- "Will attempt conversion"
        }
      }
      
      html <- paste0(html, "<tr><td style='padding: 8px;'>", col_name, "</td>",
                     "<td style='padding: 8px;'>", type_badge, "</td>",
                     "<td style='padding: 8px; color: #666;'>", details, "</td></tr>")
    }
    
    HTML(paste0(html, "</table>"))
  })
  
  observeEvent(input$confirm_trait_config, {
    req(input$wgcna_sample_id_column, input$wgcna_trait_columns)
    
    if (length(input$wgcna_trait_columns) == 0) {
      showNotification("Please select at least 1 trait column", type = "warning")
      return()
    }
    
    # SAVE TO REACTIVE VALUES
    trait_rv$sample_id_column <- input$wgcna_sample_id_column
    trait_rv$trait_columns <- input$wgcna_trait_columns
    trait_rv$configured <- TRUE
    
    toggleModal(session, "trait_selector_modal", toggle = "close")
    showNotification("Trait configuration saved!", type = "message", duration = 3)
  })
  
  # Cancel button
  observeEvent(input$cancel_trait_config, {
    toggleModal(session, "trait_selector_modal", toggle = "close")
  })
  
  # Status display
  output$trait_config_status <- renderUI({
    req(trait_rv$configured)
    HTML(sprintf(" Configuration saved: <strong>%d traits</strong> selected (%s)",
                 length(trait_rv$trait_columns),
                 paste(trait_rv$trait_columns, collapse = ", ")))
  })
  
  
  
  # Check if trait analysis results are available
  output$has_trait_results <- reactive({
    req(network_rv$current_results)
    
    # Check module_trait_analysis first (new structure)
    has_mta <- !is.null(network_rv$current_results$module_trait_analysis) &&
      isTRUE(network_rv$current_results$module_trait_analysis$has_results)
    
    # Also check module_trait_correlations (alternative structure)
    has_mtc <- !is.null(network_rv$current_results$module_trait_correlations) &&
      !is.null(network_rv$current_results$module_trait_correlations$correlation) &&
      !is.null(network_rv$current_results$module_trait_correlations$p_value)
    
    return(has_mta || has_mtc)
  })
  outputOptions(output, "has_trait_results", suspendWhenHidden = FALSE)
  
