      "<p style='margin: 5px 0;'><strong>Traits:</strong> ", 
      paste(trait_info$trait_names, collapse = ", "), "</p>",
      "<p style='margin: 5px 0;'><strong>Trait Types:</strong> "
    )
    
    # Add trait type details
    for (i in seq_along(trait_info$trait_names)) {
      trait_name <- trait_info$trait_names[i]
      trait_type <- trait_info$trait_types[i]
      
      if (trait_name %in% names(encoding_info)) {
        encoding <- encoding_info[[trait_name]]$encoding
        info_html <- paste0(info_html, "<br>  • ", trait_name, " (", trait_type, ")")
