    if (is.data.frame(summary_table) && nrow(summary_table) > 0) {
      DT::datatable(
        summary_table,
        options = list(
          pageLength = 15,
          scrollX = TRUE,
          order = list(list(2, 'desc')),  # Sort by absolute correlation
          columnDefs = list(
            list(width = '80px', targets = c(0, 1)),  # Module, Trait
            list(width = '90px', targets = 2),  # Correlation
            list(width = '100px', targets = 3),  # P_Value
            list(width = '80px', targets = c(4, 5))  # Direction, Strength
          )
        ),
        rownames = FALSE
      ) %>%
        DT::formatStyle(
          'Strength',
          backgroundColor = DT::styleEqual(
            c("Strong", "Moderate", "Weak", "Very Weak"),
            c('#c8e6c9', '#fff9c4', '#ffccbc', '#f5f5f5')
          ),
          fontWeight = 'bold'
        ) %>%
        DT::formatStyle(
          'Direction',
          backgroundColor = DT::styleEqual(
            c("Positive", "Negative"),
            c('#e3f2fd', '#ffebee')
          )
        ) %>%
        DT::formatStyle(
          'Correlation',
          background = DT::styleColorBar(range(abs(summary_table$Correlation)), '#667eea'),
          backgroundSize = '80% 80%',
          backgroundRepeat = 'no-repeat',
          backgroundPosition = 'center'
        )
    } else {
      DT::datatable(
        data.frame(Message = "No significant associations found at p < 0.05"),
        options = list(dom = 't'),
        rownames = FALSE
      )
    }
  })
  
