  observeEvent(event_data("plotly_click", source = "deconv_barplot_main"), ignoreNULL = TRUE, ignoreInit = TRUE, {
    
    click_data <- event_data("plotly_click", source = "deconv_barplot_main")
    
    print("🔍 Click event detected!")
    print("Click data structure:")
    print(str(click_data))
    
    if (!is.null(click_data) && !is.null(rv_deg_main$exploratory_deconv_plot_data)) {
      
      # ✅ Extract group name properly from plotly click data
      # For stacked bar charts, plotly returns the x-axis category value
      clicked_group <- NULL
      
      # Try multiple extraction methods
      if (!is.null(click_data$customdata)) {
        clicked_group <- as.character(click_data$customdata)
        
      } else if (!is.null(click_data$pointNumber)) {
        # If x is not available, get unique groups and use point number
        unique_groups <- unique(rv_deg_main$exploratory_deconv_plot_data$group)
        point_num <- click_data$pointNumber[1] + 1  # R is 1-indexed
        if (point_num <= length(unique_groups)) {
          clicked_group <- unique_groups[point_num]
        }
      } else if (!is.null(click_data$curveNumber)) {
        # Last resort: use curve number
        unique_groups <- unique(rv_deg_main$exploratory_deconv_plot_data$group)
        curve_num <- click_data$curveNumber[1] + 1
        if (curve_num <= length(unique_groups)) {
          clicked_group <- unique_groups[curve_num]
        }
      }
      
      print(paste("🎯 Extracted group name:", clicked_group))
      print(paste("   Available groups:", paste(unique(rv_deg_main$exploratory_deconv_plot_data$group), collapse = ", ")))
      
      if (!is.null(clicked_group) && clicked_group != "") {
        showDeconvDrillDownModal(
          clicked_group = clicked_group,
          full_data = rv_deg_main$exploratory_deconv_plot_data
        )
      } else {
        showNotification(
          "Could not determine which group was clicked. Please try again.",
          type = "warning",
          duration = 3
        )
      }
    } else {
      print("❌ Click data or plot data is NULL")
      if (is.null(rv_deg_main$exploratory_deconv_plot_data)) {
        print("   - exploratory_deconv_plot_data is NULL")
      }
    }
  })
  
  showDeconvDrillDownModal <- function(clicked_group, full_data) {
    
    # Filter data for the clicked group
    group_data <- full_data %>%
      filter(group == clicked_group)
    
    n_samples_in_group <- length(unique(group_data$sample))
    
    print(paste("📊 Creating drill-down for group:", clicked_group))
    print(paste("   Samples in group:", n_samples_in_group))
    
    # ✅ ADAPTIVE SIZING based on number of samples
    # More samples = wider modal and plot
    if (n_samples_in_group <= 20) {
      modal_size <- "l"
      plot_height <- 600
      plot_width <- 900
    } else if (n_samples_in_group <= 50) {
      modal_size <- "xl"
      plot_height <- 700
      plot_width <- 1200
    } else if (n_samples_in_group <= 100) {
      modal_size <- "xl"
      plot_height <- 800
      plot_width <- 1600
    } else {
      modal_size <- "xl"
      plot_height <- 900
      plot_width <- 2000
    }
    
    # Create individual sample plot with VERTICAL x-axis labels
    p_drill <- ggplot(group_data, aes(x = sample, y = proportion * 100, fill = cell_type)) +
      geom_bar(stat = "identity", position = "stack", width = 0.8) +
      labs(
        title = paste("Individual Sample Composition -", clicked_group),
        subtitle = paste(n_samples_in_group, "samples"),
        x = "Sample",
        y = "Proportion (%)",
        fill = "Cell Type"
      ) +
      theme_minimal() +
      theme(
        axis.text.x = element_text(angle = 90, hjust = 1, vjust = 0.5, size = 9),  # ✅ VERTICAL labels
        axis.text.y = element_text(size = 11),
        axis.title = element_text(size = 12, face = "bold"),
        plot.title = element_text(hjust = 0.5, size = 14, face = "bold"),
        plot.subtitle = element_text(hjust = 0.5, size = 11, color = "#666"),
        legend.position = "right",
        legend.text = element_text(size = 9),
        panel.grid.major.x = element_blank(),
        plot.margin = margin(10, 10, 10, 10)
      ) +
      scale_fill_viridis_d(option = "turbo", direction = -1)
    
    # Convert to interactive plotly
    p_drill_interactive <- ggplotly(p_drill, height = plot_height, width = plot_width) %>%
      layout(
        margin = list(l = 60, r = 150, t = 80, b = 120),  # Extra bottom margin for rotated labels
        xaxis = list(tickangle = -90),  # Ensure rotation in plotly too
        font = list(family = "Arial, sans-serif")
      )
    
    # Store for download
    rv_deg_main$drilldown_plot <- p_drill
    rv_deg_main$drilldown_group <- clicked_group
    
    # Show modal with adaptive sizing
    showModal(modalDialog(
      title = div(
        style = "background: linear-gradient(135deg, #667eea 0%, #764ba2 100%); 
               color: white; padding: 15px; margin: -15px -15px 20px -15px; border-radius: 5px 5px 0 0;",
        icon("search-plus"),
        paste(" Detailed View:", clicked_group, "Group")
      ),
      size = modal_size,  # ✅ Adaptive size
      
      div(
        class = "alert alert-info",
        style = "margin-bottom: 20px; font-size: 14px;",
        HTML(paste0(
          "<strong>📊 Viewing individual samples from: ", clicked_group, "</strong><br>",
          "Total samples in this group: <strong>", n_samples_in_group, "</strong><br>",
          "💡 Hover over bars to see exact proportions for each cell type."
        ))
      ),
      
      # The drill-down plot - wrapped in scrollable container for very wide plots
      div(
        style = "background: white; padding: 15px; border-radius: 8px; 
               box-shadow: 0 2px 8px rgba(0,0,0,0.1); overflow-x: auto;",  # ✅ Horizontal scroll if needed
        plotlyOutput("drilldown_plot_output", height = paste0(plot_height, "px"), width = "100%")
      ),
      
      # Download option
      div(
        style = "margin-top: 20px; text-align: center;",
        downloadButton(
          "download_drilldown_plot",
          paste("💾 Download", clicked_group, "Plot"),
          class = "btn btn-primary"
        )
      ),
      
      footer = modalButton("Close", icon = icon("times")),
      easyClose = TRUE
    ))
    
    # Render the plot in the modal
    output$drilldown_plot_output <- renderPlotly({
      p_drill_interactive
    })
  }
  
