  # Download handler for PPI Network Metrics combined image
  output$download_ppi_metrics_image <- downloadHandler(
    filename = function() {
      paste0("ppi_network_metrics_", Sys.Date(), ".png")
    },
    content = function(file) {
      req(network_rv$current_results)
      req(network_rv$current_results$analysis_type == "ppi")
      
      load_visualization_packages()
      
      # Create temporary directory for individual plots
      temp_dir <- tempdir()
      
      # Get data
      hub_data <- network_rv$current_results$hub_proteins
      interactions <- network_rv$current_results$ppi_interactions
      metrics <- network_rv$current_results$summary_stats
      
      # 1. Network Statistics Table as grob
      metric_table <- data.frame(
        Metric = c("Total Proteins", "Total Interactions", "Input Genes", 
                   "Coverage Rate", "Network Density", "Average Degree", 
                   "Hub Proteins", "Major Hubs"),
        Value = c(
          metrics$basic_stats$total_proteins %||% 0,
          metrics$basic_stats$total_interactions %||% 0,
          metrics$basic_stats$input_genes %||% 0,
          paste0(metrics$basic_stats$coverage_rate %||% 0, "%"),
          round(metrics$topology_stats$density %||% 0, 4),
          round(metrics$topology_stats$avg_degree %||% 0, 2),
          metrics$hub_stats$total_hubs %||% 0,
          metrics$hub_stats$major_hubs %||% 0
        )
      )
      
      p1 <- gridExtra::tableGrob(metric_table, rows = NULL,
                                 theme = gridExtra::ttheme_default(
                                   core = list(bg_params = list(fill = c("white", "#f5f5f5"))),
                                   colhead = list(bg_params = list(fill = "#3498db"),
                                                  fg_params = list(col = "white"))
                                 ))
      
      # 2. Confidence Distribution
      p2 <- ggplot(interactions, aes(x = combined_score)) +
        geom_histogram(bins = 20, fill = "#3498db", color = "white") +
        labs(title = "Confidence Score Distribution",
             x = "Confidence Score", y = "Number of Interactions") +
        theme_minimal()
      
      # 3. Degree Distribution
      degree_dist <- hub_data %>%
        dplyr::count(degree) %>%
        dplyr::arrange(degree)
      
      p3 <- ggplot(degree_dist, aes(x = degree, y = n, fill = degree)) +
        geom_bar(stat = "identity") +
        scale_fill_viridis_c() +
        labs(title = "Degree Distribution",
             x = "Node Degree", y = "Number of Proteins") +
        theme_minimal() +
        theme(legend.position = "none")
      
      # 4. Centrality Plot
      top_proteins <- hub_data %>%
        dplyr::arrange(desc(degree)) %>%
        dplyr::slice_head(n = 20)
      
      p4 <- ggplot(top_proteins, aes(x = betweenness, y = closeness, 
                                     size = degree, color = degree)) +
        geom_point(alpha = 0.7) +
        scale_color_viridis_c() +
        scale_size_continuous(range = c(3, 12)) +
        labs(title = "Centrality Analysis (Top 20)",
             x = "Betweenness Centrality", y = "Closeness Centrality") +
        theme_minimal()
      
      # Combine all plots
      combined <- gridExtra::grid.arrange(
        p1, p2, p3, p4,
        ncol = 2, nrow = 2,
        top = grid::textGrob("PPI Network Metrics Summary", 
                             gp = grid::gpar(fontsize = 16, fontface = "bold"))
      )
      
      # Save combined plot
      ggsave(file, plot = combined, width = 14, height = 12, dpi = 300)
    }
  )
  
  # Download handler for PPI Network as HTML
  output$ppi_download_html <- downloadHandler(
    filename = function() {
      paste0("ppi_network_", Sys.Date(), ".html")
    },
    content = function(file) {
      req(network_rv$current_results)
      req(network_rv$current_results$network_data)
      
      nodes <- network_rv$current_results$network_data$nodes
      edges <- network_rv$current_results$network_data$edges
      
      # Create visNetwork object
      network <- visNetwork(nodes, edges) %>%
        visOptions(highlightNearest = TRUE, nodesIdSelection = TRUE) %>%
        visPhysics(stabilization = TRUE) %>%
        visLayout(randomSeed = 42)
      
      # Save as HTML
      visSave(network, file = file, selfcontained = TRUE)
    }
  )
  
