        export_data$mean_score <- round(export_data$mean_score, 5)
      }
      if ("sd_score" %in% colnames(export_data)) {
        export_data$sd_score <- round(export_data$sd_score, 5)
      }
      if ("p_value" %in% colnames(export_data)) {
        export_data$p_value_formatted <- formatC(export_data$p_value, format = "e", digits = 3)
      }
      
      # Add metadata as comments in CSV
      metadata <- paste0(
        "# Cell Type Deconvolution Results\n",
        "# Method: ", rv_deg_main$exploratory_deconv$method, "\n",
        "# Date: ", Sys.Date(), "\n",
        "# Samples: ", rv_deg_main$exploratory_deconv$data_info$n_samples, "\n",
        "# Genes: ", rv_deg_main$exploratory_deconv$data_info$n_genes, "\n",
        "# Conversion Rate: ", round(rv_deg_main$exploratory_deconv$data_info$conversion_rate * 100, 1), "%\n",
        "#\n"
      )
      
      # Write metadata
      writeLines(metadata, file)
      
      # Append data
      write.table(export_data, file, append = TRUE, sep = ",", 
                  row.names = FALSE, col.names = TRUE, quote = TRUE)
    }
  )
  
  
  
