        extensions = 'Buttons',
        rownames = FALSE
      ) %>%
        DT::formatStyle(
          'Significance',
          backgroundColor = DT::styleEqual(
            c("Significant", "Not Significant"),
            c('#d4edda', '#f8d7da')
          )
        ) %>%
        DT::formatStyle(
          'Effect Size (d)',
          color = DT::styleInterval(
