  #' Protein Information Table (Updated)
  output$protein_info_table <- DT::renderDataTable({
    req(network_rv$current_results)
    req(network_rv$current_results$analysis_type == "ppi")
    
    hub_data <- network_rv$current_results$hub_proteins
    
    if (is.null(hub_data) || nrow(hub_data) == 0) {
      return(DT::datatable(
        data.frame(Message = "No protein information available"),
        options = list(pageLength = 5, dom = 't'),
        rownames = FALSE
      ))
    }
    
    # Create comprehensive protein info table
    display_table <- hub_data %>%
      mutate(
        Protein = gene,
        Degree = degree,
        `Hub Type` = hub_type %||% ifelse(degree >= 10, "Hub", "Non-hub"),
        `Gene Source` = gene_source %||% "Network",
        `Betweenness` = round(betweenness %||% 0, 2),
        `Closeness` = round(closeness %||% 0, 4),
        `Regulation` = regulation %||% "Unknown"
      ) %>%
      select(Protein, Degree, `Hub Type`, `Gene Source`, Betweenness, Closeness, Regulation) %>%
      arrange(desc(Degree))
    
    DT::datatable(
      display_table,
      options = list(
        pageLength = 15,
        scrollX = TRUE,
        dom = 'frtip'
      ),
      rownames = FALSE,
      filter = 'top'
    ) %>%
      formatStyle(
        'Hub Type',
        backgroundColor = styleEqual(
          c("Major Hub", "Hub", "Non-hub"),
          c('#e74c3c', '#f39c12', '#95a5a6')
        ),
        color = "white"
      ) %>%
      formatStyle(
        'Regulation',
        color = styleEqual(
          c("Up", "Down", "Unknown"),
          c('#e74c3c', '#3498db', '#95a5a6')
        ),
        fontWeight = "bold"
      )
  })
  
  #' Network Metrics Table (Updated)
  output$network_metrics <- renderTable({
    req(network_rv$current_results)
    req(network_rv$current_results$analysis_type == "ppi")
    
    metrics <- network_rv$current_results$summary_stats
    
    if (is.null(metrics)) {
      return(data.frame(Metric = "No metrics available", Value = NA))
    }
    
    # Extract and format metrics
    metric_table <- tryCatch({
      data.frame(
        Metric = c(
          "Total Proteins",
          "Total Interactions",
          "Input Genes",
          "Coverage Rate",
          "Network Density",
          "Average Degree",
          "Hub Proteins",
          "Major Hubs"
        ),
        Value = c(
          metrics$basic_stats$total_proteins %||% metrics$n_nodes %||% 0,
          metrics$basic_stats$total_interactions %||% metrics$n_edges %||% 0,
          metrics$basic_stats$input_genes %||% 0,
          paste0(metrics$basic_stats$coverage_rate %||% 0, "%"),
          round(metrics$topology_stats$density %||% 0, 4),
          round(metrics$topology_stats$avg_degree %||% metrics$avg_degree %||% 0, 2),
          metrics$hub_stats$total_hubs %||% 0,
          metrics$hub_stats$major_hubs %||% 0
        ),
        stringsAsFactors = FALSE
      )
    }, error = function(e) {
      data.frame(Metric = "Error loading metrics", Value = e$message)
    })
    
    metric_table
  }, striped = TRUE, hover = TRUE)
  
  #' Degree Distribution Plot (Updated)
  output$degree_distribution <- renderPlotly({
    req(network_rv$current_results)
    req(network_rv$current_results$analysis_type == "ppi")
    req(network_rv$current_results$hub_proteins)
    
    hub_data <- network_rv$current_results$hub_proteins
    
    if (nrow(hub_data) == 0) {
      # Create empty plot
      plot_ly() %>%
        layout(
          title = "No degree distribution data available",
          xaxis = list(title = "Degree"),
          yaxis = list(title = "Count")
        )
    } else {
      # Create degree distribution plot
      degree_dist <- hub_data %>%
        dplyr::count(degree) %>%
        dplyr::arrange(degree)
      
      plot_ly(
        x = degree_dist$degree,
        y = degree_dist$n,
        type = 'bar',
        marker = list(
          color = degree_dist$degree,
          colorscale = 'Viridis'
        )
      ) %>%
        layout(
          title = "Degree Distribution",
          xaxis = list(title = "Node Degree"),
          yaxis = list(title = "Number of Proteins"),
          showlegend = FALSE
        )
    }
  })
  
