  #' Download Network as PNG (Updated)
  output$download_ppi_network <- downloadHandler(
    filename = function() {
      paste0("ppi_network_", Sys.Date(), ".png")
    },
    content = function(file) {
      load_export_packages()
      req(network_rv$current_results$network_data)
      req(input$network_analysis_type_systems == "ppi")
      
      network_data <- network_rv$current_results$network_data
      
      # Create high-resolution network for export
      export_network <- visNetwork(
        nodes = network_data$nodes,
        edges = network_data$edges,
        main = list(text = "Protein-Protein Interaction Network",
                    style = "font-family:Arial;font-size:24px;font-weight:bold;"),
        width = "2000px",
        height = "2000px"
      ) %>%
        visPhysics(
          solver = "barnesHut",
          stabilization = list(enabled = TRUE, iterations = 1000)
        ) %>%
        visInteraction(
          dragNodes = FALSE, dragView = FALSE, zoomView = FALSE,
          navigationButtons = FALSE
        ) %>%
        visOptions(highlightNearest = FALSE, nodesIdSelection = FALSE) %>%
        visLayout(randomSeed = 42) %>%
        visLegend(enabled = TRUE, useGroups = TRUE, position = "right")
      
      # Save to temporary HTML file
      temp_html <- tempfile(fileext = ".html")
      visSave(export_network, file = temp_html, selfcontained = TRUE)
      
      # Convert to PNG using webshot2
      if (require("webshot2", quietly = TRUE)) {
        webshot2::webshot(
          url = temp_html,
          file = file,
          delay = 3,
          vwidth = 2000,
          vheight = 2000,
          zoom = 1,
          # --- KEY ADDITION FOR SERVER/DOCKER ENVIRONMENTS ---
          extra_args = c(
            "--no-sandbox",
            "--disable-gpu",
            "--disable-dev-shm-usage"
          )
        )
      } else {
        # Fallback: save as HTML
        file.copy(temp_html, gsub("\\.png$", ".html", file))
        showNotification("Network saved as HTML (webshot2 not available for PNG)", type = "warning")
      }
    }
  )
  
