  # Display DEG summary for PPI
  output$ppi_deg_summary <- renderText({
    
    tryCatch({
      
      if (!is.null(rv_deg_main$deg_results)) {
        
        # ✅ Get p-value type (adjusted or raw)
        pvalue_type <- input$pvalue_type_main %||% "adjusted" 
        
        # ✅ Get correct p-value column based on user selection
        pval_column <- if (pvalue_type == "adjusted") {
          "adj.P.Val"
        } else {
          "P.Value"
        }
        
        # ✅ Get thresholds
        pval_threshold <- rv_deg_main$pvalue_cutoff_deg_main %||% 
          input$pvalue_cutoff_deg_main %||% 
          0.05
        
        # ✅ Get log2FC max threshold (absolute value used for both directions)
        log2fc_max <- rv_deg_main$log2fc_max_main %||% 
          input$log2fc_max %||% 
          2
        
        # ✅ Get log2FC min threshold (negative value)
        log2fc_min <- rv_deg_main$log2fc_min_main %||% 
          input$log2fc_min %||% 
          -2
        
        print(paste("DEBUG - PPI summary thresholds:"))
        print(paste("  P-value type:", pvalue_type))
        print(paste("  P-value column:", pval_column))
        print(paste("  P-value threshold:", pval_threshold))
        print(paste("  Log2FC min:", log2fc_min))
        print(paste("  Log2FC max:", log2fc_max))
        
        # Count DEGs using the correct p-value column
        deg_data <- rv_deg_main$deg_results
        
        up_count <- sum(
          !is.na(deg_data[[pval_column]]) & 
            !is.na(deg_data$log2FC) &
            deg_data[[pval_column]] < pval_threshold &
            deg_data$log2FC > log2fc_max,  # Use max threshold for up
          na.rm = TRUE
        )
        
        down_count <- sum(
          !is.na(deg_data[[pval_column]]) & 
            !is.na(deg_data$log2FC) &
            deg_data[[pval_column]] < pval_threshold &
            deg_data$log2FC < log2fc_min,  # Use min threshold for down
          na.rm = TRUE
        )
        
        total_count <- up_count + down_count
        
        # ✅ Display label based on p-value type
        pval_label <- ifelse(pvalue_type == "adjusted", "Adj. p-value", "Raw p-value")
        
        if (total_count > 0) {
          # ✅ Display with CORRECT p-value type
          paste0(
            "Will analyze ", total_count, " significant DEGs (", 
            up_count, " up-regulated, ", down_count, " down-regulated)\n",
            "Filtering criteria: ", pval_label, " < ", pval_threshold, 
            ", Log2FC < ", log2fc_min, " or > ", log2fc_max
          )
        } else {
          paste0(
            "No significant DEGs found with current thresholds:\n",
            pval_label, " < ", pval_threshold, 
            ", Log2FC < ", log2fc_min, " or > ", log2fc_max
          )
        }
        
      } else if (!is.null(rv_deg_main$up_regulated) && !is.null(rv_deg_main$down_regulated)) {
        
        up_count <- nrow(rv_deg_main$up_regulated %||% data.frame())
        down_count <- nrow(rv_deg_main$down_regulated %||% data.frame())
        total_count <- up_count + down_count
        
        # Get thresholds for display
        pval_threshold <- rv_deg_main$pvalue_cutoff_deg_main %||% 0.05
        log2fc_max <- rv_deg_main$log2fc_max_main %||% 2
        log2fc_min <- rv_deg_main$log2fc_min_main %||% -2
        
        if (total_count > 0) {
          paste0(
            "Will analyze ", total_count, " significant DEGs (", 
            up_count, " up-regulated, ", down_count, " down-regulated)\n",
            "Filtering criteria: Adj. p-value < ", pval_threshold, 
            ", Log2FC < ", log2fc_min, " or > ", log2fc_max
          )
        } else {
          "No significant DEGs found. Please run DEG analysis first."
        }
        
      } else {
        "Please run DEG analysis first to identify significant genes for PPI analysis."
      }
      
    }, error = function(e) {
      print(paste("Error in ppi_deg_summary:", e$message))
      "DEG data not available. Please run DEG analysis first."
    })
  })
  
