  create_empty_ppi_results <- function() {
    list(
      network_data = list(
        nodes = data.frame(id = character(0), label = character(0), group = character(0), stringsAsFactors = FALSE),
        edges = data.frame(from = character(0), to = character(0), weight = numeric(0), stringsAsFactors = FALSE)
      ),
      ppi_interactions = data.frame(
        gene_from = character(0),
        gene_to = character(0),
        combined_score = numeric(0),
        interaction_source = character(0),
        stringsAsFactors = FALSE
      ),
      network_metrics = list(
        n_nodes = 0,
        n_edges = 0,
        avg_degree = 0,
        max_degree = 0,
        density = 0
      ),
      hub_proteins = data.frame(
        gene = character(0),
        degree = numeric(0),
        is_input_gene = logical(0),
        stringsAsFactors = FALSE
      ),
      summary_stats = list(
        n_nodes = 0,
        n_edges = 0,
        avg_degree = 0,
        density = 0
      ),
      analysis_params = list(
        organism = "human",
        confidence_threshold = 0.3,
        max_interactions = 500,
        n_input_genes = 0,
        n_interactions = 0
      ),
      analysis_type = "ppi",
      error = "No data available"
    )
  }
  
  #' Fill missing PPI components
  fill_missing_ppi_components <- function(ppi_results, missing_components) {
    
    empty_results <- create_empty_ppi_results()
    
    for (component in missing_components) {
      if (!component %in% names(ppi_results)) {
        ppi_results[[component]] <- empty_results[[component]]
      }
    }
    
    return(ppi_results)
  }
  
  
  
  # Fixed PPI Results Processing
  process_ppi_results_safely <- function(ppi_results, selected_genes) {
    
    print("🔍 Processing PPI results safely...")
    
    # Step 1: Validate the PPI results structure
    if (is.null(ppi_results)) {
      print("❌ PPI results are NULL")
      return(create_empty_ppi_results())
    }
    
    # Step 2: Check if results is actually a list
    if (!is.list(ppi_results)) {
      print(paste("❌ PPI results is not a list, it's:", class(ppi_results)))
      print(paste("PPI results content:", ppi_results))
      return(create_empty_ppi_results())
    }
    
    # Step 3: Check for error in results
    if ("error" %in% names(ppi_results) && !is.null(ppi_results$error)) {
      print(paste("❌ PPI analysis returned error:", ppi_results$error))
      return(list(
        error = ppi_results$error,
        analysis_type = "ppi"
      ))
    }
    
    # Step 4: Validate required components exist
    required_components <- c("network_data", "ppi_interactions", "network_metrics", "hub_proteins", "summary_stats")
    missing_components <- setdiff(required_components, names(ppi_results))
    
    if (length(missing_components) > 0) {
      print(paste("⚠️ Missing PPI components:", paste(missing_components, collapse = ", ")))
      # Fill in missing components
      ppi_results <- fill_missing_ppi_components(ppi_results, missing_components)
    }
    
    # Step 5: Ensure analysis_type is set
    if (!"analysis_type" %in% names(ppi_results)) {
      ppi_results$analysis_type <- "ppi"
    }
    
    print("✅ PPI results processed successfully")
    return(ppi_results)
  }
  
  
