  # Helper function to create empty PPI results
  create_empty_ppi_result <- function(results_info, message) {
    empty_df <- data.frame(
      gene_from = character(0),
      gene_to = character(0),
      combined_score = numeric(0),
      interaction_source = character(0),
      stringsAsFactors = FALSE
    )
    
    results_info$success <- FALSE
    results_info$error_message <- message
    
    attr(empty_df, "ppi_metadata") <- results_info
    attr(empty_df, "user_message") <- paste("❌ No PPI data:", message)
    
    print(paste("📝", message))
    return(empty_df)
  }
  
  # Helper to fill missing components
  fill_missing_ppi_components <- function(ppi_results, missing_components) {
    
    empty_results <- create_empty_ppi_results()
    
    for (component in missing_components) {
      if (component %in% names(empty_results)) {
        ppi_results[[component]] <- empty_results[[component]]
        print(paste("✅ Filled missing component:", component))
      }
    }
    
    return(ppi_results)
  }
  
  # Validate data integrity
  validate_ppi_data_integrity <- function(ppi_results) {
    
    # Check network_data structure
    if (!is.null(ppi_results$network_data)) {
      if (!is.list(ppi_results$network_data)) {
        print("⚠️ network_data is not a list, fixing...")
        ppi_results$network_data <- create_empty_ppi_results()$network_data
      } else {
        # Ensure nodes and edges exist
        if (!"nodes" %in% names(ppi_results$network_data)) {
          ppi_results$network_data$nodes <- data.frame(id = character(0), label = character(0), stringsAsFactors = FALSE)
        }
        if (!"edges" %in% names(ppi_results$network_data)) {
          ppi_results$network_data$edges <- data.frame(from = character(0), to = character(0), stringsAsFactors = FALSE)
        }
      }
    }
    
    # Check ppi_interactions is a data.frame
    if (!is.null(ppi_results$ppi_interactions) && !is.data.frame(ppi_results$ppi_interactions)) {
      print("⚠️ ppi_interactions is not a data.frame, fixing...")
      ppi_results$ppi_interactions <- create_empty_ppi_results()$ppi_interactions
    }
    
    # Check hub_proteins is a data.frame
    if (!is.null(ppi_results$hub_proteins) && !is.data.frame(ppi_results$hub_proteins)) {
      print("⚠️ hub_proteins is not a data.frame, fixing...")
      ppi_results$hub_proteins <- create_empty_ppi_results()$hub_proteins
    }
    
    return(ppi_results)
  }
  
  # ============================================================================
  # SAFE RESULTS ASSIGNMENT WRAPPER
  # ============================================================================
  assign_ppi_results_fixed <- function(ppi_results) {
    tryCatch({
      
      print("📦 Assigning PPI results with fixes...")
      
      # Process and fix the results
      ppi_results <- process_and_fix_ppi_results(ppi_results)
      
      # Ensure analysis_type is explicitly set
      ppi_results$analysis_type <- "ppi"
      
      # Store in current_results
      isolate({
        network_rv$current_results <- ppi_results
        network_rv$analysis_status <- "complete"
        network_rv$analysis_type <- "ppi"
      })
      
      # Also store in ppi_results as backup
      if (!"error" %in% names(ppi_results)) {
        network_rv$ppi_results <- ppi_results
        print("✅ PPI results stored in both current_results and ppi_results")
      }
      
      # Debug output
      print("📊 Final result structure:")
      print(paste("  - network_data: nodes =", nrow(ppi_results$network_data$nodes), "edges =", nrow(ppi_results$network_data$edges)))
      print(paste("  - ppi_interactions:", nrow(ppi_results$ppi_interactions), "interactions"))
      print(paste("  - hub_proteins:", nrow(ppi_results$hub_proteins), "proteins"))
      print(paste("  - summary_stats: available =", !is.null(ppi_results$summary_stats)))
      print(paste("  - analysis_type:", ppi_results$analysis_type))
      
      return(TRUE)
      
    }, error = function(e) {
      print(paste("❌ Error assigning PPI results:", e$message))
      
      # Set error state
      isolate({
        network_rv$current_results <- list(error = e$message, analysis_type = "ppi")
        network_rv$analysis_status <- "error"
      })
      
      return(FALSE)
    })
  }
  
  
  
