            cat("   Rows: ", nrow(data), " Cols: ", ncol(data), "\n")
          }
        } else {
          cat("❌ ", name, " is NULL\n")
        }
      }
    } else {
      cat("❌ current_results is NULL\n")
    }
    
    cat("================================\n\n")
  }
  
