  # ============================================================================
  # TAB 1: PPI NETWORK VISUALIZATION
  # ============================================================================
  
  output$ppi_network <- renderVisNetwork({
    
    req(network_rv$current_results)
    req(network_rv$current_results$analysis_type == "ppi")
    
    network_data <- network_rv$current_results$network_data
    
    if (is.null(network_data) || is.null(network_data$nodes) || nrow(network_data$nodes) == 0) {
      return(visNetwork(
        nodes = data.frame(id = "No Data", label = "No Network Data Available", color = "#cccccc"),
        edges = data.frame()
      ))
    }
    
    print("🎨 Rendering PPI network visualization...")
    print(paste("✓ Network data found:", nrow(network_data$nodes), "nodes,", nrow(network_data$edges), "edges"))
    
    tryCatch({
      
      # Create enhanced PPI network with improvements from pathway network
      visNetwork(network_data$nodes, network_data$edges, width = "100%", height = "100%") %>%
        
        # 1. ENHANCED NODE STYLING - LARGER LABELS
        visNodes(
          font = list(
            size = 18,           # Increased from default 14 to 18
            color = "black",
            strokeWidth = 1,
            strokeColor = "white"
          ),
          borderWidth = 2,
          shadow = list(enabled = TRUE, size = 5),
          scaling = list(min = 15, max = 60),  # Larger node scaling
          chosen = list(node = "function(values, id, selected, hovering) {
          values.size = values.size * 1.2;
          values.borderWidth = 3;
        }")
        ) %>%
        
        # 2. ENHANCED EDGE STYLING
        visEdges(
          smooth = list(
            enabled = TRUE,
            type = "continuous",
            forceDirection = "none"
          ),
          shadow = FALSE,
          color = list(
            color = "#848484",
            highlight = "#E74C3C",
            inherit = FALSE
          ),
          width = 2,
          selectionWidth = 4
        ) %>%
        
        # 3. GROUP STYLING (same as before but with better colors)
        visGroups(
          groupname = "Up-regulated",
          color = list(background = "#E74C3C", border = "#C0392B"),
          shape = "dot",
          font = list(size = 18, color = "black")
        ) %>%
        visGroups(
          groupname = "Down-regulated",
          color = list(background = "#3498DB", border = "#2980B9"),
          shape = "dot",
          font = list(size = 18, color = "black")
        ) %>%
        visGroups(
          groupname = "Network",
          color = list(background = "#95A5A6", border = "#7F8C8D"),
          shape = "dot",
          font = list(size = 16, color = "black")
        ) %>%
        visGroups(
          groupname = "Input",
          color = list(background = "#F39C12", border = "#E67E22"),
          shape = "dot",
          font = list(size = 18, color = "black")
        ) %>%
        
        # 4. PHYSICS SETTINGS - BASED ON YOUR PATHWAY NETWORK SUCCESS
        visPhysics(
          enabled = TRUE,
          solver = "forceAtlas2Based",
          forceAtlas2Based = list(
            gravitationalConstant = -50,
            centralGravity = 0.01,
            springLength = 100,
            springConstant = 0.08,
            damping = 0.4,
            avoidOverlap = 0.5
          ),
          stabilization = list(
            enabled = TRUE,
            iterations = 1000,
            updateInterval = 25,
            onlyDynamicEdges = FALSE,
            fit = TRUE
          ),
          timestep = 0.35,
          adaptiveTimestep = TRUE,
          maxVelocity = 30,
          minVelocity = 0.75
        ) %>%
        
        # 5. ⭐ THE MAGIC: AUTO-STABILIZATION (same as pathway network)
        visEvents(
          stabilizationIterationsDone = "function() {
          this.setOptions({ physics: false });
          console.log('PPI network stabilized - physics disabled');
        }"
        ) %>%
        
        # 6. INTERACTION OPTIONS
        visOptions(
          highlightNearest = list(
            enabled = TRUE,
            degree = 1,
            hover = TRUE,
            labelOnly = FALSE
          ),
          nodesIdSelection = list(
            enabled = TRUE,
            style = 'width: 200px; height: 26px; background: #f8f8f8; color: #333;'
          ),
          selectedBy = list(
            variable = "group",
            multiple = TRUE,
            style = 'width: 150px; height: 26px; background: #f8f8f8; color: #333;'
          ),
          collapse = FALSE
        ) %>%
        
        # 7. INTERACTION CONTROLS
        visInteraction(
          dragNodes = TRUE,
          dragView = TRUE,
          zoomView = TRUE,
          selectConnectedEdges = TRUE,
          navigationButtons = TRUE,
          tooltipDelay = 200,
          keyboard = list(
            enabled = TRUE,
            speed = list(x = 10, y = 10, zoom = 0.02)
          )
        ) %>%
        
        # 8. CONSISTENT LAYOUT
        visLayout(
          randomSeed = 12345,  # Consistent layout across renders
          improvedLayout = TRUE,
          clusterThreshold = 150
        ) %>%
        
        # 9. ENHANCED LEGEND
        visLegend(
          useGroups = TRUE,
          position = "right",
          width = 0.15,
          zoom = FALSE,
          stepY = 40,
          stepX = 100
        )
      
    }, error = function(e) {
      print(paste("❌ Error creating PPI network visualization:", e$message))
      
      # Fallback network
      return(visNetwork(
        nodes = data.frame(
          id = "error_node",
          label = paste("Network Error:", e$message),
          color = "#E74C3C",
          font.size = 16
        ),
        edges = data.frame()
      ))
    })
  })
  
  # Reset button - re-enables physics to recalculate layout
  observeEvent(input$ppi_reset_network, {
    visNetworkProxy("ppi_network") %>%
      visPhysics(enabled = TRUE) %>%
      visFit(animation = list(duration = 1000))
    
