      return(DT::datatable(
        data.frame(Message = "No interactions found"),
        options = list(pageLength = 5, dom = 't'),
        rownames = FALSE
      ))
    }
    
    # Debug what columns we actually have
    print(paste("PPI interactions rows:", nrow(ppi_data)))
    print(paste("PPI interactions columns:", paste(colnames(ppi_data), collapse = ", ")))
    
    # Build display table step by step to avoid dimension mismatch
    display_table <- data.frame(
      `Protein A` = character(nrow(ppi_data)),
      `Protein B` = character(nrow(ppi_data)),
      `Interaction Score` = numeric(nrow(ppi_data)),
      `Confidence Level` = character(nrow(ppi_data)),
      Source = character(nrow(ppi_data)),
      stringsAsFactors = FALSE,
      check.names = FALSE  # Preserve column names with spaces
    )
    
    # Fill in the data
    display_table$`Protein A` <- ppi_data$gene_from
    display_table$`Protein B` <- ppi_data$gene_to
    
    # Handle score
    if ("combined_score" %in% colnames(ppi_data)) {
      display_table$`Interaction Score` <- round(ppi_data$combined_score, 3)
    } else {
      display_table$`Interaction Score` <- 0.5
    }
    
    # Calculate confidence level
    display_table$`Confidence Level` <- ifelse(
      display_table$`Interaction Score` >= 0.8, "High",
      ifelse(display_table$`Interaction Score` >= 0.6, "Medium",
             ifelse(display_table$`Interaction Score` >= 0.4, "Moderate", "Low"))
    )
    
    # Add source
    display_table$Source <- "STRING"
    
    # Sort by score
    display_table <- display_table[order(display_table$`Interaction Score`, decreasing = TRUE), ]
    
    print(paste("Display table created with", nrow(display_table), "rows and", ncol(display_table), "columns"))
    print(paste("Display table columns:", paste(colnames(display_table), collapse = ", ")))
    
    # Create datatable with formatting - server-side processing
    DT::datatable(
      display_table,
      options = list(
        pageLength = 15,
        scrollX = TRUE,
        dom = 'lfrtip',
        deferRender = TRUE,
        processing = TRUE,
        columnDefs = list(
          list(className = 'dt-center', targets = '_all')
        )
      ),
      rownames = FALSE,
      filter = 'top'
    ) %>%
