          c('#27ae60', '#3498db', '#f39c12', '#e74c3c')
        ),
        color = styleEqual(
          c("High", "Medium", "Moderate", "Low"),
          c('white', 'white', 'white', 'white')
        )
      )
  }, server = TRUE)
  
  detect_ppi_modules <- function(ppi_interactions, min_module_size = 3) {
    
    print("🔍 Detecting network modules...")
    
    if (!requireNamespace("igraph", quietly = TRUE)) {
      print("igraph package not available for module detection")
      return(NULL)
    }
    
    library(igraph)
    
    # Create graph from interactions
    g <- graph_from_data_frame(
      d = ppi_interactions[, c("gene_from", "gene_to")],
      directed = FALSE
    )
    
    # Apply community detection algorithms
    modules <- list()
    
    # 1. Fast greedy modularity optimization
    tryCatch({
      modules$fast_greedy <- cluster_fast_greedy(g)
      print(paste("Fast greedy: found", length(modules$fast_greedy), "modules"))
    }, error = function(e) {
      print(paste("Fast greedy failed:", e$message))
    })
    
    # 2. Louvain algorithm
    tryCatch({
      modules$louvain <- cluster_louvain(g)
      print(paste("Louvain: found", length(modules$louvain), "modules"))
    }, error = function(e) {
      print(paste("Louvain failed:", e$message))
    })
    
    # 3. Walktrap algorithm
    tryCatch({
      modules$walktrap <- cluster_walktrap(g)
      print(paste("Walktrap: found", length(modules$walktrap), "modules"))
    }, error = function(e) {
      print(paste("Walktrap failed:", e$message))
    })
    
    # Use the best performing algorithm (highest modularity)
    best_method <- NULL
    best_modularity <- -1
    
    for (method in names(modules)) {
      mod_score <- modularity(modules[[method]])
      if (mod_score > best_modularity) {
        best_modularity <- mod_score
        best_method <- method
      }
    }
    
    if (is.null(best_method)) {
      return(NULL)
    }
    
    print(paste("Best method:", best_method, "with modularity:", round(best_modularity, 3)))
    
    # Extract module membership
    best_modules <- modules[[best_method]]
    membership <- membership(best_modules)
    
    # Create module summary
    module_summary <- data.frame(
      Gene = names(membership),
      Module = paste0("Module_", membership),
      stringsAsFactors = FALSE
    )
    
    # Calculate module statistics
    module_stats <- module_summary %>%
      group_by(Module) %>%
      summarise(
        Size = n(),
        Genes = paste(Gene, collapse = ", ")
      ) %>%
      filter(Size >= min_module_size) %>%
      arrange(desc(Size))
    
    return(list(
      membership = module_summary,
      statistics = module_stats,
      modularity = best_modularity,
      method = best_method
    ))
  }
  
  
  
