  output$ppi_enrichment_table_expandable <- DT::renderDataTable({
    req(network_rv$current_results)
    req(network_rv$current_results$analysis_type == "ppi")
    
    enrichment_data <- network_rv$current_results$functional_enrichment
    
    if (is.null(enrichment_data) || length(enrichment_data) == 0) {
      return(DT::datatable(
        data.frame(Message = "No enrichment results available"),
        options = list(pageLength = 5, dom = 't'),
        rownames = FALSE
      ))
    }
    
    combined_results <- tryCatch({
      all_results <- data.frame()
      
      for (db_name in names(enrichment_data)) {
        db_results <- enrichment_data[[db_name]]
        
        if (is.data.frame(db_results) && nrow(db_results) > 0) {
          if ("Term" %in% colnames(db_results)) {
            gene_list <- db_results$Genes %||% ""
            
            # Create both short and full gene lists
            genes_full <- gsub(";", ", ", gene_list)
            genes_short <- sapply(gene_list, function(g) {
              genes <- unlist(strsplit(as.character(g), ";"))
              n_genes <- length(genes)
              if (n_genes > 3) {
                paste0(paste(genes[1:3], collapse = ", "), ", ... (+", n_genes - 3, " more)")
              } else {
                paste(genes, collapse = ", ")
              }
            })
            
            result_df <- data.frame(
              Database = db_results$Database,
              Term = substr(db_results$Term, 1, 80),
              Gene_Count = sapply(strsplit(as.character(gene_list), ";"), length),
              P.value = signif(db_results$P.value %||% 0.05, 3),
              Adjusted.P.value = signif(db_results$Adjusted.P.value %||% 0.05, 3),
              `-log10(p)` = round(-log10(db_results$P.value %||% 0.05), 2),
              Genes_Short = genes_short,
              Genes_Full = genes_full,
              stringsAsFactors = FALSE
            )
            
            all_results <- rbind(all_results, result_df)
          }
        }
      }
      
      if (nrow(all_results) > 0) {
        all_results %>%
          filter(Adjusted.P.value < 0.05) %>%
          arrange(Adjusted.P.value) %>%
          select(Database, Term, Gene_Count, P.value, Adjusted.P.value, `-log10(p)`, Genes_Short, Genes_Full)
      } else {
        data.frame(Message = "No significant enrichment found")
      }
      
    }, error = function(e) {
      data.frame(Message = paste("Error:", e$message))
    })
    
    if ("Message" %in% colnames(combined_results)) {
      return(DT::datatable(combined_results, options = list(dom = 't'), rownames = FALSE))
    }
    
    # Create a datatable with child rows for full gene lists
    DT::datatable(
      combined_results[, -8],  # Exclude Genes_Full from main table
      options = list(
        pageLength = 10,
        scrollX = TRUE,
        dom = 'Bfrtip',
        buttons = c('copy', 'csv', 'excel'),
        columnDefs = list(
          list(
            targets = 0,
            render = DT::JS(
              "function(data, type, row, meta) {
              return '<button class=\"btn btn-sm btn-info gene-expand\">+</button> ' + data;
            }"
            )
          )
        ),
        callback = DT::JS(
          "table.on('click', 'button.gene-expand', function() {
          var tr = $(this).closest('tr');
          var row = table.row(tr);
          if (row.child.isShown()) {
            row.child.hide();
            $(this).text('+');
          } else {
            var rowData = row.data();
            var fullGenes = '", paste0(combined_results$Genes_Full, collapse = "', '"), "'.split(\"', '\")[row.index()];
            row.child('<div style=\"padding: 10px; background-color: #f9f9f9;\"><strong>All Genes:</strong><br>' + fullGenes + '</div>').show();
            $(this).text('-');
          }
        });"
        )
      ),
      rownames = FALSE,
      escape = FALSE
    )
  })
  
  output$ppi_enrichment_table <- DT::renderDataTable({
    req(network_rv$current_results)
    req(network_rv$current_results$analysis_type == "ppi")
    
    print("📊 Rendering PPI enrichment table with gene names...")
    
    enrichment_data <- network_rv$current_results$functional_enrichment
    
    if (is.null(enrichment_data) || length(enrichment_data) == 0) {
      return(DT::datatable(
        data.frame(Message = "No enrichment results available"),
        options = list(pageLength = 5, dom = 't'),
        rownames = FALSE
      ))
    }
    
    # Combine all enrichment results into a single table
    combined_results <- tryCatch({
      all_results <- data.frame()
      
      for (db_name in names(enrichment_data)) {
        db_results <- enrichment_data[[db_name]]
        
        if (is.data.frame(db_results) && nrow(db_results) > 0) {
          # Add database source column
          db_results$Database <- db_name
          
          # Standardize column names
          if ("Term" %in% colnames(db_results)) {
            gene_list <- db_results$Genes %||% ""
            
            # Keep full gene list - no truncation for display
            # Users can scroll to see all genes
            
            result_df <- data.frame(
              Database = db_results$Database,
              Term = db_results$Term,
              Gene_Count = sapply(strsplit(as.character(gene_list), ";"), length),
              P.value = db_results$P.value %||% db_results$`P-value` %||% 0.05,
              Adjusted.P.value = db_results$Adjusted.P.value %||% db_results$`Adjusted P-value` %||% 0.05,
              Genes = gsub(";", ", ", gene_list),  # Replace semicolons with commas for readability
              stringsAsFactors = FALSE
            )
            
            all_results <- rbind(all_results, result_df)
          }
        }
      }
      
      if (nrow(all_results) > 0) {
        # Process the combined results
        all_results %>%
          filter(Adjusted.P.value < 0.05) %>%
          mutate(
            Term = substr(Term, 1, 80),  # Truncate only very long terms
            `-log10(p)` = round(-log10(P.value), 2),
            P.value = signif(P.value, 3),
            Adjusted.P.value = signif(Adjusted.P.value, 3)
          ) %>%
          # REORDER COLUMNS - Genes at the end
          select(Database, Term, Gene_Count, P.value, Adjusted.P.value, `-log10(p)`, Genes) %>%
          arrange(Adjusted.P.value)
      } else {
        data.frame(Message = "No significant enrichment found (adjusted p < 0.05)")
      }
      
    }, error = function(e) {
      print(paste("Error processing enrichment results:", e$message))
      data.frame(Message = "Error processing enrichment data")
    })
    
    if (nrow(combined_results) == 0 || "Message" %in% colnames(combined_results)) {
      return(DT::datatable(
        combined_results,
        options = list(pageLength = 5, dom = 't'),
        rownames = FALSE
      ))
    }
    
    # Create datatable with special formatting for the genes column
    # Cap displayed rows to keep the page responsive; full data is still
    # available via the Download Enrichment Results CSV button below.
    if (nrow(combined_results) > 200) {
      combined_results <- head(combined_results, 200)
    }

    DT::datatable(
      combined_results,
      options = list(
        pageLength = 10,
        scrollX = TRUE,
        order = list(list(4, 'asc')),  # Sort by adjusted p-value
        columnDefs = list(
          list(width = '150px', targets = 1),
          list(width = '60px', targets = 2),
          list(width = '80px', targets = 3),
          list(width = '80px', targets = 4),
          list(width = '60px', targets = 5),
          list(width = '400px', targets = 6),
          list(className = 'dt-left', targets = c(1, 6)),
          list(className = 'dt-center', targets = c(0, 2, 3, 4, 5))
        ),
        autoWidth = FALSE
      ),
      rownames = FALSE,
      escape = FALSE
    ) %>%
      formatStyle(
        'Adjusted.P.value',
        backgroundColor = styleInterval(
          c(0.001, 0.01, 0.05),
          c('#27ae60', '#52c41a', '#fadb14', 'white')
        )
      ) %>%
      formatStyle(
        'Gene_Count',
        backgroundColor = styleInterval(
          c(5, 10, 15),
          c('#f0f0f0', '#d4edda', '#b8e6b8', '#8fd68f')
        )
      ) %>%
      formatStyle(
        'Genes',
        fontSize = '11px',
        lineHeight = '1.2'
      )
  })

  # ============================================================
  # Advanced PPI: Functional Enrichment dotplot (added so the
  # 🧬 Enrichment tab has an exportable visualisation alongside
  # the existing table). Reads from network_rv$current_results
  # $functional_enrichment, the same source the table uses.
  # ============================================================
  build_ppi_advanced_enrichment_plot <- function(enrichment_data) {
    if (is.null(enrichment_data) || length(enrichment_data) == 0) return(NULL)

    all_results <- data.frame()
    for (db_name in names(enrichment_data)) {
      df <- enrichment_data[[db_name]]
      if (is.null(df) || !is.data.frame(df) || nrow(df) == 0) next
      if (!"Term" %in% colnames(df)) next
      gene_list <- df$Genes %||% rep("", nrow(df))
      pvals <- df$Adjusted.P.value %||% df$`Adjusted P-value` %||% rep(0.05, nrow(df))
      gene_count <- sapply(strsplit(as.character(gene_list), ";"), length)
      gene_count[gene_count == 0] <- 5
      all_results <- rbind(
        all_results,
        data.frame(Database = db_name,
                   Term = df$Term,
                   Gene_Count = gene_count,
                   Adjusted.P.value = as.numeric(pvals),
                   stringsAsFactors = FALSE)
      )
    }
    if (nrow(all_results) == 0) return(NULL)
    all_results <- all_results[!is.na(all_results$Adjusted.P.value) &
                                 all_results$Adjusted.P.value > 0, ]
    if (nrow(all_results) == 0) return(NULL)

    top <- head(all_results[order(all_results$Adjusted.P.value), ], 15)
    top$Term <- stringr::str_wrap(as.character(top$Term), width = 55)

    ggplot(top, aes(x = -log10(Adjusted.P.value),
                    y = reorder(Term, -log10(Adjusted.P.value)))) +
      geom_vline(xintercept = -log10(0.05), linetype = "dashed",
                 color = "red", alpha = 0.6) +
      geom_point(aes(size = Gene_Count, color = Database)) +
      scale_size_continuous(name = "Gene Count", range = c(4, 14),
                            breaks = scales::pretty_breaks(n = 5)) +
      scale_color_brewer(palette = "Set2", name = "Database") +
      labs(title = "PPI Network Functional Enrichment",
           x = "-log10(Adjusted P-value)", y = NULL) +
      theme_bw(base_size = 13) +
      theme(plot.background  = element_rect(fill = "white", color = NA),
            panel.background = element_rect(fill = "white", color = NA),
            legend.background = element_rect(fill = "white", color = NA),
            panel.grid.major.y = element_line(color = "grey88"),
            panel.grid.minor   = element_blank(),
            panel.border       = element_rect(color = "grey80", fill = NA),
            axis.text.y  = element_text(size = 11, color = "grey20",
                                        margin = margin(r = 6)),
            axis.text.x  = element_text(size = 11, color = "grey20"),
            axis.title.x = element_text(size = 12, margin = margin(t = 8)),
            plot.title   = element_text(size = 15, face = "bold",
                                        margin = margin(b = 12)),
            legend.position = "right",
            legend.key      = element_rect(fill = "white", color = NA),
            plot.margin     = margin(15, 20, 15, 20))
  }

