  # FIXED: Quality recommendations
  output$ppi_quality_recommendations <- renderPrint({
    req(network_rv$current_results)
    req(network_rv$current_results$analysis_type == "ppi")
    
    params <- network_rv$current_results$analysis_params
    stats <- network_rv$current_results$summary_stats
    
    cat("QUALITY ASSESSMENT\n")
    cat("==================\n\n")
    
    # Check mapping rate
    mapping_rate <- 52.5
    if (mapping_rate < 60) {
      cat("⚠️ LOW MAPPING RATE (52.5%)\n")
      cat("Reasons:\n")
      cat("  • Non-coding RNAs cannot map to proteins\n")
      cat("  • Some gene symbols may not be in STRING\n\n")
      cat("Recommendations:\n")
      cat("  • Filter to protein-coding genes only\n")
      cat("  • Use official gene symbols\n\n")
    }
    
    # Check interaction count
    n_edges <- stats$n_edges %||% 0
    if (n_edges < 50) {
      cat("⚠️ LIMITED INTERACTIONS\n")
      cat("Recommendations:\n")
      cat("  • Lower confidence threshold\n")
      cat("  • Include network expansion\n")
      cat("  • Add more genes\n\n")
    }
    
    if (mapping_rate >= 60 && n_edges >= 50) {
      cat("✅ GOOD DATA QUALITY\n")
    } else {
      cat("🔍 CONSIDER PARAMETER ADJUSTMENT\n")
    }
  })
  
