  #---------------------------------------------------UMAP---------------------
  # Server code for umap tab
  # Function to process data (no more separate functions for normalized/raw)
  processDataUmap <- function(inFile, normalization_method) {
    # inFile <- input$file3 # No longer needed, passed as argument
    if (is.null(inFile))
      return(NULL)
    
    data <- read.csv(inFile$datapath, header = TRUE, row.names = 1, sep = ",", check.names = FALSE, stringsAsFactors = FALSE)
    
    # Remove rows where all values are 0 or nil
    data <- data[rowSums(data != 0 & !is.na(data)) > 0, ]
    
    groups <- gsub("^[^_]*_", "", colnames(data))
    
    # Apply normalization
    data <- normalizeData(data, normalization_method) # Use the same normalizeData function from PCA/DEG
    
    # Check for constant columns after normalization
    constant_cols <- apply(data, 2, function(x) length(unique(x)) == 1)
    if (any(constant_cols)) {
      showNotification(paste("Warning: The following columns have constant values after normalization:",
                             paste(colnames(data)[constant_cols], collapse = ", ")),
                       type = "warning", duration = 10)
    }
    
    # --- UMAP Calculation ---
    
    # Set the number of neighbors based on the number of data points
    n_neighbors <- min(ncol(data), 15) - 1
    
    # Perform UMAP analysis with the specified number of neighbors
    umap_result <- umap(t(data), n_neighbors = n_neighbors) # Transpose data for umap
    
    # Create data frame for plotting
    plot_data_umap <- data.frame(UMAP1 = umap_result$layout[, 1],
                                 UMAP2 = umap_result$layout[, 2],
                                 SampleID = rownames(umap_result$layout),
                                 Category = groups)
    
    return(plot_data_umap)
  }
  
  processed_umap <- reactiveVal(NULL)
  
  observeEvent(input$submit_data_umap, {
    req(input$file3)
    
    processed_data_umap <- processDataUmap(input$file3, input$normalization_method_umap)
    
    processed_umap(plot_ly(processed_data_umap, x = ~UMAP1, y = ~UMAP2, type = "scatter", mode = "markers",
                           color = ~Category, colors = c("red", "blue", "green", "black"),
                           text = ~SampleID, hoverinfo = "text"))
  })
  
  output$umap <- renderPlotly({
    processed_umap()
  })
  
  output$download_umap <- downloadHandler(
    filename = function() {
      "umap_plot.png"
    },
    content = function(file) {
      load_export_packages()
      plotly::export(processed_umap(), file = file)
    }
  )
  
  
  
  #------------------------------------------TCGA ANALYSIS-----------------------
  observeEvent(input$submit, {
    # IMMEDIATELY disable button and show loading state
    shinyjs::disable("submit")
    shinyjs::html("submit", "<i class='fa fa-spinner fa-spin'></i> Running Analysis...")
    
    # Enable parallel processing for faster computation
    if (requireNamespace("BiocParallel", quietly = TRUE)) {
      BiocParallel::register(BiocParallel::MulticoreParam(workers = 4))
    }
    
    # Reset UI to welcome state
    shinyjs::show("tcga_welcome_panel")
    shinyjs::hide("tcga_results_panel")
    shinyjs::show("tcga_deg_welcome")
    shinyjs::hide("tcga_deg_results_div")
    shinyjs::show("tcga_viz_welcome")
    shinyjs::hide("tcga_viz_results_div")
    
    # Reset state
    tcga_rv$analysis_complete <- FALSE
    tcga_rv$results <- NULL
    tcga_rv$deg_data <- NULL
    tcga_rv$volcano_generated <- FALSE
    tcga_rv$heatmap_generated <- FALSE
    
    # Show immediate feedback while loading packages
    showNotification("Initializing analysis environment...", type = "message", duration = 2, id = "pkg_load")
    
    withProgress(message = "Loading required packages...", value = 0, {
      # Load required packages inside progress
      tryCatch({
        setProgress(value = 0.02, message = "Loading TCGA packages...")
        load_tcga_packages()
        setProgress(value = 0.05, message = "Loading DEG analysis packages...")
        load_deg_packages()
      }, error = function(e) {
        showNotification(paste("Failed to load packages:", e$message), type = "error", duration = 10)
        return()
      })
      
      setProgress(value = 0.08, message = "Starting TCGA analysis...")
      
      tryCatch({
        # File path
        local_file <- file.path("/srv/shinydata", paste0(input$project_id, ".RDS"))
        
        if (!file.exists(local_file)) {
          showNotification(paste("Data file for", input$project_id, "not found."), type = "error", duration = 10)
          return()
        }
        
        setProgress(value = 0.1, message = "Loading TCGA data")
        data <- readRDS(file = local_file)
        
        if (is.null(data)) {
          showNotification("Failed to load data.", type = "error")
          return()
        }
        
        # Extract metadata
        setProgress(value = 0.2, message = "Extracting sample information")
        vital_status <- table(data@colData$vital_status)
        definition <- table(data@colData$definition)
        tissue_or_organ <- table(data@colData$tissue_or_organ_of_origin)
        
        # Extract counts
        setProgress(value = 0.25, message = "Extracting expression matrix")
        counts <- SummarizedExperiment::assay(data)
        coldata <- as.data.frame(SummarizedExperiment::colData(data))

        # One sample per patient and sample type (barcode characters 1-15). TCGA re-sequenced
        # some tumours (e.g. 89 GBM samples on a second plate); keeping both copies would count
        # one patient twice. The first barcode in sort order is kept.
        bc <- colnames(counts)
        o <- order(bc)
        keep_samples <- (!duplicated(substr(bc[o], 1, 15)))[order(o)]
        n_duplicates <- sum(!keep_samples)
        counts <- counts[, keep_samples, drop = FALSE]
        coldata <- coldata[keep_samples, , drop = FALSE]
        vital_status <- table(coldata$vital_status)
        definition <- table(coldata$definition)
        tissue_or_organ <- table(coldata$tissue_or_organ_of_origin)
        if (n_duplicates > 0) cat("Removed", n_duplicates, "re-sequenced duplicate samples\n")

        cat("Data loaded:", nrow(counts), "genes x", ncol(counts), "samples\n")
        
        # Pre-filter genes with zero expression across all samples for speed
        setProgress(value = 0.22, message = "Pre-filtering zero-expression genes")
        gene_sums <- rowSums(counts)
        counts <- counts[gene_sums > 0, ]
        cat("After pre-filter:", nrow(counts), "genes remaining\n")
        
        # Clean group names
        coldata$group <- gsub(" ", "_", coldata$definition)
        coldata$group <- gsub("[^[:alnum:]_.]", "_", coldata$group)
        coldata$group <- factor(coldata$group)
        
        # Set reference level
        if ("Solid_Tissue_Normal" %in% levels(coldata$group)) {
          coldata$group <- relevel(coldata$group, ref = "Solid_Tissue_Normal")
        } else if (any(grepl("Normal", levels(coldata$group)))) {
          normal_level <- levels(coldata$group)[grepl("Normal", levels(coldata$group))][1]
          coldata$group <- relevel(coldata$group, ref = normal_level)
        }
        
        # Validate groups
        group_counts <- table(coldata$group)
        if (length(group_counts) < 2) {
          showNotification(paste(input$project_id, "has only one sample type, so there is nothing to compare."), type = "error", duration = 10)
          shinyjs::enable("submit")
          shinyjs::html("submit", "<i class='fa fa-play'></i> Run Analysis")
          return()
        }

        # Comparison under test: primary tumour vs the reference (normal) group. Cohorts can
        # contain extra sample types (metastatic, recurrent, ...), so name the test level
        # explicitly instead of relying on factor/coefficient order.
        ref_level <- levels(coldata$group)[1]
        other_levels <- setdiff(levels(coldata$group), ref_level)
        primary_levels <- other_levels[grepl("^Primary", other_levels)]
        test_level <- if (length(primary_levels) > 0) primary_levels[1] else
          names(sort(group_counts[other_levels], decreasing = TRUE))[1]
        test_coef <- paste0("group", test_level)

        reset_submit <- function() {
          shinyjs::enable("submit")
          shinyjs::html("submit", "<i class='fa fa-play'></i> Run Analysis")
        }
        if (min(group_counts[[ref_level]], group_counts[[test_level]]) < 3) {
          showNotification(sprintf("%s: cannot compare %s (n = %d) with %s (n = %d). Each group needs at least 3 samples%s.",
                                   input$project_id, gsub("_", " ", test_level), group_counts[[test_level]],
                                   gsub("_", " ", ref_level), group_counts[[ref_level]],
                                   if (grepl("Normal", ref_level)) "; this cohort has too few normal tissue samples for a tumour-vs-normal test" else ""),
                           type = "error", duration = 20)
          reset_submit()
          return()
        }
        if (!grepl("Normal", ref_level)) {
          showNotification(sprintf("%s has no normal tissue samples, so this analysis compares %s (n = %d) with %s (n = %d).",
                                   input$project_id, gsub("_", " ", test_level), group_counts[[test_level]],
                                   gsub("_", " ", ref_level), group_counts[[ref_level]]),
                           type = "warning", duration = 20)
        }

        # Gene info
        gene_info <- as.data.frame(SummarizedExperiment::rowData(data))
        
        # Initialize
        res <- NULL
        keep <- NULL
        total_genes_before <- nrow(counts)
        normalized_counts <- NULL
        
        # ============ LIMMA ============
        if (input$analysis_method == "limma") {
          
          setProgress(value = 0.3, message = "Building design matrix")
          design <- model.matrix(~group, data = coldata)
          
          setProgress(value = 0.35, message = "Creating DGEList")
          dge <- edgeR::DGEList(counts = counts)
          
          setProgress(value = 0.4, message = "Filtering low-expression genes")
          keep <- edgeR::filterByExpr(dge, design)
          dge <- dge[keep, , keep.lib.sizes = FALSE]
          
          setProgress(value = 0.5, message = paste("Applying", input$normalization_method, "normalization"))
          dge <- edgeR::calcNormFactors(dge, method = input$normalization_method)
          
          setProgress(value = 0.6, message = "Running voom transformation")
          v <- limma::voom(dge, design, plot = FALSE)
          normalized_counts <- v$E
          
          setProgress(value = 0.7, message = "Fitting linear model")
          fit <- limma::lmFit(v, design)
          fit <- limma::eBayes(fit)
          
          setProgress(value = 0.8, message = "Extracting results")
          res <- limma::topTable(fit, coef = which(colnames(design) == test_coef), number = Inf)

          if ("logFC" %in% names(res)) names(res)[names(res) == "logFC"] <- "log2FC"


          # ============ EDGER (OPTIMIZED) ============
        } else if (input$analysis_method == "edgeR") {
          
          setProgress(value = 0.3, message = "Building design matrix")
          design <- model.matrix(~group, data = coldata)
          
          setProgress(value = 0.35, message = "Creating DGEList")
          dge <- edgeR::DGEList(counts = counts)
          
          setProgress(value = 0.4, message = "Filtering low-expression genes")
          keep <- edgeR::filterByExpr(dge, design)
          dge <- dge[keep, , keep.lib.sizes = FALSE]
          
          setProgress(value = 0.5, message = paste("Applying", input$normalization_method, "normalization"))
          dge <- edgeR::calcNormFactors(dge, method = input$normalization_method)
          
          # Store normalized counts before analysis
          normalized_counts <- edgeR::cpm(dge, log = TRUE)
          
          setProgress(value = 0.6, message = "Estimating dispersions (this may take a moment)")
          # Use robust estimation for faster convergence
          dge <- edgeR::estimateDisp(dge, design, robust = TRUE)
          
          setProgress(value = 0.75, message = "Fitting GLM model")
          fit <- edgeR::glmQLFit(dge, design, robust = TRUE)
          
          setProgress(value = 0.85, message = "Testing differential expression")
          qlf <- edgeR::glmQLFTest(fit, coef = which(colnames(design) == test_coef))
          
          res <- as.data.frame(edgeR::topTags(qlf, n = Inf))
          
          if ("logFC" %in% names(res)) names(res)[names(res) == "logFC"] <- "log2FC"
          if ("FDR" %in% names(res)) names(res)[names(res) == "FDR"] <- "adj.P.Val"
          if ("PValue" %in% names(res)) names(res)[names(res) == "PValue"] <- "P.Value"
          

          # ============ DESEQ2 (OPTIMIZED) ============
        } else if (input$analysis_method == "DESeq2") {
          
          setProgress(value = 0.3, message = "Preparing DESeq2 data")
          
          # Pre-filter more aggressively for speed
          keep_genes <- rowSums(counts >= 10) >= ceiling(ncol(counts) * 0.1)
          keep <- keep_genes
          counts_filtered <- counts[keep_genes, ]
          
          counts_int <- round(counts_filtered)
          mode(counts_int) <- "integer"
          rownames(coldata) <- colnames(counts_int)
          
          setProgress(value = 0.35, message = "Creating DESeqDataSet")
          dds <- DESeq2::DESeqDataSetFromMatrix(
            countData = counts_int,
            colData = coldata,
            design = ~ group
          )
          
          setProgress(value = 0.5, message = "Running DESeq2 analysis (optimized)")
          # Use parallel processing and skip some optional steps
          dds <- DESeq2::DESeq(dds, 
                               quiet = TRUE,
                               parallel = TRUE,
                               BPPARAM = BiocParallel::MulticoreParam(4))
          
          normalized_counts <- log2(DESeq2::counts(dds, normalized = TRUE) + 1)
          
          setProgress(value = 0.8, message = "Extracting results")
          res <- as.data.frame(DESeq2::results(dds, contrast = c("group", test_level, ref_level)))
          res <- res[!is.na(res$padj), ]
          
          if ("log2FoldChange" %in% names(res)) names(res)[names(res) == "log2FoldChange"] <- "log2FC"
          if ("padj" %in% names(res)) names(res)[names(res) == "padj"] <- "adj.P.Val"
          if ("pvalue" %in% names(res)) names(res)[names(res) == "pvalue"] <- "P.Value"
          if ("baseMean" %in% names(res)) names(res)[names(res) == "baseMean"] <- "AveExpr"
          
}
        
        # ============ POST-PROCESSING ============
        setProgress(value = 0.9, message = "Adding gene annotations")
        
        res$ensembl_id <- gsub("\\..*", "", rownames(res))
        res$gene_name <- gene_info$gene_name[match(rownames(res), rownames(data))]
        res$gene_type <- gene_info$gene_type[match(rownames(res), rownames(data))]
        res$direction <- ifelse(res$log2FC > 0, "upregulated", "downregulated")
        
        res <- res[order(res$adj.P.Val), ]

        # MA plot data for the contrast actually tested (kept per session)
        tcga_rv$ma <- list(
          A = switch(input$analysis_method, edgeR = res$logCPM, DESeq2 = log10(res$AveExpr + 1), res$AveExpr),
          M = res$log2FC, sig = res$adj.P.Val < 0.05,
          xlab = switch(input$analysis_method, edgeR = "Average log2 CPM", DESeq2 = "log10 mean normalised count",
                        "Average log2 expression (voom)"),
          title = sprintf("MA plot (%s)\n%s vs %s", input$analysis_method, gsub("_", " ", test_level), gsub("_", " ", ref_level)))

        # Count DEGs
        sig_up <- sum(res$log2FC >= input$log2fc_threshold & 
                        res$adj.P.Val <= input$adj_pval_threshold_tcga, na.rm = TRUE)
        sig_down <- sum(res$log2FC <= -input$log2fc_threshold & 
                          res$adj.P.Val <= input$adj_pval_threshold_tcga, na.rm = TRUE)
        
        setProgress(value = 0.95, message = "Storing results")
        
        # ============ STORE IN REACTIVE VALUES ============
        tcga_rv$results <- list(
          deg_results = res,
          vital_status = vital_status,
          definition = definition,
          tissue_or_organ = tissue_or_organ,
          analysis_info = list(
            project = input$project_id,
            total_genes = total_genes_before,
            filtered_genes = sum(keep),
            samples_per_group = group_counts,
            total_samples = ncol(counts),
            duplicates_removed = n_duplicates,
normalization = input$normalization_method,
            method = input$analysis_method,
            reference_group = levels(coldata$group)[1],
            test_group = test_level,
            fc_threshold = input$log2fc_threshold,
            pval_threshold = input$adj_pval_threshold_tcga,
            sig_up = sig_up,
            sig_down = sig_down
          )
        )
        
        tcga_rv$deg_data <- res
        tcga_rv$counts_normalized <- normalized_counts
        tcga_rv$coldata <- coldata
        
        # THIS IS THE KEY LINE - set analysis_complete to TRUE
        tcga_rv$analysis_complete <- TRUE
        # Show results panels, hide welcome panels
        shinyjs::hide("tcga_welcome_panel")
        shinyjs::show("tcga_results_panel")
        shinyjs::hide("tcga_deg_welcome")
        shinyjs::show("tcga_deg_results_div")
        shinyjs::hide("tcga_viz_welcome")
        shinyjs::show("tcga_viz_results_div")
        
        setProgress(value = 1, message = "Complete!")
        
        # Re-enable button with original text
        shinyjs::enable("submit")
        shinyjs::html("submit", "<i class='fa fa-play'></i> Run Analysis")
        
        showNotification(
          paste0("Analysis complete! Found ", sig_up, " upregulated and ", sig_down, " downregulated genes.",
                 if (n_duplicates > 0) paste0(" (", n_duplicates, " re-sequenced duplicate samples were counted once.)") else ""),
          type = "message", duration = 8
        )
        
      }, error = function(e) {
        showNotification(paste("Error:", e$message), type = "error", duration = 15)
        cat("ERROR:", e$message, "\n")
        tcga_rv$analysis_complete <- FALSE
        
        # Re-enable button on error
        shinyjs::enable("submit")
        shinyjs::html("submit", "<i class='fa fa-play'></i> Run Analysis")
      })
      
    }) # end withProgress
    
  }) # end observeEvent
  
  # Re-enable submit button when user changes any analysis parameter
