  # Volcano plot generation function
  generate_tcga_volcano <- function() {
    output$volcano_plot_tcga <- renderPlotly({
      req(tcga_rv$deg_data)
      
      data <- tcga_rv$deg_data
      fc_thresh <- input$tcga_volcano_fc %||% 2
      pval_thresh <- input$tcga_volcano_pval %||% 0.05
      
      # Add significance categories
      data$significance <- dplyr::case_when(
        data$log2FC >= fc_thresh & data$adj.P.Val <= pval_thresh ~ "Upregulated",
        data$log2FC <= -fc_thresh & data$adj.P.Val <= pval_thresh ~ "Downregulated",
        TRUE ~ "Not Significant"
      )
      
      # Count genes in each category
      n_up <- sum(data$significance == "Upregulated", na.rm = TRUE)
      n_down <- sum(data$significance == "Downregulated", na.rm = TRUE)
      n_ns <- sum(data$significance == "Not Significant", na.rm = TRUE)
      
      colors <- c("Upregulated" = "#E53935", "Downregulated" = "#1E88E5", "Not Significant" = "#BDBDBD")
      
      # Calculate axis limits
      max_fc <- max(abs(data$log2FC), na.rm = TRUE) * 1.1
      max_pval <- max(-log10(data$adj.P.Val[data$adj.P.Val > 0]), na.rm = TRUE) * 1.1
      
      # Create clean interactive volcano plot (no labels for better performance)
      plot_ly(data, x = ~log2FC, y = ~-log10(adj.P.Val),
              type = "scatter", mode = "markers",
              color = ~significance, colors = colors,
              marker = list(size = 6, opacity = 0.7),
              text = ~paste("Gene:", gene_name,
                            "<br>log2FC:", round(log2FC, 3),
                            "<br>adj.P.Val:", signif(adj.P.Val, 3),
                            "<br>Status:", significance),
              hoverinfo = "text") %>%
        layout(
          title = list(
            text = paste0("<b>Volcano Plot - ", tcga_rv$results$analysis_info$project, "</b>",
                          "<br><sup>Up: ", n_up, " | Down: ", n_down, " | NS: ", n_ns, "</sup>"),
            font = list(size = 14)
          ),
          xaxis = list(
            title = "log<sub>2</sub> Fold Change",
            range = c(-max_fc, max_fc),
            zeroline = TRUE,
            zerolinecolor = "#999",
            gridcolor = "#f0f0f0"
          ),
          yaxis = list(
            title = "-log<sub>10</sub>(Adjusted P-value)",
            range = c(0, max_pval),
            gridcolor = "#f0f0f0"
          ),
          shapes = list(
            # Vertical threshold lines
            list(type = "line", x0 = fc_thresh, x1 = fc_thresh, y0 = 0, y1 = max_pval,
                 line = list(color = "rgba(100,100,100,0.5)", dash = "dash", width = 1)),
            list(type = "line", x0 = -fc_thresh, x1 = -fc_thresh, y0 = 0, y1 = max_pval,
                 line = list(color = "rgba(100,100,100,0.5)", dash = "dash", width = 1)),
            # Horizontal threshold line
            list(type = "line", x0 = -max_fc, x1 = max_fc, y0 = -log10(pval_thresh), y1 = -log10(pval_thresh),
                 line = list(color = "rgba(100,100,100,0.5)", dash = "dash", width = 1))
          ),
          legend = list(
            orientation = "h",
            y = -0.15,
            x = 0.5,
            xanchor = "center"
          ),
          plot_bgcolor = "white",
          paper_bgcolor = "white"
        )
    })
  }
  
  # High-quality volcano plot download with ggrepel labels
  output$download_volcano_tcga_png <- downloadHandler(
    filename = function() {
      paste0("TCGA_", input$project_id, "_volcano_", Sys.Date(), ".png")
    },
    content = function(file) {
      req(tcga_rv$deg_data)
      
      # Load required packages
      if (!requireNamespace("ggrepel", quietly = TRUE)) {
        showNotification("Installing ggrepel for better labels...", type = "message")
        install.packages("ggrepel", quiet = TRUE)
      }
      library(ggrepel)
      
      data <- tcga_rv$deg_data
      fc_thresh <- input$tcga_volcano_fc %||% 2
      pval_thresh <- input$tcga_volcano_pval %||% 0.05
      n_labels <- input$tcga_volcano_label_n %||% 20
      
      # Add significance categories
      data$significance <- dplyr::case_when(
        data$log2FC >= fc_thresh & data$adj.P.Val <= pval_thresh ~ "Upregulated",
        data$log2FC <= -fc_thresh & data$adj.P.Val <= pval_thresh ~ "Downregulated",
        TRUE ~ "Not Significant"
      )
      
      # Add -log10 p-value
      data$neg_log10_pval <- -log10(data$adj.P.Val)
      
      # Handle infinite values
      # max_pval_display <- max(data$neg_log10_pval[is.finite(data$neg_log10_pval)], na.rm = TRUE) * 1.1
      # Handle infinite values - cap at a reasonable max, not all at same level
      max_pval_display <- max(data$neg_log10_pval[is.finite(data$neg_log10_pval)], na.rm = TRUE)
      # Add small jitter to prevent genes from aligning on same horizontal line
      infinite_mask <- !is.finite(data$neg_log10_pval)
      if (any(infinite_mask)) {
        n_infinite <- sum(infinite_mask)
        # Spread infinite values slightly above max
        data$neg_log10_pval[infinite_mask] <- max_pval_display + 1
      }
      
      data$neg_log10_pval[!is.finite(data$neg_log10_pval)] <- max_pval_display
      
      # Get top genes to label (by significance and fold change)
      top_genes <- data %>%
        dplyr::filter(significance != "Not Significant") %>%
        dplyr::arrange(adj.P.Val, desc(abs(log2FC))) %>%
        head(n_labels)
      
      # Count genes
      n_up <- sum(data$significance == "Upregulated", na.rm = TRUE)
      n_down <- sum(data$significance == "Downregulated", na.rm = TRUE)
      
      # Create ggplot
      p <- ggplot(data, aes(x = log2FC, y = neg_log10_pval)) +
        # Points
        geom_point(aes(color = significance), alpha = 0.6, size = 1.5) +
        # Color scale
        scale_color_manual(
          values = c("Upregulated" = "#E53935", "Downregulated" = "#1E88E5", "Not Significant" = "#BDBDBD"),
          name = "Status"
        ) +
        # Threshold lines
        geom_vline(xintercept = c(-fc_thresh, fc_thresh), linetype = "dashed", color = "grey50", linewidth = 0.5) +
        geom_hline(yintercept = -log10(pval_thresh), linetype = "dashed", color = "grey50", linewidth = 0.5) +
        # Labels with ggrepel
        geom_text_repel(
          data = top_genes,
          aes(label = gene_name),
          size = 2.8,
          max.overlaps = 30,
          box.padding = 0.35,
          point.padding = 0.3,
          segment.color = "grey50",
          segment.size = 0.3,
          min.segment.length = 0.1,
          force = 2,
          force_pull = 0.5
        ) +
        # Labels and title
        labs(
          title = paste0("Volcano Plot - ", tcga_rv$results$analysis_info$project),
          subtitle = paste0("Upregulated: ", n_up, " | Downregulated: ", n_down, 
                            " (|log2FC| ≥ ", fc_thresh, ", adj.P ≤ ", pval_thresh, ")"),
          x = expression(log[2]~"Fold Change"),
          y = expression(-log[10]~"(Adjusted P-value)")
        ) +
        # Theme
        theme_bw(base_size = 12) +
        theme(
          plot.title = element_text(face = "bold", size = 14, hjust = 0.5),
          plot.subtitle = element_text(size = 10, hjust = 0.5, color = "grey40"),
          legend.position = "bottom",
          legend.title = element_text(face = "bold"),
          panel.grid.minor = element_blank(),
          panel.grid.major = element_line(color = "grey90", linewidth = 0.3)
        )
      
      # Save high-resolution PNG
      ggsave(file, plot = p, width = 10, height = 8, dpi = 300, bg = "white")
    }
  )
  
