  # Heatmap generation function
  generate_tcga_heatmap <- function() {
    
    output$heatmap_plot_tcga <- renderPlot({
      req(tcga_rv$deg_data, tcga_rv$counts_normalized, tcga_rv$coldata)
      
      load_visualization_packages()
      
      tryCatch({
        deg_data <- tcga_rv$deg_data
        counts <- tcga_rv$counts_normalized
        coldata <- tcga_rv$coldata
        info <- tcga_rv$results$analysis_info
        
        n_genes <- input$tcga_heatmap_ngenes %||% 50
        selection_method <- input$tcga_heatmap_gene_selection %||% "pvalue"
        
        # Select genes based on method
        if (selection_method == "pvalue") {
          selected_genes <- deg_data %>%
            dplyr::filter(!is.na(adj.P.Val)) %>%
            dplyr::arrange(adj.P.Val) %>%
            head(n_genes) %>%
            rownames()
        } else if (selection_method == "foldchange") {
          selected_genes <- deg_data %>%
            dplyr::filter(!is.na(log2FC)) %>%
            dplyr::arrange(desc(abs(log2FC))) %>%
            head(n_genes) %>%
            rownames()
        } else {
          # Significant DEGs only
          selected_genes <- deg_data %>%
            dplyr::filter(abs(log2FC) >= info$fc_threshold, adj.P.Val <= info$pval_threshold) %>%
            dplyr::arrange(adj.P.Val) %>%
            head(n_genes) %>%
            rownames()
        }
        
        # Filter counts matrix
        selected_genes <- intersect(selected_genes, rownames(counts))
        
        if (length(selected_genes) < 2) {
          plot(1, type = "n", main = "Not enough genes selected for heatmap", xlab = "", ylab = "")
          text(1, 1, "Try adjusting thresholds or increasing gene count", cex = 1.1)
          return()
        }
        
        heatmap_data <- counts[selected_genes, , drop = FALSE]
        
        # Z-score normalization by row (genes)
        if (isTRUE(input$tcga_heatmap_scale_rows %||% TRUE)) {
          heatmap_data <- t(scale(t(heatmap_data)))
        }
        
        # Handle infinite/NA values
        heatmap_data[is.infinite(heatmap_data)] <- NA
        heatmap_data[is.na(heatmap_data)] <- 0
        
        # Clip extreme values for better visualization
        heatmap_data[heatmap_data > 3] <- 3
        heatmap_data[heatmap_data < -3] <- -3
        
        # Annotation
        annotation_col <- data.frame(
          Group = coldata$group,
          row.names = rownames(coldata)
        )
        
        # Colors
        color_choice <- input$tcga_heatmap_colors %||% "RdBu"
        color_palette <- switch(color_choice,
                                "RdBu" = colorRampPalette(rev(RColorBrewer::brewer.pal(11, "RdBu")))(100),
                                "PRGn" = colorRampPalette(rev(RColorBrewer::brewer.pal(11, "PRGn")))(100),
                                "viridis" = viridis::viridis(100),
                                colorRampPalette(c("#2166AC", "white", "#B2182B"))(100))
        
        # Annotation colors
        n_groups <- length(unique(coldata$group))
        group_colors <- RColorBrewer::brewer.pal(min(n_groups, 8), "Set2")[1:n_groups]
        names(group_colors) <- unique(coldata$group)
        annotation_colors <- list(Group = group_colors)
        
        # Gene names for row labels
        row_labels <- deg_data$gene_name[match(rownames(heatmap_data), rownames(deg_data))]
        row_labels[is.na(row_labels)] <- rownames(heatmap_data)[is.na(row_labels)]
        rownames(heatmap_data) <- make.unique(row_labels)
        
        # Generate heatmap - WIDER
        pheatmap::pheatmap(
          heatmap_data,
          color = color_palette,
          cluster_rows = isTRUE(input$tcga_heatmap_row_cluster %||% TRUE),
          cluster_cols = isTRUE(input$tcga_heatmap_col_cluster %||% TRUE),
          clustering_method = input$tcga_heatmap_clustering %||% "ward.D2",
          clustering_distance_rows = "euclidean",
          clustering_distance_cols = "euclidean",
          annotation_col = annotation_col,
          annotation_colors = annotation_colors,
          show_colnames = FALSE,
          show_rownames = isTRUE(input$tcga_heatmap_show_rownames %||% TRUE) && n_genes <= 60,
          fontsize_row = if (n_genes <= 30) 9 else if (n_genes <= 50) 7 else 6,
          fontsize = 10,
          fontsize_col = 8,
          main = paste0("Top ", length(selected_genes), " DEGs - ", info$project, 
                        if(isTRUE(input$tcga_heatmap_scale_rows %||% TRUE)) " (Z-score normalized)" else ""),
          border_color = NA,
          cellwidth = NA,
          cellheight = if (n_genes <= 30) 12 else if (n_genes <= 50) 10 else 8,
          treeheight_row = 50,
          treeheight_col = 50
        )
        
      }, error = function(e) {
        plot(1, type = "n", main = "Error generating heatmap", xlab = "", ylab = "")
        text(1, 1, paste("Error:", e$message), cex = 0.9)
      })
      
    }, height = function() {
      n_genes <- input$tcga_heatmap_ngenes %||% 50
      # Calculate height based on number of genes
      base_height <- 200  # Space for title, legend, dendrograms
      gene_height <- if (n_genes <= 30) 14 else if (n_genes <= 50) 12 else 10
      min(1200, max(600, base_height + (n_genes * gene_height)))
    }, width = 1100, res = 100)
  }
  
  
