  # -----------------------------------------------------------------------------
  # DATA VISUALIZATION TAB - VOLCANO PLOT
  # -----------------------------------------------------------------------------
  
  observeEvent(input$generate_volcano_tcga, {
    req(tcga_rv$deg_data)
    
    output$volcano_plot_tcga <- renderPlotly({
      
      data <- tcga_rv$deg_data
      fc_thresh <- input$tcga_volcano_fc
      pval_thresh <- input$tcga_volcano_pval
      
      # Add significance categories
      data$significance <- case_when(
        data$log2FC >= fc_thresh & data$adj.P.Val <= pval_thresh ~ "Upregulated",
        data$log2FC <= -fc_thresh & data$adj.P.Val <= pval_thresh ~ "Downregulated",
        TRUE ~ "Not Significant"
      )
      
      # Color mapping
      colors <- c("Upregulated" = "#E53935", "Downregulated" = "#1E88E5", "Not Significant" = "#BDBDBD")
      
      # Create plot
      p <- plot_ly(data, x = ~log2FC, y = ~-log10(adj.P.Val),
                   type = "scatter", mode = "markers",
                   color = ~significance, colors = colors,
                   marker = list(size = 6, opacity = 0.7),
                   text = ~paste("Gene:", gene_name,
                                 "<br>log2FC:", round(log2FC, 3),
                                 "<br>adj.P.Val:", signif(adj.P.Val, 3)),
                   hoverinfo = "text") %>%
        layout(
          title = list(text = paste0("Volcano Plot - ", input$project_id), font = list(size = 16)),
          xaxis = list(title = "log2 Fold Change", zeroline = TRUE, zerolinecolor = "#999"),
          yaxis = list(title = "-log10(Adjusted P-value)"),
          shapes = list(
            list(type = "line", x0 = fc_thresh, x1 = fc_thresh, y0 = 0, y1 = max(-log10(data$adj.P.Val), na.rm = TRUE),
                 line = list(color = "grey", dash = "dash")),
            list(type = "line", x0 = -fc_thresh, x1 = -fc_thresh, y0 = 0, y1 = max(-log10(data$adj.P.Val), na.rm = TRUE),
                 line = list(color = "grey", dash = "dash")),
            list(type = "line", x0 = min(data$log2FC, na.rm = TRUE), x1 = max(data$log2FC, na.rm = TRUE),
                 y0 = -log10(pval_thresh), y1 = -log10(pval_thresh),
                 line = list(color = "grey", dash = "dash"))
          ),
          legend = list(orientation = "h", y = -0.15)
        )
      
      # Add labels for top genes
      if (input$tcga_volcano_label != "none") {
        n_labels <- as.numeric(input$tcga_volcano_label)
        
        top_genes <- data %>%
          dplyr::filter(significance != "Not Significant") %>%
          dplyr::arrange(adj.P.Val) %>%
          head(n_labels)
        
        if (nrow(top_genes) > 0) {
          p <- p %>% add_annotations(
            x = top_genes$log2FC,
            y = -log10(top_genes$adj.P.Val),
            text = top_genes$gene_name,
            showarrow = TRUE,
            arrowhead = 2,
            arrowsize = 0.5,
            font = list(size = 9)
          )
        }
      }
      
      p
    })
    
    showNotification("Volcano plot generated!", type = "message", duration = 3)
  })
  
