          dplyr::filter(abs(log2FC) >= info$fc_threshold, adj.P.Val <= info$pval_threshold) %>%
          dplyr::arrange(adj.P.Val) %>%
          head(n_genes) %>%
          rownames()
      }
      
      selected_genes <- intersect(selected_genes, rownames(counts))
      heatmap_data <- counts[selected_genes, , drop = FALSE]
      
      if (isTRUE(input$tcga_heatmap_scale_rows %||% TRUE)) {
        heatmap_data <- t(scale(t(heatmap_data)))
      }
      
      heatmap_data[is.infinite(heatmap_data)] <- NA
      heatmap_data[is.na(heatmap_data)] <- 0
      heatmap_data[heatmap_data > 3] <- 3
      heatmap_data[heatmap_data < -3] <- -3
      
      annotation_col <- data.frame(Group = coldata$group, row.names = rownames(coldata))
      
      color_choice <- input$tcga_heatmap_colors %||% "RdBu"
      color_palette <- switch(color_choice,
                              "RdBu" = colorRampPalette(rev(RColorBrewer::brewer.pal(11, "RdBu")))(100),
                              "PRGn" = colorRampPalette(rev(RColorBrewer::brewer.pal(11, "PRGn")))(100),
                              "viridis" = viridis::viridis(100),
                              colorRampPalette(c("#2166AC", "white", "#B2182B"))(100))
      
      row_labels <- deg_data$gene_name[match(rownames(heatmap_data), rownames(deg_data))]
      row_labels[is.na(row_labels)] <- rownames(heatmap_data)[is.na(row_labels)]
      rownames(heatmap_data) <- make.unique(row_labels)
      
      pheatmap::pheatmap(
        heatmap_data,
        color = color_palette,
        cluster_rows = isTRUE(input$tcga_heatmap_row_cluster %||% TRUE),
        cluster_cols = isTRUE(input$tcga_heatmap_col_cluster %||% TRUE),
        clustering_method = input$tcga_heatmap_clustering %||% "ward.D2",
        annotation_col = annotation_col,
        show_colnames = FALSE,
        show_rownames = isTRUE(input$tcga_heatmap_show_rownames %||% TRUE),
        fontsize_row = 8,
        main = paste0("Top ", length(selected_genes), " DEGs - ", info$project),
        border_color = NA
      )
      
      dev.off()
    }
  )
  
  # -----------------------------------------------------------------------------
  # DATA VISUALIZATION TAB - PCA PLOT
  # -----------------------------------------------------------------------------
  
  output$pca_plot_tcga <- renderPlotly({
    req(tcga_rv$counts_normalized, tcga_rv$coldata, tcga_rv$analysis_complete)
    
    tryCatch({
      counts <- tcga_rv$counts_normalized
      coldata <- tcga_rv$coldata
      
      # Remove genes with zero variance
      var_genes <- apply(counts, 1, var, na.rm = TRUE)
      counts_filtered <- counts[var_genes > 0 & !is.na(var_genes), ]
      
      # Use top variable genes for PCA
      top_var <- head(order(var_genes, decreasing = TRUE), 1000)
      counts_pca <- counts[top_var, ]
      
      # Run PCA
      pca_result <- prcomp(t(counts_pca), scale. = TRUE, center = TRUE)
      
      # Get variance explained
      var_explained <- round(100 * pca_result$sdev^2 / sum(pca_result$sdev^2), 1)
      
      # Create plot data - use defaults if inputs not yet available
      pc_x <- if (!is.null(input$tcga_pca_pc_x)) as.numeric(input$tcga_pca_pc_x) else 1
      pc_y <- if (!is.null(input$tcga_pca_pc_y)) as.numeric(input$tcga_pca_pc_y) else 2
      color_var <- if (!is.null(input$tcga_pca_color)) input$tcga_pca_color else "group"
      
      plot_data <- data.frame(
        PC_X = pca_result$x[, pc_x],
        PC_Y = pca_result$x[, pc_y],
        Sample = rownames(pca_result$x),
        Group = coldata[rownames(pca_result$x), color_var]
      )
      
      # Create plot
      plot_ly(plot_data, x = ~PC_X, y = ~PC_Y,
              type = "scatter", mode = "markers",
              color = ~Group,
              marker = list(size = 10, opacity = 0.8),
              text = ~paste("Sample:", Sample, "<br>Group:", Group),
              hoverinfo = "text") %>%
        layout(
          title = list(text = paste0("PCA - ", tcga_rv$results$analysis_info$project),
                       font = list(size = 14)),
          xaxis = list(title = paste0("PC", pc_x, " (", var_explained[pc_x], "%)")),
          yaxis = list(title = paste0("PC", pc_y, " (", var_explained[pc_y], "%)"))
        )
      
    }, error = function(e) {
      plotly::plot_ly() %>%
        layout(title = paste("Error generating PCA:", e$message))
    })
  })
  
  
  # Pathway results flag
  output$tcga_pathway_results_ready <- reactive({
    !is.null(tcga_rv$pathway_results) && tcga_rv$pathway_complete
  })
  outputOptions(output, "tcga_pathway_results_ready", suspendWhenHidden = FALSE)
  
  # Run pathway analysis
  observeEvent(input$run_tcga_pathway, {
    req(tcga_rv$deg_data, input$tcga_pathway_dbs)

    # Show progress
    shinyjs::show("tcga_pathway_progress_div")
    tcga_rv$pathway_complete <- FALSE

    withProgress(message = "Running pathway analysis...", value = 0, {

      tryCatch({
        deg_data <- tcga_rv$deg_data
        info <- tcga_rv$results$analysis_info

        # Get significant genes (gene symbols)
        if (input$tcga_pathway_geneset == "up") {
          genes <- deg_data %>%
            dplyr::filter(log2FC >= info$fc_threshold, adj.P.Val <= info$pval_threshold) %>%
            dplyr::pull(gene_name)
        } else if (input$tcga_pathway_geneset == "down") {
          genes <- deg_data %>%
            dplyr::filter(log2FC <= -info$fc_threshold, adj.P.Val <= info$pval_threshold) %>%
            dplyr::pull(gene_name)
        } else {
          genes <- deg_data %>%
            dplyr::filter(abs(log2FC) >= info$fc_threshold, adj.P.Val <= info$pval_threshold) %>%
            dplyr::pull(gene_name)
        }

        # Clean gene list
        genes <- unique(trimws(as.character(genes[!is.na(genes)])))
        genes <- genes[genes != "" & nchar(genes) > 0 & !grepl("^[0-9]+$", genes)]

        if (length(genes) < 5) {
          showNotification("Too few genes for pathway analysis. Adjust thresholds.", type = "warning")
          shinyjs::hide("tcga_pathway_progress_div")
          return()
        }

        # Get background/universe (all tested genes) - critical for proper statistics
        universe_genes <- unique(trimws(as.character(deg_data$gene_name[!is.na(deg_data$gene_name)])))
        universe_genes <- universe_genes[universe_genes != "" & !grepl("^[0-9]+$", universe_genes)]

        setProgress(value = 0.2, message = paste("Analyzing", length(genes), "DEGs against", length(universe_genes), "tested genes"))
        print(paste("TCGA Pathway: Analyzing", length(genes), "DEGs with universe of", length(universe_genes), "genes"))

        # Convert gene symbols to Entrez IDs (needed for KEGG, Reactome, WikiPathways)
        orgdb <- org.Hs.eg.db::org.Hs.eg.db

        entrez_map <- tryCatch({
          AnnotationDbi::mapIds(orgdb, keys = genes, column = "ENTREZID",
                                keytype = "SYMBOL", multiVals = "first")
        }, error = function(e) { setNames(rep(NA, length(genes)), genes) })
        entrez_genes <- as.character(entrez_map[!is.na(entrez_map)])

        # Also convert universe to Entrez
        universe_entrez <- tryCatch({
          u <- AnnotationDbi::mapIds(orgdb, keys = universe_genes, column = "ENTREZID",
                                     keytype = "SYMBOL", multiVals = "first")
          as.character(u[!is.na(u)])
        }, error = function(e) NULL)

        print(paste("Converted", length(entrez_genes), "of", length(genes), "genes to Entrez IDs"))

        dbs <- input$tcga_pathway_dbs
        all_results <- data.frame()
        pval_cutoff <- input$tcga_pathway_pval %||% 0.05
        min_gs <- input$tcga_pathway_mingenes %||% 3

        # --- GO Biological Process ---
        if ("GO_Biological_Process_2023" %in% dbs) {
          setProgress(value = 0.3, message = "GO Biological Process...")
          tryCatch({
            go_res <- clusterProfiler::enrichGO(
              gene = genes, OrgDb = orgdb, keyType = "SYMBOL", ont = "BP",
              universe = universe_genes,
              pvalueCutoff = pval_cutoff, qvalueCutoff = 1,
              pAdjustMethod = "BH", minGSSize = min_gs, maxGSSize = 500
            )
            if (!is.null(go_res) && nrow(as.data.frame(go_res)) > 0) {
              df <- as.data.frame(go_res)
              df$Database <- "GO_Biological_Process"
              df$Term <- paste0(df$Description, " (", df$ID, ")")
              df$Overlap <- paste0(df$Count, "/", gsub(".*/", "", df$GeneRatio))
              df$Adjusted.P.value <- df$p.adjust
              df$Combined.Score <- -log10(df$pvalue) * (df$Count / as.numeric(gsub("/.*", "", df$GeneRatio)))
              df$Genes <- df$geneID
              df$GeneCount <- df$Count
              all_results <- rbind(all_results, df[, c("Term", "Database", "Overlap", "Adjusted.P.value", "Combined.Score", "Genes", "GeneCount")])
              print(paste("GO BP:", nrow(df), "results"))
            }
          }, error = function(e) print(paste("GO BP error:", e$message)))
        }

        # --- GO Molecular Function ---
        if ("GO_Molecular_Function_2023" %in% dbs) {
          setProgress(value = 0.4, message = "GO Molecular Function...")
          tryCatch({
            go_mf <- clusterProfiler::enrichGO(
              gene = genes, OrgDb = orgdb, keyType = "SYMBOL", ont = "MF",
              universe = universe_genes,
              pvalueCutoff = pval_cutoff, qvalueCutoff = 1,
              pAdjustMethod = "BH", minGSSize = min_gs, maxGSSize = 500
            )
            if (!is.null(go_mf) && nrow(as.data.frame(go_mf)) > 0) {
              df <- as.data.frame(go_mf)
              df$Database <- "GO_Molecular_Function"
              df$Term <- paste0(df$Description, " (", df$ID, ")")
              df$Overlap <- paste0(df$Count, "/", gsub(".*/", "", df$GeneRatio))
              df$Adjusted.P.value <- df$p.adjust
              df$Combined.Score <- -log10(df$pvalue) * (df$Count / as.numeric(gsub("/.*", "", df$GeneRatio)))
              df$Genes <- df$geneID
              df$GeneCount <- df$Count
              all_results <- rbind(all_results, df[, c("Term", "Database", "Overlap", "Adjusted.P.value", "Combined.Score", "Genes", "GeneCount")])
              print(paste("GO MF:", nrow(df), "results"))
            }
          }, error = function(e) print(paste("GO MF error:", e$message)))
        }

        # --- GO Cellular Component ---
        if ("GO_Cellular_Component_2023" %in% dbs) {
          setProgress(value = 0.45, message = "GO Cellular Component...")
          tryCatch({
            go_cc <- clusterProfiler::enrichGO(
              gene = genes, OrgDb = orgdb, keyType = "SYMBOL", ont = "CC",
              universe = universe_genes,
              pvalueCutoff = pval_cutoff, qvalueCutoff = 1,
              pAdjustMethod = "BH", minGSSize = min_gs, maxGSSize = 500
            )
            if (!is.null(go_cc) && nrow(as.data.frame(go_cc)) > 0) {
              df <- as.data.frame(go_cc)
              df$Database <- "GO_Cellular_Component"
              df$Term <- paste0(df$Description, " (", df$ID, ")")
              df$Overlap <- paste0(df$Count, "/", gsub(".*/", "", df$GeneRatio))
              df$Adjusted.P.value <- df$p.adjust
              df$Combined.Score <- -log10(df$pvalue) * (df$Count / as.numeric(gsub("/.*", "", df$GeneRatio)))
              df$Genes <- df$geneID
              df$GeneCount <- df$Count
              all_results <- rbind(all_results, df[, c("Term", "Database", "Overlap", "Adjusted.P.value", "Combined.Score", "Genes", "GeneCount")])
              print(paste("GO CC:", nrow(df), "results"))
            }
          }, error = function(e) print(paste("GO CC error:", e$message)))
        }

        # --- KEGG ---
        if ("KEGG_2021_Human" %in% dbs && length(entrez_genes) >= 5) {
          setProgress(value = 0.5, message = "KEGG Pathways...")
          tryCatch({
            kegg_res <- clusterProfiler::enrichKEGG(
              gene = entrez_genes, organism = "hsa",
              universe = universe_entrez,
              pvalueCutoff = pval_cutoff, qvalueCutoff = 1,
              pAdjustMethod = "BH", minGSSize = min_gs, maxGSSize = 500
            )
            if (!is.null(kegg_res) && nrow(as.data.frame(kegg_res)) > 0) {
              df <- as.data.frame(kegg_res)
              df$Database <- "KEGG"
              df$Term <- df$Description
              df$Overlap <- paste0(df$Count, "/", gsub(".*/", "", df$GeneRatio))
              df$Adjusted.P.value <- df$p.adjust
              df$Combined.Score <- -log10(df$pvalue) * (df$Count / as.numeric(gsub("/.*", "", df$GeneRatio)))
              df$Genes <- df$geneID
              df$GeneCount <- df$Count
              all_results <- rbind(all_results, df[, c("Term", "Database", "Overlap", "Adjusted.P.value", "Combined.Score", "Genes", "GeneCount")])
              print(paste("KEGG:", nrow(df), "results"))
            }
          }, error = function(e) print(paste("KEGG error:", e$message)))
        }

        # --- Reactome ---
        if ("Reactome_2022" %in% dbs && length(entrez_genes) >= 5) {
          setProgress(value = 0.6, message = "Reactome Pathways...")
          tryCatch({
            reactome_res <- ReactomePA::enrichPathway(
              gene = entrez_genes, organism = "human",
              universe = universe_entrez,
              pvalueCutoff = pval_cutoff, qvalueCutoff = 1,
              pAdjustMethod = "BH", minGSSize = min_gs, maxGSSize = 500
            )
            if (!is.null(reactome_res) && nrow(as.data.frame(reactome_res)) > 0) {
              df <- as.data.frame(reactome_res)
              df$Database <- "Reactome"
              df$Term <- df$Description
              df$Overlap <- paste0(df$Count, "/", gsub(".*/", "", df$GeneRatio))
              df$Adjusted.P.value <- df$p.adjust
              df$Combined.Score <- -log10(df$pvalue) * (df$Count / as.numeric(gsub("/.*", "", df$GeneRatio)))
              df$Genes <- df$geneID
              df$GeneCount <- df$Count
              all_results <- rbind(all_results, df[, c("Term", "Database", "Overlap", "Adjusted.P.value", "Combined.Score", "Genes", "GeneCount")])
              print(paste("Reactome:", nrow(df), "results"))
            }
          }, error = function(e) print(paste("Reactome error:", e$message)))
        }

        # --- WikiPathways ---
        if ("WikiPathway_2023_Human" %in% dbs && length(entrez_genes) >= 5) {
          setProgress(value = 0.7, message = "WikiPathways...")
          tryCatch({
            wp_res <- clusterProfiler::enrichWP(
              gene = entrez_genes, organism = "Homo sapiens",
              universe = universe_entrez,
              pvalueCutoff = pval_cutoff, qvalueCutoff = 1,
              pAdjustMethod = "BH", minGSSize = min_gs, maxGSSize = 500
            )
            if (!is.null(wp_res) && nrow(as.data.frame(wp_res)) > 0) {
              df <- as.data.frame(wp_res)
              df$Database <- "WikiPathways"
              df$Term <- df$Description
              df$Overlap <- paste0(df$Count, "/", gsub(".*/", "", df$GeneRatio))
              df$Adjusted.P.value <- df$p.adjust
              df$Combined.Score <- -log10(df$pvalue) * (df$Count / as.numeric(gsub("/.*", "", df$GeneRatio)))
              df$Genes <- df$geneID
              df$GeneCount <- df$Count
              all_results <- rbind(all_results, df[, c("Term", "Database", "Overlap", "Adjusted.P.value", "Combined.Score", "Genes", "GeneCount")])
              print(paste("WikiPathways:", nrow(df), "results"))
            }
          }, error = function(e) print(paste("WikiPathways error:", e$message)))
        }

        # --- MSigDB Hallmark ---
        if ("MSigDB_Hallmark_2020" %in% dbs) {
          setProgress(value = 0.8, message = "MSigDB Hallmark...")
          tryCatch({
            # MSigDB via enrichR (no clusterProfiler equivalent for Hallmark)
            if (requireNamespace("enrichR", quietly = TRUE)) {
              options(enrichR.base.address = "https://maayanlab.cloud/Enrichr/")
              options(enrichR.sites.base.address = "https://maayanlab.cloud/")
              options(enrichR.live = TRUE)
              tryCatch(enrichR::setEnrichrSite("Enrichr"), error = function(e) NULL)
              msig <- tx_enrichr_local(genes, "MSigDB_Hallmark_2020", background = universe_genes)
              if (!is.null(msig[["MSigDB_Hallmark_2020"]]) && nrow(msig[["MSigDB_Hallmark_2020"]]) > 0) {
                df <- msig[["MSigDB_Hallmark_2020"]]
                df <- df[df$Adjusted.P.value <= pval_cutoff, ]
                if (nrow(df) > 0) {
                  df$Database <- "MSigDB_Hallmark"
                  df$GeneCount <- sapply(strsplit(as.character(df$Overlap), "/"), function(x) as.numeric(x[1]))
                  all_results <- rbind(all_results, df[, c("Term", "Database", "Overlap", "Adjusted.P.value", "Combined.Score", "Genes", "GeneCount")])
                  print(paste("MSigDB Hallmark:", nrow(df), "results"))
                }
              }
            }
          }, error = function(e) print(paste("MSigDB error:", e$message)))
        }

        # --- BioCarta (enrichR fallback) ---
        if ("BioCarta_2016" %in% dbs) {
          setProgress(value = 0.85, message = "BioCarta...")
          tryCatch({
            if (requireNamespace("enrichR", quietly = TRUE)) {
              options(enrichR.base.address = "https://maayanlab.cloud/Enrichr/")
              options(enrichR.live = TRUE)
              tryCatch(enrichR::setEnrichrSite("Enrichr"), error = function(e) NULL)
              bc <- tx_enrichr_local(genes, "BioCarta_2016", background = universe_genes)
              if (!is.null(bc[["BioCarta_2016"]]) && nrow(bc[["BioCarta_2016"]]) > 0) {
                df <- bc[["BioCarta_2016"]]
                df <- df[df$Adjusted.P.value <= pval_cutoff, ]
                if (nrow(df) > 0) {
                  df$Database <- "BioCarta"
                  df$GeneCount <- sapply(strsplit(as.character(df$Overlap), "/"), function(x) as.numeric(x[1]))
                  all_results <- rbind(all_results, df[, c("Term", "Database", "Overlap", "Adjusted.P.value", "Combined.Score", "Genes", "GeneCount")])
                  print(paste("BioCarta:", nrow(df), "results"))
                }
              }
            }
          }, error = function(e) print(paste("BioCarta error:", e$message)))
        }

        setProgress(value = 0.9, message = "Finalizing results...")

        if (nrow(all_results) == 0) {
          showNotification("No significant pathways found. Try adjusting p-value threshold.", type = "warning")
          shinyjs::hide("tcga_pathway_progress_div")
          tcga_rv$pathway_complete <- FALSE
          return()
        }

        # Sort by adjusted p-value
        all_results <- all_results[order(all_results$Adjusted.P.value), ]

        # Filter by min gene count
        all_results <- all_results %>% dplyr::filter(GeneCount >= min_gs)

        tcga_rv$pathway_results <- all_results
        tcga_rv$pathway_complete <- TRUE

        # Update filter choices
        dbs_with_results <- unique(all_results$Database)
        updateSelectInput(session, "tcga_pathway_filter_db", choices = dbs_with_results, selected = dbs_with_results)
        updateSelectInput(session, "tcga_dotplot_db", choices = c("All" = "all", dbs_with_results))
        updateSelectInput(session, "tcga_barplot_db", choices = c("All" = "all", dbs_with_results))

        setProgress(value = 1, message = "Complete!")
        showNotification(paste0("Found ", nrow(all_results), " enriched pathways across ",
                                length(dbs_with_results), " databases!"), type = "message")

      }, error = function(e) {
        showNotification(paste("Error:", e$message), type = "error")
        tcga_rv$pathway_complete <- FALSE
      })

      shinyjs::hide("tcga_pathway_progress_div")
    })
  })
  
  # Pathway results table
  output$tcga_pathway_table <- DT::renderDataTable({
    req(tcga_rv$pathway_results)
    
    data <- tcga_rv$pathway_results
    
    # Filter by database if selected
    if (!is.null(input$tcga_pathway_filter_db) && length(input$tcga_pathway_filter_db) > 0) {
      data <- data %>% dplyr::filter(Database %in% input$tcga_pathway_filter_db)
    }
    
    # Sort
    sort_col <- input$tcga_pathway_sort
    if (sort_col %in% names(data)) {
      data <- data %>% dplyr::arrange(!!sym(sort_col))
    }
    
    # Select display columns
    display_cols <- c("Term", "Database", "Overlap", "Adjusted.P.value", "Combined.Score", "Genes")
    display_cols <- intersect(display_cols, names(data))
    
    DT::datatable(
      data[, display_cols],
      rownames = FALSE,
      filter = 'top',
      options = list(pageLength = 15, scrollX = TRUE)
    ) %>%
      DT::formatSignif(columns = "Adjusted.P.value", digits = 3) %>%
      DT::formatRound(columns = "Combined.Score", digits = 2)
  })
  
  # Dot plot
  output$tcga_pathway_dotplot <- renderPlotly({
    req(tcga_rv$pathway_results)
    
    data <- tcga_rv$pathway_results
    
    if (input$tcga_dotplot_db != "all") {
      data <- data %>% dplyr::filter(Database == input$tcga_dotplot_db)
    }
    
    if (nrow(data) == 0) {
      return(plotly::plot_ly() %>% layout(title = "No results for selected database"))
    }
    
    # Get top pathways
    top_data <- data %>%
      dplyr::arrange(Adjusted.P.value) %>%
      head(input$tcga_dotplot_ntop) %>%
      dplyr::mutate(Term = forcats::fct_reorder(Term, -Adjusted.P.value))
    
    plot_ly(top_data, x = ~GeneCount, y = ~Term,
            type = "scatter", mode = "markers",
            marker = list(
              size = ~-log10(Adjusted.P.value) * 3,
              color = ~Combined.Score,
              colorscale = "Viridis",
              showscale = TRUE,
              colorbar = list(title = "Combined\nScore")
            ),
            text = ~paste("Term:", Term,
                          "<br>Genes:", GeneCount,
                          "<br>Adj.P:", signif(Adjusted.P.value, 3),
                          "<br>Score:", round(Combined.Score, 2)),
            hoverinfo = "text") %>%
      layout(
        title = "Pathway Enrichment - Dot Plot",
        xaxis = list(title = "Gene Count"),
        yaxis = list(title = "", tickfont = list(size = 10)),
        margin = list(l = 300)
      )
  })
  
  # Bar plot
  output$tcga_pathway_barplot <- renderPlotly({
    req(tcga_rv$pathway_results)
    
    data <- tcga_rv$pathway_results
    
    if (input$tcga_barplot_db != "all") {
