        margin = list(l = 300)
      )
  })
  
  # Helper: build a TCGA pathway network styled identically to the GSEA/ORA unified_gene_pathway_network
  build_tcga_pathway_network <- function(results_df, n_pathways = 15, layout_solver = "forceAtlas2Based") {
    results_df <- results_df %>%
      dplyr::arrange(Adjusted.P.value) %>%
      head(n_pathways)

    if (nrow(results_df) == 0) {
      return(visNetwork::visNetwork(
        nodes = data.frame(id = 1, label = "No pathways to display", shape = "text"),
        edges = data.frame(from = integer(), to = integer())
      ))
    }

    # Split Genes column on both "/" (clusterProfiler) and ";" (enrichR)
    gene_lists <- strsplit(as.character(results_df$Genes), "[/;]")
    gene_lists <- lapply(gene_lists, function(g) {
      g <- trimws(g)
      g[!is.na(g) & g != ""]
    })
    all_genes <- unique(unlist(gene_lists))
    all_genes <- all_genes[!is.na(all_genes) & all_genes != ""]

    if (length(all_genes) == 0) {
      return(visNetwork::visNetwork(
        nodes = data.frame(id = 1, label = "No gene-pathway connections found", shape = "text"),
        edges = data.frame(from = integer(), to = integer())
      ))
    }

    # Database colors — same palette as unified_gene_pathway_network, extended for TCGA databases
    db_colors <- list(
      "GO_Biological_Process" = list(background = "#667eea", border = "#5a6fd6"),
      "GO_Molecular_Function" = list(background = "#9c27b0", border = "#7b1fa2"),
      "GO_Cellular_Component" = list(background = "#00bcd4", border = "#0097a7"),
      "KEGG"                  = list(background = "#4caf50", border = "#388e3c"),
      "Reactome"              = list(background = "#f44336", border = "#d32f2f"),
      "WikiPathways"          = list(background = "#ff9800", border = "#f57c00"),
      "MSigDB_Hallmark"       = list(background = "#795548", border = "#5d4037"),
      "BioCarta"              = list(background = "#607d8b", border = "#455a64")
    )

    # Truncate pathway labels (max 35 chars) — same as unified network
    truncate_label <- function(x, max_chars = 35) {
      if (nchar(x) > max_chars) paste0(substr(x, 1, max_chars - 3), "...") else x
    }

    # Pathway nodes
    pathway_nodes <- data.frame(
      id = paste0("pathway_", seq_len(nrow(results_df))),
      label = sapply(results_df$Term, truncate_label),
      group = results_df$Database,
      title = paste0(
        "<b>", results_df$Term, "</b><br>",
        "<b>Database:</b> ", results_df$Database, "<br>",
        "<b>Adj. P-value:</b> ", signif(results_df$Adjusted.P.value, 3), "<br>",
        "<b>Overlap:</b> ", results_df$Overlap, "<br>",
        "<b>Combined Score:</b> ", round(results_df$Combined.Score, 2)
      ),
      value = pmax(20, pmin(60, results_df$GeneCount * 2)),
      shape = "box",
      stringsAsFactors = FALSE
    )

    # Gene nodes
    gene_nodes <- data.frame(
      id = paste0("gene_", seq_along(all_genes)),
      label = as.character(all_genes),
      group = "gene",
      title = paste0("<b>Gene:</b> ", all_genes),
      value = 12,
      shape = "dot",
      stringsAsFactors = FALSE
    )

    nodes <- rbind(pathway_nodes, gene_nodes)

    # Edges — straight lines
    edges_list <- lapply(seq_len(nrow(results_df)), function(i) {
      genes <- gene_lists[[i]]
      if (length(genes) > 0) {
        gene_indices <- match(genes, all_genes)
        gene_indices <- gene_indices[!is.na(gene_indices)]
        if (length(gene_indices) > 0) {
          data.frame(
            from = rep(paste0("pathway_", i), length(gene_indices)),
            to = paste0("gene_", gene_indices),
            color = "#cccccc",
            width = 1.5,
            stringsAsFactors = FALSE
          )
        } else NULL
      } else NULL
    })
    edges <- do.call(rbind, edges_list[!sapply(edges_list, is.null)])

    if (is.null(edges) || nrow(edges) == 0) {
      return(visNetwork::visNetwork(
        nodes = data.frame(id = 1, label = "No gene-pathway connections found", shape = "text"),
        edges = data.frame(from = integer(), to = integer())
      ))
    }

    network <- visNetwork::visNetwork(nodes, edges, width = "100%", height = "100%")
    for (db_name in names(db_colors)) {
      network <- network %>%
        visNetwork::visGroups(groupname = db_name, color = db_colors[[db_name]],
                              shape = "box", font = list(size = 13, color = "white"))
    }

    network %>%
      visNetwork::visGroups(groupname = "gene",
                            color = list(background = "#FFA726", border = "#F57C00"),
                            shape = "dot", font = list(size = 11)) %>%
      visNetwork::visEdges(smooth = FALSE,
                           color = list(color = "#cccccc", highlight = "#ff5722")) %>%
      visNetwork::visPhysics(
        enabled = TRUE,
        solver = layout_solver,
        forceAtlas2Based = list(
          gravitationalConstant = -80,
          centralGravity = 0.005,
          springLength = 150,
          springConstant = 0.05,
          damping = 0.5,
          avoidOverlap = 0.8
        ),
        stabilization = list(enabled = TRUE, iterations = 300, updateInterval = 25, fit = TRUE)
      ) %>%
      visNetwork::visInteraction(
        dragNodes = TRUE, dragView = TRUE, zoomView = TRUE,
        navigationButtons = TRUE, tooltipDelay = 100, hover = TRUE, keyboard = TRUE
      ) %>%
      visNetwork::visOptions(
        highlightNearest = list(enabled = TRUE, degree = 1, hover = TRUE),
        selectedBy = list(variable = "group", multiple = TRUE)
      ) %>%
      visNetwork::visLegend(useGroups = TRUE, position = "right", width = 0.12) %>%
      visNetwork::visEvents(stabilizationIterationsDone = "function() {
        this.setOptions({ physics: { enabled: false } });
      }")
  }

  # TCGA pathway network — identical styling to GSEA/ORA unified_gene_pathway_network
  output$tcga_pathway_network <- visNetwork::renderVisNetwork({
    req(tcga_rv$pathway_results)
    load_network_packages()

    tryCatch({
      build_tcga_pathway_network(
        tcga_rv$pathway_results,
        n_pathways = input$tcga_network_npathways %||% 15,
        layout_solver = input$tcga_network_layout %||% "forceAtlas2Based"
      )
    }, error = function(e) {
      print(paste("TCGA network error:", e$message))
      visNetwork::visNetwork(
        nodes = data.frame(id = 1, label = paste("Error:", e$message), shape = "text"),
        edges = data.frame(from = integer(), to = integer())
      )
    })
  })
  
