  # Helper: build the TCGA dot plot from current inputs (used by render and download)
  build_tcga_dotplot <- function(results_df, db_filter, n_top) {
    data <- results_df
    if (!is.null(db_filter) && db_filter != "all") {
      data <- data %>% dplyr::filter(Database == db_filter)
    }
    if (nrow(data) == 0) {
      return(plotly::plot_ly() %>% plotly::layout(title = "No results for selected database"))
    }
    top_data <- data %>%
      dplyr::arrange(Adjusted.P.value) %>%
      head(n_top) %>%
      dplyr::mutate(Term = forcats::fct_reorder(Term, -Adjusted.P.value))
    plotly::plot_ly(top_data, x = ~GeneCount, y = ~Term,
                    type = "scatter", mode = "markers",
                    marker = list(size = ~-log10(Adjusted.P.value) * 3,
                                  color = ~Combined.Score,
                                  colorscale = "Viridis",
                                  showscale = TRUE,
                                  colorbar = list(title = "Combined\nScore")),
                    text = ~paste("Term:", Term,
                                  "<br>Genes:", GeneCount,
                                  "<br>Adj.P:", signif(Adjusted.P.value, 3),
                                  "<br>Score:", round(Combined.Score, 2)),
                    hoverinfo = "text") %>%
      plotly::layout(title = "Pathway Enrichment - Dot Plot",
                     xaxis = list(title = "Gene Count"),
                     yaxis = list(title = "", tickfont = list(size = 10)),
                     margin = list(l = 300))
  }

