    },
    content = function(file) {
      req(tcga_rv$pathway_results)
      p <- build_tcga_barplot(tcga_rv$pathway_results,
                              input$tcga_barplot_db,
                              input$tcga_barplot_ntop %||% 15)
      htmlwidgets::saveWidget(plotly::as_widget(p), file, selfcontained = TRUE)
    }
  )

