  # Helper function to create interactive gene tables
  create_gene_table_tcga_new <- function(data, table_id) {
    # Ensure required columns exist
    data <- as.data.frame(data)
    
    # Create the interactive table
    DT::datatable(
      data,
      selection = 'single',
      options = list(
        pageLength = 15,
        scrollY = "400px",
        scrollX = TRUE,
        scrollCollapse = TRUE,
        dom = 'frtip',
        ordering = TRUE,
        searching = TRUE,
        order = list(list(which(names(data) == "adj.P.Val") - 1, 'asc'))
      ),
      rownames = FALSE,
      filter = 'top',
      escape = FALSE,
      callback = JS(sprintf("
      table.on('click.dt', 'tr', function() {
        var rowIndex = table.row(this).index();
        if (rowIndex !== undefined) {
          Shiny.setInputValue('%s_clicked', rowIndex + 1, {priority: 'event'});
        }
      });
    ", table_id))
    ) %>%
      DT::formatSignif(
        columns = intersect(c("P.Value", "adj.P.Val"), names(data)),
        digits = 3
      ) %>%
      DT::formatRound(
        columns = intersect(c("log2FC", "logCPM", "AveExpr", "B"), names(data)),
        digits = 3
      )
  }
  
  # Modify the showGeneModalTCGA function to use ENSEMBL ID
  showGeneModalTCGA <- function(gene_data) {
    # Early validation - check if gene_data is valid
    if (is.null(gene_data) || nrow(gene_data) == 0) {
      showNotification("No gene data available", type = "error")
      return(NULL)
    }
    
    # Ensure gene_data is a single row data frame, not a tibble that might behave differently
    gene_data <- as.data.frame(gene_data)
    
    # Debug prints
    print("Gene data received:")
    print(str(gene_data))
    print(paste("Gene name:", gene_data$gene_name))
    print(paste("ENSEMBL ID:", gene_data$ensembl_id))
    
    # Safely extract ensembl_id
    ensembl_id <- tryCatch({
      eid <- gene_data$ensembl_id
      if (is.null(eid) || length(eid) == 0) return(NA)
      as.character(eid[1])
    }, error = function(e) NA)
    
    # Ensure we have an ENSEMBL ID
    if (is.na(ensembl_id) || ensembl_id == "") {
      showModal(modalDialog(
        title = "Error",
        "No ENSEMBL ID available for this gene",
        easyClose = TRUE
      ))
      return(NULL)
    }
    
    # Update gene_data with safe ensembl_id
    gene_data$ensembl_id <- ensembl_id
    
    withProgress(message = 'Fetching gene data from OpenTargets...', value = 0.1, {
      # Use existing fetch_opentargets_data function
      print(paste("Querying OpenTargets with ENSEMBL ID:", gene_data$ensembl_id))
      ot_data <- fetch_opentargets_data(gene_data$ensembl_id)
      
      incProgress(0.5, detail = "Processing data...")
      
      if (!is.null(ot_data)) {
        showModal(modalDialog(
          title = tags$div(
            style = "display: flex; align-items: center;",
            icon("dna", style = "color: #00796b; margin-right: 10px; font-size: 1.3em;"),
            paste("Gene Information:", gene_data$gene_name, "(", gene_data$ensembl_id, ")")
          ),
          size = "l",
          
          # Basic Info Section
          h4(icon("info-circle"), " Basic Information", style = "color: #00796b; margin-bottom: 15px;"),
          tags$div(
            style = "background-color: #f8f9fa; padding: 15px; border-radius: 8px; margin-bottom: 20px;",
            fluidRow(
              column(6,
                     tags$table(
                       class = "table table-sm",
                       tags$tbody(
                         tags$tr(tags$td(tags$strong("Gene Name:")), tags$td(gene_data$gene_name)),
                         tags$tr(tags$td(tags$strong("Approved Symbol:")), tags$td(ot_data$approvedSymbol %||% "N/A")),
                         tags$tr(tags$td(tags$strong("Approved Name:")), tags$td(ot_data$approvedName %||% "N/A")),
                         tags$tr(tags$td(tags$strong("Biotype:")), tags$td(ot_data$biotype %||% "N/A"))
                       )
                     )
              ),
              column(6,
                     tags$table(
                       class = "table table-sm",
                       tags$tbody(
                         tags$tr(tags$td(tags$strong("Log2 Fold Change:")), 
                                 tags$td(style = if(!is.null(gene_data$log2FC) && !is.na(gene_data$log2FC) && gene_data$log2FC > 0) "color: #388E3C; font-weight: bold;" else "color: #E53935; font-weight: bold;",
                                         sprintf("%.3f", gene_data$log2FC %||% NA))),
                         tags$tr(tags$td(tags$strong("Adj. P-value:")), tags$td(sprintf("%.2e", gene_data$adj.P.Val %||% NA))),
                         tags$tr(tags$td(tags$strong("Avg Expression:")), tags$td(sprintf("%.3f", gene_data$AveExpr %||% gene_data$logCPM %||% NA))),
                         if ("B" %in% names(gene_data)) tags$tr(tags$td(tags$strong("B-statistic:")), tags$td(sprintf("%.3f", gene_data$B %||% NA)))
                       )
                     )
              )
            )
          ),
          
          # Function Description Section
          if (!is.null(ot_data$functionDescriptions) && length(ot_data$functionDescriptions) > 0) {
            tags$div(
              style = "margin-bottom: 20px;",
              h4(icon("book"), " Function Description", style = "color: #00796b;"),
              tags$div(
                style = "background-color: #e8f5e9; padding: 15px; border-radius: 8px; border-left: 4px solid #4CAF50;",
                tags$p(style = "margin: 0;", ot_data$functionDescriptions[[1]])
              )
            )
          },
          
          # Disease Associations Section
          tags$div(
            style = "margin-bottom: 20px;",
            h4(icon("hospital"), " Disease Associations", style = "color: #00796b;"),
            if (!is.null(ot_data$associatedDiseases) && 
                !is.null(ot_data$associatedDiseases$rows) &&
                nrow(ot_data$associatedDiseases$rows) > 0) {
              
              DT::renderDataTable({
                diseases_df <- ot_data$associatedDiseases$rows
                
                result_df <- tryCatch({
                  data.frame(
                    Disease = sapply(diseases_df$disease$name, function(x) {
                      if (is.null(x) || is.na(x)) "Unknown" else as.character(x)
                    }),
                    `Therapeutic Areas` = sapply(diseases_df$disease$therapeuticAreas, function(areas) {
                      if (is.null(areas) || !is.data.frame(areas) || nrow(areas) == 0) {
                        "N/A"
                      } else {
                        paste(areas$name[!is.na(areas$name)], collapse = ", ")
                      }
                    }),
                    Score = round(diseases_df$score, 3),
                    stringsAsFactors = FALSE,
                    check.names = FALSE
                  )
                }, error = function(e) {
                  data.frame(Disease = "Error loading diseases", `Therapeutic Areas` = "N/A", Score = 0)
                })
                
                result_df <- result_df[order(-result_df$Score), ]
                
                DT::datatable(
                  result_df,
                  options = list(pageLength = 10, scrollY = "250px", dom = 'frtip'),
                  rownames = FALSE
                ) %>%
                  DT::formatStyle('Score', 
                                  backgroundColor = DT::styleInterval(c(0.3, 0.5, 0.7), 
                                                                      c('#ffffff', '#fff3cd', '#d4edda', '#28a745')))
              })
            } else {
              tags$div(
                style = "background-color: #f8f9fa; padding: 15px; border-radius: 8px; text-align: center;",
                tags$p(icon("info-circle"), " No disease associations found for this gene.")
              )
            }
          ),
          
          # Additional Information Section
          fluidRow(
            style = "margin-top: 20px;",
            column(6,
                   tags$div(
                     style = "background-color: #f8f9fa; padding: 15px; border-radius: 8px; height: 100%;",
                     h5(icon("pills"), " Tractability", style = "color: #00796b;"),
                     if (!is.null(ot_data$tractability) && length(ot_data$tractability) > 0) {
                       DT::renderDataTable({
                         DT::datatable(
                           as.data.frame(ot_data$tractability),
                           options = list(dom = 't', scrollY = "150px", paging = FALSE),
                           rownames = FALSE
                         )
                       })
                     } else {
                       tags$p("No tractability data available", style = "color: #666;")
                     }
                   )
            ),
            column(6,
                   tags$div(
                     style = "background-color: #f8f9fa; padding: 15px; border-radius: 8px; height: 100%;",
                     h5(icon("map-marker-alt"), " Subcellular Locations", style = "color: #00796b;"),
                     if (!is.null(ot_data$subcellularLocations) && length(ot_data$subcellularLocations) > 0) {
                       DT::renderDataTable({
                         DT::datatable(
                           as.data.frame(ot_data$subcellularLocations),
                           options = list(dom = 't', scrollY = "150px", paging = FALSE),
                           rownames = FALSE
                         )
                       })
                     } else {
                       tags$p("No location data available", style = "color: #666;")
                     }
                   )
            )
          ),
          
          # External Links
          tags$div(
            style = "margin-top: 20px; padding-top: 15px; border-top: 1px solid #ddd; text-align: center;",
            h5("External Resources", style = "color: #666; margin-bottom: 15px;"),
            tags$a(href = paste0("https://platform.opentargets.org/target/", gene_data$ensembl_id),
                   target = "_blank", class = "btn btn-outline-primary btn-sm", style = "margin: 5px;",
                   icon("external-link-alt"), " OpenTargets"),
            tags$a(href = paste0("https://www.ensembl.org/Homo_sapiens/Gene/Summary?g=", gene_data$ensembl_id),
                   target = "_blank", class = "btn btn-outline-info btn-sm", style = "margin: 5px;",
                   icon("external-link-alt"), " Ensembl"),
            tags$a(href = paste0("https://www.genecards.org/cgi-bin/carddisp.pl?gene=", gene_data$gene_name),
                   target = "_blank", class = "btn btn-outline-success btn-sm", style = "margin: 5px;",
                   icon("external-link-alt"), " GeneCards"),
            tags$a(href = paste0("https://www.ncbi.nlm.nih.gov/gene/?term=", gene_data$gene_name),
                   target = "_blank", class = "btn btn-outline-secondary btn-sm", style = "margin: 5px;",
                   icon("external-link-alt"), " NCBI Gene")
          ),
          
          footer = modalButton("Close"),
          easyClose = TRUE
        ))
      } else {
        # No data from OpenTargets
        showModal(modalDialog(
          title = tags$div(icon("exclamation-triangle", style = "color: #f57c00;"), " Limited Data Available"),
          
          tags$div(
            style = "text-align: center; padding: 20px;",
            tags$p(paste("Could not fetch OpenTargets data for:", gene_data$gene_name)),
            tags$p(paste("Ensembl ID:", gene_data$ensembl_id), style = "color: #666;"),
            tags$hr(),
            tags$p("You can try viewing the gene directly on external databases:"),
            tags$div(
              style = "margin-top: 15px;",
              tags$a(href = paste0("https://platform.opentargets.org/target/", gene_data$ensembl_id),
                     target = "_blank", class = "btn btn-primary", style = "margin: 5px;",
                     icon("external-link-alt"), " OpenTargets"),
              tags$a(href = paste0("https://www.ensembl.org/Homo_sapiens/Gene/Summary?g=", gene_data$ensembl_id),
                     target = "_blank", class = "btn btn-info", style = "margin: 5px;",
                     icon("external-link-alt"), " Ensembl")
            )
          ),
          
          size = "m",
          easyClose = TRUE,
          footer = modalButton("Close")
        ))
      }
    })
  }
  
  
  # Update download handler for gene reports
