  # Modified volcano plot handler
  observeEvent(input$show_volcano, {
    req(results())
    
    volcano_plot <- plot_ly(
      data = results()$topGenes_tcga,
      x = ~log2FC,
      y = ~-log10(adj.P.Val),
      type = "scatter",
      mode = "markers",
      marker = list(
        size = 8,
        opacity = 0.6
      ),
      color = ~case_when(
        log2FC >= input$log2fc_threshold & adj.P.Val <= input$adj_pval_threshold_tcga ~ "Upregulated",
        log2FC <= -input$log2fc_threshold & adj.P.Val <= input$adj_pval_threshold_tcga ~ "Downregulated",
        TRUE ~ "Not Significant"
      ),
      colors = c("Upregulated" = "red", "Downregulated" = "blue", "Not Significant" = "grey"),
      text = ~paste("Gene:", gene_name,
                    "\nlog2FC:", round(log2FC, 3),
                    "\nAdj P-value:", signif(adj.P.Val, 3))
    ) %>%
      layout(
        title = paste0("Volcano Plot (log2FC threshold: B1", input$log2fc_threshold, ")"),
        xaxis = list(
          title = "Log2 Fold Change",
          range = c(-max(abs(results()$topGenes_tcga$log2FC)),
                    max(abs(results()$topGenes_tcga$log2FC)))
        ),
        yaxis = list(title = "-Log10 Adjusted P-value"),
        showlegend = TRUE
      )
    
    # Store the current volcano plot in reactive values
    rv$current_volcano <- volcano_plot
    
    showModal(modalDialog(
      plotlyOutput("volcano_modal", height = "600px"),
      footer = tagList(
        downloadButton("download_volcano_tcga", "Download Plot"),
        modalButton("Close")
      ),
      size = "l",
      easyClose = TRUE
    ))
    
    output$volcano_modal <- renderPlotly({
      volcano_plot
    })
  })
  
  # Add this to store reactive values
  rv <- reactiveValues(current_volcano = NULL)
  
  # Add PCA plot rendering
  output$pca_plot <- renderPlotly({
    req(results())
    
    withProgress(message = "Generating PCA plot...", value = 0, {
      # Extract PCA data from your normalized data
      if (input$analysis_method == "limma") {
        pca_data <- prcomp(t(v$E))
      } else if (input$analysis_method == "edgeR") {
        pca_data <- prcomp(t(cpm(dge, log = TRUE)))
      }
      
      incProgress(0.3, detail = "Calculating variance") # Increment progress
      
      # Create PCA data frame
      variance_explained <- round(100 * pca_data$sdev^2 / sum(pca_data$sdev^2), 1)
      
      pca_df <- data.frame(
        PC1 = pca_data$x[, 1],
        PC2 = pca_data$x[, 2],
        Group = coldata$group,
        Sample = rownames(pca_data$x)
      )
      
      incProgress(0.7, detail = "Creating plot") # Increment progress
      
      # Create PCA plot
      yo_pca <- plot_ly(
        pca_df,
        x = ~PC1,
        y = ~PC2,
        color = ~Group,
        text = ~Sample,
        type = "scatter",
        mode = "markers",
        marker = list(size = 10)
      ) %>%
        layout(
          title = "PCA Plot",
          xaxis = list(title = paste0("PC1 (", variance_explained[1], "%)")),
          yaxis = list(title = paste0("PC2 (", variance_explained[2], "%)")),
          showlegend = TRUE
        )
      
      incProgress(1, detail = "Done") # Increment progress to 100%
      
      rv$current_PCA <- yo_pca
      
      return(yo_pca) # Return the plot object
    })
  })
  
  rv <- reactiveValues(current_PCA = NULL)
  
  # Modified download handlers
  output$download_volcano_tcga <- downloadHandler(
    filename = function() {
      paste0("volcano_plot_", input$analysis_method, "_", Sys.Date(), ".png")
    },
    content = function(file) {
      load_export_packages()
      req(results()$topGenes_tcga)
      
      # Create static ggplot version for high-quality output
      plot_data <- results()$topGenes_tcga %>%
        as.data.frame() %>%
        dplyr::mutate(
          significance = case_when(
            log2FC >= input$log2fc_threshold & adj.P.Val <= input$adj_pval_threshold ~ "Upregulated",
            log2FC <= -input$log2fc_threshold & adj.P.Val <= input$adj_pval_threshold ~ "Downregulated",
            TRUE ~ "Not Significant"
          ),
          label = ifelse(abs(log2FC) >= max(abs(input$log2fc_threshold)) &
                           adj.P.Val <= input$adj_pval_threshold, gene_name, "")
        )
      
      # Create color scale
      color_scale <- c(
        "Upregulated" = "#FF4444",
        "Downregulated" = "#4444FF",
        "Not Significant" = "#CCCCCC"
      )
      
      # Create the static plot using ggplot2
      p <- ggplot(plot_data, aes(x = log2FC, y = -log10(adj.P.Val))) +
        # Add points
        geom_point(aes(color = significance), size = 2, alpha = 0.7) +
        # Add threshold lines
        geom_vline(xintercept = c(-input$log2fc_threshold, input$log2fc_threshold),
                   linetype = "dashed", color = "darkgray") +
        geom_hline(yintercept = -log10(input$adj_pval_threshold),
                   linetype = "dashed", color = "darkgray") +
        # Custom colors
        scale_color_manual(values = color_scale) +
        # Add labels for significant genes
        geom_text_repel(
          aes(label = label),
          box.padding = 0.5,
          point.padding = 0.3,
          force = 5,
          segment.color = "grey50",
          size = 3
        ) +
        # Customize theme
        theme_bw() +
        theme(
          plot.title = element_text(size = 16, face = "bold", hjust = 0.5),
          axis.title = element_text(size = 14, face = "bold"),
          axis.text = element_text(size = 12),
          legend.title = element_text(size = 12, face = "bold"),
          legend.text = element_text(size = 10),
          legend.position = "right",
          panel.grid.major = element_line(color = "grey90"),
          panel.grid.minor = element_line(color = "grey95"),
          plot.margin = margin(20, 20, 20, 20)
        ) +
        # Labels
        labs(
          title = "Volcano Plot of Differential Expression",
          x = "Log2 Fold Change",
          y = "-Log10 Adjusted P-value",
          color = "Gene Category"
        )
      
      # Save the plot with high resolution
      ggsave(file, plot = p, width = 12, height = 10, dpi = 300, bg = "white")
    }
  )
  
  output$download_pca <- downloadHandler(
    filename = function() {
      paste0("pca_plot_", input$analysis_method, "_", Sys.Date(), ".png")
    },
    content = function(file) {
      load_export_packages()
      req(rv$current_PCA)
      
