        vheight = 1200,
        # --- KEY ADDITION FOR SERVER/DOCKER ENVIRONMENTS ---
        extra_args = c(
          "--no-sandbox",
          "--disable-gpu",
          "--disable-dev-shm-usage"
        )
      )
      
      unlink("temp.html") # Clean up temporary file
    }
  )
  
  
