  # Initialize reactive value for pathway results
  tcga_pathway_results <- reactiveVal(NULL)
  
  # Helper function to convert genes based on database requirements
  prepare_genes_for_enrichment <- function(deg_data, database) {
    # Print input data structure
    print("Input DEG data structure:")
    print(str(deg_data))
    print("Column names in DEG data:")
    print(colnames(deg_data))
    
    # First get significant genes
    significant_genes <- deg_data[deg_data$adj.P.Val < input$tcga_pval_cutoff, ]
    
    # Filter based on fold change
    selected_genes <- switch(input$tcga_gene_set,
                             "up" = significant_genes[significant_genes$log2FC > input$log2fc_threshold, ],
                             "down" = significant_genes[significant_genes$log2FC < -input$log2fc_threshold, ],
                             "all" = significant_genes[abs(significant_genes$log2FC) > input$log2fc_threshold, ]
    )
    
    print(paste("Number of significant genes after filtering:", nrow(selected_genes)))
    
    # Convert based on database requirements
    if(grepl("KEGG", database)) {
      # For KEGG: need gene symbols
      print("Converting ENSEMBL IDs to gene symbols for KEGG...")
      symbols <- mapIds(org.Hs.eg.db,
                        keys = selected_genes$ensembl_id,
                        column = "SYMBOL",
                        keytype = "ENSEMBL",
                        multiVals = "first")
      
      symbols <- symbols[!is.na(symbols)]
      print("Sample of gene symbols for KEGG:")
      print(head(symbols))
      return(as.character(symbols))
      
    } else if(grepl("GO", database)) {
      # For GO: use gene symbols
      print("Converting ENSEMBL IDs to gene symbols for GO...")
      symbols <- mapIds(org.Hs.eg.db,
                        keys = selected_genes$ensembl_id,
                        column = "SYMBOL",
                        keytype = "ENSEMBL",
                        multiVals = "first")
      
      symbols <- symbols[!is.na(symbols)]
      print("Sample of gene symbols for GO:")
      print(head(symbols))
      return(as.character(symbols))
      
    } else if(grepl("Reactome", database)) {
      # For Reactome: use gene symbols
      print("Converting ENSEMBL IDs to gene symbols for Reactome...")
      symbols <- mapIds(org.Hs.eg.db,
                        keys = selected_genes$ensembl_id,
                        column = "SYMBOL",
                        keytype = "ENSEMBL",
                        multiVals = "first")
      
      symbols <- symbols[!is.na(symbols)]
      print("Sample of gene symbols for Reactome:")
      print(head(symbols))
      return(as.character(symbols))
      
    } else if(grepl("WikiPathways|MSigDB|Hallmark", database)) {
      # For others: use gene symbols
      print("Converting ENSEMBL IDs to gene symbols...")
      symbols <- mapIds(org.Hs.eg.db,
                        keys = selected_genes$ensembl_id,
                        column = "SYMBOL",
                        keytype = "ENSEMBL",
                        multiVals = "first")
      
      symbols <- symbols[!is.na(symbols)]
      print("Sample of gene symbols:")
      print(head(symbols))
      return(as.character(symbols))
    }
  }
  
  # Observe enrichment analysis button click
  observeEvent(input$run_tcga_enrichment, {
    req(results())
    
    # Show progress
    shinyjs::show("tcga_pathway_progress")
    
    withProgress(message = 'Running pathway analysis...', value = 0, {
      tryCatch({
        
        # Verify we have TCGA results
        print("Checking TCGA results...")
        print("Available results components:")
        print(names(results()))
        
        # Get DEG results
        deg_data <- results()$topGenes_tcga
        
        print("Starting pathway analysis...")
        print(paste("Number of genes in DEG results:", nrow(deg_data)))
        
        all_results <- list()
        
        # Process each selected database
        for(db in input$tcga_pathway_db) {
          incProgress(0.1, detail = paste("Processing", db))
          
          # Get appropriate gene IDs for this database
          genes <- prepare_genes_for_enrichment(deg_data, db)
          
          print(paste("Processing database:", db))
          print(paste("Number of genes for enrichment:", length(genes)))
          print("Sample of genes being used:")
          print(head(genes))
          
          # Run enrichr for this database
          if(length(genes) > 0) {
            enrichment_result <- tx_enrichr_local(genes, databases = db)
            
            if(!is.null(enrichment_result[[db]]) && nrow(enrichment_result[[db]]) > 0) {
              all_results[[db]] <- enrichment_result[[db]]
              print(paste("Found", nrow(enrichment_result[[db]]), "enriched terms for", db))
            } else {
              print(paste("No enrichment results found for", db))
            }
          }
        }
        
        # Store results if any were found
        if(length(all_results) > 0) {
          tcga_pathway_results(all_results)
          showNotification(
            paste("Analysis complete.", length(genes), "genes analyzed."),
            type = "message"
          )
        } else {
          showNotification("No significant enrichment results found.", type = "warning")
        }
        
        # Hide progress
        shinyjs::hide("tcga_pathway_progress")
        
      }, error = function(e) {
        print(paste("Error details:", e$message))
        showNotification(paste("Error in pathway analysis:", e$message), type = "error")
        shinyjs::hide("tcga_pathway_progress")
      })
    })
  })
  
  # Render enrichment table
  output$tcga_enrichment_table <- DT::renderDataTable({
    req(tcga_pathway_results())
    
    # Combine results from all databases
    all_results <- lapply(names(tcga_pathway_results()), function(db) {
      res <- tcga_pathway_results()[[db]]
      if(!is.null(res) && nrow(res) > 0) {
        res$Database <- db
        return(res)
      }
      return(NULL)
    })
    
    # Remove NULL results
    all_results <- all_results[!sapply(all_results, is.null)]
    
    if(length(all_results) == 0) {
      return(data.frame(Message = "No significant enrichment results found"))
    }
    
    # Combine results
    results_df <- do.call(rbind, all_results)
    
    # Filter by adjusted p-value
    results_df <- results_df[results_df$Adjusted.P.value < input$tcga_pval_cutoff, ]
    
    # Sort based on selected criterion
    if(input$tcga_sort_by == "Combined.Score") {
      results_df <- results_df[order(-results_df$Combined.Score), ]
    } else if(input$tcga_sort_by == "Adjusted.P.value") {
      results_df <- results_df[order(results_df$Adjusted.P.value), ]
    } else if(input$tcga_sort_by == "Count") {
      results_df$Count <- as.numeric(sapply(strsplit(results_df$Overlap, "/"), `[`, 1))
      results_df <- results_df[order(-results_df$Count), ]
    }
    
    # Create the datatable
    DT::datatable(
      results_df,
      options = list(
        pageLength = 15,
        scrollX = TRUE,
        dom = 'Bfrtip',
        buttons = c('copy', 'csv', 'excel')
      ),
      extensions = 'Buttons',
      rownames = FALSE
    ) %>%
      formatSignif(columns = c("P.value", "Adjusted.P.value"), digits = 3)
  })
  
  # Add download handler for enrichment results
  output$download_tcga_enrichment <- downloadHandler(
    filename = function() {
      paste0("tcga_pathway_analysis_", Sys.Date(), ".csv")
    },
    content = function(file) {
      load_export_packages()
      # Get the current results
      all_results <- do.call(rbind, lapply(names(tcga_pathway_results()), function(db) {
        res <- tcga_pathway_results()[[db]]
        if(!is.null(res) && nrow(res) > 0) {
          res$Database <- db
          return(res)
        }
        return(NULL)
      }))
      
      # Write to file
      write.csv(all_results, file, row.names = FALSE)
    }
  )
  
  output$database_specific_tables <- renderUI({
    req(tcga_pathway_results())
    
    # Get the selected databases
    selected_dbs <- input$tcga_pathway_db
    
    # Check if we have results
    if(length(tcga_pathway_results()) == 0) {
      return(div(class = "alert alert-warning", "No enrichment results found."))
    }
    
    # Create a tabset panel for each database
    do.call(tabsetPanel, c(
      list(
        id = "database_tabs",
        type = "pills"
      ),
      # Generate a tab for each database with results
      lapply(names(tcga_pathway_results()), function(db) {
        # Create an ID for this specific table
        table_id <- paste0("tcga_", gsub("[^a-zA-Z0-9]", "_", db), "_table")
        
        tabPanel(
          db,  # Use db as the title
          div(
            style = "margin-top: 15px;",
            # Add download button for this specific database
            downloadButton(
              paste0("download_", table_id),
              "Download Results"
            ),
            # Render the table for this database
            DT::dataTableOutput(table_id)
          )
        )
      })
    ))
  })
  
