        if(input$tcga_sort_by == "Combined.Score") {
          results_df <- results_df[order(-results_df$Combined.Score), ]
        } else if(input$tcga_sort_by == "Adjusted.P.value") {
          results_df <- results_df[order(results_df$Adjusted.P.value), ]
        } else if(input$tcga_sort_by == "Count") {
          results_df$Count <- as.numeric(sapply(strsplit(results_df$Overlap, "/"), `[`, 1))
          results_df <- results_df[order(-results_df$Count), ]
        }
        
        # Create the datatable
        DT::datatable(
