  output$tcga_enrichment_plot <- renderPlotly({
    req(tcga_pathway_results())
    req(input$tcga_plot_type)
    
    tryCatch({
      # Combine results from all selected databases
      all_results <- lapply(names(tcga_pathway_results()), function(db) {
        res <- tcga_pathway_results()[[db]]
        if(!is.null(res) && nrow(res) > 0) {
          res$Database <- db
          return(res)
        }
        return(NULL)
      })
      
      # Remove NULL results and combine
      all_results <- do.call(rbind, all_results[!sapply(all_results, is.null)])
      
      if(is.null(all_results) || nrow(all_results) == 0) {
        return(plot_ly() %>%
                 layout(title = list(
                   text = "No enrichment results available",
                   font = list(size = 18, color = "#2f4f4f")
                 )))
      }
      
      # Filter by p-value threshold
      all_results <- all_results[all_results$Adjusted.P.value < input$tcga_pval_cutoff, ]
      
      if(nrow(all_results) == 0) {
        return(plot_ly() %>%
                 layout(title = list(
                   text = "No pathways pass significance threshold",
                   font = list(size = 18, color = "#2f4f4f")
                 )))
      }
      
      # Sort based on selected criterion
      if(input$tcga_sort_by == "Combined.Score") {
        all_results <- all_results[order(-all_results$Combined.Score), ]
      } else if(input$tcga_sort_by == "Adjusted.P.value") {
        all_results <- all_results[order(all_results$Adjusted.P.value), ]
      } else if(input$tcga_sort_by == "Count") {
        all_results$Count <- as.numeric(sapply(strsplit(all_results$Overlap, "/"), `[`, 1))
        all_results <- all_results[order(-all_results$Count), ]
      }
      
      # Calculate values for visualization
      all_results$negLogP <- -log10(all_results$Adjusted.P.value)
      all_results$Count <- as.numeric(sapply(strsplit(all_results$Overlap, "/"), `[`, 1))
      
      
      all_results <- head(all_results, input$tcga_top_pathways)
      # Create enhanced color palette
      n_dbs <- length(unique(all_results$Database))
      custom_colors <- c("#2E86C1", "#16A085", "#E67E22", "#8E44AD", "#C0392B",
                         "#1ABC9C", "#F1C40F", "#2980B9", "#27AE60", "#D35400")
      
      if(n_dbs <= length(custom_colors)) {
        colors <- custom_colors[1:n_dbs]
      } else {
        colors <- colorRampPalette(custom_colors)(n_dbs)
      }
      db_colors <- setNames(colors, unique(all_results$Database))
      
      # Create enhanced hover text
      hover_text <- paste0(
        "<b>", all_results$Term, "</b>",
        "<br><b>Database:</b> ", all_results$Database,
        "<br><b>Adjusted P-value:</b> ", format(all_results$Adjusted.P.value, scientific = TRUE, digits = 3),
        "<br><b>-log10(adj P-value):</b> ", round(all_results$negLogP, 3),
        "<br><b>Overlap:</b> ", all_results$Overlap,
        "<br><b>Combined Score:</b> ", round(all_results$Combined.Score, 2),
        "<br><br><em>Genes:</em> ", all_results$Genes
      )
      
      # Clean pathway names for display
      all_results$DisplayTerm <- gsub("_", " ", all_results$Term)
      all_results$DisplayTerm <- paste0(all_results$DisplayTerm, " (", all_results$Database, ")")
      
      # Create enhanced plots
      if(input$tcga_plot_type == "dot") {
        p <- plot_ly(
          data = all_results,
          y = ~reorder(DisplayTerm, Combined.Score),
          x = ~negLogP,
          size = ~Count,
          color = ~Database,
          colors = db_colors,
          type = "scatter",
          mode = "markers",
          marker = list(
            sizemode = "diameter",
            sizeref = 2 * max(all_results$Count) / 50,
            line = list(width = 1, color = "#ffffff"),
            opacity = 0.85
          ),
          text = ~hover_text,
          hoverinfo = "text"
        )
      } else if(input$tcga_plot_type == "bar") {
        p <- plot_ly(
          data = all_results,
          y = ~reorder(DisplayTerm, Combined.Score),
          x = ~negLogP,
          color = ~Database,
          colors = db_colors,
          type = "bar",
          orientation = "h",
          text = ~hover_text,
          hoverinfo = "text",
          textposition = "none",
          marker = list(
            line = list(width = 1, color = "#ffffff"),
            opacity = 0.85
          )
        )
      }
      
      # Enhanced layout
      p %>% layout(
        title = list(
          text = "<b>Top Enriched Pathways</b>",
          font = list(size = 20, color = "#2f4f4f"),
          pad = list(t = 20, b = 20)
        ),
        xaxis = list(
          title = list(
            text = "<b>-log10(Adjusted P-value)</b>",
            font = list(size = 14, color = "#2f4f4f")
          ),
          gridcolor = "#e5e5e5",
          gridwidth = 1,
          zeroline = TRUE,
          zerolinecolor = "#969696",
          zerolinewidth = 1,
          showline = TRUE,
          linecolor = "#969696",
          linewidth = 1,
          tickfont = list(size = 12, color = "#2f4f4f")
        ),
        yaxis = list(
          title = "",
          gridcolor = "#e5e5e5",
          gridwidth = 1,
          showline = TRUE,
          linecolor = "#969696",
          linewidth = 1,
          tickfont = list(size = 11, color = "#2f4f4f")
        ),
        margin = list(l = 400, r = 100, b = 60, t = 80),
        hoverlabel = list(
          bgcolor = "#ffffff",
          bordercolor = "#969696",
          font = list(size = 12, color = "#2f4f4f")
        ),
        showlegend = TRUE,
        legend = list(
          title = list(
            text = "<b>Database</b>",
            font = list(size = 14, color = "#2f4f4f")
          ),
          x = 1.02,
          y = 0.5,
          bgcolor = "#ffffff",
          bordercolor = "#969696",
          borderwidth = 1,
          font = list(size = 12, color = "#2f4f4f")
        ),
        plot_bgcolor = "#ffffff",
        paper_bgcolor = "#ffffff"
