                   text = paste("Error:", e$message),
                   showarrow = FALSE,
                   font = list(size = 14, color = "#2f4f4f")
                 )
               ))
    })
  })
  
  
  # Download handler for enrichment plot
  output$download_tcga_enrichment_plot <- downloadHandler(
    filename = function() {
      paste0("pathway_enrichment_", format(Sys.time(), "%Y%m%d_%H%M%S"), ".pdf")
    },
    content = function(file) {
      load_export_packages()
      # Get the results
      all_results <- do.call(rbind, lapply(names(tcga_pathway_results()), function(db) {
        res <- tcga_pathway_results()[[db]]
        if(!is.null(res) && nrow(res) > 0) {
          res$Database <- db
          return(res)
        }
        return(NULL)
      }))
      
      # Extract counts and add as numeric column
      all_results$Count <- as.numeric(sapply(strsplit(all_results$Overlap, "/"), `[`, 1))
      
      # Filter by p-value
      all_results <- all_results[all_results$Adjusted.P.value < input$tcga_pval_cutoff, ]
      
      # Sort based on selected criterion (matching interactive plot)
      if(input$tcga_sort_by == "Combined.Score") {
        all_results <- all_results[order(-all_results$Combined.Score), ]
      } else if(input$tcga_sort_by == "Adjusted.P.value") {
        all_results <- all_results[order(all_results$Adjusted.P.value), ]
      } else if(input$tcga_sort_by == "Count") {
        all_results <- all_results[order(-all_results$Count), ]
      }
      
      all_results <- head(all_results, input$tcga_top_pathways)
      
      # Calculate text size based on number of pathways
      text_size <- max(6, min(10, 200/nrow(all_results)))
      
      # Create custom color palette
      n_dbs <- length(unique(all_results$Database))
      custom_colors <- c("#2E86C1", "#16A085", "#E67E22", "#8E44AD", "#C0392B",
                         "#1ABC9C", "#F1C40F", "#2980B9", "#27AE60", "#D35400")
      colors <- if(n_dbs <= length(custom_colors)) {
        custom_colors[1:n_dbs]
      } else {
        colorRampPalette(custom_colors)(n_dbs)
      }
      db_colors <- setNames(colors, unique(all_results$Database))
      
      # Calculate plot dimensions
      height <- max(8, min(15, nrow(all_results) * 0.3))
      width <- 14  # Increased width to accommodate labels
      
      # Create y-axis ordering based on sorting criterion
      if(input$tcga_sort_by == "Combined.Score") {
        all_results$Term <- factor(all_results$Term, levels = rev(all_results$Term[order(all_results$Combined.Score)]))
      } else if(input$tcga_sort_by == "Adjusted.P.value") {
        all_results$Term <- factor(all_results$Term, levels = rev(all_results$Term[order(all_results$Adjusted.P.value)]))
      } else {
        all_results$Term <- factor(all_results$Term, levels = rev(all_results$Term[order(all_results$Count)]))
      }
      
      # Create the plot
      if(input$tcga_plot_type == "dot") {
        p <- ggplot(all_results,
                    aes(x = -log10(Adjusted.P.value),
                        y = Term,
                        size = Count,
                        color = Database)) +
          geom_point(alpha = 0.8) +
          geom_text(aes(label = Count),
                    color = "black",
                    size = text_size * 0.3,
                    vjust = -1.5) +  # Position labels above points
          scale_color_manual(values = db_colors) +
          scale_size_continuous(name = "Gene Count",
                                range = c(2, 8),
                                breaks = pretty(all_results$Count, n = 5)) +
          guides(color = guide_legend(title = "Database", override.aes = list(size = 4)),
                 size = guide_legend(title = "Gene Count"))
      } else {
        p <- ggplot(all_results,
                    aes(x = -log10(Adjusted.P.value),
                        y = Term,
                        fill = Database)) +
          geom_bar(stat = "identity", alpha = 0.8) +
          geom_text(aes(label = Count),
                    hjust = -0.2,  # Position labels just outside the bars
                    size = text_size * 0.3) +
          scale_fill_manual(values = db_colors) +
          guides(fill = guide_legend(title = "Database"))
      }
      
      # Add common theme elements
      p <- p +
        theme_minimal(base_size = text_size) +
        theme(
          plot.title = element_text(size = text_size * 1.3, face = "bold", hjust = 0.5),
          plot.subtitle = element_text(size = text_size * 0.9, hjust = 0.5),
          axis.title.x = element_text(size = text_size * 1.1, face = "bold"),
          axis.title.y = element_blank(),
          axis.text.x = element_text(size = text_size * 0.9),
          axis.text.y = element_text(size = text_size * 0.9),
          legend.title = element_text(size = text_size * 1.1, face = "bold"),
          legend.text = element_text(size = text_size * 0.9),
          legend.position = "right",
          legend.box = "vertical",
          panel.grid.major = element_line(color = "gray90"),
          panel.grid.minor = element_line(color = "gray95"),
          plot.margin = margin(20, 20, 20, 20)
        ) +
        labs(
          title = "Pathway Enrichment Analysis",
          x = "-log10(Adjusted P-value)",
          y = NULL
        )
      
      # Adjust plot margins to accommodate labels
      if(input$tcga_plot_type == "bar") {
        p <- p + scale_x_continuous(expand = expansion(mult = c(0, 0.2)))  # Add space for labels
      }
      
      # Save the plot
      ggsave(file,
             plot = p,
             width = width,
             height = height,
             dpi = 300,
             device = cairo_pdf)
    }
  )
  
  
