      gene_lists <- strsplit(as.character(all_results$Genes), ";")
      all_genes <- unique(unlist(gene_lists))
      
      # Create database color mapping as a list
      db_levels <- unique(all_results$Database)
      n_dbs <- length(db_levels)
      custom_colors <- c("#2E86C1", "#16A085", "#E67E22", "#8E44AD", "#C0392B",
                         "#1ABC9C", "#F1C40F", "#2980B9", "#27AE60", "#D35400")
      
      db_colors <- if(n_dbs <= length(custom_colors)) {
        custom_colors[1:n_dbs]
      } else {
        colorRampPalette(custom_colors)(n_dbs)
      }
      
      # Create color mapping as a list
      color_mapping <- setNames(
        lapply(seq_along(db_levels), function(i) {
          list(
            background = adjustcolor(db_colors[i], alpha.f = 0.8),
            border = db_colors[i],
            highlight = list(
              background = db_colors[i],
              border = "#000000"
            )
          )
        }),
        db_levels
      )
      
      # Create nodes dataframe
      nodes <- data.frame(
        id = c(paste0("p_", 1:nrow(all_results)),
               paste0("g_", 1:length(all_genes))),
        label = c(all_results$Term, all_genes),
        group = c(all_results$Database, rep("gene", length(all_genes))),
        title = c(
          mapply(function(term, pval, db, overlap, score) {
            paste0("<b>", term, "</b><br>",
                   "Database: ", db, "<br>",
                   "Adjusted P-value: ", formatC(pval, format = "e", digits = 2), "<br>",
                   "Overlap: ", overlap, "<br>",
                   "Combined Score: ", round(score, 2))
          }, all_results$Term, all_results$Adjusted.P.value,
          all_results$Database, all_results$Overlap, all_results$Combined.Score),
          paste0("<b>Gene:</b> ", all_genes)
        ),
        value = c(sapply(strsplit(all_results$Overlap, "/"), function(x) as.numeric(x[1])) * 2,
                  rep(10, length(all_genes))),
        stringsAsFactors = FALSE
      )
      
      # Create edges
      edges_list <- lapply(seq_len(nrow(all_results)), function(i) {
        genes <- unlist(gene_lists[[i]])
        data.frame(
          from = rep(paste0("p_", i), length(genes)),
          to = paste0("g_", match(genes, all_genes)),
          width = 1 + -log10(all_results$Adjusted.P.value[i])/5,
          stringsAsFactors = FALSE
        )
      })
      edges <- do.call(rbind, edges_list)
      
      # Create the network
      network <- visNetwork(nodes, edges, width = "100%", height = "100%") %>%
        visGroups(groupname = "gene",
                  color = list(
                    background = "#FB7E81",
                    border = "#E62E00",
                    highlight = list(
                      background = "#FF4444",
                      border = "#000000"
                    )
                  ),
                  shape = "dot",
                  shadow = TRUE)
      
      # Add groups for each database using the list-based color mapping
      for(db in db_levels) {
        network <- network %>%
          visGroups(
            groupname = db,
            color = color_mapping[[db]],
            shape = "box",
            shadow = TRUE
          )
      }
      
      # Add remaining network properties
      network %>%
        visOptions(
          highlightNearest = list(
            enabled = TRUE,
            degree = 1,
            hover = TRUE
          ),
          selectedBy = list(
            variable = "group",
            multiple = TRUE
          ),
          nodesIdSelection = TRUE
        ) %>%
        visLayout(randomSeed = 123) %>%
        visPhysics(
          solver = input$tcga_network_layout,
          stabilization = list(
            enabled = TRUE,
            iterations = 200,
            fit = TRUE
          ),
          barnesHut = list(
            gravitationalConstant = -2000,
            centralGravity = 0.3,
            springLength = 150,
            springConstant = 0.04,
            damping = 0.09
          ),
          forceAtlas2Based = list(
            gravitationalConstant = -50,
            centralGravity = 0.01,
            springLength = 100,
            springConstant = 0.08,
            damping = 0.4,
            avoidOverlap = 0.5
          ),
          repulsion = list(
            nodeDistance = 150,
            centralGravity = 0.2,
            springLength = 200,
            springConstant = 0.05,
            damping = 0.09
          )
        ) %>%
        visInteraction(
          hover = TRUE,
          hoverConnectedEdges = TRUE,
          selectConnectedEdges = TRUE,
          navigationButtons = TRUE
        ) %>%
        visEvents(type = "once", stabilizationIterationsDone = "function() {
        this.setOptions({physics: false});
      }")
    }, error = function(e) {
      message("Error in network generation: ", e$message)
      return(visNetwork(
        nodes = data.frame(id = 1, label = paste("Error:", e$message), shape = "text"),
        edges = data.frame(from = c(), to = c())
      ))
    })
  })
  } # end if(FALSE) — disabled duplicate renderer #2


