  output$download_network_pdf <- downloadHandler(
    filename = function() {
      paste("network_", Sys.Date(), ".pdf", sep = "")
    },
    content = function(file) {
      load_export_packages()
      req(tcga_pathway_results())
      req(input$network_pathway_count)
      
      # Notification setup
      notif_id <- "pdf_gen_notif"
      showNotification("Generating high-resolution PDF... This may take 30-60 seconds.",
                       id = notif_id, type = "message", duration = NULL)
      
      tryCatch({
        # Create temporary files
        temp_html <- tempfile(fileext = ".html")
        temp_png <- tempfile(fileext = ".png")
        
        # 1. Data Preparation ----------------------------------------------------
        # Combine results from all databases
        all_results <- do.call(rbind, lapply(names(tcga_pathway_results()), function(db) {
          res <- tcga_pathway_results()[[db]]
          if(!is.null(res) && nrow(res) > 0) {
            res$Database <- db
            return(res)
          }
          return(NULL)
        }))
        
        # Filter and validate results
        if(is.null(all_results) || nrow(all_results) == 0) {
          stop("No enrichment results available")
        }
        
        all_results <- all_results[all_results$Adjusted.P.value < input$tcga_pval_cutoff, ]
        if(nrow(all_results) == 0) {
          stop("No significant pathways found")
        }
        
        # Sorting
        if(input$tcga_sort_by == "Combined.Score") {
          all_results <- all_results[order(-all_results$Combined.Score), ]
        } else if(input$tcga_sort_by == "Adjusted.P.value") {
          all_results <- all_results[order(all_results$Adjusted.P.value), ]
        } else {
          all_results$Count <- as.numeric(sapply(strsplit(all_results$Overlap, "/"), function(x) {
            if(length(x) > 0) as.numeric(x[1]) else 0
          }))
          all_results <- all_results[order(-all_results$Count), ]
        }
        
        all_results <- head(all_results, input$network_pathway_count)
        
        # 2. Network Construction with Improved Spacing -------------------------
        # Extract gene lists safely
        gene_lists <- lapply(as.character(all_results$Genes), function(genes) {
          if(is.na(genes) || genes == "") return(character(0))
          unlist(strsplit(genes, ";"))
        })
        
        # Extract all unique genes
        all_genes <- unique(unlist(gene_lists))
        
        # Safety check - if no genes, create a minimal network
        if(length(all_genes) == 0) {
          # Create a simple network with just pathway nodes
          nodes <- data.frame(
            id = paste0("p_", 1:nrow(all_results)),
            label = all_results$Term,
            group = all_results$Database,
            value = rep(30, nrow(all_results)),
            title = sapply(1:nrow(all_results), function(i) {
              sprintf("Term: %s<br>Database: %s<br>Adjusted p-value: %.2e",
                      all_results$Term[i], all_results$Database[i],
                      all_results$Adjusted.P.value[i])
            }),
            stringsAsFactors = FALSE
          )
          
          # Create basic edges between pathways
          edges <- data.frame(
            from = character(0),
            to = character(0),
            width = numeric(0),
            color = "#777777",
            stringsAsFactors = FALSE
          )
        } else {
          # Limit the number of genes to prevent overcrowding
          if(length(all_genes) > 150) {
            # Keep genes that appear in multiple pathways
            gene_counts <- table(unlist(gene_lists))
            gene_counts <- sort(gene_counts, decreasing = TRUE)
            selected_genes <- names(gene_counts)[1:min(150, length(gene_counts))]
            all_genes <- selected_genes
            
            # Update gene lists to only include selected genes
            gene_lists <- lapply(gene_lists, function(genes) {
              genes[genes %in% all_genes]
            })
          }
          
          # Improved node sizing based on importance
          pathway_sizes <- sapply(strsplit(all_results$Overlap, "/"), function(x) {
            if(length(x) > 0) as.numeric(x[1]) else 1
          })
          
          max_size <- max(pathway_sizes)
          min_size <- min(pathway_sizes)
          
          # Scale pathway node sizes more appropriately (avoid division by zero)
          if(max_size == min_size) {
            scaled_sizes <- rep(35, length(pathway_sizes))
          } else {
            scaled_sizes <- 25 + (pathway_sizes - min_size) / (max_size - min_size) * 25
          }
          
          # Create improved nodes dataframe with more readable labels
          # Truncate long pathway names
          truncate_text <- function(text, max_length = 30) {
            if(nchar(text) > max_length) {
              paste0(substr(text, 1, max_length), "...")
            } else {
              text
            }
          }
          
          # Create nodes with cleaner labels
          nodes <- data.frame(
            id = c(paste0("p_", 1:nrow(all_results)), paste0("g_", seq_along(all_genes))),
            label = c(sapply(all_results$Term, truncate_text), all_genes),
            group = c(all_results$Database, rep("gene", length(all_genes))),
            value = c(scaled_sizes, rep(10, length(all_genes))),
            title = c(
              sapply(1:nrow(all_results), function(i) {
                sprintf("Term: %s<br>Database: %s<br>Adjusted p-value: %.2e<br>Genes: %d",
                        all_results$Term[i], all_results$Database[i],
                        all_results$Adjusted.P.value[i], pathway_sizes[i])
              }),
              sapply(all_genes, function(g) sprintf("Gene: %s", g))
            ),
            stringsAsFactors = FALSE
          )
          
          # Create edges - initialize an empty edge dataframe first
          edge_list <- list()
          
          for(i in seq_len(nrow(all_results))) {
            genes <- gene_lists[[i]]
            genes <- genes[genes %in% all_genes]  # Only use genes in our filtered set
            
            if(length(genes) == 0) next
            
            # Calculate edge width based on p-value significance
            if(length(all_results$Adjusted.P.value) == 0) {
              width_val <- 1
            } else {
              log_p_vals <- -log10(all_results$Adjusted.P.value)
              max_log_p <- max(log_p_vals)
              if(max_log_p == 0) {
                width_val <- 1
              } else {
                width_val <- 0.5 + 2 * (log_p_vals[i]) / max_log_p
              }
            }
            
            for(gene in genes) {
              gene_idx <- which(all_genes == gene)
              if(length(gene_idx) > 0) {
                edge_list[[length(edge_list) + 1]] <- data.frame(
                  from = paste0("p_", i),
                  to = paste0("g_", gene_idx),
                  width = width_val,
                  color = "#77777766",  # Lighter gray edges with transparency
                  stringsAsFactors = FALSE
                )
              }
            }
          }
          
          # Safely combine edges
          if(length(edge_list) == 0) {
            # Create empty edge dataframe if no edges
            edges <- data.frame(
              from = character(0),
              to = character(0),
              width = numeric(0),
              color = character(0),
              stringsAsFactors = FALSE
            )
          } else {
            edges <- do.call(rbind, edge_list)
          }
        }
        
        # 3. Network Visualization with Improved Layout --------------------------
        # Create better color palette for databases - handle small number of dbs
        num_dbs <- length(unique(all_results$Database))
        
        if(num_dbs > 0) {
          if(num_dbs < 3) {
            # Manual colors for 1-2 databases
            db_colors <- c("#E41A1C", "#377EB8")[1:num_dbs]
          } else if (!requireNamespace("RColorBrewer", quietly = TRUE)) {
            # Fallback if RColorBrewer not available
            db_colors <- c("#E41A1C", "#377EB8", "#4DAF4A", "#984EA3", "#FF7F00",
                           "#FFFF33", "#A65628", "#F781BF", "#999999")[1:num_dbs]
          } else {
            # RColorBrewer for 3+ databases
            db_colors <- RColorBrewer::brewer.pal(max(3, min(9, num_dbs)), "Set1")[1:num_dbs]
          }
          names(db_colors) <- unique(all_results$Database)
        } else {
          # Fallback if no databases
          db_colors <- c("#E41A1C")
          names(db_colors) <- "Unknown"
        }
        
        network <- visNetwork(nodes, edges, width = "100%", height = "800px") %>%
          visIgraphLayout(
            layout = "layout_with_fr",
            physics = TRUE,
            randomSeed = 123
          ) %>%
          visPhysics(
            solver = "forceAtlas2Based",
            forceAtlas2Based = list(
              gravitationalConstant = -50,
              centralGravity = 0.01,
              springLength = 100,
              springConstant = 0.05,
              avoidOverlap = 0.8
            ),
            stabilization = list(
              enabled = TRUE,
              iterations = 200,
              updateInterval = 50,
              fit = TRUE
            )
          ) %>%
          visOptions(
            highlightNearest = list(enabled = TRUE, hover = TRUE, degree = 1),
            nodesIdSelection = FALSE
          )
        # Modify network visualization settings for better quality
        network <- network %>%
          visEdges(
            smooth = list(enabled = TRUE, type = "dynamic", roundness = 0.5),
            scaling = list(min = 1, max = 4),  # Increased edge weight range
            shadow = FALSE,
            color = list(opacity = 0.8)  # Slightly reduced opacity for better contrast
          ) %>%
          visNodes(
            font = list(
              size = 24,  # Increased font size
              face = "arial",
              color = "#000000",  # Darker text color
              strokeWidth = 3,  # Increased stroke width
              strokeColor = "rgba(255,255,255,0.9)"  # More opaque stroke
            ),
            shadow = list(enabled = TRUE, size = 4, x = 2, y = 2),
            borderWidth = 2,
            borderWidthSelected = 4,
            scaling = list(min = 15, max = 45)  # Increased node size range
          )
        
        # Add color mapping for pathway nodes with more vibrant colors
        for(db in unique(all_results$Database)) {
          if(db %in% names(db_colors)) {
            col <- db_colors[db]
            network <- network %>%
              visGroups(
                groupname = db,
                color = list(
                  background = adjustcolor(col, alpha.f = 1),  # Full opacity
                  border = darken(col, 0.2),  # Less darkening
                  highlight = list(
                    background = lighten(col, 0.1),  # Less lightening
                    border = "#000000"
                  )
                ),
                shape = "box",
                shadow = TRUE
              )
          }
        }
        
        # Gene node styling with improved visibility
        if("gene" %in% nodes$group) {
          network <- network %>%
            visGroups(
              groupname = "gene",
              color = list(
                background = "#FF4444",  # More solid color
                border = "#CC0000",
                highlight = list(
                  background = "#FF6666",
                  border = "#000000"
                )
              ),
              shape = "dot"
            )
        }
        
        # Save with improved parameters
        visSave(network, temp_html, background = "white", selfcontained = TRUE)
        
        # Enhanced webshot parameters
        webshot::webshot(
          url = temp_html,
          file = temp_png,
          vwidth = 4000,    # Increased width
          vheight = 3500,   # Increased height
          delay = 50,       # Increased delay for better rendering
          zoom = 4,         # Increased zoom
          quality = 100     # Maximum quality
        )
        
        # Improved image processing
        img <- magick::image_read(temp_png)
        img <- magick::image_trim(img)
        img <- magick::image_border(img, "white", "100x100")  # Larger border
        
        # Enhanced title annotation
        img <- magick::image_annotate(
          img,
          paste("Network of Top", nrow(all_results), "Pathways -",
                format(Sys.Date(), "%B %d, %Y")),
          location = "+100+50",
          size = 36,  # Larger font size
          font = "Arial-Bold",  # Bold font
          color = "#000000"    # Pure black for better contrast
        )
        
        # Write PDF with higher density
        magick::image_write(
          img,
          path = file,
          format = "pdf",
          density = 450  # Increased density
        )
        
        suppressWarnings(file.remove(c(temp_html, temp_png)))
        removeNotification(id = notif_id)
        showNotification("PDF generated successfully!", type = "message", duration = 5)
        
      }, error = function(e) {
        removeNotification(id = notif_id)
        showNotification(paste("Error generating PDF:", e$message), type = "error", duration = 10)
        print(paste("Error details:", e$message))
        print(paste("Error call:", deparse(e$call)))
      })
    }
  )
  
  # Helper functions for color manipulation (add to global.R or server.R)
  darken <- function(color, factor = 0.2) {
    col <- col2rgb(color)
    col <- col * (1 - factor)
    rgb(t(col), maxColorValue = 255)
  }
  
  lighten <- function(color, factor = 0.2) {
    col <- col2rgb(color)
    col <- col + (255 - col) * factor
    rgb(t(col), maxColorValue = 255)
  }
  
  
  output$download_network_png_tcga <- downloadHandler(
    filename = function() {
      paste0("pathway_network_", format(Sys.time(), "%Y%m%d_%H%M%S"), ".png")
    },
    content = function(file) {
      load_export_packages()
      # Create temporary PDF
      temp_pdf <- tempfile(fileext = ".pdf")
      output$download_network_pdf$content(temp_pdf)
      
      # Convert to PNG with high resolution
      png(file, width = 3600, height = 3600, res = 300)
      
      # Read PDF and convert to PNG
      pdf_convert(temp_pdf,
                  format = "png",
                  dpi = 300,
                  filenames = file)
      
      # Clean up
      unlink(temp_pdf)
    }
  )
  
  
  
  
  # --- Box Plot Analysis Section ---
  # Reactive values for box plot analysis
  rv_boxplot <- reactiveValues(
    results = NULL,
    error_message = NULL,
    boxplot = NULL,
    boxplot_data = NULL
  )
  
  # Helper function to get gene ID from gene symbol
  get_gene_id <- function(tcga_data, gene_symbol) {
    gene_info <- as.data.frame(rowData(tcga_data))
    gene_row <- which(gene_info$gene_name == gene_symbol)
    if (length(gene_row) == 0) {
      stop(paste("Gene", gene_symbol, "not found"))
    }
    return(rownames(gene_info)[gene_row[1]])
  }
  
  observeEvent(input$analyze_box, {
    req(input$cancer_type_box, input$gene_name_box)

    rv_boxplot$error_message <- NULL

    withProgress(message = 'Analyzing Expression...', value = 0, {
      tryCatch({
        gene_symbol <- trimws(input$gene_name_box)

        # --- Try pre-computed compact data first (fast path: ~2-4s) ---
        compact_dir <- Sys.getenv("TCGA_PRECOMPUTED_PATH", "/srv/tcga_precomputed")
        compact_file <- file.path(compact_dir, paste0(input$cancer_type_box, "_compact.rds"))

        if (file.exists(compact_file)) {
          incProgress(0.3, detail = "Loading pre-computed data...")
          compact <- readRDS(compact_file)

          # Gene lookup
          row_idx <- compact$gene_to_row[gene_symbol]
          if (is.na(row_idx)) stop(paste("Gene", gene_symbol, "not found in dataset"))

          # Filter to Normal + Tumor samples
          valid_sample_types <- c("Solid Tissue Normal", "Primary solid Tumor")
          o <- order(compact$barcode)
          first_copy <- (!duplicated(substr(compact$barcode[o], 1, 15)))[order(o)]   # one sample per patient and type
          valid_mask <- compact$sample_type %in% valid_sample_types & first_copy

          expr_values <- compact$tpm[row_idx, valid_mask]
          sample_types <- compact$sample_type[valid_mask]

        } else {
          # --- Fallback to full SummarizedExperiment (slow path) ---
          incProgress(0.2, detail = "Loading TCGA data...")
          load_tcga_packages()
          data_dir <- "/srv/shinydata"
          file_path <- file.path(data_dir, paste0(input$cancer_type_box, ".RDS"))
          tcga_data <- readRDS(file_path)

          gene_id <- get_gene_id(tcga_data, gene_symbol)
          valid_sample_types <- c("Solid Tissue Normal", "Primary solid Tumor")
          o <- order(colnames(tcga_data))
          first_copy <- (!duplicated(substr(colnames(tcga_data)[o], 1, 15)))[order(o)]
          valid_samples <- tcga_data@colData$definition %in% valid_sample_types & first_copy
tcga_data_filtered <- tcga_data[, valid_samples]

          tcga <- as.data.frame(assay(tcga_data_filtered, "tpm_unstrand"))
          if (!(gene_id %in% rownames(tcga))) stop(paste("Gene ID", gene_id, "not found"))

          expr_values <- as.numeric(tcga[gene_id, ])
          sample_types <- tcga_data_filtered@colData$definition
        }

        incProgress(0.6, detail = "Building plot...")

        # Build expression data frame
        gene_expression <- data.frame(
          Expression = as.numeric(expr_values),
          SampleType = factor(sample_types, levels = valid_sample_types),
          stringsAsFactors = FALSE
        )
        gene_expression <- gene_expression[!is.na(gene_expression$Expression), ]

        # Check sample sizes
        counts <- table(gene_expression$SampleType)
        if (length(counts) != 2 || any(counts < 2)) {
          stop(paste0("This cohort has too few samples to compare (", paste(names(counts), "=", counts, collapse = ", "),
                      "); at least 2 normal and 2 tumour samples are needed."))
        }

        # Log transform
        gene_expression$log2_expression <- log2(gene_expression$Expression + 1)
        
        # Create boxplot
        p <- ggplot(gene_expression,
                    aes(x = SampleType,
                        y = log2_expression,
                        fill = SampleType)) +
          geom_boxplot(outlier.shape = NA) +
          geom_jitter(width = 0.2, size = 2, alpha = 0.5) +
          scale_fill_manual(values = c("lightblue", "salmon")) +
          theme_minimal() +
          labs(title = paste(input$gene_name_box, "Expression in", input$cancer_type_box),
               subtitle = paste("Normal =", counts["Solid Tissue Normal"],
                                "samples, Tumor =", counts["Primary solid Tumor"], "samples"),
               x = "Sample Type",
               y = "Expression log2(TPM + 1)") +
          theme(
            legend.position = "none",
            plot.title = element_text(size = 16, face = "bold"),
            plot.subtitle = element_text(size = 12),
            axis.title = element_text(size = 14),
            axis.text = element_text(size = 12, face = "bold"),
            panel.grid.major.x = element_blank()
          )
        
        # Perform t-test
        stat_test <- t.test(log2_expression ~ SampleType, data = gene_expression)
        p <- p + annotate(
          "text",
          x = 1.5,
          y = max(gene_expression$log2_expression),
          label = paste("p-value =", format(stat_test$p.value, scientific = TRUE, digits = 3)),
          size = 4
        )
        
        # Store results
        rv_boxplot$boxplot <- p
        rv_boxplot$boxplot_data <- gene_expression
        
      }, error = function(e) {
        rv_boxplot$error_message <- paste("Error:", e$message)
      })
    })
  })
  
  
  # --- Box Plot Outputs ---
  output$expression_boxplot <- renderPlot({
    req(rv_boxplot$boxplot)
    rv_boxplot$boxplot
  }, res = 96, height = function() {
    session$clientData$output_expression_boxplot_width * 0.75
  })
  
  output$download_boxplot <- downloadHandler(
    filename = function() {
      paste0(input$cancer_type_box, "_", input$gene_name_box, "_boxplot.png")
    },
    content = function(file) {
      load_export_packages()
      req(rv_boxplot$boxplot)
      ggsave(file,
             plot = rv_boxplot$boxplot,
             width = 10,
             height = 8,
             dpi = 300,
             bg = "white")
    }
  )
  
  output$summary_text_box <- renderText({
    if (!is.null(rv_boxplot$error_message)) {
      return(rv_boxplot$error_message)
    }
    # Add other summary information if successful, e.g.,
    # paste("Analysis completed for", input$gene_name_box, "in", input$cancer_type_box)
  })
  
  output$group_sizes_box <- renderTable({
    req(rv_boxplot$boxplot_data)
    rv_boxplot$boxplot_data %>%
      group_by(SampleType) %>%
      summarise(Count = n())
  })
  
  output$detailed_stats_box <- renderPrint({
    req(rv_boxplot$boxplot_data)
    t.test(log2_expression ~ SampleType, data = rv_boxplot$boxplot_data)
  })
  
  
  
  
  # --- Survival Analysis Section ---
  # Reactive values to store results
  rv_survival <- reactiveValues(
    results = NULL,
    error_message = NULL
  )
  
  # Main analysis function triggered by the analyze button
  observeEvent(input$analyze, {
    load_survival_packages()

    req(input$cancer_type, input$gene_name)

    rv_survival$error_message <- NULL

    withProgress(message = 'Analyzing...', value = 0, {

      tryCatch({
        gene_symbol <- trimws(input$gene_name)

        # --- Try pre-computed compact data first (fast path) ---
        compact_dir <- Sys.getenv("TCGA_PRECOMPUTED_PATH", "/srv/tcga_precomputed")
        compact_file <- file.path(compact_dir, paste0(input$cancer_type, "_compact.rds"))

        if (file.exists(compact_file)) {
          incProgress(0.2, detail = "Loading pre-computed data...")
          compact <- readRDS(compact_file)

          # Gene lookup
          row_idx <- compact$gene_to_row[gene_symbol]
          if (is.na(row_idx)) stop(paste("Gene", gene_symbol, "not found in dataset"))

          # Extract expression for this gene
          expr_values <- compact$tpm[row_idx, ]

          # Build clinical data
          cli_tcga <- data.frame(
            vital_status = compact$vital_status,
            days_to_death = compact$days_to_death,
            days_to_last_follow_up = compact$days_to_follow_up,
            stringsAsFactors = FALSE
          )
          cli_tcga$deceased <- ifelse(cli_tcga$vital_status == "Dead", TRUE,
                                      ifelse(cli_tcga$vital_status == "Alive", FALSE, NA))   # "Not Reported" = missing
          cli_tcga$overall_survival <- ifelse(
            cli_tcga$vital_status == "Alive",
            cli_tcga$days_to_last_follow_up,
            cli_tcga$days_to_death
          )
          cli_tcga$submitter_id <- gsub('-01.*', '', compact$barcode)

          # Build gene expression data frame
          tcga_gene_df <- data.frame(
            case_id = gsub('-01.*', '', compact$barcode),
            counts = as.numeric(expr_values),
            stringsAsFactors = FALSE
          )
          tcga_gene_df$log2_counts <- log2(tcga_gene_df$counts + 1)
          tcga_gene_df$gene_name <- gene_symbol
          tcga_gene_df$strata <- ifelse(tcga_gene_df$counts > median(tcga_gene_df$counts), "HIGH", "LOW")
          sample_barcodes <- compact$barcode

        } else {
          # --- Fallback to full SummarizedExperiment ---
          incProgress(0.2, detail = "Loading TCGA data...")
          load_tcga_packages()

          data_dir <- "/srv/shinydata"
          file_path <- file.path(data_dir, paste0(input$cancer_type, ".RDS"))
          tcga_data <- readRDS(file_path)

          cli_tcga <- as.data.frame(colData(tcga_data))
          cli_tcga <- cli_tcga %>%
            mutate(
              deceased = ifelse(vital_status == "Dead", TRUE, ifelse(vital_status == "Alive", FALSE, NA)),
              overall_survival = ifelse(vital_status == "Alive", days_to_last_follow_up, days_to_death),
              submitter_id = gsub('-01.*', '', rownames(cli_tcga))
            )

          gene_info <- as.data.frame(rowData(tcga_data))
          gene_index <- which(gene_info$gene_name == gene_symbol)
          if (length(gene_index) == 0) stop(paste("Gene", gene_symbol, "not found in dataset"))

          gene_expression <- assay(tcga_data, "tpm_unstrand")[gene_index, , drop = FALSE]
          sample_barcodes <- colnames(tcga_data)
          tcga_gene_df <- as.data.frame(t(gene_expression)) %>%
            rownames_to_column("case_id") %>%
            rename(counts = colnames(.)[2]) %>%
            mutate(
              log2_counts = log2(counts + 1),
              case_id = gsub('-01.*', '', case_id),
              gene_name = gene_symbol,
              strata = ifelse(counts > median(counts), "HIGH", "LOW")
            )
        }

        incProgress(0.6, detail = "Performing survival analysis...")
        
        
        
        # One row per patient: primary tumour samples only (TCGA sample type 01, or 03 for
        # primary blood-derived cancers such as LAML), first aliquot per patient. Normal,
        # metastatic and recurrent samples are excluded so the median split and the
        # survival model count each patient exactly once.
        sample_type <- substr(sample_barcodes, 14, 15)
        primary_code <- if (any(sample_type == "01")) "01" else if (any(sample_type == "03")) "03" else NA
        if (is.na(primary_code)) stop("No primary tumour samples found in this cohort")
        per_patient <- data.frame(
          barcode = sample_barcodes,
          case_id = substr(sample_barcodes, 1, 12),
          counts = as.numeric(tcga_gene_df$counts),
          deceased = cli_tcga$deceased,
          overall_survival = as.numeric(cli_tcga$overall_survival),
          stringsAsFactors = FALSE
        )
        per_patient <- per_patient[sample_type == primary_code, ]
        per_patient <- per_patient[order(per_patient$barcode), ]
        per_patient <- per_patient[!duplicated(per_patient$case_id), ]
        per_patient$log2_counts <- log2(per_patient$counts + 1)
        per_patient$gene_name <- gene_symbol
        per_patient$strata <- factor(ifelse(per_patient$counts > median(per_patient$counts), "HIGH", "LOW"),
                                     levels = c("LOW", "HIGH"))  # LOW = reference: HR is HIGH vs LOW
        tcga_gene_df <- per_patient

        analysis_data <- per_patient %>%
          filter(!is.na(overall_survival),
                 !is.na(deceased),
                 !is.na(strata))
        if (length(unique(analysis_data$strata)) < 2) {
          stop(paste(gene_symbol, "has the same expression in at least half of the patients (often zero), so they cannot be split into HIGH and LOW groups at the median"))
        }
        if (sum(analysis_data$deceased) == 0) {
          stop("No deaths are recorded among this cohort's patients with follow-up, so survival cannot be compared")
        }

        
        
        # Survival analysis
        
        cox_model <- coxph(Surv(overall_survival, deceased) ~ strata,
                           
                           data = analysis_data)
        
        
        
        fit <- survfit(Surv(overall_survival, deceased) ~ strata,
                       
                       data = analysis_data)
        
        
        
        logrank_test <- survdiff(Surv(overall_survival, deceased) ~ strata,
                                 
                                 data = analysis_data)
        
        
        
        # Store results
        
        rv_survival$results <- list(
          analysis_data = analysis_data,
          cox_model = cox_model,
          fit = fit,
          logrank_test = logrank_test,
          expression_data = tcga_gene_df,
          group_sizes = table(analysis_data$strata),
          gene_name = gene_symbol,
          cancer_type = input$cancer_type
        )
        
        
        
        incProgress(1, detail = "Done!")
        
        
        
      }, error = function(e) {
        
        rv_survival$error_message <- paste("Error:", e$message)
        
      })
      
    })
    
  })
  
  # Render summary text
  output$summary_text <- renderText({
    if (!is.null(rv_survival$error_message)) {
      return(rv_survival$error_message)
    }
    if (is.null(rv_survival$results)) {
      return("Click 'Analyze Survival' to begin analysis")
    }
    
    hr <- exp(coef(rv_survival$results$cox_model))
    hr_ci <- summary(rv_survival$results$cox_model)$conf.int[, c(3, 4)]
    logrank_p <- 1 - pchisq(rv_survival$results$logrank_test$chisq, df = 1)
    
    paste0(
      "Analysis Results for ", rv_survival$results$gene_name, " in ", rv_survival$results$cancer_type, "\n",
      "Hazard Ratio (HIGH vs LOW): ", round(hr, 2),
      " (95% CI: ", round(hr_ci[1], 2), "-", round(hr_ci[2], 2), ")\n",
      "Log-rank P-value: ", format(logrank_p, scientific = TRUE, digits = 2)
    )
  })
  
  # Render group sizes
  output$group_sizes <- renderTable({
    req(rv_survival$results)
    data.frame(
      Expression = names(rv_survival$results$group_sizes),
      Patients = as.numeric(rv_survival$results$group_sizes)
    )
  })
  
  # Render survival plot
  output$survival_plot <- renderPlot({
    req(rv_survival$results)
    if (!requireNamespace("ggfortify", quietly = TRUE)) library(ggfortify)

    hr <- exp(coef(rv_survival$results$cox_model))
    hr_ci <- summary(rv_survival$results$cox_model)$conf.int[, c(3, 4)]
    logrank_p <- 1 - pchisq(rv_survival$results$logrank_test$chisq, df = 1)
    
    p <- autoplot(rv_survival$results$fit,
                  surv.geom = "step",
                  conf.int = TRUE,
                  conf.int.alpha = 0.1,
                  censor = TRUE,
                  color = "strata") +
      labs(x = "Time (days)",
           y = "Survival Probability",
           color = paste(rv_survival$results$gene_name, "Expression"),
           caption = paste("n =", nrow(rv_survival$results$analysis_data),
                           "patients (", sum(rv_survival$results$analysis_data$deceased), "events)")) +
      theme_minimal() +
      theme(legend.position = "top",
            # Improve text scaling
            axis.title = element_text(size = rel(1.2)),
            axis.text = element_text(size = rel(1.1)),
            legend.text = element_text(size = rel(1.1)),
            legend.title = element_text(size = rel(1.2)),
            plot.title = element_text(size = rel(1.4)),
            plot.subtitle = element_text(size = rel(1.1))) +
      ggtitle(paste(rv_survival$results$gene_name, "Expression and Overall Survival"),
              subtitle = paste0("HR (HIGH vs LOW) = ", round(hr, 2),
                                " (95% CI: ", round(hr_ci[1], 2), "-",
                                round(hr_ci[2], 2), ")",
                                "\nLog-rank P = ",
                                format(logrank_p, scientific = TRUE, digits = 2)))
    
    # Store the plot in reactive values for download
    rv_survival$survival_plot <- p
    return(p)
  }, res = 96, height = function() {
    session$clientData$output_survival_plot_width * 0.75
  })
  
  # Render expression distribution with improved resolution
  output$expr_dist <- renderPlot({
    req(rv_survival$results)
    p <- ggplot(rv_survival$results$expression_data, aes(x = counts)) +
      geom_histogram(bins = 30, fill = "lightblue", color = "black") +
      geom_vline(xintercept = median(rv_survival$results$expression_data$counts),
                 color = "red", linetype = "dashed") +
      scale_x_log10() +
      labs(title = paste(rv_survival$results$gene_name, "Expression Distribution"),
           x = "Expression (TPM, log10 scale)",
           y = "Frequency") +
      theme_minimal() +
      theme(axis.title = element_text(size = rel(1.2)),
            axis.text = element_text(size = rel(1.1)),
            plot.title = element_text(size = rel(1.4)))
    
    # Store the plot in reactive values for download
    rv_survival$expr_dist_plot <- p
    return(p)
  }, res = 96, height = function() {
    session$clientData$output_expr_dist_width * 0.6
  })
  
  # Render detailed statistics
  output$detailed_stats <- renderPrint({
    req(rv_survival$results)
    summary(rv_survival$results$cox_model)
  })
  
  # Fixed download handlers for plots
  output$download_survival <- downloadHandler(
    filename = function() {
      paste0(rv_survival$results$cancer_type %||% input$cancer_type, "_", rv_survival$results$gene_name %||% input$gene_name, "_survival.png")
    },
    content = function(file) {
      load_export_packages()
      req(rv_survival$survival_plot)
      ggsave(file,
             plot = rv_survival$survival_plot,
             width = 10,
             height = 8,
             dpi = 300,
             bg = "white")
    }
  )
  
  output$download_dist <- downloadHandler(
    filename = function() {
      paste0(rv_survival$results$cancer_type %||% input$cancer_type, "_", rv_survival$results$gene_name %||% input$gene_name, "_expression.png")
    },
    content = function(file) {
      load_export_packages()
      req(rv_survival$expr_dist_plot)
      ggsave(file,
             plot = rv_survival$expr_dist_plot,
             width = 10,
             height = 6,
             dpi = 300,
             bg = "white")
    }
  )
  
  #------------------------------------------GSEA --------------------------------------
  
  # Server-side logic for GSEA pathway analysis
  # Load required libraries in your global.R file:
  # library(shiny)
  # library(DT)
  # library(clusterProfiler)
  # library(enrichplot)
  # library(ReactomePA)
  # library(ggplot2)
  # library(fgsea)
  # library(DOSE)
  # library(org.Hs.eg.db)
  # library(org.Mm.eg.db)
  # library(org.Rn.eg.db)
  # library(org.Dr.eg.db)
  # library(org.Dm.eg.db)
  # library(org.Ce.eg.db)
  # library(org.Sc.sgd.db)
  # library(org.At.tair.db)
  # library(org.Ss.eg.db)
  # library(org.Gg.eg.db)
  # library(visNetwork)
  # library(dplyr)
  # library(tidyr)
  # library(pathview)
  
  # Server function for GSEA
  # Reactive values to store analysis results
  gsea_results <- reactiveVal(NULL)
  gene_list <- reactiveVal(NULL)
  analysis_complete <- reactiveVal(FALSE)  # Add this new reactive value
  
  
  #GSEA Unified Analysis
  
  # 1. Reactive values to store GSEA state
  rv_gsea <- reactiveValues(
    raw_data = NULL,
    column_names = NULL,
    ranked_gene_list = NULL,
    user_selections = NULL
  )
  
  # 2. Observer for File Input: Reads header and triggers the column selection modal
  observeEvent(input$prerankedFile %OR% input$expressionFile, {
    
    # Determine which file input was used
    file_input <- if (!is.null(input$prerankedFile)) {
      input$prerankedFile
    } else {
      input$expressionFile
    }
    req(file_input)
    
    tryCatch({
      # --- START OF NEW ROBUST FILE READING LOGIC ---
      
      inFile <- file_input
      file_ext <- tolower(tools::file_ext(inFile$name))
      header_choice <- if (!is.null(input$headerPreranked)) input$headerPreranked else TRUE
      
      print(paste("Reading file:", inFile$name, "with extension:", file_ext))
      
      # Read data based on file type
      if (file_ext == "rnk") {
        print("Detected .rnk file. Reading as tab-separated with NO header.")
        data <- read.delim(inFile$datapath, header = FALSE, sep = "\t")
      } else if (file_ext == "csv") {
        print("Detected .csv file. Using header choice.")
        data <- read.csv(inFile$datapath, header = header_choice, sep = ",")
      } else if (file_ext == "tsv") {
        print("Detected .tsv file. Using header choice.")
        data <- read.delim(inFile$datapath, header = header_choice, sep = "\t")
      } else if (file_ext == "txt") {
        print("Detected .txt file. Auto-detecting separator...")
        # Peek at the first line to determine the separator
        first_line <- readLines(inFile$datapath, n = 1)
        if (grepl("\t", first_line)) {
          print("-> Detected TAB separator for .txt file.")
          data <- read.delim(inFile$datapath, header = header_choice, sep = "\t")
        } else {
          print("-> Assuming COMMA separator for .txt file.")
          data <- read.csv(inFile$datapath, header = header_choice, sep = ",")
        }
      } else {
        stop(paste("Unsupported file type:", file_ext))
      }
      
      # --- END OF NEW FILE READING LOGIC ---
      
      rv_gsea$raw_data <- data
      rv_gsea$column_names <- colnames(data)
      
      # --- Show the Column Selection Modal (this part remains the same) ---
      output$gsea_column_selector_modal_ui <- renderUI({
        showModal(modalDialog(
          title = "Confirm Data Columns",
          size = "l",
          
          div(class="alert alert-info",
              p(icon("info-circle"), " Please verify the columns containing your gene IDs and the metric for ranking.")
          ),
          
          fluidRow(
            column(6,
                   selectInput("gsea_gene_col", "Select Gene ID Column:",
                               choices = rv_gsea$column_names,
                               selected = rv_gsea$column_names[1])
            ),
            column(6,
                   selectInput("gsea_metric_col", "Select Ranking Metric Column:",
                               choices = rv_gsea$column_names,
                               selected = rv_gsea$column_names[2])
            )
          ),
          
          # Add special handling for p-values
          conditionalPanel(
            condition = "input.rankMethod == 'pvalue' && input.inputType == 'expression'",
            radioButtons("gsea_pval_direction", "For P-values, smaller values are:",
                         choices = c("Better (e.g., p-value, FDR)" = "smaller_is_better",
                                     "Worse (e.g., -log10(p))" = "larger_is_better"),
                         selected = "smaller_is_better")
          ),
          
          h5("Data Preview"),
          DT::renderDataTable({
            DT::datatable(head(rv_gsea$raw_data, 5), options = list(dom='t', searching=FALSE, ordering=FALSE))
          }),
          
          footer = tagList(
            modalButton("Cancel"),
            actionButton("confirm_gsea_columns", "Confirm and Prepare Data", class = "btn-primary")
          )
        ))
      })
      
    }, error = function(e) {
      showNotification(paste("Error reading file:", e$message), type = "error")
    })
  }, ignoreNULL = TRUE)
  
  # 3. Observer for Column Confirmation: Processes the data based on user selection
  observeEvent(input$confirm_gsea_columns, {
    req(rv_gsea$raw_data, input$gsea_gene_col, input$gsea_metric_col)
    
    withProgress(message = 'Preparing gene list...', value = 0.5, {
      tryCatch({
        data <- rv_gsea$raw_data
        gene_col <- input$gsea_gene_col
        metric_col <- input$gsea_metric_col
        
        # Extract data and remove NAs
        ranked_df <- data.frame(
          gene = data[[gene_col]],
          metric = as.numeric(data[[metric_col]])
        )
        ranked_df <- ranked_df[!is.na(ranked_df$metric) & !is.na(ranked_df$gene) & ranked_df$gene != "",]
        
        # Handle duplicate genes by keeping the one with the most extreme metric value
        ranked_df <- ranked_df %>%
          group_by(gene) %>%
          slice_max(abs(metric), n = 1, with_ties = FALSE) %>%
          ungroup()
        
        # Transform p-values if necessary
        if (input$inputType == 'expression' && input$rankMethod == 'pvalue' && input$gsea_pval_direction == 'smaller_is_better') {
          ranked_df$metric <- -log10(ranked_df$metric + 1e-10) # Add small value to avoid log(0)
        }
        
        # Create the final named, sorted vector
        final_gene_list <- setNames(ranked_df$metric, ranked_df$gene)
        final_gene_list <- sort(final_gene_list, decreasing = TRUE)
        
        rv_gsea$ranked_gene_list <- final_gene_list
        rv_gsea$user_selections <- list(gene_col=gene_col, metric_col=metric_col)
        
        removeModal()
        showNotification("Data prepared successfully! You can now run the analysis.", type="message")
        
      }, error = function(e) {
        showNotification(paste("Error preparing data:", e$message), type="error")
      })
    })
  })
  
  # 4. UI output to show data summary on the main page
  output$gsea_data_summary_ui <- renderUI({
    if (is.null(rv_gsea$ranked_gene_list)) {
      return(p("No data loaded. Please upload a file.", style="color:#6c757d;"))
    }
    
    tagList(
      p(strong("File Loaded:"), " ", nrow(rv_gsea$raw_data), " total rows"),
      p(strong("Gene Column:"), " ", rv_gsea$user_selections$gene_col),
      p(strong("Metric Column:"), " ", rv_gsea$user_selections$metric_col),
      p(strong("Ranked Genes:"), " ", length(rv_gsea$ranked_gene_list), " unique genes prepared for analysis")
    )
  })
  
  # Get organism-specific database
  getOrganismDb <- reactive({
    switch(input$organism,
           "hsapiens" = "org.Hs.eg.db",
           "mmusculus" = "org.Mm.eg.db",
           "rnorvegicus" = "org.Rn.eg.db",
           "drerio" = "org.Dr.eg.db",
           "dmelanogaster" = "org.Dm.eg.db",
           "celegans" = "org.Ce.eg.db",
           "scerevisiae" = "org.Sc.sgd.db",
           "athaliana" = "org.At.tair.db",
           "sscrofa" = "org.Ss.eg.db",
           "ggallus" = "org.Gg.eg.db",
           "org.Hs.eg.db") # Default to human
  })
  
  # 1. DISABLE UNSUPPORTED DATABASE OPTIONS
  observe({
    req(input$organism)
    
    organism_info <- getOrganismMapping(input$organism)
    supported_dbs <- organism_info$supported_dbs
    
    # Enable/disable database choices based on organism support
    # This uses shinyjs - make sure you have library(shinyjs) in your global.R
    # and useShinyjs() in your UI
    
    all_db_choices <- c("kegg", "reactome", "wiki", "go_bp", "go_mf", "go_cc")
    
    for (db in all_db_choices) {
      if (db %in% supported_dbs) {
        shinyjs::enable(paste0("pathway_databases_gsea-", db))
      } else {
        shinyjs::disable(paste0("pathway_databases_gsea-", db))
      }
    }
  })
  
  # 2. UPDATE PATHWAY CHOICES FOR PLOTTING
  observe({
    req(gsea_results())
    results <- gsea_results()
    
    if (!"Message" %in% colnames(results) && !"Error" %in% colnames(results)) {
      pathway_choices <- setNames(results$Description, results$Description)
      updateSelectInput(session, "pathwayToPlot", choices = pathway_choices)
    }
  })
  
  
  # ENHANCED BATCH CONVERSION WITH CACHING
  convertEntrezBatchCached <- function(entrez_list, organism_db) {
    # Create hash of gene list for caching
    gene_list_hash <- digest::digest(entrez_list, algo = "md5")
    
    # Try to get from cache first
    cached_result <- getCachedConversion(organism_db, gene_list_hash)
    if (!is.null(cached_result)) {
      return(cached_result)
    }
    
    # If not cached, do the conversion
    print("Performing new gene conversion (will be cached)")
    conversion_start_time <<- Sys.time()
    
    result <- convertEntrezBatch(entrez_list, organism_db)
    
    # Store in cache
    storeCachedConversion(organism_db, gene_list_hash, result)
    
    return(result)
  }
  
  # 3. ENHANCED PLOTTING FUNCTION
  output$gsea_plot <- renderPlot({
    req(gsea_results(), input$plotType)
    
    results <- gsea_results()
    if ("Message" %in% colnames(results) || "Error" %in% colnames(results)) {
      return(NULL)
    }
    
    tryCatch({
      if (input$plotType == "enrichment") {
        req(input$pathwayToPlot, rv_gsea$ranked_gene_list)
        
        withProgress(message = 'Creating professional enrichment plot...', value = 0, {
          
          incProgress(0.2, detail = "Finding pathway...")
          
          # Find the selected pathway
          selected_pathway <- results[results$Description == input$pathwayToPlot, ]
          if (nrow(selected_pathway) == 0) {
            # Create a professional "no pathway selected" plot
            par(bg = "white", mar = c(2, 2, 2, 2))
            plot(1, type = "n", axes = FALSE, xlab = "", ylab = "",
                 xlim = c(0, 10), ylim = c(0, 10))
            
            # Add a nice background
            rect(0, 0, 10, 10, col = "#f8f9fa", border = NA)
            
            # Add informative text
            text(5, 6, "Please select a pathway",
                 cex = 1.8, font = 2, col = "#495057")
            text(5, 4, "from the dropdown menu above",
                 cex = 1.3, col = "#6c757d")
            
            # Add an arrow pointing up
            arrows(5, 3, 5, 2, col = "#007bff", lwd = 3, length = 0.2)
            
            return()
          }
          
          # Get the original ranked gene list
          ranked_genes <- rv_gsea$ranked_gene_list
          pathway_genes_string <- selected_pathway$core_enrichment[1]
          
          if (is.na(pathway_genes_string) || pathway_genes_string == "") {
            # Professional "no gene data" plot
            par(bg = "white", mar = c(2, 2, 2, 2))
            plot(1, type = "n", axes = FALSE, xlab = "", ylab = "",
                 xlim = c(0, 10), ylim = c(0, 10))
            rect(0, 0, 10, 10, col = "#fff3cd", border = NA)
            text(5, 6, "No gene data available",
                 cex = 1.8, font = 2, col = "#856404")
            text(5, 4, "for this pathway",
                 cex = 1.3, col = "#856404")
            return()
          }
          
          incProgress(0.4, detail = "Matching genes...")
          
          # Get organism database
          organism_db <- getOrganismMapping(input$organism)$db_mapping$db
          
          # Use optimized gene matching
          pathway_positions <- optimizedGeneMatching(ranked_genes, pathway_genes_string, organism_db)
          
          if (length(pathway_positions) == 0) {
            # Professional "gene mismatch" plot
            par(bg = "white", mar = c(2, 2, 2, 2))
            plot(1, type = "n", axes = FALSE, xlab = "", ylab = "",
                 xlim = c(0, 10), ylim = c(0, 10))
            rect(0, 0, 10, 10, col = "#f8d7da", border = NA)
            text(5, 7, "Gene ID Format Mismatch",
                 cex = 1.6, font = 2, col = "#721c24")
            text(5, 5.5, "Pathway genes not found in ranked list",
                 cex = 1.1, col = "#721c24")
            text(5, 4, "Try a different pathway or check",
                 cex = 1.0, col = "#721c24")
            text(5, 3.5, "your gene ID format",
                 cex = 1.0, col = "#721c24")
            return()
          }
          
          incProgress(0.4, detail = "Creating professional GSEA plot...")
          
          print(paste("Creating professional plot with", length(pathway_positions), "pathway genes"))
          
          # Create the professional GSEA enrichment plot
          createInteractiveGSEAPlot(ranked_genes, pathway_positions,
                                    selected_pathway$Description[1],
                                    selected_pathway$NES[1],
                                    selected_pathway$pvalue[1])
          
        }) # End withProgress
        
      } else if (input$plotType == "dotplot") {
        req(input$numPathwaysToShow)
        
        # IMPROVED DOT PLOT - Color by significance, size by gene count
        plot_data <- results %>%
          arrange(p.adjust) %>%
          head(input$numPathwaysToShow) %>%
          mutate(
            log10p = -log10(p.adjust),
            Direction = ifelse(NES > 0, "Upregulated", "Downregulated"),
            # Add database ID in brackets
            pathway_display = paste0(Description, " [", Database, "]"),
            pathway_short = ifelse(nchar(pathway_display) > 80,
                                   paste0(substr(pathway_display, 1, 77), "..."),
                                   pathway_display)
          )
        
        ggplot(plot_data, aes(x = NES, y = reorder(pathway_short, log10p))) +
          geom_point(aes(size = setSize, color = log10p), alpha = 0.8) +
          # CHANGED: Color by significance gradient (like traditional GSEA plots)
          scale_color_gradient2(
            low = "blue",
            mid = "white",
            high = "red",
            midpoint = median(plot_data$log10p),
            name = "-log10\n(adj. p-val)"
          ) +
          scale_size_continuous(name = "Gene Count", range = c(3, 8)) +
          geom_vline(xintercept = 0, linetype = "dashed", alpha = 0.7, color = "gray50") +
          labs(
            title = paste("Top", input$numPathwaysToShow, "GSEA Pathways"),
            subtitle = "Database in brackets • Color = significance • Size = gene count",
            x = "Normalized Enrichment Score (NES)",
            y = "Pathway"
          ) +
          theme_minimal() +
          theme(
            axis.text.y = element_text(size = 11),
            plot.title = element_text(face = "bold", size = 14),
            plot.subtitle = element_text(size = 11, color = "gray60"),
            legend.position = "right",
            panel.grid.major.y = element_line(color = "gray90", linetype = "dotted"),
            panel.grid.minor = element_blank()
          ) +
          guides(
            color = guide_colorbar(title = "-log10\n(adj. p-val)",
                                   title.position = "top",
                                   barwidth = 1,
                                   barheight = 8),
            size = guide_legend(title = "Gene Count",
                                title.position = "top")
          )
        
      } else if (input$plotType == "barplot") {
        req(input$numPathwaysToShow)
        
        # IMPROVED BAR PLOT - Color by up/down regulation
        plot_data <- results %>%
          arrange(p.adjust) %>%
          head(input$numPathwaysToShow) %>%
          mutate(
            log10p = -log10(p.adjust),
            Direction = ifelse(NES > 0, "Upregulated", "Downregulated"),
            # Add database ID in brackets
            pathway_display = paste0(Description, " [", Database, "]"),
            pathway_short = ifelse(nchar(pathway_display) > 80,
                                   paste0(substr(pathway_display, 1, 77), "..."),
                                   pathway_display)
          )
        
        ggplot(plot_data, aes(x = reorder(pathway_short, log10p), y = log10p)) +
          # CHANGED: Color by regulation direction (up/down)
          geom_col(aes(fill = Direction), alpha = 0.8, width = 0.7) +
          scale_fill_manual(
            values = c("Upregulated" = "#d73027", "Downregulated" = "#4575b4"),
            name = "Regulation"
          ) +
          coord_flip() +
          labs(
            title = paste("Top", input$numPathwaysToShow, "GSEA Pathways"),
            subtitle = "Database in brackets • Color = regulation direction • Height = significance",
            x = "Pathway",
            y = "-log10(Adjusted P-value)"
          ) +
          theme_minimal() +
          theme(
            axis.text.y = element_text(size = 11),
            plot.title = element_text(face = "bold", size = 14),
            plot.subtitle = element_text(size = 11, color = "gray60"),
            legend.position = "bottom",
            panel.grid.major.x = element_line(color = "gray90", linetype = "dotted"),
            panel.grid.minor = element_blank()
          ) +
          guides(
            fill = guide_legend(title = "Regulation Direction", nrow = 1)
          )
      }
      
    }, error = function(e) {
      print(paste("Plot error:", e$message))
      plot(1, type = "n", axes = FALSE, xlab = "", ylab = "")
      text(1, 1, paste("Plot error:", e$message), cex = 1.2, col = "red")
    })
  }, height = 600)
  
  observe({
    # Monitor when gene conversion processes start/end
    if (exists("conversion_start_time")) {
      conversion_time <- Sys.time() - conversion_start_time
      if (conversion_time > 5) {  # If taking more than 5 seconds
        showNotification(
          paste("Gene conversion completed in", round(conversion_time, 1), "seconds"),
          type = "message", duration = 3
        )
      }
    }
  })
  
  # ALSO ADD A REACTIVE TO CACHE CONVERSIONS
  gene_conversion_cache <- reactiveVal(list())
  
  # Function to get cached conversions or create new ones
  getCachedConversion <- function(organism, gene_list_hash) {
    cache <- gene_conversion_cache()
    cache_key <- paste(organism, gene_list_hash, sep = "_")
    
    if (cache_key %in% names(cache)) {
      print("Using cached gene conversion")
      return(cache[[cache_key]])
    } else {
      return(NULL)
    }
  }
  
  # Function to store conversions in cache
  storeCachedConversion <- function(organism, gene_list_hash, conversion_lookup) {
    cache <- gene_conversion_cache()
    cache_key <- paste(organism, gene_list_hash, sep = "_")
    cache[[cache_key]] <- conversion_lookup
    
    # Keep cache size reasonable (max 5 entries)
    if (length(cache) > 5) {
      cache <- cache[1:5]
    }
    
    gene_conversion_cache(cache)
  }
  
  
  createInteractiveGSEAPlot <- function(ranked_genes, pathway_positions, pathway_name, nes, pvalue) {
    
    # Load required library
    library(patchwork)
    
    # --- 1. Data Preparation ---
    gene_scores <- as.numeric(ranked_genes)
    n_genes <- length(gene_scores)
    
    # Create a data frame for the main plot
    plot_data <- data.frame(
      rank = 1:n_genes,
      score = gene_scores
    )
    
    # Calculate running ES score
    increment_hit <- (abs(plot_data$score[pathway_positions]) / sum(abs(plot_data$score[pathway_positions])))
    increment_miss <- 1 / (n_genes - length(pathway_positions))
    
    running_es_values <- numeric(n_genes)
    es_temp <- 0
    
    hit_indicator <- rep(0, n_genes)
    hit_indicator[pathway_positions] <- increment_hit
    
    miss_indicator <- rep(increment_miss, n_genes)
    miss_indicator[pathway_positions] <- 0
    
    running_es_values <- cumsum(hit_indicator - miss_indicator)
    
    es_data <- data.frame(rank = 1:n_genes, es = running_es_values)
    
    # Find max ES
    max_es_pos <- which.max(abs(es_data$es))
    max_es <- es_data$es[max_es_pos]
    
    # --- 2. Define Colors and Fonts ---
    es_color <- ifelse(nes > 0, "#d73027", "#313695")
    
    # Increase the base font size for better readability
    base_font_size <- 14
    
    # --- 3. Create the Three Plots using ggplot2 ---
    
    # PLOT 1: Enrichment Score
    p_es <- ggplot(es_data, aes(x = rank, y = es)) +
      geom_line(color = es_color, size = 1.5) +
      geom_hline(yintercept = 0, color = "gray50", linetype = "dashed") +
      geom_vline(xintercept = max_es_pos, color = es_color, linetype = "dotted", size = 1) +
      geom_point(x = max_es_pos, y = max_es, color = es_color, size = 4, shape = 19) +
      labs(
        title = ifelse(nchar(pathway_name) > 70,
                       paste0(substr(pathway_name, 1, 67), "..."),
                       pathway_name),
        subtitle = paste0("NES = ", round(nes, 3), "  •  P-value = ", formatC(pvalue, format = "e", digits = 2)),
        y = "Enrichment Score (ES)"
      ) +
      theme_minimal(base_size = base_font_size) +
      theme(
        axis.title.x = element_blank(),
        axis.text.x = element_blank(),
        plot.title = element_text(face = "bold", size = rel(1.0)),
        plot.subtitle = element_text(size = rel(0.9), color = "gray30"),
        panel.grid.minor = element_blank()
      )
    
    # PLOT 2: Gene Hits (Barcode)
    p_hits <- ggplot(data.frame(pos = pathway_positions), aes(x = pos)) +
      geom_segment(aes(xend = pos, y = 0, yend = 1), color = "#2c7fb8", size = 0.8) +
      xlim(0, n_genes) +
      labs(y = "Gene Hits") +
      theme_minimal(base_size = base_font_size) +
      theme(
        axis.title.x = element_blank(),
        axis.text.x = element_blank(),
        axis.text.y = element_blank(),
        axis.ticks = element_blank(),
        panel.grid = element_blank(),
        plot.margin = margin(t = 5, b = 5, l = 0, r = 0)
      )
    
    # PLOT 3: Ranked Gene Scores
    p_scores <- ggplot(plot_data, aes(x = rank, y = score)) +
      geom_col(aes(fill = score > 0), width = 1, alpha = 0.8) +
      scale_fill_manual(values = c("TRUE" = "#d73027", "FALSE" = "#313695"), guide = "none") +
      labs(
        x = paste("Rank in Gene List (Total:", format(n_genes, big.mark = ","), "genes)"),
        y = "Ranked Score"
      ) +
      theme_minimal(base_size = base_font_size) +
      theme(
        panel.grid.minor = element_blank()
      )
    
    # Add leading edge annotation
    leading_edge_color <- ifelse(nes > 0, "#fddbc7", "#d1e5f0")
    if (nes > 0) {
      p_scores <- p_scores +
        annotate("rect", xmin = 0, xmax = max_es_pos, ymin = -Inf, ymax = Inf,
                 fill = leading_edge_color, alpha = 0.4) +
        annotate("text", x = max_es_pos/2, y = max(plot_data$score) * 0.8,
                 label = "Leading Edge", color = "#d73027", fontface = "bold")
    } else {
      p_scores <- p_scores +
        annotate("rect", xmin = max_es_pos, xmax = n_genes, ymin = -Inf, ymax = Inf,
                 fill = leading_edge_color, alpha = 0.4) +
        annotate("text", x = (max_es_pos + n_genes)/2, y = min(plot_data$score) * 0.8,
                 label = "Leading Edge", color = "#313695", fontface = "bold")
    }
    
    # --- 4. Combine the plots ---
    # Use patchwork to align and stack the plots
    combined_plot <- p_es / p_hits / p_scores +
      plot_layout(heights = c(0.5, 0.15, 0.35))
    
    return(combined_plot)
  }
  
  # 4. VALIDATION STORAGE AND DISPLAY
  observeEvent(input$run_gsea_unified, {
    # Store validation results for display
    validation <- validateGSEAInput(rv_gsea$ranked_gene_list, input$organism, input$pathway_databases_gsea)
    
    # Store in global environment for UI access
    assign("last_validation", validation, envir = .GlobalEnv)
  }, priority = 1000) # High priority to run before main analysis
  
  # 5. ENHANCED ERROR HANDLING AND LOGGING
  observeEvent(input$run_gsea_unified, {
    # Log analysis start
    cat("\n=== GSEA Analysis Started ===\n")
    cat("Time:", as.character(Sys.time()), "\n")
    cat("Organism:", input$organism, "\n")
    cat("Databases:", paste(input$pathway_databases_gsea, collapse = ", "), "\n")
    cat("Gene list size:", length(rv_gsea$ranked_gene_list), "\n")
    cat("================================\n")
  })
  
  # 6. SMART DEFAULTS BASED ON ORGANISM
  observeEvent(input$organism, {
    req(input$organism)
    
    organism_info <- getOrganismMapping(input$organism)
    supported_dbs <- organism_info$supported_dbs
    
    # Auto-select best databases for this organism
    if ("reactome" %in% supported_dbs) {
      # For organisms with Reactome support, select top 3
      default_selection <- c("kegg", "reactome", "go_bp")
    } else {
      # For organisms without Reactome, select alternatives
      default_selection <- c("kegg", "wiki", "go_bp")
    }
    
    # Only select databases that are actually supported
    final_selection <- intersect(default_selection, supported_dbs)
    
    # Update the selection (this will work with your smart selector)
    updateCheckboxGroupInput(session, "pathway_databases_gsea",
                             selected = final_selection)
  })
  
  # 7. CONVERSION RATE MONITORING
  output$conversion_rate_display <- renderUI({
    req(rv_gsea$conversion_stats)
    
    stats <- rv_gsea$conversion_stats
    
    if (stats$conversion_rate < 70) {
      alert_class <- "alert-danger"
      icon_name <- "exclamation-triangle"
      message <- "Low conversion rate - consider checking gene ID format"
    } else if (stats$conversion_rate < 85) {
      alert_class <- "alert-warning"
      icon_name <- "exclamation-triangle"
      message <- "Moderate conversion rate - some genes could not be mapped"
    } else {
      alert_class <- "alert-success"
      icon_name <- "check-circle"
      message <- "Good conversion rate"
    }
    
    div(class = paste("alert", alert_class),
        p(icon(icon_name),
          strong("Gene ID Conversion: "),
          paste0(stats$converted_count, "/", stats$original_count,
                 " (", stats$conversion_rate, "%) - "),
          message)
    )
  })
  
  # 8. ANALYSIS TIME TRACKING
  rv_analysis_timer <- reactiveValues(start_time = NULL, end_time = NULL)
  
  observeEvent(input$run_gsea_unified, {
    rv_analysis_timer$start_time <- Sys.time()
  })
  
  observeEvent(analysis_complete(), {
    if (analysis_complete()) {
      rv_analysis_timer$end_time <- Sys.time()
      
      if (!is.null(rv_analysis_timer$start_time)) {
        duration <- as.numeric(difftime(rv_analysis_timer$end_time,
                                        rv_analysis_timer$start_time,
                                        units = "secs"))
        
        showNotification(
          paste("Analysis completed in", round(duration, 1), "seconds"),
          type = "message", duration = 5
        )
      }
    }
  })
  
  # 9. EXPORT ANALYSIS REPORT
  output$downloadAnalysisReport <- downloadHandler(
    filename = function() {
      paste("GSEA_Analysis_Report_", format(Sys.time(), "%Y%m%d_%H%M"), ".html", sep = "")
    },
    content = function(file) {
      load_export_packages()
      # Create HTML report
      req(gsea_results(), rv_gsea$analysis_metadata)
      
      report_content <- paste0(
        "<html><head><title>GSEA Analysis Report</title></head><body>",
        "<h1>GSEA Analysis Report</h1>",
        "<p><strong>Generated:</strong> ", Sys.time(), "</p>",
        "<p><strong>Organism:</strong> ", rv_gsea$analysis_metadata$organism, "</p>",
        "<p><strong>Total Pathways Found:</strong> ", nrow(gsea_results()), "</p>",
        "<p><strong>Databases Analyzed:</strong> ", paste(rv_gsea$analysis_metadata$databases_analyzed, collapse = ", "), "</p>",
        # Add more report content here
        "</body></html>"
      )
      
      writeLines(report_content, file)
    }
  )
  
  # 10. MEMORY CLEANUP
  onSessionEnded(function() {
    # Clean up large objects when session ends
    if (exists("last_validation", envir = .GlobalEnv)) {
      rm("last_validation", envir = .GlobalEnv)
    }
    
    # Clean up reactive values
    rv_gsea$all_results_by_db <- NULL
    rv_gsea$up_regulated <- NULL
    rv_gsea$down_regulated <- NULL
  })
  
  observeEvent(input$run_gsea_unified, {
    req(rv_gsea$ranked_gene_list)
    
    # Pre-validation
    validation <- validateGSEAInput(rv_gsea$ranked_gene_list, input$organism, input$pathway_databases_gsea)
    
    # Show validation results
    if (length(validation$errors) > 0) {
      showNotification(paste("Validation Errors:", paste(validation$errors, collapse = "; ")),
                       type = "error", duration = 10)
      return()
    }
    
    if (length(validation$warnings) > 0) {
      showNotification(paste("Validation Warnings:", paste(validation$warnings, collapse = "; ")),
                       type = "warning", duration = 8)
    }
    
    if (length(validation$info) > 0) {
      showNotification(paste("Analysis Info:", paste(validation$info, collapse = "; ")),
                       type = "message", duration = 5)
    }
    
    withProgress(message = 'Running Enhanced GSEA Analysis...', value = 0, {
      
      analysis_complete(FALSE)
      gsea_results(NULL)
      
      # Get organism mapping and validate databases
      organism_info <- getOrganismMapping(input$organism)
      supported_dbs <- organism_info$supported_dbs
      requested_dbs <- input$pathway_databases_gsea
      
      # Filter to only supported databases
      valid_dbs <- intersect(requested_dbs, supported_dbs)
      unsupported_dbs <- setdiff(requested_dbs, supported_dbs)
      
      if (length(unsupported_dbs) > 0) {
        showNotification(
          paste("Note: The following databases are not supported for", organism_info$db_mapping$display_name, ":",
                paste(unsupported_dbs, collapse = ", ")),
          type = "warning", duration = 8
        )
      }
      
      if (length(valid_dbs) == 0) {
        showNotification("No supported databases selected for this organism.", type = "error")
        analysis_complete(TRUE)
        return()
      }
      
      # Prepare variables
      ranked_genes_local <- rv_gsea$ranked_gene_list
      input_id_type_local <- input$geneIdType
      organism_db_name_local <- organism_info$db_mapping$db
      organism_codes <- organism_info$db_mapping
      pval_threshold_local <- input$pvalThreshold
      adjust_method_local <- input$adjustMethod
      
      # Store analysis metadata
      rv_gsea$analysis_metadata <- list(
        organism = organism_info$db_mapping$display_name,
        organism_code = input$organism,
        organism_db = organism_db_name_local,  # Store for gene conversion
        databases_requested = requested_dbs,
        databases_analyzed = valid_dbs,
        gene_count = length(ranked_genes_local),
        p_threshold = pval_threshold_local,
        adjustment_method = adjust_method_local,
        analysis_time = Sys.time(),
        gene_id_type = input_id_type_local
      )
      
      tryCatch({
        # Enhanced Gene ID conversion
        incProgress(0.2, detail = "Converting and cleaning gene IDs...")
        converted_genes <- convertGeneIDsEnhanced(ranked_genes_local, input_id_type_local, organism_db_name_local)
        if (is.null(converted_genes)) stop("Gene ID conversion failed.")
        
        # Store conversion stats
        rv_gsea$conversion_stats <- converted_genes$conversion_stats
        
        all_results <- list()
        progress_per_db <- 0.6 / length(valid_dbs)
        
        # KEGG Analysis
        if ("kegg" %in% valid_dbs && !is.null(organism_codes$kegg)) {
          incProgress(progress_per_db, detail = "Analyzing KEGG pathways...")
          kegg_result <- tryCatch({
            gseKEGG(geneList = converted_genes$kegg,
                    organism = organism_codes$kegg,
                    pvalueCutoff = pval_threshold_local,
                    pAdjustMethod = adjust_method_local)
          }, error = function(e) {
            print(paste("KEGG analysis error:", e$message))
            NULL
          })
          
          if (!is.null(kegg_result) && nrow(kegg_result) > 0) {
            kegg_df <- as.data.frame(kegg_result)
            kegg_df$Database <- "KEGG"
            all_results[["KEGG"]] <- kegg_df
            print(paste("KEGG: Found", nrow(kegg_df), "significant pathways"))
          }
        }
        
        # Reactome Analysis (only for supported organisms)
        if ("reactome" %in% valid_dbs && !is.null(organism_codes$reactome)) {
          incProgress(progress_per_db, detail = "Analyzing Reactome pathways...")
          reactome_result <- tryCatch({
            gsePathway(geneList = converted_genes$reactome,
                       organism = organism_codes$reactome,
                       pvalueCutoff = pval_threshold_local)
          }, error = function(e) {
            print(paste("Reactome analysis error:", e$message))
            NULL
          })
          
          if (!is.null(reactome_result) && nrow(reactome_result) > 0) {
            reactome_df <- as.data.frame(reactome_result)
            reactome_df$Database <- "Reactome"
            all_results[["Reactome"]] <- reactome_df
            print(paste("Reactome: Found", nrow(reactome_df), "significant pathways"))
          }
        }
        
        # WikiPathways Analysis
        if ("wiki" %in% valid_dbs && !is.null(organism_codes$wiki)) {
          incProgress(progress_per_db, detail = "Analyzing WikiPathways...")
          wiki_result <- tryCatch({
            gseWP(geneList = converted_genes$wiki,
                  organism = organism_codes$wiki,
                  pvalueCutoff = pval_threshold_local)
          }, error = function(e) {
            print(paste("WikiPathways analysis error:", e$message))
            NULL
          })
          
          if (!is.null(wiki_result) && nrow(wiki_result) > 0) {
            wiki_df <- as.data.frame(wiki_result)
            wiki_df$Database <- "WikiPathways"
            all_results[["WikiPathways"]] <- wiki_df
            print(paste("WikiPathways: Found", nrow(wiki_df), "significant pathways"))
          }
        }
        
        # GO Analysis
        go_dbs <- intersect(c("go_bp", "go_mf", "go_cc"), valid_dbs)
        for (go_ont in go_dbs) {
          ont_code <- switch(go_ont, "go_bp"="BP", "go_mf"="MF", "go_cc"="CC")
          incProgress(progress_per_db, detail = paste("Analyzing GO:", ont_code, "..."))
          
          go_result <- tryCatch({
            gseGO(geneList = converted_genes$entrez,
                  OrgDb = organism_db_name_local,
                  ont = ont_code,
                  pvalueCutoff = pval_threshold_local,
                  pAdjustMethod = adjust_method_local)
          }, error = function(e) {
            print(paste("GO", ont_code, "analysis error:", e$message))
            NULL
          })
          
          if (!is.null(go_result) && nrow(go_result) > 0) {
            go_df <- as.data.frame(go_result)
            go_df$Database <- paste0("GO_", ont_code)
            all_results[[paste0("GO_", ont_code)]] <- go_df
            print(paste("GO", ont_code, ": Found", nrow(go_df), "significant pathways"))
          }
        }
        
        # Combine and finalize results
        incProgress(0.2, detail = "Finalizing results...")
        
        if (length(all_results) > 0) {
          print(paste("Found results from", length(all_results), "databases"))
          
          # Combine results ensuring consistent structure
          combined_results <- do.call(rbind, lapply(names(all_results), function(db_name) {
            df <- all_results[[db_name]]
            if (!"Database" %in% colnames(df)) df$Database <- db_name
            return(df)
          }))
          
          # Separate up and down regulated pathways
          up_regulated <- combined_results[combined_results$NES > 0, ]
          down_regulated <- combined_results[combined_results$NES < 0, ]
          
          print(paste("Total pathways:", nrow(combined_results)))
          print(paste("Upregulated:", nrow(up_regulated)))
          print(paste("Downregulated:", nrow(down_regulated)))
          
          gsea_results(combined_results)
          
          # Store separate results for specialized views
          rv_gsea$up_regulated <- up_regulated
          rv_gsea$down_regulated <- down_regulated
          rv_gsea$all_results_by_db <- all_results
          
          showNotification(
            paste("GSEA analysis completed! Found", nrow(combined_results),
                  "significant pathways (", nrow(up_regulated), "up,",
                  nrow(down_regulated), "down)"),
            type = "message"
          )
          
        } else {
          showNotification("No significant pathways found with current parameters.", type = "warning")
          gsea_results(data.frame(Message = "No significant pathways found."))
        }
        
        analysis_complete(TRUE)
        
      }, error = function(e) {
        print(paste("Error in GSEA analysis:", e$message))
        showNotification(paste("Error:", e$message), type = "error", duration = 15)
        gsea_results(data.frame(Error = e$message))
        analysis_complete(TRUE)
      })
      
    })
  })
  
  # Helper function for conditional file input handling
  `%OR%` <- function(a, b) {
    if (!is.null(a)) a else b
  }
  
