  # Batch conversion function for much faster gene symbol conversion
  convertEntrezBatch <- function(entrez_list, organism_db) {
    tryCatch({
      # Extract all unique Entrez IDs from all pathways at once
      all_entrez_strings <- entrez_list[!is.na(entrez_list) & entrez_list != ""]
      
      if (length(all_entrez_strings) == 0) return(list())
      
      # Parse all Entrez IDs
      all_entrez_ids <- unique(unlist(lapply(all_entrez_strings, function(x) {
        if (grepl("/", x)) {
          strsplit(x, "/")[[1]]
        } else if (grepl(",", x)) {
          strsplit(x, ",")[[1]]
        } else {
          c(x)
        }
      })))
      
      # Clean IDs
      all_entrez_ids <- trimws(all_entrez_ids)
      all_entrez_ids <- all_entrez_ids[all_entrez_ids != "" & !is.na(all_entrez_ids)]
      
      print(paste("Batch converting", length(all_entrez_ids), "unique Entrez IDs"))
      
      # BATCH CONVERSION - Convert all at once
      library(AnnotationDbi)
      if (is.character(organism_db)) {
        if (!requireNamespace(organism_db, quietly = TRUE)) {
          return(setNames(all_entrez_ids, all_entrez_ids))  # Return originals
        }
        library(organism_db, character.only = TRUE)
        db_obj <- get(organism_db)
      } else {
        db_obj <- organism_db
      }
      
      # Single batch conversion call
      symbols <- mapIds(db_obj,
                        keys = all_entrez_ids,
                        column = "SYMBOL",
                        keytype = "ENTREZID",
                        multiVals = "first")
      
      # Replace NAs with original IDs
      symbols[is.na(symbols)] <- all_entrez_ids[is.na(symbols)]
      
      # Return lookup table
      return(setNames(as.character(symbols), all_entrez_ids))
      
    }, error = function(e) {
      print(paste("Batch conversion error:", e$message))
      return(list())
    })
  }
  
  # Function to apply batch conversion to individual pathway strings
  applyBatchConversion <- function(entrez_string, conversion_lookup, max_genes = 3) {
    if (is.na(entrez_string) || entrez_string == "") {
      return("N/A")
    }
    
    # Parse genes
    if (grepl("/", entrez_string)) {
      genes <- strsplit(entrez_string, "/")[[1]]
    } else if (grepl(",", entrez_string)) {
      genes <- strsplit(entrez_string, ",")[[1]]
    } else {
      genes <- c(entrez_string)
    }
    
    genes <- trimws(genes)
    genes <- genes[genes != "" & !is.na(genes)]
    
    if (length(genes) == 0) return("N/A")
    
    # Apply conversion using lookup
    symbols <- sapply(genes, function(g) {
      if (g %in% names(conversion_lookup)) {
        conversion_lookup[[g]]
      } else {
        g  # Return original if not found
      }
    }, USE.NAMES = FALSE)
    
    # Take first N genes for display
    if (length(symbols) > max_genes) {
      result <- paste(paste(symbols[1:max_genes], collapse = ", "),
                      paste0("... (", length(symbols), " total)"))
    } else {
      result <- paste(symbols, collapse = ", ")
    }
    
    return(result)
  }
  
  
  # Generate results table
  output$gseaTable <- DT::renderDataTable({
    req(gsea_results())
    req(analysis_complete())
    
    tryCatch({
      result_table <- gsea_results()
      
      print("GSEA Results Structure:")
      print(colnames(result_table))
      print(paste("Number of rows:", nrow(result_table)))
      
      if (is.null(result_table) || nrow(result_table) == 0) {
        return(DT::datatable(
          data.frame(Message = "No significant pathways found."),
          options = list(dom = 't'),
          rownames = FALSE
        ))
      }
      
      # Show progress for main table too
      withProgress(message = "Preparing results table...", value = 0, {
        
        # Get organism database for gene conversion
        organism_db <- if (!is.null(rv_gsea$analysis_metadata$organism_db)) {
          rv_gsea$analysis_metadata$organism_db
        } else {
          getOrganismMapping(input$organism)$db_mapping$db
        }
        
        # Initialize display table
        display_table <- data.frame(stringsAsFactors = FALSE)
        
        incProgress(0.2, detail = "Building table structure...")
        
        # Build table with enhanced formatting
        if ("Description" %in% colnames(result_table)) {
          display_table <- data.frame(
            Pathway = as.character(result_table$Description),
            stringsAsFactors = FALSE
          )
        } else {
          display_table <- data.frame(
            Pathway = paste("Pathway", 1:nrow(result_table)),
            stringsAsFactors = FALSE
          )
        }
        
        # Add other columns
        if ("NES" %in% colnames(result_table)) {
          nes_values <- round(as.numeric(result_table$NES), 3)
          direction_symbol <- ifelse(nes_values > 0, "↑", "↓")
          
          display_table$NES <- nes_values
          display_table$Direction <- paste0(direction_symbol, " ",
                                            ifelse(nes_values > 0, "Up", "Down"))
        }
        
        if ("pvalue" %in% colnames(result_table)) {
          display_table$`P-value` <- formatC(as.numeric(result_table$pvalue),
                                             digits = 4, format = "e")
        }
        
        if ("p.adjust" %in% colnames(result_table)) {
          display_table$`Adjusted P-value` <- formatC(as.numeric(result_table$p.adjust),
                                                      digits = 4, format = "e")
        }
        
        if ("setSize" %in% colnames(result_table)) {
          display_table$`Gene Count` <- as.integer(result_table$setSize)
        }
        
        if ("Database" %in% colnames(result_table)) {
          display_table$Database <- as.character(result_table$Database)
        }
        
        # OPTIMIZED gene symbol conversion with batch processing
        if ("core_enrichment" %in% colnames(result_table)) {
          incProgress(0.4, detail = "Converting gene IDs (batch)...")
          
          # BATCH CONVERSION - much faster
          conversion_lookup <- convertEntrezBatch(result_table$core_enrichment, organism_db)
          
          incProgress(0.3, detail = "Applying conversions...")
          
          # Apply conversions (fast lookup)
          preview_gene_symbols <- sapply(result_table$core_enrichment, function(x) {
            applyBatchConversion(x, conversion_lookup, max_genes = 5)
          }, USE.NAMES = FALSE)
          
          full_gene_symbols <- sapply(result_table$core_enrichment, function(x) {
            applyBatchConversion(x, conversion_lookup, max_genes = 1000)  # All genes
          }, USE.NAMES = FALSE)
          
          display_table$`Core Genes (Preview)` <- preview_gene_symbols
          display_table$`All Core Genes` <- full_gene_symbols
          
          # Store for network analysis
          rv_gsea$full_gene_symbols <- setNames(full_gene_symbols, result_table$Description)
        }
        
        incProgress(0.1, detail = "Finalizing...")
        
        # Sort by adjusted p-value
        if ("Adjusted P-value" %in% colnames(display_table)) {
          p_values <- as.numeric(gsub("e.*", "", display_table$`Adjusted P-value`))
          display_table <- display_table[order(p_values), ]
        }
        
      }) # End withProgress
      
      # Create DataTable (same as before)
      dt <- DT::datatable(
        display_table,
        options = list(
          pageLength = 15,
          scrollX = TRUE,
          scrollY = "500px",
          dom = 'Bfrtip',
          buttons = list(
            'copy', 'csv', 'excel',
            list(extend = 'colvis', text = 'Show/Hide Columns')
          ),
          columnDefs = list(
            list(width = '250px', targets = 0),
            list(width = '80px', targets = 1),
            list(width = '100px', targets = 2),
            list(width = '100px', targets = 3),
            list(width = '120px', targets = 4),
            list(width = '80px', targets = 5),
            list(width = '100px', targets = 6),
            list(width = '300px', targets = 7),
            list(width = '500px', targets = 8),
            list(className = 'dt-center', targets = 1:6),
            list(className = 'dt-left', targets = c(0, 7, 8)),
            list(
              render = DT::JS(
                "function(data, type, row, meta) {",
                "  if(type === 'display' && meta.col == 8) {",
                "    return '<div style=\"white-space: normal; word-wrap: break-word; max-width: 500px;\">' + data + '</div>';",
                "  }",
                "  return data;",
                "}"
              ),
              targets = 8
            )
          ),
          initComplete = DT::JS(
            "function(settings, json) {",
            "  $(this.api().table().header()).css('background-color', '#f8f9fa');",
            "  $(this.api().table().header()).css('font-weight', 'bold');",
            "  this.api().column(8).visible(false);",
            "}"
          )
        ),
        rownames = FALSE,
        filter = 'top',
        escape = FALSE,
        extensions = c('Buttons', 'ColReorder')
      )
      
      # Add styling (same as before)
      if ("Direction" %in% colnames(display_table)) {
        dt <- dt %>% DT::formatStyle(
          'Direction',
          backgroundColor = DT::styleEqual(c("↑ Up", "↓ Down"), c('#d4edda', '#f8d7da')),
          fontWeight = 'bold'
        )
      }
      
      if ("NES" %in% colnames(display_table)) {
        dt <- dt %>% DT::formatStyle(
          'NES',
          backgroundColor = DT::styleInterval(c(-1, 0, 1),
                                              c('#ffcdd2', '#fff3e0', '#e8f5e8', '#c8e6c9')),
          fontWeight = 'bold'
        )
      }
      
      return(dt)
      
    }, error = function(e) {
      print(paste("Error in gseaTable rendering:", e$message))
      return(DT::datatable(
        data.frame(Error = paste("Error rendering results:", e$message)),
        options = list(dom = 't'),
        rownames = FALSE
      ))
    })
  })
  
  
  
  output$upregulated_table <- DT::renderDataTable({
    req(rv_gsea$up_regulated)
    
    if (is.null(rv_gsea$up_regulated) || nrow(rv_gsea$up_regulated) == 0) {
      return(DT::datatable(
        data.frame(Message = "No upregulated pathways found"),
        options = list(dom = 't'), rownames = FALSE
      ))
    }
    
    # Show progress
    withProgress(message = "Preparing upregulated pathways...", value = 0, {
      
      # Get organism database
      organism_db <- getOrganismMapping(input$organism)$db_mapping$db
      
      incProgress(0.3, detail = "Converting gene IDs (batch)...")
      
      # BATCH CONVERSION - Convert all genes at once
      conversion_lookup <- convertEntrezBatch(rv_gsea$up_regulated$core_enrichment, organism_db)
      
      incProgress(0.4, detail = "Applying conversions...")
      
      # Apply conversions using lookup table (very fast)
      core_genes_symbols <- sapply(rv_gsea$up_regulated$core_enrichment, function(x) {
        applyBatchConversion(x, conversion_lookup, max_genes = 3)
      }, USE.NAMES = FALSE)
      
      incProgress(0.3, detail = "Finalizing table...")
      
      display_table <- rv_gsea$up_regulated %>%
        arrange(p.adjust) %>%
        select(Description, NES, pvalue, p.adjust, setSize, Database) %>%
        mutate(
          NES = round(NES, 3),
          `P-value` = formatC(pvalue, digits = 4, format = "e"),
          `Adjusted P-value` = formatC(p.adjust, digits = 4, format = "e"),
          `Gene Count` = setSize,
          `Core Genes` = core_genes_symbols
        ) %>%
        select(Description, NES, `P-value`, `Adjusted P-value`, `Gene Count`, Database, `Core Genes`)
      
      colnames(display_table)[1] <- "Pathway"
      
      return(display_table)
    })
    
    DT::datatable(display_table,
                  options = list(pageLength = 10, scrollX = TRUE),
                  rownames = FALSE) %>%
      DT::formatStyle('NES', backgroundColor = '#d4edda', fontWeight = 'bold') %>%
      DT::formatStyle('Pathway', fontSize = '14px')
  })
  
