  cleanGeneIDs <- function(gene_ids) {
    # Remove version numbers from Ensembl IDs
    gene_ids <- gsub("\\.\\d+$", "", gene_ids)
    
    # Remove whitespace
    gene_ids <- trimws(gene_ids)
    
    # Remove empty strings and NAs
    gene_ids <- gene_ids[gene_ids != "" & !is.na(gene_ids)]
    
    # Remove duplicates while preserving order
    gene_ids <- gene_ids[!duplicated(gene_ids)]
    
    return(gene_ids)
  }
  
  
  getOrganismMapping <- function(organism) {
