                            wiki = "Mus musculus",
                            display_name = "Mouse (Mus musculus)"  # FIXED: Added proper display name
                          ),
                          "rnorvegicus" = list(
                            db = "org.Rn.eg.db",
                            kegg = "rno",
                            reactome = "rat",
                            wiki = "Rattus norvegicus",
                            display_name = "Rat (Rattus norvegicus)"  # FIXED: Added proper display name
                          ),
                          "drerio" = list(
                            db = "org.Dr.eg.db",
                            kegg = "dre",
                            reactome = NULL,  # Limited support
                            wiki = "Danio rerio",
