                          ),
                          "dmelanogaster" = list(
                            db = "org.Dm.eg.db",
                            kegg = "dme",
                            reactome = NULL,  # No support
                            wiki = "Drosophila melanogaster",
                            display_name = "Fruit Fly (Drosophila melanogaster)"  # FIXED: Added proper display name
                          ),
                          "celegans" = list(
