                            kegg = "cel",
                            reactome = NULL,  # No support
                            wiki = "Caenorhabditis elegans",
                            display_name = "C. elegans (Caenorhabditis elegans)"  # FIXED: Added proper display name
                          ),
                          "scerevisiae" = list(
                            db = "org.Sc.sgd.db",
                            kegg = "sce",
                            reactome = NULL,  # No support
                            wiki = "Saccharomyces cerevisiae",
                            display_name = "Yeast (Saccharomyces cerevisiae)"  # FIXED: Added proper display name
                          ),
                          "athaliana" = list(
                            db = "org.At.tair.db",
                            kegg = "ath",
                            reactome = NULL,  # No support
                            wiki = "Arabidopsis thaliana",
                            display_name = "Arabidopsis (Arabidopsis thaliana)"  # FIXED: Added proper display name
                          ),
                          "sscrofa" = list(
                            db = "org.Ss.eg.db",
                            kegg = "ssc",
                            reactome = NULL,  # Limited support
                            wiki = "Sus scrofa",
                            display_name = "Pig (Sus scrofa)"  # FIXED: Added proper display name
                          ),
                          "ggallus" = list(
                            db = "org.Gg.eg.db",
