                            reactome = NULL,  # Limited support
                            wiki = "Gallus gallus",
                            display_name = "Chicken (Gallus gallus)"  # FIXED: Added proper display name
                          ),
                          # Default to human
                          list(
                            db = "org.Hs.eg.db",
                            kegg = "hsa",
                            reactome = "human",
                            wiki = "Homo sapiens",
                            display_name = "Human (Homo sapiens)"  # FIXED: Added proper display name
                          )
      ),
      
      # Supported databases per organism
      supported_dbs = switch(organism,
                             "hsapiens" = c("kegg", "reactome", "wiki", "go_bp", "go_mf", "go_cc"),
                             "mmusculus" = c("kegg", "reactome", "wiki", "go_bp", "go_mf", "go_cc"),
                             "rnorvegicus" = c("kegg", "reactome", "wiki", "go_bp", "go_mf", "go_cc"),
                             "drerio" = c("kegg", "wiki", "go_bp", "go_mf", "go_cc"),  # No Reactome
                             "dmelanogaster" = c("kegg", "wiki", "go_bp", "go_mf", "go_cc"),  # No Reactome
                             "celegans" = c("kegg", "wiki", "go_bp", "go_mf", "go_cc"),  # No Reactome
                             "scerevisiae" = c("kegg", "wiki", "go_bp", "go_mf", "go_cc"),  # No Reactome
                             "athaliana" = c("kegg", "wiki", "go_bp", "go_mf", "go_cc"),  # No Reactome
