  validateGSEAInput <- function(gene_list, organism, databases) {
    validation_results <- list(
      errors = character(0),
      warnings = character(0),
      info = character(0)
    )
    
    # Check gene list quality
    if (length(gene_list) < 50) {
      validation_results$errors <- c(validation_results$errors,
                                     "Gene list too small (<50 genes). GSEA requires larger gene sets.")
    } else if (length(gene_list) < 100) {
      validation_results$warnings <- c(validation_results$warnings,
                                       "Small gene list (<100 genes) may limit pathway detection")
    }
    
    if (length(gene_list) > 20000) {
      validation_results$warnings <- c(validation_results$warnings,
                                       "Very large gene list (>20,000 genes) - consider filtering")
    }
    
    # Check for extreme values
    gene_values <- as.numeric(gene_list)
    if (all(gene_values > 0)) {
      validation_results$warnings <- c(validation_results$warnings,
                                       "All gene values are positive - no downregulated pathways expected")
    } else if (all(gene_values < 0)) {
      validation_results$warnings <- c(validation_results$warnings,
                                       "All gene values are negative - no upregulated pathways expected")
    }
    
    # Check value range
    value_range <- max(gene_values) - min(gene_values)
    if (value_range < 1) {
      validation_results$warnings <- c(validation_results$warnings,
                                       "Small dynamic range in gene values - may reduce sensitivity")
    }
    
    # Check organism-database compatibility
    organism_info <- getOrganismMapping(organism)
    unsupported <- setdiff(databases, organism_info$supported_dbs)
    if (length(unsupported) > 0) {
      validation_results$errors <- c(validation_results$errors,
                                     paste("Unsupported databases for", organism_info$db_mapping$display_name, ":",
                                           paste(unsupported, collapse = ", ")))
    }
    
    # Info messages
    validation_results$info <- c(validation_results$info,
                                 paste("Gene list size:", length(gene_list)),
                                 paste("Value range:", round(min(gene_values), 3), "to", round(max(gene_values), 3)),
                                 paste("Selected organism:", organism_info$db_mapping$display_name))
    
    return(validation_results)
  }
  
  convertGeneIDsEnhanced <- function(ranked_genes, input_id_type, organism_db_name) {
    tryCatch({
      # Clean gene IDs first
      gene_names <- names(ranked_genes)
      cleaned_genes <- cleanGeneIDs(gene_names)
      
      # Report cleaning results
      if (length(cleaned_genes) < length(gene_names)) {
        print(paste("Cleaned", length(gene_names) - length(cleaned_genes), "problematic gene IDs"))
      }
      
      # Filter ranked genes to cleaned IDs
      ranked_genes_clean <- ranked_genes[names(ranked_genes) %in% cleaned_genes]
      
      # Call your existing convertGeneIDs function with cleaned data
      result <- convertGeneIDs(ranked_genes_clean, input_id_type, organism_db_name)
      
      # Add conversion statistics
      if (!is.null(result)) {
        original_count <- length(ranked_genes)
        converted_count <- length(result$entrez)
        conversion_rate <- round((converted_count / original_count) * 100, 1)
        
        print(paste("Gene ID conversion summary:"))
        print(paste("- Original genes:", original_count))
        print(paste("- Successfully converted:", converted_count))
        print(paste("- Conversion rate:", conversion_rate, "%"))
        
        # Add metadata to result
        result$conversion_stats <- list(
          original_count = original_count,
          converted_count = converted_count,
          conversion_rate = conversion_rate
        )
      }
      
      return(result)
      
    }, error = function(e) {
      print(paste("Enhanced gene conversion error:", e$message))
      return(NULL)
    })
  }
  
  
  
  output$debug_gsea_structure <- renderText({
    req(gsea_results())
    
    results <- gsea_results()
    
    debug_info <- paste(
      "Results class:", class(results),
      "\nNumber of rows:", nrow(results),
      "\nColumn names:", paste(colnames(results), collapse = ", "),
      "\nFirst few rows structure:"
    )
    
    if (nrow(results) > 0) {
      debug_info <- paste(debug_info, "\n", capture.output(str(results[1:min(3, nrow(results)), ])))
    }
    
    return(debug_info)
  })
  
  # Update pathway selection for enrichment plot (show all pathways)
  observe({
    req(gsea_results())
    updateSelectInput(
      session = session,
      inputId = "pathwayToPlot",
      choices = unique(gsea_results()$Description)  # Show all pathways
    )
  })
  
  # Process results based on sorting criteria
  processed_results <- reactive({
    req(gsea_results(), input$plotType, input$sortBy)
    
    if(input$plotType %in% c("dotplot", "barplot")) {
      # Force reactivity on sorting changes
      force(input$sortBy)
      
      # Sort based on selection
      sorted <- if(input$sortBy == "pval") {
        gsea_results()[order(gsea_results()$p.adjust), ]
      } else {
        gsea_results()[order(-abs(gsea_results()$NES)), ]
      }
      
      # Get valid subset
      valid_n <- min(nrow(sorted), input$numPathwaysToShow)
      top_pathways <- head(sorted, valid_n)
      
      # Set factor levels for proper ordering
      top_pathways$Description <- factor(
        top_pathways$Description,
        levels = rev(unique(top_pathways$Description))
      )
      
      return(top_pathways)
    } else {
      return(gsea_results())
    }
  }) %>% bindEvent(input$sortBy, input$numPathwaysToShow, input$plotType)
  
  
  # Generate plots
  gsea_plot <- reactive({
    req(processed_results(), input$plotType)
    results_obj <- processed_results()
    
    if(input$plotType == "enrichment") {
      req(input$pathwayToPlot)
      
      pathway_idx <- which(results_obj$Description == input$pathwayToPlot)
      
      if(length(pathway_idx) == 0) {
        return(ggplot() +
                 annotate("text", x = 0.5, y = 0.5, label = "Pathway not found") +
                 theme_void())
      }
      
      pathway_data <- results_obj[pathway_idx, ]
      genes <- unlist(strsplit(pathway_data$core_enrichment, "/"))
      ranks <- gene_list()  # Assuming gene_list() is available
      
      # Create enrichment plot data
      gene_ranks <- rank(-ranks)
      gene_list_sorted <- sort(gene_ranks, decreasing = TRUE)
      genes_in_pathway <- which(names(gene_list_sorted) %in% genes)
      
      enrichment_data <- data.frame(
        rank = seq_along(gene_list_sorted),
        running_score = cumsum(ifelse(
          seq_along(gene_list_sorted) %in% genes_in_pathway,
          1/length(genes),
          -1/(length(gene_list_sorted) - length(genes))
        ))
      )
      
      ggplot(enrichment_data, aes(x = rank, y = running_score)) +
        geom_line(color = "steelblue") +
        geom_hline(yintercept = 0, linetype = "dashed") +
        geom_rug(data = data.frame(x = genes_in_pathway),
                 aes(x = x), sides = "b", color = "red", inherit.aes = FALSE) +
        labs(title = pathway_data$Description,
             subtitle = paste("NES =", round(pathway_data$NES, 2),
                              "FDR =", formatC(pathway_data$p.adjust, format = "e", digits = 2)),
             x = "Rank in Ordered Dataset",
             y = "Enrichment Score") +
        theme_minimal()
      
    } else if(input$plotType == "dotplot") {
      ggplot(processed_results(),
             aes(x = NES,
                 y = Description,  # Use factor levels directly
                 color = p.adjust,
                 size = -log10(p.adjust))) +
        geom_point() +
        scale_color_gradient(low = "red", high = "blue") +
        labs(x = "NES", y = "") +
        theme_minimal() +
        theme(axis.text.y = element_text(size = 12))
      
    } else if(input$plotType == "barplot") {
      ggplot(processed_results(),
             aes(x = NES,
                 y = Description,  # Use factor levels directly
                 fill = p.adjust)) +
        geom_col(width = 0.8) +
        scale_fill_gradient(low = "red", high = "blue") +
        labs(x = "NES", y = "") +
        theme_minimal() +
        theme(axis.text.y = element_text(size = 12))
    }
  })
  
  # Render plot
  output$gseaPlot <- renderPlot({
    gsea_plot()
  })
  
  
  
  # Add reactive values to store selection state
  pathwaySelectionState <- reactiveVal("default")  # "default" or "custom"
  selectedPathways <- reactiveVal(NULL)
  
  # Modal dialog for pathway selection
  observeEvent(input$openPathwaySelector, {
    req(gsea_results())
    results_df <- gsea_results()
    
    # Filter and sort results
    results_df <- results_df[results_df$p.adjust < input$adjPvalThreshold, ]
    if(input$networkSortBy == "NES") {
      results_df <- results_df[order(-abs(results_df$NES)), ]
    } else {
      results_df <- results_df[order(results_df[[input$networkSortBy]]), ]
    }
    
    # Create data for the table
    pathway_table <- data.frame(
      Pathway = results_df$Description,
      Database = results_df$Database,
      NES = round(results_df$NES, 3),
      Adj.P.value = formatC(results_df$p.adjust, format = "e", digits = 2),
      Q.value = formatC(results_df$qvalue, format = "e", digits = 2),
      Gene.Count = results_df$setSize,
      stringsAsFactors = FALSE
    )
    
    # Store for later use
    pathwayData(pathway_table)
    
    showModal(modalDialog(
      title = "Select Pathways for Network Visualization",
      size = "l",
      easyClose = TRUE,
      
      div(
        style = "height: 600px; padding: 20px;",
        fluidRow(
          column(12,
                 div(style = "margin-bottom: 15px;",
                     h4("Available Pathways"),
                     p("Select pathways to include in the network visualization. Use Ctrl/Cmd+click for multiple selections.")
                 ),
                 
                 # Selection buttons
                 fluidRow(
                   column(4,
                          actionButton("selectAllPathwaysBtn", "Select All",
                                       class = "btn-info btn-sm")
                   ),
                   column(4,
                          actionButton("clearAllPathwaysBtn", "Clear All",
                                       class = "btn-warning btn-sm")
                   ),
                   column(4,
                          div(id = "pathwayCountDisplay", style = "margin-top: 5px;")
                   )
                 ),
                 
                 br(),
                 
                 # Enhanced pathway selection table
                 DT::dataTableOutput("pathwaySelectTable", height = "400px")
          )
        )
      ),
      
      footer = tagList(
        modalButton("Cancel"),
        actionButton("generateCustomNetwork", "Generate Network",
                     class = "btn-primary")
      )
    ))
  })
  
