  output$gene_pathway_network <- renderVisNetwork({
    req(gsea_results())
    print("Starting OPTIMIZED Gene-Pathway network visualization...")
    
    results_df <- gsea_results()
    
    if (is.null(results_df) || nrow(results_df) == 0 || "Message" %in% colnames(results_df)) {
      return(visNetwork(
        nodes = data.frame(id = 1, label = "No significant pathways found", shape = "text"),
        edges = data.frame(from = c(), to = c())
      ))
    }
    
    # Show progress for network creation
    withProgress(message = 'Creating gene-pathway network...', value = 0, {
      
      tryCatch({
        incProgress(0.1, detail = "Filtering pathways...")
        
        # Filter by p-value threshold first
        results_df <- results_df[results_df$p.adjust < input$adjPvalThreshold, ]
        
        # Handle pathway selection logic
        if(pathwaySelectionState() == "custom") {
          req(selectedPathways())
          results_df <- results_df[results_df$Description %in% selectedPathways(), ]
          print(paste("Using custom selection:", length(selectedPathways()), "pathways"))
        } else {
          if(input$networkSortBy == "NES") {
            results_df <- results_df[order(-abs(results_df$NES)), ]
          } else {
            results_df <- results_df[order(results_df[[input$networkSortBy]]), ]
          }
          results_df <- head(results_df, input$topPathwaysNetwork)
          print(paste("Using default selection: top", input$topPathwaysNetwork, "pathways"))
        }
        
        if(nrow(results_df) == 0) {
          return(visNetwork(
            nodes = data.frame(id = 1, label = "No pathways match the criteria", shape = "text"),
            edges = data.frame(from = c(), to = c())
          ))
        }
        
        print(paste("Visualizing", nrow(results_df), "pathways"))
        incProgress(0.2, detail = "Extracting genes...")
        
        # Get unique genes from all pathways
        gene_lists <- strsplit(as.character(results_df$core_enrichment), "/")
        all_genes <- unique(unlist(gene_lists))
        all_genes <- all_genes[!is.na(all_genes) & all_genes != ""]
        
        print(paste("Found", length(all_genes), "unique genes"))
        
        # Get organism database for gene conversion
        organism_db <- getOrganismMapping(input$organism)$db_mapping$db
        
        incProgress(0.3, detail = "Converting gene IDs (batch)...")
        
        # ⚡ BATCH CONVERSION - Convert all genes at once (MUCH FASTER)
        conversion_lookup <- convertEntrezBatch(results_df$core_enrichment, organism_db)
        
        # Apply conversions using fast lookup
        gene_symbols <- sapply(all_genes, function(entrez_id) {
          if (entrez_id %in% names(conversion_lookup)) {
            conversion_lookup[[entrez_id]]
          } else {
            entrez_id  # Return original if not found
          }
        }, USE.NAMES = FALSE)
        
        print(paste("Converted", length(gene_symbols), "gene symbols"))
        incProgress(0.2, detail = "Building network structure...")
        
        # Define enhanced colors for different databases
        database_colors <- list(
          "KEGG" = list(background = "#97C2FC", border = "#2B7CE9"),
          "Reactome" = list(background = "#FB7E81", border = "#E62E00"),
          "WikiPathways" = list(background = "#7BE141", border = "#34AD1B"),
          "GO_BP" = list(background = "#FFD700", border = "#FFA500"),
          "GO_MF" = list(background = "#DDA0DD", border = "#9370DB"),
          "GO_CC" = list(background = "#F0E68C", border = "#DAA520")
        )
        
        # Create nodes dataframe with enhanced tooltips
        nodes <- data.frame(
          id = c(paste0("p_", 1:nrow(results_df)),
                 paste0("g_", 1:length(all_genes))),
          label = c(
            # Truncate long pathway names for better display
            sapply(results_df$Description, function(desc) {
              if (nchar(desc) > 50) {
                paste0(substr(desc, 1, 47), "...")
              } else {
                desc
              }
            }),
            gene_symbols  # Use converted gene symbols
          ),
          group = c(results_df$Database, rep("gene", length(all_genes))),
          title = c(
            # Enhanced pathway tooltips
            paste0("<b>", results_df$Description, "</b><br>",
                   "<b>Database:</b> ", results_df$Database, "<br>",
                   "<b>NES:</b> ", round(results_df$NES, 3), "<br>",
                   "<b>Adj. P-value:</b> ", formatC(results_df$p.adjust, format = "e", digits = 2), "<br>",
                   "<b>Gene Count:</b> ", results_df$setSize),
            # Gene tooltips with both symbol and Entrez ID
            paste0("<b>Gene:</b> ", gene_symbols, "<br>",
                   "<b>Entrez ID:</b> ", all_genes)
          ),
          value = c(
            # Size pathways by significance and NES
            pmax(15, pmin(50, abs(results_df$NES) * 15 + (-log10(results_df$p.adjust) * 2))),
            rep(12, length(all_genes))
          ),
          stringsAsFactors = FALSE
        )
        
        incProgress(0.1, detail = "Creating connections...")
        
        # Create edges with enhanced styling
        edges_list <- lapply(seq_len(nrow(results_df)), function(i) {
          genes <- unlist(gene_lists[[i]])
          genes <- genes[!is.na(genes) & genes != ""]
          
          if (length(genes) > 0) {
            data.frame(
              from = rep(paste0("p_", i), length(genes)),
              to = paste0("g_", match(genes, all_genes)),
              width = 2,
              color = list(color = "#848484", highlight = "#E74C3C"),
              smooth = list(enabled = TRUE, type = "continuous"),
              stringsAsFactors = FALSE
            )
          } else {
            NULL
          }
        })
        edges <- do.call(rbind, edges_list[!sapply(edges_list, is.null)])
        
        if (is.null(edges) || nrow(edges) == 0) {
          return(visNetwork(
            nodes = data.frame(id = 1, label = "No valid connections found", shape = "text"),
            edges = data.frame(from = c(), to = c())
          ))
        }
        
        incProgress(0.1, detail = "Rendering network...")
        
        # Create the enhanced visNetwork with improved physics
        network <- visNetwork(nodes, edges, width = "100%", height = "800px") %>%
          
          # ENHANCED GROUP STYLING with shadows and better colors
          visGroups(groupname = "KEGG",
                    color = database_colors$KEGG,
                    shape = "box",
                    shadow = list(enabled = TRUE, size = 5),
                    font = list(size = 14, face = "bold")) %>%
          visGroups(groupname = "Reactome",
                    color = database_colors$Reactome,
                    shape = "box",
                    shadow = list(enabled = TRUE, size = 5),
                    font = list(size = 14, face = "bold")) %>%
          visGroups(groupname = "WikiPathways",
                    color = database_colors$WikiPathways,
                    shape = "box",
                    shadow = list(enabled = TRUE, size = 5),
                    font = list(size = 14, face = "bold")) %>%
          visGroups(groupname = "GO_BP",
                    color = database_colors$GO_BP,
                    shape = "box",
                    shadow = list(enabled = TRUE, size = 5),
                    font = list(size = 14, face = "bold")) %>%
          visGroups(groupname = "GO_MF",
                    color = database_colors$GO_MF,
                    shape = "box",
                    shadow = list(enabled = TRUE, size = 5),
                    font = list(size = 14, face = "bold")) %>%
          visGroups(groupname = "GO_CC",
                    color = database_colors$GO_CC,
                    shape = "box",
                    shadow = list(enabled = TRUE, size = 5),
                    font = list(size = 14, face = "bold")) %>%
          visGroups(groupname = "gene",
                    color = list(background = "#FFA807", border = "#B66B00"),
                    shape = "dot",
                    shadow = list(enabled = TRUE, size = 3),
                    font = list(size = 12)) %>%
          
          # ENHANCED PHYSICS SETTINGS (same as your pathway analysis network)
          visPhysics(
            enabled = TRUE,
            solver = "forceAtlas2Based",
            forceAtlas2Based = list(
              gravitationalConstant = -50,
              centralGravity = 0.01,
              springLength = 150,
              springConstant = 0.08,
              damping = 0.4,
              avoidOverlap = 0.5
            ),
            stabilization = list(
              enabled = TRUE,
              iterations = 1000,
              updateInterval = 25,
              onlyDynamicEdges = FALSE,
              fit = TRUE
            ),
            timestep = 0.35,
            adaptiveTimestep = TRUE,
            maxVelocity = 30,
            minVelocity = 0.75
          ) %>%
          
          # ⭐ AUTO-DISABLE PHYSICS AFTER STABILIZATION
          visEvents(stabilizationIterationsDone = "function() {
          this.setOptions({ physics: false });
          console.log('Gene-pathway network stabilized - physics disabled');
        }") %>%
          
          # ENHANCED INTERACTION SETTINGS
          visInteraction(
            dragNodes = TRUE,
            dragView = TRUE,
            zoomView = TRUE,
            navigationButtons = TRUE,
            tooltipDelay = 100,
            keyboard = TRUE
          ) %>%
          
          # ENHANCED OPTIONS
          visOptions(
            highlightNearest = list(enabled = TRUE, degree = 1, hover = TRUE),
            nodesIdSelection = FALSE,
            selectedBy = list(variable = "group", multiple = TRUE)
          ) %>%
          
          # LAYOUT AND LEGEND
          visLayout(randomSeed = 123) %>%
          visLegend(useGroups = TRUE, position = "right", width = 0.12, zoom = FALSE)
        
        return(network)
        
      }, error = function(e) {
        print(paste("Error in optimized network:", e$message))
        return(visNetwork(
          nodes = data.frame(id = 1, label = paste("Error:", e$message), shape = "text"),
          edges = data.frame(from=c(), to=c())
        ))
      })
      
    }) # End withProgress
  })
  
  optimizedGeneMatching <- function(ranked_genes, pathway_genes_string, organism_db) {
    # Parse pathway genes
    if (grepl("/", pathway_genes_string)) {
      pathway_genes <- strsplit(pathway_genes_string, "/")[[1]]
    } else if (grepl(",", pathway_genes_string)) {
      pathway_genes <- strsplit(pathway_genes_string, ",")[[1]]
    } else {
      pathway_genes <- c(pathway_genes_string)
    }
    
    pathway_genes <- trimws(pathway_genes)
    pathway_genes <- pathway_genes[pathway_genes != "" & !is.na(pathway_genes)]
    
    gene_names_in_ranked <- names(ranked_genes)
    
    # Method 1: Direct match
    pathway_positions <- which(gene_names_in_ranked %in% pathway_genes)
    
    if (length(pathway_positions) > 0) {
      print(paste("Direct match found:", length(pathway_positions), "genes"))
      return(pathway_positions)
    }
    
    # Method 2: Batch conversion approach
    print("Using batch conversion for gene matching...")
    
    # Create batch conversion for pathway genes
    pathway_conversion <- convertEntrezBatch(pathway_genes_string, organism_db)
    
    # Create conversion for ranked genes (sample to avoid too many)
    sample_ranked <- if (length(gene_names_in_ranked) > 1000) {
      sample(gene_names_in_ranked, 1000)
    } else {
      gene_names_in_ranked
    }
    
    ranked_conversion <- convertEntrezBatch(paste(sample_ranked, collapse = "/"), organism_db)
    
    # Try matching with conversions
    pathway_symbols <- unlist(pathway_conversion)
    pathway_positions <- which(gene_names_in_ranked %in% pathway_symbols)
    
    if (length(pathway_positions) > 0) {
      print(paste("Symbol match found:", length(pathway_positions), "genes"))
      return(pathway_positions)
    }
    
    # Try reverse matching
    ranked_symbols <- sapply(gene_names_in_ranked, function(g) {
      if (g %in% names(ranked_conversion)) {
        ranked_conversion[[g]]
      } else {
        g
      }
    })
    
    pathway_positions <- which(ranked_symbols %in% pathway_genes)
    
    print(paste("Final match found:", length(pathway_positions), "genes"))
    return(pathway_positions)
  }
  
  convertSingleGeneToSymbol <- function(entrez_id, organism_db) {
    tryCatch({
      # Use AnnotationDbi to convert
      library(AnnotationDbi)
      
      if (is.character(organism_db)) {
        if (!requireNamespace(organism_db, quietly = TRUE)) {
          return(entrez_id)  # Return original if package not available
        }
        library(organism_db, character.only = TRUE)
        db_obj <- get(organism_db)
      } else {
        db_obj <- organism_db
      }
      
      # Convert to symbol
      symbol <- mapIds(db_obj,
                       keys = entrez_id,
                       column = "SYMBOL",
                       keytype = "ENTREZID",
                       multiVals = "first")
      
      # Return symbol if found, otherwise return original
      if (is.na(symbol)) {
        return(entrez_id)
      } else {
        return(as.character(symbol))
      }
      
    }, error = function(e) {
      return(entrez_id)  # Return original on any error
    })
  }
  
