  # Generate gene-pathway network
  output$pathwayNetwork <- renderVisNetwork({
    req(gsea_results())
    print("Starting network visualization...")
    
    # Get GSEA results
    results_df <- gsea_results()
    results_df <- results_df[results_df$p.adjust < input$adjPvalThreshold, ]
    
    if(pathwaySelectionState() == "custom") {
      # Use custom selected pathways
      req(selectedPathways())
      results_df <- results_df[results_df$Description %in% selectedPathways(), ]
    } else {
      # Use default top pathways
      if(input$networkSortBy == "NES") {
        results_df <- results_df[order(-abs(results_df$NES)), ]
      } else {
        results_df <- results_df[order(results_df[[input$networkSortBy]]), ]
      }
      results_df <- head(results_df, input$topPathwaysNetwork)
    }
    
    if(nrow(results_df) == 0) {
      return(visNetwork(
        nodes = data.frame(id = 1, label = "No pathways selected", shape = "text"),
        edges = data.frame(from = c(), to = c())
      ))
    }
    
    print(paste("Visualizing", nrow(results_df), "pathways"))
    
    # Get unique genes from all pathways
    gene_lists <- strsplit(as.character(results_df$core_enrichment), "/")
    all_genes <- unique(unlist(gene_lists))
    
    # Define colors for different databases
    database_colors <- list(
      "KEGG" = list(background = "#97C2FC", border = "#2B7CE9"),
      "Reactome" = list(background = "#FB7E81", border = "#E62E00"),
      "WikiPathways" = list(background = "#7BE141", border = "#34AD1B")
    )
    
    # Create nodes dataframe
    nodes <- data.frame(
      id = c(paste0("p_", 1:nrow(results_df)),
             paste0("g_", 1:length(all_genes))),
      label = c(results_df$Description, all_genes),
      group = c(results_df$Database,  # use database as group for pathways
                rep("gene", length(all_genes))),
      title = c(paste0(results_df$Description,
                       "\nNES: ", round(results_df$NES, 3),
                       "\nAdj. P-value: ", formatC(results_df$p.adjust, format = "e", digits = 2),
                       "\nDatabase: ", results_df$Database),
                all_genes),  # tooltips
      value = c(abs(results_df$NES) * 20,  # size pathways by NES
                rep(10, length(all_genes))), # smaller nodes for genes
      stringsAsFactors = FALSE
    )
    
    # Create edges
    edges_list <- lapply(seq_len(nrow(results_df)), function(i) {
      genes <- unlist(gene_lists[[i]])
      data.frame(
        from = rep(paste0("p_", i), length(genes)),
        to = paste0("g_", match(genes, all_genes)),
        width = 1,  # You can adjust edge width if needed
        stringsAsFactors = FALSE
      )
    })
    edges <- do.call(rbind, edges_list)
    
    # Modify the visNetwork call with more stable physics settings
    visNetwork(nodes, edges, width = "100%", height = "800px") %>%
      visGroups(groupname = "KEGG",
                color = database_colors$KEGG,
                shape = "box",
                shadow = TRUE) %>%
      visGroups(groupname = "Reactome",
                color = database_colors$Reactome,
                shape = "box",
                shadow = TRUE) %>%
      visGroups(groupname = "WikiPathways",
                color = database_colors$WikiPathways,
                shape = "box",
                shadow = TRUE) %>%
      visGroups(groupname = "gene",
                color = list(
                  background = "#FFA807",
                  border = "#B66B00"
                ),
                shape = "dot",
                shadow = TRUE) %>%
      visOptions(
        highlightNearest = list(
          enabled = TRUE,
          degree = 1,
          hover = TRUE
        ),
        selectedBy = list(
          variable = "group",
          multiple = TRUE
        )
      ) %>%
      visPhysics(
        solver = "forceAtlas2Based",
        stabilization = list(
          enabled = TRUE,
          iterations = 100,
          fit = TRUE
        ),
        forceAtlas2Based = list(
          gravitationalConstant = -50,
          centralGravity = 0.01,
