  # Add download handler for high-quality network export
  output$downloadNetwork <- downloadHandler(
    filename = function() {
      paste0("pathway_network_", format(Sys.time(), "%Y%m%d_%H%M"), ".", input$networkImageFormat)
    },
    content = function(file) {
      load_export_packages()
      # Regenerate the data
      req(gsea_results())
      results_df <- gsea_results() |>
        dplyr::filter(p.adjust < input$adjPvalThreshold)
      
      # Replicate pathway selection logic
      if(pathwaySelectionState() == "custom") {
        req(selectedPathways())
        results_df <- results_df |>
          dplyr::filter(Description %in% selectedPathways())
      } else {
        if(input$networkSortBy == "NES") {
          results_df <- results_df |>
            dplyr::arrange(-abs(NES))
        } else {
          results_df <- results_df |>
            dplyr::arrange(!!sym(input$networkSortBy))
        }
        results_df <- head(results_df, input$topPathwaysNetwork)
      }
      
      # Regenerate nodes and edges
      gene_lists <- strsplit(as.character(results_df$core_enrichment), "/")
      all_genes <- unique(unlist(gene_lists))
      
      # Create nodes (MUST be inside content function)
      nodes <- data.frame(
        id = c(paste0("p_", 1:nrow(results_df)),
               paste0("g_", 1:length(all_genes))),
        label = c(results_df$Description, all_genes),
        group = c(results_df$Database, rep("gene", length(all_genes))),
        title = c(paste0(results_df$Description,
                         "\nNES: ", round(results_df$NES, 3),
                         "\nAdj. P-value: ", formatC(results_df$p.adjust, format = "e", digits = 2),
                         "\nDatabase: ", results_df$Database),
                  all_genes),
        value = c(abs(results_df$NES) * 20, rep(10, length(all_genes)))
      )
      
      # Create edges (MUST be inside content function)
      edges <- do.call(rbind, lapply(seq_len(nrow(results_df)), function(i) {
        genes <- unlist(gene_lists[[i]])
        data.frame(
          from = rep(paste0("p_", i), length(genes)),
          to = paste0("g_", match(genes, all_genes)),
          width = 1)
      }))
      
      # Create temporary file
      temp_html <- tempfile(fileext = ".html")
      
      # Generate network visualization
      visNetwork(nodes, edges) |>
        visOptions(manipulation = FALSE) |>
        visPhysics(stabilization = TRUE) |>
        visSave(temp_html)
      
      # Convert to image with CORRECTED ARGUMENTS
      webshot2::webshot(
        url = temp_html,
        file = file,
        delay = 5,
        zoom = 2,
        vwidth = 1600,
        vheight = 1200,
        extraargs = c(  # Changed from 'options' to 'extraargs'
          "--headless=new",
          "--disable-gpu",
          "--no-sandbox",
          "--disable-dev-shm-usage"
        )
      )
      
      unlink(temp_html)
    }
  )
  
  
  
  
  
  
  
  # Download handlers
  output$downloadGSEAResults <- downloadHandler(
    filename = function() {
      paste("GSEA_Results_", format(Sys.time(), "%Y%m%d_%H%M"), ".csv", sep = "")
    },
    content = function(file) {
      load_export_packages()
      write.csv(gsea_results(), file, row.names = FALSE)
    }
  )
  
  output$downloadGSEAPlot <- downloadHandler(
    filename = function() {
      plot_type <- input$plotType
      timestamp <- format(Sys.time(), "%Y%m%d_%H%M")
      
      if(plot_type == "enrichment") {
        pathway_name <- gsub("[^[:alnum:]]", "_", input$pathwayToPlot)
        paste0("GSEA_Enrichment_", pathway_name, "_", timestamp, ".png")
      } else if(plot_type == "dotplot") {
        paste0("GSEA_DotPlot_top", input$numPathwaysToShow, "_", timestamp, ".png")
      } else {
        paste0("GSEA_BarPlot_top", input$numPathwaysToShow, "_", timestamp, ".png")
      }
    },
    content = function(file) {
      load_export_packages()
      if (input$plotType == "enrichment") {
        # For ggplot enrichment plots - FIXED VERSION
        req(input$pathwayToPlot, rv_gsea$ranked_gene_list)
        
        tryCatch({
          # Get pathway data
          results <- gsea_results()
          selected_pathway <- results[results$Description == input$pathwayToPlot, ]
          
          if (nrow(selected_pathway) > 0) {
            ranked_genes <- rv_gsea$ranked_gene_list
            pathway_genes_string <- selected_pathway$core_enrichment[1]
            
            if (!is.na(pathway_genes_string) && pathway_genes_string != "") {
              organism_db <- getOrganismMapping(input$organism)$db_mapping$db
              pathway_positions <- optimizedGeneMatching(ranked_genes, pathway_genes_string, organism_db)
              
              if (length(pathway_positions) > 0) {
                # Create the ggplot object
                enrichment_plot <- createInteractiveGSEAPlot(
                  ranked_genes,
                  pathway_positions,
                  selected_pathway$Description[1],
                  selected_pathway$NES[1],
                  selected_pathway$pvalue[1]
                )
                
                # Save the ggplot object using ggsave
                ggsave(
                  filename = file,
                  plot = enrichment_plot,
                  width = 12,
                  height = 10,
                  dpi = 300,
                  bg = "white"
                )
                
              } else {
                # Create error plot with ggplot
                error_plot <- ggplot() +
                  annotate("text", x = 0.5, y = 0.5,
                           label = "Gene matching failed",
                           size = 8, color = "red") +
                  theme_void() +
                  theme(panel.background = element_rect(fill = "white"))
                
                ggsave(filename = file, plot = error_plot,
                       width = 12, height = 10, dpi = 300, bg = "white")
              }
            } else {
              # Create error plot with ggplot
              error_plot <- ggplot() +
                annotate("text", x = 0.5, y = 0.5,
                         label = "No gene data available",
                         size = 8, color = "orange") +
                theme_void() +
                theme(panel.background = element_rect(fill = "white"))
              
              ggsave(filename = file, plot = error_plot,
                     width = 12, height = 10, dpi = 300, bg = "white")
            }
          } else {
            # Create error plot with ggplot
            error_plot <- ggplot() +
              annotate("text", x = 0.5, y = 0.5,
                       label = "Pathway not found",
                       size = 8, color = "red") +
              theme_void() +
              theme(panel.background = element_rect(fill = "white"))
            
            ggsave(filename = file, plot = error_plot,
                   width = 12, height = 10, dpi = 300, bg = "white")
          }
          
        }, error = function(e) {
          # Create error plot with ggplot
          error_plot <- ggplot() +
            annotate("text", x = 0.5, y = 0.5,
                     label = paste("Error:", e$message),
                     size = 6, color = "red") +
            theme_void() +
            theme(panel.background = element_rect(fill = "white"))
          
          ggsave(filename = file, plot = error_plot,
                 width = 12, height = 10, dpi = 300, bg = "white")
        })
        
      } else {
        # For ggplot2 plots (dotplot, barplot) - UPDATED VERSION
        req(gsea_results())
        
        results <- gsea_results()
        if ("Message" %in% colnames(results) || "Error" %in% colnames(results)) {
          return()
        }
        
        tryCatch({
          if (input$plotType == "dotplot") {
            plot_data <- results %>%
              arrange(p.adjust) %>%
              head(input$numPathwaysToShow) %>%
              mutate(
                log10p = -log10(p.adjust),
                Direction = ifelse(NES > 0, "Upregulated", "Downregulated"),
                # Add database ID in brackets
                pathway_display = paste0(Description, " [", Database, "]"),
                pathway_short = ifelse(nchar(pathway_display) > 80,
                                       paste0(substr(pathway_display, 1, 77), "..."),
                                       pathway_display)
              )
            
            # UPDATED DOT PLOT - Color by significance
            p <- ggplot(plot_data, aes(x = NES, y = reorder(pathway_short, log10p))) +
              geom_point(aes(size = setSize, color = log10p), alpha = 0.8) +
              scale_color_gradient2(
                low = "blue",
                mid = "white",
                high = "red",
                midpoint = median(plot_data$log10p),
                name = "-log10\n(adj. p-val)"
              ) +
              scale_size_continuous(name = "Gene Count", range = c(3, 8)) +
              geom_vline(xintercept = 0, linetype = "dashed", alpha = 0.7, color = "gray50") +
              labs(
                title = paste("Top", input$numPathwaysToShow, "GSEA Pathways"),
                subtitle = "Database in brackets • Color = significance • Size = gene count",
                x = "Normalized Enrichment Score (NES)",
                y = "Pathway"
              ) +
              theme_minimal() +
              theme(
                axis.text.y = element_text(size = 10),
                plot.title = element_text(face = "bold", size = 14),
                plot.subtitle = element_text(size = 11, color = "gray60"),
                legend.position = "right",
                panel.grid.major.y = element_line(color = "gray90", linetype = "dotted"),
                panel.grid.minor = element_blank()
              )
            
          } else if (input$plotType == "barplot") {
            plot_data <- results %>%
              arrange(p.adjust) %>%
              head(input$numPathwaysToShow) %>%
              mutate(
                log10p = -log10(p.adjust),
                Direction = ifelse(NES > 0, "Upregulated", "Downregulated"),
                # Add database ID in brackets
                pathway_display = paste0(Description, " [", Database, "]"),
                pathway_short = ifelse(nchar(pathway_display) > 80,
                                       paste0(substr(pathway_display, 1, 77), "..."),
                                       pathway_display)
              )
            
            # UPDATED BAR PLOT - Color by regulation direction
            p <- ggplot(plot_data, aes(x = reorder(pathway_short, log10p), y = log10p)) +
              geom_col(aes(fill = Direction), alpha = 0.8, width = 0.7) +
              scale_fill_manual(
                values = c("Upregulated" = "#d73027", "Downregulated" = "#4575b4"),
                name = "Regulation"
              ) +
              coord_flip() +
              labs(
                title = paste("Top", input$numPathwaysToShow, "GSEA Pathways"),
                subtitle = "Database in brackets • Color = regulation direction • Height = significance",
                x = "Pathway",
                y = "-log10(Adjusted P-value)"
              ) +
              theme_minimal() +
              theme(
                axis.text.y = element_text(size = 10),
                plot.title = element_text(face = "bold", size = 14),
                plot.subtitle = element_text(size = 11, color = "gray60"),
                legend.position = "bottom",
                panel.grid.major.x = element_line(color = "gray90", linetype = "dotted"),
                panel.grid.minor = element_blank()
              )
          }
          
          # Save the ggplot
          ggsave(file, plot = p, width = 12, height = 8, dpi = 300, bg = "white")
          
        }, error = function(e) {
          # Create a simple error plot and save as PNG
          png(file, width = 12, height = 8, units = "in", res = 300, bg = "white")
          plot(1, type = "n", axes = FALSE, xlab = "", ylab = "")
          text(1, 1, paste("Error creating plot:", e$message), cex = 1.5, col = "red")
          dev.off()
        })
      }
    }
  )
  
  
  output$database_summary_cards <- renderUI({
