  #########################################################################
  
  
  # Reactive value for GO Analysis processed data
  go_processed_data <- eventReactive(input$go_file, {
    req(input$go_file)
    
    tryCatch({
      # Read the uploaded file for GO analysis
      df <- read.csv(input$go_file$datapath, header = TRUE)
      
      # Check if essential columns are present
      if (!input$go_gene_id_col %in% colnames(df) || !input$go_logfc_col %in% colnames(df)) {
        stop("Invalid column names selected for Gene ID or Log2 Fold Change.")
      }
      
      # Rename columns for easier handling
      df <- df %>%
        rename(gene_id = input$go_gene_id_col, logFC = input$go_logfc_col)
      
      # Remove rows with missing gene IDs or logFC values
      df <- df %>%
        filter(!is.na(gene_id) & !is.na(logFC))
      
      # Gene ID conversion for GO analysis
      if (input$go_input_id_type == "ensembl_ids") {
        keytype <- "ENSEMBL"
      } else if (input$go_input_id_type == "entrez_ids") {
        keytype <- "ENTREZID"
      } else {
        keytype <- "SYMBOL" # Assume SYMBOL if it's gene names
      }
      
      if (input$organism_go == "human") {
        df$entrez_ids <- mapIds(org.Hs.eg.db, keys = df$gene_id, column = "ENTREZID", keytype = keytype, multiVals = "first")
        df$gene_names <- mapIds(org.Hs.eg.db, keys = df$gene_id, column = "SYMBOL", keytype = keytype, multiVals = "first")
        df$ensembl_ids <- mapIds(org.Hs.eg.db, keys = df$gene_id, column = "ENSEMBL", keytype = keytype, multiVals = "first")
      } else if (input$organism_go == "mouse") {
        df$entrez_ids <- mapIds(org.Mm.eg.db, keys = df$gene_id, column = "ENTREZID", keytype = keytype, multiVals = "first")
        df$gene_names <- mapIds(org.Mm.eg.db, keys = df$gene_id, column = "SYMBOL", keytype = keytype, multiVals = "first")
        df$ensembl_ids <- mapIds(org.Mm.eg.db, keys = df$gene_id, column = "ENSEMBL", keytype = keytype, multiVals = "first")
      } else if (input$organism_go == "rat") {
        df$entrez_ids <- mapIds(org.Rn.eg.db, keys = df$gene_id, column = "ENTREZID", keytype = keytype, multiVals = "first")
        df$gene_names <- mapIds(org.Rn.eg.db, keys = df$gene_id, column = "SYMBOL", keytype = keytype, multiVals = "first")
        df$ensembl_ids <- mapIds(org.Rn.eg.db, keys = df$gene_id, column = "ENSEMBL", keytype = keytype, multiVals = "first")
      }
      
      # Handle missing values after conversion (e.g., remove rows)
      df <- df %>% filter(!is.na(entrez_ids) | !is.na(gene_names) | !is.na(ensembl_ids))
      
      # Handle duplicates
      df <- df %>%
        # First create a long format, but only for ID columns
        pivot_longer(
          cols = c(entrez_ids, gene_names, ensembl_ids),
          names_to = "id_type",
          values_to = "converted_gene_id"
        ) %>%
        # Remove any NA values in the converted IDs
        filter(!is.na(converted_gene_id)) %>%
        # Group by the converted ID to handle duplicates
        group_by(converted_gene_id) %>%
        # Keep only the row with the highest absolute logFC for each gene ID
        slice_max(order_by = abs(logFC), n = 1, with_ties = FALSE) %>%
        ungroup() %>%
        # Convert back to wide format
        pivot_wider(
          names_from = id_type,
          values_from = converted_gene_id
        )
      
    }, error = function(e) {
      # Error handling: Display user-friendly error message
      showModal(modalDialog(
        title = "Error",
        paste("An error occurred during data processing for GO analysis:", e$message),
        easyClose = TRUE
      ))
      return(NULL)
    })
  })
  
  # Create reactive value for storing pathway results
  pathway_results <- eventReactive(input$run_pathway_analysis, {
    run_pathway_analysis()
  })
  
  # Modal UI for plots
  output$pathwayPlotModal <- renderUI({
    modalDialog(
      title = "Pathway Enrichment Plot",
      size = "l",
      div(
        style = "margin-bottom: 15px;",
        selectInput("modal_num_pathways",
                    "Number of Pathways to Display:",
                    choices = c(5, 10, 15, 20),
                    selected = 10,
                    width = "200px")
      ),
      plotOutput("modalPathwayPlot", height = "600px"),
      footer = tagList(
        downloadButton("downloadModalPlot", "Download Plot"),
        modalButton("Close")
      )
    )
  })
  
  # Pathway Analysis function
  run_pathway_analysis <- eventReactive(input$run_pathway_analysis, {
    req(pathway_processed_data())
    
    selected_databases <- reactive({
      req(input$pathway_db_gsea)
      input$pathway_db_gsea
    })
    
    withProgress(message = "Running Pathway Analysis...", value = 0, {
      tryCatch({
        df <- pathway_processed_data()
        
        # Get threshold values from UI
        pvalue_cutoff <- input$pvalue_threshold
        qvalue_cutoff <- input$qvalue_threshold
        adjust_method <- input$adjust_method
        
        # Prepare gene list
        gene_list <- df$logFC
        results <- list()
        
        # Remove any NA values and prepare gene list
        valid_indices <- !is.na(df$entrez_ids)
        gene_list_filtered <- gene_list[valid_indices]
        names(gene_list_filtered) <- df$entrez_ids[valid_indices]
        gene_list_filtered <- sort(gene_list_filtered, decreasing = TRUE)
        
        # Database-specific analyses with progress updates
        if ("kegg" %in% selected_databases()) {
          incProgress(0.2, detail = "Running KEGG analysis")
          organism <- switch(input$organism_gsea,
                             "human" = "hsa",
                             "mouse" = "mmu",
                             "rat" = "rno")
          results$kegg <- gseKEGG(
            geneList = gene_list_filtered,
            organism = as.character(input$organism_deg_main %||% "human"),
            keyType = "ncbi-geneid",
            pvalueCutoff = pvalue_cutoff,
            pAdjustMethod = adjust_method,
            minGSSize = 10,
            maxGSSize = 500
          )
        }
        
        if ("reactome" %in% selected_databases()) {
          incProgress(0.4, detail = "Running Reactome analysis")
          results$reactome <- gsePathway(
            geneList = gene_list_filtered,
            organism = input$organism_gsea,
            pvalueCutoff = pvalue_cutoff,
            pAdjustMethod = adjust_method,
            minGSSize = 10,
            maxGSSize = 500
          )
        }
        
        if ("wikipathways" %in% selected_databases()) {
          incProgress(0.6, detail = "Running WikiPathways analysis")
          wp_organism <- switch(input$organism_gsea,
                                "human" = "Homo sapiens",
                                "mouse" = "Mus musculus",
                                "rat" = "Rattus norvegicus")
          results$wikipathways <- gseWP(
            geneList = gene_list_filtered,
            organism = wp_organism,
            pvalueCutoff = pvalue_cutoff,
            pAdjustMethod = adjust_method,
            minGSSize = 10,
            maxGSSize = 500
          )
        }
        
        incProgress(1, detail = "Analysis complete")
        return(results)
        
      }, error = function(e) {
        showNotification(paste("Error in Pathway analysis:", e$message), type = "error")
        return(NULL)
      })
    })
  })
  
  #New enrichment
  # Dynamic button label
  output$enrichment_button_label <- renderUI({
    if (input$enrichment_mode == "gsea") {
      tagList(icon("chart-line"), " Run GSEA")
    } else {
      tagList(icon("list-check"), " Run ORA")
    }
  })
  
  # Enrichment complete flag
  output$enrichment_complete <- reactive({
    !is.null(enrichment_rv$results) && length(enrichment_rv$results) > 0
  })
  outputOptions(output, "enrichment_complete", suspendWhenHidden = FALSE)
  
  # Gene count display for ORA
  output$ora_gene_count_display <- renderUI({
    # Get genes based on input type
    genes <- character(0)
    
    if (input$ora_inputType == "paste") {
      if (!is.null(input$ora_gene_list) && nchar(trimws(input$ora_gene_list)) > 0) {
        genes <- parse_gene_list(input$ora_gene_list)
      }
    } else if (input$ora_inputType == "upload" && !is.null(input$ora_gene_file)) {
      file_content <- tryCatch({
        readLines(input$ora_gene_file$datapath, warn = FALSE)
      }, error = function(e) character(0))
      genes <- parse_gene_list(paste(file_content, collapse = "\n"))
    } else if (input$ora_inputType == "deg_results" && !is.null(deg_data())) {
      filtered <- deg_data() %>%
        dplyr::filter(padj <= input$ora_deg_pval, abs(log2FoldChange) >= input$ora_deg_logfc)
      
      if (input$ora_deg_direction == "up") {
        filtered <- filtered %>% dplyr::filter(log2FoldChange > 0)
      } else if (input$ora_deg_direction == "down") {
        filtered <- filtered %>% dplyr::filter(log2FoldChange < 0)
      }
      
      # Try different column names for gene symbols
      if ("gene_symbol" %in% colnames(filtered)) {
        genes <- filtered$gene_symbol
      } else if ("gene" %in% colnames(filtered)) {
        genes <- filtered$gene
      } else if ("Gene" %in% colnames(filtered)) {
        genes <- filtered$Gene
      } else if ("symbol" %in% colnames(filtered)) {
        genes <- filtered$symbol
      } else {
        genes <- rownames(filtered)
      }
      genes <- unique(genes[!is.na(genes)])
    }
    
    gene_count <- length(genes)
    
    if (gene_count == 0) {
      return(NULL)
    }
    
    # Detect gene ID type
    detected_type <- detect_gene_id_type(genes)
    
    # Determine status color and message
    if (gene_count >= 20 && gene_count <= 500) {
      color <- "#28a745"
      status_msg <- "Optimal range for ORA"
      bg_color <- "#d4edda"
    } else if (gene_count < 20) {
      color <- "#ff9800"
      status_msg <- "Consider adding more genes (20+ recommended)"
      bg_color <- "#fff3cd"
    } else {
      color <- "#ff9800"
      status_msg <- "Large gene list - consider filtering more stringently"
      bg_color <- "#fff3cd"
    }
    
    # Gene type badge
    type_info <- switch(
      detected_type$type,
      "SYMBOL" = list(bg = "#4caf50", icon = "font", label = "Gene Symbols"),
      "ENSG" = list(bg = "#2196f3", icon = "dna", label = "Ensembl Gene IDs"),
      "ENST" = list(bg = "#9c27b0", icon = "dna", label = "Ensembl Transcript IDs"),
      "ENTREZ" = list(bg = "#ff9800", icon = "hashtag", label = "Entrez IDs"),
      list(bg = "#9e9e9e", icon = "question", label = "Mixed/Unknown")
    )
    
    div(
      style = paste0("background: ", bg_color, "; padding: 15px; border-radius: 8px; border-left: 4px solid ", color, ";"),
      
      # Main count with type badge
      div(
        style = "display: flex; align-items: center; flex-wrap: wrap; gap: 10px;",
        div(
          style = "display: flex; align-items: center;",
          icon("check-circle", style = paste0("color: ", color, "; font-size: 22px; margin-right: 10px;")),
          strong(paste0(gene_count, " genes selected"), style = "font-size: 17px; color: #333;")
        ),
        tags$span(
          style = paste0("background: ", type_info$bg, "; color: white; padding: 4px 10px; border-radius: 4px; font-size: 13px;"),
          icon(type_info$icon), " ", type_info$label
        )
      ),
      
      # Status message
      div(
        style = paste0("font-size: 14px; color: ", color, "; margin-top: 10px;"),
        icon(if(gene_count >= 20 && gene_count <= 500) "check" else "exclamation-triangle"),
        " ", status_msg
      ),
      
      # Conversion notice if not symbols
      if (detected_type$type != "SYMBOL" && detected_type$confidence >= 50) {
        div(
          style = "font-size: 13px; color: #666; margin-top: 8px;",
          icon("exchange-alt", style = "color: #2196f3;"),
          " Will auto-convert to gene symbols for analysis"
        )
      }
    )
  })
  
  # Parse gene list helper
  parse_gene_list <- function(text) {
    # Safety checks
    if (is.null(text)) return(character(0))
    if (length(text) == 0) return(character(0))
    if (is.na(text[1])) return(character(0))
    
    # Convert to single string if vector
    if (length(text) > 1) {
      text <- paste(text, collapse = "\n")
    }
    
    # Trim and check if empty
    text <- trimws(as.character(text))
    if (text == "" || nchar(text) == 0) return(character(0))
    
    # Replace all common delimiters with newlines
    text <- gsub(",", "\n", text)           # Commas
    text <- gsub(";", "\n", text)           # Semicolons
    text <- gsub("\t", "\n", text)          # Tabs
    text <- gsub("\\s{2,}", "\n", text)     # Multiple spaces
    text <- gsub("\r\n", "\n", text)        # Windows line endings
    text <- gsub("\r", "\n", text)          # Old Mac line endings
    
    # Split by newlines
    genes <- unlist(strsplit(text, "\n", fixed = TRUE))
    
    # Clean each gene
    genes <- trimws(genes)
    genes <- genes[genes != ""]
    genes <- genes[!is.na(genes)]
    genes <- genes[nchar(genes) > 0]
    
    # Remove duplicates
    genes <- unique(genes)
    
    # Debug
    print(paste("parse_gene_list: Found", length(genes), "unique genes"))
    
    return(genes)
  }
  
  detect_gene_id_type <- function(genes) {
    if (length(genes) == 0) return(list(type = "unknown", confidence = 0))
    
    # Sample first 20 genes for detection
    sample_genes <- head(genes, 20)
    
    # Count matches for each type
    n_ensg <- sum(grepl("^ENSG[0-9]{11}", sample_genes, ignore.case = TRUE))
    n_enst <- sum(grepl("^ENST[0-9]{11}", sample_genes, ignore.case = TRUE))
    n_ensp <- sum(grepl("^ENSP[0-9]{11}", sample_genes, ignore.case = TRUE))
    n_entrez <- sum(grepl("^[0-9]+$", sample_genes))
    n_symbol <- sum(grepl("^[A-Za-z][A-Za-z0-9\\-\\.]+$", sample_genes) & 
                      !grepl("^ENS[GTPE]", sample_genes, ignore.case = TRUE))
    
    total <- length(sample_genes)
    
    # Determine type based on majority
    counts <- c(
      ENSG = n_ensg,
      ENST = n_enst,
      ENSP = n_ensp,
      ENTREZ = n_entrez,
      SYMBOL = n_symbol
    )
    
    best_type <- names(which.max(counts))
    confidence <- max(counts) / total
    
    # Map to standard keyType names
    keytype_map <- c(
      ENSG = "ENSEMBL",
      ENST = "ENSEMBLTRANS",
      ENSP = "ENSEMBLPROT",
      ENTREZ = "ENTREZID",
      SYMBOL = "SYMBOL"
    )
    
    result <- list(
      type = best_type,
      keytype = keytype_map[best_type],
      confidence = round(confidence * 100, 1),
      detected_count = max(counts),
      total_checked = total,
      details = counts
    )
    
    print(paste("Gene ID type detected:", best_type, "with", result$confidence, "% confidence"))
    
    return(result)
  }
  
  
  # Convert genes to symbols if needed
  convert_to_symbols <- function(genes, detected_type, organism = "hsapiens") {
    
    if (detected_type$keytype == "SYMBOL") {
      # Already symbols, just uppercase
      return(toupper(genes))
    }
    
    # Get the appropriate OrgDb
    orgdb <- switch(organism,
                    "hsapiens" = org.Hs.eg.db::org.Hs.eg.db,
                    "mmusculus" = org.Mm.eg.db::org.Mm.eg.db,
                    "rnorvegicus" = org.Rn.eg.db::org.Rn.eg.db,
                    org.Hs.eg.db::org.Hs.eg.db)
    
    tryCatch({
      # Map to symbols
      symbols <- AnnotationDbi::mapIds(
        orgdb,
        keys = genes,
        column = "SYMBOL",
        keytype = detected_type$keytype,
        multiVals = "first"
      )
      
      # Remove NAs and return
      symbols <- symbols[!is.na(symbols)]
      print(paste("Converted", length(symbols), "genes to symbols"))
      
      return(as.character(symbols))
      
    }, error = function(e) {
      print(paste("Error converting gene IDs:", e$message))
      # Return original genes if conversion fails
      return(genes)
    })
  }
  
  # GSEA file upload status
  gsea_uploaded_genes <- reactiveVal(NULL)
  
  # Monitor file upload and validate
  observeEvent(input$gsea_prerankedFile, {
    req(input$gsea_prerankedFile)
    
    tryCatch({
      file_path <- input$gsea_prerankedFile$datapath
      file_name <- input$gsea_prerankedFile$name
      file_ext <- tools::file_ext(file_name)
      
      # Read file to count genes
      if (file_ext == "csv") {
        data <- read.csv(file_path, stringsAsFactors = FALSE, check.names = FALSE)
      } else if (file_ext == "rnk") {
        data <- read.table(file_path, header = FALSE, sep = "\t", stringsAsFactors = FALSE, fill = TRUE)
      } else {
        # Auto-detect
        first_lines <- readLines(file_path, n = 3)
        sep <- if (any(grepl("\t", first_lines))) "\t" else if (any(grepl(",", first_lines))) "," else ""
        has_header <- grepl("gene|symbol|score|rank|fc", tolower(first_lines[1]))
        data <- read.table(file_path, header = has_header, sep = sep, stringsAsFactors = FALSE, fill = TRUE)
      }
      
      # Get gene count
      total_rows <- nrow(data)
      n_cols <- ncol(data)
      
      # Count unique genes (first column)
      genes <- as.character(data[[1]])
      genes <- genes[genes != "" & !is.na(genes)]
      unique_genes <- length(unique(genes))
      
      # Determine format type
      format_type <- if (n_cols == 1) "Single column (position-ranked)" else paste(n_cols, "columns detected")
      
      # Store info
      gsea_uploaded_genes(list(
        filename = file_name,
        total_rows = total_rows,
        unique_genes = unique_genes,
        n_cols = n_cols,
        format_type = format_type,
        score_range = if (n_cols >= 2) {
          scores <- suppressWarnings(as.numeric(data[[2]]))
          scores <- scores[!is.na(scores)]
          if (length(scores) > 0) paste(round(min(scores), 2), "to", round(max(scores), 2)) else "N/A"
        } else "Position-based"
      ))
      
    }, error = function(e) {
      gsea_uploaded_genes(list(error = e$message))
    })
  })
  
  # Render file status UI
  output$gsea_file_status <- renderUI({
    info <- gsea_uploaded_genes()
    
    if (is.null(info)) {
      return(NULL)
    }
    
    if (!is.null(info$error)) {
      return(div(
        style = "background: #ffebee; padding: 10px; border-radius: 6px; border-left: 4px solid #f44336; margin-top: 10px;",
        icon("exclamation-circle", style = "color: #f44336;"),
        strong(" Error reading file: "), info$error
      ))
    }
    
    # Determine status color based on gene count
    if (info$unique_genes < 100) {
      status_style <- "background: #fff3e0; border-left: 4px solid #ff9800;"
      status_icon <- icon("exclamation-triangle", style = "color: #ff9800;")
      status_msg <- "Warning: Less than 100 genes. GSEA requires at least 100 genes."
    } else if (info$unique_genes < 1000) {
      status_style <- "background: #e3f2fd; border-left: 4px solid #2196f3;"
      status_icon <- icon("info-circle", style = "color: #2196f3;")
      status_msg <- "Acceptable gene count, but more genes typically give better results."
    } else {
      status_style <- "background: #e8f5e9; border-left: 4px solid #4caf50;"
      status_icon <- icon("check-circle", style = "color: #4caf50;")
      status_msg <- "Good gene count for GSEA analysis!"
    }
    
    div(
      style = paste("padding: 12px; border-radius: 6px; margin-top: 10px;", status_style),
      
      div(style = "display: flex; align-items: center; margin-bottom: 8px;",
          status_icon,
          strong(style = "margin-left: 8px;", paste(" File:", info$filename))
      ),
      
      div(style = "display: grid; grid-template-columns: 1fr 1fr; gap: 5px; font-size: 0.85rem;",
          div(icon("list-ol"), paste(" Total rows:", format(info$total_rows, big.mark = ","))),
          div(icon("dna"), paste(" Unique genes:", format(info$unique_genes, big.mark = ","))),
          div(icon("columns"), paste(" Format:", info$format_type)),
          div(icon("chart-line"), paste(" Score range:", info$score_range))
      ),
      
      if (info$total_rows != info$unique_genes) {
        div(style = "margin-top: 8px; font-size: 0.8rem; color: #666;",
            icon("info-circle"), 
            paste(" Note:", info$total_rows - info$unique_genes, "duplicate genes will be removed")
        )
      },
      
      div(style = "margin-top: 8px; font-size: 0.85rem;", status_msg)
    )
  })
  
  
  get_ora_gene_list <- function() {
    genes <- character(0)
    
    if (input$ora_inputType == "paste") {
      # Paste gene list
      if (!is.null(input$ora_gene_list) && nchar(trimws(input$ora_gene_list)) > 0) {
        genes <- parse_gene_list(input$ora_gene_list)
      }
      
    } else if (input$ora_inputType == "upload") {
      # Upload gene file
      req(input$ora_gene_file)
      file_content <- tryCatch({
        readLines(input$ora_gene_file$datapath, warn = FALSE)
      }, error = function(e) {
        print(paste("Error reading file:", e$message))
        character(0)
      })
      genes <- parse_gene_list(paste(file_content, collapse = "\n"))
      
    } else if (input$ora_inputType == "deg_results") {
      # Use DEG results - safely access without req()
      deg_df <- tryCatch({
        if (!is.null(rv_deg_main$deg_results) && nrow(rv_deg_main$deg_results) > 0) {
          rv_deg_main$deg_results
        } else {
          NULL
        }
      }, error = function(e) NULL)
      
      if (!is.null(deg_df)) {
        filtered <- deg_df %>%
          dplyr::filter(padj <= input$ora_deg_pval, abs(log2FoldChange) >= input$ora_deg_logfc)
        
        if (input$ora_deg_direction == "up") {
          filtered <- filtered %>% dplyr::filter(log2FoldChange > 0)
        } else if (input$ora_deg_direction == "down") {
          filtered <- filtered %>% dplyr::filter(log2FoldChange < 0)
        }
        
        # Try different column names for gene symbols
        if ("gene_symbol" %in% colnames(filtered)) {
          genes <- filtered$gene_symbol
        } else if ("gene" %in% colnames(filtered)) {
          genes <- filtered$gene
        } else if ("Gene" %in% colnames(filtered)) {
          genes <- filtered$Gene
        } else if ("symbol" %in% colnames(filtered)) {
          genes <- filtered$symbol
        } else if ("SYMBOL" %in% colnames(filtered)) {
          genes <- filtered$SYMBOL
        } else {
          genes <- rownames(filtered)
        }
      }
      
    } else if (input$ora_inputType == "cluster") {
      # Use gene cluster/module (from WGCNA or similar)
      req(input$ora_cluster_selection)
      
      # Try to get genes from WGCNA modules if available
      if (!is.null(network_rv$current_results$wgcna_results)) {
        module_genes <- network_rv$current_results$wgcna_results$module_genes
        if (!is.null(module_genes) && input$ora_cluster_selection %in% names(module_genes)) {
          genes <- module_genes[[input$ora_cluster_selection]]
        }
      }
    }
    
    # Clean and deduplicate
    genes <- unique(genes[!is.na(genes) & genes != ""])
    
    # Detect gene ID type
    if (length(genes) > 0) {
      detected_type <- detect_gene_id_type(genes)
      
      # For GO analysis, we need gene symbols
      # Convert if they're Ensembl IDs
      if (detected_type$type %in% c("ENSG", "ENST") && detected_type$confidence >= 50) {
        print(paste("Converting", detected_type$type, "IDs to gene symbols for analysis"))
        genes <- convert_to_symbols(genes, detected_type, input$enrichment_organism)
      } else if (detected_type$type == "SYMBOL") {
        # Only uppercase for human - other organisms have different conventions
        # Mouse: Tp53, Rat: Tp53, Zebrafish: tp53, Fly: varies
        if (input$enrichment_organism == "hsapiens") {
          genes <- toupper(genes)
        }
        # For non-human organisms, preserve original case
      }
      # If ENTREZ, keep as is - will be handled by individual analysis functions
    }
    
    print(paste("get_ora_gene_list: Returning", length(genes), "genes"))
    return(genes)
  }
  
  
  # ============================================================================
  # 2. GET ORA BACKGROUND - Retrieves background gene set
  # ============================================================================
  
  get_ora_background <- function() {
    background <- NULL
    
    if (input$ora_background == "expressed") {
      # Use all genes from DEG data as background
      # This represents all genes that were tested in the differential expression analysis
      
      # IMPORTANT: Safely check for DEG data without triggering req() abort
      deg_df <- tryCatch({
        # Check if DEG results exist before calling the reactive
        if (!is.null(rv_deg_main$deg_results) && nrow(rv_deg_main$deg_results) > 0) {
          rv_deg_main$deg_results
        } else {
          NULL
        }
      }, error = function(e) {
        print(paste("Error accessing DEG data:", e$message))
        NULL
      })
      
      if (!is.null(deg_df) && nrow(deg_df) > 0) {
        # Try different column names for gene symbols
        if ("gene_symbol" %in% colnames(deg_df)) {
          background <- unique(deg_df$gene_symbol)
        } else if ("gene" %in% colnames(deg_df)) {
          background <- unique(deg_df$gene)
        } else if ("Gene" %in% colnames(deg_df)) {
          background <- unique(deg_df$Gene)
        } else if ("symbol" %in% colnames(deg_df)) {
          background <- unique(deg_df$symbol)
        } else if ("SYMBOL" %in% colnames(deg_df)) {
          background <- unique(deg_df$SYMBOL)
        } else if ("gene_id" %in% colnames(deg_df)) {
          background <- unique(deg_df$gene_id)
        } else {
          # Use rownames as last resort
          background <- unique(rownames(deg_df))
        }
        
        # Clean up
        background <- background[!is.na(background) & background != ""]
        
        if (length(background) > 0) {
          print(paste("get_ora_background: Using", length(background), "expressed genes from DEG data"))
        }
      }
      
      # If no background found, show notification and use NULL
      if (is.null(background) || length(background) == 0) {
        showNotification(
          "No DEG data available for background. Using all genes in database instead.", 
          type = "warning", 
          duration = 5
        )
        print("Warning: No expressed genes found in DEG data, using all genes in database")
        return(NULL)
      }
      
    } else if (input$ora_background == "all") {
      # Use all genes in database - return NULL to let clusterProfiler use default
      print("get_ora_background: Using all genes in database (NULL background)")
      return(NULL)
      
    } else if (input$ora_background == "custom") {
      # Custom background provided by user
      if (!is.null(input$ora_custom_background) && nchar(trimws(input$ora_custom_background)) > 0) {
        background <- parse_gene_list(input$ora_custom_background)
        
        if (length(background) > 0) {
          print(paste("get_ora_background: Using", length(background), "custom background genes"))
        } else {
          showNotification("Custom background is empty. Using all genes in database.", type = "warning")
          return(NULL)
        }
      } else {
        showNotification("No custom background provided. Using all genes in database.", type = "warning")
        print("Warning: Custom background selected but no genes provided")
        return(NULL)
      }
    }
    
    # Clean and uppercase background genes
    if (!is.null(background) && length(background) > 0) {
      background <- unique(background[!is.na(background) & background != ""])
      background <- toupper(background)
      print(paste("get_ora_background: Returning", length(background), "background genes"))
    }
    
    return(background)
  }
  
  
  # ============================================================================
  # 3. GET GSEA RANKED GENES - Retrieves ranked gene list for GSEA
  # ============================================================================
  
  get_gsea_ranked_genes <- function() {
    ranked_genes <- NULL
    
    if (input$gsea_inputType == "preranked") {
      # Pre-ranked file upload
      req(input$gsea_prerankedFile)
      
      tryCatch({
        # Read file
        file_path <- input$gsea_prerankedFile$datapath
        file_ext <- tools::file_ext(input$gsea_prerankedFile$name)
        file_name <- input$gsea_prerankedFile$name
        
        print(paste("Reading preranked file:", file_name))
        
        # Try different reading methods
        data <- NULL
        
        if (file_ext == "csv") {
          # Try with header first
          data <- tryCatch({
            d <- read.csv(file_path, stringsAsFactors = FALSE, check.names = FALSE)
            # Check if first row looks like data (numeric in col 2)
            if (ncol(d) >= 2 && !is.na(suppressWarnings(as.numeric(d[1, 2])))) {
              d
            } else {
              d
            }
          }, error = function(e) NULL)
          
          # If that failed, try without header
          if (is.null(data) || nrow(data) == 0) {
            data <- read.csv(file_path, header = FALSE, stringsAsFactors = FALSE)
          }
        } else if (file_ext == "rnk") {
          # RNK files typically have no header, tab-separated
          data <- read.table(file_path, header = FALSE, sep = "\t", 
                             stringsAsFactors = FALSE, fill = TRUE, quote = "")
        } else {
          # TXT and other files - try to auto-detect
          # First, peek at the file to determine separator
          first_lines <- readLines(file_path, n = 5)
          
          # Detect separator
          if (any(grepl("\t", first_lines))) {
            sep <- "\t"
          } else if (any(grepl(",", first_lines))) {
            sep <- ","
          } else {
            sep <- ""  # whitespace
          }
          
          # Check if first line looks like a header
          first_line <- first_lines[1]
          has_header <- grepl("gene|symbol|id|name|score|rank|fc|log", 
                              tolower(first_line), ignore.case = TRUE)
          
          data <- read.table(file_path, header = has_header, sep = sep, 
                             stringsAsFactors = FALSE, fill = TRUE, quote = "")
        }
        
        print(paste("File dimensions:", nrow(data), "rows x", ncol(data), "cols"))
        print(paste("Column names:", paste(colnames(data), collapse = ", ")))
        
        if (is.null(data) || nrow(data) == 0) {
          showNotification("Could not read file. Please check format.", type = "error")
          return(NULL)
        }
        
        # Extract gene names and scores based on number of columns
        genes <- NULL
        scores <- NULL
        
        if (ncol(data) == 1) {
          # Single column: genes are already ranked by position
          # Create scores that span positive to negative (like log2FC)
          # Top genes get positive scores, bottom genes get negative scores
          genes <- as.character(data[[1]])
          genes <- genes[genes != "" & !is.na(genes)]
          n <- length(genes)
          
          # Create scores from +max to -max, centered at 0
          # This mimics log2FC distribution
          scores <- seq(from = 3, to = -3, length.out = n)
          
          print(paste("Single column detected - assigned scores from", 
                      round(max(scores), 2), "to", round(min(scores), 2)))
          
        } else if (ncol(data) >= 2) {
          # Two or more columns: find gene and score columns
          
          # Try to identify gene column (usually first, or named)
          gene_col_idx <- 1
          gene_col_names <- c("gene", "symbol", "gene_symbol", "geneid", "gene_id", 
                              "name", "genes", "id", "entrez", "ensembl")
          for (i in seq_len(ncol(data))) {
            if (tolower(colnames(data)[i]) %in% gene_col_names) {
              gene_col_idx <- i
              break
            }
          }
          
          # Try to identify score column
          score_col_idx <- NULL
          score_col_names <- c("log2foldchange", "log2fc", "logfc", "fc", "foldchange",
                               "score", "rank", "stat", "t", "nes", "metric", 
                               "ranking", "value", "signed_pval")
          
          for (i in seq_len(ncol(data))) {
            col_name <- tolower(gsub("[^a-z0-9]", "", colnames(data)[i]))
            if (col_name %in% gsub("[^a-z0-9]", "", score_col_names)) {
              score_col_idx <- i
              break
            }
          }
          
          # If no score column found by name, use first numeric column that's not gene column
          if (is.null(score_col_idx)) {
            for (i in seq_len(ncol(data))) {
              if (i != gene_col_idx) {
                test_vals <- suppressWarnings(as.numeric(data[[i]][1:min(10, nrow(data))]))
                if (sum(!is.na(test_vals)) > 5) {
                  score_col_idx <- i
                  break
                }
              }
            }
          }
          
          # Default to column 2 if nothing found
          if (is.null(score_col_idx)) score_col_idx <- 2
          
          print(paste("Using column", gene_col_idx, "for genes and column", score_col_idx, "for scores"))
          
          genes <- as.character(data[[gene_col_idx]])
          scores <- suppressWarnings(as.numeric(data[[score_col_idx]]))
        }
        
        # Clean up
        valid_idx <- !is.na(genes) & genes != "" & !is.na(scores)
        genes <- genes[valid_idx]
        scores <- scores[valid_idx]
        
        # Remove duplicates - keep the one with highest absolute score
        if (length(genes) > 0 && length(scores) > 0) {
          # Create data frame for processing
          gene_df <- data.frame(gene = genes, score = scores, stringsAsFactors = FALSE)
          
          # Check how many duplicates
          n_dups <- sum(duplicated(gene_df$gene))
          if (n_dups > 0) {
            print(paste("Found", n_dups, "duplicate gene entries"))
            
            # For duplicates, keep the entry with highest absolute score
            gene_df <- gene_df %>%
              dplyr::group_by(gene) %>%
              dplyr::slice_max(abs(score), n = 1, with_ties = FALSE) %>%
              dplyr::ungroup()
            
            print(paste("After removing duplicates:", nrow(gene_df), "unique genes"))
          }
          
          genes <- gene_df$gene
          scores <- gene_df$score
        }
        
        if (length(genes) == 0) {
          showNotification("No valid genes found in file. Check file format.", type = "error")
          return(NULL)
        }
        
        # Create named vector and sort
        ranked_genes <- setNames(scores, genes)
        ranked_genes <- sort(ranked_genes, decreasing = TRUE)
        
        print(paste("Successfully processed", length(ranked_genes), "genes"))
        print(paste("Score range:", round(min(ranked_genes), 3), "to", round(max(ranked_genes), 3)))
        
        showNotification(paste("Loaded", length(ranked_genes), "ranked genes"), type = "message")
        
      }, error = function(e) {
        print(paste("Error reading preranked file:", e$message))
        showNotification(paste("Error reading file:", e$message), type = "error")
        return(NULL)
      })
      
    } else if (input$gsea_inputType == "expression") {
      # Expression data - use column mapping if available
      req(input$gsea_expressionFile)
      
      tryCatch({
        # Use cached preview data if available, otherwise read file
        if (!is.null(gsea_expression_preview())) {
          data <- gsea_expression_preview()
        } else {
          data <- read.csv(input$gsea_expressionFile$datapath, stringsAsFactors = FALSE)
        }
        
        # Get gene column (use mapped column if available)
        gene_col <- if (!is.null(input$gsea_gene_column) && input$gsea_gene_column %in% colnames(data)) {
          input$gsea_gene_column
        } else if ("gene" %in% colnames(data)) {
          "gene"
        } else if ("Gene" %in% colnames(data)) {
          "Gene"
        } else if ("gene_symbol" %in% colnames(data)) {
          "gene_symbol"
        } else if ("SYMBOL" %in% colnames(data)) {
          "SYMBOL"
        } else {
          colnames(data)[1]
        }
        
        genes <- data[[gene_col]]
        
        # Get ranking method and column
        rank_method <- if (!is.null(input$gsea_custom_rank_method)) {
          input$gsea_custom_rank_method
        } else if (!is.null(input$gsea_rankMethod)) {
          input$gsea_rankMethod
        } else {
          "direct"
        }
        
        rank_col <- if (!is.null(input$gsea_rank_column) && input$gsea_rank_column %in% colnames(data)) {
          input$gsea_rank_column
        } else if ("log2FoldChange" %in% colnames(data)) {
          "log2FoldChange"
        } else if ("logFC" %in% colnames(data)) {
          "logFC"
        } else if ("stat" %in% colnames(data)) {
          "stat"
        } else {
          # First numeric column
          numeric_cols <- colnames(data)[sapply(data, is.numeric)]
          if (length(numeric_cols) > 0) numeric_cols[1] else NULL
        }
        
        pval_col <- if (!is.null(input$gsea_pval_column) && input$gsea_pval_column != "" && input$gsea_pval_column %in% colnames(data)) {
          input$gsea_pval_column
        } else if ("pvalue" %in% colnames(data)) {
          "pvalue"
        } else if ("PValue" %in% colnames(data)) {
          "PValue"
        } else if ("P.Value" %in% colnames(data)) {
          "P.Value"
        } else {
          NULL
        }
        
        # Calculate scores based on ranking method
        if (rank_method == "direct" && !is.null(rank_col)) {
          scores <- data[[rank_col]]
        } else if (rank_method == "logfc" && !is.null(rank_col)) {
          scores <- data[[rank_col]]
        } else if (rank_method == "signed_pval" && !is.null(pval_col) && !is.null(rank_col)) {
          # Signed -log10 p-value
          sign_fc <- sign(data[[rank_col]])
          sign_fc[sign_fc == 0] <- 1
          pvals <- data[[pval_col]]
          pvals[pvals == 0] <- .Machine$double.xmin  # Avoid log(0)
          scores <- -log10(pvals) * sign_fc
        } else if (rank_method == "tstat" && !is.null(rank_col)) {
          scores <- data[[rank_col]]
        } else {
          # Fallback: use first numeric column
          numeric_cols <- sapply(data, is.numeric)
          if (any(numeric_cols)) {
            scores <- data[[which(numeric_cols)[1]]]
          } else {
            showNotification("Could not find numeric column for ranking", type = "error")
            return(NULL)
          }
        }
        
        ranked_genes <- setNames(scores, genes)
        ranked_genes <- ranked_genes[!is.na(ranked_genes) & !is.na(names(ranked_genes))]
        ranked_genes <- ranked_genes[!duplicated(names(ranked_genes))]  # Remove duplicate genes
        ranked_genes <- sort(ranked_genes, decreasing = TRUE)
        
        print(paste("Expression data processed:", length(ranked_genes), "genes using", rank_method, "method"))
        
      }, error = function(e) {
        print(paste("Error processing expression file:", e$message))
        showNotification(paste("Error processing file:", e$message), type = "error")
      })
    }
    
    if (!is.null(ranked_genes)) {
      print(paste("get_gsea_ranked_genes: Returning", length(ranked_genes), "ranked genes"))
    }
    
    return(ranked_genes)
  }
  
  
  # ============================================================================
  # 4. GET GENE SETS - Retrieves pathway gene sets for GSEA
  # ============================================================================
  
  # Cache for gene sets to avoid repeated downloads
  gene_sets_cache <- reactiveValues(data = list())
  
  get_gene_sets <- function(database, organism) {
    
    # Map organism to msigdbr species
    species_map <- c(
      "hsapiens" = "Homo sapiens",
      "mmusculus" = "Mus musculus",
      "rnorvegicus" = "Rattus norvegicus",
      "drerio" = "Danio rerio",
      "dmelanogaster" = "Drosophila melanogaster",
      "scerevisiae" = "Saccharomyces cerevisiae",
      "celegans" = "Caenorhabditis elegans",
      "sscrofa" = "Sus scrofa",
      "ggallus" = "Gallus gallus",
      "cfamiliaris" = "Canis lupus familiaris",
      "btaurus" = "Bos taurus",
      "xlaevis" = "Xenopus tropicalis"  # msigdbr has tropicalis, close enough for laevis
    )
    # Note: athaliana and ecoli are NOT in msigdbr — they use clusterProfiler directly

    species <- species_map[organism]
    if (is.na(species)) species <- "Homo sapiens"
    
    print(paste("get_gene_sets: Loading", database, "for", species))
    
    tryCatch({
      gene_sets <- NULL
      
      # Check msigdbr version and use appropriate API
      msigdbr_version <- tryCatch({
        as.character(packageVersion("msigdbr"))
      }, error = function(e) "7.0.0")
      
      use_new_api <- compareVersion(msigdbr_version, "10.0.0") >= 0
      
      if (use_new_api) {
        # New msigdbr 10.0.0+ API uses 'collection' and 'subcollection'
        if (database == "GO_BP") {
          gene_sets <- msigdbr::msigdbr(species = species, collection = "C5", subcollection = "GO:BP")
        } else if (database == "GO_MF") {
          gene_sets <- msigdbr::msigdbr(species = species, collection = "C5", subcollection = "GO:MF")
        } else if (database == "GO_CC") {
          gene_sets <- msigdbr::msigdbr(species = species, collection = "C5", subcollection = "GO:CC")
        } else if (database == "KEGG") {
          # Try KEGG_MEDICUS first (newer), then KEGG_LEGACY, then original KEGG
          gene_sets <- tryCatch({
            msigdbr::msigdbr(species = species, collection = "C2", subcollection = "CP:KEGG_MEDICUS")
          }, error = function(e) NULL)
          
          if (is.null(gene_sets) || nrow(gene_sets) == 0) {
            gene_sets <- tryCatch({
              msigdbr::msigdbr(species = species, collection = "C2", subcollection = "CP:KEGG_LEGACY")
            }, error = function(e) NULL)
          }
          
          if (is.null(gene_sets) || nrow(gene_sets) == 0) {
            gene_sets <- tryCatch({
              msigdbr::msigdbr(species = species, collection = "C2", subcollection = "CP:KEGG")
            }, error = function(e) NULL)
          }
          
          if (is.null(gene_sets) || nrow(gene_sets) == 0) {
            print(paste("KEGG not available for", species, "- using all curated pathways"))
            gene_sets <- msigdbr::msigdbr(species = species, collection = "C2")
            # Filter for KEGG-related if possible
            if ("gs_subcat" %in% names(gene_sets)) {
              kegg_subset <- gene_sets[grepl("KEGG", gene_sets$gs_subcat, ignore.case = TRUE), ]
              if (nrow(kegg_subset) > 0) gene_sets <- kegg_subset
            }
          }
        } else if (database == "REACTOME") {
          gene_sets <- msigdbr::msigdbr(species = species, collection = "C2", subcollection = "CP:REACTOME")
        } else if (database == "WP" || database == "WIKIPATHWAYS") {
          gene_sets <- msigdbr::msigdbr(species = species, collection = "C2", subcollection = "CP:WIKIPATHWAYS")
        } else if (database == "HALLMARK") {
          gene_sets <- msigdbr::msigdbr(species = species, collection = "H")
        } else if (database == "BIOCARTA") {
          gene_sets <- msigdbr::msigdbr(species = species, collection = "C2", subcollection = "CP:BIOCARTA")
        } else {
          # Default to Hallmark
          gene_sets <- msigdbr::msigdbr(species = species, collection = "H")
        }
      } else {
        # Old msigdbr API (< 10.0.0) uses 'category' and 'subcategory'
        if (database == "GO_BP") {
          gene_sets <- msigdbr::msigdbr(species = species, category = "C5", subcategory = "GO:BP")
        } else if (database == "GO_MF") {
          gene_sets <- msigdbr::msigdbr(species = species, category = "C5", subcategory = "GO:MF")
        } else if (database == "GO_CC") {
          gene_sets <- msigdbr::msigdbr(species = species, category = "C5", subcategory = "GO:CC")
        } else if (database == "KEGG") {
          gene_sets <- msigdbr::msigdbr(species = species, category = "C2", subcategory = "CP:KEGG")
        } else if (database == "REACTOME") {
          gene_sets <- msigdbr::msigdbr(species = species, category = "C2", subcategory = "CP:REACTOME")
        } else if (database == "WP" || database == "WIKIPATHWAYS") {
          gene_sets <- msigdbr::msigdbr(species = species, category = "C2", subcategory = "CP:WIKIPATHWAYS")
        } else if (database == "HALLMARK") {
          gene_sets <- msigdbr::msigdbr(species = species, category = "H")
        } else {
          gene_sets <- msigdbr::msigdbr(species = species, category = "H")
        }
      }
      
      if (is.null(gene_sets) || nrow(gene_sets) == 0) {
        print(paste("Warning: No gene sets found for", database, "in", species))
        return(list())
      }
      
      # Convert to list format for fgsea
      gene_sets_list <- split(gene_sets$gene_symbol, gene_sets$gs_name)
      
      print(paste("get_gene_sets: Loaded", length(gene_sets_list), "gene sets from", database))
      return(gene_sets_list)
      
    }, error = function(e) {
      print(paste("Error loading gene sets for", database, ":", e$message))
      return(list())
    })
  }
  
  
  # ============================================================================
  # 5. OPTIONAL: UI OUTPUTS FOR DYNAMIC SELECTION
  # ============================================================================
  
  # DEG selection for ORA
  output$ora_deg_selection <- renderUI({
    deg_df <- tryCatch({
      if (!is.null(rv_deg_main$deg_results) && nrow(rv_deg_main$deg_results) > 0) {
        rv_deg_main$deg_results
      } else {
        NULL
      }
    }, error = function(e) {
      print(paste("Error accessing DEG data:", e$message))
      NULL
    })
    
    if (!is.null(deg_df) && nrow(deg_df) > 0) {
      div(
        style = "background: #e8f5e9; padding: 10px; border-radius: 6px;",
        icon("check-circle", style = "color: #4caf50;"),
        strong(paste(n_degs, "DEGs available")),
        p(style = "font-size: 13px; color: #666; margin: 5px 0 0 0;",
          "Use the sliders below to filter")
      )
    } else {
      div(
        style = "background: #fff3e0; padding: 10px; border-radius: 6px;",
        icon("exclamation-triangle", style = "color: #ff9800;"),
        " No DEG results available. Run DEG analysis first."
      )
    }
  })
  
  # DEG selection for GSEA
  output$gsea_deg_selection <- renderUI({
    if (!is.null(deg_data()) && nrow(deg_data()) > 0) {
      n_genes <- nrow(deg_data())
      div(
        style = "background: #e8f5e9; padding: 10px; border-radius: 6px;",
        icon("check-circle", style = "color: #4caf50;"),
        strong(paste(n_genes, "genes with expression data")),
        p(style = "font-size: 13px; color: #666; margin: 5px 0 0 0;",
          "Will rank by log2 fold change")
      )
    } else {
      div(
        style = "background: #fff3e0; padding: 10px; border-radius: 6px;",
        icon("exclamation-triangle", style = "color: #ff9800;"),
        " No DEG results available. Run DEG analysis first or upload data."
      )
    }
  })
  
  # Cluster selection for ORA
  output$ora_cluster_selection <- renderUI({
    if (!is.null(network_rv$current_results$wgcna_results)) {
      modules <- names(network_rv$current_results$wgcna_results$module_genes)
      selectInput("ora_cluster_selection", "Select module:",
                  choices = modules,
                  selected = modules[1])
    } else {
      div(
        style = "background: #fff3e0; padding: 10px; border-radius: 6px;",
        icon("exclamation-triangle", style = "color: #ff9800;"),
        " No WGCNA modules available. Run WGCNA analysis first."
      )
    }
  })
  
  # Update available databases based on organism selection
  observeEvent(input$enrichment_organism, {
    org <- input$enrichment_organism
    # GO and KEGG work for all organisms with OrgDb
    base_dbs <- c("GO: Biological Process" = "GO_BP",
                  "GO: Molecular Function" = "GO_MF",
                  "GO: Cellular Component" = "GO_CC",
                  "KEGG Pathways" = "KEGG")
    # Reactome: human, mouse, rat, zebrafish, fly, yeast, cow, dog, chicken, pig, frog
    reactome_orgs <- c("hsapiens", "mmusculus", "rnorvegicus", "drerio", "dmelanogaster",
                       "scerevisiae", "btaurus", "cfamiliaris", "ggallus", "sscrofa", "xlaevis")
    # WikiPathways: human, mouse, rat, zebrafish, fly, worm, yeast, Arabidopsis, cow, dog, chicken, pig
    wp_orgs <- c("hsapiens", "mmusculus", "rnorvegicus", "drerio", "dmelanogaster",
                 "celegans", "scerevisiae", "athaliana", "btaurus", "cfamiliaris", "ggallus", "sscrofa")
    # MSigDB Hallmark: human and mouse only
    hallmark_orgs <- c("hsapiens", "mmusculus")

    extra_dbs <- character(0)
    if (org %in% reactome_orgs) extra_dbs <- c(extra_dbs, "Reactome Pathways" = "REACTOME")
    if (org %in% wp_orgs) extra_dbs <- c(extra_dbs, "WikiPathways" = "WP")
    if (org %in% hallmark_orgs) extra_dbs <- c(extra_dbs, "Hallmark Gene Sets" = "HALLMARK")

    all_dbs <- c(base_dbs, extra_dbs)
    current_selected <- isolate(input$enrichment_databases)
    valid_selected <- intersect(current_selected, all_dbs)
    if (length(valid_selected) == 0) valid_selected <- c("GO_BP", "KEGG")

    updateCheckboxGroupInput(session, "enrichment_databases",
                             choices = all_dbs,
                             selected = valid_selected)
  }, ignoreInit = TRUE)

  # ============================================================================
  # MAIN ANALYSIS OBSERVER
  # ============================================================================

  observeEvent(input$run_enrichment_analysis, {
    
    req(input$enrichment_mode)
    req(input$enrichment_databases)
    
    # Show progress
    withProgress(message = 'Running Enrichment Analysis...', value = 0, {
      
      if (input$enrichment_mode == "gsea") {
        # ========================================
        # GSEA ANALYSIS
        # ========================================
        incProgress(0.1, detail = "Preparing ranked gene list...")
        
        # Get ranked gene list based on input type
        ranked_genes <- get_gsea_ranked_genes()
        
        if (is.null(ranked_genes) || length(ranked_genes) < 100) {
          showNotification("Need at least 100 genes for GSEA", type = "error")
          return()
        }

        # Ensembl / Entrez IDs (e.g. from the FASTQ pipeline) -> gene symbols
        if (isTRUE(tx_enr_key() %in% tx_curated_keys)) {
          rk_ids <- sub("\\.[0-9]+$", "", names(ranked_genes))
          n_ens <- sum(grepl("^ENS[A-Z]*G[0-9]", rk_ids))
          n_ent <- sum(grepl("^[0-9]+$", rk_ids))
          from_type <- if (n_ens > length(rk_ids) / 2) "ENSEMBL" else if (n_ent > length(rk_ids) / 2) "ENTREZID" else NULL
          if (!is.null(from_type)) {
            rk_sym <- tryCatch(AnnotationDbi::mapIds(get_orgdb(input$enrichment_organism), keys = rk_ids,
                                                     column = "SYMBOL", keytype = from_type, multiVals = "first"),
                               error = function(e) NULL)
            if (is.null(rk_sym)) {
              showNotification("Could not convert the gene IDs to gene symbols for this organism.", type = "error")
              return()
            }
            rk_keep <- !is.na(rk_sym) & nzchar(rk_sym)
            conv <- ranked_genes[rk_keep]
            names(conv) <- rk_sym[rk_keep]
            conv <- conv[order(-abs(conv))]
            conv <- conv[!duplicated(names(conv))]
            ranked_genes <- sort(conv, decreasing = TRUE)
            showNotification(sprintf("Converted %d %s IDs to gene symbols (%d could not be mapped and were left out).",
                                     sum(rk_keep), if (from_type == "ENSEMBL") "Ensembl" else "Entrez", sum(!rk_keep)),
                             type = "message", duration = 8)
            if (length(ranked_genes) < 100) {
              showNotification("Fewer than 100 genes remain after ID conversion; GSEA needs at least 100.", type = "error")
              return()
            }
          }
        }

        # Store ranked gene vector and per-DB gene set lists for Classic GSEA plot
        enrichment_rv$ranked_genes <- ranked_genes
        enrichment_rv$gene_sets <- list()
        
        incProgress(0.3, detail = "Running GSEA...")
        
        # Run GSEA for each selected database
        results_list <- list()
        
        # Determine score type based on the ranked genes
        score_type <- "std"  # default: standard (mixed positive/negative)
        if (all(ranked_genes > 0)) {
          score_type <- "pos"
          print("All scores positive - using scoreType = 'pos'")
        } else if (all(ranked_genes < 0)) {
          score_type <- "neg"
          print("All scores negative - using scoreType = 'neg'")
        }
        
        for (db in input$enrichment_databases) {
          incProgress(0.1, detail = paste("Analyzing", db, "..."))
          
          tryCatch({
            if (!isTRUE(tx_enr_key() %in% tx_curated_keys)) {
              gdf <- tx_run_gsea(db, ranked_genes, tx_enr_key(),
                                 input$enrichment_minGS, input$enrichment_maxGS)
              if (!is.null(gdf) && nrow(gdf) > 0) {
                results_list[[db]] <- gdf
                enrichment_rv$gene_sets[[db]] <- attr(gdf, "gene_sets")
              } else {
                print(paste("No GSEA results for", db, "(species/db unsupported or too few mapped genes)"))
              }
              next
            }
            gene_sets <- get_gene_sets(db, input$enrichment_organism)
            
            if (length(gene_sets) == 0) {
              print(paste("No gene sets available for", db, "- skipping"))
              next
            }
            
            # Store gene sets for this DB so Classic GSEA plot can look up members
            enrichment_rv$gene_sets[[db]] <- gene_sets
            
            print(paste("Running fgseaMultilevel for", db, "with", length(gene_sets), "pathways"))
            
            # Use fgseaMultilevel (recommended)
            gsea_result <- fgsea::fgseaMultilevel(
              pathways = gene_sets,
              stats = ranked_genes,
              minSize = input$enrichment_minGS,
              maxSize = input$enrichment_maxGS,
              scoreType = score_type,
              eps = 0,
              nPermSimple = 10000  # Increased for better p-value estimation
            )
            
            print(paste("fgseaMultilevel completed for", db))
            
            if (!is.null(gsea_result) && nrow(gsea_result) > 0) {
              # Convert to regular data.frame to avoid issues with list columns
              gsea_df <- as.data.frame(gsea_result)
              
              # Add Database column
              gsea_df$Database <- db
              
              # Add Description column (use pathway name)
              gsea_df$Description <- gsea_df$pathway
              
              # Ensure setSize exists
              if (!"setSize" %in% names(gsea_df) && "size" %in% names(gsea_df)) {
                gsea_df$setSize <- gsea_df$size
              }
              
              # Convert leadingEdge list to character string
              # This is critical - leadingEdge is a list column that causes issues
              if ("leadingEdge" %in% names(gsea_df)) {
                gsea_df$core_enrichment <- sapply(seq_len(nrow(gsea_df)), function(i) {
                  le <- gsea_df$leadingEdge[[i]]
                  if (is.null(le) || length(le) == 0) {
                    return("")
                  }
                  paste(le, collapse = "/")
                })
                # Remove the list column to avoid serialization issues
                gsea_df$leadingEdge <- NULL
              }
              
              # Add gene count column
              if (!"Count" %in% names(gsea_df)) {
                gsea_df$Count <- gsea_df$setSize
              }
              
              # Filter out rows with NA p-values
              gsea_df <- gsea_df[!is.na(gsea_df$pval), ]
              
              # Rename p-value columns for consistency
              if ("pval" %in% names(gsea_df) && !"pvalue" %in% names(gsea_df)) {
                gsea_df$pvalue <- gsea_df$pval
              }
              if ("padj" %in% names(gsea_df) && !"p.adjust" %in% names(gsea_df)) {
                gsea_df$p.adjust <- gsea_df$padj
              }
              
              results_list[[db]] <- gsea_df
              print(paste("GSEA completed for", db, ":", nrow(gsea_df), "pathways with valid p-values"))
            } else {
              print(paste("No results for", db))
            }
            
          }, error = function(e) {
            print(paste("Error in GSEA for", db, ":", e$message))
            print(traceback())
            showNotification(paste("Error analyzing", db, ":", e$message), type = "warning")
          })
        }
        
        if (length(results_list) == 0) {
          showNotification("No GSEA results obtained. Check if gene symbols match the database (e.g., use official gene symbols like TP53, BRCA1).", type = "error")
          return()
        }
        
        # Store results
        enrichment_rv$results <- results_list
        enrichment_rv$mode <- "gsea"
        
        # Show success notification
        total_pathways <- sum(sapply(results_list, nrow))
        showNotification(paste("GSEA completed!", total_pathways, "enriched pathways found"), type = "message")
        
      } else {
        # ========================================
        # ORA ANALYSIS
        # ========================================
        incProgress(0.1, detail = "Preparing gene list...")
        
        # Get gene list based on input type
        gene_list <- get_ora_gene_list()
        
        print(paste("ORA: Got", length(gene_list), "genes"))
        print(paste("ORA: First 5 genes:", paste(head(gene_list, 5), collapse = ", ")))
        
        if (is.null(gene_list) || length(gene_list) < 5) {
          showNotification("Need at least 5 genes for ORA", type = "error")
          return()
        }
        
        # For ORA with pasted genes, use simpler approach - no background restriction
        # This finds ALL pathways containing these genes
        background_genes <- NULL
        print("ORA: Using all genes in database as background (standard for gene list analysis)")
        
        incProgress(0.3, detail = "Running ORA...")
        
        results_list <- list()
        errors_list <- list()
        
        for (db in input$enrichment_databases) {
          incProgress(0.1, detail = paste("Analyzing", db, "..."))
          print(paste("ORA: Processing database:", db))
          
          if (!isTRUE(tx_enr_key() %in% tx_curated_keys) && db %in% c("REACTOME","WP","HALLMARK")) {
            errors_list[[db]] <- paste(db, "is available for human and common model organisms only")
            next
          }
          
          ora_result <- NULL
          
          tryCatch({
            if (grepl("^GO", db)) {
              # GO analysis - uses gene symbols
              ont <- sub("GO_", "", db)
              print(paste("ORA: Running GO", ont, "analysis"))
              
              ora_result <- tx_run_enrichGO(gene_list, tx_enr_key(), ont,
                input$enrichment_correction, input$enrichment_minGS, input$enrichment_maxGS)
              
            } else if (db == "KEGG") {
              # KEGG analysis - requires Entrez IDs
              ora_result <- tx_run_enrichKEGG(gene_list, tx_enr_key(),
                input$enrichment_correction, input$enrichment_minGS, input$enrichment_maxGS)
              if (is.null(ora_result)) {
                errors_list[[db]] <- "KEGG unavailable for this species or too few mapped genes"
                next
              }
              
            } else if (db == "REACTOME") {
              # Reactome analysis - requires Entrez IDs
              print("ORA: Running Reactome analysis")
              
              entrez_genes <- convert_to_entrez(gene_list, input$enrichment_organism)
              
              if (length(entrez_genes) < 5) {
                print("ORA: Not enough Entrez IDs for Reactome analysis")
                errors_list[[db]] <- "Could not convert enough genes to Entrez IDs"
                next
              }
              
              # Reactome organism mapping
              reactome_org <- switch(input$enrichment_organism,
                                     "hsapiens" = "human",
                                     "mmusculus" = "mouse",
                                     "rnorvegicus" = "rat",
                                     "drerio" = "zebrafish",
                                     "dmelanogaster" = "fly",
                                     "scerevisiae" = "yeast",
                                     "human")
              
              ora_result <- ReactomePA::enrichPathway(
                gene = entrez_genes,
                organism = reactome_org,
                pvalueCutoff = 1,
                qvalueCutoff = 1,
                pAdjustMethod = input$enrichment_correction,
                minGSSize = input$enrichment_minGS,
                maxGSSize = input$enrichment_maxGS
              )
              
            } else if (db == "WP") {
              # WikiPathways analysis
              print("ORA: Running WikiPathways analysis")
              
              entrez_genes <- convert_to_entrez(gene_list, input$enrichment_organism)
              
              if (length(entrez_genes) < 5) {
                errors_list[[db]] <- "Could not convert enough genes to Entrez IDs"
                next
              }
              
              # Map organism code to WikiPathways full name
              wp_organism <- switch(input$enrichment_organism,
                                    "hsapiens" = "Homo sapiens",
                                    "mmusculus" = "Mus musculus",
                                    "rnorvegicus" = "Rattus norvegicus",
                                    "drerio" = "Danio rerio",
                                    "dmelanogaster" = "Drosophila melanogaster",
                                    "scerevisiae" = "Saccharomyces cerevisiae",
                                    "Homo sapiens")  # default
              
              ora_result <- clusterProfiler::enrichWP(
                gene = entrez_genes,
                organism = wp_organism,
                pvalueCutoff = 1,
                qvalueCutoff = 1,
                pAdjustMethod = input$enrichment_correction,
                minGSSize = input$enrichment_minGS,
                maxGSSize = input$enrichment_maxGS
              )
            }
            
            # Check and store results - keep ALL results, not just significant
            if (!is.null(ora_result)) {
              result_df <- as.data.frame(ora_result)
              if (nrow(result_df) > 0) {
                # Calculate Fold Enrichment for ORA results
                if ("GeneRatio" %in% names(result_df) && "BgRatio" %in% names(result_df)) {
                  # Parse ratios (format: "15/200")
                  parse_ratio <- function(ratio_str) {
                    parts <- as.numeric(strsplit(as.character(ratio_str), "/")[[1]])
                    if (length(parts) == 2 && parts[2] != 0) parts[1] / parts[2] else NA
                  }
                  gene_ratios <- sapply(result_df$GeneRatio, parse_ratio)
                  bg_ratios <- sapply(result_df$BgRatio, parse_ratio)
                  result_df$FoldEnrichment <- round(gene_ratios / bg_ratios, 2)
                }
                result_df$database <- db
                results_list[[db]] <- result_df
                
                # Count significant vs total
                n_sig <- sum(result_df$p.adjust <= input$enrichment_pval, na.rm = TRUE)
                print(paste("ORA:", db, "- Found", nrow(result_df), "pathways,", n_sig, "significant (p.adj <=", input$enrichment_pval, ")"))
              } else {
                print(paste("ORA: No pathways found for", db))
              }
            }
            
          }, error = function(e) {
            error_msg <- paste("Error in ORA for", db, ":", e$message)
            print(error_msg)
            errors_list[[db]] <<- e$message
          })
        }
        
        # Store results
        enrichment_rv$results <- results_list
        enrichment_rv$mode <- "ora"
        
        # Show summary notification
        if (length(results_list) > 0) {
          total_pathways <- sum(sapply(results_list, nrow))
          total_sig <- sum(sapply(results_list, function(df) sum(df$p.adjust <= input$enrichment_pval, na.rm = TRUE)))
          showNotification(
            paste("Found", total_pathways, "pathways (", total_sig, "significant) across", length(results_list), "database(s)"),
            type = "message",
            duration = 5
          )
        } else {
          showNotification(
            "No pathway associations found. Try different databases or check gene symbols.",
            type = "warning",
            duration = 8
          )
        }
      }
      
      incProgress(1, detail = "Complete!")
    })
    
    showNotification("Enrichment analysis complete!", type = "message", duration = 3)
  })
  
  
  # ============================================================================
  # SUMMARY CARDS
  # ============================================================================
  
  output$enrichment_summary_cards <- renderUI({
    req(enrichment_rv$results)
    req(length(enrichment_rv$results) > 0)
    
    # Safely combine results
    all_results <- tryCatch({
      combined <- lapply(names(enrichment_rv$results), function(db_name) {
        df <- enrichment_rv$results[[db_name]]
        if (!is.data.frame(df)) df <- as.data.frame(df)
        if (nrow(df) == 0) return(NULL)
        df$database <- db_name
        return(df)
      })
      combined <- combined[!sapply(combined, is.null)]
      if (length(combined) == 0) return(NULL)
      dplyr::bind_rows(combined)
    }, error = function(e) {
      print(paste("Error combining results:", e$message))
      NULL
    })
    
    if (is.null(all_results) || nrow(all_results) == 0) {
      return(div(
        class = "alert alert-info",
        style = "text-align: center; padding: 40px; border-radius: 12px;",
        icon("search", style = "font-size: 40px; color: #667eea; margin-bottom: 15px;"),
        h4("Analysis Complete", style = "color: #2c3e50;"),
        p("No pathway associations found with current settings.", style = "color: #666;"),
        p(style = "font-size: 0.9rem; color: #888;", 
          "Try: Different databases, relaxed p-value threshold, or verify gene symbols")
      ))
    }
    
    # Calculate statistics
    total_pathways <- nrow(all_results)
    n_databases <- length(unique(all_results$database))
    
    # Get p-value column
    p_col <- if ("p.adjust" %in% names(all_results)) all_results$p.adjust 
    else if ("padj" %in% names(all_results)) all_results$padj 
    else rep(1, nrow(all_results))
    
    sig_pathways <- sum(p_col <= input$enrichment_pval, na.rm = TRUE)
    
    # Get top pathway
    top_idx <- which.min(p_col)
    top_pathway <- if ("Description" %in% names(all_results)) all_results$Description[top_idx]
    else if ("pathway" %in% names(all_results)) all_results$pathway[top_idx]
    else all_results$ID[top_idx]
    top_pval <- signif(min(p_col, na.rm = TRUE), 3)
    
    # Create premium summary cards
    div(
      class = "enrichment-summary-row",
      
      # Card 1: Total Pathways
      div(
        class = "enrichment-stat-card stat-card-primary",
        div(class = "stat-icon", icon("layer-group")),
        div(class = "stat-value", format(total_pathways, big.mark = ",")),
        div(class = "stat-label", "Total Pathways")
      ),
      
      # Card 2: Significant
      div(
        class = "enrichment-stat-card stat-card-success",
        div(class = "stat-icon", icon("check-double")),
        div(class = "stat-value", sig_pathways),
        div(class = "stat-label", paste0("Significant (p<", input$enrichment_pval, ")"))
      ),
      
      # Card 3: Databases
      div(
        class = "enrichment-stat-card stat-card-accent",
        div(class = "stat-icon", icon("database")),
        div(class = "stat-value", n_databases),
        div(class = "stat-label", "Databases")
      ),
      
      # Card 4: Top Finding
      div(
        class = "enrichment-stat-card stat-card-outline",
        div(class = "stat-icon", icon("trophy")),
        div(
          style = "margin-top: 5px;",
          div(style = "font-size: 12px; color: #667eea; font-weight: 600; margin-bottom: 5px;", "TOP PATHWAY"),
          div(
            style = "font-size: 14px; font-weight: 500; color: #2c3e50; line-height: 1.3; max-height: 40px; overflow: hidden;",
            title = top_pathway,
            substr(as.character(top_pathway), 1, 45),
            if (nchar(as.character(top_pathway)) > 45) "..." else ""
          ),
          div(
            style = "font-size: 12px; color: #28a745; margin-top: 8px; font-weight: 600;",
            paste("p =", top_pval)
          )
        )
      )
    )
  })
  
  output$enrichment_results_table <- DT::renderDataTable({
    req(enrichment_rv$results)
    req(length(enrichment_rv$results) > 0)
    
    # Combine all results
    all_results <- tryCatch({
      combined <- lapply(names(enrichment_rv$results), function(db_name) {
        df <- enrichment_rv$results[[db_name]]
        if (!is.data.frame(df)) df <- as.data.frame(df)
        if (nrow(df) == 0) return(NULL)
        if (!"database" %in% names(df)) df$database <- db_name
        return(df)
      })
      combined <- combined[!sapply(combined, is.null)]
      if (length(combined) == 0) return(NULL)
      dplyr::bind_rows(combined)
    }, error = function(e) {
      print(paste("Error combining results:", e$message))
      NULL
    })
    
    if (is.null(all_results) || nrow(all_results) == 0) {
      return(NULL)
    }
    
    # Convert Entrez IDs to Gene Symbols for KEGG and Reactome
    if ("geneID" %in% names(all_results)) {
      # Check if any genes look like Entrez IDs (numeric)
      sample_genes <- head(unlist(strsplit(as.character(all_results$geneID[1]), "/")), 3)
      needs_conversion <- all(grepl("^[0-9]+$", sample_genes))
      
      if (needs_conversion) {
        # Get organism database
        orgdb <- tryCatch({
          switch(input$enrichment_organism,
                 "hsapiens" = org.Hs.eg.db::org.Hs.eg.db,
                 "mmusculus" = org.Mm.eg.db::org.Mm.eg.db,
                 "rnorvegicus" = org.Rn.eg.db::org.Rn.eg.db,
                 "drerio" = org.Dr.eg.db::org.Dr.eg.db,
                 "dmelanogaster" = org.Dm.eg.db::org.Dm.eg.db,
                 "scerevisiae" = org.Sc.sgd.db::org.Sc.sgd.db,
                 org.Hs.eg.db::org.Hs.eg.db)
        }, error = function(e) NULL)
        
        if (!is.null(orgdb)) {
          # Batch convert all unique Entrez IDs
          all_entrez <- unique(unlist(strsplit(as.character(all_results$geneID), "/")))
          all_entrez <- all_entrez[!is.na(all_entrez) & all_entrez != ""]
          
          symbol_map <- tryCatch({
            AnnotationDbi::mapIds(orgdb, keys = all_entrez, column = "SYMBOL",
                                  keytype = "ENTREZID", multiVals = "first")
          }, error = function(e) setNames(all_entrez, all_entrez))
          
          # Apply mapping
          all_results$geneSymbols <- sapply(all_results$geneID, function(gene_str) {
            if (is.na(gene_str) || gene_str == "") return("")
            entrez_ids <- unlist(strsplit(as.character(gene_str), "/"))
            symbols <- symbol_map[entrez_ids]
            symbols <- symbols[!is.na(symbols)]
            paste(symbols, collapse = ", ")
          })
        } else {
          all_results$geneSymbols <- gsub("/", ", ", all_results$geneID)
        }
      } else {
        # Already symbols, just replace / with comma
        all_results$geneSymbols <- gsub("/", ", ", all_results$geneID)
      }
    }
    
    # Prepare display table for ORA
    if (enrichment_rv$mode == "ora") {
      display_df <- all_results %>%
        dplyr::transmute(
          Database = database,
          ID = ID,
          Description = Description,
          GeneRatio = if ("GeneRatio" %in% names(.)) GeneRatio else NA_character_,
          pvalue = signif(pvalue, 4),
          p.adjust = signif(p.adjust, 4),
          Count = if ("Count" %in% names(.)) as.integer(Count) else NA_integer_,
          Genes = if ("geneSymbols" %in% names(.)) geneSymbols else if ("geneID" %in% names(.)) gsub("/", ", ", geneID) else NA_character_,
          Significant = ifelse(p.adjust <= input$enrichment_pval, "Yes", "")
        ) %>%
        dplyr::arrange(p.adjust)
      
    } else {
      # GSEA - fgsea returns: pathway, pval, padj, ES, NES, size, leadingEdge
      # First, standardize column names before processing
      if ("pathway" %in% names(all_results) && !"Pathway_name" %in% names(all_results)) {
        all_results$Pathway_name <- all_results$pathway
      } else if ("Description" %in% names(all_results) && !"Pathway_name" %in% names(all_results)) {
        all_results$Pathway_name <- all_results$Description
      } else if ("ID" %in% names(all_results) && !"Pathway_name" %in% names(all_results)) {
        all_results$Pathway_name <- all_results$ID
      } else if (!"Pathway_name" %in% names(all_results)) {
        all_results$Pathway_name <- paste0("Pathway_", seq_len(nrow(all_results)))
      }
      
      # Standardize p-value columns
      if ("pval" %in% names(all_results) && !"pvalue" %in% names(all_results)) {
        all_results$pvalue <- all_results$pval
      }
      if ("padj" %in% names(all_results) && !"p.adjust" %in% names(all_results)) {
        all_results$p.adjust <- all_results$padj
      }
      
      display_df <- all_results %>%
        dplyr::transmute(
          Database = database,
          Pathway = Pathway_name,
          NES = round(NES, 3),
          pvalue = signif(pvalue, 4),
          p.adjust = signif(p.adjust, 4),
          Size = if ("size" %in% names(.)) size else NA_integer_,
          Direction = ifelse(NES > 0, "Up", "Down"),
          Significant = ifelse(p.adjust <= input$enrichment_pval, "Yes", "")
        ) %>%
        dplyr::arrange(p.adjust)
    }
    
    DT::datatable(
      display_df,
      extensions = c('Buttons', 'FixedHeader'),
      options = list(
        dom = 'Bfrtip',
        buttons = list(
          list(extend = 'copy', className = 'btn-sm'),
          list(extend = 'csv', className = 'btn-sm'),
          list(extend = 'excel', className = 'btn-sm')
        ),
        fixedHeader = TRUE,
        scrollX = TRUE,
        scrollY = "500px",
        pageLength = 50,
        order = list(list(which(names(display_df) == "p.adjust") - 1, 'asc')),
        columnDefs = list(
          list(className = 'dt-center', targets = c(0, which(names(display_df) == "Significant") - 1))
        ),
        initComplete = DT::JS(
          "function(settings, json) {",
          "  $(this.api().table().header()).css({'background': 'linear-gradient(180deg, #f8f9fa, #e9ecef)', 'font-weight': '600'});",
          "}"
        )
      ),
      rownames = FALSE,
      filter = 'top',
      class = 'cell-border stripe hover compact',
      style = 'bootstrap4'
    ) %>%
      DT::formatStyle(
        'Significant',
        backgroundColor = DT::styleEqual(c("Yes", ""), c('#d4edda', 'transparent')),
        fontWeight = DT::styleEqual(c("Yes", ""), c('bold', 'normal')),
        color = DT::styleEqual(c("Yes", ""), c('#155724', '#999'))
      ) %>%
      DT::formatStyle(
        'p.adjust',
        backgroundColor = DT::styleInterval(
          c(0.001, 0.01, 0.05),
          c('#a5d6a7', '#c8e6c9', '#dcedc8', 'transparent')
        )
      )
  })
  
  
