  output$enrichment_by_database_tabs <- renderUI({
    req(enrichment_rv$results)
    req(length(enrichment_rv$results) > 0)
    
    # Create a tab for each database
    tabs <- lapply(names(enrichment_rv$results), function(db_name) {
