          ),
          div(
            class = "db-stat-item",
            div(class = paste0("db-stat-value ", ifelse(n_sig > 0, "success", "")), 
                style = if(n_sig == 0) "color: #999;" else "",
                n_sig),
            div(class = "db-stat-label", paste0("Significant (p<", input$enrichment_pval, ")"))
          ),
          div(
            class = "db-stat-item",
            div(class = "db-stat-value info", 
                if(!is.na(best_pval)) format(best_pval, scientific = TRUE, digits = 2) else "N/A"),
            div(class = "db-stat-label", "Best P-value")
          )
