        # Table for this database
        DT::dataTableOutput(paste0("enrichment_table_", db_name))
      )
    })
    
    do.call(tabsetPanel, c(tabs, list(id = "enrichment_db_tabs", type = "tabs")))
  })
  
  # Dynamic table renderers for each database
  observe({
    req(enrichment_rv$results)
    
    lapply(names(enrichment_rv$results), function(db_name) {
      output[[paste0("enrichment_table_", db_name)]] <- DT::renderDataTable({
        df <- enrichment_rv$results[[db_name]]
        if (!is.data.frame(df)) df <- as.data.frame(df)
        if (nrow(df) == 0) return(NULL)
        
        # Convert Entrez IDs to gene symbols for KEGG and Reactome
        if (db_name %in% c("KEGG", "REACTOME") && "geneID" %in% names(df)) {
          # Show notification during conversion
          notification_id <- showNotification(
            div(
              style = "display: flex; align-items: center; gap: 12px;",
              tags$div(
                class = "spinner-border spinner-border-sm text-primary",
                role = "status",
                style = "width: 20px; height: 20px;"
              ),
              tags$span(
                paste0("Converting Entrez IDs to gene symbols for ", db_name, "..."),
                style = "font-weight: 500;"
              )
            ),
            duration = NULL,
            closeButton = FALSE,
            type = "message"
          )
          
          # Get organism database
          orgdb <- tryCatch({
            switch(input$enrichment_organism,
                   "hsapiens" = org.Hs.eg.db::org.Hs.eg.db,
                   "mmusculus" = org.Mm.eg.db::org.Mm.eg.db,
                   "rnorvegicus" = org.Rn.eg.db::org.Rn.eg.db,
                   "drerio" = org.Dr.eg.db::org.Dr.eg.db,
                   "dmelanogaster" = org.Dm.eg.db::org.Dm.eg.db,
                   "scerevisiae" = org.Sc.sgd.db::org.Sc.sgd.db,
                   org.Hs.eg.db::org.Hs.eg.db)
          }, error = function(e) NULL)
          
          if (!is.null(orgdb)) {
            # Batch convert all unique Entrez IDs at once (more efficient)
            all_entrez <- unique(unlist(strsplit(as.character(df$geneID), "/")))
            all_entrez <- all_entrez[!is.na(all_entrez) & all_entrez != ""]
            
            # Single batch conversion
            symbol_map <- tryCatch({
              mapped <- AnnotationDbi::mapIds(
                orgdb,
                keys = all_entrez,
                column = "SYMBOL",
                keytype = "ENTREZID",
                multiVals = "first"
              )
              mapped
            }, error = function(e) {
              setNames(all_entrez, all_entrez)  # Fallback: use IDs as-is
            })
            
            # Apply mapping to each row
            df$Genes <- sapply(df$geneID, function(gene_str) {
              if (is.na(gene_str) || gene_str == "") return("")
              entrez_ids <- unlist(strsplit(as.character(gene_str), "/"))
              symbols <- symbol_map[entrez_ids]
              symbols <- symbols[!is.na(symbols)]
              paste(symbols, collapse = ", ")
            })
          } else {
            df$Genes <- gsub("/", ", ", df$geneID)
          }
          
          # Remove notification after conversion is complete
          removeNotification(notification_id)
          
        } else if ("geneID" %in% names(df)) {
          # For GO, genes are already symbols, just replace / with comma
          df$Genes <- gsub("/", ", ", df$geneID)
        }
        
        # Prepare display columns
        if (enrichment_rv$mode == "ora") {
          display_df <- df %>%
            dplyr::transmute(
              ID = ID,
              Description = Description,
              `Gene Ratio` = if ("GeneRatio" %in% names(.)) GeneRatio else NA_character_,
              `P-value` = signif(pvalue, 3),
              `Adj. P-value` = signif(p.adjust, 3),
              Count = if ("Count" %in% names(.)) as.integer(Count) else NA_integer_,
              Genes = if ("Genes" %in% names(.)) Genes else if ("geneID" %in% names(.)) gsub("/", ", ", geneID) else NA_character_
            ) %>%
            dplyr::arrange(`Adj. P-value`)
        } else {
          # --- GSEA results (Corrected Logic) ---
          
          # 1. Standardize Pathway Name
          # We check which column exists and create a new standard 'Pathway_name' column
          if ("pathway" %in% names(df)) {
            df$Pathway_name <- df$pathway
          } else if ("Description" %in% names(df)) {
            df$Pathway_name <- df$Description
          } else if ("ID" %in% names(df)) {
            df$Pathway_name <- df$ID
          } else {
            df$Pathway_name <- paste0("Pathway_", seq_len(nrow(df)))
          }
          
          # 2. Standardize P-value
          if ("pval" %in% names(df)) {
            df$pval_safe <- df$pval
          } else if ("pvalue" %in% names(df)) {
            df$pval_safe <- df$pvalue
          } else {
            df$pval_safe <- NA_real_
          }
          
          # 3. Standardize Adj P-value
          if ("padj" %in% names(df)) {
            df$padj_safe <- df$padj
          } else if ("p.adjust" %in% names(df)) {
            df$padj_safe <- df$p.adjust
          } else {
            df$padj_safe <- NA_real_
          }
          
          # 4. Create Display DataFrame
          display_df <- df %>%
            dplyr::transmute(
              Pathway = Pathway_name,
              NES = round(NES, 3),
              `P-value` = signif(pval_safe, 3),
              `Adj. P-value` = signif(padj_safe, 3),
              # Use base R logic for Size to be safe
              Size = if ("size" %in% names(.)) size else NA_integer_,
              Direction = ifelse(NES > 0, "↑ Up", "↓ Down")
            ) %>%
            dplyr::arrange(`Adj. P-value`)
        }
        
        DT::datatable(
          display_df,
          extensions = 'Buttons',
          options = list(
            dom = 'Bfrtip',
            buttons = c('copy', 'csv', 'excel'),
            scrollX = TRUE,
            scrollY = "400px",
            pageLength = 25,
            columnDefs = list(
              list(
                targets = which(names(display_df) == "Genes") - 1,
                render = DT::JS(
                  "function(data, type, row, meta) {",
                  "  if(type === 'display' && data && data.length > 60) {",
                  "    return '<span title=\"' + data + '\">' + data.substr(0, 60) + '...</span>';",
                  "  }",
                  "  return data;",
                  "}"
                )
              )
            )
          ),
          rownames = FALSE,
          filter = 'top',
          class = 'cell-border stripe hover compact'
        ) %>%
          DT::formatStyle(
            'Adj. P-value',
            backgroundColor = DT::styleInterval(
              c(0.001, 0.01, 0.05),
              c('#a5d6a7', '#c8e6c9', '#dcedc8', 'transparent')
            )
          )
      })
    })
  })
  
  # Helper: lollipop-style enrichment plot (ORA + GSEA). Used by both the
  # on-screen renderer and the download handler so they render identically.
  build_enrichment_lollipop <- function(plot_df, mode = c("ora", "gsea"),
                                        top_n = NULL, base_size = 14) {
    mode <- match.arg(mode)

    stem_color  <- "grey70"
    edge_color  <- "black"
    bwr_palette <- c("#1f4e9b", "#ffffff", "#c1272d")
    title_text  <- if (!is.null(top_n)) {
      paste("Top", top_n, "Enriched Pathways",
            if (mode == "gsea") "(GSEA)" else "")
    } else {
      "Enriched Pathways"
    }

    base_theme <- ggplot2::theme_minimal(base_size = base_size) +
      ggplot2::theme(
        plot.background  = ggplot2::element_rect(fill = "white", color = NA),
        panel.background = ggplot2::element_rect(fill = "white", color = NA),
        panel.grid.major.y = ggplot2::element_blank(),
        panel.grid.minor   = ggplot2::element_blank(),
        panel.grid.major.x = ggplot2::element_line(color = "grey90"),
        axis.text.y  = ggplot2::element_text(size = base_size - 2, lineheight = 0.9),
        axis.text.x  = ggplot2::element_text(size = base_size - 3),
        plot.title   = ggplot2::element_text(face = "bold", hjust = 0.5,
                                             size = base_size + 2),
        plot.margin  = ggplot2::margin(14, 14, 14, 14),
        legend.position = "right",
        legend.title    = ggplot2::element_text(size = base_size - 3),
        legend.text     = ggplot2::element_text(size = base_size - 4)
      )

    if (mode == "ora") {
      ggplot2::ggplot(plot_df,
                      ggplot2::aes(x = PercentDysregulated, y = Description_wrapped)) +
        ggplot2::geom_segment(
          ggplot2::aes(x = 0, xend = PercentDysregulated,
                       y = Description_wrapped, yend = Description_wrapped),
          color = stem_color, linewidth = 1.2, alpha = 0.85
        ) +
        ggplot2::geom_point(
          ggplot2::aes(size = Count, fill = neg_log_p),
          shape = 21, color = edge_color, stroke = 0.6
        ) +
        ggplot2::scale_fill_gradientn(
          colors = bwr_palette, name = "-log10(p.adj)"
        ) +
        ggplot2::scale_size_continuous(
          name = "Number of genes",
          range = c(4, 14),
          breaks = c(5, 10, 20, 30, 40, 50)
        ) +
        ggplot2::scale_x_continuous(
          expand = ggplot2::expansion(mult = c(0.01, 0.05)),
          limits = c(0, NA)
        ) +
        ggplot2::labs(x = "Percent Dysregulated", y = NULL, title = title_text) +
        base_theme
    } else {
      # GSEA branch: x = NES (can be negative); stems diverge from zero.
      ggplot2::ggplot(plot_df,
                      ggplot2::aes(x = NES, y = Description_wrapped)) +
        ggplot2::geom_vline(xintercept = 0, linetype = "dashed",
                            color = "gray50") +
        ggplot2::geom_segment(
          ggplot2::aes(x = 0, xend = NES,
                       y = Description_wrapped, yend = Description_wrapped),
          color = stem_color, linewidth = 1.2, alpha = 0.85
        ) +
        ggplot2::geom_point(
          ggplot2::aes(size = neg_log_p, fill = NES),
          shape = 21, color = edge_color, stroke = 0.6
        ) +
        ggplot2::scale_fill_gradient2(
          low = bwr_palette[1], mid = bwr_palette[2], high = bwr_palette[3],
          midpoint = 0, name = "NES"
        ) +
        ggplot2::scale_size_continuous(
          name = "-log10(p.adj)",
          range = c(4, 14)
        ) +
        ggplot2::labs(x = "Normalized Enrichment Score",
                      y = NULL, title = title_text) +
        base_theme
    }
  }

  output$enrichment_visualization <- renderPlot({
    req(enrichment_rv$results)
    req(length(enrichment_rv$results) > 0)
    req(input$enrichment_viz_type)
    
    # Get selected database or all
    if (input$enrichment_viz_database == "All") {
      # Combine all results
      all_df <- tryCatch({
        dplyr::bind_rows(enrichment_rv$results)
      }, error = function(e) {
        enrichment_rv$results[[1]]
      })
    } else {
      all_df <- enrichment_rv$results[[input$enrichment_viz_database]]
    }
    
    if (is.null(all_df) || nrow(all_df) == 0) {
      plot.new()
      text(0.5, 0.5, "No data available for visualization", cex = 1.5)
      return()
    }
    
    # Prepare data for plotting
    if (enrichment_rv$mode == "ora") {
      # For ORA, create a simple bar/dot plot
      # Helper function to wrap long text
      wrap_text <- function(text, width = 50) {
        sapply(text, function(t) {
          if (nchar(t) > width) {
            paste(strwrap(t, width = width), collapse = "\n")
          } else {
            t
          }
        })
      }
      
      # Safely parse "k/N" style ratio columns; returns 0 when missing/malformed
      parse_ratio <- function(x) {
        sapply(x, function(v) {
          parts <- strsplit(as.character(v), "/")[[1]]
          if (length(parts) == 2 && !any(is.na(suppressWarnings(as.numeric(parts))))) {
            as.numeric(parts[1]) / as.numeric(parts[2])
          } else 0
        })
      }
      # Extract denominator K from BgRatio "K/N"; returns NA when missing
      parse_bg_K <- function(x) {
        suppressWarnings(as.numeric(sub("/.*", "", as.character(x))))
      }

      has_bg <- "BgRatio" %in% names(all_df)
      plot_df <- all_df %>%
        dplyr::arrange(p.adjust) %>%
        head(input$enrichment_viz_top) %>%
        dplyr::mutate(
          Description_wrapped = wrap_text(Description, 50),
          Description_wrapped = factor(Description_wrapped, levels = rev(Description_wrapped)),
          neg_log_p = -log10(p.adjust),
          Count = as.numeric(Count),
          GeneRatio_num = parse_ratio(GeneRatio)
        )
      plot_df$BgRatio_K <- if (has_bg) parse_bg_K(plot_df$BgRatio) else NA_real_
      plot_df$PercentDysregulated <- ifelse(
        !is.na(plot_df$BgRatio_K) & plot_df$BgRatio_K > 0,
        plot_df$Count / plot_df$BgRatio_K * 100,
        plot_df$GeneRatio_num * 100
      )

      if (input$enrichment_viz_type == "lollipop") {
        build_enrichment_lollipop(plot_df, mode = "ora",
                                  top_n = input$enrichment_viz_top)

      } else if (input$enrichment_viz_type == "barplot") {
        # Bar plot - use Gene Count for fill (not p.adjust which is on x-axis)
        ggplot(plot_df, aes(x = neg_log_p, y = Description_wrapped, fill = Count)) +
          geom_col() +
          scale_fill_viridis_c(name = "Gene Count", option = "plasma") +
          labs(
            x = "-log10(Adjusted P-value)",
            y = "",
            title = paste("Top", input$enrichment_viz_top, "Enriched Pathways")
          ) +
          theme_minimal(base_size = 14) +
          theme(
            plot.background = element_rect(fill = "white", color = NA),
            panel.background = element_rect(fill = "white", color = NA),
            axis.text.y = element_text(size = 11),
            plot.title = element_text(face = "bold", hjust = 0.5)
          )

      } else if (input$enrichment_viz_type %in% c("dotplot", "gsea_classic")) {
        # GSEA-only visualizations chosen while in ORA mode
        plot.new()
        text(0.5, 0.5, "This visualization requires GSEA mode.\nRe-run analysis in GSEA mode to use it.", cex = 1.3)
      } else {
        # Default simple plot
        plot.new()
        text(0.5, 0.5, paste("Visualization type", input$enrichment_viz_type,
                             "not recognized.\nUse Lollipop Plot or Bar Plot for ORA results."), cex = 1.2)
      }
      
    } else {
      # GSEA visualizations
      # Helper function to wrap long text
      wrap_text <- function(text, width = 50) {
        sapply(text, function(t) {
          if (nchar(t) > width) {
            paste(strwrap(t, width = width), collapse = "\n")
          } else {
            t
          }
        })
      }
      
      plot_df <- all_df %>%
        dplyr::mutate(
          Description = dplyr::coalesce(pathway, Description),
          p.adjust = dplyr::coalesce(padj, p.adjust)
        ) %>%
        dplyr::arrange(p.adjust) %>%
        head(input$enrichment_viz_top) %>%
        dplyr::mutate(
          Description_wrapped = wrap_text(Description, 50),
          Description_wrapped = factor(Description_wrapped, levels = rev(Description_wrapped)),
          neg_log_p = -log10(p.adjust)
        )
      
      if (input$enrichment_viz_type == "lollipop") {
        build_enrichment_lollipop(plot_df, mode = "gsea",
                                  top_n = input$enrichment_viz_top)

      } else if (input$enrichment_viz_type == "barplot") {
        ggplot(plot_df, aes(x = NES, y = Description_wrapped, fill = NES)) +
          geom_col() +
          scale_fill_gradient2(low = "blue", mid = "white", high = "red", midpoint = 0, name = "NES") +
          geom_vline(xintercept = 0, linetype = "dashed", color = "gray50") +
          labs(
            x = "Normalized Enrichment Score (NES)",
            y = "",
            title = paste("Top", input$enrichment_viz_top, "Enriched Pathways (GSEA)")
          ) +
          theme_minimal(base_size = 14) +
          theme(
            plot.background = element_rect(fill = "white", color = NA),
            panel.background = element_rect(fill = "white", color = NA),
            axis.text.y = element_text(size = 11),
            plot.title = element_text(face = "bold", hjust = 0.5)
          )
      } else if (input$enrichment_viz_type == "dotplot") {
        # Need Count column for size. If not present (some DBs), use setSize.
        if (!"Count" %in% names(plot_df)) {
          plot_df$Count <- if ("setSize" %in% names(plot_df)) plot_df$setSize else 10
        }
        ggplot(plot_df, aes(x = NES, y = Description_wrapped, size = Count, color = neg_log_p)) +
          geom_point(alpha = 0.85) +
          scale_color_viridis_c(name = "-log10(adj. p)", option = "plasma") +
          scale_size_continuous(name = "Gene Count", range = c(4, 14)) +
          geom_vline(xintercept = 0, linetype = "dashed", color = "gray60") +
          labs(x = "Normalized Enrichment Score (NES)", y = NULL,
               title = paste("Top", input$enrichment_viz_top, "Enriched Pathways (GSEA)")) +
          theme_minimal(base_size = 14) +
          theme(
            plot.background = element_rect(fill = "white", color = NA),
            panel.background = element_rect(fill = "white", color = NA),
            axis.text.y = element_text(size = 11),
            plot.title = element_text(face = "bold", hjust = 0.5),
            legend.position = "right"
          )
      } else if (input$enrichment_viz_type == "gsea_classic") {
        # Classic 3-panel GSEA running enrichment-score plot for one pathway
        if (is.null(enrichment_rv$ranked_genes) || is.null(enrichment_rv$gene_sets)) {
          plot.new()
          text(0.5, 0.5, "Gene set data not available; re-run GSEA to use this visualization.", cex = 1.2)
          return()
        }
        req(input$enrichment_classic_pathway)
        selected_pathway <- input$enrichment_classic_pathway
        
        # Find which database holds this pathway
        pathway_db <- NULL
        for (db_name in names(enrichment_rv$results)) {
          res_df <- enrichment_rv$results[[db_name]]
          if (!is.null(res_df) && "pathway" %in% names(res_df) &&
              selected_pathway %in% res_df$pathway) {
            pathway_db <- db_name
            break
          }
        }
        if (is.null(pathway_db)) {
          plot.new()
          text(0.5, 0.5, "Selected pathway not found in results", cex = 1.2)
          return()
        }
        
        gene_sets_db <- enrichment_rv$gene_sets[[pathway_db]]
        if (is.null(gene_sets_db) || !(selected_pathway %in% names(gene_sets_db))) {
          plot.new()
          text(0.5, 0.5, "Gene set members not available for this pathway", cex = 1.2)
          return()
        }
        pathway_members <- gene_sets_db[[selected_pathway]]
        
        ranked_gene_names <- names(enrichment_rv$ranked_genes)
        pathway_positions <- which(ranked_gene_names %in% pathway_members)
        
        if (length(pathway_positions) < 3) {
          plot.new()
          text(0.5, 0.5, "Too few pathway members found in ranked list", cex = 1.2)
          return()
        }
        
        pathway_row <- enrichment_rv$results[[pathway_db]][
          enrichment_rv$results[[pathway_db]]$pathway == selected_pathway, ]
        nes_val <- if ("NES" %in% names(pathway_row)) pathway_row$NES[1] else NA
        pval_val <- if ("padj" %in% names(pathway_row)) pathway_row$padj[1] else NA
        if (is.null(nes_val) || is.na(nes_val)) nes_val <- pathway_row$ES[1]
        
        createInteractiveGSEAPlot(
          ranked_genes = enrichment_rv$ranked_genes,
          pathway_positions = pathway_positions,
          pathway_name = selected_pathway,
          nes = nes_val,
          pvalue = pval_val
        )
      } else {
        plot.new()
        text(0.5, 0.5, "Select Lollipop Plot or Bar Plot for visualization", cex = 1.2)
      }
    }
  }, height = 600)
  
  # Populate Classic GSEA pathway selector whenever GSEA results change
  observe({
    req(enrichment_rv$results)
    req(identical(enrichment_rv$mode, "gsea"))
    
    # Combine pathways from all dbs, sort by padj ascending, take top N
    combined <- tryCatch({
      do.call(rbind, lapply(enrichment_rv$results, function(df) {
        if (is.null(df) || nrow(df) == 0) return(NULL)
        if (!all(c("pathway", "padj") %in% names(df))) return(NULL)
        df[, c("pathway", "padj"), drop = FALSE]
      }))
    }, error = function(e) NULL)
    
    if (is.null(combined) || nrow(combined) == 0) return()
    combined <- combined[order(combined$padj), , drop = FALSE]
    top_n <- if (!is.null(input$enrichment_viz_top)) input$enrichment_viz_top else 20
    combined <- head(combined, max(50, top_n))
    
    pathway_choices <- unique(combined$pathway)
    top_pathway <- pathway_choices[1]
    updateSelectizeInput(session, "enrichment_classic_pathway",
                         choices = pathway_choices,
                         selected = top_pathway,
                         server = TRUE)
  })
  
  output$download_enrichment_all <- downloadHandler(
    filename = function() {
      paste0("enrichment_results_", enrichment_rv$mode, "_", Sys.Date(), ".xlsx")
    },
    content = function(file) {
      req(enrichment_rv$results)
      
      # Get organism database for gene symbol conversion
      orgdb <- tryCatch(get_orgdb(input$enrichment_organism), error = function(e) NULL)
      
      # Create workbook
      wb <- openxlsx::createWorkbook()
      
      # Add summary sheet
      openxlsx::addWorksheet(wb, "Summary")
      summary_df <- data.frame(
        Parameter = c("Analysis Mode", "Databases", "P-value Threshold", "Organism", "Date"),
        Value = c(
          toupper(enrichment_rv$mode),
          paste(names(enrichment_rv$results), collapse = ", "),
          input$enrichment_pval,
          input$enrichment_organism,
          as.character(Sys.Date())
        )
      )
      openxlsx::writeData(wb, "Summary", summary_df)
      
      # Add sheet for each database
      for (db_name in names(enrichment_rv$results)) {
        df <- enrichment_rv$results[[db_name]]
        if (is.data.frame(df) && nrow(df) > 0) {
          
          # Convert Entrez IDs to Gene Symbols for KEGG and Reactome
          if (db_name %in% c("KEGG", "REACTOME") && "geneID" %in% names(df) && !is.null(orgdb)) {
            # Batch convert all unique Entrez IDs
            all_entrez <- unique(unlist(strsplit(as.character(df$geneID), "/")))
            all_entrez <- all_entrez[!is.na(all_entrez) & all_entrez != ""]
            
            symbol_map <- tryCatch({
              AnnotationDbi::mapIds(orgdb, keys = all_entrez, column = "SYMBOL",
                                    keytype = "ENTREZID", multiVals = "first")
            }, error = function(e) setNames(all_entrez, all_entrez))
            
            # Add Gene Symbols column
            df$GeneSymbols <- sapply(df$geneID, function(gene_str) {
              if (is.na(gene_str) || gene_str == "") return("")
              entrez_ids <- unlist(strsplit(as.character(gene_str), "/"))
              symbols <- symbol_map[entrez_ids]
              symbols <- symbols[!is.na(symbols)]
              paste(symbols, collapse = ", ")
            })
            
            # Rename geneID to EntrezIDs for clarity and reorder columns
            names(df)[names(df) == "geneID"] <- "EntrezIDs"
            # Move GeneSymbols before EntrezIDs
            col_order <- names(df)
            entrez_idx <- which(col_order == "EntrezIDs")
            symbol_idx <- which(col_order == "GeneSymbols")
            if (length(entrez_idx) > 0 && length(symbol_idx) > 0) {
              col_order <- col_order[-symbol_idx]
              col_order <- append(col_order, "GeneSymbols", after = entrez_idx - 1)
              df <- df[, col_order]
            }
          } else if ("geneID" %in% names(df)) {
            # For GO and others, genes are already symbols
            df$GeneSymbols <- gsub("/", ", ", df$geneID)
          }
          
          sheet_name <- substr(db_name, 1, 31)  # Excel sheet name limit
          openxlsx::addWorksheet(wb, sheet_name)
          openxlsx::writeData(wb, sheet_name, df)
        }
      }
      
      openxlsx::saveWorkbook(wb, file, overwrite = TRUE)
    }
  )
  
  output$download_enrichment_plot <- downloadHandler(
    filename = function() {
      ext <- input$enrichment_download_format %||% "png"
      paste0("enrichment_", input$enrichment_viz_type, "_", Sys.Date(), ".", ext)
    },
    content = function(file) {
      req(enrichment_rv$results)
      req(length(enrichment_rv$results) > 0)

      fmt <- input$enrichment_download_format %||% "png"

      # Get selected database or all
      if (input$enrichment_viz_database == "All") {
        all_df <- tryCatch({
          dplyr::bind_rows(enrichment_rv$results)
        }, error = function(e) {
          enrichment_rv$results[[1]]
        })
      } else {
        all_df <- enrichment_rv$results[[input$enrichment_viz_database]]
      }

      if (is.null(all_df) || nrow(all_df) == 0) return(NULL)

      wrap_text <- function(text, width = 50) {
        sapply(text, function(t) {
          if (nchar(t) > width) {
            paste(strwrap(t, width = width), collapse = "\n")
          } else {
            t
          }
        })
      }
      parse_ratio <- function(x) {
        sapply(x, function(v) {
          parts <- strsplit(as.character(v), "/")[[1]]
          if (length(parts) == 2 && !any(is.na(suppressWarnings(as.numeric(parts))))) {
            as.numeric(parts[1]) / as.numeric(parts[2])
          } else 0
        })
      }
      parse_bg_K <- function(x) {
        suppressWarnings(as.numeric(sub("/.*", "", as.character(x))))
      }

      # Build plot_df identically to the on-screen renderer so downloads match
      if (enrichment_rv$mode == "ora") {
        has_bg <- "BgRatio" %in% names(all_df)
        plot_df <- all_df %>%
          dplyr::arrange(p.adjust) %>%
          head(input$enrichment_viz_top) %>%
          dplyr::mutate(
            Description_wrapped = wrap_text(Description, 45),
            Description_wrapped = factor(Description_wrapped, levels = rev(Description_wrapped)),
            neg_log_p = -log10(p.adjust),
            Count = as.numeric(Count),
            GeneRatio_num = parse_ratio(GeneRatio)
          )
        plot_df$BgRatio_K <- if (has_bg) parse_bg_K(plot_df$BgRatio) else NA_real_
        plot_df$PercentDysregulated <- ifelse(
          !is.na(plot_df$BgRatio_K) & plot_df$BgRatio_K > 0,
          plot_df$Count / plot_df$BgRatio_K * 100,
          plot_df$GeneRatio_num * 100
        )

        if (input$enrichment_viz_type == "lollipop") {
          p <- build_enrichment_lollipop(plot_df, mode = "ora",
                                         top_n = input$enrichment_viz_top,
                                         base_size = 16)
        } else if (input$enrichment_viz_type %in% c("dotplot", "gsea_classic")) {
          # GSEA-only viz selected while in ORA mode: emit a small notice image.
          p <- ggplot() +
            annotate("text", x = 0.5, y = 0.5,
                     label = "This visualization requires GSEA mode.",
                     size = 6) +
            theme_void() +
            theme(plot.background = element_rect(fill = "white", color = NA))
        } else {
          p <- ggplot(plot_df, aes(x = neg_log_p, y = Description_wrapped, fill = Count)) +
            geom_col() +
            scale_fill_viridis_c(name = "Gene Count", option = "plasma") +
            labs(x = "-log10(Adjusted P-value)", y = "",
                 title = paste("Top", input$enrichment_viz_top, "Enriched Pathways")) +
            theme_minimal(base_size = 14) +
            theme(
              plot.background = element_rect(fill = "white", color = NA),
              panel.background = element_rect(fill = "white", color = NA),
              axis.text.y = element_text(size = 11, lineheight = 0.9),
              plot.title = element_text(face = "bold", hjust = 0.5, size = 16),
              plot.margin = margin(14, 14, 14, 14)
            )
        }
      } else {
        plot_df <- all_df %>%
          dplyr::mutate(
            Description = dplyr::coalesce(pathway, Description),
            p.adjust    = dplyr::coalesce(padj, p.adjust)
          ) %>%
          dplyr::arrange(p.adjust) %>%
          head(input$enrichment_viz_top) %>%
          dplyr::mutate(
            Description_wrapped = wrap_text(Description, 45),
            Description_wrapped = factor(Description_wrapped, levels = rev(Description_wrapped)),
            neg_log_p = -log10(p.adjust)
          )

        if (input$enrichment_viz_type == "lollipop") {
          p <- build_enrichment_lollipop(plot_df, mode = "gsea",
                                         top_n = input$enrichment_viz_top,
                                         base_size = 16)
        } else if (input$enrichment_viz_type == "dotplot") {
          if (!"Count" %in% names(plot_df)) {
            plot_df$Count <- if ("setSize" %in% names(plot_df)) plot_df$setSize else 10
          }
          p <- ggplot(plot_df, aes(x = NES, y = Description_wrapped, size = Count, color = neg_log_p)) +
            geom_point(alpha = 0.85) +
            scale_color_viridis_c(name = "-log10(adj. p)", option = "plasma") +
            scale_size_continuous(name = "Gene Count", range = c(4, 14)) +
            geom_vline(xintercept = 0, linetype = "dashed", color = "gray60") +
            labs(x = "Normalized Enrichment Score (NES)", y = NULL,
                 title = paste("Top", input$enrichment_viz_top, "Enriched Pathways (GSEA)")) +
            theme_minimal(base_size = 14) +
            theme(
              plot.background = element_rect(fill = "white", color = NA),
              panel.background = element_rect(fill = "white", color = NA),
              axis.text.y = element_text(size = 11, lineheight = 0.9),
              plot.title = element_text(face = "bold", hjust = 0.5, size = 16),
              plot.margin = margin(14, 14, 14, 14)
            )
        } else if (input$enrichment_viz_type == "gsea_classic") {
          # Build the classic 3-panel plot for the currently selected pathway
          if (is.null(enrichment_rv$ranked_genes) || is.null(enrichment_rv$gene_sets) ||
              is.null(input$enrichment_classic_pathway)) {
            return(NULL)
          }
          selected_pathway <- input$enrichment_classic_pathway
          pathway_db <- NULL
          for (db_name in names(enrichment_rv$results)) {
            res_df <- enrichment_rv$results[[db_name]]
            if (!is.null(res_df) && "pathway" %in% names(res_df) &&
                selected_pathway %in% res_df$pathway) {
              pathway_db <- db_name
              break
            }
          }
          if (is.null(pathway_db)) return(NULL)
          gene_sets_db <- enrichment_rv$gene_sets[[pathway_db]]
          if (is.null(gene_sets_db) || !(selected_pathway %in% names(gene_sets_db))) return(NULL)
          pathway_members <- gene_sets_db[[selected_pathway]]
          ranked_gene_names <- names(enrichment_rv$ranked_genes)
          pathway_positions <- which(ranked_gene_names %in% pathway_members)
          if (length(pathway_positions) < 3) return(NULL)
          pathway_row <- enrichment_rv$results[[pathway_db]][
            enrichment_rv$results[[pathway_db]]$pathway == selected_pathway, ]
          nes_val <- if ("NES" %in% names(pathway_row)) pathway_row$NES[1] else NA
          pval_val <- if ("padj" %in% names(pathway_row)) pathway_row$padj[1] else NA
          if (is.null(nes_val) || is.na(nes_val)) nes_val <- pathway_row$ES[1]
          p <- createInteractiveGSEAPlot(
            ranked_genes = enrichment_rv$ranked_genes,
            pathway_positions = pathway_positions,
            pathway_name = selected_pathway,
            nes = nes_val,
            pvalue = pval_val
          )
        } else {
          p <- ggplot(plot_df, aes(x = NES, y = Description_wrapped, fill = NES)) +
            geom_col() +
            scale_fill_gradient2(low = "#1f4e9b", mid = "white", high = "#c1272d",
                                 midpoint = 0, name = "NES") +
            geom_vline(xintercept = 0, linetype = "dashed", color = "gray50") +
            labs(x = "Normalized Enrichment Score", y = "",
                 title = paste("Top", input$enrichment_viz_top, "Enriched Pathways (GSEA)")) +
            theme_minimal(base_size = 14) +
            theme(
              plot.background = element_rect(fill = "white", color = NA),
              panel.background = element_rect(fill = "white", color = NA),
              axis.text.y = element_text(size = 11, lineheight = 0.9),
              plot.title = element_text(face = "bold", hjust = 0.5, size = 16),
              plot.margin = margin(14, 14, 14, 14)
            )
        }
      }

      # Publication-quality dimensions; width widens for long pathway labels.
      # Classic GSEA uses fixed dimensions, multi-pathway plots scale by labels/top-N.
      if (identical(input$enrichment_viz_type, "gsea_classic")) {
        plot_width  <- 12
        plot_height <- 9
      } else {
        max_label_chars <- max(nchar(as.character(plot_df$Description_wrapped)))
        plot_width  <- max(14, 10 + (max_label_chars / 18))
        plot_height <- max(9, input$enrichment_viz_top * 0.45)
      }

      save_ok <- tryCatch({
        if (fmt == "svg") {
          ggsave(file, plot = p, device = "svg",
                 width = plot_width, height = plot_height,
                 units = "in", bg = "white")
        } else if (fmt == "pdf") {
          ggsave(file, plot = p, device = cairo_pdf,
                 width = plot_width, height = plot_height,
                 units = "in", bg = "white")
        } else {
          ggsave(file, plot = p, device = "png",
                 width = plot_width, height = plot_height,
                 units = "in", dpi = 600, bg = "white")
        }
        TRUE
      }, error = function(e) {
        # SVG/PDF device errors (e.g. svglite missing) fall back to PNG at 600 dpi
        ggsave(file, plot = p, device = "png",
               width = plot_width, height = plot_height,
               units = "in", dpi = 600, bg = "white")
        FALSE
      })
    }
  )
  
