    kg <- !is.null(tx_get_kegg_code(k))
    paste0("Available for this species: GO ", if (go) "\u2713" else "\u2717",
           " | KEGG ", if (kg) "\u2713" else "\u2717",
           "  (Reactome / WikiPathways / Hallmark: human & common models only)")
  })
  
  # Get KEGG organism code
  get_kegg_org <- function(organism) {
    switch(organism,
           "hsapiens" = "hsa",
           "mmusculus" = "mmu",
           "rnorvegicus" = "rno",
           "drerio" = "dre",
           "dmelanogaster" = "dme",
           "celegans" = "cel",
           "scerevisiae" = "sce",
           "athaliana" = "ath",
           "ggallus" = "gga",
           "sscrofa" = "ssc",
           "btaurus" = "bta",
           "xlaevis" = "xla",
           "cfamiliaris" = "cfa",
           "ecoli" = "eco",
           "hsa")
  }
  
  # Get the appropriate keytype for enrichGO
  # Most organisms use SYMBOL, yeast uses ORF, Arabidopsis can use TAIR or SYMBOL
  get_gene_keytype <- function(organism) {
    switch(organism,
           "scerevisiae" = "ORF",
           "athaliana" = "SYMBOL",  # Arabidopsis TAIR IDs also work but SYMBOL is more universal
           "SYMBOL")
  }

  # Convert gene symbols to Entrez IDs
  convert_to_entrez <- function(genes, organism) {
    if (is.null(genes) || length(genes) == 0) {
      return(character(0))
    }
    
    tryCatch({
      orgdb <- get_orgdb(organism)
      
      # Clean genes
      genes <- unique(as.character(genes))
      genes <- genes[!is.na(genes) & genes != ""]
      
      if (length(genes) == 0) return(character(0))
      
      # Detect gene ID type
      sample_genes <- head(genes, 20)
      n_ensg <- sum(grepl("^ENSG[0-9]", sample_genes, ignore.case = TRUE))
      n_ensmusg <- sum(grepl("^ENSMUSG[0-9]", sample_genes, ignore.case = TRUE))
      n_entrez <- sum(grepl("^[0-9]+$", sample_genes))
      n_symbol <- length(sample_genes) - n_ensg - n_ensmusg - n_entrez
      
      # Determine keytype based on majority
      if (n_entrez > length(sample_genes) / 2) {
        # Already Entrez IDs
        print("convert_to_entrez: Input appears to be Entrez IDs already")
        return(genes)
      } else if (n_ensg > length(sample_genes) / 3 || n_ensmusg > length(sample_genes) / 3) {
        # Ensembl IDs
        keytype <- "ENSEMBL"
        print("convert_to_entrez: Converting from Ensembl IDs")
        # Remove version numbers if present (ENSG00000141510.16 -> ENSG00000141510)
        genes <- gsub("\\.[0-9]+$", "", genes)
      } else {
        # Assume gene symbols (most common)
        keytype <- "SYMBOL"
        print("convert_to_entrez: Converting from gene symbols")
        # Only uppercase for human - other organisms have different case conventions
        # Mouse: Tp53, Rat: Tp53, Zebrafish: tp53
        if (organism == "hsapiens") {
          genes <- toupper(genes)
        }
      }
      
      # Map to Entrez
      mapped <- AnnotationDbi::mapIds(
        orgdb,
        keys = genes,
        column = "ENTREZID",
        keytype = keytype,
        multiVals = "first"
      )
      
      result <- as.character(mapped[!is.na(mapped)])
      print(paste("convert_to_entrez: Mapped", length(result), "of", length(genes), "genes"))
      return(result)
      
    }, error = function(e) {
      print(paste("Error in convert_to_entrez:", e$message))
      return(character(0))
    })
  }
  
  
