  # Create reactive values for enrichment results
  enrichment_rv <- reactiveValues(
    results = NULL,
    mode = NULL
  )
  
  # Reactive to store uploaded expression file data
  gsea_expression_preview <- reactiveVal(NULL)
  
  # Watch for GSEA expression file upload
  observeEvent(input$gsea_expressionFile, {
    req(input$gsea_expressionFile)
    
    tryCatch({
      file_path <- input$gsea_expressionFile$datapath
      file_name <- input$gsea_expressionFile$name
      
      # Read file based on extension
      if (grepl("\\.xlsx$", file_name, ignore.case = TRUE)) {
        data <- openxlsx::read.xlsx(file_path)
      } else if (grepl("\\.tsv$", file_name, ignore.case = TRUE)) {
        data <- read.delim(file_path, stringsAsFactors = FALSE)
      } else {
        # Try CSV first, then tab-delimited
        data <- tryCatch({
          read.csv(file_path, stringsAsFactors = FALSE)
        }, error = function(e) {
          read.delim(file_path, stringsAsFactors = FALSE)
        })
      }
      
      gsea_expression_preview(data)
      
    }, error = function(e) {
      showNotification(paste("Error reading file:", e$message), type = "error")
      gsea_expression_preview(NULL)
    })
  })
  
  # Render column mapping UI
  output$gsea_expression_column_mapping <- renderUI({
    req(gsea_expression_preview())
    
    data <- gsea_expression_preview()
    n_rows <- nrow(data)
    n_cols <- ncol(data)
    n_genes <- length(unique(data[[1]]))
    
    div(
      style = "margin-top: 10px;",
      
      # Upload success indicator
      div(style = "background: #d4edda; padding: 10px; border-radius: 6px; margin-bottom: 10px; border: 1px solid #c3e6cb;",
          icon("check-circle", style = "color: #28a745;"),
          span(style = "color: #155724; font-weight: 500;", " Upload complete")
      ),
      
      # Button to open configuration modal
      actionButton(
        "open_gsea_config_modal",
        tagList(icon("cog"), " Configure Column Mapping"),
        class = "btn-primary btn-block",
        style = "margin-bottom: 10px;"
      ),
      
      # Quick summary
      div(
        style = "background: #e8f5e9; padding: 12px; border-radius: 6px; border-left: 3px solid #4CAF50;",
        icon("check-circle", style = "color: #4CAF50;"),
        strong(paste0(" Ready: ", n_genes, " unique genes with ranking data"), style = "color: #2e7d32;")
      )
    )
  })
  
  observeEvent(input$open_gsea_config_modal, {
    req(gsea_expression_preview())

    tryCatch({
      data <- gsea_expression_preview()

      if (is.null(data) || !is.data.frame(data) || nrow(data) == 0 || ncol(data) == 0) {
        showNotification(
          tagList(icon("exclamation-triangle"), " Uploaded file is empty or could not be parsed. Try saving as CSV with a header row."),
          type = "error", duration = 10)
        return(invisible(NULL))
      }

      col_names <- colnames(data)
      numeric_cols <- col_names[sapply(data, is.numeric)]

      if (length(numeric_cols) == 0) {
        showNotification(
          tagList(icon("exclamation-triangle"),
                  " No numeric columns detected. GSEA needs at least one numeric column for ranking (e.g. log2FC, t-statistic, signed -log10(p)). Check that your file has a header row and the ranking column is numeric, not text."),
          type = "error", duration = 12)
        return(invisible(NULL))
      }
    
    # Auto-detect gene column
    gene_col_guess <- col_names[1]
    gene_patterns <- c("^gene$", "^Gene$", "^gene_symbol$", "^SYMBOL$", "^symbol$",
                       "^gene_name$", "^GeneName$", "^GENE$", "^genes$")
    for (pattern in gene_patterns) {
      matches <- col_names[grepl(pattern, col_names, ignore.case = TRUE)]
      if (length(matches) > 0) {
        gene_col_guess <- matches[1]
        break
      }
    }
    
    # Auto-detect ranking column
    rank_col_guess <- numeric_cols[1]
    rank_priorities <- c("log2FoldChange", "log2FC", "logFC", "FC", "stat", "t", "Score", "score")
    for (col in rank_priorities) {
      if (col %in% numeric_cols) {
        rank_col_guess <- col
        break
      }
    }
    
    # Auto-detect p-value column  
    pval_col_guess <- ""
    pval_priorities <- c("pvalue", "PValue", "P.Value", "pval", "padj", "FDR", "adj.P.Val")
    for (col in pval_priorities) {
      if (col %in% numeric_cols) {
        pval_col_guess <- col
        break
      }
    }
    
    # Preview data
    preview_data <- head(data, 15)
    
    showModal(modalDialog(
      title = tagList(
        icon("columns", style = "color: #667eea;"), 
        " Configure Expression Data for GSEA"
      ),
      size = "l",
      easyClose = FALSE,
      
      fluidRow(
        # Left side: Configuration
        column(5,
               div(
                 style = "background: #f8f9fa; padding: 20px; border-radius: 10px; height: 100%;",
                 
                 h4(icon("database"), " Data Summary", style = "color: #2c3e50; margin-top: 0;"),
                 div(
                   style = "display: flex; gap: 15px; margin-bottom: 20px;",
                   div(style = "text-align: center; padding: 10px; background: white; border-radius: 8px; flex: 1;",
                       h3(nrow(data), style = "margin: 0; color: #667eea;"),
                       tags$small("Rows", style = "color: #666;")
                   ),
                   div(style = "text-align: center; padding: 10px; background: white; border-radius: 8px; flex: 1;",
                       h3(ncol(data), style = "margin: 0; color: #28a745;"),
                       tags$small("Columns", style = "color: #666;")
                   )
                 ),
                 
                 hr(),
                 
                 h4(icon("map-signs"), " Column Mapping", style = "color: #2c3e50;"),
                 
                 div(style = "margin-bottom: 15px;",
                     selectInput("gsea_gene_column_modal", 
                                 tagList(icon("dna"), " Gene/Symbol Column:"),
                                 choices = col_names,
                                 selected = gene_col_guess,
                                 width = "100%")
                 ),
                 
                 div(style = "margin-bottom: 15px;",
                     selectInput("gsea_rank_column_modal",
                                 tagList(icon("sort-numeric-down"), " Ranking Column:"),
                                 choices = numeric_cols,
                                 selected = rank_col_guess,
                                 width = "100%")
                 ),
                 
                 div(style = "margin-bottom: 15px;",
                     selectInput("gsea_pval_column_modal",
                                 tagList(icon("calculator"), " P-value Column (optional):"),
                                 choices = c("None" = "", numeric_cols),
                                 selected = pval_col_guess,
                                 width = "100%")
                 ),
                 
                 div(style = "margin-bottom: 15px;",
                     selectInput("gsea_rank_method_modal",
                                 tagList(icon("cogs"), " Ranking Method:"),
                                 choices = c("Use ranking column directly" = "direct",
                                             "Signed P-value (-log10 * sign)" = "signed_pval",
                                             "t-statistic style" = "tstat"),
                                 selected = "direct",
                                 width = "100%")
                 ),
                 
                 # Validation status
                 uiOutput("gsea_modal_validation_status")
               )
        ),
        
        # Right side: Live Preview
        column(7,
               div(
                 style = "background: white; padding: 15px; border-radius: 10px; border: 1px solid #dee2e6;",
                 
                 h4(icon("eye"), " Data Preview", style = "color: #2c3e50; margin-top: 0;"),
                 p(style = "color: #666; font-size: 0.9rem;", "Showing first 15 rows of your data"),
                 
                 div(
                   style = "overflow-x: auto; max-height: 350px; overflow-y: auto;",
                   DT::dataTableOutput("gsea_modal_preview_table")
                 ),
                 
                 hr(),
                 
                 # Show processed ranking preview
                 h5(icon("chart-line"), " Ranking Preview", style = "color: #667eea;"),
                 uiOutput("gsea_ranking_preview")
               )
        )
      ),
      
      footer = tagList(
        modalButton("Cancel"),
        actionButton("apply_gsea_config", "Apply Configuration", 
                     class = "btn-success", icon = icon("check"))
      )
    ))
    }, error = function(e) {
      showNotification(
        tagList(icon("times-circle"),
                paste0(" Could not open column configuration: ",
                       conditionMessage(e),
                       ". Your file may be malformed; try a smaller CSV with a clear header row.")),
        type = "error", duration = 15)
    })
  })

  output$gsea_modal_preview_table <- DT::renderDataTable({
    req(gsea_expression_preview())
    
    data <- head(gsea_expression_preview(), 15)
    
    DT::datatable(
      data,
      options = list(
        pageLength = 15,
        scrollX = TRUE,
        scrollY = "280px",
        dom = 't',
        ordering = FALSE
      ),
      rownames = FALSE,
      class = "display compact stripe hover",
      selection = "none"
    )
  })
  
  
  # STEP 3D: Add validation status in modal
  output$gsea_modal_validation_status <- renderUI({
    req(gsea_expression_preview())
    req(input$gsea_gene_column_modal, input$gsea_rank_column_modal)
    
    data <- gsea_expression_preview()
    gene_col <- input$gsea_gene_column_modal
    rank_col <- input$gsea_rank_column_modal
    
    # Validation checks
    issues <- c()
    
    # Check gene column
    unique_genes <- length(unique(data[[gene_col]]))
    if (unique_genes < 100) {
      issues <- c(issues, paste0("Warning: Only ", unique_genes, " unique genes found"))
    }
    
    # Check for NA values
    na_count <- sum(is.na(data[[rank_col]]))
    if (na_count > 0) {
      issues <- c(issues, paste0(na_count, " missing values in ranking column"))
    }
    
    # Check ranking column range
    rank_range <- range(data[[rank_col]], na.rm = TRUE)
    
    if (length(issues) == 0) {
      div(
        style = "background: #d4edda; padding: 12px; border-radius: 6px; margin-top: 15px;",
        icon("check-circle", style = "color: #28a745;"),
        strong(" Ready for GSEA", style = "color: #155724;"),
        p(style = "margin: 5px 0 0 0; font-size: 0.9rem; color: #155724;",
          paste0(unique_genes, " genes • Ranking range: [", 
                 round(rank_range[1], 2), " to ", round(rank_range[2], 2), "]"))
      )
    } else {
      div(
        style = "background: #fff3cd; padding: 12px; border-radius: 6px; margin-top: 15px;",
        icon("exclamation-triangle", style = "color: #856404;"),
        strong(" Review needed", style = "color: #856404;"),
        tags$ul(style = "margin: 5px 0 0 0; padding-left: 20px; color: #856404; font-size: 0.9rem;",
                lapply(issues, tags$li))
      )
    }
  })
  
  output$gsea_ranking_preview <- renderUI({
    req(gsea_expression_preview())
    req(input$gsea_gene_column_modal, input$gsea_rank_column_modal)
    
    data <- gsea_expression_preview()
    gene_col <- input$gsea_gene_column_modal
    rank_col <- input$gsea_rank_column_modal
    
    # Get top and bottom genes
    ranked <- data[order(data[[rank_col]], decreasing = TRUE), ]
    top_genes <- head(ranked, 3)
    bottom_genes <- tail(ranked, 3)
    
    div(
      style = "display: flex; gap: 20px;",
      div(
        style = "flex: 1; background: #e8f5e9; padding: 10px; border-radius: 6px;",
        strong("Top Ranked (Upregulated)", style = "color: #2e7d32; font-size: 0.85rem;"),
        tags$ol(style = "margin: 5px 0 0 0; padding-left: 20px; font-size: 0.85rem;",
                lapply(seq_len(nrow(top_genes)), function(i) {
                  tags$li(paste0(top_genes[[gene_col]][i], " (", round(top_genes[[rank_col]][i], 2), ")"))
                }))
      ),
      div(
        style = "flex: 1; background: #ffebee; padding: 10px; border-radius: 6px;",
        strong("Bottom Ranked (Downregulated)", style = "color: #c62828; font-size: 0.85rem;"),
        tags$ol(style = "margin: 5px 0 0 0; padding-left: 20px; font-size: 0.85rem;",
                lapply(seq_len(nrow(bottom_genes)), function(i) {
                  tags$li(paste0(bottom_genes[[gene_col]][i], " (", round(bottom_genes[[rank_col]][i], 2), ")"))
                }))
      )
    )
  })
  
  
  # STEP 3F: Apply configuration and close modal
  observeEvent(input$apply_gsea_config, {
    # Copy modal selections to main inputs
    updateSelectInput(session, "gsea_gene_column", selected = input$gsea_gene_column_modal)
    updateSelectInput(session, "gsea_rank_column", selected = input$gsea_rank_column_modal)
    updateSelectInput(session, "gsea_pval_column", selected = input$gsea_pval_column_modal)
    updateSelectInput(session, "gsea_custom_rank_method", selected = input$gsea_rank_method_modal)
    
    removeModal()
    
    showNotification(
      tagList(icon("check"), " Column mapping configured successfully!"),
      type = "message",
      duration = 3
    )
  })
  
  # Show data preview modal
  observeEvent(input$preview_gsea_data, {
    req(gsea_expression_preview())
    
