      easyClose = TRUE,
      
      div(
        style = "overflow-x: auto; max-height: 500px;",
        DT::renderDataTable({
          DT::datatable(
            preview_data,
            options = list(
              pageLength = 10,
              scrollX = TRUE,
              dom = 't'
            ),
            rownames = FALSE,
            class = "display compact stripe"
          )
        })
      ),
      
      footer = modalButton("Close")
    ))
  })
  
  # Column status indicator
  output$gsea_column_status <- renderUI({
    req(gsea_expression_preview())
    req(input$gsea_gene_column, input$gsea_rank_column)
    
    data <- gsea_expression_preview()
    gene_col <- input$gsea_gene_column
    rank_col <- input$gsea_rank_column
    
    # Validate
    issues <- c()
    
    if (!gene_col %in% colnames(data)) {
      issues <- c(issues, "Gene column not found")
    } else {
      n_unique <- length(unique(data[[gene_col]]))
      n_na <- sum(is.na(data[[gene_col]]))
      if (n_na > 0) issues <- c(issues, paste(n_na, "missing gene names"))
    }
    
    if (rank_col != "" && !rank_col %in% colnames(data)) {
      issues <- c(issues, "Ranking column not found")
    } else if (rank_col != "") {
      n_na <- sum(is.na(data[[rank_col]]))
      if (n_na > 0) issues <- c(issues, paste(n_na, "missing rank values"))
    }
    
    if (length(issues) == 0) {
      div(
        style = "margin-top: 10px; padding: 8px; background: #d4edda; border-radius: 4px; color: #155724;",
        icon("check-circle"), " Ready: ", 
        strong(length(unique(data[[gene_col]]))), " unique genes with ranking data"
      )
    } else {
      div(
        style = "margin-top: 10px; padding: 8px; background: #fff3cd; border-radius: 4px; color: #856404;",
        icon("exclamation-triangle"), " Warning: ", paste(issues, collapse = ", ")
      )
    }
  })
  
  
  # Modal plot observers
  observeEvent(input$show_kegg_plot_btn, {
    req(pathway_results())
    showModal(uiOutput("pathwayPlotModal"))
    current_plot_type("kegg")
  })
  
  observeEvent(input$show_reactome_plot_btn, {
    req(pathway_results())
    showModal(uiOutput("pathwayPlotModal"))
    current_plot_type("reactome")
  })
  
  observeEvent(input$show_wikipathways_plot_btn, {
    req(pathway_results())
    showModal(uiOutput("pathwayPlotModal"))
    current_plot_type("wikipathways")
  })
  
  # Reactive value for tracking current plot type
  current_plot_type <- reactiveVal(NULL)
  
  # Modal plot rendering
  output$modalPathwayPlot <- renderPlot({
    req(pathway_results(), current_plot_type(), input$modal_num_pathways)
    
    plot_type <- current_plot_type()
    results <- pathway_results()
    num_pathways <- as.numeric(input$modal_num_pathways)
    
    if (plot_type == "kegg" && !is.null(results$kegg)) {
      dotplot(results$kegg, showCategory = num_pathways, title = "KEGG Pathways")
    } else if (plot_type == "reactome" && !is.null(results$reactome)) {
      dotplot(results$reactome, showCategory = num_pathways, title = "Reactome Pathways")
    } else if (plot_type == "wikipathways" && !is.null(results$wikipathways)) {
      dotplot(results$wikipathways, showCategory = num_pathways, title = "WikiPathways")
    }
  })
  
  # Table outputs
  output$kegg_gsea_table <- DT::renderDataTable({
    req(pathway_results()$kegg)
    as.data.frame(pathway_results()$kegg@result)
  }, options = list(scrollX = TRUE))
  
  output$reactome_gsea_table <- DT::renderDataTable({
    req(pathway_results()$reactome)
    as.data.frame(pathway_results()$reactome@result)
  }, options = list(scrollX = TRUE))
  
  output$wikipathways_gsea_table <- DT::renderDataTable({
    req(pathway_results()$wikipathways)
    as.data.frame(pathway_results()$wikipathways@result)
  }, options = list(scrollX = TRUE))
  
  # Download handlers for tables
  output$download_kegg_table <- downloadHandler(
    filename = function() {
      paste("kegg_pathway_results_", Sys.Date(), ".csv", sep = "")
    },
    content = function(file) {
      load_export_packages()
      write.csv(as.data.frame(pathway_results()$kegg@result), file)
    }
  )
  
  output$download_reactome_table <- downloadHandler(
    filename = function() {
      paste("reactome_pathway_results_", Sys.Date(), ".csv", sep = "")
    },
    content = function(file) {
      load_export_packages()
      write.csv(as.data.frame(pathway_results()$reactome@result), file)
    }
  )
  
  output$download_wikipathways_table <- downloadHandler(
    filename = function() {
      paste("wikipathways_results_", Sys.Date(), ".csv", sep = "")
    },
    content = function(file) {
      load_export_packages()
      write.csv(as.data.frame(pathway_results()$wikipathways@result), file)
    }
  )
  
  # Download handler for modal plot
  output$downloadModalPlot <- downloadHandler(
    filename = function() {
      paste0(current_plot_type(), "_enrichment_plot_", Sys.Date(), ".png")
    },
    content = function(file) {
      load_export_packages()
      png(file, width = 800, height = 600)
      plot_type <- current_plot_type()
      results <- pathway_results()
      num_pathways <- as.numeric(input$modal_num_pathways)
      
      if (plot_type == "kegg" && !is.null(results$kegg)) {
        print(dotplot(results$kegg, showCategory = num_pathways, title = "KEGG Pathways"))
      } else if (plot_type == "reactome" && !is.null(results$reactome)) {
        print(dotplot(results$reactome, showCategory = num_pathways, title = "Reactome Pathways"))
      } else if (plot_type == "wikipathways" && !is.null(results$wikipathways)) {
        print(dotplot(results$wikipathways, showCategory = num_pathways, title = "WikiPathways"))
      }
      dev.off()
    }
  )
  # GO Analysis function
  run_go_analysis <- eventReactive(input$run_go_analysis, {
    req(go_processed_data())
    
    print("Starting GO analysis...")
    
    withProgress(message = "Running GO Analysis...", value = 0, {
      tryCatch({
        df <- go_processed_data()
        
        # Get threshold values from UI
        pvalue_cutoff <- input$go_pvalue_threshold
        qvalue_cutoff <- input$go_qvalue_threshold
        adjust_method <- input$go_adjust_method
        
        # Prepare gene list
        gene_list <- df$logFC
        results <- list()
        
        # Remove any NA values and prepare gene list
        valid_indices <- !is.na(df$entrez_ids)
        gene_list_filtered <- gene_list[valid_indices]
        names(gene_list_filtered) <- df$entrez_ids[valid_indices]
        gene_list_filtered <- sort(gene_list_filtered, decreasing = TRUE)
        
        # Select appropriate organism database
        go_db <- switch(input$organism_go,
                        "human" = org.Hs.eg.db,
                        "mouse" = org.Mm.eg.db,
                        "rat" = org.Rn.eg.db)
        
        # Always analyze all GO ontologies
        go_ontologies <- c("BP", "MF", "CC")
        
        # Calculate progress step size based on number of ontologies
        progress_step <- 0.8 / length(go_ontologies)
        current_progress <- 0.1  # Start after initial setup
        
        # Run analysis for each ontology
        for (ontology in go_ontologies) {
          print(paste("Processing GO", ontology))
          incProgress(current_progress,
                      detail = paste("Processing GO", ontology))
          
          tryCatch({
            # Use clusterProfiler's gseGO for more reliable results
            go_result <- gseGO(
              geneList = gene_list_filtered,
              OrgDb = go_db,
              ont = ontology,
              keyType = "ENTREZID",
              minGSSize = 10,
              maxGSSize = 500,
              pvalueCutoff = pvalue_cutoff,
              pAdjustMethod = adjust_method
            )
            
            # Store results if analysis was successful
            if (!is.null(go_result) && length(go_result) > 0) {
              results[[paste0("go_", tolower(ontology))]] <- go_result
              print(paste("Successfully completed GO", ontology, "analysis"))
              print(paste("Number of enriched terms:", length(go_result)))
            } else {
              print(paste("No significant GO terms found for", ontology))
              showNotification(
                paste("No significant GO terms found for", ontology),
                type = "warning",
                duration = 5
              )
            }
            
          }, error = function(e) {
            print(paste("Error in GO analysis for", ontology, ":", e$message))
            showNotification(
              paste("Error in GO analysis for", ontology, ": ", e$message),
              type = "error",
              duration = 7
            )
          })
          
          current_progress <- current_progress + progress_step
          incProgress(current_progress,
                      detail = paste("Completed", ontology))
        }
        
        # Final progress update
        incProgress(1, detail = "GO analysis complete")
        
        # Validate results before returning
        if (length(results) == 0) {
          showNotification(
            "No significant GO terms found in any category. Try adjusting the threshold parameters.",
            type = "warning",
            duration = 7
          )
        }
        
        return(results)
        
      }, error = function(e) {
        showNotification(
          paste("Error in GO analysis:", e$message),
          type = "error",
          duration = 7
        )
        print(paste("Error in GO analysis:", e$message))
        return(NULL)
      })
    })
  })
  
  # Render KEGG results table
  output$kegg_gsea_table <- DT::renderDataTable({
    req(run_pathway_analysis())
    req(run_pathway_analysis()$kegg)
    print("Rendering KEGG table...")
    tryCatch({
      df <- as.data.frame(run_pathway_analysis()$kegg)
      if (nrow(df) == 0) {
        return(data.frame(Message = "No significant KEGG pathways found"))
      }
      return(df)
    }, error = function(e) {
      print(paste("Error in KEGG table:", e$message))
      return(data.frame(Error = "Failed to generate KEGG results table"))
    })
  }, options = list(pageLength = 10, scrollX = TRUE))
  
  # Render Reactome results table
  output$reactome_gsea_table <- DT::renderDataTable({
    req(run_pathway_analysis())
    req(run_pathway_analysis()$reactome)
    print("Rendering Reactome table...")
    tryCatch({
      df <- as.data.frame(run_pathway_analysis()$reactome)
      if (nrow(df) == 0) {
        return(data.frame(Message = "No significant Reactome pathways found"))
      }
      return(df)
    }, error = function(e) {
      print(paste("Error in Reactome table:", e$message))
      return(data.frame(Error = "Failed to generate Reactome results table"))
    })
  }, options = list(pageLength = 10, scrollX = TRUE))
  
  # Render WikiPathways results table
  output$wikipathways_gsea_table <- DT::renderDataTable({
    req(run_pathway_analysis())
    req(run_pathway_analysis()$wikipathways)
    print("Rendering WikiPathways table...")
    tryCatch({
      df <- as.data.frame(run_pathway_analysis()$wikipathways)
      if (nrow(df) == 0) {
