    }, error = function(e) {
      print(paste("Error in WikiPathways table:", e$message))
      return(data.frame(Error = "Failed to generate WikiPathways results table"))
    })
  }, options = list(pageLength = 10, scrollX = TRUE))
  
  # Render GO BP results table
  output$go_bp_gsea_table <- DT::renderDataTable({
    req(run_go_analysis())
    req(run_go_analysis()$go_bp)
    print("Rendering GO BP table...")
    tryCatch({
      df <- as.data.frame(run_go_analysis()$go_bp)
      if (nrow(df) == 0) {
        return(data.frame(Message = "No significant GO Biological Process terms found"))
      }
      return(df)
    }, error = function(e) {
      print(paste("Error in GO BP table:", e$message))
      return(data.frame(Error = "Failed to generate GO BP results table"))
    })
  }, options = list(pageLength = 10, scrollX = TRUE))
  
  # Render GO MF results table
  output$go_mf_gsea_table <- DT::renderDataTable({
    req(run_go_analysis())
    req(run_go_analysis()$go_mf)
    print("Rendering GO MF table...")
    tryCatch({
      df <- as.data.frame(run_go_analysis()$go_mf)
      if (nrow(df) == 0) {
        return(data.frame(Message = "No significant GO Molecular Function terms found"))
      }
      return(df)
    }, error = function(e) {
      print(paste("Error in GO MF table:", e$message))
      return(data.frame(Error = "Failed to generate GO MF results table"))
    })
  }, options = list(pageLength = 10, scrollX = TRUE))
  
  # Render GO CC results table
  output$go_cc_gsea_table <- DT::renderDataTable({
    req(run_go_analysis())
    req(run_go_analysis()$go_cc)
    print("Rendering GO CC table...")
    tryCatch({
      df <- as.data.frame(run_go_analysis()$go_cc)
      if (nrow(df) == 0) {
        return(data.frame(Message = "No significant GO Cellular Component terms found"))
      }
      return(df)
    }, error = function(e) {
      print(paste("Error in GO CC table:", e$message))
      return(data.frame(Error = "Failed to generate GO CC results table"))
    })
  }, options = list(pageLength = 10, scrollX = TRUE))
  
  # Render GO ALL results table
  output$go_all_gsea_table <- DT::renderDataTable({
    req(run_go_analysis()$go_bp, run_go_analysis()$go_mf, run_go_analysis()$go_cc)
    tryCatch({
      df_bp <- as.data.frame(run_go_analysis()$go_bp)
      df_mf <- as.data.frame(run_go_analysis()$go_mf)
      df_cc <- as.data.frame(run_go_analysis()$go_cc)
      
      # Check if each dataframe is empty and replace with a dummy row if necessary
      if (nrow(df_bp) == 0) {
        df_bp <- data.frame(Description = "No significant terms found", Ontology = "BP", stringsAsFactors = FALSE)
      } else {
        df_bp$Ontology <- "BP"
      }
      
      if (nrow(df_mf) == 0) {
        df_mf <- data.frame(Description = "No significant terms found", Ontology = "MF", stringsAsFactors = FALSE)
      } else {
        df_mf$Ontology <- "MF"
      }
      
      if (nrow(df_cc) == 0) {
        df_cc <- data.frame(Description = "No significant terms found", Ontology = "CC", stringsAsFactors = FALSE)
      } else {
        df_cc$Ontology <- "CC"
      }
      
      # Combine dataframes
      df_combined <- rbind(df_bp, df_mf, df_cc)
      
      return(df_combined)
    }, error = function(e) {
      print(paste("Error in combining GO results:", e$message))
      return(data.frame(Error = "Failed to combine GO results"))
    })
  }, options = list(pageLength = 10, scrollX = TRUE))
  
  # Download handlers for Pathway Analysis tables
  output$download_kegg_table <- downloadHandler(
    filename = function() {
      paste("kegg_gsea_results-", Sys.Date(), ".csv", sep = "")
    },
    content = function(file) {
      load_export_packages()
