      write.csv(as.data.frame(run_pathway_analysis()$wikipathways), file, row.names = FALSE)
    }
  )
  
  # Download handlers for GO Analysis tables
  output$download_go_bp_table <- downloadHandler(
    filename = function() {
      paste("go_bp_gsea_results-", Sys.Date(), ".csv", sep = "")
    },
    content = function(file) {
      load_export_packages()
      write.csv(as.data.frame(run_go_analysis()$go_bp), file, row.names = FALSE)
    }
  )
  
  output$download_go_mf_table <- downloadHandler(
    filename = function() {
