    },
    content = function(file) {
      load_export_packages()
      write.csv(as.data.frame(run_go_analysis()$go_cc), file, row.names = FALSE)
    }
  )
  
  output$download_go_all_table <- downloadHandler(
    filename = function() {
      paste("go_all_gsea_results-", Sys.Date(), ".csv", sep = "")
    },
    content = function(file) {
      load_export_packages()
      # Ensure that all GO results are available before attempting to combine them
      req(run_go_analysis()$go_bp, run_go_analysis()$go_mf, run_go_analysis()$go_cc)
      
      tryCatch({
        df_bp <- as.data.frame(run_go_analysis()$go_bp)
        df_mf <- as.data.frame(run_go_analysis()$go_mf)
        df_cc <- as.data.frame(run_go_analysis()$go_cc)
        
        # Check if each dataframe is empty and replace with a dummy row if necessary
        if (nrow(df_bp) == 0) {
          df_bp <- data.frame(Description = "No significant terms found", Ontology = "BP", stringsAsFactors = FALSE)
        } else {
          df_bp$Ontology <- "BP"
        }
        
        if (nrow(df_mf) == 0) {
          df_mf <- data.frame(Description = "No significant terms found", Ontology = "MF", stringsAsFactors = FALSE)
        } else {
          df_mf$Ontology <- "MF"
        }
        
        if (nrow(df_cc) == 0) {
          df_cc <- data.frame(Description = "No significant terms found", Ontology = "CC", stringsAsFactors = FALSE)
        } else {
          df_cc$Ontology <- "CC"
        }
        
        # Combine dataframes
        df_combined <- rbind(df_bp, df_mf, df_cc)
        
        # Write the combined data frame to a CSV file
        write.csv(df_combined, file, row.names = FALSE)
      }, error = function(e) {
        print(paste("Error in combining GO results for download:", e$message))
        showNotification(
          paste("Error in combining GO results for download:", e$message),
          type = "error"
        )
      })
    }
  )
  
  # Reactive expression to generate KEGG enrichment plot
  kegg_enrichment_plot <- eventReactive(input$generate_kegg_plot, {
    req(run_pathway_analysis())
    req(run_pathway_analysis()$kegg)
    print("Generating KEGG plot...")
    num_pathways <- as.numeric(input$num_pathways_kegg_plot)
    
    tryCatch({
      if (nrow(as.data.frame(run_pathway_analysis()$kegg)) == 0) {
        return(ggplot() +
                 annotate("text", x = 1, y = 1,
                          label = "No significant KEGG pathways found") +
                 theme_void())
      }
      dotplot(run_pathway_analysis()$kegg, showCategory = num_pathways,
              title = "KEGG Pathway Enrichment")
    }, error = function(e) {
      print(paste("Error in KEGG plot:", e$message))
      showModal(modalDialog(
        title = "Error",
        paste("An error occurred while generating the KEGG enrichment plot:", e$message),
        easyClose = TRUE
      ))
      return(NULL)
    })
  })
  
  # Render KEGG enrichment plot
  output$kegg_enrichment_plot <- renderPlot({
    kegg_enrichment_plot()
  })
  
  # Download handler for KEGG enrichment plot
  output$download_kegg_plot <- downloadHandler(
    filename = function() {
      paste("kegg_enrichment_plot-", Sys.Date(), ".png", sep = "")
    },
    content = function(file) {
      load_export_packages()
      num_pathways <- as.numeric(input$num_pathways_kegg_plot)
      p <- dotplot(run_pathway_analysis()$kegg, showCategory = num_pathways, title = "KEGG Pathway Enrichment")
      ggsave(file, plot = p, device = "png", width = 10, height = 8, dpi = 300)
    }
  )
  
  # Reactive expression to generate Reactome enrichment plot
  reactome_enrichment_plot <- eventReactive(input$generate_reactome_plot, {
    req(run_pathway_analysis())
    req(run_pathway_analysis()$reactome)
    print("Generating Reactome plot...")
    num_pathways <- as.numeric(input$num_pathways_reactome_plot)
    
    tryCatch({
