  # Download handler for Reactome enrichment plot
  output$download_reactome_plot <- downloadHandler(
    filename = function() {
      paste("reactome_enrichment_plot-", Sys.Date(), ".png", sep = "")
    },
    content = function(file) {
      load_export_packages()
      num_pathways <- as.numeric(input$num_pathways_reactome_plot)
      p <- dotplot(run_pathway_analysis()$reactome, showCategory = num_pathways, title = "Reactome Pathway Enrichment")
      ggsave(file, plot = p, device = "png", width = 10, height = 8, dpi = 300)
    }
  )
  
  # Reactive expression to generate Wikipathways enrichment plot
  wikipathways_enrichment_plot <- eventReactive(input$generate_wikipathways_plot, {
    req(run_pathway_analysis())
    req(run_pathway_analysis()$wikipathways)
    print("Generating Wikipathways plot...")
    num_pathways <- as.numeric(input$num_pathways_wikipathways_plot)
    
    tryCatch({
      if (nrow(as.data.frame(run_pathway_analysis()$wikipathways)) == 0) {
        return(ggplot() +
                 annotate("text", x = 1, y = 1,
                          label = "No significant Wikipathways pathways found") +
                 theme_void())
      }
      dotplot(run_pathway_analysis()$wikipathways, showCategory = num_pathways,
              title = "Wikipathways Pathway Enrichment")
    }, error = function(e) {
