        easyClose = TRUE
      ))
      return(NULL)
    })
  })
  
  # Render WikiPathways enrichment plot
  output$wikipathways_enrichment_plot <- renderPlot({
    wikipathways_enrichment_plot()
  })
  
  # Download handler for WikiPathways enrichment plot
  output$download_wikipathways_plot <- downloadHandler(
    filename = function() {
      paste("wikipathways_enrichment_plot-", Sys.Date(), ".png", sep = "")
    },
    content = function(file) {
      load_export_packages()
      num_pathways <- as.numeric(input$num_pathways_wikipathways_plot)
      p <- dotplot(run_pathway_analysis()$wikipathways, showCategory = num_pathways, title = "WikiPathways Enrichment")
      ggsave(file, plot = p, device = "png", width = 10, height = 8, dpi = 300)
    }
  )
  
  # Reactive expression to generate GO enrichment plot
  go_enrichment_plot <- eventReactive(input$generate_go_plot, {
    req(run_go_analysis())
    
    num_terms <- as.numeric(input$num_terms_go_plot)
    
    # Select the appropriate result based on selected ontology
    if (input$go_ontology == "ALL") {
      # Combine results if ALL is selected
      go_data <- list()
      if (!is.null(run_go_analysis()$go_bp)) go_data$BP <- run_go_analysis()$go_bp
      if (!is.null(run_go_analysis()$go_mf)) go_data$MF <- run_go_analysis()$go_mf
      if (!is.null(run_go_analysis()$go_cc)) go_data$CC <- run_go_analysis()$go_cc
      
      if (length(go_data) == 0) {
        return(ggplot() +
                 annotate("text", x = 1, y = 1,
                          label = "No GO analysis results available") +
                 theme_void())
      }
      
      # Here you might need to adjust how you combine or select which result to plot
      # For simplicity, let's just take the first one if available
      go_data <- go_data[[1]]
      
    } else {
      # Use the specific ontology result if not ALL
      go_data <- switch(input$go_ontology,
                        "BP" = run_go_analysis()$go_bp,
                        "MF" = run_go_analysis()$go_mf,
                        "CC" = run_go_analysis()$go_cc)
    }
    
    req(go_data) # Ensure go_data is available
    
    tryCatch({
      dotplot(go_data, showCategory = num_terms, title = paste("GO Enrichment (", input$go_ontology, ")"))
    }, error = function(e) {
      showModal(modalDialog(
        title = "Error",
        paste("An error occurred while generating the GO enrichment plot:", e$message),
        easyClose = TRUE
      ))
      return(NULL)
    })
  })
  
  # Render GO enrichment plot
  output$go_enrichment_plot <- renderPlot({
    go_enrichment_plot()
  })
  
  
  # Download handler for enrichment plot
  output$download_go_plot <- downloadHandler(
    filename = function() {
      paste("enrichment_plot-", Sys.Date(), ".png", sep = "")
    },
    content = function(file) {
      load_export_packages()
      # Get number of terms to display
      num_terms <- as.numeric(input$num_terms_go_plot)
      
      # Select the appropriate result based on selected ontology
      if (input$go_ontology == "ALL") {
        go_data_list <- list()
        if (!is.null(run_go_analysis()$go_bp)) go_data_list$BP <- run_go_analysis()$go_bp
        if (!is.null(run_go_analysis()$go_mf)) go_data_list$MF <- run_go_analysis()$go_mf
        if (!is.null(run_go_analysis()$go_cc)) go_data_list$CC <- run_go_analysis()$go_cc
        
        if (length(go_data_list) == 0) {
          p <- ggplot() +
            annotate("text", x = 1, y = 1, label = "No enrichment results available") +
            theme_void()
          ggsave(file, plot = p, device = "png", width = 10, height = 8, dpi = 300)
          return()
        }
        
        go_data <- go_data_list[[1]]
      } else {
        go_data <- switch(input$go_ontology,
                          "BP" = run_go_analysis()$go_bp,
                          "MF" = run_go_analysis()$go_mf,
                          "CC" = run_go_analysis()$go_cc)
      }
      
      req(go_data) # Ensure go_data is available
      
      # Convert to data frame safely
      go_df <- as.data.frame(go_data@result)  # Note: Using @result to access the data.frame
      
      if (nrow(go_df) == 0) {
        p <- ggplot() +
          annotate("text", x = 1, y = 1,
                   label = paste("No significant terms found for", input$go_ontology)) +
          theme_void()
      } else {
        # Take top n terms based on adjusted p-value
        go_df <- go_df %>%
          arrange(p.adjust) %>%
          head(num_terms)
        
        # Create the plot using NES (Normalized Enrichment Score)
        p <- ggplot(go_df, aes(x = NES, y = reorder(Description, NES))) +
          geom_point(aes(
            size = setSize,
            color = p.adjust
          )) +
          scale_color_gradient(
            limits = c(0, 0.10),
            low = "red",
            high = "blue",
            name = "Adjusted p-value"
          ) +
          scale_size_continuous(
            name = "Gene Set Size",
            breaks = scales::pretty_breaks(n = 5)
          ) +
          theme_bw() +
          labs(
            title = paste("Gene Set Enrichment Analysis (", input$go_ontology, ")"),
            x = "Normalized Enrichment Score (NES)",
            y = "Gene Set"
          ) +
          theme(
            axis.text.y = element_text(size = 10, hjust = 1),
            plot.title = element_text(size = 12, face = "bold"),
            legend.position = "right",
            # Improve readability of long descriptions
            plot.margin = margin(10, 20, 10, 10),
            panel.grid.major.y = element_line(color = "grey90")
          )
      }
      
      # Save the plot with dimensions adjusted for readability
      ggsave(file, plot = p, device = "png", width = 12, height = max(8, num_terms * 0.3), dpi = 300)
    }
  )
  
  
  
  #______________________________________________-MODAL
  # Create a reactive value to store the current plot
  current_modal_plot <- reactiveVal()
  
  # Create a reactive value to store the current GO category for the modal
  current_go_category <- reactiveVal()
  
  # Helper function to show modal for any GO category
  showGOPlotModal <- function(category) {
    current_go_category(category)
    showModal(modalDialog(
      title = paste("Gene Set Enrichment Analysis Plot -", category),
      size = "l",
      
      plotOutput("modal_enrichment_plot",
                 height = "600px",
                 width = "100%"),
      
      fluidRow(
        column(12,
               numericInput("num_terms_modal", "Number of terms to show:",
                            value = 10, min = 5, max = 50)
        )
      ),
      
      downloadButton("download_modal_plot", "Download Plot"),
      
      footer = tagList(
        modalButton("Close")
      ),
      easyClose = TRUE
    ))
  }
  
  # Observe events for each category's plot button
  observeEvent(input$show_bp_plot_btn, {
    showGOPlotModal("BP")
  })
  
  observeEvent(input$show_mf_plot_btn, {
    showGOPlotModal("MF")
  })
  
  observeEvent(input$show_cc_plot_btn, {
    showGOPlotModal("CC")
  })
  
  # Create and store the plot
  observe({
    req(input$num_terms_modal, current_go_category())
    
    # Get the appropriate GO data based on category
    go_data <- switch(current_go_category(),
                      "BP" = run_go_analysis()$go_bp,
                      "MF" = run_go_analysis()$go_mf,
                      "CC" = run_go_analysis()$go_cc)
    
    req(go_data)
    
    # Convert to data frame
    go_df <- as.data.frame(go_data@result)
    
    if (nrow(go_df) == 0) {
      current_modal_plot(ggplot() +
                           annotate("text", x = 1, y = 1,
                                    label = paste("No significant terms found for", current_go_category())) +
                           theme_void())
      return()
    }
    
    # Take top n terms based on adjusted p-value
    go_df <- go_df %>%
      arrange(p.adjust) %>%
      head(input$num_terms_modal)
    
    # Create the plot
    p <- ggplot(go_df, aes(x = NES, y = reorder(Description, NES))) +
      geom_point(aes(
        size = setSize,
        color = p.adjust
      )) +
      scale_color_gradient(
        limits = c(0, 0.10),
        low = "red",
        high = "blue",
        name = "Adjusted p-value"
      ) +
      scale_size_continuous(
        name = "Gene Set Size",
        breaks = scales::pretty_breaks(n = 5)
      ) +
      theme_bw() +
      labs(
        title = paste("Gene Set Enrichment Analysis (", current_go_category(), ")"),
        x = "Normalized Enrichment Score (NES)",
        y = "Gene Set"
      ) +
      theme(
        axis.text.y = element_text(size = 10, hjust = 1),
        plot.title = element_text(size = 12, face = "bold"),
        legend.position = "right",
        plot.margin = margin(10, 20, 10, 10),
        panel.grid.major.y = element_line(color = "grey90")
      )
    
    # Store the plot
    current_modal_plot(p)
  })
  
  # Render the modal plot
  output$modal_enrichment_plot <- renderPlot({
    req(current_modal_plot())
    current_modal_plot()
  })
  
  # Download handler for the modal plot
  output$download_modal_plot <- downloadHandler(
    filename = function() {
      paste("enrichment_plot-", current_go_category(), "-", Sys.Date(), ".png", sep = "")
    },
    content = function(file) {
      load_export_packages()
      req(current_modal_plot())
      ggsave(file,
             plot = current_modal_plot(),
             device = "png",
             width = 12,
             height = max(8, input$num_terms_modal * 0.3),
             dpi = 300)
    }
  )

}
  
  # Set options for maximum file upload size
  options(shiny.maxRequestSize = 40000*1024^2)  # 40GB upload limit # Set maximum size to 30 MB
  # Create Shiny object
  shinyApp(ui = ui, server = server)
  
  
